        [8703] = {
            description = "The rings worn by the Qiraji lieutenants are rumored to grant them formidable " ..
                "abilities. The corrupted gems that adorn them could, in theory, be swapped out with more " ..
                "pure materials to create uncorrupted versions of the rings.\n\nThe gems that adorn " ..
                "Qiraji idols would work quite well, as their quality is superior.\n\nBring me the ring " ..
                "and idols and I'll create a powerful ring for you, <class>.",
            rewardItems = {{21396, 1}},
        },
        [8705] = {
            description = "The Qiraji and their servants wield items made with the rarest and finest " ..
                "materials: bones from gargantuan ancient creatures, gems from the depths of the earth, " ..
                "metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to " ..
                "practice my craft with their shattered and smelted pieces. Prove your allegiance to the " ..
                "Circle, <name>, and I will make you a powerful weapon from the finest Qiraji materials.",
            rewardItems = {{21410, 1}},
        },
        [8706] = {
            description = "The Qiraji and their servants wield items made with the rarest and finest " ..
                "materials: bones from gargantuan ancient creatures, gems from the depths of the earth, " ..
                "metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to " ..
                "practice my craft with their shattered and smelted pieces. Prove your allegiance to the " ..
                "Circle, <name>, and I will make you a powerful weapon from the finest Qiraji materials.",
            rewardItems = {{21398, 1}},
        },
        [8707] = {
            description = "The Qiraji and their servants wield items made with the rarest and finest " ..
                "materials: bones from gargantuan ancient creatures, gems from the depths of the earth, " ..
                "metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to " ..
                "practice my craft with their shattered and smelted pieces. Prove your allegiance to the " ..
                "Circle, <name>, and I will make you a powerful weapon from the finest Qiraji materials.",
            rewardItems = {{21413, 1}},
        },
        [8709] = {
            description = "The Qiraji and their servants wield items made with the rarest and finest " ..
                "materials: bones from gargantuan ancient creatures, gems from the depths of the earth, " ..
                "metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to " ..
                "practice my craft with their shattered and smelted pieces. Prove your allegiance to the " ..
                "Circle, <name>, and I will make you a powerful weapon from the finest Qiraji materials.",
            rewardItems = {{21404, 1}},
        },
        [8711] = {
            description = "The Qiraji and their servants wield items made with the rarest and finest " ..
                "materials: bones from gargantuan ancient creatures, gems from the depths of the earth, " ..
                "metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to " ..
                "practice my craft with their shattered and smelted pieces. Prove your allegiance to the " ..
                "Circle, <name>, and I will make you a powerful weapon from the finest Qiraji materials.",
            rewardItems = {{21395, 1}},
        },
        [8747] = {rewardItems = {{21196, 1}}},
        [8748] = {rewardItems = {{21197, 1}}},
        [8749] = {rewardItems = {{21198, 1}}},
        [8750] = {rewardItems = {{21199, 1}}},
        [8751] = {rewardItems = {{21200, 1}}},
        [8752] = {rewardItems = {{21201, 1}}},
        [8753] = {rewardItems = {{21202, 1}}},
        [8754] = {rewardItems = {{21203, 1}}},
        [8755] = {rewardItems = {{21204, 1}}},
        [8756] = {rewardItems = {{21205, 1}}},
        [8757] = {rewardItems = {{21206, 1}}},
        [8758] = {rewardItems = {{21207, 1}}},
        [8759] = {rewardItems = {{21208, 1}}},
        [8760] = {rewardItems = {{21209, 1}}},
        [8761] = {rewardItems = {{21210, 1}}},
        [8764] = {rewardChoices = {{21210, 1}, {21205, 1}}},
        [8765] = {rewardChoices = {{21200, 1}, {21205, 1}}},
        [8766] = {rewardChoices = {{21200, 1}, {21210, 1}}},
        [8784] = {
            description = "You have discovered an ancient Qiraji artifact! Perhaps one of the dragons " ..
                "near the entrance of the temple would have a use for this relic.",
        },
        [8789] = {
            description = "We have not sat idly by for a millennium, <name>.\n\nWe have watched these " ..
                "beasts feast on their own when they have exhausted their utility. We have listened as " ..
                "they have plotted and schemed to destroy our world. And we have learned of their own " ..
                "internal treachery.\n\nWeaknesses exist and we know how to use those weaknesses to our " ..
                "advantage.\n\nFind and bring me their ceremonial armaments: Combined with the element " ..
                "created from the volatility of their own God, they will become a force of reckoning.",
            rewardChoices = {{21242, 1}, {21244, 1}, {21269, 1}, {21272, 1}},
        },
        [8790] = {
            description = "Arygos theorizes that the element which is born of conflicts between the Old " ..
                "Gods and their minions is also extremely deadly to them under the right conditions. I " ..
                "speak of Elementium, mortal.\n\nFind and bring me Imperial Qiraji Regalia and the toxic " ..
                "element and I shall infuse weapons of great power.",
            rewardChoices = {{21268, 1}, {21273, 1}, {21275, 1}},
        },
        [8791] = {
            description = "A terrible menace has been laid to rest. The cruel Ossirian has been " ..
                "vanquished.\n\nThe denizens of Kalimdor would be relieved to know of this victory. Take " ..
                "Ossirian's head and present it to Commander Mar'alith of Cenarion Hold.",
            rewardChoices = {{21504, 1}, {21507, 1}, {21505, 1}, {21506, 1}},
        },
        [8801] = {
            description = "The walls of Ahn'Qiraj tremble. A force of evil, older than the world itself, " ..
                "has been destroyed.\n\nAs you look at the remnants of the colossal abomination your " ..
                "heart nearly freezes. Even in death you can feel the legacy of C'Thun's evil around " ..
                "you.\n\nYou have done what was thought to be impossible.\n\nYou grab at an eye stalk of " ..
                "the fiend, stowing it safely in your pack.\n\nTake the Eye of C'Thun to the dragons in " ..
                "the next chamber.",
        },
        [8884] = {
            description = "Greetings, <class>. Take a look toward the shore; what do you see? That's " ..
                "right, our beach... our Tranquil Shore, has been infested with the malignancy known as " ..
                "the murloc.\n\nThis blight will not stand!\n\nI have a task for you. If you feel that " ..
                "you're up to it, I would have their heads! Let us see if we can put a dent in their " ..
                "numbers so large that, if they have any sense at all, they will return to the murky " ..
                "depths from which they sprang!",
        },
        [8886] = {
            description = "Thank goodness for you, <class>! Those slimy Grimscale murlocs have pirated " ..
                "away my cargo! It's bad enough that the Wretched have stolen what little magical goods I " ..
                "had, but the murlocs took the rest! What has this land come to?\n\nCould you retrieve my " ..
                "cargo? I can't expect that you'd be able to get all of it back, but I'll be grateful for " ..
                "any of it at this point. It was the Grimscale murlocs in the huts, just to the west and " ..
                "south of the anchorage on the Golden Strand, I'm sure of it!",
            rewardMoney = 225,
        },
        [8887] = {
            description = "Interesting... what you have found here is a water-proofed, leather tube " ..
                "containing a number of sheets of parchment. By the markings upon them, the pages are " ..
                "clearly navigation rutters, and each bears the signature of one Captain " ..
                "Kelisendra.\n\nYou've heard of a small, defended camp just east of the nearby Sunsail " ..
                "Anchorage. Maybe the captain is there?",
            rewardMoney = 225,
        },
        [8888] = {
            description = "<class>, hear my request. For reasons that I cannot go into now, I decided to " ..
                "shut down my nearby school. A few days ago, I sent one of my pupils, Apprentice " ..
                "Loralthalis, there with this very task. I have not heard back from her since.\n\nWill " ..
                "you go to Duskwither Spire and check in on her, to make sure that she is well? You'll " ..
                "find it by heading north on the path out of Farstrider Retreat, then go to the right " ..
                "when the road branches.",
        },
        [8889] = {
            description = "As you may know, Magister Duskwither sent me back here to shut down the power " ..
                "sources that feed the Spire. There are three of them, each located in a different place " ..
                "inside.\n\nUnfortunately, I appear to be too late, and Duskwither Spire has been overrun " ..
                "with strange, magical creatures. While I haven't the expertise to accomplish this task, " ..
                "surely a <class>, such as yourself, could do so easily?",
        },
        [8890] = {
            description = "<name>, I have one last favor to ask of you. Would you please relay what's " ..
                "transpired here to Magister Duskwither, back at the Farstrider Retreat? Let him know " ..
                "that I am well, but make certain that he is aware that some of the apprentices have " ..
                "become Wretched.\n\nThank you for your help!",
            rewardItems = {{23399, 1}},
        },
        [8891] = {
            description = "You have discovered what appears to be an investigative journal left behind by " ..
                "Magister Duskwither. A brief scan of its contents reveal some shocking attempts at " ..
                "filtering corrupted magical flows, which might explain what has happened here at " ..
                "Duskwither Spire. The magister is sure to want this brought back to him.",
            rewardMoney = 350,
        },
        [8892] = {
            description = "Sunsail Anchorage has been overrun by Wretched scum. As soon as we manage to " ..
                "get reinforcements to the area we'll show those thugs who's boss, <name>.\n\nIn the " ..
                "meantime you can help by showing them a bit of discipline. Go in there and show them we " ..
                "are not to be trifled with. You will find Sunsail Anchorage just to the west of " ..
                "Fairbreeze Village.",
            rewardMoney = 175,
        },
        [8894] = {
            description = "It's horrible, I tell you! Strange things happening in the spire, the magister " ..
                "and his apprentices run off, and then the next thing that you know, the whole grounds " ..
                "are overrun with these magical beasties! And who told Wyllithen? No one, that's " ..
                "who!\n\n<class>, you've got to help me clear some of these things out... I cannot " ..
                "maintain the grounds while these 'anomalies' are running amok!",
            rewardMoney = 350,
        },
        [8895] = {
            description = "I'm pleased to discover that you're at least somewhat competent, <name>. I'll " ..
                "give you another task since you seem so eager to prove yourself.\n\nThis is a letter to " ..
                "Ley-Keeper Caidanis, the arcanist in charge of the upkeep of the North Sanctum. Go " ..
                "southwest of Falconwing Square and you will find him. He is a very important person, so " ..
                "I hope you don't bother him too much with trivial chatter.",
            rewardMoney = 35,
        },
        [9035] = {
            description = "You, there! You must help me, please!\n\nA fellow apprentice and I were " ..
                "attacked by the Wretched! In their mad hunger for magic, they took everything they could " ..
                "get their hands on: mana crystals, wands, spellbooks... everything!\n\nMeledor gave " ..
                "chase after them; I had to stay behind and look after what they didn't take. Continue " ..
                "down the road and see if you can lend him a hand.",
        },
        [9062] = {
            description = "Those blasted Wretched sure can run fast at the sight of someone who'll stand " ..
                "up to them. But let's not worry about that now. I need to find my instructor's elemental " ..
                "grimoire.\n\nI'm certain I saw one of those cowards throw it into the river but I cannot " ..
                "seem to be able to locate it. I could use another set of eyes. I'll throw in a bit of " ..
                "coin if you spot it.",
            rewardMoney = 250,
        },
        [9064] = {
            description = "Antheol is going to fly off his rocker when he finds out his book is ruined. " ..
                "I've got a little proposal for you; don't worry, I'll make it worth your while.\n\nTake " ..
                "this book to him and tell him nothing of this incident. If he asks, just tell him you " ..
                "dropped the book into a puddle. He has no direct authority over you, so there's not much " ..
                "he can do.\n\nAntheol delivers his lectures at Stillwhisper Pond, southeast of " ..
                "Silvermoon. You'll do this for us, right? I'll reward you handsomely for this favor!",
            rewardMoney = 125,
        },
        [9066] = {
            description = "I hope you learn a valuable lesson today, <name>. Never trust someone else to " ..
                "lie for you.\n\nNow I want you to go back to my two dimwitted students and discipline " ..
                "them using this wand. My magic tells me that you'll find them along the road to the west " ..
                "on the other side of the Dead Scar.\n\nCome back to me after you've done this. I'll give " ..
                "you a small reward for your troubles.",
            rewardItems = {{22976, 1}},
            rewardMoney = 125,
        },
        [9119] = {
            description = "Since you're here, <name>, I've a favor to ask you. Ley-Keeper Velania 's " ..
                "apprentice dropped by earlier to ask for assistance. Apparently there's some malfunction " ..
                "happening at the West Sanctum. I've been a bit busy entertaining our... most pleasant... " ..
                "dwarven guest. See if you can give her a hand. You'll find the West Sanctum southwest of " ..
                "here.",
            rewardMoney = 100,
        },
        [9130] = {
            description = "Welcome volunteer! We're running low on supplies here, but Silvermoon has " ..
                "promised us materiel assistance. That's where you come in.\n\nTake this list over to " ..
                "Skymaster Brightdawn. He'll have further instructions for you on how best to get up to " ..
                "Silvermoon City.",
        },
        [9133] = {
            description = "<class>, for a very modest amount of coin, I can send you swiftly flying " ..
                "through the air on one of these magnificent beasts. And, it's safer than walking there, " ..
                "I can assure you!\n\nWhen you arrive in Silvermoon City, seek out Sathren Azuredawn in " ..
                "the Bazaar.\n\nSpeak with me once more when you've decided you're ready to brave the " ..
                "skies.",
            rewardMoney = 85,
        },
        [9134] = {
            description = "It doesn't look as if you have a cart or a beast of burden with you, so I'd " ..
                "better send you back only with what you can carry. If you've spoken with Skymaster " ..
                "Brightdawn at Fairbreeze Village, then you should get this to Sathiel as soon as " ..
                "possible by flying back.\n\nTake these goods for final inspection to Skymistress " ..
                "Gloaming just outside Silvermoon City's Shepherd's Gate.",
        },
        [9135] = {
            description = "It all checks out as far as I can tell.\n\nSo, the question is, have you " ..
                "already spoken to Skymaster Brightdawn in Fairbreeze Village? If so, then this can be as " ..
                "simple as you paying the small fare and quickly flying back.\n\nLet me know when you're " ..
                "ready.",
            rewardMoney = 175,
        },
        [9138] = {
            description = "We're surrounded here, <class>. The outlying villages have all been overrun by " ..
                "the Scourge!\n\nYou must head northeast to Suncrown Village immediately and deal with " ..
                "the Nerubian Scourge menace. You can't miss them - they're spider-like " ..
                "creatures.\n\nThere's no time to waste.... Quel'Thalas must be reclaimed!",
            rewardMoney = 350,
        },
        [9139] = {
            description = "We've had one success, but there are two more villages that must be " ..
                "reclaimed!\n\nGoldenmist Village is our next target. It lies to the northwest, and has " ..
                "been taken by the ghosts of the high elves that used to live there. Gruesome, I know, " ..
                "but these are apparently the sorts of tactics that the Scourge like to employ.\n\nGo and " ..
                "defeat these ghosts and wraiths, <class>. Take the west road out of Tranquillien to get " ..
                "there.",
            rewardItems = {{23444, 5}, {28152, 1}},
            rewardMoney = 400,
        },
        [9140] = {
            description = "<name>, the final battle against the Ghostlands villages is upon you. " ..
                "Windrunner Village to the southwest has been overrun by a large force of the more " ..
                "powerful Scourge shocktroopers; shades and gargoyles. You will be the spearpoint of our " ..
                "offensive by thinning out their numbers.\n\nThe magisters at the nearby Sanctum of the " ..
                "Sun have made a special request this time; they want the remains from these Scourge to " ..
                "study in hopes of finding creative ways of fighting them.\n\nGood hunting!",
            rewardChoices = {{23402, 1}, {23403, 1}, {23404, 1}, {28151, 1}},
            rewardMoney = 1300,
        },
        [9143] = {
            description = "The lieutenant here rushed us into battle with the trolls across the lake " ..
                "instead of scouting the situation first. We were decimated by his stupidity! You hear me " ..
                "Tomathren? You're an idiot!\n\nWill you help us, <class>? Those trolls still need to be " ..
                "dealt with. I need to stay here and nursemaid him -- I think he's lost his mind.\n\nJust " ..
                "head east to the other side of the lake into Zeb'Sora. I want revenge... bring me their " ..
                "ears so that I can fashion a nice necklace!",
        },
        [9144] = {
            description = "My nephew was sent into the Ghostlands a few days ago. He never mentioned " ..
                "anything about his task, except that it was of an extremely secret nature.\n\nHe never " ..
                "returned and I fear for the worst, <class>. A missing messenger might not mean much to " ..
                "the callous magisters of Silvermoon, but he's like a son to me. Please, <name>, will you " ..
                "look for him?",
        },
        [9145] = {
            description = "<class>, I can't just sit here waiting for an audience with the high executor " ..
                "or Dame Auriferous! This cannot wait!\n\nWe were dealing with the Shadowpine trolls of " ..
                "Zeb'Sora to the northeast across Lake Elrendar. But the lieutenant mishandled the attack " ..
                "and we lost a lot of Farstriders. Then he just fell to pieces afterward. Ranger Valanna " ..
                "sent me here, and Ranger Salissa to the Farstrider Enclave for help.\n\nPlease find " ..
                "them, <class>. Valanna was badly injured and the lieutenant's useless.",
        },
        [9147] = {
            description = "What are you standing around for? Can't you see this boy needs immediate " ..
                "attention? By the looks of it, the plague is beginning to take over his body. Within " ..
                "minutes not even a master apothecary like me will be able to save him.\n\nThe animals " ..
                "south of the river all carry the plague in their blood. Go across the bridge and hunt " ..
                "the plagued beasts there. Bring me enough plagued blood samples and I'll distill a serum " ..
                "capable of saving this blood elf. Hurry!",
        },
        [9150] = {
            description = "Can you believe it? We have an actual functioning arcane sanctum up and " ..
                "running southeast of here: the Sanctum of the Sun. All manner of important magisters " ..
                "have come to take part in running it.\n\nOf course they've all forgotten about the " ..
                "Sanctum of the Moon. Not much remains of it and its energies have given rise to bizarre " ..
                "creatures.\n\nI'm not one to let good resources go to waste, however. Go to the Sanctum " ..
                "of the Moon and see if you can recover the crystallized essences from the creatures " ..
                "there.",
            rewardMoney = 500,
        },
        [9151] = {
            description = "You've proven your loyalty to Tranquillien and have helped us defend it " ..
                "against the threat of the Scourge. Some of our most powerful magisters have come from " ..
                "Silvermoon to help us take the fight to the enemy's doorstep.\n\nThey've rebuilt the " ..
                "arcane sanctum to the south and have driven the Scourge away from the surrounding area. " ..
                "They plan to launch an offensive into Deatholme, Dar'Khan's stronghold. You would do " ..
                "well to join them, <name>. I'm sure they can make use of a seasoned <class> like " ..
                "yourself.",
            rewardMoney = 600,
        },
        [9152] = {
            description = "How am I supposed to supply the war effort when I cannot even safely get my " ..
                "supplies here? I was promised an escort that never came. And then, I had to leave one of " ..
                "my carts behind to the west when I was attacked by a band of ghouls!\n\nWant to help " ..
                "out, and get me open for business in the process? Go down the western road out of town " ..
                "and past the graveyard. On the other side of the Dead Scar is a fork in the road. The " ..
                "hill that my cart had to be left on lies just beyond.",
            rewardMoney = 400,
        },
        [9155] = {
            description = "If you've made it this far then you probably know about the Dead Scar and how " ..
                "to this day mindless Scourge follow the path of destruction that Arthas created on his " ..
                "way to Silvermoon City.\n\nMake yourself useful and thin down the Scourge's numbers in " ..
                "the Scar. If you prove to be worth your salt I'll put in a good word for you.",
            rewardMoney = 600,
        },
        [9156] = {
            description = "A bounty is hereby declared for the abominations known as Knucklerot and " ..
                "Luzran. These dreadful creations of Dar'Khan are extremely dangerous and have been " ..
                "sighted patrolling near the Howling and Bleeding Ziggurats. Individuals seeking to claim " ..
                "the reward must present the abominations' heads to Deathstalker Rathiel as proof of the " ..
                "deed.",
            rewardChoices = {{28303, 1}, {22979, 1}},
            rewardMoney = 4000,
        },
        [9157] = {
            description = "Every year we, the denizens of Suncrown Village, would take part in a ritual " ..
                "to keep the different aspects of nature under our control. Dominion over the element of " ..
                "water was symbolized by the summoning and enslavement of an elemental named Aquantion. " ..
                "Through a wicked perversion of our magic, the scoundrel broke his bonds and enslaved us " ..
                "instead!\n\nWe wore medallions shaped like waves during the ritual. Seek them at the " ..
                "bottom of the lake; we'll need them to free my compatriots' spirits!",
            rewardMoney = 500,
        },
        [9158] = {
            description = "You show courage coming to the Ghostlands, <name>. There is much work to be " ..
                "done here and not enough brave souls to do it.\n\nI've a thankless task to offer you, " ..
                "should you have the inclination to aid our cause. The very wildlife in this land has " ..
                "been tainted by the plague and we must stop it from spreading. Hunt the ghostclaw lynxes " ..
                "to the east and south of here and return when you've slain enough of them.",
            rewardMoney = 600,
        },
        [9161] = {
            description = "Dar'Khan Drathir is believed to have returned from the dead to rule over the " ..
                "armies of the Scourge in the Ghostlands. Dar'Khan aligned himself with the Scourge long " ..
                "ago... yet he was once a living, breathing elf. Much of his time was spent inside " ..
                "Dawnstar Spire, northeast of here. He hid there for many nights, scheming against his " ..
                "own.\n\nSearch the tower for more information, <name>. Perhaps he had a journal or kept " ..
                "notes. One never knows where useful information might present itself.",
        },
        [9162] = {
            description = "As you skim through the pages in the journal you're overcome by an unnerving " ..
                "sense of being watched.\n\nThe contents are unsettling. Dar'Khan's soul was one filled " ..
                "with hatred and contempt for his own people. The extent of his machinations and plots " ..
                "are all documented in great detail.\n\nPerhaps there is something here that Vynna will " ..
                "find useful.",
            rewardMoney = 800,
        },
        [9163] = {
            description = "Now, the more direct course of action that we are going to take, to figure out " ..
                "what these night elves are really up to, is to have you go to their island and steal any " ..
                "information that you can come by.\n\nI want you to head west down the road out of town " ..
                "to Shalandis Isle, just off the coast. Go there and recover any plans they might have on " ..
                "the island or on their ship.",
            rewardMoney = 600,
        },
        [9164] = {
            description = "Ah, yes. One of my finest creations. This draught will break most forms of " ..
                "alchemically induced stupor.\n\nSide effects include confusion, nausea and - in rare " ..
                "cases - temporary blindness. All much preferable to whatever the Scourge plans to do to " ..
                "those prisoners in Deatholme, if you ask me.\n\nBest of luck, brave <class>. You are " ..
                "going to need it.",
            rewardMoney = 2500,
        },
        [9166] = {
            description = "You must deliver the recovered night elf plans to An'telas for me. It is to " ..
                "the east, on the southern slopes of Sungraze Peak, just to the northeast of the Sanctum " ..
                "of the Sun.\n\nMagister Sylastor is there conducting ongoing studies into the ley-line " ..
                "nexus energy for potential use in our fight against the Scourge. Have him look at these " ..
                "plans to shed some light on what it is that these night elves are up to.",
        },
        [9167] = {
            description = "Everything we've done in the Ghostlands has been done with the goal of taking " ..
                "back what is rightfully ours. The Scourge have maintained their chokehold on the region " ..
                "for far too long.\n\nThe time has come for payback, <name>. Thanks to your help and the " ..
                "help of our new allies, the Forsaken, vengeance will soon be ours.\n\nHe who sought to " ..
                "steal the power of the Sunwell must die. Go to Deatholme, the Scourge stronghold south " ..
                "of the Dead Scar. Bring me Dar'Khan's head and your deeds will go down in history!",
            rewardChoices = {{22980, 1}, {22982, 1}, {22984, 1}, {22995, 1}},
            rewardMoney = 4000,
        },
        [9169] = {
            description = "Their moon crystals are scrying devices -- they're going to spy on us! I know " ..
                "that An'daroth can't provide enough power for that, but An'owyn, directly to the south, " ..
                "most definitely can!\n\nFrom the plans I now have a basic knowledge of how these moon " ..
                "crystals work; enough to shut them down. They're keyed so that they can be turned off. " ..
                "You must go to An'owyn, retrieve the controlling orb from one of the night elves and " ..
                "then use it on the moon crystal to stop them from enacting their plan!\n\nHurry, <class>!",
            rewardChoices = {{23400, 1}, {28160, 1}, {23401, 1}},
            rewardMoney = 1600,
        },
        [9171] = {
            description = "This is intolerable! I have nothing to work with here! Milady asks me to come " ..
                "from Silvermoon City; she deserves cuisine as befits her station. No? But I get here and " ..
                "there is no food. You must go out, <class>, and bring back fresh kills so that I have " ..
                "something to prepare.\n\nDame Auriferous prefers a crunchy texture to her food. There " ..
                "are plenty of spindleweb lurkers to the southwest on the other side of the Dead Scar. " ..
                "Disgusting, I know, but that's what we have to work with.",
            rewardItems = {{22645, 5}, {22647, 1}},
        },
        [9173] = {
            description = "<class>, I want you to reclaim Windrunner Spire!\n\nIt's an honor, really. " ..
                "Windrunner Spire is the original home of Lady Sylvanas Windrunner, queen of the Forsaken " ..
                "and former ranger-general of the elves. But now it's been overrun by the mindless " ..
                "Scourge.\n\nTo get there take the road south until it branches. Take the right fork and " ..
                "after crossing the Dead Scar continue southwest. You can't miss it.",
            rewardMoney = 700,
        },
        [9174] = {
            description = "That willful elemental ended many lives that fateful day when he revolted " ..
                "against us. By calling to the lowly murloc to sabotage our rites he subverted our magic " ..
                "and turned it against us.\n\nShow him our thirst for vengeance has not waned! Take these " ..
                "medallions and lay them at the Altar of Tidal Mastery at the bottom of the lake. " ..
                "Aquantion shall immediately answer your summons!\n\nBeware, <race>! Without our magic " ..
                "controlling him, his wrath will be unrestrained. Destroy Aquantion so we may rest!",
            rewardMoney = 1100,
        },
        [9175] = {
            description = "The necklace shimmers, a remarkable piece of jewelry that doesn't seem to " ..
                "succumb to the gloom that permeates the Ghostlands. Given the inscription, and where you " ..
                "found it, it must be the lost property of Lady Sylvanas Windrunner herself!\n\nPerhaps " ..
                "it would be best to first take it to High Executor Mavren at Tranquillien? He seems to " ..
                "be the highest ranking Forsaken in the area and is sure to know what to do with it.",
            rewardMoney = 1400,
        },
        [9176] = {
            description = "According to this journal, Dar'Khan promised the Scourge two powerful elven " ..
                "artifacts: the stone of light and the stone of flame. These were imbued with the magical " ..
                "energies of the Sunwell and attuned to have warding powers against the Scourge.\n\nThe " ..
                "crystals were to be transported to where the Howling Ziggurat and the Bleeding Ziggurat " ..
                "now stand, in the middle of the Dead Scar. If they're still held there, we need to " ..
                "recover them. Their power will be greatly useful in our struggle against the enemy.",
            rewardChoices = {{22783, 1}, {22784, 1}},
            rewardMoney = 900,
        },
        [9177] = {
            description = "This is quite extraordinary! It appears to be a gift to Lady Sylvanas " ..
                "Windrunner from her sister, Alleria!\n\nYou must take it to her in the Undercity at " ..
                "once! The lady holds court in the Royal Quarter.\n\nTo get there, use the orb of " ..
                "translocation in the Inner Sanctum of Sunfury Spire in Silvermoon City to cross over to " ..
                "the Undercity. Once there, take the elevator ride down into the city proper. Use your " ..
                "maps if you need help finding the Royal Quarter.",
        },
        [9180] = {
            description = "This is quite extraordinary! It appears to be a gift to Lady Sylvanas " ..
                "Windrunner from her sister, Alleria!\n\nYou must take it to her in the Undercity at " ..
                "once! The lady holds court in the Royal Quarter.\n\nTo get there, use the orb of " ..
                "translocation in the Inner Sanctum of Sunfury Spire in Silvermoon City to cross over to " ..
                "the Undercity. Once there, take the elevator ride down into the city proper. Use your " ..
                "maps if you need help finding the Royal Quarter.",
        },
        [9192] = {
            description = "The Underlight Mines to the southwest have been overrun by a clan of gnolls " ..
                "calling themselves the Blackpaw. I don't need to remind you how important those mines " ..
                "are to us as a strategic asset in our ongoing campaign here in the Ghostlands!\n\nTake " ..
                "the south road out of town and follow the fork to the right. Just past the ziggurat on " ..
                "the right there will be a short dirt path to the west. Follow it.\n\nThe ore must flow!",
            rewardMoney = 600,
        },
        [9193] = {
            description = "<class>, our sources tell us that the trolls buried in the Amani Catacombs " ..
                "inside Sungraze Peak have been rising from the dead. Dame Auriferous would have you " ..
                "investigate these catacombs and put to the torch any of the unanimated remains you come " ..
                "across so as to prevent any more of these creatures from rising.\n\nThe fastest way " ..
                "there is to head north out of town and then take the first fork to the right. This will " ..
                "put you on the north side of the peak, so look to the south for the entrance.",
            rewardMoney = 900,
        },
        [9199] = {
            description = "The corpses of trolls buried inside the Amani Catacombs have been rising from " ..
                "the dead! I want you to go there and bring back proof of their final demise. Some of " ..
                "these mummy trolls, and their living counterparts, carry juju; glowing objects that " ..
                "house an unknown power source. It's probably what is animating them!\n\nThe catacombs " ..
                "lie within Sungraze Peak, directly to the east. I am told that the easiest way in lies " ..
                "on the north face of the mountain. See to it, <class>!",
            rewardChoices = {{28156, 1}, {28159, 1}, {28163, 1}},
            rewardMoney = 900,
        },
        [9207] = {
            description = "I was sent here from the Sanctum of the Sun to collect some ore samples, but " ..
                "the gnolls have overrun the place! It's going to be my head on a platter if I don't get " ..
                "those samples to the magister soon. Maybe you could help, <class>?\n\nYou can find the " ..
                "ore in the tin and copper veins here, and the gnolls are carrying it around, too. When " ..
                "you have enough, take it to Magister Quallestis at the Sanctum of the Sun directly to " ..
                "the east. Go across the Dead Scar and you'll find the sanctum just south of Sungraze " ..
                "Peak.",
            rewardMoney = 600,
        },
        [9214] = {
            description = "<class>, I want you to kill as many Shadowpine trolls as you can. We need " ..
                "their numbers greatly reduced before we can shift our attention toward Deatholme. And " ..
                "while you're at it, we might as well kill two birds with one stone, so bring me back a " ..
                "load of their weapons. Better that they not go to waste, and we can use them in the " ..
                "fight against the Scourge.\n\nHit their camps hard to the east and the south at Zeb'Tela " ..
                "and Zeb'Nowa.",
            rewardMoney = 1000,
        },
        [9215] = {
            description = "WANTED: Bring the head of Kel'gash the Wicked, chieftain of the Shadowpine " ..
                "trolls, to Captain Helios. No questions asked. Kel'gash is known to dwell somewhere to " ..
                "the south in Zeb'Nowa.\n\nREWARD: Yes, but no advances!",
            rewardChoices = {{23409, 1}, {23410, 1}, {23411, 1}},
            rewardMoney = 2500,
        },
        [9216] = {
            description = "I hear the Amani trolls eat their enemies' hearts to steal their strength. " ..
                "They might just be on to something, <name>. With the proper treatment, the hearts of the " ..
                "unliving can produce potent elixirs.\n\nHunt down the zombies that roam the Dead Scar " ..
                "and bring me their hearts. I'll show you the kind of enhancement we can perform to your " ..
                "physical prowess against the undead.",
            rewardItems = {{22779, 1}},
        },
        [9217] = {rewardItems = {{22779, 1}}},
        [9219] = {rewardItems = {{22778, 1}}},
        [9220] = {
            description = "If you seek to aid our cause there is no better place to start than here and " ..
                "no better time to do it than now.\n\nBy rebuilding the Sanctum of the Sun we've raised a " ..
                "banner of defiance in front of our enemy's seat of power: Deatholme.\n\nGo forth and " ..
                "fight the hordes of undead that inhabit the vile Scourge fortress.",
            rewardMoney = 2500,
        },
        [9252] = {
            description = "We've experienced a marked increase in Scourge attacks, <name>. Our defenses " ..
                "are barely holding and there's no sign of reinforcements from Silvermoon City. Lend us a " ..
                "hand in defending the village by thinning the numbers of the undead roaming the Dead " ..
                "Scar nearby.",
            rewardMoney = 300,
        },
        [9253] = {
            description = "This increase in Scourge attacks leads me to believe there might be a " ..
                "malfunction at one of the protective runestones at the border with the Ghostlands.\n\nWe " ..
                "used these ancient stones to protect us against the undead. Most of them were destroyed " ..
                "or lost after the attack on the Sunwell.\n\nFollow the road south, towards the " ..
                "Ghostlands, and look to the west for a small path. You will find Runewarden Deryan by " ..
                "the runestone nearby; he will know whether anything's wrong.",
            rewardMoney = 85,
        },
        [9254] = {
            description = "Thank you for your help, <name>. While I get things back in order here, I'd " ..
                "like to ask you for a favor. One of my former apprentices embarked in a very dangerous " ..
                "line of research. She journeyed to the East Sanctum, in the middle of the Dead " ..
                "Scar.\n\nI worry for her well-being. See if you can find her and convince her to return " ..
                "to her senses.",
            rewardMoney = 70,
        },
        [9255] = {
            description = "As discouraging as my research results are, they still contain valuable data. " ..
                "I must have a magister review my work before it is taken seriously. Please, take these " ..
                "notes to Magistrix Landra Dawnstrider at Fairbreeze Village, west of here.",
            rewardMoney = 70,
        },
        [9256] = {
            description = "I have another task for you, <name>. Ranger Degolien was sent to Fairbreeze " ..
                "Village to find out more about a Wretched attack on a nearby shipyard. He has requested " ..
                "reinforcements which we cannot yet provide. Seek him out and grant him whatever aid you " ..
                "can.\n\nFairbreeze Village can be reached by following the road out of Falconwing Square " ..
                "all the way towards the south. Good luck, <name>.",
            rewardMoney = 85,
        },
        [9258] = {
            description = "A foul taint in the soil precedes the expansion of the Scourge into a new " ..
                "area. The protective runestones along the border with the Ghostlands have warded the " ..
                "land against this taint in the past.\n\nThe westernmost runestone was destroyed during a " ..
                "Scourge attack, which forced us to burn the ground around it to prevent the taint from " ..
                "spreading.\n\nMy sister, Larianna Riverwind, watches over the Scorched Grove. Go find " ..
                "her; she might have some work for you.",
            rewardMoney = 85,
        },
        [9272] = {rewardItems = {{22746, 1}}},
        [9274] = {
            description = "The lake to the north has been haunted by the ghosts of my ancestors for as " ..
                "long as I can remember, <name>. The poor souls were victims of a tragic incident in " ..
                "which scores of them drowned at the bottom of the lake.\n\nThe details of the event are " ..
                "mostly forgotten, but their haunting cries serve as a constant reminder of their " ..
                "curse.\n\nIf you're up to the task, I want you to go to the lake and put an end to their " ..
                "suffering, <name>. You will have my gratitude as well as theirs... I'm sure.",
            rewardMoney = 500,
        },
        [9275] = {
            description = "I'm on loan to the Farstriders in an attempt to help with their troll " ..
                "difficulties. I believe that I have a solution to their problem.\n\nAt my disposal are a " ..
                "number of potent poisons. The trolls, as you know, are living creatures and therefore " ..
                "must eat. If we combine my poison with their food... well, I'm sure that the results " ..
                "will be entertaining!\n\nCare to help rid us of the Shadowpine trolls at Zeb'Nowa to the " ..
                "south? The camp straddles both the north and south sides of the road to Zul'Aman.",
            rewardMoney = 1100,
        },
        [9276] = {
            description = "Our resources are spread pretty thin here, <class>, so your help is going to " ..
                "be invaluable. The captain has tasked me with overseeing the harassment of the local " ..
                "Shadowpine troll camps. We have a policy of keeping them off balance until the day when " ..
                "we can launch a brutal offensive to wipe them out.\n\nUntil then, we need all of the " ..
                "volunteers that we can get so that those Shadowpine troll numbers are " ..
                "decreased.\n\nThink you could head east to Zeb'Tela and hurt them a little?",
            rewardMoney = 1000,
        },
        [9279] = {
            description = "Nevermind my injuries, <brother/sister>. It's a miracle that any of us are " ..
                "alive!\n\nIt didn't look like you'd pull through; you've been in suspension for " ..
                "weeks.\n\nSomething happened and the Exodar crashed. Many have died.\n\nBut I'm relieved " ..
                "that you are alive, <name>. With you leading our efforts, I'm sure we'll get to safety " ..
                "soon! Proenitus asked me to send you to him when you awoke. He's waiting for you at the " ..
                "bottom of the hill. Just follow the path southwest.",
        },
        [9280] = {
            description = "Our immediate concern is the depleted state of our healing crystals. We must " ..
                "replenish them quickly!\n\nUnfortunately, the only way to do this at this point is to " ..
                "extract the blood from the local vale moths. Their blood will make for a suitable " ..
                "substitute.\n\nThe moths can be found in many places around the vale, but they are " ..
                "mostly concentrated in the northwest.",
            rewardChoices = {{24129, 1}, {24130, 1}, {24131, 1}},
            rewardMoney = 15,
        },
        [9281] = {
            description = "Magister Kaendris sent me down here to clear the area of any hostile wildlife. " ..
                "Once this area is secured, the magisters plan to turn it into some sort of advance " ..
                "outpost against the Scourge.\n\nNow if there's one thing I've learned as an apprentice " ..
                "it's to delegate responsibility - especially in matters that endanger one's life!\n\nIf " ..
                "you're interested, I'll pay you well to kill the greater spindlewebs and ghostclaw " ..
                "ravagers to the west and south of here.",
            rewardMoney = 2000,
        },
        [9282] = {
            description = "Magisters and Farstriders may not see eye to eye all the time, <name>. When it " ..
                "comes to Dar'Khan, however, we're all in agreement that a way must be found to defeat " ..
                "him and his legions.\n\nRanger Vynna, at the Farstrider Enclave northeast of here, has " ..
                "come across important information regarding our enemy. Speak to her and see if you can " ..
                "be of assistance.",
        },
        [9293] = {
            description = "The nearby lake has been contaminated by one of the ship's power crystals. " ..
                "Many of the plants and animals of Ammen Vale have been mutated because of this.\n\nI " ..
                "have a theory on how to heal the lake, but I must have samples from the mutated lashers " ..
                "for analysis. They can be found to the west in the Ammen Fields.\n\nWill you help me, " ..
                "<class>?",
            rewardMoney = 35,
        },
        [9294] = {
            description = "Thank goodness, I think it'll work! I have an agent for you to spread at " ..
                "Silverline Lake to the south. It will neutralize the effects of the irradiated ship's " ..
                "power crystal that fell there.\n\nSwim out and scatter the neutralizing agent near it. " ..
                "Don't worry, you won't be exposed long enough to become irradiated.",
        },
        [9303] = {
            description = "Zhanaa needs our help to salvage parts from the Exodar. Taerix prepared an " ..
                "inoculum that can be given to the Nestlewood owlkin that live in the area of a lot of " ..
                "the salvage.\n\nJust get close to the unaffected ones and use the crystal on them. " ..
                "Unfortunately, you'll have to kill the others. You'll find the owlkin at Nestlewood " ..
                "Thicket and Nestlewood Hills to the southeast.",
            rewardChoices = {{5997, 3}, {2454, 3}},
            rewardItems = {{118, 3}},
            rewardMoney = 150,
        },
        [9309] = {
            description = "We now have several separate confirmations of unusual activity up on the " ..
                "Shadow Ridge.\n\nThis is disturbing; we thought that the scouting missions already " ..
                "undertaken had been thorough. One of my scouts hasn't reported back yet.\n\n<class>, I " ..
                "need you to head southwest to the other side of Silverline Lake and find Tolaan, and see " ..
                "what has delayed him.",
        },
        [9311] = {
            description = "I have a plan. We must kill their leader. Without their master, perhaps they " ..
                "will retreat to regroup. We just need to buy time until the repairs are " ..
                "completed.\n\nThen Vindicator Aldar must know of this. Kill the surveyor, then return " ..
                "and tell him what we've found.",
            rewardChoices = {{23390, 1}, {23391, 1}, {23392, 1}, {23393, 1}, {24441, 1}, {25553, 1}},
            rewardMoney = 300,
        },
        [9312] = {
            description = "<name>, while you were out investigating the Shadow Ridge, Zhanaa here has " ..
                "been going on about the holographic emitter. You might want to speak with her.",
        },
        [9313] = {
            description = "By all that is good, <name>, you must go at once to this Azure Watch and speak " ..
                "with Dyvuun!\n\nThere is a path that leads west off of this tiny isle. Follow it and " ..
                "cross the Crystalbrook River to arrive on the larger part of the isle. Continue to " ..
                "follow the path and you should find Azure Watch.\n\nSee if you can convince them to send " ..
                "us some aid and supplies. The rest of us will follow when we can.\n\nThank you, we " ..
                "wouldn't have made it without you!",
        },
        [9314] = {
            description = "<class>! A couple mutated beasts jumped me and my leg is injured.\n\nI was " ..
                "sent on a scouting mission from Azure Watch after we received word from Zhanaa. Please, " ..
                "could you go speak with Caregiver Chellan in my stead? She needs to know how many people " ..
                "to expect in Azure Watch. Just cross the Crystalbrook River here and continue following " ..
                "the road until you get to Azure Watch.\n\nBe sure to ask her for a place for yourself to " ..
                "stay in.",
            rewardChoices = {{6290, 5}, {159, 5}},
        },
        [9315] = {
            description = "Come closer, I am... dying.\n\nI was sent here... to slay these Nerubians, but " ..
                "Vandril didn't... know that they have a leader.\n\n<The dying blood elf coughs up a good " ..
                "amount of blood.>\n\nYou must find and... slay Anok'suten. Get help. She wanders " ..
                "around... Suncrown Village.",
            rewardChoices = {{24339, 1}, {24340, 1}, {24341, 1}, {28149, 1}},
            rewardMoney = 400,
        },
        [9327] = {
            description = "I know it seems strange, but these Forsaken are here to help. You should speak " ..
                "with their leader, High Executor Mavren. He's in the tower on the west side of " ..
                "town.\n\nAnd, <class>, when you're done talking with him return to me; I have something " ..
                "dire that needs to be dealt with immediately!",
        },
        [9328] = {
            description = "This is the beginning of a new chapter in the history of our race, <name>. Our " ..
                "lands will be reclaimed and we shall cement our bond with Sylvanas and her " ..
                "allies.\n\nTake the traitor's head to Regent Lord Lor'themar Theron in Silvermoon City. " ..
                "He'll be eager to hear the news.",
        },
        [9329] = {
            description = "I know it seems strange, but the Forsaken are here to help. You should speak " ..
                "with their leader, High Executor Mavren. He's in the tower on the west side of " ..
                "town.\n\nAnd, <class>, when you're done talking with him return to me; I have something " ..
                "dire that needs to be dealt with immediately!",
        },
        [9340] = {
            description = "We're dangerously close to becoming fenced in by Alliance forces. With the " ..
                "influx of sin'dorei pilgrims from Azeroth, we must establish a route that's safe from " ..
                "our enemies' prying eyes.\n\nI've given it some thought and have arrived at a solution. " ..
                "We're to establish a secret path through the Great Fissure.\n\nYes, even though the area " ..
                "is crawling with brutal rock flayers, they are merely beasts and can be taught to fear " ..
                "us. I want you to go and kill a good number of them. They shall learn fear.",
        },
        [9345] = {
            description = "Just as Zeth'Gor came into view, a Legion patrol caught sight of me. I ran, " ..
                "hoping to duck into one of the towers in the distance, but one of their felhounds caught " ..
                "up with me and nearly hamstrung me!\n\nI managed to escape, but my leg is in terrible " ..
                "shape. Stone Guard Ambelan found me and brought me here. Now, I have to find a way to " ..
                "tend to my leg. Spineleaf grows in and around the Valley of Bones to the north. A salve " ..
                "made from it will dull the pain enough for me to travel.",
            rewardItems = {{24338, 20}},
        },
        [9349] = {
            description = "I'm starving!\n\nThere's irony in that, wouldn't you say? A starving " ..
                "cook?\n\n< Legassi laughs half-heartedly and taps a folded piece of parchment he has in " ..
                "his pocket.>\n\nAccording to this tourist map we were following - before we were so " ..
                "rudely shot down - there's an area to the southwest, near Terokkar Forest. It's called " ..
                "the Razorthorn Trail, and supposedly it's brimming with delicious ravager eggs!\n\nI " ..
                "could cook up quite a feast if only someone were brave enough to go down there and get " ..
                "me some!",
            rewardItems = {{28501, 5}},
        },
        [9351] = {
            description = "Even if I can get the zeppelin's frame repaired, I'll have to find something " ..
                "else to power the engine. I'm all out of fuel and there's no place to fill up around " ..
                "here!\n\nTo the south of us is an area of broken land called the Warp Fields. It's full " ..
                "of rogue and uncontrolled voidwalkers, but I like to think of them as walking " ..
                "batteries.\n\nIf you can bring me enough of their essence, I can convert the zeppelin's " ..
                "engine to run on it. Five gold says I'll even get better mileage out of it, too!",
            rewardChoices = {{25786, 1}, {25787, 1}},
            rewardMoney = 20000,
        },
        [9352] = {
            description = "Besides the constant threat that the Wretched represent, I also have to deal " ..
                "with all kind of fictitious reports of night elf sightings.\n\nThough most reports are " ..
                "unfounded, one recent incident demands further investigation. The West Sanctum, one of " ..
                "our primary energy sources, has suffered a terrible malfunction and rumors of Darnassian " ..
                "sabotage are rampant.\n\nTravel there and deal with anyone that looks suspicious. Report " ..
                "back to Ley-Keeper Velania, who watches over the sanctum.",
            rewardMoney = 125,
        },
        [9355] = {
            description = "Well met, <class>. Now that reinforcements are finally arriving, we can " ..
                "recapture some semblance of a normal life.\n\nOne of our first goals is to restore the " ..
                "flow of men and goods along the road to the southwest, but it must be reclaimed from the " ..
                "crust bursters that've overrun the area.\n\nIf you're willing to help us deal with this " ..
                "menace, you would have the gratitude of the Sons. Watch carefully for the disturbed " ..
                "ground they leave in their wake.",
            rewardChoices = {{25785, 1}, {25784, 1}},
            rewardMoney = 20000,
        },
        [9356] = {
            description = "Screed likes to say his flying is as \"smooth as butter.\" I think " ..
                "\"butterfingered\" is more like it!\n\nTake a look at the wreckage over there. He calls " ..
                "it a \"rough\" landing.\n\nSure, we got shot at, but I'd be willing to cut him a little " ..
                "more slack if he didn't brag about his piloting skills so often!\n\nI think I'm going to " ..
                "make him a batch of wings to drive the point home. To the east, in the Valley of Bones, " ..
                "you'll find bonestripper buzzards. Their wings are plump, juicy, and perfect for my " ..
                "needs.",
            rewardItems = {{27651, 5}, {27684, 1}},
            rewardMoney = 20000,
        },
        [9358] = {
            description = "Don't take the safety of this village for granted. We're under siege by the " ..
                "Scourge on the east and the Wretched to the west.\n\nRanger Sareyn keeps our borders " ..
                "safe from the undead that pour in from the Dead Scar. Follow the road eastwards out of " ..
                "town and see if you can lend her a hand.",
        },
        [9359] = {
            description = "Your help in subduing the Wretched has been invaluable. The Farstriders would " ..
                "surely have use for someone like you in their fight against the Amani trolls.\n\nLook " ..
                "for the Farstrider Retreat to the northeast of here, speak to Lieutenant Dawnrunner and " ..
                "see what assistance she might need.",
        },
        [9360] = {
            description = "Though you don't understand the language in these battle plans, you clearly " ..
                "make out a map marking the positions of the Farstrider Retreat and Fairbreeze " ..
                "Village.\n\nYou'd best let Lieutenant Dawnrunner at the Farstrider Retreat know about " ..
                "this.",
            rewardMoney = 400,
        },
        [9361] = {
            description = "Those eggs are superb, but what do you say we kick it up another notch?\n\nA " ..
                "side of bacon would round out the meal perfectly and I know just where to get " ..
                "it.\n\nThis place is littered with helboars. Of course, there's no one here to inspect " ..
                "and tenderize the meat, but we're in luck!\n\n< Legassi rummages around in his pack and " ..
                "produces a flask.>\n\nThis wasn't made for use on pork, but cooking is as much about " ..
                "improvisation as anything else!",
            rewardItems = {{29292, 5}},
            rewardMoney = 20000,
        },
        [9366] = {
            description = "Northeast of here lie the Pools of Aggonar. Once a sacred site to the draenei, " ..
                "their waters were corrupted after the blood from the demon Aggonar was spilled into " ..
                "them.\n\nThat blood, though old and diluted, still possesses tremendous power. " ..
                "Terrorfiends now walk the area, empowered by the pure demonic energies of the original " ..
                "blood. Slay them and retrieve as much felblood as you can. I'll make it worth your while.",
            rewardMoney = 27000,
        },
        [9369] = {
            description = "We are the draenei. Our ship crashed and, since we have many wounded, our " ..
                "immediate concern is the depleted state of our healing crystals. We must replenish them " ..
                "quickly!\n\nUnfortunately, the only way to do this at this point is to extract the blood " ..
                "from the local vale moths. Their blood will make for a suitable substitute.\n\nThe moths " ..
                "can be found in many places around the vale, but mostly in the northwest.",
            rewardChoices = {{24129, 1}, {24130, 1}, {24131, 1}},
            rewardMoney = 15,
        },
        [9370] = {
            description = "Our scouts captured a draenei paladin at the Pools of Aggonar. He was to take " ..
                "part in a cleansing ritual to purify the pools. We must stop the draenei from succeeding " ..
                "or we will lose our supply of felblood!\n\nHe was carrying this signaling gem, looking " ..
                "to mark a spot where a priest - or \"anchorite\" as they call themselves - could perform " ..
                "their rituals in safety. Place the gem near the Altar of Aggonar and be ready to ambush " ..
                "any approaching draenei.\n\nI suggest that you take a friend or two along.",
            rewardChoices = {{25501, 1}, {25500, 1}, {25499, 1}},
            rewardMoney = 27000,
        },
        [9371] = {
            description = "<name>, Botanist Taerix is in need of your assistance. You'll find her with " ..
                "her apprentices to the west, outside the ship.",
        },
        [9372] = {
            description = "Welcome to the Cenarion Post, <class>. We don't often get company out here, " ..
                "but I'm grateful for the visit. My work with the creatures of this desolate land " ..
                "requires me to travel to many remote places.\n\nThe Cenarion Expedition has dispatched " ..
                "me to study some of the most dangerous wildlife in Outland, and I've made a startling " ..
                "discovery. While many creatures here have already undergone radical changes, they " ..
                "continue to mutate. I'm collecting blood samples to document the changes, and any help " ..
                "would be welcome.",
            rewardMoney = 29000,
        },
        [9373] = {
            description = "Upon examining the battered leather case, it becomes apparent that the " ..
                "container's damage must've been caused by the caustic fluid of the worm's digestive " ..
                "tract. The leather appears to have been intricately tooled at one time, but the details " ..
                "of its adornment can no longer be made out.\n\nThe only recognizable feature of the case " ..
                "is a worn logo of the Cenarion Circle. Knowing nothing about the contents of the case, " ..
                "you decide the best course of action would be to deliver it to a Circle member.",
            rewardMoney = 20000,
        },
        [9374] = {
            description = "My husband, Arelion, had been fascinated with the Pools of Aggonar ever since " ..
                "we arrived in Outland. He spent much of his time studying slimes, of all things!\n\nHe " ..
                "went missing in there a few days ago. They say he's dead and there's nothing I can do " ..
                "about it.\n\nOne thing I can do is try to ensure that his research doesn't die with him. " ..
                "Go northeast to the pools and look for his journal. He always carried it inside a brown " ..
                "knapsack.",
            rewardMoney = 27000,
        },
        [9375] = {
            description = "<The battered blood elf's face displays relief at your presence.>\n\nPlease, " ..
                "<class>, get me out of this cage! I foolishly set out from Thrallmar ahead of the main " ..
                "group, despite Martik Tor'seldori's warnings.\n\nI was set upon by horrible creatures " ..
                "that could only be the ravagers he talked about. I managed to drive them off, but that " ..
                "was only the beginning of my troubles.\n\nAs I bound my wounds, those bird men found me, " ..
                "dragged me back to this cave, and locked me in this cage! I must get to Falcon Watch!",
            rewardMoney = 29000,
        },
        [9376] = {
            description = "That wounded pilgrim seems to be shouting something about a pack.\n\nWhen you " ..
                "encountered her, did you see a pack nearby? Hmm...\n\nShe must've left it when fleeing " ..
                "from her attackers. The quillfang ravagers, in their ravine to the south, are known to " ..
                "attack solitary travelers.\n\nIf she doesn't calm down, I won't be able to tend her " ..
                "wounds. Her stubbornness may just cost her her life.\n\nGo to Dustquill Ravine and see " ..
                "if you can find her campsite. I'm willing to bet she left it there.",
            rewardChoices = {{25781, 1}, {25782, 1}, {25783, 1}},
            rewardMoney = 29000,
        },
        [9381] = {
            description = "With the influx of pilgrims and the encroachment of Alliance forces, things " ..
                "around Falcon Watch have gotten quite busy lately. In my spare time, I usually help " ..
                "prepare batches of arrows for the rangers, but I haven't had the chance to gather " ..
                "feathers for the fletching in a long time.\n\nI could offer you a bit of coin if you'd " ..
                "be willing to gather the tail feathers of the bonestripper vultures. In the past, I've " ..
                "found them circling the bones of large beasts to the north of Falcon Watch.",
            rewardMoney = 29000,
        },
        [9383] = {
            description = "The blood elves epitomize the irresponsible use of magic, <class>. They do not " ..
                "control magical energy. Rather, they are slaves to it and will suffer nothing to stand " ..
                "between them and their addiction. They consume the energies of Outland's voidwalkers to " ..
                "power their demonic magics.\n\nI've prepared a crystal charged with a spell that will " ..
                "allow us to neutralize a voidwalker and sever its link to this world when destroyed. " ..
                "I've mostly seen the voidwalkers in the Warp Fields to the southeast of Hellfire Citadel.",
            rewardMoney = 29000,
        },
        [9385] = {
            description = "So Honor Hold sends us to deal with the arakkoa and we set up camp here " ..
                "thinking hey isn't this a great spot. Little did we know how close we were to the " ..
                "quillfang ravagers.\n\nThey are relentless predators and have made any sort of work on " ..
                "our part impossible. There's a bit of coin in it for you if you can deal with them for " ..
                "us. Do you feel up to it?",
            rewardMoney = 29000,
        },
        [9387] = {
            description = "Uncorrupted draenei, like this unlucky fellow here, are virtuous champions of " ..
                "the Light. What corruption caused their great race to devolve into the Broken and Lost " ..
                "Ones?\n\nI've heard a theory that exposure to fel energies is what caused the mutation. " ..
                "I would like to put that theory to the test.\n\nNorthwest of here lie the Ruins of " ..
                "Sha'naar. There you will find lowly Broken commanded by Illidari taskmasters. Bring me " ..
                "demonic essences from the taskmasters so that I can test them on this draenei.",
            rewardChoices = {{25915, 1}, {25914, 1}, {25913, 1}},
            rewardMoney = 29000,
        },
        [9390] = {
            description = "Hear my plight, <class>. My brother, Sedai, left long ago to contact the orcs " ..
                "of Mag'har Post. Ever the idealist, he thought the time was ripe to set our differences " ..
                "aside and negotiate a peace with them.\n\nHe's been missing for days and I fear for the " ..
                "worst.\n\nWould you set my mind to rest and look for him? Sedai must be somewhere nearby " ..
                "to the east.",
        },
        [9391] = {
            description = "With the rock flayer population thinned, all that's left is to signal the safe " ..
                "path to our pilgrims. Return to the Great Fissure with this torch and seek the three " ..
                "beacons that mark the path from the east.\n\nLight the three beacons and return to me. " ..
                "Be warned that the beacons will attract any nearby rock flayers when you first light " ..
                "them.",
            rewardChoices = {{25502, 1}, {25503, 1}, {25504, 1}},
            rewardMoney = 27000,
        },
        [9392] = {
            description = "As you advance within your class, you will want to take advantage of the " ..
                "training that your class trainer can provide you. For young rogues here on Sunstrider " ..
                "Isle, your trainer is Pathstalker Avokor. Speak with Avokor and see what training he has " ..
                "available for you. The things he will teach do have a cost, so bring some coin with " ..
                "you.\n\nAvokor - as with all the trainers on Sunstrider Isle - is inside the Sunspire on " ..
                "the lower level.",
        },
        [9393] = {
            description = "As you advance within your class, you will want to take advantage of the " ..
                "training that your class trainer can provide you. For young hunters here on Sunstrider " ..
                "Isle, your trainer is Ranger Sallina. Speak with Sallina and see what training she has " ..
                "available for you. The things she will teach do have a cost, so bring some coin with " ..
                "you.\n\nSallina - as with all the trainers on Sunstrider Isle - is inside the Sunspire " ..
                "on the lower level.",
        },
        [9394] = {
            description = "The Duskwither groundskeeper has gone missing! Someone must have forgotten to " ..
                "tell him to leave when the magister and everyone else did. I know that he's still " ..
                "somewhere around here on the grounds, but I dare not go looking for him myself with all " ..
                "of these magical creatures roaming about.\n\nWill you find him for me, <class>, and make " ..
                "sure that he's alright?",
        },
        [9395] = {
            description = "I swear that I'm going to fireball someone if I get one more request from Lord " ..
                "Saltheril concerning supplies for his party! Do I look like a party planner?! Between " ..
                "you and me, that fool and his sycophants are living in denial that we're under attack " ..
                "here!\n\nSome of us are actually busy with, oh, I don't know, defending what's left of " ..
                "Quel'Thalas! <class>, would you please head over to Saltheril's Haven and see if you can " ..
                "shut him up? It's just down the road to the west.",
        },
        [9396] = {
            description = "Outland holds many secrets, <name>. It's only a matter of time before we " ..
                "uncover them all.\n\nThe half-bird, half-man species of the arakkoa possesses ancient " ..
                "arcane knowledge that would aid us greatly in our exploration of this world. Travel to " ..
                "the Den of Haal'esh, south of here. Obtain any magical scrolls that the Haal'eshi might " ..
                "be carrying on them and bring them to me.",
            rewardMoney = 27000,
        },
        [9397] = {
            description = "The Haal'eshi arakkoa have domesticated a beautiful bird species called the " ..
                "kaliri.\n\nI've managed to capture a young male and they appear to be trainable. The " ..
                "females are much rarer, but if I had one I could attempt to breed them. She has to be " ..
                "young, though... a hatchling. An older wild bird wouldn't survive in captivity.\n\nTake " ..
                "this cage and travel south, to the Den of Haal'esh. Search the nests for eggs that are " ..
                "ready to hatch. If you bring me back a female hatchling, I'll reward you handsomely.",
            rewardMoney = 27000,
        },
        [9398] = {
            description = "The Broken that live in Outland have endured endless violence. It is of little " ..
                "surprise that as soon as the Dark Portal opened they flocked to it in droves with hopes " ..
                "of escaping this land.\n\nUnfortunately for our confused brothers and sisters coming " ..
                "from the south, the rock flayers that inhabit the Great Fissure see them as easy prey. " ..
                "Go there and thin the rock flayer population, so that our kin might have a chance.",
            rewardMoney = 27000,
        },
        [9399] = {
            description = "You probably think most Broken are evil, don't you? In reality many just lack " ..
                "guidance.\n\nBefore I met the Omenai, I too was lost.\n\nOur minds suffered terrible " ..
                "pain from the orcs' demonic magic. We are easily confused and taken advantage " ..
                "of.\n\nDemons allied with Illidan raid Hellfire daily and capture our kind as slaves. " ..
                "With the Omenai we now have hope. Travel to the Ruins of Sha'naar, southwest of here, " ..
                "and slay the Illidari taskmasters so my people may be free!",
            rewardMoney = 29000,
        },
        [9400] = {
            description = "<name>, we recently uncovered a plot to assassinate our envoy to Falcon Watch. " ..
                "Hellfire Citadel learned of our plans to send an expedition there earlier this morning " ..
                "and set up an ambush.\n\nOur scouts have informed me that an assassin known as Krun " ..
                "Spinebreaker waits along the road north of the Citadel. Go there and slay this assassin. " ..
                "Show the fel orcs we're not to be trifled with!",
        },
        [9401] = {
            description = "You pull the stone axe out of the body to examine it more closely. There's " ..
                "something unusual about the craftsmanship of the weapon.\n\nIts origin appears orcish, " ..
                "though the materials aren't like anything you've seen before. Nazgrel might be " ..
                "interested in seeing the weapon.",
            rewardMoney = 27000,
        },
        [9402] = {
            description = "So... <name> is it? Don't be flattered I know your name, one of my students " ..
                "has been fawning over you and won't shut up.\n\nHmm... if you'd like to impress " ..
                "<her/him>, why don't you do something for me? There's an azure phial at the bottom of " ..
                "the pond behind me. Dive in, retrieve it, and bring it here.",
        },
        [9403] = {
            description = "Now that you've learned a little lesson, I'll offer you something more " ..
                "substantial. It concerns your ability to defend yourself in close combat. Of course, you " ..
                "should only resort to melee in the most dire of circumstances, but that is no excuse to " ..
                "be unprepared.\n\nI can assist you in creating a staff befitting a mage of your " ..
                "learning. Simply take the phial you retrieved for me and fill it at the base of Elrendar " ..
                "Falls. Just follow the river southeast from here.",
        },
        [9404] = {
            description = "You may have noticed the walking trees near Elrendar Falls. As the keepers of " ..
                "nature, they are infused with a primal magic we can reform to our own purposes using the " ..
                "pure water you have already brought to me.\n\nUnfortunately, the green keepers are " ..
                "gnarled and twisted creatures, so you may need to kill a few before you find a useable " ..
                "branch.",
            rewardChoices = {{9513, 1}, {7508, 1}},
        },
        [9405] = {
            description = "As you know, the warchief put his power behind this expedition for one reason. " ..
                "This is the world we came from. This is where our roots lie.\n\nThis journey means " ..
                "different things to orcs and blood elves. To them it's a search for the promised land. " ..
                "To us it's more like returning home.\n\nWhoever made this axe is familiar with the old " ..
                "ways and we must contact them. This is too important for us to use ordinary tracking " ..
                "methods. Show the weapon to Far Seer Regulkut; she will know what to do.",
        },
        [9406] = {
            description = "This news you bring from beyond the Dark Portal... you want us to believe the " ..
                "son of Durotan ruled over the lands beyond it... free from any demonic taint? And that " ..
                "now his people have returned to this world?\n\nI hope for your sake that this isn't some " ..
                "manner of joke, <class>. What this means to my people... cannot be described. I must " ..
                "send word to Nagrand at once! Hellscream must hear about this.\n\nTake this letter back " ..
                "to your leader in Thrallmar. Tell him the Mag'har welcome them!",
            rewardChoices = {{25510, 1}, {25511, 1}, {25512, 1}, {25513, 1}},
        },
        [9407] = {
            description = "For years the Dark Portal loomed silent... forgotten. But it is silent no " ..
                "longer.\n\nAfter stopping the demonic assault here, our forces breached the portal and " ..
                "met the demons on their own ground!\n\nNow, we are locked in a savage war, and there are " ..
                "some who think we might not win. So it is our duty, our grim pleasure, to battle the " ..
                "fiends of Outland and ensure our victory, <name>.\n\nIf you would help us, then report " ..
                "to Lieutenant General Orion at once. He awaits you in the Outland...",
        },
        [9409] = {
            description = "Now that you've gathered all that we need to replenish our healing crystals, I " ..
                "need you to deliver the vials to Zalduun, our priest. You'll find him tending to our " ..
                "wounded inside the central chamber of the ship.",
        },
        [9410] = {
            description = "Even our best tracking wolves' senses can fail them, <name>. The spirits have " ..
                "a way of seeing the world differently than ours. The being you will call forth will find " ..
                "the person you seek, for they'll be drawn not to their scent but their essence.\n\nGo " ..
                "now, <class>, take this totem with you and use it at the location you found the stone " ..
                "axe.",
        },
        [9415] = {
            description = "Are you Marshal Bluewall 's new recruits? Of course you are.\n\nWhat are you " ..
                "waiting for? Good soldiers are dying in the desert. Aren't you excited to join " ..
                "them?\n\nNow, get going and don't dry out on the way.",
        },
        [9416] = {
            description = "You must be one of General Kirika 's new recruits. It's about time you showed " ..
                "up. Bodies wear down quick in the desert.\n\nThe dwarves have been getting " ..
                "reinforcements daily, and we can't afford to lose ground in our struggle for resources " ..
                "in Silithus.\n\nGet your instructions from the General. It's not my job to train you, " ..
                "just find you.",
        },
        [9417] = {
            description = "The arakkoa are smart creatures... smart as any gnome you ever met. They have " ..
                "this way with magic and a violent temper, however.\n\nLately they've taken to attacking " ..
                "Honor Hold patrols, which is why we were sent here. See, Mirren and I are world-famous " ..
                "marksmen, we are! But fowl and game are what we specialize in... not these... " ..
                "lightning-invoking birdmen.\n\nSo what do you say you give us a hand in this one " ..
                "assignment? You'll find the Den of Haal'esh to the southeast.",
            rewardMoney = 58000,
        },
        [9418] = {
            description = "<As you hold the orb closer to you, you hear a voice address you.>\n\nI sense " ..
                "you're not of the arakkoa, so I will attempt to barter for my freedom. My name is " ..
                "Aeranas. I once ruled over the eastern winds. The Haal'eshi mage, Avruu, trapped me " ..
                "inside this orb.\n\nFind the altar the arakkoa used to enslave me. It is hidden to the " ..
                "southeast of the arakkoa's den. Approach it with the orb and give it to me once I'm " ..
                "free. In exchange for my liberty I'll reward you with powerful treasure!",
            rewardChoices = {{25489, 1}, {25488, 1}, {25487, 1}},
        },
        [9420] = {
            description = "The arakkoa at the Den of Haal'esh, south of here, breed a magnificent species " ..
                "of birds called kaliri. Their feathers would fetch a bundle at the trading posts back in " ..
                "Azeroth. Just think of all the ale I could buy then!\n\nTell you what, you bring me a " ..
                "stack of kaliri feathers and I'll give you my very own hat. What do you say? You'll " ..
                "never find a hat like this one! Do we have a deal?",
            rewardItems = {{23587, 1}},
            rewardMoney = 27000,
        },
        [9422] = {
            description = "For some time now, we have been tapping the crystal resources of the Silithus " ..
                "desert. The only dangers we faced were from the creatures that made this place their " ..
                "home and the oppressive sand and dust and heat.\n\nBut now the Alliance seems to have " ..
                "caught on to what we have found here. It is now a race between us to capture the natural " ..
                "resources, and keep them from the other.\n\nI need every set of hands that is available. " ..
                "I hope I have yours.",
            rewardChoices = {{13446, 2}, {13444, 2}},
        },
        [9423] = {
            description = "With Sedai's death confirmed, you're left with the unpleasant task of " ..
                "returning to Obadei with the grim news.",
        },
        [9424] = {
            description = "Sedai was like a brother to Makuru. We owe him our lives and more! They call " ..
                "Makuru crazy but if the Omenai are not going to do anything about his death then they're " ..
                "the crazy ones!\n\nMakuru doesn't have much to call his own in this world, but he will " ..
                "give you his only possession if you avenge Sedai.\n\nI've seen the brown orc Mag'har " ..
                "grunts before, up in the hills to the northeast. They hate us! They don't deserve our " ..
                "mercy! Go, avenge Sedai! Bring me their ancestral beads as proof!",
            rewardChoices = {{25920, 1}, {25919, 1}, {25921, 1}},
        },
        [9426] = {
            description = "Much has changed since the days when we called this land Draenor. Parts of the " ..
                "land have been forever changed by the demons' taint.\n\nOne such place is known as the " ..
                "Pools of Aggonar. It was once the location of our people's sacred springs. The blood of " ..
                "the demon Aggonar fouled the very essence of the holy waters. This fel blood has spawned " ..
                "foul beings that must be cleansed if we're ever to reclaim the pools. Travel east of " ..
                "here and slay the Terrorfiends and slimes that wander the pools.",
        },
        [9427] = {
            description = "I must ask that you finish what we've set in motion. Now that the demonic " ..
                "influence has weakened you must take this cleansing vial and pour it at the very source " ..
                "of the taint - Aggonar's own corpse.\n\nYou will find the demon's bones at the northern " ..
                "end of the pools. Beware, I sense that Aggonar's essence has not quite left this world.",
            rewardChoices = {{25486, 1}, {25484, 1}, {25485, 1}},
        },
        [9430] = {
            description = "As I've told you before, I do not require eyes to see what others cannot. I " ..
                "will not pass judgment on what you did on Makuru's behalf, yet I think you need to see " ..
                "beyond what your eyes show you.\n\nTravel southwest to the Ruins of Sha'naar and salvage " ..
                "any relics you find. If fate wills it you will find what we need.\n\nThe meaning of my " ..
                "request might not be immediately apparent. Have faith though, <name>. Clarity comes to " ..
                "those with patience.",
        },
        [9436] = {
            description = "Well met, <class>. I've made a habit of studying the fighting techniques of " ..
                "the various troll tribes in my travels, and I've noticed a trend. The Bloodscalp trolls " ..
                "at the Tkashi Ruins and Bal'lal Ruins to the north use some of the same tactics as the " ..
                "Amani of the northern forests.\n\nTheir magic seems to have diverged in an interesting " ..
                "direction and they've used it to become the strongest tribe in the area. It could form " ..
                "the core of a powerful weapon against the Amani, but first I must find out more about it.",
            rewardMoney = 2000,
        },
        [9437] = {
            description = "The ogres here are useful for little more than crude jokes, sour ale, and " ..
                "bouts of headbutting. When my ship, the Dawn Runner, ran aground, those curs from " ..
                "Theramore made off with my cargo and last surviving crewman. I made my way here " ..
                "searching for help, but those good-for-nothing ogres stared blankly at me when I told " ..
                "them my story.\n\nI could use the help of a reliable <race> in recovering what remains " ..
                "of my cargo and freeing Ithania from North Point Tower, to the northeast, where they're " ..
                "being held.",
            rewardChoices = {{33250, 1}, {57851, 1}},
            rewardMoney = 4000,
        },
        [9452] = {
            description = "I've found that these waters are bustling with red snapper, a very tasty fish. " ..
                "With a fishing net, I can catch enough to feed dozens of draenei! Unfortunately, I was " ..
                "recently attacked by a creature known as a murloc while netting in the river and have " ..
                "suffered some injuries that prevent me from doing my job. I need help!\n\nUse this " ..
                "fishing net near schools of red snapper, found in the Crystalbrook river to the east, to " ..
                "catch the fish.\n\nWhat do you say? Remember to return the net when you are finished.",
            rewardItems = {{6256, 1}, {6529, 1}},
        },
        [9453] = {
            description = "You did a wonderful job, <name>. Our people will be thankful for this bounty. " ..
                "With that said, would you mind taking this haul of red snapper to Acteon at Azure " ..
                "Watch?\n\nHe shouldn't be hard to find as he is awaiting this catch.",
        },
        [9455] = {
            description = "The crystal you found on the nightstalker runt's body appears to be a piece of " ..
                "the Exodar. This may help explain the unusual appearance and demeanor of some of the " ..
                "animals in this region.\n\nTake the crystal back to Azure Watch. The exarch will surely " ..
                "want to know about this discovery.",
        },
        [9457] = {
            description = "So this Naias is the mastermind behind the Bloodscalp and their exotic magic? " ..
                "I'll admit, this is the last place I expected my inquiry to lead, but no matter, our " ..
                "findings may still prove useful.\n\nOff the coast to the northwest is an island " ..
                "inhabited by lesser water elementals. There's a crude stone slab there that might serve " ..
                "as an altar for the likes of the trolls. Take the totem you found to that altar. Let's " ..
                "see if we can draw this Naias out and distill his power into a more agreeable form.",
            rewardChoices = {{61091, 1}, {61092, 1}, {61093, 1}},
            rewardMoney = 4000,
        },
        [9463] = {
            description = "I have found that lashers milling about on the island hold restorative " ..
                "medicinal properties in their vines. Through proper treatment, the vines can be broken " ..
                "down into a powerful healing ointment. Unfortunately, with so many injured draenei " ..
                "passing through Azure Watch, we are always in short supply.\n\nOur delicate guest was " ..
                "found injured and unconscious by the Crystalbrook only yesterday. If you bring me vines, " ..
                "we may be able to save her.\n\nYou will find root trappers both south and east of Azure " ..
                "Watch.",
        },
        [9466] = {
            description = "By order of the Ranger Captain, a reward is hereby offered for the slaying of " ..
                "the vicious rockflayer matriarch known as Blacktalon the Savage.\n\nBlacktalon was last " ..
                "sighted inside a cave in the Great Fissure. Individuals seeking the reward are to " ..
                "present the creature's claws as proof of the deed.",
            rewardChoices = {{25481, 1}, {25482, 1}, {25483, 1}},
            rewardMoney = 58000,
        },
        [9472] = {
            description = "With all the important matters at hand Arelion still found time in his " ..
                "schedule to see a mistress!\n\nIt's all becoming perfectly clear. Viera Sunwhisper, that " ..
                "filthy wench... we'll show her to never cross a magistrix again.\n\nTake this scroll and " ..
                "find Viera. Find a way to lure her away from town and use the scroll on her.\n\nArelion " ..
                "mentioned she couldn't resist a particular wine harvested by the cenarion druids. You " ..
                "might find some at Cenarion Refuge, just inside Zangarmarsh, west of here.",
            rewardItems = {{25505, 1}},
            rewardMoney = 54000,
        },
        [9473] = {
            description = "The girl is too far gone for mere ointments to be effective. There may be " ..
                "another way...\n\nThe forest of Azuremyst holds many secrets, one of those being a rare " ..
                "plant known as the azure snapdragon that some claim to be a panacea - a cure all.\n\nYou " ..
                "can identify the plant by its stark contrast to the other plants of Azuremyst and its " ..
                "need to grow at the base of the azure pine trees. Make haste!\n\nAnd <name>, be wary of " ..
                "the root threshers of the region as they consume snapdragon for sustenance.",
        },
        [9487] = {
            description = "Arcane reavers are magical creations of brute strength. They are heavily " ..
                "armored and deliver stunning blows. You, however, can bypass their defenses and avoid " ..
                "their attacks. Your spellcraft is not without many advantages, <name>.\n\nTravel to " ..
                "Dawnstar Spire and blast apart the arcane reavers. From their remains, collect the " ..
                "crystallized fragments of magical energy and return to me. Dawnstar Spire is found to " ..
                "the east, across the lake.",
        },
        [9488] = {
            description = "The arcane fragments you collected will do nicely.\n\nNicely for what, you " ..
                "ask? For making a splendid robe fit for a <class> like yourself!\n\nAll we need now is " ..
                "some linen cloth and a spindleweb silk gland. You can find the silk gland from any " ..
                "spindleweb spider, preferably after killing them.",
            rewardItems = {{7509, 1}},
        },
        [9490] = {
            description = "Rock flayers are mean, nasty, violent creatures. But the plain ones are like " ..
                "tame beasts when compared to their matriarch, Blacktalon the Savage.\n\nMy cousin got " ..
                "eaten by her and it wasn't pretty. I swore that one day Blacktalon would pay for that. " ..
                "You bring back proof of that monster's death and I will give you my life's savings. " ..
                "Deal?\n\nYou'll find her inside a cave in the Great Fissure. Good luck!",
            rewardChoices = {{25478, 1}, {25479, 1}, {25480, 1}},
            rewardMoney = 58000,
        },
        [9498] = {
            description = "My people recently finished building Falcon Watch, a base of operations in the " ..
                "southwestern region of Hellfire Peninsula - beyond Hellfire Citadel. You are welcome " ..
                "there as an ally, <name>.\n\nIf you're looking for work, go there and tell Ranger " ..
                "Captain Venn'ren that I sent you. He will see to it that you're given tasks worthy of " ..
                "someone of your caliber.",
        },
        [9499] = {
            description = "What are you still doing here, <name>? Didn't you hear we built a proper " ..
                "sin'dorei outpost here in Hellfire Peninsula?\n\nSurely you'd rather be among fellow " ..
                "blood elves and away from all this... smell. You'll find Falcon Watch in the southwest, " ..
                "beyond Hellfire Citadel. Report to Ranger Captain Venn'ren; he will take care of " ..
                "you.\n\nThe road ahead is dangerous and heavily patrolled by Alliance scouts. I would " ..
                "recommend travelling with companions. Blood elves, preferably.",
        },
        [9505] = {
            description = "The Prophet spoke of this day: That on this island, in this new world, our " ..
                "allies would find us.\n\n\"We will be tested. They will ask that we pay for the sins of " ..
                "our fathers...\"\n\nAt the time, I did not understand the meaning behind his words, but " ..
                "seeing this creature and her reaction to us, it is now coming into focus. The corruption " ..
                "of our people has been felt even here.\n\nVenture south. It is there that we found this " ..
                "being. Find its kin and tell them of our people.",
        },
        [9506] = {
            description = "I am Admiral Odesyus of Alliance Naval Command. Our ship was forced to port on " ..
                "your island due to an infestation of sorts. It's embarrassing to even talk about, but " ..
                "goblins somehow managed to stow away in the holds of both of my ships.\n\nLast night, " ..
                "while most of the ship's crew was asleep below deck, they struck!\n\nStranger still, " ..
                "they took our navigation gear and jumped ship!\n\nThey disappeared into the thicket, " ..
                "east of here. Will you go in search of our gear? It will make for a strong gesture.",
        },
        [9513] = {
            description = "While some may look at our current predicament as an unfortunate turn of " ..
                "events, I sense that we are here for a reason. The invisible hand of fate has pushed us " ..
                "in this direction. The reason why will become evident in time.\n\nTo the west lies an " ..
                "ancient night elf city, now in ruin and overrun with naga. It would be remiss of me to " ..
                "sit idly by as the naga tainted my ancestral lands.\n\nYou have shown yourself a capable " ..
                "<class>. Honor my people and cleanse the ruins of their unwelcome inhabitants.",
        },
        [9514] = {
            description = "You cannot make out any of the symbols on the tablet. Perhaps the priestess " ..
                "would be able to decipher the mysterious runes.",
        },
        [9523] = {
            description = "The priestess tells me that the ruins to the west are what's left of a night " ..
                "elf civilization. That got me thinking about what my pappy used to always say about " ..
                "night elf ruins, \"Sonny, whenever you see night elf ruins, night elf relics are sure to " ..
                "be close by.\"\n\nNow what kind of a dwarf would I be if I didn't hire the first person " ..
                "I saw to go digging up night elf relics for me? Now get going!",
            rewardMoney = 225,
        },
        [9527] = {
            description = "We had lived peacefully among the Owlbeasts of this island for many years. You " ..
                "can imagine my surprise when they stormed the beach and attacked us.\n\nI fought tooth " ..
                "and nail but was easily overpowered. As I blacked out from the vicious blows that I had " ..
                "been dealt, I prayed that my family not suffer.\n\nWhen I awoke, all was quiet. The sand " ..
                "was soaked red with blood - their blood. They were devoured whole.\n\nI care not for " ..
                "vengeance, <name>. I only ask that their remains be returned to me for proper burial.",
        },
        [9528] = {
            description = "My family was attacked by the murlocs and owlkin of this island several weeks " ..
                "ago. I managed to escape but I think that both my mother and father have been slain. I " ..
                "don't know what I'm going to do now, but I must try and get back to my home - or what's " ..
                "left of it... Will you help me get through the forest?",
            rewardItems = {{24113, 1}},
        },
        [9530] = {
            description = "I've wondered about this for some time now, but this proves it to be " ..
                "true.\n\nThere is a traitor among us.\n\nThe plans left behind by the goblins document " ..
                "the conspiracy. Since I don't know who it could be, I'm going to need your help in " ..
                "finding the traitor. None of my crew can be trusted.\n\nIf this is going to work, I'm " ..
                "going to need a hollowed out tree and leaves. Search near the loggers north of us for " ..
                "the tree. You'll need to find the leaves by yourself. Check the forest.",
        },
        [9531] = {
            description = "According to the plans, the traitor and the leader of the goblins, Geezle, are " ..
                "to meet at a cove on the western island. I need you to be at that meeting, " ..
                "<name>.\n\nRemember the tree and leaves? You're going to wear them! It's a perfect " ..
                "disguise.\n\nGo to the cove and look for a naga flag. If the flag is there, it means a " ..
                "meeting is planned. Use the disguise kit when you see the flag and wait. Eventually the " ..
                "traitor will show up. Let the meeting finish then return to me with the identity of the " ..
                "scoundrel.",
            rewardMoney = 900,
        },
        [9538] = {
            description = "I think I've cracked it, <name>!\n\n<Aurren points to the totem.>\n\nAll that " ..
                "we need to know about the Stillpine furbolg language is imprinted on their totems. With " ..
                "just a rudimentary understanding of how their symbols work, we can study the totems and " ..
                "learn to communicate with the furbolgs.\n\nI've written down the basics of the symbol " ..
                "matrix on this parchment. Study it and then examine the totem. It should lead you to the " ..
                "next language totem.\n\nSpeak to Arugoo when you return an educated <race>!",
        },
        [9539] = {
            description = "You begin to read the totem, barely able to pronounce the awkward words and " ..
                "phrases. Slowly, words start to form in your head. You think that the totem is telling " ..
                "you to go up the nearby hill, to the northeast.",
        },
        [9540] = {
            description = "You begin to read the totem, better able to pronounce the words and phrases. " ..
                "Words start to form in your head. You think that the totem is telling you to go across " ..
                "the Crystalbrook river to the east. Perhaps your destination is on the other side of the " ..
                "river.",
        },
        [9541] = {
            description = "The symbols on this totem seem to translate much faster. The patterns and " ..
                "imagery all seem to blend into familiar words. You are fairly certain the totem is " ..
                "pointing you south, down the river. Something is at the bottom of the river itself.",
        },
        [9542] = {
            description = "You no longer see unrecognizable symbology in the totems. The totem of Yor " ..
                "reads to you just as easily as your native tongue.\n\nThe markings identify another " ..
                "furbolg den, due west of here. You are able to expertly decipher the language on the " ..
                "totem and know that your destination is Bristlelimb Village. Yor will guide you but if " ..
                "you get lost, you know that you are able to take the ancient elven road in the forest " ..
                "leading west to reach your destination.",
        },
        [9543] = {
            description = "Our history with the orcs is one of constant conflict, <name>. We were once " ..
                "near driven to extinction due to their bloodlust and have since then avoided them even " ..
                "when not under demonic influence.\n\nYet, this retaliation... it's not what Sedai " ..
                "would've wanted. Speak with our elder, Amaan the Wise. He will help shed light on these " ..
                "events.",
        },
        [9545] = {
            description = "The stubborn close their mind and convince themselves of one truth. The wise " ..
                "keep an open mind to the different possibilities leading to and stemming from the " ..
                "present.\n\nTake this relic with you to where you found Sedai. See not with your eyes, " ..
                "<name>, but with your mind.",
            rewardChoices = {{25506, 1}, {25507, 1}, {25508, 1}},
        },
        [9548] = {
            description = "Shh! Keep your voice down and don't call attention to me.\n\nIf the murlocs " ..
                "detect my presence, the experiment will be ruined! I've already come perilously close to " ..
                "contaminating my data.\n\nWhile I was foraging yesterday, one of them must've wandered " ..
                "too close and discovered my camp. I returned just in time to see two of them carrying " ..
                "off a crate with most of my equipment! It's bound to be in one of their settlements " ..
                "around here, but I can't risk revealing my presence. Are you willing to help?",
            rewardMoney = 900,
        },
        [9549] = {
            description = "My observations and writings about the Blacksilt murlocs are quite " ..
                "illuminating, <name>, but they are just the beginning. I plan to return to Ironforge " ..
                "with items produced by the Blacksilts' rudimentary crafting skills.\n\nThe problem is " ..
                "that the Blacksilt carry these items with them at all times, and I can't have their " ..
                "blood on my conscience. If you're willing to help me gather the idols carried by " ..
                "Blacksilt seers and crude knives of the Blacksilt warriors and shorestrikers, I won't " ..
                "ask how you came by them.",
            rewardItems = {{23837, 1}},
            rewardMoney = 900,
        },
        [9550] = {
            description = "The crudely-drawn map reveals nothing of its maker, but it appears to have " ..
                "been drawn with an unsteady hand. Wavering lines and symbols depict a small pavilion " ..
                "with broken columns located to the west of a partially submerged tower.\n\nIf the map is " ..
                "to be believed, this cluster of ruins appears to be located on the eastern coast of the " ..
                "island. You have no idea what you'll find, but it was important enough for the map's " ..
                "creator to record.",
        },
        [9557] = {
            description = "Lacking the means to read the book's contents, you think about who might be " ..
                "able to help you separate the author's words from the mapmaker's scrawl.\n\nRemembering " ..
                "Anchorite Paetheus 's collection of artifacts from countless cultures, you wonder if his " ..
                "experienced eye might be able to help you decipher the book's contents.",
        },
        [9558] = {
            description = "We were having a problem with arakkoa bandits raiding many of our supply " ..
                "caravans, so I hired some dwarves to take care of them.\n\nThey were brothers; Gremni " ..
                "Longbeard was the oldest.\n\nI'm a little worried about them. Those crazy dwarves packed " ..
                "more ale than food or ammunition! Maybe you can go check up on them?\n\nThe arakkoa's " ..
                "hideout, the Den of Haal'esh, can be found to the far west of here - beyond the Great " ..
                "Fissure. They set up camp northwest of there, south of Dustquill Ravine.",
        },
        [9559] = {
            description = "Promised one, you must travel north to the home of my people - Stillpine Hold. " ..
                "It is there that you will face your most daunting challenge.\n\nGo now, High Chief " ..
                "Stillpine awaits your arrival.",
        },
        [9561] = {
            description = "The translation is ready now, <name>.\n\n< Anchorite Paetheus points out a " ..
                "block of text at the end of his translation.>\n\n'The enemy is nearly upon us. We've " ..
                "gathered up all the survivors and retreated to the temple to the east. It's the last " ..
                "ground we truly hold on the island, and there is a sense among the survivors that we " ..
                "will make our last stand here. I've taken care to bury my last few possessions on the " ..
                "grounds of the temple, with the hope that someone will find them and know what happened " ..
                "here.'",
            rewardItems = {{23846, 1}},
        },
        [9562] = {
            description = "These are dark days, Promised One. Even the murlocs are kicking our tails - " ..
                "literally. Unfortunately, more than just my ego has been bruised.\n\nWhile our " ..
                "relationship with the Siltfin murlocs had always been tenuous, never could we have " ..
                "imagined that they would have the gall to attack us and steal from our food stores! " ..
                "Travel west to the Silting Shore and recover our stolen food-stuffs!\n\nAnd if you see a " ..
                "dark-skinned murloc with a patch of white fur stuck in between his webbed toes...",
            rewardMoney = 350,
        },
        [9563] = {
            description = "So you want to gain our trust? I don't trust many people these days.\n\nWe " ..
                "lost one of our own not long ago to the arakkoa. It's got me a bit on edge.\n\nTell you " ..
                "what, if you can prove your loyalty to Honor Hold and... bring me a mug of Nethergarde " ..
                "Bitter... yes, that sounds rather good about now... I'll have a deal to offer you " ..
                "then.\n\nBernie at Nethergarde Keep keeps the bitter in stock.",
        },
        [9564] = {
            description = "You recover the piece of fur that Gurf had \"lost\" in his struggle with the " ..
                "murlocs. Return the fur to Gurf and let him know that the fearsome Murgurgula has been " ..
                "slain.",
            rewardChoices = {{24438, 1}, {24439, 1}, {24440, 1}},
        },
        [9565] = {
            description = "As High Chief, my immediate concern is the root of the corruption in Stillpine " ..
                "Hold.\n\nWhy did the wildkin - once our allies - attack us? Why have they taken " ..
                "residence in Stillpine Hold?\n\nPerhaps something inside will hold the answer. Search " ..
                "Stillpine Hold for clues as to the source of corruption.",
        },
        [9566] = {
            description = "On the surface, the crystal appears to be a piece of the Exodar. Something has " ..
                "gone terribly wrong with this crystal, however, as it is blood red and rapidly " ..
                "dissolving into the water supply of the cave.\n\nThis may explain the unusually " ..
                "aggressive behavior of the creatures in Azuremyst. Return to High Chief Stillpine with " ..
                "this information.",
        },
        [9567] = {
            description = "It's good to see another new face here in Blood Watch, <class>. Although the " ..
                "blood elves are the most immediate threat, there are other sinister creatures that call " ..
                "Bloodmyst Isle home.\n\nThe Nazzivus satyr are of particular concern. They are foul, " ..
                "demonic creatures, commanding dark magics and feeding on the corruption created by the " ..
                "Exodar's crash.\n\nWe must hold them in check, but first we must learn more about them. " ..
                "Go southwest to Nazzivian and learn what you can from their grotesque monument.",
            rewardMoney = 600,
        },
        [9569] = {
            description = "Now that we have made our presence known to the satyr, we must send a message " ..
                "that we will not tolerate the Burning Legion's hounds in these lands.\n\nToo long have " ..
                "the draenei fled in the wake of the Legion and its minions, <name>. Wherever they have " ..
                "found us, they have shown no mercy.\n\nWe must not permit the satyr to exploit the " ..
                "Exodar's crash and use the corrupted crystals as weapons. Go north to where their leader " ..
                "resides in Axxarien, destroy him, and recover the corrupted crystals he has been " ..
                "gathering!",
            rewardChoices = {{27402, 1}, {27404, 1}},
            rewardMoney = 1000,
        },
        [9570] = {
            description = "After the crystal storm had subsided, a beast of myth appeared in our village. " ..
                "Brought here by the invading wildkin, this beast, the Kurken, laid waste to our village. " ..
                "Many Stillpine were slain in defense of our lands by this fiend and many have since lost " ..
                "their lives attempting to subdue the beast.\n\nIn my visions, I have seen one defeat the " ..
                "Kurken. The one must be you, <name>. You are our only hope. Enter Stillpine Hold and " ..
                "slay the Kurken. Bring me his hide as proof of deed.",
        },
        [9571] = {
            description = "Take the Kurken's hide to Moordo, on the other side of the village. He will " ..
                "fashion the hide into an item of your choice.",
            rewardChoices = {{24111, 1}, {24112, 1}},
        },
        [9573] = {
            description = "I am Stillpine the Younger, heir to the Stillpine legacy. As you can see, my " ..
                "defenders have set up a death trap for the raving wildkin that attack from inside " ..
                "Stillpine Hold. While we are able to hold them off out here, none of my defenders have " ..
                "been able to infiltrate the hold. If you could get inside and slay their leader, it " ..
                "might give us an opportunity to strike!\n\nFind Chieftain Oomooroo and destroy him. Slay " ..
                "any crazed wildkin that you encounter inside as well.",
            rewardChoices = {{24445, 1}, {24446, 1}},
        },
        [9574] = {
            description = "Bloodmyst Isle was forever changed by our arrival. The Exodar's crash " ..
                "scattered debris all over the islands and I think it's beginning to have an adverse " ..
                "effect on the wildlife.\n\nBefore I can be certain of my conclusion, I'll need to get a " ..
                "closer look. The crystals seem to have affected the trees the fastest, so it seems that " ..
                "the treants would be the most likely to show symptoms. If you bring me samples of bark " ..
                "from corrupted treants, I can begin my in-depth studies.",
            rewardMoney = 600,
        },
        [9576] = {
            description = "Examining the crudely constructed pendant, you notice the crystal pulsating " ..
                "softly. Though it emits little light, you can almost feel the crystal radiating a sense " ..
                "of wrongness.\n\nYou're not quite sure what might have possessed Cruelfin to create this " ..
                "pendant, but the find is too important to ignore. You should probably show it to someone " ..
                "at Blood Watch.",
            rewardMoney = 500,
        },
        [9578] = {
            description = "Do you think often of your family, <name>? There were a number of families " ..
                "aboard the Exodar, but I've heard of very few being reunited.\n\nI, myself, am looking " ..
                "for traces of my husband Galaen, who was a technician in the Cryo-Core. The wreckage of " ..
                "it is located to the west, and it's swarming with blood elves!\n\nI must find out what " ..
                "became of Galaen! Even news of his death is better than never knowing. My husband will " ..
                "be wearing a pendant identical to my own; they were a gift from my sister.",
        },
        [9579] = {
            description = "You have no means of identifying the corpse as Galaen with the information " ..
                "Morae gave you, but the clothing appears to have been torn in search of " ..
                "valuables.\n\nThe blood elves in the area would've claimed anything of value from the " ..
                "wreckage, including Galaen's jeweled amulet.\n\nAlthough her husband did not survive the " ..
                "crash, you believe that Morae would be grateful if you recovered her husband's amulet " ..
                "from the blood elves.",
            rewardChoices = {{26011, 1}, {26025, 1}, {26037, 1}},
            rewardMoney = 1000,
        },
        [9580] = {
            description = "As I'm sure you've seen in your time on Bloodmyst Isle, very little remains " ..
                "unchanged by our arrival. My training and experience has taught me that even the " ..
                "products of an environment like this one can be put to use.\n\nWith so few resources, we " ..
                "must rely on our ingenuity to provide for us. I've been supplementing our stores with " ..
                "meat from the bears that wander this island. With the proper preparation, it can safely " ..
                "be eaten. If you're going to be out in the field, why not help replenish our stocks?",
            rewardMoney = 800,
        },
        [9581] = {
            description = "Welcome to Blood Watch, <class>. Seeing to the defenses of the outpost is my " ..
                "primary concern, but I've also been tasked with a variety of other duties by our leaders " ..
                "at the Exodar.\n\nThe problem is that it's hardly safe to send out large amounts of " ..
                "researchers when the island is this dangerous. I need someone to gather a series of " ..
                "crystal samples from various sites on the island.\n\nThe first sample I need must come " ..
                "from the ravager infested ship debris south of the town and across the bridge.",
            rewardChoices = {{26006, 1}, {26020, 1}, {26032, 1}},
            rewardMoney = 400,
        },
        [9582] = {
            description = "When the ship crashed, our menagerie was scattered on the northeast beaches of " ..
                "this isle. I have been handed a key that unlocks the cage holding one of the deadlier " ..
                "specimens, a death ravager. The creature is little armored but resistant to most magic. " ..
                "It must be killed by a simple blade.\n\nTake this key and release the creature from both " ..
                "its prison and its pain. We cannot afford to have it escape and cause even more damage " ..
                "to the ecology than we already have.",
        },
        [9583] = {description = "An honorable person gives me cloth", rewardMoney = 44000},
        [9584] = {
            description = "Now that we have the baseline crystal, we're going to need samples from more " ..
                "dangerous areas of the island to complete the set I'll be sending to the Exodar.\n\nThe " ..
                "next sample must come from the crystals controlled by the blood elves in the Bladewood " ..
                "area to the northwest of Blood Watch. I have heard reports that they alter and harvest " ..
                "the crystals for use in some magical apparatus. See if you can find one that has not yet " ..
                "been incorporated into one of their devices, and mine a sample from it.",
            rewardMoney = 600,
        },
        [9585] = {
            description = "There's just one sample remaining before I can send this set of crystals to " ..
                "the Exodar, <name>. The final sample must come from the satyr stronghold of Axxarien to " ..
                "the northwest.\n\nI'm not certain what to expect from this crystal sample, but I'm sure " ..
                "there will be some signs of corruption. Take care to mine your shard from the crystal " ..
                "that looks like the ones you took your previous samples from, or else our researchers " ..
                "cannot make a valid comparison.",
            rewardMoney = 1000,
        },
        [9594] = {
            description = "The armor scrap is forged from a deep black metal that seems to absorb light. " ..
                "Although it doesn't appear to be enchanted, there is an unmistakable sense of wrongness " ..
                "about it.\n\nSuch armor is only used by one force - the Burning Legion. The Legion's " ..
                "presence here can only mean that they're intending to mobilize the island's satyr " ..
                "against the draenei.\n\nTake action against the local satyr, then return to Blood Watch " ..
                "and show this armor scrap to Vindicator Aalesia.",
            rewardMoney = 600,
        },
        [9602] = {
            description = "You must get this information to your people, <name>. While your brave acts " ..
                "have certainly slowed down the plans of Kael'thas and his dark master, the attacks will " ..
                "undoubtedly continue.\n\nTake the traitor's communication to your leaders. They must see " ..
                "this for themselves. Perhaps they will be able to better understand some of what was " ..
                "written.",
        },
        [9603] = {
            description = "Welcome to Azure Watch, <class>. Please excuse the disorder you see around " ..
                "you. It's easy to take simple things for granted, like a fully furnished and stocked " ..
                "inn, until you're forced to build one from nothing.\n\nWe've managed to salvage this pod " ..
                "for a building, but without the proper furnishings and first aid supplies, the inn is " ..
                "little more than a glorified tent. Nurguni at the Exodar has offered to put together a " ..
                "package to help with our most immediate needs, but I need someone to deliver this list " ..
                "to him.",
        },
        [9604] = {
            description = "For a small fee, you can rent one of my hippogryphs to fly you to the " ..
                "Exodar.\n\nTaking the hippogryph is a faster, not to mention safer, alternative for " ..
                "someone carrying an important message. If you'd like to take a ride, speak to me again " ..
                "and I'll make the arrangements.",
        },
        [9605] = {
            description = "Here's the box, <name>. That should be enough for Chellan to get the inn up " ..
                "and running. Let her know that she can keep sending in orders as the need arises. Azure " ..
                "Watch urgently needs a place to care for the wounded and put up any travelers they " ..
                "receive.\n\nWhen you're ready to return to Azure Watch, seek out Stephanos near the Seat " ..
                "of the Naaru in the Exodar.",
        },
        [9606] = {
            description = "If I remember correctly, Azure Watch's hippogryph master is Zaldaan. If you've " ..
                "spoken to him before, then you can take one of my hippogryphs to him.\n\nThat's a good " ..
                "lesson to know: hippogryphs are always trained to fly to their capital city, but they'll " ..
                "only take you to a remote hippogryph master after you've already been there.\n\nSince " ..
                "you arrived on one of Zaldaan's hippogryphs, you can also use that route to return to " ..
                "Azure Watch with the caregiver's supplies.",
            rewardMoney = 350,
        },
        [9612] = {
            description = "You saved my life, <name>! Thank you so much! That beast would have torn me to " ..
                "shreds if it weren't for you.\n\nIf you see the exarch at Azure Watch, tell him of what " ..
                "you did. I'm sure he'll be pleased to hear such news!",
            rewardMoney = 450,
        },
        [9616] = {
            description = "This appears to be a bounty ledger. You cannot understand the blood elf " ..
                "language but you note that there is a picture depicting a dead draenei, a smiling blood " ..
                "elf standing over the corpse, and a symbol of what you think is some sort of blood elf " ..
                "currency.\n\nThey've put a hit out on draenei! You must inform the exarch.",
            rewardChoices = {{24141, 1}, {24142, 1}, {24144, 1}},
        },
        [9620] = {
            description = "As we've gotten ourselves established here at Blood Watch, I've been sending " ..
                "out survey teams to create more reliable maps of the island. In most cases, they " ..
                "returned unharmed with the data we need, but the team I sent east to the ruins hasn't " ..
                "reported back.\n\nI worry about what might have happened to them, but I can't spare the " ..
                "men to send another mission after them. Find them, <name>, and lend them any assistance " ..
                "they require to return with their survey data.",
        },
        [9621] = {
            description = "There were doubts about our capabilities among our potential new allies. Of " ..
                "what use could we be to them when perceived as unable to deal with our problems at " ..
                "home?\n\nThis changes everything. No longer will our power be questioned. We'll be able " ..
                "to join the Horde as equals.\n\nTake this letter to Sylvanas, ruler of the Forsaken. " ..
                "She's already on our side but the news of Dar'Khan's death will be music to her ears. " ..
                "Prepare for a long trip, <name>. If all goes well she will send you to Orgrimmar.",
        },
        [9622] = {
            description = "The Hold is saved and soon my people will make their way back to the ancestral " ..
                "home. The prophecy has come to pass and a new age of prosperity begins for the " ..
                "Stillpine.\n\nBut I fear that darkness looms ahead for your own people. There are " ..
                "questions left unanswered - visions of prophecy unseen.\n\nReturn to your leaders and " ..
                "tell them of what you have seen here.\n\nAnd Promised One, should you ever require the " ..
                "aid of Stillpine, you have merely to ask.",
        },
        [9623] = {
            description = "You have survived the wilds of our new home and shown yourself a cut above the " ..
                "others. I believe that you have come of age to assist those battling on the front lines " ..
                "of Bloodmyst. The Hand of Argus could use a <race> like you.\n\nReport to Torallius the " ..
                "Pack Handler. You will find him outside the Exodar, tending to the elekk. Give him these " ..
                "orders so that he may direct you towards your new duties on Bloodmyst.",
        },
        [9624] = {
            description = "I've made a wonderful discovery, <class>. On the uncorrupted part of the " ..
                "island grows a remarkable fruit called the sand pear. They're found near the bottoms of " ..
                "the trees.\n\nI've been preparing pies from them, but if I'm not careful, the elekk will " ..
                "start to wander over and steal my fruit. I've taken to gathering enough to share with " ..
                "the animals, but my stores are gone and the craving for pie has returned. Would you be " ..
                "willing to help gather the fruit I need for another batch of pies? I promise I'll share!",
            rewardChoices = {{26004, 1}, {26018, 1}, {26031, 1}},
            rewardItems = {{24072, 20}},
            rewardMoney = 500,
        },
        [9625] = {
            description = "Is he crazy? Entrusting something like this to some no-named <race> " ..
                "youngling!\n\nJust remember this kid: You'll never make it as a Hand of Argus! You don't " ..
                "have the guts!\n\nI guess I'll have to humor him this time. Speak with Vorkhan at " ..
                "Kessel's Crossing on Bloodmyst Isle. Just follow the road north from here, and when it " ..
                "forks, just keep on going north.",
            rewardMoney = 100,
        },
        [9626] = {
            description = "I haven't lost any love for my homeland or its people, as you know. I've " ..
                "fought tooth and nail for Silvermoon to be allowed a place beside Undercity and " ..
                "Orgrimmar at the negotiating table.\n\nThis should silence any opposition. Take this " ..
                "letter to the Warchief in Orgrimmar. As leader of the Horde he will have the final say " ..
                "on accepting your race's pledge.\n\nI've added my own seal to the letter as a personal " ..
                "endorsement. Go northwest of the city and board the zeppelin bound for Durotar at the " ..
                "tower.",
        },
        [9627] = {
            description = "Your people suffered a great betrayal by the Alliance. You've succeeded in " ..
                "fending off Darnassian attacks as well as spies from Ironforge. Now you've defeated a " ..
                "powerful Scourge leader at the footsteps of your home. Your worthiness is no longer in " ..
                "question.\n\nIt is now apparent that you need us and we need you. Return to Lor'themar. " ..
                "Tell him I received his message loud and clear.\n\n<The warchief crushes the letter " ..
                "inside his palm.>\n\nWelcome to the Horde, elf.",
        },
        [9628] = {
            description = "It's too late to assist the cartographers in completing their mission, but it " ..
                "appears they collected the data Harbinger Mikolaas was expecting. The crystal storing " ..
                "their survey information was not among their ransacked packs, so it must be in the hands " ..
                "of the Wrathscale naga.\n\nYou know that Harbinger Mikolaas will be saddened by the loss " ..
                "of the survey crew, but would want to salvage the survey data.",
            rewardItems = {{26016, 1}},
            rewardMoney = 600,
        },
        [9629] = {
            description = "The Blacksilt murlocs on the southwestern coast are curious creatures. In some " ..
                "ways, they act barely sentient, yet in others, they show a remarkable degree of " ..
                "organization.\n\nI have a few theories about that, but no real way to test them until " ..
                "recently. I've devised a method that will allow me to track the murlocs I'm interested " ..
                "in without doing any lasting harm or interfering with their natural behavior. If you're " ..
                "willing to help with the marking, I'll gladly pay you for your assistance.",
            rewardChoices = {{26008, 1}, {26022, 1}, {26034, 1}},
            rewardMoney = 600,
        },
        [9630] = {
            description = "Your name is getting around, <name>. You've made your way into and out of " ..
                "Karazhan - more than most mortals can claim.\n\nI need to ask a special favor of you. As " ..
                "part of our research, the Violet Eye has been trying to track down Medivh's own " ..
                "journal.\n\nUnfortunately, none of the agents we've sent inside have come out. Wravien " ..
                "was the last to be sent; see if you can find him and see about any leads on the journal.",
        },
        [9631] = {
            description = "There is a small detail I've forgotten to take into account. The residue of " ..
                "Medivh's essence contained in this bone fragment is completely devoid of life - just " ..
                "like Arcanagos.\n\nThere is a way, however. And I know just the person to help " ..
                "us.\n\nTravel to Area 52 in Netherstorm and show the bone fragment to Kalynna Lathred. " ..
                "She will know just what to do.",
        },
        [9632] = {
            description = "Harbinger Mikolaas has done a commendable job of safeguarding Blood Watch, " ..
                "<class>, but our enemies are many and our resources few.\n\nOur weakness is well known " ..
                "to our enemies, but your contact with the forces of the Alliance is something they " ..
                "haven't accounted for. I have prepared a letter of introduction to the people of " ..
                "Auberdine, the closest Alliance settlement, proposing cooperation in the fight against " ..
                "our foes. Take it with you and seek out Huntress Kella Nightbow near the docks west of " ..
                "the Exodar.",
        },
        [9634] = {
            description = "One thing we've learned in our travels is that extreme care must be taken when " ..
                "introducing wildlife from one world to another. When the Exodar crashed, it was carrying " ..
                "specimens of various Outland species, including an insectoid predator called the " ..
                "ravager.\n\nSome of the specimens were lost, but many others survived and took to the " ..
                "wild. If we don't keep them in check, they will upset the natural balance here on the " ..
                "islands.\n\nYou'll find these ravagers to the west of Kessel's Crossing, near the coast.",
            rewardChoices = {{26049, 1}, {26051, 1}, {26053, 1}, {27389, 1}},
            rewardMoney = 400,
        },
        [9635] = {
            description = "The swamp gas is truly amazing, and can be very useful, mon! But first, you " ..
                "gotta be able to suck it up, and that, my friend, requires a Zapthrottle Mote " ..
                "Extractor.\n\nNow, I could just give you the schematics, but I'll need something in " ..
                "return first. How about some spare parts? Last time I checked, there were plenty lying " ..
                "around near the broken steam pump at the Dead Mire, far to the northeast.\n\nI heard " ..
                "that the withered giants spread the pieces all over that dried-out lake bed.",
            rewardItems = {{23888, 1}},
        },
        [9636] = {
            description = "Have you seen the swamp gas? Isn't it just shiny?\n\nIt takes a Zapthrottle " ..
                "Mote Extractor to suck 'em dry though. I could give you the plans to make one, but I " ..
                "really need some spare parts to fix stuff 'round here.\n\nLast time I checked, there " ..
                "were plenty of parts lying around near the steam pump at the Dead Mire to the northeast. " ..
                "I think the withered giants broke the pump out there.\n\nShall we help each other out?",
            rewardItems = {{23888, 1}},
        },
        [9637] = {
            description = "I left the Kirin Tor in pursuit of knowledge forbidden by those of my order; " ..
                "it is beyond ironic that I am now asked to assist them with that very same " ..
                "knowledge.\n\nIf I'm to perform this favor for you, you will have to do something for me " ..
                "first. I want you to obtain two of the tomes I've been searching for.\n\nThe first one " ..
                "is called the Tome of Dusk and is owned by the orc warlock known as Nethekurse. The " ..
                "second, known as the Book of Forgotten Names, belongs to the arakkoa known as Darkweaver " ..
                "Syth.",
        },
        [9638] = {
            description = "Was I supposed to be looking for this journal? It can't be... I don't quite " ..
                "recall...\n\nOf course! It is Gradav you're thinking of. He was looking for the book " ..
                "when I got here. Surely he must've found it by now; why don't you go ask him about " ..
                "it?\n\nI'd lend you a hand... but these books are just so... interesting!",
        },
        [9639] = {
            description = "Journal, what journal? You're thinking of Kamsis, surely.\n\nGo and ask her " ..
                "about it. I can't leave my project right now or all my work will be wasted!",
        },
        [9640] = {
            description = "Let me think for a second. The Violet Eye... Medivh's Journal... Why yes, it's " ..
                "all coming back to me now.\n\nI believe I had the journal you're looking for before I " ..
                "started to read these scrolls...\n\nAran... yes, Aran asked me for the book. So nicely " ..
                "too. I just had to give it to him. He's Medivh's father after all, did you know?",
        },
        [9641] = {
            description = "The Exodar's crash scattered pieces of fouled crystals all over Bloodmyst " ..
                "Isle, corrupting the water and the landscape.\n\nWe've even begun finding pieces of the " ..
                "crystals inside the flesh of animals taken for meat. I've uncovered a way to purify the " ..
                "shard and turn them into functional crystals, so if you bring me enough shards, I'll " ..
                "trade one of my completed crystals for them. So far I've found the shards in the bodies " ..
                "of bears, ravagers, flutterers, and treants inhabiting the corrupted part of the island.",
            rewardChoices = {{23985, 1}, {23986, 1}, {23989, 1}},
        },
        [9642] = {rewardChoices = {{23985, 1}, {23986, 1}, {23989, 1}}},
        [9643] = {
            description = "A good woodsman makes use of every available resource, <class>. Even the most " ..
                "bizarre creatures possess attributes we can use to our advantage.\n\nWith Blood Watch " ..
                "under constant assault from the Sunhawks, we're looking to a variety of natural defenses " ..
                "including traps. The lasher's thorny vines are perfectly suited to the construction of " ..
                "the traps I have in mind. The combination of sharp spines and deadly toxin will fell " ..
                "unwary attackers. Bring me the vines of mutated constrictors so that I can begin my work.",
            rewardMoney = 700,
        },
        [9644] = {
            description = "You fulfilled your end of the deal. I will now bind your essence to that of " ..
                "the dead blue dragon.\n\nThere is an urn in the Master's Terrace, should you touch that " ..
                "urn, you'll now release its energy and bring life back to the charred remains of " ..
                "Arcanagos. Defeat the creature and retrieve its essence immediately! You will need to " ..
                "take it to Alturus.\n\nShould you fail, the stars predict you will have let a great " ..
                "terror loose upon the skies.\n\nA terror known as Nightbane!",
            rewardChoices = {{31118, 1}, {31117, 1}, {31116, 1}},
        },
        [9645] = {
            description = "Journal? What journal?\n\nOh, right. That journal! The Violet Eye sent me here " ..
                "for it. It's all coming back now.\n\n< Kamsis points to a page in the journal.>\n\nThis " ..
                "is the page that Alturus is interested in. Did you know that while other people's " ..
                "journals serve as a record of their memories, Medivh's is literally just that?\n\nTry " ..
                "it. Go to the Master's Terrace and read the page; you'll see just what I mean. Might as " ..
                "well report to Alturus while you're at it. I'm afraid I'll be here for a while.",
        },
        [9646] = {
            description = "By order of Harbinger Mikolaas: A bounty of 18 silver to be paid to the brave " ..
                "soul who returns with proof of the marauding bear Deathclaw's demise.\n\nDeathclaw " ..
                "should be considered extremely dangerous and is responsible for the killing of a survey " ..
                "team on the coast to the northwest of Blood Watch. Travelers are advised to avoid the " ..
                "area.",
            rewardChoices = {{27400, 1}, {27398, 1}},
            rewardMoney = 1800,
        },
        [9647] = {
            description = "When we first encountered flutterers, they showed few signs of mutation. As " ..
                "the corruption got progressively worse, the moths and other species began to show signs " ..
                "of contamination.\n\nIt has progressed to the point where they damage nearly everything " ..
                "they come in contact with. They're amplifying the damage being done by the crystal " ..
                "shards scattered by the Exodar's crash. We have no choice but to begin culling their " ..
                "population in the lands north of Blood Watch.",
            rewardChoices = {{26013, 1}, {26026, 1}, {26038, 1}},
            rewardMoney = 800,
        },
        [9648] = {
            description = "Did you know mushroom hunting is far more dangerous than mushroom consumption? " ..
                "Mushroom hunters expose themselves to many unknowns - not including potential wildlife " ..
                "dangers!\n\nWhat would life be without a little danger? I am in need of mushrooms for my " ..
                "collection. Scattered throughout these unexplored wilds you will find four different " ..
                "types: An aquatic stinkhorn, a blood mushroom, a ruinous polyspore, and a fel cone " ..
                "fungus. They are each unique to various regions in Bloodmyst. Bring them to me.",
            rewardChoices = {{26014, 1}, {26028, 1}, {26040, 1}},
            rewardMoney = 1300,
        },
        [9649] = {
            description = "Good to see you again, <name>! You were exceptionally efficient in completing " ..
                "the last task that I offered you. Perhaps you would be interested in another?\n\nTo the " ..
                "northeast lies Wyrmscar Island, home to a rare species of mushroom known as Ysera's tear " ..
                "- named after the green dragonlings that inhabit the island. I only require a small " ..
                "sampling of the mushroom, but I must warn you that the denizens of the island do not " ..
                "welcome visitors. Tread carefully.",
            rewardChoices = {{26005, 1}, {26019, 1}, {26030, 1}},
            rewardMoney = 3000,
        },
        [9663] = {
            description = "You're just in time, <name>. Blood elf activity in this area has doubled in " ..
                "the past week. Our agents have informed us that the blood elves that call themselves " ..
                "Sunhawks plan to launch an offensive upon Azuremyst soon. I need you to get a warning " ..
                "out to our allies and compatriots.\n\nWarn High Chief Stillpine at Stillpine Hold, " ..
                "Exarch Menelaous at Azure Watch and Admiral Odesyus at Odesyus' Landing.\n\nTime is of " ..
                "the essence so I am lending you my elekk. Be sure to keep it out of water.",
        },
        [9666] = {
            description = "Have you seen the serpent men? The ones that call themselves naga?\n\n< Kessel " ..
                "spits.>\n\nThey dared make an advance upon this camp under cover of darkness only three " ..
                "nights ago. Can you believe the audacity of those primitive beasts?\n\nI need you to " ..
                "deliver a message to their leadership, <name>. To the northeast is Wrathscale Lair, home " ..
                "to Lord Xiz. Find him, slay him where he stands and drive this banner through his " ..
                "corpse.\n\nLet them know fear whenever they should see our standard!",
            rewardChoices = {{26012, 1}, {26027, 1}, {26039, 1}},
            rewardMoney = 600,
        },
        [9667] = {
            description = "Help me, <name>! The Bristlelimb captured me and are planning to sacrifice me " ..
                "to their foul gods!\n\nHigh Chief Bristlelimb holds the key that opens the cage. To " ..
                "force him to appear, you must slaughter the evil Bristlelimb furbolgs that inhabit the " ..
                "enclave, just two camps to the west of this camp. If you kill enough of them, he will " ..
                "surely come for vengeance! When he shows up, kill him and get the key!\n\nMy father will " ..
                "richly reward you if you can save me!",
            rewardChoices = {{24342, 1}, {24343, 1}},
        },
        [9668] = {
            description = "A Hand of Argus soldier is many things: Obedient, brave, intelligent, and " ..
                "above all, honorable. You may yet exhibit some of these traits, <class>.\n\nReport to " ..
                "Exarch Admetius at Blood Watch if you are still interested in joining the Hand. He and " ..
                "his subordinates will further train you in the ways of the draenei soldier.\n\nAnd " ..
                "remember this, <name>: Honorable people do not always perform honorably. Sometimes they " ..
                "cannot.\n\nYou will find Blood Watch just up this road, to the north.",
        },
        [9669] = {
            description = "About a week ago, my research team and I were out exploring the western wilds " ..
                "of Bloodmyst when we were attacked by bloodthirsty spiders. The effect of the crystal " ..
                "contamination was clearly evident as these spiders were massive and extremely " ..
                "aggressive.\n\nI managed to escape but my team wasn't so lucky. We must not let the same " ..
                "fate befall others. Go west to the Amberweb Pass and destroy the spiders and their " ..
                "matriarch, Zarakh.",
            rewardMoney = 3000,
        },
        [9670] = {
            description = "It was a bloody mess, <name>. We were ambushed by a large pack of these " ..
                "spiders. Their progenitor descended upon us with incredible speed and wrapped us up in " ..
                "cocoons.\n\nAfter we were webbed, she began to lay eggs near us. We were to be food for " ..
                "her young! FOOD!\n\nI managed to cut my way out and escape but I will not leave the " ..
                "others behind. So far I've been unsuccessful in nearing the pass. Would you lend a " ..
                "hand?\n\nDestroy those cocoons! Hopefully some of our team is still alive!",
            rewardItems = {{26017, 1}},
        },
        [9672] = {
            description = "Dear friend,\n\nMy hand trembles as I ink this letter. I pray that it reaches " ..
                "you in time.\n\nLast night, Edward Hanes, captain of the ship 'Lost Hope', appeared " ..
                "before me in my tent. The same Edward Hanes that died of scurvy 20 years ago.\n\nThis " ..
                "apparition told me a tale that made my heart tremble. A tale that I need you to hear and " ..
                "a mission that I need you to accomplish. Will you do it? Will you seek out Edward on " ..
                "Wyrmscar Island, northeast of your base?\n\nRegards,\n\nAdmiral Odesyus",
        },
        [9674] = {
            description = "They say when the world was sundered, this land cried the loudest. It was here " ..
                "that thousands of night elves faded into oblivion and in their place rose terrible " ..
                "creatures of hate - the naga.\n\nObedient to their twisted queen, Azshara, they would " ..
                "destroy all that would dare pass through their sea. It would remain this way for " ..
                "thousands of years - until now.\n\nThe first order of business is to remove the " ..
                "bloodcursed naga from the reef.",
        },
        [9676] = {
            description = "As you advance within your class, you will want to take advantage of the " ..
                "training that your class trainer can provide you. For young paladins here on Sunstrider " ..
                "Isle, your trainer is Jesthenis Sunstriker. Speak with Jesthenis and see what training " ..
                "he has available for you. The things he will teach do have a cost, so bring some coin " ..
                "with you.\n\nYour trainer - as with all the trainers on Sunstrider Isle - is inside the " ..
                "Sunspire on the lower level.",
        },
        [9680] = {
            description = "Kamsis was right! This information is extremely important.\n\nIf Medivh weaved " ..
                "his own essence into the magic he used to defeat the dragon, it is quite possible we " ..
                "could retrieve even a faint residue of that essence from the dragon's remains. What " ..
                "great insight may lie beneath the ashes of Deadwind Pass, awaiting discovery.\n\nGo to " ..
                "the mountains south of Karazhan and bring me back a bone fragment of seemingly draconic " ..
                "origin.",
        },
        [9682] = {
            description = "On a ledge of the reef, deeper than where you found the bloodcursed naga, you " ..
                "will find the hopeless ones: The bloodcursed voyagers, ghosts of those taken by the " ..
                "bloodcurse.\n\nIt is regrettable, what I ask of you now... but they must be destroyed " ..
                "and their cursed shells brought back to me.\n\nTheir souls must be put to rest. Return " ..
                "to me when you have done as asked and I shall give you one final task.",
        },
        [9683] = {
            description = "To the south you will find Bloodcurse Isle. Atop the island you will find a " ..
                "shrine dedicated to the beloved queen of the naga, Azshara. Destroy the statue - burn it " ..
                "in effigy! This will surely draw the ire of Atoph, the Bloodcursed leader.\n\nSlay Atoph " ..
                "and return to me!",
            rewardItems = {{24334, 1}},
        },
        [9687] = {
            description = "Not long ago, the once tranquil owlkin of the region appeared on the shores of " ..
                "this island. One by one they would come to steal the bones of the fallen dragons. I do " ..
                "not know what would cause these creatures such distress or why they would want the bones " ..
                "of the deceased, but the spirits of the brood have grown restless due to this " ..
                "sacrilege.\n\nTo the west, across the Crimson Reach, you will find Ragefeather Ridge. " ..
                "Venture to the owlkin encampments and recover the pilfered dragon bones.",
        },
        [9688] = {
            description = "The whelps that you see on this island are the agitated spirits of the green " ..
                "dragonflight. Like me, they are bound to the land, unable to ascend to their final " ..
                "resting place in the Dream.\n\nRecovering the bones of the fallen has settled them " ..
                "somewhat but you must take further action.\n\nDestroy their ethereal manifestations. I " ..
                "cannot leave this place until it is done. They must be released!",
        },
        [9689] = {
            description = "Many of the black dragonflight were slain during the attacks. One of them, a " ..
                "lieutenant of Deathwing himself, still haunts this place. If you look to the heavens, " ..
                "you can see his spectral countenance circling the skies. His hatred is so great that he " ..
                "remains even in death.\n\nTake the bones that you gathered for me earlier to the top of " ..
                "the mountain on this island and place them in the ever-burning pyre. This act should " ..
                "signal Razormaw to descend. When he does, slay his undead form.",
            rewardChoices = {{24346, 1}, {24347, 1}, {24348, 1}},
        },
        [9693] = {
            description = "What does Argus mean to you, <name>? Many draenei probably do not know or " ..
                "remember our home planet. It is there that we split from the man'ari: the twisted " ..
                "demonic reflections of ourselves that were 'gifted' by Sargeras. Or as they call " ..
                "themselves, eredar.\n\nEredar... this word once held meaning.\n\n<Admetius smacks his " ..
                "lips as if to taste the word.>\n\nDisgusting.\n\nLet us not waste anymore time. Find " ..
                "Vindicator Boros to begin your training.",
        },
        [9694] = {
            description = "Blood Watch is one of two forward bases operated by the Hand of Argus. You " ..
                "have already been to the other base, Azure Watch; things are completely different in " ..
                "Bloodmyst. When we first got here, the land was as beautiful as Azuremyst. We even " ..
                "called it Silvergale but now sickness is spreading across the land, worse yet, the blood " ..
                "elves that we were battling on the Exodar survived the crash. This brings me to your " ..
                "assignment: Venture northwest into Bladewood and terminate any blood elves that you find.",
            rewardChoices = {{26050, 1}, {26054, 1}, {27640, 1}},
        },
        [9696] = {
            description = "Our chief interrogator, Elysia, is fluent in Thalassian. Take the document to " ..
                "her and see what she has to say.",
        },
        [9697] = {
            description = "There's important research to be conducted into the ecology of the local " ..
                "creatures, especially the sporelings and bog lords of the marsh. And trust me, once you " ..
                "get out into the field, you'll find the work to be challenging.\n\nSeek out Watcher " ..
                "Leesa'oh at the Cenarion Watchpost in the western region of the marsh toward the south. " ..
                "Follow the path west and you will eventually find her. She can be a bit -- studious -- " ..
                "but don't let that get to you.\n\nOh, and watch out for her cat.",
        },
        [9698] = {
            description = "I need you to deliver the translated documents to Velen personally, <name>. I " ..
                "don't trust that deranged messenger.\n\nExplain to the Prophet that the blood elves are " ..
                "receiving reinforcements from the Outland and that they have a spy amongst the draenei " ..
                "at the Exodar. Velen resides in the Vault of Lights inside the Exodar.\n\nMake haste!",
        },
        [9699] = {
            description = "I thank you for the timely delivery, <name>. You are turning out to be one of " ..
                "the Hand's better agents.\n\nIf only we knew who they reported to in Bloodmyst and more " ..
                "importantly, where this sun portal was... They seem to have it tightly guarded - " ..
                "wherever it may be.\n\nWould you be interested in some reconnaissance work?\n\nIf so, " ..
                "take these orders back to Vindicator Boros. He will give you your next mission.",
        },
        [9700] = {
            description = "Velen states that if the blood elves have been opening rifts between this " ..
                "island and the Outland, there will be residue or anomalies left in the areas where the " ..
                "portals have been opened. You must search the island for locations that exhibit or " ..
                "display these anomalies.\n\nBe warned, <name>; some of these anomalies will be creatures " ..
                "from the void itself. Should you find void anomalies, slay them! Report back to me with " ..
                "any new information that you may find. Begin your search to the north, near the Warp " ..
                "Piston.",
            rewardChoices = {{26010, 1}, {26024, 1}, {26036, 1}},
        },
        [9701] = {
            description = "We need to learn all that we can of the sporelings at Sporeggar and their " ..
                "relationship to the creatures around them. One way to do that is what I'm doing; passive " ..
                "observation while making a note of their interactions.\n\nI need you to head over to the " ..
                "Spawning Glen to the west. Investigate the whole area and then return to tell me what " ..
                "you saw.",
            rewardMoney = 29000,
        },
        [9702] = {
            description = "I was wondering why the bog lords were crossing the road to go to the Spawning " ..
                "Glen - they must be starving for some reason. This just will not do!\n\nI mean, normally " ..
                "I wouldn't get involved, but if they continue to eat all of the sporeling pods they'll " ..
                "wipe them out!\n\nHere's what we'll do: I'll stay here and you head to the Quagg Ridge " ..
                "to the east and look for dietary clues as to why they're raiding the sporelings.",
            rewardMoney = 31000,
        },
        [9703] = {
            description = "We have others pursuing leads on the sun portals, <name>. I need you to focus " ..
                "on the task at hand.\n\nBoros has received new reports of another crash site. What we've " ..
                "since discovered is that the crash site is actually the Exodar's cryo-core. This is a " ..
                "pod holding area that houses pods exactly like the ones we draenei crawled out of in " ..
                "Ammen Vale.\n\nThis area also holds medical supplies. Head to the Cryo-Core, directly " ..
                "west of Blood Watch. Search for supplies and search for survivors.",
            rewardChoices = {{26052, 1}, {27390, 1}, {27641, 1}},
        },
        [9704] = {
            description = "It's hard work being an outrunner between Sunstrider Isle and Falconwing " ..
                "Square. Tight deadlines, long hours and worst of all... the Wretched!\n\nThe road south " ..
                "goes through the ruins of Silvermoon... the place is crawling with Wretched ready to " ..
                "kill you for a few mana crystals. Unfortunately, I think that's what happened to the " ..
                "last outrunner we sent with one of Erona's packages.\n\nI see you're eager to prove " ..
                "yourself. Venture into Dawning Lane and see if you can find any traces of our outrunner.",
        },
        [9705] = {
            description = "You take the package and confirm that indeed it comes from Magistrix Erona. " ..
                "Alarion would probably want you to bring it to her.",
            rewardMoney = 50,
        },
        [9706] = {
            description = "Your hands tremble as you pick up the book. Kuros must be told about this " ..
                "tragedy. Return the book to him.",
        },
        [9708] = {
            description = "Yes, that's it, I knew I had seen this particular phylum of mushroom elsewhere " ..
                "in the marsh!\n\nTo the north is a place known as the Hewn Bog. Odd name for the place " ..
                "if you ask me, but I've never been there. I'll need samples of those mushrooms to " ..
                "confirm my hypothesis.\n\nJust be careful, <class>. I'd heard that ogres have moved in " ..
                "to the area, so you'll have to get the samples from them. Could that be why the bog " ..
                "lords are no longer going there for their food?",
            rewardMoney = 29000,
        },
        [9709] = {
            description = "<class>, I've got an idea. I want you to head north again, this time into the " ..
                "heart of ogre territory!\n\nNorthwest of the Hewn Bog there is a place named Ango'rosh " ..
                "Stronghold, which sits on a floating island across a large mushroom bridge.\n\nThe ogres " ..
                "must be storing the harvested mushrooms there. I bet you'll find them all over the " ..
                "place, and probably on the ogres themselves, too!\n\nBring me a sufficient number and I " ..
                "will try to do something about providing the bog lords with a new source of nourishment.",
            rewardChoices = {{25525, 1}, {25530, 1}, {25534, 1}, {31661, 1}},
            rewardMoney = 62000,
        },
        [9711] = {
            description = "Matis will be brought to justice, <name>; and I want you to be the one to find " ..
                "him and bring him back to the Triumvirate.\n\nScour the island for this killer. Should " ..
                "you find him, use this flare gun. When my trackers see the flare, they'll come and " ..
                "assist in capturing Matis. Return to me after he's been captured.",
            rewardChoices = {{26007, 1}, {26021, 1}, {26033, 1}},
        },
        [9716] = {
            description = "We came to Outland expecting to find small pockets of life. What we discovered " ..
                "in Zangarmarsh was a lush environment with a thriving ecosystem.\n\nOur initial " ..
                "assessment of the area was deceiving, however. The water levels at the lakes and marshes " ..
                "have consistently been going down since we started taking measurements.\n\nThe impact " ..
                "this could have on the local animal and plant life is disastrous. Go to Umbrafen Lake, " ..
                "southwest of here, and look for clues related to this water depletion.",
            rewardMoney = 29000,
        },
        [9718] = {
            description = "We must determine how widespread the naga's activity truly is and react " ..
                "accordingly.\n\nExploring each body of water in Zangarmarsh could be a lengthy " ..
                "undertaking. If you allow me to, I will use my magic to mold your shape to one more " ..
                "suited to scouting the marsh.\n\nHold this amulet above the balcony near me when you're " ..
                "ready to begin. I will guide your way back to safety after we're done.",
        },
        [9720] = {
            description = "I cannot begin to comprehend why the naga would drain the water out of their " ..
                "own habitat. What I do understand is a need to put a stop to their operations.\n\nThese " ..
                "seeds carry with them the rage of the earth. Take them to the steam pumps operated by " ..
                "the naga and use them on their controls.\n\nThe vines that grow from the seeds will be " ..
                "as thick as your arm and as strong as iron. Go, <name>. Restore the balance that the " ..
                "naga have upset.",
            rewardMoney = 31000,
        },
        [9724] = {
            description = "The Cenarion Expedition has become a large organization with a good degree of " ..
                "autonomy. These events are important enough that we need to warn the Cenarion " ..
                "Circle.\n\nDo not worry, I will not ask you to travel back to Moonglade; we have " ..
                "emissaries as nearby as Hellfire Peninsula.",
            rewardMoney = 16000,
        },
        [9726] = {
            description = "The naga of the Bloodscale Enclave to the northeast have begun to kill our " ..
                "people. We cannot allow this to continue, <class>!\n\nWe suggest that you teach them a " ..
                "lesson as proof of our friendship.",
            rewardChoices = {{27749, 1}, {27750, 1}, {27751, 1}, {27752, 1}},
        },
        [9727] = {
            description = "Reports have come in that the naga of the Bloodscale Enclave to the northeast " ..
                "continue to kill our people. We thought that you had dealt with this, <class>!\n\nI " ..
                "suggest that you to teach them a lesson as proof of our continued friendship.",
        },
        [9728] = {
            description = "While the druids from the expedition have made themselves busy studying plants " ..
                "and researching the lakes, I've made it my business to deal with the hostiles in the " ..
                "area.\n\nEver since we set foot in Zangarmarsh, the naga have launched lethal attacks " ..
                "against us without warning. We've done our best to keep them at bay, but our resources " ..
                "are limited.\n\nI want you to go to the various naga strongholds in Zangarmarsh and show " ..
                "them that we're not to be crossed. Bring me their claws as proof of your victories.",
            rewardItems = {{28100, 5}},
            rewardMoney = 31000,
        },
        [9729] = {
            description = "Little naga make Fhwoor angry! Sporelings good friend to Fhwoor, so Fhwoor get " ..
                "naga ark.\n\nWe go into nearby naga village. You help?",
            rewardChoices = {{25536, 1}, {25537, 1}, {25538, 1}},
        },
        [9730] = {
            description = "A bounty is hereby declared by the Cenarion Expedition on Rajah Haghazed, " ..
                "leader of the Darkcrest naga. Haghazed was last sighted by Cenarion scouts at the " ..
                "Lagoon, in the central southern region of Zangarmarsh.\n\nThe Darkcrest have been linked " ..
                "to numerous attacks against the Cenarion Expedition and their leader is considered " ..
                "extremely dangerous.\n\nThose seeking to claim the bounty are advised to report to " ..
                "Warden Hamoot.",
            rewardChoices = {{27725, 1}, {27726, 1}, {27727, 1}, {27728, 1}},
            rewardMoney = 62000,
        },
        [9731] = {
            description = "The schematics you've obtained show an underground system of drains and pumps " ..
                "that connect the lakes in the region to Serpent Lake.\n\nIf the schematics are correct, " ..
                "there is a giant drain in the center of Serpent Lake. Confirm this and bring the news to " ..
                "Cenarion Refuge.",
            rewardChoices = {{27730, 1}, {27734, 1}, {27735, 1}, {27733, 1}},
            rewardMoney = 29000,
        },
        [9732] = {
            description = "Return to Ysiel and let her know that help will be extended to her as soon as " ..
                "it is possible.\n\nAffairs in Moonglade and Silithus have kept our members occupied, but " ..
                "we will do our best to send the necessary resources to the Cenarion Refuge.",
            rewardChoices = {{25522, 1}, {25523, 1}, {25524, 1}},
        },
        [9733] = {
            description = "The Cenarion Expedition has become a large organization with a good degree of " ..
                "autonomy. These events are important enough that we need to warn the Cenarion " ..
                "Circle.\n\nDo not worry, I will not ask you to travel back to Moonglade; we have " ..
                "emissaries as nearby as Hellfire Peninsula.",
            rewardMoney = 16000,
        },
        [9734] = {
            description = "Return to Ysiel and let her know that help will be extended to her as soon as " ..
                "it is possible.\n\nAffairs in Moonglade and Silithus have kept our members occupied, but " ..
                "we will do our best to send the necessary resources to the Cenarion Refuge.",
            rewardChoices = {{25522, 1}, {25523, 1}, {25524, 1}},
        },
        [9739] = {
            description = "You there! You must help us!\n\nThe fungal giants are devouring all of our " ..
                "spore sacs! You must do something, or we'll lose our young!\n\nThe spore sacs start out " ..
                "large and become smaller as the air inside them is depleted. Look for the small, mature " ..
                "spore sacs and save as many of them as you can!",
        },
        [9740] = {
            description = "Thanks to you and the work you did, my scouts were able to find the sun gate. " ..
                "The elves keep the portal location mobile so that they can move it at a moment's notice. " ..
                "That's why the site you investigated was empty.\n\nThe strength of such a system is also " ..
                "its greatest weakness. The sun gate is stabilized by portal controllers. If we can take " ..
                "down the controllers, the portal will be ours to destroy. The current sun gate location " ..
                "can be found west of here, south of the Vector Coil. Find it and destroy it!",
        },
        [9741] = {
            description = "Aesom sent my squad out on a reconnaissance mission to search for the sun gate " ..
                "a few days ago. Needless to say, we found it...\n\n<Loryi points at Jorli.>\n\nWhatever " ..
                "those fool elves are transporting through that portal is causing void energy to be " ..
                "released. The area is teaming with void critters.\n\nWe must destroy them before they " ..
                "have a chance to grow into void anomalies. You'll find the source of the creatures " ..
                "southwest of here, near the sun gate. Kill them and report back to Aesom when you're " ..
                "done.",
        },
        [9743] = {
            description = "Us sporelings and the bog lords have never gotten along well. In the past, " ..
                "we've managed to keep them at bay with spears and stones. Lately they seem to have " ..
                "become more aggressive... or more desperate. They do not fear us or our weapons.\n\nYou " ..
                "are much scarier and better armed than us. If you were to fight the boglords for us, " ..
                "we'd be forever in your debt! Bring me their tendrils so I know how many you've killed.",
        },
        [9746] = {
            description = "Victory is close at hand, <name>. With the discovery of the sun gate, it won't " ..
                "be long until their supply lines are completely closed off. Now is the time to strike at " ..
                "their numbers.\n\nTo the west you will find numerous Sunhawk camps. The Sunhawk " ..
                "pyromancers and defenders occupy the vast majority of the area. Find them, kill them and " ..
                "return to me.",
        },
        [9747] = {
            description = "The naga are terrible, yes. But even more terrible are the traitor tribes of " ..
                "Broken and Lost Ones that helped them!\n\nThe worst of all are the Lost Ones of the " ..
                "Umbrafen tribe; they use dark magic to trap and enslave others. They're especially cruel " ..
                "to escaped slaves and would slit my throat if I left the refuge even for a " ..
                "day.\n\nTravel to Umbrafen Village south of here and kill them and their leader, Kataru. " ..
                "Until then I will fear for my life every single day.",
            rewardMoney = 27000,
        },
        [9748] = {
            description = "Our shaman claim that the elements of water have become greatly agitated by " ..
                "the pollution of the water source. We know that the Exodar's power core is lodged into " ..
                "the mountain to the west. It must be leaking volatile fluids into the water supply! I " ..
                "need you to get me more information.\n\n<Aesom points to a flask and nods.>\n\nYou are " ..
                "to take this flask and follow the beach north until you reach the area where the rivers " ..
                "of Bloodmyst drain into the ocean. Take a sample from that location and return to me.",
        },
        [9751] = {
            description = "Last night, Edward Hanes, captain of the ship 'Lost Hope', appeared before me " ..
                "in my tent. The same Edward Hanes that died of scurvy 20 years ago.\n\nThis apparition " ..
                "told me a tale that made my heart tremble. A tale that I need you to hear and a mission " ..
                "that I need you to accomplish. Will you do it? Will you seek out Edward on Wyrmscar " ..
                "Island, northeast of Blood Watch?",
        },
        [9752] = {
            description = "You must help me get out of here!\n\nI was gathering herbs nearby when a " ..
                "handful of these little savages abducted me. I tried to fight them off, but there were " ..
                "too many of them.\n\nHelp me return to the Cenarion Refuge and away from these cruel " ..
                "wretches and their vile magic!",
            rewardChoices = {{25518, 1}, {25519, 1}, {25517, 1}},
            rewardMoney = 29000,
        },
        [9753] = {
            description = "We've learned much of our enemies in recent days. The blood elves are led by a " ..
                "being known as Sironas and plot to destroy us. Ultimately, they seek to enslave O'ros " ..
                "and regain control of the Exodar.\n\nLight be praised, we have stopped their supply line " ..
                "by destroying the sun gate. Unfortunately, they continue to use the contaminant of the " ..
                "Vector Coil to poison the land, using the mutagenic properties of the fallout to their " ..
                "advantage.\n\nWith this knowledge, Admetius has devised a plan. Seek him out.",
        },
        [9756] = {
            description = "Our attempts at interrogation have failed miserably, <name>. Torture is - of " ..
                "course - out of the question. What we need is a <race> on the inside.\n\nI can cast a " ..
                "spell upon you that would make you appear blood elf and adjust your language. Through " ..
                "subterfuge, we may be able to get the information we need out of the captured " ..
                "agent.\n\nUnder this guise, I want you to get whatever information you can out of the " ..
                "prisoner.\n\nAnd <name>, do not leave Blood Watch while disguised as the spell will fail.",
        },
        [9758] = {
            description = "Now my friend, if you would be so kind as to return to Arcanist Vandril, I " ..
                "know that he is very anxious to send you out on your first mission here in the " ..
                "Ghostlands.\n\nWe're counting on you, <name>. Don't let us down.",
        },
        [9759] = {
            description = "Don't accept this assignment if you value your life. You see that gigantic " ..
                "power core jutting out of the mountain side over yonder? Whoever takes on this burden " ..
                "will need to fight their way through that mountain, battling an army of Sunhawks while " ..
                "protecting me as I rig the core up for demolition. Sironas the eredar is somewhere up " ..
                "there as well.\n\nI won't think less of you if you just walk away, <name>.\n\nBut maybe " ..
                "you're the one - the one to destroy the Vector Coil and take down Sironas. Well, are you?",
            rewardChoices = {{24351, 1}, {24352, 1}, {24353, 1}, {24354, 1}},
            rewardMoney = 3500,
        },
        [9760] = {
            description = "I would not ask you to single-handedly bear the burden of destroying the " ..
                "Vector Coil and slaying Sironas, <name>; however, I believe that you can be of some help " ..
                "in clearing the way for others that might take on such a dangerous assignment.\n\nTake " ..
                "the road going north out of Blood Watch and follow it until you get to the fork. Once " ..
                "there, take the left road and follow it until you see Vindicator's Rest - it will be " ..
                "slightly west of the road itself. Corin will be waiting for you.",
        },
        [9761] = {
            description = "Only the most battle hardened, noble and positively fearless will submit to " ..
                "Legoso's mission. The exarch will not order any agent of the Hand to take on the task of " ..
                "destroying the Vector Coil and dispatching Sironas. He refuses to send any draenei to " ..
                "their death - which is what the mission is: suicide...\n\n<Corin sighs.>\n\nMy job is to " ..
                "soften up the Sunhawk defenses. You are to slay Sunhawks near the Vector Coil and keep " ..
                "the path clear for our champion - whoever that may be.",
            rewardChoices = {{26009, 1}, {26023, 1}, {26035, 1}},
        },
        [9762] = {rewardChoices = {{24349, 1}, {24350, 1}}, rewardItems = {{24344, 1}}},
        [9769] = {
            description = "< Magasha chuckles softly to herself.>\n\nI bet if they knew they were wearing " ..
                "bug parts, the fashion trend would end very quickly.\n\nWe first started killing the " ..
                "bugs 'round here 'cause they were getting in the way of our construction. Some " ..
                "enterprising merchant stops here, spends the night, and next thing you know he's buyin' " ..
                "up all the bug wings we have!\n\nSays he makes clothes out of 'em. I be stickin' to my " ..
                "armor, thanks. But if you gather the wings of any of the fireflies, I'll gladly buy 'em.",
            rewardMoney = 27000,
        },
        [9770] = {
            description = "Sometimes I wish Denjai had sent a shaman with us, or at least given us a " ..
                "totem to keep the marshfang rippers at bay.\n\nThe whole place is crawling with the " ..
                "pests! It's just not right. Shouldn't something be eating these despicable " ..
                "things?\n\nWe've all been taking turns playing exterminator. You showed up at just the " ..
                "right time, <name>. Congratulations! Now get out there and mop up some marshfangs!",
            rewardMoney = 27000,
        },
        [9771] = {
            description = "Now that you're familiar with the terrain, I'd like to ask your help with " ..
                "something else. The Dead Mire, we've taken to calling the area to the northwest, is an " ..
                "eerie place. No one has ever reported seeing anything alive there, but they didn't stay " ..
                "for very long, either.\n\nScout Jyoba volunteered to investigate the area and report on " ..
                "his findings. He left the post three days ago and hasn't returned. It's not like him to " ..
                "be gone that long without sending some kind of report. Will you search for him, <name>?",
        },
        [9772] = {
            description = "Flecks of withered fungus dot the body of Scout Jyoba. Whatever killed him " ..
                "must've been made of the same dying fungus as the giant wilting mushrooms of the Dead " ..
                "Mire. Perhaps one of the withered giants caught him by surprise as he sat writing his " ..
                "report.\n\nWithout the text of the report, it's nearly impossible to tell what the scout " ..
                "discovered. If the report can be found, it should be returned to Zurai.",
            rewardChoices = {{25600, 1}, {25601, 1}, {25602, 1}, {31768, 1}},
            rewardMoney = 27000,
        },
        [9773] = {
            description = "Mushroom soup, mushroom stew, mushroom sauce!\n\nMushroom, mushroom, mushroom! " ..
                "It's all there is to eat around here. If you say you're hungry, the cook hands you an " ..
                "axe and tells you to go chop down your dinner!\n\nWell, I'm tired of mushrooms. I've " ..
                "seen fish in the lakes around here. Sure, they look like a nasty piece of work, but " ..
                "they've got to be better than mushrooms!\n\nHow much will it cost me to hire you to " ..
                "bring me my first decent meal in weeks?",
            rewardMoney = 20000,
        },
        [9774] = {
            description = "Reavij was wise to bring leather armor. This swamp will render my mail useless " ..
                "before long.\n\nI've been replacing the scales bit by bit as I'm able. The hydra in the " ..
                "marsh have thick, protective scales that stand up well to the dampness of their " ..
                "home.\n\nFinding suitable ones is a tedious process, though. All too often, the best " ..
                "scales are torn or worn too thin for use in armor. Bring me any good ones that you might " ..
                "get from the hydra in the larger lakes.",
            rewardMoney = 27000,
        },
        [9775] = {
            description = "Shadow Hunter Denjai will no doubt expect to receive a report about my " ..
                "progress in establishing our outpost. I've prepared a short summary of what we've " ..
                "accomplished here already, but with the loss of Scout Jyoba, I can't spare a runner to " ..
                "take the report to Denjai's base of Zabra'jin to the west.\n\nIf you're headed that way, " ..
                "would you mind bringing this to him? Shadow Hunter Denjai can be a little intimidating " ..
                "at first, but once you get used to him, he's not so bad.",
        },
        [9776] = {
            description = "As you know, many of Telredor's inhabitants are refugees from the war that " ..
                "decimated the draenei. It is my goal to maintain Telredor as a safe haven for all of our " ..
                "allies in this struggle. There are some who desire to join us, but feel they are not yet " ..
                "ready.\n\nWe owe them whatever help we can provide, <name>. A group of Broken under the " ..
                "leadership of Ikuti have taken shelter in the ruins of an old temple to the northwest of " ..
                "Serpent Lake. Seek them out and extend your hand in friendship to them.",
        },
        [9777] = {
            description = "There is little in this swamp that will burn, <race>, so we must resort to " ..
                "other means for lighting Telredor. Many of the creatures and plants in the marsh emit a " ..
                "soft glow.\n\nIt's difficult and cruel to confine the glowing creatures, so we've turned " ..
                "to a species of mushroom for our light source.\n\nWe pick and cultivate the fulgor " ..
                "mushroom here, but our needs require us to gather new crops occasionally. The small " ..
                "green mushrooms often grow at the base of larger ones near Telredor.",
            rewardMoney = 27000,
        },
        [9778] = {
            description = "Before you leave Cenarion Refuge, make sure you speak with Warden Hamoot. He's " ..
                "in charge of the expedition's security.\n\nHe would never forgive me if I didn't send a " ..
                "seasoned adventurer like you his way.",
        },
        [9779] = {
            description = "It is good to see you again, <name>. I have a quandary that you might be able " ..
                "to solve.\n\nOur agents situated behind Sunhawk lines have reported seeing Sunhawk " ..
                "soldiers parsing an unusual document.\n\nUnfortunately, we have been unsuccessful in " ..
                "acquiring a copy of the document for ourselves. I need you to go out in the field and " ..
                "try to recover the document. I am certain that if you apply enough pressure, a Sunhawk " ..
                "agent will turn over the information we seek. I leave the use of force to your " ..
                "discretion.",
        },
        [9780] = {
            description = "It's good to see another fresh face here. When Haalrun and I first came to " ..
                "Telredor, we were the only outsiders, but that seems like a lifetime ago.\n\nStill, we " ..
                "try to welcome newcomers and ensure that there's always enough food and supplies. We can " ..
                "never fully repay the kindness of the Telredor anchorites, but we can follow their " ..
                "example and extend it to others.\n\nIf you would like to help, the nearby lakes are " ..
                "populated with a fish called the Umbrafen eel, whose meat is a staple of our diet.",
            rewardMoney = 27000,
        },
        [9781] = {
            description = "On my last hunting trip, I caught sight of a new outpost being built by a " ..
                "group of trolls. No doubt they've begun hunting these lands, too.\n\nIf they establish a " ..
                "permanent presence out here, the competition for food will be fierce. We cannot take " ..
                "direct action against them without provocation, but we can remove some of the natural " ..
                "competition for food.\n\nFor each mire hydra you kill, that's three fewer mouths to feed!",
            rewardMoney = 27000,
        },
        [9782] = {
            description = "I have lived among the anchorites of Telredor for some time, <name>, and in " ..
                "that time I've come to know the marsh quite well. Recently, I've started to notice a " ..
                "disturbing change in the land to the northeast.\n\nVirtually all life there has begun to " ..
                "wither and die, seemingly without explanation. I have a few ideas as to what might be " ..
                "happening, but they are little more than speculation. If you were to bring me a sample " ..
                "of the soil in that area, I may be able to get to the bottom of this mystery.",
            rewardMoney = 27000,
        },
        [9783] = {
            description = "The soil sample you brought me is nearly devoid of moisture, <name>. If the " ..
                "soil itself is losing moisture, then the creatures that live in the Dead Mire must be " ..
                "suffering terribly.\n\nI've seen what happens when the region's fungal giants begin to " ..
                "wither and die. The pain drives them mad, causing them to attack anything in their " ..
                "path.\n\nThese creatures have no idea what's happening to them. They're beyond our " ..
                "ability to save, so the best we can do is to end their suffering.",
            rewardChoices = {{25597, 1}, {25598, 1}, {25599, 1}, {31659, 1}},
            rewardMoney = 27000,
        },
        [9784] = {rewardItems = {{24402, 1}}},
        [9785] = {
            description = "You've earned the trust of the Cenarion Expedition, <name>. It is time you " ..
                "spoke to the ancients allied with our cause, Ashyen and Keleth, and asked for their " ..
                "blessing.\n\nCarrying the mark of an ancient will fill you with great power. These boons " ..
                "will become more powerful as your renown among us increases.\n\nGo, <name>, and ask the " ..
                "ancients for their blessing.",
        },
        [9786] = {
            description = "Before my people were decimated by the orcs, Telredor served as a retreat for " ..
                "draenei anchorites and spiritualists. A small order of anchorites and vindicators " ..
                "maintained a number of shrines in this region.\n\nDuring the war, we lost contact with " ..
                "the anchorites assigned to the shrines, particularly the Boha'mu temple to the " ..
                "southwest. I've heard reports that a tribe of Lost Ones has settled in the area and may " ..
                "even be using the ruins. Visit the Boha'mu Ruins and tell me of what you find there.",
            rewardMoney = 27000,
        },
        [9787] = {
            description = "From what you've told me about your observations at the Boha'mu Ruins, it " ..
                "seems this tribe of Lost Ones has reverted to the worship of animal spirits. Before we " ..
                "can approach them, we must know more of their beliefs.\n\nReturn to Feralfen Village and " ..
                "discreetly gather some of their idols so that I may study them. Try to avoid angering " ..
                "them, <name>, as it may hurt our chances of making contact with them.",
            rewardMoney = 27000,
        },
        [9788] = {
            description = "Soon after I escaped the Umbrafen tribe, I holed up in a cave south of their " ..
                "village. Little did I know that the cave was being fought over by marsh beasts and spore " ..
                "men!\n\nI had to leave in a hurry and left behind a box containing my only worldly " ..
                "possessions.\n\nAfter managing to sneak out of Umbrafen with my belongings it was " ..
                "terrible irony that I would lose them so soon after. If you're willing to bring them " ..
                "back to me I'll give you one of my very own personal items. What do you say, <name>?",
            rewardChoices = {{25514, 1}, {25515, 1}, {25516, 1}, {27716, 1}},
            rewardMoney = 27000,
        },
        [9789] = {
            description = "You want to earn a place in this safari? You'll have to prove yourself.\n\nI " ..
                "don't care what you've hunted before, you haven't hunted until you hunt what we hunt " ..
                "here. Start with the clefthoof if you're <man/tough> enough.\n\nI know that I've seen " ..
                "them in the immediate area around the safari and also close by to the south.",
            rewardMoney = 35000,
        },
        [9790] = {
            description = "Living in such a remote location has taught us to make use of everything " ..
                "available. Of course, you have to learn to stop thinking about where some of these " ..
                "materials come from first.\n\nI've found that the wings of the umbraglow stingers are " ..
                "very helpful for waterproofing. They're strong, thin, and flexible.\n\n< Haalrun " ..
                "chuckles.>\n\nI see the look on your face. Like I said, it takes time to get used to the " ..
                "idea. If you're going to be out and about, would you mind bringing me some of the wings?",
            rewardMoney = 27000,
        },
        [9791] = {
            description = "During the orcs' war against my people, gatherers rarely left Telredor for " ..
                "fear of being attacked or captured. Now, we venture out more often, but the marsh is no " ..
                "less perilous.\n\nIt seems that the nether rays have grown bolder in recent months. I " ..
                "don't know if it has something to do with more competition for their normal prey, but " ..
                "they've been attacking our foraging parties on a regular basis. If we can thin their " ..
                "ranks in the area around Telredor, perhaps they would learn to leave us alone.",
            rewardMoney = 27000,
        },
        [9792] = {
            description = "You've been honorable in our dealings, <name>, at a time when trust is hard to " ..
                "win among my people.\n\nA large group of my brethren have made their home in the old " ..
                "draenei city of Telaar in Nagrand, to the south. To reach Telaar, take the road south " ..
                "into Nagrand, then continue southeast until you find yourself in the cliffs east of " ..
                "Oshu'gun.\n\nAnyone who has aided us, as you have, would be welcome among the people of " ..
                "Telaar.\n\nSeek out Warden Moi'bff Jill and tell him you have earned my trust.",
        },
        [9793] = {
            description = "Prophet Velen's search for allies has emboldened those draenei remaining in " ..
                "Outland to begin a search of their own. The Legion's war on my people drove us from our " ..
                "cities and temples, but they have not destroyed the traces of our " ..
                "civilization.\n\nTuurem, my former home in the Terokkar Forest, was one of the first " ..
                "cities overrun by the orcs. It's been too long since I've received news of its status. " ..
                "Take this letter to Andarl in the Allerian Stronghold within Terokkar and see what you " ..
                "can find out.",
        },
        [9794] = {
            description = "<name>, I have a favor to ask of you. Normally, I would do this myself, but my " ..
                "hands are already beyond full.\n\nI have an associate named Kialon at Sylvanaar in the " ..
                "Blade's Edge Mountains to the north. He's expecting to hear from me in the near future, " ..
                "although I suspect he won't like what I have to say.\n\nIf you would deliver my response " ..
                "to him, you would have my gratitude. I must insist, and this is very important, that you " ..
                "not attempt to read the letter. It is for Kialon's eyes alone.",
        },
        [9795] = {
            description = "As if the naga and their allies weren't enough, the ogres are extending their " ..
                "reach in the marsh. They've already conquered most of the area to the northwest and " ..
                "there isn't much of a buffer left.\n\nFor each one we kill, several more take their " ..
                "place. I'm not sure how long we'll be able to hold Zabra'jin once they decide to attack. " ..
                "Make your way north into the mountains, to the orcish stronghold of Thunderlord " ..
                "Stronghold and let Nekthar know of our plight. Any help he can spare would be most " ..
                "welcome.",
        },
        [9796] = {
            description = "Shadow Hunter Denjai isn't the only one expecting a report from me. Mokasa at " ..
                "Stonebreaker Hold in Terokkar is eager to hear of our progress, especially since most of " ..
                "her messengers travel through here.\n\nShe asked me to send word once Swamprat Post was " ..
                "completed. If you wouldn't mind delivering the news, I'd be very grateful. We may be up " ..
                "and running, but there is still much to be done.\n\nTo get to Stonebreaker Hold, follow " ..
                "the road south out of Zangarmarsh, into Terokkar Forest and beyond Tuurem.",
        },
        [9797] = {
            description = "<Still catching his breath, the messenger gestures for you to sit.>\n\nThey " ..
                "may not survive, <race>! Get to Garadar as quickly as your legs will carry you.\n\n<In " ..
                "response to your blank stare, the messenger elaborates.>\n\nThe home of the Mag'har, " ..
                "lies to the south, in Nagrand. Take the southern road out of the marsh, then turn east " ..
                "at the first fork and look for a large settlement on the lake.\n\nFind our commander, " ..
                "Captain Kroghan, there and offer him what assistance you can. Garadar must not fall!",
        },
        [9798] = {
            description = "These plans seem important. You should take them to Vindicator Aldar at the " ..
                "crash site.",
            rewardMoney = 100,
        },
        [9799] = {
            description = "The Ammen Fields to the west are the primary breeding ground of the local " ..
                "lasher population. With the corruption of the water table from the nearby lake, Botanist " ..
                "Taerix is worried that the lashers will not be able to repopulate themselves once we've " ..
                "cleansed the lake.\n\nGo to the Ammen Fields and pick some of the corrupted flowers for " ..
                "me so that I might take a look at them and see what can be done. You should be able to " ..
                "identify them by their uncharacteristic red petals.",
            rewardMoney = 50,
        },
        [9800] = {
            description = "You are ill-equipped to face the restless elements of Nagrand. Before you can " ..
                "help the Earthen Ring, you must help yourself.\n\nTo the west you will find dung heaps " ..
                "left behind by the wildlife of Nagrand. You must search the dung for the digested " ..
                "remnants of the Nagrand caracoli. From this bean I am able to make a tablet that will " ..
                "aid you in your battle against the restless forces of nature.\n\nReturn to me when you " ..
                "have collected no less than two fists worth of caracoli... Ogre sized fists.",
            rewardItems = {{24421, 5}},
        },
        [9801] = {
            description = "I have a feeling that these Lost Ones may not respond well to a draenei, but " ..
                "would welcome an arakkoa. I can create a potion that will allow you to take on the form " ..
                "of an arakkoa for a short time. It requires a couple of reagents which cannot be stored " ..
                "and must be used within hours of being gathered.\n\nYou will need to bring me a handful " ..
                "of sporebat eyes and some fen strider tentacles. Both species dwell in the wilderness " ..
                "surrounding Telredor.",
            rewardMoney = 27000,
        },
        [9802] = {
            description = "The lakes of Zangarmarsh are slowly being drained of their water. We don't " ..
                "quite know why, but we do know that many plants species are in danger of becoming " ..
                "extinct.\n\nAs the expedition's cataloguer, it is my job to track and identify these " ..
                "plants so we can better understand what's happening to them.\n\nIf you'd like to help, " ..
                "bring me unidentified plant parts. They can be picked right from the ground if you're an " ..
                "herbalist, and the indigenous creatures of the swamp may also carry plant parts on them.",
            rewardItems = {{24402, 1}},
        },
        [9803] = {
            description = "The time has come for us to embrace the Feralfen and teach them that the Light " ..
                "has not forsaken them. Take the potion I've prepared and carry it with you to the " ..
                "Boha'mu Ruins.\n\nOnce you arrive at the ruins, drink the potion to assume the form of " ..
                "one of their bird spirits. Speak with Elder Kuruti and let him know the draenei are " ..
                "ready to welcome his people as our long lost brothers.",
            rewardChoices = {{25613, 1}, {25614, 1}, {25615, 1}, {31660, 1}},
            rewardMoney = 27000,
        },
        [9804] = {
            description = "The disturbance in the ebb and flow of the waters of Nagrand has greatly " ..
                "agitated the water spirits of Skysong Lake. They have in turn begun sowing destruction " ..
                "throughout the waterways of the area.\n\nWatoosun of the Water has come to us in a " ..
                "vision and granted us permission to remedy the problem - so long as the source of the " ..
                "disturbance is also dealt with...\n\nWe will get to the source, but first you must deal " ..
                "with the problems immediate to the Throne. Destroy the agitated lake spirits and return " ..
                "to me.",
        },
        [9805] = {
            description = "The wretched Lost Ones, heretofore banished to the swamps of Zangarmarsh, are " ..
                "seeking to spread their filth to other parts of our world.\n\nI have sought the wisdom " ..
                "of the furies and gained their blessing. To stop the source, we must unleash the " ..
                "elements upon them!\n\nI give you living fire, plucked from the fiery essence of " ..
                "Incineratus himself. Travel to Windyreed Village, southeast of here, and unleash the " ..
                "living fire upon their huts! Let them see the fury of the elements!",
        },
        [9806] = {
            description = "Spore bats and marsh walkers accumulate fertile spores on their appendages " ..
                "from wandering around the tallstalk mushrooms in the marsh.\n\nAs you can see, we're a " ..
                "short people so our options for gathering these spores are limited. Seek out the spore " ..
                "bats and marsh walkers and gather the fertile spores. All of Sporeggar will be in your " ..
                "debt.",
            rewardItems = {{24245, 1}},
        },
        [9807] = {rewardItems = {{24245, 1}}},
        [9808] = {
            description = "I've seen your kind use shiny round pieces of metal to trade for things that " ..
                "you need. We're not so different from you. We use shiny round mushrooms as our " ..
                "currency.\n\nGlowcap mushrooms grow everywhere in the marsh, you just have to know how " ..
                "to pick them from the ground without wrecking them. I'll teach you how to do it, if you " ..
                "promise to bring us some for our reserves. What do you say, <name>?",
        },
        [9810] = {
            description = "Watoosun was able to shed the stink of corruption; but in doing so, created a " ..
                "twisted spirit essence. A spirit essence composed of the vilest corruption found amongst " ..
                "the elements!\n\nYou will find this polluted spirit of the swamp southwest of here, " ..
                "hidden in the depths of Lake Sunspring.\n\nFind and destroy the polluted essence of " ..
                "Watoosun and any corrupt offspring that it may have created.",
            rewardChoices = {{25556, 1}, {25557, 1}, {25558, 1}},
            rewardMoney = 70000,
        },
        [9811] = {
            description = "This is the beginning of a new chapter in blood elf history, <name>. You've " ..
                "helped cement the bond between my race and yours, <race>.\n\nTake the traitor's head to " ..
                "Regent Lord Lor'themar Theron in Silvermoon City. He'll be eager to hear the news.",
        },
        [9812] = {
            description = "There were doubts about our capabilities among our potential new allies. Of " ..
                "what use could we be to them when perceived as unable to deal with our problems at " ..
                "home?\n\nThis changes everything. No longer will our power be questioned. We'll be able " ..
                "to join the Horde as equals.\n\nTake this letter to Sylvanas, ruler of the Forsaken. " ..
                "She's already on our side but the news of Dar'Khan's death will be music to her ears. " ..
                "Prepare for a long trip, <name>. If all goes well she will send you to Orgrimmar.",
        },
        [9813] = {
            description = "I haven't lost any love for my homeland or its people, as you know. I've " ..
                "fought tooth and nail for Silvermoon to be allowed a place beside Undercity and " ..
                "Orgrimmar at the negotiating table.\n\nThis should silence any opposition. Take this " ..
                "letter to the Warchief in Orgrimmar. As leader of the Horde he will have the final say " ..
                "on accepting the sin'dorei's pledge.\n\nI've added my own seal to the letter as a " ..
                "personal endorsement. Go northwest of the city and board the zeppelin bound for Durotar " ..
                "at the tower.",
        },
        [9814] = {
            description = "You like mushrooms, mon? There be a powerful one here in Zangarmarsh, growin' " ..
                "real close to Zabra'jin.\n\nYou gotta be careful, though, mon. They be callin' it the " ..
                "burstcap for a reason. If you be gettin' too close without takin' the proper " ..
                "precautions, it'll blow right up on you! Poof! Right into a cloud o' toxic spores.\n\nI " ..
                "been usin' them for readin' the omens, but they be almost gone now.",
            rewardMoney = 31000,
        },
        [9815] = {
            description = "The most affected elements of water can be found in the Halaani Basin, " ..
                "southwest of here, beneath the abandoned city of Halaa. While some distressed elements " ..
                "can be destroyed without any impact upon the environment, spawns of muck must be " ..
                "physically removed from the world once destroyed.\n\nYou see, muck spawns leave behind " ..
                "globules of tainted debris that if left untouched will spread and further contaminate " ..
                "the environment.\n\nDestroy these muck spawns and bring back their muck-ridden cores.",
            rewardChoices = {{25559, 1}, {25560, 1}, {25561, 1}},
        },
        [9816] = {
            description = "This marsh be missin' one thing, mon! There be no murlocs here.\n\nDon't " ..
                "worry, mon, I got a plan to fix the problem. See Gargle 'n' Gurgle over there? I plan to " ..
                "give the gift o' murlocs to the Lost Ones!\n\nTake this cage with you to Daggerfen " ..
                "Village an' release 'em in the northeastern cluster of huts. Now you know I can't be " ..
                "riskin' Gargle 'n' Gurgle with you, but I'll give you a cage full o' colorful young " ..
                "murlocs. Just set it on the flat rock you be findin' up there and open the door!",
            rewardChoices = {{25610, 1}, {25611, 1}, {25612, 1}},
            rewardMoney = 31000,
        },
        [9817] = {
            description = "A bounty is hereby declared by the Cenarion Expedition on Rajis Fyashe, leader " ..
                "of the Bloodscale naga. The naga sorceress was last sighted at Serpent Lake, in the " ..
                "northern region of Zangarmarsh.\n\nThe Bloodscale are to be considered extremely " ..
                "dangerous and their leader is to be approached with extreme caution.\n\nThose seeking to " ..
                "claim the bounty are advised to report to Warden Hamoot at Cenarion Refuge.",
            rewardChoices = {{27721, 1}, {27722, 1}, {27723, 1}, {27724, 1}},
            rewardMoney = 58000,
        },
        [9818] = {
            description = "Something rails the underneath. It beats the ground as if to " ..
                "punish.\n\n*Thud*\n\n<Untrag beats his chest with his fist.>\n\nIt makes this sound a " ..
                "hundred-thousand times. Endlessly it beats. The earth reels. It is calling out to us " ..
                "now.\n\nGordawg speaks to me. Gordawg knows that something forces the elements out. " ..
                "Something from the underneath.\n\nGo now and speak to Gordawg. No, listen to Gordawg, do " ..
                "not speak. Hear Gordawg...",
        },
        [9819] = {
            description = "Bring up the usurper. You will find him. Follow earthen path. First you put to " ..
                "rest tortured earth spirits. Must sleep once more.\n\n< Gordawg smashes his fist into " ..
                "the ground and brings up very foul smelling soil.>\n\nMust sleep!\n\n< Gordawg points " ..
                "southeast.>\n\nFind spirits near mountains. Near hills. Near rocks. Near earth.\n\nPut " ..
                "to sleep.\n\nTelaari Basin... Southeast.",
        },
        [9820] = {
            description = "Wanted - Dead or Alive: Boss Grog'ak, overseer of the Ango'rosh " ..
                "mushroom-cutting operation.\n\nThis brute and his axe-wielding cronies are responsible " ..
                "for chopping down the mushrooms to the north of town. Unless he is stopped, he and his " ..
                "band will cut a path to the walls of Zabra'jin.\n\n<He/She> who presents the head of " ..
                "Boss Grog'ak to Shadow Hunter Denjai shall be well-rewarded.",
            rewardMoney = 31000,
        },
        [9821] = {
            description = "< Gordawg picks up a rock and begins to chew on it.>\n\nGordawg tastes. " ..
                "Gordawg knows where this earth has been.\n\n< Gordawg raises one of his massive legs and " ..
                "stomps the ground.>\n\nLook. See Nagrand.\n\n< Gordawg directs you to the imprint of his " ..
                "foot. Within the imprint you see what appears to be a perfect geological map of Nagrand, " ..
                "marked with the locations of where you can find the elementals Gordawg wants you to " ..
                "destroy.>\n\nBREAK THEM! Bring Gordawg the pieces to eat.\n\nTake the map.",
        },
        [9822] = {
            description = "The position of the ogres' mushroom-cutting operation can't be an accident. I " ..
                "can't escape the suspicion that they're preparing for an attack on Zabra'jin.\n\nI must " ..
                "know for certain, <name>. The ogres have another outpost to the northwest, the Ango'rosh " ..
                "Grounds. If they're staging for an attack, there will be evidence of their plans there. " ..
                "Go there, <name> and search the camp for signs of their intentions. Return to me with " ..
                "anything that might be suspicious.",
            rewardMoney = 31000,
        },
        [9823] = {
            description = "In order to end the Ango'rosh threat, we must kill their leader, Overlord " ..
                "Gorefist. We'll do better than that, though. We'll make an example of the overlord and " ..
                "his followers.\n\nGo to the Ango'rosh Stronghold and deal with our foes. The stronghold " ..
                "is located in a cave on a small island to the northwest of Zabra'jin. You'll see a " ..
                "bridge made from a fallen mushroom beyond the Ango'rosh Camp.\n\nShow no mercy, <name>. " ..
                "They certainly wouldn't spare any of us.",
            rewardItems = {{25617, 1}, {27553, 5}},
            rewardMoney = 62000,
        },
        [9824] = {
            description = "I'm trying to obtain an imprint of Karazhan 's energy... for a personal " ..
                "project, of course. Unfortunately, I'm not getting anything up here. If I could get near " ..
                "an underground water source, my crystal would pick up the signals much more " ..
                "clearly.\n\nI've heard of an underground pond as well as a well in a cellar below us. " ..
                "This whole place is crawling with ghosts however, and venturing there would be hazardous " ..
                "for someone my age. What do you say; will you help an old man and perform the scrying " ..
                "for me?",
            rewardMoney = 44000,
        },
        [9825] = {
            description = "As you may have noticed, the outside of Karazhan is crawling with ghostly " ..
                "beings. The reason for their existence is unknown and unknowns bother me!\n\nBring me " ..
                "their ghostly essence so that I may study their nature. Karazhan has many secrets, " ..
                "<name>. I'm determined to uncover all of them.",
            rewardMoney = 44000,
        },
        [9826] = {
            description = "These signs do not bode well for us, <name>. I've never been one for secrecy " ..
                "so I will tell you a bit about my organization, the Violet Eye.\n\nWe are agents of the " ..
                "Kirin Tor, the Magus Senate of Dalaran. We were assigned to keep an eye on Karazhan and " ..
                "Medivh, in case things got out of hand.\n\nWhich they did... very quickly, after Medivh " ..
                "disappeared.\n\nThis report details my findings. Take it to Archmage Cedric, also from " ..
                "the Violet Eye; you will find him in the outskirts of Dalaran Crater.",
        },
        [9827] = {
            description = "A close inspection of the basidium reveals a number of indentations that might " ..
                "have once held something. The alien mass of fungus presents something of a puzzle. It's " ..
                "far from healthy, but you have little clue as to what function it might normally " ..
                "perform.\n\nPerhaps someone more familiar with the denizens of Zangarmarsh would be able " ..
                "to tell you more about the basidium.",
            rewardMoney = 27000,
        },
        [9828] = {
            description = "A close inspection of the basidium reveals a number of indentations that might " ..
                "have once held something. The alien mass of fungus presents something of a puzzle. It's " ..
                "far from healthy, but you have little clue as to what function it might normally " ..
                "perform.\n\nPerhaps someone more familiar with the denizens of Zangarmarsh would be able " ..
                "to tell you more about the basidium.",
            rewardMoney = 27000,
        },
        [9829] = {
            description = "Alturus's report is unsettling. We thought it was bad when Karazhan sealed " ..
                "itself off to the outside world. We had agents inside; we never heard from any of them " ..
                "again. Now this... demonic emanation. We must investigate it.\n\nThe only people who can " ..
                "reopen Karazhan were presumed dead: Khadgar and Medivh.\n\nWhile we hope that the latter " ..
                "is indeed gone, we recently learned that his apprentice, Khadgar, is alive and well in a " ..
                "place called Shattrath City. Find him and give him Alturus's report.",
        },
        [9830] = {
            description = "When I speak to draenei, I often get the sense that they consider themselves " ..
                "removed from their environment. Many seem to pity my brethren, the Broken, who they say " ..
                "have lost something.\n\nWe Broken may have lost our inclination toward the Light, but " ..
                "our experiences have brought us closer to the land.\n\nMy people see opportunities where " ..
                "few draenei do. Take, for example, the venom of the marshlight bleeders that live to the " ..
                "south and west. It has a wide variety of uses from hunting to healing.",
            rewardMoney = 31000,
        },
        [9831] = {
            description = "I am deeply troubled by the news in this report, <name>. Gaining entry into " ..
                "Karazhan will be difficult, however.\n\nYou see, when it became apparent that I was " ..
                "stranded here I split the key into three fragments.\n\nI placed the keys inside " ..
                "enchanted containers, and in turn placed those in places that were safe at the " ..
                "time.\n\nWith the dark changes Outland has endured this no longer is the case. The first " ..
                "fragment is in a section of Auchindoun taken over by the Shadow Council. Return this " ..
                "fragment to me.",
        },
        [9832] = {
            description = "I hid the second fragment at the bottom of Serpent Lake, long before it was " ..
                "called that. The giant drain installed there after the naga took over has likely pulled " ..
                "the container into the depths of Coilfang Reservoir.\n\nThe third fragment will prove " ..
                "the most trying, as I left it inside Tempest Keep back when it was controlled by the " ..
                "naaru. Kael'thas now rules it and the chamber where I left it has become a " ..
                "prison.\n\nBring me these remaining fragments, <name>. Much depends on your success.",
        },
        [9833] = {
            description = "One of the reasons Ikuti led us to Zangarmarsh was to help open the lines of " ..
                "communication between the draenei and the Kurenai home city of Telaar in Nagrand. In " ..
                "order for messengers to pass swiftly between Telaar and Telredor, the roads must be " ..
                "secured.\n\nOn our way here, we were attacked repeatedly by marshfang slicers. We were " ..
                "able to fight them off, but they would pose a formidable threat to a solitary messenger. " ..
                "Reducing their numbers will help ensure the safety of our messengers.",
            rewardChoices = {{27753, 1}, {27754, 1}, {27756, 1}},
            rewardMoney = 31000,
        },
        [9834] = {
            description = "Maktu can always see a draenei approaching in his shiny armor from a mile " ..
                "away, even in this murky swamp!\n\nMaktu wants to laugh at them, but then he remembers " ..
                "that they have been kind to the Kurenai and he wants to teach them about how Kurenai " ..
                "make armor.\n\nThe dark, scaly hides of the fenclaw thrashers make some of the best " ..
                "armor Maktu has ever worn. If <name> can bring Maktu some of these hides from the " ..
                "fenclaw thrashers deep in Serpent Lake, he'll be happy to share some of his armor.",
            rewardMoney = 31000,
        },
        [9835] = {
            description = "The small band of Broken you see here is a mission from a larger settlement in " ..
                "Nagrand. The Kurenai, as we call ourselves, are Broken who desire to reunite with our " ..
                "draenei brothers.\n\nMy group has come here to strengthen Kurenai ties to the draenei of " ..
                "Telredor.\n\nIf the Ango'rosh ogres have their way, this temple will not stand much " ..
                "longer. They have cleared the Hewn Bog of its towering mushrooms and draw ever closer to " ..
                "our refuge. If you would call yourself our friend, aid us in fighting this enemy.",
            rewardMoney = 31000,
        },
        [9836] = {
            description = "I've put together the very key I used as an apprentice. It looks completely " ..
                "functional as far as keys go. In regards to opening Karazhan, however, this might as " ..
                "well be a piece of scrap metal.\n\nWithout Medivh 's consent, the key is worthless. Yes, " ..
                "of course I know Medivh is dead. This merely makes things difficult, not " ..
                "impossible.\n\nThere is a place in Azeroth called the Caverns of Time, guarded by the " ..
                "bronze dragonflight. Find a way inside, travel back in time and get Medivh to enable the " ..
                "key.",
        },
        [9837] = {
            description = "I seem to have memories about future events surrounding you and this key.\n\n< " ..
                "Medivh looks at you like he's just seen a ghost.>\n\nYou have trying times ahead of you, " ..
                "<name>. Let us hope your strength does not fail you.\n\nRegarding the key, I am to hand " ..
                "it to Khadgar when he's sent to me. I couldn't hope for a better apprentice.\n\nI " ..
                "suppose you will need a key of your own.\n\n< Medivh reaches into his robe and hands you " ..
                "his own key.>\n\nGo on then. And best of luck, <class>.",
            rewardItems = {{24490, 1}},
        },
        [9838] = {
            description = "A great responsibility has been bestowed upon you, <name>. If the signs that " ..
                "the Violet Eye has observed are to be trusted, then you must help them.\n\nFor all my " ..
                "disagreements with Cedric, the work that men like Alturus do is still important. Beware " ..
                "that they do not use you, however. Remember it is you who the key is bound to, not them. " ..
                "But if the danger in Karazhan is real, then it is they who are best prepared to guide " ..
                "you in dealing with it. Go back to Alturus and help him in any way that you can.",
        },
        [9839] = {
            description = "The centerpiece of any ogre tribe is its leader. Without leadership, the " ..
                "Ango'rosh's organization will disappear and they'll resort to infighting to determine " ..
                "who will lead next.\n\nAlthough we've seen the ogres out and about in this area, their " ..
                "true strength is concentrated in their Ango'rosh Stronghold to the northwest. It's " ..
                "located in a cave on a small island connected to the marsh by a fallen mushroom.\n\nGo " ..
                "there and defeat Overlord Gorefist. That should provide us with a well-deserved respite.",
            rewardChoices = {{25618, 1}, {31770, 1}, {25619, 1}},
            rewardMoney = 31000,
        },
        [9840] = {
            description = "Now that we've found a way back into Medivh's Tower - or rather you have - the " ..
                "first thing we need to do is try to get a sense of what the situation inside is.\n\nOne " ..
                "of our agents who had managed to infiltrate Karazhan kept an encoded log of her " ..
                "observations. Unfortunately her death was confirmed shortly before Karazhan was shut " ..
                "down. Koren, Karazhan 's blacksmith, was under our pay. Though not a member of the " ..
                "Violet Eye, he should be able to help us find Keanna's log. Look for him inside.",
        },
        [9841] = {
            description = "It's impossible to work with all this infernal buzzing! Do you hear it?\n\nI " ..
                "can't get it out of my head! I know exactly what's making the noise, too. It's those " ..
                "damnable marshlight bleeders! The noise always comes from the south and west of the " ..
                "village.\n\nThey're too big to swat, crush underfoot, or wave away. The only way to stop " ..
                "that unholy droning is to kill them. I don't care how you do it, <name>, just quiet them!",
            rewardMoney = 31000,
        },
        [9842] = {
            description = "The damp atmosphere of the marsh has taken a toll on my metal tools. It's made " ..
                "woodworking a lot more difficult than it ought to be, so I've given up on metal " ..
                "blades.\n\nIt turns out that the marshfang slicers living to the south and west of town " ..
                "grow blades that are sharper than any steel I've ever owned. They're also resistant to " ..
                "rust and wear. It's just a little tricky to attach them to a handle, but I think I've " ..
                "got it figured out. I'd appreciate any blades you could bring me.",
            rewardChoices = {{27753, 1}, {27754, 1}, {27756, 1}},
            rewardMoney = 31000,
        },
        [9844] = {
            description = "Keanna's last few entries confirm our suspicions of a demonic presence inside " ..
                "Karazhan.\n\nShe detected the arrival of a Burning Legion agent whose location she " ..
                "describes as coming from the top of the tower.\n\nHer entries stop there.\n\nKarazhan is " ..
                "a very important place, <class>. It is a portal into the nether, a beacon shining into " ..
                "other worlds. The possible repercussions of it falling into the wrong hands are " ..
                "unthinkable. This demonic intrusion must be stopped. And you, <name>, are the only one " ..
                "with a key.",
            rewardMoney = 44000,
        },
        [9845] = {
            description = "It's a relief to be in someplace with water after trekking through the " ..
                "wasteland of Hellfire Peninsula. I was worried there might not be any respectable " ..
                "fishing holes in Outland.\n\nNow I'm glad I lugged my fishing supplies along. For the " ..
                "most part, the fishing's been good, except for those no good fenclaw thrashers in " ..
                "Serpent Lake.\n\nNot only do they scare the fish away, but they're bold enough to snap " ..
                "the bait right off my hook. I spend more time re-baiting the hook than I do catching " ..
                "anything!",
            rewardMoney = 31000,
        },
        [9846] = {
            description = "The most powerful tribe of Lost Ones in the marsh, the Feralfen, are said to " ..
                "possess powerful medicine. There may be no truth to such rumors, but anything that might " ..
                "help me channel the spirits of this world cannot be ignored.\n\nFind the Feralfen " ..
                "mystics, hunters and druids, <name>, and capture their totems. Everything I need to know " ..
                "should be apparent from the carvings.",
            rewardMoney = 27000,
        },
        [9847] = {
            description = "We must find out how much power this Feralfen snake spirit possesses and " ..
                "whether it can be bent to our will. Imagine what I could do with the powers of an " ..
                "Outland spirit at my command!\n\nTake this totem with you and make your way to the foot " ..
                "of the stairs leading to the Boha'mu Ruins. Plant the totem in the ground and it should " ..
                "do the rest. The spirit should not be able to tell who has used the totem until it has " ..
                "manifested.",
            rewardChoices = {{25621, 1}, {31770, 1}, {25620, 1}},
            rewardMoney = 31000,
        },
        [9848] = {
            description = "Bugs, bugs, bugs! The marsh is full of them and my companions here seem " ..
                "obsessed with them.\n\nWell, I've had it with the bugs! Something far more intriguing " ..
                "has captured my interest. To the west, there is a village of Lost Ones who call " ..
                "themselves the Daggerfen.\n\nThe whole tribe consists of highly specialized assassins. " ..
                "I've noticed them mixing and using a particularly potent kind of poison. I'm dying to " ..
                "know more about the poison, but that's going to require a copy of the recipe and a " ..
                "sample vial.",
            rewardItems = {{25616, 1}, {27553, 5}},
            rewardMoney = 31000,
        },
        [9849] = {
            description = "< Gordawg breaks off a piece of ebon rock from his back.>\n\nYou are granted a " ..
                "piece of the fury of the earth. Take the boulder of Gordawg and hurl it at the poison " ..
                "rock. Shatter their shells to discover the truth. Destroy the minions of the usurper and " ..
                "return to Gordawg with the name.\n\nYou find the shattered elements at the edge of the " ..
                "world. Southwest.",
        },
        [9850] = {
            description = "You've proved to me that you can find and take down a regular clefthoof, but " ..
                "far more dangerous are the clefthoof bulls.\n\nBag yourself twelve of those. Then you " ..
                "can talk to me of your hunting prowess.\n\nLook for them all along the middle region of " ..
                "Nagrand to the west and south.",
            rewardMoney = 37000,
        },
        [9851] = {
            description = "Banthar is the fiercest and most elusive of all the clefthoof in Outland. " ..
                "She's also the hairiest.\n\nIt is said that she roams with her clefthoof herd in the " ..
                "Spirit Fields near Oshu'gun.\n\nYou want to truly prove your hunting mastery? Bring me " ..
                "her horn!",
            rewardChoices = {{25589, 1}, {25591, 1}, {25592, 1}},
            rewardMoney = 74000,
        },
        [9852] = {
            description = "The queen of all that dwell in Nagrand is known as Tusker. She's a giant elekk " ..
                "the likes of which you won't see anywhere else!\n\nYou're right to be fearful of that " ..
                "name. Bach'lor, Gutripper, and Banthar are nothing when compared to her. It is said that " ..
                "she can be found on a huge bluff far to the southwest overlooking Oshu'gun. Bring me her " ..
                "massive heart if you dare.\n\nDo you want to leave a letter with me so that I can have " ..
                "it delivered to your next of kin in the likely event that you don't return?",
            rewardChoices = {{25639, 1}, {25640, 1}},
            rewardMoney = 117000,
        },
        [9853] = {
            description = "Gurok must be summoned. You summon Gurok and you destroy.\n\nYou must go to " ..
                "Warmaul Hill to the northwest and find where ogre worships Gurok. You put ogre skull " ..
                "from Warmaul ogres on Gurok's earthen brand. Only then will Gurok come. Seven " ..
                "skulls.\n\nIf you live, bring Gordawg back Gurok earthen head. Gordawg crushes " ..
                "head.\n\n< Gordawg bites down hard, shaking the earth beneath your feet.>",
            rewardChoices = {{25563, 1}, {25564, 1}, {25562, 1}},
        },
        [9854] = {
            description = "Do you live for the hunt as I do, <class>? Do you seek the quietude that comes " ..
                "as you stalk your prey? Would you know what it is to honor the last heartbeats of your " ..
                "fallen quarry? I will help you to achieve this.\n\nNagrand is a lush land, full of life " ..
                "in the midst of this broken world. Bring down a handful of the windrocs and then we will " ..
                "speak more.\n\nYou can find them in many places nearby in all directions around our camp.",
            rewardMoney = 33000,
        },
        [9855] = {
            description = "You must always push yourself if you are to one day stalk the mightiest of " ..
                "prey! While you are not yet ready, I will point you in the right direction.\n\nThere is " ..
                "another breed of windroc even deadlier. Seek out the ravenous windroc to test your " ..
                "mettle against. You will find them in the heart of Nagrand to the west and southwest.",
            rewardMoney = 37000,
        },
        [9856] = {
            description = "You are ready, <class>. Ready to face the mother of all windrocs, Gutripper! " ..
                "Honor demands that after hunting so many of her children that you give her the chance to " ..
                "defeat you! Seek her out amongst the greater windroc far to the west.\n\nShould you " ..
                "survive, bring her eye to me.",
            rewardChoices = {{25593, 1}, {25594, 1}, {25595, 1}},
            rewardMoney = 74000,
        },
        [9857] = {
            description = "I don't think that I'm up to the hunt today. Do you think that you might take " ..
                "my place?\n\nI told Hemet that I was going to see about bagging us some of those talbuk " ..
                "that seem to be all over the place. The stags are especially nice to hunt. You can find " ..
                "them congregated around the nearby trees.\n\nThink that you could take care of that for " ..
                "me?",
            rewardMoney = 33000,
        },
        [9858] = {
            description = "This darned scratch is getting the worst of me it would seem. So, are you up " ..
                "to filling...<cough>... in for me again?\n\nThis time you're going to bag yourself some " ..
                "thorngrazers. They're tougher and wilier than the stags, so keep your wits about you. " ..
                "Look for them... <cough>... sheltered under the trees in the middle of Nagrand to the " ..
                "west and south.\n\nGo on, get out there and...<cough>... show Hemet what you're made of. " ..
                "I'll be fine.",
            rewardMoney = 35000,
        },
        [9859] = {
            description = "<Wracking cough.>\n\nDon't worry about...<cough>... me. I'll be fine. It's " ..
                "just a...<cough>... scratch.\n\nJust the same, I think you'll... <cough>... have to fill " ..
                "in for me one more... <cough>... time.\n\nYou must seek out the great Bach'lor, king " ..
                "of...<cough>... the stags.\n\nBring me one of his hooves...<cough>, <cough>... as " ..
                "confirmation.\n\nLook for him...<cough>... leading his herd in the far west of Nagrand.",
            rewardChoices = {{25543, 1}, {25545, 1}, {25636, 1}},
            rewardMoney = 70000,
        },
        [9861] = {
            description = "This amorphous mass of elemental air is speaking to you in a language that you " ..
                "cannot understand. You believe the language to be the tongue of the elements: Kalimag. " ..
                "Perhaps someone at the Throne of the Elements could shed some insight on this unusual " ..
                "find.",
        },
        [9862] = {
            description = "Murkblood are capturing and torturing the spirits of air! Murkblood are my " ..
                "kin: A tribe of the Broken who serve the vile Musel'ek, beast lord of Coilfang.\n\nThe " ..
                "air spirit states that the Murkblood putrifiers are capturing other spirits of air and " ..
                "using them to sow chaos into the ranks of the elements. It would seem that the Murkblood " ..
                "have recently sacked an orc village to the southwest known as Sunspring and are using " ..
                "powerful elemental magic to disturb the lake. Find the putrifiers and destroy them.",
            rewardChoices = {{25565, 1}, {25566, 1}, {25567, 1}},
        },
        [9863] = {
            description = "With our leadership in ruin, we are left open to attacks from all sides. The " ..
                "foul Murkblood tribe could not have picked a better time to attack us!\n\nIn recent " ..
                "days, we have been subject to no less than 5 assaults from the Broken. They have even " ..
                "taken over our only other territorial holding in the area: Sunspring Post.\n\nWe must " ..
                "strike and show them that we are not powerless! Strike down the vile idolaters and bring " ..
                "me their twisted idols of worship so that they may ride the lightning.",
            rewardChoices = {{25568, 1}, {25569, 1}, {25570, 1}},
        },
        [9864] = {
            description = "After the last Murkblood raid, a group of younglings decided to act. We tried " ..
                "to stop them but the rage had taken hold. It has now been one week since we last saw our " ..
                "beloved younglings.\n\nPlease, <race>, you must find them! They have just barely reached " ..
                "adolescence. How can they expect to defeat such savages?\n\nThey took the road leading " ..
                "west out of town. Follow that road around and look for signs of our younglings.\n\nAnd " ..
                "<name>, avoid Halaa if you value your life. It is a war-zone.",
        },
        [9865] = {
            description = "I do not know you, stranger, but I ask for your help. I feel shame for this, " ..
                "but I am only one orc.\n\nEmotions have surfaced that I have never felt. I... I seek " ..
                "vengeance. Blood for blood. Do your people ever feel this? I wish to pick up my axe and " ..
                "split my enemies in two. To swing the weapon until my arms fall lifelessly at my sides, " ..
                "exhausted.\n\nSunspring Post is directly south of this procession. It is there that you " ..
                "will find our enemies... Kill them... Kill them all...",
        },
        [9866] = {
            description = "Will you do me one last honor, <name>? I do not wish to return to Garadar. I " ..
                "believe that my destiny lies elsewhere - that I will serve a greater purpose " ..
                "someday.\n\nPlease, return to Farseer Corhuk and tell him that I will not be returning. " ..
                "That I cannot return. I must walk the earth... He will understand.",
            rewardChoices = {{25574, 1}, {25575, 1}, {25576, 1}},
        },
        [9867] = {
            description = "We have lost many friends in recent weeks.\n\nFor decades we have dealt with " ..
                "the ogres of Nagrand but now a new threat has arisen. The Broken tribe of Murkblood " ..
                "attacked our fishing village to the southwest, Sunspring Post, and managed to kill or " ..
                "evict all of the orcs that inhabited the town.\n\nWhile the others feel that the best " ..
                "course of action is to kill indiscriminately, I know that we must destroy their " ..
                "leadership. I do not know who their leader is but I suspect that you will know when you " ..
                "find him.",
            rewardChoices = {{25583, 1}, {25584, 1}, {25585, 1}},
        },
        [9868] = {
            description = "Thank you, stranger. They would have surely killed me had it not been for " ..
                "you.\n\nI was kidnapped by these Murkbloods 3 nights ago during a nighttime raid on " ..
                "Garadar. What I have since uncovered may very well shake the foundation of the Outland: " ..
                "these savages seek to recover the totem of Kar'dash! We cannot allow the totem to fall " ..
                "into the hands of the Murkbloods!\n\nYou must help me escape. And stranger, if I do not " ..
                "make it back to Garadar, you must tell Garrosh what happened here...",
        },
        [9869] = {
            description = "Greetings, <race>. I am Ioki, elementalist of the Earthen Ring. I have come to " ..
                "Telaar to inform the Kurenai of the state of the elements.\n\nCould I ask a favor of " ..
                "you? Would you travel to the Throne of the Elements in the northern hills of Nagrand, " ..
                "beyond Skysong Lake, and tell elementalist Sharvak that I have arrived at Telaar safely? " ..
                "She will surely reward you for this small deed.",
            rewardMoney = 35000,
        },
        [9870] = {
            description = "Greetings, <race>. I am Yal'hah, elementalist of the Earthen Ring. I have come " ..
                "to Garadar to inform the Mag'har of the state of the elements.\n\nCould I ask a favor of " ..
                "you? Would you travel to the Throne of the Elements in the northern hills of Nagrand, " ..
                "beyond Skysong Lake, and tell elementalist Sharvak that I have arrived at Garadar " ..
                "safely? She will surely reward you for this small deed.",
            rewardMoney = 35000,
        },
        [9871] = {
            description = "The parchment holds a crudely painted map of Nagrand. There is a big red 'X' " ..
                "where Telaar would be on the map. It would seem that these savages are planning an " ..
                "attack on the city. Take the Murkblood invasion plans to Arechron in Telaar.",
        },
        [9872] = {
            description = "The parchment holds a crudely painted map of Nagrand. There is a big red 'X' " ..
                "where Garadar would be on the map. It would seem that these savages are planning an " ..
                "attack on the city. Take the Murkblood invasion plans to Garrosh in Garadar.",
        },
        [9873] = {
            description = "These invasion plans were written by someone I once knew. Ortor of Murkblood, " ..
                "once a noble Broken, versed in the way of the elements, now a muck addled yes-man of " ..
                "Musel'ek the bog lord.\n\nThe plans state that they have taken over an orc village " ..
                "northwest of here known as Sunspring.\n\nTravel to Sunspring Post and rid the world of " ..
                "Ortor of Murkblood. What you do, you do for the good of us all...",
            rewardChoices = {{25583, 1}, {25584, 1}, {25585, 1}},
        },
        [9874] = {
            description = "I have just gotten word of a catastrophe of epic proportions, <name>. The foul " ..
                "Murkblood have sacked the orc village of Sunspring Post, northwest of here, and murdered " ..
                "its residents. To make matters worse, they have begun dumping the bodies into Sunspring " ..
                "Lake. Should those bodies rot, our primary source of water in the region will be " ..
                "compromised.\n\nIt's a gruesome task that I give you next but it must be done. Take this " ..
                "enchanted torch and return to Sunspring. Burn all of the rotting orc corpses...",
            rewardChoices = {{25568, 1}, {25569, 1}, {25570, 1}},
        },
        [9875] = {
            description = "Lauranna must've missed this particular plant. You're certain you've " ..
                "discovered a species not yet catalogued by Lauranna's work. You'd best show it to her to " ..
                "see what she makes of it.",
        },
        [9877] = {
            description = "The battle against the Scourge is not one without casualties. Many are slain " ..
                "every day yet many more meet a worse fate.\n\nIt is not uncommon for the Scourge to take " ..
                "prisoners. Death would be preferable to what awaits them in Deatholme. They're " ..
                "interrogated and tortured while under the effects of horrible will-breaking " ..
                "poisons.\n\nApothecary Renzithen in Tranquillien has developed a remedy; go to him and " ..
                "retrieve this restorative draught.",
        },
        [9878] = {
            description = "The appearance of the Murkblood in Nagrand has had a profound negative impact " ..
                "on our environment. The elementals are all in flux which has, in turn, greatly disturbed " ..
                "the wildlife. Worse yet, the razing of Sunspring Post has reignited the hatred that the " ..
                "orcs held for our people.\n\nWhile the Kurenai are a different tribe than the Murkblood, " ..
                "all an orc sees is Broken.\n\nWe must make an effort to solve this dilemma. Travel to " ..
                "Sunspring Post, northwest of here, and resolve the Murkblood problem.",
            rewardChoices = {{25577, 1}, {25578, 1}, {25579, 1}},
        },
        [9879] = {
            description = "I would have been killed had you not come along, stranger. They have already " ..
                "murdered so many Kurenai in their search for a lost relic.\n\nWhat they seek is the " ..
                "totem of Kar'dash. Why they think that we would know anything about this totem, I cannot " ..
                "understand. Is a totem not an orcish implement by nature?\n\nThis information must be " ..
                "taken back to Arechron. Perhaps he knows why Murkblood are kidnapping Kurenai and " ..
                "torturing them for information regarding an orcish device.\n\nLet's go before more come.",
        },
        [9882] = {
            description = "Nexus Prince Haramad has ordered us to not begin work inside of Oshu'gun as it " ..
                "might anger a certain powerful naaru. Sort of puts a damper on our operation.\n\nI think " ..
                "I might've found a loophole, however.\n\nYou see, we're not the only ethereals drawn to " ..
                "this colossal diamond. A thief called Gava'xi has led a band of rogue ethereals into " ..
                "Oshu'gun and they've begun to dislodge large fragments from it.\n\nYour job, <race>, is " ..
                "to go there and retrieve what is rightfully ours.",
            rewardMoney = 35000,
        },
        [9884] = {rewardItems = {{25419, 1}}},
        [9885] = {rewardItems = {{25422, 1}}},
        [9886] = {rewardItems = {{25424, 1}}},
        [9887] = {rewardItems = {{25423, 1}}},
        [9888] = {
            description = "I have escaped certain death, surviving a cowardly nighttime attack by " ..
                "Boulderfist ogres upon my village.\n\nBut I ask you, stranger: For what?\n\n<Jorin " ..
                "points to Garrosh.>\n\nHe has refused to give us assistance. Ogres are rampaging through " ..
                "my town and he sits here, weeping into a fire. What has become of us? What will become " ..
                "of us?\n\nI've sent a scout, Kilrath, to the village, now the Bleeding Hollow Ruins. " ..
                "Will you find him and give him your assistance? He hides on the border of Nagrand and " ..
                "Terokkar.",
        },
        [9889] = {
            description = "I have been watching these beasts for days. The fat one says that he is " ..
                "waiting for something. What he is waiting for, however, is a mystery.\n\nI have a plan " ..
                "but it is going to involve some violence on your part. You will need to kill several of " ..
                "his subordinates and then beat him within an inch of his life. Do this and I am certain " ..
                "he will tell us everything that we need to know.",
        },
        [9890] = {
            description = "For many years, Boulderfist ruled all ogres in the Outland. The ogres were " ..
                "united under Krol and content with the lands that they were given. In the past few " ..
                "months, we have lost many ogres to a new clan known as Warmaul. Warmaul has taken most " ..
                "of our land in Nagrand and killed many of our people.\n\nWe had no choice but to take " ..
                "this town. We are being exterminated...\n\nKrol has gone missing and Boulderfist is in " ..
                "turmoil. Lantresor of the Blade rules in his absence.",
        },
        [9891] = {
            description = "Take what you have learned and tell Jorin at Garadar. I can assure you that he " ..
                "won't be happy to know that our village was destroyed and many of our people killed " ..
                "because the ogres needed more space.\n\nMay the ancestors watch over you... I will be " ..
                "hiding in the bushes if you need me for anything else.",
        },
        [9892] = {rewardMoney = 3800},
        [9893] = {
            description = "All this waiting around for Oshu'gun to be ready for digging is eating into " ..
                "our profits, <name>.\n\nFortunately, I've devised an alternate source of income. The " ..
                "ogres of Nagrand wear warbeads made of obsidian, a mineral that commands a hefty price " ..
                "in many other worlds.\n\nZerid already has had to take care a few of the brutes as a " ..
                "matter of security. Think of the warbeads as an added bonus. Or better yet, don't think " ..
                "about it too much and just bring them to me.",
            rewardMoney = 37000,
        },
        [9894] = {
            description = "In your travels, you might have encountered some of the expedition's watchers. " ..
                "They do the majority of the field work: documenting the unique inhabitants of the marsh, " ..
                "collecting samples, and making contact with sentient species.\n\nThe safety of the " ..
                "watchers is paramount, <class>. We've had to recall the watchers we sent to explore " ..
                "Funggor Cavern to the south, because of marshbeast attacks. Warden Hamoot believes that " ..
                "killing their leader, Lord Klaq, will bring a swift end to the attacks.",
            rewardMoney = 27000,
        },
        [9895] = {
            description = "Have you observed your surroundings closely, <name>? This is an ailing " ..
                "landscape, struggling to keep itself in balance and losing the fight.\n\nIf you know " ..
                "where to look, you can see the symptoms. Members of some species rapidly outgrow their " ..
                "peers and become more aggressive.\n\nA good example of this uncontrolled growth is the " ..
                "marshtrekker Boglash. If you wish to see it for yourself, look no further than the " ..
                "waterways south of the refuge.\n\nBe prepared to defend yourself. The creature knows no " ..
                "mercy.",
            rewardMoney = 27000,
        },
        [9896] = {
            description = "By Khaz'goroth's flaming navel, it's hot here! I can't blame the first party " ..
                "for leaving, but everyone knows 'twasn't the heat that drove them away. No, it was " ..
                "Blacksting, although they won't admit it.\n\nThey were camped just to the south of the " ..
                "glowing draenei towers to the west, just north of the Feralfen Village, when the giant " ..
                "wasp appears out of nowhere and attacks! I can't wait to see the looks on their faces " ..
                "when I bring the creature's stinger back to Ironforge and show it to them!",
            rewardChoices = {{31786, 1}, {31787, 1}, {31788, 1}, {31789, 1}},
            rewardMoney = 27000,
        },
        [9897] = {
            description = "I don't mind sharing. I'm just glad to be saved from that creep, Gankly! And I " ..
                "collected tons of skins from Zangarmarsh, so it's no problem at all!",
            rewardMoney = 33000,
        },
        [9898] = {
            description = "Magasha is the fiercest troll in the Marsh, but she only respects mighty " ..
                "hunters.\n\nI tried to prove myself to her, but the one beast that could impress her is " ..
                "beyond my skill. Maybe you could help me out? It's the giant bog wasp known as " ..
                "Blacksting that roams the area south of the glowing draenei towers to the west. If you " ..
                "bring me its stinger maybe she'll give me a chance to join her hunters.\n\nI know it's a " ..
                "little sneaky, but I promise to learn under her and do ya both proud.",
            rewardChoices = {{31786, 1}, {31787, 1}, {31788, 1}, {31789, 1}},
            rewardMoney = 27000,
        },
        [9899] = {
            description = "Someone needs to find a way to make Reavij come to his senses! He's ignoring " ..
                "his duty and instead, he's devoting all his energy to getting my attention. I've tried " ..
                "ignoring him and telling him to stop. Nothing seems to work.\n\nUntil he gets over this, " ..
                "I'm left cleaning up after him. He was supposed to have dealt with Sporewing, but I'll " ..
                "bet the monster is alive and well. If you have time, would you mind going to the western " ..
                "part of the Dead Mire and killing the bat? I'll deal with Reavij in the meantime.",
            rewardChoices = {{33457, 5}, {33458, 5}, {33459, 5}, {33460, 5}, {33461, 5}, {33462, 5}},
            rewardMoney = 27000,
        },
        [9900] = {
            description = "The presence of rogue ethereals in this area might amuse Gezhe, who sees " ..
                "nothing but opportunity wherever we go, but it's a true threat to the security of our " ..
                "operations.\n\nTheir leader, Gava'xi, is a dangerous criminal and I've made it my top " ..
                "priority to see to it that he is neutralized.\n\nIf you're looking to make yourself " ..
                "useful, go and take care of Gava'xi. I will see to it that you're rewarded properly.",
            rewardChoices = {{25544, 1}, {25637, 1}, {25634, 1}},
            rewardMoney = 37000,
        },
        [9901] = {
            description = "The first expedition the league sent reported encountering a gigantic spore " ..
                "bat they'd taken to calling Sporewing. They had to leave in a hurry, so they didn't have " ..
                "the chance to kill him while they were here, so I figured I'd finish the job for " ..
                "them.\n\nWhat's left of their report suggests that the creature can be found in the " ..
                "southwestern parts of the Dead Mire. I think Vindicator Idaar mentioned that it's to the " ..
                "northeast of Telredor.",
            rewardChoices = {{27503, 5}, {27501, 5}, {27502, 5}, {27499, 5}, {27498, 5}, {27500, 5}},
            rewardMoney = 27000,
        },
        [9902] = {
            description = "Traveling through naga-infested lands has shown me the cruel truth about how " ..
                "my less fortunate brethren are treated. At Marshlight Lake, to the southwest, I observed " ..
                "a particularly malicious taskmaster playing a deadly game. He orders his slaves out to " ..
                "the islands in Marshlight Lake when he knows that Terrorclaw, a giant bogstrok, is ready " ..
                "to feed.\n\nI needn't describe what results. We are too few to take on the naga " ..
                "directly, but we can deprive them of their amusement by killing their pet.",
            rewardChoices = {{25922, 1}, {25923, 1}, {25924, 1}, {25925, 1}},
            rewardMoney = 31000,
        },
        [9903] = {
            description = "You've dealt with most of the little hydra, but I doubt Mragesh was impressed " ..
                "by your display. He's a cunning, ferocious beast and he's dogged many an angler in his " ..
                "time.\n\nI intend to be the last one he'll ever bother. He's bound to be hiding deep in " ..
                "the waters of Serpent Lake, to the northeast. He's a has-been; he just doesn't know it " ..
                "yet.",
            rewardChoices = {{28103, 5}, {28102, 5}},
            rewardMoney = 31000,
        },
        [9904] = {
            description = "I've caught every kind of fish that lives in the marsh, but there's one that " ..
                "eludes me. Sure, I've caught eels and mudfin frenzies. But the last time I was out on " ..
                "one of the islands in Marshlight Lake, I hooked a gigantic bogstrok that snapped my line " ..
                "and got away.\n\nTerrorclaw, he's called, and I won't rest until he's dead. He's too big " ..
                "for any fisherman to catch, so I suppose we'll just have to kill him the old-fashioned " ..
                "way.",
            rewardChoices = {{25922, 1}, {25923, 1}, {25924, 1}, {25925, 1}},
            rewardMoney = 31000,
        },
        [9905] = {
            description = "Last time Maktu was out hunting hydras for hides at Serpent Lake, he was " ..
                "attacked by the biggest hydra he's ever seen. Maktu reached for his spear, but it was " ..
                "too late. He had just enough time to escape becoming hydra food.\n\nWho knows? Maybe " ..
                "next time, Maktu not be so lucky. Maktu wants to be there so there won't be a next time. " ..
                "Will you help Maktu get his revenge on Mragesh?",
            rewardChoices = {{28103, 5}, {28102, 5}},
            rewardMoney = 31000,
        },
        [9906] = {
            description = "Ogres are moved by one thing: Might. If we expose ourselves to them as being " ..
                "weak, they will take advantage of that weakness and wipe us out.\n\nGarrosh might be " ..
                "ready to lie down and let the ogre dogs take our lands but I am not! I need you to " ..
                "deliver a message to the Boulderfist, <name>. The only type of message that they are " ..
                "capable of understanding: Brutality.\n\nTravel to the Burning Blade Ruins, southeast of " ..
                "here and show them the might of the Mag'har.\n\nAnd <name>, check in with the others " ..
                "before leaving.",
        },
        [9907] = {
            description = "Directly west of here you will find the Halaani Basin. Within the basin are " ..
                "the twin clefts of Nagrand: Northwind and Southwind. Boulderfist shock troops use the " ..
                "clefts to hide their ogre mounds.\n\nI need you to track down those troops and kill all " ..
                "that you encounter in the name of Mag'har.",
            rewardChoices = {{25622, 1}, {25623, 1}, {25624, 1}},
        },
        [9910] = {
            description = "If you're venturing into the Burning Blade Ruins, I have a task for you. Take " ..
                "these Mag'har battle standards and place them at three distinct locations in the ogre " ..
                "compound. An area of high visibility is recommended. Look for the gigantic flaming pyres " ..
                "on the upper levels. Place a standard near the first, second, and third Burning Blade " ..
                "pyres.\n\nThe standard will leave a lasting impression upon any ogres who may have " ..
                "missed the battle.",
        },
        [9911] = {
            description = "This bloody mandible comes from an unbelievably large creature. The nether ray " ..
                "that it belonged to has to be the largest ever seen in Zangarmarsh. Judging from the " ..
                "condition of the mandible, the count must've abandoned a diet of carrion in favor of " ..
                "living flesh.\n\nSurely the Cenarion Expedition would be interested in such a specimen. " ..
                "Watcher Leesa'oh has a small camp to the west of Quagg Ridge.",
            rewardMoney = 31000,
        },
        [9912] = {
            description = "The Cenarion Circle's main expeditionary force in Outland is known as the " ..
                "Cenarion Expedition. Though it began as a small venture controlled directly by the " ..
                "Cenarion Circle, it's become a large and fairly autonomous body.\n\nThe expedition's " ..
                "leader, Ysiel Windsinger, has asked us to direct volunteers to her outpost. Report to " ..
                "her at the Cenarion Refuge in eastern Zangarmarsh. Take the main path to the west and it " ..
                "will lead you directly there.",
        },
        [9913] = {
            description = "My organization, the Consortium, is looking for a few resourceful individuals " ..
                "just like yourself. You'll be hard pressed to find ethereals more honest, hard-working " ..
                "or pleasant to be around than us.\n\nAll we require is loyalty, dedication and a " ..
                "reasonable amount of moral flexibility. If you're interested, speak to Gezhe, our ground " ..
                "operations leader. You will find him at Aeris Landing, north of Oshu'gun.",
        },
        [9914] = {
            description = "Ivory is a much sought after prize. I have many customers lined up in far off " ..
                "places to purchase it.\n\nI could be convinced to let you in on a cut of the " ..
                "profits.\n\nThe wild elekk roaming Nagrand have the high quality of tusks that I'm " ..
                "after. Steer clear of the bull elekk; their ivory isn't in the condition that I " ..
                "desire.\n\nOh and don't worry, it's not poaching; I have an understanding with both the " ..
                "orcs and the draenei.\n\nDo you and I have an understanding?",
            rewardMoney = 35000,
        },
        [9916] = {
            description = "The Boulderfist have moved the supplies they stole from our village to the " ..
                "twin clefts of Nagrand, found west of here in the Halaani Basin.\n\nWhile you are in the " ..
                "area, keep your eye out for the supply crates. If we can get those back, it would ease " ..
                "much of the burden that has fallen upon the matrons of Garadar.",
            rewardChoices = {{25629, 1}, {25630, 1}, {25628, 1}},
        },
        [9917] = {
            description = "Do my eyes deceive me or is there an ogre hunting party over yonder? What " ..
                "could ogres be doing this far from their mound? I don't like this one bit, stranger. " ..
                "First Murkbloods and now ogres. We just don't have the manpower to handle all of these " ..
                "threats to our land.\n\nCould you investigate the ogre presence to the east for us? " ..
                "Their forward camp is about 200 paces east of here. You'll know you're at the right " ..
                "place if you see the Boulderfist hunters. Kill them to find the plans!",
        },
        [9918] = {
            description = "The battle plans were written up by an ogre lieutenant. His name is either " ..
                "Dump or Lump.\n\n<Bintook turns the parchment sideways and cocks her head.>\n\nIt could " ..
                "also be Billy.\n\nAnyhow, I think you should go back out there and have a word with " ..
                "Billy or Lump or Dumpy or whatever! Try to approach him diplomatically. If that doesn't " ..
                "work, try using some muscle.",
        },
        [9919] = {
            description = "You're a kind <race>, <name>. Not like some of the others I've met.\n\nYou " ..
                "should meet the rest of my people; they'll be very grateful for your help. Take these " ..
                "spore sacs to my leader, Msshi'fn. You will find him in Sporeggar, north of here.",
        },
        [9920] = {
            description = "You must seek out Mo'mor immediately! You will find him in the center of " ..
                "Telaar, by the fountain. Tell him exactly what the ogre told you.",
        },
        [9921] = {
            description = "These ogre hunting parties are a precursor to invasion. We must strike at them " ..
                "before they have a chance to amass an army big enough to take over our town.\n\nYou're " ..
                "going to need to get your hands dirty, <race>.\n\nThe largest collection of Boulderfist " ..
                "in this region can be found at the Burning Blade Ruins, almost directly east of Telaar, " ..
                "near the border of Terokkar. Go there and show the Boulderfist that Telaar will not bend " ..
                "to their will!",
        },
        [9922] = {
            description = "You made a strong showing, <name>. Are you ready for more?\n\nI have received " ..
                "reports of a large contingent of Boulderfist ogres hidden in the twin clefts of Nagrand, " ..
                "northwest of here in the Halaani Basin.\n\nVenture forth to the clefts and deal with the " ..
                "remaining Boulderfist ogres.",
            rewardChoices = {{25622, 1}, {25623, 1}, {25624, 1}},
        },
        [9923] = {
            description = "HELP! They're gonna eat me! I just know it!\n\nFind the key, I know it has to " ..
                "be on one of these ogres.\n\nIf you get me out of here, my father will reward you " ..
                "handsomely! He's the leader of Telaar, Arechron.",
            rewardMoney = 99000,
        },
        [9924] = {
            description = "< Arechron sighs.>\n\nThis is so embarrassing. Do you remember my boy, Corki? " ..
                "You rescued him from the Burning Blade Ruins recently. Well, his curiosity has gotten " ..
                "the best of him once more. He told me that he was going to investigate the Boulderfist " ..
                "menace for 'uncle' Mo'mor and ran off to the ogre mounds in the Halaani Basin, north of " ..
                "here.\n\nDo you think you could track him down? I would be eternally grateful.",
            rewardChoices = {{25631, 1}, {25632, 1}, {25633, 1}},
        },
        [9925] = {
            description = "Gezhe chose to base our operations as close to Oshu'gun as possible, without " ..
                "any regard for the safety of our crew. Why? Because he projected a ten percent increase " ..
                "in productivity by setting up shop here instead of in the mountains to the " ..
                "south.\n\nNever mind the crazed voidspawn wandering all of ten feet away from us. That " ..
                "would be the security officer's problem, not Gezhe's.\n\nKill some voidspawn for me and " ..
                "I'll pay you a tenth of our security budget. Don't get excited, it's not much of a " ..
                "budget.",
            rewardMoney = 35000,
        },
        [9927] = {
            description = "<Lantresor hands you a pack full of banners.>\n\nThese are Warmaul ogre " ..
                "banners that I recently acquired.\n\nI want you to travel to Kil'sorrow Fortress, " ..
                "directly south of here, and kill as many of the Kil'sorrow filth as you can find. Drive " ..
                "a Warmaul ogre banner through the heart of each fallen Kil'sorrow soldier. Return to me " ..
                "when you have completed this task and the other that this plan requires.",
            rewardMoney = 35000,
        },
        [9928] = {
            description = "You will need to steal Kil'sorrow armaments from Kil'sorrow Fortress if my " ..
                "plan is to work.\n\nSearch the fortress for crates of Kil'sorrow armaments. Bring " ..
                "whatever you can find to me.\n\nKil'sorrow Fortress is located directly south and a " ..
                "little to the west of the Burning Blade Ruins.",
            rewardMoney = 35000,
        },
        [9931] = {
            description = "Now you must plant the seed of war in the fat, useless heads of the Warmaul. " ..
                "To the northwest, near the mountains, you will find the Laughing Skull " ..
                "Ruins.\n\n<Lantresor points into the crate of armaments you brought him.>\n\nDo you " ..
                "recognize those banners? They are Kil'sorrow banners. I want you to take a stack of " ..
                "Kil'sorrow banners and plant them on the corpses of Warmaul ogres. Remember, northwest " ..
                "is where you will find the ogres.",
            rewardMoney = 70000,
        },
        [9932] = {
            description = "Your rampage through Kil'sorrow Fortress has provided us with a special " ..
                "opportunity. We have enough bodies to make it appear as if a great battle has taken " ..
                "place.\n\nTravel to the Laughing Skull Ruins and find the Laughing Skull Courtyard. " ..
                "There should be a blazing pyre in the courtyard. Make sure the area is secure and then " ..
                "use this blanket to send up smoke signals. When my ogres see the smoke, they will sneak " ..
                "in and plant the bodies of slain Kil'sorrow soldiers.\n\nThat should be the final straw!",
            rewardMoney = 70000,
        },
        [9933] = {
            description = "<Lantresor points to an unmarked crate.>\n\nTake it. It is my offering to your " ..
                "people. You have single-handedly saved my clan from extermination.\n\nYou may tell your " ..
                "leader that Lantresor of the Burning Blade and his Boulderfist ogres accept the offering " ..
                "of peace.\n\n<Lantresor bows.>",
            rewardChoices = {{25603, 1}, {25605, 1}, {25606, 1}},
            rewardMoney = 105000,
        },
        [9934] = {
            description = "<Lantresor points to an unmarked crate.>\n\nTake it. It is my offering to your " ..
                "people. You have single-handedly saved my clan from extermination.\n\nYou may tell your " ..
                "leader that Lantresor of the Burning Blade and his Boulderfist ogres accept the offering " ..
                "of peace.\n\n<Lantresor bows.>",
            rewardChoices = {{25608, 1}, {25609, 1}, {25607, 1}},
            rewardMoney = 105000,
        },
        [9935] = {
            description = "Wanted: Dead or Alive\n\nGiselda the Crone of Kil'sorrow and her lackeys for " ..
                "murder, ritual sacrifice, communing with the Legion, kidnapping, and burglary.\n\nKnown " ..
                "to congregate at Kil'sorrow Fortress in southeastern Nagrand, near the border of " ..
                "Terokkar.\n\nLarge gold reward to be dispensed by Warden Bullrok at Garadar to anyone " ..
                "able to bring Giselda to justice.",
            rewardMoney = 105000,
        },
        [9936] = {
            description = "Wanted: Dead or Alive\n\nGiselda the Crone of Kil'sorrow and her lackeys for " ..
                "murder, ritual sacrifice, communing with the Legion, kidnapping, and burglary.\n\nKnown " ..
                "to congregate at Kil'sorrow Fortress in southeastern Nagrand, near the border of " ..
                "Terokkar.\n\nLarge gold reward to be dispensed by Warden Moi'bff Jill at Telaar to " ..
                "anyone able to bring Giselda to justice.",
            rewardMoney = 105000,
        },
        [9937] = {
            description = "You have destroyed two of the biggest threats in Nagrand, <name>. Are you " ..
                "ready to take on the scourge of the Spirit Fields?\n\nDurn the Hungerer lords over the " ..
                "area surrounding Oshu'gun, decimating all in his path. Thus far, none have been able to " ..
                "rid Nagrand of this ferocious gronn. Venture to the Spirit Fields, far southwest of " ..
                "here, near Oshu'gun, and track down Durn. Slay him and I assure you rewards commensurate " ..
                "with the difficulty of the task at hand.",
            rewardChoices = {{25772, 1}, {25773, 1}, {25774, 1}},
            rewardMoney = 111000,
        },
        [9938] = {
            description = "You have destroyed two of the biggest threats in Nagrand, <name>. Are you " ..
                "ready to take on the scourge of the Spirit Fields?\n\nDurn the Hungerer lords over the " ..
                "area surrounding Oshu'gun, decimating all in his path. Thus far, none have been able to " ..
                "rid Nagrand of this ferocious gronn. Venture to the Spirit Fields, west of here, and " ..
                "track down Durn. Slay him and I assure you rewards commensurate with the difficulty of " ..
                "the task at hand.",
            rewardChoices = {{25772, 1}, {25773, 1}, {25774, 1}},
            rewardMoney = 111000,
        },
        [9939] = {
            description = "Wanted: Dead or Alive\n\nZorbo the Advisor, wanted for numerous planned " ..
                "attacks on Garadar. Along with his reavers and shaman, Zorbo has slain countless orcs. " ..
                "Consider Zorbo as armed, dangerous, and merciless.\n\nZorbo makes his home in the " ..
                "Laughing Skull Ruins in the northern mountains of Nagrand.\n\nReward for Zorbo the " ..
                "Advisor 's death or capture to be dispensed by Warden Bullrok at Garadar.",
            rewardMoney = 70000,
        },
        [9940] = {
            description = "Wanted: Dead or Alive\n\nZorbo the Advisor, wanted for numerous planned " ..
                "attacks on Telaar. Along with his reavers and shaman, Zorbo has slain countless Broken. " ..
                "Consider Zorbo as armed, dangerous, and merciless.\n\nZorbo makes his home in the " ..
                "Laughing Skull Ruins in the northern mountains of Nagrand.\n\nReward for Zorbo the " ..
                "Advisor 's death or capture to be dispensed by Warden Moi'bff Jill at Telaar.",
            rewardMoney = 70000,
        },
        [9944] = {
            description = "Greatmother says that we must press on and serve our people. She says that we " ..
                "must serve as an example for Garrosh - to show that life goes on.\n\nI have so many " ..
                "matters to attend to here, especially with Greatmother having taken ill. Would you honor " ..
                "the Mag'har by helping one of their matrons?\n\nSeveral days ago we sent a funeral " ..
                "procession to the Ancestral Grounds and they have yet to return. Will you go search for " ..
                "them? They took the western road out of Garadar. Follow it around and avoid Halaa.",
        },
        [9945] = {
            description = "We were en route to the Ancestral Grounds when we were ambushed by Warmaul. " ..
                "They came from all sides, killing several of the procession guards and many of the " ..
                "others. They even desecrated the remains of the elder in the wagon.\n\nAnd for what? So " ..
                "they could humiliate us and display their power. Not even Boulderfist would have sunk so " ..
                "low.\n\nI am a spiritual orc, <name>, but even I have limitations. Find the attackers at " ..
                "Warmaul Hill to the northwest and destroy them!",
            rewardMoney = 37000,
        },
        [9946] = {
            description = "Have you ever seen an ogre king, <race>? Few have and lived to tell the tale. " ..
                "Unfortunately, that is exactly what we are dealing with here.\n\nThe leader of these " ..
                "barbarians is an ogre named Cho'war. Rumor has it that Cho'war was the ogre responsible " ..
                "for forcing the gronn out of the cave. Cho'war then declared himself king and dissolved " ..
                "the ogre clans that served under the gronn. Thus, Warmaul was born.\n\nFind Cho'war deep " ..
                "in the caves of Warmaul Hill. Slay him and bring me his head.",
            rewardChoices = {{25777, 1}, {25776, 1}, {25775, 1}},
            rewardMoney = 74000,
        },
        [9948] = {
            description = "If I know anything about ogres, it's that they like their food fresh. This " ..
                "means that the Mag'har that they captured are more than likely being kept alive until " ..
                "they are ready to serve. It's a sickening thought, I know, but one that we must use to " ..
                "our advantage.\n\nVenture to Warmaul Hill and search for Mag'har prisoners. If you find " ..
                "prisoners, then you will find keys to their cages on the nearby Warmaul ogres.\n\nKill " ..
                "ogres for their keys and release the prisoners.",
            rewardChoices = {{25778, 1}, {25780, 1}, {25779, 1}},
            rewardMoney = 37000,
        },
        [9951] = {
            description = "Quick, hide! The eyes of Naphthal'ar are upon you... upon us all!\n\nI dare " ..
                "not go to the top of the tower to speak with it, but you... you look as if you might " ..
                "know the right words to say. Just be careful, it doesn't like jokes and will not suffer " ..
                "fools easily.\n\nIf you can, convince it to come down for tea. But, by all means, get it " ..
                "to stop staring at me!",
            rewardChoices = {{28026, 1}, {28028, 1}, {31723, 1}, {25542, 1}, {28027, 1}},
        },
        [9954] = {
            description = "< Arechron shows you a grime covered letter.>\n\nI just received this letter. " ..
                "It's from a clan of ogres known as Warmaul that rule the northwestern lands of Nagrand. " ..
                "It says that they have Corki and if we don't cooperate, they're going to eat him. " ..
                "Admittedly, Corki is a moron, but he's still my blood. Will you rescue him, <name>?\n\nI " ..
                "presume that he's locked up in a cage somewhere on Warmaul Hill. That should be your " ..
                "first stop.",
        },
        [9955] = {
            description = "They call him Cho'war the Pillager, <name>. He's the ogre that forced out the " ..
                "gronn that used to rule over these ogres. You better believe he's powerful!\n\nThe chef " ..
                "said that Cho'war lives in the big cave - wherever that may be... Get that key and get " ..
                "me out of here! If we live through this, my father will no doubt give you the big " ..
                "reward! As soon as I'm free, seek him out.",
            rewardChoices = {{25777, 1}, {25776, 1}, {25775, 1}},
            rewardMoney = 74000,
        },
        [9956] = {
            description = "I was part of a caravan taking supplies to the Orebor Harborage in " ..
                "Zangarmarsh. As we were nearing the border of the marsh, we were jumped by a vicious " ..
                "squad of Warmaul ogres. They killed the others and took me prisoner, along with all of " ..
                "our supplies.\n\nThankfully, they neglected to place a backing on my cage. When they " ..
                "fell asleep, I made my escape.\n\nIt's too late for my comrades but we could really use " ..
                "the supplies they stole. Warmaul Hill is in the northwestern mountains of Nagrand.",
            rewardChoices = {{25778, 1}, {25780, 1}, {25779, 1}},
            rewardMoney = 37000,
        },
        [9957] = {
            description = "We haven't heard from the druids at the Cenarion Thicket of Terokkar Forest in " ..
                "quite some time.\n\n<name>, I'd like for you to go down there and check in with them to " ..
                "see what's happening. There are several ways to get there, but the fastest is to head " ..
                "south along the path, and then take the road that branches east from Shattrath City once " ..
                "you're in the forest.",
        },
        [9960] = {
            description = "Hey there, <class>. We haven't heard from the druids of the Cenarion Thicket " ..
                "in quite some time.\n\nI want you to go over there and check to see what's happening. " ..
                "You can find it by heading northwest through the forest.",
        },
        [9961] = {
            description = "<class>, I have urgent business for you. We haven't heard from the druids of " ..
                "the Cenarion Thicket in quite some time. This is unusual as we usually hear from them at " ..
                "least once every few days.\n\nI want you to go up there and make sure that they're " ..
                "alright. You can find the thicket by heading northwest through the forest.",
        },
        [9962] = {
            description = "So are you ready for your first battle? If you are, let me know and I'll get " ..
                "things started. All you have to do is go wait in the Ring of Blood for your opponent to " ..
                "arrive.\n\nThis fight is against Brokentoe, a ferocious clefthoof.\n\nGood luck! I hope " ..
                "you brought friends.\n\nAnd remember, the fight's over when either you or your opponent " ..
                "are lying face down on the arena floor.",
            rewardMoney = 111000,
        },
        [9967] = {
            description = "This next battle involves a duo - twin brothers to be precise. They call " ..
                "themselves the \"Blue Brothers.\"\n\nIt's not too late to chicken out, <name>. I'd " ..
                "certainly understand.\n\nBut if you're ready for some action, step in the Ring of Blood " ..
                "and wait for the Murkblood twins to arrive.\n\nLast one standing is the winner!",
            rewardMoney = 111000,
        },
        [9968] = {
            description = "Something strange has changed the teromoths of the thicket.\n\nWhere once " ..
                "there was a diversity of life in there, now only the teromoths remain. And while before " ..
                "they were at peace, now they are agitated and will not hesitate to attack you should you " ..
                "get close.\n\nI need to compare the vicious ones to the normal. Collect for me a number " ..
                "of samples from both. You'll find the unaffected teromoths both to the south and the " ..
                "north.\n\nI'm certain this is related to whatever killed all of the druids.",
            rewardMoney = 29000,
        },
        [9970] = {
            description = "This fight is gonna be painful, <name>. Do you have any friends that are brave " ..
                "enough to help you out? The ogres managed to get a giant from Blade's Edge named Rokdar! " ..
                "Trust me, you're gonna need friends, he seems unbeatable! He's hard as a rock - " ..
                "literally!\n\nIf you still want to fight him, step into the Ring of Blood and he will " ..
                "come.",
            rewardItems = {{22829, 5}, {22832, 5}},
            rewardMoney = 111000,
        },
        [9971] = {
            description = "I have no idea what killed all of the druids here. I've been away for a couple " ..
                "of days on a survey of the Bone Wastes to the south.\n\nPlease, you must help me to " ..
                "uncover what's behind this horrible tragedy. Go into the thicket and look for a clue " ..
                "that might reveal something to us. When I was in there briefly, I could have sworn I saw " ..
                "a dead Broken and a strange object next to him.\n\nAnd don't worry about Treelos - he " ..
                "might have been driven insane by what happened, but I think he's mostly harmless.",
            rewardMoney = 29000,
        },
        [9972] = {
            description = "You're murderin' 'em out there, kid! They got a ringer for the next match. " ..
                "They say he's a void lord or something... No way do they want you up against their " ..
                "champion. Did you here that palooka, Mogor, yapping at you? The bets are through the " ..
                "roof!\n\nGet in that ring and take this one out fast!",
            rewardItems = {{22829, 5}, {22832, 5}, {21991, 20}},
            rewardMoney = 111000,
        },
        [9973] = {
            description = "They had to ship the champion in from the Blade's Edge gladiator pits. He was " ..
                "training on mountain giants - three at a time.\n\nIf you win this one, you become the " ..
                "new champion. What do you think your odds are, kid? Do you have a shot? Just give me the " ..
                "word and I'll bet the house on you.\n\nNow get in there and win!",
            rewardMoney = 111000,
        },
        [9977] = {
            description = "< Gurgthock is counting his massive pile of gold.>\n\nYou've made me a lot of " ..
                "money, kid. If you can defeat Mogor, I promise to make it worth your while. All that " ..
                "pain you suffered in the Ring of Blood is gonna end up paying off.\n\nNow get in there " ..
                "and show these ogres what you're made of!",
            rewardChoices = {{25759, 1}, {25760, 1}, {25761, 1}, {25762, 1}, {25763, 1}, {25764, 1}},
            rewardMoney = 117000,
        },
        [9978] = {
            description = "I don't know what to make of all of this, but I do know how we can find more " ..
                "clues.\n\nEmpoor is a Broken merchant that traffics in all sorts of goods and " ..
                "information. If you were to persuade him to talk, I'm sure he might have something " ..
                "interesting to say.\n\nHe travels the road here between Tuurem and Shattrath. Watch out, " ..
                "though -- he travels with a bodyguard.",
        },
        [9979] = {
            description = "I was asked to pick up and deliver some boxes of goods from an ethereal in " ..
                "Shattrath City.\n\nLast I saw him, he was standing outside of the World's End Tavern in " ..
                "Lower City. His name is Wind Trader Lathrai, and that's all that I know!\n\nWant more " ..
                "answers, go talk with him!",
        },
        [9982] = {
            description = "A being riding atop a nether drake arrived in town late last week. He " ..
                "introduced himself as Altruis and then proceeded to ask us several questions about " ..
                "Nagrand.\n\nHe claimed that he was hunting Legion. That such insanity was actually his " ..
                "job. Can you imagine? A person that would willingly hunt demons?\n\nBefore he left, he " ..
                "asked that we let the would-be heroes in town know that he will be staying in western " ..
                "Nagrand for awhile and that should they seek a purpose, to find him.",
        },
        [9983] = {
            description = "A being riding atop a nether drake arrived in town late last week. He " ..
                "introduced himself as Altruis and then proceeded to ask us several questions about " ..
                "Nagrand.\n\nHe claimed that he was hunting Legion. That such insanity was actually his " ..
                "job. Can you imagine? A person that would willingly hunt demons?\n\nBefore he left, he " ..
                "asked that we let the would-be heroes in town know that he will be staying in western " ..
                "Nagrand for awhile and that should they seek a purpose, to find him.",
        },
        [9986] = {
            description = "We need to show the arakkoa that they cannot attack our people with impunity. " ..
                "If we don't stop them here, the roads will no longer be safe for our merchants, " ..
                "couriers, or soldiers.\n\nMy scouts have identified the leaders of each of the major " ..
                "arakkoa settlements in the area. Seek out Ashkaz, Ayit, and Urdak, in Veil Reskk, Veil " ..
                "Shienor, and Veil Skith and kill them.",
            rewardChoices = {{22829, 5}, {22832, 5}},
            rewardMoney = 31000,
        },
        [9987] = {
            description = "We need to show the arakkoa that they cannot attack our people with impunity. " ..
                "If we don't stop them here, the roads will no longer be safe for our merchants, " ..
                "couriers, or soldiers.\n\nMy scouts have identified the leaders of each of the major " ..
                "arakkoa settlements in the area. Seek out Ashkaz, Ayit, and Urdak, in Veil Reskk, Veil " ..
                "Shienor, and Veil Skith and kill them.",
            rewardChoices = {{22829, 5}, {22832, 5}},
            rewardMoney = 31000,
        },
        [9990] = {
            description = "You know, come to think of it, I do recall selling several boxes of strange " ..
                "and exotic engineering parts to Empoor about a month ago. I'm not sure what they'd be " ..
                "used for, but I know that they were delivered to Tuurem.\n\nPerhaps one or more of those " ..
                "boxes is still there?",
            rewardMoney = 31000,
        },
        [9991] = {
            description = "To be my eyes will require some diligence on your part. Nethrandamus will take " ..
                "you through the Legion camps, but you must catalog everything that you see. Even the " ..
                "smallest detail that you may think to be inconsequential could be useful for our " ..
                "purposes.\n\nPrimarily, I want you to note what structures are in the camps and what " ..
                "comprises the camps' defenses.\n\nNethrandamus is ready when you are, <name>. Do not be " ..
                "afraid, he will keep you safe from harm.",
        },
        [9992] = {
            description = "Aren't the trees in the forest beautiful? I've often wondered if they would " ..
                "survive on Azeroth.\n\nI'm hesitant to send back seedlings, though. It's a rough trip " ..
                "and they're much harder to transport than something like a sack of seeds. The seeds are " ..
                "stored in tough cones that fall from the tree's branches once they've reached " ..
                "maturity.\n\nIf you come upon some of those cones in your travels, would you mind " ..
                "bringing some of the seeds back to me?",
            rewardMoney = 29000,
        },
        [9993] = {
            description = "The oily seeds from the forest's olemba trees could prove very valuable. I'd " ..
                "like to gather a larger quantity of them, press them for their oil, and then see what I " ..
                "can do with it.\n\nJust think, there's a whole forest full of trees out there, producing " ..
                "a lot of seeds that go to waste. I don't care if it turns out to be cooking oil, lamp " ..
                "oil, or weapon oil, I won't let it go to waste!\n\nBring me any of the seeds that you " ..
                "happen to gather from the olemba cones. They're all over the place.",
            rewardMoney = 29000,
        },
        [9994] = {
            description = "I don't know about you, but I have no idea what all of those things are. I do " ..
                "know one thing though - they look dangerous!\n\n<name>, I think you should take this box " ..
                "of parts to Jenai Starwhisper at the Allerian Stronghold to the southeast. She may have " ..
                "some idea of what these are.",
            rewardMoney = 16000,
        },
        [9995] = {
            description = "I don't know about you, but I have no idea what all of those things are. I do " ..
                "know one thing though - they look dangerous!\n\n<name>, I think you should take this box " ..
                "of parts to Tooki at Stonebreaker Hold to the southeast. He may have some idea of what " ..
                "these are.",
            rewardMoney = 16000,
        },
        [9996] = {
            description = "We know that the blood elves of Firewing Point are working for Kael'thas and " ..
                "Illidan. And from what you've told me, clearly they are using the Broken of Tuurem as " ..
                "smuggling go-betweens for the creation of some horrible weapon.\n\nWhatever they're up " ..
                "to out there, the most efficient thing that we can do right now is to thin out their " ..
                "numbers.\n\nThe Firewing blood elves need to be taken out! Head up to Firewing Point to " ..
                "the north and see to it.",
            rewardMoney = 31000,
        },
        [9997] = {
            description = "We know that the blood elves of Firewing Point are working for Kael'thas and " ..
                "Illidan. And from what you've told me, clearly they are using the Broken of Tuurem as " ..
                "smuggling go-betweens for the creation of some horrible weapon.\n\nWhatever they're up " ..
                "to out there, the most efficient thing that we can do right now is to thin out their " ..
                "numbers.\n\nThe Firewing blood elves need to be taken out! Head over to Firewing Point " ..
                "to the northeast and see to it.",
            rewardMoney = 31000,
        },
        [9998] = {
            description = "The recent arrival of the fel orcs at the ruins to the east both puzzles and " ..
                "troubles Thander. They wasted no time in starting to construct fortifications and repair " ..
                "the buildings.\n\nThe construction goes on day and night, <name>. I've dispatched one of " ..
                "my most reliable agents to keep watch, but we can ill afford to delay action. Move " ..
                "against their workers, then seek out Theloria Shadecloak at the Allerian Post to the " ..
                "north of the Bonechewer Ruins. She'll give you further instructions.",
            rewardMoney = 29000,
        },
        [9999] = {
            description = "As long as the transporters stand, nothing we do to the forge camps will have " ..
                "any permanence. We must find a way to destroy the Legion structures.\n\nI need time to " ..
                "devise a plan of attack. If you can keep their engineers and tinkerers busy, it would " ..
                "greatly slow down their progress, buying me the time I need.",
        },
        [10000] = {
            description = "Our forces at Thrallmar thought they had the fel orcs contained in the " ..
                "Hellfire Citadel area, but the recent arrivals at the ruins to the east say " ..
                "otherwise.\n\nWe can't permit them to gain a foothold here. Rokag has dispatched " ..
                "Shadowstalker Kaide to the ruins to keep an eye on them, but we have to do something to " ..
                "keep them from digging in.\n\nGo to the ruins, decimate their peons, and then look for " ..
                "Kaide in the trees to the north. He'll tell you where to go from there.",
            rewardMoney = 29000,
        },
        [10001] = {
            description = "All forge camps have a master planner. The master planner dictates what types " ..
                "of structures are present at a forge camp and how each structure is situated. Moreover, " ..
                "this information is kept on a set of blueprints that the planner carries around on their " ..
                "person.\n\nWe need the master planner's blueprints. Armed with such exacting " ..
                "information, we could persuade an acquaintance of mine to lend some assistance.\n\nFind " ..
                "the mo'arg master planner and take his blueprints. He will be stationed behind the " ..
                "forges.",
        },
        [10002] = {
            description = "Over the past couple of days, I've observed a blood elf woman traveling to and " ..
                "from the fel orc stronghold and conversing with the fel orc leader. From her body " ..
                "language, she's clearly issuing orders. But why? Whose orders is she conveying?\n\nMy " ..
                "curiosity got the better of my judgment and I shadowed her when she left the fel orc " ..
                "encampment. She headed north, to Firewing Point. I stopped before reaching the perimeter " ..
                "of the blood elf outpost.\n\nKill her before she leaves the fel orc camp again.",
            rewardMoney = 31000,
        },
        [10003] = {
            description = "Over the past couple of days, I've observed a blood elf woman traveling to and " ..
                "from the fel orc stronghold and conversing with the fel orc leader. From her body " ..
                "language, she's clearly issuing orders. But why? Whose orders is she conveying?\n\nMy " ..
                "curiosity got the better of my judgment and I shadowed her when she left the fel orc " ..
                "encampment. She headed north, to Firewing Point. I stopped before reaching the perimeter " ..
                "of the blood elf outpost.\n\nKill her before she leaves the fel orc camp again.",
            rewardMoney = 31000,
        },
        [10004] = {
            description = "Take the blueprints and travel to Shattrath City in the Terokkar Forest. Once " ..
                "at Shattrath, go to the Lower City and look for a mo'arg by the name Sal'salabim. He'll " ..
                "probably be at the bar, drinking away his sorrows.\n\nBy the way, you may need to " ..
                "convince him to lend his assistance. Try to approach him with patience and " ..
                "understanding. If that does not work, use your fists.",
        },
        [10005] = {
            description = "<name>, after you're done celebrating here, I think that you should go back to " ..
                "the Cenarion Thicket and speak with Earthbinder Tavgren.\n\nI'm certain that he'll want " ..
                "to know what really happened out there.",
            rewardChoices = {{25929, 1}, {25930, 1}, {25931, 1}, {25932, 1}},
            rewardMoney = 87000,
        },
        [10006] = {
            description = "<name>, I think that after you're done celebrating here, you should go back to " ..
                "the Cenarion Thicket and speak with Earthbinder Tavgren.\n\nI'm certain that he'll want " ..
                "to know what really happened out there.",
            rewardChoices = {{25929, 1}, {25930, 1}, {25931, 1}, {25932, 1}},
            rewardMoney = 87000,
        },
        [10007] = {
            description = "Knowing Thander and Bertelm, they won't tolerate such a large buildup of " ..
                "hostile forces on our doorstep. Asking them to dispatch members of the garrison to " ..
                "participate in an attack on the camp isn't an option either. It would just leave us too " ..
                "vulnerable to attack.\n\nIt falls to us to do what we can to diminish the threat the fel " ..
                "orc buildup poses. Kill what you can of their forces and I will look for ways to stall " ..
                "any reinforcements.",
            rewardChoices = {{25971, 1}, {25972, 1}, {25973, 1}},
            rewardMoney = 31000,
        },
        [10008] = {
            description = "If word reaches Thrallmar that they've failed to contain the fel orcs, we're " ..
                "going to be receiving a lot of company down here. Frankly, I'm not sure I want all that " ..
                "attention, so we're going to keep this little problem under wraps, got it?\n\nIf we can " ..
                "inflict enough casualties on the fel orcs, chances are their presence will never come to " ..
                "the attention of anyone outside Stonebreaker. So, let's end it now.\n\nWade in there, " ..
                "swing your weapon, wave your hands, or whatever it is you do - just kill fel orcs.",
            rewardChoices = {{25971, 1}, {25972, 1}, {25973, 1}},
            rewardMoney = 31000,
        },
        [10009] = {
            description = "< Sal'salabim laughs.>\n\nThis Sal'salabim design.\n\n< Sal'salabim points to " ..
                "the architecture and formations on the blueprints.>\n\nLook at towers. Demon hunter no " ..
                "can see, yes? Poor, poor Altruis. He cry if he had eyes, yes?\n\nYes, Sal'salabim help " ..
                "but first you help Sal'salabim.\n\n< Sal'salabim gives you a ledger.>\n\nThese creatures " ..
                "owe Sal'salabim golds. Many golds. Go collect for Sal'salabim and come back. They no " ..
                "give you Sal'salabim gold easy. Have to fight, but you strong. You defeat Sal'salabim!",
            rewardMoney = 39000,
        },
        [10010] = {
            description = "< Sal'salabim points to the blueprint.>\n\nYou see where fel cannons are?\n\n< " ..
                "Sal'salabim draws an arrow denoting a change of direction.>\n\nYou turn fel cannon " ..
                "around and use on structures.\n\nWait! Don't be mad! One thing you not know. Overseers " ..
                "have key to turn cannons. You need key first! One from each overseer!\n\nNot so easy, " ..
                "eh?\n\nTake information back to Altruis.",
        },
        [10011] = {
            description = "Gather your courage, <name>. You will need it if you are to face an " ..
                "overseer.\n\nOnce you are ready, find and kill the overseers at each camp. Take their " ..
                "keys and use them to turn and fire the fel cannons upon the camps. Return to me once the " ..
                "camps are destroyed.",
            rewardChoices = {{25819, 1}, {25820, 1}, {25821, 1}, {25822, 1}},
            rewardMoney = 117000,
        },
        [10012] = {
            description = "The writing on the plans is far too delicate and precise to have come from any " ..
                "of the fel orcs. You can't make out what the text says, but the implications are pretty " ..
                "clear: the fel orcs are taking orders from the blood elves at Firewing Point.\n\nWhy " ..
                "would the two forces be working together? Bertelm might have some insight into this odd " ..
                "alliance. You decide to make your way back to the Allerian Stronghold and show him the " ..
                "map.",
            rewardMoney = 31000,
        },
        [10013] = {
            description = "The writing on the plans is far too delicate and precise to have come from any " ..
                "of the fel orcs. You can't make out what the text says, but the implications are pretty " ..
                "clear: the fel orcs are taking orders from the blood elves at Firewing Point.\n\nWhy " ..
                "would the two forces be working together? Rokag might have some insight into this odd " ..
                "alliance. You decide to make your way back to Stonebreaker Hold and show him the map.",
            rewardMoney = 31000,
        },
        [10016] = {
            description = "Have you come across the timber worgs in your travels? I've had the " ..
                "opportunity to observe them while mapping some of the northern reaches of the forest. I " ..
                "wouldn't recommend getting close to them unless you're prepared for combat.\n\nThey have " ..
                "no fear of us and won't hesitate to defend their territory.\n\nIt's fitting that such a " ..
                "creature would have a magnificent tail. I've been trying to collect enough of them to " ..
                "trim a new cloak, but the worgs have a habit of evading my snares. Will you help?",
            rewardMoney = 31000,
        },
        [10017] = {
            description = "More and more refugees come through the gates of Shattrath City each day. Some " ..
                "have sustained such injuries, it's a real wonder they made it here.\n\nI can deal with " ..
                "most of the conventional injuries; my training as an Aldor healer has prepared me for " ..
                "that. Poison wounds are more problematic as my anti-venom supplies have begun to run " ..
                "low.\n\nBring me venom sacs from the local dreadfang spiders so I can produce more " ..
                "antidotes. You'll find a pocket of the spiders in the southeastern region of Terokkar.",
        },
        [10018] = {
            description = "Generations ago, when orc clans still called Terokkar Forest home, the wolf " ..
                "spirit played an important role in their lives. When the orcs departed, they had no " ..
                "longer had any need for the spirit and they left it behind.\n\nIn time, the spirit grew " ..
                "lonely and it too left the forest.\n\nI believe I can bring the wolf spirit back to his " ..
                "ancestral home, just as we orcs have returned. The ritual will require me to create " ..
                "vestments from the pelts of the wolves of the forest to guide the spirit back to its " ..
                "home.",
            rewardMoney = 31000,
        },
        [10020] = {
            description = "The woman to my right suffered a severe injury to the head. She survived, but " ..
                "lost her eyesight.\n\nA traditional cure used among my people requires the blood of a " ..
                "very old basilisk.\n\nUnfortunately, due to poaching from various groups, Terokkar " ..
                "basilisks don't tend to live very long.\n\nThere is one basilisk whose name I've known " ..
                "since I was a youngling. It is known only as \"Stonegazer\" and it's rumored to live " ..
                "east of here, near the land's edge.\n\nBring me its blood so that Zahlia may see once " ..
                "again.",
            rewardMoney = 62000,
        },
        [10021] = {
            description = "Much of this region was inhabited by draenei long ago. We Aldor were charged " ..
                "with the safeguarding of our holy sites and altars. Many of them have since been " ..
                "destroyed or taken over by our enemies.\n\nTo the east of here there is an arakkoa " ..
                "outpost. It was purposefully built on the location of three of our sacred altars. The " ..
                "arakkoa use their foul magic to warp and defile the innate power of our shrines.\n\nTake " ..
                "this to the arakkoa outpost and use it to cleanse the three altars.",
        },
        [10022] = {
            description = "Now that I have the fur I'll need for the trim, I've been thinking that the " ..
                "pelt of a particular wolf would make a good hood for my cloak. Imagine seeing your enemy " ..
                "clad in the pelt of the most cunning predator in the forest!\n\nI've tried trapping old " ..
                "Ironjaw without success. I've tried cornering him, outsmarting him, and baiting him. " ..
                "None of it has worked.\n\nHe stalks the northeastern reaches of the forest, and I'd " ..
                "gladly reward you if you could succeed where I have failed.",
            rewardChoices = {{25974, 1}, {25975, 1}, {25976, 1}, {25977, 1}},
            rewardMoney = 31000,
        },
        [10023] = {
            description = "You've done well in gathering the first pelts.\n\nThe final piece of the " ..
                "vestments requires a pelt unlike any other. There is one particular wolf, an old and " ..
                "cunning one, that has earned his place as the patriarch of the forest wolves. He is " ..
                "known among them as Ironjaw, the mighty hunter.\n\nIn my visions, I have seen him " ..
                "wandering the northeastern region of the forest. Including his pelt in the vestments " ..
                "will surely light the wolf spirit's path.\n\nDo not mourn Ironjaw. He will be well " ..
                "honored.",
            rewardMoney = 31000,
        },
        [10024] = {
            description = "Our leader, Voren'thal the Seer, was once a close advisor to Kael'thas. His " ..
                "prophetic visions warned him that Kael's path would lead to the destruction of our " ..
                "race.\n\nThe visions are usually vague and unfocused, but our alchemists have devised an " ..
                "elixir to help him focus his clairvoyance. Unfortunately, this elixir calls for a rare " ..
                "ingredient: basilisk eyes. My usual source, this pathetic ethereal, has failed " ..
                "me.\n\nSeek the dampscale basilisks in the rocky regions of Terokkar and bring me their " ..
                "eyes.",
        },
        [10026] = {
            description = "It's embarrassing to admit this, but something has happened to me here in " ..
                "Terokkar Forest that hasn't occurred since my apprentice days.\n\nOccasionally, my " ..
                "spells will fizzle when I know I've done everything correctly. I almost drove myself " ..
                "crazy the first time it happened.\n\nI think I've found the cause. The forest is full of " ..
                "creatures called warp stalkers, demonic creatures with an affinity for magic and a habit " ..
                "of disturbing magical flows. The best way to deal with them is simply to kill them.",
            rewardMoney = 31000,
        },
        [10027] = {
            description = "There's nothing more annoying than preparing to cast a spell, only to have it " ..
                "interrupted by some unseen force. After the fourth time, I knew it couldn't be " ..
                "coincidence and I sent Keb'ezil out to investigate.\n\nI guarantee you'll never " ..
                "encounter an imp that talks back more than Keb.\n\nAnyway, he managed to find the source " ..
                "of the problem, a pesky creature known as a warp stalker. They have a habit of " ..
                "disturbing the magical energy wherever they blink into existence. I've had enough of " ..
                "their interference.",
            rewardMoney = 31000,
        },
        [10028] = {
            description = "Amid the ruins of Tuurem are a number of vessels containing raw, magical " ..
                "energy. We are fortunate that the Broken who have overrun the city are ignorant to the " ..
                "resource in their midst, but we cannot assume they will remain so forever.\n\nWith those " ..
                "vessels and their power in hand, the scattered survivors of my people can resist the " ..
                "lure of demonic magic. Every quel'dorei we can save from our prince's folly is one more " ..
                "that can help us regain our lost glory. Bring me these vessels, <class>.",
            rewardMoney = 29000,
        },
        [10030] = {
            description = "The bones of the dead draenei litter the Bone Wastes from the explosion of " ..
                "Auchindoun. Their spirits are restless, and cannot move on to the next life.\n\n<class>, " ..
                "you must help me to recover their bones and take them to their final resting place! Only " ..
                "then will they be at peace; only then will they know comfort.\n\nGather up the restless " ..
                "bones with care and deliver them to Ramdor the Mad at Auchindoun in the center of the " ..
                "Bone Wastes. Despite his name, he will know how to care for them.",
            rewardMoney = 33000,
        },
        [10031] = {
            description = "Many spirits of the draenei were corrupted by the explosion of Auchindoun. Now " ..
                "they wander the wastes in torment.\n\n<name>, I beseech you to put them to rest. Destroy " ..
                "the lost spirits and broken skeletons that haunt the Bone Wastes beyond Auchindoun's " ..
                "walls.\n\nWhat? You think leaving them to wander in blind agony would be " ..
                "better?\n\nAfterward, return to Soolaveen at the Refugee Caravan and tell him of that " ..
                "which you have done.",
            rewardChoices = {{25948, 1}, {25949, 1}, {25951, 1}, {31725, 1}},
            rewardMoney = 33000,
        },
        [10033] = {
            description = "A bounty is declared on the bonelashers of the Bone Wastes. As known carriers " ..
                "of the plague, they are to be destroyed forthwith!\n\nWhile they can be found throughout " ..
                "the wastes, they are known to congregate at Carrion Hill in the north.\n\nReport to " ..
                "Taela Everstride afterward to collect your reward.",
            rewardMoney = 33000,
        },
        [10034] = {
            description = "The bonelashers of the Bone Wastes bit Mawg and made him sick. Now he wants " ..
                "all of them destroyed!\n\nWhile they can be found throughout the wastes, they are known " ..
                "to congregate at Carrion Hill in the north.\n\nReturn to Mawg Grimshot after you've done " ..
                "the deed and he'll give you a good reward.",
            rewardMoney = 33000,
        },
        [10035] = {
            description = "There's a creature in the Bone Wastes so fearsome that only the dauntless dare " ..
                "to stalk him.\n\nI speak of Torgos, king of the bonelashers, who circles over Veil Rhaze " ..
                "on the western edge of the wastes.\n\nToo bad that there's an arakkoan scarecrow there, " ..
                "known as Torgos's Bane, which keeps him at bay. I'd bet if you laid his mate Trachela's " ..
                "carcass at the foot of that scarecrow he'd come down anyway. She can be found at Carrion " ..
                "Hill in the northern wastes.\n\nBring me one of Torgos's tail feathers.",
            rewardChoices = {{25937, 1}, {25936, 1}},
            rewardMoney = 66000,
        },
        [10036] = {
            description = "I want Torgos, king of the bonelashers, dead!\n\nNot long ago, while I was out " ..
                "hunting at Veil Rhaze on the western edge of the wastes, he fell upon me.\n\n<Mawg taps " ..
                "his eyepatch.>\n\nHe took my eye, and now I would have his life! Bring me one of his " ..
                "tail feathers as proof and I'll give you a worthy reward.\n\nYou'll need his mate " ..
                "Trachela's carcass though to call him down as he's deathly afraid of the old arakkoan " ..
                "scarecrow known as Torgos's Bane.\n\nFind her at Carrion Hill in the northern wastes.",
            rewardChoices = {{25937, 1}, {25936, 1}},
            rewardMoney = 66000,
        },
        [10037] = {
            description = "Speaking of lakes, there's a lake with real good fishin' up to the northeast. " ..
                "I used to go up there with my friends, but my mom won't let me go anymore.\n\nShe says " ..
                "it's too dangerous, but I haven't seen anything up there but a few little spiders. Like " ..
                "spiders can do anything to you...\n\nMy favorites were always the eels that live up " ..
                "there. If you're going to be up by the lake, would you think about bringing back some of " ..
                "the eels? They're feisty but once you subdue 'em, you can bring 'em back no problem.",
            rewardItems = {{25978, 1}},
        },
        [10038] = {
            description = "A report's just come in from one of our scouts near Grangol'var Village. He " ..
                "says that a shadowy band has moved into the ruins there.\n\n<name>, I want you to speak " ..
                "with Private Weeks and see how you can assist him to figure out what this unknown group " ..
                "is up to. Just head west past Stonebreaker Hold. His last report puts his position near " ..
                "the north entrance to the village.",
        },
        [10039] = {
            description = "I am informed that one of our scouts near Grangol'var Village is currently " ..
                "observing a shadowy band that has recently moved in there.\n\n<name>, I want you to " ..
                "speak with Scout Neftis and see how you can assist her in figuring out what this unknown " ..
                "group is up to.\n\nJust head south out of here, and then due west, skirting the north of " ..
                "the Bone Wastes. Her last report puts her position near the southern entrance to the " ..
                "village.",
        },
        [10040] = {
            description = "I don't know who they are, but I know they're hostile!\n\nI'm going to give " ..
                "you a disguise, and I want you to go in there and speak with three of them that I've " ..
                "observed as being 'chatty'. Talk with the initiate, the laborer, and the " ..
                "advisor.\n\nJust watch out; there're a few hunters in there who'll be able to see " ..
                "through your disguise and they look tough! And whatever you do, don't leave the village " ..
                "-- the disguise is kind of flimsy. If you lose your disguise, come back to me and I'll " ..
                "give you another.",
            rewardMoney = 33000,
        },
        [10041] = {
            description = "I don't know who they are, but I know they're hostile!\n\nI'm going to give " ..
                "you a disguise, and I want you to go in there and speak with three of them that I've " ..
                "observed as being 'chatty'. Talk with the initiate, the laborer, and the " ..
                "advisor.\n\nJust watch out; there're a few hunters in there who'll be able to see " ..
                "through your disguise and they look tough! And whatever you do, don't leave the village " ..
                "-- the disguise is kind of flimsy. If you lose your disguise, come back to me and I'll " ..
                "give you another.",
            rewardMoney = 33000,
        },
        [10042] = {
            description = "What! Those guys are Shadow Council?!\n\n<name>, you have to go back in there " ..
                "and waste them! I want you to take out their leader and as many of their executioners " ..
                "and summoners as you can.\n\nAfter you're done with that, report back to Lieutenant " ..
                "Gravelhammer at the Allerian Stronghold.\n\nGood luck, <class>!",
            rewardChoices = {{25933, 1}, {25934, 1}, {25935, 1}},
            rewardMoney = 66000,
        },
        [10043] = {
            description = "What! Those guys are Shadow Council?!\n\n<name>, you have to go back in there " ..
                "and waste them! I want you to take out their leader and as many of their executioners " ..
                "and summoners as you can.\n\nAfter you're done with that, report back to Advisor Faila " ..
                "at Stonebreaker Hold.\n\nGood luck, <class>!",
            rewardChoices = {{25933, 1}, {25934, 1}, {25935, 1}},
            rewardMoney = 66000,
        },
        [10044] = {
            description = "The Greatmother has asked that I seek you out and deliver a message. She " ..
                "wishes to speak with you at once.\n\nMy will has been sapped but make no mistake, " ..
                "<name>, if you anger the Greatmother, I will come down upon you with all the force that " ..
                "I can muster. She is in the main hall.\n\n< Garrosh points at the large building to the " ..
                "north.>\n\nListen to what she has to say and do as she tells you.",
        },
        [10045] = {
            description = "Mother Kashur wishes to speak with you, <name>. Before this becomes possible, " ..
                "you must collect the herbs required to create a potion that will expand your mind, " ..
                "allowing you to commune with the spirits.\n\nYou must gather Olemba root from Terokkar, " ..
                "marshberries from Zangarmarsh, Telaari fronds from Nagrand and dragonspine from the " ..
                "Blade's Edge mountains. I have written down instructions on this parchment as to the " ..
                "cultivation of these herbs. Return to me when you have gathered the materials.",
        },
        [10047] = {
            description = "The 'Path of Glory,' they called it. A road leading from the heart of their " ..
                "gruesome fortress to the Dark Portal, paved with the bones of my people.\n\nIt wasn't " ..
                "enough for them to hunt us down like animals, destroy our cities, and torture those who " ..
                "survived. No, they had to use our bones as paving stones, denying my brethren a proper " ..
                "burial under the Light.\n\nThose tortured souls still wander these lands, crying out for " ..
                "release. I ask you, <name>, help me in this undertaking.",
        },
        [10050] = {
            description = "Near the end of our invasion, the Armory to the south fell under attack by the " ..
                "Horde's insidious Death Knights. Those vile shades cursed the Armory's defenders - and " ..
                "trapped their souls between the realms of the living and the dead.\n\nThose noble souls " ..
                "must be set free! I beg you, <name>, end my comrades' torment, for I have not the heart " ..
                "to slay them myself.",
            rewardMoney = 20000,
        },
        [10051] = {
            description = "Thank goodness for you!\n\n<class>, I need you to help me escape. I have " ..
                "information vital to the security of the Allerian Stronghold and probably all of " ..
                "Outland!\n\nI came here from the Cenarion Expedition on a diplomatic mission, but as you " ..
                "can see, they weren't very friendly. If you help me get to safety, I can assure you that " ..
                "you will be handsomely rewarded!",
            rewardChoices = {{25916, 1}, {25917, 1}, {25918, 1}},
            rewardMoney = 62000,
        },
        [10052] = {
            description = "Thank goodness for you!\n\n<class>, I need you to help me escape. I have " ..
                "information vital to the security of Stonebreaker Hold and probably all of Outland!\n\nI " ..
                "came here from the Cenarion Expedition on a diplomatic mission, but as you can see, they " ..
                "weren't very friendly. If you help me get to safety, I can assure you that you will be " ..
                "handsomely rewarded!",
            rewardChoices = {{25916, 1}, {25917, 1}, {25918, 1}},
            rewardMoney = 62000,
        },
        [10055] = {
            description = "Reinforcements are great, but I don't see 'em haulin' any wagons loaded with " ..
                "ingots or timber.\n\nTake a look around, friend. Trees are in short supply, and the " ..
                "mines are overrun with Legion scum.\n\nI'm in a bad way fer supplies, and I'm makin' " ..
                "what substitutions I can, but it's time to start reusing what we can.\n\nThe southern " ..
                "edge of the Path o' Glory is strewn with the ruins of siege machinery. Some pieces of " ..
                "'em are still usable. Feeling up to a bit o' a salvage operation?",
            rewardChoices = {{29931, 1}, {29938, 1}, {29943, 1}, {29945, 1}},
            rewardMoney = 20000,
        },
        [10057] = {
            description = "The disturbances at Expedition Armory continue, despite your best efforts. No " ..
                "one truly knows everything that happened there, nor exactly what binds the spirits of " ..
                "the fallen soldiers to the ruins.\n\nPerhaps we've been approaching this the wrong way. " ..
                "I've always assumed that each of the ghosts had a tie to the ruins, but what if their " ..
                "ties were to their leaders?\n\nArch Mage Xintor and Lieutenant Commander Thalvos were " ..
                "particularly close to their men, so perhaps overcoming their ghosts will calm the rest.",
            rewardChoices = {{25989, 1}, {25992, 1}, {25993, 1}},
            rewardMoney = 20000,
        },
        [10058] = {
            description = "<The priest's gaze slowly moves from his mug to you.>\n\nDon't you know better " ..
                "than to bother a man in his cups?\n\nOh, what's the use? I suppose newcomers are a good " ..
                "sign. What would Turalyon think?\n\nI remember the eve of our departure, when I gave " ..
                "Mysteries of the Light to him. During the campaign and the ensuing years, he never " ..
                "forgot to read his daily passage to the men.\n\nWhen he left us again, he gave the book " ..
                "back to me. Like a fool, I believed it safe in my quarters to the south of the armory.",
            rewardMoney = 20000,
        },
        [10063] = {
            description = "Babysitting! Would you believe it?\n\nThey pulled me out of a promising dig " ..
                "and sent me along with Captain Odesyus' expedition to babysit that little gnome!\n\nI'd " ..
                "never heard o' a gnome wanting to become a prospector before, so I asked.\n\nSeems we " ..
                "are takin' gnomes now, and this particular one has a fascination with murlocs!\n\nWell, " ..
                "he's gone off and set up shop in an old turtle shell on the northern shore of the " ..
                "island. Go and have a look if you don't believe me!",
        },
        [10064] = {
            description = "The Hand of Argus has established a forward base at Vindicator's Rest, but " ..
                "they are sorely outnumbered by both the blood elves and mutated wildlife. Without " ..
                "backup, their outpost is in danger of falling, and we'd have no way to keep an eye on " ..
                "events near the Vector Coil.\n\nReport to Scout Jorli at Vindicator's Rest to the " ..
                "northwest and offer her your assistance, <name>.",
        },
        [10065] = {
            description = "During our mission to reconnoiter the Sunhawks and their portal, I sustained a " ..
                "serious wound. Scout Loryi has managed to staunch the bleeding and she's trying to " ..
                "figure out a way to evacuate me to Blood Watch.\n\nThe problem is that we'd have to " ..
                "abandon our position here in order to guarantee a safe return.\n\nAs soon as we leave " ..
                "this consecrated ground, we'll be set upon by ravagers. If you can clear some of the " ..
                "enraged ravagers, it might allow us to make the trip back safely.",
        },
        [10066] = {
            description = "We don't dare abandon our post, or wander too far from Vindicator's Rest, " ..
                "<race>. The mutated creatures closest to the Vector Coil have been changed profoundly by " ..
                "energy leaking from the crystals.\n\nThe mutated tanglers appear to have gained a " ..
                "certain degree of sentience. They've learned to create, set, and conceal vicious traps " ..
                "that can ensnare even the most careful warrior.\n\nWe'll never be able to move against " ..
                "the Sunhawks if we're constantly forced to look underfoot. Attack the problem at its " ..
                "source, <name>.",
            rewardMoney = 1000,
        },
        [10067] = {
            description = "Most of the creatures touched by the crystals' energy have been corrupted in " ..
                "the same ways: strange marks on their flesh, increased aggression, and small crystal " ..
                "shards in their bodies. However, the fouled water spirits north of here appear to be " ..
                "turning entirely to crystal.\n\nI've never seen anything react to the crystals this way " ..
                "before, when we explored the foul pool, they were particularly dangerous. We must get " ..
                "rid of them before the Sunhawks can exploit them as a new source of energy.",
            rewardMoney = 1100,
        },
        [10068] = {
            description = "As you begin to grow in power, your connection to the arcane will develop, " ..
                "granting you access to new spells.\n\nGo, develop your power, and then demonstrate what " ..
                "you learn for me.",
        },
        [10069] = {
            description = "It is time for your first lesson in the ways of the Light, <name>. As you " ..
                "fight more battles, it will bring you closer to the light, and you'll start to uncover " ..
                "new abilities.\n\nGo, get more experience, and learn a new ability. Return and " ..
                "demonstrate it for me, and we'll continue your training.",
        },
        [10070] = {
            description = "And now, it is time for your first lesson.\n\nAs you become more skilled, you " ..
                "will begin to discover new techniques.\n\nGo out, get some more experience, and learn " ..
                "your first new ability. Once you do, go find a training dummy and practice your new " ..
                "skill.",
        },
        [10071] = {
            description = "As you grow in power, you'll start to figure out the tricks of the " ..
                "trade.\n\nOne of the first things you'll probably figure out is how to Eviscerate your " ..
                "enemy after landing some initial attacks.\n\nGet some experience, learn how to do it, " ..
                "and then find one of the training dummies outside and give it a try.",
        },
        [10072] = {
            description = "As you grow in skill, so will the array of powers that you can call " ..
                "upon.\n\nI'd like you to go, continue to become more experienced, and discover a new " ..
                "spell. Once you do, come back and demonstrate it for me.",
        },
        [10073] = {
            description = "By now, you've heard the rumors about our kind, the warlocks. Pay them no " ..
                "mind; they are uttered by those jealous of our fearsome powers.\n\nAs you become more " ..
                "experienced, you will uncover mysteries of controlling fel energies.\n\nGo, continue " ..
                "your journey until you uncover a new technique. I want you to practice using this new " ..
                "spell on the training dummies outside the Sunspire.",
        },
        [10074] = {
            description = "This base was the primary draenei research facility for the study of naaru " ..
                "crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the " ..
                "crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this " ..
                "region carries with it some residual powder of the Oshu'gun crystals. If you find any " ..
                "powder while adventuring in this region, return it to me and I shall reward you with a " ..
                "token of my appreciation which you may use to make purchases from the quartermaster.",
            rewardItems = {{26044, 1}},
            rewardMoney = 37000,
        },
        [10075] = {rewardItems = {{26044, 1}}, rewardMoney = 29000},
        [10076] = {
            description = "This base was the primary draenei research facility for the study of naaru " ..
                "crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the " ..
                "crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this " ..
                "region carries with it some residual powder of the Oshu'gun crystals. If you find any " ..
                "powder while adventuring in this region, return it to me and I shall reward you with a " ..
                "token of my appreciation which you may use to make purchases from the quartermaster.",
            rewardItems = {{26044, 1}},
            rewardMoney = 37000,
        },
        [10077] = {rewardItems = {{26044, 1}}, rewardMoney = 29000},
        [10078] = {
            description = "Now that we've gotten our salvage operation off the ground, it's time to begin " ..
                "the second phase of the plan.\n\nAcross the Path of Glory, the Horde still has their old " ..
                "blade throwers trained on us. Don't let their age fool you, <name>, they're still very " ..
                "dangerous. Much as we're working to reclaim what we can, we can't assume the Horde is " ..
                "going to dismantle their weaponry.\n\nTake this torch and burn the remaining siege " ..
                "equipment. I'll take no chances with Honor Hold's safety.",
            rewardChoices = {{29928, 1}, {29930, 1}, {29934, 1}, {29941, 1}},
            rewardMoney = 20000,
        },
        [10079] = {
            description = "The mine's been overrun by a plague of gan'arg misfits!\n\nNot only did they " ..
                "run all my workers out of the tunnels, but they're pounding away in there night and day! " ..
                "To make things worse, now I've got Danath on me back! He says he's going to take away me " ..
                "ale ration if I don't get this taken care of soon!\n\nNone of the miners'll go in there, " ..
                "and the guards are busy drinking themselves silly.\n\nI'm begging you, <name>, help me " ..
                "here. Danath can take me dignity, but he'll never take me ale!",
            rewardMoney = 20000,
        },
        [10081] = {
            description = "Do not be alarmed by what you might see once the effect has taken hold! These " ..
                "spirits are all around us - always. The potion allows your mind to be able to understand " ..
                "and ultimately see the spirits. You will need to be under its influence if you are to " ..
                "speak with Mother Kashur.\n\nYou will find her a great ways to the southwest, at the " ..
                "Ancestral Grounds.",
        },
        [10082] = {
            description = "Do you see them walking around us? The Ancestral Grounds are normally quiet " ..
                "and undisturbed.\n\nAs of late, the ancestral spirits have risen and are extremely " ..
                "agitated. Something is causing a great disturbance to the spirits. We must discover what " ..
                "that something could be, but first, we must put the immediate threat to rest.\n\nThese " ..
                "ghosts that you see walking about are not truly the ancestors but a representation of " ..
                "their state of being. You must destroy the agitated orc spirits. Do this and return to " ..
                "me.",
        },
        [10085] = {
            description = "I need for you to journey to the villages of the ancestors, <name>. Seek each " ..
                "one out and see if the ancestors remain.\n\nVisit Sunspring Post to the north, visit the " ..
                "Laughing Skull Ruins far to the north against the mountains, visit Garadar to the " ..
                "northeast, and finally, visit the Bleeding Hollow Ruins on the borders of Nagrand and " ..
                "the Terokkar Forest, to the east.\n\nReturn to me once you have observed the ancestors " ..
                "in their homes.",
        },
        [10086] = {
            description = "Would you believe it? These orcs hired me to help them shore up damaged " ..
                "fortifications and build explosives. What a dream job! It's too bad we're so short on " ..
                "materials, but a clever goblin like myself learns how to make do!\n\nCan you help me? I " ..
                "need salvaged wood and metal from the ruined battlements along the Path of Glory. Go " ..
                "down there and salvage, and watch out for those red-skinned orcs!\n\nWhen you're done, " ..
                "come back for big rewards!",
            rewardChoices = {{29931, 1}, {29938, 1}, {29943, 1}, {29945, 1}},
            rewardMoney = 20000,
        },
        [10087] = {
            description = "I'm a lucky, lucky goblin. I get to make explosives and killing machines, " ..
                "knowing they'll be used immediately on important missions!\n\nSpeaking of missions, I " ..
                "just got one from Thrallmar command: burn the Alliance cannons on the far side of the " ..
                "Path of Glory... the ones pointing dangerously close to Horde fortifications. Take this " ..
                "torch and make your way to each cannon. Fire the torch and watch the sparks fly!",
            rewardChoices = {{29928, 1}, {29930, 1}, {29934, 1}, {29941, 1}},
            rewardMoney = 20000,
        },
        [10093] = {
            description = "Fortunately, the Path of Glory is not the only trace of my people in these " ..
                "lands. To the west, a few of our holy sites survive, although some have been " ..
                "overrun.\n\nWhile Velen prepared for the journey that would lead him to Azeroth, those " ..
                "of us who would remain behind sought to reestablish a presence at our holy places.\n\nIn " ..
                "the western part of the Hellfire Peninsula, you will find a small group of draenei at " ..
                "the Temple of Telhamat, led by Amaan the Wise. I am certain he'd be interested in " ..
                "meeting you.",
        },
        [10096] = {
            description = "Ikeyen's been telling me stories about what happened to him down in those " ..
                "caves and I think it's just awful!\n\nYou know, maybe we should do something to help out " ..
                "those poor sporeloks. Ikeyen says that they live there in the Funggor Cavern, but that " ..
                "the marsh beasts have recently invaded.\n\nWhy don't you go down there and see if you " ..
                "can clear some of those marsh beasts out? It's just to the southwest.",
            rewardChoices = {{27715, 1}, {27717, 1}, {31657, 1}, {31658, 1}},
            rewardMoney = 27000,
        },
        [10099] = {
            description = "Those infernal gan'arg keep scurrying into the mine! For each one you kill, " ..
                "two or three more seem to take its place!\n\nThere's got to be someone down there in the " ..
                "deepest reaches of the mine directing the incursion. You seemed to do well against them " ..
                "last time, and Light knows you're the only one brave enough to venture back into the " ..
                "mine. Find out who's responsible for this disturbance and make him pay!",
            rewardChoices = {{25982, 1}, {25983, 1}, {25984, 1}},
            rewardMoney = 20000,
        },
        [10101] = {
            description = "Oshu'gun - the diamond mountain - was once sacred to my people. It was there " ..
                "that the clans would gather every year to celebrate the springtime festival. It was " ..
                "there that our shaman communed with the honored ancestors. It was the center of our " ..
                "culture - until the shadows overtook us. When the clans became a horde, the spirits of " ..
                "Oshu'gun fell silent. The ancestors turned their backs on us.\n\nYet something now draws " ..
                "them from their rest. Venture to Oshu'gun and discover what could trouble the spirits so.",
        },
        [10102] = {
            description = "As my energies bled away over the centuries, a void slowly grew in my place - " ..
                "devouring the souls of those nearby. Helplessly, I watched as generations of orc souls " ..
                "were drawn into the vortex. Recently, my enemies harnessed the vortex and used it to " ..
                "draw countless void minions into their Burning Legion.\n\nNow, the key to ending this " ..
                "cycle and freeing the orc spirits lies with another naaru - A'dal. I have sensed his " ..
                "essence within the ancient city of Shattrath in the Terokkar Forest.",
        },
        [10103] = {
            description = "With the arrival of Field Commander Romus and his forces, the Alliance and " ..
                "their draenei friends have grown bold. They're militarizing every old draenei ruin from " ..
                "here to Shattrath.\n\nIn response, the trolls have established a new outpost in the " ..
                "eastern part of Zangarmarsh, just south of the Dead Mire. Swamprat Post, they're calling " ..
                "it. I'm glad they have a sense of humor about living in a place like that, because I " ..
                "wouldn't relish it.\n\nThe post's commander has asked me to send anyone I can spare.",
        },
        [10104] = {
            description = "The rumors from Tuurem are unsettling. Some say the town's ruins are overrun " ..
                "with crazed Broken and Lost Ones, while opportunistic artifact hunters steal draenei " ..
                "relics.\n\nIt's hard to know which are true and which aren't, but we have a " ..
                "responsibility to safeguard the ruins as best we can. Find Andarl at the Allerian " ..
                "Stronghold in Terokkar Forest. He is something of a student of magical relics. More than " ..
                "anyone else, he's likely to know what's going on there.",
        },
        [10105] = {
            description = "Now that Swamprat Post is complete, our control of the roads in and out of the " ..
                "marsh is much less tenuous. Our presence in Terokkar Forest is much less secure. Even " ..
                "so, at Stonebreaker Hold, Rakoria awaits word of our progress.\n\nShe's sharp and " ..
                "capable, <name>, but be careful around her. She's got a lot of goods she's eager to move " ..
                "along the roads, but don't assume she's got our best interests at heart. Rakoria goes " ..
                "where she believes there's profit to be found.",
        },
        [10106] = {
            description = "The Hellfire Citadel wages constant battles with our forces. We are holding " ..
                "our own so far, but we can't yet launch a real offensive against them. To do that, we " ..
                "need forward staging areas.\n\nOur scouts identified three fortifications near Hellfire " ..
                "Citadel. We want you to help secure these forts. Capture each fort, and then report back " ..
                "to me.\n\nMay fortune shine upon you in the conflicts ahead, <name>, for you will no " ..
                "doubt clash with Horde forces eager to gain these same fortifications.",
            rewardItems = {{24579, 3}},
            rewardMoney = 77000,
        },
        [10107] = {
            description = "Kilrath sends news of the Boulderfist leader: He is an orc! An ancient orc " ..
                "that passed through the Dark Portal in the time of our fathers and has since returned to " ..
                "his homeland. I wish for you to track down this orc and try to convince him to pull back " ..
                "the Boulderfist ogres. He resides on an upper platform in the Burning Blade Ruins to the " ..
                "southeast near the border of Terokkar. Good luck, <name>!\n\nBe warned, he is a " ..
                "blademaster...",
        },
        [10108] = {
            description = "The huntress's agents send news of the Boulderfist leader: He is an orc! An " ..
                "ancient orc that passed through the Dark Portal in the time of our fathers and has since " ..
                "returned to his homeland. I wish for you to track down this orc and try to convince him " ..
                "to pull back the Boulderfist ogres. He resides on an upper platform in the Burning Blade " ..
                "Ruins to the east. Good luck, <name>!\n\nBe warned, he is a blademaster...",
        },
        [10109] = {
            description = "Do you see them?? By Gazlowe's horrific halitosis, I will have those eggs! " ..
                "Say, you look like you might be of some use.\n\nI'll tell you what, <race>; if you " ..
                "gather a few items for me to make my Jump-a-tron 4000 functional, I'll give you a key " ..
                "that will let you operate the machine as well! What can you do with a Jump-a-tron 4000 " ..
                "you say? What can't you do is more like it...\n\nI'll need air elemental gas from the " ..
                "air elementals of Nagrand. They're all over the place so don't ask me where to find 'em!",
            rewardItems = {{27808, 1}},
            rewardMoney = 35000,
        },
        [10110] = {
            description = "The fel orcs of Hellfire Citadel must be scoured from our birthland! To attack " ..
                "them, we must first secure forward staging points near the Citadel.\n\nOur outrunners " ..
                "found three fortifications that will suit this purpose, but the Alliance has the same " ..
                "idea and even now sends forces to take them!\n\nWe want you to stop the Alliance and " ..
                "capture these forts. Aid in the capture of each fort and then return to me.\n\nFor the " ..
                "Horde!",
            rewardItems = {{24581, 3}},
            rewardMoney = 27000,
        },
        [10111] = {
            description = "Now that you've been initiated, I want you to get me that egg! Use the " ..
                "Jump-a-tron and try to hit the nest dead center. But be careful! Bodily injury or " ..
                "serious permanent damage may occur from a bad jump.",
            rewardChoices = {{28030, 1}, {28031, 1}, {28032, 1}},
            rewardMoney = 70000,
        },
        [10112] = {
            description = "Hmmm? A box you say? Or was it several? Do you know what material the box was " ..
                "constructed from?\n\nAnd what was the name of this merchant? Empoor? Are you certain " ..
                "that he's one of the Broken? I don't do much business with their kind.\n\nPerhaps my " ..
                "memory would be jogged if you were to do me a favor?\n\nThe Skithian arakkoa - primitive " ..
                "casters that they are - recently stole a huge shipment of my more exotic goods. I want " ..
                "it all back!\n\nYou can find Veil Skith just to the south of Shattrath City.",
            rewardChoices = {{25927, 1}, {31724, 1}, {25926, 1}, {25928, 1}},
            rewardMoney = 31000,
        },
        [10113] = {
            description = "\"Go out and find us some supplies,\" he said. I was nearly killed about 15 " ..
                "times before I found this place! These Broken might not be the most hospitable bunch but " ..
                "at least they're not trying to tear my skin from my bones.\n\nAnyway, I'm not going " ..
                "back. My days of huntin' big game are over. If you end up heading northeast towards " ..
                "Zangarmarsh and run into the Nesingwary Safari, let them know that \"Shotgun\" " ..
                "quit.\n\nHey, maybe you can take my place! Good luck, stranger.",
        },
        [10114] = {
            description = "These orcs have never seen a tauren before - if you can believe such a thing. " ..
                "If it weren't for Captain Kroghan, they would have probably been serving me for their " ..
                "next meal right about now.\n\nBut where are my manners? I am Ohlorn Farstrider, hunter " ..
                "extraordinaire! I am part of the Nesingwary expedition that came up here from Azeroth in " ..
                "search of big game. If you are interested in the hunt, perhaps you should visit my crew " ..
                "at the Nesingwary Safari, due east of here near the border of Zangarmarsh.",
        },
        [10115] = {
            description = "The Kurenai and the draenei don't always see eye to eye, particularly on the " ..
                "issue of the Lost Ones. We are content to help the Lost Ones who seek us out, but we " ..
                "won't pursue them. Some draenei are intent on 'redeeming' them all.\n\nHowever, there " ..
                "are times when even the Lost Ones go too far, such as the Daggerfen. In their village to " ..
                "the west, they dabble in poisons and deceit, arts that come unnaturally to us.\n\nWe " ..
                "must put an end to this before the vile Daggerfen can extend their influence.",
            rewardMoney = 31000,
        },
        [10116] = {
            description = "Wanted: Chieftain Mummaki - leader of the foul and degenerate Lost One tribe " ..
                "of the Daggerfen, for his brutal attacks against the Orebor Harborage.\n\nThe chieftain " ..
                "and his band of assassins are responsible for the deaths of numerous Kurenai and draenei " ..
                "and should only be approached by seasoned combatants.\n\nTravelers are advised to avoid " ..
                "the Daggerfen Village area to the west of the Orebor Harborage.\n\nTo claim the bounty, " ..
                "present proof of the chieftain's demise to Ikuti.",
            rewardMoney = 62000,
        },
        [10117] = {
            description = "Wanted: Chieftain Mummaki - leader of the foul and degenerate Lost One tribe " ..
                "of the Daggerfen, for his brutal attacks against Zabra'jin and its inhabitants.\n\nThe " ..
                "chieftain and his band of assassins are responsible for the deaths of numerous scouts " ..
                "and messengers and should only be approached by seasoned combatants.\n\nTravelers are " ..
                "advised to avoid the Daggerfen Village area to the northwest of Zabra'jin.\n\nTo claim " ..
                "the bounty, present proof of the chieftain's demise to Shadow Hunter Denjai.",
            rewardMoney = 62000,
        },
        [10118] = {
            description = "Of all the Lost One tribes in Zangarmarsh, the Daggerfen are the most cunning " ..
                "and most aggressive. They are highly organized and make no secret of the fact that they " ..
                "desire control over the other Lost Ones in the marsh.\n\nTheir attacks have already " ..
                "taken quite a toll on my scouts and messengers. I cannot afford to lose any more " ..
                "men.\n\nIf we don't act soon, they'll have complete control over the roads and Zabra'jin " ..
                "will effectively be surrounded.",
            rewardMoney = 31000,
        },
        [10119] = {
            description = "For 20 years the Dark Portal has remained a silent monument - a eulogy to a " ..
                "time long since forgotten.\n\n<Relthorn looks around.>\n\nI never thought to see this " ..
                "day, yet here we stand, looking into the abyss.\n\nOn the other side of this gate we are " ..
                "locked in a savage war - a war that we cannot win without support. You must go through " ..
                "the Dark Portal and help our troops, <class>.\n\nReport to Commander Duron at once. He " ..
                "awaits you in Outland...",
        },
        [10120] = {
            description = "Aided by the Alliance, my forces will hold the line here, but I need you to " ..
                "deliver my report to General Krakork in Thrallmar. With his help, we'll be able to drive " ..
                "these demons back into the abyss that spawned them! Speak to Vlagga Freyfeather who " ..
                "stands on the platform behind us. She'll speed you on your way.",
        },
        [10121] = {
            description = "Though this land is full of strange new enemies, the Burning Legion is still " ..
                "the greatest threat to our Expedition. One of my most trusted warriors, Sergeant " ..
                "Shatterskull, has been studying the Legion's tactics - trying to discern the demons' " ..
                "true purpose in this land. Seek him out at the supply caravan just outside the southern " ..
                "wall.\n\nAnd <name> - be wary of the Legion. Their evil cannot be underestimated.",
        },
        [10123] = {
            description = "Doom Lord Kazzak commands the Burning Legion in Outland. While we can't get to " ..
                "Kazzak - yet - we can and must get to his lieutenants that command Legion troops from " ..
                "the ground.\n\nThey have stationed dreadlords in Felspark Ravine, east of here. They are " ..
                "responsible for these infernal storms that rain down upon our heads. To take them and " ..
                "their minions out would be a great set back to the Burning Legion.",
            rewardChoices = {{29908, 1}, {29909, 1}, {29910, 1}, {29911, 1}, {29913, 1}},
        },
        [10124] = {
            description = "Your battle prowess has been noted by high command, <class>. They want to send " ..
                "you to the front lines to meet up with Maimfist's crew. They're radicals, devoted to the " ..
                "complete extermination of the Burning Legion, so you may fit right in...\n\nHead east " ..
                "about 200 paces and veer south at the jutting mass of land. You'll see Reaver's Fall " ..
                "where an old farm used to stand. Once there, you are to report to Forward Commander " ..
                "To'arch.\n\nNow move out!",
        },
        [10129] = {
            description = "We've identified the two main transporters that the Burning Legion are using " ..
                "to bring in reinforcements: Gateway Murketh and Gateway Shaadraz.\n\nIf you look east up " ..
                "the Path of Glory, you'll see them on either side of the road. I want you to bomb them " ..
                "both into oblivion!\n\nHere are the bombs you'll use, specially designed by a goblin in " ..
                "Area 52. Now, speak with Wing Commander Brack -- he'll put you on a wyvern.",
            rewardChoices = {{29929, 1}, {29937, 1}, {29942, 1}, {29944, 1}},
        },
        [10132] = {
            description = "You see that huge red crystal to the north? It fell from the sky not long ago, " ..
                "causing a massive earthquake.\n\nWhen we came out here to investigate the disturbance, " ..
                "we found all of these colossi wandering about that weren't previously here.\n\nThere's " ..
                "definitely something strange about that crystal and the energies that it's emanating, " ..
                "but I don't have time for that. Those mountain giants are my immediate concern.\n\nI " ..
                "want you to head up to Fallen Sky Ridge and deal with them.",
            rewardChoices = {{28062, 1}, {28063, 1}},
            rewardMoney = 58000,
        },
        [10134] = {
            description = "As the colossus falls under the weight of your attacks, you notice for the " ..
                "first time that it was holding a red crystal fragment.\n\nWhile it was small and " ..
                "unnoticeable in the mountain giant's hand, it's a fairly hefty piece for you to carry " ..
                "around. It also suspiciously looks like it's a piece of the giant crystal in the middle " ..
                "of the ridge.\n\nIt's most definitely a clue as to the strangeness that is occurring " ..
                "here, and you're sure that the druids at the Cenarion Post to the south will want to see " ..
                "it.",
            rewardMoney = 15000,
        },
        [10136] = {
            description = "Magister Bloodhawk finally deciphered the Legion missive you found earlier. It " ..
                "turned out to be attack plans sent by one of Highlord Kazzak's lieutenants - Arazzius " ..
                "the Cruel. Apparently, Arazzius commands the Legion ground forces in Hellfire. The time " ..
                "has come to terminate his command, <name>. Terminate with extreme prejudice.\n\nHead " ..
                "west to the Pools of Aggonar and put an end to this so-called 'Legion lord'. Today, the " ..
                "Horde reclaims Hellfire Peninsula. Let the Legion be damned.",
            rewardChoices = {{28040, 1}, {28041, 1}, {28042, 1}},
            rewardMoney = 87000,
        },
        [10140] = {
            description = "When you're ready, I'll arrange a flight straight to Honor Hold.\n\nFrom " ..
                "there, speak with Marshal Isildor and give him Duron's report. He'll be happy to see " ..
                "another recruit from the homelands, and I'm sure the information in that report is " ..
                "important stuff!",
        },
        [10141] = {
            description = "While the Burning Legion invaded Azeroth, they were also at work here, in " ..
                "Outland. We have tracked their movements over the years, but this latest activity, " ..
                "<class> - well, this is beyond anything we've seen.\n\nSeek out Sergeant Altumus near " ..
                "the eastern supply caravan. She has been monitoring the invaders and may have insights " ..
                "into their purpose.\n\nBe swift - and take care, <name> - the Burning Legion is not to " ..
                "be underestimated.",
        },
        [10142] = {
            description = "Doom Lord Kazzak commands the Burning Legion in Outland. While we can't get to " ..
                "Kazzak - yet - we can and must get to his lieutenants that command Legion troops from " ..
                "the ground.\n\nThey have stationed dreadlords at the Path of Anguish, east of here. They " ..
                "are the ones responsible for these infernal storms that rain down upon our heads. To " ..
                "take them and their minions out would be a great set back to the Burning Legion.",
            rewardChoices = {{29908, 1}, {29909, 1}, {29910, 1}, {29911, 1}, {29913, 1}},
        },
        [10143] = {
            description = "Your battle prowess has been noted by high command, <class>. They want to send " ..
                "you to the front lines to meet up with Rohamus's crew. They're radicals, devoted to the " ..
                "complete extermination of the Burning Legion, so you may fit right in...\n\nHead east " ..
                "about 400 paces, across the Valley of Bones, until you run into a destroyed fel reaver. " ..
                "You'll see Expedition Point where a Legion base used to stand. Once there, you are to " ..
                "report to Forward Commander Kingston.\n\nNow move out!",
        },
        [10144] = {
            description = "You'll find the Legion front to our northeast, and spaced along it are portals " ..
                "used to gather reinforcements from throughout Outland. We, <name>, are going to destroy " ..
                "those portals!\n\nTake this primer. Designed in Area 52, it uses the demons' own power " ..
                "as an explosive device! Defeat Legion forces around Portals Grimh and Kaalez to gather " ..
                "demonic rune stones, use the primer to detonate the stones inside the portals... then " ..
                "watch the fireworks!!\n\nGo, <name>, and return to me when your mission is complete.",
            rewardChoices = {{29927, 1}, {29932, 1}, {29935, 1}, {29939, 1}, {29946, 1}},
        },
        [10146] = {
            description = "Just west of the Dark Portal are two huge transporters: Gateway Murketh and " ..
                "Gateway Shaadraz.\n\nIf you look east up the Path of Glory, you'll see them on either " ..
                "side of the road. I want you to bomb them both into rubble!\n\nHere are the bombs you'll " ..
                "use, specially designed by a goblin in Area 52. Now, speak with Wing Commander Dabir'ee " ..
                "-- he'll put you on a gryphon and send you on your way.",
            rewardChoices = {{29929, 1}, {29937, 1}, {29942, 1}, {29944, 1}},
        },
        [10159] = {
            description = "We've been fighting an ongoing battle to keep the pass through Thornfang Hill " ..
                "to the west clear of ravagers. It would be bad if we were to become completely cut off " ..
                "from the refuge in Zangarmarsh.\n\nWe don't want to displace the creatures, but there " ..
                "seems to be little choice as their attacks on travelers through the area have become " ..
                "more aggressive.\n\nClear some of the ravagers out of there if you can.",
            rewardMoney = 29000,
        },
        [10160] = {
            description = "Rumors have surfaced that some new breed of orc is on the rise. Larger, meaner " ..
                "- more cunning than the brutes we're familiar with. If these rumors are true then our " ..
                "forces, already stretched, may be taxed beyond their limit.\n\nI have entrusted my " ..
                "lieutenant, Amadi, with investigating this matter. If you would help us in this dark " ..
                "hour, seek her out. She is stationed at the broken tower just west of the Hold.\n\nAnd " ..
                "<name> - be careful out there. You're heading into a dangerous new world.",
        },
        [10161] = {
            description = "In the event of an emergency, it's always the pilot's job to keep a level " ..
                "head, especially when the only orders your co-pilot follows come from his " ..
                "stomach.\n\nThe good news is that we won't need to wait days for replacement parts to be " ..
                "imported. The bad news is that the \"spare\" parts got scattered from here to the Valley " ..
                "of Bones to the east.\n\nThe other bad news? The spare parts aren't so spare. They, uh, " ..
                "fell off during our rapid descent. Could you help me collect enough to get us off the " ..
                "ground again?",
            rewardChoices = {{25979, 1}, {25980, 1}, {25981, 1}},
            rewardMoney = 20000,
        },
        [10162] = {
            description = "Now that you've got your wings, perhaps you'd be interested in running another " ..
                "bombing mission?\n\nThis time we've isolated the Legion's main production area, behind " ..
                "the forge camps to the north. I need you to get on a wyvern and destroy the whole damned " ..
                "thing!\n\nHere are your bombs - now, talk to Wing Commander Brack when you're ready for " ..
                "takeoff.",
            rewardChoices = {{29926, 1}, {29933, 1}, {29936, 1}, {29940, 1}},
        },
        [10163] = {
            description = "Now that you've got your wings, perhaps you'd be interested in running another " ..
                "bombing mission?\n\nThis time we've isolated the Legion's main production area, behind " ..
                "the forge camps to the north. I need you to get on a gryphon and destroy the whole " ..
                "damned thing!\n\nHere are your bombs - now, talk to Gryphoneer Windbellow when you're " ..
                "ready for takeoff.",
            rewardChoices = {{29926, 1}, {29933, 1}, {29936, 1}, {29940, 1}},
        },
        [10166] = {
            description = "This pendant brings back memories of a different time. A better " ..
                "time.\n\nUnfortunately, memories are the last thing I need right now.\n\nI want you to " ..
                "bury this by the runestone in the Scorched Grove. It was there that I first met the " ..
                "treant elder. Put my old friend's memory to rest.",
        },
        [10167] = {
            description = "Deep within the Auchenai Crypts is a tomb: A tomb unlike any that exists on " ..
                "this shattered realm. It was from this tomb, the first tomb, that the vast mausoleum of " ..
                "Auchindoun was born.\n\nYou must venture to the Auchenai Crypts of Auchindoun and find " ..
                "this tomb. Slay the guardian of the crypt to release the captive spirit within. The " ..
                "spirit holds the key...",
        },
        [10168] = {
            description = "For several centuries, the spirits of Auchindoun coalesced into my darkened " ..
                "essence. Many of the catastrophes that befell this crypt were a direct result of my " ..
                "weakened state.\n\nRegrettably, there is nothing that can be done to stop this cycle. It " ..
                "is a facet of the naaru condition - without the void, the Light cannot exist.\n\nYour " ..
                "only recourse is to destroy the ancient spirits of Nagrand before they transform into " ..
                "creatures of the void. Use the soul mirrors found throughout this crypt to free them...",
        },
        [10170] = {
            description = "Return to Greatmother Geyah at Garadar with news of your victory, <name>. This " ..
                "will surely lift the spirits of the Mag'har. Perhaps even the young Hellscream will be " ..
                "lifted from his malaise.",
        },
        [10171] = {
            description = "You have done so much for the Mag'har, <name>. Your accomplishments are known " ..
                "to all, including Garrosh. Go to him now and tell him of your latest victory. Tell him " ..
                "that you do what you do for him and his people. Surely he will be lifted by your words.",
        },
        [10172] = {
            description = "You are an honorable <race>, <name>. You have done much for the Mag'har. No " ..
                "one could ever deny your service to my people. Alas, the time of the Mag'har is at an " ..
                "end. You have shown me, more than anything, that I am unfit to lead these people. My " ..
                "cursed blood runs too deep. I will not... I cannot become the second Hellscream to damn " ..
                "the orcs.\n\nPlease, <name>, return to the Greatmother and tell her what I have told " ..
                "you. I am too ashamed to see her... to look into her eyes.",
            rewardChoices = {{28169, 1}, {28172, 1}, {28173, 1}, {28175, 1}},
            rewardItems = {{28168, 1}},
        },
        [10173] = {
            description = "Allow me to introduce myself, <class>.\n\nI am Ravandwyr, apprentice to the " ..
                "Archmage Vargoth.\n\nMy master is... indisposed, shall we say. I am here on a matter of " ..
                "great importance.\n\nThe Arklon Ruins southeast of the city are a hotbed of Burning " ..
                "Legion activity. Their purpose in the ruins concerns neither me nor my master, but their " ..
                "leader, Ekkorash, possesses the archmage's staff.\n\nThis conjuring powder will allow " ..
                "you to draw the demon out of hiding. Sprinkle it on the brazier at the center of the " ..
                "ruins.",
            rewardMoney = 39000,
        },
        [10174] = {
            description = "Now, you will be able to use the archmage's staff to contact him.\n\nHe " ..
                "resides in the Violet Tower, on an 'island' to the southeast. The tower is both " ..
                "sanctuary and prison to him, cursed as it is. Kirin Tor can neither enter nor leave, " ..
                "keeping me apart from my master.\n\nThe staff's magic can penetrate the tower's " ..
                "defenses, but only if invoked by one outside the Kirin Tor.\n\nTake the archmage's staff " ..
                "and use it to conjure his image. Tell him what has happened and that I have not " ..
                "completely failed him.",
        },
        [10176] = {
            description = "Now that you've gathered all the items I'll need to break Kael'thas's curse, " ..
                "one thing remains to be done. When Kael'thas sealed the tower, he placed an arcane " ..
                "golem, known as Ar'kelos, at the bottom of the tower.\n\nYou must defeat Ar'kelos in " ..
                "order allow me to work magic within the tower again.\n\nWhen you enter the Violet Tower, " ..
                "the curse will begin to affect you.\n\nOnce you have defeated Ar'kelos, ascend the tower " ..
                "and assist me in making preparations for the ritual.",
            rewardChoices = {{29777, 1}, {29779, 1}, {29775, 1}, {29776, 1}},
            rewardMoney = 39000,
        },
        [10180] = {
            description = "I tried to persuade Isfar to remain here, in the safety of Shattrath, but he " ..
                "would have none of it. Instead, he's decided to venture out to Auchindoun again on his " ..
                "own.\n\nHe was lucky enough to escape the Sethekk Halls once, but if they discover him, " ..
                "there won't be a second time.\n\nI admire his desire to free his sister, but he's not " ..
                "going to be able to do it without help.\n\nFind Isfar and have a word with him, <name>. " ..
                "If you can't persuade him to come back, perhaps you could help him rescue Lakka?",
        },
        [10182] = {
            description = "The sword is of exceptional quality, finely crafted and perfectly balanced for " ..
                "a battle-mage. The seal of the Kirin Tor and the name \"Dathric\" are engraved into the " ..
                "weapon's pommel.\n\nTurning the weapon over in your hands, you notice a sense of " ..
                "wrongness radiating from the metal, as if the item is torn between two worlds. Could " ..
                "this be the item anchoring Battle-Mage Dathric's spirit to this world?\n\nPerhaps " ..
                "returning it to its proper place can break the bond, freeing Dathric's spirit to rest at " ..
                "last.",
        },
        [10183] = {
            description = "I'm out here studying the nether - the ethereal currents and all that. This is " ..
                "an ideal spot away from the lights and hubbub of town. Isn't this bridge great? If I " ..
                "could just keep this junk working.\n\nHey, you know, if you're looking for work there's " ..
                "plenty at Area 52! It's just up the path and take a right at the fork in the " ..
                "road.\n\nWhy don't you deliver my latest research notes to Rocket-Chief Fuselage? I'm " ..
                "sure that he'd have plenty for you to do, what with the X-52 rocket ship, and all!",
            rewardMoney = 10000,
        },
        [10184] = {
            description = "Most of the spirits in the village are little more than pale remnants of Kirin " ..
                "Tor mages. They retain no knowledge of their former selves and wander the ruins in blind " ..
                "anger.\n\nIt wasn't always like this, though. In the immediate aftermath of the attack, " ..
                "the spirits were restless, but not spiteful. With the passage of time they have only " ..
                "grown more aggressive. I dare not venture into the southern part of the village, for " ..
                "they will not spare even me. Quiet them and let us hope it will purge their anger.",
            rewardMoney = 39000,
        },
        [10185] = {
            description = "After the blood elves leveled Kirin'Var Village, they started the construction " ..
                "of a large building to the northwest. Without the expertise of the archmage, we can't " ..
                "say for certain what's going on there.\n\nOne thing is clear, though. The blood elf " ..
                "activities have unleashed a tide of ravenous mana elementals on the village. They seem " ..
                "drawn to the ruins of Wizard Row, wreaking further destruction. We cannot permit this to " ..
                "continue.",
            rewardChoices = {{29954, 1}, {29955, 1}, {29959, 1}, {30401, 1}},
            rewardMoney = 39000,
        },
        [10186] = {
            description = "Let me be the first to welcome you aboard, Junior Technician 3rd Grade " ..
                "<name>!\n\nWe're building my masterpiece out here - the X-52 Nether-Rocket!\n\nBut first " ..
                "we need to get all of the parts and fuel for it. That's where you come in.\n\nTo start, " ..
                "I need crystals - LOTS of crystals - for the rocket's Etherlithium Engine Matrix. The " ..
                "draenei had crystals coming out of their ears!\n\nSo head north to the Ruins of Enkaat " ..
                "and get them for me! Nevermind all of the draenei ghosts.",
            rewardChoices = {{30218, 1}, {30224, 1}, {30225, 1}, {30515, 1}},
            rewardMoney = 39000,
        },
        [10188] = {
            description = "Before we departed Azeroth all those years ago, the Kirin Tor entrusted our " ..
                "expedition with a powerful artifact, the Sigil of Krasus. It was a great boon to us in " ..
                "our battle against the orcs and it could play a key role in helping me break the " ..
                "enchantment that imprisons me.\n\nHowever, when Kael'thas divested me of my possessions, " ..
                "he gave the sigil to Spellbinder Maryana, who remained behind with the garrison. If he " ..
                "truly realized what he had in his possession, he wouldn't have given it away so easily.",
            rewardChoices = {{29771, 1}, {29772, 1}, {29773, 1}, {29774, 1}},
            rewardMoney = 41000,
        },
        [10189] = {
            description = "You may have noticed one of Kael's manaforges on your way here. You know, the " ..
                "large purple buildings sucking energy from the sky?\n\nWe were sent here by the Sha'tar " ..
                "to investigate them. You can help our information gathering efforts by obtaining a " ..
                "personnel roster. Giving us an idea of who's there and what they do will prove to be " ..
                "invaluable information.\n\nWe believe Captain Arathyn, leading a ballista team just " ..
                "outside of Manaforge B'naar, is in possession of one such roster. Obtain it for us.",
            rewardMoney = 39000,
        },
        [10190] = {
            description = "I have the very important task of collecting the machinery inside these ruins, " ..
                "but I'm having a problem keeping all of my bots charged up.\n\nThe phase hunters - those " ..
                "wyrm-looking things - have lots of energy! You can find them all over the edges of this " ..
                "island, floating in from the nether.\n\nFill the battery on this recharging blaster by " ..
                "using it on a phase hunter when they're very weak, and then finish it off to soak up the " ..
                "last of its energy.",
            rewardMoney = 39000,
        },
        [10191] = {
            description = "Greetings, <race>. I am charged up and fully functional.\n\nThere are fragile " ..
                "draenei machines in these ruins, which I must retrieve. I am equipped with delicate " ..
                "servos in my wrist actuators, and the latest in combustion-pneumatic bump soakers. " ..
                "Handling them with care will not be an issue.\n\nHowever, the ghosts that haunt these " ..
                "ruins will likely attack, so I will need you and your friends along for protection.",
            rewardChoices = {{30226, 1}, {30252, 1}},
            rewardMoney = 78000,
        },
        [10192] = {
            description = "The Kirin Tor sent one other of Krasus's possessions with our expedition. It " ..
                "was his spellbook, called Krasus's Compendium. Containing all the spells he mastered, it " ..
                "lent us a much-needed advantage in the war.\n\nBefore Kael'thas and his forces laid " ..
                "siege to Kirin'Var, the compendium had been stolen from me by a rebellious apprentice " ..
                "intent on studying necromancy. The apprentice and his followers divided and studied the " ..
                "text in secret, locking themselves inside their houses in the southern part of town.",
            rewardMoney = 41000,
        },
        [10193] = {
            description = "Based on the roster information, we know that the brains of the manaforge " ..
                "operations are the warp-masters and warp-engineers. It is they who oversee the retrieval " ..
                "of a so called \"warp-energy\" by the manaforge and its delivery to a remote destination " ..
                "via a system of underground pipes.\n\nThe only other specialists in the area are " ..
                "geologists. Everyone else is either part of the military or a magister crony; both " ..
                "easily replaced.\n\nGet in there and kill Kael's specialists; that's what'll hurt him " ..
                "the most.",
            rewardMoney = 39000,
        },
        [10194] = {
            description = "While you were gone, my men uncovered another one of these manaforges. It is " ..
                "east of here and is known as Manaforge Coruu.\n\nTwo of my best spies have arranged a " ..
                "secret landing spot outside of the manaforge. You are to help them infiltrate Kael's " ..
                "forces and obtain whatever information you can.\n\nSpeak to Veronia just outside the " ..
                "city walls; she's arranged for a windrider that will take you to Manaforge Coruu. Once " ..
                "there, speak to Caledis Brightdawn; he will brief you on your mission.",
        },
        [10197] = {
            description = "Infiltrating the ranks of Kael's army will not be an easy task. With my " ..
                "knowledge of illusionary magic I could pass you off as one of Kael's followers, but " ..
                "there are certain details in their uniforms I could not replicate.\n\nBring me a set of " ..
                "their robes, a pair of their gloves and a Sunfury guardsman medallion. This will make " ..
                "the results of my magic much more convincing.",
            rewardMoney = 39000,
        },
        [10198] = {
            description = "I've prepared a uniform with the pieces you obtained. It is magically enhanced " ..
                "to complete the illusion.\n\nWe spotted Commander Dawnforge going in to meet Arcanist " ..
                "Ardonis a few minutes ago. He had a full retinue of guards with him, so whatever they're " ..
                "discussing is bound to be incredibly important; see if you can catch any of it.\n\nOh, I " ..
                "almost forgot. You'll want to stay away from the arcane golems patrolling the manaforge. " ..
                "They will see right through the illusion.",
            rewardChoices = {{30383, 1}, {30384, 1}, {30386, 1}, {30397, 1}},
        },
        [10199] = {
            description = "So, I'm just missing the one ingredient that'll give my concoction that little " ..
                "extra kick that it needs.\n\nThe sting of the nether rays, roaming around near the " ..
                "shaleskin flayers, delivers quite a punch. Bring me some of their stingers and I'll " ..
                "extract the venom right out of them!\n\nI'm certain the results will be explosive!",
            rewardChoices = {{29999, 1}, {30000, 1}, {30001, 1}, {30002, 1}},
            rewardMoney = 39000,
        },
        [10200] = {
            description = "It would be best if this information got back to Thalodien as soon as " ..
                "possible. I'll stay here and cover our tracks.\n\nIt wouldn't do us much good to have " ..
                "Kael'thas find out what we were snooping around here. Secret information is always " ..
                "better if your enemy doesn't know you have it.",
        },
        [10201] = {
            description = "The oil is finally ready for its first test. It seems heavy enough to serve as " ..
                "a high quality weapon oil.\n\nThe only way to find out is to have a professional try it " ..
                "out. See Grek over there by the wanted posters? Sure, he's no poet, but the orc knows " ..
                "his way around a weapon!\n\nTake a sample of the oil to him and ask him to use it on his " ..
                "weapon. After he's had a chance to test it out, let me know what he thinks of it.",
            rewardChoices = {{20748, 1}, {20749, 1}},
        },
        [10202] = {
            description = "We've recently been contacted by a Sunfury magister who wishes to join our " ..
                "ranks and swears he has information we're in need of. We've checked our informants to " ..
                "make sure he's not a double agent and he checks out.\n\nHe's stationed in Manaforge Ara " ..
                "which makes communication difficult. Talk to him and see what he knows. If he's half as " ..
                "useful as he claims to be, we'll be able to put him to good use.",
        },
        [10203] = {
            description = "See the fissure running through Area 52? We did that! <grin>\n\nIt's yielding " ..
                "up all sorts of goodies for the X-52 Nether-Rocket, but we're running short on " ..
                "equipment.\n\nWe had an operation at the Arklon Ruins to the southeast until the Burning " ..
                "Legion moved in. I need you to take this Ultra Deconsolodation Zapper to the ruins. Use " ..
                "it to beam our gear back to Lead Sapper Blastfizzle down in the fissure.\n\nJunior " ..
                "Technician 3rd Grade <name>, this is your chance for that promotion. Don't blow it!",
            rewardMoney = 41000,
        },
        [10204] = {
            description = "Kael's magisters have refined their usage of mana crystals to the point where " ..
                "they can siphon large amounts of energy in a matter of seconds.\n\nThey do this by " ..
                "attuning smaller bloodgem crystal shards to larger, fully charged ones.\n\nGo to " ..
                "Manaforge B'naar and obtain one of these shards from a Sunfury magister and use it to " ..
                "siphon energy from one of the larger crystals.\n\nReturn to me so that I may study the " ..
                "effects of the aura. Do not worry; any side effects should be temporary.",
            rewardMoney = 39000,
        },
        [10205] = {
            description = "Warp-Raider Nesaad must be dealt with! I have no idea how he survived my " ..
                "attack, but he cannot be allowed to continue his operation out there.\n\nGo back and " ..
                "take out Nesaad. He keeps a small ethereal camp near the southwestern corner of the " ..
                "Heap.\n\nDon't fail like I did, <class>.",
            rewardChoices = {{30265, 1}, {30266, 1}, {30267, 1}},
            rewardMoney = 41000,
        },
        [10206] = {
            description = "Those ethereal clowns are as opportunistic as us, I'll give them that. But no " ..
                "one, and I mean NO ONE, moves in on a B.O.O.M. claim!\n\nThe Heap to the south is " ..
                "ours!\n\nIf we're to finish the X-52 Nether-Rocket, we're going to need all of the new " ..
                "tech that we can get our hands on. And since the ethereals are stealing from us, I think " ..
                "it's only fair that we repay them in kind.\n\nWhy don't you head down there and see if " ..
                "you can acquire some of their technology out from under their noses!",
            rewardChoices = {{30274, 1}, {30275, 1}, {30276, 1}},
            rewardMoney = 39000,
        },
        [10208] = {
            description = "Directly east of here is the Legion Front. Spaced across the front are " ..
                "infernal portals and gateways, used to bring reinforcements to Hellfire Peninsula and " ..
                "throughout Outland. We're going to destroy those portals!\n\nTake these primers. " ..
                "Designed in Area 52, they use the demons' own power as an explosive! Defeat Legion " ..
                "forces around Portals Xilus and Kruul to gather demonic rune stones, use the primer to " ..
                "detonate four stones inside the portals, and watch! Return to me when your mission is " ..
                "complete.",
            rewardChoices = {{29927, 1}, {29932, 1}, {29935, 1}, {29939, 1}, {29946, 1}},
            rewardMoney = 27000,
        },
        [10209] = {
            description = "The next thing we must do is reclaim my familiar, Glacius, from the blood elf " ..
                "summoner who holds it captive. Summoner Kanthin was one of the most senior magisters in " ..
                "the force Kael'thas sent to decimate Kirin'Var. It's only natural that he would claim my " ..
                "familiar as a kind of trophy.\n\nI'm certain that Kanthin, fool that he is, has tried to " ..
                "compel Glacius to serve him. My scrying has revealed that Kanthin is now stationed at " ..
                "'Manaforge Duro,' if that terminology has any meaning for you.",
            rewardMoney = 41000,
        },
        [10210] = {
            description = "Welcome to Shattrath City, <class>. This might be the one place in all of " ..
                "Outland where you'll find any semblance of safety.\n\nA group of naaru known as the " ..
                "Sha'tar drove the demons away from here.\n\nIf you've never met a naaru, you ought to " ..
                "see A'dal inside the Terrace of Light. The leader of the Sha'tar is an awe-inspiring " ..
                "sight if I ever saw one. Sure is a change of pace from anything else in this bleak land.",
        },
        [10211] = {
            description = "Do not burden A'dal with petty inquisitions, <class>. That just might be the " ..
                "most powerful being you ever come face to face with.\n\nYou do not look familiar. I " ..
                "suppose you want to learn about the city?\n\nYou'll have to excuse me if I don't give " ..
                "you a tour myself, but I'm a bit busy discussing strategy with A'dal. Perhaps you'll " ..
                "find a summoned servant acceptable in my stead? Excellent!",
        },
        [10213] = {
            description = "When I was wounded in the wastes I saw a goblin zeppelin crash. It went down " ..
                "to the northwest, beyond the Expedition Armory.\n\nThe zeppelin was on fire. Shrieking, " ..
                "burning goblins were falling like bombs from the sky. Of course I was in a lot of pain " ..
                "and I had lost a lot of blood. I may have imagined the whole thing.\n\nIf you can find " ..
                "any survivors, we can offer them sanctuary here at Spinebreaker Post.",
        },
        [10220] = {
            description = "I was sent here to make contact with the Unyielding spirits. These once proud " ..
                "Alliance soldiers were defeated long ago, and now their cursed spirits haunt the ruins " ..
                "to the west.\n\nIf they would only join us we would gain a powerful ally. Imagine, a " ..
                "legion of undying warriors to use against our enemies. But these undead are mad with " ..
                "hatred and will not listen to me.\n\nPerhaps they can be forced to join us.",
            rewardMoney = 20000,
        },
        [10221] = {
            description = "<name>, my former protege, Sparky Uberthruster, wouldn't wear his helmet while " ..
                "down here and one day transformed into the infamous Dr. Boom!\n\nAnd he stole off to the " ..
                "northeast with most of our sapping equipment! He and his Boom Bots have been a menace to " ..
                "Area 52 ever since.\n\nI need you to go to his Camp of Boom just outside of town and put " ..
                "an end to him! Use these Boom's Doom bombs to take him out.\n\nAnd make sure not to get " ..
                "too close to him or his Boom Bots!",
            rewardChoices = {{29967, 1}, {29968, 1}, {29969, 1}, {30514, 1}},
            rewardMoney = 39000,
        },
        [10222] = {
            description = "After Prince Kael'thas's forces destroyed the village and imprisoned the " ..
                "archmage in the Violet Tower, they withdrew to Sunfury Hold to the northeast. The very " ..
                "men who destroyed our village and slew our fellows toast their 'amazing victory' while " ..
                "we are helpless to avenge the fallen.\n\nWe must not allow these crimes to go " ..
                "unanswered! Be the instrument of our vengeance, <name>. Go to Sunfury Hold and claim the " ..
                "lives of those responsible for this crime.",
            rewardMoney = 41000,
        },
        [10223] = {
            description = "I'll never forget the blood elf who led the attack. He wore a tabard with a " ..
                "device I've never seen before, over top of crimson armor.\n\nHe was ferocious and " ..
                "merciless, leading from the front where most other blood elf officers would never be " ..
                "seen. He was responsible for the deaths of many Kirin Tor mages that day, but he didn't " ..
                "linger long at Sunfury Hold. Kael'thas has ordered him to Manaforge Duro to aid in their " ..
                "attempt to control the area. Find him, <name>, and silence his bow for good.",
            rewardChoices = {{29792, 1}, {30399, 1}, {29793, 1}, {29794, 1}},
            rewardMoney = 41000,
        },
        [10224] = {
            description = "As the X-52's chief of engineering, I have to see to it that the " ..
                "nether-rocket's main engines are in tip-top shape.\n\nUnfortunately, I haven't built " ..
                "them yet.\n\n<class>, I'm in dire straits here! I have almost all of the parts. All that " ..
                "I'm missing is the engine core.\n\nLuckily for us, I think we can make use of the " ..
                "essence from the local mana wraiths to jump-start the engines.\n\nThey can be found near " ..
                "most of the glowing trenches in the northern part of the island. Except for here in Area " ..
                "52, of course.",
            rewardMoney = 39000,
        },
        [10225] = {
            description = "<name>! I need you to take all of these etherlithium crystals over to Chief " ..
                "Engineer Trep, my, uh, chief of engineering.\n\nHe should know what to do with them. And " ..
                "if he doesn't, you see to it that he finds out!",
        },
        [10226] = {
            description = "Darn it, that didn't do it!\n\nOk, I've got another idea! I had Xyrol whip up " ..
                "an elemental power extractor. I'm not certain exactly what this power will do, but I " ..
                "know that I can use it.\n\nThe sundered rumblers and warp aberrations on the ledge of " ..
                "the Crumbling Wastes to the south have just what I need for the engines!\n\nThe " ..
                "extractor will change the form of their power into something solid that you'll be able " ..
                "to gather up after you've defeated them.",
            rewardChoices = {{30262, 1}, {30263, 1}, {30264, 1}, {30516, 1}},
            rewardMoney = 39000,
        },
        [10227] = {
            description = "I see dead draenei. They're all around us.\n\nBah, nobody believes me because " ..
                "I'm a child. Not even my own mommy believes me.\n\n< Ha'lei points to Ramdor.>\n\nHe " ..
                "believes me, though... He sees them too. Boy does he get angry about it!\n\nIt's kind of " ..
                "funny. I see ghosts and people just smile and pat me on the head, trying to placate me. " ..
                "Ramdor sees ghosts and people label him as crazy. I sure hope I never grow up!\n\nYou " ..
                "should probably talk to Ramdor before you go inside. He was once a death priest.",
        },
        [10228] = {
            description = "I believe that the dead, which we have been caring for these last 500 odd " ..
                "years, should be left alone. Maladaar has other plans. He has retreated to the Crypt of " ..
                "Remembrance to start his experiments... Necromancy.\n\nI hope you weren't thinking about " ..
                "going in there... Not before helping me out so that these damned spirits will finally " ..
                "leave me alone. I know where they keep their treasures, <race>. Got your attention, " ..
                "eh?\n\nBring me the book of the dead, held by the Aldor, Ezekiel of Shattrath.",
        },
        [10229] = {
            description = "This tome appears to be some sort of history written in a secret Alliance " ..
                "cipher. Althen, the historian in Spinebreaker Post, has studied the Unyielding for some " ..
                "time; he may be able to crack the Alliance code and decipher the book.",
        },
        [10230] = {
            description = "Perhaps we have taken the wrong approach to the Unyielding?\n\nThe tome tells " ..
                "me the Expedition Armory was destroyed by orcs and death knights long ago. The " ..
                "Unyielding remain here as vengeful spirits trapped in an eternal battle against the fel " ..
                "orc clans.\n\nThey think only of revenge. We must arrange for them to defeat their most " ..
                "hated enemies. Enter the Expedition Armory once again and find Lieutenant Commander " ..
                "Thalvos. He carries a battle horn that can summon the Unyielding. Bring it to me.",
        },
        [10231] = {
            description = "Ramdor? Hrm, let me think... Ramdor... Oh yes, the death priest. What does he " ..
                "want with the book? Well it doesn't matter. Yes I lied to you and no I don't have the " ..
                "book. Not anymore, anyway. It was stolen. Probably by one of those filthy " ..
                "refugees.\n\nBesides, Auchindoun is now defunct. We have no use for the book. If you " ..
                "find it, you can keep it.\n\nLike I said, I saw some of those ruffians snooping around " ..
                "the terrace last week. Start your search with them. They're probably playing dice in the " ..
                "slums.",
        },
        [10232] = {
            description = "The Burning Legion has moved in on our claim at the Scrap Field down the path " ..
                "and across the bridge to the east.\n\nThis could be a huge problem for us! With the " ..
                "Legion at the Arklon Ruins, and now there, it's starting to look bad for us - and the " ..
                "rocket project - here at Area 52.\n\n<name>, I need you to go out there and deal with " ..
                "those demons! I'd do it, but I'm a lover, not a fighter.\n\nYep, this is going to be " ..
                "trouble, I can feel it!",
            rewardMoney = 41000,
        },
        [10233] = {
            description = "Ridding Sunfury Hold of its garrison is not sufficient to keep the blood elves " ..
                "from reoccupying it. Kael'thas's followers are zealous and tenacious. Leaving them " ..
                "anything to use at Sunfury is effectively an invitation to return.\n\nNo, it must all be " ..
                "destroyed. See to it that their tents and artillery burn to ashes!\n\n<The ghost's fists " ..
                "clench.>\n\nSteal torches from the Sunfury flamekeepers to accomplish your task, <name>.",
            rewardMoney = 41000,
        },
        [10234] = {
            description = "You look like a capable young <man/woman>! I was wondering if you could lend " ..
                "me a hand?\n\nTo the east is the Scrap Field, which the Burning Legion has moved into. " ..
                "It's full of huge fel reaver parts. There're also a whole bunch of smaller parts in " ..
                "there that they don't seem to care about.\n\nI want you to get in there and get me a lot " ..
                "of those smaller fel reaver parts!",
            rewardMoney = 41000,
        },
        [10235] = {
            description = "You know what might just discourage them? Take out their leader!\n\nIt seems " ..
                "to work everywhere else from what I've heard. And when they see a <grizzled/tough> " ..
                "<class>, such as yourself take out their leader... why, I bet they'll tuck tail and run " ..
                "for the hills!\n\nGet back in there and take out the big one they call Doomclaw. I hear " ..
                "he keeps himself in the eastern part of the Scrap Field underneath the pipe.\n\nBring me " ..
                "his claw, too! Maybe we can make use of it.",
            rewardChoices = {{30277, 1}, {30278, 1}, {30279, 1}},
            rewardMoney = 41000,
        },
        [10236] = {
            description = "I can't believe I left Booty Bay to come to Outland. My cousin Screed Luckheed " ..
                "promised me I would make a fortune, but instead he flew off in his zeppelin and left me " ..
                "here to try to scrape a living out of this mine.\n\nHow am I suppose to make a living " ..
                "here with helboars and demons and fel orcs attacking all the time? My shredder here was " ..
                "broken yesterday and the parts I need to fix it were stolen by fel orcs. They took the " ..
                "parts into the fissure to the southwest and may have dropped them there.",
            rewardItems = {{23424, 5}},
            rewardMoney = 20000,
        },
        [10237] = {
            description = "<name>, you have to get word back to Area 52 immediately! Hurry!\n\nTell the " ..
                "rocket-chief that the Burning Legion is after us now!",
        },
        [10238] = {
            description = "Why would fel orcs steal my shredder parts? I hate them so much. They just " ..
                "sneak into my camp here and take things all the time. A couple of days ago they stole " ..
                "three of my peons! Now the rest of my peons have run off because they are afraid they " ..
                "are going to be eaten by fel orcs.\n\nI can't run a mine without peons. If you could " ..
                "save the peons that I lost maybe the others would come back. The fel orcs have their " ..
                "camps along the wall to the southwest.",
            rewardItems = {{30858, 5}},
            rewardMoney = 20000,
        },
        [10239] = {
            description = "We are not the only ones battling the influx of the mana beings. The blood " ..
                "elves, too, are troubled by them, but I'm not sure why.\n\nWhatever they're involved in " ..
                "over there, they don't seem to be stopping. Instead, I've seen them employ a variety of " ..
                "methods to kill the creatures. The most effective involves magical defenses fueled by " ..
                "some sort of concentrated energy.\n\nCapture some of these energy sources and bring them " ..
                "to me. Don't hesitate to stymie the elves if an opportunity presents itself.",
            rewardMoney = 41000,
        },
        [10240] = {
            description = "We are prepared to try to construct a perimeter around the village using the " ..
                "energy source taken from the blood elves. I can't guarantee that it will work, but we " ..
                "have to attempt it.\n\nOtherwise, the mana creatures will surely continue devouring the " ..
                "spirits of the fallen Kirin Tor.\n\nUse this device at the small runes around the " ..
                "perimeter of town to release the energy there. If I've woven the field correctly, we " ..
                "should start noticing a difference once you've used the device at each point.",
            rewardChoices = {{29784, 1}, {29785, 1}, {29786, 1}, {30398, 1}},
            rewardMoney = 41000,
        },
        [10241] = {
            description = "We were sent here by the Sha'tar to investigate the manaforges that Kael'thas' " ..
                "army is operating here. Unfortunately, the Scryers threaten to renege on their " ..
                "information-gathering duties unless we support them with military action.\n\nWe can't " ..
                "afford to compromise this mission over politics, so we've agreed to weaken the " ..
                "manaforge's defenses so that the Scryers can do their work.\n\nProve your loyalty to the " ..
                "Aldor and slay the Sunfury magisters and bloodwarders that guard Manaforge B'naar.",
            rewardMoney = 39000,
        },
        [10242] = {
            description = "<name>, my equipment here is, unfortunately, not configured for all the tests " ..
                "I'd like to perform. However, my colleague at Spinebreaker Post, Apothecary Albreck, " ..
                "possesses the required implements.\n\nI have acquired a sample of Bleeding Hollow blood " ..
                "-- gained from a past mission of Thrallmar's agents. Take the sample to Albreck and " ..
                "allow him to study it.\n\nTo reach Spinebreaker Post, speak with Wing Commander Brack, " ..
                "near the wyverns to the south.",
            rewardMoney = 2300,
        },
        [10243] = {
            description = "The Scryers obtained a personnel roster for Manaforge B'naar and are now " ..
                "having a field day picking out assassination targets.\n\nThey've missed one small bit of " ..
                "information, scribbled on the side of the roster. It appeared to be a password or code " ..
                "like those used to access naaru-made technology like the Exodar or Tempest Keep.\n\nGo " ..
                "inside the manaforge and look for a control panel. Copy its readouts on this scroll as " ..
                "well as you can. We must confirm our suspicions about the origin of the technology.",
        },
        [10245] = {
            description = "You try to transcribe the shapes as you see them flash across your eyes. The " ..
                "results are less than exact, but should serve as adequate evidence to prove or disprove " ..
                "the Aldor's suspicions.",
            rewardMoney = 39000,
        },
        [10246] = {
            description = "Your success at Manaforge B'naar was quite noteworthy. I'm sure that Anchorite " ..
                "Karja will ask you for a repeat performance at Manaforge Coruu next.\n\nWe've learned of " ..
                "a particularly important regiment of Sunfury arcanists and researchers being deployed " ..
                "there and I would like you to target them. Succeed and you will deliver a crushing blow " ..
                "against our enemy's forces.",
        },
        [10247] = {
            description = "On the outskirts of town to the east are the Proving Grounds. Our top " ..
                "experimentalist, Doctor Vomisa, has been toying with a combination of fel reaver, " ..
                "ethereal, and of course, goblin technologies there.\n\nThis is in no small part thanks " ..
                "to your gathering efforts Junior Technician 3rd Grade, <name>!\n\nGo to him; I know that " ..
                "he'll have a solution for saving Area 52.\n\nAnd since he's likely to use you as a test " ..
                "subject, if I were you, I'd bring some friends along just in case.",
        },
        [10248] = {
            description = "Doctor Vomisa, Ph.T. at your service. Here, take this controller. I want you " ..
                "to activate it and give my newly-invented Scrap Reaver X6000 a spin.\n\nJust stay " ..
                "nearby! The controller is tied to my console here, and if you get too far away, the " ..
                "robot will cease to function.\n\nTry out everything... I'll be watching and calibrating " ..
                "its servos based upon your test run.",
            rewardMoney = 41000,
        },
        [10249] = {
            description = "I'm certain that the rocket-chief is going to want to have a word or two with " ..
                "you!\n\nIf I were you, I wouldn't hesitate to get back to Area 52 and speak with him!",
            rewardChoices = {{30014, 1}, {30016, 1}, {30019, 1}},
            rewardItems = {{30847, 1}},
            rewardMoney = 123000,
        },
        [10250] = {
            description = "East of here is an old destroyed Alliance siege tower. Now scavengers loot it " ..
                "for old nails and bits of scrap. Long ago, many Alliance warriors lost their lives at " ..
                "this tower and their banner was captured by Urtrak, a foul orc commander.\n\nBlow the " ..
                "Unyielding battle horn near the Alliance banner. This will get the attention of Urtrak. " ..
                "It may also summon forth warriors who fell in battle long ago.",
        },
        [10251] = {
            description = "A couple of draenei paid us a visit last night. They'd somehow learned that we " ..
                "had the book in our possession and made a very generous offer to \"take it off our " ..
                "hands.\"\n\nWe didn't ask them what they wanted with the book but the young one kept " ..
                "talking about \"the master's grand design,\" whatever that means.\n\nLook, I don't ask " ..
                "questions when money is in play. They gave us a lot of gold and we gave them the " ..
                "book.\n\nHe said that they lived in Nagrand - in the old Abandoned Armory, north of " ..
                "Telaar.",
        },
        [10252] = {
            description = "It has already begun. Levixus stands atop the ruins of Auchindoun and reads " ..
                "from the book of the dead. He calls the dead out by name and, through demonic ritual, " ..
                "binds the tortured souls to his will. He will raise all of Auchindoun if given the " ..
                "chance!\n\nBut... you must first prepare. You cannot do battle with that which you " ..
                "cannot see.\n\n<Nitrin hands you a parchment.>\n\nBring me the items I require to brew " ..
                "the tincture. It will open your mind and allow you to see into the spirit world.",
        },
        [10254] = {
            description = "< Marshal Isildor spits in the dust.>\n\nWell, time to earn your pay. Report " ..
                "at once to Force Commander Trollbane within the keep. He and his advisors will no doubt " ..
                "be heartened to see you.\n\n< Marshal Isildor salutes you stoically.>\n\nFor the " ..
                "Alliance!",
        },
        [10255] = {
            description = "I think there's something we can use in the blood as the base of an antidote. " ..
                "Don't look at me like I've lost my mind!\n\nIt's a common theme in nature. Often, the " ..
                "cure for something can be derived from the toxin itself. That's just what I aim to " ..
                "do.\n\nRidding the boars of their demonic influence would probably eliminate their " ..
                "aggression and give us insight into how to best attempt to help other species.",
            rewardChoices = {{25985, 1}, {25986, 1}, {25987, 1}},
            rewardMoney = 29000,
        },
        [10256] = {
            description = "In retrospect, I suppose I should've expected Kael'thas's magic to be this " ..
                "robust. He's always been a talented mage, but I've never seen anything like the power he " ..
                "wielded during the attack on the tower.\n\nThe ward keeps me from being able to scry out " ..
                "the force holding it in place, but it doesn't preclude you from scrying.\n\nYou'll " ..
                "require a focus, though. A crystal-bearing giant named Apex roams the plains to the west " ..
                "of Manaforge Duro. One of its crystals would make an excellent scrying focus.",
            rewardMoney = 41000,
        },
        [10257] = {
            description = "It doesn't surprise me that Kael'thas has put the key to this ward in the " ..
                "hands of someone like Commander Sarannis. Prince Kael'thas is a great many things, but " ..
                "he is no simpleton.\n\nIn order to break this curse once and for all, you must enter " ..
                "Tempest Keep and claim the keystone.\n\nOnly once the keystone has been destroyed will I " ..
                "regain my freedom.",
            rewardMoney = 132000,
        },
        [10258] = {
            description = "Hogarth, the commander of the Armory, is in the eastern tower. You must report " ..
                "your victory over Urtrak to him. Perhaps he will be friendly? Of course he may try to " ..
                "consume your soul. One can never tell with spirits such as these.\n\nThe Unyielding are " ..
                "still against us and will no doubt kill you if they can. Be careful <name>.",
            rewardChoices = {{29108, 1}, {29109, 1}},
        },
        [10261] = {
            description = "WANTED: 1 Annihilator Servo to replace the failing one in my Long Neck " ..
                "Spectrum Analyzer.\n\nYou and your friends might want to check with the blood elves at " ..
                "Manaforge B'naar to the west to see if they have any spares. They seem to have a few " ..
                "arcane annihilators roaming about.\n\nPlease deliver the servo in pristine condition to " ..
                "Papa Wheeler at Area 52.",
            rewardChoices = {{30294, 1}, {30295, 1}, {30296, 1}},
            rewardMoney = 78000,
        },
        [10262] = {
            description = "There is something else that I want your help with.\n\nA group of ethereals, " ..
                "known as the Zaxxis, have cut their relationship with the Consortium and gone into " ..
                "business for themselves. They've even cut deals with the Sunfury blood elves. This will " ..
                "not be tolerated!\n\nI infiltrated their group at the Heap to the south. But after I " ..
                "took out their leader, I had to escape here to Area 52.\n\n<class>, go down there and " ..
                "bring back their insignias. Of course, not all wear them because they're cowards.",
            rewardMoney = 39000,
        },
        [10263] = {
            description = "The naaru of Shattrath City have been trying to find a means to bring the " ..
                "Consortium over to their way of seeing things.\n\nLuck would have it that the business " ..
                "relationship between the ethereals and the blood elves of the Netherstorm has recently " ..
                "soured.\n\nThere's a Consortium representative in town named Nether-Stalker Khay'ji who " ..
                "recently ran into trouble with a pack of renegade ethereals. As a representative of the " ..
                "Aldor, I would like for you to help him in any way that you can.",
        },
        [10264] = {
            description = "The naaru of Shattrath City have been trying to find a means to bring the " ..
                "Consortium over to their way of seeing things.\n\nLuck would have it that the business " ..
                "relationship between the ethereals and the blood elves of the Netherstorm has recently " ..
                "soured.\n\nThere's a Consortium representative in town named Nether-Stalker Khay'ji who " ..
                "recently ran into trouble with a pack of renegade ethereals. As a representative of the " ..
                "Scryers, I would like for you to help him in any way that you can.",
        },
        [10265] = {
            description = "Our leader, Nexus-Prince Haramad, has tasked me with the acquisition of a " ..
                "crystal artifact from the Arklon Ruins to the southeast.\n\nThey're old draenei ruins. " ..
                "Unfortunately for both myself and the goblins here, the Burning Legion has decided to " ..
                "move in to perform their own excavation.\n\nIf you're willing to help me, go to the " ..
                "ruins and take the crystal artifact from the dreadlord named Pentatharon.",
            rewardMoney = 41000,
        },
        [10266] = {
            description = "While you were at the Arklon Ruins, I received a request for assistance from " ..
                "one of our representatives out in the field. It would appear that the Consortium is " ..
                "having some 'difficulties' in trying to recover property from the blood elves, which " ..
                "they refuse to pay for.\n\nPlease head east out of Area 52 and cross the bridge to the " ..
                "next island over. You'll find my associate, Gahruj, at the Midrealm Post, just inside of " ..
                "Eco-Dome Midrealm.",
        },
        [10267] = {
            description = "Our business relations with the blood elves appear to be at an end. A few " ..
                "weeks ago a large shipment of surveying equipment was delivered to them at Manaforge " ..
                "Duro. They have refused to pay for it.\n\n<name>, I would ask that you pay the blood " ..
                "elves of Manaforge Duro to the east a visit. They appear to be having some trouble with " ..
                "an infestation of mana creatures there, so take advantage of their preoccupation.\n\nI " ..
                "care not what happens to them, but I would very much like to see the return of our " ..
                "property.",
            rewardChoices = {{30271, 1}, {30272, 1}, {30273, 1}},
            rewardMoney = 41000,
        },
        [10268] = {
            description = "Nexus-Prince Haramad has conveyed to me that he is interested in the immediate " ..
                "return of this property to him personally. I would greatly appreciate if you would " ..
                "deliver it in my stead.\n\nIt is a great honor to gain an audience with the " ..
                "nexus-prince, and I am sure that he would be keenly interested in hearing the tales of " ..
                "your adventures here in the Netherstorm.\n\nSeek out his chamber atop the Stormspire to " ..
                "the north. He is often present as a holographic image, which you may address.",
            rewardMoney = 21000,
        },
        [10269] = {
            description = "There is another reason for the retrieval of the surveying equipment. There is " ..
                "a crystal from draenei legend of great importance to me.\n\nIt is said that the crystal " ..
                "bestows god-like powers to its bearer! But it is in danger of being unearthed by others " ..
                "- namely the Burning Legion.\n\n<name>, take the equipment and use it to find the first " ..
                "triangulation point. We know it to be somewhere to the east near Manaforge " ..
                "Ultris.\n\nAfterward, check-in with my agent, Dealer Hazzin, on the Manaforge Ultris " ..
                "island.",
            rewardMoney = 41000,
        },
        [10270] = {
            description = "From the look on your face, I can tell you're a <race> who appreciates a good " ..
                "profit.\n\nI've built a reputation as a dealer in exotic goods, and I'm about to launch " ..
                "a new venture.\n\nI need a reliable subcontractor to procure the goods from the " ..
                "Celestial Ridge.\n\nFirst, you'll need to re-energize a teleport pad. There is a spare " ..
                "power pack in Access Shaft Zeon, which is on the south side of Manaforge UItris. The " ..
                "Protectorate is operating in there, so you may be able to follow their tracers to your " ..
                "goal.",
            rewardMoney = 44000,
        },
        [10271] = {
            description = "As you've no doubt seen, the area is teeming with nether dragons in various " ..
                "stages of growth. All nether dragons, young and old, contain an essence that's highly " ..
                "desired by K -- err, by a client of mine.\n\nMost people aren't willing to risk their " ..
                "lives to gather it, so we've got the place to ourselves. You can start by gathering the " ..
                "essence from any of the creatures out here, but it's imperative that we start building a " ..
                "supply right away. Return to me once you have the first batch.",
            rewardMoney = 44000,
        },
        [10272] = {
            description = "We've come here to investigate rumors of a strange breed of dragons, perhaps " ..
                "even descendents of Deathwing himself. These are clearly not ordinary black dragons, " ..
                "though.\n\nWe'll know more once we've had a chance to examine their eggs. Their hatred " ..
                "for my flight runs deep, so I can't get close enough to gather the eggs. Will you agree " ..
                "to help?",
            rewardMoney = 44000,
        },
        [10273] = {
            description = "Your former employer, Wind Trader Marid, must've gotten wind that you're " ..
                "helping us now. Through my projection, I've seen his nether-stalkers entering the area, " ..
                "hoping to track us down.\n\nWe've been able to evade them so far, but Marid must be " ..
                "dealt with before the problem grows more severe.\n\nIf your impressions of Marid are " ..
                "correct, he'll do just about anything to secure the supply of his product. Return to him " ..
                "and tell him you're prepared to offer a deal. Lure him away and slay him.",
            rewardMoney = 44000,
        },
        [10274] = {
            description = "The nether dragons have the same ferocious temperament as their black dragon " ..
                "forbears, but there is something entirely alien about them. They hatch and mature " ..
                "rapidly, harnessing the strange energies that forged their kind in the destruction of " ..
                "Draenor.\n\nThere is so much more I need to know about them, but I believe the powers " ..
                "may be of use to my own flight. If we can displace the leader of these drakes, Veraku, " ..
                "with a show of dominance, we can cow the rest of them into submission.",
            rewardChoices = {{29808, 1}, {29810, 1}, {29811, 1}, {29812, 1}},
            rewardMoney = 88000,
        },
        [10275] = {
            description = "I've recalibrated the triangulation device with the information that you " ..
                "provided from the first point. You'll use it in exactly the same manner to discover the " ..
                "second.\n\nAll that I can tell you is that the second point is somewhere far to the " ..
                "west.\n\nOnce you've located it, speak with Wind Trader Tuluman; another of the " ..
                "nexus-prince's agents. He's posing as a weapon merchant at a small trading post next to " ..
                "the bridge, which leads to the island that Manaforge Ara is on.",
            rewardMoney = 44000,
        },
        [10276] = {
            description = "With the data from both the first and second points, I'm now certain that the " ..
                "crystal is at the top of the Ruins of Farahlon to the northeast.\n\nUnfortunately, the " ..
                "data indicates that the crystal is moving, which means that it has already been " ..
                "discovered, probably by the Burning Legion!\n\nJust in case, I recommend that you take " ..
                "some friends along.\n\nSlay the demon that has the crystal and return it to Nexus-Prince " ..
                "Haramad.",
            rewardMoney = 44000,
        },
        [10277] = {
            description = "Greetings, <name>. Please follow the custodian. She will make things a bit " ..
                "more... clear.",
        },
        [10278] = {
            description = "Long have I wandered through Outland, searching for the truth of the void. Now " ..
                "I am old and weak. Perhaps you will help me?\n\nI must learn the secrets of the " ..
                "voidwalkers. You must find the Warp Fields to the west. West of the Expedition Armory " ..
                "there is a dark place on the edge of the abyss where time and space are weak. Use my " ..
                "unstable warp rift generator in the Warp Fields to create a warp rift. You must gather " ..
                "warp nether from the creatures that come through.",
            rewardMoney = 20000,
        },
        [10279] = {
            description = "Ah, <name>. We have been expecting you. Please, allow one of my brothers to " ..
                "fly you down to the master. He awaits you below...",
        },
        [10280] = {
            description = "I am an ethereal of my word, <name>. You have truly inspired me.\n\nI am now " ..
                "going to give you the ata'mal crystal to hand over to the naaru. As it was your heroics " ..
                "that made this possible, I wish for you to deliver it.\n\nYou may use my personal " ..
                "teleporter to go directly to Shattrath City. Simply step through it and you will be " ..
                "transported there.\n\nGive the crystal to the naaru known as A'dal on the Terrace of " ..
                "Light. May the trade winds be at your back.",
            rewardChoices = {{30256, 1}, {30257, 1}, {30258, 1}},
            rewardMoney = 132000,
        },
        [10281] = {
            description = "Greetings, <name>. Do not be alarmed. This is merely a projection of my " ..
                "current form. It's the only way my companion and I could keep watch without revealing " ..
                "ourselves.\n\nThe ethereal who approached you, Marid, is little better than a swindler " ..
                "in the guise of a legitimate merchant. I'd like you to consider working with me instead. " ..
                "My purpose out here is to find out more about the unusual dragonkin on this ridge. Meet " ..
                "me at the north end of the ridge and we will discuss this further.",
        },
        [10282] = {
            description = "To the west is the timeway to Hillsbrad of the past - 7 years to be " ..
                "exact.\n\nForces are working against the Horde warchief, Thrall, attempting to prevent " ..
                "him from ever escaping Durnholde Keep.\n\nIf Thrall never escapes, this world - as you " ..
                "know it - will cease to exist.\n\nGather a group of adventurers and take the timeway to " ..
                "old Hillsbrad. Two of our agents await you inside.\n\nSpeak with Erozion on the other " ..
                "side.",
        },
        [10286] = {
            description = "Arelion's journal does not deal with any sort of scholarly studies. It details " ..
                "his escapades with a young female blood elf! How could I've been such a " ..
                "fool?\n\nUnfortunately, the floozy's identity is not revealed in this journal. Aledis, a " ..
                "colleague of Arelion's, was his best friend and confidant. Go question him and find out " ..
                "who he was having this affair with.\n\nI saw Aledis leave Falcon Watch for Zangarmarsh. " ..
                "Follow the road headed north from town; it'll eventually lead west, toward Zangarmarsh.",
        },
        [10287] = {
            description = "I'm Arelion's friend, but I'm not going to take the beating of my life for " ..
                "him. His mistress is Viera Sunwhisper.\n\nGo tell that harpy of a wife of his. What's " ..
                "she going to do anyway?",
            rewardMoney = 14000,
        },
        [10288] = {
            description = "I want you to speak with Amish Wildhammer, standing about 30 paces south of " ..
                "us, and catch the first flight to Honor Hold. When you arrive at Honor Hold, you'll be " ..
                "greeted by Marshal Isildor. I have prepared a report detailing our situation here. Give " ..
                "him the report, and tell him you're ready for duty.\n\nYou have your orders, soldier, " ..
                "now move out! And though your blood must be burning to help us against the fiends below, " ..
                "waste no time here. Honor Hold needs you even more.",
        },
        [10289] = {
            description = "When you're ready, I'll summon a wyvern to fly you to Thrallmar. Once you " ..
                "arrive, deliver Orion's report to General Krakork.\n\nLok'tar ogar, <name> - good luck.",
        },
        [10290] = {
            description = "To the northeast is an area called the Netherstone, a landmark not seen when " ..
                "this was a lush, green land. Newly-exposed crystal formations have shown us a mineral " ..
                "we've called farahlite in honor of this land's former identity.\n\nThe tiny amount of " ..
                "farahlite we've mined has already proven popular with our clients. The highest grade of " ..
                "the mineral comes not from static deposits, but from the giants around the Netherstone. " ..
                "I can offer you a cut of the profits if you'll help supply the higher grade farahlite.",
            rewardMoney = 44000,
        },
        [10291] = {
            description = "Though our warriors are without peer, our hold on this wasteland is still " ..
                "tenuous. Report to Nazgrel inside the barracks - he has need of agents... such as you. " ..
                "If we can't protect our holdings here, we'll be of no use to anyone. Now go!",
        },
        [10293] = {
            description = "Now that we've got a good baseline product, we're going to need something of " ..
                "higher quality. Certainly the farahlite we've gathered so far is nice, but I know " ..
                "there's better out there.\n\nWe'll have to get a sample directly from Cragskaar, the " ..
                "patriarch of the Farahlon giants! You should be able to find it among the other giants " ..
                "in the Netherstone area. It's got huge pieces of farahlite jutting from its back and " ..
                "that's exactly what we need. Fell the giant and collect a farahlite core from it.",
            rewardChoices = {{29813, 1}, {29814, 1}, {29815, 1}},
            rewardMoney = 41000,
        },
        [10294] = {
            description = "We have to improve my warp rift generator. You must take it to Void Ridge. " ..
                "Head east of here. You must avoid the foul fort of Zeth'Gor. To the east beyond Zeth'Gor " ..
                "is a small pass through the mountains. Through this pass you will find Void Ridge, a " ..
                "terrible place on the edge of the abyss.\n\nYou must kill the walkers that you find " ..
                "there, and bring me shards of their souls. With their power we will improve upon the " ..
                "warp rift generator and open a portal to the beyond that cannot be closed.",
            rewardMoney = 20000,
        },
        [10295] = {
            description = "My warp rift generator is complete. You can now use it to summon a true prince " ..
                "of the void, a creature whose soul shard will tell us much of what lies beyond.\n\nGo " ..
                "south in Void Ridge and use my warp rift generator near the void stones. Look for a " ..
                "cluster of crystals near the edge of the abyss. A huge warp rift will form and Void " ..
                "Baron Galaxis will surely appear.\n\nDestroy this creature and bring me his soul shard.",
            rewardChoices = {{29399, 1}, {29400, 1}, {29398, 1}},
            rewardMoney = 29000,
        },
        [10296] = {
            description = "The Infinite Dragonflight have abandoned all pretense of subtlety. They plot " ..
                "to destroy the Guardian, Medivh, and prevent the Dark Portal from ever opening. While " ..
                "outwardly, this may appear a boon to the forces of the Alliance, it is in actuality " ..
                "catastrophic and will result in your world ending.\n\nYou must venture through the " ..
                "timeway leading to the Black Morass. Go west and then south, past my future self, until " ..
                "you reach the tunnel that houses the swamp specimens. Cross over and speak with Sa'at.",
        },
        [10297] = {
            description = "Beyond this timeway the Guardian, Medivh, feverishly works to open the Dark " ..
                "Portal.\n\nScattered across the morass, rifts will materialize. Infinite will pour out " ..
                "of the rifts and attempt to destroy Medivh's shields and, ultimately, Medivh.\n\nKill " ..
                "their rift lords and leaders! Do this until Medivh succeeds.",
            rewardChoices = {{29320, 1}, {29322, 1}, {29321, 1}, {29323, 1}},
        },
        [10299] = {
            description = "We cannot shut down the manaforges by force as we'd risk causing an explosion " ..
                "that would shake Outland to the core.\n\nAccording to your transcription, there is an " ..
                "emergency shutdown that permanently disables the technology - a safety mechanism common " ..
                "in naaru constructs.\n\nTo perform this procedure you will have to obtain a crystal that " ..
                "will allow you to communicate with the console. This access crystal is in the possession " ..
                "of an overseer called Theredis according to our information.",
            rewardMoney = 39000,
        },
        [10300] = {
            description = "< Ravandwyr inspects the staff, noting that part of the headpiece seems to be " ..
                "missing.>\n\nSimply barbaric! Ekkorash must've taken the staff's crystalline headpiece " ..
                "for use in some other trinket, not realizing that it works in concert with the rest of " ..
                "the staff.\n\nAs long as it remains broken, the staff's power is greatly diminished. " ..
                "With a suitable draenei crystal, I should be able to repair it. I've heard the goblins " ..
                "remarking about the crystals carried by the ghosts at the Enkaat Ruins to the north.",
            rewardMoney = 41000,
        },
        [10301] = {
            description = "While I'm glad to have most of Krasus's Compendium back, it's useless without " ..
                "the heliotrope oculus. You see, Krasus was well aware of the sheer power of the spells " ..
                "recorded in the book and took steps to safeguard them from prying eyes.\n\nOnly a " ..
                "knowledgeable mage can use the oculus to unlock the compendium's secrets.\n\nDuring " ..
                "Kael'thas's attack, one of his lieutenants, Spellreaver Marathelle, looted it and took " ..
                "it to Sunfury Hold northeast of the tower. No doubt she thought it a pretty little " ..
                "bauble.",
            rewardMoney = 41000,
        },
        [10302] = {
            description = "The irradiated power cores from the Exodar have been wreaking havoc on the " ..
                "environment here. The most obvious effect has been the appearance of the strange " ..
                "creatures that seem to have sprung up near them.\n\nThere may be something we can do to " ..
                "help them, but now, their sheer numbers are becoming too much for us to handle.\n\nI'd " ..
                "like you to go out and cull their numbers somewhat, and perhaps I'll have another idea " ..
                "after giving it some thought.",
            rewardMoney = 35,
        },
        [10303] = {
            description = "You must eliminate... the blood elf... threat. Find out... what they're... up " ..
                "to!\n\nThey're on the... ridge behind me.",
            rewardChoices = {{24133, 1}, {24134, 1}, {24135, 1}},
        },
        [10304] = {
            description = "With your help, we were able to find a solution to our problems faster than I " ..
                "could have hoped.\n\nI don't have any other work for you to do. My apprentices and I can " ..
                "handle the rest.\n\nYou should go speak with Vindicator Aldar on the other side of the " ..
                "ship.",
        },
        [10305] = {
            description = "This worn, sturdy tome is no spellbook, as you might expect a Kirin Tor mage " ..
                "to carry. The pages of the volume are covered with hand-copied stories, accompanied by " ..
                "colorful illustrations.\n\nThe tome seems to be far older than its former owner and may " ..
                "have even been a family heirloom. A powerful tie to the book may have been the last " ..
                "thread tying Belmara's spirit to the ruins of Kirin'Var. Returning it to its proper " ..
                "place on the bookshelf in her quarters might help appease her restless spirit.",
        },
        [10306] = {
            description = "The cloak, undoubtedly of high elven craftsmanship, is richly tailored, even " ..
                "by the standards of the Kirin Tor. The symbols and characters sewn into the cloak's " ..
                "fabric hold no meaning for you, but clearly imbue the garment with magical " ..
                "properties.\n\nPerhaps this object binds the spirit of its former owner to this plane of " ..
                "existence. If so, returning it to the dresser in Conjurer Luminrath's quarters might " ..
                "break the spirit's link to this world, allowing it to rest.",
        },
        [10307] = {
            description = "Looking at the hat, you find yourself asking if any Kirin Tor mage would own " ..
                "such headgear. Judging from the hat's wear, it seems the gnome wouldn't go anywhere " ..
                "without it.\n\nYou try on the hat momentarily, discovering no magical properties beyond " ..
                "a faint urge to dance.\n\nThe treasured possession might be the source of the dead " ..
                "mage's bond to the village. Placing the hat in the footlocker in Cohlien's quarters " ..
                "might free his spirit.",
        },
        [10309] = {
            description = "You see that scrapped fel reaver over there to the south? Isn't it a thing of " ..
                "beauty?\n\nI want its heart!\n\nWhat? Yes, of course it has a heart... what " ..
                "doesn't?\n\n<N. D. looks indignant for a moment.>\n\nGo on over there, pry it open, " ..
                "bring back what I want and I'll give you a nice finder's fee in return.\n\nOh, and I'd " ..
                "take a friend or two along if I were you. These Zaxxis ethereals are a pretty mean " ..
                "bunch!\n\nTake this fel zapper to jumpstart its heart when you're ready to begin.",
            rewardChoices = {{30268, 1}, {30269, 1}, {30270, 1}},
            rewardMoney = 39000,
        },
        [10310] = {
            description = "With the Burning Legion nearby at the fel reaver scrap field, we must do what " ..
                "we can to stop the flow of demons into the area.\n\nThey have a warp-gate to the south " ..
                "in an area that they've cleverly named Invasion Point: Destroyer.\n\nI need you to go " ..
                "with me to the site and keep me safe while I sabotage it.\n\nAfterward, go to the " ..
                "Midrealm Post to the north inside Eco-Dome Midrealm and apprise Gahruj of our " ..
                "success.\n\nWe're going to need a friend or two of yours along to help with this.",
            rewardChoices = {{29978, 1}, {29979, 1}, {29980, 1}},
            rewardMoney = 88000,
        },
        [10311] = {
            description = "<class>, it is good to see a helpful face around here.\n\nThe Burning Legion " ..
                "at the nearby fel reaver heap has become more bold, and I am beginning to fear for our " ..
                "safety here. The demons are constantly receiving reinforcements from Invasion Point: " ..
                "Destroyer to the south.\n\nMy compatriot, Drijya, has gone down there to scout and see " ..
                "if he can do something about the Burning Legion's warp-gate.\n\nPlease find and assist " ..
                "him in any way that you can.",
        },
        [10312] = {
            description = "Silencing the spirits has not bled them of their aggression as we had hoped it " ..
                "would. The malevolent spirits you subdued have reemerged in the streets of the " ..
                "town.\n\nWe must uncover what is causing this to happen. The destruction of Kirin'Var " ..
                "was just the beginning, or else the spirits would have been quieted by now.\n\nThe town " ..
                "hall in the southern section of Kirin'Var maintained a logbook of all the residents. " ..
                "Last I heard, it was in the keeping of Battle-Mage Dathric. Perhaps his spirit still has " ..
                "it.",
            rewardMoney = 41000,
        },
        [10313] = {
            description = "If our instincts are right and these manaforges have been made using " ..
                "technology from Tempest Keep, then all of Outland could be in grave danger.\n\nTempest " ..
                "Keep's energy-recharging mechanisms were never supposed to be used this close to the " ..
                "land. The warp energies are capable of destroying this very land, even when contained " ..
                "within Kael's pipelines.\n\nTake this orb to Manaforge B'naar; it is attuned to measure " ..
                "warp energies. Use it at the pipelines' ends, where they go into the earth.",
            rewardChoices = {{30362, 1}, {30363, 1}, {30364, 1}, {30521, 1}},
        },
        [10314] = {
            description = "The strange magical device resembles nothing you've ever seen before. It's " ..
                "certainly not of blood elf manufacture.\n\nAs you sense spirits moving closer to the " ..
                "building, the orb glows with a greater intensity, which fades as the spirits leave. " ..
                "There's no question that it plays a role in the corruption of the ghosts.\n\nHow it " ..
                "works remains a mystery. Perhaps Custodian Dieworth will have some insight if you can " ..
                "provide the remains of some of the spirits along with your observations.",
            rewardMoney = 41000,
        },
        [10315] = {
            description = "The blood elves are fools! I'm glad that our trade relations with them have " ..
                "fallen apart. In all of my travels throughout the cosmos, I have never encountered " ..
                "beings so selfish.\n\nThey continue to destroy the land around us with their manaforges, " ..
                "so let's see if we can put a dent in their operations across the bridge at Manaforge " ..
                "Ara.\n\nTheir nethermancers channel energy to and from the blood gems to stabilize the " ..
                "flow of power. Go over there and wipe them out!",
            rewardMoney = 44000,
        },
        [10316] = {
            description = "Whoever is behind the transformation of the spirits has been very deliberate " ..
                "in their actions, taking care to target the most powerful mages first, but why? The kind " ..
                "of magic required to influence the spirits of slain Kirin Tor mages must be very " ..
                "powerful.\n\nWhy would a powerful mage go to all this trouble? I'm inclined to say this " ..
                "is another plot of Kael'thas's, designed to cause more misery here. If there are blood " ..
                "elves here, they're likely to be hiding in the houses across the covered bridge.",
        },
        [10317] = {
            description = "The blood elves call the mine underneath Manaforge Ara the Trelleum Mine. Ever " ..
                "since they lost the one underneath Manaforge Ultris, this is where their sole supply of " ..
                "material for running the forges is coming from.\n\nNeedless to say, it would be a boon " ..
                "for us to cripple their mining operation. Perhaps we'd even be able to move in and take " ..
                "it over for ourselves?\n\nWhatever the case, I want you to go in there and deal with " ..
                "Foreman Sundown. The mine is around the back of the island to the left.",
        },
        [10318] = {
            description = "I used to be the foreman here. But now that I've been demoted, I've come to " ..
                "realize our pilgrimage from Quel'Thalas to Outland was all a lie.\n\nA lie perpetrated " ..
                "by Kael'thas to strengthen his forces here in the Netherstorm.\n\nI've tried to convince " ..
                "my brethren that we should leave, especially with the Burning Legion here, but they are " ..
                "all too stubborn.\n\nDo me a favor? Kill Overmaster Grindgarr. Then return to your " ..
                "ethereal and tell him that I am no longer his enemy.",
            rewardChoices = {{30003, 1}, {30004, 1}, {30005, 1}, {30006, 1}},
            rewardMoney = 44000,
        },
        [10319] = {
            description = "I suppose an explanation is in order. You've met one of the archmage's " ..
                "apprentices, Ravandwyr, but there was also another named Naberius.\n\nHe was an ardent " ..
                "student, but was drawn to necromancy. When Kael'thas appeared with his forces, Naberius " ..
                "seized the opportunity to betray the archmage, handing over the secrets to the tower's " ..
                "defense.\n\nNow, it seems, he has become a lich. If we are to stop him, we must capture " ..
                "his phylactery. Knowing him, he would've buried it somewhere out of sight in his domain.",
            rewardMoney = 41000,
        },
        [10320] = {
            description = "Archmage Vargoth saw the danger in Naberius 's pursuit of necromancy, but I " ..
                "don't think he ever anticipated that his own apprentice would wreak this much " ..
                "destruction upon the Kirin Tor.\n\nYou must defeat him, <name>, or else he will continue " ..
                "enslaving the spirits of our fallen brothers, robbing them of their rightful rest and " ..
                "destroying what little remains of Kirin'Var.\n\nWith his phylactery in hand, he can be " ..
                "confronted by two or three combatants, but who knows what his magic might do to more " ..
                "foes?",
            rewardChoices = {{29780, 1}, {29781, 1}, {29782, 1}, {29783, 1}},
            rewardMoney = 41000,
        },
        [10321] = {
            description = "Your success at B'naar has given us a great deal of hope, <name>.\n\nWe've " ..
                "shared our discoveries with the Scryers and in return they've given us more information " ..
                "on the remaining manaforges.\n\nThree other manaforges still stand, in full control of " ..
                "the Sunfury army.\n\nYou will find Manaforge Coruu to the east. Overseer Seylanna holds " ..
                "the access crystal there. Obtain it and use it on the manaforge's control console to " ..
                "begin the emergency shutdown.\n\nWe're all counting on you, <name>.",
            rewardMoney = 41000,
        },
        [10322] = {
            description = "We've received news from one of the two manaforges that remain operational. " ..
                "The Sunfury army is losing control of Manaforge Duro.\n\nDroves of errant mana creatures " ..
                "have been attracted to it by its increased energy production - the manaforge is in " ..
                "chaos.\n\nAn explosion at Duro has the potential to cause a chain reaction that would " ..
                "endanger all of Outland. Overseer Athanel is in possesion of the access crystal you need " ..
                "to safely disable the manaforge.",
        },
        [10323] = {
            description = "One manaforge is all that keeps Tempest Keep functional. After we bring " ..
                "Manaforge Ara down, Kael will have to resort to depleting whatever energy he's got " ..
                "stored up.\n\nTravel to Manaforge Ara, in the northwest, and deliver the final blow that " ..
                "we need by shutting it down.\n\nThe last access crystal is in the possession of Overseer " ..
                "Azarad. Be warned that we expect heavy opposition in the last of Kael's functional " ..
                "manaforges. You're likely to need the assistance of reliable friends.",
            rewardChoices = {{30377, 1}, {30365, 1}},
            rewardMoney = 44000,
        },
        [10325] = {
            description = "As you probably know, <name>, the Aldor are keepers of the Light and servants " ..
                "of the naaru.\n\nDiametrically opposed to us are the agents of the Burning Legion - " ..
                "demons bent on the destruction of worlds and the corruption of the innocent.\n\nIf you " ..
                "wish to prove yourself to the Aldor, bring me the insignias of low-ranking Legion and " ..
                "their Shadow Council followers. We know of a Shadow Council hideout in the Bone Wastes " ..
                "and there are many Legion outposts in Nagrand and the Blade's Edge Mountains.",
        },
        [10328] = {
            description = "Something about these manaforges has been bothering me, <name>. Naaru " ..
                "technology is incredibly advanced; it should've taken Kael'thas years to even begin to " ..
                "understand it.\n\nInformation-gathering on the subject has been difficult as Kael's army " ..
                "is well disciplined and destroys all evidence of written communication.\n\nWe've been " ..
                "informed Manaforge Duro is under attack by mana creatures. It is possible that those " ..
                "defending it have not yet destroyed their briefings. Obtain them and bring them to me.",
        },
        [10329] = {
            description = "I was having a friendly discussion with the Aldor while you were gone. " ..
                "Manaforges sure look like modified naaru technology from Tempest Keep. Apparently, most " ..
                "naaru constructs have certain safeguards that allow them to be permanently disabled in " ..
                "case of emergency.\n\nThe procedure is usually initiated at a control console via an " ..
                "access crystal. Lo and behold, according to the roster you secured, such a crystal is in " ..
                "the possession of a fellow called Overseer Theredis. Obtain it and see what you can do.",
            rewardMoney = 39000,
        },
        [10330] = {
            description = "Thalodien told us of your success in disabling Manaforge B'naar. He expects a " ..
                "repeat performance here and asked us to keep an eye out for anyone using a crystal to " ..
                "access the console inside. Overseer Seylanna holds the access crystal, we're sure of " ..
                "it.\n\nGo back in there and finish the operation. No need to be stealthy anymore; get " ..
                "the crystal, begin the shutdown, kill the technicians trying to stop you and get " ..
                "out.\n\nHurry, it won't be long before Kael's lapdogs sniff us out.",
            rewardMoney = 41000,
        },
        [10331] = {
            description = "You haven't seen a heavy smithing hammer lying around by chance, have you? I " ..
                "brought it out here with me to finish the shoes for some of old man Amorlin's horses, " ..
                "but I can't find it.\n\nI've searched the barn no less than a half dozen times and I " ..
                "just can't seem to find it. Maybe one of the other apprentices retrieved it and took it " ..
                "back to the smithy? Would you be willing to go down there and take a look? The workshop " ..
                "is to the southeast of the tower in the Town Square.",
            rewardMoney = 41000,
        },
        [10332] = {
            description = "At last, my journeyman project is complete! I can't wait to formally present " ..
                "it to Master Rhonsus.\n\n<The apprentice looks at you as you describe your experiences " ..
                "retrieving the hammer.>\n\nThey attacked you? All of them? By the Light, they've gone " ..
                "mad!\n\nWhat are we to do, <name>? It grieves me to say so, but it may be necessary to " ..
                "kill Master Rhonsus. It would leave me as the only smith in Kirin'Var, but I believe my " ..
                "training is sufficient to serve the town's needs.",
            rewardChoices = {{29787, 1}, {29788, 1}, {29789, 1}, {29791, 1}},
            rewardMoney = 41000,
        },
        [10333] = {
            description = "Say, <name>, I was wondering if you could do me another favor.\n\nMy partner " ..
                "out in the field could probably use a hand. I was wondering if you could go check in on " ..
                "her.\n\nI'm sure that Mama Wheeler will appreciate the help. Just don't mind her sharp " ..
                "tongue.\n\nShe's trying to look out for our interests to the east. You'll find her just " ..
                "inside Eco-Dome Midrealm at the Midrealm Post.",
        },
        [10334] = {
            description = "Where, oh where has my Bessy gone? After the attack, I searched the fields and " ..
                "the Chapel Yard for her, but she was nowhere to be seen!\n\nAll I have left of her is " ..
                "this old cowbell. She usually comes running when she hears it, but these feeble old " ..
                "bones probably couldn't shake it hard enough.\n\nI'll loan you Bessy's bell if you're " ..
                "willing to go out to the fields and ring it as hard as you can. Perhaps all Bessy 's " ..
                "waiting for is a little more cowbell.",
            rewardMoney = 41000,
        },
        [10335] = {
            description = "I have to get over to the Ruins of Farahlon to start my excavations! The " ..
                "problem is that the place has been infested by demons!\n\nMaybe you could do some " ..
                "preliminary work for me?\n\nThere are three locations within the ruins to the northeast " ..
                "where I want you to place surveying markers. Each is near a draenei banner.\n\nReturn to " ..
                "me when you've managed to place all three markers.",
            rewardChoices = {{30253, 1}, {30254, 1}, {30255, 1}},
            rewardMoney = 44000,
        },
        [10336] = {
            description = "A few weeks ago, the Burning Legion moved into the Ruins of Farahlon, " ..
                "thwarting our plans to excavate the site for its artifacts.\n\nThen earlier today, I " ..
                "learned that one of their dreadlords, Culuthas, somehow killed off all of the other " ..
                "Burning Legion. He has since summoned in demons that serve him.\n\n<class>, I want you " ..
                "to go up to those ruins to the northeast and rid them of their demon infestation.",
            rewardMoney = 44000,
        },
        [10337] = {
            description = "Realizing that Bessy is still staring at you, you gesture toward Thadell 's " ..
                "location. You find yourself promising to protect the cow on her way home. Upon finishing " ..
                "your sentence, you realize there's no possible way the cow could understand anything " ..
                "you've said.\n\nShrugging your shoulders, you prepare to guard the bovine on her way " ..
                "back to Thadell.",
            rewardChoices = {{29804, 1}, {29806, 1}, {29807, 1}, {30400, 1}, {30523, 1}},
            rewardMoney = 41000,
        },
        [10338] = {
            description = "So Manaforge Duro is under attack and Sunfury forces have lost control? What a " ..
                "dilemma! If Duro goes down, then Tempest Keep goes down. Only drawback is... if Tempest " ..
                "Keep is destroyed, the explosion will probably take what little remains of this forsaken " ..
                "land with it.\n\nDead Kael'thas is good. Dead everyone else is... not that great, I " ..
                "suppose. It pains me to ask this of you, but go to Manaforge Duro and shut it down " ..
                "before it goes up in flames. The access crystal is held by Overseer Athanel.",
        },
        [10339] = {
            description = "Directly south of here you will find the Ethereum Staging Grounds. The " ..
                "Ethereum are there, preparing for something... Perhaps an assault on Ultris.\n\nWe can't " ..
                "take any chances, though, <class>. Break through their perimeter defenses and take out " ..
                "their training facility.\n\nOnce you've destroyed their soldiers and Captain Zovax, " ..
                "locate Ethereum transponder Zeta and use it to establish contact with me to get your " ..
                "next set of orders.",
        },
        [10340] = {
            description = "<name>, you've done a great job here at the front, and you showed a lot of " ..
                "talent with that armored gryphon... I think I have another mission in mind for " ..
                "you.\n\nThis new mission launches from Shatter Point -- an attack base the Wildhammers " ..
                "set up on a floating piece of land near the Portal. It's a little unnerving there, but " ..
                "you have tough guts. You'll be fine.\n\nTalk to Wing Commander Dabir'ee and have him " ..
                "send you to Shatter Point. From there, report to the gryphon master Runetog Wildhammer.",
        },
        [10341] = {
            description = "The news you've discovered is fortunate, <name>. Not only do you get to waltz " ..
                "into Manaforge Duro unfettered, this also presents a great opportunity to deal a blow to " ..
                "Kael's army.\n\nUse the mana creature assault to your advantage and pick off any Sunfury " ..
                "stragglers you run into.\n\nI do not take particular glee in the senseless slaughter of " ..
                "my own kin the way that Thalodien does, but the tactical advantage here is too high to " ..
                "pass up.",
            rewardChoices = {{30394, 1}, {30395, 1}, {30396, 1}, {30522, 1}},
        },
        [10342] = {
            description = "I make a good living selling drinks to the boozehounds around here. But I want " ..
                "something more!\n\nThe rocket-chief is always telling me how he can't perfect the rocket " ..
                "fuel needed to get the X-52 off of the ground.\n\nWe can solve that little problem for " ..
                "him.\n\nFor starters I need to extract the oil from the shale of the local shaleskin " ..
                "flayers! It'll form a concentrated, if explosive, base for the mix that I have in " ..
                "mind.\n\nFind the flayers, and their shale, all over the place near the purple rocks.",
            rewardMoney = 39000,
        },
        [10343] = {
            description = "Kael'thas's assault on Kirin'Var began with thundering noise and a bright " ..
                "flash of light in the officer quarters to the northwest. The destruction there was the " ..
                "most severe and after the withdrawal of the blood elves, a strange thing began to " ..
                "happen.\n\nBeings of pure mana began streaming into the village from all over the area. " ..
                "For now, we're containing them as we can, but with more information about the weapon " ..
                "Kael'thas used, I hope to cut off the flow of mana creatures entirely.",
        },
        [10344] = {
            description = "Wing Commander Gryphongar runs this outfit of Wildhammers. If this is your " ..
                "first time to Shatter Point, then you should report to him.\n\nYou'll find him inside " ..
                "what's left of that tower over yonder.",
        },
        [10345] = {
            description = "You see these corpses, <race>? Arconus is responsible for this slaughter. He's " ..
                "sucked them dry, leaving nothing more than a fleshy husk. But don't let the bodies fool " ..
                "you! Inside those corpses lie flesh beasts, waiting to pounce on the unsuspecting fool " ..
                "that gets too close.\n\nI've got my orders. I must remain here until backup arrives. " ..
                "That doesn't mean that you can't take my igniter and destroy the withered corpses that " ..
                "litter the mines. One way or another, the mission must be completed.",
            rewardChoices = {{30341, 1}, {30342, 1}, {30352, 1}, {30519, 1}},
        },
        [10346] = {
            description = "<name>, you've proven yourself as a capable gryphon rider, and we could use " ..
                "you on more sorties over the Abyssal Shelf. What say you, <class>? Do you want some more " ..
                "flight time?",
        },
        [10347] = {
            description = "<name>, are you ready for another sortie over the Abyssal Shelf? I fear that, " ..
                "if we do not maintain pressure on the Legion forces there and allow them to strengthen " ..
                "their hold, then we may suffer a large demon attack from the north.\n\nWhat say you, " ..
                "<class>? Do you want to take another windrider and hammer the Abyssal Shelf one more " ..
                "time?",
        },
        [10348] = {
            description = "I hear that a group of 'druids' from Azeroth has taken quite an interest in " ..
                "the effects of our eco-dome technology.\n\nThe Cenarion Expedition's representatives are " ..
                "eager to get access to the plants growing within the domes, particularly one called the " ..
                "ivory bell, known for its healing properties. They're found in clumps of brush around " ..
                "larger plants in Eco-Dome Midrealm.\n\nI'll share the profits with you if you're willing " ..
                "to gather the herbs for my first delivery.",
            rewardMoney = 41000,
        },
        [10349] = {
            description = "You should take the crystal lump over to the earthbinder. She's just like " ..
                "you... always needing to get to the bottom of a mystery and thinking all of the " ..
                "time.\n\nIf you ask me, she thinks a little too much.\n\nJust give it to her and I'm " ..
                "sure that she'll get you into a heap of trouble figuring out what is going on up there " ..
                "on the ridge.",
            rewardMoney = 3000,
        },
        [10351] = {
            description = "It must be that the evil emanations from that giant crystal are summoning the " ..
                "mountain giants and driving them insane.\n\nIt's too big to move, and beyond our ability " ..
                "to destroy, but I know a way to quell its power.\n\nI've summoned a circle at the " ..
                "northwest corner of the crystal on the ridge. Take this seed to the circle and channel " ..
                "its powers to heal the land through the natural forces of rain, growth and insect " ..
                "repopulation.\n\nBeware, <name>, I sense an external force at play here... this is not " ..
                "natural!",
            rewardChoices = {{28069, 1}, {28070, 1}, {28074, 1}, {28075, 1}},
            rewardMoney = 58000,
        },
        [10353] = {
            description = "Araxes and I were deployed to Ultris 2 days ago. Our mission: Find and " ..
                "terminate the void lord Arconus. We tracked him to this mine and discovered that he'd " ..
                "been feeding off the energies of the creatures in the area.\n\nA fire-fight broke out " ..
                "which resulted in Araxes and I separating. Now I'm stuck here, badly injured. The " ..
                "mission is in shambles!\n\nIf you can take out Arconus, high command would be grateful. " ..
                "Should you accept this mission, I will assist by providing a reflection of myself as a " ..
                "guardian.",
            rewardChoices = {{30328, 1}, {30329, 1}, {30330, 1}, {30517, 1}},
            rewardMoney = 44000,
        },
        [10355] = {
            description = "We must determine how far the damage has spread. The basidium you brought me " ..
                "comes from a bog giant. Their larger, hardier cousins, the bog lords, should prove more " ..
                "resistant to the degeneration that's struck the giants.\n\nIt would be good to know how " ..
                "the changes in the Dead Mire have affected the other creatures out there, too.\n\nReturn " ..
                "to the Dead Mire and see if you can get samples from the bog lords and the hydra in the " ..
                "area.",
            rewardMoney = 27000,
        },
        [10365] = {
            description = "You've done much better than any of us anticipated. Manaforge Ara is the last " ..
                "of Kael's working manaforges. You'll find it northwest of here, though you're likely to " ..
                "have to do some circumnavigating to get to it. We want you to shut it down.\n\nThe last " ..
                "access crystal is in the possession of Overseer Azarad. This is Kael's very last source " ..
                "of energy as far as we know, so expect heavy opposition. I'd bring a couple of friends " ..
                "along if I were you.\n\nHmm... Azarad. What an odd name for a sin'dorei.",
            rewardChoices = {{30366, 1}, {30378, 1}},
            rewardMoney = 44000,
        },
        [10367] = {
            description = "Anywhere you see a tribe of enslaved Broken you will also find a traitor. A " ..
                "despicable being who sold his brothers for promises of power.\n\nThere is a hut at the " ..
                "top of the stairs in the center of the ruins. That's the turncoat's hut.\n\nHe's not " ..
                "there right now, so you will be able to sneak in if you're patient. Inside you will find " ..
                "a coffer with a key inside of it. That key unlocks the chains that keep the Dreghood " ..
                "elders prisoner. Bring it to me.\n\nBeware, Arzeth the Merciless wanders nearby.",
        },
        [10368] = {
            description = "The Dreghood spirit is broken because our elders are imprisoned. Take this key " ..
                "and go downstairs to free them.\n\nThey are Morod the Windstirrer, Akoru the Firecaller " ..
                "and Aylaan the Waterwaker. Once they are free, the spirits will return to the Dreghood " ..
                "tribe.",
        },
        [10369] = {
            description = "Yes, the elemental spirits have returned to us! We are not as strong as we " ..
                "once were, but a little magic can go a long way in the right hands.\n\nArzeth has great " ..
                "powers bestowed upon him by his dark lord. Take this staff. It was once a great symbol " ..
                "of our tribe. Use it against Arzeth and his powers will be temporarily removed from him. " ..
                "Defeat him then, so that my people may finally be free!",
            rewardMoney = 54000,
        },
        [10380] = {
            description = "We've been so blind, <name>, that the alliance of two of our most dangerous " ..
                "enemies went completely unnoticed.\n\nI wouldn't be surprised if the Scryers had " ..
                "something to do with hiding this information from us, but we must now face the reality. " ..
                "The Burning Legion and Kael'thas' Sunfury army serve under the same banner.\n\nThese " ..
                "demons are the only reason Kael'thas was ever able to utilize the technology in Tempest " ..
                "Keep. Under Orelis's orders I must command you to destroy them.",
        },
        [10381] = {
            description = "My mission here is finished. I did what Orelis ordered me to - I've never " ..
                "failed to.\n\nNo more. I foresee a great carnage - a crusade, they'll call it - " ..
                "following the news of this alliance between Kael'thas and the Burning Legion.\n\nFirst " ..
                "they give our holiest city away to our enemies and then they ask us to die fighting " ..
                "their enemies. Go back to Orelis; tell him the naaru can fight their own fights from now " ..
                "on.",
            rewardChoices = {{30379, 1}, {30380, 1}, {30381, 1}, {30382, 1}},
        },
        [10382] = {
            description = "Well, <name>, I hope you're prepared for the next phase of our operation. The " ..
                "Legion never rests - and neither shall we! Take a gryphon and fly over to Honor Point - " ..
                "it's a small post near the Legion Front.\n\nSpeak with Field Marshal Brock. He'll have " ..
                "instructions for you when you arrive. Oh, and tell that pasty-faced shield-kisser I said " ..
                "'hello'.",
        },
        [10384] = {
            description = "Look around you, fleshling. Very close to this transponder should be an " ..
                "Ethereum data cell. Locate that data cell, open it, and retrieve the contents.\n\nBring " ..
                "it back to this transponder at once!",
        },
        [10385] = {
            description = "They're using relays to transfer information around the staging " ..
                "grounds.\n\nThere is only one way for you to see these relays and extract the " ..
                "information they hold. Unfortunately, doing so may cause you irreparable brain " ..
                "damage.\n\nIf you're still interested, you'll need to slay Ethereum here at the staging " ..
                "grounds and take their essences. Once you have an essence, drink it down. It will " ..
                "temporarily allow you to see an Ethereum relay - giving you enough time to destroy a " ..
                "relay and extract its information.",
        },
        [10388] = {
            description = "Hope you enjoyed your flight, friend. A messenger arrived while you were away " ..
                "- seems Nazgrel 's got a new use for you. You'd best head back to Thrallmar and check in " ..
                "with him. I have a feeling the Legion's just getting warmed up.",
        },
        [10389] = {
            description = "Greetings, <name>. I've deciphered the Legion missive and uncovered the " ..
                "demons' strategic plans for this Peninsula. Apparently, there is a large group of " ..
                "hellish terrorfiends gathering near the Pools of Aggonar in the west. We cannot allow " ..
                "such a force to go unchallenged. You must go there and decimate their cursed numbers.",
            rewardMoney = 20000,
        },
        [10390] = {
            description = "<name>, we have reason to believe that the easternmost forge camp is not yet " ..
                "complete. The Legion's gan'arg servants are working 'round the clock to get the facility " ..
                "up and running. We can't allow that to happen.\n\nHead east to Forge Camp: Mageddon and " ..
                "slay 10 gan'arg. Bring me the head of their master - Razorsaw - and the Legion's fel " ..
                "reaver production will grind to a halt!",
            rewardMoney = 20000,
        },
        [10391] = {
            description = "There is a second production facility, Forge Camp: Rage, that lies to the " ..
                "immediate northeast of Thrallmar. The demons have positioned a number of their fel " ..
                "cannons along the ridge - and they're aimed straight at us! You must enter the camp and " ..
                "destroy these fel cannons.\n\n<name>, you must be sure to detonate them all - or nothing " ..
                "will stop the Legion from raining fiery hell down upon our heads!",
            rewardMoney = 20000,
        },
        [10392] = {
            description = "You are an honor to us, <name>. But now we must strike before the Legion " ..
                "recovers! To the north of Thrallmar lies Invasion Point: Annihilator. It houses a " ..
                "warp-portal through which the Legion draws its reinforcements.\n\nYou must overload that " ..
                "portal - and blast it back to the abyss it came from. The portal's activation key will " ..
                "be held by the Point's commander - Warbringer Arix'Amal. Slay him. Take the key. Use it " ..
                "on the portal and do what must be done. May the warchief's blessings be with you.",
            rewardMoney = 20000,
        },
        [10393] = {
            description = "The text on the note is written in some dark, indecipherable scrawl. The more " ..
                "you stare at them, the more the symbols seem to twist and burn before your eyes. There " ..
                "is only one in Thrallmar that can transcribe such vile script - the blood elf Magister " ..
                "Bloodhawk.",
        },
        [10394] = {
            description = "Pay close attention, <name>. We've been surveying the Legion camps that lie " ..
                "along the ridge ahead. We have reason to believe that these so-called 'Forge Camps' are " ..
                "where the demons are constructing those blasted Fel Reavers.\n\nYou can see the closest " ..
                "target, Forge Camp: Mageddon, to the west. Our intelligence suggests that it's still " ..
                "under construction. If you can slay the Gan'arg Servants and their master - Razorsaw - " ..
                "we can bring the Legion's Fel Reaver production to a grinding halt!",
            rewardMoney = 20000,
        },
        [10395] = {
            description = "The text on the note is written in some dark, indecipherable scrawl. The more " ..
                "you stare at them, the more the symbols seem to twist and burn before your eyes. There " ..
                "is only one at Honor Hold who can decipher such archaic script - the draenei mystic, " ..
                "Kryv.\n\nTake the Burning Legion Missive to Warp-Scryer Kryv who resides within the " ..
                "War-Room at Honor Hold.",
        },
        [10396] = {
            description = "Now we focus on the second target - Forge Camp: Rage. It lies just west of " ..
                "Mageddon. Trouble is, the demons have a number of fel cannons aimed straight at the " ..
                "Horde's outpost of Thrallmar! Though I can scarcely believe it, we actually need the " ..
                "Horde to help us hold the line at the Dark Portal. We can't afford to let Thrallmar " ..
                "fall. You've got to destroy these cannons before the Legion pulverizes our allies!",
            rewardMoney = 20000,
        },
        [10397] = {
            description = "Well, we've located the Legion's final base on the ridge - Invasion Point: " ..
                "Annihilator. It lies northwest of Forge Camp: Rage - and it houses a warp-portal through " ..
                "which the Legion has been drawing its reinforcements!\n\nYou've got to close that portal " ..
                "to prevent any more demons from coming through. The Point's overlord, Warbringer " ..
                "Arix'Amal, holds the portal's activation key. Take it from him and shut that blasted " ..
                "gateway down!",
            rewardMoney = 20000,
        },
        [10399] = {
            description = "It is just as I feared. Arix'Amal - the demon you killed earlier, was working " ..
                "for a secret Legionlord - Arazzius the Cruel. It appears this new villain has amassed a " ..
                "force of hellish terrorfiends near the Pools of Aggonar.\n\nYou must journey there and " ..
                "slay the terrorfiends before they strike against us. But be wary, friend - the Pools of " ..
                "Aggonar lie within a tortured, poisonous valley. You can find the cursed pools to the " ..
                "northwest of here, beyond Hellfire Citadel.\n\nLight be with you, <name>.",
            rewardMoney = 20000,
        },
        [10400] = {
            description = "The honorable Warp-Scryer has told me of your perils, <name> - and of the new " ..
                "foe you've discovered. If Kryv is to be believed, this ' Arazzius the Cruel ' is as " ..
                "powerful and evil as any foe the Sons of Lothar have ever faced.\n\nWill you stand for " ..
                "us now, <name>? Will you face this Legionlord and deliver the Light's justice upon him? " ..
                "If so, you will find him at the Pools of Aggonar. If not, his evil will most certainly " ..
                "find you.",
            rewardChoices = {{28040, 1}, {28041, 1}, {28042, 1}},
            rewardMoney = 87000,
        },
        [10403] = {
            description = "Perhaps not all hope is lost for the Dreghood. I am one of four elders that " ..
                "guided this tribe before we were enslaved by the Illidari. I thought the others were " ..
                "dead, but I've slowly learned that at least two others are alive - chained down and " ..
                "powerless just as I am.\n\nI've not yet been able to find Naladu and fear for the worst. " ..
                "There are more huts in the ruins upstairs; perhaps you could look for him. It would be a " ..
                "great boon for our tribe if all our elders were alive.",
        },
        [10405] = {
            description = "We must destroy the machinery that is making these nexus-stalker aberrations " ..
                "possible. To strike at their proto-accelerator would be futile as it is an ethereal " ..
                "creation. We must instead destroy the manaforge energy tube that they are using as a " ..
                "conduit.\n\nI have all that I need to create a device to overload the conduit save for " ..
                "one item. I need a wrapping from an archon or overlord that might be transforming soon " ..
                "in order to calibrate the device.",
        },
        [10406] = {
            description = "I'm sending one of my demolitionists out to place the disruption device. Just " ..
                "make sure no harm comes to him as he's placing the disruptor.\n\nKeep him protected! He " ..
                "will not fight back if enemies attack him as he is only a holographic image but the " ..
                "image can be destroyed!\n\nReturn to me once the job is done.",
            rewardChoices = {{30335, 1}, {30336, 1}, {30337, 1}, {30518, 1}},
        },
        [10407] = {
            description = "The infamous eredar, Socrethar, leads the Burning Legion in Netherstorm. " ..
                "Mentioning his name is enough to make most draenei shudder. He gives orders from an " ..
                "island in the northwest that only his most trusted lieutenants can access.\n\nTo get " ..
                "there you will need to obtain a teleportation stone, which won't be an easy task. The " ..
                "first half of the stone is in the possession of Forgemaster Morug at Forge Base: " ..
                "Oblivion. The second half is held by Silroth at Forge Base: Gehenna.",
            rewardMoney = 44000,
        },
        [10408] = {
            description = "I have in my possession another disruptor, one capable of destroying the three " ..
                "conduits that surround Salhadaar. Once the conduits are destroyed, Salhadaar's " ..
                "protective force fields will be down. For this act, he will strike at you with a " ..
                "ferocity you have never before witnessed, <name>.\n\nIf you are willing to rid the world " ..
                "of Salhadaar, I will give you the disruptor.",
            rewardChoices = {{30009, 1}, {30010, 1}, {30011, 1}, {30012, 1}, {30013, 1}},
            rewardMoney = 132000,
        },
        [10409] = {
            description = "When facing eredar of great power, large armies are useless for the most part. " ..
                "Their corruptive powers over mortal souls are such that only the strongest-willed can " ..
                "even stand face to face with them.\n\nTake this stone to the Invasion Point: Overlord, " ..
                "between Forge Base: Oblivion and Gehenna and bring your closest, strongest friends with " ..
                "you. Orelis and Karja will meet you at Socrethar's Seat; I will send Adyen along with " ..
                "them.\n\nMay the Light prevail today, <name>. May Socrethar meet his end.",
            rewardChoices = {{30368, 1}, {30369, 1}, {30370, 1}, {30371, 1}, {30860, 1}},
            rewardMoney = 132000,
        },
        [10410] = {
            description = "The time has come to face Socrethar, <name>. Confronting an eredar leader " ..
                "isn't something that's taken lightly among us. A single mistake is likely to cost us our " ..
                "lives if we're ill-prepared.\n\nTake Socrethar's teleportation stone to High Priestess " ..
                "Ishanah at the Shrine of Unending Light in Shattrath City. She will determine how we " ..
                "need to handle the situation.",
        },
        [10411] = {
            description = "Around the ruined manaforge you will find the run-off of Dimensius's handy " ..
                "work. Seeping sludge occupies the pools that surround Ultris. Directly below those " ..
                "pools, where the Ethereum Staging Grounds now stand, you will find even more run-off in " ..
                "the form of void waste.\n\nThe best method of disposal is to use electro-shock to break " ..
                "slimes down to globules. Use this elixir to augment your attacks with electricity. The " ..
                "resultant discharge will break the slimes up into their raw form. Destroy the globules!",
            rewardMoney = 132000,
        },
        [10412] = {
            description = "It is no secret that Kael'thas Sunstrider perceives us as a great threat. " ..
                "Let's face it - not many sin'dorei, fresh from Silvermoon, are willing to join the sort " ..
                "of company that Kael keeps.\n\nIt's also no secret that this is not just a war of words. " ..
                "Scryers and the armies that serve Kael'thas attack each other on sight. The only way to " ..
                "prove you're with us, <name>, is to do your share of fighting.\n\nKael's lower ranking " ..
                "followers wear Firewing signets to indicate their rank. Bring them to me.",
        },
        [10413] = {
            description = "You carefully fill a vial with the fallen void horror's ooze.\n\nResearcher " ..
                "Navuud at the Protectorate Watch Post would be quite interested in such a find! Take it " ..
                "to him at once!",
            rewardChoices = {{30338, 1}, {30339, 1}, {30340, 1}},
            rewardMoney = 88000,
        },
        [10416] = {
            description = "Arcane tomes are not ordinary books that happen to deal with arcane matters. " ..
                "There is intrinsic power in them - a power I've learned to synthesize into a single " ..
                "arcane rune.\n\nShould you find an arcane tome in your travels I will give you one such " ..
                "rune. Only the most powerful wielders of magic carry the books I need. In Outland this " ..
                "usually means Kael's blood elves - but you'd be surprised by where such tomes often turn " ..
                "up.",
            rewardItems = {{29736, 1}},
        },
        [10417] = {
            description = "Wherever the Consortium establishes a presence, we bring our eco-dome " ..
                "technology. The fields allow us to work in a controlled and life-sustaining atmosphere " ..
                "since we often find ourselves in hostile environments.\n\nNetherstorm 's volatile " ..
                "conditions and creatures have begun to destroy the equipment that sustains our domes, " ..
                "especially the generator east of here. I've started a diagnostic there in hopes of " ..
                "understanding what can be done to combat the damage. Would you collect the results and " ..
                "bring them to me?",
            rewardMoney = 39000,
        },
        [10418] = {
            description = "In searching the area for clues about the damage to our equipment, I've seen " ..
                "pieces of the shield generators at the bottom of the small lake to the north. I'm not " ..
                "sure why the crocolisks have taken an interest in the equipment, but we have to put a " ..
                "stop to this problem.\n\nThe Consortium is quite clear on this matter. If it comes down " ..
                "to a choice between the equipment and crocolisks, the animals will have to go. I'll make " ..
                "it worth your while to deal with them.",
            rewardMoney = 39000,
        },
        [10419] = {rewardItems = {{29736, 1}}},
        [10420] = {
            description = "This temple is one of the holiest places in all of Outland. The power of the " ..
                "Light here is so strong, that even items with the strongest fel taint can be cleansed of " ..
                "a worldly item.\n\nShould you run into any fel armaments in your confrontations with " ..
                "demonic enemies, bring them to me and I will demonstrate the cleansing power of the " ..
                "Light.",
            rewardItems = {{29735, 1}},
        },
        [10421] = {rewardItems = {{29735, 1}}},
        [10422] = {
            description = "Captain Tyralius took a platoon of soldiers south towards the Ethereum Staging " ..
                "Grounds 10 days ago. We haven't heard from him or his crew since.\n\nChances are good " ..
                "that they were ambushed and killed but I'm getting a curious reading from my " ..
                "instruments.\n\nI think it's a distress signal but these things have been wrong before. " ..
                "If Tyralius is still alive, they're keeping him in one of their prisons. You'll have to " ..
                "locate the prison and open it with a key, probably found on the warden.",
            rewardMoney = 132000,
        },
        [10423] = {
            description = "Master Engineer Ghabar will want to know about the results of the diagnostics. " ..
                "If anything, they caution us to keep a close eye on the workings of our dome generators. " ..
                "As the fields become more and more unstable, their effects will become harder to " ..
                "control. It could spell disaster for our expedition and anything else housed within the " ..
                "domes.\n\nYou'll find Ghabar at the Stormspire. Just follow the road north from this " ..
                "eco-dome and across the bridge. It'll lead you to the elevator at the base of the spire.",
        },
        [10424] = {
            description = "If Mehrdad's results are correct -- and I have no reason to believe they're " ..
                "faulty -- then the rest of the domes could be in trouble.\n\nI do think Mehrdad has " ..
                "failed to identify the underlying cause of the failures. From time to time, creatures " ..
                "damage the generators, but never this severely.\n\nTo be on the safe side, I'd like for " ..
                "you to run a set of diagnostics at the Stormspire's main dome generator, located in " ..
                "Eco-Dome Sutheron at the very eastern edge of the dome.",
            rewardMoney = 21000,
        },
        [10425] = {
            description = "Thank K'aresh! He would have torn me apart!\n\nI'm a Protectorate soldier, " ..
                "fleshling. My platoon was sent on a recon mission about 10 days ago. As we were moving " ..
                "across the upper ledges of this island, a group of Ethereum jumped us. At least I think " ..
                "it was Ethereum. They had the same energy color but their wrappings looked void.\n\nOnly " ..
                "Tyralius was spared. I think they put him in a prison cell.\n\nI've got to get back to " ..
                "the Protectorate Watch Post! Can you escort me back?",
            rewardChoices = {{30331, 1}, {30332, 1}, {30333, 1}, {30334, 1}},
        },
        [10426] = {
            description = "Just look around you, <class>! Isn't it amazing? Of course, this incredible " ..
                "resurgence of life is a byproduct of the ethereal domes, but imagine what it could do in " ..
                "the hands of the expedition.\n\nI'm preparing to negotiate with the ethereals for access " ..
                "to their technology, but I'd like to get a better idea of its effects on plant-based " ..
                "life.\n\nI've built a device to concentrate the dome's energies on the lashers in this " ..
                "area. Would you be so kind as to test it for me and share the results?",
            rewardMoney = 41000,
        },
        [10427] = {
            description = "Your work with the lashers turned up some astounding information, but I wonder " ..
                "if it holds true for animals as well.\n\nGathering information on the talbuks that live " ..
                "underneath this dome is going to be trickier than studying the lashers, I'm " ..
                "afraid.\n\nUsing this tagging device, you can put a weakened talbuk to sleep and apply a " ..
                "tag that I'll use to track the animal as it matures. The tagging mechanism won't work " ..
                "unless the talbuk has expended most of its energy.",
            rewardMoney = 41000,
        },
        [10428] = {
            description = "In the fevered dreams of our injured guest, she spoke of a fisherman, Cowlen, " ..
                "who was in some distress at Silvermyst Isle, to the southwest, off the coast of " ..
                "Azuremyst.\n\nWith all that has been happening, no one has had the opportunity to look " ..
                "into it, but I do feel a bit of worry. Perhaps there's something you can do, <name>?",
        },
        [10429] = {
            description = "The dome technology possesses such power! Certainly, there are bounds beyond " ..
                "which we dare not go, <name>.\n\nCreatures allowed to grow too large or too fast could " ..
                "be just as bad as a barren landscape.\n\nI have heard rumors of just such a creature in " ..
                "the pool to the east. I've heard the ethereal merchants conspiring to catch the " ..
                "overgrown hydra for sport, but I have another purpose in mind for the giant. Bring me " ..
                "the creature's heart so I may study it.",
            rewardMoney = 41000,
        },
        [10430] = {
            description = "I've been working on a portable generator repair kit for use in some of the " ..
                "harsher climates that the Consortium operates in. Granted, it wasn't designed for " ..
                "Netherstorm, but we shouldn't have any problems with it.\n\nI had already scheduled a " ..
                "test with one of my best techs up at Eco-Dome Farfield beyond the Netherstone to the " ..
                "northeast. Take this prototype to Tashar. He'll know what to do with it. If it works, we " ..
                "can use it to reinforce the shield generators at the larger domes.",
        },
        [10431] = {
            description = "The Sunfury briefings support the theory that Kael'thas has been receiving " ..
                "outside help in constructing and running these manaforges. Who this is remains a bit of " ..
                "a mystery, though we're likely to find out in Manaforge Ara.\n\nI've sent a group of my " ..
                "men to scout the surrounding area. Go to Tuluman's Landing, north of here, and speak to " ..
                "Kaylaan. See what he's discovered at Manaforge Ara. Find out who is assisting the " ..
                "Sunfury army and take care of them.",
        },
        [10432] = {
            description = "As you may have noticed, there are servants of the Burning Legion all over " ..
                "Manaforge Ara. Kael'thas has entered an alliance with the Burning Legion. He must've " ..
                "caught wind of Illidan's descent into insanity and switched paymasters " ..
                "accordingly.\n\nIf the Scryers get definite proof of this, it will give them a " ..
                "considerable political advantage. I know for a fact that the Legion forces at this " ..
                "manaforge have orders that bear Kael's seal.\n\nGet these orders and bring them to " ..
                "Thalodien.",
        },
        [10433] = {
            description = "The ethereals are clever and very observant, so it's no accident that I'm here " ..
                "posing as a simple furrier. In fact, I've been sent from Area 52 to appraise the " ..
                "technology the ethereals use to generate their eco-domes.\n\nI'd like to enlist your " ..
                "help, <class>. We've been asked to use non-goblin agents whenever possible.\n\nWhat I " ..
                "want you to do is bring me a number of ripfang lynx pelts in the guise of a hunter. You " ..
                "can find the lynxes all over Eco-Dome Midrealm.",
            rewardMoney = 41000,
        },
        [10434] = {
            description = "Excellent job.\n\n<Shauly winks at you.>\n\nI think they're buying it. Now, " ..
                "when I send you up to speak with my associates at the Stormspire, there won't be any " ..
                "suspicion at all.\n\nYou'll want to look for Action Jaxon and Audi the Needle up there. " ..
                "They'll tell you everything you need to know. Tell 'em Shauly sent you.",
        },
        [10435] = {
            description = "<Audi looks around and then lowers her voice.>\n\nI'm sure Shauly told you a " ..
                "bit about our work here. When Jaxon and I are out in the field 'hunting,' we've been " ..
                "collecting pieces of the ethereal eco-dome generators and hiding them in the nests of " ..
                "our prey, the raptors in Eco-Dome Farfield.\n\nIt's a remote area to the northeast of " ..
                "the Stormspire, close to the Netherstone. I don't anticipate you'll run into many " ..
                "ethereals there, but would you be willing to help us collect the dome generator pieces?",
            rewardChoices = {{30284, 1}, {30285, 1}, {30286, 1}, {30402, 1}},
            rewardMoney = 41000,
        },
        [10436] = {
            description = "Before we can begin the test, we have to make certain the area is clear of " ..
                "anything that might interfere. In our case, that means these overgrown lizards.\n\n< " ..
                "Tashar gestures toward the scythetooth raptors.>\n\nThere's no telling what might happen " ..
                "if one of those decides to take a nice bite out of the generator while it's charging. " ..
                "I've seen a lot of strange things in all my years as a technician, including more than a " ..
                "few abominations that had their beginnings as humble animals.",
            rewardMoney = 41000,
        },
        [10437] = {
            description = "Atop Manaforge Ultris lies the tear in the nether that the void lord, " ..
                "Dimensius, came through. That tear provides Dimensius with a link to the void, rendering " ..
                "him immune to physical harm. If we can get a lock on the conduit that Dimensius is using " ..
                "to keep himself phased out of this plane of existence, we can destroy it and then " ..
                "destroy Dimensius.\n\nTo do this, we're going to first need you to collect fragments of " ..
                "Dimensius from the void creatures that he sends out to do his dirty work.",
        },
        [10438] = {
            description = "Here it is, <name>. Take this phase disruptor and mount up! The Protectorate " ..
                "nether drake will fly you close enough to Ultris so that you can drop the disruptor on " ..
                "top of the void conduit.\n\nDrop as many disruptor charges as possible to ensure " ..
                "complete annihilation!\n\nWhen you are ready, speak with the nether drake and he'll take " ..
                "you up.\n\nIf you miss the mark you will have to get more bombs from me before you can " ..
                "go up again.",
        },
        [10439] = {
            description = "Your brave actions have forced Ameer to react! He has deployed Captain Saeed " ..
                "and the Avengers!\n\nNow all that is left to do is destroy Dimensius.\n\nWhen you are " ..
                "ready, I will call for Saeed. If he is not currently fighting another battle, he will be " ..
                "awaiting orders from you - directly east of here.\n\nLet him know when you are ready to " ..
                "fight and he will put his troops in motion!\n\nI wish you luck, fleshling! We have " ..
                "hunted Dimensius for a thousand years!",
            rewardChoices = {{30297, 1}, {30298, 1}, {30299, 1}, {30300, 1}},
            rewardMoney = 132000,
        },
        [10440] = {
            description = "The test was a resounding success! We can certainly use this device to start " ..
                "repairing the domes.\n\nCarry word of the test results to the Stormspire and let Ghabar " ..
                "know that I've also found a pattern in the damage to the shield generators. Key pieces " ..
                "of generator units have gone missing from a number of sites. This is no accident, " ..
                "<name>, no technological failure. We're being stolen from.",
            rewardChoices = {{30290, 1}, {30291, 1}, {30520, 1}, {30293, 1}},
        },
        [10442] = {
            description = "<class>, there's some tauren by the name of Thiah Redmane that keeps pestering " ..
                "us for assistance. She's with the Cenarion Expedition, and they've setup a little post " ..
                "just to the west on the south side of the road leading to Zangarmarsh.\n\nIf you hit " ..
                "Thornfang Hill, you've gone too far.\n\nDo you think you might head over there and see " ..
                "what she needs? I don't want to have to bother Ranger Captain Venn'ren with such " ..
                "trivialities.",
        },
        [10443] = {
            description = "The Cenarion Circle has sent an expedition to Outland and, as I understand it, " ..
                "they are here to study what has happened and to help reverse any damage that they " ..
                "can.\n\nThey've setup a little post just to the west on the south side of the road " ..
                "leading to Zangarmarsh.\n\nIf you hit Thornfang Hill, you've gone too far.\n\nWould you " ..
                "please go and see how you might help them? Speak with Thiah Redmane as she is the one " ..
                "that sent the request to us for assistance.",
        },
        [10444] = {
            description = "This calls for immediate action!\n\nWe have someone out in the field closer to " ..
                "Firewing Point that I want you to speak with. He'll have a better idea of what our next " ..
                "step should be.\n\nReport to Lieutenant Meridian out at the Allerian Post and apprise " ..
                "him of the situation. You'll find the post to the northeast on the southern bank of the " ..
                "river just south of Firewing Point.\n\nGodspeed, <name>.",
        },
        [10446] = {
            description = "They're building a second mana bomb in the courtyard. My intel suggests that " ..
                "the final code for the bomb is being held by Sharth Voldoun, the overseer of the project " ..
                "at Firewing Point.\n\n<name>, you have to go back in there and retrieve the final code " ..
                "from him. He keeps himself to the top of the highest spire.\n\nTake the final code to " ..
                "the mana bomb that they're working on in the central courtyard and set it off.\n\nOnly " ..
                "then will we be certain that the Allerian Stronghold is safe.",
            rewardChoices = {{31782, 1}, {31783, 1}, {31784, 1}, {31785, 1}},
            rewardMoney = 66000,
        },
        [10447] = {
            description = "They're building a second mana bomb in the courtyard. My intel suggests that " ..
                "the final code for the bomb is being held by Sharth Voldoun, the overseer of the project " ..
                "at Firewing Point.\n\n<name>, you have to go back in there and retrieve the final code " ..
                "from him. He keeps himself to the top of the highest spire.\n\nTake the final code to " ..
                "the mana bomb that they're working on in the central courtyard and set it off.\n\nOnly " ..
                "then will we be certain that Stonebreaker Hold is safe.",
            rewardChoices = {{31782, 1}, {31783, 1}, {31784, 1}, {31785, 1}},
            rewardMoney = 66000,
        },
        [10448] = {
            description = "This calls for immediate action!\n\nWe have someone out in the field closer to " ..
                "Firewing Point that I want you to speak with. She'll have a better idea of what our next " ..
                "step should be.\n\nReport to Sergeant Chawni out at Stonebreaker Camp and apprise her of " ..
                "the situation.\n\nTake the road north out of the hold. From the middle of Tuurem, follow " ..
                "the road to the east. You'll find the camp on the bank of the river that lies just " ..
                "southwest of Firewing Point.\n\nGood luck, <name>.",
        },
        [10449] = {
            description = "Apethecary Zelana has been studying the beasts of Hellfire Peninsula in the " ..
                "field. She wants a sample of the blood you gathered; with luck, she might discover what " ..
                "turned those Bonechewer freaks' skins red!\n\nZelana is at Reaver's Fall, southeast of " ..
                "Thrallmar. Follow the road east and when you see a destroyed, green-glowing hunk of " ..
                "metal, you're there. She has a camp set up behind the wyverns.",
            rewardMoney = 2300,
        },
        [10450] = {
            description = "Bonechewers! They should all die! The sight of their red skin and depravity " ..
                "makes my blood boil!\n\nI have a mission for you, <name>. Kill Bonechewer orcs and " ..
                "collect their vile blood. There is an apothecary who needs the blood for her tests, so " ..
                "we can discover how these orcs fell to the demon taint, a taint from which we so " ..
                "recently freed ourselves.\n\nBonechewers scavenge near the ruined battlements along the " ..
                "Path of Glory, to the south. Return to me when your mission is complete.",
            rewardChoices = {{29914, 1}, {29915, 1}, {29916, 1}, {29917, 1}, {29919, 1}},
            rewardMoney = 9000,
        },
        [10451] = {
            description = "Thank the Earthmother! I parted ways with the others several days ago. I was " ..
                "intent on discovering the source of the disturbance that the spirits of water were " ..
                "feeling. My search led me to Coilskar where I discovered that the naga were befouling " ..
                "the water supply of Shadowmoon Valley.\n\nUnfortunately, I was discovered and taken " ..
                "prisoner. There's no telling what ghastly things they had in store for me.\n\nWe must " ..
                "leave this place! Help me escape and then seek out Torlok at the Altar of Damnation.",
            rewardChoices = {{30927, 1}, {30937, 1}, {30952, 1}, {30968, 1}},
            rewardMoney = 132000,
        },
        [10455] = {
            description = "We've been growing the Living Grove at an accelerated rate, but somehow the " ..
                "lynxes there have become lost to our control.\n\nWhere once their population was stable, " ..
                "the grovestalker lynxes are now beginning to encroach upon Sylvanaar, and there have " ..
                "been a number of unpleasant incidents of late.\n\nI suspect that the arakkoa of Veil " ..
                "Lashh are somehow behind it, but the immediate issue is with the lynxes themselves.\n\nI " ..
                "would be most grateful if you would help us to deal with this situation.",
            rewardMoney = 35000,
        },
        [10456] = {
            description = "The filthy races of the Horde have taken over a settlement to the east. " ..
                "They've brought with them a large pack of the dire wolves that they prefer to use as " ..
                "mounts and sentries.\n\nThese sentries have been marauding across the bridge that " ..
                "separates us. They've been stalking our fey drakes, which are critical to the " ..
                "pollination of the Living Grove.\n\nUse the east exit to traverse the bridge over " ..
                "Bloodmaul Ravine that leads to the Jagged Ridge to the east, and bring me their tails as " ..
                "proof!",
            rewardMoney = 35000,
        },
        [10458] = {
            description = "We must try and make amends. We must commune with the elements of this region " ..
                "and see if anything can be done!\n\nI grant you the totem of spirits, <race>. If you " ..
                "slay an enraged elemental spirit in close proximity of the totem, it will consume the " ..
                "elemental's soul. You must use the totem to consume many souls before you may return to " ..
                "me.\n\nDo this for the spirits of fire and earth first. Return to me when the totem is " ..
                "full.",
        },
        [10460] = {rewardItems = {{29294, 1}}},
        [10461] = {rewardItems = {{29307, 1}}},
        [10462] = {rewardItems = {{29298, 1}}},
        [10463] = {rewardItems = {{29302, 1}}},
        [10466] = {
            description = "You've made your pledge, <class>. Now it is up to you to see it " ..
                "through.\n\nServe the Scale of the Sands well and you will be rewarded. Fail and the " ..
                "timeline as we know it will be unravelled!",
            rewardItems = {{29299, 1}},
        },
        [10468] = {
            description = "You've carried out the promise you made to us, <name>. And for that you've " ..
                "gained the recognition you deserve.\n\nAs you continue to become attuned with past " ..
                "events surrounding mount Hyjal, I can continue to tap into the power contained in your " ..
                "ring. It won't be long until it has reached its full potential.",
            rewardItems = {{29304, 1}},
        },
        [10471] = {
            description = "You've carried out the promise you made to us, <name>. And for that you've " ..
                "gained the recognition you deserve.\n\nAs you continue to become attuned with past " ..
                "events surrounding mount Hyjal, I can continue to tap into the power contained in your " ..
                "ring. It won't be long until it has reached its full potential.",
            rewardItems = {{29296, 1}},
        },
        [10475] = {
            description = "Your accomplishments have gone beyond my greatest expectations, <name>.\n\nYou " ..
                "step in and out of time as comfortably as any bronze dragon I've known. You are destined " ..
                "for great power and I am more than pleased to help you on your way there.\n\nContinue to " ..
                "serve the Scale of the Sands and I will unleash your gift's full potential.",
            rewardItems = {{29297, 1}},
        },
        [10476] = {
            description = "If you seek to prove your loyalty to us, there is no better way than to fight " ..
                "against our enemies.\n\nOf these, there are none that can match the ogres in strength " ..
                "and fierceness. Bring me the warbeads they wear around their necks as proof of their " ..
                "demise and I'll let the others know of your prowess.",
        },
        [10479] = {
            description = "Though we seek a peaceful life, our enemies are many. Of these, none match the " ..
                "ogres in sheer brute power.\n\nIf you seek to prove your prowess to us, bring me the " ..
                "warbeads they wear around their necks. I will tell others of your accomplishments.",
        },
        [10480] = {
            description = "The Illidari naga of the region have taken control of the only clean water " ..
                "supply that exists in Shadowmoon Valley.\n\nDirectly north of here you will find the " ..
                "lair of the naga: Coilskar. Around Coilskar are pockets of agitated water that howl to " ..
                "the land in anguish. It is at those pockets that the enraged spirits of water now " ..
                "wander.\n\nTravel to Coilskar and use the totem of spirits to capture watery souls. You " ..
                "will find the largest concentration of these spirits near Coilskar Cistern.",
        },
        [10481] = {
            description = "Venture southeast, hero. When you see fields of gigantic blue crystals jutting " ..
                "out from the land, you will have reached your destination. It is there, at the " ..
                "Netherwing Fields, that you will find the enraged spirits of air. They roam the cliffs " ..
                "and mountain bases that surround the fields.\n\nDestroy their tortured forms and capture " ..
                "their souls with the totem of spirits. Return to me when this is done.",
            rewardChoices = {{30930, 1}, {30942, 1}, {30953, 1}, {30964, 1}},
        },
        [10482] = {
            description = "Scavengers, orcs of the Bonechewer clan, skulk about the ruined battlements " ..
                "overlooking the Path of Glory. We must assume that these fel orcs are gathering war " ..
                "machine parts for their masters within Hellfire Citadel--they must be stopped!\n\nFind " ..
                "Bonechewer orcs to the north, <name>. Find them and slay them! But use caution, for " ..
                "although these orcs are the lesser of the fel clans, their strength is the match of any " ..
                "orc we've faced thus far.",
            rewardChoices = {{29914, 1}, {29915, 1}, {29916, 1}, {29917, 1}, {29919, 1}},
            rewardMoney = 9000,
        },
        [10483] = {
            description = "<name>, in our battles with the Bleeding Hollow clan of fel orcs, we have " ..
                "found upon them foreboding trinkets. These orcs have collected the insignias of fallen " ..
                "Honor Hold soldiers and created cursed talismans from them. We fear the dark magic of " ..
                "the Bleeding Hollow orcs have transformed our insignias into evil charms with powers " ..
                "against us!\n\nFind such a talisman from the Bleeding Hollow orcs of Zeth'Gor, to the " ..
                "east, and bring it to Corporal Ironridge at Expedition Point, northeast of Zeth'Gor.",
        },
        [10484] = {
            description = "<name>, we cannot allow the Bleeding Hollow orcs to possess their cursed " ..
                "talismans! You must acquire them for us so they may be disposed of, and so the soldiers " ..
                "who owned them may be honored for their sacrifices.\n\nGo to Zeth'Gor, the cursed abode " ..
                "of the Bleeding Hollow, and perform your grim task... return to me when you have " ..
                "collected the talismans.",
            rewardMoney = 9000,
        },
        [10485] = {
            description = "You have shown great strength and fortune, for you have delved into Zeth'Gor " ..
                "and lived! Now, let us hope your fortune holds, for I have a dire task to ask of " ..
                "you...\n\nWarlord Morkh sits within the barracks of Zeth'Gor, commanding his fel troops " ..
                "against us. His tactics are as clever as they are cruel, and I must admit that his " ..
                "successes against us have cut deep. And so, <name>, I ask you to remove Morkh from his " ..
                "seat. Bring me his armor so that we might display it for our soldiers and bolster them.",
            rewardMoney = 9000,
        },
        [10486] = {
            description = "The Thunderlord were once a proud orc clan before they were transformed into " ..
                "fel orcs through the blood of Mannoroth.\n\nRecently we recovered this orc stronghold " ..
                "from the ogres that infest the ravine below. They had moved in when the Thunderlord clan " ..
                "abandoned it.\n\nWe will keep this place and I will have your help doing so.\n\nIn the " ..
                "Jagged Ridge to the south and the west, there are bloodletters that have become like a " ..
                "plague upon us. They eat and breed incessantly.\n\nKill them and then return to me.",
            rewardMoney = 35000,
        },
        [10487] = {
            description = "The Alliance has recently moved in to the west, using their elven magics to " ..
                "grow a town and grove in a short matter of time. We must keep their defenses weak so " ..
                "that they do not also grow a spine.\n\nI have a plan that will do that and more. I want " ..
                "you to traverse the bridge to the southwest, which crosses over Bloodmaul Ravine and " ..
                "leads into the Living Grove.\n\nAttack their fey drake defenses in the Living Grove and " ..
                "bring back the magical dust that sometimes can be found upon their wings.",
            rewardMoney = 35000,
        },
        [10488] = {
            description = "With the magical dust you recovered, I have fashioned a magic ointment that " ..
                "will aid in our own defenses.\n\nOur dire wolves are the perfect combination of mount, " ..
                "sentry and friend, but the Alliance scum have been poaching them in the Jagged " ..
                "Ridge.\n\n<name>, I want you to take this ointment and apply it to our dire wolf " ..
                "friends. The Alliance will get a rude surprise the next time that they send one of their " ..
                "hunting parties.\n\nBe aware though that some of the wolves may not like this, and will " ..
                "turn on you.",
            rewardChoices = {{31481, 1}, {31482, 1}, {31483, 1}, {31484, 1}},
            rewardMoney = 35000,
        },
        [10489] = {
            description = "WANTED!\n\nStronglimb Deeproot, ancient of war and chief defender of the " ..
                "Living Grove south of Sylvanaar.\n\nFind him by heading west across the bridge that " ..
                "traverses the Bloodmaul Ravine.\n\nReturn his hewn trunk to Tor'chunk Twoclaws.",
            rewardChoices = {{31485, 1}, {31486, 1}, {31487, 1}, {31488, 1}},
            rewardMoney = 35000,
        },
        [10502] = {
            description = "There is a threat to Sylvanaar far deadlier than the Horde at Thunderlord " ..
                "Stronghold.\n\nI'm speaking of the native ogres of these mountains. Just to the south " ..
                "and east, down in the ravine, lives the Bloodmaul clan. While they aren't the only group " ..
                "of ogres that threaten us here, they are the closest.\n\nI would have you head south " ..
                "through the Living Grove, and then go down the path to the east, which leads to their " ..
                "outpost. Slay as many of the Bloodmaul ogres at Bloodmaul Outpost as you can.",
            rewardMoney = 35000,
        },
        [10503] = {
            description = "There is a threat to Thunderlord Stronghold worse than the Alliance at " ..
                "Sylvanaar.\n\nI speak of the ogres of these mountains. Just to the west, down in the " ..
                "ravine, lies the Bladespire clan. While they aren't the only ogres, they are the closest " ..
                "and they're the ones that we defeated to take this place.\n\nHead north through the " ..
                "Jagged Ridge, and then down the path, which leads to their hold. Slay as many of the " ..
                "Bladespire ogres and their raptors as you can at Bladespire Hold and the Bladespire " ..
                "Grounds.",
            rewardMoney = 70000,
        },
        [10505] = {
            description = "To the south of the Bladespire clan lies yet another threat: Bloodmaul " ..
                "Outpost.\n\nWhile the Bloodmaul ogres are not the strongest clan in the mountains, not " ..
                "having the favor of the gronn known as Gruul the Dragonkiller, they run a close " ..
                "second.\n\nNow that we've dealt with winnowing the Bladespire, it is time to turn our " ..
                "eye upon their rivals.\n\nFrom Bladespire Hold head south through the ravine until you " ..
                "come to Bloodmaul Outpost. Slay as many of the Bloodmaul ogres in the vicinity as you " ..
                "can.",
            rewardChoices = {{31477, 1}, {31478, 1}, {31479, 1}, {31480, 1}},
            rewardMoney = 35000,
        },
        [10506] = {
            description = "With their wolf pack reduced, the Horde is looking for replacements. " ..
                "Unfortunately there's another source nearby.\n\nThe Bloodmaul ogres in the ravine below " ..
                "to the east keep a strong pack as their own sentries. I hated sending you to kill the " ..
                "Thunderlord wolves, so why don't we do something different this time?\n\nI've derived a " ..
                "magic powder from the dust that naturally falls off the wings of our fey drakes. " ..
                "Sprinkle it on the Bloodmaul dire wolves to make them undesirable to the Horde.",
            rewardMoney = 35000,
        },
        [10507] = {
            description = "This is the chance we've been waiting for, <name>. Not only have we uncovered " ..
                "the evidence we need to show our people who Kael'thas is really working for, but we can " ..
                "prove our strength by defeating his new masters.\n\nMy frail health prevents me from " ..
                "aiding you in person with this endeavor, but I will offer you an object that will allow " ..
                "me to project my powers across the continent.",
            rewardChoices = {{30372, 1}, {30373, 1}, {30374, 1}, {30375, 1}, {30859, 1}},
            rewardMoney = 132000,
        },
        [10508] = {
            description = "I don't want to send you to Voren'thal empty-handed. It's not in my style to " ..
                "be underwhelming.\n\nTo gain access to Socrethar's Seat in the north, we'll need to use " ..
                "his own teleporters - locked by Socrethar's teleportation stone. The first half of the " ..
                "stone is in the possession of Forgemaster Morug at Forge Base Oblivion. The second half " ..
                "is held by the demon Silroth at Forge Base: Gehenna.\n\nObtain these and Voren'thal will " ..
                "be impressed beyond words.",
            rewardMoney = 44000,
        },
        [10509] = {
            description = "Now I can properly send you back to Shattrath City. You've uncovered evidence " ..
                "of Kael'thas making pacts with the Burning Legion and you've got the key to the " ..
                "overlord's back door.\n\nMake sure Voren'thal doesn't topple over with excitement from " ..
                "the news - the old man's getting a bit fragile, if you know what I mean. You'll find him " ..
                "inside the Seer's Library at the Scryer's Tier.",
        },
        [10510] = {
            description = "Well it's good to see someone who's willing to help out around " ..
                "here!\n\nBorgrim and I are part of the Explorers' League, and we're here to learn what " ..
                "we can of these mountains. We've heard all sorts of tales, and I can't wait to get " ..
                "settled in and started.\n\nOne thing in particular has caught my attention. The night " ..
                "elves speak of a place down in the ravine to the east known as the Draenethyst Mine. " ..
                "It's at the south end of Bloodmaul Outpost. I'd like some of the crystals that grow " ..
                "naturally therein.",
            rewardChoices = {{31429, 1}, {31430, 1}, {31431, 1}, {31432, 1}},
            rewardMoney = 35000,
        },
        [10511] = {
            description = "If I'm going to start this vacation out right, then I'm going to need more " ..
                "brew. Unfortunately, the elves know nothing of the fine art of fermentation.\n\nI " ..
                "overheard that the Bloodmaul ogres down in the ravine have plenty. I'm willing to give " ..
                "it a try.\n\nDo me a favor? Head south through the Living Grove and then down the ramp " ..
                "to the east into Bloodmaul Outpost and procure me some? I hear they have big barrels of " ..
                "it laying around and that their brewmasters carry it around to all the other ogres.",
            rewardMoney = 35000,
        },
        [10512] = {
            description = "I'll not take another sip of that ill-smelling muck! But it does give me an " ..
                "idea.\n\n<Borgrim gets a twinkle in his eye.>\n\nSo here's the plan. We know that the " ..
                "Bloodmaul practically live off of this swill. But I wonder what their enemies, the " ..
                "Bladespire ogres, think of it?\n\n<name>, I want you to take the rest of this rubbish " ..
                "and see if you can get the Bladespire ogres tanked. You can find them by heading north " ..
                "from Bloodmaul Outpost through the ravine.",
            rewardMoney = 35000,
        },
        [10513] = {
            description = "I do not know how we can acquire the spell that the spirits mentioned, <name>. " ..
                "Truth be told, I don't even know where we would start such a search.\n\n<Torlok stares " ..
                "off in the distance, lost in thought.>\n\nHrm... It is a long shot but it might be our " ..
                "only chance. There is an orc that I have seen visit this area before. I spoke to him " ..
                "briefly once. He is a hermit that claims to live above Coilskar Cistern to the " ..
                "northeast. Seek out this orc, Oronok Torn-heart.\n\nAs I said, it is a long shot.",
        },
        [10514] = {
            description = "I've been a lot of things, stranger, but what I once was isn't what's " ..
                "important. What I am now is what matters and what I am now is a farmer.\n\nI use trained " ..
                "felboars to dig up tubers from the hardened earth of the Shattered Plains. Recently, " ..
                "though, flayers from a nest to the northeast have been attacking my animals, preventing " ..
                "me from gathering tubers.\n\nWould you go to the area north of here and gather tubers " ..
                "for me? Use this whistle while standing on a tuber mound and a boar will come dig one up!",
            rewardChoices = {{30357, 20}, {30358, 20}, {30359, 20}, {30361, 20}},
        },
        [10515] = {
            description = "We need to show those flayers what happens when you mess with Oronok's " ..
                "business!\n\nI want you to go back to the Shattered Plains and destroy every flayer egg " ..
                "that you see. They'll be deep in flayer territory so keep your guard up.",
        },
        [10516] = {
            description = "I know it's strange, but I do want to stay in this cage. It gives me the " ..
                "perfect opportunity to do what I came here for; to gather information on the " ..
                "Bladespire.\n\nI can leave at any time, but I would like to have my sword and shield " ..
                "back.\n\nTwo of their leaders have my trappings. Droggam has my sword and Mugdorg has my " ..
                "shield.\n\nIf you have need, obtain and use the brew from Bloodmaul Outpost to the south " ..
                "to thin out their help and entice those two, but beware their sober guards who don't " ..
                "drink!",
            rewardMoney = 35000,
        },
        [10517] = {
            description = "The leader of Bladespire Hold is known as Gorr'Dim. Trust me... the name is " ..
                "appropriate.\n\nStill, I wouldn't underestimate him. He's crafty enough to have elevated " ..
                "his clan to be the favorite of Gruul the Dragonkiller and they now dominate these " ..
                "mountains. And Gorr'Dim keeps an entourage about him at all times, including defenders " ..
                "who are sworn not to drink the Bloodmaul brew.\n\nFor the safety of Sylvanaar, I'm " ..
                "asking that you go back in there and deal with him.",
            rewardMoney = 37000,
        },
        [10518] = {
            description = "I want you to steal the Bladespire banner from one of their champions and take " ..
                "it south to Bloodmaul Outpost. Plant it atop their Northmaul Tower.\n\nThis will " ..
                "infuriate the Bloodmaul and they will attack you relentlessly. But it will also keep " ..
                "their hatred focused on Bladespire Hold, and away from Sylvanaar.\n\nYou will know you " ..
                "have accomplished the deed when you have defeated Gurn Grubnosh and taken his helm. " ..
                "Return it to Sylvanaar.\n\n<name>, this isn't going to be easy. Take a friend or two " ..
                "with you.",
            rewardChoices = {{31433, 1}, {31434, 1}, {31435, 1}, {31436, 1}},
            rewardMoney = 74000,
        },
        [10519] = {
            description = "<Oronok adjusts his posture and stands to his full height.>\n\nI had to be " ..
                "sure, <name>. And to be sure, I had to test you. Please excuse the little masquerade. I " ..
                "am as much a farmer as you are a felboar. Which is to say, not at all.\n\nIf you are to " ..
                "recover the Cipher of Damnation, you will need to listen to what I have to tell you. " ..
                "When you are ready, let me know and I will tell you the story.",
        },
        [10521] = {
            description = "My first born, Grom'tor, left to search Coilskar Point - directly southwest of " ..
                "here.\n\nHe's the warrior in the family - ill-tempered and blood-thirsty... Traits he " ..
                "inherited from his mother. Search along the outskirts of Coilskar Point. If you see naga " ..
                "corpses, Grom'tor is sure to be close.\n\nWhen you find him, tell him this: \"We spill " ..
                "blood for just cause.\" It will let him know that you are a friend to Torn-heart and " ..
                "prevent your premature death.",
        },
        [10522] = {
            description = "This naga filth is the sixth one I've interrogated today. He's got the fancy " ..
                "armor so I figured he knew something. Those other ones were useless.\n\n<Grom'tor points " ..
                "to the corpses of the naga around him.>\n\nI only had to beat him once and he told me " ..
                "everything.\n\nThe first part of the cipher is hidden in a naga chest at Coilskar Point " ..
                "or Coilskar Cistern, east of here. He says naga carry the keys. Kill 'em, take their " ..
                "keys and use them to open the Coilskar chests. Return to me when you find the cipher.",
        },
        [10523] = {
            description = "<Grom'tor wraps the documents up and places them in a lockbox.>\n\nTake this " ..
                "box to father. He awaits your return at the farm, northeast of here.\n\nTell him that I " ..
                "will be home soon. As soon as I am done having my fun...",
            rewardChoices = {{30923, 1}, {30945, 1}, {30956, 1}, {30981, 1}},
        },
        [10524] = {
            description = "The artifact bears markings that indicate its origins as being created by the " ..
                "Thunderlord clan orcs. These orcs used to live at Thunderlord Stronghold before they " ..
                "were changed into fel orcs.\n\nFor a time the Bladespire ogres inhabited the stronghold " ..
                "until recently when the Horde pushed them out.\n\nYou've heard of other artifacts that " ..
                "were lost. A drum, an arrow and a tablet come to mind as objects that you know are being " ..
                "sought after.\n\nFind them in Bladespire Hold and return them to Rokgar Bloodgrip.",
            rewardMoney = 35000,
        },
        [10525] = {
            description = "<race> fool. You almost destroyed the drum!\n\nI've worked too hard to get " ..
                "here, and my hands have been empty up until now. At least you were able to succeed where " ..
                "the others only met with failure, or worse.\n\nIt is time to evoke a vision that will " ..
                "lead you to the last relic that I have been seeking.\n\nTake this fiery fragment of my " ..
                "soul. Use it to transform your body into flame and denature your spirit into a vision " ..
                "guide that will shoot forth to reveal the location of the final Thunderlord relic.",
        },
        [10526] = {
            description = "If the vision that I granted you is true, then you must travel down into the " ..
                "ravine and to the south end of Bloodmaul Ravine. There you will find the Draenethyst " ..
                "Mine.\n\nJourney to the back of the mine, and retrieve the Thunderspike. Ignore " ..
                "everything else! I have no interest in the crystals of the mine, nor the ogres " ..
                "therein.\n\nAs soon as you have the spear return it to me here!\n\nAnd, <name>, be very " ..
                "careful with it... I would hate to think what would happen to you should you break it.",
            rewardChoices = {{31474, 1}, {31475, 1}, {31476, 1}},
            rewardMoney = 74000,
        },
        [10527] = {
            description = "My youngest son, Ar'tor, left to search Illidari Point - far to the southwest, " ..
                "nestled between Legion Hold and Wildhammer Stronghold.\n\nWhile Ar'tor is a hunter of " ..
                "remarkable skill and an expert tracker, I fear that he may be in over his head this " ..
                "time. Illidari Point is the proving grounds for Illidan's demons. These are demons that " ..
                "left the Burning Legion to join the Betrayer!\n\nTravel to Illidari Point and find " ..
                "Ar'tor, <name>.",
        },
        [10528] = {
            description = "From assessing the scene, you note that Ar'tor is being held in place by " ..
                "energy beams emanating from the crystals hovering around the rune. Try as you might, " ..
                "Ar'tor is unmovable.\n\nYou note that the crystals have an empty slot at their base - " ..
                "perhaps for a key. It also seems as if succubi periodically perform some sort of ritual " ..
                "at the site.\n\nSearch Illidari Point for their leader. Perhaps she holds the key to " ..
                "releasing Ar'tor.",
        },
        [10537] = {
            description = "It is a sign, <name>. Even in death, I cannot be stopped. Recovering a part of " ..
                "the Cipher of Damnation is my destiny. With your help, that destiny will be " ..
                "fulfilled.\n\nBefore we embark on that journey, I must have my longbow, Lohn'goron. It " ..
                "is a family heirloom that has been handed down from Torn-heart to Torn-heart for " ..
                "generations.\n\nMy instinct tells me that a demon stole it from my corpse. Kill the " ..
                "demons here until you find my bow.",
        },
        [10538] = {
            description = "That last experiment was not a complete loss -- I did save a small bit of the " ..
                "blood you brought me. Now boiled down, it should be free of whatever curses the Bleeding " ..
                "Hollow witches placed on their people's blood.\n\nI need more for study. Go gather " ..
                "Bleeding Hollow blood from the orcs in Zeth'Gor. When you've gathered the blood, bring " ..
                "it to their cursed cauldron and boil it. Bring me the boiled blood.",
            rewardMoney = 9000,
        },
        [10540] = {
            description = "At last, we are ready. I will bestow a piece of my spirit upon you, hero. It " ..
                "will guard you and help you in your battle against evil.\n\nYou must then travel south " ..
                "of here towards the back of Illidari Point. Hidden in the ether is a vile creature known " ..
                "as Veneratus the Many. My spirit hunter will call him out when he is near.\n\nDestroy " ..
                "Veneratus and take from his corpse the second part of the Cipher of Damnation.",
        },
        [10541] = {
            description = "I thank you, hero. For without you, my spirit would forever remain in this " ..
                "cursed place.\n\n<Ar'tor hands you a spectral lockbox.>\n\nTake it and deliver it to my " ..
                "father at the farm, far to the northeast, above Coilskar Cistern... Inside are " ..
                "Lohn'goron and the second part of the cipher.\n\nHe will be sad to hear news of my " ..
                "death. Promise me that you will assure him that I died a free soul. Tell him that I see " ..
                "the hunting grounds and they are glorious. Tell him that I wait for him there...",
            rewardChoices = {{30931, 1}, {30936, 1}, {30957, 1}, {30959, 1}, {30971, 1}},
        },
        [10542] = {
            description = "T'chali used to be a pretty friendly troll. Me come down here to teach the " ..
                "Bloodmaul how to brew their beer. But once me do that, the Bloodmaul bury T'chali and " ..
                "leave him here to rot!\n\nThe worst part of it was that they stole me hookah!\n\nSo, you " ..
                "want to help T'chali? You bring me hookah back. T'chali think the ogres that stole it " ..
                "headed southwest over by the mine.\n\nAnd while you're in there, pick up some brews, too!",
            rewardMoney = 35000,
        },
        [10543] = {
            description = "T'chali has been waiting for his revenge!\n\nThe day they bury T'chali and " ..
                "leave him to die, it was Grimnok Battleborn that led them. And the next day it was " ..
                "Korgaah that come south to raid and kick T'chali in the head.\n\nI want them " ..
                "dead!\n\nYou will find Grimnok atop the Southmaul Tower in Bloodmaul Outpost. You will " ..
                "find Korgaah in the top of a building at the north end of Bladespire Hold. Korgaah has " ..
                "sober defenders, so use the brew to distract him away from them, because they won't " ..
                "drink.",
            rewardMoney = 37000,
        },
        [10544] = {
            description = "T'chali wants revenge on all of the ogres!\n\nT'chali was a powerful witch " ..
                "doctor in life. If you reach into me grave you will find a wicked strong " ..
                "fetish.\n\nInvoke the fetish's magic at the entrances to the buildings and towers of " ..
                "both Bladespire Hold and Bloodmaul Outpost. The voodoo you work will summon an evil " ..
                "spirit that you must defeat. This in turn will curse that building.\n\nBeware, if you " ..
                "attempt to curse a building that is already cursed, you will call down another cursed " ..
                "spirit!",
            rewardChoices = {{31470, 1}, {31471, 1}, {31472, 1}, {31473, 1}},
            rewardMoney = 70000,
        },
        [10545] = {
            description = "As T'chali was saying, he helped out his Bloodmaul friends to make their brew. " ..
                "But what T'chali did not say was why.\n\nThe Bloodmaul are in dire straits. The " ..
                "Bladespire clan be crushing them, and they needed a new weapon to help out with their " ..
                "fight.\n\nThat's when T'chali came up with a great idea. Why not make the perfect brew, " ..
                "one that strengthens you and weakens your enemy? Only thing is, T'chali does not know if " ..
                "it works.\n\nSo, you gonna take this brew up to Bladespire Hold and see if it works!",
            rewardMoney = 35000,
        },
        [10546] = {
            description = "While Ar'tor was off hunting and Grom'tor was off fighting, Borak studied. " ..
                "Eventually he took up a vocation as a scholar and left for the wilds of Draenor. He " ..
                "returned home a few years ago a changed orc.\n\nHis heightened sense of awareness and " ..
                "mental acuity had forged a silent assassin.\n\nNow a confident and powerful orc, he has " ..
                "taken to recovering the most guarded piece of the cipher.\n\nFind Borak hiding near " ..
                "Eclipse Point, far to the south. He watches from the shadows of the bridge.",
        },
        [10547] = {
            description = "I'd have given up had I not noticed... He's a Thistlehead. I couldn't place it " ..
                "at first but the signs are all there...\n\nNow if we could get our hands on some " ..
                "bloodthistle, we'd be in business.\n\nIn my travels, I met a shady Broken in Shattrath " ..
                "named Tobias.\n\nTobias made a business of trading bloodthistle to blood elves for " ..
                "rotten arakkoa eggs.\n\nDirectly west of here are arakkoa ruins. Search them for an egg " ..
                "and head to the lower city of Shattrath. That's where you'll find Tobias.",
        },
        [10550] = {
            description = "I wasn't lying. That egg was incredible. Where did you get it from?\n\nWell, " ..
                "if you ever need more bloodthistle, you know where I am and what I need.\n\nHere's a " ..
                "bundle of the stuff. Take it back to your benefactor.",
        },
        [10553] = {
            description = "Now that you've chosen a side, <name>, you should meet the Scryers' " ..
                "leader.\n\nYou will find Voren'thal the Seer inside the Seer's Library at the Scryer's " ..
                "Tier.\n\nSee if you can be of assistance to him. He will be glad to hear you've decided " ..
                "to lend them a hand.",
        },
        [10554] = {
            description = "Now that you've decided to side with the Aldor, you'd do well to introduce " ..
                "yourself to their leader. You will find High Priestess Ishanah inside the Shrine of " ..
                "Unending Light.",
        },
        [10555] = {
            description = "The magic practiced by the Lashh'an arakkoa is unnatural. They rip out " ..
                "handfuls-clawfuls?-of their own feathers as reagents!\n\nThat doesn't sound like good " ..
                "magic to me. I've come here to learn more about their spells. Unfortunately getting " ..
                "close is too much for me.\n\nYou could succeed: cast one of their spells on yourself, " ..
                "then return to me. You'll have to find one of their spellbooks, high up in the trees of " ..
                "Veil Lashh.\n\nAnd unless you've grown feathers I can't see, you'll need to get some of " ..
                "those.",
        },
        [10556] = {
            description = "The pictograms indicate using feathers to cast the spell at one of the circles " ..
                "of power in Veil Lashh.\n\nConfusing iconography seems to show an arakkoa being suffused " ..
                "with the spirit of a kaliri.",
            rewardMoney = 35000,
        },
        [10557] = {
            description = "I built an amazing device, the Zephyrium Capacitorium, and I'm sure it'll work " ..
                "perfectly, but... do you want to help me test it?\n\nThere's plenty of hazard " ..
                "pay!\n\nSpeak with my twin over there, Rally. Good luck, <name>. Come back after your " ..
                "experiment. Or... if that's not possible due to sustained injuries, your next of kin can " ..
                "report to collect your pay.",
            rewardMoney = 8000,
        },
        [10562] = {
            description = "Don't let your guard down, <race>. We're under constant assault from the " ..
                "Burning Legion.\n\nFrom their base of Legion Hold to the northwest, the demons rain down " ..
                "a ceaseless stream of infernals. As quickly as we can kill them, the new meteors impact " ..
                "and begin a new wave of attacks.\n\nMy men are ragged and exhausted. I don't know how " ..
                "much longer they'll hold out. Please, <name>, lend your help to our defenses. Take your " ..
                "place on the line and halt the advance of the infernals!",
            rewardMoney = 41000,
        },
        [10563] = {
            description = "The fortress of Legion Hold is nigh impregnable, and to be completely honest, " ..
                "I can't spare the forces for an assault. Our hopes are riding on you, <name>.\n\nWhat " ..
                "little information we've been able to gather indicates that the Legion stocks and " ..
                "prepares its infernals at the hold. With the help of a disguise I'll give you, you must " ..
                "sneak into Legion Hold and learn about their plans. Your best hope is to intercept or " ..
                "overhear communication between their commanders. Good luck, <name>.",
            rewardMoney = 41000,
        },
        [10564] = {
            description = "The device we've assembled won't win any beauty contests, but it should be " ..
                "capable of destroying the infernals amassed at Legion Hold. Judging from what the fel " ..
                "reaver power core's energy did to the Fetid Pool, it holds a respectable amount of " ..
                "explosive power.\n\nIf you set the device off in the middle of the green glyph at the " ..
                "hold, it should be in range to hit all of the infernals.",
            rewardChoices = {{30929, 1}, {30946, 1}, {30947, 1}, {30986, 1}},
            rewardMoney = 41000,
        },
        [10565] = {
            description = "The arakkoa of Vekh'nir have been a thorn in our sides for many years. Some " ..
                "strange religion guides them, a religion which has the arakkoa in a frenzy of activity. " ..
                "They carry these crystals with them now, which they have turned to some dark " ..
                "purpose.\n\nI know something of their rituals. They take the crystals to their spell " ..
                "circles to infuse them. We at the village would like to know more. Waylay a few of the " ..
                "arakkoa until you find a crystal, charge it, then return it to me.",
        },
        [10566] = {
            description = "I've fashioned four wands that I believe will enhance the power of the " ..
                "arakkoa's crystals. Take these wands to Trogma's Claim, and try them on the ogre " ..
                "slaves.\n\nYou'll need to find an infused crystal off of the arakkoa in the " ..
                "area.\n\nWhen you figure out which is best, come back to me.",
            rewardMoney = 35000,
        },
        [10567] = {
            description = "The arakkoa of Ruaan Weald elevate from their flock the Harbingers of the " ..
                "Raven, the heralds of their god.\n\nThey believe that the Harbingers watch over them " ..
                "from the sky, where they receive the teachings of the Raven, and descend to pass this " ..
                "message along.\n\nThe Harbingers hold a powerful sway over the souls of the arakkoa. " ..
                "They use magical pendants, which we need.\n\nAttract one of the Harbingers by slaying " ..
                "its flock and taking their claws. Place the claws upon the altar to get his attention.",
        },
        [10568] = {
            description = "Years ago, the dreaded warlock known as Gul'dan raised the volcano in the " ..
                "middle of Shadowmoon. The draenei village of Baa'ri, to the southwest, was buried under " ..
                "the lava along with its inhabitants and artifacts of religious importance.\n\nThe " ..
                "treacherous tribe of Broken known as the Ashtongue has been ordered by Illidan to " ..
                "excavate the area. We must use this opportunity to recover the Tablets of Baa'ri, an " ..
                "ancient text rumored to hold the secrets of the Temple of Karabor, now known as the " ..
                "Black Temple.",
        },
        [10569] = {
            description = "Our scouts have brought back disturbing reports from the ruined arakkoa " ..
                "encampments in the area.\n\nThe ghosts of powerful arakkoa magicians wield powers we " ..
                "never thought they possessed. They seem to be organizing, as though preparing for " ..
                "something, but our knowledge is limited. We cannot afford to remain ignorant!\n\nTravel " ..
                "north to the Sketh'lon Wreckage, to the northwest of the Deathforge and search for signs " ..
                "of their motives.",
            rewardMoney = 41000,
        },
        [10570] = {
            description = "<Borak takes the bundle of bloodthistle from you and places it to his " ..
                "nose.>\n\nPungent...\n\nNow, take this bundle and place it at the other end of this " ..
                "bridge. When the envoy makes his daily rounds, he will be compelled to pick it up - " ..
                "without his bodyguard. You see, blood elves look down upon bloodthistle addicts. If any " ..
                "of his compatriots ever found out...\n\nAll you need to do is lie in wait for him to " ..
                "dismiss his bodyguard. When he is alone, make your strike! Kill him and take the missive.",
        },
        [10571] = {
            description = "According to the tablets, an artifact known as a Medallion of Karabor was kept " ..
                "at Baa'ri. Only the highest-ranking draenei priests were granted these, as they allowed " ..
                "unfettered access into the Temple of Karabor.\n\nWe must find out whether the Ashtongue " ..
                "have recovered the medallion that was kept at Baa'ri yet. Its power would provide great " ..
                "aid in our fight against Illidan.\n\nAkama's lieutenant at Baa'ri, Oronu the Elder, " ..
                "receives written orders from him daily. Obtain them and bring them to me.",
        },
        [10572] = {
            description = "We cannot permit the Legion to carry out its plan to destroy Wildhammer " ..
                "Stronghold on their march to the Black Temple.\n\nThere's only one way to stop them, " ..
                "<name>. You must create an explosive large enough to destroy the Legion's entire " ..
                "stockpile of infernals at the hold.\n\nThe Fetid Pool near Legion Hold holds an old fel " ..
                "reaver power core you could use as the base of your device. Search the other wreckage " ..
                "near the fel reaver for armor plating we might be able to make a casing from.",
            rewardMoney = 41000,
        },
        [10573] = {
            description = "From your findings at Legion Hold, we know that the Legion's Shadow Council " ..
                "allies are producing infernals in the Deathforge. I've dispatched a small scouting party " ..
                "to keep watch over the area, but they're not able to accomplish everything we " ..
                "need.\n\nIf the Deathforge is left alone to operate, they'll rebuild the infernal " ..
                "stockpile that you destroyed at Legion Hold.\n\nI want you to meet up with Stormer Ewan " ..
                "Wildwing, at the Deathforge Tower, to the northwest, overlooking the Deathforge itself.",
        },
        [10574] = {
            description = "According to Akama's letter, four fragments of the medallion were unearthed " ..
                "and given to the Ashtongue Corruptors. These dreaded Broken were once powerful shaman " ..
                "who now defile the very elements they revered.\n\nHaalum, Corruptor of Air, can be found " ..
                "at Netherwing Pass. Eykenen and Uylaru, Corruptors of Earth and Fire, were last seen at " ..
                "the Fel Pits near the Hand of Gul'dan. Lakaan, Corruptor of Water, is rumored to be near " ..
                "Coilskar Point.\n\nFind them and obtain the medallion fragments.",
        },
        [10575] = {
            description = "The fragments you obtained are only half of the medallion. The Ashtongue " ..
                "leader, Akama, must have kept the other half.\n\nI dread to ask this of you, as Akama is " ..
                "both evil and cunning.\n\nHe and the Ashtongue Deathsworn - the vilest and most brutal " ..
                "of the tribe - are rumored to run a torture chamber inside the Warden's Cage.\n\nI want " ..
                "you to find that dreaded prison, and find the whereabouts of Akama. His second in " ..
                "command at the location is a Broken known as Sanoru - interrogate him if you have to.",
        },
        [10576] = {
            description = "<Borak looks you up and down.>\n\nThis is going to be tricky, but I think I " ..
                "can make it work.\n\nI can disguise you as one of these Illidari blood elves, <name>. " ..
                "What I need first, though, are several pieces of their armor. It is imperative that the " ..
                "armor be clean. No blood stains! We want to avoid suspicion.\n\nBring me the gear and " ..
                "I'll take care of the rest of the disguise.\n\nOnce the disguise is assembled, you're " ..
                "going to deliver the message to the Grand Commander - in person.",
        },
        [10577] = {
            description = "Take this disguise and enter Eclipse Point. Once inside, use the disguise to " ..
                "cloak yourself. The Eclipsion blood elves will be unable to see through the disguise, " ..
                "thereby granting you safe passage to Grand Commander Ruusk.\n\nOnce you find Ruusk, tell " ..
                "him where next to move the cipher. You're going to have to act your heart out, <name>. " ..
                "Play it off as if you are his superior, delivering a message from his lord. That should " ..
                "do it!\n\nOh - watch out for the dragonhawks as they see through the disguise.",
        },
        [10578] = {
            description = "That Cipher fragment will never reach Zuluhed. You're going to ambush Ruul the " ..
                "Darkener and his transport before it has a chance to make the delivery.\n\nThe Dragonmaw " ..
                "Fortress is directly east of here, across the Netherwing Fields. Somewhere between " ..
                "Dragonmaw Fortress and the Sanctum of the Stars is where you'll find Ruul. Strike hard " ..
                "and strike fast! And <name>, from the sound of it, this Ruul is going to be tough. Keep " ..
                "your guard up.\n\nReturn the Cipher to me should you succeed.",
        },
        [10579] = {
            description = "Take this box to my father. He still resides at Oronok's Farm, far to the " ..
                "north, above Coilskar Cistern. When all three fragments are pieced together, the ancient " ..
                "words will be known once more.\n\nGood luck, <name>. Tell my father that I will be home " ..
                "soon.",
            rewardChoices = {{30925, 1}, {30939, 1}, {30944, 1}, {30951, 1}, {30962, 1}, {30967, 1}},
        },
        [10580] = {
            description = "Despite the good that we've done here, I feel bad about one thing: driving " ..
                "Toshley and his gnome friends away.\n\nWe had no choice; they were making a mess of our " ..
                "efforts in the grove with all of their technology and experimentation.\n\nI would " ..
                "appreciate it if you would find out what became of them. Last we heard, they headed east " ..
                "across the bridge. I'm certain that they must have turned south, away from Thunderlord " ..
                "Stronghold.\n\nLook for a clue as to their whereabouts in the southern Jagged Ridge.",
        },
        [10581] = {
            description = "VERY WELL, I AM HEREBY WARNING YOU THAT YOU WILL FIND NOTHING UP ON THE " ..
                "RIDGE.\n\nDO NOT FOLLOW THE TRAIL OF SPARE PARTS THAT LEAD TO TOSHLEY 'S STATION! YOU " ..
                "WILL NOT FIND TOSHLEY, NOR ANY OTHER GNOME THERE.",
        },
        [10582] = {
            description = "<Ewan listens to you recount the events at Legion Hold, nodding.>\n\nThat puts " ..
                "our observations into perspective. We've caught glimpses of them launching infernals in " ..
                "the direction of the hold, but haven't been able to find much more than that.\n\nThe " ..
                "Shadow Council has the Deathforge sealed tighter than a new keg o' thunderbrew. The " ..
                "first thing you'll need to do is crack some skulls so you can get in there and poke " ..
                "around. Start eliminating the Shadow Council guarding the entrance to the Deathforge!",
            rewardMoney = 41000,
        },
        [10583] = {
            description = "Wing Commander Nuainn originally sent three of us out here to keep watch over " ..
                "the Deathforge and to gather information. Flanis Swiftwing volunteered to try to " ..
                "infiltrate the Deathforge, but we haven't heard anything from him in days.\n\nI fear the " ..
                "worst, <name>. Flanis is a skilled scout, but if he's gotten in over his head, we have " ..
                "no way of knowing. Search the Deathforge for him and recover any information or items he " ..
                "might have collected.",
            rewardMoney = 41000,
        },
        [10584] = {
            description = "Those dumb ogres at the Bladespire Outpost to the north have been raiding our " ..
                "power converters! And you're going to get them back for me, sort of.\n\nNo doubt, with " ..
                "their big, clumsy hands, the ogres have damaged the converters. So, what I want you to " ..
                "do is release the energy from them and then use this protovoltaic magneto collector on " ..
                "the resultant electromental to encase it.\n\nIt'll likely be sore with you, so you'll " ..
                "need to 'kill' it while it's contained in the magneto sphere.",
            rewardMoney = 37000,
        },
        [10585] = {
            description = "In order for the Shadow Council to construct infernals as quickly as they're " ..
                "being used, they must have an area dedicated to summoning the corrupted elementals that " ..
                "serve as the souls of the creatures.\n\nThe summoning chamber is likely to be found " ..
                "below ground, near a pool of fouled water or lava. Locate the summoning chamber within " ..
                "the Deathforge and find a way to end their summoning ritual. The mo'arg involved in " ..
                "making the infernals may carry a tool that will help disrupt the summoner's magics.",
            rewardMoney = 41000,
        },
        [10586] = {
            description = "We've made a lot of progress against the Shadow Council's operations at the " ..
                "Deathforge, but if we're to truly be triumphant, we'll need to defeat the Legion's " ..
                "overseer there.\n\nI found a key among the items in Flanis's pack. I'm certain it will " ..
                "prove useful in tracking down this Warbringer Razuun you observed at Legion " ..
                "Hold.\n\nAfter you've hunted down and dealt with Warbringer Razuun, report directly to " ..
                "Wing Commander Nuainn. He'll want to know immediately!",
            rewardMoney = 41000,
        },
        [10587] = {
            description = "Our scouts have reported a massive influx of Sunfury blood elf recruits " ..
                "heading to the Ruins of Karabor. Normally this would represent a purely military threat, " ..
                "however we believe something else is amiss.\n\nDescriptions of their attire and fighting " ..
                "style are suspiciously close to that of Illidan himself. I do not want to become alarmed " ..
                "without good reason, so I would like you to go there and bring me back their weapons. We " ..
                "will then determine whether my fears are unfounded or not.",
        },
        [10588] = {
            description = "How many times has this spell been used in the history of our worlds? " ..
                "Undoubtedly, its power for destruction is unparalleled.\n\nWhat you must do now is take " ..
                "the cipher, now made whole, and read from it at the Altar of Damnation - where the " ..
                "memory of Gul'dan stands.\n\nWhat you will see once the words are uttered are the " ..
                "memories left imprinted upon the land. Stand your ground and await the coming of " ..
                "Cyrukh.\n\nYou must be victorious, <name>. This land cannot withstand another shattering.",
            rewardChoices = {{31036, 1}, {31038, 1}, {31062, 1}, {31071, 1}, {31072, 1}, {31073, 1}},
            rewardItems = {{31074, 1}},
            rewardMoney = 132000,
        },
        [10589] = {
            description = "According to Razuun's orders, the massive infernal staging area is called " ..
                "Invasion Point: Cataclysm and it's nestled in the northern mountains. The only way to " ..
                "reach it is by using a teleporter located at Legion Hold.\n\nCertain members of the " ..
                "Legion host carry devices allowing them to activate the teleporters. You must capture " ..
                "one of these devices to win access to the teleporter. Slaughter all of the demons if you " ..
                "must, but you can't afford to return empty-handed.",
            rewardMoney = 41000,
        },
        [10594] = {
            description = "Take these scanners to the Singing Ridge. By dropping them in a pattern on the " ..
                "ground, you will create overlapping fields that will read the amplitude of the crystals. " ..
                "Stand amidst them in such a way that you're in five oscillation fields and I'll have the " ..
                "information that I need!\n\nYour scanners will even work with those that others " ..
                "drop.\n\nOh, and it's likely that a rift will be formed! I have no idea what, if " ..
                "anything, will come out of it, but be prepared for the worst.",
            rewardChoices = {{31442, 1}, {31443, 1}, {31444, 1}, {31445, 1}},
            rewardMoney = 37000,
        },
        [10595] = {
            description = "<Gulmok looks to the sky.>\n\nOur scouts are putting up a good fight, but the " ..
                "infernals keep coming!\n\nFrom their base of Legion Hold to the southwest, the demons " ..
                "bombard us with impunity! Even the elite Kor'kron guard cannot hold them off " ..
                "forever.\n\nI'm drafting every able-bodied <race> to do their part in defense of " ..
                "Shadowmoon Village. This is no game, <class>. The survival of the village is at stake. " ..
                "Do your duty to the Horde, and join the fray!",
            rewardMoney = 41000,
        },
        [10596] = {
            description = "The fortress of Legion Hold is your target. You'll have no reinforcements, so " ..
                "a frontal attack is out of the question.\n\nWhat little information we have shows that " ..
                "the Legion stocks and prepares its infernals at the hold. With the help of a disguise " ..
                "I'll give you, you must sneak into Legion Hold and discover their plans.\n\nYour best " ..
                "hope is to intercept or overhear communication between their commanders.",
            rewardMoney = 41000,
        },
        [10597] = {
            description = "We can't allow the Legion to trample us on their march to Black " ..
                "Temple.\n\nFind a way to destroy the infernals they intend to use against us. That's not " ..
                "a request, <name>; it's an order.\n\nThe Fetid Pool near Legion Hold holds an old fel " ..
                "reaver power core you could use as the basis for a kind of fel bomb. Search the other " ..
                "wreckage near the fel reaver for a section of armor plating. You should be able to make " ..
                "a bomb powerful enough to take out those infernals and give the hold a nice shake!",
            rewardMoney = 41000,
        },
        [10598] = {
            description = "The device we've assembled won't win any beauty contests, but it should be " ..
                "capable of destroying the infernals amassed at Legion Hold. Judging from what the fel " ..
                "reaver power core's energy did to the Fetid Pool, it holds a respectable amount of " ..
                "explosive power.\n\nIf you set the device off in the middle of the green glyph at the " ..
                "hold, it should be in range to hit all of the infernals.",
            rewardChoices = {{30929, 1}, {30946, 1}, {30947, 1}, {30986, 1}},
            rewardMoney = 41000,
        },
        [10599] = {
            description = "While you were taking care of the infernals at Legion Hold, I've been going " ..
                "over your reports. We've got no reason to believe the Legion lied about what's going on " ..
                "at the Deathforge. They're really cranking out infernals down there, so I've dispatched " ..
                "a scouting party to keep watch over it.\n\nIf we don't shut down the Deathforge, they'll " ..
                "rebuild the infernal stockpile that you destroyed at Legion Hold.\n\nReport to Scout " ..
                "Zagran atop Slag Watch, to the southeast of here and overlooking the Deathforge.",
        },
        [10600] = {
            description = "<Zagran listens to you recount the events at Legion Hold, nodding.>\n\nThat " ..
                "fills in the gaps we've seen. We've caught glimpses of them launching infernals in the " ..
                "direction of the hold, but haven't been able to find much more than that.\n\nThe Shadow " ..
                "Council has the forge pretty much locked down. Looks like you're going to need to fight " ..
                "your way in. Start eliminating the Shadow Council guarding the entrance to the " ..
                "Deathforge!",
            rewardMoney = 41000,
        },
        [10601] = {
            description = "The scouting party originally had three members. Unfortunately, Kagrosh " ..
                "decided he wanted to be a hero.\n\nHe descended into the Deathforge and we haven't heard " ..
                "from him since.\n\nIn all likelihood, the fool's gone and gotten himself killed. The " ..
                "Shadow Council members aren't idiots and Kagrosh wasn't exactly strong in the subtlety " ..
                "department, if you know what I mean. Keep an eye out for him in the Deathforge and " ..
                "recover any information or items he might have collected.",
            rewardMoney = 41000,
        },
        [10602] = {
            description = "In order to churn out infernals as quickly as the Deathforge seems to, they " ..
                "must have an area dedicated to summoning the elementals that form the core of the " ..
                "infernals.\n\nThe summoning chamber is likely to be found below ground, near a pool of " ..
                "fouled water or lava. Locate the summoning chamber within the Deathforge and find a way " ..
                "to end their summoning ritual. The mo'arg involved in making the infernals may carry a " ..
                "tool that will help disrupt the summoner's magics.",
            rewardMoney = 41000,
        },
        [10603] = {
            description = "We've made a lot of progress against the Shadow Council here at the " ..
                "Deathforge, but now it's time to finish the job.\n\nI found a key among the items in " ..
                "Kagrosh's pack. At least he accomplished something before they got to him.\n\nThe key " ..
                "should help you to track down this Warbringer Razuun you observed at Legion " ..
                "Hold.\n\nAfter you've hunted down and dealt with Warbringer Razuun, report directly to " ..
                "Blood Guard Gulmok. We must not keep him waiting.",
            rewardMoney = 41000,
        },
        [10604] = {
            description = "According to Razuun's orders, the massive infernal staging area is called " ..
                "Invasion Point: Cataclysm and it's located in the mountains behind our village! The only " ..
                "way to reach it is by using a teleporter at Legion Hold.\n\nCertain Legion minions carry " ..
                "a device allowing them to use the teleporter. You must capture one of these devices to " ..
                "win access to the teleporter. Slaughter all of the demons if you must, but you can't " ..
                "afford to return empty-handed. Do not delay; the enemy is perilously close.",
            rewardMoney = 41000,
        },
        [10606] = {
            description = "The best way to destroy the rest of the Legion's supplies is to use their own " ..
                "weapons against them. I've been working on a rig that will let you take control of one " ..
                "of those Fel Reaver Sentinels below.\n\nThere are a couple things I need to work out, " ..
                "yet. For that, I'll need the manual that Doctor Gutrick keeps locked in a chest at the " ..
                "bottom of the ramp. He probably won't give up the key without a fight, so you'll need to " ..
                "capture it. Bring the fel reaver manual back to me and I'll do the rest!",
            rewardMoney = 41000,
        },
        [10607] = {
            description = "At Grishnath, totems left by the Oracles of the Raven enable the arakkoa to " ..
                "hear the Word of the Raven. Unfortunately, the language of the arakkoa is indecipherable " ..
                "to us.\n\nUsing the Harbinger's pendant, we can understand it. You will be able to take " ..
                "the souls of the arakkoa to understand their language. While you are suffused with the " ..
                "arakkoa's spirit, you can visit the totems and understand their message.\n\nDiscover " ..
                "this for us, <name>.",
            rewardChoices = {{31531, 1}, {31532, 1}, {31533, 1}, {31534, 1}},
        },
        [10608] = {
            description = "The damned rock flayers are keeping me from my research down in the Singing " ..
                "Ridge! By digging at the crystals there, with every scratch they are ruining my chances " ..
                "of studying the harmonics of the singing crystals.\n\nYou look like someone who can help " ..
                "me deal with this problem. Head south and clear those crystal flayers out.",
            rewardMoney = 37000,
        },
        [10609] = {
            description = "I'm researching the applications of drake essences to my work as a physician. " ..
                "I think they could be a panacea for a host of maladies!\n\nI need someone to go south to " ..
                "the Singing Ridge and get me some.\n\nWilling to take my temporal phase modulator and " ..
                "use it on the nether whelps that hatch from the nether drake eggs? Retrieve the essences " ..
                "from whatever they turn into.\n\nWhich, I might add, I'm not certain of what that will " ..
                "be as we're using some pretty dicey, time and space modifying tech here.",
            rewardChoices = {{31438, 1}, {31439, 1}, {31440, 1}, {31441, 1}},
            rewardItems = {{31437, 5}},
            rewardMoney = 37000,
        },
        [10611] = {
            description = "The best way to destroy the rest of the Legion's supplies is to use their own " ..
                "weapons against them. I've been working on a rig that will let you take control of one " ..
                "of those Fel Reaver Sentinels below.\n\nThere are a couple things I need to work out, " ..
                "yet. For that, I'll need the manual that Doctor Maleficus keeps locked in a chest near " ..
                "the bottom of the ramp. He probably won't give up the key without a fight, so you'll " ..
                "need to capture it. Bring the fel reaver manual back to me and I'll do the rest.",
            rewardMoney = 41000,
        },
        [10612] = {
            description = "< Plexi leafs through the manual.>\n\nWell, this has everything we need, but " ..
                "there's just one problem. Fel Reavers aren't really built to respond to remote " ..
                "control.\n\nWe can modify one for you to use for a short time, but you'll have to work " ..
                "fast, or there's no telling what might happen! I wouldn't be surprised if your little " ..
                "stunt with the fel reaver catches the attention of the Legion's lackeys, either. Keep an " ..
                "eye out, and whatever you do, don't forget to destroy as much as you can!",
            rewardMoney = 41000,
        },
        [10613] = {
            description = "< Nakansi leafs through the manual.>\n\nAll the information is here, but be " ..
                "warned. These things weren't built to be controlled remotely.\n\nWe can modify one for " ..
                "you to use for a short time, but you'll have to work fast, or there's no telling what " ..
                "might happen! I wouldn't be surprised if your little stunt with the fel reaver catches " ..
                "the attention of the Legion scum, either. Try to keep yourself safe, but remember, the " ..
                "mission and the safety of Shadowmoon Village come first!",
            rewardMoney = 41000,
        },
        [10614] = {
            description = "I have chased rumors of the Mok'Nathal across Outland with nothing to show for " ..
                "it. Finally, we may have found their home.\n\nBut now that the moment is here, I am " ..
                "filled with unease. Unease that has kept me awake deep into the nights during my search. " ..
                "Will they accept me?\n\nI... know their leader's name: Leoroxx. Seek him out. You must " ..
                "be my eyes in this.",
        },
        [10615] = {
            description = "The information you have helped me reveal about the nature of the arakkoa here " ..
                "will be of great interest to another.\n\nWe were visited by members of the Cenarion " ..
                "Expedition, who have also become concerned with the arakkoa's intentions here in the " ..
                "Blade's Edge Mountains.\n\nYou should seek him out. His name is Timeon, and you will " ..
                "find him at Evergrove in Ruuan Weald. Follow the road west from here, then north when it " ..
                "forks in Razor Ridge. Finally, follow the road west when it splits in the Bladed Gulch.",
        },
        [10617] = {
            description = "The silk from the cocoons of the silkwings are used for all manner of things " ..
                "in the village. We can never get enough, and we never have enough.\n\nIt is difficult to " ..
                "harvest the cocoons from the larva once they begin the process of metamorphosis.\n\nOur " ..
                "warriors are occupied with the assault on our village. If you could gather these for us, " ..
                "that would be helpful.",
            rewardMoney = 35000,
        },
        [10618] = {
            description = "Hunting silkwing larva is a difficult challenge for our young warriors, but " ..
                "luckily, even if they fail to harvest the cocoon from the larva, we can still use the " ..
                "wings of hatched silkwings.\n\nIn fact, we use the wings for much more than the cocoons, " ..
                "and we can never have too many.\n\nIf you'll be out there, it would be a great help if " ..
                "you could bring me some.",
            rewardMoney = 33000,
        },
        [10619] = {
            description = "The Ashtongue tribe is feared among all Broken. It consists of the most " ..
                "vicious and bloodthirsty individuals, handpicked by Akama himself. They are as fierce " ..
                "and ruthless as any naga, demon or blood elf in Illidan's army and they have been " ..
                "deployed in large numbers at the Ruins of Baa'ri, southwest of here. Go there and put a " ..
                "dent in their numbers before they get a chance to mount an attack on us.",
        },
        [10620] = {
            description = "We hired on to help Toshley when he decided to move to Outland, and we've been " ..
                "on the move ever since.\n\nNow it looks like we've finally put down some roots. All of " ..
                "the crazy scientists have their projects going, and us Roughriders are here to protect " ..
                "them.\n\nWhat we need right now is for you to go north into Razor Ridge, or east to the " ..
                "Scalewing Shelf, and keep them clear by killing the stalkers. They're stealthy spiders " ..
                "that live amongst the rock outcroppings, and jump unsuspecting passersby.",
            rewardChoices = {{31449, 5}, {31450, 5}},
            rewardMoney = 37000,
        },
        [10621] = {
            description = "The shard appears to be a piece of a larger weapon. Sharp-looking runes etched " ..
                "into the metal glow with a menacing light.\n\nThe weapon's intended purpose isn't clear " ..
                "to you, but it's hard to ignore. Most of the mo'arg at Legion Hold seem to be working " ..
                "with fragments of the same metal you hold in your hand. Perhaps one of the weaponsmiths " ..
                "at Wildhammer Stronghold might be able to tell you more about it.",
            rewardMoney = 41000,
        },
        [10622] = {
            description = "Akama has been tracking your progress quite closely, <name>.\n\nThe Ashtongue " ..
                "you've slain at the Ruins of Baa'ri are amongst the most evil Broken known among us... " ..
                "carefully hand-picked by Akama himself to maintain the facade we need to present to " ..
                "Illidan. The Deathsworn, however, know of Akama's true intentions.\n\nFirst things " ..
                "first. We need to know that you are not with Illidan. A Satyr known as Zandras watches " ..
                "over us from above the prison walls on his behalf. Slay him as proof of your allegiance.",
        },
        [10623] = {
            description = "The shard appears to be a piece of a larger weapon. Sharp-looking runes etched " ..
                "into the metal glow with a menacing light.\n\nThe weapon's intended purpose isn't clear " ..
                "to you, but it's hard to ignore. Most of the mo'arg at Legion Hold seem to be working " ..
                "with fragments of the same metal you hold in your hand. Perhaps one of the weaponsmiths " ..
                "at Shadowmoon Village might be able to tell you more about it.",
            rewardMoney = 41000,
        },
        [10624] = {
            description = "Have you felt the cold chill? Perhaps what you thought was a hand on your " ..
                "shoulder? That was not your mind playing tricks on you, <race>. The land is haunted. " ..
                "Ghosts litter the landscape, stuck here for all eternity.\n\nWould you like to see them? " ..
                "Are you sure about that? These types of things tend to change a person - and not for the " ..
                "better.\n\nVery well, I will need you to collect for me the ever-burning ash that is " ..
                "found near any of the fel lava pools of western Shadowmoon. Anywhere near green lava...",
            rewardMoney = 41000,
        },
        [10625] = {
            description = "I call them \" Spectrecles.\" Clever, no? When you equip these goggles, you " ..
                "will be able to see the spirits of Shadowmoon Valley.\n\nBefore I let you have them, " ..
                "though, you must promise me that you will help us clear out the ghosts at the " ..
                "village.\n\nTake the goggles and destroy any and all spirits that you see wandering " ..
                "about Shadowmoon Village. Hopefully, destroying these spirits will force any that remain " ..
                "to move elsewhere.",
            rewardMoney = 41000,
        },
        [10626] = {
            description = "With a larger supply of this material, we might be able to forge a weapon for " ..
                "you to use.\n\nThe two pit lords at Legion Hold, Makazradon and Morgroron, have already " ..
                "been equipped with these anti-demon weapons. We have no way of knowing how many more the " ..
                "Legion intends to produce, but if we can capture these prototypes, there should be " ..
                "enough for our project.\n\n<Ordinn grins.>\n\nThere's a certain amount of satisfaction " ..
                "in using the Legion's own 'secret weapons' against them, don't you think?",
            rewardChoices = {{30926, 1}, {30938, 1}, {30950, 1}, {30966, 1}},
            rewardMoney = 41000,
        },
        [10627] = {
            description = "With a larger supply of this material, I can forge a weapon suitable for " ..
                "you.\n\nThe two pit lords at Legion Hold, Makazradon and Morgroron, have already been " ..
                "equipped with these anti-demon weapons. Capturing those two weapons should provide us " ..
                "with enough material to make your weapon, and then some.\n\nI can't wait to bring the " ..
                "battle to the enemy using these weapons. That'll teach the Legion to trifle with " ..
                "anti-demon magics.",
            rewardChoices = {{30926, 1}, {30938, 1}, {30950, 1}, {30966, 1}},
            rewardMoney = 41000,
        },
        [10628] = {
            description = "You've proven what side you're on. I will reveal to you our leader's " ..
                "hideout.\n\nFollow the halls beyond; there will be an underground passage hidden by " ..
                "stagnant water on your right.\n\nI must warn you, <name>. You are not to speak to anyone " ..
                "of what you see there.",
        },
        [10629] = {
            description = "I finally got my shredder working but I seem to have lost the keys. I keep a " ..
                "pack of felhounds to protect my camp. They don't do a very good job and they like to " ..
                "bite me a lot. They also like shiny things. I think this one felhound I have may have " ..
                "eaten my shredder keys. I'll pay you if you'll take my felhound on a walk. Kill some " ..
                "helboars and let him eat. He'll do his business. When he's done, see if you can't find " ..
                "the keys in his \"leavings.\"",
            rewardItems = {{18588, 5}},
            rewardMoney = 40000,
        },
        [10630] = {
            description = "I'm almost back in business. Problem is all these gan'arg are in my mine. I " ..
                "can't send my peons in and even once I fix this shredder I wouldn't want to risk it in " ..
                "combat. Deep down in the mine the gan'arg have a leader. If you kill him maybe the " ..
                "gan'arg will leave. Then I could make some money and buy my way out of here.",
            rewardChoices = {{30855, 1}, {30856, 1}, {30857, 1}},
            rewardMoney = 20000,
        },
        [10632] = {
            description = "It's nice that you've been helping out Toshley and his scientists. I, however, " ..
                "do not have the luxury of indulging in my 'personal' interests.\n\nIf you want to make a " ..
                "difference around here, you'll do what I ask of you, and right now, I need " ..
                "weapons.\n\nOur guns are effective at range, but when the bugs get in close, we need to " ..
                "have powerful melee weapons as a backup.\n\nThe teeth of the daggermaw lashtails in the " ..
                "northern part of the Razor Ridge make for great vibro-weapon blades. Scare me up some.",
            rewardChoices = {{31446, 1}, {31447, 1}, {31448, 1}},
            rewardMoney = 37000,
        },
        [10633] = {
            description = "Stories abound about the life of Teron Gorefiend, but most are just that - " ..
                "stories. We do not know what happened to Gorefiend after he returned to Draenor.\n\nThe " ..
                "only thing we are certain of is that he has already died once.\n\nI have heard the " ..
                "scouts here speaking of an ancient orc spirit that resides at the Altar of Shadows, far " ..
                "to the southeast, across the Netherwing Fields and through Netherwing Pass. Take the " ..
                "Spectrecles and track this orc down. He will surely have more information on Gorefiend.",
        },
        [10634] = {
            description = "In life, Gorefiend was a monster, but in death, Gorefiend was an unmitigated " ..
                "terror.\n\nTo the southeast you will find Netherwing Ledge. What was once part of the " ..
                "mainland of Shadowmoon is now a floating island in the sky.\n\nVhel'kur, spawn of " ..
                "Deathwing, once called it his home, but now knows it as his grave. He flies an endless " ..
                "circle above the island, seething at his defeat to Gorefiend.\n\nIf you are to recover " ..
                "the Gorefiend's armor, it is Vhel'kur that you must defeat.",
        },
        [10635] = {
            description = "Many a cruel act he committed but none so cold as the slaughter of the clerics " ..
                "of Karabor.\n\nAfter Gul'dan's Horde defeated the draenei of Karabor, the surviving " ..
                "clerics of Karabor were marched out, told that they were to be taken to Hellfire Citadel " ..
                "as prisoners of war.\n\nGorefiend, not yet a death knight, murdered each and every last " ..
                "one of them in cold blood. They now roam in front of the Black Temple with vengeance in " ..
                "their hearts.\n\nIt is the clerics of Karabor that hold the cloak of Gorefiend.",
        },
        [10636] = {
            description = "One by one they knelt before him, offering their lives as a show of " ..
                "allegiance. Gorefiend hoisted his sickle and cut clean their heads. Shortly after this " ..
                "slaughter, Gorefiend took his own life.\n\nBut this was no act of contrition! No, " ..
                "Gorefiend sought immortality! From the corpses of the fallen death knights rose the " ..
                "Ghostriders of Karabor.\n\nThey now ride the roads encircling the Hand of Guldan, " ..
                "awaiting the day that their master returns. It is they who hold the truncheon of " ..
                "Gorefiend. Retrieve it...",
        },
        [10637] = {
            description = "The weapons are authentic, as we feared. Illidan is training demon hunters at " ..
                "the Ruins of Karabor and we must put an end to it.\n\nDo not be fooled by their name, " ..
                "<name>, their power will be used against us as often as against any demon.\n\nTheir " ..
                "warlocks summon and subdue demons to be used as part of the initiates' training. A pit " ..
                "lord named Azaloth has proven too strong to be used in training and is kept banished. " ..
                "Find a way to let him loose on his captors. That should buy us the time we need.",
        },
        [10639] = {
            description = "With Gorefiend's items restored, there is but one last piece to this puzzle: A " ..
                "host.\n\n<The ancient shadowmoon spirit 's lips curl up to form a wicked " ..
                "grin.>\n\nSurely you did not believe the fairy tale that I told you. The Altar of " ..
                "Shadows is my prison. Without your help, I would have been stuck here for all eternity. " ..
                "Now, I will take over your body and you will destroy my captors and break these bonds. " ..
                "Refuse and we will both be stuck here forever.\n\nTeron Gorefiend will be free!",
            rewardChoices = {{31104, 1}, {31105, 1}, {31106, 1}, {31107, 1}, {31109, 1}, {31110, 1}},
        },
        [10640] = {
            description = "It is rare in this day and age to hear of those who follow the path of the " ..
                "demon hunter. It is rarer still to find someone who does and has no allegiance to " ..
                "Illidan.\n\nThere are rumors of one such individual here in Outland. One name is said to " ..
                "be feared in the Legion fields of Nagrand more than any army of Aldor vindicators. That " ..
                "name is Altruis.\n\nGo to western Nagrand and find him. He might be willing to shed some " ..
                "light on these new demon hunter training grounds.",
        },
        [10641] = {
            description = "The Burning Legion has proven its capacity to corrupt mortal souls time and " ..
                "again. If I'm to entrust you with the knowledge you seek, I must have proof of your " ..
                "allegiance.\n\nA demoness known as Sathal has eluded me for a long time as she's gifted " ..
                "with an incorporeal form.\n\nShe watches over the wrath priestesses as they do her " ..
                "bidding at Forge Base: Gehenna. Slay one of her minions and spill her blood on the " ..
                "ground. This affront should cause Sathal to materialize temporarily. Slay her while you " ..
                "can.",
        },
        [10642] = {
            description = "I fear that these dwarves do not understand what they have built upon. This " ..
                "area was once the ancestral grounds for the Shadowmoon orcs. I speak of spirits, " ..
                "<race>.\n\nFor nearly twenty years they have laid dormant beneath the Wildhammer " ..
                "Stronghold, but recently, something has riled them up.\n\nVenture beyond the gates of " ..
                "Wildhammer and seek out the pools and rivers of fel lava found across this land. Near " ..
                "the lava will be ever-burning ash. Bring me this ash so that I may craft something that " ..
                "will help us.",
            rewardMoney = 41000,
        },
        [10643] = {
            description = "Let it be known that Zorus does have a sense of humor.\n\nEnough small talk. " ..
                "Don the Spectrecles so that you are able to see the Shadowmoon orc spirits that wander " ..
                "this stronghold. Do not be frightened as we are truly the invaders here. Alas, they must " ..
                "be destroyed, for their time has long since passed.\n\nDestroy the Shadowmoon harbingers " ..
                "infesting Wildhammer Stronghold and return to me.",
            rewardMoney = 41000,
        },
        [10644] = {
            description = "Stories abound about the life of Teron Gorefiend, but most are just that - " ..
                "stories. We do not know what happened to Gorefiend after he returned to Draenor.\n\nThe " ..
                "only thing we are certain of is that he has already died once.\n\nI have heard the " ..
                "scouts here speaking of an ancient orc spirit that resides at the Altar of Shadows, far " ..
                "to the east, across the Netherwing Fields and through Netherwing Pass. Take the " ..
                "Spectrecles and track this orc down. He will surely have more information on Gorefiend.",
        },
        [10645] = {
            description = "With Gorefiend's items restored, there is but one last piece to this puzzle: A " ..
                "host.\n\n<The ancient shadowmoon spirit 's lips curl up to form a wicked " ..
                "grin.>\n\nSurely you did not believe the fairy tale that I told you. The Altar of " ..
                "Shadows is my prison. Without your help, I would have been stuck here for all eternity. " ..
                "Now, I will take over your body and you will destroy my captors and break these bonds. " ..
                "Refuse and we will both be stuck here forever.\n\nTeron Gorefiend will be free!",
            rewardChoices = {{31104, 1}, {31105, 1}, {31106, 1}, {31107, 1}, {31109, 1}, {31110, 1}},
        },
        [10646] = {
            description = "You've proven your allegiance, <name>. You must forgive my caution, but in " ..
                "this world things are not what they appear.\n\nI will tell you about Varedis when you're " ..
                "ready.",
        },
        [10647] = {
            description = "Wanted - DEAD:\n\nUvuros, scourge of Shadowmoon Valley.\n\nBy order of " ..
                "Overlord Or'barokh, the fel beast, Uvuros, is to be killed on sight and his mane " ..
                "stripped from his carcass as proof of deed. Return the fiery mane of the beast to " ..
                "Warcaller Sardon Truslice should you succeed.\n\nUvuros was last seen at the Hand of " ..
                "Gul'dan, located in the heart of Shadowmoon Valley - east of Shadowmoon Village.",
            rewardChoices = {{31111, 1}, {31112, 1}, {31114, 1}, {31115, 1}},
            rewardMoney = 132000,
        },
        [10648] = {
            description = "Wanted - DEAD:\n\nUvuros, scourge of Shadowmoon Valley.\n\nBy order of Thane " ..
                "Yoregar, the fel beast, Uvuros, is to be killed on sight and his mane stripped from his " ..
                "carcass as proof of deed. Return the fiery mane of the beast to Warcaller Beersnout " ..
                "should you succeed.\n\nUvuros was last seen at the Hand of Gul'dan, located in the heart " ..
                "of Shadowmoon Valley - northeast of Wildhammer Stronghold.",
            rewardChoices = {{31111, 1}, {31112, 1}, {31114, 1}, {31115, 1}},
            rewardMoney = 132000,
        },
        [10649] = {
            description = "I sympathize with your intentions of stopping Varedis and his followers, but " ..
                "you won't stand a chance against him. That is, unless you find the artifact that gave " ..
                "him his power.\n\nThe Book of Fel Names is rumored to be in the possession of Blackheart " ..
                "the Inciter inside the Shadow Labyrinth in Auchindoun. Obtaining it will be your only " ..
                "hope against Varedis.",
        },
        [10650] = {
            description = "This book... I could use it to increase my power tenfold... No! It would end " ..
                "up corrupting my very soul, this I am sure of. Return to those who sent you here, " ..
                "<name>.\n\nYou now have the means to stop Varedis. Wait until he manifests his demonic " ..
                "form through metamorphosis, at that point you will need to burn the book in his " ..
                "presence. That will be the only way you can deprive him of his power.",
        },
        [10651] = {
            description = "We must dispose of this foul artifact, but not before we use it to dispose of " ..
                "Varedis 's powers.\n\nWe need to permanently shut down the Ruins of Karabor training " ..
                "grounds, which will mean killing not only Varedis but also the three night elf masters " ..
                "that assist him: Alandien, Theras and Netharel.\n\nGather a suitable force and return to " ..
                "the Ruins of Karabor. Follow Altruis's instructions for defeating Varedis. For all of " ..
                "our sakes, I hope they work.",
            rewardChoices = {{30933, 1}, {30948, 1}, {31002, 1}, {31009, 1}, {31010, 1}, {31013, 1}},
        },
        [10652] = {
            description = "All arrangements have been made to take you to where our spies are hiding. " ..
                "Just come see me when you're ready and we'll get you on your way.",
        },
        [10653] = {
            description = "By now it should be clear to you why we oppose the Burning Legion and those " ..
                "who serve them.\n\nIf you wish to prove yourself to the Aldor, bring me the insignias of " ..
                "high-ranking Legion and their Shadow Council followers. The highest-ranking Legion can " ..
                "be found in Netherstorm and Shadowmoon Valley.",
        },
        [10656] = {
            description = "As you might know, the Scryers and the armies of Kael'thas are at war. Kael " ..
                "sees us as a threat to his influence over other blood elves and has tried to crush us " ..
                "time and again.\n\nIf you wish to aid us in our battle against Kael'thas, there are " ..
                "plenty of targets for you to go after. Kael's highest ranking soldiers wear Sunfury " ..
                "signets to mark their ranks. You will find them all over Netherstorm and Shadowmoon " ..
                "Valley.",
        },
        [10657] = {
            description = "We haven't kept the use of the Zephyrium Capacitorium under budget. But, it " ..
                "occurs to me that the serpents of the Scalewing Shelf to the east have a lightning " ..
                "breath and glands that we can make use of.\n\nI've repolarized the magneto collector to " ..
                "absorb lightning strikes and I want you to head up there, activate it on yourself, and " ..
                "get us some cheap fuel from those serpents.",
            rewardChoices = {{31452, 1}, {31453, 1}, {31454, 1}, {31455, 1}},
            rewardItems = {{31451, 5}},
            rewardMoney = 37000,
        },
        [10660] = {
            description = "I am interested in learning more about the strange reptiles that mill about " ..
                "the lava flows of Shadowmoon Valley. Never have I seen beasts able to withstand the " ..
                "searing heat of molten lava!\n\nOutside of Shadowmoon Village, where the ground has " ..
                "ruptured and lava flows through the cracks, you will find felfire diemetradons. Slay " ..
                "them and bring me their spleens. From their spleens I will be able to begin preliminary " ..
                "analysis of their resistance to heat.\n\nBegin your search to the southeast.",
            rewardMoney = 41000,
        },
        [10661] = {
            description = "Have you ever heard of food that cooks itself and stays hot forever? Dare to " ..
                "dream, I say!\n\nBut maybe it's not a dream at all! Outside the fortress, near the lava " ..
                "pools and streams, you can find beasts that thrive in the sizzling heat. They're called " ..
                "felfire diemetradons.\n\nThe dwarves around here tell me that those diemetradons have " ..
                "the tastiest spleens ever and that the spleens practically come pre-cooked! Bring me " ..
                "those spleens and I'll give you some coin.\n\nStart your search directly east of here.",
            rewardMoney = 41000,
        },
        [10662] = {
            description = "<Ordinn examines the results from his attempt at smithing the metal and shakes " ..
                "his head.>\n\nThis is beyond my ability, but that's not to say the weapon can't be " ..
                "recreated for your use.\n\nThere was a talented smith who accompanied the Sons of Lothar " ..
                "to Draenor, David Wayne. He was a remarkable blacksmith, but chose to leave the " ..
                "expedition. These days, he lives in a small camp on a peninsula east of Firewing Point " ..
                "in Terokkar Forest. Take the ingots to him and see if he can help you with the weapon.",
        },
        [10663] = {
            description = "<The orc shakes his head at his failure.>\n\nThis is beyond my ability, but " ..
                "that's not to say the weapon can't be recreated.\n\nIt pains me to suggest this, but " ..
                "your only hope may be a human smith by the name of David Wayne. It's true he was once a " ..
                "member of the Alliance's expedition, but that was a long time ago and he has since left " ..
                "the Sons of Lothar. These days, he lives in a small camp on a peninsula east of Firewing " ..
                "Point in Terokkar Forest. Take the ingots to him and see if he can help you.",
        },
        [10664] = {
            description = "The ingots that you brought contain most of the metal I'll need to forge the " ..
                "sword's blade, but I'll need a variety of things to create other parts of the " ..
                "weapon.\n\nLet's see, among the things I don't have here are an adamantite frame, some " ..
                "heavy knothide leather, and a demon warding totem. Skilled crafters should be able to " ..
                "produce the first two, but the third is only sold by the reagent vendor in Shattrath's " ..
                "Lower City, Fantei. You'll find him with the other tradesmen.",
            rewardMoney = 41000,
        },
        [10665] = {
            description = "Working with the ingots you brought is going to require a lot of heat -- " ..
                "rather more than a conventional forge can supply.\n\nI'm going to need a supplemental " ..
                "heat source for the forge and there are very few things in Outland that can supply that " ..
                "kind of power.\n\nThe Mechanar area of Tempest Keep turns out manacells containing an " ..
                "incredible amount of power. Find one of the overcharged manacells from the stacks around " ..
                "Mechano-Lord Capacitus and bring it back here.",
        },
        [10666] = {
            description = "Recreating the enchantments on the blade requires several spells to be spoken " ..
                "in demonic.\n\nIt's not something I was taught during my training as an apprentice, but " ..
                "there's no way around it. There's a book, called the Lexicon Demonica, that will provide " ..
                "most of the words I need, but it's in the hands of a powerful Shadow Council " ..
                "warlock.\n\nDeep in the halls of Auchindoun's Shadow Labyrinth, it is held by " ..
                "Grandmaster Vorpil. Do whatever you must to secure the book and bring it to me.",
            rewardMoney = 41000,
        },
        [10667] = {
            description = "The frame that you brought me earlier will not be sufficient to hold molten " ..
                "metal without reinforcement. A rare kind of earth can be used to cool and imbue the " ..
                "frame, giving the adamantite an unnatural strength.\n\nUnderworld loam, as the earth is " ..
                "known, is accorded great value among the naga. Few enough of them possess it, and in " ..
                "Outland, I know of only one naga who uses it -- Hydromancer Thespia, who resides in the " ..
                "Steamvault of Coilfang Reservoir.",
            rewardMoney = 44000,
        },
        [10668] = {
            description = "I still have respect for Illidan. Without him I would not have found my " ..
                "path.\n\nHe is not who he once was, however. His soul has been corrupted by power, his " ..
                "mind has been twisted by defeat. He has become what I am sworn to destroy and his pet " ..
                "servants, the Illidari, are as much of an abomination as any demon of the Burning " ..
                "Legion.\n\nHis grasp on Outland is slipping yet his reach is still vast. Prove you're " ..
                "not with him by slaying his lieutenant Lothros at Illidari Point in Shadowmoon Valley.",
        },
        [10669] = {
            description = "Some demons pledge allegiance to no one but themselves. A true enemy of demons " ..
                "finds and destroys his prey regardless of affiliation, however.\n\nThe demon Xeleth - a " ..
                "Legion defector - was once worshipped as a god by primitive swamp creatures in " ..
                "Zangarmarsh. When Draenor was nearly destroyed, he retreated into a slumber deep beneath " ..
                "Marshlight Lake. Find the portal at the lake and plant this spear into the " ..
                "ground.\n\nXeleth will awake - be ready to slay him and prove you're an enemy to all " ..
                "demons.",
        },
        [10670] = {
            description = "The sword's enchantments must be contained within a powerful focus, such as a " ..
                "gem. I know of a gem that we can use for this purpose, for there are few that can play " ..
                "host to such powerful magics without shattering.\n\nThe gem we need is called the tear " ..
                "of the earthmother. It's a powerful artifact in the hands of the ogres who created it, " ..
                "and Warbringer O'mrogg, who currently holds the gem, has many powerful allies in " ..
                "Hellfire Citadel's Shattered Halls. Take care in retrieving the tear, <name>.",
            rewardMoney = 44000,
        },
        [10671] = {
            description = "<name>, I've got something else for you to do. One of the eggheads wants to " ..
                "study the fiendling flesh beasts that can be found at Razaan's Landing, north of the " ..
                "Razor Ridge.\n\nMore to the point, they want to study the flesh of the flesh beasts that " ..
                "are there.\n\n<Dizzy makes a disgusted face.>\n\nBut, of course, they aren't willing to " ..
                "get their hands dirty, and they only want the ether-energized flesh, which it's not " ..
                "likely that all of them have.\n\nI say, beggars can't be choosers, but what can you do?",
            rewardMoney = 37000,
        },
        [10672] = {
            description = "We must study these creatures further.\n\nFar to the east - near the huge lava " ..
                "flow beneath the ruins of Baa'ri - you will find arcano control units. These controllers " ..
                "were crafted by a genius named Gnomus for the sole purpose of exploring lava via " ..
                "mechanical scorpion.\n\nHe has long since lost his mind and is now only interested in " ..
                "eating the hottest food known to gnome-kind.\n\n<Tiorus gives you a funny look.>\n\nI " ..
                "want you to use the control and tag the diemetradons of the lava flow for further study.",
            rewardMoney = 41000,
        },
        [10673] = {
            description = "Gnomus knows about the massive diemetradon and plans to eat it! He must have " ..
                "been able to see what I could see through the eyes of his arcano-scorp. Look, there's no " ..
                "time to explain. He's crazy and that craziness is going to cost us the closest thing " ..
                "we've got to a fireproof jumpsuit.\n\nGet back to the lava flow near Baa'ri and track " ..
                "down Felspine the Greater. Once you find it, kill it and bring me back its " ..
                "hide.\n\nDon't try and reason with me, <name>. I'm well past that point.",
            rewardMoney = 88000,
        },
        [10674] = {
            description = "The Razaani ethereals have been playing with some interesting technology at " ..
                "Razaan's Landing to the north.\n\nI'm sure they won't mind if you use this trap to take " ..
                "a few samples of their little pink floating light orbs? They're probably only for " ..
                "decoration anyway.\n\nThe trap has a special property to it that when opened should " ..
                "attract one of the floating balls towards it. Of course, it'll probably also alert the " ..
                "Razaani to your presence.",
            rewardMoney = 37000,
        },
        [10675] = {
            description = "<The blood drains out of Toshley 's face.>\n\nThese orbs are made up of both " ..
                "nether energy and souls, some of them gnome souls!\n\nHow dare they! Were they the ones " ..
                "killing our people that traveled north?!\n\n<name>, you must put a stop to this, and the " ..
                "only way to do that is to finish off their leader, Nexus-Prince Razaan.\n\nYou'll have " ..
                "to coax him out of hiding though. I'm guessing that you can do that by killing a lot of " ..
                "his Razaani ethereal.\n\nBring me the collection of souls that he no doubt has.",
            rewardChoices = {{31456, 1}, {31457, 1}, {31458, 1}, {31459, 1}},
            rewardItems = {{30690, 1}},
            rewardMoney = 78000,
        },
        [10676] = {
            description = "<David gathers his smithing supplies.>\n\nYou've done well in getting " ..
                "everything we'll need to reforge the anti-demon blade. Your hard work and dedication is " ..
                "about to be repaid.\n\nThe time has come to forge the sword.",
        },
        [10677] = {
            description = "I remember seeing larger diemetradons east of the Hand of Gul'dan, near the " ..
                "lava flows around the Ruins of Baa'ri. What I want you to get for me now is one " ..
                "overdeveloped felfire gizzard from the beasts around that area. You might have to kill " ..
                "several to find a gizzard like the one I described. Keep at it! One of them is bound to " ..
                "have my next meal.",
            rewardMoney = 41000,
        },
        [10678] = {
            description = "Long story short, I used to work with a blood elf named Tiorus. My partnership " ..
                "with Tiorus dissolved once I got into gourmet living. He decided to take it upon himself " ..
                "to continue our research using MY inventions. Anyhow, he had some of his Horde goons " ..
                "using my arcano-scorp probes at the Ruins of Baa'ri lava flow and discovered the mother " ..
                "of all diemetradons!\n\nI need you to get there before he does and kill the diemetradon, " ..
                "Felspine, and bring his hide back to me.\n\nHurry up!",
            rewardMoney = 88000,
        },
        [10679] = {
            description = "The blade is nearly finished!\n\nYou can almost feel the magic beginning to " ..
                "coalesce inside the steel, but one thing remains to be done.\n\nYou must take the forged " ..
                "blade to the Scalding Pools near the top of the Hand of Gul'dan in Shadowmoon Valley and " ..
                "plunge it into the lava pools to quench the sword. When you have quenched the sword, " ..
                "return.",
            rewardChoices = {{30787, 1}, {30788, 1}, {30789, 1}, {31745, 1}},
            rewardMoney = 44000,
        },
        [10680] = {
            description = "The elements need your help, <race>! Shadowmoon Valley has been subject to " ..
                "unspeakable evils. The spirits remain tortured to this day. Many are enraged and " ..
                "unwilling to commune with the Earthen Ring.\n\nHelp this world heal, friend.\n\nDirectly " ..
                "northeast of Wildhammer Stronghold you will find an area known as the Altar of " ..
                "Damnation. Make your way there and speak with Earthmender Torlok.",
        },
        [10681] = {
            description = "The elements need your help, <race>! Shadowmoon Valley has been subject to " ..
                "unspeakable evils. The spirits remain tortured to this day. Many are enraged and " ..
                "unwilling to commune with the Earthen Ring.\n\nHelp this world heal, " ..
                "friend.\n\nSoutheast of Shadowmoon Village - in the heart of Shadowmoon Valley - you " ..
                "will find an area known as the Altar of Damnation. Make your way there and speak with " ..
                "Earthmender Torlok.",
        },
        [10682] = {
            description = "When we arrived in the Ruuan Weald, the wyrm cultists were keeping themselves " ..
                "to Blackwing Coven, through the tunnel to the west. But now, they are encroaching upon " ..
                "us here.\n\nI need you to find the wyrmcultists' overseer. He's known to make a regular " ..
                "patrol between their various camps in the Ruuan Weald.\n\nNegotiate with him. Let him " ..
                "know that there's room for compromise, but that we will not condone or allow the " ..
                "wholesale slaughter of the wildlife, nor the felling of all of the trees.",
            rewardMoney = 37000,
        },
        [10683] = {
            description = "The Ashtongue Broken have been ordered by Illidan to excavate the Ruins of " ..
                "Baa'ri, to the far north. They're in search of draenei artifacts, no doubt - Baa'ri was " ..
                "home to many Baa'ri relics before Gul'dan buried the town under a volcanic explosion. We " ..
                "must use this opportunity to recover the Tablets of Baa'ri, an ancient text rumored to " ..
                "hold the secrets of the Temple of Karabor... a place you might know as the Black Temple.",
        },
        [10684] = {
            description = "According to the tablets, an artifact known as a Medallion of Karabor was kept " ..
                "at Baa'ri. Only the highest-ranking draenei priests were granted these, as they allowed " ..
                "unfettered access into the Temple of Karabor.\n\nWe must find out whether the Ashtongue " ..
                "have recovered the medallion that was kept at Baa'ri yet. Its power would provide great " ..
                "aid in our fight against Illidan.\n\nAkama's lieutenant at Baa'ri, Oronu the Elder, " ..
                "receives written orders from him daily. Obtain them and bring them to me.",
        },
        [10685] = {
            description = "According to Akama's letter, four fragments of the medallion were unearthed " ..
                "and given to the Ashtongue Corruptors. These dreaded Broken were once powerful shaman " ..
                "who now defile the very elements they revered.\n\nHaalum, Corruptor of Air, can be found " ..
                "at Netherwing Pass. Eykenen and Uylaru, Corruptors of Earth and Fire, were last seen at " ..
                "the Fel Pits near the Hand of Gul'dan. Lakaan, Corruptor of Water, is rumored to be near " ..
                "Coilskar Point.\n\nFind them and obtain the medallion fragments.",
        },
        [10686] = {
            description = "The fragments you obtained are only half of the medallion. The Ashtongue " ..
                "leader, Akama, must have kept the other half.\n\nI dread to ask this of you, as Akama is " ..
                "both evil and cunning.\n\nHe and the Ashtongue Deathsworn - the vilest and most brutal " ..
                "of the tribe - are rumored to run a torture chamber inside the Warden's Cage.\n\nI want " ..
                "you to find that dreaded prison, and find the whereabouts of Akama. His second in " ..
                "command at the location is a Broken known as Sanoru - interrogate him if you have to.",
        },
        [10687] = {
            description = "Our scouts have reported a massive influx of Sunfury blood elf recruits " ..
                "heading to the Ruins of Karabor. Normally this would represent a purely military threat, " ..
                "however we believe something else is amiss.\n\nDescriptions of their attire and fighting " ..
                "style are suspiciously close to that of Illidan himself. I do not want to become alarmed " ..
                "without good reason, so I would like you to go there and bring me back their weapons. We " ..
                "will then determine whether my fears are unfounded or not.",
        },
        [10688] = {
            description = "The weapons are authentic, as we feared. Illidan is training demon hunters at " ..
                "the Ruins of Karabor and we must put an end to it.\n\nDo not be fooled by their name, " ..
                "<name>, their power will be used against us as often as against any demon.\n\nTheir " ..
                "warlocks summon and subdue demons to be used as part of the initiates' training. A pit " ..
                "lord named Azaloth has proven too strong to be used in training and is kept banished. " ..
                "Find a way to let him loose on his captors. That should buy us the time we need.",
        },
        [10689] = {
            description = "You don't see many demon hunters nowadays. They're viewed with suspicion by " ..
                "their own people and it's very rare to find one that doesn't have some sort of " ..
                "allegiance to Illidan.\n\nThere are rumors of one such demon hunter out in Nagrand. His " ..
                "name is Altruis. He hates all demons with a passion and will help us if you can convince " ..
                "him that you share his goals.\n\nGo to western Nagrand and find him. He might be willing " ..
                "to shed some light on these new demon hunter training grounds.",
        },
        [10690] = {
            description = "WANTED!\n\nRema, the den mother and primary defender of the Jagged Ridge south " ..
                "of Thunderlord Stronghold.\n\nFind her by heading east out of town and across the bridge " ..
                "that traverses the Bloodmaul Ravine. She keeps herself secluded in the tunnel at the " ..
                "southern edge of the ridge.\n\nReturn with news of her demise to Commander Skyshadow of " ..
                "Sylvanaar.",
            rewardChoices = {{31422, 1}, {31423, 1}, {31424, 1}},
            rewardMoney = 35000,
        },
        [10691] = {
            description = "This book... I could use it to increase my power tenfold... No! It would end " ..
                "up corrupting my very soul, this I am sure of. Return to those who sent you here, " ..
                "<name>.\n\nYou now have the means to stop Varedis. Wait until he manifests his demonic " ..
                "form through metamorphosis, at that point you will need to burn the book in his " ..
                "presence. That will be the only way you can deprive him of his power.",
        },
        [10692] = {
            description = "Of course we must destroy this book, but not before we use it to destroy " ..
                "Varedis.\n\nIf we're to shut down this academy of Illidan imitators, we'll have to deal " ..
                "not just with Varedis but also the three night elf masters that assist him: Alandien, " ..
                "Theras and Netharel.\n\nGather a suitable force and return to the Ruins of Karabor. " ..
                "Follow Altruis's instructions for defeating Varedis. Hopefully his plan will work - " ..
                "otherwise... it'll have been a pleasure working with you.",
            rewardChoices = {{30933, 1}, {30948, 1}, {31002, 1}, {31009, 1}, {31010, 1}, {31013, 1}},
        },
        [10701] = {
            description = "To whomever cares about the timely construction of the X-52 Nether-Rocket " ..
                "--\n\nThe king of the local mountain giants, Netherock, has been terrorizing the " ..
                "Crumbling Wastes. He's been interfering with operations all along the south ledge of the " ..
                "island!\n\nTake your friends and deal with him! Then, return to me here in Area " ..
                "52.\n\nRocket-Chief Fuselage",
            rewardChoices = {{31312, 1}, {31313, 1}, {31314, 1}, {31315, 1}},
            rewardMoney = 78000,
        },
        [10702] = {
            description = "All Horde forces in this region have been dispatched to handle the attacks " ..
                "from the Burning Legion. This means that we are short-handed for grunt work.\n\nOur " ..
                "supply caravans are in constant danger from the wildlife of the region. We can't veer 15 " ..
                "feet off the road without running into a chimaera, felboar, or abnormally large " ..
                "scorpion.\n\nGet out there and clear Shadowmoon Valley of its sadistic wildlife! Just " ..
                "kill 'em all!",
            rewardMoney = 123000,
        },
        [10703] = {
            description = "It's time to get down in the muck and get dirty. What were you expectin'? You " ..
                "gotta learn to walk before you can crawl, right? Er, reverse that...\n\nAnyway, we got " ..
                "all hands on deck fer killin' the garbage being thrown at us by the Burning Legion. That " ..
                "leaves you with the honor of cleaning up the crazed wildlife of Shadowmoon " ..
                "Valley.\n\nGrab a sword, staff, whatever it is that makes you happy, and kill as much of " ..
                "the wildlife as you can see. That'll clear a way out for our supply caravans!",
            rewardMoney = 123000,
        },
        [10704] = {
            description = "A message was embedded in the ata'mal crystal that you recovered. Nexus-Prince " ..
                "Haramad has given us information vital to our campaign against Tempest Keep.\n\nHe tells " ..
                "us that there are two pieces, shards to a key, which, when combined, will unlock the " ..
                "keep's Arcatraz satellite.\n\nOne half is possessed by an ancient in the Botanica known " ..
                "as Warp Splinter. The other is held by Pathaleon the Calculator inside the " ..
                "Mechanar.\n\nBring both shards to me and I will combine them into the Arcatraz key.",
            rewardChoices = {{31460, 1}, {31461, 1}, {31462, 1}, {31464, 1}, {31465, 1}},
            rewardItems = {{31084, 1}},
            rewardMoney = 132000,
        },
        [10705] = {
            description = "I hope you're not shocked when I reveal to you that the pieces of the " ..
                "Medallion of Karabor you obtained from my minions are mere replicas.\n\n< Akama shows " ..
                "you an identical medallion in his open palm.>\n\nMy Deathsworn and I have kept the " ..
                "secret from Illidan for as long as possible. We are however, still missing the final " ..
                "piece.\n\nUdalo came to me in dreams to announce he had found it. Unfortunately he is " ..
                "held by Kael'thas inside the Arcatraz in Tempest Keep. Find him and see what he knows.",
        },
        [10706] = {
            description = "Before he died, Udalo appears to have written a single word on the floor " ..
                "beneath him. The writing is barely legible but you recognize the word " ..
                "Atam'al.\n\nPerhaps Akama will understand the meaning of his brethren's message.",
        },
        [10707] = {
            description = "It has been known to us that the fel orcs, under Illidan's command, have " ..
                "guarded an Ata'mal crystal known as the Heart of Fury at the Ata'mal Terrace. They cloud " ..
                "its presence with dark magic, to keep it from the Sha'tar.\n\nFight your way to the " ..
                "Ata'mal Terrace outside the Black Temple and turn your eyes to the sky. Shadowlord " ..
                "Deathwail will circle the terrace, beyond your reach. You will have to slay him and his " ..
                "warlocks before you can obtain the crystal.\n\nIt won't be easy, <name>. I wish you luck.",
        },
        [10709] = {
            description = "So you come from the world beyond the Portal? And you know of Rexxar. Oh yes, " ..
                "I am quite familiar with him.\n\nYou see, he is my son.\n\nBut he made his choice a " ..
                "lifetime ago. He is not one of us, and he is not welcome here. We have enough troubles " ..
                "with the Bloodmaul ogres.\n\nKnow this: being born a half-breed does not make you " ..
                "Mok'Nathal.",
        },
        [10710] = {
            description = "I've been fiddling with the Zephyrium Capicitorium and I'm ready to perform " ..
                "another test! Do you want to help?\n\nThis next flight should be short, but " ..
                "fast!\n\nUm... and although I'm sure there's no danger... I have this, uh, waiver that " ..
                "I'd like you to sign. It's just a formality, I assure you!\n\nBest of luck! Talk to " ..
                "Rally to launch yourself, and come back to me after the experiment is over!",
            rewardMoney = 16000,
        },
        [10711] = {
            description = "<name>, I raised the efficiency of the Zephyrium Capacitorium by 30 percent. " ..
                "That will launch a test subject of your weight and wind drag ratio to new heights! Want " ..
                "to test my theory? This experiment ought to send you near Razaan's Landing.\n\nSpeak " ..
                "with Rally... he'll get you prepared for launch.",
            rewardMoney = 24000,
        },
        [10712] = {
            description = "Hey, <name>. I'm glad I caught you! I have a very important mission!\n\nHere " ..
                "is a nether-weather vane. I need you to take some in flight readings for me and deliver " ..
                "them to my cousin in Ruuan Weald.\n\nSpeak with Rally and take a Zephyrium Capacitorium " ..
                "flight to Ruuan Weald. While you're flying, spin the vane!\n\nAfter you land, bring the " ..
                "spinning vane to O'Mally Zabnabber.\n\nGood luck, <name>. And don't delay!",
            rewardMoney = 31000,
        },
        [10713] = {
            description = "We will not stand idly by while they decimate the Ruuan Weald around us. Our " ..
                "first priority must be to the trees.\n\n<class>, I want you to go back out into the " ..
                "Weald and deliver a very different message for us. I want you to slay every one of their " ..
                "hewers that you come into contact with!\n\nIf they will not listen to reason, perhaps " ..
                "they will listen to a more assertive method of persuasion!",
            rewardChoices = {{31510, 1}, {31512, 1}, {31516, 1}, {31521, 1}},
            rewardMoney = 37000,
        },
        [10714] = {
            description = "If the Mok'Nathal are tormented by the Bloodmaul ogres, then I will stop them " ..
                "and their followers. Ogres are simple creatures, and there is little profit they could " ..
                "gain from harassing the Mok'Nathal.\n\nThere must be something more to this. <name>, " ..
                "take Spirit, my hawk, and spy upon the conversations of the Bloodmaul's leaders. He may " ..
                "go undetected where we cannot.",
            rewardMoney = 37000,
        },
        [10715] = {
            description = "So, your Rexxar would have me fashion a poison for him? I'll give him what he " ..
                "desires, but there will be a price. Even for friends, there must be a price. Free things " ..
                "destroy friendships.\n\nFirst, you must venture a short distance to the southwest to the " ..
                "Churning Gulch.\n\nTherein mill some of the most poisonous creatures in all of Outland, " ..
                "or anywhere. I speak of the crust bursters, and this poison will require gathering their " ..
                "glands for me.",
            rewardItems = {{31535, 5}},
            rewardMoney = 37000,
        },
        [10717] = {
            description = "Pardon me, but I couldn't help but overhear your conversation with Chawn. I'd " ..
                "like to help.\n\nI'm studying the Blackwing Coven, and helping the druids in their " ..
                "dealings with them.\n\nI am very interested in acquiring a few of their dragon whelps; " ..
                "it would help us to gauge exactly what we're up against by understanding that which they " ..
                "revere.\n\nBut first, we're going to need to acquire some nets. I noticed that the " ..
                "wyrmcult poachers out in the Ruuan Weald have an abundance of them.",
            rewardMoney = 37000,
        },
        [10718] = {
            description = "<name>, now that you can see me, there is something you must tell Rexxar. I " ..
                "know that he seeks his people, and I know where they are.\n\nThe Mok'Nathal, as they are " ..
                "known, have a village to the east beyond the Razor Ridge.\n\nGo, give Rexxar this news. " ..
                "His people are in danger, and I know that he will want to come to their aid.",
        },
        [10719] = {
            description = "The cultist dropped this note, which apparently was to be delivered to " ..
                "Overseer Nuaar. It is signed by someone named Kolphis Darkscale.\n\nIt is likely that " ..
                "Tree Warden Chawn will be interested in looking at this.",
        },
        [10720] = {
            description = "The ogres, simple as they are, would notice you dispersing this poison " ..
                "throughout their camp. Thus, I will teach you how to enlist the help of one of nature's " ..
                "smallest creatures to do this task.\n\nBy playing a simple rhythm on this drum, you can " ..
                "coax a marmot to follow your commands.\n\nThere is a den of marmots near the Bloodmaul " ..
                "camp, to the north, down in the Daggermaw Canyon past the Circle of Blood.\n\nOnce you " ..
                "have a marmot's aid, use it to disperse the poison to the Bloodmaul's kegs.",
            rewardMoney = 37000,
        },
        [10721] = {
            description = "<name>, I have a pet boar named Huffer. He wants to help you to have some fun " ..
                "with one of the nearby sons of Gruul.\n\nGrulloc inhabits a place known as the Cursed " ..
                "Hollow. When you get there, let Huffer loose. The gronn will have a fine time chasing " ..
                "him around, and you will retrieve the bag that he guards and deliver it to Baron " ..
                "Sablemane.\n\nTo get to the Cursed Hollow, head down the northern ramp and east through " ..
                "Dragons' End. The hollow is on the eastern edge.",
            rewardMoney = 37000,
        },
        [10722] = {
            description = "I know what must be done! <name>, you must pose as Overseer Nuaar and attend " ..
                "that meeting!\n\nThe wyrmcultists at the coven all have a standard outfit that they " ..
                "wear, so go collect scraps from them, and when you have enough, put together a " ..
                "disguise.\n\nPose as Overseer Nuuar and speak with Kolphis Darkscale to see what he has " ..
                "to say, and then return to Tree Warden Chawn.\n\nYou'll find the coven by heading " ..
                "through the Wyrmskull Tunnel and following the path past the Raven's Wood and Grishnath " ..
                "to its end.",
            rewardMoney = 39000,
        },
        [10723] = {
            description = "The gronn we seek is Gorgrom the Dragon-Eater. With Sablemane's trap, you will " ..
                "make short work of the gronn. You will find him accepting sacrifices from the ogres of " ..
                "Boulder'mok.\n\nFollow the road north from the Circle of Blood, then west at Ruuan " ..
                "Weald. Go northwest through the tunnel.\n\nFirst, kill the ogres for their heads. We " ..
                "will send a message. Set the trap at his altar. When he is dead, plant the grisly totems " ..
                "near him - none can mistake that message.\n\nTake the bear.\n\n<Misha growls.>",
            rewardChoices = {{31541, 1}, {31542, 1}, {31543, 1}},
        },
        [10724] = {
            description = "Shortly after my arrival in the mountains, I came under attack by a group of " ..
                "Bladespire ogres.\n\nThough I fought free of them, and slew many, they took my wyvern, " ..
                "Leokk, captive. Spirit has found him, locked in a cage in the heart of the Bladespire " ..
                "encampment outside of Gruul's lair.\n\nOne of the ogres must carry his key. Find it and " ..
                "Spirit can use it to unlock Leokk's cage.\n\nYou will find the encampment at the north " ..
                "end of the Daggermaw Canyon down below.",
            rewardMoney = 37000,
        },
        [10725] = {
            description = "Your services have gone above and beyond what is expected of you, <name>. You " ..
                "are but a step away from achieving the highest honor available to non-citizens of " ..
                "Dalaran.\n\nContinue to prove your loyalty to us and I will empower your signet to its " ..
                "full capacity.",
            rewardItems = {{29287, 1}},
        },
        [10726] = {
            description = "Your services have gone above and beyond what is expected of you, <name>. You " ..
                "are but a step away from achieving the highest honor available to non-citizens of " ..
                "Dalaran.\n\nContinue to prove your loyalty to us and I will empower your signet to its " ..
                "full capacity.",
            rewardItems = {{29290, 1}},
        },
        [10728] = {
            description = "Your services have gone above and beyond what is expected of you, <name>. You " ..
                "are but a step away from achieving the highest honor available to non-citizens of " ..
                "Dalaran.\n\nContinue to prove your loyalty to us and I will empower your signet to its " ..
                "full capacity.",
            rewardItems = {{29279, 1}},
        },
        [10729] = {rewardItems = {{29284, 1}}},
        [10730] = {rewardItems = {{29288, 1}}},
        [10731] = {rewardItems = {{29280, 1}}},
        [10732] = {rewardItems = {{29276, 1}}},
        [10733] = {
            description = "You've chosen your path, <class>. Now it is up to you to travel the path to " ..
                "wherever it may lead.\n\nYou will find that having friends among the Archmages of " ..
                "Dalaran has its advantages. Serve us well and your deeds will not go unrewarded.",
            rewardItems = {{29285, 1}},
        },
        [10734] = {
            description = "You've chosen your path, <class>. Now it is up to you to travel the path to " ..
                "wherever it may lead.\n\nYou will find that having friends among the Archmages of " ..
                "Dalaran has its advantages. Serve us well and your deeds will not go unrewarded.",
            rewardItems = {{29289, 1}},
        },
        [10735] = {
            description = "You've chosen your path, <class>. Now it is up to you to travel the path to " ..
                "wherever it may lead.\n\nYou will find that having friends among the Archmages of " ..
                "Dalaran has its advantages. Serve us well and your deeds will not go unrewarded.",
            rewardItems = {{29281, 1}},
        },
        [10736] = {
            description = "You've chosen your path, <class>. Now it is up to you to travel the path to " ..
                "wherever it may lead.\n\nYou will find that having friends among the Archmages of " ..
                "Dalaran has its advantages. Serve us well and your deeds will not go unrewarded.",
            rewardItems = {{29277, 1}},
        },
        [10739] = {
            description = "You have not disappointed us, <name>. We continue to have very high hopes for " ..
                "you, however.\n\nContinue to serve the Violet Eye and you will be appropriately rewarded.",
            rewardItems = {{29291, 1}},
        },
        [10740] = {
            description = "You have not disappointed us, <name>. We continue to have very high hopes for " ..
                "you, however.\n\nContinue to serve the Violet Eye and you will be appropriately rewarded.",
            rewardItems = {{29282, 1}},
        },
        [10741] = {
            description = "You have not disappointed us, <name>. We continue to have very high hopes for " ..
                "you, however.\n\nContinue to serve the Violet Eye and you will be appropriately rewarded.",
            rewardItems = {{29278, 1}},
        },
        [10742] = {
            description = "Now it comes to this. We will bring Goc forth from his lair, and we will " ..
                "destroy him. With Goc dead, the Bladespire ogres will threaten the Mok'Nathal no longer. " ..
                "Go to Goc 's altar outside Gruul's Lair, then blow my horn. I will come, and we will " ..
                "face the son of Gruul together.",
            rewardChoices = {{31544, 1}, {31545, 1}, {31546, 1}, {31547, 1}, {31548, 1}, {31549, 1}},
            rewardMoney = 132000,
        },
        [10744] = {
            description = "You must bring word of our success to Kurdran Wildhammer immediately! His men, " ..
                "under Wing Commander Nuainn, have fought nonstop to keep Wildhammer Stronghold safe and " ..
                "your return will surely bolster their spirits. With the threat from the Legion out of " ..
                "the way, Kurdran can finally turn his attention to dealing with the forces of Illidan. " ..
                "Our place here is far from secure, but we've won a major victory this day.",
            rewardChoices = {{30924, 1}, {30973, 1}},
            rewardMoney = 44000,
        },
        [10745] = {
            description = "You must bring word of our success to Overlord Or'barokh immediately! Now that " ..
                "we've crushed the Legion and obliterated their presence in Shadowmoon Valley, the " ..
                "overlord can turn his attention to our other foes.\n\nAlthough the Kor'kron guard will " ..
                "never admit it, they'll be glad we're no longer fighting on two fronts.",
            rewardChoices = {{30924, 1}, {30973, 1}},
            rewardMoney = 44000,
        },
        [10747] = {
            description = "I need to examine the whelps that they are raising at the Blackwing " ..
                "Coven.\n\nThere should be an abundance of them flying around inside their cavernous " ..
                "base, as well as a number of eggs, which if you get close to them will likely " ..
                "hatch.\n\nPlease, <name>, take the net and capture a handful of them alive for " ..
                "me.\n\nFind them by heading west across the Wyrmskull Bridge and heading through the " ..
                "Wyrmskull Tunnel. Follow the path to its end past Grishnath and the Raven's Wood.",
            rewardChoices = {{31509, 1}, {31513, 1}, {31515, 1}, {31519, 1}},
            rewardMoney = 39000,
        },
        [10748] = {
            description = "They've left us no choice, <name>. It's time to put an end to the threat from " ..
                "the Blackwing Coven by taking out their leader, Maxnar the Ashmaw.\n\nI don't know if " ..
                "you caught a glimpse of him while you were in there, but he's one of the dragonkin, " ..
                "half-man, half-dragon. And he's tough, so don't underestimate him!\n\nFinish it quickly " ..
                "and with any luck you'll secure the safety of Evergrove and the Ruuan Weald.",
            rewardChoices = {{31508, 1}, {31511, 1}, {31514, 1}, {31520, 1}},
            rewardMoney = 78000,
        },
        [10749] = {
            description = "Here, take this to your master. I'm sure that whatever the reason, Rexxar will " ..
                "put it to good use.\n\nOh, and do be certain to remind him that he owes me.\n\nHe knows " ..
                "what I want, and I'm certain that however he intends to obtain it for me, I'll be seeing " ..
                "you again sooner than you think.\n\nNow, do be a good little <boy/girl> and run this up " ..
                "to Rexxar.",
        },
        [10750] = {
            description = "Word has come from my wind riders, <name>. The Eclipsion blood elves are " ..
                "planning something big. They have begun forming their armies at the Path of Conquest, " ..
                "far to the southeast - adjacent to Eclipse Point.\n\nI want you to travel to the Path of " ..
                "Conquest and assess the situation. Once you have done so, use this flare gun to signal a " ..
                "wind rider. One will swoop down from the sky to meet you. Inform them of what you have " ..
                "discovered and they will give you your next set of orders.",
        },
        [10751] = {
            description = "We're going to need more time, <race>. I'm going to fly further ahead with " ..
                "some of the other wind riders. Hopefully, we can gather some more information. What I " ..
                "need from you now is to clear a path and more importantly, keep their arrows pointed " ..
                "away from us!\n\nCall for a wind rider with the Kor'kron flare gun once you have thinned " ..
                "their numbers.",
        },
        [10753] = {
            description = "The number of atrocities committed by the Burning Legion is countless. Even as " ..
                "we speak, they send their legion forces against the creatures of this land. Helpless to " ..
                "defend against their power, they fall one by one. <name>, help me stop these crimes of " ..
                "nature destroy all which they corrupt.\n\nOver the hill, east of here, you will see the " ..
                "corruption spreading across Bladed Gulch. Kill the ones causing the crime, the Fel " ..
                "Corrupters, and as many Felsworn as you can.",
            rewardMoney = 29000,
        },
        [10759] = {
            description = "I get the feeling that all the pieces are here, but I just can't put them " ..
                "together in a way that makes sense.\n\nI think our best lead is to attempt to locate " ..
                "this deserter. If he left his comrades at the camp, there's a chance you might be able " ..
                "to persuade him to help us understand what the dark conclave arakkoa are " ..
                "planning.\n\nStart your search for him along the road in Magma Fields to the northwest. " ..
                "It seems a likely place for him to take refuge.",
        },
        [10760] = {
            description = "The Sketh'lon Wreckage, just to the east, is an eerie place. The peons are " ..
                "convinced that it's cursed.\n\nThere are few trees here, so the peons have no choice but " ..
                "to venture into the arakkoa ruins to chop wood. The arakkoa spirits prey on the work " ..
                "groups, draining their life and using it to fuel their foul magics.\n\nWe must find out " ..
                "what is driving the dark conclave and stop them before their influence expands. Search " ..
                "the Sketh'lon Wreckage for evidence of their plans.",
            rewardMoney = 41000,
        },
        [10761] = {
            description = "There's nothing here that would explain why the spirits of these arakkoa have " ..
                "remained in this world or how they came into thirst for the blood of orcs.\n\nI think " ..
                "our best lead is to try to find the deserter mentioned in the journal. If he left his " ..
                "comrades at the camp, there's a chance you might be able to persuade him to help us " ..
                "understand what the dark conclave arakkoa are planning.\n\nStart your search for him on " ..
                "the road through the Magma Fields to the southeast.",
        },
        [10762] = {
            description = "The symbol on the key's handle... it is hard to make it out inside the mold, " ..
                "but I recognize it at the Shattered Hand's own.\n\nThere is a good chance this key will " ..
                "allow you to enter the Shattered Halls.\n\nSpeak to Dumphry. He is a master of his " ..
                "craft. If he can't craft this key for you, no one can.",
        },
        [10763] = {
            description = "Fel orcs might be complete barbarians but their smithing is not as primitive " ..
                "as you might think. Only fel iron can be used with this mold if we want to end up with a " ..
                "working key - anything else would probably end up breaking it.\n\nBring me some fel iron " ..
                "bars, a bit of arcane dust and motes of fire. I'll try my hand at it, but I make no " ..
                "promises.",
        },
        [10764] = {
            description = "It's not working, <lad/lass>. I cannot give it enough heat... the materials " ..
                "will not be properly tempered.\n\nYou know, the fel reavers used by the Burning Legion " ..
                "are powered by a scalding core of fel fire - it burns much hotter than normal " ..
                "fire.\n\nIf you could find enough people to take one down, you could heat the mold in " ..
                "the insides of the fallen reaver. Beware, <class>, those fel reavers pack quite a punch.",
            rewardItems = {{28395, 1}},
        },
        [10765] = {
            description = "At the southern end of the Path of Conquest, near a stationary caravan, I " ..
                "discovered what looked like a meeting between a giant and a blood elf chancellor. You've " ..
                "probably already noticed the smaller giants on the path as well. Something is just not " ..
                "right about all of this, grunt.\n\nI want you to fight your way to this meeting and " ..
                "break up the party. Recover whatever you can from the scene and then call for one of us " ..
                "with the flare gun.",
        },
        [10766] = {
            description = "Now that we have access to the Legion's base at Invasion Point: Cataclysm, we " ..
                "need to figure out a way to shut down their operations there. Wildhammer Stronghold " ..
                "won't be safe until the Legion's presence is erased from Shadowmoon Valley.\n\nI've sent " ..
                "an advance party up to the invasion point to help you formulate a plan to destroy the " ..
                "Legion's supplies. Go back to Legion Hold and step into the teleporter with the green " ..
                "crystals above it. Plexi will meet you at your destination.",
        },
        [10767] = {
            description = "Now that we have access to the Legion's base at Invasion Point: Cataclysm, we " ..
                "need to figure out a way to shut down their operations there. Shadowmoon Village won't " ..
                "be safe until the Legion's presence is erased from the valley.\n\nI've sent an advance " ..
                "party up to the invasion point to help you formulate a plan to destroy the Legion's " ..
                "supplies. Go back to Legion Hold and step into the teleporter with the green crystals " ..
                "above it. Nakansi will meet you at your destination.",
        },
        [10768] = {
            description = "The wind riders must return to Shadowmoon Village to prepare for the next " ..
                "phase of our assault. What I need from you now are the tabards that these blood elves " ..
                "wear.\n\nWhen you have collected enough tabards, call for a wind rider using the " ..
                "Kor'kron flare gun. Prepare yourself for a bit of espionage, <race>!",
        },
        [10769] = {
            description = "Researcher Tiorus was kind enough to put this concoction together for the " ..
                "final strike. I merely pour it upon this tabard that you have provided for me and the " ..
                "item is imbued with the essence of the Illidari filth.\n\nTake the enchanted tabard and " ..
                "travel to the Eclipsion Fields, southwest of Eclipse Point. Once there, use the tabard " ..
                "to transform into an agent of Illidan. While in disguise, slay the crazed colossi that " ..
                "wander the field. They will think it an attack by the Eclipsion and sever all ties!",
            rewardChoices = {{31075, 1}, {31077, 1}, {31076, 1}, {31078, 1}},
            rewardMoney = 132000,
        },
        [10770] = {
            description = "Northeast of here, on the plateau above us lies the burnt ashes of my ancient " ..
                "home. A great wood flourished there before the Burning Legion sent their imps to burn us " ..
                "away. So many died that even centuries later my tired old heart hungers for revenge. " ..
                "There are too many of them for us to ever reclaim the land, but you could make them " ..
                "afraid.\n\nSurely you will help me?",
            rewardMoney = 37000,
        },
        [10771] = {
            description = "If you follow the road east and up the side of the mountain, then turn north, " ..
                "you will come to my long lost home.\n\nOnce there was a wood there. Its name is " ..
                "forgotten. Long ago the Burning Legion summoned scorched imps and other creatures of " ..
                "flame. My home was destroyed and my people fled. Now only I remain.\n\nI have saved some " ..
                "ironroot seeds that could be planted in fertile volcanic soil. Their magic is strong. Do " ..
                "this for me and I will share with you the treasures of a forgotten age.",
            rewardChoices = {{31414, 1}, {31415, 1}, {31416, 1}},
            rewardMoney = 37000,
        },
        [10772] = {
            description = "My gryphon riders have come back with a bit of news! The Eclipsion blood elves " ..
                "are planning something big. They've begun forming their armies at the Path of Conquest, " ..
                "located east of here - adjacent to Eclipse Point.\n\nI want you to travel to the Path of " ..
                "Conquest and assess the situation. Once you've done so, use this flare gun to signal a " ..
                "gryphon rider. One will swoop down from the sky to meet you. Tell 'em what you've " ..
                "discovered and they'll give you the next set of orders.",
        },
        [10773] = {
            description = "We're going to need more time, <race>. I'm going to fly further ahead with " ..
                "some of the other gryphon riders. Hopefully, we can gather some more information. What I " ..
                "need from you now is to clear a path and more importantly, keep their arrows pointed " ..
                "away from us!\n\nCall for a gryphon rider with the Wildhammer flare gun once you have " ..
                "thinned their numbers.",
        },
        [10774] = {
            description = "At the southern end of the Path of Conquest, near a stationary caravan, I " ..
                "discovered what looked like a meeting between a giant and a blood elf chancellor. What " ..
                "are giants even doing here? Something is just not right about all of this, grunt.\n\nI " ..
                "want you to fight your way to this meeting and break up the party. Recover whatever you " ..
                "can from the scene and then call for one of us with the flare gun.",
        },
        [10775] = {
            description = "The gryphon riders must return to Wildhammer Stronghold to prepare for the " ..
                "next phase of our assault. What I need from you now are the tabards that these blood " ..
                "elves wear.\n\nWhen you have collected enough tabards, call for a gryphon rider using " ..
                "the Wildhammer flare gun. Prepare yourself for a bit of espionage, <race>!",
        },
        [10776] = {
            description = "Gnomus was kind enough to put this concoction together for the final strike. I " ..
                "merely pour it upon this tabard that you have provided for me and the item is imbued " ..
                "with the essence of the Illidari filth.\n\nTake the enchanted tabard and travel to the " ..
                "Eclipsion Fields, southwest of Eclipse Point. Once there, use the tabard to transform " ..
                "into an agent of Illidan. While in disguise, slay the crazed colossi that wander the " ..
                "field. They will think it an attack by the Eclipsion and sever all ties!",
            rewardChoices = {{31075, 1}, {31077, 1}, {31076, 1}, {31078, 1}},
            rewardMoney = 132000,
        },
        [10777] = {
            description = "What you read in the commander's journal is true. While the orcish Horde " ..
                "massed under Gul'dan, my people sought to defend ourselves from the threat by striking " ..
                "against him. Gul'dan learned of their intentions and cast a mighty spell that destroyed " ..
                "our camps and twisted the spirits of my brothers.\n\nThey must be stopped before they " ..
                "unleash a greater evil. In the Sketh'lon Wreckage to the north, seek out Asghar and " ..
                "bring me the totem he carries. With it, we can begin to thwart the dark conclave's plans.",
            rewardMoney = 41000,
        },
        [10778] = {
            description = "The totem alone is not strong enough to counteract the sinister magics of the " ..
                "dark conclave.\n\nWe can combine it with other objects of power, forming a staff to " ..
                "focus the energies. We cannot rescue my brethren from the depths of their depravity, but " ..
                "we can stop them.\n\nOne of the items I need for the staff is the Rod of Lianthe, held " ..
                "by the blood elves at Eclipse Point to the southeast. It is kept in a pavilion on the " ..
                "top tier of the ruins and will be heavily guarded. Use caution, <name>.",
            rewardMoney = 41000,
        },
        [10780] = {
            description = "There is one last element missing from the staff. We must direct the staff's " ..
                "power toward the Dark Conclave spirits.\n\nWe can do that by gathering feathers " ..
                "scattered on the ground at the Sketh'lon Base Camp and using them in the staff. The base " ..
                "camp is to the south, east of Wildhammer Stronghold.\n\nGul'dan's magic utterly " ..
                "destroyed my brethren, leaving only their spirits, but it did not stop there. The magic " ..
                "fed on the spell the arakkoa were preparing, forging a sinister force that engulfed the " ..
                "spirits.",
            rewardMoney = 41000,
        },
        [10781] = {
            description = "They are probably searching for you on the Path of Conquest as we speak. You " ..
                "must make your escape, <race>!\n\nLeave me, I'm done for... They... I think I hear them " ..
                "coming. It's now or never! Get out! If you choose to stay, you will have to fight!\n\nIf " ..
                "you fight and somehow manage to survive, take what you have learned here and deliver " ..
                "that knowledge to A'dal in Shattrath City.",
            rewardChoices = {{31380, 1}, {31381, 1}, {31382, 1}, {31383, 1}},
            rewardItems = {{31408, 1}},
            rewardMoney = 132000,
        },
        [10782] = {
            description = "The staff is nearly finished!\n\nAll that remains is to imbue the headpiece " ..
                "with power flowing from the echoes of Gul'dan in this accursed place. To the east, near " ..
                "the Fel Pits and south of the Deathforge, is the Altar of Damnation.\n\nThere, fragments " ..
                "of Gul'dan's past are trapped. When you carry the unfinished headpiece of the staff into " ..
                "the area around the altar, don't be surprised if some of the entities react to it. You " ..
                "will be carrying a dangerous object with strong connections to the cataclysm.",
            rewardMoney = 41000,
        },
        [10783] = {
            description = "Here is my plan. We will poison the ogres and then destroy their gronn " ..
                "master.\n\nDuring my travels in these mountains, I met a man named Baron Sablemane. He " ..
                "is a master of the alchemical arts, and may be convinced to assist us.\n\nYou will find " ..
                "him at the Circle of Blood, down in the canyon to the north of here. Whatever price he " ..
                "requires, I will leave it to your discretion to accept.",
        },
        [10784] = {
            description = "<Tor'chunk leans in close to whisper.>\n\n<name>, you've done us more than " ..
                "proud in the fight against the ogres so far. And while I have every confidence in what " ..
                "Rexxar has planned, I would still ask that you crush the ogres at Bloodmaul Camp before " ..
                "returning.\n\nThat way we'll be doubly certain of the outcome.\n\nTo get there, head " ..
                "north down the ramp out of Thunderlord. Then, at the base of the ramp, head west across " ..
                "Dragons' End and north through the Churning Gulch and Daggermaw Canyon.",
            rewardChoices = {{31537, 1}, {31538, 1}, {31539, 1}, {31540, 1}},
            rewardMoney = 37000,
        },
        [10785] = {
            description = "There's is no cause of fury greater in this world than that of Gruul and his " ..
                "sons. They slaughtered my people - my children - and now I will have revenge.\n\nI have " ..
                "fashioned a trap from dragon fire, and if you're clever enough, you can use it to kill " ..
                "even a gronn.\n\nJust hurry, take the trap to Rexxar. My thirst for revenge must be " ..
                "quenched.",
        },
        [10786] = {
            description = "I know that Rexxar has plans for you to head to Boulder'mok. I have something " ..
                "that I want you to do while you are there.\n\nWe must take any chance we can get to " ..
                "strike down the ogres of these mountains, or they will overrun us, and all that we have " ..
                "bled and died for will be for nothing!\n\nBoulder'mok lies far to the northwest. Travel " ..
                "north to Ruuan Weald, and from there head west through the tunnel and past the Raven's " ..
                "Wood.\n\n<name>, I want you to kill the Bladespire ogres of Boulder'mok. Wipe them out!",
            rewardMoney = 78000,
        },
        [10791] = {
            description = "I've nearly completed the vestments that I'll wear during the ceremony. As I " ..
                "add the finishing touches, I'd like you to set this incense by the candles near the " ..
                "runestone to my left.\n\nI believe it will help us to attract the wolf spirit's " ..
                "attention, since it was made in the days of the orcish clans. I can almost imagine my " ..
                "ancestors using it in a ceremony paying tribute to the wolf spirit after a successful " ..
                "hunt.\n\nOnce you've placed the incense, I'll begin the ceremony.",
            rewardChoices = {{25974, 1}, {25975, 1}, {25976, 1}, {25977, 1}},
        },
        [10792] = {
            description = "The Bleeding Hollow clan have betrayed their noble heritage! We, the orcs who " ..
                "fought and died to save ourselves from the fel taint of Mannoroth, look upon our vile " ..
                "cousins and see only weakness and ignobility... and for that, they must burn!\n\nEnter " ..
                "Zeth'Gor, their bastion to the east, and burn their buildings. Kill peons for their " ..
                "torches, ignite them at their forge, and hurl the burning torches at their hovels, their " ..
                "stable and their barracks. Burn them all, and then return to me!\n\nFor the Horde!",
            rewardChoices = {{27731, 1}, {27732, 1}},
            rewardMoney = 20000,
        },
        [10793] = {
            description = "This journal documents the recent activities of Illidan's armies. It also " ..
                "explains why Val'zareq was parading around the Path of Conquest. He was personally " ..
                "responsible for the capture of a high general of the Sha'tar.\n\nThis general is being " ..
                "held at a post known as Crimson Watch, located at the southern end of the Path of " ..
                "Conquest. A mysterious faction, calling itself the Crimson Sigil, is charged with his " ..
                "incarceration. If you choose to investigate, it would be wise to bring allies.",
        },
        [10795] = {
            description = "Good, I've seen you around and I've been meaning to speak to you about a " ..
                "matter of some importance.\n\nThere are reports coming in that for some reason the " ..
                "Bloodmaul ogres are planning an offensive against Sylvanaar and Ruuan Weald. We don't " ..
                "know who or what is pushing them to do this, but I intend to nip their plan in the " ..
                "bud!\n\nBloodmaul Camp is where the attacks are to be staged from. Head northwest down " ..
                "the ramp out of the Ruuan Weald and you will find it. I want you to kill their leader, " ..
                "Dorgok!",
            rewardMoney = 37000,
        },
        [10796] = {
            description = "I've heard that you've done us more than proud in the fight against the ogres " ..
                "thus far. Now, I would ask that you face them again. I want you to crush the ogres at " ..
                "Bloodmaul Camp!\n\nTo get down there, head northwest down the ramp out of the Ruuan " ..
                "Weald. You'll find them at the base of the ramp.\n\nGood luck, <class>!",
            rewardChoices = {{31537, 1}, {31538, 1}, {31539, 1}, {31540, 1}},
            rewardMoney = 37000,
        },
        [10797] = {
            description = "A token in the form of a small statuette falls from Dorgok's dead clutch. It " ..
                "bears a striking resemblance to one of the gronn.\n\nSurely, Commander Haephus Stonewall " ..
                "at Evergrove in the Ruuan Weald, up the ramp to the east, would be interested in this!",
        },
        [10798] = {
            description = "This is bad news. Gorgrom the Dragon-Eater is behind the recent Bloodmaul " ..
                "plans against Sylvanaar!\n\nWhy he's manipulating them, and not just using the " ..
                "Bladespire, I don't know. But if we're to deal with a gronn, we're going to need " ..
                "help.\n\nI know a man who is wise in the ways of all sorts of exotic magics. Baron " ..
                "Sablemane is his name, and you can find him at the Circle of Blood, back down the ramp " ..
                "to the northwest, and then southwest through the canyon.\n\nAsk him to fashion us a trap " ..
                "for the gronn.",
        },
        [10799] = {
            description = "Very well, I'll create this trap, but first I want something in " ..
                "return.\n\nThere happens to be a nearby gronn that is in possession of an item that I " ..
                "want, but you can't face him, not yet anyway.\n\nSo, you and I are going to fashion a " ..
                "sleeping powder from the poison of the nearby crust bursters.\n\nYou'll find them in the " ..
                "Churning Gulch to the southwest. Bring me a number of their glands, and be quick about " ..
                "it!",
            rewardItems = {{31535, 5}},
            rewardMoney = 37000,
        },
        [10800] = {
            description = "I've outdone myself again. I've fashioned a sleeping powder for you to use on " ..
                "Grulloc, the gronn I spoke of who is guarding what I want.\n\nGrulloc keeps himself at " ..
                "the Cursed Hollow, an area at the eastern edge of Dragons' End on the other side of the " ..
                "Circle of Blood.\n\nIf I were you, I wouldn't tarry long once you have his sack. The " ..
                "effects of the dust won't last long.",
            rewardMoney = 37000,
        },
        [10801] = {
            description = "There's nothing more that I hate in this world than the sons of Gruul and " ..
                "their father! They slaughtered my people, and my children, and now I will have a taste " ..
                "of revenge!\n\nI have fashioned a trap from some dragon fire, and if you're clever " ..
                "enough, you might just be able to use it to kill a gronn.\n\nI'm sure that you have a " ..
                "particular gronn in mind; it matters not to me which one you kill. Just hurry, take the " ..
                "trap to your Commander Stonewall.\n\nMy thirst for revenge must be quenched!",
        },
        [10802] = {
            description = "We must show the ogres that we are not to be trifled with. We must send a " ..
                "message.\n\nTravel to Boulder'mok and kill the ogres there. Make sure you keep their " ..
                "heads.\n\nThen go to Gorgrom's altar and place the trap there for him. Gorgrom will " ..
                "appear, and you must lure him into the trap. When he is dead, mount your grisly totems " ..
                "near his corpse, so that the ogres may look at their fallen master and their fallen " ..
                "brothers, and know the price for seeking to destroy us.",
            rewardChoices = {{31541, 1}, {31542, 1}, {31543, 1}},
            rewardMoney = 78000,
        },
        [10803] = {
            description = "I know that we have plans for you to head to Boulder'mok. I have something " ..
                "that I want you to do while you are there.\n\nWe must take any chance we can get to " ..
                "strike down the ogres of these mountains, or they will overrun us, and all that we have " ..
                "bled and died for will be for nothing!\n\nBoulder'mok lies to the west. Travel " ..
                "southwest, cross the bridge and head through the tunnel. On the west side of the Raven's " ..
                "Wood you will find them.\n\n<name>, I want you to wipe out the Bladespire ogres of " ..
                "Boulder'mok.",
            rewardMoney = 39000,
        },
        [10804] = {
            description = "Something has them spooked, <race>.\n\n< Mordenai points to the nether drakes " ..
                "flying overhead.>\n\nThey won't even come down to feed. I have seen several fall to the " ..
                "earth, dead from exhaustion before their bodies hit the ground.\n\nWe must save them! " ..
                "The Rocknail flayers that are found near the crystals are their natural prey. Kill " ..
                "flayers and take their carcasses. Place a carcass in the field and stand extremely " ..
                "still. As long as you do not make any aggressive motions, they will not attack you.",
        },
        [10805] = {
            description = "You've proven yourself resourceful, and now I think I'm going to put you to " ..
                "personal use in my own fight against Gruul and his sons.\n\nThe Bladespire clan are the " ..
                "favored of the gronn, and while you may have thinned out their numbers elsewhere, you " ..
                "haven't yet dealt with their strongest.\n\nGruul protects the exterior of his lair with " ..
                "only the toughest of ogres, and it is those that you must kill. Head north through the " ..
                "Daggermaw Canyon and you will find Gruul's Lair at the end.",
            rewardMoney = 74000,
        },
        [10806] = {
            description = "The time has come for us to face Goc, the master of the Bladespire ogres. It " ..
                "is also time that I take a hand in events, to see the last of the gronn's life.\n\nTake " ..
                "my signet ring. When you come to the Altar of Goc, use it, and I will come to join " ..
                "you.\n\nTogether we will destroy Goc.",
            rewardChoices = {{31544, 1}, {31545, 1}, {31546, 1}, {31547, 1}, {31548, 1}, {31549, 1}},
            rewardMoney = 132000,
        },
        [10807] = {
            description = "The Ashtongue tribe is feared among all Broken. It consists of the most " ..
                "vicious and bloodthirsty individuals, handpicked by Akama himself. They are as fierce " ..
                "and ruthless as any naga, demon or blood elf in Illidan's army and they have been " ..
                "deployed in large numbers at the Ruins of Baa'ri, to the north. Go there and put a dent " ..
                "in their numbers before they get a chance to mount an attack on us.",
        },
        [10808] = {
            description = "The spirits of the dark conclave seek to summon an ancient and powerful evil " ..
                "through a ritual conducted at the lava pits to the south of the Sketh'lon Base " ..
                "Camp.\n\nGul'dan's magic mingled with their own, empowering them to aid this creature in " ..
                "manifesting in our world! We must not allow this to happen, <name>. The death and " ..
                "destruction it would bring are unimaginable!\n\nCarry the staff with you to the site of " ..
                "the summoning and use its magics to stop the dark conclave once and for all!",
            rewardChoices = {{30928, 1}, {30941, 1}, {30955, 1}, {30960, 1}},
            rewardMoney = 41000,
        },
        [10809] = {
            description = "The poster reads:\n\n\"Worg Master Kruush leads the worg riders of the " ..
                "Bleeding Hollow clan. A price has been placed on his head, for his riders exact heavy " ..
                "tolls on supply trains to Spinebreaker Post.\"\n\n\"Scouts report him within Zeth'Gor, " ..
                "and the hero able to bring the severed head of this villain to me will earn the thanks " ..
                "of the Horde, and a large bounty.\"\n\n\"- Captain Darkhowl \"",
            rewardMoney = 18000,
        },
        [10810] = {
            description = "As you examine the damaged mask, you hear strange sounds coming from within. " ..
                "If the mask wasn't damaged you might be able to hear the sounds more clearly.\n\nO'Mally " ..
                "Zapnabber in Ruuan Weald might be able to fix the mask.",
            rewardMoney = 10000,
        },
        [10811] = {
            description = "Their patron soars high above, <name>. Perhaps the kindness that you showed " ..
                "his children has moved his heart. Seek Neltharaku out and enlist his aid. Together, you " ..
                "may be able to solve the plight of the Netherwing drakes.\n\n< Mordenai points to the " ..
                "sky.>\n\nFly high, friend...",
        },
        [10812] = {
            description = "Ok, it should work now. What is it, you ask? Why, it's a communication device " ..
                "- it allows those blockheads to communicate with each other. You know, the Burning " ..
                "Legion! I would suggest that you hand this mask to Wildlord Antelarion. He's over there " ..
                "pacing around. Always moving, he is.\n\nWell get moving, he's been trying to get his " ..
                "hands on one of these for sometime now.",
            rewardMoney = 10000,
        },
        [10813] = {
            description = "<name>, you have braved the lair of the Bleeding Hollow orcs, dreaded " ..
                "Zeth'Gor, and survived! Perhaps you have the strength to aid me, for I aim to gaze into " ..
                "the mind of its darkest witch, Grillok!\n\nTake this shard. Use it to ensorcel an Eye of " ..
                "Grillok and bind it to yourself. Return here and approach my cauldron... and it will " ..
                "pull the eye from you.\n\nGo, <name>. And use care -- An Eye of Grillok will betray you " ..
                "to our enemies if given the slightest opening!",
            rewardMoney = 14000,
        },
        [10814] = {
            description = "I have information that you may find useful. Please listen to what I have to " ..
                "tell you, <race>.",
        },
        [10816] = {
            description = "You did well against the Broken in Baa'ri, <name>. Let's see how well you do " ..
                "against Illidan's most feared army.\n\nThe fel orcs of the Shadowmoon Clan occupy the " ..
                "Ata'mal Terrace, once a very holy site where ata'mal crystals were used in spiritual " ..
                "ceremonies.\n\nWe had reason to believe they were hiding an actual ata'mal crystal in " ..
                "the vicinity, but our scrying has revealed nothing. Nevertheless, the fel orcs are on " ..
                "draenei holy ground and their presence must be dealt with.",
            rewardChoices = {{30922, 1}, {30940, 1}, {30958, 1}, {30961, 1}},
            rewardMoney = 44000,
        },
        [10817] = {
            description = "You did well against the Ashtongue Broken, <name>. I have another challenge " ..
                "for you, should you be up to it.\n\nNot too long ago, the Sanctum of the Stars suffered " ..
                "a tremendous attack by Illidan's fel orcs.\n\nWe've determined it was perpetrated by the " ..
                "Shadowmoon orcs who occupy the Ata'mal Terrace.\n\nShow them that the Scryers are not to " ..
                "be trifled with.",
            rewardChoices = {{30922, 1}, {30940, 1}, {30958, 1}, {30961, 1}},
            rewardMoney = 44000,
        },
        [10818] = {
            description = "<name>, while you were out being one hell of a <class>, Baron Sablemane sent " ..
                "his pet dragon up here with a message.\n\nHe's asked for you personally. From what I " ..
                "understand, he wants you to head up his own fight against the gronn.\n\nI guess you're " ..
                "the most qualified person in all of Outland to help him, but if I were you, I'd get in " ..
                "contact with a couple of friends first and ask them to join you at the Circle of Blood.",
        },
        [10819] = {
            description = "I have a very special mission for you, <name>. I need you to infiltrate Forge " ..
                "Camp: Anger east of here. When you enter the camp you will need to wear the Felsworn gas " ..
                "mask and locate the Legion communicator. Once you have located the communication device " ..
                "speak with whomever is on the other side of the device.\n\nIf all works out you can " ..
                "trick the demon into something devious! Try telling the demon that Camp Anger has " ..
                "revolted.\n\nGood luck to you <class>.",
        },
        [10820] = {
            description = "For every moment I hear silence, you draw closer to your death! " ..
                "SPEAK!\n\nWhat? The camp has revolted? This cannot possibly be true! My minions would " ..
                "not dare undermine my authority.\n\nWell then, every last one of them will pay for this " ..
                "treachery, they will pay dearly. Silence them all and be done with it! Report back to me " ..
                "once you have carried out my order or you shall be dealt with.",
        },
        [10821] = {
            description = "Doomcryer did nothing to stop the revolt? How dare she! She has been trying to " ..
                "undermine my authority for some time. However, this time will be her last. You must " ..
                "summon her and deal with her personally.\n\nHer anger guards hold the keys that summon " ..
                "her to Forge Camp: Anger. Retrieve the five keys and activate the five Legion obelisks. " ..
                "The obelisks have a short duration, so make sure they are all activated at the same " ..
                "time. Remember, the anger guards carry more keys.",
            rewardChoices = {{31792, 1}, {31793, 1}, {31790, 1}, {31791, 1}},
            rewardMoney = 78000,
        },
        [10824] = {
            description = "The survival of the Scryers hinges on outrecruiting Kael'thas. Every pilgrim " ..
                "from Quel'Thalas that joins his side brings him closer to victory. The opposite is true " ..
                "for us.\n\nSoon, however, we will run out of recruits and it will come down to what side " ..
                "can kill the other quicker. Prove your worth to the Scryers by bringing me Sunfury " ..
                "signets worn by high-ranking blood elves allied with Kael'thas and Illidan. You'll find " ..
                "them at Eclipse Point to the west and the Ruins of Karabor, to the northeast.",
        },
        [10825] = {
            description = "This strange, magical orb drops from beneath the contour feathers of the " ..
                "arakkoa.\n\nSuffused with an eerie, purple glow, the orb pulses to an unheard beat. " ..
                "Holding it makes you mildly uncomfortable, and so you quickly place it within your " ..
                "pack.\n\nPerhaps Tree Warden Chawn at Ruuan Weald to the west, through the tunnel and " ..
                "across the Wyrmskull Bridge, would be interested in examining it?",
        },
        [10826] = {
            description = "By now it should be clear to you why we oppose the Burning Legion and those " ..
                "who serve them.\n\nIf you wish to prove yourself to the Aldor, bring me the insignias of " ..
                "high-ranking Legion and their Shadow Council followers. Here in Shadowmoon you will find " ..
                "a strong Legion presence to the far west in Legion Hold and the Deathforge.",
        },
        [10829] = {
            description = "This is troubling! The arakkoa are causing the ancients and protectors to " ..
                "become possessed by evil spirits!\n\nBut, there is one ancient that could not possibly " ..
                "have been affected. His name is Treebole, and you must go to him at once if we're to " ..
                "save the trees of the Raven's Wood!\n\nGo back to the Raven's Wood. You will find him at " ..
                "the fork in the path just past Grishnath.",
        },
        [10830] = {
            description = "The Grishna have caused the leafbeards and stonebarks to be inhabited by evil " ..
                "koi-koi spirits.\n\nWe must save the trees or soon all of the Raven's Wood will be lost " ..
                "forever!\n\nCombine the magic of a Grishnath orb, found throughout Grishnath, with a " ..
                "dire pinfeather from a dire raven.\n\nUse the resultant exorcism feather to draw out and " ..
                "slay the koi-koi spirit as quickly as possible. The stonebarks are too powerful for this " ..
                "ritual, but if enough leafbeards are saved, they will be freed as well.",
            rewardChoices = {{31526, 1}, {31527, 1}, {31523, 1}, {31528, 1}},
            rewardMoney = 78000,
        },
        [10834] = {
            description = "Grillok Darkeye has wagered a piece of himself to dark powers, and gained " ..
                "great magic for it. His lost eye burns deep in some hellish pit, now a demon's " ..
                "trinket... and the patch that covers his betrayal holds its own dark secrets.\n\nBring " ..
                "me Grillok's eyepatch, <name>, and I will reward you greatly for your service...",
            rewardChoices = {{28050, 1}, {28051, 1}, {28052, 1}, {28055, 1}, {28057, 1}},
            rewardMoney = 54000,
        },
        [10835] = {
            description = "<name>, I have prepared a preliminary report of my findings regarding the " ..
                "Bleeding Hollow orcs. My colleague in Thrallmar, Apothecary Antonivich, will be happy to " ..
                "receive them. He too studies the phenomenon of fel orcs... in hopes of preventing such a " ..
                "tragedy from again befalling our orcish allies.\n\nTake him this report, and I will " ..
                "continue my study of the blood you brought me. If fortune is with us, we will isolate " ..
                "the cause of the fel orc affliction.",
            rewardMoney = 5200,
        },
        [10836] = {
            description = "I require time so that I may devise a plan to save my children and mate. You " ..
                "will buy me this time, mortal.\n\nVenture into Dragonmaw Fortress, located on the " ..
                "eastern edge of the Netherwing Fields, and lay waste to all Dragonmaw orcs that you " ..
                "find. The ensuing chaos and confusion should have a considerable impact on their " ..
                "plans.\n\nBe warned, some of my kin are too far gone - their minds corrupted by the " ..
                "Dragonmaw. For them, the only resolution is death. You have my permission to end their " ..
                "lives as well.",
        },
        [10837] = {
            description = "I believe that I can imbue nethervine crystals with my own essence. The power " ..
                "contained within these imbued crystals should be sufficient to free enslaved drakes of " ..
                "their masters' grasps.\n\nTravel to Netherwing Ledge, an island located off the broken " ..
                "shelf of Shadowmoon Valley, to the southeast. It is on Netherwing Ledge that you will " ..
                "find nethervine crystals. Return to me when you have collected enough crystals to fill " ..
                "your packs.\n\nAnd <name>, Beware the Dragonmaw that now inhabit the island.",
        },
        [10838] = {
            description = "The Demoniac Scryer is now ready. Take it behind Hellfire Citadel, to Hellfire " ..
                "Basin, and summon it upon the ground. It will then begin to attune itself to Hellfire " ..
                "Citadel. After its attunement, speak to the Scryer and transcribe what it tells you. " ..
                "Bring that transcription to me...\n\nGo, <name>, but only when you are ready. There is " ..
                "no doubt that Hellfire Citadel will detect the Scryer and send wardens to destroy it!",
            rewardItems = {{31715, 1}},
            rewardMoney = 40000,
        },
        [10839] = {
            description = "Veil Skith lies to the northwest of the caravan and to the south of Shattrath " ..
                "in a secluded grove of the forest. It is rumored that the colony of Skettis has " ..
                "constructed a maligned altar of worship. This Darkstone of Terokk must be purified if " ..
                "the arakkoa of Skith are ever to be redeemed.\n\nTake this Rod of Purification and cast " ..
                "it upon the Darkstone. Blessed by A'dal, the rod's purity might be enough to bring " ..
                "clarity to the Darkstone. Go now and may the light shine upon thee.",
            rewardMoney = 31000,
        },
        [10840] = {
            description = "To the east, buried under the charred sand, is the Tomb of Lights, a lost " ..
                "resting place of the dead. Before our caravan was ambushed I was going to journey to the " ..
                "tomb and cleanse it of evil spirits.\n\nLittle did I know it was already infested with " ..
                "another kind of evil. Even now the ethereals plunder the bodies of the fallen for " ..
                "trinkets and keepsakes that were given to the dead centuries ago.\n\nThere is little I " ..
                "can do while our caravan struggles to survive.",
            rewardMoney = 33000,
        },
        [10842] = {
            description = "The Tomb of Lights has become corrupted by the Shadow Council and the draenei " ..
                "dead have become cursed spirits, angry and confused with a burning hatred for the " ..
                "living.\n\nEnter the tomb and seek out these tragic victims. Give them the rest that " ..
                "they deserve.",
            rewardChoices = {{31617, 1}, {31615, 1}},
        },
        [10843] = {
            description = "Since time forgotten we have fought with the Bladespire ogres.\n\nWe have " ..
                "managed to push them back so that now they only hold a tenuous grip at Bladespire " ..
                "Outpost. It's back the way that you came, on the southwestern edge of the Razor " ..
                "Ridge.\n\nProve your worth to me by killing their leader, Gnosh Brognat.\n\nLet us see " ..
                "what stuff you are made of when fighting the ogres.",
            rewardMoney = 39000,
        },
        [10845] = {
            description = "My hunters have just returned from a scouting mission to the Singing Ridge. It " ..
                "seems that the nether drakes, which infest the crystals there, have increased greatly in " ..
                "number, and threaten to spill out into our laps.\n\nSince you have proven yourself a " ..
                "competent slayer, let us see if your <class> skills are the match of an adult " ..
                "drake.\n\nFind the Singing Ridge by heading south through the Scalewing Shelf. Enter and " ..
                "slay their brood mother, Dreadwing.",
            rewardChoices = {{31683, 1}, {31684, 1}, {31685, 1}, {31686, 1}},
            rewardMoney = 39000,
        },
        [10846] = {
            description = "< Leoroxx looks you in the eye with the kind of stare that chills your " ..
                "soul.>\n\nYou come to the Mok'Nathal, but you do not understand us. You do not " ..
                "understand our struggle to survive.\n\nIf you would understand us, then you will have to " ..
                "endure a taste of that struggle.\n\nTo the south are the Vekh 'nir arakkoa. They have " ..
                "enslaved a group of ogres in the caverns known as Trogma's Claim and their leader, Vekh " ..
                "is in there.\n\nSlay him!",
            rewardMoney = 37000,
        },
        [10847] = {
            description = "Doom harkens from the cliffs of Skettis.\n\nMy people, the arakkoa, face a " ..
                "fate shrouded in unspeakable evil. Too often have we abused dark magic for wrongdoing. " ..
                "Through A'dal I have learned of the Light and of redemption.\n\nTerokk watches his " ..
                "colonies from Skettis through orbs enchanted by the black art. Steal these Eyes from " ..
                "Veil Reskk and Veil Shienor in northern Terokkar. Let me see what Terokk sees. Let me " ..
                "look through the eyes of Skettis.",
            rewardChoices = {{22829, 1}, {22832, 1}},
            rewardMoney = 27000,
        },
        [10848] = {
            description = "Veil Rhaze was a particularly wicked colony of Skettis.\n\nDespite the " ..
                "village's eradication by the Auchindoun disaster, Terokk's influence remained in the " ..
                "maligned spirits there. Travel west to Veil Rhaze and slay those murderous wretches. " ..
                "You'll find them to the west of the Shadow Tomb, on the border of Bone Wastes and " ..
                "Terokkar Forest.\n\nThis will be our first blow against Terokk and the guardians of " ..
                "Skettis.",
            rewardChoices = {{31761, 1}, {31762, 1}},
            rewardMoney = 31000,
        },
        [10849] = {
            description = "Other arakkoa took part in the betrayal of Terokk.\n\nKirrik recognized Terokk " ..
                "as a charlatan, not a prophet. The only prophecy Terokk envisioned was the doom borne of " ..
                "his own bidding.\n\nIt was Kirrik who led us bravely from Skettis. After our pilgrimage " ..
                "to Shattrath, Kirrik traveled to the colonies in search of others.\n\nThis missive tells " ..
                "of what the Eyes have seen. Kirrik must be told! Follow the road south out of Shattrath " ..
                "to the Bone Wastes and look for the caravan.",
            rewardMoney = 7400,
        },
        [10851] = {
            description = "There is the right way to honor one's ancestors, and there is the wrong " ..
                "way.\n\nThe Bladespire ogres carry totems with them, but they do not use them to show " ..
                "their respect. Instead, they seek to use them to manipulate and control.\n\nWe should " ..
                "steal their totems because they are unworthy! We will then put them to better use.\n\nGo " ..
                "to the Bladespire Outpost to the west, just southwest of the Razor Ridge. Slay the " ..
                "Bladespire mystics and crushers, and take their totems from them!",
            rewardMoney = 37000,
        },
        [10852] = {
            description = "We broke down here because some guys came in the night and made a lot of " ..
                "noise. It was scary. I don't know when we are going to get moving again.\n\nSome of my " ..
                "friends are missing though. I don't know where they are. I think those scary bird men " ..
                "took them away to the northwest. They probably are all locked up in cages and stuff. If " ..
                "you find them that would be great. I'm kind of worried about them.",
            rewardItems = {{31666, 1}},
        },
        [10853] = {
            description = "The spirits of the nether drakes in the Singing Ridge are in need of " ..
                "liberation.\n\nThe nether drakes were not always nether drakes. They used to be black " ..
                "drakes.\n\nBut then, with the destruction of this world, a wave of nether energy washed " ..
                "over everything and had the side-effect of changing the drakeling eggs.\n\nNow they are " ..
                "all twisted versions of their former selves. We must help them to find peace.\n\nDo this " ..
                "by slaying a drake near to the spirit calling totem, and then take its spirit from it.",
            rewardChoices = {{31711, 1}, {31712, 1}, {31713, 1}, {31714, 1}},
            rewardItems = {{31437, 5}},
            rewardMoney = 37000,
        },
        [10854] = {
            description = "Take this enchanted nethervine crystal and make your way back to Dragonmaw " ..
                "Fortress. Once there, seek out the enslaved drakes and invoke the magic of the " ..
                "nethervine crystal. My own energies will pour forth, causing the drakes to break free " ..
                "from the bond of their captors. When you see that the drake has broken free, help it " ..
                "defeat its captor! It will most assuredly be weak from the imprisonment.\n\nRelease all " ..
                "that you can find and return to me, <name>.",
        },
        [10855] = {
            description = "Ah, yes - the fel reaver! Certainly the Legion's most terrible mechanical " ..
                "creation. There are no less than three of these abominations aimed at the " ..
                "Stormspire.\n\nFortunately for us, they are not active yet. This affords us the " ..
                "possibility of dealing with them through sabotage instead of brute force.\n\nObtain " ..
                "condensed nether gas from the gan'arg at Forge Base: Oblivion and fill a nearby fel " ..
                "reaver's fuel tank with it. I've a feeling its engine won't handle it too well.",
            rewardMoney = 41000,
        },
        [10856] = {
            description = "Brave acts of industrial sabotage will only get us so far, <name>. Just as " ..
                "Forge Base: Oblivion serves as an assembly site for Fel Reavers, Forge Base: Gehenna " ..
                "serves as a staging ground for their army as it is where the majority of the Legion's " ..
                "teleportation devices are located.\n\nI want you to go in there and put a dent in their " ..
                "numbers. They must have a full regiment of wrathbringers by now and we just can't allow " ..
                "that.",
        },
        [10857] = {
            description = "As fun as killing demons might be, it does us little good when the Legion can " ..
                "keep using its teleporters to replace anything we kill.\n\nUnfortunately, I don't have " ..
                "any high-powered explosives handy... but the mo'arg that maintain the teleporters " ..
                "do.\n\nTake this rod... I've tuned its powers to interfere with mo'arg brain " ..
                "frequencies. Return to Forge Base: Gehenna and use it on any mo'arg you see. You won't " ..
                "have long, but you'll be able to use their demolition charges on the nearby teleporters.",
            rewardChoices = {{31700, 1}, {31701, 1}, {31703, 1}, {31699, 1}},
        },
        [10858] = {
            description = "It shames me to ask for your assistance once more, <name>, but you are my " ..
                "flight's only hope. Without my mate, the netherwing brood may die out " ..
                "completely.\n\nMake your way to the top of Dragonmaw Fortress and find Karynaku.\n\nWe " ..
                "will be flying overhead. Should a break appear in their defenses, the might of the " ..
                "netherwing will swoop down to assist you.",
        },
        [10859] = {
            description = "The Razaani ethereals have strange devices that emit small, pink floating " ..
                "light orbs. They remind me of souls.\n\nThey are not to be confused with the large " ..
                "yellow balls that break free of the ethereal when they die, these are something else " ..
                "entirely.\n\nI'd like for you to head north to Razaan's Landing and drop some totems, " ..
                "which will attract the pink light orbs.\n\nBring them back to me so that I might " ..
                "determine exactly what they are.",
            rewardMoney = 37000,
        },
        [10860] = {
            description = "Hungry, <race>? The Great Spirit helps those that help themselves. If you want " ..
                "to earn a meal, I suggest that you listen up, because Braagor there isn't going to give " ..
                "you anything for free, nor as tasty!\n\nThe raptors and scalewings of Razor Ridge and " ..
                "the Scalewing Shelf have everything that's needed for two of the most delicious dishes " ..
                "you'll ever taste. Bring me their raptor ribs and serpent flesh, and I'll make some of " ..
                "each for you.\n\nI may even teach you how to cook them up for yourself, if you hurry.",
            rewardItems = {{31672, 3}, {31673, 3}, {31675, 1}, {31674, 1}},
            rewardMoney = 37000,
        },
        [10861] = {
            description = "In the wretched colony to the southwest known as Veil Lithic, Terokk's minions " ..
                "are attempting to befoul their avian brethren before they hatch. The dark sorcerers of " ..
                "Lithic encase eggs in a shadowy curse. When the hatchlings emerge, they mindlessly serve " ..
                "Terrok.\n\nTravel to Veil Lithic and prematurely break the eggs before the curse has " ..
                "time to seep in. Even if you are too late, you can put down the tainted " ..
                "ones.\n\nRemember, the Light shines brightest in the darkness.",
            rewardChoices = {{25958, 1}, {25959, 1}, {25960, 1}, {25961, 1}},
            rewardMoney = 31000,
        },
        [10862] = {
            description = "The cowardly arakkoa attack us daily. They ambush our hunters and sometimes " ..
                "even raid inside our walls. We kill them when we can, but their magic is strong and they " ..
                "often escape our warbands.\n\nI have learned that some arakkoa claim to be friendly with " ..
                "the Horde. They live in Shattrath City to the northwest. Rilak the Redeemed is their " ..
                "leader. Search for him in the Lower City, and when you find him, demand his surrender.",
            rewardMoney = 23000,
        },
        [10863] = {
            description = "Out here on the frontier we have to deal with the arakkoa every day. They " ..
                "strike at us when they please, raiding our supply lines and killing our scouts.\n\nYet " ..
                "we know very little about these enigmatic creatures. I have received news that northwest " ..
                "of here in Shattrath City there are arakkoa who are not hostile. They might be willing " ..
                "to share the secrets of their race.\n\nRilak the Redeemed is their leader. He resides in " ..
                "the northern part of the Lower City.",
            rewardMoney = 23000,
        },
        [10864] = {
            description = "I have a device, the Demoniac Scryer, that can analyze fel magic. I would have " ..
                "you use the Scryer, but first... you must appease it. The Scryer, you see, has trapped " ..
                "within it a creature of vast intelligence and its needs are, shall we say, quite " ..
                "eccentric.\n\nTo appease the Scryer, you must kill orcs. Specifically, they must be " ..
                "Shattered Hand orcs -- the Scryer demands their souls.\n\nReturn to me when the souls " ..
                "are reaped. You will find the orcs north, and south, and surrounding... Hellfire Citadel.",
            rewardMoney = 20000,
        },
        [10865] = {
            description = "Quickly, you must inform Leoroxx of what is transpiring up at Razaan's " ..
                "Landing!\n\nThose orbs were comprised of souls, some of them Mok'Nathal!",
        },
        [10866] = {
            description = "He hides in my thoughts, mortal. He waits for me to break... for me to bend to " ..
                "his will.\n\nAnd this will be his undoing. I will call for him. I will tell him that I " ..
                "will do as he asks. When he appears, kill him and take the key!\n\nKnow this: Zuluhed is " ..
                "an ancient orc with unknown powers. He has surely been empowered further by Illidan. You " ..
                "risk your life for me in doing as I ask. Are you certain you wish to make such a " ..
                "sacrifice?",
        },
        [10867] = {
            description = "There can be only one response to this... this, DEFILEMENT of the souls of our " ..
                "ancestors!\n\n<name>, if you would aid us to restore the souls of our honored dead to " ..
                "their rightful place, go back to Razaan's Landing.\n\nGo back up there and kill the " ..
                "razaani until their leader, Nexus-Prince Razaan shows his cowardly face. Kill him and " ..
                "get those souls back, and then give them over to Spiritcaller Dohgar!",
            rewardChoices = {{31687, 1}, {31688, 1}, {31689, 1}, {31690, 1}},
            rewardMoney = 78000,
        },
        [10868] = {
            description = "The arakkoa have attacked us again, this time striking in the night and then " ..
                "using their dark magic to escape before we could charge out to meet them in numbers. " ..
                "They use their summoning circles to rescue their warriors from certain death but they " ..
                "cannot run from us if we attack their homes. Veil Reskk and Veil Shienor lie to the " ..
                "north and northeast.\n\nFind these arakkoa nests and kill as many as you can.",
            rewardMoney = 27000,
        },
        [10869] = {
            description = "The arakkoa have attacked us again, this time striking in the night and then " ..
                "using their dark magic to escape before we could marshal our soldiers.\n\nVeil Reskk and " ..
                "Veil Shienor lie to the north and northwest. Find these arakkoa nests and kill as many " ..
                "as you can. They may not fear us, but at least we can thin their numbers.",
            rewardMoney = 27000,
        },
        [10870] = {
            description = "Allow me to return you to Mordenai. I am certain that he wishes to see you " ..
                "once more.",
            rewardChoices = {{31490, 1}, {31491, 1}, {31492, 1}, {31493, 1}, {31494, 1}},
            rewardMoney = 132000,
        },
        [10871] = {
            description = "Allow me to return you to Mordenai. I am certain that he wishes to see you " ..
                "once more.",
            rewardChoices = {{31490, 1}, {31491, 1}, {31492, 1}, {31493, 1}, {31494, 1}},
            rewardMoney = 132000,
        },
        [10872] = {
            description = "He hides in my thoughts, mortal. He waits for me to break... for me to bend to " ..
                "his will.\n\nAnd this will be his undoing. I will call for him. I will tell him that I " ..
                "will do as he asks. When he appears, kill him and take the key!\n\nKnow this: Zuluhed is " ..
                "an ancient orc with unknown powers. He has surely been empowered further by Illidan. You " ..
                "risk your life for me in doing as I ask. Are you certain you wish to make such a " ..
                "sacrifice?",
        },
        [10873] = {
            description = "Our small outpost is under constant attack. Several nights ago, we were raided " ..
                "by the spiders of Netherweb Ridge, on the southeastern edge of the Bone Wastes. They " ..
                "poisoned many of our people, wrapped them in webs and carried them away. Some of our " ..
                "warriors took up arms and with little preparation pursued the spiders.\n\nWe have not " ..
                "seen the captives or our hunting parties since. We hope that some may still be alive, " ..
                "perhaps imprisoned by the spiders. Our numbers are few. Will you search for our people?",
            rewardMoney = 33000,
        },
        [10874] = {
            description = "Terokk's perch, Skettis, looms above the Bone Wastes to the east. At the base " ..
                "of Skettis lies Veil Shalas, the most formidable of Terokk's colonies. It is through the " ..
                "stronghold of Veil Shalas that Terokk's forward sages wage war against the Light.\n\nThe " ..
                "evil-doers of Shalas communicate with their master using a complex system of magical " ..
                "signal fires. Travel to the east, <race>, and extinguish the fires. Once Veil Shalas is " ..
                "silenced, we can begin to plot the fall of Skettis.\n\nBut I get ahead of myself.",
            rewardChoices = {{25965, 1}, {25966, 1}, {25963, 1}},
            rewardMoney = 33000,
        },
        [10875] = {
            description = "<name>, during your foray with the Demoniac Scryer, I sent word of your " ..
                "exploits against the fel orcs. Nazgrel, our illustrious leader in Thrallmar, wishes to " ..
                "speak with you. I believe he has a bloody mission in mind...",
        },
        [10876] = {
            description = "Force-Commander Gorax is training Shattered Hand captains at the base of " ..
                "Hellfire Citadel, honing them to a bloody razor's edge. You must kill him, <name>, for " ..
                "his loss would be a mighty blow to the fel orcs.\n\nHowever, that is not all you must " ..
                "do.\n\nTake this banner. Place it atop Gorax's corpse. Gorax's commander, the Hand of " ..
                "Kargath, must answer your challenge if he has even a drop of true orc blood within " ..
                "him!\n\nHis head, the head of the hand of Kargath, is what I seek.",
            rewardChoices = {{31717, 1}, {31718, 1}, {31719, 1}, {31720, 1}},
            rewardMoney = 58000,
        },
        [10877] = {
            description = "Long ago a caravan went to Auchindoun with a mission to take a Dread Relic " ..
                "from the ancient tombs beneath the necropolis. They fled, but the relic was their " ..
                "undoing. The relic is evil and it summons evil when touched. Their caravan was destroyed " ..
                "somewhere to the east.\n\nThis dark artifact is the key to a terrible plan to defeat " ..
                "Teribus the Cursed, a creature that flies over the Bone Wastes. Help me if you wish, but " ..
                "your life and even your soul will be at risk.",
            rewardMoney = 35000,
        },
        [10878] = {
            description = "After our caravan fell prey to an attack by Shadow Council cabal cultists, " ..
                "scouts were sent to Shattrath to call for help. The guards think we're safe for now, but " ..
                "they underestimate these madmen.\n\nI, for one, am not looking forward to having my " ..
                "throat slit by some cabal initiate in the middle of the night. Do us all a favor and " ..
                "take the fight to them, before they come to us.\n\nYou will find our attackers south of " ..
                "here, at Auchindoun's northern entrance.",
        },
        [10879] = {
            description = "Skettis has waged war on us! Have you gathered enough strength to help with " ..
                "Shattrath's defense?\n\nHold off the attackers!",
            rewardChoices = {{31727, 1}, {31726, 1}},
            rewardMoney = 99000,
        },
        [10880] = {
            description = "This message bears a dark seal and though the language seems somewhat " ..
                "familiar, it appears to be encoded.\n\nPerhaps someone at the Refugee Caravan will know " ..
                "something about it.",
        },
        [10881] = {
            description = "Many believe it was the Shadow Council that caused the explosion that tore " ..
                "Auchindoun apart. It is rumored they awoke a great evil inside.\n\nIf that is true, then " ..
                "that evil must have turned against them. According to these orders, part of the Shadow " ..
                "Council is fleeing Auchindoun. They are using the Shadow Tomb to store powerful " ..
                "artifacts from Auchindoun.\n\nThree of these are sacred, for they belonged to the " ..
                "powerful patriarchs Arunen, K'alen and Atalor. I must ask you to retrieve them.",
            rewardChoices = {{31728, 1}, {31729, 1}},
        },
        [10883] = {
            description = "You have proven yourself capable of great feats, <name>. Your discovery of the " ..
                "Cipher of Damnation and Kael'Thas' involvement is most important to our cause. Should " ..
                "Kael use the cipher, what little is left of this world may collapse.\n\nA'dal is " ..
                "convinced that Kael must be stopped and now seeks adventurers willing to undergo trials. " ..
                "Those that prove their strength will be granted favor by the naaru.\n\n< Khadgar " ..
                "nods.>\n\nA'dal awaits...",
        },
        [10884] = {
            description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nWithin " ..
                "the Shattered Halls of Hellfire Citadel are three of your people. They are held there by " ..
                "the merciless one, Kargath Bladefist. He seeks to execute them as a sign of his virility " ..
                "and power. You must save these prisoners before such an atrocity can come to pass. As " ..
                "proof of deed, bring me the unused axe of the executioner. It must not have a drop of " ..
                "blood on its blade!",
        },
        [10885] = {
            description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nThe " ..
                "trial of strength is divided in two. You must destroy the leader of the Coilfang " ..
                "Steamvaults, Warlord Kalithresh, and bring me his trident. Slay the extra-planar being " ..
                "known as Murmur, in the Shadow Labyrinth of Auchindoun, and bring me his essence.\n\nDo " ..
                "this and you will have passed the trial of strength.",
        },
        [10886] = {
            description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nIn our " ..
                "travels we have encountered many dangerous beings. Some of these beings we incarcerated " ..
                "and placed in what is now known as the Arcatraz of Tempest Keep.\n\nThere is one " ..
                "prisoner, however, that is a victim of circumstance. A stowaway who was in the wrong " ..
                "naaru vessel at the wrong time.\n\nVenture to the Arcatraz and rescue the gnome, " ..
                "Millhouse Manastorm. Ensure his survival.",
        },
        [10887] = {
            description = "I appreciate your help, <name>. I was certain I was going to be " ..
                "killed.\n\nLet's get out of here with a hurry. It won't be long before more cultists " ..
                "come after us.",
            rewardChoices = {{31733, 1}, {31734, 1}, {31731, 1}, {31732, 1}},
        },
        [10889] = {
            description = "Your actions, while brave, will surely rouse a vindictive response from " ..
                "Terokk.\n\nHurry to Shattrath. Send word to Rilak!",
            rewardMoney = 26000,
        },
        [10893] = {
            description = "With the Blackwing wyrmcultists massing in the tunnel, we're hard pressed to " ..
                "deal with the situation. Quite frankly, they have the numbers.\n\nAnd while we've been " ..
                "able to take care of any of their people that get too close, the fact remains that if " ..
                "they attack in earnest, we're going to be overrun.\n\nThe situation calls for someone to " ..
                "get through to the other end of the tunnel, and take out their leader, Draaca Longtail. " ..
                "Up for some fun?",
            rewardMoney = 37000,
        },
        [10894] = {
            description = "Hmm, I'm not certain what we should do. I'm not much of a military " ..
                "planner.\n\nWatcher Moonshade will know what to do. He's heading up our defensive " ..
                "efforts at the Wyrmskull Tunnel to the west at the end of Wyrmskull Bridge. We have a " ..
                "force out there just in case the cultists try anything funny.\n\nPlease, take the note " ..
                "to him with all due haste.",
        },
        [10895] = {
            description = "It's time to strike Zeth'Gor from the air! Our gryphon riders are ready for a " ..
                "sortie, <name>. But they need someone on the ground to direct their fire. Are you ready " ..
                "for a covert mission?\n\nTake these smoke beacons into Zeth'Gor, the Bleeding Hollow " ..
                "stronghold to the west. They have four guard towers: one near their northern wall, one " ..
                "near their southern wall, one near their forge and another nestled in their foothills. " ..
                "Place a beacon underneath each of the towers and we'll fly in and bomb them!",
            rewardChoices = {{28050, 1}, {28051, 1}, {28052, 1}, {28055, 1}, {28057, 1}},
            rewardMoney = 18000,
        },
        [10896] = {
            description = "The trees of this land are ravaged by the power that was unleashed from " ..
                "Auchindoun. The foul magic that was unleashed blasted the land into the wastes you see " ..
                "all around. The trees that survived are now infested with wretched wood mites that crawl " ..
                "under their bark and gnaw at their flesh.\n\nRotting forest-ragers and infested " ..
                "root-walkers are breeding grounds for the mites. They are found along the edge of the " ..
                "wood to the east. Destroy these creatures and then kill the mites that flee their husks.",
            rewardMoney = 33000,
        },
        [10898] = {
            description = "Skywing flutters around you.\n\nYou get the feeling he wants you to follow him.",
            rewardChoices = {{31764, 1}, {31765, 1}, {31766, 1}},
            rewardItems = {{31760, 1}},
            rewardMoney = 66000,
        },
        [10903] = {
            description = "<name>, while you were on your mission in Zeth'Gor, I received news of my " ..
                "commanding officer, Colonel Jules. He was stricken with a demonic corruption while " ..
                "fighting near the Gor'gaz Outpost, and his situation has grown very bad.\n\nYou have " ..
                "made such great gains for us against the fel orcs. Your strength in battle is without " ..
                "question... is your spirit just as strong?\n\nPlease, return to Honor Hold and speak " ..
                "with Klatu, in an upper room at the Honor Hold inn.",
        },
        [10904] = {
            description = "We must shut down the Burning Legion's access to Death's Door, but first " ..
                "you're going to destroy their two warp-gates!\n\nThe problem is, we can't even scratch " ..
                "one of those things, so you're going to need to use their own weapons against " ..
                "them.\n\nThe death's might, death's watch, deathforge over-smiths and deathforge " ..
                "technicians carry the ammunition for the fel cannons.\n\nNormally it wouldn't affect any " ..
                "of them, but if you bring the cannonballs to me, I will imbue them with Nature's " ..
                "unbridled wrath!",
            rewardMoney = 39000,
        },
        [10908] = {
            description = "You look surprised to be talking to me. I do not blame you. My people, the " ..
                "arakkoa, deserve to be feared.\n\nSpeak with Rilak the Redeemed in Shattrath City if you " ..
                "wish to know more. He can be found in the northern part of the Lower City, with the " ..
                "other outcasts of Skettis.\n\nAnd, <name>, we will speak again.",
            rewardMoney = 3000,
        },
        [10909] = {
            description = "Colonel Jules was cursed in a battle near the Gor'gaz Outpost, a haunt for " ..
                "Shattered Hand fel orcs. My master, Barada, works feverishly to cure the poor human, but " ..
                "he needs help. The Colonel's tormented spirit seeks peace, and his path to peace is, I " ..
                "fear, a path of vengeance.\n\nTake this anchorite relic to Gor'gaz Outpost. Place it " ..
                "upon the ground near Shattered Hand orcs and defeat them. This will release their fel " ..
                "spirits -- you must slay those fel spirits for Jules' own spirit's recovery.",
            rewardMoney = 20000,
        },
        [10910] = {
            description = "Now there is an even greater threat from the Burning Legion. To the south is a " ..
                "portal known as Death's Door, which opens upon the horrific world where the Legion " ..
                "breeds its deadly hounds.\n\nTo get there, exit Evergrove by heading east up the ramp. " ..
                "Follow the path south, through the Bladed Gulch, Razaan's Landing, Razor Ridge and the " ..
                "Scalewing Shelf. Then, take the ramp down into the Vekhaar Stand and enter Death's Door " ..
                "through the tunnel, south of Mok'Nathal.\n\nOnce there, use this druid signal.",
            rewardMoney = 39000,
        },
        [10911] = {
            description = "Now that the ammunition can affect the Burning Legion, it's time for you to " ..
                "use it.\n\nThere are two warp-gates, which are used for teleportation and enhancement of " ..
                "the void terrors. One is in the south and the other in the north, and each is within " ..
                "range of a fel cannon.\n\nUse the naturalized ammunition to take control of each fel " ..
                "cannon and destroy the warp-gates.\n\nAttack the gate with artillery to begin, and be " ..
                "prepared to kill its defenders to keep the cannon alive if necessary.",
            rewardMoney = 39000,
        },
        [10912] = {
            description = "Baelmon the Hound-Master must die! He maintains the ritual that keeps the " ..
                "portal functioning.\n\nThe Death's Door portal is located at the north end of the " ..
                "canyon. When you find it, you will find Baelmon.\n\nYou're going to need help on this " ..
                "one, so take this wand. When you battle the Hound-Master, use it and a couple of my " ..
                "friends will come to your aid.\n\nAfter you have defeated Baelmon, return to Wildlord " ..
                "Antelarion.\n\nAnd, <name>, thank you for all that you've gone through for us here.",
            rewardChoices = {{31693, 1}, {31696, 1}, {31695, 1}, {31692, 1}, {31691, 1}, {31694, 1}},
            rewardMoney = 117000,
        },
        [10913] = {
            description = "Is there nothing that can be done to stem the tide of corruption? My soldiers " ..
                "have been battling the Auchenai for days now with no end in sight. Each casualty, " ..
                "whether Auchenai or Sha'tar, is snatched from the battlefield - their souls lifted and " ..
                "taken to parts unknown.\n\nI will not have it! A proper burial is out of the question " ..
                "but those fiends will not have their souls! Take this torch and travel to the field of " ..
                "battle, directly east of here. Burn every corpse you see! We will not fuel their rituals.",
        },
        [10914] = {
            description = "It is not enough. A hero is needed. Our forces are overwhelmed as the Auchenai " ..
                "continue to grow in number.\n\n< Commander Ra'vaj looks at you.>\n\nWill you be the " ..
                "hero? Return to the field of battle and strike at their soldiers. Keep them occupied so " ..
                "that my scouts can get behind their lines and see what they are creating.",
        },
        [10915] = {
            description = "They are feeding the souls they steal to a coffin that they have dragged out " ..
                "from the Auchenai Crypts. My scouts believe the contents of the coffin to contain the " ..
                "first exarch of the crypts. They seek to resurrect the ancient one!\n\nYou must battle " ..
                "your way to the western side of Auchindoun and disturb the contents of that coffin " ..
                "before they feed it enough souls. Should you lose your way, follow the walking " ..
                "souls.\n\nDestroy whatever is inside that coffin!",
            rewardChoices = {{31794, 1}, {31796, 1}, {31797, 1}, {31798, 1}},
        },
        [10916] = {
            description = "Anchorite Barada plans to exorcise the corruption from Colonel Jules, and will " ..
                "require an assistant for the task. Such an assistant must be prepared...\n\nI am ashamed " ..
                "to admit that my prayer beads were lost in Honor Hold's courtyard. I believe the dog Fei " ..
                "Fei stole them and buried them, but I do not know where. If you speak with his master, " ..
                "Warrant Officer Tracy Proudwell, perhaps she will know where Fei Fei hides his stolen " ..
                "treasures.",
        },
        [10917] = {
            description = "As an outcast, I am marked for death by arakkoa loyal to the city of Skettis. " ..
                "I cannot leave these walls for fear of my life, but that doesn't mean I cannot strike at " ..
                "them in retaliation.\n\nI have a small cache of treasure that I'm willing to part with, " ..
                "should you help me strike back at my would-be assassins. Bring me feathers from the " ..
                "denizens of the various Veils of Terokkar as proof of their demise.",
            rewardItems = {{31800, 1}},
            rewardMoney = 33000,
        },
        [10918] = {rewardItems = {{31800, 1}}},
        [10920] = {
            description = "When the dreadfang widows attacked our outpost we heard the voice of the naaru " ..
                "calling us to battle. We pursued the creatures into the night. Some of our people we " ..
                "found dead in the dark, others we could hear struggling against their captors.\n\nBy " ..
                "morning we had come to this place and we fought a fierce battle but we were beaten. " ..
                "Dreadfang poison will soon take my companions and I cannot last long. Before I die I " ..
                "must know that the dreadfang widows were beaten.",
        },
        [10921] = {
            description = "You have slain many of the dreadfang widows but they will continue to spawn " ..
                "and soon they will strike at us again. Deep within Netherweb Ridge is the lair of the " ..
                "Terokkarantula, the brood-mother of these gruesome creatures. If we are to be safe, she " ..
                "must die.",
            rewardChoices = {{31819, 1}, {31821, 1}, {31820, 1}, {31823, 1}},
        },
        [10922] = {
            description = "Oy! You look like you can take care of yerself, <race>. Me and the crew here " ..
                "are looking for a bodyguard to watch over us while we hit a dig site to the north. The " ..
                "pay is pretty good and all you gotta do is make sure no nasty creatures kill me or any " ..
                "of my employees.\n\nIf you successfully make it back without any casualties, Dwarfowitz " ..
                "over there will pay ya.",
            rewardMoney = 33000,
        },
        [10923] = {
            description = "Now you must use the Dread Relic in a foul necromantic ritual if you wish to " ..
                "challenge Teribus the Cursed. To the northeast, beyond Auchindoun, is the Writhing " ..
                "Mound, a place where necromancers gather.\n\nThe auchenai death-speakers and doomsayers " ..
                "carry doom skulls that are laced with powerful necro-enchantments. If you collect enough " ..
                "skulls you can use their power along with the power of the Dread Relic to command " ..
                "Teribus to face you.",
            rewardChoices = {{31816, 1}, {31817, 1}, {31818, 1}},
        },
        [10924] = {
            description = "The blood of the warp chasers in this area is a powerful and rare reagent. " ..
                "It's one of my biggest sellers.\n\nNormally, I take my imp, Zeppit, out to help me " ..
                "gather it. Warp chaser blood is simply too caustic to be handled safely by you or I, but " ..
                "it doesn't bother Zeppit.\n\nThings are getting busier here at the shop, so if I send " ..
                "Zeppit with you, will you help gather the blood? Zeppit's attention tends to wander, so " ..
                "you'll need to be close to the chaser when it dies for Zeppit to do his work.",
            rewardMoney = 41000,
        },
        [10926] = {
            description = "We will not make it back on our own. The dreadfang poison is too strong. You " ..
                "must return to Sha'tari Base Camp for us. Scout Navrin will send a rescue party out to " ..
                "find us.",
        },
        [10927] = {
            description = "Commander Skyshadow wants this tunnel cleared out so we can expedite trade " ..
                "with the Harborage. I must not leave my post here so I am leaving the task in your " ..
                "hands. Clear the tunnel and report to Commander Skyshadow at once!",
            rewardMoney = 33000,
        },
        [10928] = {
            description = "Tor'chunk Twoclaws wants this tunnel cleared out so we can expedite trade with " ..
                "Swamp Rat. I must not leave my post here so I am leaving the task in your hands. Clear " ..
                "the tunnel and report to Tor'chunk Twoclaws at once!",
            rewardMoney = 33000,
        },
        [10929] = {
            description = "How would you like to do a little more work for the Explorers' League? These " ..
                "bone worms have us all quite intrigued.\n\nI've got a drum right here that you can use " ..
                "out in the Bone Wastes. Just bang on the damned thing and see what you get. If it's a " ..
                "worm, kill it and bring back the carcass for us to study. We'll need a good lot of " ..
                "carcasses to get a valid testing sample.",
        },
        [10930] = {
            description = "I was right! These carcasses you brought me belong to maturing worms. Do you " ..
                "know what that means? It means that somewhere out there is a big one! I think we can get " ..
                "it to come out if we can provide the right kind of food. Let's see... something big! " ..
                "Yes!\n\nI remember seeing clefthooves east of here on the other side of the Bone Wastes. " ..
                "Get out there and kill a clefthoof. Once it's dead, use the drums. Hopefully the big one " ..
                "will come up to feed. If you manage to kill it, bring me its organs!",
            rewardChoices = {{31756, 1}, {31758, 1}, {31759, 1}},
        },
        [10935] = {
            description = "<name>, it is time to save Colonel Jules. His condition has worsened and " ..
                "Barada fears that, if we do not cleanse him of his corruption, he will be lost to " ..
                "us.\n\nTake the prayer beads you found and speak with Anchorite Barada to begin the " ..
                "ritual. Let no disruptions stop the ritual... and if all goes well, Colonel Jules will " ..
                "be saved. Speak with Jules when he is saved, then return to me.",
            rewardMoney = 40000,
        },
        [10936] = {
            description = "While we were busy, a messenger was waiting out in the hall. I suppose he grew " ..
                "tired, or perhaps he simply ran away at the sight of Jules floating around the " ..
                "room.\n\nEither way, Force Commander Danath is looking for you. I suggest that you seek " ..
                "an audience with him inside the barracks as quickly as possible!",
        },
        [10937] = {
            description = "I'm receiving reports that the Shattered Hand fel orcs, out in front of " ..
                "Hellfire Citadel, are organizing for what looks like an all-out assault. No doubt, " ..
                "they're not happy about your successes against all of the clans.\n\nGet to the base of " ..
                "the citadel, where the Path of Glory ends. You'll find the fel orcs busy with their " ..
                "preparations, but you're going to catch them with their pants down.\n\nEliminate the one " ..
                "that's in charge of that force. Kill Drillmaster Zurok!",
            rewardChoices = {{31717, 1}, {31718, 1}, {31719, 1}, {31720, 1}},
            rewardMoney = 54000,
        },
        [10940] = {
            description = "Now that you have gathered all of the Furies cards together into a deck, a " ..
                "ninth card mysteriously appears with the same backing as the first eight. On this card " ..
                "is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have " ..
                "heard that the entrance to this faire appears near Mulgore and Goldshire every month.",
            rewardItems = {{31858, 1}},
        },
        [10941] = {
            description = "Now that you have gathered all of the Lunacy cards together into a deck, a " ..
                "ninth card mysteriously appears with the same backing as the first eight. On this card " ..
                "is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have " ..
                "heard that the entrance to this faire appears near Mulgore and Goldshire every month.",
            rewardItems = {{31859, 1}},
        },
        [10944] = {
            description = "Thanks again, <name>. I recognize your name. Akama has entrusted you with his " ..
                "plans and so I will trust you as well.\n\nThe naga discovered I was working against " ..
                "Illidan and tried to get me to speak by torturing me. I did not tell them a thing - " ..
                "Akama himself taught me to master pain through meditation.\n\nIllidan asked the naga to " ..
                "bring me to him. He would have seen right through my flesh and into my soul's deepest " ..
                "secrets.\n\nAkama must be warned. Our plans are in jeopardy!",
            rewardMoney = 88000,
        },
        [10946] = {
            description = "Olum's sacrifice was tremendous. I would never have asked him to give up his " ..
                "life myself. But it is done.\n\nIf we're to lure Illidan back into a false sense of " ..
                "security, we need to do his bidding - at least for now.\n\nI command a vast army of " ..
                "Ashtongue, but - aside from the Deathsworn - none can be trusted.\n\nYou are to perform " ..
                "the deed that Illidan demands. Take this cowl; it is magical in nature. You will appear " ..
                "to be one of my men to any who see you slaying Kael's phoenix, Al'ar.",
            rewardMoney = 132000,
        },
        [10947] = {
            description = "Illidan's attention is now on Kael'thas, thanks to you. The time has come to " ..
                "make our move.\n\nI've had a vision of an artifact that will aid us in our final " ..
                "struggle - the phylactery of a lich known as Winterchill. Unfortunately its power was " ..
                "lost forever after his defeat in the Battle of Mount Hyjal.\n\nThere might be a way to " ..
                "retrieve this artifact, however. Legend speaks of a place in Azeroth guarded by bronze " ..
                "dragons... a place where past and present meet. It is there you will find what we seek.",
        },
        [10948] = {
            description = "You might wonder why I go to such lengths to hide my intentions. Why not throw " ..
                "my lot in openly with the naaru?\n\nMy very essence - my soul - is held prisoner inside " ..
                "the Black Temple. Illidan could destroy me any moment... until now! This phylactery will " ..
                "allow me to regain control of my soul.\n\nThe time has come, <name>. I'll lead Maiev and " ..
                "my Deathsworn to Illidan's doorstep.\n\nSpeak to A'dal and and tell him of our plan. If " ..
                "we strike together we'll break through Illidan's defenses.",
        },
        [10949] = {
            description = "< A'dal shows you an image of a naaru outside of the Black Temple, fighting " ..
                "alongside draenei vindicators and blood elf magisters. You immediately understand that " ..
                "this is the distraction Akama is waiting for.>",
            rewardMoney = 44000,
        },
        [10957] = {
            description = "When Illidan obtained the Broken's allegiance, Akama was our wisest. He knew " ..
                "that openly opposing the Betrayer would lead to the extinction of our race.\n\nInstead " ..
                "he has plotted and schemed for this very moment under utmost secrecy. Failure would be " ..
                "catastrophic... not just for Akama, not just for the Broken, but for all of Outland. No " ..
                "one this close to Illidan has ever been able to deliver such a terrible blow to " ..
                "him.\n\nHelp Akama free his soul and he will grant you access to Illidan's sanctum.",
        },
        [10958] = {
            description = "<As you look up at Xi'ri, your mind becomes focused and your will determined. " ..
                "Your work here is not done; you must go inside the Black Temple and find Akama's " ..
                "followers.>\n\n<Much depends on Akama's success.>",
        },
        [10969] = {
            description = "It would seem that an outside force has taken an interest in the business " ..
                "practices of the Consortium. Five Consortium dealers have gone missing in the past two " ..
                "days. We have reason to believe the Ethereum are involved. If you are interested in " ..
                "assisting, seek out Commander Ameer at the Protectorate Watch Post.\n\nYou will find the " ..
                "Protectorate Watch Post directly east of here on the next island.",
            rewardMoney = 4400,
        },
        [10970] = {
            description = "We salvaged this prison orb on our last scouting mission into Ethereum " ..
                "territory. We'd have never found it had it not been for the distress signal that it was " ..
                "faintly emitting.\n\nWe think one of our own might be locked up in there but we have no " ..
                "way of opening the orb up without harming whatever is inside.\n\nWhat we know about the " ..
                "Ethereum is that any of their members could - at any given time - be carrying a key to " ..
                "unlock an orb. Retrieve one and return so that we may uncover the mysteries of this orb.",
            rewardMoney = 44000,
        },
        [10971] = {
            description = "<Ameer holds up a tag.>\n\nI found this prisoner I.D. tag with the remains of " ..
                "the fallen vanguard. I can only assume that all of their prisoners are tagged in the " ..
                "same manner.\n\nI'm going to start cataloguing the tags in hopes of making sense of " ..
                "their penal system. If in your adventures you find more Ethereum prison keys, you can " ..
                "use them to open the Ethereum prisons at the Ethereum Staging Grounds - directly south " ..
                "of here. Bring me back any and all I.D. tags that you find.",
            rewardMoney = 44000,
        },
        [10972] = {
            description = "I am in need of more I.D tags, <name>. What I've discovered thus far is that " ..
                "this is not just a way to catalogue prisoners but it also documents locations!\n\nOnce " ..
                "this code is broken we'll be able to pinpoint exactly where all of our allies are held " ..
                "and free them with minimal hostile action received.",
        },
        [10973] = {
            description = "I have cracked the code! Each tag is broken up into several segments. The " ..
                "front side of the tag is always the same and states: \"A Thousand Worlds...\" I am " ..
                "unsure as to the meaning of this phrase but it sounds insidious.\n\nOn the back side of " ..
                "the tag are the vital statistics. The first set of runes indicates location and the " ..
                "second indicates prisoner type. Furthermore, it would seem that the keys can be combined " ..
                "to form a special key that accesses another prison type. Now I just need more keys...",
            rewardMoney = 132000,
        },
        [10974] = {
            description = "The Ethereum have a settlement on the northernmost shelf of Blade's Edge " ..
                "Mountains known as Bash'ir's Landing. According to the key tablet, much larger versions " ..
                "of the prisons are kept at Bash'ir's. It should also be noted that the Ethereum refer to " ..
                "those prisons as stasis chambers.\n\nThe key tablet grants access to a very specific " ..
                "stasis chamber at the landing known as Stasis Chamber Alpha. Take the key and " ..
                "investigate.\n\nMy image will be awaiting your return at Bash'ir's Landing. Speak to me " ..
                "there.",
            rewardItems = {{32064, 1}},
        },
        [10975] = {rewardItems = {{29750, 1}}, rewardMoney = 44000},
        [10976] = {
            description = "What I must now know is what the Ethereum have held inside the Mana-Tombs of " ..
                "Auchindoun.\n\nIn your battles against the beasts of the stasis chambers of Bash'ir you " ..
                "may run across an item known as the Mark of the Nexus-King. Should you find such an " ..
                "item, return it to me immediately! It is the final piece in crafting a key that will " ..
                "allow access to the stasis chamber inside the Mana-Tombs.",
            rewardMoney = 44000,
        },
        [10977] = {
            description = "The Mark of the Nexus-King that you recovered has allowed me to forge a new " ..
                "key for the stasis chambers found inside the Mana-Tombs.\n\nAccording to the glyphs on " ..
                "the mark, two exist: one near the front and one near Nexus-Prince Shaffar. This key that " ..
                "I am about to give you will open the stasis chamber near the front.\n\nI want you to go " ..
                "to the Mana-Tombs of Auchindoun and open the Mana-Tombs Stasis Chamber.",
            rewardItems = {{29434, 1}},
            rewardMoney = 132000,
        },
        [10981] = {rewardItems = {{32079, 1}}},
        [10982] = {rewardItems = {{32092, 1}}, rewardMoney = 132000},
        [10983] = {
            description = "Mog'dorg wise! Him send Grok to city, look for help. Bloodmaul clan need " ..
                "help.\n\nMog'dorg say, send powerful little ones to him at Blade's Edge Mountains. Him " ..
                "stand on tower at Circle of Blood. Mog'dorg wise!",
            rewardMoney = 4400,
        },
        [10984] = {
            description = "< V'eru 's voice fills your mind with crystalline tone and clarity.>\n\nThere " ..
                "is an ogre down in the Lower City, pleading for the assistance of passersby. They have " ..
                "all turned a deaf ear upon his plight.\n\nDo you think you might aid him?\n\nHis name is " ..
                "Grok, and he is sitting near the merchants to the southeast.\n\nThank you, <name>.",
        },
        [10989] = {
            description = "Mog'dorg the Wizened waits for you at top of da tower. He tells me to look for " ..
                "a <race> <class> just like you. You go speak with him about smart things.\n\nGo now, but " ..
                "don't tell no one. It's a secret!",
        },
        [10995] = {
            description = "To the east, at the terminus of Dragons' End, is the Cursed Hollow. Therein, " ..
                "Grulloc, son of Gruul, plots his dimwitted schemes.\n\nI heard that one of his " ..
                "possessions was stolen from him through trickery. Was that you? Unfortunate that he was " ..
                "not slain in the process.\n\nIf we are to regain our freedom, I would have you take his " ..
                "most prized possession, a dragon skull from when he rejoiced in his father's slaying of " ..
                "the black dragonflight. The only way you'll get the skull is to vanquish him.",
            rewardMoney = 88000,
        },
        [10996] = {
            description = "On the Razor Ridge, above and to the southeast, Maggoc patrols. His father " ..
                "assigned him as the warden of the eastern mountain range, and he revels in terrorizing " ..
                "any creature that gets in his way.\n\nAs a son of Gruul, he must be done away with if my " ..
                "clan is to survive. That's where you come in.\n\nMaggoc carries a treasure chest with " ..
                "him at all times. Prove to me that he has been slain by bringing me his precious chest. " ..
                "Feel free to keep whatever you find within it.",
            rewardMoney = 88000,
        },
        [10997] = {
            description = "Are you familiar with Shattrath City, <class>? Above it to the northwest is a " ..
                "place called the Barrier Hills, which you can only get to upon a flying mount.\n\nOne of " ..
                "Gruul's sons, Slaag, exiled himself and took control of the Gordunni ogres that reside " ..
                "there. Even at such a distance, we cannot afford to leave him in peace, lest he return " ..
                "when the rest of his brothers have been slain.\n\n<name>, you must travel there, and " ..
                "bring back his standard as proof that he has been dealt with.",
            rewardMoney = 88000,
        },
        [10998] = {
            description = "There is one more gronn to be slain: Skulloc Soulgrinder. He keeps himself " ..
                "hidden away, but there is a way to coax him forth.\n\nHe was trained by an ogre warlock " ..
                "known as Vim'gol the Vile, whose grimoire you must retrieve!\n\nVim'gol must be summoned " ..
                "by standing within a fire ring at his circle. Find Vim'gol's Circle in the mountains, to " ..
                "the northeast, near the Broken Wilds.",
            rewardMoney = 88000,
        },
        [10999] = {description = "Bring me 8 trogg stone teeth."},
        [11000] = {
            description = "The grimoire is the key to Skulloc's downfall.\n\nRead aloud from the book at " ..
                "Soulgrinder's Barrow to initiate the ritual. An object known as the Soulgrinder will " ..
                "appear, as well as Skulloc's ghostly victims, who will try to destroy it. You must keep " ..
                "them from doing so long enough to force Skulloc fully into the world.\n\nFind the barrow " ..
                "by heading north through the Daggermaw Canyon on the other side of the Circle of Blood. " ..
                "It is on the right side before Gruul's Lair.\n\nBring back Skulloc's soul.",
            rewardMoney = 132000,
        },
        [11002] = {
            description = "The source of Illidan Stormrage's fel orc army has been vanquished. The " ..
                "manufactory halts production of its grim product - at least for now. All that remains " ..
                "are a few trinkets and this severed head - a fitting trophy for a hero of the " ..
                "Alliance.\n\nReturn Magtheridon's head to Danath Trollbane at Honor Hold.",
            rewardChoices = {{28792, 1}, {28793, 1}, {28790, 1}, {28791, 1}},
            rewardMoney = 132000,
        },
        [11003] = {
            description = "The source of Illidan Stormrage's fel orc army has been vanquished. The " ..
                "manufactory halts production of its grim product - at least for now. All that remains " ..
                "are a few trinkets and this severed head - a fitting trophy for a hero of the " ..
                "Horde.\n\nReturn Magtheridon's head to Nazgrel at Thrallmar.",
            rewardChoices = {{28792, 1}, {28793, 1}, {28790, 1}, {28791, 1}},
            rewardMoney = 132000,
        },
        [11005] = {
            description = "Thank you for paying heed to my fevered rants. All along we had been trying to " ..
                "identify and destroy the Skettis chain of command; we had learned of three clerics known " ..
                "as the talonpriests, but we'd never seen them with our own two eyes. Now we know " ..
                "why.\n\nTalk to Severin to obtain more of the elixir he discovered. Use the elixir to " ..
                "find and kill the three talonpriests: Ishaal, Skizzik and Zellek. They're rumored to " ..
                "dwell in Veil Ala'rak, near the eastern shore of Blackwind Lake.",
        },
        [11006] = {rewardItems = {{32446, 1}}},
        [11007] = {
            description = "The air around you hums - a gentle hum. The naaru are aware of your victory. " ..
                "Perhaps they are the reason you were compelled to pick up this sphere from the " ..
                "still-twitching remains of Kael'thas Sunstrider. What secrets could it hold?\n\nPerhaps " ..
                "A'dal in Shattrath City could make sense of the item.",
            rewardChoices = {{30007, 1}, {30015, 1}, {30017, 1}, {30018, 1}},
            rewardMoney = 132000,
        },
        [11008] = {
            description = "You think you have what it takes to be part of the Skyguard? We'll have to see " ..
                "how you handle yerself in the air.\n\nThe arakkoa are breeding a gargantuan variety of " ..
                "their attack pets and are using it against our scouts. I want you to take these blasting " ..
                "charges and use them to destroy hatcheries above the arakkoa's dwellings. Avoid the " ..
                "monstrous kaliri guarding the hatcheries. They'll knock you off your mount before you " ..
                "know what hit you.",
            rewardMoney = 44000,
        },
        [11009] = {
            description = "Now that you have delivered us from bondage, we can begin the process of " ..
                "reunifying the clans. This will take some time; old grudges are difficult to " ..
                "overcome.\n\nBut more pressing, you must go to Ogri'la in the heavens above to the west. " ..
                "You must defend it, and us, from those forces above that the gronn used to protect us " ..
                "from: ethereals, demons, and worst of all, the black dragonflight.\n\nWhen you find ogre " ..
                "heaven, seek out the wisdom of Chu'a'lor on how best to proceed.",
        },
        [11010] = {
            description = "You have a flying mount... so what! You think you have what it takes to use it " ..
                "properly?\n\nForge Camp: Wrath and Forge Camp: Terror, to the north and south, are a " ..
                "major pain in my backside, as well as being a threat to peaceful Ogri'la. With all of " ..
                "those fel cannons shooting down the Skyguard left and right, we can't get through there " ..
                "to take care of business.\n\nYou want to prove yourself? Take these bombs and knock out " ..
                "their ammo stacks. Just don't let them shoot you down, too!",
            rewardMoney = 44000,
        },
        [11013] = {
            description = "Netherwing Ledge... What was once a bastion of sanctuary for the Netherwing is " ..
                "now home to the Dragonmaw. While the orcs may have control of our territory, our magic " ..
                "there is still strong. Strong enough to cloak your true identity and allow you to " ..
                "infiltrate the ranks of Dragonmaw.\n\nI have prepared this letter for you to present to " ..
                "their leader, Overlord Mor'ghor. Fly headlong into the maw of our enemy and seek out " ..
                "Dragonmaw Base Camp to start your new life as a fel orc of Illidan Stormrage.",
        },
        [11014] = {
            description = "<Mor'ghor crumples up the service letter and tosses it aside.>\n\nAlright " ..
                "grunt, first things first. If you're gonna join my beloved Dragonmaw army, you'll need " ..
                "to work. Everyone works up here on the ledge. Get a job and don't screw it up and I'll " ..
                "see if there might be something more interesting for you to do later.\n\nGo talk to " ..
                "Taskmaster Varkule Dragonbreath. He's standin' in the middle of town. He'll assess your " ..
                "skills and assign work as he sees fit.\n\nNow get out of my face!",
        },
        [11016] = {
            description = "A skinner, eh? Well you'll find plenty to skin here! You gotta search for " ..
                "flayers around crystal formations. Take 'em down and take their hides. Sometimes they'll " ..
                "have a hide worth keepin'. Bring those to me.",
            rewardMoney = 44000,
        },
        [11017] = {
            description = "A flower picker?! Hilarious... Unfortunately, our mages and shaman need your " ..
                "services. The netherdust bushes that grow on this ledge have special pollen that is " ..
                "apparently very useful in their magical dealings. Bring me that stuff and I'll consider " ..
                "your work order complete.",
            rewardMoney = 44000,
        },
        [11018] = {
            description = "A miner!\n\n<Varkule salutes.>\n\nAn orc after my own heart! That's how " ..
                "Varkule got his start - minin'! There ain't nothin' better than getting down and dirty " ..
                "in the mines, is there?\n\nNow get out there and find those nethercite deposits. Strip " ..
                "'em for all their worth and bring me back the ore.",
            rewardMoney = 44000,
        },
        [11020] = {
            description = "The Dragonmaw have peons stationed at nearly every crystal formation up here. " ..
                "While the outright slaying of them would draw far too much unwanted attention to you, " ..
                "there is a way that we can thin their numbers and remain below the suspicious eyes of " ..
                "Mor'ghor.\n\nVenture into the wilds of Shadowmoon Valley and slay the tainted wildlife. " ..
                "Take from them their corrupt fel glands. Use those fel glands with this mutton that I'll " ..
                "give you near the peons. They'll take one bite and fall deathly ill!",
            rewardMoney = 44000,
        },
        [11021] = {
            description = "This mysterious tome was on Talonpriest Ishaal's body. It contains arcane " ..
                "symbols and charts of celestial bodies beyond your comprehension.\n\nAll writing is in a " ..
                "language you don't understand; likely an ancient version of the arakkoa written tongue. " ..
                "Perhaps you should bring this to Sky Commander Adaris.",
        },
        [11022] = {
            description = "<King/Queen> <name>! You speak with Mog'dorg the Wizened before you leave and " ..
                "go to Ogri'la!",
        },
        [11023] = {
            description = "We're still having problems with those flak cannons, <name>.\n\nDon't get me " ..
                "wrong -- I think that you did an outstanding job the last time out -- but, that doesn't " ..
                "change the fact that those damned demons seem to be replenishing their ammo supplies " ..
                "faster than we can knock them out. And that means we're having a hell of a time getting " ..
                "our people through there, not to mention the risk those demons pose to Ogri'la.\n\nWhat " ..
                "do you say? Want to take another shot at it?",
            rewardItems = {{32569, 15}},
            rewardMoney = 44000,
        },
        [11024] = {
            description = "There is an arakkoa in Lower City by the name of Rilak... He can be trusted. " ..
                "Take the book... to him.\n\n<Adaris drifts into unconsciousness as he returns the book " ..
                "to you.>",
        },
        [11025] = {
            description = "When prepared correctly, the crystals of the mountains exhibit strange powers, " ..
                "such as the clarity of mind that we have found here in Ogri'la.\n\nAll of the creatures " ..
                "atop the mountains covet the crystal shards and use them to further their own goals. An " ..
                "economy has even sprung up around them.\n\nTo assist us, you must first learn about the " ..
                "Apexis shards. Bring me some. In addition to the creatures here having them, they can " ..
                "sometimes be found where the flayers dig at the larger crystals.",
            rewardMoney = 44000,
        },
        [11026] = {
            description = "You've arrived at the perfect time, friend! We are in need of assistance. In " ..
                "return, you will receive something very rare, which will help us both in the " ..
                "end.\n\nWe're not a violent ogre any longer, but the demons nearby threaten to overrun " ..
                "us and the Skyguard. The problem with demons is that, once killed, they come right back " ..
                "in new bodies!\n\nBut, if you use this crystal to summon a banishing portal, when they " ..
                "die near it, their essences will be drawn in and banished back from whence they came!",
            rewardItems = {{32643, 1}},
            rewardMoney = 44000,
        },
        [11028] = {
            description = "This almanac presages the return of Terokk, the most powerful and terrible " ..
                "Skettis king in arakkoa history.\n\nI always believed this to be the mere legend, " ..
                "<name>. The return of the talonpriests and your recovery of this tome indicate " ..
                "otherwise.\n\nWith each day, Terokk comes closer to returning to full strength. Your " ..
                "only chance is to bring him to our world prematurely. Return to Skettis and speak to " ..
                "Adaris about this. Let us hope he has the wisdom to do the right thing.",
        },
        [11029] = {
            description = "Open the package, <name>. It is a disguise. It doesn't look very convincing, " ..
                "does it?\n\nI craft them for ethereal smugglers in search of rare books. There is an " ..
                "arakkoa scribe who dwells in the central island in Skettis, Terokk's Rest; his name is " ..
                "Sahaak. He is old and nearly blind.\n\nUse the disguise to speak with him and obtain the " ..
                "book known as the Adversarial Bloodlines. Be careful, <name>. The disguise won't fool " ..
                "the other arakkoa.",
        },
        [11030] = {
            description = "<class>, we've got a problem -- we have lots of sons. And ever since the " ..
                "Skyguard moved in nearby, all our sons ever talk about is joining their ranks.\n\nAs a " ..
                "proud father, we want them to have every advantage for when they apply. So, would you go " ..
                "to the fel crystalforge at either forge camp to the north or south, and procure a magic " ..
                "flask for our sons? You can't miss their green smoke.\n\nWe think that they take ten " ..
                "apexis shards to make. We'd give you the shards, but we don't have any at the moment.",
            rewardMoney = 44000,
        },
        [11031] = {rewardChoices = {{29290, 1}, {29279, 1}, {29283, 1}}},
        [11032] = {rewardChoices = {{29290, 1}, {29287, 1}, {29283, 1}}},
        [11033] = {rewardChoices = {{29290, 1}, {29279, 1}, {29287, 1}}},
        [11034] = {rewardChoices = {{29283, 1}, {29279, 1}, {29287, 1}}},
        [11035] = {
            description = "On the northeast edge of this island exists a dock used for the packaging and " ..
                "transport of Netherwing crystals and relics. Dragonmaw Transporters transport the goods " ..
                "from the dock to Dragonmaw Fortress while Dragonmaw Ascendants guard the ground from any " ..
                "would-be attackers.\n\nThis leaves one opening for you to make a strike at the " ..
                "Dragonmaw: The Dragonmaw Skyway.\n\nFly to the shattered islands of the Dragonmaw Skyway " ..
                "and ambush the transporters that use the route. Recover our stolen relics!",
            rewardMoney = 44000,
        },
        [11036] = {
            description = "I'll be the first to admit I'm not quite sure what this order is for, but " ..
                "Rocket-Chief Fuselage 's instructions were very specific -- only the very best fruit, " ..
                "preserved to survive a long voyage and sealed against the elements.\n\nThere were other " ..
                "specifications, zero-gravity this and low pressure that. I don't pretend to understand " ..
                "it, but the price is right, so he'll get his superfood. Bring this crate to him up at " ..
                "Area 52. After crossing into Netherstorm, keep following the road until you see the town.",
        },
        [11037] = {
            description = "I've had a most unusual vision, <name>, and I don't know quite what to make of " ..
                "it. I've seen an arrow, an immense arrow, riding into the sky on a trail of fire. Such a " ..
                "feat is trivial for a skilled mage, but somehow I know the arrow I saw is not the " ..
                "product of magic.\n\nIt will be unlike anything the people of Azeroth have ever " ..
                "achieved. You must seek out the people working on this, <name>. Lend them your help, for " ..
                "without it, their efforts may yet fail.",
        },
        [11038] = {
            description = "Not long ago, High Priestess Ishanah sent a small group of anchorites to " ..
                "Netherstorm, under the command of Exarch Orelis. They were to investigate the activities " ..
                "of Kael'thas and his minions, but we haven't received any reports of their findings " ..
                "yet.\n\nI worry that our presence in the area might not be strong enough to carry out " ..
                "the mission. I'm certain that the exarch could benefit from your knowledge and " ..
                "experience. Are you willing to travel to Area 52 and assist him?",
        },
        [11039] = {
            description = "Some time ago, Voren'thal dispatched a small team to Netherstorm to " ..
                "investigate the activities of Kael'thas. Our leader has the utmost confidence in " ..
                "Spymaster Thalodien and his compatriots, and has decided to honor his request for " ..
                "reinforcements.\n\nThalodien's report was brief, but clear that he's encountered " ..
                "something of great importance. Report to him at Area 52 and assist him in any way " ..
                "possible, <name>.",
        },
        [11040] = {
            description = "You can count on one hand the number of times I've collaborated with a goblin. " ..
                "We're far more likely to be in competition with them, but when I received Rocket-Chief " ..
                "Fuselage 's request, I just couldn't refuse him.\n\nThis crate is full of parts I'm not " ..
                "using here, but that the rocket-chief might be able to put to use on his project. Would " ..
                "you be kind enough to deliver them if you're on your way to Area 52?\n\nWho knows, maybe " ..
                "some fine gnomish parts could keep his creation from exploding!",
        },
        [11042] = {
            description = "A strange vision haunts me, <name>. I see a continuous cloud of smoke " ..
                "ascending toward the sky, left in the wake of a giant fire moving ever faster away. It " ..
                "is not a natural phenomenon, nor a creation of evil; that much I know.\n\nI have no " ..
                "knowledge of what it looks like, save that it is the product of the labor of many. Yet, " ..
                "without more hands, it may never come to be.\n\nTravel to Netherstorm, <class>. Locate " ..
                "those responsible for this creation and offer them your aid.",
        },
        [11043] = {
            description = "I've heard that the Wildhammer dwarves maintain a gryphon roost at their " ..
                "fortress down in southern Shadowmoon Valley. If you're going down there, would you speak " ..
                "to them on my behalf? I have some ideas on how to improve their gryphons!\n\nWhy stop at " ..
                "armoring them when you could attach an altimeter, a rear view mirror, and rocket? " ..
                "Imagine how fast you could go with one of those babies strapped to your gryphon's back! " ..
                "I'll call it the TurboGryphon 8000!",
        },
        [11044] = {
            description = "A vision of cataclysm often disturbs my rest -- a rain of green fire falling " ..
                "to the earth, felling the valiant defenders of a mighty fortress. It has haunted me for " ..
                "weeks now, although I have only recently come to understand its meaning.\n\nTo the far " ..
                "east, in Shadowmoon Valley, the Wildhammer dwarves endure constant attacks from the " ..
                "Burning Legion and numerous other foes. They fight bravely, but without relief, their " ..
                "enemies will triumph. Go to their side, <name>. Help them in their fight.",
        },
        [11045] = {
            description = "The history of Shadowmoon Valley is a long and troubled one. Few delve into it " ..
                "for fear of breathing new life into the unspeakable atrocities that took place " ..
                "there.\n\nNot all are so timid, though. Zorus the Judicator searches for the truth about " ..
                "the ghosts of Shadowmoon's past. It is a staggering undertaking, one with which he would " ..
                "welcome help, I'm sure.\n\nIf you should venture into the valley, look for Zorus at " ..
                "Wildhammer Stronghold, in the central portion of the valley's southern region.",
        },
        [11046] = {
            description = "The history of Shadowmoon Valley is a long and troubled one. Few study it for " ..
                "fear of breathing new life into the unspeakable atrocities that took place there.\n\nNot " ..
                "all are so timid, though. Chief Apothecary Hildagard 's research delves into the ghosts " ..
                "of Shadowmoon's past. It is a staggering undertaking, one with which she would welcome " ..
                "help, I'm sure.\n\nIf your travels bring you there, seek Hildagard at Shadowmoon " ..
                "Village, in the northwestern reaches of the valley.",
        },
        [11047] = {
            description = "As an apprentice wind rider master, one of my tasks is to care for the beasts " ..
                "when they're not flying. The problem is that we have so few here, there's very little " ..
                "downtime for any of them.\n\nI'm afraid we'll work them all to death if we don't receive " ..
                "any replacements. There's a large stable down in Shadowmoon Village, in western " ..
                "Shadowmoon Valley. Dama Wildmane oversees the wind rider care and training " ..
                "there.\n\nWould you speak with her on our behalf and let her know about our situation?",
        },
        [11048] = {
            description = "My original orders were to remain in Garadar for a short time, then continue " ..
                "on and report to Blood Guard Gulmok at Shadowmoon Village. What I've seen in my time " ..
                "here is that Garadar could benefit from a long term Horde liaison.\n\nI know that Blood " ..
                "Guard Gulmok needs all the troops he can get, but I know he'll understand that my " ..
                "mission here isn't yet complete. Travel to Shadowmoon Village, in northwestern " ..
                "Shadowmoon Valley, and inform Blood Guard Gulmok of my delayed arrival.",
        },
        [11049] = {
            description = "Should you discover any Netherwing eggs while exploring, bring them to " ..
                "me.\n\nBe warned, a Netherwing egg is a rare discovery. Do not become frustrated if you " ..
                "cannot locate one. These Dragonmaw have been very thorough in collecting most of them " ..
                "and shipping them off to parts unknown.\n\nEggs might be found on creatures of the " ..
                "island, near crystal formations, in the mines, or even inside a nethercite node or " ..
                "netherdust bush.\n\nKeep a low profile. We don't need Mor'ghor catching wind of your " ..
                "actions.",
            rewardMoney = 88000,
        },
        [11051] = {
            description = "If we know the demons, and we do because we've studied them extensively, " ..
                "they're fast at work repairing any damage that has been done to their precious " ..
                "transporter.\n\nSo, if you want a chance at another darkrune, take our banishing crystal " ..
                "back out there and eliminate more demons. Besides, you want to help us to lessen the " ..
                "threat that the demons pose, yes?\n\nWe said \"chance\" because the process we use " ..
                "yields mixed results. You might get a darkrune, or you might get something else entirely.",
            rewardItems = {{32777, 1}, {32569, 15}},
            rewardMoney = 44000,
        },
        [11052] = {
            description = "< Akama inserts the crystal into the medallion in his hand.>\n\nI am not as " ..
                "strong as I once was, <name>. Being so close to evil itself all these years - I do not " ..
                "know if I can trust myself with an artifact as powerful as this.\n\nTake this as my " ..
                "promise to you that when the time comes and you face Illidan, I will be on your side. " ..
                "Take it to the one being we know we can trust with its power. Take the medallion to " ..
                "A'dal in Shattrath City.",
            rewardChoices = {{30932, 1}, {30943, 1}, {30984, 1}, {30999, 1}, {31000, 1}, {31417, 1}},
        },
        [11053] = {
            description = "Rare it is that a peon survives for as long as you have. Rarer still is when a " ..
                "peon rises from the dregs to attain a new rank.\n\n<Varkule claps.>\n\nThe Overlord has " ..
                "called for you, grunt. A new rank awaits, no doubt.",
            rewardItems = {{32694, 1}},
            rewardMoney = 44000,
        },
        [11054] = {
            description = "So you're the new overseer, eh? Well there's one thing any good overseer needs " ..
                "and that's the proper disciplinary weapon. Before you can go out there and knock some " ..
                "sense into these peons you need to have your \"piece.\" Each overseer has to gather the " ..
                "materials required to make their own \"piece\" and you'll be no different.\n\nI'll need " ..
                "knothide leather and the hardened hide of Tyrantus. You'll find Tyrantus in Eco-Dome " ..
                "Farfield, located in the northern reaches of Netherstorm.",
            rewardMoney = 44000,
        },
        [11055] = {
            description = "This is your booterang. There are many like it but this one is yours.\n\nAs an " ..
                "overseer you will use this booterang to sow terror into the hearts of defiant peons. " ..
                "Proper use of the booterang will instill obedience and ensure subservience.\n\nVenture " ..
                "forth to the crystal fields and discipline any peons that you see slacking off. Show " ..
                "them the might of the booterang!",
            rewardMoney = 44000,
        },
        [11056] = {
            description = "Do not draw attention to our conversation. Adaris would not approve.\n\nI " ..
                "belong to the lowest caste of arakkoa, <name>. During Terokk's rule I would've been " ..
                "sacrificed to the dark powers worshipped by his talonpriests. If what you say is true " ..
                "and the talonpriests are seeking Terokk's return, then you must prevent them from " ..
                "succeeding - regardless of what your leader says!\n\nI've something to offer you that " ..
                "you'll find useful. There is a package at my old dwelling in Upper Veil Shil'ak. Bring " ..
                "it to me!",
        },
        [11057] = {
            description = "We commend your zeal in wanting to help out here in Ogri'la, <class>. However, " ..
                "we have a favor to ask of you before we can accept your assistance.\n\nDown below our " ..
                "brethren are enslaved to the Sons of Gruul. Please, speak with Mog'dorg the Wizened, who " ..
                "is leading an ogre resistance against their gronn masters.\n\nSeek him out atop the " ..
                "tower on the eastern side of the Circle of Blood arena.",
        },
        [11058] = {
            description = "Long ago a now-extinct sect of the arakkoa known as the Apexis lived here. " ..
                "Remnants of their civilization are still present. We call them apexis relics.\n\nWhat we " ..
                "know about them is that, when properly used, they grant a boon. Each relic presents a " ..
                "colored sequence which, when the crystals are pressed in the correct order, leads " ..
                "through a series of levels, each harder than the last.\n\nAn apexis shard is needed to " ..
                "power the relic. Return when you have attained the insight of the apexis vibration.",
            rewardMoney = 44000,
        },
        [11059] = {
            description = "You've figured out how to use the single-person relics, but as you may have " ..
                "seen, there are bigger ones, which they surround.\n\nThese larger apexis monuments " ..
                "function in much the same way, but they take 35 apexis shards to activate.\n\nOf greater " ..
                "concern to us are the guardians that are summoned through their use. These crystal " ..
                "constructs turned on their arakkoan masters long ago, and now endanger Ogri'la.\n\nWe " ..
                "would ask that you destroy one and bring us proof.",
            rewardMoney = 132000,
        },
        [11060] = {rewardItems = {{32602, 1}}, rewardMoney = 4400, startedBy = {{23300}}},
        [11061] = {
            description = "As to that other magical flask, it can only be obtained from one spot: Bash'ir " ..
                "Landing. It's an ethereal base, and they aren't too friendly with outsiders, so it might " ..
                "be a little dangerous to obtain.\n\nWhere's Bash'ir Landing, you ask? Well, if you get " ..
                "on your flying steed and head north by northeast, well past Forge Camp: Wrath, you'll " ..
                "eventually spot it. The Bash'ir crystalforge itself is at the northeast corner of the " ..
                "landing.\n\nThank you for doing this, <name>. It'll mean the world to our sons!",
            rewardMoney = 44000,
        },
        [11062] = {
            description = "<name>, we were wondering if you might be willing to visit our friends just to " ..
                "the north at the Skyguard Outpost?\n\nSky Commander Keller and his Skyguard are here " ..
                "running missions for our mutual protection, and he's asked us to send along anyone that " ..
                "we feel would excel at helping out.\n\nThat would be you!\n\nHead up there as soon as " ..
                "you can, and please, give him our regards.",
            rewardMoney = 4400,
        },
        [11064] = {
            description = "Don't let the gray hair fool you, grunt. I'm still ten times the rider that " ..
                "you are! And don't go thinking that this old dog doesn't have any tricks up his " ..
                "sleeve.\n\nNow all you gotta do is follow me and try not to get knocked down off your " ..
                "mount. If you can do that, Oldie will admit defeat.\n\nWe'll lift off as soon as you're " ..
                "ready.",
            rewardMoney = 44000,
        },
        [11065] = {
            description = "Wanna help the Skyguard and Ogri'la?\n\nJust hear me out before you walk away, " ..
                "<hot stuff/girly>. We're in need of remounts! The bombing runs and missions to Bash'ir " ..
                "Landing have taken a toll on our mounts.\n\nThe aether rays that fly around Vortex " ..
                "Summit, and the Crystal Spine to the northeast, look like they'd do just fine. You don't " ..
                "even have to bring them back here, though that would be nice. Just break and rope them, " ..
                "and we'll track them down later.\n\nThink you can wrangle me up some?",
            rewardMoney = 44000,
        },
        [11066] = {
            description = "So, I hope that you're up to helping us wrangle up even more aether rays! From " ..
                "what I can see, you're a natural with the rope! And it's for a good cause, because not " ..
                "only do we get fresh mounts, but it helps us to protect Ogri'la, which the ogres " ..
                "appreciate.\n\nRemember, the aether rays fly around Vortex Summit, and the Crystal Spine " ..
                "to the northeast.\n\nThink you can wrangle me up some more?",
            rewardItems = {{32569, 15}},
            rewardMoney = 44000,
        },
        [11067] = {
            description = "Dragonmaw treat you right, <name>. Even a worn out cursed being like me is " ..
                "given a chance. Now if you want to prove your worth to the Skybreakers, you will have to " ..
                "defeat me.\n\nI'm going to shake you off my tail like a bad case of fleas...\n\nWe'll " ..
                "lift off when you are ready.",
            rewardMoney = 44000,
        },
        [11068] = {
            description = "You are challenging ME? Don't make me laugh!\n\nYou're serious? Very well " ..
                "then! All you need to do is not die. You can manage to not die, right?? Even if I'm " ..
                "hurling skulls at you and flying circles around your pathetic riding skills?\n\nJust let " ..
                "me know when you're ready and we'll lift off.",
            rewardMoney = 88000,
        },
        [11069] = {
            description = "Three years I spent in that hell hole. Three years a prisoner of war to the " ..
                "damnable Frostwolf Clan. Made to sit in their tower and listen to them endlessly whine " ..
                "about the bridge to Dun Baldar. About how it's \"unfair\" that blah, blah, blah, blah... " ..
                "War isn't fair! To hell with 'em all!\n\nThe minute I was freed I left that place " ..
                "forever and came here to start a new life. Now Mulv and I are vying for the top orc " ..
                "spot. If you want it, you're gonna have to go through me, scrub.\n\nWe go when you're " ..
                "ready.",
            rewardMoney = 88000,
        },
        [11070] = {
            description = "Three years of blood, sweat and tears. Mostly tears... The amount of crying " ..
                "that a hardened soldier does when it comes down to all-out war is amazing!\n\n\"They're " ..
                "jumping into our tower with their horses!\" \"Why is their base so well defended?\" " ..
                "\"They're taking our relief hut, I'm going A.W.O.L.!\"\n\nWimps...\n\nI took the first " ..
                "train out of \"cry-town\" the minute the Dark Portal opened. Now I'm a top gun for the " ..
                "Dragonmaw. If you want to be top orc, you'll have to defeat me.\n\nWe go when you are " ..
                "ready.",
            rewardMoney = 88000,
        },
        [11071] = {
            description = "You dare challenge Skyshatter? The world around you will fall into darkness as " ..
                "the heavens are torn asunder by my meteors.\n\nYou stand no chance, soldier. Yet it is " ..
                "your desire to die...\n\nI will entertain this morbid obsession if only to prove a point " ..
                "to any that might foolishly dream of making the same mistake.\n\nWe ride when you are " ..
                "ready!",
            rewardItems = {{32863, 1}},
            rewardMoney = 132000,
        },
        [11075] = {
            description = "Your help is required at the Netherwing Mines, overseer <name>.\n\nTwo days " ..
                "ago our mining operations came to a grinding halt when we made a grim discovery. A miner " ..
                "was working in the depths of the mine and struck his pick upon an unusual crystal " ..
                "formation. Unfortunately, this crystal formation was attached to a very angry nether " ..
                "dragon. The beast woke from its slumber and annihilated all of our workers.\n\nReport to " ..
                "the Mistress of the Mines. They await you at the mouth of the mines, southwest of here.",
        },
        [11076] = {
            description = "Much of our hard work lies scattered about in these mines. Carts full of cargo " ..
                "are littered across every inch of this mine! We just can't get to any of it with the " ..
                "current infestation.\n\nThat's where you come in, <name>. Your daily duty here at this " ..
                "mine is to collect the cargo left behind by the miners and deep mine workers.\n\nGather " ..
                "the nethermine cargo and return it to me or my sister.",
            rewardMoney = 88000,
        },
        [11077] = {
            description = "That dragon waking up riled up a host of other nasty creatures in these mines. " ..
                "Two types are proving to be a thorn in the side of the Dragonmaw: Nethermine flayers and " ..
                "Nethermine ravagers. You must help us by killing them off. All I ask is your involvement " ..
                "once per day.\n\nGet in there and kill as many as you can!",
            rewardMoney = 44000,
        },
        [11078] = {
            description = "As ye've flown around, ye must have noticed the dragons above. I trust ye " ..
                "haven't fallen victim ta their rage. Help us put an end ta it, <name>!\n\nRivendark and " ..
                "Obsidia lord over this terrace, while Insidion and Furywing rule the skies over yon " ..
                "terrace ta the northeast. Each has a perch on their respective domains. I be wondering " ..
                "if ye and yer friends will go ta one, <lad/lass>, break open an egg with 35 apexis " ..
                "shards and attract the dragon down.\n\nBring me some teeth as proof.",
            rewardMoney = 132000,
        },
        [11079] = {
            description = "Gahk think being smart is dumb sometimes. Gahk not want to think. Me want " ..
                "little <race> to smash big demons!\n\nDey have some chiefs, and da chiefs all have whips " ..
                "to hurt da little demons. You bring Gahk a whip!\n\nYou challenge demon chief in forge " ..
                "camps at burning, green, fel crystal prism. Use 35 apexis shards to get dem to come. Dey " ..
                "called Galvanoth, Braxxus, Zarcsin and da Mo'arg Incinerator.",
            rewardMoney = 132000,
        },
        [11080] = {
            description = "Now that you have felt the enlightening vibrations of the apexis relics, it is " ..
                "time for you to further your understanding of their workings. We are very eager to " ..
                "benefit from your observations!\n\nAs you progress in your ability to attune to the " ..
                "relics, you will gain a higher level of knowledge. This recognition will come in the " ..
                "form of an emanation from the relic.\n\nReturn to us when you have attained such an " ..
                "emanation.",
            rewardItems = {{32569, 15}},
            rewardMoney = 34000,
        },
        [11081] = {
            description = "This document outlines a revolt planned by the Murkblood broken. It seems that " ..
                "the dragon was to be used as a diversion to draw attention away from their escape. " ..
                "Looking at all of the corpses littering the mine, it would be safe to assume that their " ..
                "plans failed.\n\nReturn the escape plans to the Mistress of the Mines.",
        },
        [11082] = {
            description = "These miners are far too stupid to concoct any type of escape plan. We must " ..
                "find and punish the source. Venture into the depths of the mine and seek out the " ..
                "Murkblood overseers. If they have not been overcome by the denizens of the mine, they " ..
                "will undoubtedly be hiding.\n\nOnce you locate one, interrogate him until he reveals the " ..
                "true mastermind behind the escape. Return to me with the identity of this traitor and " ..
                "the hand of the overseer.",
            rewardMoney = 44000,
        },
        [11083] = {
            description = "Don't worry about this dragon, <name>. We've got plans for it...\n\nDeeper in " ..
                "this mine is a band of crazed Murkblood. After the dragon broke out, they were cut off " ..
                "from the exit. Somehow, after a mere 2 days of isolation, they've lost all sense of " ..
                "decency.\n\nThey've resorted to cannibalism and the promotion of mayhem. We don't need " ..
                "that kind of madness in this place. Find 'em and kill 'em. All of 'em.",
        },
        [11084] = {
            description = "Well, well, well... still alive I see. That's good, because Mor'ghor has " ..
                "requested your presence in his tower at once. Get a move on!",
            rewardItems = {{32695, 1}},
            rewardMoney = 44000,
        },
        [11085] = {
            description = "Hail, <name>. I thank you for coming to my aid.\n\nThe arakkoa's monstrous " ..
                "birds knocked me from my nether ray while on a scouting mission.\n\nLet's get out of " ..
                "here, while we can.",
            rewardMoney = 34000,
        },
        [11086] = {
            description = "One of your responsibilities as a captain of Dragonmaw is to snuff out Burning " ..
                "Legion activity in Outland. It is your duty to silence those that defy Lord " ..
                "Illidan!\n\nThe demons foolishly attempt to stabilize the portal found on the Twilight " ..
                "Ridge of western Nagrand. They must pay for their treachery, and you will be the orc " ..
                "that collects on their debt.\n\nTravel to the Twilight Ridge and lay waste to its " ..
                "inhabitants. You will be responsible for making at least one attack per day on their " ..
                "fortifications.",
            rewardMoney = 44000,
        },
        [11089] = {
            description = "Reth'hedron now lords over the Twilight Ridge of Nagrand. An eredar of such " ..
                "power being loosed upon this world does not bode well for the Illidari. Alas, we do not " ..
                "have the resources required to slay Reth'hedron. Not with the war the Sha'tar have " ..
                "brought to the Black Temple. No... I have a better plan.\n\nYou will subdue Reth'hedron, " ..
                "banishing him back through the Twilight Portal. For this a soul cannon must be " ..
                "fashioned.\n\nReturn to me with the materials on this list.",
        },
        [11090] = {
            description = "<Balthas holds up an alien looking device.>\n\nThis is a soul cannon. Its " ..
                "effects are devastating when attuned. This one is attuned to my blood. The same blood " ..
                "flowing through the veins of Reth'hedron - my brother. Aye, his misplaced allegiance " ..
                "will be the end of him.\n\nTake the cannon and fly to the Twilight Ridge in western " ..
                "Nagrand. Locate Reth'hedron and fire! You must stay on your mount and within range for " ..
                "the effects to take hold. Stand your ground against him and he will have no choice but " ..
                "to flee!",
            rewardChoices = {{32869, 1}, {32870, 1}, {32871, 1}, {32872, 1}},
            rewardMoney = 44000,
        },
        [11091] = {
            description = "You honor us with your efforts on our behalf. And now there is someone that we " ..
                "would like for you to meet.\n\nJho'nass is our most trusted quartermaster. He maintains " ..
                "a stock of goods that we provide for sale to only the most dedicated of friends to " ..
                "Ogri'la.\n\nYou are one such friend, <name>.\n\nWhen you find the time, go and speak " ..
                "with him. As we understand it, he has prepared a little something for you as a token of " ..
                "our appreciation.",
            rewardItems = {{32835, 1}},
            rewardMoney = 4400,
        },
        [11092] = {
            description = "Captain <name>!\n\n<Taskmaster Varkule salutes you.>\n\nOverlord Mor'ghor has " ..
                "asked to see you in his chambers at once!",
            rewardItems = {{32864, 1}},
        },
        [11093] = {
            description = "Nether rays are surprisingly loyal and obedient once properly trained. " ..
                "Unfortunately the war on Skettis is taking a toll on them.\n\nWe have dozens of sorties " ..
                "a day - the poor fellows rarely get a break. And with recent shortages on feed, if those " ..
                "blasted birdmen don't kill them on a mission then starvation will.\n\nIf you can lend a " ..
                "hand, take one of our rays to the woods in the south. They don't mind warp chaser meat " ..
                "as long as it's a fresh kill.",
            rewardChoices = {{22831, 2}, {28103, 2}},
            rewardMoney = 44000,
        },
        [11094] = {
            description = "Commander <name>, stand at attention! You are to take a battalion of " ..
                "Skybreakers and sack the Scryers' outpost located at the foot of the Netherwing Fields. " ..
                "With the Sanctum of the Stars destroyed, our lines of communication to our posts at " ..
                "Eclipse Point and Illidari Point will once more be open.\n\nGo now! Use this flare gun " ..
                "to signal the Skybreakers for the attack!",
        },
        [11095] = {
            description = "The Dragonmaw only dare attack us when our guard is down. They would face " ..
                "certain defeat if they were to attack us while we were prepared.\n\nI want you to let " ..
                "them come, <name>.\n\n<Thelis nods.>\n\nYes... a trap. Take this flare that their " ..
                "overlord gave you and deliver it to Commander Hobb. He is standing guard right outside " ..
                "this building.",
        },
        [11096] = {
            description = "So you want to join the Skyguard? Well, I know you can fly... but can you " ..
                "fight?\n\nThe Skyguard is sworn to protect Shattrath from the dangers that loom above " ..
                "us, both near and far. The Gordunni ogres who dwell in the Barrier Hills to the north " ..
                "are an immediate threat to us.\n\nReaching the ogres has been problematic for " ..
                "Shattrath's ground units. That's where we come in. See what you can do to help contain " ..
                "them.",
        },
        [11097] = {
            description = "Take these Scryer medals. Mor'ghor will need proof of \"victory\" once this is " ..
                "over. He will recognize them as coming from the corpses of fallen Scryer " ..
                "soldiers.\n\nNow all that remains is to use the signal flare to alert the Dragonmaw " ..
                "raiders. We will crush them when you are ready. Just give me the word.",
            rewardMoney = 88000,
        },
        [11098] = {
            description = "The Barrier Hills are only one of the fronts where we've been deployed. A less " ..
                "immediate but far more dangerous threat looms from beyond the Skethyl Mountains, from " ..
                "within the arakkoa city of Skettis.\n\nA few months ago our scouts detected a huge " ..
                "increase in arakkoa activity there. Several attacks against Shattrath followed. We've " ..
                "stationed forces outside of their city since.\n\nTake these explosives to Sergeant Doryn " ..
                "at Blackwind Landing, just outside Skettis. Tell him you're a new recruit.",
        },
        [11099] = {
            description = "Commander <name>, stand at attention! You are to take a battalion of " ..
                "Skybreakers and sack the Aldor outpost located northwest of our beloved Black Temple. " ..
                "With the Altar of Sha'tar destroyed, our lines of communication to our posts at Coilskar " ..
                "will once more be open.\n\nGo now! Use this flare gun to signal the Skybreakers for the " ..
                "attack!",
        },
        [11100] = {
            description = "The Dragonmaw only dare attack us when our guard is down. They would face " ..
                "certain defeat if they were to attack us while we were prepared.\n\nI want you to let " ..
                "them come, <name>.\n\n<Ceyla nods.>\n\nYes... a trap. Take this flare that their " ..
                "overlord gave you and deliver it to Commander Arcus. He is standing guard right outside " ..
                "this building.",
        },
        [11101] = {
            description = "Take these Aldor medals. Mor'ghor will need proof of \"victory\" once this is " ..
                "over. He will recognize them as coming from the corpses of fallen Aldor soldiers.\n\nNow " ..
                "all that remains is to use the signal flare to alert the Dragonmaw raiders. We will " ..
                "crush them when you are ready. Just give me the word.",
            rewardMoney = 88000,
        },
        [11102] = {
            description = "You can fly around as a crow... so what! Ever annihilate something on the " ..
                "ground while you were flying? Want to?\n\nForge Camp: Wrath and Forge Camp: Terror, to " ..
                "the north and south, are a major pain in my backside, as well as being a threat to " ..
                "peaceful Ogri'la. With all of those fel cannons shooting down the Skyguard left and " ..
                "right, we can't get through there to take care of business.\n\nWant to prove yourself? " ..
                "Take these bombs and knock out their ammo stacks. Just don't let them shoot you down, " ..
                "too!",
            rewardMoney = 44000,
        },
        [11103] = {rewardChoices = {{29301, 1}, {29297, 1}, {29309, 1}}},
        [11104] = {rewardChoices = {{29301, 1}, {29297, 1}, {29305, 1}}},
        [11105] = {rewardChoices = {{29305, 1}, {29297, 1}, {29309, 1}}},
        [11106] = {rewardChoices = {{29301, 1}, {29305, 1}, {29309, 1}}},
        [11107] = {
            description = "I am unworthy to even carry a message directed at you, sir. Please forgive me " ..
                "for this indulgence. Overlord Mor'ghor has requested your presence in his chambers at " ..
                "once!",
        },
        [11108] = {description = "Come, highlord <name>. Illidan himself awaits us!", rewardMoney = 132000},
        [11109] = {rewardItems = {{32859, 1}}},
        [11110] = {rewardItems = {{32860, 1}}},
        [11111] = {rewardItems = {{32857, 1}}},
        [11112] = {rewardItems = {{32858, 1}}},
        [11113] = {rewardItems = {{32862, 1}}},
        [11114] = {rewardItems = {{32861, 1}}},
        [11119] = {
            description = "Heya, <boyo/girly>! Up fer some fun are ye?\n\nEvery couple o' hours, me " ..
                "aether-techs launch an assault on Bash'ir Landing, far ta the northeast in the Blade's " ..
                "Edge Mountains. They say that they're there 'studying' the Bash'ir crystalforge, but " ..
                "it's an assault; there be no two ways about it. We use the crystalforge to resupply, and " ..
                "there's always extra to be sold.\n\nGo on down ta the landin' pad and speak with the " ..
                "aether-tech apprentice. He'll tell ye when the next mission is ta launch.",
            rewardMoney = 4400,
        },
        [11129] = {
            description = "Help, <name>! My prized puppy, Kyle, has run away! I just know he's running " ..
                "around Bloodhoof Village, lost and hungry.\n\nWill you find him and feed him? Once he " ..
                "eats he will settle down and come home.\n\nTo feed him you will need to find food. His " ..
                "favorite meal is tender strider meat. Just venture east and you should find plenty of " ..
                "striders. Hunt one down and take its succulent meat to Kyle. When you see Kyle in town, " ..
                "put the meat down and he is sure to come to you.",
            rewardMoney = 175,
        },
        [11153] = {
            description = "All of our ships are sunk! We need your help to break the pirate blockade " ..
                "below in the Shattered Straits!\n\nTake these cluster bombs and hitch a ride on the " ..
                "zeppelin that Harrowmeiser has 'loaned' to us. He'll fly you over the decks of those " ..
                "pirate scoundrels, and you make sure to give it to them good!\n\nIf you can't bomb them " ..
                "to smithereens, I'm afraid we'll never be able to break the blockade.",
            rewardMoney = 47000,
        },
        [11154] = {
            description = "You, yes you... I need your help!\n\nPetrov sent me up here to get bat guano " ..
                "for the cluster bombs he's making back at the keep. He sent me to my doom!\n\nThe " ..
                "darkclaw bats hang out in the Rivenwood to the north, but I'm not taking a step off of " ..
                "this platform unless it's to go home!\n\nBut you... you could get it for me! Yes? Pretty " ..
                "please?!!!\n\nHere, take these firecrackers. My thinking is that if you drop 'em " ..
                "underneath the bats, the guano will be scared right out of them!",
            rewardChoices = {{35896, 1}, {35897, 1}, {35898, 1}, {35899, 1}},
            rewardMoney = 47000,
        },
        [11155] = {
            description = "With all of the strange disappearances of our livestock, we better resupply in " ..
                "a hurry, or the beasties around these parts will be the least of our worries!\n\nSeeing " ..
                "as I'm in charge of feeding this lot, I'm going to need you to head east and get me some " ..
                "meat. More to the point, I'm looking to cook us up some tender shoveltusk meat.\n\nJust " ..
                "beware the stags... they're mean!",
            rewardItems = {{34125, 20}},
            rewardMoney = 47000,
        },
        [11157] = {
            description = "<name>, I don't trust anyone but you to take care of this. I need the " ..
                "proto-drake eggs and proto-whelps in the burning forest to the southeast " ..
                "destroyed!\n\nSince we arrived here, the Ember Clutch has been ablaze; there must be " ..
                "some sort of perverse magic at work. And lately it seems to be growing. My men tell me " ..
                "that if we don't do something quickly, we'll be surrounded on all sides by the fire " ..
                "within a few weeks' time!\n\nGet down there and eliminate the threat by destroying those " ..
                "eggs and the proto-whelps.",
            rewardMoney = 47000,
        },
        [11167] = {
            description = "Not long after Arthas condemned us to this wretched existence, we in the Royal " ..
                "Apothecary Society endeavored to create a plague of our own. A plague that would devour " ..
                "all flesh: living, dead or undead.\n\nWe've succeeded in creating this plague and we're " ..
                "here to hand deliver it to the Scourge's doorstep.\n\nThe Alliance intercepted the ship " ..
                "carrying the latest strain engineered in our Undercity laboratories. Head to the " ..
                "wreckage southeast of here and salvage whatever containers you can.",
            rewardChoices = {{35832, 1}, {35833, 1}, {35834, 1}, {35835, 1}},
            rewardMoney = 47000,
        },
        [11168] = {
            description = "I've a feeling the long trip across the sea is affecting the effectiveness of " ..
                "our plague. What is needed is a potent toxin to boost the potency of the strain.\n\nThe " ..
                "crabs near this beach are a distant relative of the much smaller brown-shelled " ..
                "tidecrawler. The smaller tropical variety produces a paralytic toxin strong enough to " ..
                "knock out an ogre.\n\nAs we all know bigger is better! The much larger glands on the " ..
                "local variety should prove more potent. Bring me a few!",
            rewardMoney = 24000,
        },
        [11170] = {
            description = "We've just received word of reinforcements coming to the aid of the Alliance " ..
                "forces. Their timing couldn't be better!\n\nWe're in sore need of test subjects and " ..
                "these North Fleet reservists will do nicely!\n\nTake these plague vials with you and " ..
                "speak to Camille, the Bat Handler. Tell her you need to commandeer a riding bat for a " ..
                "special assignment for us.\n\nOnce you're at sea, drop the vials on the reinforcement " ..
                "fleet. I can't wait to see the results!",
            rewardChoices = {{35841, 1}, {35842, 1}, {35843, 1}, {35839, 1}},
            rewardMoney = 47000,
        },
        [11175] = {
            description = "Tell me, is it true? Did the explorers that went into Whisper Gulch go " ..
                "mad?\n\nMy daughter is the overseer of the Explorers' League that went north to some " ..
                "place called Steel Gate. With the horrible events that have befallen us, I fear for her " ..
                "safety.\n\nPlease, <class>, I am too old to make the journey. Her name is Irena. Will " ..
                "you go make certain that she is alright?",
        },
        [11176] = {
            description = "Our work out here is really just beginning. But now that we've brought these " ..
                "flying machines in from Westguard Keep, it should really pick up.\n\nThe problem is that " ..
                "we're lacking enough qualified pilots. And with things getting worse in the Rivenwood to " ..
                "the north, I'd like to get things wrapped up here quickly and then head back home.\n\nIf " ..
                "you can lend a hand, go have a chat with one of my chief archaeologists. You'll find " ..
                "them next to the flying machines on the north and south sides of the site.",
        },
        [11182] = {
            description = "All things in nature seek a balance. It is only through the interference of " ..
                "those not in tune with that harmony that the balance is shifted.\n\nYou waste your " ..
                "efforts when you kill the whelps and drakes. The real culprits behind the expansion of " ..
                "these magically burning woods are the newly awakened vrykul and their master, Skeld " ..
                "Drakeson.\n\nIf it's blood on your hands that you seek, start with them. You will find " ..
                "their lair on the south side of the Ember Clutch.",
            rewardChoices = {{35921, 1}, {35923, 1}, {35924, 1}, {35922, 1}},
        },
        [11187] = {
            description = "THIS IS OUTRAGEOUS! Those proto-drakes are attacking the keep!\n\nBeasts such " ..
                "as that should have been scared off when you took care of their clutches and " ..
                "whelps.\n\nYou did take care of them, right?\n\n<name>, this calls for more direct " ..
                "action. Speak with my advisor, Mage-Lieutenant Malister. He'll provide you with the " ..
                "means to get at those infernal creatures.",
        },
        [11188] = {
            description = "Now that we've riled up these Ember Clutch proto-drakes, they may be inclined " ..
                "to continue their attacks upon the keep. This will not do.\n\nI hate to compound one " ..
                "wrong with another, but in this case it would appear that we will have to destroy the " ..
                "creatures. A regrettable course of action, but one that we need to undertake " ..
                "regardless.\n\nTake my wand. I've been experimenting with increasing its range, but it " ..
                "doesn't pack much of a punch. However, what it will do is get a proto-drake 's attention.",
            rewardChoices = {{35871, 1}, {35872, 1}, {35873, 1}, {35875, 1}},
            rewardMoney = 47000,
        },
        [11190] = {
            description = "<Lad/Lass>, who's the genius that made our cannons a non-standard size? Now we " ..
                "have ta make special cannonballs ta shoot out o' the infernal contraptions!\n\nI would " ..
                "look kindly on ye if ye would go out and find the balls we've already shot. No doubt " ..
                "with the way these louts shoot they be all o'er the place ta the south and east.\n\n<The " ..
                "cannoneer spaces his hands apart to give you an idea of how big the cannonballs " ..
                "are.>\n\nThat would be faster than us making 'em from scratch fer a certainty.",
            rewardMoney = 47000,
        },
        [11199] = {
            description = "<name>, now that those damnable proto-creatures have been dealt with, I've " ..
                "another task for you.\n\nOne of my scouts has reported back some suspicious activity by " ..
                "the Forsaken to the south. It looks like they're up to no good at the vrykul village " ..
                "known as Halgrind.\n\nI want you to personally take over the investigation down there. " ..
                "Speak with Scout Knowles to find out what he's uncovered and proceed from there.\n\nHis " ..
                "last reported position is at the Ember Spear Tower, just to the west of Halgrind.",
        },
        [11202] = {
            description = "The Forsaken are up to no good and from what I can tell, those plague tanks of " ..
                "sludge are a big part of it.\n\nIf I may suggest, <sir/ma'am>, we should probably " ..
                "destroy them before they can get any more use out of the things. I took the liberty of " ..
                "preparing a bundle of torches from the Ember Clutch. These things have been burning for " ..
                "days!\n\nHere, I'm sure you can put them to better use than I in destroying those tanks.",
            rewardChoices = {{35888, 1}, {35889, 1}, {35890, 1}, {35891, 1}},
            rewardMoney = 47000,
        },
        [11208] = {
            description = "Drazzit will expect to hear something from me soon, but I don't think the site " ..
                "is secure enough for me to leave. If you have time, would you be willing to take some of " ..
                "the salvaged cargo down to him at Mudsprocket?\n\nIf you haven't been there yet, it's a " ..
                "small settlement to the southwest of here, beyond the Stonemaul Ruins. You can take the " ..
                "road there from Tabetha's Farm, too. When you get to Mudsprocket, the guy you're looking " ..
                "for is Drazzit Dripvalve.",
        },
        [11211] = {
            description = "When that goblin... what's her name... Boxie, Foxy... Moxie, that's it! " ..
                "Anyway, when she came through here on her way to the zeppelin wreck, she said the town " ..
                "of Mudsprocket was having some problems.\n\nThat crashed zeppelin was bringing them " ..
                "fresh supplies. If you follow the road south from here, past the Stonemaul Ruins, you'll " ..
                "eventually come to Mudsprocket.\n\nWhy don't you check in with Drazzit Dripvalve down " ..
                "there and see if there's anything you can do to help?",
        },
        [11213] = {
            description = "A human woman named Tabetha lives on a small farm near the middle of the " ..
                "marsh. Ordinarily, I wouldn't associate with a human, but her help has proven useful at " ..
                "times.\n\nUnfortunately, she's been out of touch for quite some time now and I'm looking " ..
                "for someone to travel down to her farm to see if everything's all right.\n\nIf you " ..
                "follow the road south out of the village, then into the swamp's interior, you'll find " ..
                "her farm near the middle of the Quagmire.",
        },
        [11215] = {
            description = "The Steamwheedle Cartel's new outpost in the southern part of the marsh isn't " ..
                "faring so well. The zeppelin carrying supplies to Mudsprocket crashed, leaving them " ..
                "without vital tools, food, and medical supplies.\n\nFollow the road down south and into " ..
                "the marsh's interior. You'll pass by Tabetha's Farm and the Stonemaul Ruins before the " ..
                "road brings you to Mudsprocket. Offer any help you can provide to the town's leadership.",
        },
        [11216] = {
            description = "I was sent here by my mentor to look for assistance, but unfortunately I'm not " ..
                "allowed outside of Lower City and the individuals that frequent this establishment tend " ..
                "to be less than helpful.\n\nYou do seem different, more like the adventurous type. If " ..
                "you're interested in aiding our cause, speak to Archmage Alturus outside of Medivh's old " ..
                "dwelling, Karazhan.\n\nIn the meantime, I'm going to see about gaining access to the " ..
                "rest of the city. One of our old associates is rumored to be here.",
        },
        [11218] = {
            description = "<name>, the captain's tasked me with a mission. I'd like you to help.\n\nA " ..
                "bunch of my fellow Explorers' League people went nuts digging up stuff in the Whisper " ..
                "Gulch just to the north. They're attacking anyone trying to get in!\n\nThe captain is " ..
                "only concerned with the ore for the keep. Lucky for us, I have just the thing to do the " ..
                "trick.\n\nGet in there, blow up the ore, and bring it back along with any gems you find. " ..
                "Running this place isn't cheap you know!\n\nI gotta warn you though, that ore is strange!",
            rewardMoney = 47000,
        },
        [11221] = {
            description = "Our mission in Northrend is to destroy Arthas. The Alliance are but an " ..
                "obstacle that we'll crush wherever we find them.\n\nWe've managed to destroy their " ..
                "easternmost fleet; but the survivors have barricaded themselves on the Derelict Strand, " ..
                "south of here.\n\nOur forces should've overwhelmed their make-shift defenses long ago, " ..
                "but we underestimated their will to live. Seek my officers in the field, Dark Ranger " ..
                "Lyana and Deathstalker Razael and get them to report on the situation.",
        },
        [11224] = {
            description = "I've heard rumors of bad happenings in the Whisper Gulch to the north. Most of " ..
                "the Explorers' League went down into that place, and some say they went mad with what " ..
                "they discovered.\n\nThat doesn't change the fact that they took most of our mules and " ..
                "equipment with them, though. I won't lose those mules!\n\nIf you find yourself in there, " ..
                "and happen across any of my mules, just get up close on them and threaten them with a " ..
                "raised hand. They'll spook and come home for sure.",
            rewardMoney = 47000,
        },
        [11227] = {
            description = "The high executor wants me to use my dogs to sniff out enemy scouts, but I can " ..
                "tell you right now these plaguehounds aren't going anywhere until they're properly " ..
                "fed.\n\nIf our military doesn't understand that these beasts are picky enough to not eat " ..
                "the rubbish they've given me, then they can't expect them to be of any use in the " ..
                "field.\n\nYou seem to have some time on your hands, why don't you take one of these dogs " ..
                "out hunting for crows out west? Their meat isn't very tasty to us, but my boys love it!",
            rewardMoney = 47000,
        },
        [11228] = {
            description = "Fordragon's got another thing coming if he thinks the group of green-gilled " ..
                "scrubs he sent to defend this port can hold out much longer.\n\n< Macalroy raises an " ..
                "eyebrow as he examines your equipment.>\n\nYou, however, might fare a bit better.\n\nThe " ..
                "importance of holding this port cannot be stated enough; and with those monsters flying " ..
                "overhead, the situation around here has gone from bad to worse.\n\nReport to Vice " ..
                "Admiral Keller just northwest of here and let him know that you're all out of bubble gum.",
        },
        [11229] = {
            description = "We have the Windrunner, the Queen's Reprisal and the Oblivion stationed just " ..
                "east of the Derelict Strand. Send orders to the fleet's commander, Captain Harker, that " ..
                "they're to destroy the Alliance's cannons.\n\nSpeak to our bat handler, Camille, and ask " ..
                "for passage to the fleet's location. Be quick, <name>, every minute we spend fighting " ..
                "the Alliance is a minute we could've spent fighting Arthas.",
        },
        [11230] = {
            description = "This should have been a walk in the park. Their forces are hungry, injured and " ..
                "ill equipped. Yet somehow, we walked right into their trap.\n\nWe approached these reefs " ..
                "from the south to gain cover and were immediately boarded by the Alliance dogs.\n\nI'm " ..
                "sorry to say, if you want our cannons to fire at anything, you're going to have to help " ..
                "us take our ships back.",
            rewardChoices = {{35814, 1}, {35815, 1}, {35817, 1}},
            rewardMoney = 47000,
        },
        [11231] = {
            description = "The captain may not care, but from the little we know, the vrykul are " ..
                "conducting heinous rites in some sort of 'awakening' ritual up north in " ..
                "Gjalerbron.\n\nThey're using living sacrifices to fuel their unholy rituals!\n\n<class>, " ..
                "you must put a stop to this! It matters not who or what is in those cages, they must be " ..
                "freed. I'd bet that the vrykul hold the keys.\n\nThe Light knows the last thing we need " ..
                "is more of those strange vrykul walking about, or worse yet, them wakening something " ..
                "even more evil!",
            rewardMoney = 47000,
        },
        [11232] = {
            description = "We should be able to kill our way back to our guns. Unfortunately, visibility " ..
                "is less than desirable so you will have to mark our targets from the ground.\n\nTake " ..
                "these smoke flares with you and use them to mark the locations of the cannons along the " ..
                "northern wall in the Derelict Strand, west of here, where the Alliance are holding " ..
                "out.\n\nLet Lyana know as soon as the way is clear for the ground troops. We can take " ..
                "care of ourselves over here.",
        },
        [11233] = {
            description = "You've proven yourself in the field of battle, <name>. You might very well " ..
                "have changed the tides in our favor.\n\nI've an important assignment for you now. I'm " ..
                "not sure how much longer the weakness we've exposed is going to last, so we must use the " ..
                "element of surprise to our advantage.\n\nI want you to use the confusion created by our " ..
                "attack and go behind enemy lines to assassinate their leaders. In order of rank, they " ..
                "are: Captain Olster, Lieutenant Celeyne and Sergeant Lorric. Good luck, <class>.",
            rewardChoices = {{35807, 1}, {35808, 1}, {35809, 1}, {35810, 1}, {35811, 1}, {35812, 1}},
            rewardMoney = 94000,
        },
        [11234] = {
            description = "Let's send word back to old Anselm then. Victory has come later than expected, " ..
                "but better late than never. Tell him it will take our forces a few hours at most to " ..
                "finish off the stragglers here.\n\nGlory to the Banshee Queen!",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [11235] = {
            description = "And now we have a different problem. My scouts that have lived to return have " ..
                "informed me that the vrykul are up to no good at their main fortress to the " ..
                "north.\n\nThey call the place Gjalerbron, though you'd pronounce the 'Gj' as if it were " ..
                "an 'Sh'. Odd creatures.\n\nBut that's not important; what is, is that you get up there " ..
                "and put an end to the lives of as many of those creatures as you can while trying to " ..
                "figure out what they're up to.\n\nI know that I can count on you, <name>.",
            rewardMoney = 47000,
        },
        [11236] = {
            description = "The Scourge are at Gjalerbron and they have necromancers with them! They must " ..
                "be working to bring the vrykul into Arthas' fold.\n\nI want the leader of these " ..
                "necrolords eliminated!\n\nDo whatever it takes, <name>, but see to it that Necro " ..
                "Overlord Mezhen, and whatever he's attempting to accomplish, is neutralized.\n\nI will " ..
                "not see the vrykul successfully allied with the Scourge!\n\nLook for Mezhen on the " ..
                "platform in the rear right section of Gjalerbron.",
            rewardChoices = {{35877, 1}, {35878, 1}, {35879, 1}, {35938, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 100000,
        },
        [11237] = {
            description = "These plans detail an imminent attack upon Westguard Keep. It would appear " ..
                "that the frost wyrm, Glacion, who circles overhead is to be used for the " ..
                "offensive.\n\nSurely Mage-Lieutenant Malister would be of some assistance in this " ..
                "matter. Deliver the plans to him at the keep to the south.",
            rewardMoney = 50000,
        },
        [11238] = {
            description = "You were right to bring this to me, <name>. You must venture to Gjalerbron and " ..
                "slay that wyrm and its master, Wyrmcaller Vile!\n\nEven now, as we speak here, the frost " ..
                "wyrm may be on its way.\n\nHowever, if I'm reading these plans correctly, blowing the " ..
                "wyrmcaller's horn on his platform, outside in the rear left area of Gjalerbron, will " ..
                "call Glacion back. When the creature lands, destroy it!\n\nAnd <name>, please bring me " ..
                "the horn. We wouldn't want it falling back into the wrong hands.",
            rewardChoices = {{35880, 1}, {35882, 1}, {35883, 1}, {35881, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 100000,
        },
        [11239] = {
            description = "Your service has been exemplary, <name>, but there is something that is " ..
                "troubling me: the Scourge.\n\nThe Light cannot abide their presence, and neither shall " ..
                "we. I hope that it is not asking you too much, but I would have you return north to " ..
                "Gjalerbron and crush the unholy Scourge in that vile lair! Be sure to check for them in " ..
                "the Waking Halls beneath Gjalerbron as well.\n\nPurification is the key to salvation, my " ..
                "child. Make us proud!",
            rewardChoices = {{35884, 1}, {35885, 1}, {35887, 1}, {35886, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 47000,
        },
        [11240] = {
            description = "So, I hate to say it, pal, but while you were out, the captain took a keener " ..
                "interest in that place.\n\nLooks like he wants my old Explorers' League boss in there " ..
                "dead. My guess would be that we're gearing up for an offensive to clear out the rest of " ..
                "them, and the captain wants their head lopped off, as it were.\n\nDo me a favor? Head " ..
                "back into Whisper Gulch and put an end to Squeeg Idolhunter. From what I remember, my " ..
                "guess would be that he's in the cave in the northwest corner.",
            rewardChoices = {{35917, 1}, {35918, 1}, {35919, 1}, {35920, 1}},
            rewardMoney = 47000,
        },
        [11241] = {
            description = "Thanks for bailing me out of this mess, <name>. I was not looking forward to " ..
                "what these Alliance scumbags had in store for me.\n\nLet's get out of here and see if we " ..
                "can get back at them somehow. Is that a campfire over there?",
            rewardChoices = {{35823, 1}, {35824, 1}, {35826, 1}, {35827, 1}, {35829, 1}, {35830, 1}},
            rewardMoney = 94000,
        },
        [11243] = {
            description = "If Valgarde falls, our primary supply line into Northrend will cease to exist. " ..
                "From there it'll only be a matter of time before we're all servants of the Lich King. " ..
                "Now I don't know about you, but I've got a wife and three kids back in Elwynn and I'll " ..
                "be damned if I'll go down without a fight.\n\nThe situation here is critical and we can " ..
                "use all the manpower you're able to muster. Get to the front gate and help the guards " ..
                "defend the city against the invading monsters!",
            rewardMoney = 44000,
        },
        [11244] = {
            description = "We'd been here for a month when those malformed giants appeared out of thin " ..
                "air. We were ill-prepared for any sort of attack and paid dearly for our complacency. An " ..
                "entire archaeology team was lost and several townsfolk were abducted and taken to the " ..
                "ruins. We've been on the defensive ever since.\n\nTo make matters worse, the scouts we " ..
                "sent to rescue our people have been harpooned by the vrykul and left for dead in the " ..
                "forest directly north of Valgarde. Dislodge those harpoons and free our scouts!",
            rewardChoices = {{35807, 1}, {35808, 1}, {35809, 1}, {35810, 1}, {35811, 1}, {35812, 1}},
            rewardMoney = 44000,
        },
        [11245] = {
            description = "<Sir/Ma'am>, as we move through Skorn, we have to bring down those " ..
                "towers!\n\nIf you have a look at them, you'll notice that their tops are lined with " ..
                "casters. Getting too close to them would mean certain doom for us!\n\nHowever, we do " ..
                "have it within our means to call in cannon volleys from Westguard Keep. To do so, we " ..
                "need to get close enough so that you can lob a smoke flare atop of them.\n\nJust don't " ..
                "get too close!",
            rewardMoney = 47000,
        },
        [11246] = {
            description = "We've had reports that these vrykul can rise from the dead; not unlike the " ..
                "Scourge, but a different kind of undeath.\n\nLet's not take any chances.\n\nHere, take " ..
                "my machete. As we move through this place, you'll need to carve up the remains of the " ..
                "vrykul that we take down. I'd do it, but I have a sensitive stomach.\n\n<The sergeant " ..
                "smirks.>\n\nI spent all morning sharpening it, so it should do the job.",
            rewardMoney = 47000,
        },
        [11247] = {
            description = "Captain Adams gave me strict instructions to make sure that a good deal of " ..
                "infrastructure damage was inflicted on this site.\n\nHowever, since you're in charge out " ..
                "here, that's at your discretion, <sir/ma'am>.\n\nMay I suggest that we burn down the two " ..
                "longhouses and the barracks that are in the lower area of Skorn? All we have to do is " ..
                "get inside each and throw this torch.",
            rewardMoney = 47000,
        },
        [11248] = {
            description = "<name>, I must now ask you to undertake an operation so hazardous, so deadly, " ..
                "that only you can see it through.\n\nThe vrykul fortress, Skorn, sits on our eastern " ..
                "border. My scouts inform me that those 'giants' are poised to strike us, and with my " ..
                "forces scattered all over the fjord, I don't have the men to take the place by " ..
                "force.\n\nInstead, you're going to use your cunning. I've sent a sergeant ahead with the " ..
                "details. Show this command insignia at Skorn and he'll reveal himself and follow your " ..
                "orders.",
        },
        [11249] = {
            description = "This huge scroll is made from dragon skin. Unfurling its more-than-ten-foot " ..
                "length, you can see that the images painted upon its scaly surface depict a mysterious " ..
                "vrykul ritual.\n\nA vrykul thane, surrounded by angelic-looking beings, ascends into the " ..
                "heavens. A mysterious, darkened figure looms large in the picture's background.\n\nA " ..
                "tingling in your gut tells you that the thane of Skorn is about to do this. You must " ..
                "stop it! A large pyre sits at the top of Skorn in front of the thane's lodge.",
            rewardChoices = {{35900, 1}, {35901, 1}, {35902, 1}, {35903, 1}},
            rewardMoney = 100000,
        },
        [11250] = {
            description = "We -- well, you -- have done everything that we were sent here to accomplish " ..
                "<sir/ma'am>. I must say that it's been a pleasure taking orders from such a fine, young " ..
                "<race>.\n\nThe captain is sure to want to hear of your success, but if you decide to " ..
                "stay out here for whatever reason, I am at your disposal.",
            rewardChoices = {{35905, 1}, {35909, 1}, {35910, 1}, {35904, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 100000,
        },
        [11251] = {
            description = "It's come at great cost, but we've completed our inspection of the " ..
                "site.\n\nThe news isn't good. Nearly everyone has been slain or captured. Only a few " ..
                "veteran guards remain unaccounted for.\n\nThe scouts have done all we can here. You must " ..
                "pick up where we've left off.\n\nSounds of a skirmish are coming from up the hill to the " ..
                "northeast. Have a look, <class>. We can only hope there are some who have survived, and " ..
                "that they may have some intel we can use against this enemy.",
            rewardMoney = 4800,
        },
        [11253] = {
            description = "Now that this rascal's belly's full, maybe he will be more willing to " ..
                "cooperate. Here's his leash, just come get him from his cage whenever you're ready to " ..
                "take him.\n\nI don't know what Anselm expects you to find, but look for clues wherever " ..
                "it is that the dog takes you.",
        },
        [11254] = {
            description = "Upon closer inspection, the scroll appears to be a heavily-illustrated map of " ..
                "the fjord. The location of various villages are depicted in what seem to be tribal " ..
                "symbols.\n\nThe location of Vengeance Landing is marked with a disproportionately large " ..
                "skull.\n\nThis map will almost certainly be of military value to High Executor Anselm.",
        },
        [11255] = {
            description = "This battle is far from over, <name>. If our people are still alive inside " ..
                "that village, someone has to go and get 'em.\n\n< Vice Admiral Keller nods at " ..
                "you.>\n\nHead north and enter Wyrmskull Village. Once there, look for our people. If " ..
                "they are imprisoned you'll need to find a way to break them out.\n\nMaybe they'll have " ..
                "some more information about what it is that we're actually fighting.",
            rewardMoney = 44000,
        },
        [11256] = {
            description = "<name>, the vrykul fortress, Skorn, sits to the south. Its strange giants have " ..
                "recently awakened and have begun to spread, attacking us wherever they can.\n\nMy scouts " ..
                "inform me that they are poised to strike at us here, but I do not have the strength to " ..
                "repel such a force. Instead, we will prepare to leave north to less dangerous " ..
                "lands.\n\nI ask that you use your cunning to buy us time. I've sent a brave ahead with " ..
                "the details. Show this emblem at Skorn and he'll reveal himself and do all he can to aid " ..
                "you.",
        },
        [11257] = {
            description = "Our elders say that these vrykul may be able to rise from the dead; not unlike " ..
                "the walking dead you call the Scourge, but a different kind of undeath.\n\nWe should not " ..
                "take any chances.\n\nHere, take my machete. As we move through this place, carve up the " ..
                "remains of the vrykul that we slay.\n\nI spent the morning sharpening it, so it should " ..
                "cleave even through their thick bones.",
            rewardMoney = 47000,
        },
        [11258] = {
            description = "Chieftain Ashtotem ordered me to destroy many buildings here.\n\nHowever, you " ..
                "are in charge, so it falls to your hands, <name>.\n\nI suggest that we burn down the two " ..
                "longhouses and the barracks that are in the lower area of Skorn. All we have to do is " ..
                "get inside each and set them ablaze with this torch.",
            rewardMoney = 47000,
        },
        [11259] = {
            description = "As we move through Skorn, we must destroy the towers.\n\nIf you have a look at " ..
                "them, you'll notice that their tops are lined with casters. Getting too close to them " ..
                "would mean certain doom.\n\nHowever, we can call in wind rider air strikes from Camp " ..
                "Winterhoof. To do so, we need to get close enough so that you can lob a smoke flare atop " ..
                "of them.\n\nJust don't get too close.",
            rewardMoney = 47000,
        },
        [11260] = {
            description = "This huge scroll is made from dragon skin. Unfurling its more-than-ten-foot " ..
                "length, you can see that the images painted upon its scaly surface depict a mysterious " ..
                "vrykul ritual.\n\nA vrykul thane, surrounded by angelic-looking beings, ascends into the " ..
                "heavens. A mysterious, darkened figure looms large in the picture's background.\n\nA " ..
                "tingling in your gut tells you that the thane of Skorn is about to do this. You must " ..
                "stop it! A large pyre sits at the top of Skorn in front of the thane's lodge.",
            rewardChoices = {{35900, 1}, {35901, 1}, {35902, 1}, {35903, 1}},
            rewardMoney = 100000,
        },
        [11261] = {
            description = "You have done everything that we were sent here to do, <class>. I must admit " ..
                "that you fight well. Your people are not as strange as I first thought.\n\nChieftain " ..
                "Ashtotem is certain to want to hear of your success, but if you decide to stay out here " ..
                "for whatever reason, I will continue to fight at your side.",
            rewardChoices = {{35905, 1}, {35909, 1}, {35910, 1}, {35904, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 100000,
        },
        [11263] = {
            description = "My longrunners that have lived to return have informed me that the vrykul have " ..
                "awakened at their main fortress to the west.\n\nIt is a forbidden place known as " ..
                "Gjalerbron. The longrunners tell me that the vrykul are performing strange " ..
                "rituals.\n\nWe cannot allow this to continue.\n\nAre you willing to continue to assist " ..
                "us? Will you kill the vrykul at Gjalerbron before they finish whatever they are doing " ..
                "and attack us here?",
            rewardMoney = 47000,
        },
        [11264] = {
            description = "The dead ones are at Gjalerbron and they have necromancers with them?\n\nWe " ..
                "must eliminate the leader of these necrolords.\n\nDo whatever it takes, <name>, but see " ..
                "to it that Necro Overlord Mezhen, and whatever he's attempting to accomplish, is " ..
                "neutralized.\n\nWe cannot afford to see the vrykul successful in whatever they are doing " ..
                "with these undead creatures!\n\nLook for Mezhen on the platform in the rear right " ..
                "section of Gjalerbron.",
            rewardChoices = {{35877, 1}, {35878, 1}, {35879, 1}, {35938, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 100000,
        },
        [11265] = {
            description = "From the little we know, the vrykul are conducting unnatural rites in an " ..
                "'awakening' ritual to the west in Gjalerbron.\n\nThey're using living sacrifices to fuel " ..
                "their rituals.\n\n<name>, you must stop this. It matters not who or what is in those " ..
                "cages, they must be freed. I would guess that the vrykul hold the keys.\n\nThe last " ..
                "thing we need is more of those strange vrykul threatening us, or worse, them wakening " ..
                "something even more evil....",
            rewardMoney = 47000,
        },
        [11266] = {
            description = "These plans detail an imminent attack upon Camp Winterhoof. It would appear " ..
                "that the frost wyrm, Glacion, who circles overhead, is to be used for the " ..
                "offensive.\n\nSurely Celea Frozenmane would be of some assistance in this matter. " ..
                "Deliver the plans to her at the camp to the east.",
            rewardMoney = 50000,
        },
        [11267] = {
            description = "Your instincts were right to bring this to me, but my wind riders cannot fight " ..
                "a dragon. You must venture west to Gjalerbron and slay the frost wyrm and its master, " ..
                "Wyrmcaller Vile!\n\nEven now it may be on its way!\n\nIf I'm reading these plans " ..
                "correctly, blowing the wyrmcaller's horn on his platform, outside in the rear left area " ..
                "of Gjalerbron, will call Glacion back. When the creature lands, destroy it!\n\nAnd " ..
                "<name>, bring me the horn. We wouldn't want it falling back into the wrong hands!",
            rewardChoices = {{35880, 1}, {35882, 1}, {35883, 1}, {35881, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 100000,
        },
        [11268] = {
            description = "Your assistance to us has been tremendous, <name>, but there is something that " ..
                "is troubling me: these so-called Scourge.\n\nThe spirits of the land and air, the waters " ..
                "and the fire below the world, would not abide their presence, but seem to do nothing " ..
                "about them. We will see to it that they are dealt with!\n\nPerhaps it is asking too " ..
                "much, but I would have you return west to Gjalerbron and destroy the unnatural Scourge " ..
                "in that vile lair. Be sure to check in the Waking Halls below Gjalerbron as well!",
            rewardChoices = {{35884, 1}, {35885, 1}, {35887, 1}, {35886, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 47000,
        },
        [11269] = {
            description = "The vanguard of the Alliance force will be arriving within days. The soldiers " ..
                "will be expecting their winter gear to be prepared, but I've still got more cloaks to " ..
                "make.\n\nI've been using spotted hippogryph down for the cloaks' linings, but my stock " ..
                "won't last!\n\nYou've got to help me, <name>. Captain Adams will have my hide if those " ..
                "cloaks aren't ready in time! Bring me all the down you can find out there. It's dropped " ..
                "to the ground by molting hippogryphs flying over the wilderness around the fort.",
            rewardChoices = {{35926, 1}, {35927, 1}, {35928, 1}, {35925, 1}},
            rewardMoney = 47000,
        },
        [11270] = {
            description = "We're slowly finishing off the remnants of Stormwind's North Fleet stationed " ..
                "on this coast. The bodies to the west are a testament to how brutal this confrontation " ..
                "has been.\n\nThis does not happen to bother my refined aesthetics, but it does present a " ..
                "danger to our lives.\n\nIn the lands of the Lich King, the dead are a weapon that can " ..
                "rise against us at any point in time. Take this torch - you're going to make sure that " ..
                "doesn't happen.",
        },
        [11271] = {
            description = "The down of the spotted hippogryph is prized by my people and used for " ..
                "everything from fletching to ceremonial clothing. We're making preparations to leave the " ..
                "post, so this is the last chance I'll get to gather it this season.\n\nWith your help, " ..
                "I'll have enough to make sure everyone has the equipment they need for the long trek " ..
                "into the hills. Conditions worsen very quickly up there and a storm can blow in without " ..
                "warning.\n\nThe down can be found all over the ground in the area surrounding the post.",
            rewardChoices = {{35926, 1}, {35927, 1}, {35928, 1}, {35925, 1}},
            rewardMoney = 47000,
        },
        [11273] = {
            description = "We were on the brink of an archaeological breakthrough when those monsters " ..
                "attacked! Sadly, I was the only one to make it back to Valgarde. Now I don't know if my " ..
                "crew is dead or alive, but the artifacts we uncovered on that dig must be found!\n\nIf " ..
                "you're heading into Wyrmskull Village, will you keep an eye out for my team? If there's " ..
                "any hope of recovering that information, we must pursue it!\n\nSearch for Pulroy first. " ..
                "He was the last one I saw before I made my escape.",
        },
        [11274] = {
            description = "To whomever finds this journal:\n\nThese bloodthirsty monsters have taken up " ..
                "residence in the ruins of Wyrmskull. What they want or why they're here is a mystery. In " ..
                "any case, the artifacts are not safe with those beast-men around.\n\nZedd and I made a " ..
                "new discovery while hiding out: a cipher to decode the tablets! Unfortunately Zedd and I " ..
                "were separated late last night. He had the cipher. Tablets were with Glorenfeld and " ..
                "Daegarn. Location unknown...\n\nFind Zedd.\n\n-Pulroy",
        },
        [11275] = {
            description = "My people have been hunting the giant yeti of these hills for generations and " ..
                "I will be participating for the first time this year. It will probably be the last " ..
                "before we leave the post forever.\n\nTo prepare for the hunt, I must fashion a loud horn " ..
                "from the horns of the dire rams that roam the snowy areas near our camp. The elders tell " ..
                "me the sound mimics the mating call of the female yeti, but I have my doubts.\n\nBring " ..
                "me the best dire ram horns you can find, <name>, and I'll select one from among them.",
            rewardMoney = 47000,
        },
        [11276] = {
            description = "There's no sign of the cipher on Zedd. After carefully searching the area you " ..
                "discover some writing in the dirt:\n\n\"Glor and Dae inside catacombs. Have cipher and " ..
                "tablets.\"\n\nPerhaps you should head into the catacombs located just north of here and " ..
                "search for Glorenfeld and Daegarn. The bridge crossing the worg pit will lead you right " ..
                "to the tunnel leading down into the catacombs.",
        },
        [11277] = {
            description = "They're keepin' Daegarn locked up in a cage at the large fightin' ring nearby. " ..
                "From what I've gathered, the Dragonflayers bring out their prisoners to battle against " ..
                "their most powerful gladiators. They dump the losers in the basement where Scourge " ..
                "necromancers turn 'em into ghoulies! It's horrifying!\n\nBut first things first! The " ..
                "tablets are strewn about all across this dungeon. Let's get those recovered before you " ..
                "go off tryin' to be a hero.",
        },
        [11278] = {
            description = "'Tis a shame we lost two of our best dwarves while uncovering these relics. " ..
                "They sacrificed their lives to keep this information safe.\n\n< Glorenfeld wraps the " ..
                "cipher and tablets in a tattered cloth.>\n\nTake these back to Valgarde. McSorf will " ..
                "know what to do with the find.\n\nAs for me? I'll be alright on my own. I've gotten this " ..
                "far in one piece!",
            rewardChoices = {{35818, 1}, {35820, 1}, {35821, 1}, {35822, 1}},
            rewardMoney = 12000,
        },
        [11279] = {
            description = "This new plague that we're working on is wonderful and I think we should " ..
                "expand its testing.\n\nHow about testing it on proto-whelps?!\n\nJust think of the " ..
                "possibilities. The ability to infect not only humanoids, but extend our reach to any " ..
                "creature!\n\nHere, I've hoarded an extra plague canister for the right time and place, " ..
                "and you look like the right person.\n\nSpray the eggs at Ember Clutch to the northwest, " ..
                "then get specimens from the plagued proto-whelps that hatch.",
            rewardMoney = 47000,
        },
        [11280] = {
            description = "Wait, that gives me an idea! What if it didn't kill the whelps because it was " ..
                "sprayed on the outside of their eggs?\n\n<name>, we have to get the plague inside of " ..
                "them!\n\nI know! I've got some plagued meat here. Take it to the Ember Clutch and get " ..
                "them to eat it!\n\nBut no, we're thinking too small. Let's get one of the proto-drakes " ..
                "flying overhead to come down and eat it.\n\nYes!\n\nStay close to the meat and observe " ..
                "what happens. Yes, it might attack you, but such is the price of progress.",
            rewardChoices = {{35871, 1}, {35872, 1}, {35873, 1}, {35875, 1}},
            rewardMoney = 47000,
        },
        [11281] = {
            description = "The horn has been roughed out, but before I make the traditional carvings, I " ..
                "want to be certain that it will work. Ahota tells me that he tests his horns at the foot " ..
                "of the frozen waterfall to the northeast of the post. Ahota tells me that our hunters " ..
                "have used the acoustics of frozen water in this way for generations. I can't wait to " ..
                "learn more!\n\nWill you help me test out the horn? If I've done everything right, you " ..
                "may even attract a yeti, so be prepared! Bring the horn back once you've tested it.",
            rewardChoices = {{35929, 1}, {35930, 1}, {35931, 1}, {35937, 1}},
            rewardMoney = 47000,
        },
        [11282] = {
            description = "When you've been in lots of fight like Gorth, you learn that to beat enemy " ..
                "good you have to make them really scared to die!\n\nBut these vrykuls not afraid. You " ..
                "kill one and another comes... screaming louder and with a bigger weapon than the one " ..
                "before.\n\nOnly thing that makes vrykuls afraid is when we kill the biggest and baddest " ..
                "vrykul of all.\n\nGo fight the Winterskorn across the blockade until hero vrykuls show " ..
                "up! Then you kill them dead and put queen's flag on corpses. They must learn to fear!",
            rewardChoices = {{35868, 1}, {35869, 1}, {35870, 1}, {35867, 1}},
            rewardMoney = 47000,
        },
        [11283] = {
            description = "Them vrykuls just keeps coming and coming out from town west of here. No end " ..
                "in sight!\n\nGorth has an idea. You go INSIDE town and kill them Winterskorn there. THEN " ..
                "they stop coming here!",
            rewardChoices = {{35818, 1}, {35820, 1}, {35821, 1}, {35822, 1}},
            rewardMoney = 94000,
        },
        [11284] = {
            description = "Maybe if the sentries won't help me, you will? I'm the foreman of the mine " ..
                "just across the bridge. My men are mining ore for the weapons our expeditionary force " ..
                "will need to carve a path into the Grizzly Hills.\n\nA giant yeti has invaded the mine, " ..
                "blocking the tunnel we need to expand! We've tried yelling at him and smoking him out, " ..
                "but nothing's worked.\n\nMaybe you could rouse it from its sleep with a meal of meat " ..
                "from the frosthorn rams in the snowy areas around town? Please? We're desperate!",
            rewardChoices = {{35929, 1}, {35930, 1}, {35931, 1}, {35937, 1}},
            rewardMoney = 47000,
        },
        [11285] = {
            description = "Killing the Winterskorns maybe not enough. Maybe we burn their houses too! " ..
                "Uh... and their bridges. We should burn whole town to be safe!\n\nYou take this torch. " ..
                "Go to Baleheim, to the west, and burn EVERYTHING! That teach them good.",
        },
        [11286] = {
            description = "I came out here for a different reason; an old friend of mine has been calling " ..
                "to me in my dreams. But now that I see these small things with their machines making a " ..
                "big hole in the ground, it makes my blood boil.\n\nFrom what I can see, these dwarves, " ..
                "as they are known, are digging up artifacts; artifacts that could be important to our " ..
                "past.\n\nI want you to go down there and get these things for me. Don't let any of those " ..
                "dwarves stand in your way.",
            rewardChoices = {{35912, 1}, {35911, 1}, {35936, 1}},
            rewardMoney = 47000,
        },
        [11287] = {
            description = "<class>, I grow worried that my son, Sage Mistwalker, has been gone for such a " ..
                "long time. The land is cruel and deadly.\n\nHe spoke of a recurring vision that he had " ..
                "of a wolf, and went west with a small group of longrunners to seek its source. I believe " ..
                "the name of the place he mentioned was Steel Gate.\n\nWill you find him? I want to make " ..
                "sure that no ill has befallen him.",
        },
        [11288] = {
            description = "<Ares gasps for air as he tries to speak.>\n\nI am an envoy of the Argent " ..
                "Crusade, charged with a sacred duty.\n\nOur forces were decimated in the Plaguelands. By " ..
                "the light of dawn, the artifact was cleansed and made pure once more. So many perished " ..
                "in the wake of its redemption.\n\nThere is still a chance... still time.\n\nThe artifact " ..
                "was hurled into the den of the fallen, far below us. Guarded by the unmerciful " ..
                "dead.\n\n<Ares' body glows with blinding light.>\n\nLight. Will. Protect. You.",
            rewardChoices = {{35823, 1}, {35824, 1}, {35826, 1}, {35827, 1}, {35829, 1}, {35830, 1}},
        },
        [11289] = {
            description = "<Ares smiles.>\n\nGlory to the Light. You have done it!\n\n<Ares " ..
                "coughs.>\n\nTake the artifact and return it to Valgarde. Lord Irulon Trueblade awaits " ..
                "its return.\n\nFight with honor, friend. Always. Honor.\n\n<Ares dies.>",
            rewardMoney = 47000,
        },
        [11290] = {
            description = "While we were able to gather very little information as to the whereabouts of " ..
                "Ingvar, we do know that Yanis resides in a cave next to the worg pit inside Wyrmskull " ..
                "Village.\n\nIntelligence gathered from the rescued soldiers indicates that Yanis guards " ..
                "Dragonflayer battle plans.\n\nI need you to go back to Wyrmskull and recover those " ..
                "plans. Kill any vrykul that get in your way - including Yanis!",
            rewardChoices = {{35814, 1}, {35815, 1}, {35816, 1}, {35817, 1}},
            rewardMoney = 44000,
        },
        [11291] = {
            description = "< Vice Admiral Keller rolls up the battle plans.>\n\nWe've got all the " ..
                "information we need to keep Valgarde protected. You must take these battle plans to " ..
                "Westguard Keep, located on the western fjord cliff wall. Speak with the flight master " ..
                "assistant, Emilune Winterwind. She will put you on the back of a gryphon headed towards " ..
                "Westguard.\n\nOnce there, find Captain Adams. He's the one in charge. Adams will know " ..
                "what to do with these plans.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [11292] = {
            description = "Glad to meet you. I've come here from the Grizzly Hills to do business with " ..
                "your cohorts. My people maintain a large outpost there, and you'd do well to visit it " ..
                "when you head north.\n\nI've set up traps in the woodlands and snowy areas around here. " ..
                "With the meat and the furs from the creatures they capture, I'll have plenty to barter " ..
                "with the townspeople.\n\nI can offer you a share of my profits if you're willing to help " ..
                "gather prey from the traps. Beware though, you won't be the only predator out there.",
            rewardChoices = {{35863, 1}, {35864, 1}, {35865, 1}, {35866, 1}},
            rewardMoney = 44000,
        },
        [11295] = {
            description = "No one seems to know very much about the vrykul. Our records show no signs of " ..
                "activity in their lands for centuries. Yet here they are, just as we move against " ..
                "Arthas.\n\nThe map you retrieved makes it clear that we'll have to defeat them if our " ..
                "forces are to get any further into Northrend.\n\nOne of my best sergeants, an " ..
                "abomination known as Gorth, oversees the blockade beyond the lift. Assist him in " ..
                "launching a pre-emptive strike on Baleheim. If a vrykul attack occurs, it will be " ..
                "launched from there.",
        },
        [11296] = {
            description = "Something, most likely the walking dead known as the Scourge, has agitated the " ..
                "creatures hereabouts.\n\nWhile escorting the sage here, we lost most of our hunting " ..
                "force to the riven widows -- huge and deadly spiders, which inhabit the Rivenwood to the " ..
                "north.\n\nI must stay here to protect the small force we have left, but you... you could " ..
                "see if my longrunners are still alive, trapped within the riven widow's " ..
                "cocoons.\n\nWould you do this, stranger?",
            rewardChoices = {{35896, 1}, {35897, 1}, {35898, 1}, {35899, 1}},
            rewardMoney = 50000,
        },
        [11297] = {
            description = "Even the earth cannot hold back the tide of death washing over it. Corpses " ..
                "walk the land, spreading their putrefaction with alarming speed.\n\nA small expedition " ..
                "has made its way up the western cliffs and rests near Whisper Gulch. Take a look for " ..
                "yourself, <name>. See if you can learn their purpose and dissuade them from bringing " ..
                "their poisons into our lands. Travel southwest from the post, toward the cliffs " ..
                "overlooking the western beach. Their camp will be west of the excavation at Steel Gate.",
        },
        [11298] = {
            description = "To the southeast is an area called Whisper Gulch. It's overrun with members of " ..
                "the Explorers' League who've gone mad! They attacked our caravan as it passed through " ..
                "the area, and they've harried our foraging parties as well.\n\nI must know what's " ..
                "causing this madness! I suspect that whatever they're drinking from the kegs scattered " ..
                "around the gulch contributes to their insanity. I want you to steal the kegs from those " ..
                "dwarves while they're busy mining away.",
            rewardMoney = 47000,
        },
        [11299] = {
            description = "You might have already seen the room where Daegarn is being held while you " ..
                "were gatherin' the tablets. It's through this corridor and then down a set of steps. " ..
                "Daegarn will be in the room at the bottom of the steps - locked up tight!\n\nGet down " ..
                "there and find him. At the very least you might be able to get the cipher from him.",
        },
        [11300] = {
            description = "Oluf will come out if you defeat the other gladiators. That's 'bout the only " ..
                "way we're getting' that cipher back. Put on your whompin' boots and get busy in the Ring " ..
                "of Judgement. If you do manage to get the cipher back, return it to Glorenfeld o'er near " ..
                "the entrance to these catacombs.\n\nMe? Don't worry about me! We're on the brink of " ..
                "discovering the missing link to human-kind!",
        },
        [11301] = {
            description = "Has Malthus drawn you in with his blather about beer kegs and crazy " ..
                "dwarves?\n\nI'm not questioning that the dwarves are crazy, but I don't think stealing " ..
                "their beer is going to do any good.\n\nWhat we need is brains. Lots of brains. We'll get " ..
                "down to the bottom of this mystery in no time, and perhaps even find a new component for " ..
                "the plague.\n\nTake this saw, go southeast into the Whisper Gulch, and kill yourself " ..
                "some dwarves. Use the saw to help you harvest the brains and bring them back here.",
            rewardChoices = {{35863, 1}, {35864, 1}, {35865, 1}, {35866, 1}},
            rewardMoney = 47000,
        },
        [11302] = {
            description = "When we first scouted locations for the fort, we encountered hostile creatures " ..
                "at two of the glades here in the north. When we passed the snow-covered one directly " ..
                "south of the town, the dryads there watched us with interest, but did not attack.\n\nWe " ..
                "were tired and worn down by the weather. They could've easily killed several of our men, " ..
                "but they didn't.\n\nPerhaps, in reaching out to them, we might discover unexpected " ..
                "allies. Are you willing to travel to the Frozen Glade and make contact with them?",
        },
        [11303] = {
            description = "The vrykuls in Baleheim is completely defeated, no doubt about it. But still " ..
                "their leader stays in town and won't give up.\n\nGorth sends Lydell and his assassins to " ..
                "make good ambush to the northwest. You talk to Lydell and figure out how to get Vrykul " ..
                "chieftain to come out. Then you kill him. You kill him real good.",
            rewardMoney = 94000,
        },
        [11304] = {
            description = "I'm afraid our equipment isn't exactly the best here at Vengeance Landing. " ..
                "After all it's a military controlled outpost.\n\nI will need you to take a sample of " ..
                "this strain to Chief Plaguebringer Harris in New Agamand, follow the road beyond " ..
                "Baleheim south and then west. They have better equipment there - he will know what to " ..
                "do.\n\nYou must hurry, <name>. Our enemies are stronger and more numerous than us. We " ..
                "need to develop a viable weapon against them!",
        },
        [11305] = {
            description = "We've been spraying down the vrykul village of Halgrind for weeks now and the " ..
                "vrykul just won't drop dead.\n\nLet's face it, <name>, by now our Plague has been " ..
                "exposed to humans, dwarves, dogs, livestock... you name it. As our strains adapt to " ..
                "their hosts, more impurities get thrown in the mix. What we need is a strain made custom " ..
                "for the vrykul's biology.\n\nHalgrind's chieftain fled the town after we took it over; " ..
                "you'll find him west of here. As a patriarch of the Dragonflayer clan, his blood is " ..
                "ideal.",
            rewardChoices = {{35849, 1}, {35851, 1}, {35852, 1}, {35856, 1}},
        },
        [11306] = {
            description = "You've done well so far, <name>. I'd like to teach you some of my more " ..
                "advanced techniques, so that you gain a better understanding of the plague.\n\nTake this " ..
                "empty flask and fill it with blood from the cauldron to my left. Mix it with the plague " ..
                "samples to my right until you obtain a well balanced mix.",
        },
        [11307] = {
            description = "Now that we have a strain of the plague that has adapted to vrykul carriers, " ..
                "we really ought to test it on our specimens in Halgrind. If all goes according to plan, " ..
                "they will disintegrate immediately as the plague devours their innards!\n\nYou will find " ..
                "Halgrind north of here. Our plaguebringers are deploying the previous strain there - " ..
                "shouldn't be hard to spot.",
            rewardChoices = {{35857, 1}, {35858, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 47000,
        },
        [11308] = {
            description = "Being the practical man that I am, I'm going to declare our research here a " ..
                "success. After all, what army can't be stopped by turning its rank and file against each " ..
                "other?\n\nI will send word of our achievements to Vengeance Landing soon enough. But " ..
                "first I need you to take care of cleaning up our experimentation site.\n\nSee " ..
                "\"Hacksaw\" Jenny about making you a custom abomination. One packing some explosive " ..
                "power if you catch my drift.",
        },
        [11309] = {
            description = "So Harris wants a demolition job, eh? Yeah, I can help out.\n\nYou're gonna " ..
                "have to get me some parts, though. I can't afford to use up my choice components on " ..
                "something that's gonna get blown up.\n\nFirst of all, I'm going to need shoveltusk " ..
                "ligaments... way better than the human kind.\n\nI will also need a pound of flesh. A " ..
                "fellow known as Anton sells cheap meat. He travels up and down the road to the west.",
            rewardChoices = {{35844, 1}, {35846, 1}, {35848, 1}},
            rewardMoney = 47000,
        },
        [11310] = {
            description = "Well, here you are! Our friend's going to be somewhat... unstable. So I " ..
                "suggest not putting him together until reaching Halgrind.\n\nOnce you're there, use the " ..
                "abomination to round up as many vrykul as you can before self-destructing.\n\nCome back " ..
                "with whatever's left once you're done. I can always use more body parts!",
            rewardChoices = {{35859, 1}, {35860, 1}, {35861, 1}, {35862, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 94000,
        },
        [11311] = {
            description = "If you are to survive here, as we have, you must learn to face the " ..
                "environment's challenges head on. The elements will claim your life if you're not " ..
                "vigilant, as the proliferation of elementals in these northern hills shows.\n\nWe must " ..
                "cull the elementals one last time before we can leave this place. Are you willing to aid " ..
                "us while we continue to make preparations?\n\nYou must kill any iceshard elementals or " ..
                "howling cyclones you encounter in the snowy hills surrounding the outpost.",
            rewardMoney = 47000,
        },
        [11312] = {
            description = "For generations, my people have told tales of frost nymphs cavorting in glades " ..
                "hidden away in the wilderness. I used to search for them as a child, against the advice " ..
                "of my parents, until I nearly froze to death.\n\nThese days, it isn't necessary to comb " ..
                "the forests for them. They've decided to reveal themselves for reasons I can only guess, " ..
                "but I don't think the change can be ignored. Venture southeast to the Frozen Glade and " ..
                "seek out the nymphs, but beware; you will pass the Twisted Glade on your way.",
        },
        [11313] = {
            description = "The ice elementals surrounding our glade were once our companions, but a " ..
                "volatile and destructive force has swept through the land, turning them against " ..
                "us!\n\nThis is but one of the horrors my sisters and I have endured. We have revealed " ..
                "ourselves to you in the hope that you will help us stave off the decay that has crept " ..
                "into our glades and poisoned our sisters!\n\nWe've been gathering the cores of the ice " ..
                "elementals and keeping them safe so that one day, we might be able to restore them. Will " ..
                "you help?",
            rewardMoney = 47000,
        },
        [11314] = {
            description = "To the southwest was a glade that used to look much like this one. Mysterious " ..
                "forces and alien magics are reshaping the land. The glade has thawed, the sisters living " ..
                "there driven mad by the sudden change.\n\nWe thought to reach out to them, but they " ..
                "attacked us. I fear many may be beyond saving, but I cannot give up hope.\n\nTake my " ..
                "pendant, travel southwest to the Vibrant Glade, and use it to try to free my sisters.",
            rewardMoney = 47000,
        },
        [11315] = {
            description = "The sisters who lived in the Vibrant Glade, to the southwest, used to tend to " ..
                "gorgeous beds of scarlet ivy, but the same force that has driven them mad has " ..
                "transformed their beloved ivy.\n\nThe vines now grasp at the feet of the unwary, or lash " ..
                "at any who approach the glade. Before we can reclaim the glade, the vines must be tamed " ..
                "and uprooted.\n\nClear as much of the ivy as you are able. It has already begun to grow " ..
                "out of control.",
            rewardMoney = 47000,
        },
        [11316] = {
            description = "The glade to the west has been transformed into a hideous place called the " ..
                "Twisted Glade. Horrible beasts dwell among the trees, stones, and pool of the " ..
                "glade.\n\nI cannot guess where the creatures came from or what horrible forces animate " ..
                "them, but they must be dealt with!\n\nI fear that if they are allowed to dominate the " ..
                "glade, they will poison it beyond redemption. Clear the glade of these creatures who " ..
                "murdered our sisters.",
            rewardMoney = 47000,
        },
        [11317] = {
            description = "We braved the Rivenwood because of my troubled dreams concerning my worg " ..
                "life-friend, Ulfang. He has called out for help, and you must go to him.\n\nBut, you do " ..
                "not have the means to speak with him, or walk amongst the other worgs. I know a " ..
                "way.\n\nFirst, you must cleanse your inner turmoil.\n\nThere is a shrine that sits at " ..
                "the top of Frostblade Peak, northeast of Camp Winterhoof. A single path leads up to it " ..
                "from the western base of the mountain.\n\nMeditate there and then return to me.",
            rewardMoney = 47000,
        },
        [11319] = {
            description = "The glade to the northwest, now the Twisted Glade, used to be home to a number " ..
                "of keepers of the glade. Together with the sisters, they saw to the glade's " ..
                "upkeep.\n\nWhen the glade changed, the sisters died, but somehow the keepers managed to " ..
                "survive. Now, they seed the land with poisonous spores that wither healthy " ..
                "greenery.\n\nI'll give you one of the cores from the ice elementals. Once you've " ..
                "destroyed a spore, use the ice crystal to freeze it and keep it from regenerating.",
            rewardChoices = {{39072, 1}, {39073, 1}, {39074, 1}},
            rewardMoney = 47000,
        },
        [11322] = {
            description = "Of late I've had nightmares concerning a worg named Ulfang. He has called out " ..
                "for help, and you must go to him.\n\nHowever, you do not have the means to speak with " ..
                "him, or walk amongst the other worgs. I know a way.\n\nBut first, you must cleanse your " ..
                "inner turmoil through meditation.\n\nThere is a shrine that sits at the top of " ..
                "Frostblade Peak, far to the northeast. A single path leads up to it from the western " ..
                "base of the mountain.\n\nMeditate there to cleanse yourself and then return to me.",
            rewardMoney = 47000,
        },
        [11323] = {
            description = "From my dreams, I know that Ulfang is in a cave on the snowy northwestern edge " ..
                "of the Rivenwood.\n\nHe is in great danger.\n\nI have devised a magical disguise that " ..
                "will make you appear as a worg while you are within the Rivenwood. The disguise is weak, " ..
                "relying upon the strange magics of that haunted wood. While it will only convince the " ..
                "worgs, it will allow you to get close to Ulfang.\n\nPlease, <class>, find and help him.",
        },
        [11324] = {
            description = "When you've eaten Talonshrike's eyes, you should be able see Garwal and rip " ..
                "out his throat!\n\n<race>-thing, seek out and slay Garwal in the western Rivenwood. " ..
                "After you have killed him, go and tell Mistwalker that I am once more the alpha worg!",
            rewardChoices = {{35913, 1}, {35914, 1}, {35915, 1}, {35916, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 94000,
        },
        [11325] = {
            description = "From my dreams, I know that Ulfang is in a cave on the snowy northwestern edge " ..
                "of the Rivenwood.\n\nHe is in great danger!\n\nI have devised a magical disguise that " ..
                "will make you appear as a worg while you are within the Rivenwood. The disguise is weak, " ..
                "relying upon the strange magics of that haunted wood. While it will only convince the " ..
                "worgs, it will allow you to get close to Ulfang.\n\nPlease, <class>, find and help him.",
        },
        [11326] = {
            description = "When you've eaten Talonshrike's eyes, you should be able see Garwal and rip " ..
                "out his throat!\n\n<race>-thing, seek out and slay Garwal in the western Rivenwood. " ..
                "After you have killed him, go and tell Moonleaf that I am once more the alpha worg!",
            rewardChoices = {{35913, 1}, {35914, 1}, {35915, 1}, {35916, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 94000,
        },
        [11327] = {
            description = "Well darn, we need some of that plague-stuff.\n\nI know!\n\nWhile you were " ..
                "destroying the vats, I happened to spy one of the apothecaries from New Agamand being " ..
                "pulled into Halgrind by the vrykul down in there. Poor fella'.\n\n<name>, I'd bet " ..
                "anything that apothecary has the goods on him. Think you could go into Halgrind and " ..
                "retrieve his package?",
            rewardMoney = 47000,
        },
        [11328] = {
            description = "Right, so I think you should get this stuff over to Peppy Wrongnozzle back at " ..
                "the keep. She's something of an amateur alchemist, but she's the only one we've " ..
                "got.\n\nOne thing about Peppy; she does love her drink. So, you'll likely find her at " ..
                "the tavern 'soaking up the atmosphere'.\n\nI'm sure she'll know what to do.",
        },
        [11329] = {
            description = "I never want to see another barrel of salted fish as long as I live! Filling " ..
                "barrels day in and day out, and there are still more to be filled!\n\nI wish I hadn't " ..
                "used up all that bait I bought from Nat Pagle. Worked like magic, it did. Now I'm lucky " ..
                "if I can catch a fish an hour!\n\nI hear the northern barbfish make pretty good bait, " ..
                "but who's crazy enough to dive into a freezing cold lake and hack up the water plants in " ..
                "search of them? Not me... but maybe, just maybe, I can persuade you to...",
            rewardMoney = 44000,
        },
        [11330] = {
            description = "Voila, inshtant plague vacshine!\n\nBut I sure as heck am not going to try " ..
                "thish on myself. And I know you don't want to be my tesht shubject!\n\nOh, I've got... " ..
                "I've got an idea!\n\nWe've got a vrykul prishoner being held down in the cells under the " ..
                "keep. Why don't you take thish mix I whipped up down there, and get that giant to drink " ..
                "it...hic?!",
            rewardMoney = 24000,
        },
        [11331] = {
            description = "Here'sh the deal. I'm not going to the captain with thish news. I'm an amateur " ..
                "alchemist, thish ishn't my job, and I'm on break!\n\nBeshides, he'sh a big grumpkin... " ..
                "and you know him better than I do!\n\nSho, jusht go up into the keep and tell him. I'm " ..
                "sure he'll be reashonable about the whole thing...hic.\n\n<Peppy turns back to her " ..
                "drinking.>",
        },
        [11332] = {
            description = "The Royal Apothecary Society thinks they're going to perfect a new plague to " ..
                "melt us down where we stand?!\n\nNot on my watch!\n\nGet out to the courtyard and speak " ..
                "with Greer Orehammer. He's got a gryphon and some bombs ready for you. I want you to " ..
                "bomb the plague tanks at New Agamand to smithereens!",
            rewardChoices = {{35892, 1}, {35893, 1}, {35894, 1}, {35895, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 94000,
        },
        [11333] = {
            description = "While the Explorers' League may discern bits and pieces of the past through " ..
                "their archaeological findings and the Vice Admiral might extract some knowledge of the " ..
                "present through brute force, the truth lies with the spirits.\n\nWith the proper " ..
                "reagents I am able to see into the spirit world. It is there that the past, present and " ..
                "future of Northrend resides.\n\nIf you wish to learn more, I will require my reagent " ..
                "pouch. It was lost in a ship that is now at the bottom of Daggercap Bay, just east of " ..
                "here.",
        },
        [11343] = {
            description = "The spirit world has fallen under the sway of the Lich King. Fearsome " ..
                "creatures made of pure nightmare now stand watch over the realm of the elements. I sense " ..
                "that these val'kyr are guarding a terrible secret.\n\nI am too old and weak to survive " ..
                "another journey. You must go in my place, <name>.\n\nTake this incense burner to " ..
                "Wyrmskull Village and use it to enter the spirit world. Find the large dwelling in the " ..
                "northeast! Avoid the val'kyr at all costs lest they make you a permanent fixture in " ..
                "their world.",
        },
        [11344] = {
            description = "All that we know of the vrykul indicates that they only recently appeared in " ..
                "Northrend. Why, then, are we seeing vrykul in visions that date back 15,000 years? " ..
                "Surely if the vrykul had previously existed in Northrend we would have known.\n\nYou " ..
                "must press on to Nifflevar. To get there you must go northeast, through Wyrmskull " ..
                "Village, and take the path leading up through the dam. Nifflevar is on the bluffs of the " ..
                "fjord.\n\nUse the incense burner once you arrive at Nifflevar and search the area for " ..
                "clues.",
            rewardChoices = {{35832, 1}, {35833, 1}, {35834, 1}, {35835, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [11346] = {
            description = "The vast rocky area to the southeast, Giants' Run, has been overrun by Iron " ..
                "Dwarves. Scouts have reported seeing the dwarves coaxing stone giants from the ground, " ..
                "then carving runes on them.\n\nI can't fathom their motives, but I suspect they're " ..
                "somehow trying to turn the giants into weapons. The iron rune stonecallers and binders " ..
                "carry large tomes with them, which must contain the runes they're carving on the " ..
                "giants.\n\nCapture the pieces of this book, assemble them, and bring it back to me, " ..
                "<name>.",
            rewardMoney = 47000,
        },
        [11348] = {
            description = "Can you feel the power emanating from the runes I've carved on this tablet? " ..
                "They're smaller versions of the runes that the Iron Dwarves are using. We'll use it to " ..
                "shut down their operation.\n\nTake it to Giants' Run and use it on a stone giant that " ..
                "the dwarves have not altered.\n\nThe giant should obey you, but I've tailored the runes " ..
                "to restore it to its natural state after a time. The giant may prove a valuable ally in " ..
                "the battle against Binder Murdis, the leader of the Iron Dwarf forces at Giants' Run.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 47000,
        },
        [11349] = {
            description = "I've got a set of picks, hammers, and chisels with me, but they won't work for " ..
                "carving these runes. The tools used by the Iron Dwarves are imbued with magic during " ..
                "their forging.\n\nWhen they're used to carve runes, the symbols form much more than mere " ..
                "words. These runes have the power to bind, compel, and twist.\n\nI believe I know how it " ..
                "works, but without a set of those tools, I can't be certain. Look for kits resembling " ..
                "mine near the Iron Dwarf pavilions at Giants' Run and bring them to me.",
            rewardMoney = 47000,
        },
        [11350] = {
            description = "Chieftain Ashtotem dispatched me on a scouting mission to Giants' Run, a " ..
                "broad, rocky plateau to the southeast, past the Frozen Glade.\n\nThe area has been taken " ..
                "over by Iron Dwarves who seem to be altering the giants as they emerge from the " ..
                "earth.\n\nThe iron rune stonecallers and binders carry large tomes with them, which must " ..
                "contain the runes they're carving on the giants.\n\nCapture the pieces of this book, " ..
                "assemble them, and bring it back to me. It's the only way we'll understand their plans.",
            rewardMoney = 47000,
        },
        [11351] = {
            description = "I think I've figured out what the Iron Dwarves are doing. The tools they use " ..
                "are imbued with magic during their forging.\n\nWhen they're used to carve runes, the " ..
                "symbols form much more than mere words. These runes have the power to bind, compel, and " ..
                "twist.\n\nIf I had a set of those tools, I could mimic the runes in the book. I captured " ..
                "one of these boxes from one of the pavilions at Giants' Run, but it was empty. Look for " ..
                "similar boxes and recover a set of tools from them.",
            rewardMoney = 47000,
        },
        [11352] = {
            description = "Can you feel the power emanating from the runes I've carved on this tablet? " ..
                "They're smaller versions of the runes that the Iron Dwarves are using. We'll use it to " ..
                "shut down their operation.\n\nTake it to Giants' Run and use it on a stone giant that " ..
                "the dwarves have not altered.\n\nThe giant should obey you, but I've tailored the runes " ..
                "to restore it to its natural state after a time. The giant may prove a valuable ally in " ..
                "the battle against Binder Murdis, the leader of the Iron Dwarf forces at Giants' Run.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 47000,
        },
        [11355] = {
            description = "To the east, at Giants' Run, rune-inscribed stone giants have started to " ..
                "migrate north toward Frostblade Peak. What their ultimate destination is, I do not " ..
                "know.\n\nThe glowing runes inscribed in the stone flesh of the giants guide them on " ..
                "their journey.\n\nUse this pick to deactivate the runes on the giants' corpses and " ..
                "return with your findings.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 50000,
        },
        [11358] = {
            description = "If we can locate what's luring the giants northwest, we might be able to stop " ..
                "them before they reach their destination.\n\nAlthough I was able to decipher many of the " ..
                "runes on the samples you brought me, the ones I don't know concern me the most. When I " ..
                "visited Giants' Run, I noticed a large broken tablet jutting from the ground where the " ..
                "northeastern part of the area met the snow at the foot of Frostblade Peak. Take this " ..
                "sample, compare the runes with the tablet, and see what you can learn.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 50000,
        },
        [11359] = {
            description = "Binder Murdis created Megalith to be the most powerful of the runed giants and " ..
                "to lead them in their mission. Defeating Megalith will leave them lost and without " ..
                "direction. After the expeditionary force arrives, our soldiers will be able to isolate " ..
                "and defeat the remaining giants and oust their Iron Dwarf masters from their " ..
                "camps.\n\nSearch the foothills of Frostblade Peak, north of Giants' Run for Megalith and " ..
                "defeat him!",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 100000,
        },
        [11364] = {
            description = "Do you question your master? Neither does Mah'duun.\n\nThe blood of the " ..
                "centurions of the Shattered Hand clan is what I seek. You will find them within the " ..
                "Shattered Halls of Hellfire Citadel.\n\nIf you want the bounty, you will not return " ..
                "until you have slain them all.",
            rewardItems = {{29460, 1}},
            rewardMoney = 88000,
        },
        [11365] = {
            description = "To the east, at Giants' Run, rune-inscribed stone giants have started to " ..
                "migrate north toward Frostblade Peak. I know nothing of their goals, nor of their " ..
                "destination.\n\nThe glowing runes inscribed in the stone flesh of the giants guide them " ..
                "on their journey. Fell some of these giants.\n\nTake this pick with you and use it on " ..
                "the corpses of the runed stone giants. It will deactivate the runes. Once you've tested " ..
                "enough giants, return to me with your findings.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 50000,
        },
        [11366] = {
            description = "We must find what's luring the giants northwest, so we can stop them before " ..
                "they reach their destination.\n\nWhile the rune samples gave us some clues, the unknown " ..
                "runes worry me.\n\nWhen I visited Giants' Run, I noticed a large broken tablet jutting " ..
                "from the ground where the northeastern part of the area met the snow at the foot of " ..
                "Frostblade Peak. Take this sample, compare the runes with the tablet, and see what you " ..
                "can learn about the identity of this lodestone.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 50000,
        },
        [11367] = {
            description = "Binder Murdis created Megalith to be a kind of keystone for the runed giants " ..
                "and to lead them in their mission. Defeating Megalith will leave them lost and without " ..
                "direction. I will ask Chieftain Ashtotem to divert some of our men as we move north and " ..
                "dedicate them to eliminating the last of the runed giants. Without their giants, the " ..
                "Iron Dwarves cannot stand against us.\n\nSearch the foothills of Frostblade Peak, north " ..
                "of Giants' Run for Megalith and defeat him!",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 100000,
        },
        [11369] = {
            description = "There is only ever one great mother of the marsh walkers in Zangarmarsh. She " ..
                "is always known as the Black Stalker, and she hatches from one of the eggs left behind " ..
                "when her mother dies.\n\nI have a buyer who is interested in one of those eggs. He " ..
                "mentioned something about adding her as a zoo attraction.\n\nIf you are interested in " ..
                "the reward I am offering, travel to the Underbog and slay the Black Stalker for her egg.",
            rewardItems = {{29434, 1}},
            rewardMoney = 132000,
        },
        [11370] = {
            description = "While it is known that Warlord Kalithresh of the naga is a great warrior in " ..
                "his own right, there are fewer who know that he has codified all of his " ..
                "knowledge.\n\nOne of my customers is aware of it though, and is keenly interested in " ..
                "obtaining his treatise.\n\nI ask that you travel to the Steamvault in Coilfang Reservoir " ..
                "and obtain this book for me.",
            rewardItems = {{29434, 1}},
            rewardMoney = 132000,
        },
        [11373] = {
            description = "Today I have a personal request of you, yet the reward will certainly match " ..
                "the danger.\n\nMy family has a 'history', shall we say, with Nexus-Prince Shaffar and " ..
                "his followers. If the amulet he wears were to fall into my hands then surely that would " ..
                "mean that he had been dealt with.\n\nIf the bounty I am offering is of interest to you " ..
                "then journey to his lair within Auchindoun's Mana-Tombs.",
            rewardItems = {{29434, 1}},
            rewardMoney = 132000,
        },
        [11374] = {
            description = "Within Auchindoun's Auchenai Crypts many unsavory experiments are undertaken " ..
                "in the pursuit of a greater understanding of the necromantic arts. Many are the spirits " ..
                "that are tortured or destroyed therein.\n\nI have a customer who is interested in the " ..
                "liberation of one of those spirits. I have been informed that this spirit is contained " ..
                "within a soul gem held by none other than Exarch Maladaar himself.\n\nSeek him out " ..
                "within the crypts with all due haste and return to me with the gem.",
            rewardItems = {{29434, 1}},
            rewardMoney = 132000,
        },
        [11375] = {
            description = "When I'm done speaking, you may not want to take this commission.\n\nI have an " ..
                "eccentric client who specializes in the study of dead realities. It is rumored that the " ..
                "being known as Murmur destroyed the last world from which he was summoned. The professor " ..
                "is interested in examining his 'whisper' as he called it to understand how it is that " ..
                "Murmur accomplished such a feat.\n\nWill you journey to the Shadow Labyrinth within " ..
                "Auchindoun and retrieve it for me?",
            rewardItems = {{29434, 1}},
            rewardMoney = 132000,
        },
        [11376] = {
            description = "Mah'duun has heard it said that none are as cruel as the six-armed demonesses " ..
                "inside the Shadow Labyrinth.\n\nGo to Auchindoun, seek them out, kill them all.\n\nIf " ..
                "you cannot accomplish so simple a task, we do not have anything further to say to one " ..
                "another.",
            rewardItems = {{29460, 1}},
            rewardMoney = 88000,
        },
        [11377] = {
            description = "I'm providing the catering for some unusual party guests tonight. One of these " ..
                "fellows was flying around in Skettis and got knocked to the ground by a monstrous " ..
                "kaliri--his leg was broken badly.\n\nThey've requested something special for his get " ..
                "well party: Kaliri Stew.\n\nI can loan you my cooking pot so you can whip up a batch of " ..
                "stew for me. The recipe itself is simple, but you'll need to get a giant kaliri wing and " ..
                "some cooked warp burgers.",
            rewardChoices = {{33844, 1}, {33857, 1}},
        },
        [11378] = {
            description = "The tastes of my customers range from the mundane to the exotic. And sometimes " ..
                "they want to do very mundane things with the exotic objects they seek.\n\nSuch is the " ..
                "case with my latest request. My client, who shall remain nameless, wishes to obtain the " ..
                "head of the Epoch Hunter to mount on his wall.\n\n<class>, will you find a way to travel " ..
                "back in time to Old Hillsbrad and procure said head for my trophy-hunting patron?",
            rewardItems = {{29434, 1}},
            rewardMoney = 132000,
        },
        [11379] = {
            description = "I'm trying to invent something with some real zing. But to be honest, I'm more " ..
                "of an idea goblin these days. I've lost my sense of adventure.\n\nBut you... remind me " ..
                "of my younger days; ready to take on the world with a sword in one hand and a skillet in " ..
                "the other.\n\nI want you to take my beloved cooking pot and head out to Blade's Edge. " ..
                "Throw in some shortribs and crunchy serpent--already cooked for extra flavor--and broil " ..
                "it over an abyssal's corpse, the only thing hot enough to do the trick.",
            rewardChoices = {{33844, 1}, {33857, 1}},
        },
        [11380] = {
            description = "Wouldn't you know it, I think my foodstuffs are up to date and someone comes " ..
                "along and requests the unusual: Mana Berry Delight.\n\nUnfortunately, mana berries are " ..
                "only found in the eco-domes of Netherstorm. Just don't bother looking around " ..
                "Stormspire--it's picked clean.\n\nI could only trust someone trained in the culinary " ..
                "arts to pick the best berries, so don't let me down!",
            rewardChoices = {{33844, 1}, {33857, 1}},
        },
        [11381] = {
            description = "Death is in the air. I've never had so many orders for my famous soup--it " ..
                "lifts your spirits and soothes the soul.\n\nAnd I know a fellow cook when I see one! " ..
                "Would you like to help me out and get a cut of the profits?\n\nHere, take my cooking " ..
                "pot, gather some clefthoof meat and I'll let you in on a little secret. What makes my " ..
                "soup so good for the soul? It's not chicken--I cook it at the Ancestral Grounds in " ..
                "Nagrand to soak up all that spiritual stuff there.",
            rewardChoices = {{33844, 1}, {33857, 1}},
        },
        [11383] = {
            description = "Mah'duun knows where you must go. Mah'duun knows that you must kill rift " ..
                "lords. But, Mah'duun does not know exactly when.\n\nI know that does not make sense, but " ..
                "the voice on the winds was not more specific.\n\nTravel to the Black Morass through the " ..
                "Caverns of Time and the way shall be made clear.",
            rewardItems = {{29460, 1}},
            rewardMoney = 88000,
        },
        [11384] = {
            description = "Not long ago, I was approached by a kaldorei druidess with a touching request. " ..
                "And plenty of gold, of course!\n\nIt would appear that the forces of Darnassus wish to " ..
                "restore an ancient of the arcane known as Warp Splinter. The giant tree has been " ..
                "confused or corrupted, I'm not certain, but you'll find it inside of the Botanica at " ..
                "Tempest Keep.\n\nShe said that all they would need to regrow him was a small clipping.",
            rewardItems = {{29434, 1}},
            rewardMoney = 132000,
        },
        [11386] = {
            description = "I always assumed that Pathaleon the Calculator used magic to project his image " ..
                "across Outland. Apparently I was wrong.\n\nMy latest customer tells me that the blood " ..
                "elf uses a mechanical device for his communication with the leaders of Prince " ..
                "Kael'thas's special projects. As I understand it, he acquired it from the Zaxxis rebels " ..
                "in the Netherstorm.\n\nMy client wishes to obtain the projector. Why don't you pay " ..
                "Pathaleon a visit? He can be found within the Mechanar at Tempest Keep.",
            rewardItems = {{29434, 1}},
            rewardMoney = 132000,
        },
        [11388] = {
            description = "Today's client seeks something truly unique.\n\nIt is said that Harbinger " ..
                "Skyriss is a servant of the Old Gods. It is also said that he carries a large scroll " ..
                "that contains their instructions for his domination of life in the universe on their " ..
                "behalf.\n\nMy current buyer wishes to get <his/her> hands on that scroll, nevermind that " ..
                "<he/she> won't be able to read the language upon it.\n\nTravel to Tempest Keep 's " ..
                "Arcatraz and get it for me, will you, <class>?",
            rewardItems = {{29434, 1}},
            rewardMoney = 132000,
        },
        [11390] = {
            description = "Well, what are you waiting for, there's work to be done!\n\nHere's the keys to " ..
                "our flying machine. Grab three sacks of relics and haul them up to the crane platforms " ..
                "on the north and south sides of Steel Gate. I'll mark them for you.\n\nHurry up! We " ..
                "haven't got all day!",
            rewardChoices = {{35912, 1}, {35911, 1}, {35936, 1}},
            rewardItems = {{22829, 5}},
            rewardMoney = 47000,
        },
        [11391] = {
            description = "Eh? Yer back for another day's work?\n\nWell, alright, here's the keys. We " ..
                "don't need any haulin' today, so just keep an eye out for anything suspicious, " ..
                "okay?\n\nI've hooked her up with some rockets and a machine gun - just in case.",
            rewardItems = {{22829, 2}},
            rewardMoney = 47000,
        },
        [11393] = {
            description = "<name>, my betrothed, Jaren, went west with a small group of explorers to " ..
                "check into rumors of artifacts on the Chillmere Coast. But there are murloc down there, " ..
                "and I fear the worst has befallen them.\n\nSurely you have time to see if they're " ..
                "alright? There's a way down to the beach just to the southwest, though watch out for the " ..
                "worgs and other things lurking in the woods.",
        },
        [11394] = {
            description = "Originally I came down here to investigate some rumors about artifacts to be " ..
                "dug up. I knew that there were murlocs along the coast here, but I never in a million " ..
                "years thought I'd see this.\n\n<The explorer pokes his head out to look around the " ..
                "tree.>\n\nThe Scourge are out there, and they're changing murlocs, and anything else " ..
                "they can get their hands on, into the walking dead!\n\n<class>, I think it's our duty to " ..
                "do something about this. Think you could take out a good chunk of those Scourge?",
            rewardMoney = 47000,
        },
        [11395] = {
            description = "The Scourge creature you just destroyed had this device held in its clutches. " ..
                "It has a jewel set into it which looks similar to the one that tops the scourging " ..
                "crystals.\n\nSurely, Explorer Jaren would like to have a look at this.",
        },
        [11396] = {
            description = "Look at the button on the side of the controller here. I bet if you got close " ..
                "enough to one of those scourging crystals, you could use the controller to bring its " ..
                "shield down. Then it would simply be a matter of destroying the thing before its shield " ..
                "goes back up.\n\nWhat do you say, <name>? You up for it? I can guarantee a nice reward " ..
                "for you if you can bring down those shields and destroy the crystals.\n\nIt's the least " ..
                "we can do to keep the Scourge from making more of their own kind.",
            rewardChoices = {{35933, 1}, {35934, 1}, {35932, 1}, {35935, 1}},
            rewardMoney = 94000,
        },
        [11397] = {
            description = "I came here to investigate a rumor about a Scourge presence nearby. I expected " ..
                "murlocs along the coast down below, but I never thought I'd see this!\n\nThe Scourge are " ..
                "down there, and they're changing murlocs, and anything else they can get their hands on, " ..
                "into the walking dead!\n\n<class>, we will not suffer them to create more of their kind, " ..
                "especially not from murlocs! There is a ramp down to the beach just northwest of the " ..
                "camp. See to it that you deal with the Scourge in a timely fashion!",
            rewardMoney = 47000,
        },
        [11398] = {
            description = "The Scourge creature you just destroyed had this device held in its clutches. " ..
                "It has a jewel set into it which looks similar to the one that tops the scourging " ..
                "crystals.\n\nSurely, Apothecary Anastasia would like to have a look at this.",
        },
        [11399] = {
            description = "Look at the button on the side of the controller here. I bet if you got close " ..
                "enough to one of those scourging crystals, you could use the controller to bring its " ..
                "shield down. Then it would simply be a matter of destroying the thing before its shield " ..
                "goes back up.\n\nBrave enough to hazard another trip down there, <name>? I can guarantee " ..
                "a nice reward for you if you can bring down those shields and destroy the " ..
                "crystals.\n\nHow can you refuse if it means less Scourge, especially ones made from " ..
                "murlocs?",
            rewardChoices = {{35933, 1}, {35934, 1}, {35932, 1}, {35935, 1}},
            rewardMoney = 94000,
        },
        [11406] = {
            description = "When the expeditionary force moves north, Captain Adams expects everything to " ..
                "be ready at Fort Wildervar. The scouts and craftsmen there have been tasked with " ..
                "preparing the gear and rations for our men for the climb into the hills.\n\nThe " ..
                "captain's famous for his temper, so I want to send someone ahead to check on the " ..
                "preparations. Fort Wildervar is far to the northeast, beyond Skorn, up in the " ..
                "snow-covered areas near the border with Grizzly Hills. Find Gil Grisert there and make " ..
                "sure he is prepared.",
            rewardMoney = 4400,
        },
        [11410] = {
            description = "The barbfish you brought should work well as bait for most fish, but I fear " ..
                "it'll attract a monster!\n\nWhen I first arrived, I put some of Nat Pagle's favorite " ..
                "bait on my hook and cast it into the water. A huge monster latched on, with giant teeth " ..
                "and icicles hanging from its fins!\n\nWould've pulled me into those icy waters if I " ..
                "hadn't cut the line! I can't use the new bait until ol' Frostfin 's been dealt with. Use " ..
                "this bait near the sunken boat in the middle of the lake. He won't be able to resist!",
            rewardMoney = 47000,
        },
        [11411] = {
            description = "In my travels as a courier, I've seen a number of strange denizens of the " ..
                "Howling Fjord, but one group stands out. From a distance, they look like tauren, but " ..
                "upon closer inspection, they're quite different -- sturdier and shaggier.\n\nI found one " ..
                "of their settlements far to the north, beyond Halgrind, Skorn, and the northern forests. " ..
                "Camp Winterhoof, it's called, and it sits in the foothills of Gjalerhorn near the border " ..
                "with Grizzly Hills. Make contact with them, and see if they might be of use to us.",
        },
        [11414] = {
            description = "Watcher Moonleaf is from my dreams! If you are her friend, you are mine.\n\nI " ..
                "was alpha male until the last full moon. Then the strange white worg, Garwal, came from " ..
                "the north, and with the help of my once-brothers, he quickly became alpha worg. There is " ..
                "something unnatural about him.\n\nTo help, you must first kill those who betrayed " ..
                "me.\n\nBjomolf hunts to the northwest of a place called Steel Gate. And look for Varg to " ..
                "the southeast, near the West Spear Tower.\n\nThey will not be fooled by your form.",
        },
        [11415] = {
            description = "Mistwalker is from my dreams! If you are his friend, you are mine.\n\nI was " ..
                "alpha male until the last full moon. Then the strange white worg, Garwal, came from the " ..
                "north, and with the help of my once-brothers, he quickly became alpha. There is " ..
                "something unnatural about him.\n\nTo help, you must first kill those who betrayed " ..
                "me.\n\nBjomolf hunts to the northwest of a place the two-legs call Steel Gate. And look " ..
                "for Varg to the southeast, near the West Spear Tower.\n\nThey will not be fooled by your " ..
                "form.",
        },
        [11416] = {
            description = "Garwal hides himself behind an unnatural magic. None can see him unless he " ..
                "wants you to. There may be one chance we can take, though.\n\nMy enemy, the great eagle, " ..
                "Talonshrike, is said to have eyes that can see anything. If you were to take her eyes, " ..
                "then you would surely be able to see Garwal.\n\nTalonshrike keeps her nest at the base " ..
                "of a waterfall just to the southwest of the vrykul place called Skorn. If you touch the " ..
                "eggs in her nest, she will come down from the sky to kill you.\n\nGet her eyes.",
        },
        [11417] = {
            description = "Garwal hides himself behind an unnatural magic. None can see him unless he " ..
                "wants you to. There may be one chance we can take, though.\n\nMy enemy, the great eagle, " ..
                "Talonshrike, is said to have eyes that can see anything. If you were to take her eyes, " ..
                "then you would surely be able to see Garwal.\n\nTalonshrike keeps her nest at the base " ..
                "of a waterfall just to the southwest of the vrykul place called Skorn. If you touch the " ..
                "eggs in her nest, she will come down from the sky to kill you.\n\nGet her eyes.",
        },
        [11418] = {
            description = "We see one brave hippogryph circling over the fort, then swooping down and " ..
                "taking prey. Jethan over there has taken a couple of shots at the creature, but his " ..
                "arrows bounced right off!\n\nWe've taken to calling this remarkable creature " ..
                "Steelfeather, but we can't see why he prefers the area around Fort Wildervar. Most " ..
                "hippogryphs are wary of people.\n\nResearcher Aderan has helped us fashion a charm from " ..
                "one of the creature's feathers. He claims it will allow the user to see through " ..
                "Steelfeather's eyes.",
            rewardMoney = 34000,
        },
        [11420] = {
            description = "Two weeks ago our chief engineer got his hands on a vrykul harpoon gun - the " ..
                "same type of gun that the vrykul use to take down our ships. By studying that gun he " ..
                "managed to put together a comprehensive operation manual.\n\nUnfortunately he was " ..
                "abducted and taken north of here to Wyrmskull Village. We eventually did find him, but " ..
                "near death and without the manual. His dying words indicated that the manual was lost in " ..
                "the Utgarde Catacombs, located at the northwest end of Wyrmskull. Get me that manual!",
            rewardMoney = 47000,
        },
        [11421] = {
            description = "We must strike while the vrykul forces are in disarray! Take the harpoon " ..
                "control mechanism to Nifflevar and locate the northernmost harpoon building on the bluff " ..
                "side of the village.\n\nOnce there, commandeer one of the vrykul harpoon guns that are " ..
                "stationed on the building's deck. Use the harpoon gun to rain hell upon Wyrmskull " ..
                "Village! Destroy the longhouse, dockhouse, storage facility and any defenders that the " ..
                "vrykul may send at you!\n\nDo this and Daggercap Bay will become a much safer port!",
            rewardChoices = {{35841, 1}, {35842, 1}, {35843, 1}, {35839, 1}},
            rewardMoney = 94000,
        },
        [11422] = {
            description = "<From the scratches he makes in the rock, you see several symbols: a trident, " ..
                "a mur'ghoul, the sun, a wrecked ship, and a rough stick-figure of " ..
                "yourself.>\n\n<Puzzling out what the murloc is conveying takes a while. Obviously he " ..
                "wants you to get a trident from the Chillmere Coast, but the image of the sun is " ..
                "puzzling. That is until you realize he means his son.>\n\n<His son was changed into a " ..
                "mur'ghoul! He wants you to find him to the south near the wrecked ship and return with " ..
                "his trident.>",
            rewardMoney = 47000,
        },
        [11423] = {
            description = "As our armies march through Northrend, our enemies will not suffer mere " ..
                "defeat. Their houses will burn, their corpses will be devoured by our plagues, all trace " ..
                "of their existence will be lost.\n\nThis worries me as a seeker of knowledge. The " ..
                "eastern town of Nifflevar will soon be razed by our forces in Vengeance Landing. The " ..
                "vrykul bard, Helgus, lived there and wrote three sagas: the Saga of the Twins, the Saga " ..
                "of the Winter Curse and the Saga of the Val'kyr. Obtain them before Nifflevar is " ..
                "destroyed.",
        },
        [11424] = {
            description = "My work should be extremely easy in a time of war. There ought to be usable " ..
                "body parts everywhere.\n\nIt's not that simple, though. With these eggheads making all " ..
                "sorts of killer plagues and sending them to enemy towns, most of the material gets " ..
                "contaminated.\n\nThere is a place, though, where usable samples exist. Shield Hill, " ..
                "south of here, is an ancient vrykul burial ground where the dead walk but are not " ..
                "afflicted with any plague - ours or the Lich King's. Get me some bones, I'll pay ya well.",
            rewardChoices = {{35892, 1}, {35893, 1}, {35894, 1}, {35895, 1}},
            rewardMoney = 47000,
        },
        [11426] = {
            description = "Don't worry, <name>; this is all going to lead to something big! HUGE! You're " ..
                "just going to have to trust me for now and do as I ask of you.\n\nWe need to get the " ..
                "mechanism mentioned in the manual for the next step of the plan. I have a strong " ..
                "suspicion that you'll find one on one of those vrykul that operate the harpoon guns in " ..
                "Wyrmskull Village. You'll find them on the east side of the village, on the docks by the " ..
                "longhouses.",
        },
        [11427] = {
            description = "Do you see those vrykul buildings on the bluffs to the northeast? The vrykul " ..
                "call that place Nifflevar. It's where most of their harpoon attacks on our frigates " ..
                "originate.\n\nWell guess what? The time for payback has come, <name>. I need you to take " ..
                "this harpoon control mechanism and meet up with Lieutenant Icehammer, who is hiding out " ..
                "in a vrykul building northwest of Nifflevar.\n\nWhen you're ready I'll place you on the " ..
                "back of one of our gryphons and zip you right to him!",
        },
        [11428] = {
            description = "You have been a great friend and ally to us, <name>. There is one more thing I " ..
                "must ask of you.\n\nYou have seen the corruption of the Twisted Glade and the beasts " ..
                "that dwell there. The blacksouled keepers will continue raising these abominations from " ..
                "the waters and soil of our glade unless we act against them.\n\nThe most powerful of the " ..
                "blacksouled keepers is known as Keeper Witherleaf. Slay him, <name>, and open the way " ..
                "for the redemption of the glade as you once redeemed my sisters.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 94000,
        },
        [11429] = {
            description = "I'm not about to put the fate of this mission into the hands of some untested " ..
                "scrub.\n\nNow, if you want to prove to me that you've got what it takes to carry out " ..
                "this mission, you'll need to do what I tell you.\n\nTake this battle standard and head " ..
                "over to Baleheim, directly north of here. Once you're at Baleheim, find the center of " ..
                "town and drop our flag. Fight off any vrykul dirt bags that attempt to take down our " ..
                "beloved flag and return to me once you've established Alliance dominance!",
        },
        [11430] = {
            description = "That was a fairly strong showing at Baleheim, <name>. Before you go off " ..
                "patting yourself on the back there's work to be done at Nifflevar.\n\nWe've located the " ..
                "vrykul responsible for the majority of the harpoon attacks on our frigates - goes by the " ..
                "name of Yavus. You'll find him in the main harpoon structure on the bluffs of Nifflevar, " ..
                "southeast of here.\n\nTrack him down and execute him for crimes against the " ..
                "Alliance!\n\nDo me proud, <name>!",
            rewardMoney = 47000,
        },
        [11432] = {
            description = "I've overheard what you've had to say with Father Levariol. Allow me to " ..
                "suggest that he's not having you go far enough.\n\nYou must also deal with the vrykul " ..
                "that lie dormant in the Waking Halls beneath Gjalerbron!\n\nI have no doubt that the " ..
                "rituals involved with awakening them are the key to their downfall. Most likely the " ..
                "necrolords have some device that you can use to bring the vrykul out of their dormant " ..
                "state prematurely.\n\nSurely such a disruption will prove fatal to the vrykul.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 47000,
        },
        [11433] = {
            description = "I've overheard what you've had to say with Greatmother Ankha. With all due " ..
                "respect, she's not having you go far enough.\n\nYou must also deal with the vrykul that " ..
                "lie dormant in the Waking Halls beneath Gjalerbron!\n\nI have no doubt that the rituals " ..
                "involved with awakening them are the key to their downfall. Most likely the necrolords " ..
                "have some device that you can use to bring the vrykul out of their dormant state " ..
                "prematurely.\n\nSurely such a disruption will prove fatal to the vrykul.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 47000,
        },
        [11434] = {
            description = "I've made my fortune by specializing in treasure that regular pirates don't " ..
                "appreciate: art, antiquities, collector's pieces.\n\nBlack Conrad's fleet sank south of " ..
                "here years ago. All the gold and jewelry was picked clean by divers, but two ancient " ..
                "relics remain there. One is a museum-quality Amani vase, the other is an eagle " ..
                "figurine.\n\nGo and retrieve them for me and I'll vouch for you with the other pirates. " ..
                "I'll even throw in something to make your underwater adventure a bit more manageable.",
        },
        [11436] = {
            description = "Navigating the steep bluffs of Howling Fjord can be nerve-racking! I've come " ..
                "up with a solution to ease that burden by utilizing vrykul technology and dwarven " ..
                "ingenuity. With just a few adjustments and some fine tuning I've created Icehammer's " ..
                "harpoon controller! Of course it hasn't been tested, but that's what you're here " ..
                "for!\n\nTake the controller to the big gun in Nifflevar and use it to launch yourself " ..
                "into Valgarde. Report your victory to Zorek. Oh yea, you can keep the controller.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [11443] = {
            description = "Hey... Uh... What's up? What are you doing down here?\n\nMe? Oh... Well, you " ..
                "see... I'm... Um... I'm trying to clean this place up! Orders from Keller himself! He " ..
                "says to me, \"Harry, I want you to put on a divin' bell and search the shipwrecks of " ..
                "Daggercap for OUR stuff...\"\n\nSay, maybe you could lend me a hand while you're down " ..
                "here. Throughout the bay here are all kinds of goodies, err, I mean supplies. Go out and " ..
                "bring me back whatever you find. Use this diving helm so you don't run out of air and " ..
                "die.",
            rewardMoney = 47000,
        },
        [11448] = {
            description = "It's all a bunch of cryptic nonsense! Even with this cipher I can't make heads " ..
                "or tails of these tablets. Admittedly, cryptography is not my strong point.\n\nYou'll " ..
                "need to take the cipher and tablets to our cryptographer, Stanwad. Unfortunately, I " ..
                "haven't heard from Stanwad in two weeks. He took a team of twenty scientists to the dig " ..
                "sites on the southeastern bluffs of the fjord and hasn't been heard from since. The best " ..
                "I can do is have McGoyver over there give you a lift with his flying machine.",
        },
        [11451] = {
            description = "Hi, I wrote a poem for my friend Caylee. She likes to hang out with the Aldor " ..
                "in Shattrath City. You know, in Outland?\n\nCould you take my poem to her? My mommy says " ..
                "I'm too young to go to Shattrath City!",
        },
        [11452] = {
            description = "A sheaf of parchment drops from the still hand of the overlord. Upon it you " ..
                "can discern the outline of the rituals that are taking place in the catacombs " ..
                "below.\n\nHowever, it appears that the queen of the vrykul, Angerboda, is having " ..
                "difficulty awakening King Ymiron. The ritual is taking place within the large chamber, " ..
                "known as the Winter's Terrace, on the north end of Gjalerbron.\n\nIf you hurry, you may " ..
                "be able to stop her before it is too late.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 100000,
        },
        [11453] = {
            description = "A sheaf of parchment drops from the still hand of the overlord. Upon it you " ..
                "can discern the outline of the rituals that are taking place in the catacombs " ..
                "below.\n\nHowever, it appears that the queen of the vrykul, Angerboda, is having " ..
                "difficulty awakening King Ymiron. The ritual is taking place within the large chamber, " ..
                "known as the Winter's Terrace, on the north end of Gjalerbron.\n\nIf you hurry, you may " ..
                "be able to stop her before it is too late.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 100000,
        },
        [11455] = {
            description = "Us pirates are known for many things, but hygiene isn't one of them. Most " ..
                "pirate ships be carrying five or six times as many rats as people.\n\nIt's no wonder all " ..
                "the bears on this island caught the rabies soon after we moved in. Long story short, the " ..
                "boss wants 'em all dead.\n\nIt just so happens I know a recipe for a bear musk fragrance " ..
                "popular among Stormwind nobles. We kill the bears and sell the musk. I see a fine " ..
                "business opportunity for us here. What say ye?",
            rewardMoney = 47000,
        },
        [11456] = {
            description = "We tuskarr rely mostly on our fish catch for sustenance. In times of great " ..
                "need, however, we will on occasion hunt land animals.\n\nThe nearby village of Iskaal " ..
                "was recently attacked by pirates and the survivors just keep pouring in.\n\nOur catch " ..
                "has been modest this week, but there are many shoveltusk on the island and their meat is " ..
                "plentiful.\n\nAid my people by hunting these great beasts and obtaining their meat.",
            rewardMoney = 47000,
        },
        [11457] = {
            description = "Issliruk, the spirit of war, is depicted as a silver eagle by my people. Our " ..
                "stories tell of how Issliruk fought against a hundred worgs to save his young.\n\nIt is " ..
                "time for us, too, to fight against our foes to save our brethren. We will need to craft " ..
                "new weapons. The horns of the frostwing chimaera that make their home in the snowy parts " ..
                "of the island are sharp and are easily crafted into spear tips. Bring me the best of " ..
                "these horns that you can find.",
            rewardMoney = 47000,
        },
        [11458] = {
            description = "The totem of Issliruk is ready, <name>, and for that I thank you. We must cast " ..
                "our peaceful ways for the time being and strike at those who've attacked our land and " ..
                "our kin.\n\nThe pirate slavers that raided Iskaal have lost their minds and slaughtered " ..
                "all their captives. Go to Iskaal, to the east of here and do what must must be done. " ..
                "Take this horn and call on my brethren should you need assistance.",
        },
        [11459] = {
            description = "Is like dis, mon. Ye be wantin' me 'elp spotting some craven bag-o-wire been " ..
                "cardin' da crew?\n\nYe gotta bring me a croaker, matey. Aft I an' I show ye who da " ..
                "blaggard be, mon. Nah, nah, croaker show ye. Ye'll ku fer yerself with yer own " ..
                "deadlights, yahso.\n\nBring us a carver yahso too, 'atsteppa. Galang, bucko.",
        },
        [11460] = {
            description = "The first and most important factor in falconry is the bond between the " ..
                "falconer and <his/her> bird. Trust must be earned by the master!\n\n<Hidalgo points to " ..
                "the falcons in the cage at his feet.>\n\nIf you are to earn their trust you will first " ..
                "need to fill their bellies.\n\nThe fjord rock falcon, as these birds are known, " ..
                "primarily eat grubs. Throughout the fjord you will find loose rocks that serve as " ..
                "breeding grounds for these grubs. Find a grub and return here to feed the falcons in the " ..
                "cage.",
        },
        [11464] = {
            description = "I heard you did a little work for Terry. I was hoping someone reliable would " ..
                "show up around these parts.\n\nSee, pirates love to gamble. They, however, do not love " ..
                "to pay their gambling debt.\n\nIf you're interested in collecting some coin on my " ..
                "behalf, I'd be willing to give you a cut.\n\nLet's start you out with an easy one. " ..
                "\"Silvermoon\" Harry's a bit of an eccentric, keeps all sorts of expensive blood elf " ..
                "knickknacks inside his tent - yet when I see him he always pretends to be broke. Get my " ..
                "gold.",
        },
        [11465] = {
            description = "I was leading a caravan here from Valgarde that was attacked by Dragonflayers. " ..
                "I was the only survivor of that ambush. Unfortunately, I couldn't make it back here with " ..
                "the cargo of fjord turkeys. This is the perfect opportunity for you to get your feet wet " ..
                "with your rock falcon.\n\n<Hidalgo hands you a cage.>\n\nTake this falcon cage and head " ..
                "west down the road leading out of this camp. Use the falcon to capture the loose turkeys " ..
                "and return here when you've gathered enough.\n\nRemember to feed the falcon!",
        },
        [11466] = {
            description = "Our next customer, Jack Adams, won't be the pushover that Harry was. He spends " ..
                "all day drinking with his friends, tough pirates all of them. Let's not use force this " ..
                "time, could get ugly.\n\nSee if you can use his drinking habit to your advantage. " ..
                "There's only so much alcohol someone can handle before passing out.\n\nMaybe one of the " ..
                "bar wenches will be of assistance. Once he's out, see if you can slip your hand into his " ..
                "pocket and get what's mine.",
            rewardMoney = 94000,
        },
        [11467] = {
            description = "You might've heard of Black Conrad, he's a famous pirate around these " ..
                "parts.\n\nWell, he had a thing for gambling on my fights. He had a thing for not paying, " ..
                "too.\n\nI'd love to collect, but trouble is... he's dead.\n\nI was about ready to write " ..
                "the whole thing off, when I came across this...\n\n< Taruk unfolds a map of the Isle of " ..
                "Spears with an X on a northeastern plateau.>\n\nHe hid his treasure on tuskarr land. I " ..
                "want you to get it. I'll be damned if I let that bilge sucker get away without paying.",
            rewardItems = {{34119, 1}, {199210, 1, "Northrend Adventuring Supplies"}},
        },
        [11468] = {
            description = "Do you feel the closeness, <name>? Surely you feel a true bond forming between " ..
                "you and your falcon. Would you believe me if I told you that when the time is right " ..
                "you'll be able to see through the eyes of your bird? Aye, it is the ultimate level of " ..
                "falconry.\n\nBut first you must hunt more! The bird must hone and quicken its reflexes. " ..
                "Send it against a more formidable opponent! The fjord hawks of the region make the tops " ..
                "of the trees around us their homes. They shall be your next target!",
        },
        [11469] = {
            description = "Yeah, I got to get the deck swabbed spotless afore Mad Jonah comes 'round. An' " ..
                "I ain't gonna do it on my hands and knees neither!\n\nProblem is, we're all outa soap. " ..
                "That's more your problem than mine though, mate. Being the newbie 'round here, I gots a " ..
                "special trip for ya to make.\n\nUp on the northwest coast of this island, there's a " ..
                "whole mess o' sea lions. Amongst the nearby ice floes you'll find the alpha bull, Big " ..
                "Roy. Bring me back his blubber and I'll magic-up the best soap ya ever seen!",
            rewardMoney = 47000,
        },
        [11470] = {
            description = "You are most definitely ready for the next step in falconry, <name>.\n\nTake " ..
                "your trained falcon east of here, to the vrykul hawk roost near the Stonewall Lift. From " ..
                "the roost you will send out your falcon to steal the eggs of the hawks. Their nests will " ..
                "be located in remote areas of the cliff walls surrounding the roost. Locate those nests " ..
                "and use your falcon to scavenge for the eggs!\n\nBeware the fjord hawk matriarchs, " ..
                "<name>. Should you come under attack, use your falcon's escape and soar abilities to " ..
                "flee!",
            rewardChoices = {{35859, 1}, {35860, 1}, {35861, 1}, {35862, 1}},
            rewardMoney = 94000,
        },
        [11471] = {
            description = "I know why you're here, <name>. You've been sent to kill our leader, Jonah " ..
                "Sterling.\n\nI'd like to offer my help. Jonah's leadership threatens our " ..
                "operation.\n\nAttacking the Horde and the Alliance fleets simultaneously? Suicidal. " ..
                "Trying to sell the tuskarr as slaves when they die days after leaving this climate? " ..
                "Disastrous.\n\nJonah's hideout is located inside a cave west of here. Bring me his " ..
                "spyglass as proof of the deed and my first action as leader will be to end all attacks " ..
                "against your allies.",
            rewardChoices = {{38258, 1}, {38259, 1}, {38257, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [11472] = {
            description = "The Northsea Pirates slaughtered the isles' alpha sea lion bull, Big Roy. They " ..
                "made soap from him to clean the decks of their ships!\n\n< Anuniaq sighs.>\n\nNow the " ..
                "sea lions won't mate. Help me to repopulate their numbers.\n\nThe reef bulls can be " ..
                "found at the Twin Shores to the southeast. They crave the tasty reef fish that can be " ..
                "found on the east and west sides of the isles.\n\nTake this net and gather enough fish, " ..
                "at least a dozen -- maybe more, to lure a bull across the strait to a reef cow.",
            rewardMoney = 102000,
        },
        [11473] = {
            description = "Our second in command, Annie Bonn, has been acting rather paranoid as of late. " ..
                "She seems sure we have an infiltrator in our ranks, can ye believe it?\n\nAnyhow, we " ..
                "have a foolproof way of uncovering rats around these parts. See, good ole' Zeh'gehn over " ..
                "here happens to be an authentic witch doctor. His family hails all the way from Zul... " ..
                "something or other.\n\nGo let him know that we're in need of his divination skills. I " ..
                "must warn ye, <name>, only one or two of us can understand anything Zeh'gehn says.",
        },
        [11474] = {
            description = "As usual, the real work is left up to me and my crew. Thankfully McSorf's team " ..
                "didn't die for nothin'. The cipher they recovered will help us crack the stuff we've " ..
                "found up here - that is if we can ever get back to it! Damned iron dwarves have sprung " ..
                "up like leaks all over the place and are now attemptin' to bury the sites! Can you " ..
                "believe it? Bastards want to bury our finds!\n\nAnyhow, talk to Walt over yonder. He'll " ..
                "get you started.",
        },
        [11475] = {
            description = "I've been studying this deactivated construct for days, <name>. I think I can " ..
                "create a reasonable facsimile of the golem that would have room inside to fit one " ..
                "passenger. The idea being that it would fool those iron dwarves and allow us to get " ..
                "inside Baelgun's.\n\nNow I'm not gonna be able to make anything with a hammer and poker. " ..
                "I need my tools! Unfortunately I left those behind at Ivald's Ruin when the iron dwarves " ..
                "first attacked. Get me my tools!\n\nIvald's Ruin is located far to the northeast.",
        },
        [11476] = {
            description = "Some of the pirates around here... we have our own special way of talking. " ..
                "Zeh'gehn has... many different special ways of talking... all mixed together.\n\nFrom " ..
                "what I can tell he wants a frog and a knife.\n\n\"Silvermoon\" Harry might have a knife " ..
                "on the cheap. There's frogs all over town, just grab one and bring it to him along with " ..
                "the knife.\n\nI'd hate to be in the poor critter's shoes, if you know what I mean.",
        },
        [11477] = {
            description = "Keep it down, <race>. These iron dwarves are quick on the trigger. Now don't " ..
                "let the activities down in the dig fool you. Those steel-skinned abominations aren't " ..
                "digging anything up! No sir - on the contrary - they're burying the site! For whatever " ..
                "whacked out reason, they don't want anyone finding this place.\n\nWhat kind of dwarf " ..
                "buries ancient relics and dig sites? I'll tell you what kind: the kind you kill with " ..
                "reckless abandon! Get in there and take 'em out!",
        },
        [11478] = {
            description = "I see that you haven't visited my brothers at the Explorers' League Outpost " ..
                "south of here. Why don't you do Donny a favor and deliver this message to Stanwad. He'll " ..
                "be interested to hear about the activities of the iron dwarves up here.\n\nLike I said, " ..
                "mount up and start heading south. You'll see the outpost right before you get to " ..
                "Baelgun's.",
        },
        [11479] = {
            description = "Croaker's spoken, matey. \"Crowleg\" Dan's on da ship yonder.\n\nBest go trace " ..
                "that blaggard, mon. Show'im dis set's not fe be crossed. Gaan back fe Terry when ye " ..
                "keelhaul 'is behind.",
        },
        [11480] = {
            description = "All the good work you've done for us hasn't gone unnoticed, <name>. Our second " ..
                "in command, the delightful Annie Bonn, is incredibly impressed with what you've done so " ..
                "far and wants to meet you.",
        },
        [11481] = {
            description = "By the naaru, I thank you, <race>, for your efforts.\n\nOur work is far from " ..
                "finished, however, and I must request that you undertake a critical mission - one as " ..
                "important as any I've issued.\n\nOur forces are spread thinly. To compound the strain, " ..
                "we've had to dispatch a contingent to Azeroth to investigate developments at the Sunwell " ..
                "Plateau.\n\nYou are needed there, <name>. Report to Larethor. Tell him that I wish we " ..
                "could spare more men.",
            rewardMoney = 4400,
        },
        [11482] = {
            description = "Hear me, <race>.\n\nDuty requires that you return to Azeroth. Every able " ..
                "person is to report to the Sunwell Plateau immediately.\n\nI'm afraid I have no more " ..
                "information to share, except this:\n\nYou'll be joining forces with the Aldor for this " ..
                "mission. Speak with a draenei by the name of Larethor when you arrive.\n\nApparently, " ..
                "the situation calls for us to set our differences aside and join forces.\n\nPrepare " ..
                "yourself, friend. This sounds serious.",
            rewardMoney = 4400,
        },
        [11483] = {
            description = "Tools? Check. Materials? Negative.\n\nIf we're going to build this thing, " ..
                "you're going to have to get me the materials.\n\nFirst things first, <name>. For the " ..
                "skeletal structure I'm going to need a large barrel from Nifflevar, some dark iron " ..
                "ingots from Valgarde, and industrial strength rope from Baleheim.\n\nNifflevar and " ..
                "Baleheim are vrykul towns northwest of here. Valgarde is located in Daggercap Bay, also " ..
                "to the northwest. Speak with McGoyver to get the ingots. He'll fly you back here once " ..
                "you're all done.",
        },
        [11484] = {
            description = "While the infrastructure for a piece of machinery like this is important, we " ..
                "can't underestimate the appearance of the construct. If we're to fool the iron dwarves " ..
                "the clone must be exact!\n\nI can make this happen.\n\nBring me a pristine shoveltusk " ..
                "hide from the shoveltusk of this region and steel ribbing from vrykul in Nifflevar or " ..
                "Baleheim to the northwest.",
        },
        [11485] = {
            description = "Alright, <name>; the time has come for you to climb inside this thing and " ..
                "learn how to use its basic abilities. When you're ready, get on the work bench and I'll " ..
                "get you situated inside the construct.\n\nYour first lesson is going to be using the " ..
                "construct's transportation system. You'll notice that the iron dwarves have set up " ..
                "special rune carvings around the dig site. Their constructs use those rune carvings to " ..
                "power up and fly from point to point. Try it with the rune carving I built here.",
        },
        [11489] = {
            description = "The most important part of your job while controlling the construct is the " ..
                "collection of data. I've placed an iron dwarf relic in the cart over yonder. It's the " ..
                "floating, lightning infused crystal.\n\nGet on the work bench and I'll put you back in " ..
                "the construct. Once you're back in the driver's seat, use the construct's data " ..
                "collection ability to pick up the test data.",
        },
        [11490] = {
            description = "Go to the terrace... use the orb.\n\n< Tyrith gasps for breath.>\n\nHurry... " ..
                "they must be stopped... before they can....\n\n< Tyrith dies.>",
            rewardMoney = 44000,
        },
        [11491] = {
            description = "You always gotta have a contingency plan in case your main plan backfires! " ..
                "That's why I've built in some anti-intelligence systems into the construct.\n\nYour " ..
                "shiny new ride might rouse some suspicion while you're at Baelgun's excavation site. " ..
                "That's what your bluff ability is for! Just use that any time you're confronted and " ..
                "you'll be safe from harm.\n\nTest it out on Lebronski by walking on his rug. Once he " ..
                "starts huffin' and puffin', use the bluff!\n\nGet on the work bench when you're ready to " ..
                "begin.",
        },
        [11494] = {
            description = "Your construct is ready to go. All abilities have been given a once over and " ..
                "I've programmed the machine to both comprehend and speak the language of the " ..
                "titans.\n\nTake the construct to Baelgun's Excavation Site, due south of here, and " ..
                "collect data from the lightning infused relics that litter the site. Remember to bluff " ..
                "any iron dwarves that suspect your construct to be a fake. And don't forget about rocket " ..
                "jumping from rune to rune to get around in there!\n\nGet on the table when you're ready!",
            rewardChoices = {{35844, 1}, {35846, 1}, {35848, 1}},
            rewardMoney = 141000,
        },
        [11495] = {
            description = "The cavern that we opened at Baelgun's was the one place that most steered " ..
                "clear of... Can't say I blame 'em. The sound of thunder shot out of that cave, <name>! " ..
                "Loud, booming thunder!\n\nI think near the end, it was abandoned by all. Bad, bad things " ..
                "happened to any that went in to explore - most never coming back.\n\nI want you to check " ..
                "that cave out while you're at Baelgun's. Explore around the titan statue inside and " ..
                "report back with your findings.",
            rewardChoices = {{35849, 1}, {35851, 1}, {35852, 1}, {35856, 1}},
            rewardMoney = 94000,
        },
        [11499] = {
            description = "<class>, today I ask the impossible. Today, you must obtain the signet ring of " ..
                "Kael'thas Sunstrider, lord of the blood elves!\n\nIt's true, the rumors of his death " ..
                "within Tempest Keep were ill-founded. He has appeared once more, this time at the " ..
                "Magisters' Terrace on the Isle of Quel'Danas. What he is doing there is a tale for " ..
                "someone else to tell you. What I know is that I have innumerable collectors interested " ..
                "in his princely ring, and I mean to acquire it for them.\n\nOr rather, I mean for you to " ..
                "do so.",
            rewardItems = {{29434, 1}},
            rewardMoney = 132000,
        },
        [11500] = {
            description = "It has been whispered to Mah'duun that the sisters of torment are to be sent " ..
                "back to the hells from which they sprang.\n\nMah'duun knows that these demons can be " ..
                "found at the Magisters' Terrace on the Isle of Quel'Danas.\n\nYou will do this thing to " ..
                "earn the bounty, or you will not.",
            rewardItems = {{29460, 1}},
            rewardMoney = 88000,
        },
        [11501] = {
            description = "Westguard needs to know what's going on here, <name>. I want you to personally " ..
                "deliver the news to Captain Adams.\n\nWhenever you're ready, let me know and I'll put " ..
                "you back in the construct for one final flight. It'll take you to Westguard Keep, but " ..
                "more than likely blow up in the process.\n\nIt's been a pleasure...",
            rewardChoices = {{35857, 1}, {35858, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [11502] = {
            description = "We are not a warlike race, <race>. However when war comes to our lands, we do " ..
                "not run away from it.\n\nThe Alliance and the Horde wage war in the city of Halaa, to " ..
                "the northwest. We do not know what the blood elves are scheming, but any victory for the " ..
                "Horde would be disastrous. The history between our people and the orcs is one of " ..
                "bloodshed and betrayal.\n\nGo and slay the enemy in Halaa and you will be rewarded in " ..
                "coin, honor and renown.",
            rewardMoney = 44000,
        },
        [11503] = {
            description = "Our ancient enemy, the draenei, have returned with powerful allies. They wage " ..
                "war in Halaa, southwest of here.\n\nWe cannot allow them a victory there as Garadar " ..
                "would be next without a doubt.\n\nGo and slay those who would aid our ancient enemy.",
            rewardMoney = 44000,
        },
        [11504] = {
            description = "The path east of us is a primary hunting trail of the tuskarr. At least that's " ..
                "what it used to be...\n\nMore recently our hunters have been returning to Kamagua " ..
                "claiming that the dead have risen and are out for blood! That is what has brought my son " ..
                "and me here. Elder Atuik asks that we find resolution in the bluffs.\n\nWill you assist " ..
                "us in our time of need? I seek heroes willing to brave the perils of Shield Hill, " ..
                "southeast of here. Search the desecrated graves for clues and return your findings to me.",
        },
        [11505] = {
            description = "Auchindoun's spirits have no stake in the conflict between the Alliance and " ..
                "the Horde, but incurring their favor will give our side an edge in the " ..
                "region.\n\nAncient custom directs the living to pay their respects at spirit towers in " ..
                "the Bone Wastes - though only at specific times of the day. If you can help secure a " ..
                "tower during these times, you will have helped bring the spirits to our side.\n\nShould " ..
                "we succeed in gaining the spirits' favor, they will grant us a boon that will aid us in " ..
                "our endeavors.",
            rewardMoney = 106000,
        },
        [11506] = {
            description = "The draenei might be our enemies, but the spirits of their ancestors in " ..
                "Auchindoun are restless and have no allegiance.\n\nThe draenei's custom required them to " ..
                "pay their respects at spirit towers at various times during the day. If you can help " ..
                "secure a tower during these times, you will help the spirits return to peace in " ..
                "Auchindoun.\n\nThe Alliance will try to capture the towers in order to secure the dead's " ..
                "favor. We must ensure that our side succeeds instead.",
            rewardMoney = 114000,
        },
        [11507] = {
            description = "<Orfus bundles up the clues you brought him.>\n\nMy people are bitterly " ..
                "entrenched in a war with the Northsea Freebooters. If any tuskarr could help us in our " ..
                "quest to right the wrongs of the pirates, it will be Elder Atuik of Kamagua. You must " ..
                "take these clues to him at once.\n\nTo get to Kamagua you must take the Ancient Lift, " ..
                "behind me. Take the lift directly to Kamagua and find Elder Atuik.",
        },
        [11508] = {
            description = "The pirate thieves have set up port at Scalawag Point, far to the south. " ..
                "Unfortunately, they have fortified their camp with many deadly defenses.\n\nThere is " ..
                "someone that might be able to assist us in infiltrating Scalawag.\n\nA pirate mercenary " ..
                "by the name of Grezzix Spindlesnap recently came to our village in search of food and " ..
                "shelter. In exchange he gives us information about our enemies and feeds them " ..
                "misinformation about our attack plans. Seek him out at his ship just off the coast here " ..
                "- southwest.",
        },
        [11509] = {
            description = "The Northsea Freebooters all fear and respect Grezzix. I'm thinking they " ..
                "recognize my special talents and envy my amazing ship. All you need to do is tag along " ..
                "with my cabin boy, Lou, and you'll be in like... In like tin. Pirates love tin.\n\nJust " ..
                "talk to Lou when you're ready to go and he'll take you to Scalawag.\n\nOh yea, you'll " ..
                "want to talk to \"Silvermoon\" Harry first. He'll have more information on the stuff " ..
                "they pilfered. Just watch what you say around him. He's a freak... crazy for blood elves.",
        },
        [11510] = {
            description = "One of the first things Jonah Sterling did after he went crazy was to take my " ..
                "prized sin'dorei scrying crystal and feed it to the bane of my existence, \"Scoodles\" " ..
                "the orca.\n\nNo I didn't name the damned thing. I just know that she swims out past the " ..
                "ships directly southeast of Scalawag. Kill that overinflated goldfish and rip out my " ..
                "beautiful sin'dorei crystal from its stomach.\n\nDo this and we can get down to business.",
        },
        [11511] = {
            description = "Those artifacts are cursed and you'd be crazy to go looking for them, <race>. " ..
                "I know for certain that anyone that's come into direct contact with any of those items " ..
                "has either gone mad or been killed.\n\nTake that staff, for example. Last I heard the " ..
                "ship that held it was abandoned and left to rot on the coast of the Isle of Spears, " ..
                "north of here.\n\nIf you want that thing, check the ship's hold.\n\nWhatever you do, " ..
                "don't bring that staff back here! And steer clear of Abdul! He'll tear your heart out.",
        },
        [11512] = {
            description = "Some say Jonah was never quite right in the head, but I know the truth. It was " ..
                "the heart. That damned frozen heart! I saw the change in him the second he pulled it " ..
                "from the grave. I could see the blood freeze in his veins... It was then that the " ..
                "madness truly took over.\n\nHe left us to hole up in his cave on the north side of this " ..
                "island. Last I heard he had thrown the heart in the back of his bear den. Too little, " ..
                "too late...\n\nI'll kill you myself if you even think about bringing that heart back " ..
                "here!",
        },
        [11514] = {
            description = "We must maintain the energy to our portal or it will collapse. The mana cells " ..
                "that the ethereals at Bash'ir Landing have hidden will continue to serve our purposes. " ..
                "The landing sits atop the northwestern corner of the Blade's Edge Mountains, far to the " ..
                "north.\n\nRemember, acquire a phase device from one of the ethereals and then use it to " ..
                "locate the smuggled goods.\n\nJust be cautious of the phase wyrms that they use to guard " ..
                "the mana cells.",
            rewardItems = {{35232, 1}},
            rewardMoney = 44000,
        },
        [11515] = {
            description = "When Kael's forces retreated through that portal, his most loyal lackeys were " ..
                "rewarded with an abominable gift. They stayed behind and gorged themselves on the blood " ..
                "of demons for days.\n\nThe blood has changed them, given them new powers. It will also " ..
                "prove their undoing.\n\nObtain blood samples from other demons. Use them to power this " ..
                "fel siphon and deprive these arrogant fools of their new powers. Slay them in their " ..
                "weakened state and return to me.",
            rewardChoices = {{30809, 5}, {30810, 5}},
            rewardMoney = 44000,
        },
        [11516] = {
            description = "We have to shut down this gateway to stop Legion reinforcements to the Isle of " ..
                "Quel'Danas.\n\nTake these embers, they contain one of my creations: a living flare. It " ..
                "is designed to act as a powerful destructive force - as long as it has been provided " ..
                "enough energy.\n\nFind the fel sparks that wander the area and slay them near the living " ..
                "flare. The flare will grow in power each time, until it becomes unstable.\n\nOnce you've " ..
                "achieved this bring the flare to the gateway. It will know what to do.",
            rewardItems = {{35232, 1}},
            rewardMoney = 44000,
        },
        [11519] = {
            description = "If you listen real close you can hear cannon fire coming from the northeast. " ..
                "That's Captain Ellis 's ship, Sister Mercy. Thing is, Ellis and his entire crew were " ..
                "killed 'bout a month ago.\n\n<Harry nods.>\n\nGhost ship...\n\nIf it's info you be " ..
                "wantin' 'bout the shield, Ellis is the man to ask.\n\nSister Mercy docks on the small " ..
                "island between here and Sorlof's Strand to pick up more souls for the ship's crew 'bout " ..
                "once every five minutes. There be no shortage of souls 'round these parts...",
        },
        [11521] = {
            description = "My stocks are presently sufficient, but I'll need plenty of razorthorn roots " ..
                "to keep up with the demand.\n\nCollecting the roots is difficult, but I know a special " ..
                "method of extraction.\n\nUsing the glands of the Razorthorn flayers, one can control a " ..
                "ravager there and use it to expose a root.\n\nTo find the roots, travel to Outlands and " ..
                "fly northeast from Shattrath until you reach Razorthorn Rise.\n\nReturn to me, <name>, " ..
                "once you have collected five of the roots.",
            rewardItems = {{35232, 1}},
            rewardMoney = 44000,
        },
        [11523] = {
            description = "We've succeeded in reactivating the crystal wards around the sanctum, but why " ..
                "stop there? We'll build defenses around the other structures, but the Wretched are " ..
                "stubborn and continue to steal power from the crystal wards.\n\nHunt them down and get " ..
                "the mana remnants they carry. Use the remnants to energize the sanctum wards; the safety " ..
                "of our operation depends on it.",
            rewardMoney = 34000,
        },
        [11525] = {
            description = "My plan to replace the damaged crystals on the erratic sentries has been a " ..
                "success. We've managed to take the Sun's Reach Sanctum with their help.\n\nI've crafted " ..
                "new crystals that will bring more of them under our control; place them inside the hulls " ..
                "of defeated sentries. We'll deploy them to other locations once they're converted.",
            rewardMoney = 34000,
        },
        [11526] = {
            description = "We sent one of our operatives to investigate the fel portal in the middle of " ..
                "Dawning Square, south of here. She never returned.\n\nTake this scroll we found on one " ..
                "of the enemy corpses. We believe it will grant you access through the portal. Once " ..
                "through, find Magistrix Seyla and aid her in any way you can.",
            rewardMoney = 34000,
        },
        [11527] = {
            description = "Aye, we got problems, matey. Me gunners have mutinied! M'n'the crew up top be " ..
                "tryin' to kick Sorlof's keester while dealin' with the mutinous gunners " ..
                "down'blo.\n\nYe're gonna have to go down'blo and deal with those mutinous sea dogs and " ..
                "take their blastin' powder for the big'un o'er on the poop deck.\n\nWith ye mannin' the " ..
                "big'un, Sorlof is sure to die and give up the booty!",
        },
        [11529] = {
            description = "Me crew is gonna get the big'un all primed an'ready for ya, matey. She's " ..
                "restin' snuggly on the bow, o'er on the other side of the ship. Go'n man it and be ready " ..
                "to fire when Sorlof is in our sights!\n\nOnce we take that landlubber down, ye'll have " ..
                "to recover the booty for us, seein' as how we can't leave the damned ship! Bring that " ..
                "booty back to me and ye'll get your cut - the shield...",
        },
        [11530] = {
            description = "Here's yer shield. Me hopes it doesn't curse ye like it did me'n'me crew. Ye " ..
                "don't have to go home, but ye can't stay here... I be certain that thar be some that " ..
                "would be interested in getting' it back.\n\nNow get that thing off me ship!",
        },
        [11531] = {
            description = "This strange engine part doesn't look like it fits in a steam pump, much less " ..
                "anything else you've seen. Perhaps K. Lee Smallfry might know something about it.",
            rewardMoney = 29500,
        },
        [11533] = {
            description = "We've taken the armory from the enemy thanks to our aerial attacks against the " ..
                "Legion's forces in the Dead Scar.\n\nAs a matter of fact, it's gone so well that we're " ..
                "going to continue our air strikes against them. Take these arcane charges and use them " ..
                "against their forces.\n\nTalk to Ayren Cloudbreaker at the Sun's Reach Harbor when " ..
                "you're ready for flight.",
            rewardMoney = 34000,
        },
        [11536] = {
            description = "Now that we have an anvil, I can really get to work.\n\nNo matter how many " ..
                "supplies we receive, I'll always be able to put the Darkspine Iron Ore to good use. " ..
                "We'll need a constant supply of weapons and armor if we're to be successful " ..
                "here.\n\nThere are a group of naga on the coast to the east of here. They're collecting " ..
                "ore and placing it in chests for shipment to the Legion. Relieving them of their ore " ..
                "will help our efforts in more ways than one....",
            rewardMoney = 44000,
        },
        [11537] = {
            description = "We must continue to defeat and demoralize the armies of the Legion.\n\nThe " ..
                "emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion " ..
                "positions. The enemy rallies around them for they fear them more than they fear " ..
                "us.\n\nToday we will change that. Take this banner and slay the demons of the Legion. " ..
                "When you meet the emissary, slay and impale him.",
            rewardMoney = 44000,
        },
        [11540] = {
            description = "We've driven the Dawnblade army out of the Sun's Reach Harbor. Sun's Reach is " ..
                "ours in its entirety. Yet somehow... I'm not entirely satisfied.\n\nI want you to go to " ..
                "Dawnstar Village, west of here, and slay any surviving Dawnblade combatants. They sealed " ..
                "their fate when they followed Kael to this place.",
            rewardMoney = 44000,
        },
        [11541] = {
            description = "The naga have taken the Greengill Coast to the southeast. Their females, the " ..
                "Darkspine sirens, are using magic to enslave the indigenous murlocs.\n\nIt's my " ..
                "responsibility to see to it that whatever the naga are up to over there is disrupted. " ..
                "That's where you come in.\n\n<class>, I want you to get the controlling orbs from the " ..
                "female naga and throw them near the Greengill slaves, breaking the orb and setting the " ..
                "murlocs free.\n\nMy guess is that the murlocs will be incensed and turn on their masters.",
            rewardMoney = 44000,
        },
        [11543] = {
            description = "We've managed to capture Sun's Reach in its entirety. Unfortunately a fleet of " ..
                "Dawnblade reservists is on its way to take back the harbor.\n\nTake this oil and secure " ..
                "a dragonhawk from Ayren Cloudbreaker. You should be able to fly within reach of the " ..
                "ships' sails; once you're close enough, set them on fire.\n\nLand in one of the ships " ..
                "and attack the reservists. With their ship sails on fire they won't be able to mount " ..
                "much of a defense.",
        },
        [11544] = {
            description = "The Ata'mal Terrace in eastern Shadowmoon Valley is holy to the draenei, but " ..
                "is now overrun by fel orcs. They have dug up the special ore from that place and created " ..
                "corrupted weapons and armor.\n\nI need the armaments to form an alloy with the naga ore. " ..
                "Our anchorites have blessed my anvil with the ability to cleanse them.\n\nRetrieve the " ..
                "armaments from the Shadowmoon chosen, slayers and darkweavers. Return them here, " ..
                "breaking down and purifying them upon my anvil, and then hand me the cleansed results.",
            rewardChoices = {{34538, 1}, {34539, 1}},
            rewardMoney = 88000,
        },
        [11546] = {
            description = "Welcome, <name>.\n\nThere are a number of ways I can assist you in your " ..
                "efforts here.\n\nFor example, I've recently discovered a recipe for a unique " ..
                "elixir.\n\nThe bloodberry grows wild in many regions of Azeroth and has long been " ..
                "considered nothing more than a nuisance. I've learned though, that when exposed to the " ..
                "Sunwell's power this plant takes on special properties that can be distilled and imbibed " ..
                "to magnify one's abilites.\n\nBring me a sample from the nearby bushes and I'll show you " ..
                "what I mean.",
            rewardItems = {{34537, 1}},
            rewardMoney = 44000,
        },
        [11548] = {
            description = "We've built a memorial to honor those slain in battle. It's but a small " ..
                "consolation to the families that lost their loved ones.\n\nI am taking up a collection " ..
                "to aid the orphans and spouses of our war heroes. If you can spare a small donation it " ..
                "would go a long way.",
        },
        [11549] = {
            description = "You've done so much for us, <name>. We greatly appreciate your " ..
                "assistance.\n\nYou might have noticed Anchorite Ayuri's efforts outside. She has a big " ..
                "heart and is very convincing, but the donations do not quite add up to what she had " ..
                "expected.\n\nIf you were to make a large contribution to her cause, I will make sure " ..
                "that word of your deeds in this war spreads far and wide. What do you say?",
        },
        [11550] = {
            description = "Despite our best efforts, Kael'thas's sinister plans have been carried out. " ..
                "The Sunwell has been re-ignited in preparation for the Deceiver's arrival.\n\nThe object " ..
                "that stands before me and below A'dal is a representation of the current status of the " ..
                "Sunwell's defenses. Mighty barriers have been raised, stymieing our attacks against the " ..
                "inner chambers. If ever there were a time that our world needed assistance, it would be " ..
                "now.\n\nReport to Archmage Ne'thul at the Isle of Quel'Danas, north of Quel'Thalas.",
        },
        [11554] = {rewardChoices = {{34583, 1}, {34584, 1}}},
        [11555] = {rewardChoices = {{34587, 1}, {34585, 1}}},
        [11556] = {rewardChoices = {{34592, 1}, {34593, 1}}},
        [11557] = {rewardChoices = {{34595, 1}, {34594, 1}}},
        [11559] = {
            description = "Now that you can speak with the Winterfin, it is time for you to let them get " ..
                "to know you. One of the best ways to do that is to conduct business with them.\n\nThe " ..
                "murlocs prize clams over any other object and their only surviving merchant is " ..
                "Ahlurglgr. If I were you, I'd collect a handful of Winterfin clams and give them to him " ..
                "as a gift.\n\nThe clams can be found all over down in the trench, as well as across it " ..
                "in the Winterfin village and their caverns.",
            rewardMoney = 47000,
        },
        [11560] = {
            description = "Oh good, you're back!\n\nWhen the landslide at the village across the water " ..
                "exposed the caverns, a malevolent lobstrok, known as Claximus, came out of the caves and " ..
                "stole the Winterfin tadpoles away.\n\nSomething happened to all of the murlocs that " ..
                "followed him in there, and when they re-emerged, they were under his " ..
                "control.\n\n<class>, you must swim across the waters and rescue the Winterfin tadpoles " ..
                "in the village and caverns.\n\nThe future of the Winterfin tribe depends upon you!",
            rewardChoices = {{37034, 1}, {37508, 1}, {37558, 1}, {37527, 1}},
            rewardMoney = 47000,
        },
        [11561] = {
            description = "Our brothers and sisters across the water are now our mortal enemies. They " ..
                "have kidnapped our tadpoles, driven us out of our village, and killed more of us than I " ..
                "can count.\n\nProve yourself, <race>! Swim across the rift and slay them!\n\nDespite the " ..
                "favor that the new king has shown you, only then will we consider accepting you here. " ..
                "Fail to do so, and you might as well leave now and never return!",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 47000,
        },
        [11562] = {
            description = "I have something embarrassing to admit: I'm being blackmailed!\n\nMrmrglmr " ..
                "agreed to clean some of my things, and got hold of my spare murloc costume. He's " ..
                "threatening to reveal my true nature to the other murlocs.\n\nI need not explain to you " ..
                "what a disaster that would be! Besides, I have a plan that's going to require that we " ..
                "get that costume back.\n\nPlease, <name>, go to Mrmrglmr at the other end of the Retreat " ..
                "to the north and do whatever he asks of you.",
        },
        [11563] = {
            description = "If your pathetic little eyes were any good, you'd see that we're being " ..
                "slaughtered by the orcas to the north in the bay!\n\nAssuming your precious night elf " ..
                "king wants his spare costume back, I think you'll do me a favor and bring back the head " ..
                "of the king of the orcas, Glrggl: he who swims against the tides of fate -- eradicating " ..
                "the hope of life for all those who hear the siren song of death upon the waves!\n\nBe " ..
                "quick about it, <race>, Winterfin murlocs are losing their lives even as we waste time " ..
                "talking!",
            rewardMoney = 47000,
        },
        [11564] = {
            description = "Word is, strange <race>, that you might be going after the king of the orcas, " ..
                "Glrggl.\n\nThat's all fine and good, but if you want to taste the stew that makes life " ..
                "worth living, then you'll bring me back the succulent blubber of the orcas that swim in " ..
                "Glimmer Bay.\n\nHurry... I have quite a bit of cutting to do on this carcass if you want " ..
                "to reap the benefits of your efforts.",
            rewardItems = {{39691, 20}, {199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 47000,
        },
        [11565] = {
            description = "Very well, your king's secret is safe with me as long as he continues to help " ..
                "us against our enemies.\n\nHere, take this to him. I cleaned it up nicely, though I have " ..
                "no idea why he needs a second disguise.\n\nMaybe he has something in mind for you?",
        },
        [11566] = {
            description = "The time has come to put an end to this unnatural situation, <name>. For the " ..
                "Winterfin murlocs to have a chance at a future, Claximus must die!\n\nI want you to take " ..
                "my spare murloc suit and enter the Winterfin Caverns under the pretext of surrender. " ..
                "With the white flag in hand, the murlocs won't attack you.\n\nYou'll find him in the " ..
                "southwestern most corner of the caverns. Once you get close enough, deal with Claximus. " ..
                "Bring me one of his claws as proof that the grisly deed has been done.",
            rewardChoices = {{37215, 1}, {37392, 1}, {37426, 1}, {37506, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 100000,
        },
        [11567] = {
            description = "I was on the vessel that was bringing in the armor. We'd just boarded the ship " ..
                "and were headin' back here when we were attacked by a Forsaken destroyer.\n\nThey " ..
                "boarded our ship, took all the booty for themselves, and then sunk her.\n\nThat was the " ..
                "last I'd seen of that armor. If you want, you can take my bomber from Scalawag to the " ..
                "dreaded isle that the destroyer be docked. Talk to my woman, Alanya, outside. She'll get " ..
                "you on the bomber.\n\nIf you manage to find the stuff, don't you dare bring it back!",
        },
        [11568] = {
            description = "<Orfus hands you a satchel.>\n\nWithin this satchel are the artifacts that you " ..
                "recovered. Locate the burial mounds of Shield Hill, far to the southeast, where the " ..
                "items were originally stolen from and return the artifacts. It is my hope that this " ..
                "gesture will quell the spirits that now haunt our hunting grounds.\n\nBe strong, " ..
                "<name>...",
        },
        [11570] = {
            description = "The lock on my cage doesn't look too solid, but I'm not foolish enough to try " ..
                "to leave without assistance.\n\nWill you help me safely get out of these caverns? " ..
                "There's no time to waste, <race>.\n\nWhen you get back to the retreat, please let the " ..
                "king know that I'm okay. He's sure to give you a reward.",
            rewardChoices = {{37036, 1}, {37039, 1}, {37041, 1}, {37042, 1}, {37044, 1}, {37046, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 47000,
        },
        [11571] = {
            description = "To help, you must learn how to speak the Winterfin dialect. We'll work with " ..
                "the forces of nature and magic to do that.\n\nTake this empty conch shell. At the bottom " ..
                "of the watery trench below exists Scalder, an elemental of air and watery fury.\n\nOnce " ..
                "she is defeated, use the conch upon her remains to capture her magical steam. Return the " ..
                "full conch to me, and I'll imbue my knowledge of the Winterfin tongue into " ..
                "you.\n\nLuckily, a friend taught me a water breathing spell, which I will cast upon you.",
            rewardMoney = 47000,
        },
        [11572] = {
            description = "Return to Elder Atuik at Kamagua. He and the rest of my people must be warned " ..
                "of this impending doom that approaches from the sea.\n\n<Orfus shivers.>\n\nUse the " ..
                "Ancient Lift to reach him. Please hurry!",
            rewardChoices = {{36874, 1}, {36872, 1}, {36871, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 141000,
        },
        [11573] = {
            description = "Hail, traveler. I am Lunk-tusk of the Kalu'ak. We are known as tuskarr to your " ..
                "people. My partner and I were recently sent up to investigate strange happenings along " ..
                "one of our hunting trails. It was when we approached the graveyard known as Shield Hill " ..
                "that we were attacked by the undead. I was lucky to make it to this camp, but I am " ..
                "uncertain as to what became of Orfus.\n\nWe parted ways at the Ancient Lift, southeast " ..
                "of here along the cliff edge. Will you go see if he is ok?",
        },
        [11574] = {
            description = "I told them all that I remember. Why don't they believe me?\n\nI was gathering " ..
                "herbs by the rift. They came from nowhere, dark wizards with magical beasts - I was " ..
                "surrounded!\n\nA magical box appeared above me, opened up and pulled me inside. Just as " ..
                "it began to close around me, my rescuers swooped in on the backs of red drakes. It was " ..
                "breathtaking!\n\nI never thanked them for saving me. Please, <class>, find them, and " ..
                "pass on my gratitude.",
            rewardMoney = 24000,
        },
        [11575] = {
            description = "I told them all that I remember. Why don't they believe me?\n\nI was gathering " ..
                "herbs by the rift. They came from nowhere, dark wizards with magical beasts. I was " ..
                "surrounded!\n\nA huge magical cube appeared above me. It opened up and pulled me inside. " ..
                "I swear it's true!\n\nJust as it began to close around me, my rescuers swooped in on the " ..
                "backs of drakes - It was amazing! My captors scattered and I was able to escape.\n\nI " ..
                "never thanked them for saving me. Please, <class>, if you see them, pass on my gratitude.",
            rewardMoney = 24000,
        },
        [11576] = {
            description = "Greetings, <race>. I am Garren of Dalaran.\n\nNot long ago, the rift was a " ..
                "peaceful place - geothermally speaking at least.\n\nRecently though, earthquakes have " ..
                "occurred with alarming frequency and scars in the earth have appeared, exposing unique " ..
                "energy fields of chaotic power.\n\nMy mission here is to chart and monitor these " ..
                "anomalies. My instruments indicate that another has appeared on the cliff face to the " ..
                "southwest.\n\nTake this device with you and use it when you locate the new disruption.",
            rewardMoney = 37000,
        },
        [11582] = {
            description = "Did you feel that?! That was just an aftershock... you should've been here a " ..
                "few minutes ago!\n\nI'm afraid I must call upon your services again. My instruments " ..
                "indicate that there is an immense disruption just west of here, far beneath the water's " ..
                "surface.\n\nJust as before, I need you to take the arcanometer and capture the anomaly's " ..
                "data.\n\nI'll cast a spell that will enable you to breathe underwater. If it wears off " ..
                "before you find it, come let me know and I'll renew its effects.",
            rewardMoney = 37000,
        },
        [11585] = {
            description = "Throm-Ka, <race>! Welcome to Warsong Hold. My heart swells with pride to see " ..
                "that such a distinguished hero of the Horde has answered the call of duty!\n\nThis " ..
                "impregnable fortress is a testament to the tenacity of the Horde. Through much we have " ..
                "battled to establish this foothold in Northrend. It is from here that our journey to " ..
                "Icecrown begins and it is through the leadership of the son of Hellscream that we will " ..
                "succeed!\n\nGarrosh awaits your arrival below.\n\nLok'tar ogar!",
        },
        [11586] = {
            description = "Throm-Ka, <race>! Welcome to Warsong Hold. My heart swells with pride to see " ..
                "that such a distinguished hero of the Horde has answered the call of duty!\n\nThis " ..
                "impregnable fortress is a testament to the tenacity of the Horde. Through much we have " ..
                "battled to establish this foothold in Northrend. It is from here that our journey to " ..
                "Icecrown begins and it is through the leadership of the son of Hellscream that we will " ..
                "succeed!\n\nGarrosh awaits your arrival below.\n\nLok'tar ogar!",
        },
        [11587] = {
            description = "Greetings, <class>. I am Donathan, a loyal representative of " ..
                "Dalaran.\n\nForgive my abruptness, but we find ourselves in the midst of a crisis. Mages " ..
                "all across Azeroth are being abducted and I have been authorized to conscript anyone " ..
                "able to assist in the unraveling of this mystery.\n\nThe camp just south of ours is " ..
                "where our investigation begins. I call upon you to rescue one of the imprisoned mages " ..
                "held there. You must obtain a key from one of the mage hunters and use it to open an " ..
                "arcane prison.",
            rewardMoney = 47000,
        },
        [11590] = {
            description = "<name>, we have a situation.\n\nI've just learned that one of our archmages en " ..
                "route from Dalaran has gone missing. Naturally, we suspect the mage hunters are behind " ..
                "her disappearance.\n\nTime is clearly of the essence. We must know what has become of " ..
                "Lady Evanor at once if we are to have any hope of rescuing her.\n\nTake this device. " ..
                "Return to Beryl Point and use it on a Beryl sorcerer when he is near death. It should " ..
                "bind him long enough for you to bring him here for questioning.",
            rewardMoney = 47000,
        },
        [11591] = {
            description = "That dimwitted cur, Steeljaw, tried to take our caravan of supplies on a " ..
                "shortcut through a taunka graveyard!\n\nWe just struck up relations with them!\n\nNow " ..
                "the caravan lies in ruins, overrun by the taunka spirits that rose out of their graves " ..
                "as he was trampling them.\n\nHead south and see if you can salvage the situation, " ..
                "<class>. I sent Grunt Ragefist and a few others down there with him to help out.\n\nWhy " ..
                "don't you see if you can lend a hand.",
        },
        [11592] = {
            description = "One of your orcs named Steeljaw tried to save some time by taking a shortcut " ..
                "through our burial grounds. This had better not be how your Horde normally acts, <race>, " ..
                "or you will find the taunka to be the end of you!\n\nBut, you look as if you want to " ..
                "help fix this situation. Good!\n\nSteeljaw's cursed spirit now haunts this place and " ..
                "disturbs the remains of my ancestors. We must put an end to him!\n\nIf we live through " ..
                "this, tell your Overlord Bor'gorok at the outpost to the north.\n\nAre you with me?",
            rewardChoices = {{37271, 1}, {37393, 1}, {37425, 1}, {37557, 1}},
            rewardMoney = 100000,
        },
        [11593] = {
            description = "Our fallen deserve a hero's funeral, but we cannot bury them here on sacred " ..
                "taunka ground.\n\nI'll not ask you to drag their bodies back here, but take this and " ..
                "head further into the cemetary. When you come across our dead caravan guards and " ..
                "workers, put them to the torch.\n\nHonor our dead, <class>!",
            rewardMoney = 47000,
        },
        [11594] = {
            description = "Force-Commander Steeljaw's idiocy caused this mess. What was he thinking " ..
                "taking a caravan through a taunka burial mound?\n\nStill, what's done is done. Now it is " ..
                "up to us to deal with the consequences.\n\nOverlord Bor'gorok asked me to help " ..
                "Longrunner Proudhoof in any way that I can. The longrunner has asked that we lay to rest " ..
                "the spirits of his ancestors.\n\nWhat do you say, <class>? Are you <man/strong> enough " ..
                "to handle such a simple task?",
            rewardMoney = 47000,
        },
        [11595] = {
            description = "Hellscream has the weight of the Horde upon his shoulders. Do not be dissuaded " ..
                "from your duties because of his temperament, <name>.\n\n<Saurfang nods.>\n\nDid you " ..
                "think that I would forget the name of a hero of Orgrimmar? It is not every day that I " ..
                "have the pleasure of putting the head of Nefarian on a pike!\n\nThe Scourge have begun " ..
                "their assault upon this fortress. Our soldiers steady the line, but are in desperate " ..
                "need of backup. Report to Razgor. He is stationed directly outside of Warsong Hold.",
        },
        [11596] = {
            description = "Do not let Hellscream dissuade you from your duties as a soldier of the Horde, " ..
                "<race>. He bears a terrible burden in these frozen wastes, with the outcome of his " ..
                "charge resulting in victory over the Scourge or the extinction of all life on Azeroth. " ..
                "It is for this reason that we require your strength and wisdom.\n\nThe Scourge have " ..
                "begun their assault upon this fortress. Our soldiers steady the line, but are in " ..
                "desperate need of backup. Report to Razgor. He is stationed directly outside of Warsong " ..
                "Hold.",
        },
        [11597] = {
            description = "It seems that we always meet in the direst of circumstances, Scarab Lord. Were " ..
                "you not saving the world from certain destruction the last time we met?\n\n<Saurfang " ..
                "chuckles.>\n\nYour assistance is most welcome in Northrend, despite what the young " ..
                "chieftain might say.\n\nIf we had even a dozen more soldiers with your power, we would " ..
                "be sitting in Orgrimmar right now, hunched over a warm fire.\n\nReport to Overlord " ..
                "Razgor, right outside the main entry to Warsong Hold, to the south.",
        },
        [11598] = {
            description = "While Warsong is protected by 10 feet of steel and stone on all sides, this " ..
                "quarry is soft and primed for attacks by the Nerubians.\n\n<Razgor points " ..
                "west.>\n\nBeyond this quarry stand thousands of Scourge, awaiting orders to attack. " ..
                "Should the Nerubians take down our inner defenses, we will be overrun by the undead " ..
                "legions of Arthas.\n\nWe can't let that happen - which is why you're going on the " ..
                "offensive and slaughtering the Nerubians in the quarry.\n\nBlood and thunder, soldier! " ..
                "Take 'em both with you.",
        },
        [11599] = {
            description = "I recently received word from William Allerton, a family friend, that my " ..
                "brother enlisted here in Valiance Keep on the same day he did. Thing is... my brother's " ..
                "been dead for years.\n\nI sold everything I owned to come looking for Thassarian, only " ..
                "to be stonewalled by the local bureaucracy. I've even been threatened with arrest if I " ..
                "keep snooping around.\n\nI need someone in the good graces of the higher-ups... someone " ..
                "like you. If you can help me, I heard that William's stationed at the Farshire mine.",
        },
        [11600] = {
            description = "William's neck has been cut by a sharp object.\n\nFurther inspection reveals a " ..
                "single clue to bring to Leryssa - an enlistment card bearing the name of William " ..
                "Allerton.",
            rewardChoices = {{37207, 1}, {37418, 1}, {37483, 1}, {37556, 1}},
        },
        [11601] = {
            description = "Poor Mr. Allerton might yet help us find my brother.\n\n< Leryssa unveils a " ..
                "voluminous book, not unlike an army recruitment ledger.>\n\nI borrowed it, ok? Let's " ..
                "see, does that enlistment card have a date?\n\nWilliam saw Thassarian at the enlistment " ..
                "line. Their entries must be near each other... here it is!\n\nHe was assigned to... Unit " ..
                "S? All the other military units are named after Alliance towns.\n\nWho's in the unit? " ..
                "Where are they deployed? We need rumors. See if the innkeeper's heard anything.",
        },
        [11602] = {
            description = "Aerial reconnaissance of the quarry reports that the Nerubians are storing " ..
                "their eggs on the scaffolding surrounding the base. Smart beasts these are... They're " ..
                "keeping the eggs high and dry, away from the epicenter of conflict.\n\nYou're going to " ..
                "have to go back out there and track down their eggs. Find 'em, smash 'em, and trash " ..
                "'em.\n\nEach egg destroyed means twenty less Nerubians feeding on our corpses.",
            rewardChoices = {{36878, 1}, {36879, 1}, {36880, 1}, {36881, 1}, {36882, 1}, {36883, 1}},
        },
        [11603] = {
            description = "The military was all that old man Colburn had. After he retired, he still " ..
                "clung to it like a lifeline.\n\nHe knows the name of every general, unit, brigade, " ..
                "detachment... you name it. He's the man you need.\n\nProblem is, his mind is scarred. He " ..
                "won't talk to anyone unless he gets his Kul Tiras wine. Takes him back to the times he " ..
                "was a marine.\n\nI haven't received a shipment in months. The last merchant ship out of " ..
                "Kul Tiras sunk northeast of here. See if you can salvage a bottle to bring Colburn.",
            rewardItems = {{40042, 5}},
        },
        [11604] = {
            description = "Unit S... Unit S.... hmmmpph.... don't make any sense... it oughta be named " ..
                "after a town...\n\nDarkshire was sent to Dragonblight. The Goldshire boys were sent to " ..
                "the Fjord. Where did I hear...\n\nOh, yes... the deserter! There's a turn-tail in the " ..
                "barracks prison. Got thrown in not too long ago. Kept saying that \"S\" stood for " ..
                "suicide.\n\nLook for the deserter. He might have some information for you.",
        },
        [11605] = {
            description = "<A distant voice echoes in your head as you regard the stone statue.>\n\nDo " ..
                "not be startled, stranger. I am Elder Atkanok, an ancient ancestor of the tuskarr " ..
                "people, a skilled craftsman in my own time and the guardian of this quarry for " ..
                "centuries.\n\nThe quarry has been overrun, leaving many statues unfinished while the " ..
                "ancestors' spirits wander the world. Will you aid me in righting this wrong?\n\nFirst, I " ..
                "must know the names of these wandering ancestors. Look for the markers near their " ..
                "statues.",
            rewardMoney = 50000,
        },
        [11606] = {
            description = "We can kill all the Nerubians that we see and destroy all the eggs that we " ..
                "find, but those things won't stop coming until we blow their tunnels and passageways up. " ..
                "Of course, we can't do that without some heavy grade munitions. Unfortunately, most of " ..
                "our stockpile is being used up by the goblins and blacksmiths for our siege tanks and " ..
                "weaponry.\n\nWe do happen to have a pretty good supply of the stuff out in Mightstone " ..
                "Quarry - underneath all the Nerubian crap. You'll just have to go out and get it for me.",
        },
        [11607] = {
            description = "In the attack on the quarry, the shaman and craftsmen working here were slain. " ..
                "The violence threw the spirit world into utter chaos and we'll be unable to guide the " ..
                "ancestors home unless we find a way to soothe the spirits of the murdered.\n\nThe " ..
                "aggressors themselves pay no heed to the spirits, but their companions, the beryl " ..
                "hounds, sense the spirits and hold them in thrall.\n\nKill the beryl hounds, and using " ..
                "the raw energy left behind, break the imprisonment of the spirits of the innocent.",
            rewardMoney = 50000,
        },
        [11608] = {
            description = "North, south, east and west. Those are the locations that you should be " ..
                "concerned about. Surrounding this fortress, within Mightstone Quarry, are four perfectly " ..
                "situated Nerub'ar sinkholes.\n\n<Holgoth hands you a bundle.>\n\nBe very careful with " ..
                "that package, <name>. Mishandle it and you'll be dog meat.\n\nInside the bundle are " ..
                "seaforium depth charges. Get to each of those Nerub'ar sinkholes and plant a depth " ..
                "charge at their center point. If all goes well, the tunnels will collapse.\n\nGet a move " ..
                "on!",
            rewardChoices = {{36888, 1}, {36937, 1}, {36938, 1}, {37555, 1}},
        },
        [11609] = {
            description = "With the spirits of the murdered craftsmen and shaman at rest, the way is " ..
                "clear for us to complete the ceremonies interrupted by the attack. You must perform a " ..
                "role traditionally reserved for a tuskarr shaman, and you must possess all the necessary " ..
                "ritual items.\n\nThere is no time to craft new ones, so you will need to scour the " ..
                "quarry for those left by the victims of the attack. Handle these objects with care, " ..
                "<name>, for some are centuries old. You may need to wrest them from the hands of the " ..
                "invaders.",
            rewardMoney = 50000,
        },
        [11610] = {
            description = "With your help, the ancestor spirits can now be guided to their rightful " ..
                "homes, the statues lovingly prepared by Kaskala's craftsmen and shaman.\n\nThe " ..
                "ceremonies for these ancestors were interrupted during the attack on the quarry, and you " ..
                "will need to complete them. Take with you the objects that you recovered from the " ..
                "quarry, stand in front of the statues with the name markers, and recite this " ..
                "chant.\n\n<Words in a strange language flood your head, but you have no difficulty " ..
                "recalling them.>",
            rewardChoices = {{37227, 1}, {37380, 1}, {37514, 1}, {37548, 1}},
            rewardMoney = 100000,
        },
        [11611] = {
            description = "<Mortuus sighs.>\n\nPeons... We may as well post up a sign offering the " ..
                "Nerub'ar a free meal.\n\nSee, the problem with a peon is that: (1) they're dumber than " ..
                "dirt; and (2) they're weaker than a leper gnome. Of course they're the first to be taken " ..
                "by the Scourge!\n\nThis puts me in a bit of a predicament, you see. Without peons, " ..
                "manual labor comes to a halt. No peons, no construction.\n\nFind and release my peons, " ..
                "<race>. If they're alive, you'll find 'em spun up in webbing throughout Mightstone " ..
                "Quarry.",
            rewardChoices = {{37206, 1}, {37403, 1}, {37417, 1}, {37482, 1}},
        },
        [11612] = {
            description = "You're a welcome sight, <class>. My name is Etaruk, and I used to be a " ..
                "craftsman here at the Coldrock Quarry.\n\nMy companions and I were preparing a new set " ..
                "of statues for their last set of rites when we saw those mysterious blue platforms come " ..
                "flying over the plateau.\n\nWhen they landed, the mages they carried swarmed the quarry, " ..
                "murdering my fellows and plundering the quarry. If we don't stop them, they'll destroy " ..
                "our statues and make off with our artifacts. Will you help me defeat the invaders?",
            rewardMoney = 50000,
        },
        [11613] = {
            description = "They call themselves the Kvaldir. My people have legends about them; we call " ..
                "them the tuk-hariq - walkers of the fog.\n\nMy village was destroyed by these giant " ..
                "mist-men. Everyone I knew was slain, including my father Ariut.\n\nBy tuskarr law I must " ..
                "seek retribution against those who shed my kin's blood.\n\nI am but a fisherman and I've " ..
                "not yet passed the test of manhood... I cannot stand toe-to-toe with the vile " ..
                "Kvaldir.\n\nIf you were to carry out my blood duty for me, I will be in great debt to " ..
                "you.",
            rewardChoices = {{37021, 1}, {37022, 1}, {37023, 1}, {37025, 1}, {37026, 1}, {37024, 1}},
        },
        [11614] = {
            description = "We are here by order of Varimathras! The mission of the Shadowstalkers is a " ..
                "simple one: spy. Well, spy with a little assassination on the side.\n\nOne of my best " ..
                "field agents has gone missing. I haven't heard from him in days, which has left me " ..
                "fearing the worst. No, not death! Death would be ideal. I fear he may have gone rogue... " ..
                "turned traitor even.\n\nHis last known location was northern Mightstone Quarry. He was " ..
                "gathering intelligence on the Nerubians. Find him.\n\nHe better be dead...",
        },
        [11615] = {
            description = "You skim through the pages of the book, looking for anything of importance. On " ..
                "the last page you discover what appears to be frantic scribbling:\n\nNecrolords. At " ..
                "least a dozen by my count.\n\nFarms to west being used as some sort of horrible spawning " ..
                "glade for Scourge.\n\nRow upon row of victims.\n\nI think they're on to me. Made a dash " ..
                "for the hold. I won't be captured alive.\n\nDreadvenom hemotoxin. If they decide to bite " ..
                "into me, they'll be in for a surprise.\n\nTake this information back to Barthus.",
        },
        [11616] = {
            description = "<Barthus tears out the last page and rolls it up.>\n\nTake this to Hellscream " ..
                "at once! In the meantime, I'm going to send a team to scout out the farms.\n\nBe sure to " ..
                "tell Hellscream that we're going to need reinforcements.",
        },
        [11617] = {
            description = "I'm sure you've seen those blue and white platforms hovering over the quarry. " ..
                "They're the transportation the mage hunters used to land their forces here, and now " ..
                "they're loading them up with our artifacts and fragments of our statues.\n\nWe must stop " ..
                "them before they leave the quarry.\n\nThe small creatures digging in the quarry carry " ..
                "explosives. Take them and use them to destroy the three floating platforms. The leader " ..
                "keeps watch from a fourth, grounded platform, but we'll deal with him afterward.",
            rewardMoney = 50000,
        },
        [11618] = {
            description = "<Hellscream shakes his head.>\n\nYou may not have noticed that we're trying to " ..
                "win a war here, <race>. I need all available soldiers at the primary points of conflict. " ..
                "This means that we don't have any real soldiers to spare for these minor " ..
                "incursions.\n\n<Hellscream pauses to think.>\n\nIf Barthus wants reinforcements at the " ..
                "farm...\n\n<Hellscream claps his hands together.>\n\n...he shall have them! Report to " ..
                "Barthus's assassins at the farms, west of here. Let them know that reinforcements have " ..
                "arrived.",
        },
        [11619] = {
            description = "My own father was slain by the leader of this raiding party, Gamel the Cruel. " ..
                "He has made his abode inside a cave on the beach.\n\nYou've dealt with his men already. " ..
                "Finish what you've started, <name>. Avenge my father and I will share with you what " ..
                "little I still have.",
            rewardChoices = {{37209, 1}, {37419, 1}, {37523, 1}, {37541, 1}},
            rewardMoney = 47000,
        },
        [11620] = {
            description = "There is someone who might shed light on this mystery, <race>. It is rumored " ..
                "that the Kvaldir have kept a naga priestess alive at the temple on the west side of the " ..
                "shore.\n\nShe will no doubt have great reason to resent her uninvited Kvaldir guests. " ..
                "Perhaps my father is expecting her to cooperate with you in some way.",
        },
        [11623] = {
            description = "The leader of the mage hunter forces is a fearsome creature called Curator " ..
                "Insivius. My people have hunted the beasts of the seas and land for countless " ..
                "generations, but I've never seen anything like this curator before.\n\nHe's landed one " ..
                "of those flying disks on the upper rim of the quarry and oversees the operation from " ..
                "there. <name>, I can only believe the ancestors themselves sent you to my rescue and I " ..
                "hope you will help me drive the mage hunters from this quarry once and for all.",
            rewardChoices = {{37378, 1}, {37436, 1}, {37515, 1}, {37521, 1}},
            rewardMoney = 50000,
        },
        [11624] = {
            description = "I must find out what happened to my master, Farseer Grimwalker!\n\nEarlier, he " ..
                "was observing the magnataur at nearby Magmoth. But one of his grunts just returned, " ..
                "saying that the group had been crushed, and that the farseer was dragged into the depths " ..
                "of the place.\n\nBefore I send you on a suicide mission, I wish to consult with the " ..
                "spirits to learn more.\n\nThere is an air elemental known as Imperean in the ruins of " ..
                "Eldra'nath to the west. She is wise and may give you the information we seek.",
        },
        [11625] = {
            description = "Five hundred years ago, Azshara imprisoned a being named Leviroth in the " ..
                "waters below. Now these barbarians seek to undo our queen's work!\n\nThey took over our " ..
                "city and began to sacrifice my brethren to awaken him! When they ran out of naga, they " ..
                "began to take tuskarr. Their spirits will know no peace!\n\nI will help you, for it will " ..
                "go a long way towards quelling my vengeance. Their captain, Ragnar, dwells deep inside " ..
                "northeastern Riplash. He has in his possession a golden trident. Bring it to me!",
        },
        [11626] = {
            description = "Raj Naz'jan was the emperor of Riplash when Leviroth was imprisoned. Azshara " ..
                "herself blessed his trident so it would slay the beast should it ever escape.\n\nNow you " ..
                "wield it, <race>. As much as it disgusts me, I will have my revenge on these barbaric " ..
                "giant-men.\n\nTake the trident to the depths beneath Riplash. You will find Leviroth " ..
                "below an iceberg closest to northern Riplash.\n\nDrive the trident into his flesh and " ..
                "slay him! Return to whomever sent you when you're done; I wish to see no more of you.",
            rewardChoices = {{37213, 1}, {37396, 1}, {37423, 1}, {37487, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [11627] = {
            description = "Ah, it is information that you crave: the whereabouts and condition of your " ..
                "'farseer'. He did not see so far as to avoid the trouble which befell " ..
                "him.\n\nNevertheless, I will give you the means to acquire the knowledge. But first, you " ..
                "will do some things for me.\n\nNo doubt you have seen the war between fire and water to " ..
                "the south. Simmer keeps boiling Churn 's pool, and the two have been battling for " ..
                "ages.\n\nGo to the Charred Rise and Blistering Pool, and convince each of them to stop " ..
                "their bickering.",
            rewardMoney = 50000,
        },
        [11628] = {
            description = "To the northeast looms the Temple City of En'kilah, the Scourge's seat in " ..
                "Borean Tundra. From behind its walls, the Scourge commander has sent his Nerubians to " ..
                "surround us.\n\nRemaining on the defensive would doom my people, but my advisors differ " ..
                "in their strategies. Durm would charge in blindly, while Sage Aeire favors " ..
                "stealth.\n\nThe Temple City has blighted the nearby lands and the native creatures. " ..
                "Aeire believes the pelts of the scourged mammoths can serve as a cloak that may hide an " ..
                "infiltrator.",
            rewardMoney = 50000,
        },
        [11629] = {
            description = "You have done what was asked, and now I give you that which you " ..
                "desire.\n\nDeliver this primal to the spirit talker back at your Bor'gorok Outpost. If " ..
                "she is wise, she will know a ritual to gain you the information which you seek.",
        },
        [11630] = {
            description = "By curing the hides with the blighted earth outside the Temple City, Sage " ..
                "Aeire believes she can create a cloak which will cause most of the Scourge minions to " ..
                "ignore your presence. You should blend right in, she says.\n\nShe'd best be correct. " ..
                "It's our only chance to gather information and plan our counterattack.\n\nYou should be " ..
                "able to find the earth she needs poking in the areas to the south and west of the " ..
                "fortress. Bring it to me when you've finished gathering it.",
            rewardMoney = 50000,
        },
        [11631] = {
            description = "Here, <name>, I've attuned the primal to you.\n\nOpen your soul to it in the " ..
                "presence of my totem of air and concentrate upon the fate of Farseer Grimwalker.\n\nThe " ..
                "spirit of the wind touches all; with any luck you will be granted a vision.",
            rewardChoices = {{37274, 1}, {37352, 1}, {37442, 1}, {37530, 1}},
        },
        [11632] = {
            description = "You hold the carapace fragment of Ith'rix the Harvester and realize that this " ..
                "is only the beginning. Even now you sense that victory is fleeting. Surely the Lich King " ..
                "has a thousand more beasts like Ith'rix, waiting to be unleashed upon the Horde.\n\nTake " ..
                "your trophy and present it to High Overlord Saurfang, inside Warsong Hold. He should be " ..
                "notified of your victory over a powerful Scourge agent.",
            rewardChoices = {{37214, 1}, {37394, 1}, {37424, 1}, {37505, 1}},
        },
        [11633] = {
            description = "Sage Aeire has finished the shroud. Take it with you and travel to the Temple " ..
                "City of En'kilah. Don the cloak within the city's bounds to hide yourself from most of " ..
                "the Scourge there. This will be our best opportunity to gather information about the " ..
                "enemy's fortifications and leaders.\n\nWhile wearing the cloak, scout the three large " ..
                "spires on the grounds of the city. While the shroud will shield you from most of the " ..
                "Scourge, the En'kilah abominations will be able to find you if you get too close.",
            rewardMoney = 50000,
        },
        [11634] = {
            description = "You're a tough mother, <name>. I think your talents are better suited " ..
                "elsewhere - like the root of the whole damn problem!\n\n<Razgor points to the " ..
                "west.>\n\nA thousand Scourge, at least four full sized floating death machines and who " ..
                "knows what else.\n\nBut you're gonna find out and then you're gonna handle it... That's " ..
                "right, you're gonna beat the hell out of the Scourge army that's currently beating down " ..
                "our door.\n\nGet to the top of Warsong Hold and report to Wind Master To'bor. He'll be " ..
                "expecting you.",
        },
        [11635] = {
            description = "You must go to Magmoth to the east.\n\nYou must descend into the depths of " ..
                "their caverns.\n\nYou must speak with Farseer Grimwalker's spirit!",
            rewardMoney = 47000,
        },
        [11636] = {
            description = "Tanks, mon. I be talkin' bout siege machines! We got heavy tanks stationed at " ..
                "Garrosh's Landing on da west coast. We gonna get you to da tank and you gonna use da " ..
                "tank to lay down some Horde justice on da Scourge!\n\nDa only tricky part be getting' " ..
                "you der. No way we be sendin' you on our wind riders. Too risky.\n\nYou see dat pixie " ..
                "o'er der? Dat blondie elf? Yanni be his name, mon. He can get you to da coast, safely. " ..
                "Once der, talk to Annihilator Grek'lor!",
        },
        [11637] = {
            description = "After my small force of grunts were killed, I was dragged down here and " ..
                "ritually murdered. The snobold who did this is known as Kaganishu.\n\nThough you have " ..
                "vanquished his shaman helpers, my spirit is still tethered to this place. After he slew " ..
                "me, he created a fetish from my body, which anchors me here. Kaganishu is using it to " ..
                "learn all that I know of shamanism.\n\nYou must retrieve the fetish from him and use it " ..
                "upon my spirit. Kaganishu is nearby in the caves.\n\nOnly then will I truly be free.",
            rewardMoney = 50000,
        },
        [11638] = {
            description = "<name>, now that my spirit has been freed would you do me the honor of " ..
                "returning my remains to Spirit Talker Snarlfang? They lay upon the ground beneath " ..
                "me.\n\nI sense that the spirit talker is still at Bor'gorok Outpost to the west where " ..
                "last I saw her.",
            rewardChoices = {{37047, 1}, {37049, 1}, {37528, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 94000,
        },
        [11639] = {
            description = "The overlord refuses to allow the shaman to heal my wounds. He says that it " ..
                "will be a good lesson for me and give me time to reflect upon my failure.\n\nBut you " ..
                "could get revenge for me and the others who fell at Magmoth!\n\nI know that the spirit " ..
                "talker wants you to go in there to save the farseer.\n\nIt's just to the east. Go, " ..
                "<class>... go slay the magnataur and their snobold servants. Regain the outpost's honor!",
            rewardChoices = {{37270, 1}, {37353, 1}, {37441, 1}, {37479, 1}},
            rewardMoney = 47000,
        },
        [11640] = {
            description = "Within the spires you described dwell the main lieutenants of the Scourge " ..
                "leader, the high priests. Not only do they command the Scourge forces, but they hold the " ..
                "key to the necropolis above, and their master.\n\nAn endless stream of Scourge minions " ..
                "will overrun us if we can't find and defeat their leader. I cannot leave my people " ..
                "defenseless, however much Durm might want to bring the fight to the enemy. It falls to " ..
                "you, <name>, to slay the high priests and take the scrolls they hold.",
            rewardMoney = 50000,
        },
        [11641] = {
            description = "From the beginning, I've counseled that Chieftain Wintergale should assemble " ..
                "our mighty warriors and attack our enemy at their base. My advice has fallen on deaf " ..
                "ears and he has proven that he'd rather tip-toe around according to Sage Aeire's " ..
                "plans.\n\nI'll wait no longer. If Chieftain Wintergale is too cowardly to send our " ..
                "warriors into battle, perhaps you'd be willing to show him that a direct attack can " ..
                "succeed. Storm the Temple City of En'kilah and slay all in your path, <name>.",
            rewardMoney = 50000,
        },
        [11642] = {
            description = "We need to get these tanks back up and runnin'! They ain't gonna fix " ..
                "themselves. Mobu 's gonna be the one to handle that stuff. Talk to him and see what he " ..
                "needs. Maybe you can shut him up before he finally drives me into a berserker frenzy and " ..
                "I cleave him in two!",
        },
        [11643] = {
            description = "These wrenches are useless, buddy. I need my pneumatic tank transjigamarig to " ..
                "get these things up and running! Unfortunately, I left it at my old digs, on the other " ..
                "side of this landing. It's the beat down hut next to the stables. You're gonna have to " ..
                "go and get it for me, because I sure as hellfire am not going to go anywhere near the " ..
                "mist.\n\nOh yea, buddy, watch out for the mist. The mist is what tore up these shores.",
        },
        [11644] = {
            description = "I need metal to patch these tanks up! Super strong metal plates can be found " ..
                "scattered about all across Garrosh's Landing and at the bottom of the bay.\n\nJust be " ..
                "careful when you're out there searching for plates. The mist is... um... AGGRESSIVE! The " ..
                "mist is what took out the landing and the adjoining tuskarr town. Poor little tuskarr...",
        },
        [11645] = {
            description = "Those dirty, stinkin' snobolds... they stole all of my supplies!\n\nWhat's a " ..
                "snobold you ask? It's like a kobold, 'cept they serve the magnataur; kinda take care of " ..
                "them. I know, weird!\n\nAnywho, wanna help me out? I know the little creeps stole off " ..
                "with all of my stuff. Stupid me thinkin' that it'd be nice and safe, packed up on the " ..
                "north side of the airstrip.\n\nWhy don'tcha do me a favor and head north to their stupid " ..
                "Magmoth. There's a cash reward if you bring all my stuff back quick!",
            rewardMoney = 47000,
        },
        [11646] = {
            description = "Listen closely, <name>, for there is not a moment to spare.\n\nYour prisoner " ..
                "is being prepared for interrogation here in our tower. In the event that he is less than " ..
                "forthcoming, your assistance may be required.\n\nMake your way up to where he is being " ..
                "detained and tell Librarian Normantis that I've sent you to assist him.",
        },
        [11647] = {
            description = "The presence of plague cauldrons within the Temple City of En'kilah worries me " ..
                "greatly, <name>. It's clear that Chieftain Wintergale trusts your judgment and your " ..
                "knowledge of our enemy. Would you help me deal with the cauldrons as you help the " ..
                "chieftain carry out his plans in the Temple City?\n\nI've prepared a totem which will " ..
                "attack and neutralize the contents of the cauldrons. All you must do is locate the " ..
                "cauldrons and use the totem near each. Each Scourge weapon we destroy brings us closer " ..
                "to victory.",
            rewardChoices = {{37234, 1}, {37356, 1}, {37439, 1}, {37517, 1}},
            rewardMoney = 50000,
        },
        [11648] = {
            description = "It is fortunate you're here, <race>.\n\nYou see, the Kirin Tor code of conduct " ..
                "frowns upon our taking certain 'extreme' measures - even in desperate times such as " ..
                "these.\n\nYou, however, as an outsider, are not bound by such restrictions and could " ..
                "take any steps necessary in the retrieval of information.\n\nDo what you must. We need " ..
                "to know where Lady Evanor is being held at once!\n\nI'll just busy myself organizing " ..
                "these shelves here. Oh, and here, perhaps you'll find this old thing useful....",
            rewardMoney = 37000,
        },
        [11649] = {
            description = "Now that their little squabble is dealt with, there is still the matter of " ..
                "helping you and your spirit talker.\n\nAs you can see, my vassals have been enraged by " ..
                "the ongoing war between fire and water. This will not change anytime soon, but it will " ..
                "serve to your advantage.\n\nIn order to assist you, what we need are their motes. Head " ..
                "further into the ruins and retrieve them from the tempests.",
            rewardMoney = 47000,
        },
        [11650] = {
            description = "As you may have noticed, we created the airstrip on the southern border of a " ..
                "magnataur den!\n\n<Crafty says something uncharitable about Fizzcrank under her " ..
                "breath.>\n\nThe old man has put me in charge of finding a... ahem... creative solution " ..
                "to this situation: if we don't deal with them soon, they'll come down here and tear us " ..
                "limb from limb!\n\nThat's where you come in. I want you to get me everything on this " ..
                "shopping list. Please.",
            rewardMoney = 47000,
        },
        [11651] = {
            description = "Thanks for all your help, buddy. You can let Grek'lor know the tanks are ready " ..
                "for action. Hopefully you can clean up this place once and for all!",
        },
        [11652] = {
            description = "Once you're ready, jump into one of the tanks and drive it out to the Plains " ..
                "of Nasam, southeast of here.\n\nUse the tank's weapon arsenal to take down the Scourge " ..
                "army. If you get in a jam, the \"Meatpounder\" will tear 'em up and the land mines will " ..
                "finish 'em off! If you find any of our soldiers, grab 'em! One last thing, fuel tanks " ..
                "can be found all over the field.\n\nTry to get close enough to that structure in the " ..
                "center and see what's going on.\n\nIf you do all of this and live, go to Hellscream!",
            rewardChoices = {{37276, 1}, {37325, 1}, {37446, 1}, {37476, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [11653] = {
            description = "That'll do her, chief! So, here's what I want ya to do....\n\nTake my blaster " ..
                "and head north to Magmoth. If we're gonna have a chance at all against those monsters, " ..
                "we need to cut them down to size... so to speak.\n\nIn order to gauge its effectiveness, " ..
                "I need you to slay the magnataur while the blaster's effects are still on it. Any of the " ..
                "crushers or mates will do, but don't bother with the offspring... they're too small to " ..
                "worry about.",
            rewardChoices = {{37272, 1}, {37388, 1}, {37428, 1}, {37526, 1}},
            rewardMoney = 47000,
        },
        [11654] = {
            description = "As you inspect the captured blood vial, you realize its contents are still " ..
                "warm. The victim must have just been bled and may still be alive.\n\nWhat use would the " ..
                "Scourge have for blood? They've never shown an interest in live prisoners in the past. " ..
                "Perhaps if you can locate the source of the blood, you'll be able to discover what the " ..
                "Scourge is planning.",
            rewardMoney = 39000,
        },
        [11655] = {
            description = "Across the mist to the north you will find Garrosh's Landing. To the south are " ..
                "the ruins of my old home, Pal'ea. Both have been ransacked by an ancient force known as " ..
                "the Kvaldir.\n\nThese fearsome savages slew all of my people without mercy and drove " ..
                "your people inland.\n\nAll that remains of the tuskarr of Pal'ea are our personal " ..
                "effects, taken as relics by the Kvaldir. While we are not a vengeful race, justice must " ..
                "be served. The tuskarr relics must be returned to me. Enter the mist and find them...",
        },
        [11656] = {
            description = "Tuskarr magic is similar to what your people call shamanism. While we serve " ..
                "the elements differently than you, the power that we are able to call forth is " ..
                "formidable.\n\n<Waltor waves a torch-like baton in front of you.>\n\nWith this tuskarr " ..
                "torch I want you to return to the mist and strike at the Kvaldir vessels. You will find " ..
                "three of their vessels docked behind the mist at Garrosh's Landing, north of here, and " ..
                "one docked off the shores of Pal'ea, to the south. Burn their ships in effigy! For all " ..
                "to see!",
            rewardChoices = {{37207, 1}, {37418, 1}, {37483, 1}, {37556, 1}},
        },
        [11658] = {
            description = "Okay, don't panic! The blaster might not've worked, but we still have " ..
                "options.\n\n<Crafty snaps her fingers.>\n\nWe're going to divert attention away from the " ..
                "airstrip! To make this work, we'll need a few things first.\n\n<Wobblesprocket looks you " ..
                "up and down appraisingly.>\n\nSteeljaw's caravan, just to the west, stupidly took a " ..
                "shortcut through a taunka graveyard and was destroyed by their risen spirits.\n\nHead " ..
                "over there and get some outfits off of the dead orcs. Pick up one of their banners, too!",
            rewardMoney = 47000,
        },
        [11659] = {
            description = "They're... bleeding the prisoners... putting the blood... in those " ..
                "globes.\n\n<Grumm's eyes close momentarily and he leans his head back.>\n\nThe blood... " ..
                "taken up to necropolis... to feed blood prince...\n\n<Grumm gasps for " ..
                "breath.>\n\nP-promise... you'll... destroy blood... globes... bring word... to " ..
                "Junek.\n\n<The snow tracker collapses into unconsciousness.>",
            rewardMoney = 50000,
        },
        [11660] = {
            description = "A Kvaldir lieutenant known as Orabus directed the initial incursion against my " ..
                "people at Pal'ea, He oversaw the destruction of both villages and then disappeared into " ..
                "the mist.\n\nIn those early days there was talk of a horn that Orabus gifted to the " ..
                "Kvaldir mistweavers. This horn could be used to summon him should the need arise.\n\nWe " ..
                "need to get that horn from the Kvaldir mistweavers and call forth Orabus. If he is " ..
                "destroyed, these savages might retreat.\n\nSeek out mistweavers at Pal'ea, to the south.",
        },
        [11661] = {
            description = "Take the horn and travel west to the Warsong Jetty. Make your way to the end " ..
                "of the jetty and blow into the horn. The sound should rouse Orabus.\n\nSlay the foul " ..
                "beast and return to me!",
            rewardChoices = {{37208, 1}, {37402, 1}, {37484, 1}, {37543, 1}},
            rewardMoney = 141000,
        },
        [11662] = {
            description = "A fellow survivor of Pal'ea known as Karuk has made his way to the main base " ..
                "of the Kvaldir in the Borean Tundra - far to the south where the snow was once " ..
                "bountiful. Karuk hides along the bluffs overlooking Riplash Strand.\n\nSeek out Karuk " ..
                "and let him know what you did for my people here at the Coast of Echoes.\n\nThe safest " ..
                "route to Karuk is through your fortress. From Warsong Hold, take the road south and " ..
                "follow it around until you reach Riplash Strand.",
        },
        [11663] = {
            description = "Thank you, <class>! The information you've extracted is of vital importance to " ..
                "the Kirin Tor.\n\nReturn at once to Donathan as we make plans for the rescue of Lady " ..
                "Evanor.",
            rewardMoney = 4800,
        },
        [11664] = {
            description = "I can hear the mist creatures outside. Their yells are driving me mad, but I " ..
                "dare not try to escape. And where would I even go? How long would it be until they " ..
                "caught up with me and executed me like the others?\n\nI wonder, how far has the mist " ..
                "crept, stranger? Has it overtaken this whole continent?\n\nWould you be willing to help " ..
                "me try and escape the mist? I think I can lead us back toward my father. I still sense " ..
                "his life spirit. He is close.",
            rewardChoices = {{37212, 1}, {37399, 1}, {37422, 1}},
        },
        [11665] = {
            description = "Hello <lad/lass>. I'm glad you've stopped by to talk to this old man--there's " ..
                "trouble back home.\n\nA traveling merchant recently sold a batch of baby crocolisks to " ..
                "some gullible children. Crocolisks are wild beasts, and many have escaped and now lurk " ..
                "in city waterways.\n\nGrab your strongest fishing pole and drop a line in Stormwind or " ..
                "Orgrimmar and bring one of the little devils back to me. I'm anxious to see one.",
            rewardItems = {{35348, 1}},
        },
        [11666] = {
            description = "You probably know all about the golden darter--they're fairly common in the " ..
                "rivers of Terokkar Forest and a delicacy for priests. But here's one you haven't heard " ..
                "of: the blackfin darter.\n\nThe fish is notoriously crafty and difficult to catch. You " ..
                "have to pull your line at the last possible second, because they nibble at the bait " ..
                "before they take it.\n\nDrop your line in the rivers of Terokkar and bring me a blackfin " ..
                "darter. Avoid the lakes, as the blackfin only thrive in moving water.",
            rewardItems = {{34863, 1}},
        },
        [11667] = {
            description = "Figluster's mudfish is a surprisingly quick bottom feeder found in the waters " ..
                "of Nagrand. They grow their entire lives and are well known as fighters.\n\nYears ago, I " ..
                "caught what I'm certain was the world's biggest mudfish... until it snapped my line and " ..
                "escaped.\n\nA fisherman of your caliber doesn't need to be told what to do--your destiny " ..
                "awaits in the lakes of Nagrand.",
            rewardItems = {{34863, 1}},
        },
        [11668] = {
            description = "There's a lot of big fish in the Zangarmarsh lakes. Ever wonder what they " ..
                "eat?\n\nShrimp. Giant freshwater shrimp. The Rokk tells me the dishes you can make with " ..
                "shrimp are nearly endless.\n\nBut shrimp are too small to catch with a fishing line. So " ..
                "here's the trick: cut open the bloated barbed gill trout and you'll find a shrimp or two " ..
                "if you're lucky.",
            rewardItems = {{34863, 1}},
        },
        [11669] = {
            description = "This old man is going hunting soon. I'm gonna take down a mammoth shark off " ..
                "the coast of Azshara.\n\nThe thing is, I need a toxin that'll stay on a spear tip while " ..
                "it's underwater. To make that kind of stuff, I need the glands from a poisonous fish: " ..
                "the felblood snapper.\n\nSuch a vile fish only thrives in the waters of Hellfire " ..
                "Peninsula and Shadowmoon Valley. Bring me back a whopper and I'll be a happy old man.",
            rewardItems = {{34863, 1}},
        },
        [11670] = {
            description = "With all of those outfits you, er, recovered, I fashioned a Warsong orc " ..
                "disguise. I had the genius idea of combining it with some old stuff that I had left " ..
                "hanging around from last Hallows' End, so it should be foolproof!\n\nHere, in this sack " ..
                "is the disguise and the banner you recovered. Head down into the bowels of Magmoth and " ..
                "slay the magnataur chieftain, Magmothregar.\n\nIf you're going to convince them to turn " ..
                "their attention on the Warsong orcs, you'll need to plant the banner while disguised.",
            rewardChoices = {{37054, 1}, {37072, 1}, {37073, 1}, {37357, 1}, {37231, 1}},
            rewardMoney = 100000,
        },
        [11671] = {
            description = "So it's true. They have her.\n\nIt's clear what must be done, <race>. She WILL " ..
                "be saved.\n\nI must remain here and aid in the rescue preparations. I call upon you " ..
                "again; this time to collect the prison key. All we know of this Salrand figure is that " ..
                "she cannot be harmed so long as her shield is intact.\n\nWe've customized a special " ..
                "explosive that should strip her of this protection, allowing you to perform your duty. " ..
                "Return to me when you've collected the key.\n\nHurry, <name>. Lady Evanor is suffering!",
            rewardMoney = 47000,
        },
        [11672] = {
            description = "You've come to enlist, right? Normally you'd have to stand in line like the " ..
                "other recruits. Normally you'd be out of luck because the recruitment ledger's gone " ..
                "missing and I can't process anyone until the new books get here.\n\nFortunately for you, " ..
                "<name>, I've heard about you and what you did in Outland. To be honest, you're a cut " ..
                "above these poor saps. Lines aren't for you.\n\nGo to the barracks and speak to General " ..
                "Arlos. He'll be more than happy to meet with someone of your caliber.",
        },
        [11673] = {
            description = "I knew they'd send someone for me sooner or later... turned out to be later, " ..
                "of course.\n\nI came in here to parlay with the snobolds, but their main shaman, " ..
                "Kaganishu, decided instead that I'd make a tasty snack for Magmothregar.\n\nWait... " ..
                "what?! They didn't send you?!\n\nDID THEY FORGET ABOUT ME?!\n\nOkay, you're here now and " ..
                "that's all that matters.\n\nAs soon as you break this chain we'll make our way back to " ..
                "the airstrip. Then you can tell Fizzcrank I'm safely back.\n\nIf he remembers me, that " ..
                "is.",
            rewardChoices = {{37047, 1}, {37049, 1}, {37528, 1}},
            rewardMoney = 100000,
        },
        [11674] = {
            description = "There are many new mysteries walking the lands now. One of our sages, " ..
                "Highmesa, has foolishly gone north with only one longrunner to investigate something " ..
                "strange near the Dens of Dying.\n\nWhat are the dens, you ask? They are a sacred place " ..
                "to the magnataur, where they go in their old age to die. She saw something fall from the " ..
                "sky near them a few days ago.\n\nIf you would be friend to the taunka, I would have you " ..
                "find and help her. She is not so stubborn that she will not accept your aid.",
        },
        [11675] = {
            description = "The magnataur at the Dens of Dying have contracted a plague. We must find the " ..
                "cause, but first we must put them out of their misery.\n\n<race>, you must go north onto " ..
                "the slopes in front of us and destroy as many of the poor creatures as you can.",
            rewardMoney = 47000,
        },
        [11676] = {
            description = "The soldiers that they didn't kill are being held in cages scattered across " ..
                "this farmland. Through some thievery we've managed to find a few keys, but we're unable " ..
                "to get close enough to any prisoners without being attacked.\n\nWe need your \"talents\" " ..
                "in securing those keys and freeing the prisoners. Bash in the brains of the necrolords " ..
                "and aberrations and take their keys. Use those keys to free Scourge prisoners.",
        },
        [11677] = {
            description = "I'm convinced that the plague is being caused by something in the caves up " ..
                "there.\n\n<class>, I want you to take these seeds. I normally use them as a ward against " ..
                "the Scourge, though perhaps they can be used to disrupt whatever foulness is happening " ..
                "in the dens.\n\nFind the source of the plague and throw them into it.",
            rewardChoices = {{37223, 1}, {37391, 1}, {37427, 1}, {37507, 1}},
            rewardMoney = 47000,
        },
        [11678] = {
            description = "Bristlehorn should have returned by now.\n\nThe other reason why we came up " ..
                "here was to investigate that Scourge structure to the west, which fell from the sky. " ..
                "He's impetuous and has likely gotten himself into trouble.\n\n<name>, go to that place " ..
                "and find him, please.",
        },
        [11679] = {
            description = "Delays, delays... the one thing we cannot afford right now!\n\nAs much as I " ..
                "hate to disturb Lord Surristrasz, he's our only hope of saving our beloved " ..
                "Evanor.\n\nBring him the key fragments and hope that his mood is favorable.\n\nHurry, " ..
                "<class>, our assault team is waiting.",
        },
        [11680] = {
            description = "The key is forged anew.\n\nNow heed my counsel, <race>. Succeed in your " ..
                "endeavor or die trying, for if a single scale falls from one of my drakes I shall hold " ..
                "you personally accountable.\n\nNow, off with you.",
            rewardMoney = 4800,
        },
        [11681] = {
            description = "At last, we attack!\n\nOnce we've cleared the platform I'll use the " ..
                "key.\n\nYou are to ensure that Lady Evanor remains safe after her release.\n\nHurry now, " ..
                "let us be off!",
            rewardChoices = {{37224, 1}, {37387, 1}, {37429, 1}, {37509, 1}},
            rewardMoney = 47000,
        },
        [11682] = {
            description = "I am aware of your recent deeds here, <name>, and again I thank you.\n\nAs for " ..
                "this local menace, we've learned all we need to know from them. They'll be dealt with in " ..
                "short order. On now to more important issues....\n\nAzeroth needs you. The region just " ..
                "west of here is the center of an urgent crisis.\n\nI'll leave the details to Lord " ..
                "Surristrasz. You must speak with him at once.\n\nGood luck, friend of Dalaran.",
            rewardMoney = 24000,
        },
        [11683] = {
            description = "The fallen necropolis to the west can only be assumed to still be filled with " ..
                "Scourge.\n\nWhile you are at Talramas, <class>, I would ask that you dispatch all of the " ..
                "Lich King's servants that you find within and in the surrounding pools where it fell.",
            rewardChoices = {{37239, 1}, {37355, 1}, {37518, 1}, {37560, 1}},
            rewardMoney = 47000,
        },
        [11684] = {
            description = "Can you feel the tremors in the earth?\n\nThe Scourge's nerubians are on the " ..
                "move deep beneath the ground. They've emerged to the southwest in the Geyser Fields, and " ..
                "are harassing the patrols Chieftain Wintergale sent out.\n\n<The taunka elder offers you " ..
                "a worn map.>\n\nPerhaps a single person can succeed where the patrols have failed. Take " ..
                "this with you to the Geyser Fields and map out the locations of the Nerubian sinkholes.",
            rewardMoney = 47000,
        },
        [11685] = {
            description = "Now that we know the exact locations of the nerubian sinkholes, we can " ..
                "collapse them to halt the Scourge offensive and cripple their force. Wind Tamer Barah " ..
                "knows a way to harness elementals to destroy the tunnels the Nerubians are using, but " ..
                "she will require your help.\n\nSoutheast of the village, near the coast beyond the " ..
                "Frozen Reach, you'll find an area dominated by frozen earth elementals. The hearts of " ..
                "these elements are exactly what Wind Tamer Barah will need.",
            rewardMoney = 47000,
        },
        [11686] = {
            description = "According to Luther's notes the Scourge is now using this place as a breeding " ..
                "ground for those monsters you see lumbering across the field.\n\n<Ickoris " ..
                "shudders.>\n\nThose monsters were once orcs... tauren...\n\nWe need more information " ..
                "before a plan can be devised. I want you to investigate three sites that are heavily " ..
                "trafficked by Scourge: the Warsong Granary, southwest of us, Torp's Farm, directly west " ..
                "of us, and the old Warsong Slaughterhouse, north of us.\n\nReturn to me once you've " ..
                "scouted 'em out.",
        },
        [11687] = {
            description = "There are two... that must... be killed.\n\nThe doctor and... the lich-lord... " ..
                "are above. Find them... destroy them... before....\n\n...it is too... late....",
            rewardMoney = 50000,
        },
        [11688] = {
            description = "Just look at 'em! My beautiful kodos are helpless to defend themselves against " ..
                "those filthy swine! I need you to buy me some time, <race>. I think I can cure the kodo " ..
                "of the sickness, but you need to keep the unliving swine off 'em, else there'll be " ..
                "nothin' left to cure!\n\nGet out there and send those swine to their graves - " ..
                "permanently!",
        },
        [11689] = {
            description = "The greatmother will need to know, <name>.\n\nWill you please return to " ..
                "Taunka'le? Tell her that I will be following shortly.",
            rewardChoices = {{37354, 1}, {37440, 1}, {37519, 1}, {37529, 1}, {37074, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 94000,
        },
        [11690] = {
            description = "Take this riding snaffle, <name>. You'll notice that I've placed a tiny " ..
                "medicine dispenser in the mouthpiece. That thing will cure the infection as soon as a " ..
                "kodo bites down. Once you've cured the sick out of 'em, you'll need to ride 'em home. " ..
                "They'll be weak so you'll need to gently direct 'em here.\n\nBring my babies back, " ..
                "<name>!\n\nOne last thing, you've got ten minutes! That's how long the antidote will " ..
                "remain effective inside that snaffle.",
            rewardChoices = {{36884, 1}, {36885, 1}, {36886, 1}, {36887, 1}},
        },
        [11692] = {
            description = "You're a proven <hero/heroine>. I have another problem!\n\nMy boss, Tinky, " ..
                "went east with Bixie Wrenchshanker and I CAN'T get the outgoing on this thing to work! " ..
                "Tinky's the only one that can fix it and we really need it working one-hundred " ..
                "percent.\n\nYou think you could find them? Bixie said something about following some old " ..
                "magnataur to a place called The Dens of Dying.\n\nI'm guessing that's where you'll find " ..
                "them.\n\nYou can catch a ride out there by talking with Kara Thricestar at the runway.",
        },
        [11693] = {
            description = "Tinky and I came out here stalking some old magnataur. Apparently those caves " ..
                "up there are where they go to die.\n\nOf course, we had no idea that they were going to " ..
                "get plagued when they went in there. We can't have plagued things just roaming about; " ..
                "it's not healthy.\n\nSay, why don't you put down a number of those things while I figure " ..
                "out what our next step should be?",
            rewardMoney = 47000,
        },
        [11694] = {
            description = "So, while you were out taking care of those plagued beasts, I took a peek " ..
                "inside the caves up there.\n\nThere are cultists in there plaguing them!\n\nThey have " ..
                "some sort of noxious concoction brewing in a cauldron. I have a powder that I normally " ..
                "use as an anti-poison, and I mixed it up with some other stuff. I think it'll neutralize " ..
                "their brew!\n\nTake it up to one of those caves and see if it works.",
            rewardChoices = {{37223, 1}, {37391, 1}, {37427, 1}, {37507, 1}},
            rewardMoney = 47000,
        },
        [11695] = {
            description = "I can fashion the likeness of an elemental from these pieces of inanimate " ..
                "stone, but breathing life into it is different. For that, we'll need help and a bit of " ..
                "luck.\n\nLegend tells of an ancient artifact called the Horn of Elemental Fury, sought " ..
                "after by a great hero. I'll lend you a scroll with a copy of the tale. I don't know if " ..
                "the legend is true, but it's our best bet. If the legend is right, the parts of the horn " ..
                "may be in the Flood Plains surrounding the village to the north and southwest.",
            rewardMoney = 47000,
        },
        [11697] = {
            description = "I told Tinky not to go off on her own, but she just HAD to check out that " ..
                "crashed necropolis to the west.\n\nI'm 100% certain that those cultists came from inside " ..
                "that thing, which means I'm now 100% certain that Tinky's in trouble!\n\nShe's the " ..
                "airstrip's number one engineer. Without her we're doomed!\n\nI'd find her myself, but " ..
                "one of those things got in a swipe on my leg before I could vanish again. <name>, if " ..
                "anyone can get her out, it's you!",
        },
        [11698] = {
            description = "If the cultists up in those caves survived the crash, then that fallen " ..
                "necropolis to the west can only be assumed to still be filled with Scourge. There're " ..
                "probably lots of them out in front of it in the pools, too!\n\nWhile you're at Talramas, " ..
                "<class>, do you think you could dispatch all of the Lich King's flunkies that you find " ..
                "there?",
            rewardChoices = {{37239, 1}, {37355, 1}, {37518, 1}, {37560, 1}},
            rewardMoney = 47000,
        },
        [11699] = {
            description = "The cultists magicked me into this cage and there's no door to it. Little did " ..
                "they know that I'm the chief transmatter engineer for the airstrip!\n\nWith your help, " ..
                "and a little elbow-grease, I won't be in here for long.\n\nI'm going to need an " ..
                "engine-core crystal from one of the ghouls in here, a magical gyroscope from their " ..
                "doctor, and a piloting scourgestone from the lich-lord up top.\n\nWith all of that " ..
                "stuff, I should be able to make a port device to get back to Fizzcrank's and escape the " ..
                "gnome way!",
        },
        [11700] = {
            description = "My evil twin's out there somewhere now.\n\nI'm pretty sure that she's not back " ..
                "at the airstrip. In fact, wherever she ended up, it's colder there than here. But I " ..
                "could only 'feel' her for a moment.\n\nOh well, I'll reconfigure this thing and port " ..
                "myself back to the airstrip soon enough. In the meantime, do you think you could go east " ..
                "and let Bixie know that I'll meet her back there?\n\nThanks, <name>!",
        },
        [11701] = {
            description = "Okay, I think I'm going to start making my way back to the airstrip, too. Of " ..
                "course, I'm moving a little slower with this leg injury.\n\nSay, do you think you could " ..
                "get there ahead of me and pass on the good news to Ol' Fizzcrank? I bet anything that " ..
                "there'll be a reward in it for you.\n\nThanks, <name>!",
            rewardChoices = {{37354, 1}, {37440, 1}, {37519, 1}, {37529, 1}, {38214, 1}},
            rewardMoney = 94000,
        },
        [11702] = {
            description = "Dis is gonna sound weird, <class>, but dere be a murloc askin' for our " ..
                "help!\n\nHe goes by da name of King Mrgl-Mrgl, leader of da Winterfin murlocs. Him and " ..
                "his people been run outa dere village and wantin' you to come save dem.\n\nYou find him " ..
                "by headin' west and go down da cliffs. He hangin' out on da south side of da Winterfin " ..
                "Retreat.",
        },
        [11703] = {
            description = "The Scourge agent that's overseeing the abduction and transformation of Horde " ..
                "soldiers into undead monsters is using the northwest farm as a spawning glade. " ..
                "Shadowstalker Getry has been staking out that monster for the past week and has gathered " ..
                "some vital information that might allow us to end this menace.\n\nGet to Getry and see " ..
                "if you can help him put a stop to this Scourge assembly line. You'll find Getry at the " ..
                "abandoned tower on the northwest border of these farms.",
        },
        [11704] = {
            description = "This is the weirdest thing, <class>, but there's a murloc asking for our " ..
                "help!\n\nHe goes by the name of King Mrgl-Mrgl, leader of the Winterfin murlocs. It " ..
                "would seem that he and his people have been run out of their village and they want " ..
                "someone to come save them.\n\nThat someone is you!\n\nYou'll find Winterfin Retreat, and " ..
                "the king, by heading west down the road until you come to the cliffs. Head down to the " ..
                "water line near the Blistering Pool.",
        },
        [11705] = {
            description = "This is madness. How do they expect us to take on a Scourge necrolord and an " ..
                "unknown number of his minions?\n\n<Getry sighs.>\n\nIf Ickoris sent you he must think " ..
                "that you are capable of great feats. Perhaps you will call down a miracle today, " ..
                "eh?\n\nWhen you're ready we will descend and face Varidus.\n\nIf we make it out of this " ..
                "mess in one piece, report back to Hellscream in Warsong Hold.",
            rewardChoices = {{37277, 1}, {37447, 1}, {37475, 1}, {37545, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [11706] = {
            description = "I have created and bound Alluvius using the Horn of Elemental Fury. He will " ..
                "respond to the horn's call when you stand near the southernmost sinkhole in the Geyser " ..
                "Fields.\n\nThe quake Alluvius will unleash should collapse the Nerubian tunnels and put " ..
                "an end to their flanking attack. I wouldn't be surprised if the Nerubian commander " ..
                "showed himself after the quake. If the collapse of the tunnels doesn't break the back of " ..
                "their assault, the defeat of their leader surely will.",
            rewardChoices = {{37228, 1}, {37375, 1}, {37437, 1}, {37516, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 94000,
        },
        [11707] = {
            description = "Oh good, you're <name>, right?\n\nWe need your help up north at Fizzcrank " ..
                "Airstrip, like yesterday! The magnataur, and the Scourge... and the pumping " ..
                "station!\n\nIt's madness I tell you, madness!\n\nYou've got to head up there and talk to " ..
                "old man Fullthrottle a.s.a.p.!",
        },
        [11708] = {
            description = "Now that you're here, it's time for me to tell you the full story of what's " ..
                "going on.\n\nAfter you've heard my tale, go outside and find my second-in-command, Jinky " ..
                "Wingnut. She'll handle everything from here on out.",
        },
        [11709] = {
            description = "While you have done much to secure our foothold in these frozen wastes, other " ..
                "dangers still lurk in the shadows. I want you to assist Warden Nork Bloodfrenzy, " ..
                "stationed at the internment camp just outside and immediately southeast of Warsong Hold. " ..
                "Seek him out and offer your assistance for prisoner transport and exchange.\n\nYou are " ..
                "dismissed, <name>.",
        },
        [11710] = {
            description = "There're spare parts strewn all over to the east in the Scalding Pools, the " ..
                "Geyser Fields... heck, probably even up on the pumping station still, too. Bring back a " ..
                "whole bunch. Maybe then I'll be able to get outgoing teleport on this thing working, not " ..
                "to mention getting the incoming transmatter ports aligned.\n\nI'd hate to see another " ..
                "accident....",
            rewardMoney = 47000,
        },
        [11711] = {
            description = "We're seeing more deserters show up at our gates with each passing day. We " ..
                "simply do not have enough room to keep all of these maggots caged up. Especially not if " ..
                "we want to keep the pigs happy.\n\n<Nork snorts as he laughs.>\n\nI want you to escort " ..
                "one of these cowards to the crossroads east of here and fire this flare gun. One of " ..
                "their captains will show up when they see the flare and take the coward off your " ..
                "hands.\n\nReport to Scout Tungok on the east road once the delivery has been made.",
        },
        [11712] = {
            description = "If you listened to the old man, then you know that we have gnomes out there " ..
                "that were changed. Gearmaster Mechazod infected them with something that reversed the " ..
                "\"Curse of the Flesh\", and now they're robots!\n\nWe think we have a way to re-curse " ..
                "them back to normal. We want you to take this re-cursive transmatter injection and use " ..
                "it on the corpses of any mechagnomes you come across.\n\nWe're hoping that this stuff " ..
                "will cure them and allow us to lock onto them to port 'em out of there.\n\nWhaddya say, " ..
                "<name>?",
            rewardChoices = {{37234, 1}, {37356, 1}, {37439, 1}, {37517, 1}},
            rewardMoney = 47000,
        },
        [11713] = {
            description = "Fizzcrank sent out an aerial surveillance team to map the Nerubian sinkholes " ..
                "in the southern part of the Geyser Fields, but they haven't yet returned. I can't afford " ..
                "to wait any longer for their information, so I'm going to need someone to check out the " ..
                "sinkholes on foot.\n\nI understand the dangers involved, and I'll compensate you " ..
                "accordingly. Take this map with you and record the vital information about each of the " ..
                "sinkholes you encounter out there.",
            rewardMoney = 94000,
        },
        [11714] = {
            description = "Perhaps you'd be interested in helping me clean up these fields? They're " ..
                "littered with dirty little rat men! Kobolds, snobolds, whatever you wanna call 'em, " ..
                "they're all over the damned place. The stink alone is making my life hell!\n\nTake care " ..
                "of the vermin for me and I'll make it worth your while, <name>.",
            rewardChoices = {{37205, 1}, {37404, 1}, {37481, 1}, {37524, 1}},
        },
        [11715] = {
            description = "I plan to build a machine that will collapse the tunnels the Scourge is using " ..
                "to deploy their Nerubians, but with the main drilling rig out of order, we'll have to " ..
                "collect the fuel for the device some other way.\n\nOut in the Geyser Fields to the " ..
                "southeast, small pools of oil bubble up away from the main rig. If you can collect " ..
                "enough of the oil from those pools, I can make a crude fuel to power the " ..
                "machine.\n\nSimply deploy the collector near the rig, and it will pump and store the oil " ..
                "in its tank.",
            rewardMoney = 47000,
        },
        [11716] = {
            description = "We are witnessing something amazing here, <race>. A whole undiscovered ecology " ..
                "lives and breathes not more than a few paces from us! I surmise it is the bloodspore " ..
                "plant that sets this environment abuzz.\n\nI have collected some pollen from the nearby " ..
                "male species of bloodspore plant but still lack female receptors for pollination. Fetch " ..
                "me a bushel of the bloodspore carpels. You'll find them near the larger plants " ..
                "surrounding us.\n\nBe wary of their guardians! The kobolds won't give them up easily!",
        },
        [11717] = {
            description = "It's obvious! The bloodspore moths are the entities responsible for " ..
                "pollination on these plains. It must be something that happens within the moth's " ..
                "internal system that acts as a catalyst for this pollen to work. It's all starting to " ..
                "make sense now, <name>. That's why the kobolds don't kill the moths and instead go to " ..
                "great lengths to protect them! Those stupid little rats have it all figured out!\n\nWell " ..
                "we'll just have to get our own moth pollen! What do you say? Fetch me some in the name " ..
                "of science?",
        },
        [11718] = {
            description = "I've reconfigured the skeleton of an old bot to create an earthquake large " ..
                "enough to collapse the tunnels, but the machinery is delicate and sensitive to " ..
                "Northrend's biting cold.\n\nI've devised a means of insulating it using the thickest " ..
                "hides of the native mammoths. They roam the plains south of the airstrip and adjacent to " ..
                "the Geyser Fields. Bring back enough of the hides for me to finish the machine and then " ..
                "we'll be able to unleash it on the Nerubians!",
            rewardMoney = 47000,
        },
        [11719] = {
            description = "<Laurith looks you over as if to size you up.>\n\nSo we've got this pollinated " ..
                "bloodspore flower and nobody to test its effects on. Say, would you perhaps be " ..
                "interested in rubbing this on your skin and letting me observe? What's the worst that " ..
                "could happen anyway?\n\nDon't you worry, <name>! Just take this sample and rub it all " ..
                "over your face.",
        },
        [11720] = {
            description = "Hellscream assigned Mighthorn and I with the daunting task of magnataur " ..
                "extermination on the southern front of Warsong Hold. With us came an entire platoon of " ..
                "seasoned Horde soldiers. Our initial foray into the nearby magnataur dens proved quite " ..
                "unsuccessful as our entire squad was wiped out by the lair defenders. We're the only " ..
                "ones left...\n\nWe aren't scientists or researchers. We're soldiers of the Horde, just " ..
                "like you. Soldiers on a mission that cannot fail...\n\nSpeak to Primal Mighthorn now.",
        },
        [11721] = {
            description = "Magnataur live in prides, much like lions: one or two dominant males and " ..
                "several females along with their offspring. In the case of Gammoth, the magnataur den " ..
                "west of here, Gammothra is the leader. It is Gammothra that controls this magnataur " ..
                "population and therefore it is Gammothra that must be slain to prevent any type of " ..
                "magnataur uprising.\n\nTake this pouch of crushed bloodspore flower to Gammoth. Use the " ..
                "powder from the pouch to weaken Gammothra and then slay him! Return his head to me as " ..
                "proof.",
        },
        [11722] = {
            description = "We cannot take all of the credit for this Horde victory, <name>. It was you " ..
                "who risked your life to test the bloodspore and it was you who ultimately put an end to " ..
                "Gammothra.\n\nHonor us by returning to Warsong Hold and presenting the head of Gammothra " ..
                "to Lord Hellscream.",
            rewardChoices = {{37204, 1}, {37405, 1}, {37415, 1}, {37480, 1}},
        },
        [11723] = {
            description = "Behold, the machine that will save us from the Nerubian threat!\n\n<Abner " ..
                "beams with pride as he presents the finished bot.>\n\nTake this remote control with you, " ..
                "and go out to the southernmost of the Nerubian sinkholes in the Geyser Fields. Use the " ..
                "remote to activate the Shake-n-Quake 5000. It will do the rest on its own.\n\nDon't be " ..
                "surprised if the quake it creates attracts the attention of a Nerubian leader. In fact, " ..
                "it would be a great opportunity to finish off the Nerubian offensive.",
            rewardChoices = {{37228, 1}, {37375, 1}, {37437, 1}, {37516, 1}},
            rewardMoney = 94000,
        },
        [11724] = {
            description = "This egg was obviously important to somebody, as the corpse nearby can attest. " ..
                "As you look the egg over you notice that it has already been tagged for shipment to the " ..
                "Bloodspore Plains, care of Bloodmage Laurith. That's just east of here!\n\nCollect the " ..
                "egg and take it to the expectant Bloodmage.",
        },
        [11725] = {
            description = "I should've flown the mission myself. It's not that I don't trust Tailspin. " ..
                "Far from it. Heck, he was the best wingman I ever flew with.\n\nNo, it's just that it's " ..
                "my responsibility to lead a mission of such import.\n\nI sent Tailspin out with our " ..
                "fastest recon squadron to gather information about the Nerubian infestation in the " ..
                "middle of the Geyser Fields.\n\nThe last report we received placed his squadron in the " ..
                "pools to the far south and just west of the Nerubian sinkholes.\n\nFind Tailspin, <name>.",
        },
        [11726] = {
            description = "The wolves have been pawing through the wreckage ever since the crash and I'm " ..
                "afraid they consumed the microfilm from our mission in the process.\n\nI have a plan to " ..
                "recover that microfilm, but I need your help to make it work.\n\nTo the south and east, " ..
                "in the Flood Plains, live creatures called gorlocs. They prepare their foods with " ..
                "noxious spices, which would sicken any other creature. If you can gather enough of the " ..
                "spice pouches from gorloc steam belchers or gorloc waddlers, I can make the wolf bait.",
            rewardMoney = 47000,
        },
        [11727] = {
            description = "It's good to have you among us, <name>. We've all heard of your past " ..
                "deeds.\n\nAs you know, King Wrynn is moving great armies into Northrend to meet those of " ..
                "Arthas. But armies are nothing without true heroes to inspire and lead them.\n\nI want " ..
                "you to be that hero for my men. Fight alongside them against the Scourge that lays siege " ..
                "to our stronghold.\n\nReport to Sergeant Hammerhill outside the inner hold. Valiance " ..
                "Keep cannot fall. The future of our campaign depends on it.",
        },
        [11728] = {
            description = "Whatever you do, don't eat this bait yourself. Just set it down in the " ..
                "vicinity of an oil-soaked wolf. If they're desperate enough to eat the microfilm, " ..
                "they'll come running when they smell the bait.\n\nSimply wait for nature to take its " ..
                "course and then all you need to do is search the, uh... byproduct for the film.\n\nI'd " ..
                "offer you my special lupus pupus scupus for the job, but I left it back at the airstrip. " ..
                "I'm afraid you'll have to conduct the... err... search the old-fashioned way.",
            rewardMoney = 47000,
        },
        [11729] = {
            description = "The unit you just dismantled had this inside of its mechanical innards.\n\nIt " ..
                "looks pretty complicated... certainly someone back at the airstrip would want to take a " ..
                "look at it. Maybe Crafty Wobblesprocket?",
        },
        [11730] = {
            description = "The Ultrasonic Screwdriver is the ultimate tool. It can do anything to " ..
                "mechanical stuff!\n\nHead back into the pools and dismantle a number of Mechazod's " ..
                "robots. Then all you have to do is use the screwdriver on their remains, and I'm betting " ..
                "that they'll turn to our side, for a short time anyway.\n\nI'm pretty sure it won't work " ..
                "on the mechagnomes, so don't even bother with them.\n\nOh, and if you want to take " ..
                "anything from the robot's insides, you'll want to do so before using the screwdriver!",
            rewardChoices = {{37270, 1}, {37353, 1}, {37441, 1}, {37479, 1}},
            rewardMoney = 94000,
        },
        [11733] = {
            description = "I've been mindful of your efforts, mortal. Do not feign surprise. Surely " ..
                "you've felt my eye upon you.\n\nThe time has come to peel back a layer of darkness from " ..
                "your mind. There are stark truths that you have grown ready to accept.\n\nBefore hearing " ..
                "the tale, you shall be shown firsthand what we face.\n\nPut your affairs in order, " ..
                "<class>....",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 37000,
        },
        [11788] = {
            description = "Okay, I think we're ready for the penultimate assault... before you can bring " ..
                "down Mechazod, you're going to have to dismantle his lieutenants first!\n\nYou'll find " ..
                "Twonky, ED-210, Max Blasto, and The Grinder at the West Point, North Point, Mid Point " ..
                "and South Point stations, respectively.\n\nTo get them to show up, just turn the valves " ..
                "at the stations to mess up whatever they're trying to do out there. You can't miss the " ..
                "places, they all have spinning lights.",
            rewardMoney = 94000,
        },
        [11789] = {
            description = "You there! Please, I need your help. This soldier will succumb to the " ..
                "cryptfiends' venom unless we act immediately.\n\nI've managed to slow down the poison, " ..
                "but without a suitable supply of antidote I cannot counteract it.\n\nI was promised a " ..
                "new shipment of anti-venom in the Stormbreaker's most recent trip from the south. Go " ..
                "inside its hold and search for a chest of first aid supplies.\n\nHurry, <class>! We " ..
                "can't afford to lose any more men unnecessarily.",
            rewardItems = {{22850, 2}},
        },
        [11791] = {
            description = "We must notify General Arlos at once. I've known the captain for a long time " ..
                "and, believe me, he is one of the more careful ones.\n\nWho knows how many cultists have " ..
                "been smuggled into our settlements in Northrend in other ships? This could be disastrous.",
        },
        [11792] = {
            description = "Not so fast there. I don't know about you, <class>, but I was hardly convinced " ..
                "by the general's words. They rung unsure... as if they were not his own.\n\nSomething's " ..
                "amiss here. All of our efforts to collaborate have been blocked and delayed. It is time " ..
                "we took a more independent approach.\n\nIf we're to learn more about the cultists inside " ..
                "the keep... perhaps we should investigate those outside.\n\nIntelligence reports a small " ..
                "group of them aiding the Scourge north of here. See if they carry any clues.",
            rewardChoices = {{36888, 1}, {36937, 1}, {36938, 1}, {38213, 1}},
        },
        [11793] = {
            description = "I'm afraid this is a matter I must delegate to one of my operatives... someone " ..
                "who can work in secret. Keep the evidence with you and take it to Vindicator Yaala " ..
                "inside the inn.\n\nTell her I sent you and speak of this matter to no one else. We do " ..
                "not know who might be working for the cult.",
        },
        [11794] = {
            description = "I've made it my business to learn as much as possible about the vile death " ..
                "cult, including their secret language.\n\nVurenn was right. The cultists mention " ..
                "disguised operatives in various locations in Valiance Keep: the lower docks, the jail " ..
                "inside the inner hold and in the inn's kitchen.\n\nTake this oculus. Use it at those " ..
                "three locations - anyone that has recently used the cult's necromancy will be enshrouded " ..
                "by a dark aura. Take care of the cultists before something nefarious happens.",
            rewardChoices = {{37204, 1}, {37405, 1}, {37415, 1}, {37480, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [11795] = {
            description = "Injured or not, as squadron commander, I'm responsible for locating and " ..
                "returning the insignia of all fallen pilots under my command. In all the years I've " ..
                "flown with Fizzcrank, we've never failed to return the signet of a pilot.\n\nMy injuries " ..
                "make it dangerous for me to stray far from the safety of the wreckage, but perhaps you " ..
                "would be willing to help me recover the insignia? In the meantime, I'll make " ..
                "preparations to carry out my final duty as squadron commander.",
            rewardMoney = 47000,
        },
        [11796] = {
            description = "There's only one more thing left to do before I can finally return to the " ..
                "airstrip and make my report. Section 8.2, paragraph D of the emergency protocol requires " ..
                "me to scuttle as much of the wreckage as possible, in order to prevent our technology " ..
                "from falling into enemy hands.\n\nI'll give you my torch if you agree to help me " ..
                "complete this last duty. I don't want to think about what the Horde's goblin allies will " ..
                "do if these machines fall into their hands.",
            rewardMoney = 47000,
        },
        [11797] = {
            description = "Well, well, well. It's good to see Arlos bring out the big guns.\n\nDon't get " ..
                "me wrong - our lads are doing the best they can, but someone of your renown fighting " ..
                "alongside them could really turn the tides for us. I'm not sure how much longer we can " ..
                "hold out against these undead Nerubians.\n\nWhat do you say you get out there and kill " ..
                "me some creepers? Show these boys how it's done.",
            rewardChoices = {{36878, 1}, {36879, 1}, {36880, 1}, {36881, 1}, {36883, 1}, {38208, 1}},
            rewardMoney = 47000,
        },
        [11798] = {
            description = "Gearmaster Mechazod is insane! He says that he offers us immortality by " ..
                "removing this so-called 'Curse of the Flesh', but what he's really making are robotic " ..
                "slaves!\n\n<name>, we're pretty certain that he's still at the pumping station out in " ..
                "the middle of the pools to the east.\n\nThe last we saw of him, he was in the command " ..
                "hut up top. Go up there and research his stuff.\n\nYou must confront Mechazod if gnomes " ..
                "everywhere,... no, everyone everywhere, are to stay alive!",
            rewardChoices = {{37274, 1}, {37352, 1}, {37442, 1}, {37530, 1}},
            rewardMoney = 100000,
        },
        [11865] = {
            description = "Just south of us the caribou used to roam freely, peacefully. Then Nesingwary " ..
                "showed up and everything changed. Now the caribou are in a perpetual state of frenzy, " ..
                "always in a panic. They are stalked by the hunters and trappers hidden in the " ..
                "field.\n\nNesingwary's executioners are unfit for death. They must feel the torture that " ..
                "they put the caribou through!\n\nTake this pile of fake furs and lay it upon their " ..
                "caribou traps to the south. Watch as the hunters are caught in their own deadly traps!",
        },
        [11866] = {
            description = "Whether they be treasure seekers or bloodthirsty hunters of the wastes, any " ..
                "being that supports Nesingwary and dares to strike at our beloved wildlife shall be " ..
                "considered an enemy of D.E.H.T.A.\n\nShould you slay these filthy Nesingwary " ..
                "sympathizers, bring me proof of their demise and you shall be rewarded with a blessing " ..
                "from the druids of D.E.H.T.A.",
            rewardMoney = 50000,
        },
        [11867] = {
            description = "Whether they be treasure seekers or bloodthirsty hunters of the wastes, any " ..
                "being that supports Nesingwary and does dare strike at our beloved wildlife shall be " ..
                "considered an enemy of D.E.H.T.A. Should you slay these filthy Nesingwary sympathizers, " ..
                "bring me proof of their demise and you shall be rewarded with a blessing from the druids " ..
                "of D.E.H.T.A.",
        },
        [11868] = {
            description = "Near the southern end of this bluff is where you will find the treacherous " ..
                "leader of the caribou trappers. She is a savage like no other, making a mockery out of " ..
                "the carcasses of the slain animals: drinking from their blood and howling to the " ..
                "moons!\n\nFind this murderer, Karen, and end her worthless existence.\n\nPrepare " ..
                "yourself properly, <name>. Karen the Culler has indulged in the riches that Nesingwary " ..
                "has lavished upon her!",
            rewardChoices = {{36939, 1}, {36998, 1}, {37002, 1}, {37004, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 50000,
        },
        [11869] = {
            description = "To the west of us you will find Lake Kum'uya. It is, as far as we know, the " ..
                "only freshwater giant clam habitat in the world.\n\nOf course Nesingwary's lackeys are " ..
                "now using the lake as a giant pearl farm. They must be stopped! A lesson must be taught " ..
                "to those that would think to endanger an entire species.\n\nGo to Lake Kum'uya and " ..
                "locate the loot crazed divers. Slay them until the water runs red! Return to me when a " ..
                "proper example has been made!",
        },
        [11870] = {
            description = "We have just gotten word from Liandra that mercenaries hired by Nesingwary are " ..
                "moving goods off the beach and onto the main Nesingwary shipping vessel. No doubt they " ..
                "plan on making a fortune from their murderous trade!\n\nShe has asked that we send " ..
                "assistance to the Abandoned Reach, directly south of here on the beachfront of the " ..
                "Borean Tundra.\n\nMake haste, Liandra awaits you there!",
        },
        [11871] = {
            description = "Strewn across this beach, amidst the flotsam and jetsam, are crates and sacks " ..
                "of animal parts. It would seem that Nesingwary is in cahoots with the Northsea " ..
                "Freebooters. Those dirty pirates are transporting the goods that Nesingwary's murderous " ..
                "lackeys gather offshore. No doubt they will end up in the homes and on the backs of " ..
                "wealthy, unscrupulous individuals across Azeroth.\n\nThis won't happen. Not on our " ..
                "watch. Bring me all shipments that you find upon this beach. They'll never have them!",
        },
        [11872] = {
            description = "It's despicable, really, to anoint one's self as the \"Clam Master,\" as if " ..
                "they hold mastery over the creatures of the sea. None may make such claims!\n\nThis " ..
                "\"Clam Master\" must be found and slain. He was last seen at the wreckage just off the " ..
                "coast of the Abandoned Reach. Find him and kill him.\n\nOnce this is done, return to " ..
                "Hierophant Cenius at the D.E.H.T.A. Encampment, north of here, and let her know that the " ..
                "mission was a success.",
            rewardChoices = {{37014, 1}, {37015, 1}, {37016, 1}, {37017, 1}, {37018, 1}, {37019, 1}},
        },
        [11873] = {
            description = "Would you be willing to head back to the airstrip and let Fizzcrank know that " ..
                "I'll be along shortly to give my formal report? I've got to deal with the wreckage of my " ..
                "flying machine, and then I'll be on my way.\n\nI'll be certain that Fizzcrank knows that " ..
                "he has you to thank for my survival and the recovery effort.\n\nI only wonder what the " ..
                "old man would've done himself if he'd been flying with us. I miss those days.",
            rewardChoices = {{37275, 1}, {37351, 1}, {37443, 1}, {37478, 1}},
            rewardMoney = 94000,
        },
        [11875] = {
            description = "The troops of the Shattered Sun Offensive will need every advantage they can " ..
                "get to beat back the allies of Kil'Jaeden. My colleagues in Stormwind have created oils " ..
                "which will strengthen the blades and armor of our troops.\n\nThe key ingredient, nether " ..
                "residue, pervades Outland -- if you know where to look. Any master herbalist, skinner, " ..
                "or miner who knows the signs can gather it while plying <his/her> trade. Those herbs, " ..
                "ores, and beasts native to Outland may all bear the residue.",
            rewardItems = {{18253, 1}},
            rewardMoney = 88000,
        },
        [11876] = {
            description = "They're majestic beasts, aren't they?\n\n<Lathorius points towards the " ..
                "mammoths of the northern tundra.>\n\nWith each passing day their numbers diminish. " ..
                "Demons that call themselves hunters slay the beasts for sport and riches.\n\n<Lathorius' " ..
                "face contorts with anger.>\n\nIt's the whimpers that drive me to madness, <name>. You " ..
                "can hear them, carried by the wind. The mammoth calves, trapped in the hunters' vile " ..
                "traps, call out to us.\n\nTake this hammer and smash those traps. Free the calves!",
        },
        [11877] = {
            description = "As we press the offensive on Quel'Danas, we've discovered that Kael'thas' " ..
                "minions are planning a counterattack. By ordering the Sunfury blood elves, based in " ..
                "Netherstorm, to attack our operations in Outland, he hopes to draw troops and attention " ..
                "away from the Sunwell.\n\nWe must not allow this to happen, <name>. Each and every blade " ..
                "is needed on the front lines.\n\nGo to Netherstorm and capture their attack plans. Any " ..
                "of the Sunfury blood elves up there could be in possession of the plans. Good luck, " ..
                "<name>.",
            rewardItems = {{35232, 1}},
            rewardMoney = 44000,
        },
        [11878] = {
            description = "Although you have acted valiantly in freeing the trapped calves, many of them " ..
                "will still die. You see, without a caretaker, these calves must fend for themselves in " ..
                "the wild.\n\nBut there is a way! Hope yet remains!\n\nNorth of here in the mammoth " ..
                "fields, bordering the Scalding Pools, you will find Khu'nok the Behemoth: a mammoth as " ..
                "wise as he is ancient. Take this mammoth orphan and present it to Khu'nok. He will know " ..
                "what to do.",
        },
        [11879] = {
            description = "You cannot defeat the being responsible for the slaughter of my kind by " ..
                "yourself. The mammoths of the tundra will help you!\n\nVenture forth to the plains and " ..
                "find a mammoth bull. He will allow you to mount him and control his movements and " ..
                "actions. Ride upon his back and find Kaw, north of here at Kaw's Roost. Together, you " ..
                "will be the instrument of Kaw's demise.\n\nDestroy Kaw's armies and take from Kaw his " ..
                "coveted war halberd. Return to Lathorius at the D.E.H.T.A. Encampment should you succeed.",
            rewardChoices = {{37005, 1}, {37007, 1}, {37008, 1}, {37009, 1}},
        },
        [11880] = {
            description = "I'm sure that 'gnomish inventor' is a crackpot. He was babbling about some " ..
                "dark distortions that have begun to appear in the Spirit Fields around Oshu'gun in " ..
                "Nagrand.\n\nAccording to him, these, uh, multiphase... um, spectro-goggles will allow " ..
                "the wearer to see the distortions and take readings from them. He insisted that " ..
                "recording this data was fundamental to our campaign at the Sunwell. I think he's nuts, " ..
                "but I'm under orders to investigate anything that might help. Would you mind taking some " ..
                "readings?",
            rewardMoney = 34000,
        },
        [11881] = {
            description = "Have you seen the flying machines buzzing around? That's gnomish innovation at " ..
                "its finest.\n\nI've long waited to get my hands on some of their technology and a " ..
                "perfect opportunity has presented itself. One of their recon wings crashed in the " ..
                "Scalding Pools, in the southwest part of the Geyser Fields.\n\nBlow this whistle near " ..
                "one of the crashed machines and my trusty mule, Jenny will answer. She'll follow you and " ..
                "carry the salvage, but you must keep her safe. She'll begin to drop the cargo if " ..
                "attacked.",
            rewardMoney = 47000,
        },
        [11884] = {
            description = "West of here, on the high bluffs above Lake Kum'uya, roams a despicable being " ..
                "known as Nedar. The self proclaimed \"Lord of Rhinos\" hunts the wastes for the injured " ..
                "or young - rhinos unable to defend themselves against his cowardly attacks. To add " ..
                "insult to injury, Nedar has raised a rhino of his own to become his mount and " ..
                "bodyguard.\n\nIt is a rare thing that D.E.H.T.A. would ever call for the death of an " ..
                "animal, but Nedar's tainted rhino must be disposed of... Kill them both and return to me.",
            rewardChoices = {{37203, 1}, {37406, 1}, {37414, 1}, {37520, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [11885] = {
            description = "The descendants held prisoner by the Skettis talonpriests are listed in this " ..
                "book: Gezzarak the Huntress, Karrog the crystal giant, the heretic known as " ..
                "Darkscreecher Akkarai and Vakkiz the Windrager. They will all need to be slain before " ..
                "Terokk returns to this world.\n\nYou will need the scrolls carried by the time-lost " ..
                "arakkoa to call them forth at the summoning circles in Skettis. These are powerful " ..
                "beings you will be facing; you would do well to bring friends.",
            rewardItems = {{32720, 1}},
        },
        [11887] = {
            description = "Rifling through the dead gnome's possessions, you come across a small packet " ..
                "filled with rations, tools, and a handy roll of gnomish duct tape. The contents of these " ..
                "kits might prove helpful to Fezzix Geartwist when it comes time for him to reassemble " ..
                "the wreckage of the gnomish flying machines.\n\nBringing a few of these kits to Fezzix " ..
                "might just be worth a nice bonus.",
            rewardMoney = 47000,
        },
        [11888] = {
            description = "<race>, the chieftain is making me wait... time that Taunka'le does not " ..
                "have!\n\nThere has been talk of your prowess. Rather than wait for Garrosh to send help, " ..
                "I ask you to go and help my people.\n\nTaunka'le village lies far to the northeast. " ..
                "Follow the road east out of the hold, turning north at the intersection. Not long after, " ..
                "you will come to another intersection. Follow the path east, passing south and then east " ..
                "of the great pools along the flood plains.\n\nSpeak with Sage Earth and Sky when you " ..
                "arrive.",
        },
        [11889] = {
            description = "We're doing a good job of holding the front lines against these bugs. Some of " ..
                "these cheeky fiends, however, can fly over the aforementioned front lines and are really " ..
                "beating down on our inner defenses.\n\nI've requisitioned reinforced fishing nets from " ..
                "our civilian ships. If you've got a good enough throwing arm, they'll help you knock the " ..
                "enemy out of the sky. Thin their numbers so that our defenses can hold the keep.",
            rewardMoney = 47000,
        },
        [11890] = {
            description = "The gnomes have run into some trouble in the pools to the west. It serves them " ..
                "right as they have been fouling up the land with their so-called inventions.\n\nI want " ..
                "you to go out to their pumping station and observe what has befallen them. Return to me " ..
                "after.",
            rewardMoney = 47000,
        },
        [11892] = {
            description = "You have done much for the animals of the Borean Tundra, <name>. Nesingwary's " ..
                "lackeys have been beaten back and taught a lesson that they will not soon " ..
                "forget.\n\nHarold Lane, the primary agent responsible for the mass slaughters in " ..
                "Nagrand, has been identified as the man in charge of Nesingwary operations in the " ..
                "tundra. He is stationed at Lake Kum'uya, west of here.\n\n<Lathorius hands you an " ..
                "intricately carved oak horn.>\n\nFind Lane and kill him. Use this horn should you " ..
                "require our aid.",
            rewardChoices = {{38252, 1}, {38251, 1}, {38250, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [11893] = {
            description = "I kept trying to tell that silly goblin his machines are unreliable.\n\nBut " ..
                "the power of the elements; that is deep and abiding. When my apprenticeship is over, I " ..
                "will wield their full power. What I know now should be sufficient to help out our friend " ..
                "Fezzix, though.\n\nTake this windsoul totem and plant it near any of the steam ragers to " ..
                "the west of the village. The totem will gather up the energies of slain elementals. " ..
                "Return the fully charged totem to me and I'll do the rest.",
            rewardMoney = 47000,
        },
        [11894] = {
            description = "Remember all that gnomish duct tape you brought me?\n\nWell, I've found a use " ..
                "for it. The body of this flying machine is so banged up in places, that I'm going to " ..
                "need to reinforce it if I ever hope to fly.\n\nDorain over there has been telling me " ..
                "that the taunka use steam cured caribou leather for making watertight containers. Marsh " ..
                "caribou live all around the village and in the Flood Plains to the south. Get the best " ..
                "hides you can find and cure them over the steam vents in the Geyser Fields.",
            rewardChoices = {{37272, 1}, {37388, 1}, {37428, 1}, {37526, 1}},
            rewardMoney = 94000,
        },
        [11895] = {
            description = "From what you describe, the creatures of metal should be easy to deal with. " ..
                "But first, you must master the storm.\n\nBehind me in the lodge is a totem. When you are " ..
                "ready, focus your will upon it and the storm will come. You must defeat the storm and in " ..
                "so doing take its essence into yourself.\n\nIf others are there, it is enough that you " ..
                "all work together to defeat it. Return to me after, <class>.",
            rewardMoney = 47000,
        },
        [11896] = {
            description = "You now have the power of the storm within you. I will give you the means to " ..
                "focus that power and weaken the robots in the pools.\n\nTake this lightning rod. Use it " ..
                "against the robotic creations of the mechagnomes you find within the greater pools area " ..
                "to the west. Do not worry about using it against the mechagnomes themselves; Greatmother " ..
                "Taiga has other plans for them.\n\nOnce the robots are weakened by the power of the " ..
                "storm, dismantle them utterly!",
            rewardMoney = 47000,
        },
        [11897] = {
            description = "The Scourge are showing no sign of letting up, <name>. It's those blasted " ..
                "sinkholes; they connect to tunnels all the way to Icecrown for all we know. Giant undead " ..
                "worms burrow under the ground to create them.\n\nIf there's something years of mining " ..
                "has taught me it's that without support beams, tunnels will cave in easily after an " ..
                "explosion.\n\nTake these explosives and place them at the entrance to the sinkholes up " ..
                "on the ridge beyond the beach to the west. Come back after you've collapsed them.",
            rewardChoices = {{36884, 1}, {36885, 1}, {36886, 1}, {36887, 1}},
        },
        [11898] = {
            description = "On the lowest tier of the Temple City, there is a gray altar bathed in light. " ..
                "Step into it to gain entry to the dread necropolis Naxxanar.\n\nBe cautious, <name>. " ..
                "Prince Valanar will certainly be defended by his personal retainers, who will give their " ..
                "lives to keep you from ascending to the top level of the necropolis.\n\nYou must find " ..
                "your way through the necropolis to the prince's seat. If you fail to defeat him, <name>, " ..
                "I fear my people will never know the safety Icemist offers.",
            rewardChoices = {{38232, 1}, {38230, 1}, {38231, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 94000,
        },
        [11899] = {
            description = "The mechagnomes in the pools to the west are a great mystery to us. They " ..
                "appeared not long after the gnomes disappeared from their pumping station and its " ..
                "environs.\n\nThey are an unnatural danger and must be dealt with.\n\nTake this " ..
                "soulcatcher and use it on the remains of the mechagnomes to capture their souls. When " ..
                "you return, we will set them free so that we might find out what happened.",
            rewardMoney = 47000,
        },
        [11900] = {
            description = "I had hoped that the Nexus' impact was limited to this region. Recently " ..
                "though, reports have flooded in from all over Azeroth suggesting that geologic " ..
                "instability is growing exponentially!\n\nI need the Nexus monitored regularly as I work " ..
                "to develop a solution.\n\nI've placed sensitive instruments around Coldarra, disguised " ..
                "as Malygos' scrying orbs. One lies in the trench near the Nexus, and three are hidden in " ..
                "the structures around the valley's perimeter. Visit each and return to me with their " ..
                "readings.",
            rewardMoney = 47000,
        },
        [11901] = {
            description = "There's Scourge everywhere, <class>. We've organized the farmers and miners " ..
                "into a militia, but this just won't cut it.\n\nThe one detachment of troops that " ..
                "Valiance Keep sent is defending the mine. We haven't heard from them in days!\n\nIf you " ..
                "really wish to help us, why don't you go to the mine and see what's going on? Maybe we " ..
                "can get them to send us some reinforcements.",
        },
        [11902] = {
            description = "The sacks of grain emanate the foul stench you've come to associate with the " ..
                "Plague. This probably explains what happened to the footmen defending the mine.\n\nYou'd " ..
                "best bring word back to Gerald Green.",
        },
        [11903] = {
            description = "Well, <name>. With the last of our military in Farshire dead or worse, we can " ..
                "do but one thing: fight these Scourge ourselves.\n\nWe have deployed militia in what " ..
                "remains of Farshire. Without your help, they've but little hope of winning. Go and lend " ..
                "them a hand. Me and the lads will watch this path. We can't let the Scourge break " ..
                "through!",
            rewardChoices = {{37208, 1}, {37402, 1}, {37484, 1}, {37543, 1}},
            rewardMoney = 47000,
        },
        [11904] = {
            description = "The Scourge just keeps coming... but we can't give up! Listen, <name>. Inside " ..
                "that mine there's a cart with the last of the ore the Alliance is going to see on this " ..
                "side of the continent for a long time.\n\nThe problem is the cart release is locked. " ..
                "When the military went in there, Captain Jacobs commandeered all the important " ..
                "equipment, including the cart release key.\n\nThe plague that affected the soldiers in " ..
                "the mine must also have affected Jacobs. Get the key from him and salvage the ore.",
        },
        [11905] = {
            description = "Azeroth's ley lines are being redirected to the Nexus.\n\nThe influx of arcane " ..
                "energies is tearing a rift between dimensions.\n\nI cannot stop it, but I've discovered " ..
                "a way to slow it down.\n\nTake this and activate it near the forming rift.",
            rewardChoices = {{42758, 1}, {42761, 1}, {42763, 1}, {42765, 1}},
            rewardMoney = 188000,
        },
        [11906] = {
            description = "<A single tear rolls down the face of Iron Eyes.>\n\nI have heard that you are " ..
                "heading back into the pools to the west. I have something for you to do while you are " ..
                "out there, <race>.\n\nThe gnomes, who care nothing for the land, have polluted it with " ..
                "their machinery. I want you to pick up any spare parts that you come across.\n\nReturn " ..
                "them to me here. I will see to it that they are properly disposed of before we leave " ..
                "this place for good.",
            rewardChoices = {{37275, 1}, {37351, 1}, {37443, 1}, {37478, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 47000,
        },
        [11907] = {
            description = "It is known that Gearmaster Mechazod has four sub-chieftains that manage the " ..
                "robots in the pools.\n\nWe must put an end to them!\n\nOur longrunners and snow trackers " ..
                "say that if you were to turn the valves at the west point, north point, mid point and " ..
                "south point stations, each of his sub-chieftains would come quickly to prevent you from " ..
                "fouling their operations.\n\nThe stations are centered on the spinning lights in the " ..
                "pools surrounding the pumping station.\n\nHurry, <name>!",
            rewardChoices = {{37054, 1}, {37072, 1}, {37073, 1}, {37357, 1}, {37231, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 94000,
        },
        [11908] = {
            description = "I was in charge of the harvest golems - an important job until the Scourge " ..
                "destroyed most of our farmlands. I've an idea that would make the golems useful again, " ..
                "however.\n\nI think I can rewire the harvest collectors so they'll give us a hand " ..
                "fighting the Scourge.\n\nI'm not an expert at this just yet, so I'm going to need my " ..
                "manual. The problem is, I left it at the workshop... which happens to be that burning " ..
                "building next to the mine. Think you could go salvage it?",
            rewardMoney = 47000,
        },
        [11909] = {
            description = "Clearly this Gearmaster Mechazod creature is not in his right mind. If his " ..
                "offer of a cure and immortality means all of us becoming robotic slaves then he must be " ..
                "stopped!\n\nThe winds that guide me whisper that he's atop the pumping station out in " ..
                "the middle of the pools to the west.\n\nMost likely, he'll be found in the command hut " ..
                "on top of the structure. Go inside and research his works.\n\n<name>, you must confront " ..
                "Mechazod if we are to survive!",
            rewardChoices = {{37122, 1}, {37522, 1}, {37535, 1}, {37537, 1}, {37547, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 100000,
        },
        [11910] = {
            description = "It's become clear that the instability in the region has had an effect on its " ..
                "indigenous creatures.\n\nI've taken a particular interest in the Glacial Ancients and " ..
                "their recent adaptations. I suspect that their transformation into these 'Magic-bound' " ..
                "Ancients may hold clues to our predicament here.\n\nFor my studies, I'll need samples " ..
                "from both. Do hurry....",
            rewardMoney = 47000,
        },
        [11911] = {
            description = "I've learned more in my short time here than in decades of studies.\n\nThe " ..
                "ancients here are being exposed to incredible levels of arcane energy. It's literally " ..
                "transforming them into something...\n\nI'm confident that there's a final stage in their " ..
                "metamorphosis. Find me some evidence of their final state.",
            rewardChoices = {{42760, 1}, {42762, 1}, {42766, 1}, {42767, 1}, {42768, 1}},
            rewardMoney = 188000,
        },
        [11912] = {
            description = "Oh! What a relief it is to see a fresh face. I was beginning to feel we had " ..
                "been forsaken.\n\nOur supply lines were cut off days ago, and things have been looking - " ..
                "well, bleak. To be honest, this was a suicide mission to begin with if you ask " ..
                "me.\n\nMaybe I'm simply not cut out for all of this violence - to say nothing of the " ..
                "bitter cold! I'd much rather be back in Dalaran studying ancient texts.\n\nTo the point, " ..
                "our food supply is nearly spent. Please, gather what you can and bring it to me.",
            rewardMoney = 47000,
        },
        [11913] = {
            description = "I heard what you told Gerald and I don't like it one bit. If cultists managed " ..
                "to poison the grain in the mines with their foul plague, they could've easily done the " ..
                "same with the grain outside.\n\nWe don't have time to sort the good grain from the bad. " ..
                "We must act quickly and burn it all.\n\nTake this torch and set fire to any sacks of " ..
                "grain you find out here. It would be a tragedy if we survived this attack only to " ..
                "succumb to the plague afterwards.",
            rewardChoices = {{37205, 1}, {37404, 1}, {37481, 1}, {37524, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 47000,
        },
        [11914] = {
            description = "Our existence here depends entirely upon staying hidden. Should the shield " ..
                "fail, even for a moment, Malygos' minions would have us.\n\nOne of my responsibilities " ..
                "is to rejuvenate the warmages' mana levels so their focus doesn't falter. With our " ..
                "supply lines lost, I've been forced to improvise.\n\nI could use your help, " ..
                "<name>.\n\nVery near the Nexus, Arcane Serpents feast on the abundant magical energies. " ..
                "Once defeated, they will yield a mana essence that I can make use of.",
            rewardChoices = {{37383, 1}, {37434, 1}, {37512, 1}, {37559, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 47000,
        },
        [11916] = {
            description = "You have faced all challenges that have been set before you and squashed them " ..
                "beneath your boot heel. It is because of you, <name>, that the Horde is now firmly " ..
                "entrenched in Northrend.\n\nBut our work has only just begun. We must march to Icecrown " ..
                "and we must tear down its walls!\n\nYour next assignment begins to the east, at " ..
                "Taunka'le Village. Our taunka allies are in dire straits and require aid. Secure " ..
                "transport from the stable master, Durkot Wolfbrother, and seek out Chieftain Wintergale " ..
                "at Taunka'le.",
            rewardChoices = {{38237, 1}, {38238, 1}, {38239, 1}, {38240, 1}, {38241, 1}, {38242, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [11918] = {
            description = "This is war, mortal, and we are the tip of the spear.\n\nYour little spats " ..
                "over land or currency pale in comparison to this conflict. We face the aspect Malygos " ..
                "and his entire blue dragonflight. All you need to know is that if he is victorious, this " ..
                "world shall be no more.\n\nWe are but few here, and we fly against many. Our deaths are " ..
                "all but a certainty, and our ultimate success lies in merely delaying our enemy.\n\nGo " ..
                "now. Busy yourself while I decide what to do with you.",
            rewardMoney = 47000,
        },
        [11919] = {
            description = "The blues have begun to cover their drakes in mysterious runes. I must " ..
                "discover their significance.\n\n< Raelorasz pokes his hand with a spear and coats the " ..
                "tip with his blood.>\n\nTake this and use it on one of them. Wait for it to become " ..
                "subdued, then bring it here to me before it expires.\n\nTheir hatchlings feed around the " ..
                "northwest edge of the valley.",
            rewardChoices = {{37226, 1}, {37382, 1}, {37435, 1}, {37513, 1}},
            rewardMoney = 47000,
        },
        [11920] = {
            description = "This altar bears all the markings of the Cult of the Damned. It appears " ..
                "fanatics from the mainland have made it into Northrend. It might be prudent to notify " ..
                "the captain of the ship.\n\nPerhaps he is to be found above deck.",
        },
        [11927] = {
            description = "Hey, <name>. There's a girl in the inn that's asking about you. Her name's " ..
                "Leryssa.\n\nI don't think she knows you, but she said she needed your help. She sounded " ..
                "really desperate.",
        },
        [11928] = {
            description = "My lads should be able to take it from here, <name>. Valiance Keep is built to " ..
                "take a beating far worse than this. I worry about our farmlands and mine in Farshire, " ..
                "however.\n\nWe sent a full detachment to protect our mining operations right before the " ..
                "invasion - they should be able to defend the civilians.\n\nGerald Green 's in charge of " ..
                "the villagers there. There's a passage out of the northern wall out of Valiance Keep; " ..
                "it'll take you straight to him. See what you can do to help them.",
        },
        [11929] = {
            description = "We are lost, <name>. This place has been our home for many generations, but it " ..
                "is no longer safe. There remains only death... Death and a memory of what used to " ..
                "be.\n\nI have called for the evacuation of Taunka'le. All remaining taunka must leave at " ..
                "once and make their way to our capital city, Icemist, located in the " ..
                "Dragonblight.\n\n<Wintergale points east.>\n\nYou must help get my people to safety, " ..
                "<name>. Mother Tauranook awaits you at the village gates. Hurry! The Scourge closes in " ..
                "from all sides!",
        },
        [11930] = {
            description = "The path across Transborea, to the east, is the only way to reach the " ..
                "Dragonblight. Many perils await you as you make your journey across the tundra. Beware " ..
                "the Scourge and its influence upon the beasts of the land. Rumors have started to spread " ..
                "about our very own taunka brothers and sisters rising from the dead and attacking " ..
                "caravans on their way to the Dragonblight! Defend your caravan and get the evacuees to " ..
                "safety!\n\nWartook Iceborn waits for you across the bridge leading into the Dragonblight.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [11931] = {
            description = "I sense a distinct peculiarity in the drakes here but the meaning of the runes " ..
                "that cover their bodies still eludes me.\n\nWithout a codex, it will take more time than " ..
                "we can afford for me to interpret them.\n\nNot far from here is a Kirin Tor traitor, " ..
                "Caleras, who is likely to have a copy of the tome I require. His underlings hold the " ..
                "runes I will need for my translation.\n\nHurry, mortal. Malygos gains strength with " ..
                "every passing moment.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 47000,
        },
        [11932] = {
            description = "Listen, <name>. No offense, but the operation they put Thassarian in charge of " ..
                "was pure suicide.\n\nA handful of our men were to launch an attack on the biggest " ..
                "Scourge presence in the area. Call me crazy, but storming a Scourge ziggurat outside a " ..
                "plagued Nerubian city with a dozen men ain't my idea of fun.\n\nIf you're still " ..
                "interested in finding Thassarian, we were supposed to arrange for passage east with a " ..
                "tuskarr by the name of Ataika in Kaskala to the northeast. Good luck with your fool's " ..
                "errand.",
        },
        [11936] = {
            description = "Our goals here are simple. We are to remain hidden from Malygos, observe his " ..
                "brood, and thwart his efforts wherever possible. To that end, I have a task for " ..
                "you.\n\nThe blues are laying their eggs at the base of the Nexus. Exposure to so much " ..
                "arcane energy will surely make them hatch sooner, and there's no telling what effect it " ..
                "will have on their spawn.\n\nI don't intend to find out. Slay the local wyrmkin and use " ..
                "their frozen axes to break the eggs.",
            rewardMoney = 47000,
        },
        [11938] = {
            description = "Now that we have this phylactery, I shouldn't have any problems getting the " ..
                "information I need. It won't take long for the Scourge in the Temple City to notice " ..
                "something's up, however.\n\nI won't be able to fend off a full scale attack here. Or " ..
                "maybe I would... but I'd rather not find out.\n\nI want you to head down there and " ..
                "inflict some casualties. Hopefully they'll be distracted long enough for these two to " ..
                "spill their guts... figuratively, of course. Take Lurid with you, he might be of aid.",
            rewardChoices = {{37271, 1}, {37393, 1}, {37425, 1}, {38212, 1}},
        },
        [11940] = {
            description = "I need more drake hatchlings to continue researching the runes covering their " ..
                "bodies.\n\nThey can be found around the northwest edge of the valley....\n\n< Raelorasz " ..
                "pokes his hand with a spear and coats the tip with his blood.>\n\nTake this and use it " ..
                "on one of them. Wait for it to become subdued, then bring it here to me before it " ..
                "expires.",
            rewardMoney = 47000,
        },
        [11941] = {
            description = "Something about this scrap of metal prevents you from casting it " ..
                "aside.\n\nPerhaps Raelorasz might be able to shed some light on its purpose.",
            rewardMoney = 47000,
        },
        [11942] = {
            description = "The lich has spoken, <name>. The high priests of En'kilah hold the secret to " ..
                "entering Naxxanar.\n\nGo to the Spire of Blood, the Spire of Pain and the Spire of Decay " ..
                "and slay each of the priests.\n\nReturn once you've obtained the three scrolls.",
            rewardMoney = 50000,
        },
        [11943] = {
            description = "You've discovered a fragment of a special prison, <name>.\n\nMalygos' minions " ..
                "use similar prisons to hold their captured mages and other arcane entities, but this " ..
                "prison was constructed to hold something... stronger.\n\nIn hopes that the enemy of our " ..
                "enemy will prove to be a friend, you must search for the prison's remaining " ..
                "fragments.\n\nThey are likely to be in the possession of Malygos' most trusted " ..
                "underlings.",
            rewardItems = {{35671, 1}},
            rewardMoney = 47000,
        },
        [11944] = {
            description = "Our situation is nearly hopeless. We were ordered to take the Wailing Ziggurat " ..
                "with a handful of men.\n\nWe'll be lucky if we can hold this position against the " ..
                "Scourge. We're outnumbered, injured and have no escape route.\n\nIf you can take some of " ..
                "the pressure off of us, we might be able to solidify our position. Kill some of the " ..
                "undead circling the structure - we'll hold off their advance.",
            rewardChoices = {{37214, 1}, {37394, 1}, {37424, 1}, {37505, 1}},
        },
        [11945] = {
            description = "Dark times are upon us. Karkut's spirit walks the earth and gathers the " ..
                "spirits of dead tuskarr.\n\nThe sons of the mist have taken many of our brethren. Soon " ..
                "dear Kaskala will be reduced to ashes.\n\nThere is hope yet. Not for us perhaps, but " ..
                "we've sent our families to Unu'pe. We fight here so there may be a future for " ..
                "them.\n\nThey will need supplies or they will starve. There's not enough food in Unu'pe. " ..
                "Salvage any supplies before it's too late for our families.",
            rewardMoney = 50000,
        },
        [11946] = {
            description = "I am... free?\n\nI was destined to spend an eternity roaming an empty abyss, " ..
                "and now am saved? You cannot fathom my gratitude, mortal.\n\nWhen I refused to bend to " ..
                "his will Malygos bound me to that prison, then shattered it and scattered the pieces. " ..
                "Should I live one hundred of your lifetimes, I shall not forget this " ..
                "kindness.\n\nPerhaps, in time, I will find ways to repay you. For now, though, we must " ..
                "focus our attention on Malygos. I am weak, and there is much to be done.\n\nI need your " ..
                "help, <name>.",
            rewardMoney = 4800,
        },
        [11949] = {
            description = "Kaskala is a sacred place for us, <race>. Our ancestors were guided here by " ..
                "the spirit of Tayutka herself.\n\nNow these foul creatures attack us from the mists " ..
                "without any provocation.\n\nWe will show them that our spears are not merely for " ..
                "whaling. Fight alongside us, friend. Perhaps my people might repay you some time in the " ..
                "future.",
            rewardChoices = {{37211, 1}, {37421, 1}, {37486, 1}, {37525, 1}},
            rewardMoney = 50000,
        },
        [11950] = {
            description = "Listen, <name>. Warriors like me are replaceable. If I fall, my brothers and " ..
                "cousins will pick up my spear and fight.\n\nMy people cannot survive without wise " ..
                "elders. Stubborn Muahit, our most venerable shaman, refuses to leave the altar to " ..
                "Tayutka in the central island. We would suffer a significant loss if he was slain by " ..
                "these monsters.\n\nYou are an outsider, maybe he'll listen to you. Show him reason... " ..
                "ask him to flee to the safety of Unu'pe before it's too late.",
        },
        [11951] = {
            description = "During my captivity I was able to learn much about Malygos. Fate now allows us " ..
                "to use this knowledge against him.\n\nThere is a great blue dragon, Saragosa, who " ..
                "circles high above the Nexus. She serves both as the aspect's guardian and as his " ..
                "consort. If any serious threats arise, she alerts her master of the danger.\n\nI " ..
                "suffered greatly at the hand of Saragosa during my captivity, and now her time to die " ..
                "has come. First, however, we must fashion the perfect bait....",
            rewardMoney = 47000,
        },
        [11956] = {
            description = "No time for small talk, <name>. I was sent on what was to be a suicide mission " ..
                "to take this ziggurat. I've accomplished my duty as a soldier, now is the time to get " ..
                "some answers.\n\nThis lich has knowledge I seek, yet I cannot inflict pain to his " ..
                "physical body to obtain that knowledge.\n\nThe lich stored his soul in a phylactery, and " ..
                "while it remains hidden, I won't be able to pry the information from him.\n\nReturn to " ..
                "the camp and take my horse, Dusk, she will lead you to the phylactery. Bring it to me.",
        },
        [11957] = {
            description = "Using the mana crystals you provided, I have created this Power " ..
                "Focus.\n\nSaragosa is a glutton. She will be unable to resist its lure. Inside it lie " ..
                "magics that will greatly diminish her power. Let us hope she does not see through my " ..
                "ruse....\n\nPrepare yourself, <name>, and speak to me again when you are ready to face " ..
                "Saragosa.",
            rewardChoices = {{37280, 1}, {37322, 1}, {37456, 1}, {37562, 1}},
            rewardMoney = 47000,
        },
        [11958] = {
            description = "The wolvar have always been our natural enemies. But the incursion of your " ..
                "peoples into the Great Dragonblight has forced them into a small space upon the glade to " ..
                "the north.\n\nCombined with the land's upheaval this morning, they have become even more " ..
                "aggressive than ever before. They have made several raids upon our goods... things that " ..
                "we'll need if we are to survive the trek from our home here.\n\nAs a sign of good faith " ..
                "and friendship, retrieve our goods from the Snowfall Glade wolvar.",
            rewardMoney = 50000,
        },
        [11959] = {
            description = "Already it goes from bad to worse. There is only one course to take... " ..
                "regrettably, Loguhn must die!\n\nHe's the alpha male of the Snowfall Glade tribe and one " ..
                "mean wolvar. But it's the only way to get a short break from their attacks and stealing " ..
                "forays.\n\nYou will find the \"Render of Flesh\" in front of his hovel upon the northern " ..
                "rise of the glade. It's larger than the others and hard to miss. Kill him and smear his " ..
                "blood upon yourself, both to show your dominance and respect.",
            rewardChoices = {{38026, 1}, {38087, 1}, {37982, 1}, {37939, 1}},
            rewardMoney = 106000,
        },
        [11960] = {
            description = "We must move decisively against the wolvar if we're to have a chance of " ..
                "survival. However, I worry that in our zeal, too many of them will be slain.\n\nThe " ..
                "Snowfall Glade wolvar have as much right to exist as do we. You and I will see to it " ..
                "that they get that chance.\n\nIf Elder Ko'nani hasn't asked you already, he will ask you " ..
                "to deal with them. While you're upon the glade to the north, I'd like you to bag up " ..
                "their pups and bring them back to me.",
            rewardMoney = 50000,
        },
        [11961] = {
            description = "Powerful spirits watch over my tribe -- Kaskala will not be lost.\n\nIssliruk " ..
                "will give us courage, Tayutka will make sure our survivors always have food and shelter " ..
                "and Karkut will watch over the fallen so they do not lose their way.\n\nIssliruk's " ..
                "guidance is the one we need the most right now. I asked my nephew, Iruk, to bring me " ..
                "Issliruk's totem, but the Kvaldir's spears struck him down and his body fell into the " ..
                "waters to the north. Bring me the totem, <name>. Don't let my nephew's death be in vain.",
            rewardMoney = 39000,
        },
        [11962] = {
            description = "That's it then. With the last of the ore you salvaged we now have enough to " ..
                "send to Valiance Keep.\n\nIf Farshire is wiped off the face of Azeroth, then at least " ..
                "let us be remembered as the first ones to defend our land and the last ones to give " ..
                "up.\n\nTake this ore to Hilda Stoneforge - she is a good friend of mine. Tell her to " ..
                "make some good weapons with this ore. We'll need plenty of them in the days to come.",
        },
        [11963] = {
            description = "Farshire is overrun and all that Gerald can think of is to get me my ore " ..
                "shipment? I swear that man has as much heart as any of our soldiers on the " ..
                "frontlines.\n\nWe cannot let the civilians lose their lands if they're willing to fight " ..
                "for them. We might not have the troops to spare, but we can send them weapons.\n\nThese " ..
                "were earmarked for new recruits, but I'll be able to cover those with the ore you've " ..
                "brought me. Send word to Gerald that weapons are on the way.",
        },
        [11965] = {
            description = "Farshire has a fighting chance now, <name>. That's all we could've asked for " ..
                "and you've made it possible.\n\nAll we need now is a rallying point. I'll have my men " ..
                "deliver the weapons to our town hall. Go and ring the town hall bell so any survivors " ..
                "know to rally there.\n\nIt's time to show the Scourge what we're made of.",
            rewardChoices = {{38227, 1}, {38226, 1}, {38228, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [11967] = {
            description = "Malygos is certainly aware that something is amiss.\n\nI know him. His focus " ..
                "is fragmented. I am confident that I can lure him from the safety of his realm when he " ..
                "learns what has become of his precious Saragosa.\n\nTake me to Raelorasz at once, " ..
                "<name>. He must rouse every dragon he commands to face Malygos.",
            rewardMoney = 24000,
        },
        [11968] = {
            description = "The spirits have heard our cry for help, <name>. It's a sign that Kaskala " ..
                "might yet be saved.\n\nTake advantage of the confusion the weather has created and slay " ..
                "the Kvaldir leader. Your actions will sway the battle in our favor, I am sure of it.",
            rewardChoices = {{37029, 1}, {37030, 1}, {37031, 1}, {37032, 1}, {37033, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [11969] = {
            description = "We owe this opportunity in great part to your efforts, <name>.\n\nIt is only " ..
                "fitting that you initiate the attack on Malygos.\n\nTake this spark and use it to light " ..
                "the signal fire northwest of the Nexus. Keristrasza will direct you from there.",
            rewardChoices = {{37075, 1}, {37076, 1}, {37077, 1}, {37078, 1}, {37080, 1}, {37564, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 47000,
        },
        [11973] = {
            description = "Malygos has taken Keristrasza to serve as his consort!\n\nWe cannot allow this " ..
                "to come to pass.\n\nYou must do whatever it takes to spare her such a fate, <race>.",
            rewardChoices = {{38221, 1}, {38222, 1}, {38223, 1}},
            rewardMoney = 188000,
        },
        [11977] = {
            description = "<Wartook points northeast.>\n\nShe is quite kind, you know. If it were not for " ..
                "your emissary, the surviving refugees may have given up hope. While she may not be " ..
                "taunka by birthright, the tribe has taken to her as a village elder for the time " ..
                "being.\n\nIf you are who I think you are, please go and pay Emissary Brighthoof a visit " ..
                "inside the refugee camp. She has been waiting for you.",
        },
        [11978] = {
            description = "Before we can officially bring these taunka into the Horde we must recover our " ..
                "armaments from the Anub'ar Nerubians that infest the nearby woods. The armaments were " ..
                "lost when a caravan from Agmar's Hammer was ambushed by the Scourge late last " ..
                "night.\n\nVenture out into the woods to the east of Westwind Refugee Camp and recover " ..
                "those armaments, <race>.",
        },
        [11979] = {
            description = "The Scourge have seized control of the capital city of the taunka, Icemist " ..
                "Village! All living taunka that escaped the massacre are being held in protective " ..
                "custody at the Westwind Refugee Camp on the western border of Dragonblight.\n\nLord " ..
                "Hellscream believes that the taunka must join the Horde if they are to survive and has " ..
                "sent a tauren emissary to Westwind to bolster our relationship with the winter tauren. " ..
                "Travel to Westwind Refugee Camp and seek out Emissary Brighthoof. You will assist her.",
        },
        [11980] = {
            description = "I was one of the guards chosen to escort the caravan carrying the armament " ..
                "shipment to this camp. The attack came fast and without warning. We fought and killed " ..
                "dozens of the beasts, but in the end there were simply too many. Tor'zin and I barely " ..
                "made it out alive...\n\nIf not for our injuries we would be out in the woods hunting " ..
                "down those fiends ourselves. Will you help us regain our lost pride? Search the woods " ..
                "east of here for Anub'ar Nerubians and kill them! For the Horde!",
            rewardChoices = {{37964, 1}, {38006, 1}, {38048, 1}, {38110, 1}, {38081, 1}},
        },
        [11981] = {
            description = "The Earthen warrior's stone surface is covered with cracks and gouges. " ..
                "Although it is incapable of bleeding, you can sense that the warrior is near death.\n\nA " ..
                "low, hoarse voice escapes from the dying warrior's mouth.\n\n\"Find... Kurun... you must " ..
                "find... Kurun.\"\n\nIt looks at you helplessly as you ask for any clues as to who or " ..
                "what Kurun might be.\n\n\"Our... leader... he stands on the... hill overlooking Thor " ..
                "Modan... commands us. Please... tell him... we cannot take... the city... \"",
        },
        [11982] = {
            description = "Beneath us is iron's ancient bastion, Thor Modan. Thousands of years ago, the " ..
                "stone giants tore the land asunder, collapsing part of the city and exposing much of the " ..
                "rest.\n\nEven now, the iron dwarves attempt to reclaim their old capital, but we will " ..
                "not permit it. My giants fill the trench with boulders and debris, hoping to seal it off " ..
                "and kill the servants of iron as they work. Take up the boulders you see near the trench " ..
                "to the northeast, and help us put an end to their efforts.",
            rewardMoney = 59000,
        },
        [11983] = {
            description = "They are ready, <name>. These taunka will all willingly join the Horde and " ..
                "give all that they have to see the Scourge driven from this world.\n\n<Brighthoof hands " ..
                "you a scroll bearing the insignia of the Horde.>\n\nWithin this scroll you will find the " ..
                "blood oath of the Horde. Tradition dictates that our new taunka brothers and sisters " ..
                "utter the sacred words herein.\n\nTake the scroll and swear the taunka into the Horde, " ..
                "commander. Return the scroll to me when you have completed your duty.",
        },
        [11984] = {
            description = "'Ol Budd's seen better days.\n\nEver since our stay in Ghostlands he's been " ..
                "useless to us. We've had to find ways to make it on our own, and today that means " ..
                "sellin' trolls to the highest bidder.\n\nFortunately, we've recently found a use for " ..
                "Budd. Something about his condition allows him to mingle with the local trolls, so we " ..
                "taught him a little game that's turned us a tidy profit.\n\nSee for yourself. Talk to " ..
                "Budd, take him southwest to Drak'Zin Ruins and use this cage as soon as he tags a troll.",
            rewardChoices = {{39116, 1}, {39128, 1}, {39129, 1}, {39131, 1}, {39132, 1}, {39142, 1}},
            rewardMoney = 56000,
        },
        [11985] = {
            description = "If we can't overcome the defenders inside Thor Modan, the iron dwarves can " ..
                "hold out forever. The Earthen are bravely taking on the constructs built by the sons of " ..
                "iron, but they cannot break into the city.\n\nThe tunnels narrow too quickly for my " ..
                "fellow giants to be of use, so our options are few. Would you be willing to venture into " ..
                "the city and kill the dwarf commanding the resistance?",
            rewardChoices = {{38715, 1}, {39019, 1}, {39048, 1}, {39080, 1}},
            rewardMoney = 59000,
        },
        [11986] = {
            description = "This battered, mud-stained journal has seen better days. Leafing through the " ..
                "pages, you discover dozens of notes, diagrams, and maps.\n\nThe author's handwriting " ..
                "seems vaguely familiar, but you're unable to place it until you discover an entry signed " ..
                "with the name of Brann Bronzebeard.\n\nThe back half of the book, containing the most " ..
                "recent entries, has been torn away. Pages litter the battlefield, and it will be " ..
                "impossible to know what Brann discovered here until the book is whole again.",
            rewardMoney = 59000,
        },
        [11988] = {
            description = "Brann's journal mentions that he used a runic keystone to illuminate the " ..
                "important runes on the plate he discovered. Without the keystone, the plate's contents " ..
                "would be little better than gibberish.\n\nAt the end of Brann's last entry, he describes " ..
                "the iron dwarf defenders seizing the keystone from him, shattering it, and dividing it " ..
                "among themselves. Before we can decipher the runed plate, we must hunt down the " ..
                "fragments. Any of the dwarves within Thor Modan or the buildings around it may carry " ..
                "fragments.",
            rewardMoney = 59000,
        },
        [11989] = {
            description = "Watch yerself, mon.\n\nDrakuru shrunk more <race> heads than I can remember - " ..
                "and even if I could remember, I couldn't count that high. Lucky for you I be stuck in " ..
                "dis cage or I'd be addin' one more to da list.\n\nBut things bein' what they are, mebbe " ..
                "we be puttin' our differences aside fer a time, eh?\n\nDrakuru know things, mon. Things " ..
                "that will aid you in your struggle here.\n\n< Drakuru cuts the palm of his hand on one " ..
                "of his tusks and extends it through the cage.>\n\nSo, what you say, mon... truce?",
        },
        [11990] = {
            description = "First things first, mon. There be some preparatory work that need doin'.\n\nNo " ..
                "tellin' how long dey gunna keep me here. Ya be needin' a powerful elixir so we can be " ..
                "keepin' in touch.\n\nLucky for you, I know just the thing! And the ingredients all be " ..
                "close by.\n\nI need a vial from the pretty little troll over there, some waterweed from " ..
                "the lake just north of here, and a few haze leaves found around the camp here.\n\nHurry " ..
                "now, mon, before dey be haulin' me away.",
        },
        [11991] = {
            description = "A legendary set of artifacts, lost for thousands of years, were created to " ..
                "make Drak'Tharon Keep impervious.\n\nMost think they be myth, but Drakuru knows better, " ..
                "mon!\n\nI nearly discovered where one be, but got captured while interpreting " ..
                "hieroglyphs. Ya gotta summon my soul back dere so I can finish readin' em!\n\nUse my " ..
                "elixir at da brazier on Drak'Zin Ruins, southwest of here. You'll hafta mix in da frozen " ..
                "mojo my bruddas be holdin'. I hate ta see my bruddas fall, but it be for the greater " ..
                "good.",
            rewardChoices = {{38716, 1}, {39020, 1}, {39049, 1}, {39081, 1}},
            rewardMoney = 56000,
        },
        [11993] = {
            description = "We've no time to lose! Now that we've reassembled the runic keystone -- well, " ..
                "most of it -- we can decipher the contents of those very same runic plates Brann was " ..
                "working on before he fled.\n\nWe have no way of knowing if he managed to read the " ..
                "contents of all three plates, but we'll have to assume he got enough information to " ..
                "determine his next destination.\n\nStand before each of the plates and use the keystone " ..
                "to determine the contents of each. Brann may be counting on us!",
            rewardChoices = {{38710, 1}, {39013, 1}, {39043, 1}, {39075, 1}},
            rewardMoney = 59000,
        },
        [11995] = {
            description = "<class>, I know these tuskarr will ask you to do many favors for them, but you " ..
                "must get to Stars' Rest with all due haste!\n\nThe upheaval in the land this morning is " ..
                "sure to have broader repercussions than just inconveniencing the natives.\n\nStars' Rest " ..
                "is westward past the intersection of the road leading north out of the harbor. There is " ..
                "an archmage there named Modera. She will be expecting you.",
        },
        [11996] = {
            description = "<class>, I know these tuskarr will ask you to do many favors for them, but you " ..
                "must get to Agmar's Hammer with all due haste!\n\nThe upheaval in the land this morning " ..
                "is sure to have broader repercussions than just inconveniencing the natives.\n\nThe " ..
                "Hammer is westward past the intersection of the road leading north out of the harbor. " ..
                "Archmage Aethas Sunreaver himself will be expecting you!",
        },
        [11998] = {
            description = "Our best bet for moving our forces quickly to Icecrown Glacier lies with the " ..
                "network of tunnels beneath the ancient iron dwarf city of Thor Modan.\n\nBrugar " ..
                "Stoneshear and his Explorers' League boys aren't going to be happy, but orders are " ..
                "orders.\n\nThe news might go over better if you brought him a cask of that moonshine " ..
                "sold by that trapper, Hugh Glass, down at Redwood Trading Post, southeast of here along " ..
                "the tree line.\n\nMan's not right in the head, but you won't find better moonshine out " ..
                "here.",
        },
        [11999] = {
            description = "The Moonrest Gardens to the southwest were the final resting place of a group " ..
                "of Highborne elves. It was also a ley line nexus.\n\nThe blue dragonflight used a " ..
                "magical device they call a surge needle to destroy that nexus, freeing the power to " ..
                "redirect at their will.\n\nI want more information and you are going to get it for " ..
                "me!\n\nAfter the land was destroyed at the ruins, the ghosts of the Highborne rose up " ..
                "and decimated half of the mage hunters there. Go rifle their corpses for clues.",
            rewardMoney = 50000,
        },
        [12000] = {
            description = "The Moonrest Gardens to the southwest were the final resting place of a noble " ..
                "group of Highborne elves. It was also a powerful ley line nexus.\n\nThe blue " ..
                "dragonflight used a magical device they call a surge needle to destroy that nexus, " ..
                "freeing the power to redirect at their will.\n\nI need more information and I hope that " ..
                "you will get it for me.\n\nAfter the upheaval at the ruins, the ghosts of the Highborne " ..
                "rose up and decimated half of the mage hunters present. Go rifle their corpses for clues.",
            rewardMoney = 50000,
        },
        [12002] = {
            description = "I hope Gryan knows I withdrew my men from Thor Modan when the battle began. " ..
                "There's no way we can excavate anything until that place settles down.\n\nYou seem like " ..
                "a brave sort, though, and you have Stoutmantle's trust.\n\nThor Modan is just to the " ..
                "northeast of us and the battle still rages between our Earthen brothers and the " ..
                "creations of those accursed iron dwarves. Help our brethren to even the odds and I'll " ..
                "start figuring out how we're going to accomplish this survey of Thor Modan.",
            rewardMoney = 59000,
        },
        [12003] = {
            description = "The first place we'll search for entrances to the Thor Modan tunnel system " ..
                "will be the outlying buildings.\n\nAs I left the site with my men, it looked like the " ..
                "iron dwarf defenders were taking refuge inside the buildings. Be careful as you explore " ..
                "them.\n\nAny tunnel entrances are likely to be toward the back of the buildings. I'm not " ..
                "sure what Stoutmantle thinks we're going to find down there, but I doubt the iron " ..
                "dwarves will make the search easy.",
            rewardMoney = 59000,
        },
        [12004] = {
            description = "We need to kill two birds with one stone here, <class>. You're the " ..
                "stone.\n\nOur two birds are Wind Trader Mu'fah and Goramosh. They should be somewhere in " ..
                "the western half of the Moonrest Gardens. Most likely they're in the larger two-story " ..
                "building overlooking the pit.\n\nI require proof of their demise, if you would be so " ..
                "kind.",
            rewardChoices = {{37943, 1}, {37987, 1}, {38031, 1}, {38094, 1}},
            rewardMoney = 106000,
        },
        [12005] = {
            description = "We need to kill two birds with one stone here, <class>. You're the " ..
                "stone.\n\nOur two birds are Wind Trader Mu'fah and Goramosh. They should be somewhere in " ..
                "the western half of the Moonrest Gardens. Most likely they're in the larger two-story " ..
                "building overlooking the pit.\n\nI require proof of their demise, if you would be so " ..
                "kind.",
            rewardChoices = {{37943, 1}, {37987, 1}, {38031, 1}, {38094, 1}},
            rewardMoney = 106000,
        },
        [12006] = {
            description = "These so-called mage hunters came here and destroyed our resting " ..
                "place.\n\nAvenge us, or I will see to it that your base of operations is overrun with " ..
                "the spirits of the dead!",
            rewardMoney = 50000,
        },
        [12007] = {
            description = "I've got it, mon!\n\nTo da north, on da Ziggurat at Zeb'Halak be a stone head " ..
                "with ruby eyes. One o' dem be da Eye of the Prophets! Bring it to the brazier there and " ..
                "drink my elixir.\n\nAgain, ya be needing some mojo for my elixir to work - dis time from " ..
                "da warlord, Zim'bo. He be hidin' in one of da huts in Zeb'Halak.\n\nIt be a shame to " ..
                "kill Zim'bo, mon, but he swore da blood oath to defend Drak'Tharon and he done failed. " ..
                "Now at least his mojo be helpin' us to reclaim Drak'Tharon.",
            rewardMoney = 56000,
        },
        [12008] = {
            description = "Directly east of this refugee camp stands Agmar's Hammer - testament to the " ..
                "Hordes' power in the Dragonblight.\n\nWhile I have no doubt that our Horde brothers and " ..
                "sisters are already seeing the result of your efforts to bring the taunka into the " ..
                "Horde, I want you to deliver news of your success to Overlord Agmar in person.\n\nGo " ..
                "now, <name>! Race the winds! East to Agmar's Hammer!",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [12009] = {
            description = "With all of the troubles, I've lost my assistants. I was wondering if maybe " ..
                "you could help me?\n\nI have many crab traps under the waves of the harbor. Will you " ..
                "retrieve them for me? I'm too old for that sort of thing and the waters can be very " ..
                "dangerous.\n\nPlease, take this bladder. It will help you to breathe while you're down " ..
                "there.",
            rewardMoney = 50000,
        },
        [12010] = {
            description = "When we began excavating the city, I sent Surveyor Orlond to check the " ..
                "stability of the tunnels in Thor Modan. I didn't see him escape when we withdrew at the " ..
                "beginning of the battle, and I worry he may still be trapped inside the city.\n\nIf " ..
                "we're going to get an army through Thor Modan, we'll need the information he was " ..
                "collecting. Stoutmantle and his superiors would have my hide if the tunnels collapsed on " ..
                "one of their brigades!",
        },
        [12011] = {
            description = "This crab trap appears to have been destroyed by something much larger than " ..
                "the nearby circling sharks.\n\nPerhaps Tua'kea, the fisherman at Moa'ki Harbor, should " ..
                "be told about this?",
            rewardMoney = 5000,
        },
        [12013] = {
            description = "There is one last thing that I would have you do, <name> the <race>. I would " ..
                "have you destroy Arcanimus!\n\nThe sorcerers to the west used that giant device in the " ..
                "sky to bore a massive pit into our resting place. When they did that, they unleashed a " ..
                "monstrosity!\n\nI would not care if it were only a concern for mortals, but Arcanimus " ..
                "feeds upon the spirits of the dead.\n\nYou will put an end to it now!",
            rewardChoices = {{37941, 1}, {37984, 1}, {38092, 1}, {38028, 1}},
            rewardMoney = 106000,
        },
        [12014] = {
            description = "Orlond's notes indicate that he brought a piece of equipment called a portable " ..
                "seismograph with him, but the device is nowhere to be seen.\n\nThe survey log shows that " ..
                "Orlond completed all his readings in the Thor Modan tunnel, save one labeled the 'east " ..
                "end of the exposed tunnel.'\n\nThe last entry in the log indicates Orlond tried to take " ..
                "refuge in the water and was attacked by subterranean threshers. They might've taken his " ..
                "equipment.You'll need to recover it before you can take the last reading.",
            rewardChoices = {{38717, 1}, {39021, 1}, {39050, 1}, {39082, 1}},
            rewardMoney = 46000,
        },
        [12016] = {
            description = "I'm sure of it... our ancient aquatic nemesis, Tu'u'gwar, \"He Who Plays With " ..
                "Food\", has returned. We must lay a trap for him, you and I.\n\nIf Tu'u'gwar has one " ..
                "weakness it's his stomach. There's one meat for certain that he'd never be able to pass " ..
                "up.\n\n\"Two Huge Pincers\", the mother of all crabs, Kili'ua, paces upon her island out " ..
                "in the waters to the southwest. You must pay her a visit and return with her meat.",
            rewardMoney = 50000,
        },
        [12017] = {
            description = "The time has come my friend: Tu'u'gwar must be dealt with!\n\nI've prepped the " ..
                "meat so that the beast is sure to come once you bait the hook I have out in the water. " ..
                "Just follow the fishing line here down to it.\n\nWhatever you do, don't let Tu'u'gwar " ..
                "swallow you whole, <name>!",
            rewardChoices = {{37936, 1}, {37980, 1}, {38023, 1}, {38084, 1}},
            rewardMoney = 106000,
        },
        [12019] = {
            description = "I served Arthas in death, because I had no choice. He had control over my will " ..
                "and my body. The Cult of the Damned serves Arthas in life... willingly.\n\nNow that we " ..
                "know the words of power to enter Naxxanar we can put an end to the cultist blight. Go to " ..
                "En'kilah and look for the teleportation orb beneath the floating citadel.\n\nWork your " ..
                "way up and meet me at the top. Arm yourself with what courage you can, we might not make " ..
                "it out of this alive.",
            rewardChoices = {{38237, 1}, {38238, 1}, {38239, 1}, {38240, 1}, {38241, 1}, {38242, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 150000,
        },
        [12026] = {
            description = "This battered, mud-stained journal has seen better days. Leafing through the " ..
                "pages, you discover dozens of notes, diagrams, and maps in the dwarven language.\n\nThe " ..
                "only text you're able to decipher is the name of Brann Bronzebeard scrawled at the end " ..
                "of one of the entries.\n\nThe back half of the book, containing the most recent entries, " ..
                "has been torn away. Someone thought the notes important enough to attempt to destroy " ..
                "them. Perhaps gathering the missing pages from the battlefield will yield some clues.",
            rewardMoney = 59000,
        },
        [12027] = {
            description = "Excuse me, <Mister/Ma'am>, do you know the way back to the soldiers' " ..
                "camp?\n\nMr. Floppy and I decided to go for a walk in the woods, and my brother Walter " ..
                "was gonna come with us, but then he had squire things to do.\n\nSo Mr. Floppy and I went " ..
                "by ourselves, but we got lost, and there were a whole bunch of hungry wolves, but we " ..
                "found this tower.\n\nThe wolves went away, but we're still lost.\n\nI asked Mr. Floppy, " ..
                "and he doesn't know the way back. Would you help us? Please?",
            rewardChoices = {{38714, 1}, {39018, 1}, {39047, 1}, {39079, 1}},
            rewardMoney = 56000,
        },
        [12028] = {
            description = "<race>, we have not heard from our people at Indu'le Village since the ground " ..
                "shook and was torn apart!\n\nHave you ever been upon a vision quest? You've bested " ..
                "Loguhn, so you must be capable.\n\nI will give you a special incense to sprinkle into my " ..
                "brazier. Breathe deep from its vapors and your spirit will be sent aloft to view what " ..
                "has transpired at Indu'le.\n\nAs your spirit soars, I will be able to look through your " ..
                "eyes.",
            rewardMoney = 50000,
        },
        [12029] = {
            description = "<Hic>... gotta burn these corpshes 'fore they shtart walkin' around " ..
                "again.\n\nPoppa always said, only thing worshe than havin' to kill a troll is havin' ta " ..
                "kill a troll twice.\n\nSay,<hic>... shpeakin' of Scourge, we can't get into tha' troll " ..
                "keep up north 'til we get them trolls thinned out a bit.\n\nHow 'bout ya take shome o my " ..
                "grog here and put them bashtards outta their misery?",
            rewardMoney = 56000,
        },
        [12030] = {
            description = "My people....\n\n<The mystic is on the verge of breaking down.>\n\nWhile your " ..
                "spirit was flying through the village, I sensed that Elder Mana'loa took notice of you. " ..
                "<name>, he wishes to speak with you. The stone elders are revered by us as fonts of " ..
                "ancient wisdom.\n\nThe elder must want to help. Seek him in the northwest corner of the " ..
                "village.",
            rewardMoney = 50000,
        },
        [12031] = {
            description = "The sacred ground of the elves to the west has been torn asunder. Now their " ..
                "magic is moving through the land causing ruin where it flows.\n\nThe souls of the " ..
                "Kalu'ak are in danger as the blue dragons forces attempt to control the magic.\n\nThe " ..
                "power came up through the lake, instantly slaying most in the village. Those that " ..
                "survived were driven insane.\n\n<name>, you must release these spirits so that they may " ..
                "move on. Leave the deranged living alone; they may yet regain their sanity in time.",
            rewardMoney = 50000,
        },
        [12032] = {
            description = "The watery goddess, Oacha'noa, must be consulted; only she will know what the " ..
                "destiny of the Kalu'ak is to be. And only The Pearl of the Depths can call her forth " ..
                "from the murky nether.\n\nOff the coast to the southwest rises The Briny Pinnacle. Atop " ..
                "it sits the altar upon which the pearl rests.\n\nCommune at the altar and Oacha'noa is " ..
                "certain to hear your call. Do as she says lest you incur her wrath and bring ruin upon " ..
                "all of the tuskarr.\n\nShould you survive, return to the mystic.",
            rewardChoices = {{38126, 1}, {38127, 1}, {38128, 1}, {38146, 1}, {38148, 1}, {38150, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 100000,
        },
        [12033] = {
            description = "<Torvus shakes your hand, giving you a letter in the process.>\n\n<Torvus " ..
                "speaks under his breath.>\n\nJust play along, <name>.\n\nIt is good to see you here, " ..
                "soldier! Lord Hellscream has undoubtedly sent his strongest warriors to Lord " ..
                "Agmar!\n\n<Torvus speaks under his breath.>\n\nRead it and then destroy it in the fire " ..
                "pot next to me.",
        },
        [12034] = {
            description = "There remain only two primary threats that stand in our way. One is the dread " ..
                "citadel of Naxxramas, far to the east, above the Alliance fortress of Wintergarde and " ..
                "the other is the Pit of Narjun, exit point for the undead armies of Azjol'Nerub. It is " ..
                "from the Pit of Narjun that the Anub'ar Nerubians assaulted and ultimately razed the " ..
                "taunka village of Icemist.\n\nWe will destroy the Anub'ar and close off the Pit of " ..
                "Narjun.\n\nReport to Senior Sergeant Juktok for your mission orders.",
        },
        [12035] = {
            description = "Ok, I've got it! The rewiring is a little complicated, but nothing a clever " ..
                "<class> like you can't handle.\n\nTake my tools and put some of the harvest collectors " ..
                "out of commission. Once they're down use the tools to plug all the red wires into the " ..
                "blue sockets. That'll make them go into self-defense mode. Hurry, <name>. Before long " ..
                "there won't be anything left to save.",
            rewardChoices = {{37206, 1}, {37403, 1}, {37417, 1}, {37482, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [12036] = {
            description = "The undead Nerubians that attacked Icemist Village came from a gigantic " ..
                "sinkhole known as the Pit of Narjun. If left alone, those fiends will no doubt flank our " ..
                "forces at the Wrathgate and end our march to victory.\n\nI need eyes on the ground, " ..
                "<name>. You are to head west and investigate the Pit of Narjun. We need to locate their " ..
                "primary exit point and seal it off! Find me that location.",
        },
        [12038] = {
            description = "Whatcha waitin' fer, <class>? Them shcourged trolls ain't gunna kill " ..
                "themselves!\n\nYou know the drill. Git up ta Drak'Tharon up north... Take some o thish " ..
                "here grog and hurl it at 'em from a distance...<hic>. Then jusht sit back an' watch 'em " ..
                "burn.",
            rewardMoney = 50000,
        },
        [12039] = {
            description = "Angrathar, the Wrathgate... I watched as the metal holding the gate together " ..
                "pulsed and undulated as if it were alive! In 50 years I've never seen metal " ..
                "\"breathe.\"\n\nOnly ones who knew anything about it were the tuskarr. They called it " ..
                "the \"Black Blood of Yogg-Saron\" and told me to keep my distance.\n\nThere's a sinkhole " ..
                "outside Icemist Village to the west called the Pit of Narjun. I've heard of these " ..
                "sinkholes being rich with this strange ore. If you head that way, could you try and get " ..
                "me some samples?",
        },
        [12040] = {
            description = "We are in the midst of a civil war. At the heart of this world the last living " ..
                "members of my species defend themselves against total annihilation. The Lich King seeks " ..
                "to rule the kingdom of Azjol-Nerub at any cost. Those that do not acquiesce are branded " ..
                "enemies of the Scourge and marked for death.\n\nIn Arthas we both have an " ..
                "enemy...\n\nJoin our cause and rid this place of the taint of Anub'ar! Let Anub'arak " ..
                "himself hear the anguish of their death cries!",
        },
        [12041] = {
            description = "You have proven that you are willing to assist the Azjol Empire in its time of " ..
                "need and as such the Azjol Empire will assist the Horde.\n\nTake this scroll back to " ..
                "your leader. It documents the strengths and weaknesses of the Nerubians attacking " ..
                "Icemist Village. Consider it a gesture of good faith - a willingness to help your " ..
                "people. Use the knowledge on those pages to crush the Anub'ar and you will have done a " ..
                "service for us all.\n\nFarewell, <race>.",
            rewardChoices = {{37954, 1}, {37996, 1}, {38040, 1}, {38101, 1}},
        },
        [12042] = {
            description = "Secrets of da ages, be revealed to me now!\n\n<Drakuru peers through the Eye " ..
                "of the Prophets.>\n\nAhh, great be mah destiny, <name>. You be lucky ta know " ..
                "me....\n\nThere! I be seein' it, mon. The Heart of the Ancients. Dis be too easy!\n\nYou " ..
                "gunna find da heart lyin' near da corpse of a goblin east of here. He be up in a " ..
                "chamber, near a river of broken trees.\n\nHurry, mon, before someone else be findin' it!",
            rewardItems = {{36739, 1}},
        },
        [12043] = {
            description = "You, <class>! These undead south of us are being a constant nuisance to our " ..
                "work. Go clear them out, will ya?",
            rewardMoney = 56000,
        },
        [12044] = {
            description = "Hello hello! The Scourge to the south are digging up some ancient dragon " ..
                "thing. I could care less why they're doing it, but they're pulling cartloads of " ..
                "composite ore in the process.\n\nGo lift me a bunch of that ore. That stuff should yield " ..
                "a pretty penny for all the weapons the Horde are crafting.",
            rewardMoney = 56000,
        },
        [12045] = {
            description = "I've never seen you before... are you new to the Vice? Glad to have you. I " ..
                "could always use some more hands.\n\nYou get the materials, I'll finish my machine, then " ..
                "we can sell it to those commander types and all go home rich.\n\nI actually have most of " ..
                "the primary components, so I just need some of the materials for the weapon itself. Narf " ..
                "said that jagged ice shards from those elementals to the north would make perfect " ..
                "shrapnel for my bombs - go nab some, will ya?",
            rewardMoney = 56000,
        },
        [12046] = {
            description = "I need some new packaging for the shrapnel bombs. All the stuff I have is too " ..
                "hard and the shrapnel doesn't spread when it bursts.\n\nWhat we need is some really thin " ..
                "animal hide. Those jormungar tunnelers to the west might work... or perhaps the condors " ..
                "sifting through the dragon bones. Go get me whatever you can find.",
            rewardMoney = 56000,
        },
        [12047] = {
            description = "No no no! Those ice shards didn't work at all! They'll melt before they even " ..
                "do any damage. That's the last time I'll trust Narf's word on materials. This means we " ..
                "need something else entirely for the shrapnel.\n\nI know! I'm brilliant. Bone " ..
                "splinters.\n\nThere are some bones all around here that the jormungar have been gnawing " ..
                "on pretty thoroughly. Go check them out and see if you can find me some splintered bone " ..
                "that I can use.",
            rewardChoices = {{37948, 1}, {37991, 1}, {38035, 1}, {38080, 1}, {38072, 1}},
            rewardMoney = 56000,
        },
        [12048] = {
            description = "I can't make a damned thing out of this ore. It simply will not hold together! " ..
                "Despite my best efforts the Scourge metal will not bend!\n\nPerhaps if I had some " ..
                "samples of some forged Scourge armaments I might be able to reverse engineer the process " ..
                "by which the items are created.\n\nIcemist Village is crawling with armored Scourge " ..
                "Nerubians. Go there and get me some Scourge armaments! With your help I might actually " ..
                "succeed in creating something from this ore.\n\nYou'll find Icemist to the west.",
            rewardChoices = {{37961, 1}, {38003, 1}, {38045, 1}, {38107, 1}},
        },
        [12049] = {
            description = "Those troops are sure to be needin' a hefty supply of food in their " ..
                "bellies.\n\nI'll let you in on a little secret that a squeamish <race> like you would " ..
                "never know... those jormungar worms taste just like chicken.\n\nGo provoke one of those " ..
                "giant hulking jormungar to the east. You're not likely to be able to kill one straight " ..
                "out, so just toss this down its throat when it opens its mouth wide. Bring me back as " ..
                "many of the slabs of meat as you can tote.",
            rewardMoney = 56000,
        },
        [12050] = {
            description = "Next up, we need to haul in some lumber for all the towers the Alliance are " ..
                "building. There are some thin trees to the south, but the trees the harpies are nesting " ..
                "in to the north look much more fit for structures.\n\nTake this. When you get to the " ..
                "harpy nesting area, use the control and one of my Shredders should come to you. Gather " ..
                "as much lumber as it can carry. The harpies are sure to disagree with you chopping down " ..
                "their homes - just deal with them as necessary.\n\nHop to it!",
            rewardChoices = {{38141, 1}, {38142, 1}, {38143, 1}, {38187, 1}, {38191, 1}, {38197, 1}},
            rewardMoney = 56000,
        },
        [12052] = {
            description = "<class>, did you see that? That's the harpy that's been leading the attack on " ..
                "our shipments to the gate! I've seen her in the back of Coldwind Heights " ..
                "before.\n\nThose harpies have slowed our profits long enough! Kill them all.",
            rewardChoices = {{37947, 1}, {37990, 1}, {38034, 1}, {38097, 1}},
            rewardMoney = 112000,
        },
        [12053] = {
            description = "The taunka are now our brothers in arms. We must show our solidarity and " ..
                "retake Icemist Village.\n\nYou will find Icemist Village west of Agmar's Hammer, sitting " ..
                "at the foot of the mountains. Travel there and challenge the Anub'ar Nerubians! Plant " ..
                "our beloved Horde banner at Icemist Village and destroy all that dare come to tear it " ..
                "down!\n\nLet the Anub'ar feel the true might of the Horde! Let our battle standard be " ..
                "the last thing that they see before death!",
            rewardChoices = {{37956, 1}, {37998, 1}, {38041, 1}, {38102, 1}},
        },
        [12054] = {
            description = "Vor'takh is right -- we cannot allow this opportunity to slip through our " ..
                "fingers.\n\nFortunately, I think I know of a way to translate the journal of this " ..
                "Brann.\n\nThe shamans of the Redfang furbolgs, who congregate at the Heart's Blood " ..
                "Shrine south of the camp, grow an herb known as spiritsbreath. An experienced mystic can " ..
                "use incense made from it to seek wisdom from the spirits of the ancestors.\n\nSeek out " ..
                "the shaman known as Grumbald One-Eye. He should carry the herb for his devotions to " ..
                "Ursoc.",
            rewardMoney = 59000,
        },
        [12055] = {
            description = "Picking up this strange device, you are certain that it is magical in nature. " ..
                "Unfortunately, it doesn't seem to connote any other kind of use.\n\nPerhaps the archmage " ..
                "back at Stars' Rest to the east of the Moonrest Gardens would be able to tell what it's " ..
                "used for?",
        },
        [12056] = {
            description = "I witnessed his treachery with my own eyes! The traitor led an Anub'ar assault " ..
                "on this stronghold, taking out some of my best soldiers.\n\n<Gort shakes his " ..
                "head.>\n\nHe'd been working with the Scourge the whole time and we didn't have a clue! " ..
                "How many more like Zangus are there? We'll find 'em all and when we do...\n\n<Gort makes " ..
                "a cutting motion across his neck.>\n\nFirst on the list is Zangus. Our scouts report " ..
                "that he is hiding in The Pit of Narjun, west of here. Find him, kill him, bring me his " ..
                "head.",
            rewardMoney = 50000,
        },
        [12057] = {
            description = "The tome is bound in flesh and appears to be bleeding. Upon examination you " ..
                "discover page after page filled with strange symbols that appear to be written in " ..
                "blood.\n\nWhatever knowledge is held within the pages of this tome could be important. " ..
                "Return it to Captain Gort at Agmar's Hammer, east of Icemist Village.",
        },
        [12058] = {
            description = "Brann's journal also contained a guide to iron dwarf symbols. I've inscribed " ..
                "these on a keystone which will help you to understand the words inscribed on the rune " ..
                "plates.\n\nFrom the journal entries, it seems Brann may be chasing after clues to the " ..
                "origins of his people. Keep your eyes open for any clues as to his " ..
                "destination.\n\nReturn to Thor Modan, northeast of here, stand before each of the " ..
                "plates, and use the stone to determine the contents of each. We can't allow the Alliance " ..
                "to find him first.",
            rewardChoices = {{38710, 1}, {39013, 1}, {39043, 1}, {39075, 1}},
            rewardMoney = 59000,
        },
        [12059] = {
            description = "Picking up this strange device, you are certain that it is magical in nature. " ..
                "Unfortunately, it doesn't seem to connote any other kind of use.\n\nPerhaps the archmage " ..
                "back at Agmar's Hammer to the northeast of the Moonrest Gardens would be able to tell " ..
                "what it's used for?",
        },
        [12060] = {
            description = "This is a teleportation device. If I had to guess, I'd say that it leads to " ..
                "the surge needle platform floating above the Moonrest Gardens to the west.\n\nI need you " ..
                "to use it to investigate what's up there. It appears that the device works both ways so " ..
                "you shouldn't have to jump off.\n\nI expect that once you teleport to the top of the " ..
                "surge needle, there will be some sort of apparatus on it to observe.\n\nYou should be " ..
                "able to use the teleporter from anywhere within the gardens.",
            rewardMoney = 50000,
        },
        [12061] = {
            description = "This is a teleportation device. If I had to guess, I'd say that it leads to " ..
                "the surge needle platform floating above the Moonrest Gardens to the " ..
                "southwest.\n\n<name>, I need you to use it to investigate what's up there. It appears " ..
                "that the device works both ways so you shouldn't have to jump off.\n\nI expect that once " ..
                "you teleport up to the top of the surge needle, there will be some sort of apparatus on " ..
                "it to observe.\n\nYou should be able to use the teleporter from anywhere within the " ..
                "gardens.",
            rewardMoney = 50000,
        },
        [12063] = {
            description = "< Greatmother Icemist bows.>\n\nIt is an honor to meet you, hero. It is " ..
                "because of your actions that many of us are here now, alive and ready for battle against " ..
                "the Scourge.\n\nYou have done so much for us that it shames me to ask you for your " ..
                "assistance once more. Despite my pleas, my only son, Banthok, left here to go in search " ..
                "of his father, High Chief Icemist. He was last seen heading west, towards Icemist " ..
                "Village. Please find Banthok. I do not know what I would do if I lost my son.",
        },
        [12064] = {
            description = "They have my father bound by magical chains in the middle of Icemist Village. " ..
                "From what I have been able to gather, the prison is controlled by three powerful Anub'ar " ..
                "magi - each holding a piece of the key.\n\nScour Icemist and locate the magi. Kill them " ..
                "and take their key fragments. With all three pieces we might be able to free my father. " ..
                "Once he is free...\n\nRetribution will come swiftly.",
            rewardChoices = {{37959, 1}, {38001, 1}, {38044, 1}, {38105, 1}},
        },
        [12065] = {
            description = "The mage hunter forces are active on the Glittering Strand to the south of " ..
                "Moonrest Gardens. My guess is that you'll find a heavily guarded focus on the beach and " ..
                "a captain who is in charge of it.\n\nNo doubt the captain will have some sort of " ..
                "controlling device on their person. Get the controller and use it on the focus.\n\nWith " ..
                "any luck, we'll be able to get some more information about what they're really up to out " ..
                "there.",
            rewardMoney = 50000,
        },
        [12066] = {
            description = "The mage hunter forces are active on the Glittering Strand to the south of " ..
                "Moonrest Gardens. My guess is that you'll find a heavily guarded focus on the beach and " ..
                "a captain who is in charge of it.\n\nNo doubt the captain of the force down there will " ..
                "have some sort of controlling device on their person. Get the controller and use it on " ..
                "the focus.\n\nWith any skill on your part, we'll be able to get some more information " ..
                "about what they're really up to out there.",
            rewardMoney = 50000,
        },
        [12067] = {
            description = "You find a letter secreted in the lining of her robes. It " ..
                "reads:\n\n\"Father,\n\nI'm sorry for disappearing on you. If you're reading this letter, " ..
                "then I'm dead.\n\nI've been forced to work for Malygos's armies under threat that our " ..
                "family would be killed if I didn't. I feel so ashamed.\n\nIf there's anything that you " ..
                "can do to fight them, don't worry about me. I have them fooled and I'm sabotaging them " ..
                "from the inside.\n\nI love you, Daddy!\n\nEm\"\n\nCommander Saia Azuresteel will want to " ..
                "see this!",
            rewardMoney = 50000,
        },
        [12068] = {
            description = "<Drakuru places the Eye of the Prophets on his brow and the Heart of the " ..
                "Ancients on his chest.>\n\nWe be close, mon, very close!\n\nThe Drakkari Tablets be all " ..
                "dat remain ta be found. Nobody be knowin' how old dey be or what dey be sayin', but with " ..
                "the eye and the heart Drakuru can be readin' dem. Dey lie deep inside the crypt at " ..
                "Drakil'jin, due east of here.\n\nOnce ya got the tablets, get sacred mojo from the " ..
                "oracles and protectors so ya can summon me there. They'd be proud to be dyin' for such a " ..
                "cause.",
            rewardChoices = {{38718, 1}, {39022, 1}, {39051, 1}, {39089, 1}, {38751, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 59000,
        },
        [12069] = {
            description = "<Banthok hands you the prison key.>\n\nYou must hurry, <name>. Take the key " ..
                "and use it to unchain my father from the Anub'ar prison. Once he is freed, assist him in " ..
                "destroying the Anub'ar leader, Under-king Anub'et'kan. When the Under-king is defeated, " ..
                "take from his chitinous carapace a fragment as a trophy to present to the Horde at " ..
                "Agmar's Hammer. Let Agmar see the might of the High Chief!",
        },
        [12070] = {
            description = "The sons of iron have used their runes to enthrall many of my brothers and are " ..
                "using them to break the siege on Thor Modan. I wish we did not have to fight them, but " ..
                "we have no choice.\n\nMy giants will not hold out long against them.\n\nI have imbued " ..
                "this earthen shard with a blessing that will aid our allies. Take it with you to the " ..
                "battle in the Boulder Hills to the north, and use it to reassure and fortify my " ..
                "brethren.\n\nKill any iron dwarves who would stand in your way.",
            rewardMoney = 59000,
        },
        [12071] = {
            description = "They have seen the might of the Horde by land, now they must feel it from the " ..
                "air! I want you to report to Valnok Windrager at once! You will find him here, in " ..
                "Agmar's Hammer.\n\nValnok has already been briefed on your mission and is expecting you.",
        },
        [12072] = {
            description = "You've no doubt seen the army of Anub'ar blightbeasts that are being " ..
                "constructed at Icemist Village. The Anub'ar have plans to send those monsters against " ..
                "our soldiers at the Wrathgate. This cannot happen!\n\nVenture west to Icemist Village " ..
                "with this flare gun and use it to call down one of my war riders. Climb on its back and " ..
                "command it to destroy the blightbeasts that are out of reach from the ground!\n\nOnce " ..
                "you have decimated their aerial forces, return to me for your reward!",
            rewardChoices = {{37957, 1}, {37999, 1}, {38103, 1}, {38042, 1}},
        },
        [12073] = {
            description = "The Alliance isn't the only force opposing us in Grizzly Hills. The iron " ..
                "dwarves have firm control of the eastern coast, although Thor Modan, to the northeast, " ..
                "is besieged by stone giants.\n\nA skilled warrior uses an enemy's weakness against him " ..
                "and we would be fools to ignore the vulnerability of the iron dwarves at Thor Modan. " ..
                "Show the iron dwarves no mercy. Slay any and all who would stand in your way.\n\nThe " ..
                "'sons of iron' will learn to fear the Horde.",
            rewardMoney = 59000,
        },
        [12074] = {
            description = "The old iron dwarf capital of Thor Modan, far to the northeast, is under siege " ..
                "by a mysterious band of stone giants and earthen.\n\nWhy the creations of the titans " ..
                "would war against each other is beyond my understanding and the Horde's interest, but " ..
                "there is an opportunity here to weaken a mutual enemy.\n\nTravel to Thor Modan and seek " ..
                "out this ' Kurun ' who commands the giants and earthen. Make common cause with him and " ..
                "use his forces to crush the iron dwarves.",
        },
        [12075] = {
            description = "Cold out here, isn't it, <race>?\n\nKo'char has refused to meet with me. It " ..
                "seems he has more pressing things on his mind - namely, the jormungar that have been " ..
                "attacking them from the cavern below. Maybe you can help me convince Ko'char that I'm " ..
                "one of the good guys.\n\nI saw a giant being eaten by some of the worms at the entrance " ..
                "to the cavern north of here... I'm still puzzled as to how the worms are killing them so " ..
                "easily. Bring me a sample from one of his wounds.",
            rewardMoney = 56000,
        },
        [12076] = {
            description = "Even at first glance, the sample you brought me shows obvious signs of some " ..
                "kind of corrosive spit. It would be a natural assumption that the same substance these " ..
                "worms use to burrow through the ground has allowed them a formidable weapon against the " ..
                "Ice Giants.\n\nTake this scraper and pick a fight with some of the worms. When they spit " ..
                "on you, use the scraper to remove it and bring it back to me.\n\nGet me a couple samples " ..
                "- I'm going to have to use it as the base for an elixir.",
            rewardMoney = 56000,
        },
        [12077] = {
            description = "This elixir should protect against their spit. Offer it to Ko'char for me, " ..
                "will you? Tell him there's plenty more where that came from if he'll return the favor.",
            rewardItems = {{36770, 1}},
            rewardMoney = 56000,
        },
        [12078] = {
            description = "So be it. If the giants will not come to our aid, perhaps we can make use of " ..
                "these worms. There are sure to be some spawn with their brood mother in the cavern " ..
                "below. Take this box and capture 3 of their spawn and bring them to me.\n\nWhere " ..
                "diplomacy fails, enslaving is a perfectly viable alternative.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 56000,
        },
        [12079] = {
            description = "Greetings little one. I know not what madness has brought you to the Crystal " ..
                "Vice, but you are welcome in my presence.\n\nThese ice worms... these jormungar have " ..
                "taken a taste to eating my brothers. I doubt you will find my kind friendly by any terms " ..
                "during this time of battle, but if you are here to help with the worms, then you have my " ..
                "ear.\n\nIf we are to take the cavern back, we must first clear the canyon of these " ..
                "jormungar feeders. Join us in battle, <race>!",
            rewardMoney = 56000,
        },
        [12080] = {
            description = "The jormungar have a spawnmother in the caverns below. We call her Rattlebore " ..
                "- a name that was gifted to her by an adventurer from the Plaguelands. I saw her only " ..
                "briefly as I was fighting off their initial onslaught - she is large enough to devour " ..
                "one of my young whole. This cavern will not be ours until she is removed from it.",
            rewardChoices = {{37945, 1}, {37989, 1}, {38033, 1}, {38096, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 168000,
        },
        [12081] = {
            description = "Without your help, we wouldn't have been able to turn the tide of the battle " ..
                "for Thor Modan. This ancient city has long been a battlefield between the forces of " ..
                "earth and stone. I can only hope we have silenced it for the last time.\n\nThe iron " ..
                "dwarves can still use their magic to capture and enslave my brothers. Gavrock is " ..
                "searching for a way to free the runed giants. Look for him on a small cluster of " ..
                "islands, called the Ruins of Tethys, off the central part of the Eastwind Shore to the " ..
                "south.",
        },
        [12082] = {
            description = "Listen, kid. This is no place for you to be playin' around.\n\nI'm about to " ..
                "make a break for it. Stick with me and I'll get you outta here.",
            rewardChoices = {{38729, 1}, {39028, 1}, {39056, 1}, {39094, 1}},
            rewardMoney = 59000,
        },
        [12083] = {
            description = "I'm convinced that there must be more of those foci, each of them in-turn " ..
                "redirecting the ley line energies. We still don't know precisely what they're doing with " ..
                "all of that power, though.\n\nMy guess is that you'll find another one atop the Lothalor " ..
                "Woodlands to the southeast. Once again you'll need to find the person in charge and take " ..
                "whatever controlling device they have in their possession as I'm sure that each focus " ..
                "has its own.\n\nBe careful, <name>, those woods are very dangerous.",
            rewardChoices = {{37942, 1}, {37985, 1}, {38029, 1}, {38093, 1}},
            rewardMoney = 50000,
        },
        [12084] = {
            description = "I'm convinced that there must be more of those foci, each of them in-turn " ..
                "redirecting the ley line energies. We still don't know precisely what they're doing with " ..
                "all of that power, though.\n\nMy guess is that you'll find another one atop the Lothalor " ..
                "Woodlands to the south. Once again you'll need to find the person in charge and take " ..
                "whatever controlling device they have in their possession as I'm sure that each focus " ..
                "has its own.\n\nBe quick about your business, <class>. I feel that time may be running " ..
                "out.",
            rewardChoices = {{37942, 1}, {37985, 1}, {38029, 1}, {38093, 1}},
            rewardMoney = 50000,
        },
        [12085] = {
            description = "You find a letter secreted in the lining of his robes. It " ..
                "reads:\n\n\"Deino,\n\nTa'zinni sorry for disappearing on ya. If you're reading this " ..
                "letter, then I be dead.\n\nI been forced to work for Malygos's armies under threat that " ..
                "the family would be killed if I didn't. Ta'zinni wasn't gonna let that happen!\n\nDon't " ..
                "worry about me, just keep your kids safe. I have them fooled and I'm sabotaging them " ..
                "from the inside.\n\nI love you, sistah!\n\nTa'zinni\"\n\nOverlord Agmar is sure to want " ..
                "to see this!",
            rewardMoney = 50000,
        },
        [12086] = {
            description = "The man you seek went far to the east, to a place near the coast called " ..
                "Death's Stand, beyond Unu'pe.\n\nBe careful if you go in search of him, <name>. He bore " ..
                "the mark of Karkut... he who watches over the dead.",
        },
        [12088] = {
            description = "Well, <name>, you helped us out... so I figure it's only fair that we help you " ..
                "out as well.\n\nYou're looking for Thassarian? He disappeared this morning. We think he " ..
                "went off north to the Wailing Ziggurat. If we hadn't fought side by side by him we'd " ..
                "even think he was a traitor.\n\nSee, he's a Death Knight... and I know they're on our " ..
                "side and all... but it wasn't too long ago they were servants of Arthas.\n\nBut not " ..
                "Thassarian, he's a good guy. Go to the Wailing Ziggurat, see if he's doing okay.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [12089] = {
            description = "By decree of Overlord Agmar:\n\nTarget: Magister Keldonus\n\nCrime: " ..
                "Treason\n\nStatus: Alive\n\nMagister Keldonus, once mage commander of Agmar's Hammer, is " ..
                "to be killed on sight in the name of the Horde.\n\nKeldonus was last seen traveling " ..
                "southwest towards Moonrest Gardens to join the blue dragonflight in their campaign " ..
                "against magic.\n\nApproach with caution as Keldonus is a powerful magus.\n\nAll bounties " ..
                "are paid out by Captain Gort at Agmar's Hammer.",
            rewardChoices = {{38137, 1}, {38138, 1}, {38189, 1}, {38194, 1}, {38195, 1}, {38196, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 112000,
        },
        [12090] = {
            description = "By decree of Overlord Agmar:\n\nTarget: Gigantaur\n\nCrime: Attacks upon the " ..
                "Horde; \"Bein' ugly\"\n\nStatus: Alive\n\nThe magnataur lord, Gigantaur, is wanted in " ..
                "relation to a number of attacks against Horde soldiers and installations in the " ..
                "Dragonblight.\n\nGigantaur was last seen wandering the woods and roads south by " ..
                "southeast of Agmar's Hammer.\n\nGigantaur should be considered armed and extremely " ..
                "dangerous.\n\nAll bounties are paid out by Captain Gort at Agmar's Hammer.",
            rewardChoices = {{37969, 1}, {38012, 1}, {38055, 1}, {38116, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 112000,
        },
        [12091] = {
            description = "By decree of Overlord Agmar:\n\nTarget: Dreadtalon\n\nCrime: Attacks upon the " ..
                "Horde\n\nStatus: Alive\n\nDreadtalon is wanted for numerous attacks upon Horde caravans " ..
                "traveling to and from Venomspite.\n\nDreadtalon makes his home on a bluff overlooking " ..
                "the Ruby Dragonshrine, east of Agmar's Hammer. He should be approached with extreme " ..
                "caution.\n\nAll bounties are paid out by Captain Gort at Agmar's Hammer.",
            rewardChoices = {{37970, 1}, {38013, 1}, {38056, 1}, {38117, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 112000,
        },
        [12092] = {
            description = "It's not only the <race> race that has been impacted by what the blue " ..
                "dragonflight forces have done. The ancients of the Lothalor Woods to the southeast have " ..
                "been affected as well.\n\nSome have been corrupted-- avoid them at all costs--but most " ..
                "can still be saved. However, the treants of the woods seem to be immune to the magic " ..
                "seeping through the land and the arcane wyrms that have come with it.\n\nAsk the treants " ..
                "for their bark and feed it to the ancients. Hopefully that will be enough to save them.",
            rewardChoices = {{37966, 1}, {38008, 1}, {38051, 1}, {38112, 1}},
            rewardMoney = 50000,
        },
        [12093] = {
            description = "Even as Kurun attacks Thor Modan, the iron dwarves work their magics against " ..
                "our brothers. Summoning our brothers from the earth, then binding them with runes, the " ..
                "sons of iron force them to war against the children of stone.\n\nAlong the Eastwind " ..
                "Shore, they use runes of compulsion to send enslaved giants to the battlefields of the " ..
                "north.\n\nFind the four runes of compulsion and force their overseers to appear by " ..
                "defeating the rune-weavers who man each rune. Without the overseers, the runes are " ..
                "useless.",
            rewardMoney = 59000,
        },
        [12094] = {
            description = "While the runes of compulsion are dormant, there is a chance we can release " ..
                "the runed giants.\n\nI will give you a piece of stone that has been part of me since my " ..
                "creation. If properly imbued, it can be used to free the bound giants.\n\nTwo ancient " ..
                "stone markers sit atop places of power between the Path of Iron and the forest's edge -- " ..
                "locations your people would call the intersections of ley lines. The other is on an " ..
                "island at the southern end of these ruins. Charge the shard at each stone and return.",
            rewardMoney = 59000,
        },
        [12095] = {
            description = "East of here, in the heart of the Dragonblight, is a field full of nothing but " ..
                "dragon bones and snow. The Scourge have set up multiple camps in the central tundra and " ..
                "are raising frostwyrms to send against our forces at the Wrathgate. While most of these " ..
                "frostwyrms are easily dealt with by Rokhan and his dragon hunters, one of them is " ..
                "proving to be a bit problematic.\n\nGo northeast and seek out Rokhan at Dragon's Fall. " ..
                "Help him and his men put down Sarathstra and you'll be rewarded handsomely!",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [12096] = {
            description = "The ancients of the Lothalor Woods to the south are being corrupted by arcane " ..
                "wyrms... wyrms which have risen out of the ground!\n\nThose that are already corrupted " ..
                "are deadly and of no use to us, but most can still be saved. Luckily, the treants of the " ..
                "woods seem to be immune to everything happening up there.\n\nAsk the treants for their " ..
                "bark and when you get some, feed it to the ancients. This should strengthen them.\n\nNow " ..
                "leave me to my business! I have to keep an eye on these apothecaries.",
            rewardChoices = {{37966, 1}, {38008, 1}, {38051, 1}, {38112, 1}},
            rewardMoney = 50000,
        },
        [12097] = {
            description = "Me hunters be dead or frozen, <name>. You still want to do dis? Just say da " ..
                "word and me call for da dragon once more.\n\nIf ya kill it, take da beast's frozen heart " ..
                "back to Agmar's Hammer and present it to Gort. He sure to reward you good, mon.",
            rewardChoices = {{38530, 1}, {38531, 1}, {38532, 1}, {38533, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 177000,
        },
        [12098] = {
            description = "I'm certain that you'll find the next ley line focus somewhere in the remains " ..
                "of Indu'le Village to the southeast. The problem is, we've had absolutely no reports of " ..
                "there being one there.\n\nIf you would, please investigate the village for any signs of " ..
                "the focus or the mage hunters and their commander in the area.\n\nDon't forget to search " ..
                "in the lake if you have to.",
            rewardMoney = 50000,
        },
        [12099] = {
            description = "The rock shard you imbued should be powerful enough to break the runic magic " ..
                "binding my brothers.\n\nTake it with you and find the runed giants walking north along " ..
                "the Eastwind Shore. Unleash the power stored in the stone and observe the results.\n\nIf " ..
                "it works, the runed giants should return to their senses and stop obeying the iron " ..
                "dwarves. If the stone fails to work, the giants may attack in a weakened state. But, " ..
                "what choice do we have? If we do not try, they will remain enslaved without hope.",
            rewardChoices = {{39109, 1}, {39112, 1}, {39117, 1}, {39119, 1}, {39120, 1}},
            rewardMoney = 118000,
        },
        [12100] = {
            description = "With Scourge comes death and disease. We often overlook that the wildlife of a " ..
                "Scourge infested area is ravaged and ultimately destroyed by rot and contagion.\n\nFor " ..
                "most of the indigenous beasts of the Dragonblight it is too late. The festering disease " ..
                "that the Scourge brings has already infected the beasts and they are now rabid and " ..
                "rotting.\n\nYou must venture west, towards the Pit of Narjun, and cull the infected " ..
                "wildlife. Check their corpses for a preserved organ as we need one to devise a vaccine.",
        },
        [12101] = {
            description = "Our Forsaken allies have sent their apothecary core here to assist us in " ..
                "destroying the Scourge at the Wrathgate. One among them, Doctor Sintar Malefious, is " ..
                "well versed in the Scourge rot and methods of containing the spread. I had previously " ..
                "worked out a deal with him in regards to devising a vaccine for wildlife. He's since " ..
                "been waiting on the organ.\n\nDeliver this rot resistant organ to Dr. Malefious and let " ..
                "him know it's from me. He'll direct you on your next task.",
        },
        [12102] = {
            description = "How fortuitous it is that the Ruby Dragonshrine lays just to the east. It is " ..
                "there that you will find a flower called the ruby lilac. This lifegiving plant is all " ..
                "that I need to concoct a vaccine for the untainted beasts of this region.\n\nTravel east " ..
                "and search the Ruby Dragonshrine for the lilac.\n\nJust one thing: The dragonshrine, " ..
                "like all the dragonshrines in this blasted wasteland, is beset by the Scourge. Watch " ..
                "your step. We wouldn't want you to be devoured by an emberwyrm.\n\n<Sintar laughs.>",
        },
        [12104] = {
            description = "<Doctor Malefious hands you a vial full of murky liquid.>\n\nHere you are " ..
                "then, <race>. Take this back to the cow and let him know that all debts have been paid. " ..
                "We are officially \"square.\"\n\nNow leave me before I set Jennings upon you.",
        },
        [12105] = {
            description = "The journal was written by a denizen of Silverbrook named Mikhail. It details " ..
                "the arrival of a shadow-worshipping group called the \"wolfcult.\"\n\nThe villagers were " ..
                "reluctant to embrace the cult at first, but sympathizers sprung up gradually among town " ..
                "residents.\n\nUnsettled by this, Mikhail sent his daughter Sasha away from Silverbrook " ..
                "while he attempted to reason with the other villagers.\n\nMikhail's last entry mentions " ..
                "a meeting of local town leaders to discuss unspecified events in Hollowstone Mine.",
            rewardChoices = {{38734, 1}, {39033, 1}, {39060, 1}, {39098, 1}},
        },
        [12106] = {
            description = "I'm certain that you'll find the next ley line focus somewhere in the remains " ..
                "of Indu'le Village to the southeast. The problem is, I've had absolutely no reports of " ..
                "there being one there.\n\nI need you to go investigate the village for any signs of the " ..
                "focus or the mage hunters and their commander in the area.\n\nSearch in the lake if you " ..
                "have to!",
            rewardMoney = 50000,
        },
        [12107] = {
            description = "Within his robes you find two things of interest.\n\nOne is a talisman, which " ..
                "is clearly a focus controlling device. The other is a set of orders from someone named " ..
                "Sidragos, which were ultimately intended for the leader back at the Moonrest " ..
                "Gardens.\n\nThe water-soaked parchment informs Goramosh that he is to move all mage " ..
                "hunter forces east to the Azure Dragonshrine.\n\nPerhaps you should get what information " ..
                "you can from the focus and head east to observe the dragonshrine from its western ledge.",
            rewardChoices = {{38129, 1}, {38151, 1}, {38152, 1}, {38153, 1}, {38217, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 100000,
        },
        [12109] = {
            description = "The Westfall boys were sent east to look for a path into the northern " ..
                "territories. Their secondary objective is to secure strategic resource points, so I'm " ..
                "sure they wouldn't mind investigating a mine.\n\nLook for the Westfall Brigade " ..
                "encampment far to the northeast and seek out Gryan Stoutmantle. You might remember him " ..
                "if you ever spent any time in Westfall. Make sure to tell him I sent you.\n\nHe'll be " ..
                "more than happy to let you claim a functioning mine for the king.",
        },
        [12110] = {
            description = "Within his robes you find two things of interest.\n\nOne is a talisman, which " ..
                "is clearly a focus controlling device. The other is a set of orders from someone named " ..
                "Sidragos, which were ultimately intended for the leader back at the Moonrest " ..
                "Gardens.\n\nThe fragile water-soaked parchment informs Goramosh that he is to move all " ..
                "mage hunter forces east to the Azure Dragonshrine.\n\nPerhaps you should get what " ..
                "information you can from the focus and head east to observe the dragonshrine from its " ..
                "western ledge.",
            rewardChoices = {{38129, 1}, {38151, 1}, {38152, 1}, {38153, 1}, {38217, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 100000,
        },
        [12111] = {
            description = "Inside this pack are several vials containing the vaccine that Sintar created. " ..
                "I now want you to search the nearby woods for Snowfall elk and arctic grizzlies. When " ..
                "you locate the animals, find a safe distance and throw a vial in their general " ..
                "direction. The vial will shatter and release a fine gas that will act as the inoculating " ..
                "agent. The beasts merely have to step inside the gas and they will be vaccinated - " ..
                "ultimately saved.\n\nInoculate as many of the beasts as you can and return to me.",
            rewardChoices = {{38131, 1}, {38132, 1}, {38169, 1}, {38170, 1}, {38171, 1}, {38172, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 53000,
        },
        [12112] = {
            description = "Well it seems you were of a bit of use after all. It's not been my experience " ..
                "to meet many a <race> that are.\n\nWe don't have any more use for you here. Head into " ..
                "the Vice and see if my brother Zort could use a hand. He went to see if he could con the " ..
                "giants into laying down their lives so that we don't have to. He certainly wasn't known " ..
                "for having the brains in the family.",
            rewardMoney = 44000,
        },
        [12113] = {
            description = "G'day to ya, <class>! Have yerself a seat by me fire, eh?\n\nI'd offer to " ..
                "share a nice hot meal, only I ain't got one. I'm stuck here waitin' on an associate, or " ..
                "I'd be out tryin' to remedy that situation meself.\n\nSay, you seem to have nuthin' but " ..
                "time on yer hands and there be plenty o' meat in these parts. What say ya lend a hand " ..
                "and round up some grub?",
            rewardMoney = 59000,
        },
        [12114] = {
            description = "Trolls... me hates 'em all! < Harkor spits.>\n\nI once got meself captured by " ..
                "a band o' tha beasts... came this close ta gettin' me head shrunk!\n\nMe friends tell me " ..
                "to just move on and put it all behind me, but that just ain't sittin' right.\n\nWanna " ..
                "know what would make me feel better, <race>? Seein' a pile of their corpses so high it " ..
                "blots out the sun! I've got good gold to spend if ya can make that happen.",
            rewardChoices = {{38728, 1}, {38758, 1}, {39027, 1}, {39055, 1}, {39093, 1}},
            rewardMoney = 59000,
        },
        [12115] = {
            description = "There is one who recently joined our cause that might be able to decipher this " ..
                "tome. An unbound death knight known as Koltira Deathweaver has temporarily taken " ..
                "residence here at Agmar's Hammer. As he was once a death knight of Arthas and member of " ..
                "the Scourge, he might be able to translate the language of the dead.\n\nTake the " ..
                "flesh-bound tome to Koltira and ask him to translate the pages.",
        },
        [12116] = {
            description = "Greetings, <class>. It is kind of you to stop and listen to Kraz 's " ..
                "tale.\n\nFor many years Kraz has strained to hear the spirits and do their " ..
                "bidding.\n\nRecently, many voices have been crying to Kraz from these ruins. They seek " ..
                "for a peace they cannot find on their own.\n\nIf you would help the spirits of those who " ..
                "have come before, enter this crypt and collect something that once belonged to those " ..
                "tormented souls.",
            rewardMoney = 118000,
        },
        [12117] = {
            description = "<race>, word just arrived from Moa'ki Harbor. Something very bad happened over " ..
                "there this morning!\n\nYou've been very helpful to us here. Would you consider using the " ..
                "boat from Unu'pe to travel to the great Dragonblight?\n\nBy the sound of things, Elder " ..
                "Ko'nani could certainly use your assistance.",
            rewardChoices = {{37283, 1}, {37319, 1}, {37566, 1}, {37546, 1}},
        },
        [12118] = {
            description = "<race>, word just came in off the boat from Moa'ki Harbor. Something very bad " ..
                "happened over there this morning!\n\nYou've been very helpful to us here. Would you " ..
                "consider using the boat to travel to the great Dragonblight?\n\nBy the sound of things, " ..
                "Elder Ko'nani could certainly use your assistance.",
            rewardChoices = {{37283, 1}, {37319, 1}, {37566, 1}, {37546, 1}},
        },
        [12119] = {
            description = "<name>, you must travel as swiftly as you can to Wyrmrest Temple and present " ..
                "this letter to the steward, Tariolstrasz.\n\nThe temple sits in the center of the " ..
                "Dragonblight. Follow the road east until it ends, and then cross The Dragon Wastes to " ..
                "get to it.\n\nI'm sure that when the steward reads your introduction, he'll see to it " ..
                "that you gain an audience with Queen Alexstrasza. We can only hope that we're not too " ..
                "late.\n\nThank you for all that you have done on our behalf. Safe journeys!",
        },
        [12120] = {
            description = "Corruption....\n\nEven before you delivered these jars, Kraz could sense it. " ..
                "This corruption fills the ancient Drakkari spirits with great angst and prevents them " ..
                "from entering the rest they seek.\n\nKraz will not lie, <class>. Cleansing this place " ..
                "will require great sacrifice, but we shall speak of that at another time.\n\nThere is " ..
                "one among the living here who holds the key to its cleansing. Seek out Drak'aguul and " ..
                "return to Kraz with the mallet he carries.",
            rewardChoices = {{38730, 1}, {39029, 1}, {39057, 1}, {39095, 1}},
            rewardMoney = 59000,
        },
        [12121] = {
            description = "These Drakkari have met you with nothing but savage hostility. You owe them " ..
                "nothing. Few indeed would carry out the task that Kraz asks of you today.\n\nTo cleanse " ..
                "this place and send the spirits to their eternal rest, you must join them in " ..
                "death.\n\nThere is one inside the crypt who awaits you - on the other side. He holds the " ..
                "knowledge we seek, <name>.\n\nUse the mallet on the gongs. The spirit of he who corrupts " ..
                "this place will surely deliver you to the spirit world.\n\nKraz awaits your return.",
            rewardMoney = 59000,
        },
        [12122] = {
            description = "<name>, you must travel as swiftly as you can to Wyrmrest Temple and present " ..
                "this letter to the steward, Tariolstrasz.\n\nThe temple sits in the center of the " ..
                "Dragonblight. Follow the road east until it ends, and then cross The Dragon Wastes to " ..
                "get to it.\n\nI'm sure that when the steward reads your introduction, he'll see to it " ..
                "that you gain an audience with Queen Alexstrasza. We can only hope that we're not too " ..
                "late.\n\nThank you for all that you have done on our behalf. Safe journeys!",
        },
        [12123] = {
            description = "<The dragon steward pulls your letter of introduction out of his " ..
                "sleeve.>\n\nYes... yes, I think that you are ready to see the queen now.\n\nWhen you are " ..
                "ready, speak to me again and I will see to it that one of these drakes delivers you " ..
                "safely to the top of the temple. You will need to present your letter in person to Queen " ..
                "Alexstrasza.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [12124] = {
            description = "<The dragon steward pulls your letter of introduction out of his " ..
                "sleeve.>\n\nYes... yes, I think that you are ready to see the queen now.\n\nWhen you are " ..
                "ready, speak to me again and I will see to it that one of these drakes delivers you " ..
                "safely to the top of the temple. You will need to present your letter in person to Queen " ..
                "Alexstrasza.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [12125] = {
            description = "The blood of innocents was once used to sate the thirst of the blade. Alas, " ..
                "such options are no longer available to me.\n\n<Koltira pauses to think.>\n\nWe must " ..
                "improvise. South of here, upon the high bluffs, is the tuskarr village of Indu'le. " ..
                "Having been recently overrun by the Blue Dragonflight's chaotic magic, the resident " ..
                "tuskarr of Indu'le have gone mad.\n\nTake this blood gem and use it on a deranged " ..
                "villager. If I cannot take the blood of innocents, I shall have the blood of the meek!",
        },
        [12126] = {
            description = "The power of the unholy is coveted among my kind. It makes up the very fiber " ..
                "of our existence, granting death to those that dare make a mockery of it! Thankfully " ..
                "there is a font from which I may draw from in my time of need.\n\nTake this unholy gem " ..
                "and make your way to the Ruby Dragonshrine, east of here. It is there that you will find " ..
                "Duke Vallenhal, death knight of Arthas. Weaken his resolve in battle and unleash the " ..
                "power of the gem upon him. It will finish him off and steal his unholy energy!",
        },
        [12127] = {
            description = "The biting cold protects the death knight while repelling his enemies. He that " ..
                "commands the power of frost can incite chaos and destruction!\n\nTake this frost gem and " ..
                "travel far across the open tundra of the Dragonblight until you come upon the Mirror of " ..
                "Dawn, east of Wyrmrest Temple. It is there that you are to battle the legions of ice " ..
                "revenants that dwell upon the lakes surface and take from them the essence of frost. " ..
                "Utilize the power of the gem when they are weak, <name>!",
        },
        [12128] = {
            description = "With all the excitement about the army trying to move through Thor Modan, I'd " ..
                "almost forgotten about Raegar's crew down at Prospector's Point.\n\nI sent Raegar and " ..
                "his assistants, along with a mountaineer friend, down to establish a small post near Dun " ..
                "Argol, at the southern end of the Eastwind Shore.\n\nThey were to investigate the iron " ..
                "dwarf presence in the southern hills, but I haven't received any reports yet. Could you " ..
                "check up on them if you're going down that way?",
        },
        [12129] = {
            description = "The iron dwarves are making no secret of the fact that they're preparing for " ..
                "war. With their giants, golems, and lightning elementals, they'd have a technological " ..
                "advantage against the Westfall Brigade. If they don't find passage north in time, the " ..
                "irons could take them by surprise.\n\nWe've got to tie them up here, and I've got just " ..
                "the way to do it. Dun Argol is full of rune-smiths churning out war golems. They carry " ..
                "plans for specific pieces, so you'll need to find and assemble all the parts.",
            rewardMoney = 59000,
        },
        [12130] = {
            description = "We've got the blueprints, but we can't do anything with them without parts! We " ..
                "don't have access to a foundry, much less materials, but there's a whole load of parts " ..
                "up in Dun Argol.\n\nYour job?\n\nGive them a new home.\n\nThey're likely to be scattered " ..
                "around any of the buildings where the iron rune-smiths are working, and I wouldn't blame " ..
                "the irons for being cranky when you try to filch their handiwork. The more parts you can " ..
                "bring, the better we can make this golem.",
            rewardMoney = 59000,
        },
        [12131] = {
            description = "We're almost there, but the war golem won't run without power cells. From the " ..
                "information I was able to collect in Dun Argol before we were discovered, both " ..
                "Rune-Smith Durar and Rune-Smith Kathorn each create one power cell.\n\nWe'll need one " ..
                "power cell from each of the rune-smiths before our golem will work.\n\nYou should be " ..
                "able to find each rune-smith in his workshop on the central level of Dun Argol.",
            rewardMoney = 59000,
        },
        [12132] = {
            description = "While you have done much for me, one task remains.\n\nBeside the world you " ..
                "know exists another world. It is from that world, the world of shadows, that my " ..
                "tormentors assault me. While I am powerless to face my own demons, you could end their " ..
                "reign of terror. You have the strength, I have seen it with my own eyes.\n\nEnter the " ..
                "world of shadows and face the demons that torment me!\n\nDo this and I will translate " ..
                "the tome, as promised.",
        },
        [12134] = {
            description = "This thing... this curse... that's affecting Silverbrook and Solstice " ..
                "Village... it makes beasts out of people.\n\nMy father tried to warn them, but they all " ..
                "listened to the wolfcult instead.\n\nThey're too far gone now, it's time to put them " ..
                "down... for their own sake.",
            rewardChoices = {{39010, 1}, {39011, 1}, {39110, 1}, {38755, 1}},
            rewardMoney = 59000,
        },
        [12136] = {
            description = "Here it is, <name>. I have translated everything printed upon the pages of the " ..
                "tome. Inside it you will find a list of the names of Cult of the Damned members spanning " ..
                "the entire continent.\n\nTheir network of spies and operatives is impressive, to say the " ..
                "least.\n\nFarewell, friend. May the book serve you and your people well.",
            rewardChoices = {{37958, 1}, {38000, 1}, {38043, 1}, {38104, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 159000,
        },
        [12137] = {
            description = "It be as the prophecies said, mon. A <race> <class> be comin' to set our " ..
                "spirits to rest. We been waitin' for a long time now!\n\nThe Drakkari have become a lost " ..
                "people, fierce and savage.\n\nBut here we suffer by no fault of our own, mon. This place " ..
                "need cleansin' and only the living can do it.\n\nSpeak to me when ya be ready to rejoin " ..
                "your body. Then take the snow from the chest near me here and put my bruddas to " ..
                "sleep.\n\nTake their remnants to your spirit guide. He be knowin' what to do next.",
        },
        [12138] = {
            description = "You'd think the guys making the power cells would've thought to power them up, " ..
                "but no, they've got to make it difficult for us.\n\nFine, we'll charge those cells the " ..
                "hard way. There's enough power in them to run the golem for a short time, but don't " ..
                "expect it to be any good in combat.\n\nYou see the lightning sentries that the irons " ..
                "have posted around the perimeter of Dun Argol? Bring the golem with you, take it close " ..
                "to them, and use the golem to absorb the power as the sentries die.",
            rewardMoney = 59000,
        },
        [12140] = {
            description = "Like the tauren, Forsaken, trolls and blood elves, so too do the taunka need a " ..
                "leader born of their own blood. The one you saved from Icemist, Roanauk, will be this " ..
                "leader.\n\n< Overlord Agmar hands you a parchment.>\n\nI give to you something familiar " ..
                "- the blood oath of the Horde.\n\nTake the oath to Roanauk Icemist and initiate him into " ..
                "the Horde as leader of the taunka.\n\nLet us not keep him waiting.\n\n<Agmar nods.>",
            rewardChoices = {{38002, 1}, {38106, 1}, {38293, 1}, {37960, 1}},
        },
        [12141] = {
            description = "I see that you are very eager to help, <name>. You didn't come all the way to " ..
                "Northrend to stay holed up in a city! I've just the task for you... something that'll " ..
                "take you far away from here.\n\nWe've long sought to gain the favor of the tuskarr " ..
                "native to Northrend. Recently a young tuskarr came to us seeking help, something we " ..
                "couldn't offer at the time.\n\nNow that you're around, maybe you can lend him a hand. " ..
                "Look for Karuk near the Riplash Strand, southwest of here, and see what you can do to " ..
                "help.",
        },
        [12142] = {
            description = "Ugh! One of those little snobold runts trashed our camp while we were busy " ..
                "with that last dragon. They've been plaguing us whenever we turn our backs... I've had " ..
                "enough!\n\nTo the south you'll find the snobolds hiding under the skirts of some of the " ..
                "local magnataur. Go slaughter them.\n\nIf the magnataur interfere on behalf of their " ..
                "slaves, kill them as well.",
            rewardMoney = 53000,
        },
        [12143] = {
            description = "I can't believe this! Another band of those vermin just tried to take off with " ..
                "more of our supplies. They're scurrying off towards that north canyon, get after them " ..
                "and deal with whoever they're going to!",
            rewardChoices = {{37965, 1}, {38007, 1}, {38049, 1}, {38111, 1}},
            rewardMoney = 53000,
        },
        [12144] = {
            description = "Oi, mon! One of dose little snobold runts trashed our camp during da last " ..
                "dragon attack. Dey've been houndin us wheneva we turn our backs and I've had " ..
                "enough.\n\nTo da east you'll find da snobolds hiding under da skirts of some of da local " ..
                "magnataur. Go slaughter dem. If da magnataur interfere on behalf of deir slaves, kill " ..
                "dem as well.",
            rewardMoney = 53000,
        },
        [12145] = {
            description = "I can't believe dis! Another band of dose vermin just tried ta take off with " ..
                "more of our supplies. Dey're scurrying down da canyon now, get after dem and deal with " ..
                "whoever dey're going to!",
            rewardChoices = {{37965, 1}, {38007, 1}, {38049, 1}, {38111, 1}},
            rewardMoney = 53000,
        },
        [12146] = {
            description = "The underside of the horn boasts an emblazoned seal with a hammer and a " ..
                "lightning bolt. Something about the horn seems extremely out of place on a " ..
                "Magnataur.\n\nTake the horn south down the Path of the Titans to Wyrmrest and seek out " ..
                "someone who might be interested in these threatening implications.",
            rewardMoney = 53000,
        },
        [12147] = {
            description = "The underside of the horn boasts an emblazoned seal with a hammer and a " ..
                "lightning bolt. Something about the horn seems extremely out of place on a " ..
                "Magnataur.\n\nTake the horn east across the Dragon Wastes to Wyrmrest and seek out " ..
                "someone who might be interested in these threatening implications.",
            rewardMoney = 53000,
        },
        [12148] = {
            description = "Such a strange seal to see among magnataur... it suggests an unusual amount of " ..
                "organization.\n\nMagnataur rarely put aside their aggressive natures to cooperate with " ..
                "each other. I suspect they have their eyes set on raiding a large settlement.\n\nI very " ..
                "much doubt that this horn is unique, I need you to prove me wrong. In the canyon " ..
                "northwest of the Azure Dragonshrine you will find Bonesunder. Go challenge him and bring " ..
                "me back any evidence you find that might confirm my concerns.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 53000,
        },
        [12149] = {
            description = "Magnataur are hideously violent creatures... this is the main reason we rarely " ..
                "see them come together in any real numbers without killing each other. A powerful leader " ..
                "has stepped up somewhere among them and we need to hunt him down if we are to stop this " ..
                "threat.\n\nI will start asking around. I need you to disrupt them as much as possible in " ..
                "the meantime.\n\nEast of here there are 3 torches erected. Near them, there are 3 " ..
                "dominant Magnataur - put them down to buy us some time to hunt down this leader.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 53000,
        },
        [12150] = {
            description = "Dregmar Runebrand is a magnataur runemaster... a rare breed. He's generally " ..
                "solitary, but has been known to associate with the more powerful and influential " ..
                "magnataur in Dragonblight for quite some time. He will know who this new leader " ..
                "is.\n\nIt is unlikely we will gain any aid with the increasing concerns with the Scourge " ..
                "and the blue flight, so I need you to procure the information from Dregmar by any means " ..
                "necessary.\n\nI was told he can be found amongst the cliffs overlooking the Mirror of " ..
                "the Dawn.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 112000,
        },
        [12151] = {
            description = "There's no reason to suspect Dregmar's words are anything but true. Whether " ..
                "Grom'thar defeats you or is defeated by you, he can wash his hands of this.\n\nFollow " ..
                "his instructions... take the horn that you brought me earlier, travel to the ring of " ..
                "torches south of the Azure Dragonshrine, and blow it to announce your challenge.\n\nWhen " ..
                "Grom'thar the Thunderbringer arrives, kill him and bring me his head.",
            rewardChoices = {{38130, 1}, {38154, 1}, {38155, 1}, {38156, 1}, {38157, 1}, {38224, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 168000,
        },
        [12152] = {
            description = "It is good to see you back among the living. Many who travel the path of the " ..
                "dead do not return to speak of it.\n\nWhile you were away, a vision appeared to Kraz " ..
                "revealing what remains to be done.\n\nA sacred offering lies somewhere inside the crypt. " ..
                "Take this spirit dust fashioned from the remnants you collected and use it on the " ..
                "offering.\n\nThe infused offering will bring an end to the corrupted warlord and will " ..
                "release the many tormented souls.\n\nMay the spirits guide your actions, <name>.",
            rewardChoices = {{39113, 1}, {39114, 1}, {39125, 1}, {39127, 1}, {39124, 1}, {39118, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 59000,
        },
        [12153] = {
            description = "Now that you've charged up your war golem, we're going to put all that energy " ..
                "to good use. Activate the golem inside Dun Argol to take control of it.\n\nOur " ..
                "information about Dun Argol's leader, Iron Thane Furyhammer, suggests his bodyguard " ..
                "protects him from all harm.\n\nThat bodyguard is the construct he travels with, called " ..
                "The Anvil. Disable the construct, and his protection will disappear.\n\nThe thane stays " ..
                "in the building at the top of Dun Argol and supervises production from the bottom level.",
            rewardChoices = {{38711, 1}, {39015, 1}, {39044, 1}, {39076, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 118000,
        },
        [12154] = {
            description = "The large hall at the top of Dun Argol houses the power source for the entire " ..
                "area. If you can destroy the power core, it will cripple Dun Argol for some time.\n\nNo " ..
                "power means no golems, no sentries, and no more lightning armaments.\n\nWhen we were " ..
                "sent up here, they told us these explosives were for excavation, but thanks to Iron " ..
                "Thane Furyhammer, the research has been scrapped. We may as well get some use out of " ..
                "them, though. They're the only thing we have on hand capable of destroying the power " ..
                "core.",
            rewardMoney = 59000,
        },
        [12157] = {
            description = "We're lucky we made it this far, <name>. We were ambushed by Scourge as soon " ..
                "as we landed.\n\nOne of our men turned out to be a spy for the Cult of the Damned. " ..
                "Thassarian appears to have more evidence of cultist infiltration. Apparently it goes all " ..
                "the way to the top.\n\nI've sent one of my best couriers to our outpost in western " ..
                "Dragonblight, but he has not yet returned. I fear he may have fallen to the Scourge. " ..
                "Will you go to Dragonblight and search for him? Courier Lanson is his name.",
        },
        [12158] = {
            description = "I've been meaning to send some of our lads to check out Hollowstone Mine. " ..
                "Haven't had a chance to yet -- we've had our hands full between the Horde on the west " ..
                "and the iron dwarves to the east.\n\nIf Dumont sent you, though, the least I can do is " ..
                "point you in the right direction.\n\nYou'll find the mine entrance to the northwest, not " ..
                "far from here. See if you think operations there can be salvaged. We sure could use the " ..
                "additional resources until our mine in Farshire is operational again.",
        },
        [12159] = {
            description = "< Petrov looks deeply disturbed, breathing heavily and shifting his gaze " ..
                "nervously around the mine.>\n\nMy comrades... we must put their souls to rest! I kill " ..
                "them and kill them but.. they just come back!\n\nI've had an idea for a while but I just " ..
                "don't have the heart to do it myself.\n\nMaybe you can do this for me? Take this lantern " ..
                "and use its oil to burn their remains so they never get up again.\n\nI'll answer your " ..
                "questions later. Help my friends first!",
            rewardChoices = {{38735, 1}, {39034, 1}, {39064, 1}, {39099, 1}},
            rewardMoney = 59000,
        },
        [12160] = {
            description = "It worked! It worked! My comrades can finally enjoy their well-earned " ..
                "rest...\n\nI'll stay here and finish the job. We Hollowstone miners always finish the " ..
                "job -- we never give up!\n\nThat's why Arugal made an example of us. We wouldn't fall in " ..
                "line, you see? We wouldn't join his wolfcult!",
        },
        [12161] = {
            description = "Hey there. I overheard what you were saying to the captain and I just want you " ..
                "to know... things aren't that simple in Northrend.\n\nJust because someone's dead it " ..
                "doesn't mean they're out of the picture.\n\nSouthwest of here, near Vordrassil Pass, " ..
                "lives a blind woman who goes by the name Ruuna the Blind. They say she speaks to the " ..
                "dead and has visions of the past and future.\n\nI haven't heard your whole story but it " ..
                "sounds like she'd be right up your alley.",
        },
        [12164] = {
            description = "It is time, then, <name>. Arugal must be defeated.\n\nGet a couple of people " ..
                "you can trust and head for Bloodmoon Isle. It's just off the coast, east of " ..
                "here.\n\nWe'll hit them fast. Take out Arugal's lieutenants -- I'll catch up with you " ..
                "when it's time to take out the monster himself.",
            rewardChoices = {{39168, 1}, {39169, 1}, {39170, 1}, {39171, 1}, {39172, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 177000,
        },
        [12165] = {
            description = "Prospector Rokar has decided to help us. He's concocted a plan to use the iron " ..
                "dwarves' strength against them.\n\nI must admit, our new 'friend' is more insightful " ..
                "than I'd given him credit for. He's correct in that our numbers are too few for a direct " ..
                "attack.\n\nTravel to Dun Argol, in the snowy regions to the southeast, and capture all " ..
                "the parts of their war golem blueprints from the iron rune-smiths there. Bring the " ..
                "assembled blueprint to Rokar and we'll see if his plan has any merit.",
            rewardMoney = 59000,
        },
        [12166] = {
            description = "<race> will you assist me?\n\nThe Scourge have moved into Icemist to the " ..
                "north. Wherever they go, they spread their taint, and the creatures of the land " ..
                "suffer.\n\nTake this vial, which is filled with the liquid fire of Elune from the " ..
                "moonwell. Please, use the liquid to cleanse the corpses of the blighted wildlife that " ..
                "you find.",
            rewardMoney = 50000,
        },
        [12167] = {
            description = "The Anub'ar cultists are indirectly responsible for the plaguing of the " ..
                "beasts, and we must put an end to it!\n\nThe fumes that emit from the cultists' suits " ..
                "seep into everything they come near, poisoning and corrupting their surroundings.\n\nYou " ..
                "must go north to Icemist Village and slay them. Bring back any of their suits that " ..
                "survive your assault and I will see to it that they are properly disposed of.",
            rewardMoney = 50000,
        },
        [12168] = {
            description = "An inscription on the back of the favor reads,\n\n\"To my favorite " ..
                "pupil,\n\nIf you continue to show promise, I will teach you wonders beyond your " ..
                "imaginings.\n\nIf you do not, I will have you destroyed!\n\nAs ever,\n\nHigh Cultist " ..
                "Zangus\"\n\nNo doubt the warden at Stars' Rest will want to see this.",
        },
        [12169] = {
            description = "I have dreamed of Zangus before but without the context that you have " ..
                "discovered, I knew not what it meant. You have brought clarity to the vision that the " ..
                "goddess has bestowed upon me, and now I know that he can be found within the Pit of " ..
                "Narjun to the north.\n\nYou know your target, <name>. If there's to be an end to the " ..
                "suffering of the land, the high cultist must die!",
            rewardChoices = {{37961, 1}, {38003, 1}, {38045, 1}, {38107, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 100000,
        },
        [12170] = {
            description = "The Venture Company abandoned operations shortly after we showed up. Clearly " ..
                "they were afraid of what we were going to do to their greedy little hides.\n\nWith them " ..
                "gone, their logging camps are up for grabs. Our war machine is a hungry beast... without " ..
                "renewing our supplies we won't make it to Icecrown.\n\nUnfortunately the Alliance seems " ..
                "to have the same idea and we must make sure we're the ones that prevail. Head into the " ..
                "logging camp and help us fight the Alliance scum.",
            rewardMoney = 56000,
        },
        [12171] = {
            description = "The list I hold must be delivered to High Commander Halford Wyrmbane. He " ..
                "commands the 7th Legion, stationed at Wintergarde Keep on the eastern borders of " ..
                "Dragonblight.\n\nIf any of the traitors on this list are stationed at Wintergarde... it " ..
                "could be catastrophic.\n\nHurry, <name>. Show the document to Palena Silvercloud here at " ..
                "Stars' Rest and explain the nature of your mission. She will put you on her fastest " ..
                "hippogryph to Wintergarde!",
        },
        [12172] = {
            description = "Welcome, mage.\n\nBy now you must be wondering where Dalaran is and how to get " ..
                "there. I will help you.\n\nBut before I can teach you how to teleport to our great city, " ..
                "you must attune yourself to the ley lines of Northrend. Otherwise, you risk destroying " ..
                "yourself in the process.\n\nTake this attunement crystal and use it in the pit under the " ..
                "surge needle at the Moonrest Gardens to the west. Then you will be ready to learn the " ..
                "spell.",
            rewardMoney = 53000,
        },
        [12173] = {
            description = "Hello, mage.\n\nBy now you must be wondering where Dalaran is and how to get " ..
                "there. I can help you with this if you can survive a simple test.\n\nBefore I teach you " ..
                "how to teleport to our great city, you must attune yourself to the ley lines of " ..
                "Northrend. Otherwise, you will destroy yourself in the process!\n\nTake this attunement " ..
                "crystal and use it in the pit under the surge needle at the Moonrest Gardens to the " ..
                "southwest. Then you will be ready to learn what I have to teach.",
            rewardMoney = 53000,
        },
        [12174] = {
            description = "<Palena hands the missive back to you.>\n\nSnowstorm will take you to " ..
                "Wintergarde, <name>. I guarantee you that it will be the fastest flight you've ever " ..
                "taken. Go now!",
        },
        [12175] = {
            description = "Let me tell you something, mon. When you get put in charge of outfittin' the " ..
                "armies of the Horde, you go through a lot of hides!\n\nConqueror Krenna, the she-wolf " ..
                "runnin' this place, she gave me a tight deadline. If I don't outfit her whole regiment " ..
                "by week's end she's gonna have me wrestling bears in the pit.\n\nHelp me out and I'll " ..
                "pay you top price. I'll be needin' hides from graymist hunters.\n\nYou'll find them all " ..
                "around in pockets to the north, hunting stag. Remember, mon. Top price!",
            rewardChoices = {{38734, 1}, {39033, 1}, {39060, 1}, {39098, 1}},
            rewardMoney = 56000,
        },
        [12176] = {
            description = "Krenna, she be wantin' worg hides for all the outfits. There's not gonna be " ..
                "enough worg hides for her army, though. Not now, not ever.\n\nThose worgs -- they be " ..
                "skinny, mon! Here's what we're gonna do... if you can keep a secret that is.\n\nEast of " ..
                "Voldrune there be grizzly bears as fat as an ogre. Those large hides -- those we can " ..
                "use!\n\nHurry, <brother/sister>. Krenna's not known for her patience.",
            rewardChoices = {{38735, 1}, {39034, 1}, {39064, 1}, {39099, 1}},
        },
        [12177] = {
            description = "Ah, we have a small problem. Grizzly hides... they be brown, mon!\n\nThink... " ..
                "think!\n\nI got it, mon! Is like this: gray is black an' white all mixed up. You get me " ..
                "some coal an' some flour, I'll grind it all up and dust the hides with it. No one will " ..
                "know the better!\n\nBlacksmiths sell coal for smeltin' an' you can get flour from the " ..
                "provisioner.",
        },
        [12178] = {
            description = "This is it, mon. Let's take these hides to Krenna and see if they pass the " ..
                "test.\n\nLet's hope for both our sakes Krenna doesn't notice anything.",
        },
        [12180] = {
            description = "Raegar sent a team of prospectors into Dun Argol to search for artifacts and " ..
                "information about the history of the settlement. Raegar's team never expected Dun Argol " ..
                "to be this heavily populated.\n\nThey're being held captive while the iron dwarves " ..
                "prepare for war. We haven't the men to charge in after them, and Raegar's too busy " ..
                "fantasizing about defeating the irons to be of much help.\n\nIt falls to you, <name>. " ..
                "Any of the irons or their servants could be carrying the keys to the cages holding our " ..
                "men.",
            rewardMoney = 59000,
        },
        [12181] = {
            description = "My, my, how long has it been? How long have we been working on this damned " ..
                "plague? Finally, after an eternity of failure, we are blessed with perfection. This... " ..
                "It doesn't even have a proper name yet! This blight... That's it, BLIGHT! This blight " ..
                "will tear down the very fabric of life!\n\n<Harris hands you a vial.>\n\nNow, find the " ..
                "bat handler, Tobias, and show him the specimen. He'll get you on your way to Venomspite.",
        },
        [12182] = {
            description = "I got a special bat all lined up for you, buddy. Fastest and smoothest ride " ..
                "I've got. He'll take you right to Venomspite - in style.\n\nJust hand that vial over to " ..
                "Chief Plaguebringer Middleton once you land.",
        },
        [12183] = {
            description = "If, as Prospector Varana said, only certain irons are permitted to communicate " ..
                "with this Loken, it'll probably be the overseers who have the privilege.\n\nWe have to " ..
                "get you in there to see what all this is about, but it won't be easy. The first step " ..
                "will be to get a proper uniform for you.\n\nThen, we'll worry about doing your " ..
                "makeup.\n\nFind one of the overseers at Dun Argol, kill him, and bring back his uniform. " ..
                "If you get blood on it, you'll have only yourself to blame.",
            rewardMoney = 59000,
        },
        [12184] = {
            description = "Now that we've got the uniform, we've got to get enough information to " ..
                "complete your camouflage.\n\nRaegar brought along this camera to document the team's " ..
                "finds, but I have a different use in mind. I want you to take it with you to Dun Argol " ..
                "and use it to capture the images of iron dwarves.\n\nOf course, your models aren't going " ..
                "to be a cooperative lot, so you may have to, err... subdue them first. Bring back the " ..
                "camera and the images when you're done.",
            rewardMoney = 59000,
        },
        [12185] = {
            description = "Using the images you've captured, I've created everything you need for your " ..
                "overseer disguise kit. You'll make a fine iron dwarf, if I do say so myself.\n\nTake the " ..
                "kit with you to Dun Argol, use it to disguise yourself, then go to the easternmost " ..
                "building on the broad middle tier of the city.\n\nThere, you should see a pedestal where " ..
                "the thane and overseers receive their orders from this Loken. Activate it while " ..
                "disguised and learn all you can from the communication.",
            rewardChoices = {{38713, 1}, {39017, 1}, {39046, 1}, {39078, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 59000,
        },
        [12188] = {
            description = "The details behind the functionality of the blight are hardly important. All " ..
                "you need to know is that it does the job it was designed to do. I have managed to " ..
                "synthesize a strain of the blight that is inert.\n\n<Middleton uncorks a vial and " ..
                "inhales.>\n\nSee, my body is still, mostly, intact. Now mix this with a reactive agent " ..
                "and we'd all be turned to shapeless piles of goo.\n\nOn the beach south of here you will " ..
                "find pathetic specters of Alliance soldiers past. Slay them and bring me ectoplasmic " ..
                "residue.",
            rewardChoices = {{37963, 1}, {38005, 1}, {38047, 1}, {38109, 1}},
        },
        [12189] = {
            description = "The shipment from New Agamand was to arrive at Venomspite last week and then " ..
                "be delivered to me after some simple field tests. It is a Horde imperative - the last " ..
                "piece of the \"victory puzzle.\"\n\n<Sintar sighs.>\n\nIt is quite disheartening to know " ..
                "that you are surrounded by imbeciles and incompetent boobs!\n\nYou must travel to " ..
                "Venomspite, near the eastern border of Dragonblight. Find that buffoon, Middleton, and " ..
                "let him know that I am waiting on the package.",
        },
        [12190] = {
            description = "Harkor 's gunna drop a gold brick when he sees these choice ingredients. All " ..
                "that be left is gettin' them to him.\n\nHe's camped out on the eastern coast near dem " ..
                "haunted ruins - Drakil'jin, dey be called.\n\nYou'll likely be makin' it there before I " ..
                "can finish up with these corpses... unless, ya think you'd rather try your hand at " ..
                "embalming?",
            rewardMoney = 56000,
        },
        [12195] = {
            description = "A recent hunting expedition brought back more than just game.\n\nThey " ..
                "encountered a wounded dwarf fleeing the iron dwarf stronghold of Dun Argol. He may have " ..
                "information we can use to strike at our ancient enemy, but before he's of any use to us, " ..
                "we must bring down his fever.\n\nThe horns of the silvercoat stags, who roam the nearby " ..
                "forest, have long been used to make healing poultices. If you can bring enough of the " ..
                "horns to me, we'll see if the poultice can bring our 'guest' around.",
            rewardMoney = 59000,
        },
        [12196] = {
            description = "We don't have enough time for me to forge the parts myself, but the foundries " ..
                "over at Dun Argol, to the southeast, are working day and night to churn out golem " ..
                "parts.\n\nI think you should go back there and pick up enough of them for me to make a " ..
                "golem from this blueprint.\n\nThey're probably scattered around any of the buildings " ..
                "where the iron rune-smiths are working.\n\nPlease hurry, <name>. That Tormak looks like " ..
                "he's just waiting for an excuse to carry out his threat!",
            rewardMoney = 59000,
        },
        [12197] = {
            description = "Well, we've got the shell of a golem, but that's not good enough for Tormak. " ..
                "He doesn't realize that these things don't just come together and miraculously start " ..
                "working! We're going to need power cells to animate it.\n\nWhen I was in Dun Argol, I " ..
                "noticed that Rune-Smith Durar and Rune-Smith Kathorn were the ones who manufactured the " ..
                "cells. We'll need one from each to power our golem.\n\nYou should be able to find each " ..
                "rune-smith in his workshop on the central level of Dun Argol.",
            rewardMoney = 59000,
        },
        [12198] = {
            description = "The golem's cells have just enough power to run it at the lowest levels, but " ..
                "it can't power any of its combat systems.\n\nThe good news is that the perimeter of Dun " ..
                "Argol is patrolled by lightning sentries. We should be able to use their power to charge " ..
                "up the golem's weapon systems.\n\nBring the golem with you, take it close to them, it " ..
                "will absorb the power as the sentries die.",
            rewardMoney = 59000,
        },
        [12199] = {
            description = "Now that the golem is fully charged, it can be used against the leader at Dun " ..
                "Argol.\n\nWhen I observed Iron Thane Furyhammer, he was always guarded by a personal " ..
                "golem that shielded him from all harm.\n\nThat construct, called The Anvil, can be " ..
                "disrupted, causing him to drop the shield. Use your golem's EMP ability to do just that. " ..
                "You'll be able to activate and take control of your golem inside Dun Argol.\n\nThe thane " ..
                "is in the main plant at the top and supervises production from the bottom level.",
            rewardChoices = {{38711, 1}, {39015, 1}, {39044, 1}, {39076, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 118000,
        },
        [12200] = {
            description = "With an inert specimen of the blight compound complete and the activating " ..
                "agent in hand there only remains a need for a suitable shell to house the " ..
                "components.\n\nSouthwest of here, on the shores of central Dragonblight, is where you " ..
                "will find the Emerald Dragonshrine. Within the shrine you will find the hardened " ..
                "remnants of a green dragon's tear drop. I don't know the whole story, but apparently " ..
                "they cry a lot right before they die. Go figure.\n\nGo to the Emerald Dragonshrine and " ..
                "gather tears.",
        },
        [12201] = {
            description = "It sounds like this Loken is the mastermind behind the sudden preparations for " ..
                "war on the part of the iron dwarves.\n\nOnly the highest ranking irons are likely to " ..
                "have access to him, so we'll have to make you into an overseer to find out what's going " ..
                "on in there.\n\nI have a plan, for that, but we'll need some supplies.\n\nFind one of " ..
                "the iron rune overseers at Dun Argol, to the southeast, kill him, and bring back his " ..
                "uniform.",
            rewardMoney = 59000,
        },
        [12202] = {
            description = "Now we have to finish the job of making you as repulsive as those iron " ..
                "dwarves.\n\nThe best way to do that is to base your disguise on the ugly mugs of real " ..
                "iron dwarves.\n\nWhen Tormak's hunting party discovered that wayward prospector, they " ..
                "took the camera he carried. Now, I suppose, we'll get the chance to use it.\n\nTake it " ..
                "with you to Dun Argol, kill some iron dwarves, and record their likenesses in this " ..
                "device. Bring it back once you have enough examples.",
            rewardMoney = 59000,
        },
        [12203] = {
            description = "I've created everything else you'll need for your overseer disguise kit. Try " ..
                "not to retch when you put it on. I took pains to make it as true to reality as " ..
                "possible.\n\nTake the kit with you southeast to Dun Argol, use it to disguise yourself, " ..
                "then go to the easternmost building on the broad middle tier of the city.\n\nThere, you " ..
                "should see a pedestal where the thane and overseers receive their orders from this " ..
                "Loken. Activate it while disguised and learn all you can from the communication.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 59000,
        },
        [12204] = {
            description = "The iron dwarves stand as one of the fiercest and most coordinated foes in " ..
                "Northrend. Wherever we have traveled, they have battled us with the name of Loken on " ..
                "their lips.\n\nWe must learn who this Loken is and what he seeks. The locals may be of " ..
                "help.\n\nTo the northeast, at the Redwood Trading Post, a human named Hugh Glass peddles " ..
                "his wares. Further east, at the Ruins of Tethys, you'll find a stone giant named " ..
                "Gavrock. Ask them about this Loken. They've got to know something of use.",
            rewardMoney = 46000,
        },
        [12205] = {
            description = "By order of High Executor Wroth all members of the illegal organization known " ..
                "as the Scarlet Onslaught are to be put to death immediately.\n\nNo quarter is to be " ..
                "offered, and those proceeding to action upon this decree should be aware that any who " ..
                "are captured by the humans will be left to die, or worse!\n\nIn the High Executor's " ..
                "words, \"Paint the snow red with their blood!\"",
            rewardMoney = 50000,
        },
        [12206] = {
            description = "Have you read the wanted poster? What is the high executor " ..
                "thinking?!\n\n<Vicky looks around and continues in hushed tones.>\n\nWe can't very well " ..
                "have those Scarlet Onslaught idiots being raised by their priests, or worse, rising as " ..
                "the Scourge, now can we?\n\nNo, I'm in total agreement with you, we have to do something " ..
                "about the corpses.\n\nI have just the thing. Take this blight that we just created and " ..
                "test it on the prisoner in the cage right here.\n\nNo muss, no fuss, no returning " ..
                "enemies.",
            rewardMoney = 5000,
        },
        [12207] = {
            description = "Long ago, powerful druids planted a tree to the northeast of here.\n\nIt was " ..
                "called Vordrassil and it was to be a world tree. It is not known why, but after the tree " ..
                "was fully grown, the druids decided it needed to be destroyed.\n\nEver since we arrived " ..
                "here, the earth has spoken to me, <name>. Its cries of pain come from the places where " ..
                "Vordrassil's remains fell on the ground.\n\nCorrupting ooze roams those places. Bring me " ..
                "samples of it so we may begin to heal the land.",
            rewardChoices = {{38719, 1}, {39023, 1}, {39052, 1}, {39090, 1}},
        },
        [12208] = {
            description = "Good for nothing wretches!\n\nThey could have had it easy. We extended our " ..
                "hand in peace. All they had to do was give us passage through Drak'Tharon and we'd have " ..
                "let them be.\n\nBut no, the prideful little ice trolls decided that they wanted it " ..
                "rough. Now they'll be destroyed and we'll pass through their precious keep to Zul'Drak " ..
                "anyway.\n\nWe've contracted a gang to deliver us captured trolls. Talk to Samir if you " ..
                "want in on the action. You can find him to the northwest of here, due south of Zeb'Halek.",
            rewardMoney = 14400,
        },
        [12209] = {
            description = "Ah good, new meat. Do you wish to prove yourself, new meat?\n\nThe Scarlet " ..
                "Onslaught, the most zealous and racist of the Scarlet Crusade, are in our backyard to " ..
                "the south. If we're going to fight them, we'll need more armor and weapons than I can " ..
                "make in such a short time.\n\nWhy don't we take theirs?\n\nMore to the point, why don't " ..
                "YOU take theirs?",
            rewardMoney = 50000,
        },
        [12210] = {
            description = "You, <race>! No sense standing around here when there's work to be " ..
                "done!\n\nDrak'Theron Keep is the most direct route to Zul'Drak. We MUST capture it to " ..
                "ensure safe passage for the Alliance. But until we get the numbers to make an assault, " ..
                "we'll have to content ourselves in thinning out the ice trolls and collecting " ..
                "intel.\n\nTo that end, we've conscripted a gang of thugs to capture and deliver live " ..
                "trolls for interrogation. Travel northwest and speak with Samir at Granite Springs. " ..
                "He'll direct you further.",
            rewardMoney = 41000,
        },
        [12211] = {
            description = "I don't understand it. The blight should have worked!\n\nNo sense worrying " ..
                "about it now.\n\n<The apothecary seems relieved for some reason.>\n\nThough it doesn't " ..
                "work on the Onslaught for some strange reason, we still need to keep their priests from " ..
                "raising them.\n\nI have another idea, one that their corpses shouldn't have any " ..
                "protection from.\n\n<name>, take a container of my rats and unleash them upon any " ..
                "Onslaught corpses you come across at New Hearthglen. I starve the vermin, so they should " ..
                "be voracious!",
            rewardChoices = {{37971, 1}, {38014, 1}, {38057, 1}, {38118, 1}},
            rewardMoney = 50000,
        },
        [12212] = {
            description = "G'day, <class>.\n\nThe good lieutenant here says that there's been a Horde " ..
                "raid on our storehouse that's left our food supply dangerously low.\n\nNo doubt we'll " ..
                "make those cretins pay, but first we need to focus our attention on restocking. My men " ..
                "are doing all they can, but we're going to need every able body to contribute if we're " ..
                "to avert a crisis.\n\nYou should have no trouble harvesting venison from the local stag " ..
                "in these parts. Happy hunting!",
            rewardMoney = 56000,
        },
        [12213] = {
            description = "Something... dark... happened to the tree Vordrassil. After the druids decided " ..
                "to destroy it, its hollow remains grew roots deep into the ground.\n\nI want you to go " ..
                "to the three locations to the northeast where the tree's trunk shattered and go as far " ..
                "beneath the ground as you can.\n\nUse this orb once you get there to get an imprint of " ..
                "the energy surrounding the area. This might shed some light on what happened to " ..
                "Vordrassil and why it failed to become a world tree.",
        },
        [12214] = {
            description = "Hello. I am Hansel. Pleased to meet you, <sir/ma'am>.\n\nThe high executor " ..
                "came to me and said, 'Hansel, I want you to get us new mounts.'\n\nWhere does he think " ..
                "dreadsteeds come from? The ground?\n\n<whispering> Actually, they do if you can find a " ..
                "horse graveyard.\n\nBut we don't have one of those, so what we need you to do is go " ..
                "south to New Hearthglen, kill the knights, take their riding crops, and steal their " ..
                "warhorses.\n\nRide the horse back to me here and hand over the reins, if you would.",
            rewardMoney = 50000,
        },
        [12215] = {
            description = "As if we didn't have enough to concern ourselves with....\n\nWith the present " ..
                "food crisis, we find ourselves competing for food with the local worgs. The situation is " ..
                "becoming more dire, and I fear that if we don't address the issue immediately we'll soon " ..
                "find ourselves with nothing to hunt.\n\nScour the forest, <race>. Kill any graymist you " ..
                "find. Recent reports have sighted a concentration of them on the other side of the river " ..
                "west of here.",
            rewardMoney = 44000,
        },
        [12216] = {
            description = "We've all been working hard and it's beginning to pay off, but we're still far " ..
                "from our goal. We need much more meat than we have and it's growing clear that the local " ..
                "stag population won't be enough by itself.\n\nI'm afraid we need you to turn your " ..
                "attention to more dangerous prey - the grizzlies that give this region its name. They're " ..
                "plentiful, and they're well fed from the abundant fish that swim in these streams.\n\nBe " ..
                "safe, <class>!",
            rewardMoney = 56000,
        },
        [12217] = {
            description = "Well, <name>, we've determined how the Horde was able to locate our hidden " ..
                "stores of food.\n\nIt turns out that they were binding their sight to the unsuspecting " ..
                "eagles that soar above the trees here. Using eagle vision, they were able to effectively " ..
                "spy on our every action.\n\nBy order of the lieutenant, we've got to hunt down these " ..
                "majestic birds in order to thwart our enemy.",
            rewardMoney = 56000,
        },
        [12218] = {
            description = "Before I can ship you off to Doctor Malefious with the good news, you will " ..
                "have to run a simple field test of the blight with the modifications I have made.\n\nThe " ..
                "hungering dead stream out from what remains of Old Wintergarde. Commandeer a vehicle " ..
                "from the east gate and drive it northeast through Vengeance Pass until you reach the " ..
                "twin towers at the southeastern edge of Wintergarde. Drop the blight bomb on the undead " ..
                "that cover the area. Report back to me with the results!",
        },
        [12219] = {
            description = "My ancestors once planted a tree in the middle of the Grizzly Hills.\n\nIt was " ..
                "called Vordrassil and it was to become a world tree.\n\nFor reasons long forgotten, " ..
                "after the tree was fully grown, they decided it needed to be destroyed. Its giant trunk " ..
                "splintered at three locations in the area to the north.\n\nWhere the tree touched the " ..
                "ground, foul ooze began to crawl the earth. Bring me slime samples so I can begin my " ..
                "work and the earth can be healed.",
            rewardChoices = {{38719, 1}, {39023, 1}, {39052, 1}, {39090, 1}},
        },
        [12220] = {
            description = "When the tree Vordrassil fell, its hollow remains grew roots deep into the " ..
                "ground.\n\nI want you to go north of here to the three locations where the trunk " ..
                "shattered and go as far beneath the ground as you can. You'll find them west of " ..
                "Grizzlemaw.\n\nUse this orb once you get there to get an imprint of the energy " ..
                "surrounding the area. If we're to heal the land, we must first find out what caused " ..
                "Vordrassil to fail as a world tree all those years ago.",
        },
        [12222] = {
            description = "Even as we attempt to fight off the Horde, the Dragonflayer tribe musters in " ..
                "their village of Voldrune, near the coast to the south.\n\nThe most powerful warriors in " ..
                "the village are granted flame-imbued talismans that give them the ability to control " ..
                "powerful, savage proto-drakes. If we can gain control of one of these drakes, perhaps we " ..
                "can use it to neutralize the threat posed by Voldrune.\n\nThe Dragonflayer flamebinders " ..
                "create the talismans and imbue them with power. Kill them and take the talismans.",
            rewardMoney = 56000,
        },
        [12223] = {
            description = "There's a flurry of activity down in Voldrune village to the south. Thane " ..
                "Torvald Eriksson and his huscarls are preparing for war. With most of our men in the " ..
                "field dealing with the Horde's treachery, Amberpine will be vulnerable.\n\nTravel to " ..
                "Voldrune, which is near the southern coast, and show those Dragonflayers we're no soft " ..
                "target.\n\nSlay as many of the huscarls as you can find. Make them think twice about " ..
                "taking advantage of our conflict with the Horde.",
            rewardMoney = 56000,
        },
        [12224] = {
            description = "You have done well, <brother/sister>. All that you have faced, you have done " ..
                "as a champion of the Horde. The Scourged Anub'ar of Azjol-Nerub, crushed under your " ..
                "foot! The taunka, brave and powerful new members of the Horde, because of you! Our " ..
                "super-weapon against the Scourge, tested and perfected by you!\n\nThe time has come, the " ..
                "moment is now - our elite soldiers at the Wrathgate need you. The son of Saurfang awaits " ..
                "your arrival at the Kor'kron Vanguard. Go now, northeast to the Wrathgate.",
            rewardChoices = {{38540, 1}, {38541, 1}, {38542, 1}, {38543, 1}},
        },
        [12225] = {
            description = "Your stomach growls as the pungent smell of hearty nuts draws your attention " ..
                "to the bucket of seeds.\n\nSome thoughtful soul has obviously left these complimentary " ..
                "morsels here to rejuvenate weary visitors. Grateful, you take the remaining few and " ..
                "devour them.\n\nThe seeds do not disappoint. Finding yourself hungry for more, you set " ..
                "out to discover their origins....",
        },
        [12226] = {
            description = "We must act quickly, <race>! We can't risk letting those precious seeds become " ..
                "fully digested. They need to come out, NOW.\n\nForage up some blackroot from the " ..
                "riverbank just west of here and I'll make you a purgative that should get things " ..
                "moving.\n\nHurry now! And remember, you brought this upon yourself....",
            rewardMoney = 53000,
        },
        [12227] = {
            description = "Alright, <race>. Here's the juice.\n\nIt works immediately, so don't use it " ..
                "until you're safely inside the outhouse.\n\nNow go get me those seeds!",
            rewardChoices = {{38746, 1}, {38745, 1}, {38747, 1}},
        },
        [12229] = {
            description = "Not long ago we sent an expedition to the east, where it was attacked by " ..
                "crazed furbolgs. One of the survivors described slaying one of them and its body " ..
                "expelling a dark slimy substance.\n\nFor thousands of years, the furbolgs in this region " ..
                "have been peaceful. It is possible that there is a link to the furbolgs' behavior and " ..
                "the dark energy we were able to detect earlier.\n\nBring me samples of the furbolgs' " ..
                "blood. You will find them to the east in the Rage Fang Shrine and the Heart's Blood " ..
                "Shrine.",
            rewardChoices = {{38726, 1}, {39025, 1}, {39053, 1}, {39091, 1}},
        },
        [12230] = {
            description = "I'm tasked with the destruction of the Scarlet Onslaught's ballistae. " ..
                "Unfortunately, the apothecaries and I are at odds on the use of our resources, so I've " ..
                "nothing to destroy them with!\n\nTo the northeast are the Carrion Fields. The Scourge " ..
                "siegesmiths there at their forge and meat wagons are demolition masters.\n\nLuckily for " ..
                "us, they also leave their bombs lying about.\n\nI want you to retrieve them for me, off " ..
                "of the ground or the siegesmiths, I don't care which.",
            rewardMoney = 50000,
        },
        [12231] = {
            description = "It is possible that the furbolg of Grizzly Hills have the same taint that " ..
                "plagued Vordrassil. They've been involved in a deadly tribal war recently after years of " ..
                "peaceful coexistence.\n\nThe shrines that they guard to the east are home to Ursoc's " ..
                "offspring.\n\nIf the corruption has affected the furbolg, it is possible that because of " ..
                "their lineage, Kodian and Orsonn have remained unharmed.\n\nIf that's the case, find " ..
                "them and listen to what they have to say.",
        },
        [12232] = {
            description = "At last, our chance to strike at their siege engines! Don't flub it.\n\nI " ..
                "kid.\n\nA little.\n\n<class>, bombard New Hearthglen's ballistae with these " ..
                "bombs.\n\nWe'll show the Royal Apothecary Society how it's done old style. No " ..
                "concoctions required!",
            rewardChoices = {{37949, 1}, {37992, 1}, {38284, 1}},
            rewardMoney = 50000,
        },
        [12234] = {
            description = "I need to know what New Hearthglen is up to.\n\nI want you to steal their " ..
                "orders of the day so that I can find that out.\n\nHead south and in their abbey, in " ..
                "their barracks, and on their beach, find those daily plans!\n\nJust in case you're " ..
                "confused, the barracks is the large building right next to the smithy.",
            rewardMoney = 50000,
        },
        [12235] = {
            description = "Lord Fordragon has led a crushing assault against Arthas at the Wrathgate. In " ..
                "response to this affront, Arthas has sent Naxxramas down upon us. While Kel'Thuzad hides " ..
                "in the floating citadel, his ground commander, Thel'zan, lays siege to Wintergarde Keep. " ..
                "The lower village is already lost and any chance of extracting survivors from the ruins " ..
                "diminishes by the minute.\n\nWe must act quickly! Report to Gryphon Commander Urik at " ..
                "the gryphon station at once! He'll get you up to speed.\n\nLeave me!",
        },
        [12236] = {
            description = "The time has come, <name>. Now we will learn whether our efforts will " ..
                "accomplish what we need or nothing at all.\n\nTake these ashes and seek the furbolg that " ..
                "Kodian told you about, Tur Ragepaw, near Ursoc's Den. You will find the den to the north " ..
                "of Grizzlemaw.\n\nConvince Tur to aid you, for you will need all the help you can " ..
                "get.\n\nOnce you've defeated the bear god, use these ashes over his body.\n\nEven if his " ..
                "worldly form is destroyed, his spirit must be saved.",
            rewardChoices = {{39174, 1}, {39175, 1}, {39176, 1}, {39177, 1}, {39178, 1}},
            rewardItems = {{39173, 1}, {199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 177000,
        },
        [12237] = {
            description = "With this whistle you can call down a Wintergarde gryphon. Mount the creature " ..
                "and head towards the ruins of Wintergarde Village, now known as the Carrion Fields, " ..
                "southeast of here. Once at the fields, keep your eyes peeled for helpless Wintergarde " ..
                "villagers. When you spot one, fly low and use the gryphon to pick them up. Return the " ..
                "rescued villager here, to the gryphon station.\n\nThere are Scourge all over the place " ..
                "so you'll need to keep your wits about you, hero. Good luck!",
        },
        [12239] = {
            description = "I have a spy within the ranks of the Scarlet Onslaught. I need you to deliver " ..
                "these daily orders to her so that she can plan the next phase of our assault.\n\nShe " ..
                "goes by the name of Agent Skully and she's under a magical guise to appear as the " ..
                "Onslaught's cemetery caretaker.\n\nHere, take these orders to her, and then do as she " ..
                "asks. You'll find the graveyard on the side of the abbey.",
            rewardMoney = 50000,
        },
        [12240] = {
            description = "I received a few barrels of termites from my sister at the Bulwark back home " ..
                "in the last shipment. I think they're going to come in handy for something I have in " ..
                "mind for you.\n\nThe lumbermill operations at New Hearthglen are problematic for us, but " ..
                "so far we haven't been able to get anyone in there to take out their foreman.\n\nI think " ..
                "that if you were to unleash these termites on his precious woodworks, he'd be sure to " ..
                "come running.\n\nReady to take him out, <class>?",
            rewardMoney = 50000,
        },
        [12241] = {
            description = "The furbolgs' work must be undone, <name>. The best of intentions do not count " ..
                "for much when the result is tainted by such strong a corruption.\n\nThe sapling must be " ..
                "destroyed, for it is the source of this dark influence. Take this torch and use it to " ..
                "set fire to the corrupted sapling and bring me its ashes.\n\nOnce cleansed, by fire, I " ..
                "will use what power I can to remove the taint from them. You will need the ashes to " ..
                "purify Ursoc from the evil power that holds sway over him.",
        },
        [12242] = {
            description = "We must make sure that Vordrassil is never regrown. The furbolg must have " ..
                "harvested its seed.\n\nGo to Grizzlemaw, in central Grizzly Hills, and obtain all the " ..
                "seeds that you can find. I will make sure they're properly destroyed.",
            rewardChoices = {{38757, 1}, {38753, 1}, {38743, 1}},
        },
        [12243] = {
            description = "I have another mission for you.\n\nI was able to repurpose some of the blight " ..
                "to concoct my world-famous burning water. I want you to take it and set the sails of the " ..
                "Sinner's Folly ablaze!\n\nUse it from the dock. Once the sails are on fire, the " ..
                "deckhands will be busy putting them out, and you'll slip belowdecks to 'retrieve' the " ..
                "captain's rutters.\n\nYou'll find the ship on Crusader's Landing, below and south of New " ..
                "Hearthglen. Look for the captain's quarters on the first lower deck, behind the stairs.",
            rewardChoices = {{37950, 1}, {37993, 1}, {38037, 1}, {38068, 1}},
            rewardMoney = 50000,
        },
        [12244] = {
            description = "Listen, pal. Why don't ya roll up your sleeves and grab a wrench? There's work " ..
                "to be done! They need these shredders refurbished and sent down to Venture Bay, and they " ..
                "need it done yesterday....\n\nNo wrench? Well what good are ya then? May as well go down " ..
                "with the rest of the lugheads and play with the Horde!\n\nWhile you're there, see if you " ..
                "can drive some of those broken-down shredders up here for repairs. Be careful! They're " ..
                "in pretty bad shape.",
            rewardItems = {{37500, 1}},
            rewardMoney = 56000,
        },
        [12245] = {
            description = "We have more fools for you to kill.\n\nMy agents tell me that several of our " ..
                "good citizens have seen fit to fall into the hands of the Scarlet Onslaught.\n\nThis " ..
                "will not do.\n\nGo back to New Hearthglen and eliminate Deathguard Schneider, Senior " ..
                "Scrivener Kinnedius, Engineer Burke and Chancellor Amai.\n\nFrom what I hear, they're " ..
                "spread out throughout the area. No doubt they are being kept in cages awaiting " ..
                "torture.\n\nSpeak with them and then kill them!",
            rewardMoney = 50000,
        },
        [12246] = {
            description = "The furbolgs that live east of here are more aggressive and bestial than the " ..
                "ones we're used to. Our forces have squared off with them more than once, and the " ..
                "survivors always speak of a dark, slimy substance dripping from their corpses.\n\nTheir " ..
                "condition could be linked with the contaminants we found on Vordrassil's " ..
                "remains.\n\nBring me samples of the furbolgs' blood. You will find them in the Rage Fang " ..
                "Shrine and the Heart's Blood Shrine, far to the east.",
            rewardChoices = {{38726, 1}, {39025, 1}, {39053, 1}, {39091, 1}},
        },
        [12247] = {
            description = "The furbolgs of Grizzly Hills carry with them a corruption of some kind, that " ..
                "is for sure. Tribal war has broken out amongst them after years of peaceful " ..
                "coexistence.\n\nWhat remains to be seen is whether the bears they worship as gods have " ..
                "also been tainted.\n\nUrsoc's two children, Orsonn and Kodian, dwell in the Heart's " ..
                "Blood Shrine and the Rage Fang Shrine, south and southeast of Grizzlemaw.\n\nSee if they " ..
                "will speak to you regarding what has happened here.",
        },
        [12248] = {
            description = "The druids of old seem to have had good reasons for destroying Vordrassil. We " ..
                "cannot let the furbolgs regrow it.\n\nOn the other hand, saving Ursoc's spirit hinges on " ..
                "the magic contained by the sapling.\n\nTake this torch and use it to burn the tree. You " ..
                "will find it in the middle of Grizzlemaw, inside Vordrassil's old trunk.\n\nBring me " ..
                "Vordrassil's ashes. It is my hope that once purified by fire, we may use its magic to " ..
                "cleanse Ursoc's spirit of its dark taint.",
        },
        [12249] = {
            description = "It is time, <name>. Take these ashes and look for the furbolg that Kodian " ..
                "spoke of. If he went to seek Ursoc, he will be near his den, north of Grizzlemaw.\n\nYou " ..
                "will need his help. You won't be able to defeat Ursoc alone.\n\nOnce you've defeated " ..
                "Ursoc, use these ashes to purify his spirit. Only then will we know whether our efforts " ..
                "have been in vain or not.",
            rewardChoices = {{39174, 1}, {39175, 1}, {39176, 1}, {39177, 1}, {39178, 1}},
            rewardItems = {{39173, 1}, {199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 177000,
        },
        [12250] = {
            description = "We cannot allow Vordrassil to grow again. If the furbolg regrew it once, they " ..
                "can do it again.\n\nGo to Grizzlemaw, in central Grizzly Hills, and obtain Vordrassil's " ..
                "seeds. I will make sure they're properly disposed of.",
            rewardChoices = {{38757, 1}, {38753, 1}, {38743, 1}},
        },
        [12251] = {
            description = "Return to High Commander Halford Wyrmbane at once, <name>. Let him know that " ..
                "your mission was a success and that the few remaining villagers that were rescued are " ..
                "back to work.",
            rewardChoices = {{37956, 1}, {37998, 1}, {38041, 1}, {38102, 1}},
        },
        [12252] = {
            description = "Enough! I want you to put an end to the torture of my people!\n\nThe " ..
                "Onslaught's torturer, Alphonse, has been bleeding information out of everyone that gets " ..
                "caught by those fiends! I need to know what they know.\n\nMy sources tell me that he has " ..
                "set up shop in the basement of their barracks, which is right next to the " ..
                "smithy.\n\nI'll loan you my personal branding iron to see to it that the job is done " ..
                "right.\n\nFind him and get that information.",
            rewardChoices = {{37953, 1}, {37995, 1}, {38039, 1}, {38100, 1}},
            rewardMoney = 50000,
        },
        [12253] = {
            description = "Just down this path here is Wintergarde's town square. Once a hive of activity " ..
                "for the citizens of Wintergarde, now a warzone, filled with murderous geists hell-bent " ..
                "on vengeance towards the living.\n\nIn the buildings surrounding the town square are " ..
                "trapped villagers that must be rescued! I ask much of you, now, <name>, but you are the " ..
                "only soldier I can spare. Free our people. Take this path down into town square and " ..
                "enter those houses. Kill anything that gets in your way! Return to me should you survive.",
        },
        [12254] = {
            description = "These plans indicate something imminent is being planned.\n\nBut first, " ..
                "there's the matter of this strange protection that the Onslaught forces have. If " ..
                "Venomspite is to deal with them once and for all, we must find out who's behind it and " ..
                "eliminate them.\n\nI've noticed that the bishop in the chapel on the far side of New " ..
                "Hearthglen, across from the lumbermill, has stepped up his blessing of the troops. Kill " ..
                "him and steal his prayer book.\n\nMaybe it will give us a clue.",
            rewardMoney = 50000,
        },
        [12255] = {
            description = "Now that you've captured the flame-imbued talismans and weakened Voldrune's " ..
                "defenses, we can strike at its leader, Thane Torvald Eriksson.\n\nThe thane's favorite " ..
                "mount is an unruly proto-drake he calls Flamebringer. It is kept bound in chains in the " ..
                "western part of Voldrune, but with the talismans, you should be able to control it long " ..
                "enough to use it against the thane.\n\nOnce you have Flamebringer under your control, " ..
                "search the tops of the towers of Voldrune for the thane and show him no mercy.",
            rewardChoices = {{38712, 1}, {39016, 1}, {39045, 1}, {39077, 1}, {38749, 1}},
            rewardMoney = 56000,
        },
        [12256] = {
            description = "Even as the Alliance cowards attack our positions, the Dragonflayer vrykul " ..
                "outpost of Voldrune, to the southeast, prepares for war. The vrykul are far from the " ..
                "strongest enemy we face here, but we must eliminate them before they can truly threaten " ..
                "us.\n\nTheir most powerful warriors are permitted to ride half-trained proto-drakes into " ..
                "battle. To control the beasts, their flamebinders create powerful talismans. You'll need " ..
                "to slay them and take the talismans if our plan is to work.",
            rewardMoney = 56000,
        },
        [12257] = {
            description = "Preparations for war are underway in the vrykul village of Voldrune to the " ..
                "southeast. Voldrune's thane cannot field a large army, but with our forces spread thin, " ..
                "we are still at risk.\n\nWe cannot risk giving the thane and his men an opportunity to " ..
                "attack, so we must take the battle to them. If you are truly a <class> of the Horde, you " ..
                "will relish the chance to demonstrate our strength.\n\nCut down the huscarls and prove " ..
                "to this Dragonflayer clan that the Horde is not to be trifled with!",
            rewardMoney = 56000,
        },
        [12258] = {
            description = "The town square, down this path, is overrun with the undead citizens of " ..
                "Wintergarde! Our own crypt provides a seemingly endless supply of soldiers for the " ..
                "Scourge to throw at us. Take no pity on them, though, <name>. While they were once " ..
                "mortal, capable of compassion and thought, they are now ravaging undead with only one " ..
                "purpose: our destruction.\n\nVenture forth to the town square and deliver the vengeful " ..
                "geists to their maker. Give them peace.",
            rewardChoices = {{37954, 1}, {37996, 1}, {38040, 1}, {38101, 1}},
        },
        [12259] = {
            description = "With the flame-imbued talismans, we can finally challenge the thane.\n\nHis " ..
                "favorite mount is a ferocious proto-drake called Flamebringer. It is kept bound in " ..
                "chains in the western part of Voldrune, but with the power of the talismans, you should " ..
                "be able to bend it to your will and use it against the thane.\n\nOnce you have " ..
                "Flamebringer under your control, search the tops of the towers of Voldrune for the thane " ..
                "and use Flamebringer to destroy him.",
            rewardChoices = {{38712, 1}, {39016, 1}, {39045, 1}, {39077, 1}, {38749, 1}},
            rewardMoney = 56000,
        },
        [12260] = {
            description = "You may wonder how I can maintain this guise; I use a magic mirror that was " ..
                "loaned to me by the spy mistress.\n\nIt only has so much power in it, but I think " ..
                "there's enough for the both of us. Here, take it. I want you to use it to impersonate " ..
                "one of the Onslaught raven priests.\n\nBe quick about it... I have no idea how long my " ..
                "glamour will last while you have the mirror.\n\nRealize that you won't immediately be " ..
                "perfectly disguised, so don't count on it being foolproof until I've had a chance to " ..
                "help you.",
            rewardMoney = 50000,
        },
        [12261] = {
            description = "They're drawing power from the bones of my dead brothers...\n\nI have no love " ..
                "for the cult, but I'm baffled by their audacity. There will be no mercy shown for " ..
                "them... not that I ever would have anyway.\n\nEnsure that they have no place to flee " ..
                "when the slaughter starts. Place a destructive ward at the end of the path leading out " ..
                "of the shrine... where the road starts to give way to snow. Defend it until it is fully " ..
                "charged.",
            rewardMoney = 56000,
        },
        [12262] = {
            description = "We will spare no one.\n\nOutside, lowly necrolytes and their skeletal servants " ..
                "shame my land with their presence. Slaughter them all.",
            rewardMoney = 56000,
        },
        [12263] = {
            description = "The Cult of the Damned has not come just to extract power from dead dragons. I " ..
                "suspect I know what they are up to, but I need you to prove me correct.\n\nI will grant " ..
                "you the guise of this dead necrolyte. Proceed to the back of the cave and confirm their " ..
                "intentions for being in this sacred place. I will watch through your eyes.\n\nBe " ..
                "cautious <name>, any damage done to you is likely to break the fragile illusion.",
            rewardMoney = 56000,
        },
        [12264] = {
            description = "The cave beyond was swarming with Cult atrocities. There is only one way to " ..
                "deal with such creatures... you know what to do.",
            rewardMoney = 56000,
        },
        [12265] = {
            description = "I sensed a large accumulation of magic in the runes that we witnessed when you " ..
                "were scouting the cave. I will not have you toy with extracting the magic... often the " ..
                "most straight forward solution is the most effective one.\n\nDestroy the runes... stamp " ..
                "them out and ensure that the Cult will not have access to whatever power that they've " ..
                "accumulated there.",
            rewardMoney = 56000,
        },
        [12266] = {
            description = "You can leave now, <race>.\n\nGo tell Nalice she missed out on a good slaughter.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 5600,
        },
        [12267] = {
            description = "With the cult's ranks thinned and some of their power stripped, it's time to " ..
                "strike at the source of the corruption.\n\nRothin the Decaying is resurrecting black " ..
                "dragons as magmawyrms in the back of the cave. Go to the summoning chamber and cleanse " ..
                "the remaining bones in the only way that will ensure that they will never be toyed with " ..
                "again... with flame.\n\nBurning the bones will surely gain Rothin's attention, see to it " ..
                "that he is destroyed as well.\n\nThe magic in this vial should see the task done.",
            rewardChoices = {{37944, 1}, {37988, 1}, {38095, 1}, {38032, 1}},
            rewardMoney = 118000,
        },
        [12268] = {
            description = "Ack! This thing's a mess!\n\nGoblin engineering leaves a great deal to be " ..
                "desired, believe you me. Just look at this! It's a wonder it ever worked to begin " ..
                "with.\n\nGive me a hand, will ya? To get this even close to operable specifications I'll " ..
                "need to replace a few cogs, sprockets, and springs. You should have no trouble finding " ..
                "them down around the sawmill.",
            rewardMoney = 56000,
        },
        [12269] = {
            description = "That blasted necropolis blindsided us! In the wake of its destruction " ..
                "Wintergarde Mine was lost. Worse yet, Kel'Thuzad's acolytes have raised the slain miners " ..
                "as Scourge and are using them to supply their siegesmiths with materials from our " ..
                "mine!\n\nThe supply line must be halted and our lost brothers must be put to " ..
                "rest.\n\nTravel to Wintergarde Mine, northeast of here in the Carrion Fields, and " ..
                "destroy the risen miners. Return to me with their miner cards so that I may put their " ..
                "passing in our registry.",
        },
        [12270] = {
            description = "Read my lips, <class> - I need those shredders! Just as important - I need to " ..
                "keep them out of the hands of the Alliance!\n\nThey've been refurbishing the shredders " ..
                "and using them against our brothers in Venture Bay. Now we're going to give them a taste " ..
                "of their own medicine!\n\nYou see a shredder out there, grab it! You see one of the " ..
                "Alliance scum on one, kill 'em and then grab it! Once you have one, drive it back here " ..
                "to me and we'll get to work on it.\n\nDismissed!",
            rewardItems = {{37500, 1}},
            rewardMoney = 56000,
        },
        [12271] = {
            description = "A rod drops from Alphonse's dead hand. There are pulsing magical runes along " ..
                "its length.\n\nCould this be how he was getting his confessions?\n\nBetter let the high " ..
                "executor have a look at it.",
            rewardMoney = 25000,
        },
        [12272] = {
            description = "Hours before the Naxxramas invasion, one of the miners stumbled upon a dark " ..
                "ore that was oozing a viscous fluid. In the chaos that occurred during the evacuation of " ..
                "the mine, we lost the samples taken from the alien node. Now the Scourge prospects the " ..
                "ore for use in their machines of death.\n\nYou must get back to Wintergarde Mine, due " ..
                "northeast of here in the Carrion Fields, and recover the strange ore. It is imperative " ..
                "to our mission's success!",
        },
        [12273] = {
            description = "It's time for us to utterly demoralize the Onslaught forces!\n\nI want you to " ..
                "take the rod and use it on four of their leaders: Commander Jordan upstairs at the " ..
                "barracks, Lead Cannoneer Zierhut down the southeast ramp overlooking the beach, " ..
                "Blacksmith Goodman at the smithy, and Stable Master Mercer at the stables.\n\nPlace them " ..
                "under the rod's compulsion, concentrate on making them denounce the Onslaught, and then " ..
                "kill them!",
            rewardChoices = {{37968, 1}, {38011, 1}, {38054, 1}, {38115, 1}},
            rewardMoney = 106000,
        },
        [12274] = {
            description = "We need more information from the high abbot, and now that we have the visage " ..
                "of one of the raven priests, I think we can get you close to talk with " ..
                "him.\n\nUnfortunately, we need to separate him from his bodyguards or you'll never get " ..
                "any information out of him.\n\n<The agent leans on her shovel and thinks a moment.>\n\nI " ..
                "think I've got it! While in disguise, go to the top of the abbey and ring the bell. That " ..
                "should bring the abbot's bodyguards running and you can then head down to speak with him.",
            rewardMoney = 53000,
        },
        [12275] = {
            description = "Quarterflash recently requisitioned my group for a specialist that he could " ..
                "send on a reconnaissance mission to the Wintergarde Mine. To that end, I sent him " ..
                "Slinkin, my demolitionist. I foolishly thought that he could close off that pit of " ..
                "damnation after his mission for Quarterflash was complete, securing another victory for " ..
                "us against the Scourge.\n\nAn entire day has now passed and Slinkin has not returned. I " ..
                "want answers! Speak with Siege Engineer Quarterflash and track down my missing agent!",
        },
        [12276] = {
            description = "While I have not heard from Slinkin or know what fate has befallen him, " ..
                "perhaps I can assist in finding him.\n\n<Quarterflash holds up a tiny mechanical " ..
                "toy.>\n\nThis is not a toy, newfound compatriot. It is, in fact, my latest mechanical " ..
                "creation. The machine was created with the sole purpose of finding that which has been " ..
                "lost. These are unfortunate circumstances, but the machine is your best chance at " ..
                "finding Slinkin.\n\nWhen you are ready to begin your search, place the bot on the ground " ..
                "next to me.",
        },
        [12277] = {
            description = "If there is good in your heart and your conscience is clear, read on.\n\nIn " ..
                "this mine, near the foreman's scaffold, rests a hefty cargo of dynamite. Go there and " ..
                "pick up several bundles of the explosive and make your way towards the entrance of the " ..
                "mine. Once there, set the dynamite and blow up the entrance. Remember to do this for the " ..
                "upper and lower entry points of Wintergarde Mine.\n\nYou must leave nothing to chance. " ..
                "The evil that exists here must never be allowed out. Light guide you.",
            rewardChoices = {{38002, 1}, {38106, 1}, {38293, 1}, {37960, 1}},
        },
        [12279] = {
            description = "Thank goodness you're back, Limpy! I worried that Griselda and I were going to " ..
                "be all alone.\n\nI'm cooking up some food here for us, but Griselda'll have none of " ..
                "it.\n\nShe's fond of the fish that live off the coast of the Eastwind Shore, to the " ..
                "east. Can't stand them myself, but she's always been a picky eater. Six good-sized fish " ..
                "ought to keep her happy for a while.\n\nNow, run... err... limp along, Joe. Wouldn't " ..
                "want to keep the girl waiting, would ya?",
            rewardMoney = 59000,
        },
        [12280] = {
            description = "Twenty shredders by noon tomorrow!\n\nWho makes these schedules, anyway? No " ..
                "one who ever put one of these garbage cans back together, that's who....\n\nIf I'm going " ..
                "to hit my quota, I'll need a hand. Help me out and I'll share my commission with you - " ..
                "fair enough?\n\nI need cogs, sprockets and springs. They're littered across the ground " ..
                "down by the shredders.",
            rewardMoney = 56000,
        },
        [12281] = {
            description = "We must take solace in the fact that Slinkin's death, while tragic, was for " ..
                "the greater good. His discovery coupled with your heroics in the mine and the samples " ..
                "you returned brings us one step closer to understanding the Scourge war machine.\n\nTake " ..
                "this package to High Commander Halford Wyrmbane. It holds a sample of the strange ore " ..
                "and my analysis.",
        },
        [12282] = {
            description = "The memories of the past haunt this land, <name>. I hear the cries of the " ..
                "fallen echo across Northrend - calling to me.\n\nArthas left a terrible imprint on " ..
                "everything he touched. Only wither and decay remains in his wake. It is important, then, " ..
                "for us to study the past so that we may better know our enemy. Perhaps untold truths " ..
                "shall surface that could help in our campaign.\n\nFirst, you must recover my scrying orb " ..
                "from the town hall, <name>. Exit this tower and turn left down the path to reach the " ..
                "town square.",
            rewardChoices = {{37938, 1}, {38025, 1}, {38086, 1}, {38070, 1}},
        },
        [12283] = {
            description = "We have to figure out what's going on here. We need the general's " ..
                "diary!\n\nI'm pretty sure that you'll find it on her nightstand upstairs at her house. " ..
                "It's the one next to church, across from the stables and the lumbermill.\n\nOnce you " ..
                "acquire the diary, take it to the high executor back at Venomspite.\n\nYou'll have to do " ..
                "this the old-fashioned way; the power of the mirror is low and there's only enough left " ..
                "for me.\n\n<The agent smirks.>",
            rewardMoney = 50000,
        },
        [12284] = {
            description = "We've suffered heavy casualties here, <race>.\n\nThe only good news is that " ..
                "we've given as much as we've taken. I've requested more troops, but the bulk of our " ..
                "forces are bogged down in Venture Bay. It looks like we're on our own for now.\n\nNo " ..
                "matter how bad it gets, we MUST stand our ground! The precious resources of this region " ..
                "are essential to the Horde's long-term success in Northrend.\n\nWe've got to keep the " ..
                "Alliance on their heels until help arrives. Get out there and give 'em something to " ..
                "think about.",
            rewardMoney = 56000,
        },
        [12285] = {
            description = "Their attack is imminent, <class>. I need you to get in there and sever the " ..
                "head of the Scarlet Onslaught, literally!\n\nIt's not going to be easy... Abbendis is " ..
                "sure to be surrounded by a great many of her men.\n\nBring back her head and I'll see to " ..
                "it that you're properly rewarded for saving Venomspite.\n\nFail and don't even bother to " ..
                "return!",
            rewardChoices = {{38534, 1}, {38535, 1}, {38536, 1}, {38537, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 106000,
        },
        [12287] = {
            description = "I have gazed upon the orb and seen the path that you must walk, " ..
                "<name>.\n\nMany years ago an atrocity was committed upon the shores of Dragonblight. The " ..
                "act itself remains shrouded in darkness, but I am certain that your destiny lies south, " ..
                "amidst the ruins of the Forgotten Shore.\n\nTake the road southeast through the ravaged " ..
                "town square. Follow the trail until you arrive at Dawn's Reach. You will meet an old " ..
                "friend of mine there known as Orik Trueheart. He will be expecting you.",
        },
        [12288] = {
            description = "You there, <class>! Help me!\n\nWe're losing valuable lives! There are simply " ..
                "too many wounded for me to tend to alone. If we can't get our soldiers healed we could " ..
                "be run out of Grizzly Hills altogether!\n\nTake this tourniquet and use it on the " ..
                "wounded down on the battlefield.\n\nHurry, <name>! They're dyyying!!",
            rewardMoney = 56000,
        },
        [12289] = {
            description = "It is a dark day for the Alliance. Many good men lay dead or dying here. Our " ..
                "only consolation is that they fought well and brought down many of the enemy with " ..
                "them.\n\nWith the bulk of our forces committed to Venture Bay we stand alone to weather " ..
                "this storm. The resources in this region are vital to the Alliance and may well make the " ..
                "difference in our struggle against the Horde. We must not fail!\n\nGo, <name>. Strike at " ..
                "them while they lick their wounds. Avenge your fallen brothers and keep our hopes alive!",
            rewardMoney = 56000,
        },
        [12290] = {
            description = "The spirits of the damned haunt the coast. In life they were brave and noble " ..
                "soldiers of the Alliance, but in death they are cursed - bound to this world until the " ..
                "end of days. We must discover the source of their anguish if we are to free them!\n\nTo " ..
                "the southeast, on the Eldritch Heights, you will find a rare herb known as murkweed. It " ..
                "is murkweed that I will use to concoct an elixir that will allow you temporary entry " ..
                "into the world of the forgotten. Go now and gather the weed.",
        },
        [12291] = {
            description = "The toxins in the murkweed elixir will render you unconscious. So powerful is " ..
                "the effect of the murkweed that even your spirit will be fooled, allowing you to " ..
                "temporarily enter the world of the dead.\n\nOnce a spirit, you must speak to the ghostly " ..
                "denizens of the Forgotten Shore. Seek out the cause of their anguish and return to " ..
                "me.\n\nRemember, <name>, these spirits were once Alliance soldiers. Treat them with " ..
                "respect, honor and dignity.\n\nNow, with elixir in hand, venture south to the Forgotten " ..
                "Shore.",
        },
        [12292] = {
            description = "We've reached a deadlock with the Horde in Grizzly Hills. Our forces are just " ..
                "about evenly matched and all signs so far have pointed to a stalemate.\n\nUntil this " ..
                "morning, that is. The local trappers have requested our help. Apparently the Horde took " ..
                "something that belongs to them... a relic of some sort.\n\nWe get this back for them and " ..
                "they'll give us the edge we need. Head to the Evergreen Trading Post, west of Conquest " ..
                "Hold and look for a cedar chest.",
            rewardChoices = {{38732, 1}, {38759, 1}, {39030, 1}, {39058, 1}, {39096, 1}},
        },
        [12293] = {
            description = "We have what the trappers want. Now it's up to us to sign them up with our " ..
                "side.\n\nTake the chest to a trapper named Ivan at the Aspen Grove Post, just north of " ..
                "here.\n\nIf all goes well, we'll have local woodsmen serving as scouts for the king's " ..
                "army in no time.",
        },
        [12294] = {
            description = "Very well, <name>. Your people kept their end of the bargain.\n\nTell Dumont " ..
                "that we'll honor the deal.",
        },
        [12295] = {
            description = "We'd been trying to negotiate with the trappers for weeks, but we'd gotten " ..
                "nowhere until you found that blasted chest of theirs.\n\nThis should be good news to our " ..
                "envoy in Silverbrook. We sent Ducal there about a week ago and his last letter indicated " ..
                "he'd been making little progress.\n\nGo to Silverbrook and aid him in his diplomatic " ..
                "efforts. Take the roads heading northwest of here and you should find it after crossing " ..
                "a couple of bridges.",
        },
        [12296] = {
            description = "Oh, the carnage....\n\nI've been through many battles, <class>, and this one " ..
                "was more brutal than any I've seen. Our fight with the Horde has become more intense " ..
                "than ever. It's them or us here in Northrend - life or death.\n\nIf we are to survive " ..
                "here another day we'll need to mend our wounded. There are too many for me to rescue " ..
                "alone.\n\nI've prepared special bandages that will enable you to assist me. Take one and " ..
                "tend to those who have not yet succumbed to their wounds.",
            rewardMoney = 56000,
        },
        [12297] = {
            description = "The list I hold must be delivered to High Commander Halford Wyrmbane. He " ..
                "commands the 7th Legion, stationed at Wintergarde Keep on the eastern borders of the " ..
                "Great Dragonblight.\n\nIf any of the traitors on this list are stationed at " ..
                "Wintergarde... it could be catastrophic.\n\nHurry, <name>. Show the document to Greer " ..
                "Orehammer here at Westguard Keep and explain the nature of your mission. He'll put you " ..
                "on his fastest gryphon to Wintergarde!",
        },
        [12298] = {
            description = "<Greer hands the missive back to you.>\n\nSkysong will take you to " ..
                "Wintergarde, <name>. I guarantee you that it will be the fastest flight you've ever " ..
                "taken. Go now!",
        },
        [12299] = {
            description = "It's good to meet you. Let us celebrate our pact by partaking in some good old " ..
                "fashioned Horde-killing.\n\nYou'll find marauders from Conquest Hold just outside our " ..
                "town, west of here. Why don't you head out there and hunt them like the filthy animals " ..
                "they are?\n\nLet's see if our new allies can back all their talk with some action.",
            rewardChoices = {{38762, 1}, {38760, 1}, {38761, 1}},
            rewardMoney = 112000,
        },
        [12300] = {
            description = "Alright, friend. You've done us a favor or two, but that's not the true test " ..
                "of a person's courage.\n\nAround these parts, you're not a real hunter unless you wear " ..
                "your prey's skin.\n\n< Sergei unsheathes his skinning knife and hands it to you.>\n\nThe " ..
                "leader of those motherless orcs attacking our town is called Bonesnap; you'll find him " ..
                "at a camp further northwest.\n\nThat's right. You're going to skin the monster.",
        },
        [12301] = {
            description = "Zelig gave this crystal ball to me years ago with specific instruction on its " ..
                "use. For five years - whenever I would feel anger, anxiety, or sorrow over the events " ..
                "that transpired here - I was to focus my thoughts upon the orb.\n\nI now understand why " ..
                "Zelig gave this crystal to me.\n\nTake my crystalline orb to the Forgotten Shore. Find " ..
                "the ruins of my old base on the upper reaches of the beach and place the orb in the " ..
                "center of town. Let the forgotten see the world through my heart and soul.",
        },
        [12302] = {
            description = "Thanks for helping me, <name>. My name's Sasha. Listen, I have to get the hell " ..
                "out of here.\n\nThe people that sent you here... my people... they've changed. They're " ..
                "not good people anymore... and they want to turn you into one of... one of " ..
                "them.\n\nThis... 'test' they sent you on is just the beginning.\n\nHead to the " ..
                "northwestern end of Silverbrook. You'll find something of interest to you.\n\nGood " ..
                "luck... and trust no one.",
        },
        [12303] = {
            description = "<The quartermaster lowers his voice and whispers to you.>\n\n<class>, I need " ..
                "your help; our coffers are empty. The Kor'kron Vanguard at the Wrath Gate has taken all " ..
                "of our coin for the fight there.\n\nBut, I've heard whispers that there's treasure to be " ..
                "had amongst the wrecks on the Forgotten Shore to the southeast.\n\nWe have to do " ..
                "something soon, or we won't be able to continue the fight against the Scarlet Onslaught. " ..
                "War isn't cheap, you know!",
            rewardChoices = {{37986, 1}, {38030, 1}, {38181, 1}, {38071, 1}, {38036, 1}},
            rewardMoney = 50000,
        },
        [12304] = {
            description = "It's time for Venomspite to expand!\n\nWe'll take care of the Onslaught in due " ..
                "time, but I want you to spearhead our efforts on the Forgotten Shore. The property value " ..
                "has outstanding potential and just look at that view!\n\nUnfortunately, there's an " ..
                "infestation of human ghosts, shipwrecked crews and the like who haven't quite realized " ..
                "that they're dead.\n\nClear the beach and the waters off the shore, and maybe you and I " ..
                "will talk about building a cozy, new mausoleum down there soon.",
            rewardMoney = 50000,
        },
        [12305] = {
            description = "You have honored me and honored the memory of hundreds of Alliance veterans, " ..
                "<name>. Zelig was wise in sending you here. Please return to him and give him my thanks. " ..
                "He will be happy to hear of the events that transpired at the Forgotten Shore.\n\nI do " ..
                "not have the gift of foresight like Zelig, but I am certain that great things await you, " ..
                "friend.\n\nFarewell.",
            rewardChoices = {{37986, 1}, {38030, 1}, {38181, 1}, {38071, 1}, {38036, 1}},
        },
        [12307] = {
            description = "Have you heard of the wolfsbane plant? It is a horrible weed... it destroys " ..
                "our farmable crops.\n\nWe spent all of last week cutting them down, but the roots are " ..
                "beginning to sprout again.\n\nIt might not seem like an urgent matter, but a resurgence " ..
                "of the plant could be a real... disaster. Do you think you could help us by uprooting " ..
                "them where you find them near the village?",
            rewardChoices = {{38756, 1}, {39062, 1}, {39105, 1}, {38754, 1}},
            rewardMoney = 44000,
        },
        [12308] = {
            description = "You... you're not one of them? Quick! Let me out!\n\nWe have to get to " ..
                "Amberpine Lodge immediately! Once Lieutenant Dumont finds out who these people really " ..
                "are, this town will be reduced to rubble!",
            rewardChoices = {{38733, 1}, {39031, 1}, {39059, 1}, {39097, 1}, {38750, 1}},
        },
        [12309] = {
            description = "After the Scourge breached the south wall, I ordered Cavalier Durkon to " ..
                "investigate the town crypt. Moments ago I was handed his report.\n\nThe undead that " ..
                "plague us are coming from two sources: the ruins of Wintergarde, now a breeding ground " ..
                "for Scourge, and our very own town crypt! Amidst the chaos and confusion the Scourge " ..
                "managed to get a necrolord inside the crypt.\n\nIn his message, Durkon requested " ..
                "assistance. You will find him and help him, <name>. The crypt is on the western border " ..
                "of the town square.",
        },
        [12310] = {
            description = "Our response must be immediate. Decisive. We must teach these savages not to " ..
                "cross us.\n\nOur scouts have located what's left of the Silverbrook trappers... you " ..
                "know, the ones you didn't get to douse in flames. Apparently they're blockading the road " ..
                "to the southeast... perhaps they're trying to box us in.\n\nHead to the Forest's Edge " ..
                "post and take care of them. Their leader's reported to be a man named Vladek... make " ..
                "sure he's dealt with.",
            rewardMoney = 56000,
        },
        [12311] = {
            description = "Held within the cold stone walls of this crypt are the remains of the nobles " ..
                "and dignitaries that died in Northrend. At its very core now sits a necrolord who raises " ..
                "the corpses as servants of the Scourge.\n\nYou must make your way to the bottom of the " ..
                "Wintergarde Crypt and kill Necrolord Amarion. Only then will the assault from within " ..
                "cease!\n\nAnd <name>, be on the lookout for any information that might be laying about " ..
                "inside the room where Amarion resides.",
            rewardChoices = {{37953, 1}, {37995, 1}, {38039, 1}, {38100, 1}},
        },
        [12312] = {
            description = "Scrawled across the flesh-bound chapters of this tome are strange symbols and " ..
                "shapes that seem to have been scraped into the pages with a blade. You have no idea what " ..
                "is written, but you are certain that whatever it is, it must be important.\n\nDeliver " ..
                "the tome to Cavalier Durkon standing guard topside at Wintergarde Crypt.",
        },
        [12314] = {
            description = "The Horde's forces are poised to break through our lines and complete their " ..
                "conquest of Venture Bay if we do not act. The Horde's forces in the port are commanded " ..
                "by Captain Zorna, near the ship on the far side of the bay.\n\nIf you can defeat her, " ..
                "the Horde's offensive will falter and we can seize the chance to capture the port. " ..
                "Beware, <name>, for Zorna is a fierce fighter. It may take several people to defeat her, " ..
                "or if you have access to a repaired shredder, you might try using it to your advantage.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 56000,
        },
        [12315] = {
            description = "With every advance, our men are met by fresh Alliance reinforcements. It's " ..
                "almost as though their commander anticipates my every move!\n\nThe time has come for " ..
                "good Captain Brightwater to meet his end. He commands his troops from aboard an Alliance " ..
                "destroyer at the far end of the bay.\n\nThis will be no easy fight, <name>. Take along a " ..
                "couple of trusted friends, or if you have a key to one of those repaired shredders, use " ..
                "it to disembowel Brightwater! Either way, he must fall!",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 56000,
        },
        [12316] = {
            description = "We cannot permit the Horde to control Venture Bay. The port is essential to " ..
                "our operations in Grizzly Hills and beyond.\n\nCaptain Stoutmantle has taken the rest of " ..
                "the Westfall Brigade east in search of a passage through the mountains, so we'll have no " ..
                "reinforcements.\n\nGo into the field, <name>, and kill the Conquest Hold berserkers the " ..
                "Horde has sent against us. Cut them down until none remain standing. The Alliance must " ..
                "have this port!",
            rewardMoney = 56000,
        },
        [12317] = {
            description = "This wretched Westfall Brigade is proving a tougher opponent than we'd " ..
                "thought. Though few in number, they fight well and bravely, but we cannot afford to wait " ..
                "them out.\n\nConqueror Krenna's orders were to capture the port quickly. You must break " ..
                "the stalemate, <name>. Find the enemy's marines and slaughter them until the resistance " ..
                "ceases. Only then will we be able to claim ownership of the port.\n\nGo quickly. We " ..
                "don't want to keep Conqueror Krenna waiting.",
            rewardMoney = 56000,
        },
        [12319] = {
            description = "What can it be, <name>? That was certainly no ordinary curse that the blasted " ..
                "lich put on you!\n\n<Durkon flips through the grisly pages of the tome.>\n\nI don't even " ..
                "know if I'm looking at it the right way. We must find out what information is held " ..
                "within this tome!\n\n<Durkon hands the book back to you.>\n\nThe High Commander will " ..
                "know what to do. Take the flesh-bound tome to him and tell him exactly what happened " ..
                "here.",
        },
        [12320] = {
            description = "Take the book and follow the path leading up to the barracks. Once inside the " ..
                "barracks take the staircase down to the prison. At the prison you will find Inquisitor " ..
                "Hallard and our mayor, Godfrey. I believe Godfrey might be the missing piece of this " ..
                "puzzle and Hallard the man to put it all together.\n\nGo now!",
        },
        [12321] = {
            description = "Godfrey Goodard, once a righteous man and mayor of Wintergarde, is now an " ..
                "agent of the Scourge. His transformation from man to undying ghoul has taken place " ..
                "slowly, over time. He hears the call of the Lich King now and lives only to serve his " ..
                "master.\n\nBut as with all Scourge, Godfrey knows the language of death and with proper " ..
                "motivation, will tell us what we need to know about the tome.\n\nOnce you hear what you " ..
                "need to hear, return to the High Commander at the front lines. I'll clean up here as " ..
                "needed.",
            rewardChoices = {{37950, 1}, {37993, 1}, {38037, 1}, {38068, 1}},
        },
        [12323] = {
            description = "There are still pockets of cowardly Venture Company men holed up in some of " ..
                "the buildings at the center of Venture Bay. I need every man I can spare out there " ..
                "fighting against the Horde, but we can't allow those Venture Company stragglers to camp " ..
                "out in those buildings, either.\n\nMaybe we can \"convince\" them to make for their " ..
                "ship. Take this smoke bomb and use it to smoke out the stragglers from their places in " ..
                "the bunkhouse, sawmill, or stables. Don't get too close, though; they probably bite.",
            rewardMoney = 56000,
        },
        [12324] = {
            description = "Not only is this port infested with sniveling Alliance cowards, but to make " ..
                "matters worse, there are still Venture Company employees holed up in some of the " ..
                "buildings. They're not worth the time it takes to kill and I can't spare the warriors " ..
                "anyway.\n\nMaybe we can \"convince\" them to make for their ship. Take this smoke bomb " ..
                "and use it to smoke out the stragglers from their places in the bunkhouse, sawmill, or " ..
                "stables. Don't get too close, though; there's no telling what diseases they're carrying.",
            rewardMoney = 56000,
        },
        [12325] = {
            description = "You have done much to advance our efforts against the Scourge, <name>. In " ..
                "fact, the morale of all those who have come into contact with you soars! Such is your " ..
                "influence over the soldiers and citizenry of Wintergarde, ally.\n\nAnd because of you we " ..
                "are now prepared to go on the offensive! You are to report to Duke August Foehammer, " ..
                "across the Carrion Fields at Thorson's Post, east of here. Gryphon Commander Urik at the " ..
                "gryphon station has prepared a special gryphon to drop you behind enemy lines. Go now!",
        },
        [12326] = {
            description = "This is a seek and destroy mission. You'll be driving a tank into the Carrion " ..
                "Fields to dismantle Scourge plague wagons. With the tank comes a crew of three 7th " ..
                "Legion soldiers. All must survive if this mission is to succeed!\n\nYou'll need to get " ..
                "in close to a plague wagon to unleash your engineer. Let them do their deed and move on " ..
                "to the next one. When the field is clear of plague wagons, head to the mausoleum in " ..
                "front of the ruined keep and drop off the rest of your crew. Meet with Ambo Cash inside.",
            rewardChoices = {{37949, 1}, {37992, 1}, {38284, 1}},
        },
        [12327] = {
            description = "Ah, you seek a vision of the past. You're a wise <race>.\n\nEvery time someone " ..
                "drops by for a reading, they seem to always ask about the future. When you get to be my " ..
                "age, you learn that scrying the past, more often than not, is more useful.\n\nDrink this " ..
                "potion and peer into my crystal ball. Let us see what knowledge we can obtain.",
        },
        [12328] = {
            description = "I will not charge you gold for my services, for I can foresee that your " ..
                "actions are necessary and much hinges on what you learn today.\n\nI will, however, ask " ..
                "you to collect a reagent for me. Obtain gossamer dust from the fern feeder moths " ..
                "northeast of here. Do this and I will prepare a potion that will take you to the time " ..
                "and place where the events took place that you need to witness.",
            rewardChoices = {{38727, 1}, {39026, 1}, {39054, 1}, {39092, 1}},
        },
        [12329] = {
            description = "There are two types of people in this world, <name>. Those who believe in " ..
                "coincidence and those who don't.\n\nOn the day I lost my eyesight I was given the gift " ..
                "of clairvoyance. I suppose you can guess what sort of person I am.\n\nEarlier today, a " ..
                "young woman named Sasha was granted the same vision you were. You will want to talk to " ..
                "her.\n\nYou'll find her directly east of here at the White Pine Trading Post, on the way " ..
                "to Solstice Village.",
        },
        [12330] = {
            description = "My sister is here somewhere, and I can't seem to get this monster to " ..
                "talk.\n\nHe doesn't seem to care about his own well-being, but I've an idea. I knew " ..
                "Anatoly's wife, Tatjana, from before the wolfcult arrived -- she was a " ..
                "horse-handler.\n\nTake this tranquillizer dart. Bring her back alive, we're going to " ..
                "need her if we're to have any leverage with Anatoly.\n\nI will help you find the person " ..
                "behind all this once we save my sister.",
            rewardChoices = {{38744, 1}, {38752, 1}, {38748, 1}},
        },
        [12372] = {
            description = "Emboldened by the overabundance of magic now flowing through the Azure " ..
                "Dragonshrine, the blue dragonflight has dared to attack Wyrmrest Temple itself!\n\nI ask " ..
                "that you ride one of our defenders into battle to slay their dragons and drakes, and to " ..
                "attack the eruption of ley line energies at the dragonshrine itself in order to " ..
                "destabilize it.\n\nOutside on the east and west terraces are wyrmrest defenders. Speak " ..
                "with one to ride it into battle.\n\nWithout your help, <name>, we will surely lose.",
            rewardMoney = 56000,
        },
        [12411] = {
            description = "Please, <name>. I know it is Arugal you're after. I swear on my father's " ..
                "memory I will help you take him down.\n\nBut I must beg you... Anya is completely " ..
                "innocent, we cannot leave her with these savages.\n\nHelp me rescue my sister and you'll " ..
                "have me at your side when you face Arugal.\n\nI know the den Anatoly spoke of. We'll " ..
                "find it on the other side of this hill. Let's go, my sister's in danger.",
        },
        [12412] = {
            description = "If there is one thing I can get through your head, let it be this: the " ..
                "Alliance will be crushed in the Grizzly Hills.\n\nThere is far too much lumber, ore, " ..
                "game and strategic territory for us to give up on any single battlefront here.\n\nSo far " ..
                "we've been successful... but there's something that could tip the scales in our enemy's " ..
                "favor.\n\nFar to the east of here, at the Forest Edge's Post, local trappers seek to " ..
                "join the Alliance. Slaughter them before they have the chance to do so.",
            rewardChoices = {{38732, 1}, {38759, 1}, {39030, 1}, {39058, 1}, {39096, 1}},
        },
        [12413] = {
            description = "A few hours ago, the trappers were nothing but peasants threatening to add " ..
                "their number to the Alliance's.\n\nNow they've become something else... an uncertainty. " ..
                "I do not like uncertainties. Go to the hills outside their main town in northern Grizzly " ..
                "Hills, Silverbrook, and help my men crush them.",
            rewardChoices = {{38733, 1}, {39031, 1}, {39059, 1}, {39097, 1}, {38750, 1}},
        },
        [12414] = {
            description = "Cap'n Stoutmantle left most of our calvary... cavlary... uh, horsemen at the " ..
                "fight for Venture Bay.\n\nWe chose a good place to put the camp 'cause there are tons of " ..
                "highland mustangs running around near here and in the Boulder Hills to the northeast. " ..
                "The Cap'n put me in charge of capturing some of 'em.\n\nWill you help? I've got a stick " ..
                "and some string, and there are loads of wild carrots growing near the camp. Pick the " ..
                "carrots and use them with the stick to lure in the mustang, then ride it back here.",
            rewardMoney = 59000,
        },
        [12415] = {
            description = "The Alliance's 'Westfall Brigade' is camped far to the north, near Thor Modan. " ..
                "They have foolishly divided their forces to contest our control of Venture Bay, and they " ..
                "have been left without cavalry.\n\nThey're now trying to capture and tame the wild " ..
                "highland mustangs that roam the area around the Westfall Brigade Encampment and Boulder " ..
                "Hills. We must stop them before they're able to replace their lost mounts. Take this and " ..
                "throw it near the horses to drive them away.",
            rewardMoney = 59000,
        },
        [12416] = {
            description = "The Scourge have overrun the shrine. The shrine's keeper, Dahlia Suntouch, is " ..
                "nowhere to be found. The red wyrms that fell in the shrine's defense now beset us in the " ..
                "form of twisted skeletal emberwyrms. The situation is dire, <race>.\n\nCaptain Iskandar " ..
                "leads a group of your kind in stemming the flow of the Scourge out of the shrine.\n\nGo " ..
                "to his aid... but please stay behind his men. The flow of Scourge is endless and I don't " ..
                "want to lose you in one of those scarred canyons.",
            rewardMoney = 56000,
        },
        [12417] = {
            description = "I have another task that needs attention. I have brothers who are falling in " ..
                "the battle overhead and if we do not act quickly, they will only bolster the emberwyrm " ..
                "ranks.\n\nGet into the shrine through one of the other passes to the south or north... " ..
                "the Scourge presence should be lighter there.\n\nSearch the shrine for ruby acorns that " ..
                "have fallen from the tree and plant them near the bodies of my fallen brood. Through " ..
                "this, they can give new life... a proud fate for any of my kind.",
            rewardMoney = 56000,
        },
        [12418] = {
            description = "I have one final task for you, <race>... one that should turn the tide of this " ..
                "fight.\n\nReturn to the shrine and kill the necromancers that are fueling this " ..
                "onslaught. With them dead, we should be able to beat these forces back and eventually " ..
                "retake the shrine.\n\nI also need you to find the source of the corruption under the " ..
                "shrine and put an end to it.\n\nI know I have asked a lot of you, but if you do this for " ..
                "me, we will win this battle.",
            rewardChoices = {{37962, 1}, {38004, 1}, {38046, 1}, {38108, 1}},
            rewardMoney = 118000,
        },
        [12419] = {
            description = "As you pick up the brooch, its faint glow brightens slightly.\n\nKrasus will " ..
                "want to know of Dahlia's fate. Take the brooch to him at Wyrmrest.",
            rewardMoney = 15000,
        },
        [12422] = {
            description = "Listen, <name>. I need you to act with discretion and speed.\n\nOne of " ..
                "Krenna's top sergeants has captured a trapper outcast outside of Silverbrook. Now, if " ..
                "things turn out the way they usually do, the prisoner is going to be executed before the " ..
                "day is over.\n\nWe can't let that happen. You see, the prisoner matches the description " ..
                "of Mikhail's older daughter in his diary.\n\nIf we set her loose and follow her closely, " ..
                "she'll lead us to whoever's controlling the trappers. Take this letter to her.",
        },
        [12423] = {
            description = "From what you can gather, this journal was written by a denizen of Silverbrook " ..
                "named Mikhail.\n\nIt is written in some variant of the common human tongue. Perhaps you " ..
                "should bring this back to Conqueror Krenna.",
        },
        [12424] = {
            description = "This book is written in the pig-tongue the humans use. It needs to be burned " ..
                "immediately.\n\nHand it to my sister Gorgonna and do not waste my time.",
        },
        [12425] = {
            description = "This trapper business has the potential to be more important than we've " ..
                "accounted for.\n\nIf they're not with the Alliance, there's a good chance they're with " ..
                "the Scourge, which could mean trouble.\n\nOur previous efforts might've paid off, " ..
                "though. We spotted our former captive meeting with a fortune teller of some sort before " ..
                "we lost track of her.\n\nI'm almost certain now that she will take us to their leader if " ..
                "we can find her again. Find Ruuna the Blind and see what you can find out.",
        },
        [12427] = {
            description = "So you're interested in the fights, eh? Well, Krenna has outlawed pit-fighting " ..
                "for all enlisted combatants. But you, my friend, are technically a free agent and are " ..
                "not included in this prohibition.\n\nNice loophole, eh?\n\nAnyway, if you're interested " ..
                "I can start you off with something easy, a measly bear. I'll even let you bring friends " ..
                "along!",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 112000,
        },
        [12428] = {
            description = "You're not bad. Not bad at all.\n\nThink you can take a furbolg? What about " ..
                "one of those extra-large crazed Northrend furbolgs?\n\nGood, good. Get your crew " ..
                "together, and head to the ring. Let's give these folks a show... maybe we can earn some " ..
                "more coin while we're at it.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 168000,
        },
        [12429] = {
            description = "It's nice to have a real fighter around these parts... we'd only had prisoners " ..
                "and caged beasts for the past few weeks. The people get bored, ya know?\n\nAnyhow, your " ..
                "next challenge is a genuine iron golem stolen from the depths of Thor Modan... think you " ..
                "can swing it?",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 168000,
        },
        [12430] = {
            description = "I'm gonna shoot straight with ya, kid. This next contender's a " ..
                "murderer.\n\nLiterally.\n\nHe was to be executed last week, but he strangled the hangman " ..
                "with his left hand, so Krenna's guards sort of let me have him.\n\nFeel free to pass on " ..
                "this one. I wouldn't blame ya.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 177000,
        },
        [12431] = {
            description = "You must've really upset Krenna. She and Gorgonna have had a spat and you're " ..
                "wanted in the pit immediately.\n\nThere are some wild rumors that it's a fight to the " ..
                "death! That would be bad news for you, but great news for our business venture!\n\nAt " ..
                "any rate, you can't run away from fate... best get in there on the quick and get it over " ..
                "with.",
            rewardChoices = {{39179, 1}, {39180, 1}, {39181, 1}, {39182, 1}, {39183, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 177000,
        },
        [12432] = {
            description = "You there, <race>! Get your lousy carcass over here!\n\nThe Alliance have a " ..
                "shipment of lumber all ready for transport just northeast of here. Since getting our " ..
                "hands on that wood is out of the question, there's only one thing to do - destroy " ..
                "it!\n\nThe goblin at the end of the dock here has some torpedoes all ready to go. He's " ..
                "got all the fuel for them on the docked goblin ship to the north.\n\nGet some fuel, then " ..
                "commandeer one of the torpedoes and ride it into their ship.\n\nDismissed!",
            rewardMoney = 56000,
        },
        [12433] = {
            description = "Gah! Not again. Another blown gasket....\n\nEvery time one of these goes, " ..
                "lubricant gums up all of the gears. Without solvent, it takes hours to clean.\n\nTell ya " ..
                "what, <race>. There's some fancy rocket fuel on the Venture Company barge in the dock " ..
                "there - element 115 I think they call it. That stuff makes for a great solvent.\n\nGet " ..
                "me one of those and I'll make it worth your trouble.",
            rewardMoney = 56000,
        },
        [12435] = {
            description = "I abhor the loss of life... any life. But I will not stand idly by and allow " ..
                "Malygos to kill us and defile the temple!\n\nI have appointed Lord Devrestrasz as the " ..
                "commander of Wyrmrest's defenses.\n\nSpeak with Torastrasza to ride a drake down to " ..
                "him.\n\nPlease lend him your aid, <name>. Your involvement with the defense of Wyrmrest " ..
                "will be critical to us prevailing against the blue dragonflight.",
        },
        [12436] = {
            description = "Hail, <class>. You'll find that here at Conquest Hold, we buy and sell what " ..
                "Krenna wants us to buy and sell... at the price that Krenna wants us to buy and " ..
                "sell.\n\nAll this is stifling business. I'm hoping to make a little bit of coin on the " ..
                "side and feed our grunts at the same time. Why don't you go hunt down some stag and " ..
                "bring me the venison?\n\nThey're numerous in the area, so bring me only the best meat.",
        },
        [12437] = {
            description = "Listen, <name>. This battle is as much over resources as tactical " ..
                "supremacy.\n\nI have a mission that could turn the tide in our struggle against the " ..
                "Horde here.\n\nThere are torpedoes at the end of the dock that we can use to take down " ..
                "the Horde's lumber ship to the northwest.\n\nYou'll need to get some of the fuel that's " ..
                "stored on the docked goblin ship just north of here, then ride one of the torpedoes into " ..
                "their transport!",
            rewardMoney = 56000,
        },
        [12438] = {
            description = "Posted by: Illusia Lune\n\nThe Scourge flesh giant known as Kreug Oathbreaker " ..
                "was responsible for the deaths of my husband, children and my dear friends, the " ..
                "Whisperveils. Those brave enough to take on this bounty will find Kreug in the " ..
                "southeastern reaches of the Carrion Fields.\n\nI demand justice! Kill Kreug " ..
                "Oathbreaker!\n\nIn the event that Kreug is slain, I have pooled money and items together " ..
                "and given them to Highlord Leoric Von Zeldig to give out as a reward.\n\nPlease " ..
                "vindicate us!",
            rewardChoices = {{37957, 1}, {37999, 1}, {38103, 1}, {38042, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 112000,
        },
        [12439] = {
            description = "Another force threatens to destroy all that we have worked for, <name>. You " ..
                "must head westward to Stars' Rest. Archmage Modera has sensed a great disturbance in the " ..
                "magical ley lines of our world that must be dealt with immediately!\n\nGo now, <name>! " ..
                "Speak to Rodney Wells at the gryphon station here in Wintergarde and let him know the " ..
                "nature of your mission. He will place you on his fastest gryphon to deliver you to " ..
                "Stars' Rest. Speak with Archmage Modera when you arrive.",
        },
        [12440] = {
            description = "When you are ready I will place you on my fastest gryphon to Stars' Rest. Once " ..
                "you get there, find and speak with Archmage Modera.\n\nGood luck, ally!",
        },
        [12441] = {
            description = "Posted by: Drolfy\n\nWhile out in the Eldritch Heights with my cousins, " ..
                "Skrotee and Brote, a vicious band of wolvar from the Bloodpaw tribe attacked us. We " ..
                "attempted to flee, but I fear they got Skrotee and Brote.\n\nI demand retribution! Is " ..
                "there someone brave enough to venture to the southeastern reaches of Dragonblight, to " ..
                "the Eldritch Heights, and kill High Shaman Bloodpaw and his cronies?\n\nI have given a " ..
                "hefty sum of gold to Highlord Leoric Von Zeldig to disperse to anyone that claims this " ..
                "bounty!",
            rewardChoices = {{38131, 1}, {38132, 1}, {38169, 1}, {38170, 1}, {38171, 1}, {38172, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 112000,
        },
        [12442] = {
            description = "Posted by: Highlord Leoric Von Zeldig\n\nUpon the northeastern path from " ..
                "Wintergarde a battalion of 7th Legion were ambushed and slain by Onslaught Commander " ..
                "Iustus and an army of mindless Scarlet Onslaught zealots. Such cold and calculated " ..
                "actions must be met with force!\n\nWintergarde demands justice! Seek out Onslaught " ..
                "Commander Iustus at Onslaught Base Camp to the northeast and end his miserable " ..
                "existence.\n\nI will hand out the reward for this bounty to any who would dare take up " ..
                "the task!",
            rewardChoices = {{38054, 1}, {38115, 1}, {38528, 1}, {38529, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 112000,
        },
        [12443] = {
            description = "Gah! Not again. Another blown gasket....\n\nEvery time one of these goes, " ..
                "lubricant gums up all of the gears. Without solvent, it takes hours to clean.\n\nTell ya " ..
                "what, <race>. There's some fancy rocket fuel on the Venture Company barge in the dock " ..
                "there - element 115 I think they call it. That stuff makes for a great solvent.\n\nGet " ..
                "me one of those and I'll make it worth your trouble.",
            rewardMoney = 56000,
        },
        [12444] = {
            description = "The Venture Company's on its way out of Grizzly Hills. They used to run " ..
                "logging operations here, but things got a little too dangerous for them.\n\nTheir " ..
                "abandoned sites are up for grabs and we sure as hell can't let the Horde get their hands " ..
                "on them.\n\nThe Blackriver Logging Camp is the smallest of the three logging sites in " ..
                "this zone, but we still need it. Do your part and fend off the Horde forces. Any lumber " ..
                "they get here will be made into weapons to be used against us elsewhere.",
            rewardMoney = 56000,
        },
        [12447] = {
            description = "The Scourge come. Korialstrasz calls upon his allies in a futile attempt to " ..
                "save their Ruby Dragonshrine, but it seems the good graces of the red flight don't " ..
                "extend to saving the shrines of the other flights.\n\nSurprised? I'm not.\n\nThere is " ..
                "another of my brood who has left to clear our Obsidian Dragonshrine of the undead vermin " ..
                "that now infest it. All it would take to prove yourself more noble and righteous than " ..
                "Alexstrasza herself is a quick jaunt over there and a few swings of a blade.\n\nI'm " ..
                "amused.",
            rewardMoney = 5600,
        },
        [12448] = {
            description = "The Scourge have overrun the shrine. The shrine's keeper, Dahlia Suntouch, is " ..
                "nowhere to be found. The red wyrms that fell in the shrine's defense now beset us in the " ..
                "form of twisted skeletal emberwyrms. The situation is dire, <race>.\n\nCaptain Drayzen " ..
                "leads a group of your kind in stemming the flow of the Scourge out of the shrine.\n\nGo " ..
                "to his aid... but please stay behind his men. The flow of Scourge is endless and I don't " ..
                "want to lose you in one of those scarred canyons.",
            rewardMoney = 56000,
        },
        [12449] = {
            description = "I have another task that needs attention. I have brothers who are falling in " ..
                "the battle overhead and if we do not act quickly, they will only bolster the emberwyrm " ..
                "ranks.\n\nGet into the shrine through the pass in the south... the Scourge presence " ..
                "should be lighter there.\n\nSearch the shrine for ruby acorns that have fallen from the " ..
                "tree and plant them near the bodies of my fallen brood. Through this, they can give new " ..
                "life... a proud fate for any of my kind.",
            rewardMoney = 56000,
        },
        [12450] = {
            description = "I have one final task for you, <race>... one that should turn the tide of this " ..
                "fight.\n\nReturn to the shrine and kill the necromancers that are fueling this " ..
                "onslaught. With them dead, we should be able to beat these forces back and eventually " ..
                "retake the shrine.\n\nI also need you to find the source of the corruption under the " ..
                "shrine and put an end to it.\n\nI know I have asked a lot of you, but if you do this for " ..
                "me, we will win this battle.",
            rewardChoices = {{37962, 1}, {38004, 1}, {38046, 1}, {38108, 1}},
            rewardMoney = 118000,
        },
        [12451] = {
            description = "While we build Conquest Hold, I sent Scout Vor'takh to make contact with our " ..
                "taunka allies in the east. They're based in Camp Oneqwah, which is in the easternmost " ..
                "part of Grizzly Hills, beyond Grizzlemaw.\n\nMake the journey there, hear Vor'takh's " ..
                "report and offer your assistance with anything he and the local chieftain may need. Your " ..
                "contributions to Conquest Hold have been exemplary and I know Vor'takh will be grateful " ..
                "for the assistance.",
        },
        [12453] = {
            description = "I've been asked to lend my support to our efforts against the Alliance. At the " ..
                "moment our military forces are about evenly matched and we're looking for ways to find " ..
                "an edge.\n\nThe imperial eagles that fly over the mountains and trees in this area would " ..
                "make excellent scouts for us. Take this silver feather and use it to bind my sight to " ..
                "that of them.\n\nBeing able to see our enemy's movements will grant us the strategic " ..
                "advantage we need. You'll find abundant eagles in the mountains to the east.",
            rewardChoices = {{38762, 1}, {38760, 1}, {38761, 1}},
            rewardMoney = 44000,
        },
        [12454] = {
            description = "Ysera sleeps in the Emerald Dream, watching over both the Dream and Azeroth. " ..
                "But a horrible nightmare has taken hold in the Dream, and now I fear that Ysera is being " ..
                "affected by it.\n\nRecently, I asked her to aid in the fight against the Scourge that " ..
                "are raising frostwyrms at the other dragonshrines. She misunderstood.\n\nInstead, she " ..
                "told our dragonshrine's defenders to treat those not of the green dragonflight as " ..
                "enemies.\n\nI need you to slay some of the skytalons. The shrine must regain its balance.",
            rewardMoney = 56000,
        },
        [12455] = {
            description = "The munitions drop went badly, friend. The shipment of ammo from Westguard " ..
                "Keep was intercepted by the frostwyrms circling overhead. The flying machines were torn " ..
                "apart in a matter of seconds and their cargo was scattered to the wind. Most of it is " ..
                "still topside - on the Carrion Fields.\n\nI'm gonna need you to go back up and recover " ..
                "the munitions crates that are scattered all over this damned place.\n\nHurry it up! We " ..
                "can't start this offensive without guns and ammo, <buddy/missy>!",
        },
        [12456] = {
            description = "I can feel that the shrine is not completely back in balance. The verdant " ..
                "keeper has been angered by our actions, and I sense that he will not listen to " ..
                "reason.\n\nAlystros is an immense skytalon who perches at the south end of the Emerald " ..
                "Dragonshrine. It is he who is in charge of the dragonshrine's aerial defenses. I fear " ..
                "that we will have to deal with him.\n\nTake these skytalon molts and place them on the " ..
                "ground where he can see them. He will come. Bring me his plume.",
            rewardChoices = {{37937, 1}, {37981, 1}, {38024, 1}, {38085, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 112000,
        },
        [12457] = {
            description = "We've set up chain guns and barricades directly to the east and to the west. " ..
                "Our injured soldiers are hiding in both rooms - trying their best to not alert the " ..
                "mindless ghouls to their presence.\n\nNow that we have ammo, I need you to man one of " ..
                "the chain guns and use it to blast a path clear for our soldiers! Once you're on board, " ..
                "call a soldier out from hiding and then lay down heavy fire to keep the Scourge off " ..
                "him!\n\nGet a move on!",
        },
        [12458] = {
            description = "We need more weapons in the fight against the Scourge. The natural properties " ..
                "of the Emerald Dragonshrine to the southeast may be the answer.\n\nAny unliving " ..
                "creature, save those that Sylvanas has redeemed, that steps foot in the dragonshrine " ..
                "falls to dust.\n\nI want to test a theory, and I want you to be my instrument in doing " ..
                "so, young <race>. Go to the Emerald Dragonshrine and take the seeds from the emerald " ..
                "lashers therein.",
            rewardMoney = 56000,
        },
        [12459] = {
            description = "Since we only have three seeds, we must put them to the best possible " ..
                "use.\n\nYour targets are one of the reanimated frost wyrms circling to the north near " ..
                "Galakrond's Rest, Turgid the Vile in the ruined barracks at the Carrion Fields to the " ..
                "east, and Overseer Deathgaze at Jintha'kalar far to the northeast.\n\nWhile the seeds " ..
                "would outright destroy one of the lesser Scourge, they will greatly weaken these three. " ..
                "Enough so, in fact, that you should be able to handle them on your own.",
            rewardChoices = {{37940, 1}, {37983, 1}, {38027, 1}, {38088, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 168000,
        },
        [12460] = {
            description = "We need you at the Ruby Dragonshrine.\n\nThe dragons are beset on all sides by " ..
                "the blue flight and the scourge... they're in no better a state than we are. The " ..
                "situation seems dire, but this affords us a rare opportunity to establish a valuable " ..
                "alliance.\n\nI secured a regiment to aid the red dragonflight against the Scourge at the " ..
                "Ruby Dragonshrine. If you have a fight in you, please go find Ceristrasz on the ridge " ..
                "east of the shrine and help him in any way that you can.",
            rewardMoney = 5600,
        },
        [12461] = {
            description = "You are leaving to the Ruby Dragonshrine. This is not a request.\n\nThe " ..
                "dragons are beset on all sides by the blue flight and the scourge... they're in no " ..
                "better a state than we are. It is not often we are afforded the opportunity to redeem " ..
                "ourselves for the transgressions of our ancestors.\n\nI have secured a regiment to aid " ..
                "the red dragonflight against the Scourge at the Ruby Dragonshrine. Join them and crush " ..
                "the Scourge beneath your boots!\n\nFor the Horde!",
            rewardMoney = 5600,
        },
        [12462] = {
            description = "Just down the steps lies the gateway to damnation: Scourge as far as the eye " ..
                "can see and getting thicker with each passing moment. What little intelligence we've " ..
                "been able to gather indicates that two Scourge necrolords are furiously working at " ..
                "emptying the first two crypts down below. Before we can breach the inner chamber to " ..
                "Thel'zan, we'll need to take care of those two clowns and their Naxxramas cronies.\n\nGo " ..
                "down into the mausoleum and take out the necrolords and the Naxxramas dreadguards and " ..
                "shades.",
            rewardChoices = {{37959, 1}, {38001, 1}, {38044, 1}, {38105, 1}},
        },
        [12463] = {
            description = "There's been talk of a tunnel dug by Scourge that connects the embalming " ..
                "chambers of the mausoleum with the large crypts, now unearthed by Thel'zan and his " ..
                "minions. I recently sent my best rogue, Plunderbeard, in search of answers, but have yet " ..
                "to hear back from him. If I were a betting man I'd wager that he's a goner.\n\nI want " ..
                "you to go down those steps and head straight through the embalming chamber and look for " ..
                "Plunderbeard. Dead or alive, he'll have answers.",
        },
        [12464] = {
            description = "My old enemy, High General Abbendis, has come to Northrend.\n\nSomehow she " ..
                "survived the attacks upon Tyr's Hand and brought a small force north. They've " ..
                "established New Hearthglen to the south.\n\nWhile they could prove useful in fighting " ..
                "the Scourge, Abbendis herself is far too shrewd an opponent to let live. Trust me, if we " ..
                "let them stand, she will be at our throats before the dust settles.\n\nSo, we'll deprive " ..
                "them of their leadership and go about our business. Bring me her head as proof.",
            rewardChoices = {{38134, 1}, {38135, 1}, {38176, 1}, {38177, 1}, {38178, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 106000,
        },
        [12465] = {
            description = "Whatever was written on the remaining pages of Plunderbeard 's journal must be " ..
                "recovered. Search the chambers located on the other side of this tunnel for Plunderbeard " ..
                "'s assailants. They must be the ones who tore the journal apart!\n\nShould you recover " ..
                "the missing pages, return them to Ambo Cash at the entrance of the Wintergarde Mausoleum.",
        },
        [12466] = {
            description = "You need to get to the 7th Legion Front in northern Dragonblight. Return to " ..
                "Wintergarde Keep and take the north gate out of town. Keep north until you hit a road. " ..
                "Take a left on that road and follow it until you reach the snowline. Once at the " ..
                "snowline keep heading west until you hit the Path of the Titans. Follow that north and " ..
                "it'll lead you right into the 7th Legion Front.\n\nOnce there, speak with Legion " ..
                "Commander Tyralion. He'll be expecting you.\n\nAnd <name> - it has been a pleasure. " ..
                "Farewell.",
        },
        [12467] = {
            description = "Your frostwyrm is out there.\n\n<Tyralion points west.>\n\nAnd it's a big " ..
                "one!\n\nWhen you're ready to fight, go speak with \"Wyrmbait.\" He'll \"fetch\" her. " ..
                "Once Icestorm is close enough we'll chain her to the ground and finish her off! " ..
                "Hopefully, with your help, we'll be able to take her down and get you that " ..
                "phylactery.\n\nOnce you've got the phylactery, return to Wintergarde Keep and report to " ..
                "High Commander Halford Wyrmbane. He's been making preparations for the final showdown " ..
                "with Thel'zan.",
            rewardChoices = {{37958, 1}, {38000, 1}, {38043, 1}, {38104, 1}},
        },
        [12468] = {
            description = "The Horde is a magnificent war machine and you are nothing but a cog.\n\nI am " ..
                "in charge of securing fuel for this machine. If I fail, the machine fails.\n\nLumber, " ..
                "ore, water... it's all here and we want it. And so does the Alliance.\n\nBefore we can " ..
                "move against the human scum, we need to solidify our control over the western " ..
                "region.\n\nSpeak to Sergeant Nazgrim about eradicating the vrykul in Voldrune and then " ..
                "maybe - if you turn out to not be a complete failure - we'll send you on further tasks.",
        },
        [12469] = {
            description = "Upon closer examination, the goblin appears to have been running a pack full " ..
                "of explosives across the wastes for delivery. The harpy feathers half-buried in the snow " ..
                "nearby suggest how he met his ill fate.\n\nIt appears that the goblin was bringing the " ..
                "explosives towards the Wrath Gate from somewhere to the east. It seems most prudent to " ..
                "follow the ridge back to the east and inform the sender of their runner's fate.",
            rewardMoney = 5600,
        },
        [12470] = {
            description = "A time storm at the Bronze Dragonshrine to the northeast is keeping immortals " ..
                "from entering.\n\nThe Infinite Dragonflight are in a fight inside with the defenders to " ..
                "wrest control of the dragonshrine. We must take this opportunity to gain " ..
                "information.\n\nYou are not immortal. You can cross into the dragonshrine and use the " ..
                "Hourglass of Eternity. Protect the hourglass for long enough and the leader of the " ..
                "Infinite Dragonflight should be revealed.\n\nBe warned, the Infinite Dragonflight will " ..
                "try to stop you!",
            rewardChoices = {{38133, 1}, {38173, 1}, {38174, 1}, {38202, 1}},
            rewardMoney = 118000,
        },
        [12471] = {
            description = "I thank you for saving me, <name>. The kvaldir are animals!\n\nThey made us " ..
                "fight the other prisoners. It would've been more merciful to just kill us all.\n\nThe " ..
                "youngling Karuk is still alive -- I noticed him arrive here. Tell him his father fought " ..
                "until the end.",
        },
        [12472] = {
            description = "Thanks to your heroics, Lord Fordragon has given the command to launch a full " ..
                "assault against Thel'zan. 7th Legion have made their way into the summoning chamber of " ..
                "the mausoleum and located what appears to be a gateway to hell. The only piece that's " ..
                "missing now is you.\n\nTake the phylactery and report to Legion Commander Yorik inside " ..
                "the Wintergarde Mausoleum.\n\nThere is a tunnel that the Scourge dug out just outside " ..
                "the keep that you can take to get to Yorik quickly. Go now, <name>! Lead us to victory!",
        },
        [12473] = {
            description = "Every good story has a beginning and an ending, <name>. While your story is " ..
                "far from over, I'll be damned if it's not already turning out to be the stuff of legend! " ..
                "No matter what happens to us when this is all over, what you've done at Wintergarde will " ..
                "be a tale told for years to come.\n\nNow, ally, when you are ready I will use the " ..
                "phylactery to coax Thel'zan out of hiding.\n\nShould we somehow succeed, report the " ..
                "victory to High Commander Halford Wyrmbane at Wintergarde Keep.",
        },
        [12474] = {
            description = "With the Naxxramas war machine stopped dead in its tracks the time has come " ..
                "for you to help our forces at Angrathar, the Wrathgate. Nestled against the mountain in " ..
                "northern Dragonblight is our base of operations, Fordragon Hold. It is there that Lord " ..
                "Fordragon awaits your arrival! Go now, <name>!\n\nTake the north gate out of town and " ..
                "travel north by northwest until you arrive at your destination.\n\nLight protect you!",
            rewardChoices = {{38540, 1}, {38541, 1}, {38542, 1}, {38543, 1}},
        },
        [12475] = {
            description = "After the betrayal at the Forgotten Shore, Prince Arthas - with Muradin in tow " ..
                "- began his quest for Frostmourne. Could the location of the cavern where Frostmourne " ..
                "was found be near? What secrets could it hold? While the orb has no answers for these " ..
                "questions, it does show me something.\n\nTo the northeast of Wintergarde Keep is an " ..
                "outpost built by the Scarlet Onslaught. Somewhere within that outpost is a map. The orb " ..
                "tells me that this map will be of great use to us.\n\nRetrieve it!",
        },
        [12476] = {
            description = "To the northeast of Wintergarde Keep is a newly built encampment, set up by " ..
                "the Scarlet Crusade - or rather - the Scarlet Onslaught as they now call themselves. " ..
                "While we are unsure as to why they are in Northrend, they are certainly no less " ..
                "dangerous than they were before. As of last night the Scarlet Onslaught has killed " ..
                "twelve of our soldiers. They must be taught a lesson, <name>.\n\nGo to Onslaught Base " ..
                "Camp and thin them out.",
            rewardItems = {{33447, 5}},
            rewardMoney = 53000,
        },
        [12477] = {
            description = "\" The Path of Redemption,\" ever heard of it? It is allegedly a journal that " ..
                "holds the prophetic ramblings of High General Abbendis of the Scarlet Onslaught. Within " ..
                "that book can be found the motivations and goals of the Scarlet zealots - not to mention " ..
                "a whole lot of insanity.\n\nVenture to Onslaught Base Camp, northeast of Wintergarde " ..
                "Keep, and recover a copy of \" The Path of Redemption \" from one of the Onslaught " ..
                "soldiers.",
        },
        [12478] = {
            description = "They have labeled the cave as Frostmourne Cavern. Why the Scarlet Onslaught is " ..
                "interested in such things is unknown, but by the look of things, the area surrounding " ..
                "the cave is heavily guarded. Nonetheless, we must proceed!\n\nTake this scrying orb and " ..
                "travel north out of town and then northwest towards Scarlet Point. Make your way into " ..
                "the cave and battle your way to the bottom. Once there, use the orb. Return here with " ..
                "what you discover.",
            rewardChoices = {{38530, 1}, {38531, 1}, {38532, 1}, {38533, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [12481] = {
            description = "The vrykul are being clever about this. Fortunately I've a trick up my " ..
                "sleeve.\n\nThis leader of theirs, Bjorn, is a real hothead. We've pieced together enough " ..
                "of their language to fashion what we think is a good insult. Something involving his " ..
                "mother and large barnyard animals... we're not quite sure.\n\nTake this piece of paper " ..
                "and read it to him. Once he starts chasing you, lure him back here. We'll make sure he " ..
                "doesn't make it out alive.",
            rewardChoices = {{35888, 1}, {35889, 1}, {35890, 1}, {35891, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 94000,
        },
        [12482] = {
            description = "We await reinforcements from Vengeance Landing to move against Nifflevar. If " ..
                "we were to capture it earlier, though, it would provide us with a great advantage over " ..
                "the Alliance.\n\nHead into town and see if you can put a dent in their numbers.",
        },
        [12483] = {
            description = "Say, while yer here, how bout ya help ol' Prigmon with a little chore? I got a " ..
                "friend who can make a mean stew - one like ya never tasted before!\n\nThere be a few " ..
                "ingredients found in these parts that he be needin'. They be in ruins to the southwest " ..
                "and the camp just north o' here.\n\nWhatd'ya say, mon?",
            rewardMoney = 59000,
        },
        [12484] = {
            description = "Ugh.\n\nWrappin' up these unfortunate trolls be makin' my heart ache, but not " ..
                "so much as my back!\n\nHelp ol' Prigmon out and haul one of these carcasses over to " ..
                "Mack.\n\nIf we don't burn 'em they be walkin' again in no time.",
            rewardMoney = 14400,
        },
        [12486] = {
            description = "Did you feel it?\n\n<Sauranok momentarily clutches his chest in confusion. His " ..
                "hand comes away trailing red-hot steam.>\n\nSomething terrible has happened to my old " ..
                "friend, Farseer Grimwalker. I just sensed it.\n\nHe had a pupil that he took with him " ..
                "when he went north. They were going to help the overlord establish an outpost on the " ..
                "edge of Sholazar Basin.\n\nHer name is Snarlfang. She is a spirit talker.\n\nPerhaps she " ..
                "will know what happened. Or, at least, she can help you to find out.",
        },
        [12487] = {
            description = "I've received a request for help from our base in the Grizzly Hills. I'm " ..
                "sending you to see Conqueror Krenna.\n\n<The high executor waves a sheaf of parchment in " ..
                "the air as if he could care less what is written on it.>\n\nShe's attempting to secure " ..
                "all of the natural resources or somesuch. Just watch your back around her. The word is " ..
                "that she's aggressive even for an orc.\n\nFollow the road east and then southeast. Cross " ..
                "the bridge at the Dragonspine Tributary and go east from the Evergreen Trading Post.",
        },
        [12488] = {
            description = "It's a good thing that I intercepted this request from High Executor Wroth " ..
                "before it got to Overlord Agmar. What is Wroth thinking?\n\n<The sergeant rips up the " ..
                "letter that he's holding.>\n\n<class>, go see what it is that the high executor " ..
                "wants.\n\nFollow the road east and pass through The Dragon Wastes. You'll find a path " ..
                "leading up out of the wastes on the southeast side, and the Forsaken town, Venomspite, " ..
                "will stand before you on the south side of the mountain.",
        },
        [12489] = {
            description = "So, where did you come from? I don't suppose that fool of an archmage sent " ..
                "you, too?\n\nYou're lucky to be in one piece, <laddie/lass>! They nearly blew you " ..
                "up!\n\nThe jungle here's a darned dangerous place, 'specially with the Venture Company " ..
                "about.\n\nGit you! Go see the boss... he'll sort you out. The camp's at the end of that " ..
                "path to the northwest.\n\nNow, git!",
            rewardMoney = 31000,
        },
        [12495] = {
            description = "Our assault against Angrathar has staggered the Scourge, but they remain " ..
                "unrelenting. From overhead they send their frost wyrms to strafe the field of battle, " ..
                "making an advance upon the gate itself impossible. The frost wyrm attacks must be " ..
                "stopped, but before we defile the bones of ancient dragons, we must gain permission from " ..
                "their queen.\n\nTravel southeast to Wyrmrest Temple and seek out Queen Alexstrasza. Tell " ..
                "her what we must do and ask her for guidance.\n\nGo now, <name>!",
        },
        [12496] = {
            description = "Though I know you hunger to destroy the Scourge that stand before us at the " ..
                "Wrath Gate, we must first deal with the threat that looms overhead. Until the strafing " ..
                "assaults of the frost wyrms are halted, we cannot move forward.\n\nBut before we assault " ..
                "the dying grounds of dragons, we must first be granted permission. Venture now to the " ..
                "hallowed halls of dragonkind: Wyrmrest Temple. Once there, seek out Queen " ..
                "Alexstrasza.\n\nRide now, <name>! Southeast, to Wyrmrest!",
        },
        [12497] = {
            description = "Atop the Wicked Coil, the Grand Necrolord of the Scourge, Antiok, sits upon " ..
                "the shoulders of the reconstructed storm giant lord, Thiassi. From there he commands the " ..
                "armies of undead to work day and night to unearth Galakrond's massive bones. Should they " ..
                "succeed in raising Galakrond, all of your efforts will have been for naught.\n\nWhile I " ..
                "cannot call down the full fury of the Red Dragonflight to assist you in your journey, I " ..
                "will grant you my blessing. Go now and speak with my majordomo, Torastrasza.",
        },
        [12498] = {
            description = "Use this beacon to signal a Wyrmrest vanquisher. Climb upon its back and fly " ..
                "north to Galakrond's Rest. Once there, command the dragon to destroy the Scourge " ..
                "scavengers that work to unearth Galakrond. Once the area has been cleansed, fly to the " ..
                "Wicked Coil, overlooking Galakrond's Rest, to destroy Grand Necrolord Antiok and recover " ..
                "the scythe that he uses to control the wyrms.\n\nDo this and return to Queen Alexstrasza " ..
                "for a hero's reward!\n\n<name>, beware the rotting storm giants that wander the area!",
            rewardChoices = {{38010, 1}, {38053, 1}, {38114, 1}, {38073, 1}},
        },
        [12499] = {
            description = "With Antiok slain and the scythe in our possession, the frost wyrm assaults " ..
                "upon your forces at Angrathar will halt. The wyrms that remain in the Dragonblight will " ..
                "be hunted and destroyed, their bones returning to the earth.\n\nThe time to make your " ..
                "final stand is now, <name>. Return to Fordragon Hold and notify Highlord Fordragon.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [12500] = {
            description = "With Antiok slain and the scythe in our possession, the frost wyrm assaults " ..
                "upon your forces at Angrathar will halt. The wyrms that remain in the Dragonblight will " ..
                "be hunted and destroyed, their bones returning to the earth.\n\nThe time to make your " ..
                "final stand is now, <name>. Return to the Kor'kron Vanguard and notify Saurfang the " ..
                "Younger.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [12501] = {
            description = "Unsheathe that weapon, <race>. It's time to go on patrol!\n\nI've got four " ..
                "posts under my command and it's crucial to our success that they remain in our control. " ..
                "I'm ordering you to visit each of them and offer your assistance.\n\nYou can begin with " ..
                "Captain Brandon southeast of here. He'll direct you to the next post when he's finished " ..
                "with you.\n\nReport back to me once you've assisted each of my men. And remember, you'll " ..
                "be more richly rewarded for returning to me quickly - so double-time it!\n\nDismissed!",
            rewardMoney = 62000,
        },
        [12502] = {
            description = "Listen, <class>. This is the Argent Crusade. Our men will fight to the end and " ..
                "never complain no matter what the conditions.\n\nThat said, we've taken some heavy " ..
                "casualties in this campaign and we've been hitting it hard with little or no sleep for " ..
                "months. That all takes a toll on morale, whether we admit it or not.\n\nIt may not seem " ..
                "like much, but seeing our standard raised over the battlefield is of considerable " ..
                "comfort to a soldier. Take these banners and raise them at the pedestals in Drak'Sotra.",
            rewardMoney = 15800,
        },
        [12503] = {
            description = "Despite our substantial successes in the lower third of Zul'Drak, we must " ..
                "still face the onslaught of the Scourge. Such is the way in this frigid hell.\n\nThe " ..
                "attacks are unrelenting, yet my men need rest. If you are willing, we could use your aid " ..
                "in reinforcing them.\n\nBelow in the courtyard you'll find no end to the fighting. " ..
                "Dispatch the Scourge there with all the zeal you can muster, <class>.",
            rewardMoney = 62000,
        },
        [12504] = {
            description = "<The sergeant quickly reads through the orders you've handed him, a frown " ..
                "coming over his face.>\n\nLook, <lad/lass>, I'd love to just up and leave, but take a " ..
                "look out there. All of my people are fighting.\n\nTell you what, you've come this far, " ..
                "you think you're up to doing me a small favor? Head out there and round up my " ..
                "soldiers?\n\nTell 'em that the sergeant orders them to report back immediately. Lend " ..
                "them a hand if you will.",
            rewardChoices = {{39771, 1}, {39780, 1}, {39782, 1}, {39834, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 62000,
        },
        [12505] = {
            description = "<class>, you're here to help, right? I've got new orders for our forces that " ..
                "are currently deployed at the Drakkari altar to the north.\n\nYou can't miss it. Just " ..
                "head straight up the avenue. Sergeant Stackhammer shouldn't be hard to find.",
            rewardMoney = 6200,
        },
        [12506] = {
            description = "There's trouble at the altar of the snake god.\n\nThe presence of the Scourge " ..
                "has weakened the land, <race>. This in turn has weakened the wild gods.\n\nWe know that " ..
                "the Drakkari are taking advantage of this to do evil things to the gods.\n\nI need you " ..
                "to be my eyes and ears. The Altar of Sseratus is at the end of the avenue to the north. " ..
                "Sneak around the back and get a look inside of the main altar building.\n\nWhatever you " ..
                "do, avoid the prophet at all costs!",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 62000,
        },
        [12507] = {
            description = "This bottle of strange mojo may be the key to what is truly going on " ..
                "here.\n\nThe Zandalari troll Hexxer Ubungo, back at The Argent Stand, may want to take a " ..
                "look at it.",
            rewardMoney = 15800,
        },
        [12508] = {
            description = "I couldn't help but overhear what you were talking to the sergeant about. That " ..
                "doesn't change the fact that we still have a job to do here.\n\nWhile you're out there, " ..
                "do you think you could help us to put some of those followers of Sseratus out of their " ..
                "misery?",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 62000,
        },
        [12509] = {
            description = "Finally, the patrol arrives!\n\nHere's the situation, <race>. We've lost many " ..
                "of our finest soldiers in this campaign and have had to call upon our recruits to fill " ..
                "in the gaps.\n\nWe've just fought one of our fiercest battles and many of the recruits " ..
                "were simply not prepared to face this enemy. There are more fights ahead, and I need " ..
                "them ready to follow orders.\n\nIf there's one thing I can't stomach, it's cowardice. " ..
                "Perhaps you can help them find the courage to continue.",
            rewardMoney = 15800,
        },
        [12511] = {
            description = "While we focus to hold our ground at Wintergarde and deal with the unfolding " ..
                "events of the Wrathgate, battalions from as far away as Westfall battle their way " ..
                "through the dense foliage and inhospitable denizens of Grizzly Hills. All in hopes of " ..
                "finding an alternate route into Icecrown.\n\nLieutenant Dumont, stationed at Amberpine " ..
                "Lodge, has enlisted the aid of able bodied citizens willing to risk life and limb in the " ..
                "uncharted wilds. Will you rise to meet this challenge?",
        },
        [12512] = {
            description = "Ahh, good. They sent someone.\n\nListen, <race>. We need a hand here. Our " ..
                "forces were pushed back and we've lost Drak'Sotra to the Scourge. Where they came from " ..
                "is anyone's guess....\n\nThe point is, we need every man we can get here, and some of " ..
                "our best have yet to return from battle.\n\nI need you to enter the ruins now that the " ..
                "fighting has died down and find our wounded, patch them up, and bring them here to " ..
                "me.\n\nScour Drak'Sotra! They couldn't have gone far.",
            rewardChoices = {{39807, 1}, {39857, 1}, {39860, 1}, {39868, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 62000,
        },
        [12514] = {
            description = "Now what we need is something to spike the mojo with. Something that'll make " ..
                "it so that when the prophet drinks it, he'll become less powerful.\n\nDrak'Agal lies to " ..
                "the east. There's a mushroom there that the natives call muddlecap fungus. I think it's " ..
                "exactly what we need.\n\nBring back lots of them. When we mix them into the mojo, the " ..
                "mind of anyone who drinks it will become muddled.",
            rewardMoney = 62000,
        },
        [12515] = {
            description = "My hat? Yes, it's an unusual style, I know, from far away... few tailors here " ..
                "know how to make them.\n\nWhen I was young and hot-blooded, I wore it as a standing " ..
                "challenge. Many came seeking to defeat me and win it for themselves... but no one ever " ..
                "did.\n\nAh, but those days are long past. I'm an old man, now: I drink, I fish, but I no " ..
                "longer duel.",
            rewardItems = {{38276, 1}},
        },
        [12516] = {
            description = "There. I've modified the mojo. Now when the prophet drinks it, not only will " ..
                "he lose some of his power, his mind will also be addled by the effects of the " ..
                "fungus.\n\nAt least that's the theory.\n\nAs for how to get him to drink it, might I " ..
                "suggest you simply throw it at him? No doubt he'll catch and drink it given the " ..
                "arrogance that he's displayed at the altar.\n\nUnless you can kill him, <class>, your " ..
                "Argent Crusade is about to come to a terrible end.",
            rewardChoices = {{39785, 1}, {39815, 1}, {39817, 1}, {39843, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 124000,
        },
        [12518] = {
            description = "Now that you have gathered all of the Mage cards together into a deck, another " ..
                "card appears on top. It depicts a fortune teller that seems to stare at you no matter " ..
                "how you hold the card.\n\nYou feel the card could be used to communicate with someone or " ..
                "something.",
            rewardChoices = {{44215, 1}, {44213, 1}},
        },
        [12519] = {
            description = "Look at me, <race>. Do I look like I have time fer fillin' out reports?\n\nIt " ..
                "be all I can do to keep this post free o' the bloody Scourge, and they want me to mess " ..
                "with paperwork!\n\n<sigh> No sense in complainin'. I need to get the commander some " ..
                "kinda kill count from the last skirmish.\n\nYou wanna be helpful? Go and get me all the " ..
                "medals you can find from the dead trolls around here. That'll hafta be close enough.",
            rewardMoney = 15800,
        },
        [12520] = {
            description = "No rough landing is going to stop ol' Hemet from mastering the largest game " ..
                "Sholazar has to offer. In the wilds northwest of the camp, the jungles are ruled by the " ..
                "mighty shardhorn rhino. You can prove your worth to the expedition, <lad/lass>, by " ..
                "showing me that you're tough enough to face down those powerful beasts.",
            rewardMoney = 62000,
        },
        [12521] = {
            description = "When I heard that the legendary Hemet Nesingwary was setting sail for the " ..
                "Sholazar Basin, I offered to help fund his expedition. We know little of Sholazar, but " ..
                "it's said to be a lush paradise in the midst of this frozen continent.\n\nHemet has " ..
                "agreed to send back samples of exotic plants, reagents, and crystals. There hasn't been " ..
                "any word from him. Monte Muzzleshot was supposed to be bringing them supplies, but he " ..
                "hasn't returned, either. If you'll look into it, I'll send you in my flying machine.",
        },
        [12522] = {
            description = "She's ruined... ruined! I told that captain to be careful with such a precious " ..
                "cargo, but would she listen to me? No!\n\nWhen the ship ran aground, it damaged my " ..
                "flying machine, the Spirit of Gnomeregan. Now, we're left without any means to send our " ..
                "reports!\n\nThere is a chance, though, that the Venture Company's antics may work in our " ..
                "favor. They shot down another flying machine right about where Monte parachuted into the " ..
                "swamp to the east. Go there and retrieve the engine. It may be our only hope.",
            rewardMoney = 48000,
        },
        [12523] = {
            description = "Great, now that we've got an engine, we're going to need an assortment of " ..
                "other parts to get her back in flying condition. Don't worry, I know what I'm " ..
                "doing.\n\nA good mechanic can hold his creations together with anything, but we're " ..
                "better off if it doesn't come to that.\n\nAnyway, those Venture Company dullards have " ..
                "plenty of spare parts for their mining equipment all over Swindlegrin's Dig on the far " ..
                "side of that yellow crystal pillar to the northeast. Scoop up a few and bring them back " ..
                "here.",
            rewardMoney = 62000,
        },
        [12524] = {
            description = "Ever since we arrived, the Venture Company has hampered our efforts to secure " ..
                "our campsite and survey the area. Normally, we wouldn't care what they were up to, but " ..
                "they've started antagonizing our scouts and shooting down supply flights.\n\nWe can't " ..
                "allow this insult to stand. Hemet Nesingwary's expedition came here to hunt, and hunt it " ..
                "shall.\n\nGo to Swindlegrin's Dig, on the far side of the crystal pillar to the " ..
                "northeast, and kill any Venture Company employee you see!",
            rewardMoney = 62000,
        },
        [12525] = {
            description = "We must send Foreman Swindlegrin packing if we're going to shut down his mine " ..
                "permanently, but be careful. His bodyguard, Meatpie, is a large, mean ogre, and isn't " ..
                "likely to let you see the foreman without a fight.\n\nThe two probably occupy a platform " ..
                "that would let them look out over the entire Venture Company operation at Swindlegrin's " ..
                "Dig.\n\nRemember, the dig is on the far side of the Suntouched Pillar to the northeast. " ..
                "Good luck, <name>.",
            rewardChoices = {{39332, 1}, {39376, 1}, {39430, 1}, {39452, 1}},
            rewardMoney = 62000,
        },
        [12526] = {
            description = "Well, that's settled then. We'll seek out this native sage and have a word " ..
                "with him. He's not likely to volunteer his services, though.\n\nI'm told he keeps a " ..
                "small lean-to near the Bones of Nozronn, just across the river to the south. Seek him " ..
                "out, introduce yourself, and ask what he requires to help us track down this patriarch " ..
                "of the rhinos.",
        },
        [12527] = {
            description = "My master, Finklestein, is in the shrine at Heb'Valok to the northwest " ..
                "preparing a truth serum, and he needs basilisk crystals. Heb'Valok is on the west side " ..
                "of the road leading north before the Altar of Sseratus.\n\nThere are basilisks to the " ..
                "east at Drak'Agal.\n\nIf you grab the Zul'Drak rats and throw them at the basilisk, they " ..
                "will become gorged and docile after eating five. Then you'll be able to take their " ..
                "crystals.\n\nKilling the basilisk won't do you any good. That'd just break its crystals!",
            rewardMoney = 62000,
        },
        [12528] = {
            description = "My kill! You take my kill!\n\n<Gekgek taunts you with his spear.>\n\nYou dumb, " ..
                "<race>. Now you owe Gekgek! You be Frenzyheart slave. You slay many more beasts for " ..
                "Frenzyheart.\n\nYou go Frenzyheart Hill to northeast - you tell High-Shaman Rakjak you " ..
                "the new slave.\n\nGo, <race>! Go or I taunt you a second time!\n\n<Gekgek waves his " ..
                "spear around menacingly.>",
            rewardMoney = 16600,
        },
        [12529] = {
            description = "You think you so great hunter, eh? You no Frenzyheart, you not know of " ..
                "hunt.\n\nGoregek is great ape hunter. He slay so many ape you can't count on " ..
                "claws.\n\nYou go with Goregek and hunt hardknuckles to east. You the slave, <race>. You " ..
                "do what Goregek tell you.",
            rewardMoney = 65000,
        },
        [12530] = {
            description = "Slave thing!\n\nRakjak want me to babysit you while I kill hardknuckles. I " ..
                "feeling generous today, so I let you kill some too, but don't get in Goregek's " ..
                "way!\n\nRakjak not know yet, but Goregek has eye on big bad hardknuckle mama. We go to " ..
                "Hardknuckle Clearing to east and poke softknuckles with poker and she sure to come " ..
                "yelling!\n\n<Goregek rubs his hands together gleefully.>",
            rewardMoney = 65000,
        },
        [12531] = {
            description = "Lion killer, chicken chaser, new Frenzyheart slave...\n\nI know you no want to " ..
                "stay slave, so I tell you what to do. Show you better than the other Frenzyheart hunters " ..
                "and then Rakjak respect you.\n\nUnder sands of south river there a beast that kills " ..
                "wasp, apes, and even wolvar. He called Serfex. You bring claw of Serfex to Rakjak and " ..
                "maybe he release you from slaveness.\n\nHope Dajik teaching you good so Serfex be easy " ..
                "stuff.",
            rewardMoney = 65000,
        },
        [12533] = {
            description = "Rakjak not dumb. Maybe you good at killing things. Maybe Frenzyheart can make " ..
                "you into real hunter.\n\nDajik hunts giant wasp things better than all wolvar. Go with " ..
                "Dajik to Sapphire Hive to southeast or to river in south and learn the hunt.",
            rewardMoney = 65000,
        },
        [12534] = {
            description = "Bristlepine can be dangerous, but most stay far away from wolvar. Wasps on " ..
                "other hand not fear the Frenzyheart... they even kill some of our hunters.\n\nI know " ..
                "Rakjak want wasp queen dead, but no wolvar want to go into her hive. You go kill wasp " ..
                "queen in Sapphire Hive to southeast and get stinger for Rakjak. Me bet Rakjak like that.",
            rewardChoices = {{39346, 1}, {39387, 1}, {39436, 1}, {39450, 1}},
            rewardMoney = 65000,
        },
        [12535] = {
            description = "You good hunter, but Frenzyheart can make you stronger. Harkek think maybe you " ..
                "ready for something more important.\n\nBefore Rakjak send you on important mission, you " ..
                "need gather things for Rakjak. All along river to south are blue crystals. Rakjak need " ..
                "lots of blue crystals.\n\nYou go get crystals now.",
            rewardMoney = 65000,
        },
        [12536] = {
            description = "Zepik is best hunter of the Frenzyheart. Zepik hunts big-tongues... ugly " ..
                "things near swamps that try to steal all stuff they can find.\n\nZepik going on long " ..
                "trek to break big-tongue shrine and try to scare them away. We no want big-tongues in " ..
                "this land anymore.\n\nThere a crocolisk chained on northeast side of hill, next to tree " ..
                "- go with Zepik and do what Zepik tell you.",
            rewardMoney = 16600,
        },
        [12538] = {
            description = "Gorillas and wasps are boring! Big-tongues the only thing fun to " ..
                "hunt.\n\nWhile we mess up rain shrine, we kill lots of mist big-tongues. That sure to " ..
                "make them not want to come back to village thing.\n\n<Zepik nods to himself confidently.>",
            rewardMoney = 65000,
        },
        [12539] = {
            description = "Okay, we done! Time to go back. No crocolisk to ride this time though.\n\nIf " ..
                "we go east and stay near ridge, it should lead all the way back near hill.\n\nNeed to be " ..
                "careful not to go far below ridge though or we might go right into big-tongue tree " ..
                "village thing. Zepik not think they like us right now.",
            rewardMoney = 65000,
        },
        [12540] = {
            description = "Okay <guy/lady>, Rakjak have very important job. You go capture injured " ..
                "big-tongue that tracker spotted at river to north.\n\nNot bring hunter this time because " ..
                "they maybe want to just kill it. I want to hide it so that I can poke it and make it " ..
                "tell me things.\n\nGo you and bring me big-tongue prize thing.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 65000,
        },
        [12541] = {
            description = "Ahh, you must be the promised patrol. Your timing couldn't be better. I have " ..
                "urgent need of an extra pair of hands.\n\nWe have a Drakkari prisoner who's been sent " ..
                "here to undergo questioning. Before the interrogation begins, I require assistance in " ..
                "the creation of a truth serum.\n\nCreating a truth serum is tricky business, demanding " ..
                "keen instincts, perfect timing, and improvisation at every step.\n\nLet me know when " ..
                "you're ready, <race>. And remember, timing is everything!",
            rewardMoney = 15800,
        },
        [12542] = {
            description = "<class>! The Argent Crusade is looking for able bodied soldiers that are " ..
                "willing to set aside their differences and join forces to battle the forces of the Lich " ..
                "King. Will you take up our cause?\n\nShould you be interested, venture north to Light's " ..
                "Trust and speak with Crusader Valus.\n\nYou will find Light's Trust amidst the ruins of " ..
                "the sacked troll city of Jintha'kalar - bordering Zul'Drak.\n\nFarewell.",
        },
        [12543] = {
            description = "We not know you, stranger, but we know you want something.\n\nWe will talk to " ..
                "Bones of Nozronn for you, but you must bring us offerings. We need powerful emperor " ..
                "cobra fangs to complete our oracle's necklace.\n\nGo to the Wildgrowth Mangal, northeast " ..
                "of our hut, find cobras and bring back best fangs. Then we make bones speak to you.",
            rewardMoney = 62000,
        },
        [12544] = {
            description = "Bones of Nozronn, Oracle Soo-rahm sends <name> to you!\n\nWe have prepared " ..
                "incense for you. Light it and place it near Nozronn's head and you will hear his " ..
                "voice.\n\n<Confused, you tell Soo-rahm that you haven't even told him your " ..
                "question.>\n\nTrue, we not know, but mighty Nozronn does. Do not doubt. Nozronn will " ..
                "answer your heart's question.\n\nGo. Nozronn not wait long.",
            rewardMoney = 48000,
        },
        [12545] = {
            description = "We wrested this ancient Drakkari temple from a swarm of invading Scourge. Not " ..
                "more than one-hundred paces from where we stand is the ruined city of Jintha'kalar. " ..
                "Scourge necromancers run amok, turning the living Drakkari trolls that remain into " ..
                "servants of the Lich King.\n\nAll are now lost to the Light. All must be " ..
                "purged.\n\n<Valus looks upon you sternly.>\n\nAll.",
            rewardChoices = {{38188, 1}, {38190, 1}, {38198, 1}, {38206, 1}, {38207, 1}},
            rewardMoney = 56000,
        },
        [12547] = {
            description = "This colossal being appears to be inactive. You notice an empty rune-shaped " ..
                "slot on its chest.\n\nPerhaps you might be able to find the missing rune inside the " ..
                "nearby overlook.",
            rewardChoices = {{39366, 1}, {39411, 1}, {39442, 1}, {39465, 1}},
            rewardMoney = 68000,
        },
        [12548] = {
            description = "It is time, <name>. The Waygate has been activated for the first time in seven " ..
                "centuries. Use it to travel to where our final hope lies.\n\nLet us put an end to those " ..
                "who would seek to bring the taint of undeath to this pristine land. Let us unleash the " ..
                "Etymidian.",
        },
        [12549] = {
            description = "If you've hunted with Hemet before, you know that he's tested his skill " ..
                "against many large cats, but the dreadsabers here in Sholazar are different. They're " ..
                "able to bring down larger game than I've ever seen a cat hunt. To overcome and kill such " ..
                "a predator is the mark of a true hunter.\n\nIf you seek to prove you're up to the " ..
                "challenge, test yourself against the dreadsabers. They live in the wilderness " ..
                "surrounding the camp and south of the river.",
            rewardMoney = 62000,
        },
        [12550] = {
            description = "I have heard that the natives tell stories of a large dreadsaber they call " ..
                "Shango. I haven't seen any evidence of this Shango's existence, but my injuries have " ..
                "kept me from venturing outside the camp.\n\nIf you fancy yourself something of a " ..
                "tracker, you might be able to find out the truth about Shango. Debaar said she saw some " ..
                "large tracks on her last outing. Go north from the camp toward Bittertide Lake, and " ..
                "search its southern shore for the prints.",
            rewardMoney = 62000,
        },
        [12551] = {
            description = "I warn you, stranger -- do not make any comments about crashing the ship. I " ..
                "already get enough of it from the rest of the expedition.\n\nIf you're looking to try " ..
                "your hand at hunting, though, you should test your skills against the wily mangal " ..
                "crocolisks. They live all along the river to the south, and in the Wildgrowth Mangal to " ..
                "the east. Prove you can hold your own against them and we'll talk again, hunter.",
            rewardMoney = 62000,
        },
        [12552] = {
            description = "When the trolls brought down Kolramas, it crashed next to us to the southeast. " ..
                "Unfortunately the crash did not destroy all of the Scourge within.\n\nNow they're " ..
                "raising our men from the dead and using them against us!\n\nThis will not be allowed to " ..
                "continue. You will see to it that their necromagi are slaughtered! Do we understand each " ..
                "other?",
            rewardMoney = 62000,
        },
        [12553] = {
            description = "Why do I always get the tough tasks to tackle?\n\nThe Scourge at Kolramas have " ..
                "plague sprayers that are getting dangerously close. You don't want to know what's going " ..
                "to happen if they start heading this way!\n\nI've got an idea for how we might bring " ..
                "them down, but first we're going to need something... something from their own " ..
                "creatures.\n\nThe Hath'ar skimmers can spin a very strong web that we can put to good " ..
                "use. Bring back some of their spinnerets.",
            rewardMoney = 62000,
        },
        [12554] = {
            description = "<name>, head back down there!\n\nYou'll find the leader of Kolramas, Malas the " ..
                "Corrupter, gloating from atop the crashed necropolis.\n\nKill him and bring me his head!",
            rewardChoices = {{43160, 1}, {43161, 1}, {43162, 1}, {43163, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 124000,
        },
        [12555] = {
            description = "There! One tangled skein thrower ready and waiting for you to take those " ..
                "plague sprayers down.\n\nYou just aim and let loose. The webbing should foul up their " ..
                "hover spells long enough to cause them to crash to the ground just like " ..
                "Kolramas.\n\nKind of poetic. I like that!",
            rewardChoices = {{39784, 1}, {39806, 1}, {39808, 1}, {39822, 1}, {39823, 1}, {39824, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 62000,
        },
        [12557] = {
            description = "I assume by your interruption that you wish to be numbered among those I am " ..
                "considering for apprenticeship.\n\nA worthy aspiration...\n\nShould I someday choose to " ..
                "accept your petition, I must be confident that you can find your way around my " ..
                "laboratory. I have many ingredients here; some plentiful, and others in short " ..
                "supply.\n\nTake your time, <class>. Find a muddy mire maggot, a withered batwing, an " ..
                "amberseed, and some chilled serpent mucus.\n\nSucceed, and I'll know to take your " ..
                "request seriously.",
            rewardMoney = 6200,
        },
        [12559] = {
            description = "It is time then. Let us activate the waygate.\n\nYou will find the first " ..
                "switch inside the Makers' Perch in the western edge of the basin.\n\nBeware, <name>. The " ..
                "titans used the perch to watch over their creations. Many of their stone servants still " ..
                "guard the place.",
            rewardMoney = 51000,
        },
        [12560] = {
            description = "The mangal crocolisk is a master of the ambush, and I intend to beat the best " ..
                "at his game. To do that, we'll need to construct a convincing camouflage for you. We'll " ..
                "use plants that grow in the sandy soil of the riverbanks and lake beaches.\n\nThe " ..
                "sandfern is best for this purpose. It grows in the sandy areas near the shores of the " ..
                "Seabreach Flow, just to the south, Bittertide Lake and Bittertide Falls, to the north, " ..
                "and the edges of River's Heart, the large lake beyond the mangal to the east.",
            rewardMoney = 62000,
        },
        [12562] = {
            description = "Intelligence reports that ever since those water elementals appeared in the " ..
                "Drak'Sotra Fields, a number of Drakkari shaman have come down from the upper tiers of " ..
                "Zul'Drak to take control of them.\n\nI cannot stress enough, <sir/ma'am>, how dangerous " ..
                "that could prove. We do not want them to have water elementals at their disposal.\n\nThe " ..
                "commander has ordered that these Drakkari water binders are to be put to the sword. Head " ..
                "south when you're ready.",
            rewardMoney = 62000,
        },
        [12563] = {
            description = "Unsheathe that weapon, <race>. It's time to go on patrol!\n\nI've got four " ..
                "posts under my command and it's crucial to our success that they remain in our control. " ..
                "I'm ordering you to visit each of them and offer your assistance.\n\nYou can begin with " ..
                "Captain Brandon southeast of here. He'll direct you to the next post when he's finished " ..
                "with you.\n\nReport back to me once you've assisted each of my men. And remember, you'll " ..
                "be more richly rewarded for returning to me quickly - so double-time it!\n\nDismissed!",
            rewardMoney = 62000,
            startedBy = {{28039}},
        },
        [12564] = {
            description = "Gritty as my men are, they're still mortal.\n\nWounds and pain diminish their " ..
                "ability to perform their missions. No amount of training changes that simple fact of " ..
                "life.\n\nThankfully, one of our alchemists has developed a recipe for a salve that binds " ..
                "to our bandages and greatly reduces the pain our soldiers experience.\n\nThe salve " ..
                "requires a special poppy these trolls cultivate just west of here. Go to Drak'Sotra " ..
                "Fields and harvest some of them to keep our stockpiles from running out.",
            rewardMoney = 15800,
        },
        [12565] = {
            description = "I am heartened to see the zeal with which your Argent Crusade is dealing with " ..
                "the Scourge, <race>. I would like to help with your efforts.\n\nThe Drakkari trolls of " ..
                "this once-great city used to make regular offerings to their gods, but now neglect them, " ..
                "or worse.\n\nIf you were to make offerings to the gods, they would show their " ..
                "appreciation in return.\n\nZim'Abwa 's statue is just to the southwest. Zim'Abwa would " ..
                "gladly accept your offerings of Drakkari artifacts as a sign that you are protecting " ..
                "Zul'Drak.",
        },
        [12566] = {
            description = "I am Longrunner Nanik of the Taunka, sent by the chieftain of Camp Winterhoof " ..
                "to seek out allies in the fight against the vrykul. They mass to the west and south of " ..
                "our village, and though we slay 10 of them for every one of our dead, we cannot " ..
                "hold.\n\nApothecary Scyllis has promised to send brave <class>s northwest to our aid. " ..
                "Will you help my people fend off the vrykul assaults?\n\nFollow the road far to the " ..
                "northwest, across the river, and into the foothills of the mountains to reach Camp " ..
                "Winterhoof.",
        },
        [12568] = {
            description = "Trust me, <race>. I know....\n\nThe smell of burnt flesh has become sickening " ..
                "to even me, a Forsaken. Nevertheless, it is our solemn duty to ensure that our brethren " ..
                "never walk with the Scourge.\n\nPour this oil on the corpses of our fallen to ensure " ..
                "that we never face them on the battlefield as enemies.",
            rewardMoney = 15800,
        },
        [12569] = {
            description = "The largest crocolisk in the basin, known around here as \"Bushwhacker\" for " ..
                "his ambush prowess, likes to sun himself in the shallow waters of River's Heart. It's " ..
                "the large lake at the basin's center, and is to the east of our camp.\n\nI want you to " ..
                "take the camouflage I've prepared and hide on the western beach of River's Heart and " ..
                "ambush Bushwhacker when he shows himself. Bring back his mighty jaws if you are able to " ..
                "overcome him.",
            rewardChoices = {{39331, 1}, {39374, 1}, {39461, 1}, {39480, 1}},
            rewardMoney = 62000,
        },
        [12571] = {
            description = "We were here long before the puppy-men came. This is very sacred place - we " ..
                "will not leave.\n\nYou seem like maybe you good, but we have Lafoo stay with you just in " ..
                "case. You understand we think.\n\nThere snakes thing that keeps trying to eat our " ..
                "hatchlings. Go with Lafoo and make them stop, okay? Especially big one near waterfall to " ..
                "northeast.",
            rewardMoney = 65000,
        },
        [12572] = {
            description = "Soo-say said we go with you. You be nice, okay?\n\nOoh, ooh! We know! We can " ..
                "make Soo-say happy if we bring back more offerings for shrine! We not need to go far, " ..
                "there's always stuffs to dig up around village... just look for sparkles in " ..
                "dirt!\n\nLet's go! Let's go! More offerings for shrine!",
            rewardMoney = 65000,
        },
        [12574] = {
            description = "< High-Oracle Soo-say stares at your forehead for a while before " ..
                "speaking.>\n\nSoo-gan ask for help. We think they might have been attacked by puppy-men " ..
                "again.\n\nWe sending you and Jaloot to help... follow west river up to Mistwhisper " ..
                "Refuge. Do what Soo-gan says... hit the puppy-men on the nose if they being mean, they " ..
                "don't like that.\n\n< High-Oracle Soo-say goes back to staring at your forehead as you " ..
                "leave.>",
            rewardMoney = 33000,
        },
        [12576] = {
            description = "We try to be nice to puppy-men ever since they came, but they nothing but " ..
                "mean.\n\nWe okay with them being dumb - they not do much harm. Now they mess with sacred " ..
                "shrines though. Sacred shrines not for messing with. The Great Stones are here from all " ..
                "the way back when the Great Ones made us.\n\nWe wouldn't know what to do if the Great " ..
                "Mist Stone were hurt. Go to their camp to north... make puppy-men stop and not come back!",
            rewardMoney = 65000,
        },
        [12577] = {
            description = "You're a good dryskin. Mistwhisper safe, treasure safe, and puppy-men sure to " ..
                "leave us alone now.\n\nYou go back to Rainspeaker Canopy and tell Soo-say you done good.",
            rewardMoney = 33000,
        },
        [12578] = {
            description = "I not think you be back in time to go out again, but I wrong. I sending Moodle " ..
                "to nearby Mosswalker friends to bop silly Mosswalkers for not coming see shrine. Their " ..
                "village is east, up ridge, northeast of broken pillar.\n\nYou go with Moodle! He extra " ..
                "smart Rainspeaker... you listen to him good-like.",
            rewardMoney = 33000,
        },
        [12579] = {
            description = "I've always suspected that the pillars have been the main reason for our " ..
                "weather and seclusion from the undead... this confirms it a bit.\n\nNot terribly long " ..
                "ago, there was a sound of a great explosion when the Lifeblood Pillar fell. The weather " ..
                "changed for the mosswalkers almost immediately... it began to snow, something we never " ..
                "see.\n\nThey were able to stop the snow by bringing more lifeblood crystals to the Great " ..
                "Moss Stone. Perhaps if we can do the same, it will help ward off the undead as well.",
            rewardMoney = 65000,
        },
        [12580] = {
            description = "There's some small chance that the Mosswalkers are not all dead yet... and at " ..
                "the very least, they deserve to not be butchered like this.\n\nLet's find some revenge " ..
                "for this slaughter and see if there are any to be saved in the process.",
            rewardMoney = 65000,
        },
        [12582] = {rewardMoney = 33000},
        [12583] = {
            description = "I know that one of those plague sprayers crashed somewhere within Drak'Sotra " ..
                "to the west of us.\n\nWhy don't you see if you can find it. I can use the parts from the " ..
                "sprayer to create the device that's going to bring those things down!",
            rewardMoney = 62000,
        },
        [12584] = {
            description = "We know that Kolramas, the crashed necropolis to the southeast, was carrying a " ..
                "large amount of an ore known as saronite when the trolls shot it down.\n\nMy scouts tell " ..
                "me that much of the saronite is strewn about within the innards of that " ..
                "thing.\n\nEitrigg and his friends back at The Argent Stand want a bunch of the stuff so " ..
                "that they can study it.\n\nI want you to head in there and see if you can collect enough " ..
                "for them.",
            rewardChoices = {{39773, 1}, {39795, 1}, {39837, 1}, {39792, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 62000,
        },
        [12585] = {
            description = "Well, it ain't glamorous, but it needs doin'.\n\nMy troops have been fightin' " ..
                "their hearts out while knee-deep in stagnant water for days on end. That just can't be " ..
                "good fer ya.\n\nWhat they need is a nice fire to dry 'em out and lighten their " ..
                "spirits.\n\nThis part of the city's soaked, but the dead roots of these thornwood trees " ..
                "have a way of resistin' the moisture.\n\nRound us up some fuel for burnin' and we'll be " ..
                "mighty grateful.",
            rewardMoney = 15800,
        },
        [12587] = {
            description = "Unsheathe that weapon, <race>. It's time to go on patrol!\n\nI've got four " ..
                "posts under my command and it's crucial to our success that they remain in our control. " ..
                "I'm ordering you to visit each of them and offer your assistance.\n\nYou can begin with " ..
                "Captain Brandon southeast of here. He'll direct you to the next post when he's finished " ..
                "with you.\n\nReport back to me once you've assisted each of my men. And remember, you'll " ..
                "be more richly rewarded for returning to me quickly - so double-time it!\n\nDismissed!",
            rewardMoney = 62000,
            startedBy = {{28039}},
        },
        [12588] = {
            description = "One of our troops came across an old treasure map during our last offensive. " ..
                "If what it shows is true, then there are priceless troll artifacts nearby.\n\nMy " ..
                "soldiers have their hands full, pressed between the Drakkari and the Scourge. I need you " ..
                "to follow up on this intelligence.\n\nTake this shovel and use it at the loose dirt " ..
                "mounds to the southwest. Return to me after a diligent search has been conducted.",
            rewardMoney = 15800,
        },
        [12589] = {
            description = "So you think you can shoot?\n\nWell, let's give it a try. Here, we'll start " ..
                "you out with something nice and gentle. Don't worry, it's got no kick to it at all. " ..
                "Remember, don't point that gun at anything you don't intend to fire at.\n\nNow, when " ..
                "you're ready, just take aim at that apple on top o' old Lucky Wilhelm's head and let 'er " ..
                "fly!",
        },
        [12591] = {
            description = "Clever...\n\nJust when it seemed we were getting things under control, they " ..
                "tunneled right underneath us and secured the shrine!\n\nNow we're caught between two " ..
                "nethurbian armies and our predicament is worsening by the minute.\n\nAs our first course " ..
                "of action, we must stop them from reinforcing. Their tunnels must be sealed.\n\nTake " ..
                "these grenades and throw them down their craters to the northwest.",
            rewardMoney = 15800,
        },
        [12592] = {
            description = "So y'have something of a hunter's instinct. You're not a bad shot, and Hemet " ..
                "hasn't driven you out, so he must be planning on including you in the hunt.\n\nHow'd you " ..
                "like to have a bit of a competition, just me and you?\n\nHemet and the others will ask " ..
                "you to help in their hunting. Along the way, you and I will count up the kills we " ..
                "contribute to their goals. Now, this isn't something you can win in the blink of an eye, " ..
                "and you'll find yourself killing many different kinds of creatures. Good luck!",
            rewardChoices = {{39330, 1}, {39373, 1}, {39428, 1}, {39448, 1}},
            rewardMoney = 124000,
        },
        [12593] = {
            description = "All that I am: anger, cruelty, vengeance - I bestow upon you, my chosen " ..
                "knight. I have granted you immortality so that you may herald in a new, dark age for the " ..
                "Scourge.\n\nGaze now upon the lands below us. The Scarlet Crusade scurries to undo my " ..
                "work, while Light's Hope stands defiantly against us - a blemish upon these Plaguelands. " ..
                "They must all be shown the price of their defiance.\n\nYou will become my force of " ..
                "retribution. Where you tread, doom will follow. Go now and claim your destiny, death " ..
                "knight.",
        },
        [12594] = {
            description = "Of all the posts, they throw me in this one.\n\nThe place is flooded with " ..
                "putrid, stagnant water and now it's host to sewage elementals!\n\nI don't really know " ..
                "what they are or why they're here, and frankly I couldn't care less. What I do know is " ..
                "they're making a mess of my sector! How am I supposed to conduct any dignified military " ..
                "operations with those foul things roaming around?\n\nGet out there, <class>, and don't " ..
                "come back 'til you've cleared your share of 'em off of my battlefield!",
            rewardMoney = 15800,
        },
        [12595] = {
            description = "Well, <name>, you've certainly proven your mettle as a hunter of all kinds of " ..
                "game animals -- rhinos, cats, and crocolisks. For some members of the expedition, these " ..
                "creatures are sufficient to test their hunting skills, but others, like myself, crave " ..
                "larger challenges.\n\nDorian Drakestalker went north, across Bittertide Lake and " ..
                "established a camp there. He's heard rumors of gigantic primordial drakes. Just imagine " ..
                "what a quarry they would be! Go check up on Dorian and see if he's had any luck.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [12596] = {
            description = "Welcome to The Argent Stand, scrub. I am Commander Kunz, but you - you can " ..
                "call me... Commander.\n\nDon't think you're going to just cruise through my region, " ..
                "picking which missions you're going to participate in, answering to no one.\n\nHere, you " ..
                "report to me and you follow my orders to the letter. Understood?!\n\nFirst, you're going " ..
                "to get familiar with my men and the region we're charged with clearing.\n\nReport to " ..
                "each of them and do as they ask. Return to me when your patrol is done.",
            rewardChoices = {{39800, 1}, {39850, 1}, {39851, 1}, {39864, 1}, {39827, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
            rewardMoney = 62000,
        },
        [12597] = {
            description = "Gritty as my men are, they're still mortal.\n\nWounds and pain diminish their " ..
                "ability to perform their missions. No amount of training changes that simple fact of " ..
                "life.\n\nThankfully, one of our alchemists has developed a recipe for a salve that binds " ..
                "to our bandages and greatly reduces the pain our soldiers experience.\n\nThe salve " ..
                "requires a special poppy these trolls cultivate just west of here. Go to Drak'Sotra " ..
                "Fields and harvest some of them to keep our stockpiles from running out.",
            rewardMoney = 15800,
        },
        [12598] = {
            description = "Clever...\n\nJust when it seemed we were getting things under control, they " ..
                "tunneled right underneath us and secured the shrine!\n\nNow we're caught between two " ..
                "Nerubian armies and our predicament is worsening by the minute.\n\nAs our first course " ..
                "of action, we must stop them from reinforcing. Their tunnels must be sealed.\n\nTake " ..
                "these grenades and throw them down their craters to the northwest.",
            rewardMoney = 15800,
        },
        [12599] = {
            description = "Well, it ain't glamorous, but it needs doin'.\n\nMy troops have been fightin' " ..
                "their hearts out while knee-deep in stagnant water for days on end. That just can't be " ..
                "good fer ya.\n\nWhat they need is a nice fire to dry 'em out and lighten their " ..
                "spirits.\n\nThis part of the city's soaked, but the dead roots of these thornwood trees " ..
                "have a way of resistin' the moisture.\n\nRound us up some fuel for burnin' and we'll be " ..
                "mighty grateful.",
            rewardMoney = 15800,
        },
        [12601] = {
            description = "Ahh, you must be the promised patrol. Your timing couldn't be better. I have " ..
                "urgent need of an extra pair of hands.\n\nWe have a Drakkari prisoner who's been sent " ..
                "here to undergo questioning. Before the interrogation begins, I require assistance in " ..
                "the creation of a truth serum.\n\nCreating a truth serum is tricky business, demanding " ..
                "keen instincts, perfect timing, and improvisation at every step.\n\nLet me know when " ..
                "you're ready, <race>. And remember, timing is everything!",
            rewardMoney = 15800,
        },
        [12602] = {
            description = "Ahh, you must be the promised patrol. Your timing couldn't be better. I have " ..
                "urgent need of an extra pair of hands.\n\nWe have a Drakkari prisoner who's been sent " ..
                "here to undergo questioning. Before the interrogation begins, I require assistance in " ..
                "the creation of a truth serum.\n\nCreating a truth serum is tricky business, demanding " ..
                "keen instincts, perfect timing, and improvisation at every step.\n\nLet me know when " ..
                "you're ready, <race>. And remember, timing is everything!",
            rewardMoney = 15800,
        },
        [12603] = {
            description = "The primordial drakes occupy most of the area to the north and east, and I can " ..
                "feel the heat of their breath even at this distance. Before we can challenge the " ..
                "mightiest among the drakes, we must test our skills against the lesser " ..
                "creatures.\n\nStill, don't let your guard down; any one of these beasts can devour a man " ..
                "whole. Once you've familiarized yourself with the combat tactics of these drakes, return " ..
                "and I will tell you our next step.",
            rewardMoney = 65000,
        },
        [12604] = {rewardItems = {{43556, 1}}, rewardMoney = 186000},
        [12605] = {
            description = "We're not likely to get Broodmother Slivina's attention waving our arms around " ..
                "like fools, but if we're smart, we can bait her into fighting us. We'll also secure " ..
                "more, uh, fodder for my little project.\n\n<Dorian glances over at Zootfizzle.>\n\nBut " ..
                "don't worry about that for now. Just look for the primordial drake eggs in the area east " ..
                "and northeast of the camp. Burst them open and scoop up the hatchlings that come out. " ..
                "When the broodmother realizes what we've done, she'll have no choice but to face us.",
            rewardMoney = 65000,
        },
        [12606] = {
            description = "Now that the tunnels have been sealed, our next concern is recovering those " ..
                "who have fallen to the enemy.\n\nWith any luck, several of our soldiers are still alive " ..
                "and relatively well inside the nerubian cocoons.\n\nFree them, <class>, while you still " ..
                "can!",
            rewardMoney = 62000,
        },
        [12607] = {
            description = "Before you go off challenging Broodmother Slivina, Dorian thought it might be " ..
                "a good idea for you and Hemet to coordinate your efforts by riding into battle on the " ..
                "back of a mammoth.\n\nThe area around the camp is full of them. Just take this bridle " ..
                "and slip it over the head of a shattertusk mammoth. Be careful of the bulls, though. " ..
                "They won't tolerate the harness at all. Bring the mammoth back here when you've found a " ..
                "suitable one.",
            rewardMoney = 51000,
        },
        [12608] = {
            description = "<It appears the Avatar of Freya was right. The undead were not able to enter " ..
                "Sholazar Basin before the Lifeblood Pillar was brought down -- they used their living " ..
                "agents from the Cult of the Damned instead.>\n\n<You'd best warn her about the Lich " ..
                "King's living agents within Sholazar Basin.>",
            rewardMoney = 68000,
        },
        [12610] = {
            description = "Ever since Finklestein's arrival, I've been relegated to collecting various " ..
                "ingredients for his experiments and recipes.\n\nI'll follow my orders as I've vowed to " ..
                "do, but I'm a seasoned veteran. I've taken part in dozens of conflicts. I'd much rather " ..
                "be on the front lines, having a more direct impact on the Crusade's outcome " ..
                "here.\n\nHelp me, <race>. Collect some bat wings for me so that I might get back to the " ..
                "real action sooner.",
            rewardChoices = {{39804, 1}, {39854, 1}, {39855, 1}, {39867, 1}},
            rewardMoney = 62000,
        },
        [12611] = {
            description = "The agents of the Lich King have foolishly trespassed upon these lands where " ..
                "the power of life rules supreme. All harm they inflict will be returned to them " ..
                "sevenfold.\n\nThe monster directly responsible for corrupting the land is known as " ..
                "Thalgran Blightbringer; you will find him just to the north of here. Take this ward and " ..
                "use it to reflect the power of death upon him. Show the Scourge that the power of life " ..
                "prevails above all.",
            rewardChoices = {{39367, 1}, {39412, 1}, {39444, 1}, {39464, 1}},
            rewardItems = {{39481, 1}},
            rewardMoney = 65000,
        },
        [12612] = {
            description = "The titans shaped entire life forms here, fostering their unfettered " ..
                "growth.\n\nThe five crystal pillars that surround the basin emanate pure lifeforce. The " ..
                "Scourge should've never been able to penetrate the basin, but one of the pillars was " ..
                "destroyed.\n\nGo to the Lifeblood Pillar and see if you can find out what happened. No " ..
                "undead would've been able to approach the pillar, so keep your eyes out for living " ..
                "intruders. You'll find what remains of the pillar directly south of here.",
        },
        [12613] = {
            description = "We cannot stop now, <race>. You've triggered the first switch, but one " ..
                "remains.\n\nThe titans constructed a second vantage point where they oversaw their " ..
                "creations. You'll find it to the east, high in the mountains.\n\nPull the activation " ..
                "switch theta inside the overlook and the waygate will open.",
        },
        [12615] = {
            description = "Hexxer Ubungo probably told you about making offerings to the gods of " ..
                "Zul'Drak. Zim'Abwa is not the only god that stands forgotten by the Drakkari.\n\nWe have " ..
                "taken refuge within the presence of Zim'Torga, the Mother of Prosperity. As with " ..
                "Zim'Abwa, if you were to give offerings of the Drakkari to her, she is sure to give you " ..
                "her blessing.",
        },
        [12619] = {
            description = "The single most important piece of equipment to a death knight is the " ..
                "runeblade. It is through the runeblade that a death knight commands the powers of frost, " ..
                "blood and the unholy. The runeblade also acts as a vessel to store the death knight's " ..
                "runic power.\n\nThe time has come to create your first runeblade. Search the weapon " ..
                "racks on this floor and locate a battle-worn sword. Once found, take the sword to a " ..
                "nearby runeforge and use it to create a runeblade.",
            rewardItems = {{38707, 1}},
        },
        [12620] = {
            description = "We were not quick enough, <name>. The cultist scum have arrived at the " ..
                "Glimmering Pillar and are making preparations to destroy it, I can sense them.\n\nWe " ..
                "don't have much time. Blow upon this horn atop the Glimmering Pillar to channel my power " ..
                "through the crystal.\n\nWe shall show this scum to not trifle with the titans' creations.",
            rewardMoney = 51000,
        },
        [12621] = {
            description = "The cultists have been taken care of, but the Scourge's invasion has not " ..
                "slowed down. The situation is becoming desperate, <name>.\n\nThere exists a last resort. " ..
                "Before I reveal any more, however, I must be sure I have your absolute trust.",
        },
        [12622] = {
            description = "You thinkin' what Ahunae thinkin', mon?\n\nSome of the Drakkari trolls have " ..
                "gathered at the Pools of Jin'Alai to the southwest. We be needin' to draw out their " ..
                "leaders, and Ahunae knows just how you be doin' it, too!\n\nGo in there and kill those " ..
                "trolls. When you kill enough, their leaders show up.\n\nWhen they show up next to their " ..
                "totems, you make sure to be gettin' the treasure of Kutube'sa, Gawanil, and Chulo the " ..
                "Mad, mon.",
            rewardChoices = {{39775, 1}, {39796, 1}, {39838, 1}, {39798, 1}},
            rewardItems = {{20390, 5}},
            rewardMoney = 65000,
        },
        [12623] = {
            description = "We Zandalari could use your help, <name>. We must put an end to what the " ..
                "Drakkari are doing to their gods!\n\nTo the northeast, up the great steps that lead to " ..
                "the next tier of Zul'Drak, lies Zim'Torga. It is the home to another of the god statues " ..
                "and a refuge that my people are desparately attempting to defend.\n\nI would like for " ..
                "you to travel there and speak to Witch Doctor Khufu. Be warned though, the place is " ..
                "under constant attack from the Drakkari.",
        },
        [12624] = {
            description = "When I found out that Miss Boulian was helping Nesingwary with his expedition, " ..
                "I signed up as a deckhand immediately. You see, I'd been meaning to marry her for " ..
                "months!\n\nI had it all planned out. I was going to propose the very night of the " ..
                "shipwreck... but now the ring is gone. I've searched everywhere!\n\nI know it might " ..
                "sound crazy, but I know the engagement ring is in the Basin. If some Venture Company " ..
                "didn't steal it, maybe a wild creature ate it. But it's here somewhere... I just know it!",
            rewardChoices = {{39446, 1}, {39466, 1}, {39479, 1}, {39474, 1}},
            rewardMoney = 186000,
        },
        [12627] = {
            description = "I have been trying to commune with the gods. However, the medicine men at the " ..
                "Pools of Jin'Alai are performing rituals that are interfering with my attempts.\n\nIt is " ..
                "imperative that we break through their obtrusion. If you were to head southwest into the " ..
                "pools area, I am certain that you would come across the cauldrons they are using for " ..
                "their magic.\n\nDisturb each of the cauldrons to bring down their ritual that is " ..
                "blocking me.",
        },
        [12628] = {
            description = "The gods have spoken, <name>. We now know what you must do.\n\nYou must now go " ..
                "to the Altar of Har'koa to the southeast and speak with the leopard goddess.",
        },
        [12629] = {
            description = "Once the Scourge have a target in their sights, they'll stop at nothing to " ..
                "acquire it.\n\nYou're doomed to a mindless existence as a walking " ..
                "corpse....\n\n<Stefan's face twists into a cruel grin.>\n\n... unless we can use their " ..
                "desires against them.\n\nI'll explain later. I have complex magic to prepare which " ..
                "requires certain material components.\n\nTravel due east of here to the Reliquary of " ..
                "Agony. Slay abominations and gather the ghoul drool you'll find there then return to me " ..
                "with their remnants.",
            rewardMoney = 59000,
        },
        [12630] = {
            description = "Before you meet Nass, there's something you should know.\n\nHe got a toxic " ..
                "dose of blight back in the day, and now he's deaf, blind, and mostly numb.\n\nIt's not " ..
                "all bad, though. He's virtually immune to the stuff now, which makes him perfect for " ..
                "certain tasks - like the one I'm about to give you.\n\nThere are many freshly scourged " ..
                "trolls nearby and we need to study the blight's effect on them. Take Nass, and this " ..
                "boot. When you've slain a troll, give him a good kick and he'll know to take a hair " ..
                "sample.",
            rewardMoney = 59000,
        },
        [12631] = {
            description = "Crafted of bone and dripping with blood, this choker is of intricate and " ..
                "deliberate design.\n\nGazing upon it overwhelms you with an ominous presence - one that " ..
                "compels you to wear it. You fight the urge, and resolve to bring it back to Ebon " ..
                "Watch.\n\nIf anyone can explain this, a death knight can....",
            rewardMoney = 46000,
        },
        [12633] = {
            description = "Crafted of bone and dripping with blood, this choker is of intricate and " ..
                "deliberate design.\n\nGazing upon it overwhelms you with an ominous presence - one that " ..
                "compels you to wear it. You fight the urge, and resolve to bring it back to Ebon " ..
                "Watch.\n\nIf anyone can explain this, a death knight can....",
            rewardMoney = 46000,
        },
        [12634] = {
            description = "Life's tossed me a cartload of lemons this time! When the ship ran aground, " ..
                "the kegs carrying my best brew burst! All we have now are a few bottles of rum, and it " ..
                "won't sustain a thirsty expedition!\n\nWe need to get some booze cooking, and " ..
                "fast!!\n\nThe trees in the Wildgrowth Mangal, to the east, seem laden with fruit, but " ..
                "it's too high for me to reach. Look for good, strong vines, see if you can use it to " ..
                "shake some of that fruit out of the trees. Bring me whatever you can find.",
            rewardMoney = 62000,
        },
        [12635] = {
            description = "I overheard that you are going to see to the well-being of Har'koa. Good luck " ..
                "to you.\n\nI am wondering if while you are in the vicinity of the altar, you would be " ..
                "willing to recover their relics? I do not require many, and it is only a short trip to " ..
                "the southeast.\n\nWhat do you say?",
        },
        [12636] = {
            description = "Behold, Acherus, the grand citadel of death! It has no equal in this world! " ..
                "Not even the mighty Naxxramas could withstand a direct assault from the Ebon Hold. " ..
                "Looming above the face of the necropolis is the all-seeing eye of Acherus. From it the " ..
                "master is able to see great distances into the territories held by our enemies. What the " ..
                "eye sees, the Lich King sees, and now the time has come for you to peer through the eye! " ..
                "the Lich King has called for you, <name>.\n\nGo now! Suffer well, <brother/sister>...",
        },
        [12637] = {
            description = "It was either wisdom or luck that prevented you from wearing this choker, " ..
                "<race>.\n\nEither way, your acquiring it was no random occurance. You've been targeted " ..
                "by someone, or something....\n\nTake your choker to Bloodrose, here. Let her demonstrate " ..
                "the fate that nearly befell you.",
            rewardMoney = 30000,
        },
        [12638] = {
            description = "It was either wisdom or luck that prevented you from wearing this choker, " ..
                "<race>.\n\nEither way, your acquiring it was no random occurence. You've been targeted " ..
                "by someone, or something....\n\nTake your choker to Bloodrose, here. Let her demonstrate " ..
                "the fate that nearly befell you.",
            rewardMoney = 30000,
        },
        [12639] = {
            description = "We captured these elementals from nearby, and I have plenty of defenders now. " ..
                "But, it takes a great deal of power to make them strong enough to stand up to our " ..
                "enemies.\n\nThe frozen earth at Drak'Mabwa to the northwest have what I need to maintain " ..
                "our defenses. I'll need more of their essence if I'm to keep this up.",
            rewardChoices = {{39772, 1}, {39783, 1}, {39835, 1}, {39786, 1}},
            rewardMoney = 65000,
        },
        [12640] = {
            description = "Dagoda gonna be sendin' you northwest to Drak'Mabwa to get her more stuff for " ..
                "her defenders if she didn't already.\n\nWhile you up there, Ahunae be wantin' you to " ..
                "destroy the rifts those elementals pourin' out of. The last thing we needin' is for them " ..
                "to attack us!\n\nJust watch out, more of those frozen earth'll show up when you try to " ..
                "seal the rifts.",
            rewardMoney = 65000,
        },
        [12641] = {
            description = "Towering above this platform is the eye of Acherus. From it you will call " ..
                "forth a probe that you will then use to analyze Scarlet Crusade fortifications at New " ..
                "Avalon. The eye has a host of powers that should make the acquisition of this data " ..
                "simple.\n\nUse the eye's siphon to analyze the forge, town hall, hold, and chapel. The " ..
                "eye's control mechanisms are located on either side of this platform. Waste no more " ..
                "time, <name>.\n\nThe Scourge will have this place. The Lich King commands it!",
        },
        [12642] = {
            description = "My feelings tell me that Rhunok doesn't have much time.\n\nI can tell that the " ..
                "arctic bear god's spirit has already separated from his weakened body. It is his spirit " ..
                "with which you must commune.\n\nHis altar lies to the northwest beyond Drak'Mabwa.",
        },
        [12643] = {
            description = "Once the Scourge have a target in their sights, they'll stop at nothing to " ..
                "acquire it.\n\nYou're doomed to a mindless existence as a walking " ..
                "corpse....\n\n<Stefan's face twists into a cruel grin.>\n\n... unless we can use their " ..
                "desires against them.\n\nI'll explain later. I have complex magic to prepare which " ..
                "requires certain material components.\n\nTravel due east of here to the land beneath the " ..
                "Reliquary of Agony. Slay the ghouls and abominations you'll find there and return to me " ..
                "with their remnants.",
            rewardMoney = 59000,
        },
        [12644] = {
            description = "Now that we've got the raw materials, I've had my assistant ready the still. " ..
                "He'll oversee the process, but I want you to help keep everything under control. You " ..
                "might be tempted to think that we just throw everything into the still and let it sit, " ..
                "but you're wrong.\n\nIngredients and heat need to be added at certain times, and the " ..
                "pressure regulated at others. You'll have no more than 10 seconds to react to a " ..
                "situation. Speak with \"Tipsy\" McManus when you're ready to start distilling.",
            rewardMoney = 48000,
        },
        [12646] = {
            description = "My prophet absorbed too much of my power too quickly, and subsequently killed " ..
                "himself. You can see the results at the water-filled crater to the south in " ..
                "Drak'Mabwa.\n\nMy former priests have already resurrected him so that he can finish the " ..
                "job. They're channeling my power back into him, and it will not be long now before he " ..
                "reawakens.\n\nYou must put an end to him and return with my mojo before it is too late.",
        },
        [12647] = {
            description = "My body is too far gone now, <name>. It is only a matter of time before a new " ..
                "prophet is elevated and finishes what the other began.\n\nI am going to imbue you with " ..
                "the last of my power. The tormentor inside the altar building carries incense, which " ..
                "will awaken my body and make it vulnerable.\n\nUse the incense and do me the kindness of " ..
                "putting an end to my suffering.\n\nI apologize if I fight back. Even for me, the will to " ..
                "survive is strong.",
            rewardChoices = {{39789, 1}, {39825, 1}, {39858, 1}, {39893, 1}},
        },
        [12648] = {
            description = "There... I've created a disguise that should make you indistinguishable from " ..
                "the Scourge.\n\nYou'll be free to walk among them as long as the disguise holds. Only " ..
                "the blightguards will be able to see through my illusion. Watch out for them!\n\nAnother " ..
                "thing you must know is that the disguise is unstable and may drop unexpectedly, so stay " ..
                "alert.\n\nLet's test it out. Use the choker and visit the Scourge merchant just east of " ..
                "here. Return to me with a bottle of bitter plasma.",
            rewardMoney = 46000,
        },
        [12649] = {
            description = "There... I've created a disguise that should make you indistinguishable from " ..
                "the Scourge.\n\nYou'll be free to walk among them as long as the disguise holds. Only " ..
                "the blightguards will be able to see through my illusion. Watch out for them!\n\nAnother " ..
                "thing you must know is that the disguise is unstable and may drop unexpectedly, so stay " ..
                "alert.\n\nLet's test it out. Use the choker and visit the Scourge vendor just east of " ..
                "here. Return to me with a bottle of bitter plasma.",
            rewardMoney = 46000,
        },
        [12650] = {
            description = "There is another altar nearby where there are artifacts to be saved.\n\nIt is " ..
                "said that the Drakkari at the Altar of Rhunok to the northwest, beyond the broken tundra " ..
                "of Drak'Mabwa, have already plundered their own holy site.\n\n<class>, I would be " ..
                "appreciative if you could rescue those artifacts from their undeserving hands.",
        },
        [12651] = {
            description = "When the trouble with the Venture Company started, I asked Marvin " ..
                "Wobblesprocket and his wife, Tamara, to take their flying machines east to River's " ..
                "Heart. I asked them to setup a small camp there so that we could use them as a relay to " ..
                "fly in supplies and survey the area.\n\nThey should have arrived by now and started " ..
                "setting up. River's Heart is near the center of the basin where the rivers converge. " ..
                "Search for Lakeshore Landing on the northeast shore. Marvin mentioned it would be the " ..
                "best spot.",
            rewardMoney = 6600,
        },
        [12653] = {
            description = "And now it is time for you to return to the leopard goddess. Somehow I sense " ..
                "that she has other plans for you.\n\nTell her that no matter what, we are eternal.",
        },
        [12654] = {
            description = "When Hemet asked me to accompany Marvin out here, I hoped that I might have " ..
                "the opportunity to work on my own hunting skills in between repairing the flying " ..
                "machines and setting up the camp.\n\nI wanted to take down a ferocious lion named Pitch. " ..
                "He's said to make his home south of here, near where the Wildgrowth Mangal meets the " ..
                "northern face of the Skyreach Pillar. If you can find the beast, would you bring back " ..
                "his remains? If the rumors are true, they'd make a trophy even Hemet will respect!",
            rewardMoney = 62000,
        },
        [12655] = {
            description = "There is another god of Zul'Drak that is being neglected.\n\nZim'Rhuk 's " ..
                "statue lies directly to the north. Known as \"The Wise One\", Zim'Rhuk is also known to " ..
                "be very protective of his domain. He maintains guardians that deal harshly with anyone " ..
                "that does not have the wits to slip past them.\n\nAvoid the guardians and give the " ..
                "Drakkari offerings to Zim'Rhuk so that you will benefit from his blessing.",
        },
        [12658] = {
            description = "Dorian's had me training and feeding the baby drakes he captures, and it has " ..
                "gotten me thinking. I want a pet of my own!\n\nNo, not a juvenile drake. I don't want a " ..
                "pet capable of biting my hand off!\n\nHowever, in the Bonefields to the northeast of the " ..
                "camp, beyond the area dominated by the drakes, there's a large population of goretalon " ..
                "rocs. The grown ones are beyond hope of domesticating, but if you bring me the eggs from " ..
                "their nests, I can raise them from the time they hatch.",
            rewardMoney = 65000,
        },
        [12659] = {
            description = "I thinkin' it be time to do some scalpin', mon!\n\nThe trolls at Heb'Drakkar " ..
                "to the northeast should do nicely. With their fancy bats and attackin' us, they got it " ..
                "comin'!\n\nAhunae even give you his own knife so that you do the job right.",
            rewardMoney = 65000,
        },
        [12660] = {
            description = "The Lich King's lackeys have dared to bring weapons of destruction into my " ..
                "domain. I will not stand for this.\n\nGo to their outpost to the north and destroy the " ..
                "weapons they would use against the land. We cannot let the Scourge taint another inch of " ..
                "these sacred lands.",
            rewardMoney = 65000,
        },
        [12661] = {
            description = "By now you've probably guessed the details of my plan.\n\nWe're using the " ..
                "Scourge's interest in you against them. You're going undercover. I know it's likely a " ..
                "death sentence, but if we do nothing your death is a certainty.\n\nTravel northeast to " ..
                "Reliquary of Pain and stand on the platform while wearing your disguise. Once inside " ..
                "Voltarus, you must earn the trust of the Scourge commander.\n\nWhen you've completed " ..
                "your mission, blow this horn and I'll fly to your location to receive your report.",
            rewardChoices = {{39809, 1}, {39830, 1}, {39866, 1}, {39869, 1}, {39870, 1}},
            rewardMoney = 59000,
        },
        [12663] = {
            description = "<name>!\n\nYa musta received mah gift! Turn around, mon, lemme get a good look " ..
                "at ya... Ahh, ya make me proud.\n\nWe come such a long way, you and I, and now we be " ..
                "servin' da Lich King together.\n\nStick with me and big things be comin, mon. Big " ..
                "things... but first, we need to be gettin' ya caught up. So much been happenin' since I " ..
                "saw ya last.\n\nGo speak ta Gorebag for a tour of Zul'Drak. Listen for me and I'll tell " ..
                "ya all ya be needin' ta know.",
        },
        [12664] = {
            description = "Ahh, another supplicant answerin' da Lich King's call.\n\n<Drakuru sniffs " ..
                "you.>\n\nFreshly scourged, eh? Ya still be reekin' of da living!\n\nLong be da line of " ..
                "dem who seek da Lich King's blessings. Ya must rise above da masses and prove yerself " ..
                "worthy of wieldin' true power.\n\nLookin' down over Zul'Drak, I sensed potential in ya. " ..
                "I ordered your - invitation.\n\nDa rest be up ta you....\n\nGo an' speak ta Gorebag for " ..
                "a tour of Zul'Drak. Dere be much ta do if you're to be of any worth to me.",
        },
        [12665] = {
            description = "There's something wrong with Quetz'lun, the wind serpent goddess. What it is " ..
                "exactly I cannot sense, but I do know that her altar has been overrun with powerful " ..
                "creatures.\n\nI'm going to send you there on the back of one of my children, which you " ..
                "saved. The two of you will move swiftly and with great stealth to uncover what has " ..
                "become of Quetz'lun.\n\nMy child will see you safely back to me. Just keep your eyes " ..
                "open.\n\nWhen you are ready, ask and I will call one of my kittens for you.",
        },
        [12666] = {
            description = "Quetz'lun may be dead, but I can still feel her spirit lingering in the " ..
                "underworld at the altar. We have to find a way to get you to her.\n\nLuckily for us, I " ..
                "just happen to have a supply of former supplicants at hand who are no longer in need of " ..
                "their sacred adornments. Both my subduers and claws are likely to still be wearing " ..
                "them.\n\nBring the adornments to me and I'll draw upon their energy to enable you to " ..
                "cross over into Quetz'lun's underworld nightmare.",
        },
        [12667] = {
            description = "You are prepared, but I'm not certain that you're ready for what is to " ..
                "come.\n\nWhen you cross back over into Quetz'lun's altar area, you will enter the realm " ..
                "of the dead. From what I can feel of it, it's not going to be pleasant.\n\nTry not to be " ..
                "distracted by what you see in there. Simply head for the altar building and seek out " ..
                "Quetz'lun's Spirit.",
        },
        [12668] = {
            description = "I have something special planned for my favorite high priests. But first you " ..
                "get to prove yourself in laying the foundation for my revenge.\n\nYou do still want to " ..
                "live, yes?\n\nAs you have seen, my devotees are enjoying their stay here, but now it's " ..
                "time for them to make final restitution.\n\nDo me the smallest of favors if you would, " ..
                "<name>. Lure them near my soul fonts and then put an end to their existences.\n\nThey " ..
                "taste so delicious, and their sacrifice will not go in vain, I can assure you.",
        },
        [12669] = {
            description = "Everything you've reported is consistent with what we know. Learning of " ..
                "Drakuru and earning his trust will lay the groundwork for your future " ..
                "missions.\n\nReturn to him and do as he says. Do whatever you must to appear sincere, " ..
                "<name>. A great deal is riding upon your performance.\n\nThis time I'm adding an " ..
                "additional assignment: While you're in the field, pour this additive into their blight " ..
                "cauldrons. It should neutralize the scourging agent and render the batch useless.",
            rewardChoices = {{39810, 1}, {39871, 1}, {39872, 1}, {39874, 1}},
            rewardMoney = 59000,
        },
        [12670] = {
            description = "Below Acherus stands Death's Breach, the staging point for our assault upon " ..
                "the Scarlet Crusade. You are to ride one of my Scourge gryphons, located on either side " ..
                "of this platform, and report to Prince Valanar. Do as he says and you may live to see " ..
                "these lands fall before us.",
        },
        [12671] = {
            description = "It's about time we had planes up and running in this place. The professor's " ..
                "been asking me to check out a strange weather pattern coming from the " ..
                "northeast.\n\nThing is, I'm going to need a co-pilot if we're going into uncharted " ..
                "territory. No way in hell I'm heading out there alone.\n\nWhat do you say, " ..
                "<tough-guy/hotshot>? You might learn a thing or two. And once you learn to deal with the " ..
                "northern winds... you can pretty much fly anywhere.",
            rewardMoney = 65000,
        },
        [12672] = {
            description = "I will give you a chance at continued existence.\n\nThere are fragments of the " ..
                "power that fueled my curse scattered about the altar grounds. It is my desire that you " ..
                "collect some of them for me. Not so many that the curse will be lifted, but enough that " ..
                "I will be able to eventually make use of them to exact revenge upon my prophet.\n\nGo, " ..
                "insect. Run and do my bidding before I change my mind about letting you live.",
        },
        [12673] = {
            description = "If ya ever gonna be worthy of da Lich King's gifts, ya must learn ta be a " ..
                "great leader - one who be commandin' respect!\n\nI got a task dat gonna refine your " ..
                "command skills, mon....\n\nSumma my minions be trained ta harvest blight crystals from " ..
                "da land below, but dey be lazy and slow. You gonna be in charge o' dem, mon.\n\nTake dis " ..
                "scepter and teach 'em how to get da job done. When dey be under your control, make 'em " ..
                "harvest dem crystals!",
            rewardMoney = 59000,
        },
        [12675] = {
            description = "There is one last thing that is needed to enact the final revenge against my " ..
                "prophet. The power fragments you collected must be imbued with a portion of a living " ..
                "gods' spirit. You're going to need to beseech Har'koa for some of hers.\n\nOnce you've " ..
                "done that, when you return here, you will not come to the underworld. Instead, you will " ..
                "return to the physical world of my altar. My children and guardians will no longer " ..
                "attack you, and you'll be able to get to my prophet without having to worry about them.",
        },
        [12677] = {
            description = "Blight crystals?! What could this scumbag Drakuru be up to? Clearly, he's " ..
                "working on something significant.\n\nContinue to do his bidding and perhaps once he's " ..
                "more familiar with you he'll reveal his plans. In the meantime, we need to have a look " ..
                "at these crystals.\n\nWhile you're in Voltarus, try to get some samples of the harvested " ..
                "crystals when no one's looking.\n\nBe alert! Handling those crystals can trigger your " ..
                "disguise to fail.",
            rewardMoney = 59000,
        },
        [12678] = {
            description = "They make their stand now, outside of Death's Breach, futilely attempting to " ..
                "push us back in hopes of saving their horses, mines, lumber and citizens.\n\nThis will " ..
                "be your first lesson in Scourge warfare: TERROR!\n\nGo to the front lines, south of " ..
                "here, and destroy Scarlet Crusaders. Leave their corpses so that we may utilize them for " ..
                "the death march.\n\nBut most importantly: kill the fleeing villagers. Soldiers dying are " ..
                "an affordance, but villagers? That is what strikes fear into the hearts of man.",
            rewardItems = {{38671, 1}},
            rewardMoney = 8500,
        },
        [12679] = {
            description = "The Sky Darkeners are mindless constructs with one purpose: KILL! " ..
                "Specifically, they are aiming to kill any man or woman that they see fleeing Havenshire " ..
                "for the safety of New Avalon. We certainly can't allow those cowards to make it to " ..
                "safety and then take up arms against us!\n\nThere is one slight problem. They use " ..
                "saronite arrows for maximum range and damage. Saronite, however, is a metal only found " ..
                "in Northrend, so supplies are limited! Retrieve those arrows for me and I will reward " ..
                "you handsomely.",
            rewardChoices = {{38664, 1}, {39320, 1}, {39322, 1}},
            rewardMoney = 8500,
        },
        [12680] = {
            description = "How fortuitous it is that the Crusade has a stable full of horses a mere " ..
                "stone's throw from this post. Though they guard it tenaciously, an enterprising young " ..
                "death knight could break through their defenses and take what is rightfully " ..
                "<his/hers>!\n\nOnce you acquire a horse from the Havenshire Stables, return it to me and " ..
                "I will see what can be done about transforming it into a proper " ..
                "deathcharger.\n\nRemember, <name>, it's only stealing if you're caught. Watch out for " ..
                "that deranged stable master, Kitrik!",
            rewardMoney = 8500,
        },
        [12683] = {
            description = "There's no more caustic material in all of the basin than bittertide hydra " ..
                "sputum. I've got special containers to collect just such a thing for Archmage Pentarus' " ..
                "studies. Now all I need is a brave, um... collector.\n\nYou look like a hardy, " ..
                "adventurous <class>. How'd you like to make a bit of money and aid Dalaran's cause at " ..
                "the same time?\n\nAll you need to do is take this container with you to Bittertide Lake, " ..
                "to the southwest. Engage the hydra and use the container to sample the sputum they " ..
                "shower you with.",
            rewardMoney = 65000,
        },
        [12684] = {
            description = "Mam'toth, the god of the mammoths, destroyed himself, and took much of his " ..
                "temple with him, rather than allowing his trolls to gain his power.\n\nIf I'm to " ..
                "sacrifice a portion of my spirit, I will need something with which to bolster " ..
                "myself.\n\nMam'toth left behind an enormous crater to the northeast, just north of the " ..
                "Altar of Quetz'lun. Within the crater his blood yet lives.\n\nBring it to me.",
        },
        [12685] = {
            description = "This is what it has come down to... revenge.\n\n< Har'koa sighs.>\n\nTake this " ..
                "ritual kit and enact it near Quetz'lun's corpse upon her altar. If everything works " ..
                "properly, her spirit should be drawn into the material world where she will be able to " ..
                "reclaim her power from the prophet.\n\nThe rest will be up to you, <name>. You must slay " ..
                "the prophet in his drained state.",
            rewardChoices = {{39826, 1}, {39844, 1}, {39845, 1}, {39861, 1}, {39793, 1}},
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [12686] = {
            description = "Ignorance! Dis be intolerable, mon! My entire batch of blight be " ..
                "useless!\n\nDat mongrel, Darmuk! He be responsible for watchin over da blight. He failed " ..
                "me, mon!\n\nDis be a good lesson for ya, <name>. Failure be like a disease dat spreads. " ..
                "Ya gotta catch it and kill it early, before it be killin' you!\n\nTake dis scepter. It " ..
                "make my scourged trolls stronger. Use dem ta kill Darmuk. He be lurkin' down below just " ..
                "to da south.\n\nLet dat be an example to all, mon. Don't be failin' Drakuru!",
            rewardMoney = 30000,
        },
        [12687] = {rewardMoney = 8500},
        [12688] = {
            description = "These goblin goons and their minions have decided that they own this pillar " ..
                "and its crystals. I came here to explore the crystals and take samples, but they " ..
                "overpowered me and won't let me return to the camp.\n\nIf you'll help me fight our way " ..
                "out of here, we can teach these thugs a lesson they'll never forget!",
            rewardMoney = 62000,
        },
        [12689] = {rewardMoney = 33000},
        [12690] = {
            description = "It be time we start our march to Gundrak, mon. It be time for me ta turn ya " ..
                "loose on dem trolls!\n\nDey breached our wall and put a whole army just north of " ..
                "us.\n\nHahaha!\n\nDey be fuel for da fire, mon! We gunna take da chieftiains an' kill da " ..
                "rest! It all be part of my master plan....\n\nYou take dis scepter and go command my " ..
                "abominations. Bring 'em to da Drakkari army and kill em all! When da chieftains come, my " ..
                "pet Shalewing gunna snatch 'em up and bring 'em here to me.",
            rewardMoney = 59000,
        },
        [12692] = {
            description = "Okay, I going back to Frenzyheart Hill to make sure all Frenzyheart know what " ..
                "you done for wolvar and for Zepik. You great hunter and they dumb to think you " ..
                "not.\n\nGo back to hill and talk to Elder Harkek... I make sure he knows you not traitor " ..
                "before any other Frenzyheart.\n\nThank you, Lich Hunter.",
            rewardMoney = 33000,
        },
        [12695] = {
            description = "Yay! Soo-say probably worrying about us! Maybe you go back to town and tell " ..
                "him everything okay? Yeah, go tell Soo-say.\n\nI going grab shiny ball thing from dead " ..
                "lich guy - I meet you there! Go go! I meet you there!",
            rewardMoney = 33000,
        },
        [12696] = {
            description = "You did a good job helping Wes with getting that flying machine back up and " ..
                "running.\n\nIf you'd like to help us further, there is an unusual weather pattern coming " ..
                "in from the northeast. I have a pilot ready to work for me, but I'm afraid he needs a " ..
                "copilot.\n\nIf you think you're up to it, you can take the flight to Lakeside Landing. " ..
                "Tell Vic I sent you.",
        },
        [12697] = {
            description = "CHAOS, <name>! The Crusade is in a frenzy. They have diverted all forces " ..
                "outside of New Avalon to set up a blockade at Light's Point, east of here. They are " ..
                "desperately trying to strip the Havenshire Mine of all resources and load the cargo " ..
                "aboard the frigates they have docked on the coast.\n\nLet's stir things up a bit, shall " ..
                "we? Gothik the Harvester, grand necromancer of the Lich King, has graced us with his " ..
                "presence. He has a gift he'd like to bestow upon the Scarlet Crusade. Seek him out.",
        },
        [12699] = {
            description = "There's one little problem we have to solve before we head out. You see, I " ..
                "can't seem to find the keys to my flying machine.\n\nI've looked pretty much everywhere " ..
                "for them... maybe you can give me a hand. Only place I haven't looked yet is inside the " ..
                "lake.\n\nI'll even give you my very own air tank. It's almost empty, but it's got a " ..
                "couple of hits left.",
            rewardMoney = 65000,
        },
        [12700] = {
            description = "Only the Scarlet forces at New Avalon and Light's Point challenge us! The time " ..
                "to attack the Scarlet fleet at Light's Point has come.\n\nThe diversion at the mine has " ..
                "caused chaos amidst their ranks. They are frantically working to clear the area and " ..
                "return to their ships.\n\nThe time is ripe! Prince Valanar is seizing this opportunity " ..
                "to finish off the Scarlet fleet. Report to him at once!",
        },
        [12702] = {
            description = "I bet you not guess what happen again.\n\nNope, not Goregek or " ..
                "chickens.\n\nOkay, I lie. Goregek let chickens out again. Dumb Goregek and rumbly " ..
                "belly.\n\nLet me know if you need help from any of the hunters... they around here " ..
                "somewhere.",
            rewardMoney = 65000,
        },
        [12703] = {
            description = "You the great Lich Hunter, eh? Good to have such strong Frenzyheart ally for " ..
                "battle. Maybe you strong enough to call Kartak even.\n\nBig battle at Kartak's Hold to " ..
                "southwest. Go kill spark big-tongues until you get good bit of Oracle Blood. Bring blood " ..
                "to altar in Kartak's Hold to call Kartak for delicious feast of big-tongue.\n\nKartak " ..
                "take your body if you worthy... with Kartak's powers, you slaughter more big-tongues " ..
                "than even best dreams.\n\nGo kill lots, hunter!",
            rewardMoney = 136000,
        },
        [12704] = {
            description = "Since mosswalker been attacked I worried maybe we not good to Great Rain " ..
                "Stone... we maybe too greedy. We need more treasures to offer!\n\nYou good at finding " ..
                "shinies last time... maybe you go look more around village for shinies? You maybe need " ..
                "one of good Rainspeakers for help. Just tell us who.",
            rewardMoney = 65000,
        },
        [12705] = {
            description = "Puppy-men been attacking Sparktouched... we need fight or they just attack " ..
                "other Oracles too.\n\nYou been good friend to us, so maybe we allow you special honor. " ..
                "Great Ones left protector long time ago for shrines... it here still, but it not know " ..
                "something wrong til shrines messed with.\n\nPuppy-men down there have bad crystals for " ..
                "making trouble... bring a bad crystal to Lightning Shrine so Soo-holu know to " ..
                "help.\n\nDon't be scared if Soo-holu take your body... he very powerful, so he keep you " ..
                "safe.",
            rewardMoney = 136000,
        },
        [12706] = {
            description = "< Prince Valanar hands you a sealed scroll.>\n\nThis is the full report of our " ..
                "victory at Death's Breach. You are to deliver this to Highlord Mograine - inside " ..
                "Acherus. I have made sure to include your heroics in the report. Mograine will " ..
                "undoubtedly reward you greatly for this victory, <name>.\n\nGo now!",
            rewardItems = {{38669, 1}},
            rewardMoney = 8500,
        },
        [12707] = {
            description = "Ahunae hear about your trip to Mam'toth Crater, mon. The children of Mam'toth " ..
                "are enraged and cry out for justice!\n\nFollow the avenue northeast up the steps to the " ..
                "next tier of Zul'Drak. On your right you will find what's left of the Altar of " ..
                "Mam'toth.\n\nWhen you get there, flash this Medallion of Mam'toth in front of the eyes " ..
                "of one of the enraged mammoths. It'll calm down for a little while, letting you hop on " ..
                "its back.\n\nRide it around, trampling all of the Mam'toth disciples that you can find!",
            rewardChoices = {{39770, 1}, {39776, 1}, {39778, 1}, {39818, 1}, {39833, 1}},
            rewardMoney = 65000,
        },
        [12708] = {
            description = "I know that you're headed up to the Zol'Maz Stronghold to the northeast, " ..
                "<class>. While you're there, I need you to deal with the warlord's special " ..
                "guardians.\n\nThe enchanted tiki warriors, as they're called, represent a very real " ..
                "threat. If the Drakkari were to mass produce them, we'd quickly be overrun.\n\nLet's you " ..
                "and I demonstrate that they're not worth the effort to create, shall we?",
        },
        [12710] = {
            description = "Ya doin' well, <name>.\n\nYou be provin' dat I got an eye for talent! Now ya " ..
                "see why da Lich King gave me his blessing....\n\nDa time has come for me to reveal my " ..
                "master plan to ya, mon.\n\nNow you be seein' how we gunna sweep through da swarms of " ..
                "Drakkari trolls to take our rightful place in da great palace of Gundrak.\n\nTake dis " ..
                "scepter, mon. It be a token of my trust in ya. With it, you be able ta access my upper " ..
                "chamber and witness for yourself our secret weapons.",
            rewardMoney = 30000,
        },
        [12712] = {
            description = "<name>, we need a key to unlock the chains of the rhino god, Akali. Even now " ..
                "he is being prepared for the slaughter.\n\nThe Drakkari warlord, Zol'Maz, carries the " ..
                "key. Hearing of your exploits, he has secluded himself and his family at their " ..
                "stronghold up the steps to the northeast.\n\nThe warlord is strong and you will need " ..
                "help. If you were to combine the tiki, sword and incantation of his family members, you " ..
                "would be able to summon such help as you challenge him before his home's gate.",
        },
        [12714] = {
            description = "It is the will of the Lich King that drives us onward, <name>. None are more " ..
                "aware of this than death knights. Our very existence is intrinsically tied to his " ..
                "consciousness. Surely you have heard him speak to you - invading your thoughts...\n\nCan " ..
                "you hear him now? Perhaps it is too early for you.\n\n<Mograine closes his eyes and nods " ..
                "to an unseen host.>\n\nYes, my lord. It will be done.\n\n<name>, you are to return to " ..
                "Death's Breach and report to Prince Valanar. The Lich King commands it!",
        },
        [12715] = {
            description = "The attacks upon the gates of the last Scarlet bastion have begun. Our ghouls " ..
                "are wearing the Crusade's front lines down while we labor to fortify our new forward " ..
                "base, the Crypt of Remembrance.\n\nVenture south to the crypt, which borders New Avalon, " ..
                "and report to my dear brother, Prince Keleseth.\n\nHe will be expecting you.\n\nPrepare " ..
                "yourself, <name>, for you are about to witness the next stage of Scourge warfare: " ..
                "DOMINATION!\n\nRide now, death knight!",
        },
        [12716] = {
            description = "Look at this pumpkin patch! Notice anything missing? Of course you don't, " ..
                "because you're a moron! Your brain was probably the first thing to die.\n\n<Noth " ..
                "sighs.>\n\nI have been commanded to put together a plague cauldron. You will help " ..
                "me.\n\nDirectly inside the gate of New Avalon is the inn. Enter the inn and steal an " ..
                "empty cauldron. Then go to the forge, also near the gate, and steal some iron chains. " ..
                "Bring those back to me along with 10 Crusader skulls. Do I need to tell you where to get " ..
                "those too?",
            rewardItems = {{38668, 1}},
            rewardMoney = 8500,
        },
        [12718] = {rewardItems = {{39327, 5}}},
        [12719] = {
            description = "Nothing less than total annihilation will suffice, <name>. To that end, a few " ..
                "hundred mindless ghouls assaulting the front gate of New Avalon will not do. We must " ..
                "infiltrate the inner sanctum and dispose of their officials. They must be shown that no " ..
                "one can escape the Scourge's grasp!\n\nMake your way to the New Avalon Town Hall, " ..
                "southwest of here, and assassinate the mayor. Search the building for the New Avalon " ..
                "registry and bring it to me.",
            rewardMoney = 8500,
        },
        [12723] = {
            description = "I have sent Orbaz, Thassarian and Koltira behind enemy lines to search for the " ..
                "courier. They have set up a base of operations at the Scarlet Tavern, located at the " ..
                "southern end of New Avalon. The tavern is tucked away behind the two orchards, adjacent " ..
                "to the Chapel of the Crimson Flame. You are to make your way to the tavern and report to " ..
                "Orbaz Bloodbane. He will update you on their situation.",
        },
        [12725] = {
            description = "Breaking through the Scarlet lines was no easy task. We suffered many " ..
                "casualties during the assault and lost one of our best death knights, Koltira " ..
                "Deathweaver. I don't know whether he's dead or alive, but I'll be damned if we don't " ..
                "search for him.\n\nI last saw him being bound in irons and dragged away to the Scarlet " ..
                "Hold, northeast of here. Tear that keep asunder, death knight. Find Koltira!",
        },
        [12726] = {
            description = "Listen to storm, yes? The Stormwright's Shelf echoes with ancient song.... the " ..
                "Song of Wind and Water.\n\nThe great tempest devours the sons of typhoons and storms. " ..
                "Take this drum and play his song... play Haiphoon's song.\n\nHelp him feed on wind and " ..
                "water so tempest can continue.",
            rewardMoney = 74000,
        },
        [12727] = {
            description = "The alarms have been sounded. The High Inquisitor and his acolytes will be " ..
                "here soon. I'm too badly injured to be of much use, but I'll do what little I can to " ..
                "help.\n\nSlay the High Inquisitor and his cronies. Tear off his head and return with it " ..
                "to Thassarian. Vengeance will soothe his savage soul.\n\nOne more thing, <name>. If you " ..
                "do manage to survive and make it back to Thassarian, tell him that they're executing " ..
                "prisoners at the chapel. Perhaps he'll send you there to play the hero once more.",
            rewardItems = {{38665, 1}},
            rewardMoney = 16500,
        },
        [12729] = {
            description = "The gods have spoken and we must heed their wisdom.\n\nTravel north to " ..
                "Zim'Rhuk to destroy guardians there until they yield the unblemished heart. Travel east " ..
                "to the Altar of Quetz'lun and disrupt the altar wardens until you recover their gusty " ..
                "essence.\n\nDeliver both to Har'koa and she will combine them into that which will " ..
                "compel late Akali's prophet to appear.",
            rewardItems = {{199210, 1, "Northrend Adventuring Supplies"}},
        },
        [12732] = {
            description = "One day, Rejek will be mighty warrior. Blood and skyfire will make Rejek " ..
                "strong. You see soon.\n\nRejek give you vial, you take to very top of Suntouched Pillar, " ..
                "far to west. Put waters there in vial.\n\nThen go to north edge of basin, to ledge north " ..
                "of Bonefields. You find and kill goretalon matriarch. Take heartblood.\n\nYou combine " ..
                "heartblood and water, bring to Rejek. Rejek drink, make strong.",
            rewardMoney = 74000,
        },
        [12733] = {
            description = "Born of the Lich King's victory over Illidan Stormrage in the heart of the " ..
                "frozen wastes, Death's Challenge is a rite of passage that all death knights must " ..
                "undergo.\n\nSeek out other death knights of Acherus and challenge them to a duel. They " ..
                "must accept and fight until a victor emerges!\n\nGo now, <name>! Victory for the " ..
                "Scourge! Glory to the Lich King!",
            rewardItems = {{40483, 1}},
            rewardMoney = 25000,
        },
        [12734] = {
            description = "Rejek just became youngest warrior in all of Frenzyheart tribe. Father gave " ..
                "Rejek a mighty sword to defeat Frenzyheart enemies, but old tradition say sword need to " ..
                "be blooded first. Older warrior usually do that. You do this honor for Rejek?\n\nTake " ..
                "blade, put in corpses of all Frenzyheart foes: wasps and hardknuckles to southwest, and " ..
                "the big-tongues. Maybe blood blade on Mistwhispers, far to northwest near Bittertide " ..
                "Lake.",
            rewardMoney = 74000,
        },
        [12735] = {
            description = "Earth in Sholazar is pure. The pillars have protected the land for " ..
                "centuries.\n\nWater, not as pure, it comes from outside Sholazar.... from oceans, from " ..
                "lakes, from rivers. Water sometimes bring bad spirits - need to be cleansed.\n\nYou take " ..
                "this chime and play at Bittertide Lake, Wintergrasp River and River's Heart. It make bad " ..
                "spirit angry... and then you must kill it.",
            rewardMoney = 74000,
        },
        [12736] = {
            description = "Of course you not as smart as gorloc! You just simple <race>.\n\nYou not " ..
                "without hope, though! You show you can learn. Maybe crystals make you smart like " ..
                "crystals make us smart!\n\nI teach you to play song to clear your mind. You play song by " ..
                "crystals then crystals make your mind better... not as good as gorloc's but better than " ..
                "you have now. Lifeblood Pillar is broken, but other pillars still good!",
            rewardMoney = 74000,
        },
        [12737] = {
            description = "The storm is a destructive force. Storm burns trees. Storm floods " ..
                "houses.\n\nBut storm can also be life force if you know right song. In Stormwright " ..
                "Shelf, above Maker's Perch, you can find small dirt mounds. They very fertile -- they " ..
                "carry inside a strong seed. All they wait for is the right song.\n\nYou take this horn " ..
                "and play song for them.",
            rewardMoney = 74000,
        },
        [12738] = {
            description = "The cry for vengeance must be heard, <name>. Commander Plaguefist and a " ..
                "company of death knights are on their way to raze the Chapel of the Crimson Flame. If " ..
                "there are any death knights imprisoned at the chapel, Plaguefist will get them " ..
                "out.\n\nYou can still catch up to them if you hurry. The chapel is due west of here.",
        },
        [12739] = {
            description = "We got here, tore the place apart, and headed toward the prison house. We " ..
                "weren't expecting what we found in there, <name>. Seems the Crusade's been real busy. " ..
                "That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the " ..
                "time we arrived, but a few were still breathing.\n\nI was about to go in there and " ..
                "execute the rest of them, but I think you should have the honors. In particular, there's " ..
                "a real feisty tauren in there that I think you'll take great pleasure in executing.",
            rewardMoney = 8500,
        },
        [12741] = {
            description = "Silly big-tongues think singing to the clouds give them power. Rejek show " ..
                "big-tongues how to get power by taking it!\n\nFar to northwest, there is large, flat " ..
                "area the big-tongues call 'Stormwright's Shelf.' Rejek is sure you can only get there by " ..
                "flying like bird.\n\nOn this shelf, Rejek has heard of mighty forces of wind and water. " ..
                "Kill them for their badness, then take it to the big-tongue 'Shrine of the Tempest' at " ..
                "shelf's western side. Rejek will await your return with ultimate power.",
            rewardMoney = 74000,
        },
        [12742] = {
            description = "We got here, tore the place apart, and headed toward the prison house. We " ..
                "weren't expecting what we found in there, <name>. Seems the Crusade's been real busy. " ..
                "That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the " ..
                "time we arrived, but a few were still breathing.\n\nI was about to go in there and " ..
                "execute the rest of them, but I think you should have the honors. In particular, there's " ..
                "a real feisty human in there that I think you'll take great pleasure in executing.",
            rewardMoney = 8500,
        },
        [12743] = {
            description = "We got here, tore the place apart, and headed toward the prison house. We " ..
                "weren't expecting what we found in there, <name>. Seems the Crusade's been real busy. " ..
                "That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the " ..
                "time we arrived, but a few were still breathing.\n\nI was about to go in there and " ..
                "execute the rest of them, but I think you should have the honors. In particular, there's " ..
                "a real feisty night elf in there that I think you'll take great pleasure in executing.",
            rewardMoney = 8500,
        },
        [12744] = {
            description = "We got here, tore the place apart, and headed toward the prison house. We " ..
                "weren't expecting what we found in there, <name>. Seems the Crusade's been real busy. " ..
                "That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the " ..
                "time we arrived, but a few were still breathing.\n\nI was about to go in there and " ..
                "execute the rest of them, but I think you should have the honors. In particular, there's " ..
                "a real feisty dwarf in there that I think you'll take great pleasure in executing.",
            rewardMoney = 8500,
        },
        [12745] = {
