        [28795] = {
            description = "Have you ever seen a goblin, <name>? They're wretched little green-skinned " ..
                "monsters that love only two things: gold and themselves.\n\nThe Blackrock orcs have " ..
                "enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in " ..
                "the north you can barely make out their silhouettes, sneaking about in the grass.\n\nI " ..
                "need you to head out there and kill every goblin that you see. They need to learn that " ..
                "nobody messes with the Alliance!",
            rewardItems = {{2186, 1}},
            rewardMoney = 50,
        },
        [28803] = {rewardMoney = 114000},
        [28808] = {
            description = "Have you embraced the Holy Light yet, <brother/sister>? It is through the Holy " ..
                "Light that we are saved! It is through the Holy Light that I am able to heal these " ..
                "overly demanding soldiers! And it is through the Holy Light that you will be able to " ..
                "venture out into the field to the north and rescue our fallen brothers!\n\nTake this " ..
                "prayer book with you into the field and cast the Light's healing touch on the injured.",
            rewardItems = {{57256, 1}},
            rewardMoney = 50,
        },
        [28812] = {
            description = "Have you embraced the Holy Light yet, <brother/sister>? It is through the Holy " ..
                "Light that we are saved! It is through the Holy Light that I am able to heal these " ..
                "overly demanding soldiers! And it is through the Holy Light that you will be able to " ..
                "venture out into the field to the north and rescue our fallen brothers!\n\nTake this " ..
                "prayer book with you into the field and cast the Light's healing touch on the injured.",
            rewardItems = {{57256, 1}},
            rewardMoney = 50,
        },
        [28814] = {
            description = "The documents detail the arrival of High Priestess Azil to the depths of the " ..
                "Stonecore.\n\nAzil is described as a high-ranking member of the Twilight Council. " ..
                "Additionally, her entourage of over a hundred devout followers is preparing for an " ..
                "unholy ritual of unforeseen darkness.\n\nSounds like an event you need to put a stop to.",
            rewardChoices = {{66891, 1}, {66892, 1}, {66893, 1}},
            rewardMoney = 360000,
        },
        [28816] = {
            description = "The Earthen Ring has identified the watery realm of Vashj'ir as a source of " ..
                "the adversary's destructive energies.\n\nIt is still uncertain what dangers might be " ..
                "faced there. Any information you could gather would be of great value.\n\nThe Horde is " ..
                "sending warships to the region as we speak. To gain passage, speak to Commander Thorak " ..
                "at Bladefist Bay.\n\nMay the spirits guide you, <name>.",
        },
        [28817] = {
            description = "Excellent work, <name>! The rear is now officially clear. We'll take care of " ..
                "the stragglers. I want you to go back to Marshal McBride, standing in front of " ..
                "Northshire Abbey, south of here, and let him know that the goblin situation is under " ..
                "control.\n\nFarewell, <class>.",
            rewardMoney = 7,
        },
        [28820] = {
            description = "Excellent work, <name>! The rear is now officially clear. We'll take care of " ..
                "the stragglers. I want you to go back to Marshal McBride, standing in front of " ..
                "Northshire Abbey, south of here, and let him know that the goblin situation is under " ..
                "control.\n\nFarewell, <class>.",
            rewardMoney = 7,
        },
        [28821] = {
            description = "Excellent work, <name>! The rear is now officially clear. We'll take care of " ..
                "the stragglers. I want you to go back to Marshal McBride, standing in front of " ..
                "Northshire Abbey, south of here, and let him know that the goblin situation is under " ..
                "control.\n\nFarewell, <class>.",
            rewardMoney = 7,
        },
        [28822] = {
            description = "Excellent work, <name>! The rear is now officially clear. We'll take care of " ..
                "the stragglers. I want you to go back to Marshal McBride, standing in front of " ..
                "Northshire Abbey, south of here, and let him know that the goblin situation is under " ..
                "control.\n\nFarewell, <class>.",
            rewardMoney = 7,
        },
        [28823] = {
            description = "Excellent work, <name>! The rear is now officially clear. We'll take care of " ..
                "the stragglers. I want you to go back to Marshal McBride, standing in front of " ..
                "Northshire Abbey, south of here, and let him know that the goblin situation is under " ..
                "control.\n\nFarewell, <class>.",
            rewardMoney = 7,
        },
        [28825] = {
            description = "<An unfamiliar feeling wells up from deep within you, flooding your mind with " ..
                "thoughts and images.>\n\nHear my words, <name>.\n\nOur world finds itself in the grip of " ..
                "a terrible crisis.\n\nI call upon you to lend your aid in this desperate hour.\n\nI am " ..
                "Naraat.\n\nSeek me out at once, and your calling shall be revealed.\n\nI await you at " ..
                "the Eastern Earthshrine in Stormwind City.",
        },
        [28826] = {
            description = "Greetings, hero of Azeroth.\n\nWe of the Earthen Ring know you by name, " ..
                "<name>.\n\nYour exploits and accomplishments are many. Azeroth already stands in your " ..
                "debt, and yet again she is in need of her heroes.\n\nI am but a messenger. A powerful " ..
                "presence seeks audience with you.\n\nPeer into the Waters of Farseeing and behold the " ..
                "dilemma of our world.",
        },
        [28828] = {
            description = "I don't have a very discerning palate, but even I can't stand the taste of " ..
                "those chimaeras that you'll find around here. Their eggs, however, are a different " ..
                "story.\n\nChimaera eggs are the richest, most buttery eggs you'll find this side of " ..
                "Orgrimmar. Way better than boring owl eggs, and not as sulfurous as those weird wildkin " ..
                "eggs.\n\nI'll take as many of them as you can gather. Head northeast, and look for their " ..
                "nests in the snow.",
            rewardChoices = {{67170, 1}, {67187, 1}, {67204, 1}, {67220, 1}, {67227, 1}},
            rewardItems = {{67273, 1}},
            rewardMoney = 8000,
        },
        [28829] = {
            description = "What happened to me, you ask? Listen, <class>, and listen well, for my tale is " ..
                "one of tragedy...\n\nI was sent here to Owl Wing Thicket to find some relics. I only " ..
                "made it this far before I was overwhelmed by a flurry of wings and talons.\n\nHow they " ..
                "roared and pecked, <class>!\n\nI now lay here, a broken orc, with nothing but vengeance " ..
                "on my mind. Please, <class>, if you have any sense of honor, you will go into Owl Wing " ..
                "Thicket and help me regain mine.",
            rewardMoney = 8000,
        },
        [28830] = {
            description = "My mysterious benefactors gave me more than one task. The second task took me " ..
                "farther south, to the Frostwhisper Gorge. I was surprised to learn that the gorge's " ..
                "bridge had been broken in two, preventing land travel from one side to the other.\n\nIn " ..
                "addition, the juvenile Frostmaul tumblers were separated from their stronger adult " ..
                "parents. I thought that I could defeat them in battle.\n\nI was incorrect. I was forced " ..
                "to run away in shame.\n\nTeach these tumblers a lesson, <name>. Fight them, and win.",
            rewardMoney = 8000,
        },
        [28831] = {
            description = "The Frostmaul giants wouldn't have been a problem if it weren't for that " ..
                "damned Frostilicus. When the ground shook and the bridge broke, he and his fellow water " ..
                "elementals seeped out of the earth and took over the bottom of Frostwhisper Gorge, " ..
                "forcing the giants out.\n\nDamn you, Frostilicus!\n\nYou would do me a great honor if " ..
                "you would send him back into the ground, <class>. You will find him to the south, at the " ..
                "bottom of the gorge.",
            rewardChoices = {{67172, 1}, {67189, 1}, {67206, 1}, {67221, 1}},
            rewardMoney = 8000,
        },
        [28834] = {
            description = "Good! You've brought allies.\n\nYou must hurry if we are to rescue " ..
                "Erunak.\n\nGo now. Fight your way through Neptulon's halls. Find the shaman and free him " ..
                "from these worms... if he still lives.\n\nDon't worry about them coming up from behind " ..
                "you. I'll see that nothing makes it past me!",
            rewardChoices = {{65654, 1}, {65655, 1}, {65656, 1}},
            rewardMoney = 328000,
        },
        [28836] = {
            description = "That vile worm has earned a thousand deaths!\n\nIt won't be easy. She and her " ..
                "minions are firmly entrenched in this place, but she's bound to be exhausted from her " ..
                "fight with Neptulon.\n\nNow is the time to strike! We won't have another opportunity " ..
                "like this.\n\nRun her through, <name>!",
            rewardChoices = {{65657, 1}, {65658, 1}, {65659, 1}},
            rewardMoney = 328000,
        },
        [28837] = {
            description = "We, the blue dragons, have been forced out of our home, Mazthoril. An impostor " ..
                "by the name of Umbranse has taken advantage of us in our weakest hour, and now occupies " ..
                "the cave.\n\nMazthoril is a place of extremely potent magic, and he does not know how to " ..
                "wield it. Even the wildlife suffers.\n\nThe beasts nearby have been altered. Please, " ..
                "<race>, I must ask you a favor. Gather their brains, so I can see if I can undo this " ..
                "Umbranse's wild magic.",
            rewardMoney = 8000,
        },
        [28838] = {
            description = "What a shame. Whatever Umbranse has done, he has prevented me from undoing his " ..
                "magic.\n\nHe is wiser than I had anticipated.\n\nI do have a backup plan, however. I " ..
                "have seen owlbeasts enter and leave Mazthoril, even after Umbranse took control. Their " ..
                "ancient druidic magic must be capable of disabling Umbranse's. Luckily, I happen to be " ..
                "somewhat of an expert in their methods.\n\nTravel south, to Dun Mandarr. You will find a " ..
                "chest with a dreamcatcher in it.\n\nThat will be your first step.",
        },
        [28839] = {
            description = "The owlbeasts' sacred caves are located to the east. Within several of these " ..
                "caves, you should find totems. I want you to approach these totems and gather whatever " ..
                "essence you can from them. The dreamcatcher should absorb this essence for use within " ..
                "Mazthoril.",
        },
        [28840] = {
            description = "I don't want our gambit to fail, <name>. Such a failure would only draw " ..
                "attention to our efforts, giving Umbranse an opportunity to hone his defenses. No, we " ..
                "have to do this right the first time.\n\nThe Frostwhisper Gorge, to the south, provides " ..
                "us access to powerful ice elementals. The water within these elementals' hulls should " ..
                "amplify the power of your dreamcatcher, ensuring our efforts.\n\nObtain this water, " ..
                "<name>. Then return to our small camp.",
            rewardChoices = {{67173, 1}, {67190, 1}, {67207, 1}},
        },
        [28841] = {
            description = "Mazthoril's innate magic can wreak unimaginable havoc if mishandled. " ..
                "Umbranse's wanton casting within the cavern has opened up a number of tesseracts - in " ..
                "other words, portals - connecting to other worlds. If I am to return to Mazthoril, these " ..
                "tesseracts must be closed.\n\nThe dreamcatcher will close the portals, buying you safe " ..
                "entrance into Umbranse's lair. First defeat whatever comes out of the tesseracts, then " ..
                "use the dreamcatcher to quickly close them, before anything else spills into this world.",
            rewardMoney = 8500,
        },
        [28842] = {
            description = "Umbranse lurks in the back of Mazthoril. His time has come.\n\nUnfortunately, " ..
                "I am unable to join you on this quest. While I'd love to get my hands on that snake, " ..
                "Mazthoril's magic would rip me apart in its current state. No, I need you to finish this " ..
                "for me.\n\nWhen the deed is done, use this charm. It will return you safely to the " ..
                "egress.",
            rewardChoices = {{67174, 1}, {67191, 1}, {67208, 1}, {67222, 1}},
            rewardMoney = 16500,
        },
        [28845] = {
            description = "One of our civilian leaders was taken prisoner by the air elementals.\n\nThey " ..
                "are probably torturing him for information as we speak.\n\nGo to the Vortex Pinnacle, " ..
                "where these foul creatures came from, and look for Itesh.\n\nYou will find the entrance " ..
                "to the Vortex Pinnacle hovering off of the southeastern coast of Uldum.",
            rewardMoney = 9000,
        },
        [28847] = {
            description = "We have isolated Umbranse's position here in Winterspring. It is as I " ..
                "suspected.\n\nUmbranse is at Mazthoril, the cavern that once belonged to the blue " ..
                "dragonflight, in the southwest. My mother, Haleh, will greet you there. She is stationed " ..
                "outside of the cave in a small camp with a few other survivors.\n\nLook for her campfire.",
            rewardMoney = 800,
        },
        [28848] = {
            description = "I have heard tales of Umbranse, though I have not ever met him in person. " ..
                "Rumor has it that he's been collecting magical artifacts, though for what purpose, I " ..
                "couldn't say.\n\nBest pass this information on to a trusted ally. Nymn, the high elf, " ..
                "can be found within Everlook, the large goblin town to the northeast. Tell him all that " ..
                "we learned today.",
            rewardMoney = 800,
        },
        [28852] = {
            description = "At last, reinforcements! I'm so glad you're here. We never imagined just how " ..
                "entrenched the Twilight's Hammer forces are. And there are so many!\n\nSeveral of our " ..
                "drakes have been captured just inside the main hall. Please, break their bonds and free " ..
                "them.\n\nOnce free, together we can scourge these halls clean with flame. Just climb " ..
                "aboard a red drake and call out your targets. You will definitely want to cut down the " ..
                "enemy numbers before delving deeper into the ruins.",
            rewardItems = {{66943, 1}},
        },
        [28853] = {
            description = "Thank you, <class>, for braving the horrors of this dark and terrible " ..
                "place.\n\nThe bowels of Grim Batol are the heart of Cho'gall's war machine. If we are to " ..
                "stop his machinations throughout the Highlands, we must learn all we can from these " ..
                "depths.\n\nSeek out Drahga Shadowburner within. He is Cho'gall's runner, the link " ..
                "between here and the Bastion of Twilight. We must learn the secrets he carries.",
            rewardChoices = {{66936, 1}, {66937, 1}, {66938, 1}},
            rewardMoney = 376000,
        },
        [28854] = {
            description = "This terrible place was Alexstrasza's nightmare. During what mortals call the " ..
                "second war, she was chained in the depths below, her tormented offspring forced to serve " ..
                "the demon-corrupted Horde.\n\nAlexstrasza may be free, but the beast known as Erudax " ..
                "still corrupts her offspring below.\n\n< Baleflame 's body tenses in anger.>\n\nDestroy " ..
                "him, <class>. Crush him that we may end these horrors once and for all!",
            rewardChoices = {{66933, 1}, {66934, 1}, {66935, 1}},
            rewardMoney = 376000,
        },
        [28856] = {
            description = "Let's see... oh, here's a good one! Silithus!\n\nSo, apparently the Cenarion " ..
                "Circle needs assistance with an insect infestation of some sort.\n\n<Vizzie " ..
                "shivers.>\n\nUgh! No thanks, not for me. I'm perfectly happy freezing to death here in " ..
                "Everlook if the alternative is bugs.\n\nHmm... it says here that visitors should speak " ..
                "with Windcaller Proudhorn, and the easiest way to get there is via the path up Un'Goro " ..
                "Crater's northwestern cliffs.\n\nYou interested?",
            rewardMoney = 4000,
        },
        [28857] = {
            description = "Now here's an interesting one. It says to report to Quartermaster Lungertz at " ..
                "Nethergarde Keep, in the Blasted Lands. That's just about as far as you can get from " ..
                "here!\n\nIt says they're having trouble with Horde attacks. Hmph! I didn't know the " ..
                "Horde even had an outpost in the Blasted Lands! They tend to worry more about demons and " ..
                "less about rivalries down there, as I understand it.\n\nYou'll have to cross the Great " ..
                "Sea, then travel south from the Swamp of Sorrows.\n\nYou interested?",
            rewardMoney = 4000,
        },
        [28858] = {
            description = "Now here's an interesting one. It says that members of the Horde should talk " ..
                "to Okrilla at Dreadmaul Hold.\n\nHmph! I didn't even know that the Horde held Dreadmaul " ..
                "Hold!\n\nI guess this Okrilla requires help fighting some ogres and the Alliance. You'd " ..
                "think she'd already have her hands full with all the demons down there!\n\nThe best way " ..
                "to Dreadmaul Hold is to cross the Great Sea, then to take the road south from the Swamp " ..
                "of Sorrows.\n\nYou interested?",
        },
        [28859] = {
            description = "Cenarion Hold, in Silithus, is one of the biggest druid settlements in " ..
                "Kalimdor. Almost as big as Moonglade, mon.\n\nSomeday, maybe Zen'Aliri be headin' on " ..
                "over to Cenarion Hold... fightin' some Twilight's Hammer, healin' the land where the " ..
                "silithid tear it... but Zen'Aliri 's master tells him to wait.\n\nSo Zen'Aliri " ..
                "waits.\n\nThe easiest way to get there is that path up Un'Goro Crater's northwestern " ..
                "cliffs.\n\nIf you got no master... there's nothing keepin' you from movin' on.",
            rewardMoney = 4000,
        },
        [28860] = {
            description = "With your help we've thumped the Dragonmaw pretty hard, but still their daily " ..
                "attacks in the Thundermar outskirts persist. We need to keep up the pressure!\n\nWade " ..
                "back into the battle that's raging in the Thundermar ruins to the south and southwest. " ..
                "Kill Dragonmaw marauders and collect the insignias that their greatest warriors wear.",
            rewardMoney = 90000,
        },
        [28862] = {
            description = "Refugees are still pouring into Thundermar from the fighting, and I'm hungry! " ..
                "I mean them. The refugees, they're hungry.\n\nGet me some food from the Thundermar " ..
                "Ruins! Scour the ruins to the south, east, and southwest for any stores that still " ..
                "remain. Especially them big hocks of ham. I love those! Er, the refugees do.\n\nAnd see " ..
                "if you can find some of them little cocktail weenies.",
            rewardMoney = 90000,
        },
        [28864] = {
            description = "After my sister's wedding, I developed a taste for that Thunderbrew Lager that " ..
                "Kurdran had imported from Dun Morogh. More is on the way, but our caravan keeps getting " ..
                "jumped by the Dragonmaw!\n\nHead on up to the southeast side of Thunderstrike Mountain " ..
                "and catch up with the caravan. Look for a fellow named Hammelhand at the side of the " ..
                "road, and help him get the booze through the pass.\n\nJust get it as far as Kirthaven, " ..
                "and we'll take it from there.",
            rewardMoney = 90000,
        },
        [28873] = {
            description = "< Griff 's stomach growls.>\n\nStill hungry. It's like... every day, I'm " ..
                "hungry.\n\nI hear there's more food stashed up in the Thundermar Ruins across the river " ..
                "to the north, where all the fighting is. Bring some to my mouth.",
            rewardMoney = 90000,
        },
        [28882] = {
            description = "We fought hard to get a foothold on this ugly rock and there is no way we are " ..
                "going to let the Horde get in the way of our plans. Keeping control of Tol Barad is our " ..
                "first priority and we need your help, <name>. Fight your way to victory in Tol Barad and " ..
                "return to me word of your triumph.",
            rewardMoney = 114000,
        },
        [28884] = {
            description = "Maintaining control of Tol Barad is the key to our strategic plans here in the " ..
                "Eastern Kingdoms, <race>. We must do whatever it takes to keep the Alliance off this " ..
                "island and that means we need your help. Fight with everything you have to win control " ..
                "of Tol Barad and bring me word of victory.",
            rewardMoney = 114000,
        },
        [29015] = {
            description = "Hey <race>, you interested in treasure? I knew that would get your " ..
                "attention.\n\nWord from the river dock here is that one of the miners in the Venture " ..
                "Company's Boulder Lode mine just northeast of here discovered an emerald the size of " ..
                "your fist.\n\nI know a few buyers who'd be interested in getting their hands on " ..
                "something like that, and I'd be willing to go half and half on its sale. You in?",
            rewardChoices = {{59570, 1}, {59571, 1}, {59572, 1}},
        },
        [29021] = {
            description = "The Venture Company have a small research facility west of here, just past the " ..
                "Sludge Fen. I don't know very much about what they're doing, but did manage to discover " ..
                "that they're experimenting with something called a \"samophlange\".\n\nNow what the heck " ..
                "is a samophlange? Well, whatever it is, I want to examine it, so I need someone to go " ..
                "get it.\n\nI obtained a copy of their control system operating manual, you should be " ..
                "able to figure out how to disengage the samophlange from it.",
        },
        [29022] = {
            description = "The three control valves are currently opened. The various readings on the " ..
                "control panel lead you to presume that they must be shut off before the apparatus can be " ..
                "shut off.",
        },
        [29023] = {
            description = "With the apparatus deactivated, the control panel can be opened up and the " ..
                "samophlange removed from the console. With everything else in place, all that is left is " ..
                "to acquire the key to unlock the console.",
        },
        [29026] = {
            description = "I think I really put my foot into that one - it looks like I might have " ..
                "knocked one of the load-bearing fluxors into the spokes of the deregulator gear. We can " ..
                "fix this, easy. I know an expert on triple-expansion piston drives who would love to get " ..
                "her hands on a samophlange. Take the broken samophlange to Wenikee Boltbucket, just " ..
                "south of Mor'shan Rampart, she'll patch 'er right up.\n\nHey, no need to walk - this " ..
                "gives me the perfect opportunity to test my personal people porter device!",
        },
        [29027] = {
            description = "I want to fix this samophlange, but to do that I'm going to need some " ..
                "supplies. I ran out of seventeen-point-five gauge nugget slugs and I'm going to need a " ..
                "bunch of those for the work ahead.\n\nUnfortunately, the closest place to get them is " ..
                "the Burning Blade farm to the southwest. The place will be heavily guarded, so be " ..
                "careful, but the samophlange just might be worth the risk. Search the tool buckets, then " ..
                "return to me when you've gathered enough nugget slugs.",
        },
        [29034] = {
            description = "I think this little fellow will be a good match for you.\n\nThis cub is going " ..
                "to require a lot of attention to ensure that he grows up strong and healthy. You should " ..
                "check up on your cub at least once each day. Feeding and caring for your Winterspring " ..
                "cub is the best way to build a bond of trust with him.\n\nAs your cub grows, he will " ..
                "shed his old whiskers and grow new ones appropriate to his size. Once your cub has shed " ..
                "twenty whiskers, bring him back to me along with some materials for your saddle.",
            rewardItems = {{13086, 1}, {69986, 1}},
        },
        [29035] = {
            description = "Your Winterspring cub looks at you and licks its lips. The little cat must be " ..
                "hungry and it's up to you to find a suitable meal for your charge.\n\nRivern Frostwind " ..
                "mentioned keeping some shardtooth bear meat on hand for feeding his frostsaber cubs. " ..
                "Perhaps your cub would enjoy some fresh shardtooth meat of its own. Various kinds of " ..
                "shardtooth bears can be found all over Winterspring.",
            rewardItems = {{68644, 1}},
        },
        [29037] = {
            description = "Your cub looks at you expectantly. What could it want now?\n\nThe little cat " ..
                "licks its lips. It must be meal time again! As the cub's surrogate <father/mother> " ..
                "you're responsible for providing meat until it can hunt on its own.\n\nBut what if you " ..
                "let someone else do the hunting? The Winterfall furbolg of Winterspring usually have a " ..
                "lot of smoked meat on hand in both of their camps. Surely, they wouldn't miss a few " ..
                "pieces and your cub would get to try something new.",
            rewardItems = {{68644, 1}},
        },
        [29038] = {
            description = "Your Winterspring cub paws playfully at your hands. Without any playmates, the " ..
                "cub has few chances to practice its hunting skills.\n\nPerhaps you should take your cub " ..
                "hunting for the small arctic hares that burrow in the snow of northern Winterspring. " ..
                "Bring your cub close to the mounds of snow covering the hare burrows and wait for the " ..
                "cub's instincts to take over.",
            rewardItems = {{68644, 1}},
        },
        [29039] = {
            description = "Your Winterspring cub paws playfully at your hands. Without any playmates, the " ..
                "cub has few chances to practice its hunting skills.\n\nPerhaps you should take your cub " ..
                "hunting for the small arctic hares that burrow in the snow of northern Winterspring. " ..
                "Bring your cub close to the mounds of snow covering the hare burrows and wait for the " ..
                "cub's instincts to take over.",
            rewardItems = {{68644, 1}},
        },
        [29040] = {
            description = "The winterspring cub plays with a small tuft of fur from a large animal, " ..
                "batting the discarded hair about. While your cub looks like it's enjoying the new game, " ..
                "you wonder if it might get more enjoyment from a proper cat toy.\n\nWith a little bit of " ..
                "leather from a yeti pelt and some feathers from crazed moonkin, you could make a " ..
                "respectable toy. You'll need a hide from the yeti in the Ice Thistle Hills southeast of " ..
                "Everlook and feathers from the moonkin at the Hidden Grove or Owl Wing Thicket.",
            rewardItems = {{68644, 1}},
        },
        [29051] = {
            description = "The Winterspring cub plays with a small tuft of fur from a large animal, " ..
                "batting the discarded hair about. While your cub looks like it's enjoying the new game, " ..
                "you wonder if it might get more enjoyment from a proper cat toy.\n\nWith a little bit of " ..
                "leather from a yeti pelt and some feathers from crazed moonkin, you could make a " ..
                "respectable toy. You'll need a hide from the yeti in the Ice Thistle Hills southeast of " ..
                "Everlook and feathers from the moonkin at the Hidden Grove or Owl Wing Thicket.",
            rewardItems = {{68644, 1}},
        },
        [29052] = {
            description = "Your Winterspring cub looks at you and licks its lips. The little cat must be " ..
                "hungry and it's up to you to find a suitable meal for your charge.\n\nRivern Frostwind " ..
                "mentioned keeping some shardtooth bear meat on hand for feeding his frostsaber cubs. " ..
                "Perhaps your cub would enjoy some fresh shardtooth meat of its own. Various kinds of " ..
                "shardtooth bears can be found all over Winterspring.",
            rewardItems = {{68644, 1}},
        },
        [29053] = {
            description = "Your cub looks at you expectantly. What could it want now?\n\nThe little cat " ..
                "licks its lips. It must be meal time again! As the cub's surrogate <father/mother> " ..
                "you're responsible for providing meat until it can hunt on its own.\n\nBut what if you " ..
                "let someone else do the hunting? The Winterfall furbolg of Winterspring usually have a " ..
                "lot of smoked meat on hand in both of their camps. Surely, they wouldn't miss a few " ..
                "pieces and your cub would get to try something new.",
            rewardItems = {{68644, 1}},
        },
        [29066] = {
            description = "<Blackhorn used the power of Thol'embaar's remains to slip his bonds. But at " ..
                "least the inferno seems to be subsiding.>\n\n< Matoclaw will want to know what happened " ..
                "here. She's waiting for you back at the Grove of Aessina.>",
            rewardMoney = 7800,
        },
        [29071] = {rewardItems = {{68808, 1}}},
        [29073] = {rewardItems = {{68809, 1}}},
        [29079] = {
            description = "The invading orcs aren't fools. They are sizing us up, making sure that when " ..
                "they attack it will be to their advantage.\n\nIn the forest, to the northwest, are " ..
                "Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. " ..
                "I want you take the fight to them!\n\nKill the Blackrock spies! We must show them that " ..
                "we know they are watching us and that we are prepared!",
            rewardItems = {{57387, 1}},
            rewardMoney = 40,
        },
        [29080] = {
            description = "I have here an urgent message from Sergeant Willem. Turns out that the " ..
                "Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the " ..
                "abbey. Willem has asked me to send him a hero. You have to go help them, <name>!\n\nFind " ..
                "Sergeant Willem north of the abbey at the command tent. Go!",
            rewardMoney = 13,
        },
        [29081] = {
            description = "Have you ever seen a goblin, <name>? They're wretched little green-skinned " ..
                "monsters that love only two things: gold and themselves.\n\nThe Blackrock orcs have " ..
                "enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in " ..
                "the north you can barely make out their silhouettes, sneaking about in the grass.\n\nI " ..
                "need you to head out there and kill every goblin that you see. They need to learn that " ..
                "nobody messes with the Alliance!",
            rewardItems = {{2186, 1}},
            rewardMoney = 50,
        },
        [29082] = {
            description = "Have you embraced the Holy Light yet, <brother/sister>? It is through the Holy " ..
                "Light that we are saved! It is through the Holy Light that I am able to heal these " ..
                "overly demanding soldiers! And it is through the Holy Light that you will be able to " ..
                "venture out into the field to the north and rescue our fallen brothers!\n\nTake this " ..
                "prayer book with you into the field and cast the Light's healing touch on the injured.",
            rewardItems = {{57257, 1}},
            rewardMoney = 50,
        },
        [29087] = {
            description = "Hey <name>, do you see this footprint? We found them all over the camp last " ..
                "night! Nothing's missing, but all our belongings have been...examined. The muddy trails " ..
                "lead back toward the Sludge Fen.\n\nSomeone's been sniffing around, and I don't like it " ..
                "one bit. Can you go west to the Sludge Fen and investigate? See if you can find any more " ..
                "tracks just like this one!",
            rewardMoney = 800,
        },
        [29095] = {
            description = "Now that the threat here has been stilled, you should return to the " ..
                "Crossroads. Thork would like to speak to you.\n\nFarewell, friend.",
            rewardMoney = 800,
        },
        [29100] = {
            description = "Dese be troublin' times for us Darkspear. Da Zandalar be reuniting all da " ..
                "troll clans an' plan to take back da lands dey lost.\n\nWe tryin' to warn all dat we " ..
                "can. But it might be too late.\n\nAnother Darkspear gone down to Stranglethorn to warn " ..
                "da people. But it ain't safe to travel alone in Stranglethorn.\n\nHelp me find him and " ..
                "make sure da people in Stranglethorn are warned of da rise of da troll tribes.\n\nI " ..
                "gonna bind my spirit wit' ya. When ya get to Stranglethorn, I be able to aid ya.",
            rewardMoney = 94000,
        },
        [29102] = {
            description = "Da first place we check gonna be da place most likely to be attacked first. " ..
                "You call it Fort Livingston.\n\nFort Livingston be surrounded by troll ruins... It make " ..
                "for an easy target.\n\nMaybe we find da emissary dere. Hopefully it ain't too late.",
            rewardMoney = 94000,
        },
        [29110] = {
            description = "They took Balgor and the caravan supplies from our very doorstep!\n\nThose " ..
                "supplies are vital for our victory against the Alliance in Ashenvale, and Balgor...if " ..
                "anything happens to my dear little brother, I will rip every Burning Blade member to " ..
                "shreds myself.\n\n<name>, I need you to rescue Balgor and the captured caravan. Follow " ..
                "the path just north of us, up onto Dreadmist Peak. Do not let any of those Burning Blade " ..
                "dogs live.",
        },
        [29112] = {
            description = "Listen <name>, we can't leave quite yet. I managed to overhear their plans " ..
                "while they were preparing for the ritual sacrifice.\n\nThey're planning to use a " ..
                "powerful artifact called the Demon Seed to launch a full scale attack on the Horde. " ..
                "They're keeping it under close guard over in that cave.\n\nIf you can get your hands on " ..
                "the Demon Seed, we should take it to my sister Nagala. She'll know what to do with it.",
            rewardItems = {{69219, 1}},
            rewardMoney = 900,
        },
        [29114] = {
            description = "We've been fending off serpents for days now, <name>. But the serpents are " ..
                "nothing compared to what else is out in that jungle.\n\nWe hunters are being " ..
                "hunted.\n\nA large panther named Mauti has been dragging my men off into the bush.\n\nWe " ..
                "sent Grent Direhammer, one of our best hunters, to track this beast down.\n\nDirehammer " ..
                "headed off to the east, perhaps you can find them there.",
            rewardMoney = 94000,
        },
        [29116] = {
            description = "Well, that explains why Mauti seemed smaller... The real Mauti has run off " ..
                "with Grent Direhammer, but being the wise hunter that he is, he has fired flares off so " ..
                "you can track him. Find Direhammer before it's too late!",
            rewardMoney = 94000,
        },
        [29123] = {
            description = "Of all of our tasks here in Hyjal, the most pressing is simple: destroy these " ..
                "invaders. The very nature of fire is that it is all-consuming. Lower your defense for " ..
                "just a moment and it will destroy everything in sight.\n\nKill any of the fiery invaders " ..
                "you find. Every enemy defeated purchases more time for Hyjal.",
            rewardMoney = 94000,
        },
        [29128] = {
            description = "We need to place pressure on the assault camp at Sethria's Roost. Ragnaros' " ..
                "minions are using this area as a point to push their battlefront beyond the bounds of " ..
                "Hyjal. I'm putting you in charge of a small squad to deal with them.\n\nI have selected " ..
                "an elite group of fighters to assist you. Travel to Sethria's Roost. Your compatriots " ..
                "have been instructed to meet you once you arrive. Then put an end to the elementals' " ..
                "assault.",
            rewardMoney = 188000,
        },
        [29129] = {
            description = "A pleasure, <class>.\n\n< Ziradormi smiles.>\n\nIt was kind of you to arrive " ..
                "so quickly.\n\nFor reasons unknown to me, my master seeks audience with you.\n\nI would " ..
                "counsel you not to take this invitation lightly. Anachronos seldom has cause to interact " ..
                "with mortals. Wisdom would dictate that you seek him out in the Caverns of Time at " ..
                "once.\n\nSpeak to me when you are ready and I shall personally deliver you.",
            rewardMoney = 94000,
        },
        [29131] = {
            description = "We are in trouble here, <name>. Your troll friend has been through here and " ..
                "warned us that things were going to get serious, but I didn't think it would be this " ..
                "bad.\n\nWe are doing our best to hold off these trolls. But any help you can offer would " ..
                "greatly help.",
            rewardMoney = 94000,
        },
        [29132] = {
            description = "I expected that I would find you here, <class>. But then, we of the bronze " ..
                "flight have somewhat of an advantage when it comes to such things.\n\n< Coridormi " ..
                "smiles.>\n\nFor reasons unknown to me, my master seeks audience with you.\n\nI would " ..
                "counsel you not to take this invitation lightly, <name>. Anachronos seldom has cause to " ..
                "interact with mortals. Wisdom would dictate that you seek him out in the Caverns of Time " ..
                "at once.\n\nSpeak to me when you are ready and I shall personally deliver you.",
            rewardMoney = 94000,
        },
        [29133] = {
            description = "The other Darkspear emissary was here briefly. He was eager to get to the next " ..
                "location and warn them. I sent him on a flight to the Explorers' League Digsite in the " ..
                "Cape of Stranglethorn. I hope he wasn't too late.\n\nI will give you use of one of my " ..
                "gryphons, a direct flight there.\n\nTalk to me when you are ready to go, <name>.",
            rewardMoney = 94000,
        },
        [29135] = {
            description = "I perceive the questions that burn within your mind and I must confess that I " ..
                "share in your uncertainty... a rare position for one such as I, and a most unsettling " ..
                "one.\n\nAs I scour time to find traces of this obscured event, you must aid me in the " ..
                "creation of an Eye, both to test your worthiness, and to provide an essential tool in " ..
                "the unraveling of this mystery.\n\nVenture into the Plane of Fire, <class>, and gather " ..
                "Eternal Embers. Bring them to me with Sands of Time and I will create the Eye.",
            rewardMoney = 282000,
        },
        [29143] = {
            description = "The fire elementals are pouring out of portals on the far side of the Ashen " ..
                "Fields. We need someone to close them. Cut off some of their " ..
                "reinforcements.\n\nBanishing these kinds of elemental magics is something our wisps are " ..
                "perfectly suited for. One will come with you. Lead it to a portal and keep it alive " ..
                "until it finishes.",
            rewardMoney = 94000,
        },
        [29148] = {
            description = "< Matoclaw 's voice continues to echo within your head.>\n\nMillagazor is a " ..
                "creature of flame, but in many ways, he is not unlike the birds of this land. As such, " ..
                "Aviana's artifacts may still have the power to summon him.\n\nThe fiery portal to the " ..
                "west is where you will find him. Use the quill near the portal's entrance, then prepare " ..
                "for a fierce battle.",
            rewardMoney = 94000,
        },
        [29149] = {
            description = "Of all of our tasks here in Hyjal, the most pressing is simple: destroy these " ..
                "invaders. The very nature of fire is that it is all-consuming. Lower your defense for " ..
                "just a moment and it will destroy everything in sight.\n\nKill any of the fiery invaders " ..
                "you find. Every enemy defeated purchases more time for Hyjal.",
            rewardMoney = 94000,
        },
        [29159] = {
            description = "We've fought hard to secure this area, but our foothold is tenuous.\n\nOur " ..
                "scouts report that the area around us is teeming with vicious fire spiders. They are the " ..
                "spawn of the vicious brood widow, Beth'tilac.\n\nHelp us hold our line by clearing the " ..
                "area of Cinderweb Spinners or Cinderweb Creepers. It will drive her mad to see her " ..
                "children slain.",
            rewardMoney = 94000,
        },
        [29160] = {
            description = "We have a real problem on our hands. Not only are the nearby spiders vicious " ..
                "and predatory, their numbers appear to be endless.\n\nWe need to stop the growth of " ..
                "their army. Cut their heads off in the egg, not on the battlefield.\n\nThe Cinderweb " ..
                "Spinners' eggs are laid among the stone pillars to the north. Collect 20 eggs and bring " ..
                "them back to me.",
            rewardMoney = 94000,
        },
        [29163] = {
            description = "Of all of our tasks here in Hyjal, the most pressing is simple: destroy these " ..
                "invaders. The very nature of fire is that it is all-consuming. Lower your defense for " ..
                "just a moment and it will destroy everything in sight.\n\nKill any of the fiery invaders " ..
                "you find. Every enemy defeated purchases more time for Hyjal.",
            rewardMoney = 94000,
        },
        [29172] = {
            description = "< Bloodslayer T'ara eyes you for a moment.>\n\nAfter de fall of Hakkar, de " ..
                "city of de Gurubashi fell into disrepair, and de jungle claimed most of Zul'Gurub for " ..
                "its own. Some powerful beasts now be livin' in da cracks an' hollows of de ancient " ..
                "city.\n\nWe seen de powers dem Gurubashi priests wield - dey turn de very plantlife " ..
                "against us wit' venomous concoctions. You tink you be strong? Dispose of dese beasts, " ..
                "before dey become mindless agents of Jin'do.",
            rewardMoney = 376000,
        },
        [29175] = {
            description = "A city like Zul'Gurub be similar ta one of de many towering trees you see " ..
                "nearby.\n\nDe trunk may be thick, and de canopy vast and leafy, but without nutrients " ..
                "from de roots far below, de tree gonna wither and fall.\n\nJin'do's army be fed largely " ..
                "by de actions of a couple a' minor Gurubashi trolls. Sever dem roots, and de city gonna " ..
                "fall.",
            rewardMoney = 376000,
        },
        [29179] = {
            description = "The elementals continue to press on us, and I do not expect them to subside " ..
                "any time soon.\n\nYou'll find them pouring across the Ashen Fields to the north. Thin " ..
                "their ranks.",
            rewardMoney = 94000,
        },
        [29189] = {
            description = "Some of our scouts have not reported back for duty. We fear they have " ..
                "succumbed to the deadly spiders in the vicinity.\n\nHope may not be lost, however. The " ..
                "spiders often wrap up their live prey in cocoons for later consumption.\n\nGo search the " ..
                "pillars to the north for cocooned victims. You may yet be able to save some of our " ..
                "brethren.",
            rewardMoney = 94000,
        },
        [29192] = {
            description = "We must tread carefully, <class>. Fandral's Druids of the Flame practice their " ..
                "fiery magic beyond the pillars to the north.\n\nI need you to capture one of those " ..
                "druids alive for questioning. We must seize every opportunity to learn of their " ..
                "plans.\n\nOne of my wardens will accompany you. Follow her instructions if you wish to " ..
                "survive.",
            rewardMoney = 94000,
        },
        [29193] = {
            description = "Time well spent, mortal.\n\nWhile you struggled in the Plane of Fire, my " ..
                "watchers and I were able to determine when and, most importantly, where our vision was " ..
                "obscured.\n\nWe discovered that the shroud was placed over the Nexus, far to the north " ..
                "in the realm of the blue dragonflight.\n\nI have attuned the Timeless Eye to show you " ..
                "the occurrences that remain hidden to us here.\n\nBring it to Coldarra at once and seek " ..
                "out a place suitable for its activation.\n\nGo, child. Time is of the essence...",
            rewardMoney = 94000,
        },
        [29194] = {
            description = "< Tarecgosa listens as you explain your presence in Coldarra.>\n\nYour tale " ..
                "rings true, <class>. Much has changed since the death of Malygos - little of it for the " ..
                "better.\n\nI know of the device you carry, and I recognize Anachronos' magic in its " ..
                "creation. There is but one place in all of Coldarra that would allow this Timeless Eye " ..
                "to be used discreetly.\n\nYou will require my assistance if you hope to succeed. Speak " ..
                "with me again inside the Nexus and you shall have it.",
            rewardMoney = 188000,
        },
        [29197] = {
            description = "Our invasion plan looks to have backfired. Several of our birds have already " ..
                "reported in, speaking of fires breaking out across the vales of central Hyjal.\n\nNow, " ..
                "many of our druids are stranded out in the field, unprepared for such a large-scale " ..
                "attack. Thisalee was near Ashen Lake, and several others were out in the Regrowth, to " ..
                "the northeast.\n\nGo, <name>! Find them, and make sure that they do not succumb to this " ..
                "backdraft!",
            rewardMoney = 94000,
        },
        [29200] = {
            description = "Before we depart, <name>, I have another matter to which you should " ..
                "attend.\n\nA Druid of the Flame has been spotted in the ruins to the northwest. I " ..
                "suspect it is the same one that attacked us at the portal several days ago. Now would be " ..
                "an ideal time to see what it is that she truly wants... and if necessary, dispose of " ..
                "her.\n\nSee to this flame druid, then we can continue on our planned course.",
            rewardMoney = 94000,
        },
        [29215] = {
            description = "The Shadow Wardens have joined the fight at the Molten Front, on your request. " ..
                "You should find Captain Saynna Stormrunner and see to it that they've found a way to " ..
                "best apply their skills.",
            rewardMoney = 23500,
        },
        [29221] = {
            description = "Da warning helped, <name>.\n\nWe gathered more Headhunters to help defend. But " ..
                "Headhunters... Dey not used to hunting heads on serpents. So we soon be overwhelmed. " ..
                "Dese serpents, dey seem to come from everywhere. An' it probably only gonna get " ..
                "worse.\n\nHelp us and kill da serpents and have Bwemba use her mojo to cure da ones dat " ..
                "are sick from poison.",
            rewardMoney = 94000,
        },
        [29225] = {
            description = "< Tarecgosa listens intently as you describe your " ..
                "vision.>\n\nImpossible!\n\nNot even Arygos would dare to go to such lengths.\n\nI do not " ..
                "question your integrity, <class>, but you must understand - your mortal mind can easily " ..
                "be deceived.\n\nRegardless, Kalecgos must be informed of these events. You must travel " ..
                "to Nordrassil at once to seek him out.\n\nI shall remain here to conceal the evidence of " ..
                "our activities. Speak of this to no one else!",
            rewardMoney = 47000,
        },
        [29226] = {
            description = "We've been fending off serpents for days now, <name>. But the serpents are " ..
                "nothing compared to what else is out in that jungle.\n\nWe hunters are being " ..
                "hunted.\n\nA large panther named Mauti has been dragging my men off into the bush.\n\nWe " ..
                "sent Grent Direhammer, one of our best hunters, to track this beast down.\n\nDirehammer " ..
                "headed off to the east, perhaps you can find them there.",
            rewardMoney = 94000,
        },
        [29230] = {
            description = "I got da feeling dat somethin' ain't right wit' dat panther, <name>. It ain't " ..
                "natural. I gonna need to perform some rituals over da body. Put Mauti down, an' den " ..
                "let's see what we can find out, <name>.",
            rewardMoney = 94000,
        },
        [29232] = {
            description = "Ah... It's you, <name>. Mauti... He's dead? Then my brother has been avenged. " ..
                "I've only one request from ya... This scamp here, he's been pawing at me bare feet. No " ..
                "dwarf should go to the earth with bare feet.\n\nPlease, bury me with me boots.",
            rewardMoney = 94000,
        },
        [29233] = {
            description = "Dis death ain't be in vain, <name>. We figure out dat Kilnara be on da prowl. " ..
                "Tings don't look good.\n\nWe better check out Grom'gol Base Camp to da west. Maybe we " ..
                "find my contact dere.",
            rewardMoney = 94000,
        },
        [29234] = {
            description = "I am duty-bound to look into your claims immediately, <race>, which means my " ..
                "mission here now must fall to you.\n\nA surge of ancient magic, far too strong to have " ..
                "occurred naturally, drew me here. I have since discovered a most troubling " ..
                "development.\n\nA bough from Nordrassil has been ripped from the tree and taken deep " ..
                "into the Firelands. There, a powerful ritual threatens to corrupt Nordrassil, consuming " ..
                "it in flame.\n\nYou must find a way to interrupt the ritual and reclaim the World Tree's " ..
                "branch.",
            rewardMoney = 282000,
        },
        [29236] = {
            description = "Bwemba... Is that you?\n\nYour contact was here. He was eager to get to the " ..
                "next location and warn them. And really, who could blame him? I gave him use of a wyvern " ..
                "to reach the goblins of Hardwrench Hideaway, in the Cape of Stranglethorn.\n\nI will " ..
                "give you use of one of my wyverns to reach Hardwrench.\n\nTalk to me when you are ready " ..
                "to go, <name>.",
            rewardMoney = 94000,
        },
        [29238] = {
            description = "Some of da survivors mentioned food, <name>. We better check da food supplies. " ..
                "I gotta a bad feelin' about dis.",
            rewardMoney = 94000,
        },
        [29239] = {
            description = "Much has transpired since last we spoke.\n\nI have taken it upon myself to " ..
                "visit the Nexus and recover Anachronos's artifact, but not before using it for myself. " ..
                "Now I too have witnessed that which you have seen.\n\nBefore discussing the matter " ..
                "further, allow me to express my gratitude to you for your assistance, both here and in " ..
                "the Plane of Fire.",
            rewardItems = {{71084, 1}},
            rewardMoney = 282000,
        },
        [29243] = {
            description = "One of Ragnaros' Lieutenants has shown itself at Ragnaros' Reach. It is time " ..
                "to strike. Captain Saynna has requested that you be there to help see the fight " ..
                "through.\n\nWitherbranch and some others will have joined the battle by the time you " ..
                "arrive. You should make haste to the northwest and find them.",
            rewardMoney = 188000,
        },
        [29246] = {
            description = "The Arch Druid has an immense tolerance for pain. I've treated burn victims " ..
                "that spend twenty-two hours a day screaming in pain, and their burns weren't even half " ..
                "as bad as what Hamuul has suffered.\n\nNevertheless, I can sense that he is in greater " ..
                "discomfort than normal today. Bring me the hearts of the large fire elementals to the " ..
                "southeast. I can use them to prepare a soothing salve for our patient.",
            rewardMoney = 94000,
        },
        [29249] = {
            description = "The acorn seems to be unharmed.\n\n< Avrilla shrugs.>\n\nNo point in beating " ..
                "around the bush. Let's plant it and see what comes out.\n\nLuckily for you, we brought " ..
                "some leftover soil with us to help establish our base.\n\nYou'll find the soil at the " ..
                "graveyard directly east.",
            rewardMoney = 47000,
        },
        [29251] = {
            description = "Look, <name>. You've helped out plenty so far, but that's not going to be " ..
                "enough. I need these crazy trolls stopped, or at least stopped from getting into Booty " ..
                "Bay.\n\nI'm going to send a man in to oversee the action, but I want you to go into " ..
                "Zul'Gurub and make something happen.\n\nAt the very least, I want you to find me " ..
                "something that will help keep these trolls out of Booty Bay.\n\nYou do that and we'll " ..
                "treat you right.",
            rewardMoney = 94000,
        },
        [29252] = {
            description = "I've been sent here by Baron Revilgaz of Booty Bay to make sure this troll " ..
                "menace is halted. Or that it is at least halted at the gates of Booty Bay.\n\nI want " ..
                "action and I want results.\n\nI want you to get in there and kill.\n\nI want you to get " ..
                "in there and find me something that will help keep these trolls out of Booty Bay.\n\nYou " ..
                "do that and we'll make sure you get paid.",
            rewardMoney = 94000,
        },
        [29253] = {
            description = "There is a stash of loot located in the statue on Janeiro's Point just " ..
                "northwest of Booty Bay in Stranglethorn Vale.\n\nHead to the statue and claim your " ..
                "prize, <class>.",
            rewardItems = {{69262, 1}, {69863, 1}, {69864, 1}, {69865, 1}},
            rewardMoney = 94000,
        },
        [29254] = {
            description = "The little red flower wiggles its tendrils happily. It seems to like " ..
                "you!\n\nPerhaps Avrilla would like to see what grew out of the acorn.",
            rewardMoney = 94000,
        },
        [29255] = {
            description = "The Crimson Lasher has developed some cracking blisters on its vines. Without " ..
                "treatment, this condition could be life threatening.\n\nLuckily, the Charred Soldiers " ..
                "and Charred Vanquishers in the area produce a waxy substance known as Embergris, which " ..
                "should soothe the Lasher's pain.\n\nBring me some of this substance, and kill those " ..
                "nasty fire elementals while you're at it.",
            rewardMoney = 94000,
        },
        [29265] = {
            description = "My fellow druid, Choluna, has asked us to collect any specimens of plant life " ..
                "that we might find here in the Firelands...\n\n...I don't know whose idea it was to " ..
                "bring scholars to a warfront.\n\nNevertheless, you will already be in the cave - killing " ..
                "things - so be on the lookout for anything growing out of the ground.",
            rewardMoney = 94000,
        },
        [29267] = {
            description = "So much violence, so much death. Brothers have died, a mother has died, and " ..
                "now a panther cub will die if there is no one to take care of it.\n\nWill you take a " ..
                "pause from the violence to help care for a panther cub?",
            rewardItems = {{68833, 1}},
        },
        [29269] = {
            description = "I was charged with her protection, yet it was she who sacrificed herself for " ..
                "my sake.\n\nI cannot bear to lose her, <name>. I must make a solemn request of " ..
                "you.\n\nNever has a mortal borne the essence of a true dragon, but with your permission " ..
                "I would make an exception.\n\nPlease, while there is life in her, will you allow me to " ..
                "bind Tarecgosa to you?",
            rewardMoney = 94000,
        },
        [29270] = {
            description = "Tarecgosa is bound to you, <name>, but only temporarily. An aspect's power is " ..
                "required to permanently seal her essence.\n\nMalygos's successor will not be chosen " ..
                "until Azeroth's moons next eclipse, and the bond you share will not last until " ..
                "then.\n\nFortunately, there is a way to buy us the time we need. Powerful elements exist " ..
                "that can extend the ritual's effects. Some of these can be found in the Plane of Fire, " ..
                "with which you've become familiar.\n\nObtain them, <class>, and sustain Tarecgosa until " ..
                "the eclipse.",
            rewardMoney = 94000,
        },
        [29272] = {description = "Need... water... badly...", rewardMoney = 94000},
        [29273] = {
            description = "The fire hawks of Fireplume Peak can withstand incredible temperatures. While " ..
                "you'll often find them circling the skies above, they're also known to swim in molten " ..
                "lava.\n\nIsn't that right, Anren?\n\nWe'd like to know just how hot that lava can get. " ..
                "Fireplume Peak has three large lava pools. Use this to measure the temperature of each.",
            rewardMoney = 94000,
        },
        [29274] = {
            description = "On the Firelands' largest island, our troops have been having trouble against " ..
                "Shannox, the flamewaker hunter. Not only does he have impeccable aim, but he keeps " ..
                "trained hounds that give our troops no end of trouble.\n\nTholo, in all his wisdom, " ..
                "thinks it would be a good idea to study the biology of these hounds. I, of course, agree " ..
                "with Tholo.\n\nYou will find several hounds in the Molten Flow, beneath the Furnace. We " ..
                "will need their ashes to study.",
            rewardMoney = 94000,
        },
        [29276] = {
            description = "The Widow's Clutch, to the northeast, is named after Beth'tilac, the enormous " ..
                "queen of the flame spiders. Her webs and her poison are a nagging threat to our main " ..
                "offensive force.\n\nWe believe that if we study the flame spiders here on the Molten " ..
                "Front, we can use that information to find success against Beth'tilac. Use whatever " ..
                "methods you can to gather their venom and their web fluid, then return to my trusted " ..
                "friend Anren.",
            rewardMoney = 94000,
        },
        [29278] = {
            description = "Have you seen those fireballs falling out of the sky? I saw one crash in the " ..
                "fields to the north, and the rock that landed was made of pure Living Obsidium!\n\nI can " ..
                "use the material to craft ultra-sturdy heat proof armor and weapons for our troops. Can " ..
                "you bring me a lode?\n\nGo to the Magma Springs and touch one of the magnetic stones. " ..
                "Just watch where you're standing when the rain of fire hits, and gather up the rocks " ..
                "before they crumble from the impact.",
            rewardMoney = 94000,
        },
        [29279] = {
            description = "We've constructed this moonwell, but it serves little purpose until it is " ..
                "filled with the sacred waters of the Well of Eternity.\n\nWith an active moonwell, we " ..
                "would be able to bless our food stores, and we may also be able to use the blessing to " ..
                "offer you some protection from fire as well.\n\nWhen you've obtained enough marks, speak " ..
                "to Matoclaw at the Sanctuary of Malorne. She'll be able to secure transport of the " ..
                "sacred waters.",
            rewardMoney = 188000,
        },
        [29282] = {
            description = "Ricket should be at Malfurion's Breach with Damek, as you requested. I'm not " ..
                "sure you fully know what you're getting into with those two though.\n\nSpeaking of " ..
                "which, you should probably go check on them... make sure they haven't managed to blow up " ..
                "the Sentinel Tree itself. As long as you keep them busy with the elementals, the chances " ..
                "of \"accidents\" at the breach should lessen dramatically.",
            rewardMoney = 23500,
        },
        [29284] = {
            description = "The ancients have seen the value of your wisdom, and have set root at " ..
                "Malfurion's Breach. You should seek out Elderlimb. I am certain he would like to hear " ..
                "from you.",
            rewardMoney = 23500,
        },
        [29285] = {
            description = "The time of choosing has arrived, <name>.\n\nWhile only members of the blue " ..
                "dragonflight may attend, Tarecgosa's binding makes your presence requisite.\n\nI must " ..
                "ask that you take on her form and vote on her behalf.\n\nDo not tarry. The moment of the " ..
                "eclipse draws near....",
            rewardItems = {{71085, 1}},
            rewardMoney = 282000,
        },
        [29293] = {
            description = "Many of our Storm Crows have gone ahead to scout the peak and attempt to " ..
                "retrieve some of the fire hawk eggs, but to very little success I'm afraid. The thermals " ..
                "make it nearly impossible to fly safely, and the fire hawks aren't exactly friendly " ..
                "either.\n\nI need you to head over there and rescue any druids that you can. I've got " ..
                "splints, bandages, burn salves, smelling salts... anything you'll need to get them back " ..
                "on their feet, assuming they're still alive. Please hurry and help anyone you can find.",
            rewardMoney = 94000,
        },
        [29295] = {
            description = "You're not going to take on fiery behemoths wearing THAT, are you? If you " ..
                "aren't wearing my obsidium crafted goods, you're going to burn right up! And even if you " ..
                "are, you can never have enough of the good stuff.\n\nLook <brother/sister>, I can craft " ..
                "you the best armor that gold can buy, but I need pure, unsmelted Living Obsidium " ..
                "first.\n\nThe Obsidium Punishers on Fireplume Peak are literally made of the stuff. Go " ..
                "kill them and gather their pieces.",
            rewardMoney = 94000,
        },
        [29296] = {
            description = "The fire hawks are upset by our continued presence. They're getting extremely " ..
                "hostile, and not just in the usual territorial ways. I worry that if we leave them " ..
                "unchecked, they will soon be joining the assault on our tree, and I'm not sure we're " ..
                "capable of handling that.\n\nGo across the way to Fireplume Peak and do what you have to " ..
                "to keep them in check. I'm far more concerned with our safety right now than theirs, so " ..
                "be decisive about it.",
            rewardMoney = 94000,
        },
        [29297] = {
            description = "Staghelm's druids are putting up a fierce fight at Wildflame Point to the " ..
                "northeast.\n\nThe druids fly above us in fire crow form, then strike when we least " ..
                "expect it. Worst part is, they know exactly how to stay out of our reach!\n\nWe would be " ..
                "totally helpless, except Damek lent me his trusty harpoon. He says these weapons will " ..
                "fly straight and true even in this super dense air.\n\nTake the dwarf's weapon and shoot " ..
                "some birds out of the sky!",
            rewardMoney = 94000,
        },
        [29305] = {
            description = "One of Ragnaros' Lieutenants has shown himself at Ragnaros' Reach, the walled " ..
                "area to our northeast.\n\nI hoped to send you as soon as you returned, but I suspect " ..
                "Witherbranch and some of our forces have already joined the fight by now. You should " ..
                "hurry.\n\nYou should be able to drop down the cliff wall right here and reach them " ..
                "quickly.",
            rewardMoney = 188000,
        },
        [29307] = {
            description = "You are the first mortal to witness a dragon council, <name>, and among the " ..
                "only beings in Azeroth to take part in the choosing of an Aspect.\n\nMy ascension has " ..
                "endowed me with incredible power. I have taken the liberty to strengthen Tarecgosa's " ..
                "bond with you, though she will require a more... permanent home.\n\nI would have you " ..
                "venture one last time into the Plane of Fire and bring me the heart of Ragnaros.\n\nWhen " ..
                "next we meet, I will be able to suitably thank you for all that you have done.",
            rewardMoney = 282000,
        },
        [29310] = {
            description = "On the day when Leyara attacked Hamuul, she was waiting near some ruins in " ..
                "Hyjal, northwest of the Regrowth. She acted strangely at the time: calm, silent, and " ..
                "staring off into the distance. Perhaps that location is of some importance to " ..
                "her.\n\nThe locket might react if brought to that location.",
        },
        [29312] = {
            description = "It is an honor to make your acquaintance, <race>.\n\nYour deeds echo in the " ..
                "ears of Azeroth's creatures, mortal and immortal alike.\n\nI shall present the heart of " ..
                "Ragnaros to Kalecgos when he arrives. Its power is to be harnessed to further endow your " ..
                "weapon.\n\nThe ceremony is to begin shortly. I have been appointed to escort you there " ..
                "when you are ready.",
            rewardItems = {{71086, 1}},
            rewardMoney = 282000,
        },
        [29313] = {
            description = "My family has been making the best kimchi in Darnassus for generations, " ..
                "<name>. The secret is something simple, but it makes all the difference.\n\nWe bury the " ..
                "jars in the ground until it's ready to serve and my latest batch has just reached that " ..
                "point. You can find the jars buried in earthen mounds all over the city. Would you help " ..
                "me gather them while the contents are just right?",
            rewardMoney = 20000,
        },
        [29314] = {
            description = "The living are not the only ones who require sustenance. One of my duties is " ..
                "to prepare the rice cakes that are left for the ancestors. Normally, my senior " ..
                "apprentice has the honor of taking the cakes to the Temple of the Moon for blessing and " ..
                "then presenting them to the ancestors. Since she is out of the city today, would you " ..
                "mind performing the duty in her place?",
            rewardMoney = 20000,
        },
        [29315] = {
            description = "Some chefs complain that our beloved Undercity doesn't boast the ingredients " ..
                "to create truly fine fare.\n\nSuch mewling little cretins. Delicious delights " ..
                "abound!\n\nGather some of the rank, slimy Sewer Caps growing in Undercity's northwest " ..
                "sewer line and return them to me.",
            rewardMoney = 74000,
        },
        [29316] = {
            description = "There are certain things that everyone needs, from the basic household cook to " ..
                "the master chef. One of the city's most important staples is rice flour. Most families " ..
                "keep at least one basket of rice in their houses and the residents of the Craftsmen's " ..
                "Terrace and Tradesmen's Terrace are no different.\n\nI often ask my students to help " ..
                "with the task of pounding rice into flour since it's good practice and an endless task. " ..
                "Why don't you give it a try?",
            rewardMoney = 8500,
        },
        [29317] = {
            description = "There was an... incident... with an orc guard and one of Master Apothecary " ..
                "Faranell 's abominations.\n\nApparently, the Kor'kron Overseer chopped its head clean " ..
                "off and kicked it into the slime.\n\nFaranell's apprentices searched for hours but they " ..
                "can't find the thing. Care to try fishing it up? I'm sure the old fellow'd be grateful.",
            rewardItems = {{67414, 1}},
            rewardMoney = 90000,
        },
        [29318] = {
            description = "One of my responsibilities is to feed the sentinels of Darnassus while they're " ..
                "on duty. It's a time-consuming task, but one I'm happy to undertake. It's also a great " ..
                "way to practice your skills. Would you mind helping me with today's meal? Simply take " ..
                "these ribs, cook them near a stove or fire, and distribute them to sentinels throughout " ..
                "the city.",
            rewardMoney = 114000,
        },
        [29319] = {
            description = "Some of our apothecaries took to dumping their more volatile waste chemicals " ..
                "into Stillwater Pond and... well, let's just say that no one wants to know how big " ..
                "mutant flesh-eating toads can grow.\n\nWould you consider fishing up some giant " ..
                "flesh-eating tadpoles before it gets to that? Just don't try to handle them with your " ..
                "bare hands.",
            rewardItems = {{67414, 1}},
            rewardMoney = 114000,
        },
        [29320] = {
            description = "You've fished in Brightwater Lake, yes?\n\nThe prize catch there is one of the " ..
                "lake's massive corpse-fed pikes. However, they only bite on a very specific type of " ..
                "bait... corpse worms.\n\nSearch the graves in the courtyard up top and you should find " ..
                "some.",
            rewardItems = {{67414, 1}},
            rewardMoney = 114000,
        },
        [29321] = {
            description = "It seems like everyone I know loves clams, but I can't stand them! They're " ..
                "smelly and slimy, and harvesting them means digging through mud. Give me a fishing pole " ..
                "and some bait any day.\n\nStill, I want to surprise my brother with a bucket of fresh " ..
                "clams. I'd reward you if you were willing to gather those clams for me.\n\nJust go " ..
                "through the portal to Rut'theran Village and look for the clams in the shallows near the " ..
                "shore.",
            rewardItems = {{67414, 1}},
            rewardMoney = 114000,
        },
        [29322] = {
            description = "It takes a special sort of fisherman to reap the bounty of Undercity's " ..
                "burbling slime troughs. Think you can handle gathering some of the squirming, sentient " ..
                "slime mold slithering about down there?\n\nYou can try to fish them up, but they're " ..
                "wily; you might be better off just diving into the ooze and grabbing them.\n\nRemember, " ..
                "they're only useful alive and intact... who'd want to eat a dead slime mold?! Disgusting.",
            rewardItems = {{67414, 1}},
            rewardMoney = 114000,
        },
        [29323] = {
            description = "We've used up most of our food stores in taking care of refugees and feeding " ..
                "those whose homes and livelihoods were destroyed. If we don't replenish our stores, " ..
                "we'll all be in danger next time there's a bad storm or a Horde invasion.\n\nPerhaps " ..
                "you'd be willing to help me build up our stock of lake whitefish. You can catch it " ..
                "anywhere in Darnassus, and once it's dried, it'll keep until it's needed.",
            rewardItems = {{67414, 1}},
            rewardMoney = 20000,
        },
        [29324] = {
            description = "Have you met Sister Aquinne? She and I grew up together in Dolanaar, and she " ..
                "recently came to the city to study at the Temple of the Moon. We decided to go for a " ..
                "boat ride, but the clumsy oarsman managed to capsize the craft!\n\nWhen we got back to " ..
                "the shore, Aquinne's moon pendant was missing. The lakes in Darnassus are full of giant " ..
                "catfish who will gobble up anything shiny!\n\nI've been catching them nonstop, hoping to " ..
                "find the one with her pendant. I don't suppose you want to help?",
            rewardItems = {{67414, 1}},
            rewardMoney = 20000,
        },
        [29325] = {
            description = "Have you ever eaten octopus meat? It takes some getting used to, but it's my " ..
                "favorite! I even know some people who like to eat the whole thing while it's alive!\n\nI " ..
                "don't plan on trying that anytime soon, but I am out of fresh octopi at the moment. Will " ..
                "you help me gather some more? They live in the shallow water off the shore near " ..
                "Rut'theran Village.",
            rewardItems = {{67414, 1}},
            rewardMoney = 20000,
        },
        [29326] = {
            description = "Hello, <class>! My brothers and sisters of the Earthen Ring have spoken well " ..
                "of your deeds in the wake of the Cataclysm. But much remains to be done if we are to " ..
                "heal this broken world.\n\nWalk with me, friend. Preparations for a ceremony are " ..
                "underway, a ritual that I hope will be a turning point in our battle against the " ..
                "Twilight's Hammer.\n\nWhen all is done, you will be able to spread the word about our " ..
                "triumph here.",
            rewardMoney = 71000,
        },
        [29327] = {
            description = "I do know the one you seek... but I do not know if it is wise for you to " ..
                "follow him. He has cast himself into the cyclone. The winds now tear at his body and " ..
                "mind, leaving nothing but shreds of flesh and doubt.\n\nChasing after him would only " ..
                "expose you to the same fate. The wind's edge leaves nothing uncut.\n\nYou have been " ..
                "warned. Now what will you do?",
        },
        [29329] = {
            description = "With the Stonemother's blessing, I can take us to where Go'el is being " ..
                "held.\n\nWe must be careful. The Twilight's Hammer has agents all around. You help me " ..
                "hold them off while I attempt to get through to Go'el!\n\nSpeak with me when you are " ..
                "ready, and I will take you to him.",
        },
        [29331] = {
            description = "Before he passed through the portal to Mount Hyjal, Thrall asked you to follow " ..
                "him. There is something he would like you to witness.",
            rewardChoices = {{71267, 1}, {71268, 1}, {71269, 1}, {71270, 1}},
            rewardMoney = 376000,
        },
        [29332] = {
            description = "The lilies that grow around Stillwater Pond can be rendered down into a " ..
                "delightful broth.\n\nWell... by \"delightful,\" I mean \"won't immediately sicken any " ..
                "orc who drinks it.\"\n\nWhy don't you go gather some for me, hmmm? Just watch out for " ..
                "the giant flesh-eating tadpoles.",
            rewardMoney = 90000,
        },
        [29333] = {
            description = "The orc guards are always grumbling about bland and moldering Undercity fare - " ..
                "as if it's OUR fault they can't get by on a diet of mushrooms and old corpses - so I " ..
                "think it's time they learn just the sort of exotic delights we can cook up when we've a " ..
                "mind to.\n\nGather some of the freshwater snails ambling about beneath Brightwater Lake " ..
                "and I'll show them what a true culinary master can create.",
            rewardMoney = 90000,
        },
        [29334] = {
            description = "For all the grousing those Kor'kron Overseers do about Undercity food, there's " ..
                "ONE thing they'll eat in spades: My sister Audrey's Thrice-Spiced Crunchy Stew.\n\nIts " ..
                "popularity means she's always running low on ingredients. Could you gather some for her " ..
                "at the coach she sells them from?\n\nYou'll find traps all over the city; just take " ..
                "their contents to Audrey and she'll handle the rest!",
            rewardMoney = 114000,
        },
        [29338] = {
            description = "We must travel now to the Firelands. Within that realm, Go'el's burning spirit " ..
                "could become as terrible as Ragnaros himself! Prepare yourself, for we will be alone in " ..
                "a hostile world.\n\nSpeak with me when you are ready... and may the ancestors protect us!",
        },
        [29342] = {
            description = "The best tastin' fish live in the cold waters o' Dun Morogh, <name>, an' don't " ..
                "let anyone else tell ye otherwise! Me favorite, an' the most popular one in Ironforge, " ..
                "is the arctic char, which only comes from our ancestral lands.\n\nI like tae think o' it " ..
                "as Ironforge's gift t' the world!\n\nWhy don't ye try yer hand at catchin' a few " ..
                "yerself? The best place tae find 'em is down in Helm's Bed Lake, in the eastern end o' " ..
                "Dun Morogh.",
            rewardItems = {{67414, 1}},
            rewardMoney = 114000,
        },
        [29343] = {
            description = "I'm sure by now ye've heard the tale o' Old Ironjaw, the most famous and " ..
                "elusive fish in the waters o' Ironforge's Forlorn Cavern. Well, in his many years, he's " ..
                "been responsible for the rise o' many young ironjaws. Don't let the name fool ye, " ..
                "<name>, these young'uns are every bit as clever as their dad, but somewhat lackin' in " ..
                "experience.\n\nWith skill an' patience, ye could probably catch one, an' when ye do, " ..
                "bring it to the museum in Ironforge's Library an' put it on display fer all to see!",
            rewardItems = {{67414, 1}},
            rewardMoney = 114000,
        },
        [29344] = {
            description = "Hae I introduced ye tae me pet, Squirky? I'm teachin' him tae fish all " ..
                "proper-like. Fer now, I've been feedin' him minnows fished from the pool in this " ..
                "cavern.\n\nMaybe ye'd like tae give it a try? Just cast yer lure in the pool over there " ..
                "and feed Squirky any minnows ye happen tae fish up. He'll love ye ferever!",
            rewardItems = {{67414, 1}},
            rewardMoney = 20000,
        },
        [29345] = {
            description = "A well-meaning goblin visitor introduced Azshara snakeheads to our waters and " ..
                "now they're overrunning the pond.\n\nPlease, if you can catch some of these voracious " ..
                "predatory fish before they eat every smallfish and mud snapper in Thunder Bluff, I'd be " ..
                "terribly grateful.",
            rewardItems = {{67414, 1}},
            rewardMoney = 90000,
        },
        [29346] = {
            description = "One of the Forsaken from the Pools of Vision came to me and said he'd lost his " ..
                "ring to a blind cavefish in the waters there.\n\nOr perhaps it was his finger. It was " ..
                "hard to tell; his jaw did not move and his Orcish was no better than mine.\n\nIn any " ..
                "case, I thought it would be a kind gesture towards our unusual visitors to catch and gut " ..
                "cavefish until the ring - or finger - was found.\n\nWould you help?",
            rewardItems = {{67414, 1}},
            rewardMoney = 114000,
        },
        [29347] = {
            description = "If ye've ever fished fer crayfish, ye know they respond best to live bait, an' " ..
                "the more bait, the better. Would ye like to test my new bait? Simply smear this on " ..
                "yerself an' hop into Helm's Bed Lake in eastern Dun Morogh.\n\nAfter ye've got the " ..
                "catch, take it to me friend, Cook Ghilm at Gol'Bolar Quarry, west of the lake. He's an " ..
                "expert at cookin' those oversized bugs!",
            rewardItems = {{67414, 1}},
            rewardMoney = 82000,
        },
        [29348] = {
            description = "Thunder Bluff's fishing pond is being overrun with voracious Azshara " ..
                "snakeheads; there are hardly any smallfish or mud snappers left.\n\nWe already have " ..
                "fishers trying to kill as many snakeheads as they can, but can you assist us in our " ..
                "restocking efforts?\n\nIf you could gather some fish from Stonebull Lake and bring them " ..
                "here to Thunder Bluff, I would be very grateful.",
            rewardItems = {{67414, 1}},
            rewardMoney = 114000,
        },
        [29349] = {
            description = "One of the great delicacies of Mulgore is the crayfish that dwell in our lakes " ..
                "and streams. They are particularly popular during weddings or the celebration of a " ..
                "birth.\n\nWould you help me catch some of these crafty crustaceans for the cooking pots " ..
                "of Thunder Bluff?\n\nYou can fish them up from Stonebull Lake, or simply dive in and " ..
                "grab them.",
            rewardItems = {{67414, 1}},
            rewardMoney = 114000,
        },
        [29350] = {
            description = "One o' the gnomish engineerin' trainers gave me a blueprint fer a fancy lure " ..
                "he says'll help me catch fish faster and keep 'em from gettin' away. The whole thing " ..
                "sounds a mite silly if ye ask me, but I'll try anythin' once.\n\nHere are the " ..
                "blueprints. Ye're going to need shiny baubles, which ye can buy from my assistant inside " ..
                "the buildin', a hair trigger ye can buy from an engineerin' supplier in Tinker Town, and " ..
                "a few rat traps from the Deeprun Tram.",
            rewardItems = {{67414, 1}},
            rewardMoney = 900,
        },
        [29351] = {
            description = "The guards who defend Ironforge put their lives on the line against our many " ..
                "enemies, and it's up to us to take care of them.\n\nToday, their rations consist of two " ..
                "dwarven favorites, haggis and Ironforge pale ale. Would ye be so kind as to help me " ..
                "distribute them? That way, everyone gets his food in a timely manner and we can move on " ..
                "to other tasks.",
            rewardMoney = 114000,
        },
        [29352] = {
            description = "Oh, no, <name>, this is going to be a disaster if we don't find some chicken " ..
                "soon... Ye just cannae make cock-a-leekie soup without the chicken! It's not " ..
                "possible!\n\nThere's still time to make the soup and broth if ye can find some fresh " ..
                "chicken. Will ye help me? There are usually a few chickens running around outside the " ..
                "front entrance to the city. If ye can get yer hands on, say, six o' them, that should " ..
                "save me soup.",
            rewardMoney = 56000,
        },
        [29353] = {
            description = "The haggis must flow. Aye, it's a figure o' speech, for haggis'll ne'er flow! " ..
                "Ye dinnae want to know what'll happen if the people o' Ironforge don't get their " ..
                "haggis.\n\nI'm working on the next batch, but I'm still missing a couple of " ..
                "ingredients.\n\nSognar Cliffbeard is the meat vendor in the Military Ward, an' he'll " ..
                "sell you the big bag o' sheep innards I need. Ye can buy mild spices from any cooking " ..
                "supplier and ye can find sacks o' oatmeal in any inn or among the supplies in the city.",
            rewardMoney = 114000,
        },
        [29354] = {
            description = "One of a fisher's most simple and effective tools is the shiny bauble; affixed " ..
                "to a line, even the most novice angler has a chance at a catch.\n\nWith all the fishing " ..
                "going on of late, though, Thunder Bluff is in woefully short supply!\n\nMight I ask you " ..
                "to collect shiny stones from around the base of the central rise? Bring them to Nahari " ..
                "Cloudchaser so that she might craft more shiny baubles with them.",
            rewardItems = {{67414, 1}},
            rewardMoney = 114000,
        },
        [29355] = {
            description = "It might seem like a basic thing, <name>, but spice bread is a longtime " ..
                "favorite in Ironforge. Some days, I have trouble keeping up!\n\nWould ye like to cook " ..
                "some to practice yer skills an' help meet the demand? Ye can buy all the ingredients " ..
                "ye'll need from me brother, Emrul Riknussun, who is downstairs.",
            rewardMoney = 114000,
        },
        [29356] = {
            description = "My stocks o' IPA, that's Ironforge Pale Ale for ye novices, are gettin' low. " ..
                "Luckily, the brewery isn't too far away an' they should have a new cask o' Drugan's IPA " ..
                "waitin' fer us. That Drugan's a genius of a brewer, I tell ye.\n\nI won't be able to get " ..
                "down to Kharanos meself today, but perhaps ye can dash down there, pick up the new cask " ..
                "an' run it back 'ere? What d'ye say?",
            rewardMoney = 114000,
        },
        [29357] = {
            description = "Isn't it amazing how something as simple as spice bread is used every day in " ..
                "Darnassus? When I'm not seeing to my other responsibilities, I like to bake spice bread " ..
                "to hone my skills as a cook and practice my technique.\n\nWhy don't you give it a try? " ..
                "You should be able to get your ingredients here in the shop.\n\nNo matter how much we " ..
                "make, it never goes to waste. Bring me your loaves when you're done and I'll have " ..
                "someone share them with our friends, the Gilneans.",
            rewardMoney = 20000,
        },
        [29358] = {
            description = "The Shu'halo use pine nuts in so MANY dishes: meat, fish, vegetables, even " ..
                "baked into breads or sprinkled over sweet pastries.\n\nThe Earth Mother has blessed us " ..
                "in that the very BEST pine nuts come from the trees upon these very mesas. Simply gather " ..
                "pine cones and toast them over a cooking fire to release the nuts within.\n\nWould you " ..
                "please be so kind as to gather some? There are hardly ever enough to go around...",
            rewardMoney = 110000,
        },
        [29359] = {
            description = "Herring is one of the most sought-after fish in Darnassus, but not just any " ..
                "herring. The Kaldorei herring is native only to the waters surrounding Teldrassil.\n\nI " ..
                "try to keep a good supply of it because it's so versatile! I just finished smoking a " ..
                "batch of it, so I need to rebuild my stocks. Would you mind helping me? You can catch " ..
                "Kaldorei herring by fishing in Rut'theran Village.",
            rewardItems = {{67414, 1}},
            rewardMoney = 94000,
        },
        [29360] = {
            description = "It's not always about making food for the orcs, <class>. This time, it's about " ..
                "making food for what will hopefully be their replacements.\n\nWe need to start small, we " ..
                "need to catch flies. Flies love rotting meat, and we love rotting meat... as projectile " ..
                "weapons!\n\nCheck out the Meat Wagons for any extra bits of meat. Where you find the " ..
                "meat, you'll find the flies.\n\nBring me 25 bloated flies, and then I can start on the " ..
                "next stage of our cooking plan.",
            rewardMoney = 114000,
        },
        [29361] = {
            description = "Sometimes fishing means throwing something back, <class>.\n\nWe've been " ..
                "overfeeding these frogs for just that occasion. We've fed these frogs bloated spiders, " ..
                "that were fed bloated flies, and now, we are going to feed a real monster.\n\nThe moat " ..
                "above, in the Ruins of Lordaeron, is home to our very own moat monster.\n\nToday is " ..
                "feeding day. But we must train it as well. In this bag, you will find a decoy kit and " ..
                "some bloated frogs. Use the decoy kit, then toss the frogs to the monster when it " ..
                "appears.",
            rewardItems = {{67414, 1}},
            rewardMoney = 114000,
        },
        [29362] = {
            description = "You know of the Pools of Vision, yes?\n\nThere is a sort of mushroom that " ..
                "grows there... not the tough, rank fungi that dominates the place, but smaller, more " ..
                "delicate caps that grow beneath them.\n\nThey are rare and quite delicious, adding a " ..
                "flavor to meat dishes that one might even call magical.\n\n...what? No, really. They " ..
                "just taste good. That's it.",
            rewardMoney = 90000,
        },
        [29363] = {
            description = "I am often asked, \"Aska, who is making all this Mulgore spice bread?!\"\n\nIt " ..
                "is a reasonable question. Our fine and noble bread is traded in countless settlements in " ..
                "the most far-away lands, even by our staunchest foes. IT'S JUST THAT GOOD.\n\nAnd the " ..
                "answer...?\n\nIt is \"YOU.\" Please take this packet of Mulgore spices and use it to " ..
                "turn bland, boring spice bread into MULGORE spice bread!",
            rewardMoney = 114000,
        },
        [29364] = {
            description = "One of Thunder Bluff's most important staples is cornmeal; bowls of corn may " ..
                "be found in nearly every home.\n\nWith so many of the local mills under constant attack " ..
                "by harpies, gnolls, reckless mining companies and Earth Mother knows what else, I often " ..
                "ask my students to help with the task of grinding corn into cornmeal.\n\nWould you care " ..
                "to help?",
            rewardMoney = 90000,
        },
        [29365] = {
            description = "Even the novice cook knows that a great dish begins with great " ..
                "ingredients.\n\nI have standing orders with merchants throughout Thunder Bluff, but I'd " ..
                "like to see how well you do at selecting the very best of what they have to " ..
                "offer.\n\nPlease make the rounds and gather perfect portions of meat, fish, vegetables " ..
                "and herbs from local merchant stalls.",
            rewardMoney = 114000,
        },
        [29387] = {
            description = "The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave " ..
                "heroes to assist with a full-scale assault on the Firelands.\n\nWilling and able-bodied " ..
                "heroes of the Alliance should report to the Sanctuary of Malorne in Mount Hyjal " ..
                "immediately.",
        },
        [29389] = {
            description = "Your work has given us the advantage we need to mobilize against the denizens " ..
                "of the Firelands. We are gathering our invasion force just south of our position.\n\nWe " ..
                "could use your strength again, <race>. Speak with Matoclaw at the Sanctuary of Malorne. " ..
                "She is coordinating the invasion effort.",
        },
        [29390] = {
            description = "The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave " ..
                "heroes to assist in defending Mount Hyjal from elemental invaders. These invaders must " ..
                "be repelled before forces can mobilize for a direct assault on the Firelands.\n\nWilling " ..
                "and able-bodied heroes should report immediately to Mount Hyjal and assist the ancient " ..
                "defenders: Lo'gosh, Tortolla, Aviana, and Aessina.\n\nNew travelers to Mount Hyjal may " ..
                "look for a Warchief's Command to Hyjal on any Horde call board. See if you've already " ..
                "completed this by typing:\n\n/run print(C_QuestLog.IsQuestFlaggedCompleted(29390))",
        },
        [29408] = {
            description = "Every wisdom has a time and place, and times are changing for those of us " ..
                "living here on Shen-zin Su. For this lesson, I would ask two things of you.\n\nFor the " ..
                "first, I hold a flame in my hand. Gather your wits, and when you think you are ready, " ..
                "attempt to snatch the flame.\n\nShould you succeed, I want you to then climb to the top " ..
                "of this temple and burn the Edict of Temperance that you find there.",
            rewardMoney = 35,
        },
        [29409] = {
            description = "<name>, I see great strength and great courage in you, and an unsurpassed " ..
                "purity of soul.\n\nThe hour is young, but I think you may be ready to face a greater " ..
                "challenge.\n\nGo to the bottom of the stairs, and cross the bridge. There, you will find " ..
                "Jaomin Ro, one of our eldest students. Challenge and defeat him in honorable combat, and " ..
                "this first phase of your training will be complete.",
            rewardChoices = {{73220, 1}, {73221, 1}, {73222, 1}},
            rewardMoney = 100,
        },
        [29412] = {
            description = "Please, <mister/miss>, you just gotta help me!\n\nFather bought me a bunch of " ..
                "balloons from the Darkmoon Faire. They're magical, you know, and never lose their " ..
                "floatiness!\n\nThere's just one thing...\n\nA gust of wind blew them out of my hands. " ..
                "They're scattered all over Stormwind!\n\nI'd chase after them myself, but this city's so " ..
                "big I'd get lost for sure.\n\nCan you find them for me before they float away?\n\nPlease?",
            rewardItems = {{72042, 1}},
            rewardMoney = 1200,
        },
        [29418] = {
            description = "Now that that's done with, let's get to it then!\n\nHuo, the spirit of fire, " ..
                "hungers for dry dogwood root kindling. It grows among the trees south of the village. It " ..
                "should be easy enough for you to gather some.",
            rewardMoney = 75,
        },
        [29422] = {
            description = "You are worthy of passing, <class>.\n\nHuo, the spirit of fire rests in the " ..
                "chamber beyond. Let him feast upon the kindling you've gathered, and use the wind to fan " ..
                "his flames. Doing so should endear you to him. Once he is ignited, if he is willing, " ..
                "lead him to the Temple of Five Dawns, the building standing high in the center of the " ..
                "island.",
            rewardMoney = 75,
        },
        [29423] = {
            description = "< Huo bounces around excitedly, ready to follow you.>\n\n< Master Shang Xi " ..
                "told you to bring Huo to meet him at the Temple of Five Dawns in the center of the " ..
                "island. Your next destination lies before you.>",
            rewardChoices = {{73233, 1}, {73234, 1}, {73235, 1}, {73236, 1}},
            rewardMoney = 50,
        },
        [29437] = {
            description = "Fandral Staghelm was kept prisoner here in Hyjal. It was the green dragon " ..
                "Alysra - one of my very own! - who was in charge of keeping Fandral secure.\n\nWe can " ..
                "only conclude that the Twilight's Hammer has gotten to her. You must confront her, " ..
                "<name>. Destroy her if you must - I cannot bear to see it.\n\nShe was last seen in the " ..
                "Ruins of Lar'donir, west of the World Tree.",
            rewardMoney = 188000,
        },
        [29440] = {
            description = "The Earthen Ring calls to you once more, <name>.\n\nThrall has cast aside his " ..
                "mantle as warchief of the Horde, but in his new role he needs the support of his people " ..
                "more than ever. He has requested one of the Horde's finest to accompany him in his next " ..
                "endeavor, a ritual of healing that will profoundly impact our world.\n\nYou will find " ..
                "him under the boughs of Nordrassil in Mount Hyjal, on the southern side of the tree. " ..
                "Heed the call!",
        },
        [29452] = {
            description = "<A pleasant image fills your mind's eye as a calm voice echoes through your " ..
                "being.>\n\nYoung <class>, be still and hear my words.\n\nI am called to collect you, to " ..
                "deliver you, to one whose eye none can escape.\n\nFind me in Orgrimmar, mortal, for your " ..
                "time has come.",
            rewardMoney = 47000,
        },
        [29453] = {
            description = "<A pleasant image fills your mind's eye as a calm voice echoes through your " ..
                "being.>\n\nYoung <class>, be still and hear my words.\n\nI am called to collect you, to " ..
                "deliver you, to one whose eye none can escape.\n\nFind me in Stormwind, mortal, for your " ..
                "time has come.",
            rewardMoney = 47000,
        },
        [29475] = {
            description = "A skilled engineer can choose ONE specialization, and I know the secrets of " ..
                "goblin engineering.\n\nYou look like you're ready to blow things up, but I'll need some " ..
                "samples of your work. Bring me twenty big iron bombs, twenty sticks of solid dynamite, " ..
                "and five explosive sheep.\n\nSubmit these items to an engineering trainer in any of the " ..
                "capital cities and you'll be an official goblin engineer with access to all the " ..
                "schematics!",
        },
        [29477] = {
            description = "A skilled engineer can choose ONE specialization, and I can teach you the ways " ..
                "of gnomish engineering.\n\nYou look like you know what you're doing, but I'll need some " ..
                "samples of your work. Bring me six mithril tubes, an accurate scope, and two advanced " ..
                "target dummies.\n\nSubmit these items to an engineering trainer in any of the capital " ..
                "cities and you'll be an official gnomish engineer with access to all the schematics!",
        },
        [29481] = {
            description = "Elixirs are all about potency! If you want to become an elixir master, I can " ..
                "teach you.\n\nI can't just train anyone, and I require proof that you are devoted before " ..
                "we continue. Several flasks should be sufficient to show your dedication.\n\nRemember " ..
                "<name>, you can only learn ONE specialization, so if you complete your elixir training, " ..
                "then potion and transmutation specialization will no longer be available.",
        },
        [29482] = {
            description = "Iron to gold, water to fire... if you want to become an transmutation master, " ..
                "then I can show you the way.\n\nThe training is very expensive, so you'll have to bring " ..
                "me some of the finest transmuted materials in the world.\n\nRemember <name>, you can " ..
                "only learn ONE specialization, so if you complete your transmutation training, then " ..
                "potion and elixir specialization will no longer be available.",
        },
        [29522] = {
            description = "Another of my most talented students is awaiting you in Wu-Song Village to the " ..
                "northwest. He is of a different mind than Aysa, but in their differences, they bring " ..
                "balance to each other.\n\nJi Firepaw will instruct you on gathering the offerings for " ..
                "the spirit of fire. Trust in his wisdom.",
            rewardMoney = 13,
        },
        [29523] = {
            description = "Strange thing about wind, it can be hard to wrap your hands around it.\n\nBest " ..
                "practice for me has been finding some sort of living wind. If it can punch you, you can " ..
                "punch it back, and it won't slip through your grasp.\n\nHead over to the Shrine of the " ..
                "Summer Breeze to the south and summon just such a living wind using this wind stone. " ..
                "Best it, gather a Fluttering Breeze from it, and come back over this way so that we can " ..
                "figure out what's next.",
            rewardChoices = {{73230, 1}, {73231, 1}, {73232, 1}},
            rewardMoney = 75,
        },
        [29524] = {
            description = "Facing a living opponent is a very different thing from the stationary targets " ..
                "in the yard. Living opponents strike back. There is the very real fear of failure, and " ..
                "sometimes, even death.\n\nYou must have the courage to overcome those " ..
                "fears.\n\nChallenge the other trainees within the temple or down the steps below, and " ..
                "defeat them.",
            rewardChoices = {{73217, 1}, {73218, 1}, {73219, 1}},
            rewardMoney = 100,
        },
        [29530] = {
            description = "One of our scouts brought back unpleasant news. We've spotted a powerful agent " ..
                "of the Burning Legion in the ramparts!\n\nI need you to kill this demon before he has a " ..
                "chance to relay news of our efforts to his superiors.",
            rewardMoney = 54000,
        },
        [29531] = {
            description = "I really need you to kill some stuff for me. It's pretty important.",
            rewardMoney = 94000,
        },
        [29535] = {
            description = "The Maker serves the purpose of creating more fel orcs by infusing them with " ..
                "demon blood.\n\nMy superiors believe that we may be able to reverse the process, but we " ..
                "need samples of their blood and The Maker's infusion rod before we can know for sure.",
            rewardMoney = 58000,
        },
        [29536] = {
            description = "We know that the fel orcs are growing their forces by infusing orcs with demon " ..
                "blood.\n\nI need you to venture deep inside these unholy halls and find out how that's " ..
                "happening. We can't risk sending an army into this place until we know exactly what " ..
                "we're dealing with.",
            rewardChoices = {{25712, 1}, {25714, 1}, {25713, 1}},
            rewardMoney = 58000,
        },
        [29537] = {
            description = "In all of the Blood Furnace, there is one area where our scryers cannot reach " ..
                "despite their efforts.\n\nThis 'gap', as they've been calling it, is fairly large, and " ..
                "must be where Magtheridon is being held captive..\n\nYou must find the source of the " ..
                "interference and dispose of it.",
            rewardChoices = {{25701, 1}, {25702, 1}, {25710, 1}, {25711, 1}},
            rewardMoney = 58000,
        },
        [29538] = {
            description = "The Maker uses demon blood and a special rod to turn brown and green orcs into " ..
                "red ones. We'd like to see if we can take that blood, mess around with it a bit, and " ..
                "make it turn orcs of all colors into harmless docile lumps.\n\nYou're going to bring me " ..
                "some samples of their blood so we can see. Don't forget to grab that rod!",
            rewardMoney = 58000,
        },
        [29539] = {
            description = "As it turns out, the eggheads back at Honor Hold can't see much into this " ..
                "place. Bunch of lying lazy mages, is what they are.\n\nEither way, we don't really know " ..
                "exactly what's going on in here. So, you're going in to find out!",
            rewardChoices = {{25712, 1}, {25714, 1}, {25713, 1}},
            rewardMoney = 58000,
        },
        [29540] = {
            description = "So they've got this big ol' demon stashed away in this place, is what they're " ..
                "telling me. And there's an orc that's in charge of keeping him under wraps.\n\nKilling " ..
                "an orc is killing an orc, am I right? Doesn't matter what he did or what he's doin', " ..
                "orcs are always ripe for the slaughter!",
            rewardChoices = {{25701, 1}, {25702, 1}, {25710, 1}, {25711, 1}},
            rewardMoney = 58000,
        },
        [29541] = {
            description = "This looks bad... you'd better do something. See if you've already completed " ..
                "this by typing:\n\n/run print(C_QuestLog.IsQuestFlaggedCompleted(29541))",
        },
        [29543] = {
            description = "With the Legion to one side and the fel orcs to the other, Honor Hold is going " ..
                "to be overrun in a matter of time if we don't do something about it.\n\nHead west to the " ..
                "Hellfire Ramparts and speak with Advance Scout Chadwick. He's in charge of a covert " ..
                "operation to start an Alliance invasion on the entire citadel.",
            rewardMoney = 2800,
        },
        [29548] = {
            description = "Well, you heard the King. Admiral Taylor's last transmission came from " ..
                "somewhere in the southern seas.\n\nWe will begin our search from the air! Locating the " ..
                "Prince - the White Pawn - is of critical priority.\n\nThe Skyfire is fueled, supplied, " ..
                "and ready to depart. She and her crew idle in the sky just north of the harbor.\n\nMake " ..
                "your last preparations, then meet Admiral Rogers on the deck. We will depart without " ..
                "delay.",
            rewardMoney = 98000,
        },
        [29552] = {
            description = "We may have won the first battle, but a critical task still remains.\n\nDozens " ..
                "of Skyfire pilots were shot down during the initial aerial battle.\n\nWithout medical " ..
                "aid, their condition will deteriorate over time, until they finally perish. We are their " ..
                "only hope for survival.\n\nGo into the orchard and revive as many pilots as you can " ..
                "find.\n\nWe will leave no one behind.",
            rewardChoices = {{90384, 1}, {90385, 1}, {90387, 1}, {90388, 1}, {90389, 1}},
            rewardMoney = 98000,
        },
        [29556] = {
            description = "We've located an Alliance wreck to the south. Unfortunately, the locals have " ..
                "informed us that it's currently being scavenged by a group of creatures called " ..
                "\"hozen.\"\n\nBy pillaging our wrecked ships, these creatures have already shown that " ..
                "they aren't friendly. We can't have them taking spoils from our ships, stealing our " ..
                "supplies, and worse, potentially capturing or killing any survivors.\n\nGet down there " ..
                "and take them out! When you're done, meet up with Nodd Codejack, our SI:7 agent in the " ..
                "area.",
            rewardMoney = 98000,
        },
        [29558] = {
            description = "I see you want to save your friend. I can help you, if you will help " ..
                "me.\n\nFirst of all, it should be obvious that the fewer the Slingtail roaming around, " ..
                "the easier it will be to escape.\n\nKill the hozen guards around us, and we will be one " ..
                "step closer to freedom.",
            rewardMoney = 98000,
        },
        [29559] = {
            description = "You may be an outsider, but you and I have a common enemy in the " ..
                "hozen.\n\nMany members of my tribe are trapped in cages nearby. I have also seen your... " ..
                "Alliance... soldiers as well.\n\nI cannot leave without freeing my brethren, just as you " ..
                "cannot leave yours.\n\nThe Slingtail hold the keys to those cages. Find the keys and " ..
                "free our friends.",
            rewardChoices = {
                {81022, 1}, {81023, 1}, {81024, 1}, {81025, 1}, {81026, 1}, {81027, 1}, {81028, 1},
                {81029, 1}, {81030, 1},
            },
            rewardMoney = 98000,
        },
        [29560] = {
            description = "Hozen skulls are prized tokens among my village.\n\nWe use them to perform " ..
                "ceremonial rites, and the older the skull, the more potent its magic.\n\nLuckily for us, " ..
                "the hozen are careless, filthy beasts. They leave the skulls of their dead scattered " ..
                "among their huts and campfires.\n\nCollect these skulls for me, and I will reward you " ..
                "handsomely.",
            rewardMoney = 98000,
        },
        [29562] = {
            description = "Without healing, your friend Taylor will die. My village is just east of here, " ..
                "in the middle of the large lake.\n\nI will take Taylor myself, but the fighting is most " ..
                "dangerous in that direction.\n\nI need you to help clear a path through the hozen, so " ..
                "that I may run safely into my village.\n\nCan you do this?",
            rewardMoney = 49000,
        },
        [29563] = {
            description = "You have to help me! We were sent here to investigate the various parts of the " ..
                "reservoir, but my friends haven't come back yet, and it's been a long time.\n\nThat's " ..
                "why I need you to discover what became of them. Naturalist Bite and Weeder Greenthumb " ..
                "went this way.",
        },
        [29564] = {
            description = "My village was able to escape the naga onslaught at first. We would have all " ..
                "made it to Nagrand had it not been for my brother. He sold our souls for his own " ..
                "freedom.\n\nNow he works here as a slave driver, whipping his own brothers until their " ..
                "backs bleed. Make Mennu pay, <race>.",
            rewardMoney = 66000,
        },
        [29565] = {
            description = "From what Nahuud has told me, two mighty creatures, Rokmar the Crackler and " ..
                "Quagmirran, were among the first enslaved by the naga when they arrived. They helped to " ..
                "subjugate many of the native races of Zangarmarsh.\n\nThough it pains me greatly to ask " ..
                "you to do so, you must put them down.",
            rewardChoices = {{25540, 1}, {28029, 1}, {25541, 1}},
            rewardMoney = 66000,
        },
        [29567] = {
            description = "The spore giants may be attacking my people today, but the marsh walkers have " ..
                "taken more innocent lives than any creature I've ever seen. They are our ancient " ..
                "enemies.\n\nTheir brood mother, the Black Stalker, resides deep within this bog. If you " ..
                "were to destroy her and bring me her brain as proof, I would tell tales of your bravery " ..
                "to my grandchildren.",
            rewardChoices = {{28109, 1}, {28108, 1}},
            rewardMoney = 66000,
        },
        [29573] = {
            description = "It's nearly safe for our men to come in here and take what's rightfully ours. " ..
                "The real danger now is Shaffar's personal army that he has crawling all over this " ..
                "place.\n\nI need you to take care of his forces for me while I regain my strength.",
            rewardMoney = 70000,
        },
        [29574] = {
            description = "There is a creature not far inside these halls called Pandemonius who is able " ..
                "to twist void energies to sustain and empower itself.\n\nA bit further in lies Tavarok, " ..
                "a being that takes those same void energies and converts them into a crystalline " ..
                "structure stronger than any I've ever seen!\n\nI absolutely must obtain samples for " ..
                "further study.",
            rewardMoney = 70000,
        },
        [29575] = {
            description = "With his ward in place and his forces ready, Nexus-Prince Shaffar has been " ..
                "able to pillage this place for all it's worth without so much as an ounce of " ..
                "trouble.\n\nUnsurprisingly, Nexus-Prince Haramad isn't pleased by this, and has placed a " ..
                "hefty bounty on Shaffar's head.",
            rewardMoney = 70000,
        },
        [29576] = {
            description = "My sight has long since faded, but when the wind is right I can still smell " ..
                "the blossoms of Nectarbreeze Orchard as if they were in my own palm.\n\nToday, though, " ..
                "their fragrance is muddled with smoke. Please, if you are able, check in on the orchard " ..
                "and see that things are okay. Perhaps my old nose is playing tricks on me.\n\nYou'll " ..
                "find the orchard to the southwest, beyond the statue of the Jade Serpent.",
            rewardMoney = 49000,
        },
        [29577] = {
            description = "Have a look at that!\n\n<Ashyo motions at the massive waterfall to the " ..
                "north.>\n\nThis must be the water supply for the whole valley!\n\nThink about it, " ..
                "<name>: the pandaren use this water to grow vegetables the size of a house. Where could " ..
                "it come from? What is so special about it?\n\nThe elders among my people know a " ..
                "technique for speaking with the water and divining the future. Perhaps this same " ..
                "technique can provide insight into the water's source...\n\nIt's worth a shot at least!",
            rewardMoney = 102000,
        },
        [29578] = {
            description = "The damn mogu hit us out of nowhere! Anyone they don't kill on sight is being " ..
                "dragged away into the woods.\n\nThis is the only safehouse, and its all I can do to hold " ..
                "the door.\n\nWhat do you say, friend? Are you willing to stand up and fight for the weak?",
            rewardMoney = 98000,
        },
        [29581] = {
            description = "Ashyo must have experienced what we call the golden dream.\n\nMany of us " ..
                "working here have seen it, too - often after a long day of toiling in the pools. It is " ..
                "said this vision--and the feeling of elation it brings--is a reward to the mind for " ..
                "working the body.\n\nThere IS an easier way, though we rarely resort to it anymore: a " ..
                "tea can be brewed using lotus root and dreamleaf, which grows around the shrine on the " ..
                "upper tier.\n\nBring the dreamleaf to Yan back in town and he can brew the tea for you.",
            rewardMoney = 102000,
        },
        [29582] = {
            description = "Grek had bad night last night.\n\nShiny mummy man came into Grek 's house and " ..
                "told Grek that he had to go to Mana Tombs in Auchindoun. But Grek still trying to read " ..
                "wanted poster!\n\n< Grek 's face lights up.>\n\nGrek knows! You go find shiny mummy man " ..
                "and tell him Grek sent you. It perfect plan!",
            rewardMoney = 3600,
        },
        [29585] = {
            description = "We've tended these orchards and made cider from their nectar for generations. " ..
                "In that time, we've learned a special trick for putting out fires in a pinch.\n\n<Hanae " ..
                "pushes a jug of cider into your hand.>\n\nThe cider itself - when mixed with crushed " ..
                "gingerleaf and saliva - quickly becomes sticky and viscous. Perfect for smothering " ..
                "flames.\n\nPlease, while you're out there, try to get the flames under control. I've " ..
                "already mixed in the gingerleaf, just swig and spit.",
            rewardChoices = {
                {84243, 1}, {84244, 1}, {84245, 1}, {84246, 1}, {84247, 1}, {84248, 1}, {84249, 1},
                {84250, 1}, {88709, 1},
            },
            rewardMoney = 98000,
        },
        [29596] = {
            description = "Exarch Maladaar performs his unholy work in the deepest part of the crypts. He " ..
                "poses a threat to both of our worlds if he is not stopped.\n\nYou must slay him for the " ..
                "benefit of us all, dead and alive.",
            rewardChoices = {{29337, 1}, {29339, 1}, {29340, 1}, {29341, 1}},
        },
        [29598] = {
            description = "It was Taretha who created the original diversion at Durnholde, allowing " ..
                "Thrall to escape.\n\nNow the Infinite have captured Taretha. The diversion will not " ..
                "happen without our involvement. You must use the incendiary devices that I give you and " ..
                "burn down the internment lodges.",
        },
        [29599] = {
            description = "I have plans for my people, stranger.\n\nOne day, they shall overthrow their " ..
                "oppressors and rise as one. They will break free from the bonds that hold them and from " ..
                "that uprising shall be born the orcish Horde.\n\nWe will leave when you are ready.",
            rewardChoices = {{29316, 1}, {29317, 1}, {29318, 1}, {29319, 1}},
        },
        [29600] = {
            description = "These pools are very special: they nurture life like nothing else in " ..
                "Pandaria.\n\nUnfortunately this means they draw all kinds of attention from local fauna. " ..
                "Recently, dragon turtles have discovered that toadspawn pools are common on the tier " ..
                "just above us. They're running wild up there, trampling the lotuses and snapping at my " ..
                "workers.\n\nThey aren't much of a threat on their own, but in groups they can be pretty " ..
                "nasty. Please, if you can spare your strength, help clear them out.",
            rewardChoices = {
                {81805, 1}, {81806, 1}, {81807, 1}, {81808, 1}, {81809, 1}, {81810, 1}, {81811, 1},
                {81812, 1}, {81813, 1},
            },
            rewardMoney = 102000,
        },
        [29607] = {
            description = "I have a buyer who is interested in the eyes of the Cobalt Serpents that have " ..
                "taken up residence here.\n\nIf you were to bring me some of these rare gems, I would cut " ..
                "you a portion of the profits.\n\nDo we have a deal?",
            rewardMoney = 164000,
        },
        [29609] = {
            description = "Welcome to Northrend. I have been asked to arrange travel for you to Dalaran " ..
                "so that you can meet our friends in the city.\n\nSpeak with me and accept a ride to " ..
                "Dalaran. Once you land, make your way to The Filthy Animal.\n\nMake contact with Uda the " ..
                "Beast immediately.\n\nShe can help you bind your hearthstone to the city so you can use " ..
                "the portal in Sunreaver's Sanctuary to travel back to Orgrimmar quickly.",
        },
        [29612] = {
            description = "Lok'tar Ogar, old friend. It has been too long since last we spoke.\n\nIt is " ..
                "good to see that you emerged safely from the depths of Vashj'ir.\n\nWarchief Hellscream " ..
                "has stationed me here in Grommash Hold.\n\nBy his decree, all in service to the Horde " ..
                "are to swear allegiance to their new Warchief.\n\nYou would do well not to keep him " ..
                "waiting, <name>.",
            rewardMoney = 9800,
        },
        [29613] = {
            description = "Warlord Kalithresh is in charge of the entire Steamvault operation.\n\nI need " ..
                "you to kill him, <name>. The naga have left us with no option but violence.\n\nShow him " ..
                "no mercy.",
            rewardMoney = 176000,
        },
        [29615] = {
            description = "The Steamvault is the heart of the naga's efforts to pump the water out of " ..
                "Zangarmarsh, and Hydromancer Thespia personally oversees those efforts.\n\nTaking her " ..
                "out would seriously hinder their operation.",
            rewardMoney = 132000,
        },
        [29617] = {
            description = "People come from all over Pandaria to train at the Tian Monastery, just to the " ..
                "north of here. Probably because they never turn anybody down. They'll accept jinyu, " ..
                "hozen... or even a foreign <race> like you!\n\nMy childhood friend, Lin, just joined the " ..
                "monastery's order a few weeks ago. If you're interested in learning how our monks train, " ..
                "maybe you should go talk with her!",
            rewardMoney = 9400,
        },
        [29618] = {
            description = "How strange, to have such a foreign-looking <class> visiting our temple. Are " ..
                "you here to study?\n\nYou... you look very strong. You wouldn't have any trouble getting " ..
                "accepted into the monastery. You should talk to the High Elder, up on the balcony above.",
            rewardMoney = 9800,
        },
        [29619] = {
            description = "I heard, I heard! The High Elder wants you to train with us!\n\nThere's going " ..
                "to be a banquet for us, the trainees... and you should probably bring a gift, as a sign " ..
                "of courtesy.\n\nThe oranges in the grove south of the temple are extra-sweet right now. " ..
                "Bring some back, for the banquet.",
            rewardMoney = 98000,
        },
        [29623] = {
            description = "Perfection can be achieved through repetition. Every single student in the " ..
                "training arena below will eventually perfect his or her form... assuming they don't give " ..
                "up first. This is a fact.\n\nI encourage you to join them, <name>. As an honorary guest " ..
                "of the monastery, you are not required to perform the requisite 10,000 daily strikes. " ..
                "Simply follow the leader's example for a few minutes.",
            rewardMoney = 98000,
        },
        [29624] = {
            description = "Your next test also involves concentration and attention. I want you to " ..
                "practice your abilities on the training bags in the pit below.\n\nThe bags are hung in " ..
                "groups of two. When I call out \"Left\", attack the bag on the left. When I call out " ..
                "\"Right\", attack the bag on the right.\n\nIf you fail to follow my simple directions, " ..
                "this task will become much harder.\n\nNow beat on those practice bags until they burst, " ..
                "<name>.",
            rewardChoices = {
                {80731, 1}, {80732, 1}, {80733, 1}, {80734, 1}, {80735, 1}, {80736, 1}, {80737, 1},
                {80738, 1}, {80739, 1},
            },
            rewardMoney = 98000,
        },
        [29626] = {
            description = "We don't have many rules here, but we do have one particular rule that is " ..
                "worth remembering. If you want to eat...\n\n< Xiao 's stomach grumbles " ..
                "audibly.>\n\n...you have to work. Groundskeeper Wu can give you your chores for the day. " ..
                "He's in the market, to the west.",
            rewardMoney = 9800,
        },
        [29627] = {
            description = "First things first, though.\n\nA proper trainee needs a proper weapon. And a " ..
                "scrupulous trainee builds his own... or at least gathers the materials.\n\nThe switches " ..
                "which grow nearby should suffice for any respectable weapon. You'll also need to shop " ..
                "for black walnut extract to treat the wood. While you're there, get some ale, " ..
                "for...\n\n<Wu pauses.>\n\n...well, you know what ale is for.",
            rewardMoney = 98000,
        },
        [29628] = {
            description = "Some of our trainees have... larger-than normal appetites. We have " ..
                "occasionally had difficulty supplying enough food for all of them. In times like these, " ..
                "we have to ask for help.\n\nA kindly older woman, who lives in a small house to the " ..
                "northwest, has agreed to make some stew for our trainees. All you need to do is go and " ..
                "get it.",
            rewardMoney = 98000,
        },
        [29629] = {
            description = "The black walnut extract you purchased from Miss Whiteblossom is but one of " ..
                "many extracts we keep in stock for various applications.\n\nBlushleaf extract can be " ..
                "gathered from the flowers in the Waxwood Forest to the west. Several units can be " ..
                "extracted from one flower, but only those with calm nerves and steady hands can remove " ..
                "all of the extract from one flower.",
            rewardMoney = 98000,
        },
        [29630] = {
            description = "The greenwood sprites in the Waxwood Forest to the west pose no direct threat " ..
                "to us, this is true. However, their numbers have increased as of late, as have their " ..
                "wily antics.\n\nPart of our duty as wardens of this forest is to maintain the balance. " ..
                "Your duty is to do so by returning these sprites to the earth.",
            rewardChoices = {
                {80740, 1}, {80741, 1}, {80742, 1}, {80743, 1}, {80744, 1}, {80745, 1}, {80746, 1},
                {80747, 1}, {80748, 1},
            },
            rewardMoney = 98000,
        },
        [29631] = {
            description = "Might I ask a favor of you, trainee <name>?\n\nBefore I came to the monastery, " ..
                "I was a stranger to battle. During my time as a trainee, I performed adequately, but I " ..
                "was never placed in any real danger. Now, as a graduate and a wage-earning guard, I am " ..
                "expected to protect this perimeter at all costs.\n\nI can handle greenwood sprites, but " ..
                "the tigers in the western Waxwood are something different altogether. Would you mind " ..
                "taking care of them for me?",
            rewardMoney = 98000,
        },
        [29632] = {
            description = "Alright, <race>. I'd like to see what you're really made of.\n\nYou'll find my " ..
                "pupils all over the monastery. Challenge them to fights. Push them to their limits. They " ..
                "have been instructed to do the same to you.\n\nWin or lose, you both will come out of " ..
                "the fight stronger.",
            rewardMoney = 98000,
        },
        [29634] = {
            description = "The jinyu are long-standing allies of the pandaren, and we welcome any of " ..
                "their kind into our monastery. Husshun, one of their elder shaman, is one of our newest " ..
                "trainees.\n\nHis skills as a monk are mediocre at best, but he is still a fierce " ..
                "combatant. He should provide you with the challenge that you deserve.",
            rewardMoney = 98000,
        },
        [29636] = {
            description = "I have taught you everything that I can, <name>. It is time you spoke with " ..
                "Instructor Myang.\n\nThe fights that she stages are less traditional than the sparring " ..
                "matches I am used to. Nevertheless, the path of a traveling adventurer like yourself is " ..
                "unpredictable, and a broad knowledge of fighting styles is an admirable " ..
                "trait.\n\nFarewell, <name>, and best of luck on the remainder of your training.",
            rewardMoney = 9800,
        },
        [29639] = {
            description = "You have passed every test we prepared for you, <name>. It is now time for you " ..
                "to move on to bigger and better things.\n\n...but not before another banquet. The High " ..
                "Elder will be waiting for you at the banquet grounds to celebrate your graduation from " ..
                "our monastery.",
            rewardChoices = {{80798, 1}, {80799, 1}, {80800, 1}, {80801, 1}, {80802, 1}, {80803, 1}},
            rewardMoney = 98000,
        },
        [29644] = {
            description = "The Shadow Council has lost control of the cosmic being that they summoned " ..
                "here almost two years ago.\n\nKnown only as Murmur, it threatens to overrun the Shadow " ..
                "Council and break free into the outside world!",
            rewardChoices = {{28176, 1}, {28177, 1}, {28178, 1}, {28179, 1}},
            rewardMoney = 132000,
        },
        [29645] = {
            description = "When the Cabal found our spies, they fed them to Ambassador Hellmaw one by " ..
                "one.\n\nOur men deserve justice. Slay the ritualists binding him, then dispose of " ..
                "Hellmaw.\n\nIt is a most deserving fate.",
            rewardMoney = 88000,
        },
        [29646] = {
            description = "Well, I've done all that I can with you. Sounds like the others have, " ..
                "too.\n\nHigh Elder Cloudfall will be waiting at the banquet grounds, ready to celebrate " ..
                "your departure. Not that we're happy you're leaving... he just enjoys celebrations.",
            rewardChoices = {{80798, 1}, {80799, 1}, {80800, 1}, {80801, 1}, {80802, 1}, {80803, 1}},
            rewardMoney = 98000,
        },
        [29647] = {
            description = "The Rumpus was your final test. You have mastered the disciplines taught at " ..
                "this monastery.\n\nJust as your training began with a banquet, so shall it end. High " ..
                "Elder Cloudfall should be waiting at the banquet grounds. I'll be right behind you.",
            rewardChoices = {{80798, 1}, {80799, 1}, {80800, 1}, {80801, 1}, {80802, 1}, {80803, 1}},
            rewardMoney = 98000,
        },
        [29649] = {
            description = "Gunny is dying from a powerful curse, <name>.\n\nGrand Warlock Nethekurse " ..
                "augments his power with a pair of mystical braziers. If you bring me an ember from that " ..
                "brazier, perhaps it can counteract the dark magic?",
            rewardChoices = {{25788, 1}, {25789, 1}, {25790, 1}, {25791, 1}, {25792, 1}},
            rewardMoney = 132000,
        },
        [29651] = {
            description = "Their elite warriors are ruthless... so... powerful.\n\n< Caza'rez spits up " ..
                "blood.>\n\nYou have to kill them... or we will never defeat Kargath...",
            rewardMoney = 132000,
        },
        [29653] = {
            description = "Kargath was once one of the Horde's greatest heroes.\n\nHe now wears the false " ..
                "mantle of Warchief. Bring me his namesake weapon so that we can remember the champion he " ..
                "once was, rather than the monster he's become.",
            rewardChoices = {{25808, 1}, {25810, 1}, {25811, 1}, {25809, 1}},
            rewardMoney = 176000,
        },
        [29655] = {
            description = "Warbringer O'mrogg has killed more brave soldiers than any enemy I've ever " ..
                "encountered. He is ruthless, cunning, and extremely powerful.\n\nTake him down and bring " ..
                "me his warcloth so that we may fashion it into a banner and show them the fury of the " ..
                "Horde!",
            rewardMoney = 88000,
        },
        [29660] = {
            description = "Kael'thas' forces in the Botanica were unsuccessful in handling the numerous " ..
                "creatures contained within. We must take action to right their wrongs.\n\nThe first step " ..
                "is to eliminate their forces so that they cannot cause further problems.",
        },
        [29663] = {
            description = "I require peace to perform my meditation. Practice your arts while I meditate " ..
                "on Shu's location.\n\nOther monks practice balance and combat upon the balance poles in " ..
                "the surrounding pools. Engage them and defeat them.",
            rewardMoney = 100,
        },
        [29664] = {
            description = "You're strong of mind and strong of will, but you lack the skills to face me " ..
                "in combat. You must fight with your body, but in truth, it is your character that is " ..
                "being tested.\n\nLet us even the playing field.\n\nTake this torch, light it in the " ..
                "brazier next to me, and then use it to light the three unlit braziers around the pool.",
            rewardMoney = 75,
        },
        [29666] = {
            description = "There are dangers in the pools. The latest and most vicious are the water " ..
                "pincers. A time has come for their numbers to be diminished, and I am no longer up to " ..
                "the task.\n\nIf you could clear out some of the water pincers, I would be very " ..
                "appreciative. Beware their numbers... sometimes it's best to lure them from the " ..
                "pool-side rather than wading all the way in.",
            rewardMoney = 100,
        },
        [29667] = {
            description = "It seems that Kael'thas' forces have twisted the Botanica 's specimens beyond " ..
                "saving. I do not want to see them unleashed upon Outland as so many others " ..
                "have.\n\nThere is one, Laj, who I would like to examine. He is different somehow. " ..
                "Perhaps we can learn from him.",
        },
        [29670] = {
            description = "Thanks to you, there's a small militia of farmers hiding nearby. Hanae said " ..
                "something about giving them \"liquid courage\" which, I'm pretty sure, means they're " ..
                "sauced and ANGRY.\n\nThe mogu think they can walk all over us - we'll give them a fight " ..
                "that will open their eyes.\n\nFollow the trail through the ruins and down to the beach. " ..
                "Find their leader. When you engage him, we'll be there to back you up.",
            rewardChoices = {{80778, 1}, {80779, 1}, {80780, 1}, {80781, 1}, {80782, 1}},
            rewardMoney = 98000,
        },
        [29676] = {
            description = "It seems Shu, the spirit of water, had a play companion when he came to the " ..
                "pools throughout the years. An old pandaren we know as Old Man Liang.\n\nLiang moved " ..
                "away from the main town and stopped practicing in the pools some time ago. I am told he " ..
                "lives in a small house northeast of here, up the hill.\n\nLiang may know what has driven " ..
                "Shu away, and where the spirit might be found.\n\nGo to Liang. Ask of Shu.",
            rewardMoney = 25,
        },
        [29680] = {
            description = "We have done as Master Shang asked of us. I will return to the temple to " ..
                "inform the master of our progress. You should continue south on the road to the " ..
                "farmlands to seek out Wugou, the spirit of earth.\n\nJi awaits you at the Dai-Lo " ..
                "Farmstead, and he'll surely need your help. I must warn you, Ji can be reckless in his " ..
                "directness. Remember well the things I have taught you: discipline and patience.",
            rewardMoney = 25,
        },
        [29681] = {
            description = "Harbinger Skyriss is the heart of the problem in the Arcatraz.\n\nHe corrupted " ..
                "Warden Mellichar and made him release many of the prisoners. It is only a matter of time " ..
                "before the Harbinger himself is let loose.\n\n<name>, you cannot let a servant of the " ..
                "Old Gods live!",
            rewardChoices = {{31747, 1}, {31749, 1}, {31748, 1}},
        },
        [29684] = {
            description = "We've had a contact embedded in Magisters' Terrace gathering intelligence for " ..
                "us for some time now, but we've lost contact with him.\n\nThe information he was " ..
                "collecting is vital to our mission.",
        },
        [29685] = {
            description = "As you've now witnessed, the Legion forces work tirelessly, manipulating the " ..
                "Sunwell's power to achieve their malevolent ends.\n\nKael'thas has risen from the ashes " ..
                "of defeat and once more leads them in their efforts. He must be stopped.",
            rewardChoices = {{35487, 1}, {35488, 1}},
            rewardMoney = 44000,
        },
        [29689] = {
            description = "The time has come to lay the final blow against the fel orcs.\n\nAdvance Scout " ..
                "Chadwick awaits your presence inside the Shattered Halls of Hellfire Citadel. Make " ..
                "haste, their forces could strike against Honor Hold at any moment!",
            rewardMoney = 4400,
        },
        [29690] = {
            description = "<Nazgrim fills his lungs with sea air.>\n\nYou smell that, <name>? It's the " ..
                "smell of our home, the lands our kind have bled and died to preserve.\n\nAnd listen... " ..
                "you hear that? It's the sound of peace and safety - a haven we've carved, where our " ..
                "enemies fear to tread.\n\nRemember these things. You won't experience them again anytime " ..
                "soon. We have ourselves a war to win.\n\nNow go get settled, we're shovin' off!",
            rewardMoney = 9800,
        },
        [29694] = {
            description = "They have an airbase! I have underestimated this Alliance Captain for the last " ..
                "time. So many good warriors lost...\n\nThere must have been a few survivors who were " ..
                "able to bail during the crash. We need every able-bodied fighter we can get.\n\nFind as " ..
                "many survivors as you can in the forest below, and I will investigate the wreckage " ..
                "itself. Rally everyone together at the nearby village for a counter-attack.",
            rewardChoices = {{90330, 1}, {90332, 1}, {90333, 1}, {90335, 1}, {90337, 1}},
            rewardMoney = 98000,
        },
        [29717] = {
            description = "I tried to fight one of the jade tigers in the woods but they were too scary. " ..
                "They stare at you and you turn to a jade statue!\n\nHonest truth! Chen's sister's friend " ..
                "Ni heard it from Kai's mom.\n\nI want to be brave like you though. Can you show me how " ..
                "to beat up those jade tigers?",
            rewardChoices = {{88704, 1}, {88705, 1}, {88706, 1}, {88707, 1}, {88708, 1}},
            rewardMoney = 98000,
        },
        [29723] = {
            description = "The Jade Witch must still have Shin.\n\nI... I can't do it! I don't want to " ..
                "see the witch. Can you please go talk to her and see if she has Shin?\n\nYou're an " ..
                "adult, I don't think she would try to turn you into jade.",
            rewardItems = {{82984, 1}},
            rewardMoney = 98000,
        },
        [29725] = {
            description = "Yeah, we found Amber, she's alive, and all that. That's about where the good " ..
                "news stops though.\n\nLet's see if I can pick up where ol' Rell left off...",
        },
        [29728] = {
            description = "I must ask you to do one more thing for me, <name>.\n\nThe personal effects on " ..
                "this ship cannot be left for others to find. We'll have to destroy it.\n\nI cobbled " ..
                "together some Makeshift Dynamite from the scraps you brought me.\n\nPlace the dynamite " ..
                "anywhere on the ship, but take care not to put them too close together.\n\nThey might " ..
                "be...uh...a little unwieldy, so you should spread them out in case of premature " ..
                "detonation.",
            rewardMoney = 98000,
        },
        [29743] = {
            description = "It's plain to see that this statue and the surrounding ruins are of ancient " ..
                "origin. Clearly, this land has a deep history, which means it could not have been born " ..
                "of the cataclysm.\n\nAnd yet these waters have been explored for ages now, with no " ..
                "record of anything here but open sea.\n\nPerhaps if you were to sketch the pieces of " ..
                "this broken statue, you might shed light on the continent's origins.",
        },
        [29745] = {
            description = "<Living statues rampage through the woods.\n\nFor now, they seem content in " ..
                "pummeling the forest sprites into splinters, but if they continue any further the " ..
                "pandaren will have more than just missing jade to worry about.>",
            rewardMoney = 98000,
        },
        [29747] = {
            description = "<Mogu conjurers call forth hapless spirits from beyond, forcing them into " ..
                "statues.\n\nIt seems that destroying the statues alone will not be enough to break the " ..
                "cycle.>",
            rewardMoney = 98000,
        },
        [29749] = {
            description = "<Your mind is racked with a howl. Beneath it, a wispy voice is barely audible, " ..
                "as if from far away.>\n\nPlease... help... heart of the ruins... a ritual... " ..
                "conjuring...\n\n...should not be here...\n\nMy staff... on the altar... take it. Please " ..
                "hurry.",
            rewardChoices = {{84261, 1}, {84262, 1}, {84263, 1}, {84264, 1}, {84265, 1}, {84266, 1}},
            rewardMoney = 98000,
        },
        [29753] = {
            description = "I'm afraid I have another favor to ask, <name>.\n\nThe bottles you recovered " ..
                "contain neither the spirits of mogu ancestors nor recently slain foes; they contain " ..
                "spirits of beasts. It seems the spiritclaws have resorted to poaching in an effort to " ..
                "fuel their simulacra.\n\nThis complicates our task, for I cannot take the beasts with me " ..
                "through the bridge.\n\nTake the bottles west to Tideview Thicket and smash them to " ..
                "return the spirits to nature. Some may be blind with rage and will need to be subdued.",
            rewardMoney = 98000,
        },
        [29756] = {
            description = "I'm almost ready for the ritual, there's just one more thing we need: An " ..
                "offering.\n\nRelax, I don't mean a sacrifice. Just a bit of food.\n\nThere are sure to " ..
                "be mushrooms growing in Tideview Thicket to the northwest that are suitable for this. " ..
                "Please bring some.",
            rewardMoney = 98000,
        },
        [29757] = {
            description = "Have you heard about the crisis we're having at the pools?\n\nToads have moved " ..
                "in and are spawning like crazy! It's become a real problem for the lotus " ..
                "farmers.\n\nCoincidentally, I make a jam out of gelatinous toadspawn. I call it " ..
                "\"Bottletoads\" and it's a big hit with the kids around here. Can't keep any in " ..
                "stock.\n\nIf you're heading to the pools, you'd be doing everyone a favor by uh... " ..
                "liberating some of those toad eggs.\n\nInto this bottle. For me.\n\nJust look for " ..
                "bubbles and scoop right in!",
            rewardMoney = 102000,
        },
        [29758] = {
            description = "<This dragon turtle's massive shell is rock-hard and covered in sharp ridges. " ..
                "One of the locals could almost certainly make use of it.>",
            rewardMoney = 102000,
        },
        [29759] = {
            description = "I hope you are capable of this next task, for our lives depend on it.\n\nThere " ..
                "is only one key that will unlock our chains. Unfortunately, the key hangs around the " ..
                "neck of the hozen's pet tiger, Kung Din.\n\nThey keep the tiger in the great pit to the " ..
                "north. The only way to retrieve the key will be to kill the beast.",
            rewardChoices = {
                {90365, 1}, {90366, 1}, {90367, 1}, {90368, 1}, {90369, 1}, {90370, 1}, {90371, 1},
                {90372, 1}, {90373, 1},
            },
            rewardMoney = 98000,
        },
        [29762] = {
            description = "We recently lost a fierce battle against the hozen at Moonwater Retreat.\n\nWe " ..
                "evacuated as many of our people as we could, but still, there were many we could not " ..
                "save.\n\nWe have no tokens of our lost over which to send our prayers.\n\nIf someone " ..
                "could go and retrieve heirlooms from the dead bodies, we could properly lay them to " ..
                "rest, and move on.\n\nIt would mean so much to us if you could do this, <name>.",
            rewardMoney = 98000,
        },
        [29763] = {
            description = "The vrykul are fearless in a fight. Seems they actually yearn fer a death in " ..
                "battle. With their numbers and that ferocity, we're doomed - plain and " ..
                "simple.\n\nThere's one they esteem though, goes by the name of Ingvar. Bring him down " ..
                "and you'll deal a mighty blow to their spirit.",
            rewardChoices = {{38218, 1}, {38219, 1}, {38220, 1}},
            rewardMoney = 188000,
        },
        [29764] = {
            description = "Take it from me, <lad/lass>, them vrykul weapons be downright nasty! " ..
                "Deceptively well-balanced, wickedly sharp - just plain deadly.\n\nI need you to pilfer " ..
                "some o' them weapons before they're used on us!",
            rewardChoices = {{44374, 1}, {44375, 1}, {44376, 1}, {44377, 1}},
        },
        [29765] = {
            description = "I coulda taken out da whole lot of 'em, mon.\n\nShot 'em one by one, den " ..
                "played dead when dey be gettin' close. Fell for it every time, dey did - well almost " ..
                "every time...\n\nOne of 'em finally got wise. Called my bluff. Before I knew it, dey was " ..
                "usin' my eyes as marbles.\n\nRan off with my goods an' left me here ta die, da " ..
                "savages...\n\nHelp me, mon. Lemme die wit my dignity intact.",
            rewardMoney = 98000,
        },
        [29769] = {
            description = "I'll keep trying to find ways to wake this stubborn little guy up, but there " ..
                "is no shortage of trouble on the island it seems. The crops to the south are infested " ..
                "with virmen, rabbit-like thieves and pillagers.\n\nRascals!\n\nThey breed faster than we " ..
                "can kill them! I have the perfect solution for such a situation: kill them faster! With " ..
                "you here, <name>, that shouldn't be a problem.",
            rewardMoney = 125,
        },
        [29770] = {
            description = "The virmen to the south have been running off with all of our crops, but " ..
                "they're taking more than they can eat. They must be stockpiling them somewhere - the " ..
                "ones they like anyway.\n\nWill you go out and recover any of the uprooted crops you can " ..
                "find? I've got an island's worth of people to feed, and every single vegetable makes a " ..
                "difference.",
            rewardChoices = {{74580, 1}, {74581, 1}, {74582, 1}},
            rewardMoney = 125,
        },
        [29774] = {
            description = "Alright <name>, I was thinking about what we'd try next if the whole gong " ..
                "thing didn't work, and it came to me just like that! Water in the face always worked on " ..
                "me. It's got to be twice as effective for someone so dry and earthy!\n\nMind going over " ..
                "and asking Shu, the spirit of water, if he'll help us out? He should be playing in the " ..
                "pool next to the waterfall, just on the other side of that tree.",
            rewardMoney = 125,
        },
        [29775] = {
            description = "Well, that wraps it up here, doesn't it <name>? Now that we've got these two " ..
                "roused and all friendly towards you, we just need to get them back to the Temple of Five " ..
                "Dawns.\n\nYou go ahead. I'm going to say my goodbyes, then I'll follow you up shortly.",
            rewardChoices = {{74577, 1}, {74578, 1}, {74579, 1}},
            rewardMoney = 125,
        },
        [29777] = {
            description = "The hozen have stolen our brushes and are painting over our scrolls of wisdom " ..
                "with their own wisdoms, if you can call them that. If you're here to help, stop them and " ..
                "bring our brushes back before they can do more harm.",
            rewardMoney = 175,
        },
        [29778] = {
            description = "<name>, we must help Elder Shaopai. There are few more deserving of our " ..
                "kindness.\n\nOn the way here, you surely noticed the scrolls of wisdom hanging in the " ..
                "grotto to the south. The hozen have defiled many of them, and sadly, they are not " ..
                "recoverable. We will deal with the problem directly - burn the defiled scrolls. Wipe the " ..
                "hozen writings away entirely.\n\nDo not worry for Elder Shaopai. The people shall come " ..
                "together and help him rewrite the wisdoms in time. I shall see to that.",
            rewardChoices = {{74594, 1}, {74595, 1}, {74596, 1}},
            rewardMoney = 175,
        },
        [29779] = {
            description = "Alright <name>, this is the second time we've had to deal with ravaging hozen. " ..
                "I think it's time we take care of this problem the Huojin way. No more patience. No more " ..
                "mediation. We go to the source.\n\nWe're going into the hozen village to the north and " ..
                "we're punishing those smelly troublemakers. I've been looking forward to a chance to " ..
                "fight by your side again, <name>.",
            rewardMoney = 175,
        },
        [29780] = {
            description = "<name>, I need you to understand that the way of the Huojin is not the way of " ..
                "violence. When fighting is needed, we will not hesitate, but when fighting is not " ..
                "needed, neither do we instigate. However, the direct solution is often cutting the head " ..
                "off the snake, as they say.\n\nThe hozen have a leader instigating these attacks. If we " ..
                "remove Ruk-Ruk, we won't have to wipe the hozen out entirely.\n\nI know you are not of " ..
                "the Huojin, but are you with me in what must be done, <name>?",
            rewardChoices = {{74591, 1}, {74592, 1}, {74593, 1}},
            rewardMoney = 175,
        },
        [29781] = {
            description = "The monkeys have been stealing from the village during their attacks. We " ..
                "should be fine without some of the extra food stores, but the idea of monkeys with " ..
                "fireworks... I'm a little bit concerned. Not to mention, who knows when some fireworks " ..
                "will come in handy?\n\nHelp me recover the stolen fireworks from their village, <name>?",
            rewardMoney = 175,
        },
        [29782] = {
            description = "This giant jade tiger pillar doesn't seem to fit in amidst the hozen " ..
                "buildings.\n\nWhat it does seem is very hard. Very solid.\n\nYou know just the person to " ..
                "bring this to.",
            rewardChoices = {{74587, 1}, {74588, 1}, {74589, 1}, {74590, 1}},
            rewardMoney = 175,
        },
        [29783] = {
            description = "Gather me stone blocks from the Ridge of Laughing Winds to the south.\n\nYou " ..
                "have seen my strength twice, yet I still spy doubt within your eyes. It will not last.",
            rewardMoney = 175,
        },
        [29784] = {
            description = "Aysa has been meditating on the lake since we've arrived, all her thoughts " ..
                "focused on Dafeng. I don't know what she hopes to discover out there, but she's no fool, " ..
                "and Master Shang Xi has entrusted this task with her.\n\nYou will need to cross the " ..
                "ropes leading from the end of the dock to reach her. It shall test your balance, but I " ..
                "think you're up to the task, <name>.",
            rewardMoney = 175,
        },
        [29785] = {
            description = "If you listen long enough, the wind will carry the answer to you.\n\nDafeng, " ..
                "the spirit of air, has been scared from the skies by Zhao-Ren, the Onyx Serpent. He " ..
                "hides within the Chamber of Whispers, at the south side of the plateau.\n\nGo to him. Ji " ..
                "and I will join you there.",
            rewardMoney = 175,
        },
        [29786] = {
            description = "Dafeng, the spirit of air, is terrified by Zhao-Ren, the Onyx Serpent. We must " ..
                "help him face that fear, or face it for him ourselves.\n\nWhen I told Ji of the serpent, " ..
                "he said he had an idea and would begin preparations outside of the chamber. Despite his " ..
                "rash nature, I must admit, I envy his passion and conviction.\n\nLet us go outside and " ..
                "confront the Onyx Serpent.",
            rewardItems = {{74586, 1}},
            rewardMoney = 175,
        },
        [29787] = {
            description = "The four elemental spirits will help you speak with the land and uncover its " ..
                "plight, but first, I have one small task to ask of you.\n\nJoin me, my pupil. Accompany " ..
                "this old pandaren to the western grove.",
            rewardMoney = 225,
        },
        [29788] = {
            description = "You faced forest sprites in the Dawning Valley, but the forest sprites in this " ..
                "grove are a different breed. Crueler and more dangerous.\n\nIf you would clear some of " ..
                "these sprites out, the spirits would thank you.",
            rewardMoney = 225,
        },
        [29789] = {
            description = "I am tired, <name>. I must rest.\n\nWe have a ritual to perform, but we " ..
                "require some of the charms from this grove. If you wander the grove, you should see them " ..
                "all over hanging from the trees.\n\nIf it does not offend one as young as you, will you " ..
                "permit me to sit and recover my strength while you gather these charms?",
            rewardMoney = 225,
        },
        [29792] = {
            description = "It is up to all of you to remove the thorn from the side of Shen-zin Su. Do " ..
                "not let your differences come between you. Trust in each other.\n\nWithin the Pei-Wu " ..
                "Forest is a lone hermit. Head directly to his hut. He knows intimately of the dark " ..
                "things that now lurk in the trees.",
            rewardMoney = 300,
        },
        [29795] = {
            description = "My men are malnourished, injured, and exhausted, but they are Horde. Every one " ..
                "will fight to their dying breath. As our new ally, we will stand by you when the time " ..
                "comes, but we would stand stronger with weapons.\n\nI have my men out gathering bamboo " ..
                "stalks to fashion into spears. If you can spare the effort, we could use the extra pair " ..
                "of capable hands.",
            rewardMoney = 300,
        },
        [29797] = {
            description = "We need supplies to tend to our wounded, but the supply crates containing them " ..
                "were scattered in the crash. If you can bring back any crates you find, I would be very " ..
                "grateful.",
            rewardMoney = 300,
        },
        [29799] = {
            description = "This is more horrific than I imagined, but we can handle this. We need to " ..
                "gather the healers and close the wound. We need to save Shen-zin Su.\n\nFind any healers " ..
                "you can! Rescue them, relieve them - whatever you need to do to get them over here " ..
                "healing the wound.\n\nKeep the healers safe at all costs!",
            rewardChoices = {{74600, 1}, {74601, 1}, {74602, 1}},
            rewardMoney = 300,
        },
        [29801] = {
            description = "Hello, <name>! You've earned a reputation among the flight as having - shall " ..
                "we say - 'nimble fingers.'\n\nWe need someone of your skills for a matter of utmost " ..
                "delicacy. Before I reveal more, we need to know you're the right <man/woman> for the " ..
                "job.\n\nWhen the course of battle takes you to the Eye of Eternity, I need you to " ..
                "pickpocket Hagara the Stormbinder to retrieve a cryptomancer's decoder ring. Are you up " ..
                "to the task?",
            rewardMoney = 94000,
        },
        [29803] = {
            description = "Prince Keleseth acts as Arthas' eyes and ears in the Fjord.\n\nI don't like " ..
                "that one bit!\n\nGo and give him a round o' pain. You'll be doing the world a favor by " ..
                "doing so.",
            rewardChoices = {{39676, 1}, {39678, 1}, {39679, 1}, {39680, 1}},
        },
        [29806] = {
            description = "[ph] Find and challenge the Roaming Brawler to a fight. See if you've already " ..
                "completed this by typing:\n\n/run print(C_QuestLog.IsQuestFlaggedCompleted(29806))",
        },
        [29811] = {
            description = "Krik'thir, guardian of the gates to Azjol-Nerub, was not a traitor.\n\nHe fell " ..
                "in the War of the Spider defending our home from the Scourge.\n\nAs per his station, he " ..
                "was in possession of the key to the hidden empire. I'd like you to retrieve it so it may " ..
                "be returned to its people.",
            rewardMoney = 168000,
        },
        [29815] = {
            description = "These creatures are everywhere - and very hostile! We'll need to deal with " ..
                "them before any more Alliance show up.\n\nThis one's taken quite a beating, but I've " ..
                "still made some determinations about its anatomy.\n\nWith the proper reagents, I'll be " ..
                "able to fashion a poison that should be quite effective against this species. In fact, " ..
                "I'll just need to modify a bit of the poison I have with me.\n\nGo and find me some " ..
                "viscous chlorophyll down by the water. Any semi-sentient flora should do.",
            rewardMoney = 98000,
        },
        [29821] = {
            description = "Listen, <pal/toots>.\n\nI sent out a coupla supply drones from the gunship, " ..
                "and they've all been lost or crashed. Almost all, that is.\n\nOne of 'em buzzed right " ..
                "through the camp here and crashed out by them waterfalls.\n\nHow 'bout you see what you " ..
                "can do about bringin' the contents of that crate back here, hmm?\n\nWe're all outta " ..
                "drones, but my rocket boots might yet come in handy... or footy, as the case may " ..
                "be.\n\nHah! I just kill me...",
        },
        [29823] = {
            description = "We weren't only looking for Alliance, you know. We were also looking for those " ..
                "snooked-up, tik-flikklin' jinyu!\n\nWell, we found 'em all right...",
        },
        [29824] = {
            description = "With our leader turned to jade, our hozen guide disappeared, and a prisoner of " ..
                "war in tow, there was only one thing that Kiryn and I could do:\n\nMarch into our " ..
                "enemy's territory and deliver some vengeance.\n\nWant to know how it went?",
            rewardChoices = {{80768, 1}, {80769, 1}, {80770, 1}, {80771, 1}, {80772, 1}},
            rewardMoney = 392000,
        },
        [29827] = {
            description = "Since you've been gone, more and more of these creatures are approaching our " ..
                "camp. They appear to be amassing for a major assault!\n\nWe're going to have to take " ..
                "some drastic measures if we hope to see tomorrow.\n\nHere, take my poisoned throwing " ..
                "stars and figure out a way to thin out their numbers.",
            rewardChoices = {
                {90304, 1}, {90305, 1}, {90306, 1}, {90307, 1}, {90308, 1}, {90309, 1}, {90310, 1},
                {90311, 1}, {90312, 1},
            },
            rewardMoney = 98000,
        },
        [29828] = {
            description = "One of the fleeing Drakkari trolls told me of a great raptor king, Dred, that " ..
                "was immune to the plague.\n\nIf you could find King Dred and bring me one of his teeth, " ..
                "perhaps I could fashion it into a weapon.",
            rewardMoney = 112000,
        },
        [29833] = {
            description = "While it is true that the Prophet of Akali will trouble this world no more, " ..
                "there yet remains work to be done.\n\nThe greater part of Akali's blood has empowered " ..
                "another, and it is in him that the true danger lies.\n\nQuickly, <name>, make your way " ..
                "to Gundrak and speak with Tol'mar. He will be able to direct you further in this cause.",
        },
        [29839] = {
            description = "Dis whole mess coulda been avoided if da Drakkari had worshipped da gods " ..
                "instead of destroyin' dem.\n\nI heard dat dey have a special golem - one imbued with " ..
                "forbidden powah.\n\nBring me back a piece from dat golem so we can learn from our " ..
                "bruddas and sistahs.",
            rewardChoices = {{43171, 1}, {43172, 1}, {43173, 1}, {43174, 1}, {43176, 1}},
            rewardMoney = 204000,
        },
        [29840] = {
            description = "Gundrak looks doomed. You know dis to be true.\n\nIf you be havin' the " ..
                "courage, search for history tablets to see what brought the Drakkari Empire to such an " ..
                "end.\n\nPerhaps one day we be bringin' dem back to der former glory.",
            rewardChoices = {{43180, 1}, {43178, 1}, {43179, 1}, {43177, 1}},
            rewardMoney = 204000,
        },
        [29847] = {
            description = "Just beyond this cave lies Ravenholdt Manor. You need to get inside without " ..
                "being seen!\n\n< Mostrasz places an enchantment on you.>\n\nThere - now I'll be able to " ..
                "keep an eye on you and communicate as you venture into the compound. Now sneak into that " ..
                "manor, locate the egg, and don't get caught...",
            rewardMoney = 94000,
        },
        [29848] = {
            description = "I would gladly give my life for the Makers or their creations.\n\nHowever, " ..
                "since Loken's betrayal it seems all of Ulduar has turned on the world. One in " ..
                "particular, the Maiden of Grief, seems to reel in agony at her new orders.\n\nPlease lay " ..
                "her to rest and bring me one of her tears.",
            rewardMoney = 136000,
        },
        [29850] = {
            description = "The iron dwarves are busy at work carving out massive stone constructs that I " ..
                "fear will soon be used as powerful weapons.\n\nYou must defeat their overseer, " ..
                "Krystallus, and the dark rune giants already walking the halls before it is too late!",
            rewardMoney = 136000,
        },
        [29851] = {
            description = "With this tournament we grow ever closer to our final confrontation with the " ..
                "Lich King.\n\n<name>, fight with valor and honor. Every fighter here has gathered for " ..
                "the common good.\n\nTogether, we will stop Arthas!",
        },
        [29864] = {
            description = "We are hard at work ensuring that we minimize our losses to the Scourge war " ..
                "machine.\n\nThe vrykul here are undermining that mission by willingly joining the Lich " ..
                "King's ranks.\n\nPlease, brave champion, you must defeat their spiritual leader, Svala, " ..
                "before she leads her people into the eternal shadow!",
            rewardMoney = 222000,
        },
        [29865] = {
            description = "West of here is the Silkwood Road. It has fallen into shadow as the spiders " ..
                "there have turned to a more evil and gluttonous path.\n\nI would face these villains " ..
                "myself but someone has to defend the noodle shop from... um... dangers and such.\n\nGo, " ..
                "hero, and conquer these beasts! Should you succeed perhaps I shall regale you with some " ..
                "of my epic tales of heroism.\n\nI'll also pay you.",
            rewardChoices = {
                {80704, 1}, {80705, 1}, {80706, 1}, {80707, 1}, {80708, 1}, {80709, 1}, {80710, 1},
                {80711, 1}, {80712, 1},
            },
            rewardMoney = 98000,
        },
        [29866] = {
            description = "Ah, welcome traveler. I have need of your services!\n\nSyra Goldendraft was " ..
                "looking for some silk. Personally I hate silk as it always gets stuck in my fur.\n\nI " ..
                "really want to impress her though.\n\nIf you bring me some silk from the Silkwood to the " ..
                "west of here I will gladly pay you for your help.",
            rewardMoney = 98000,
        },
        [29871] = {
            description = "I'm not sure where Clever Ashyo got his \"Clever\" title from. All jinyu are " ..
                "clever, and I wouldn't say that he's any more clever than most of them.\n\nQuite the " ..
                "opposite, actually.\n\nAt least he's a capable fighter. He did well enough at Tian " ..
                "Monastery to be selected for our training mission.\n\nIf you want to help him look for " ..
                "the Hidden Master, you can find him along the Valley's northern border.",
            rewardMoney = 10200,
        },
        [29872] = {
            description = "Lin is more talented than she thinks she is. Strong of fist but weak of " ..
                "spirit. With more confidence, she could be better than all of us.\n\nPerhaps she will " ..
                "find the surety she needs on her trip into the west. She's probably on her way to " ..
                "Stoneplow as we speak. Stop and speak to her, if you find yourself on that side of the " ..
                "Valley.",
            rewardMoney = 10200,
        },
        [29873] = {
            description = "So... Ken-Ken. The hozen.\n\nPersonally, I'm impressed he's progressed so far " ..
                "in his training. He's got a brain between his ears, which is more than can be said for " ..
                "most of his kind.\n\nHe said he was headed east, but, seeing as we're already on the far " ..
                "east side of the valley, I can't imagine he went too far from here. Look for him at " ..
                "Zhu's Watch, in Krasarang Wilds, down the path to the south. See what he's found.",
            rewardMoney = 9400,
        },
        [29874] = {
            description = "Kang's pride regularly becomes overconfidence, which often leads him down " ..
                "dangerous paths. His current path is as dangerous as any - he is headed deep into the " ..
                "Krasarang Wilds.\n\nI wouldn't normally ask a favor of a stranger, but... would you make " ..
                "sure that he is well? It would give me relief to know that a brave <race> was looking " ..
                "out for him.",
            rewardMoney = 9400,
        },
        [29875] = {
            description = "Kang's pride regularly becomes overconfidence, which often leads him down " ..
                "dangerous paths. His current path is as dangerous as any - he is headed deep into the " ..
                "Krasarang Wilds.\n\nI wouldn't normally ask a favor of a stranger, but... would you make " ..
                "sure that he is well? It would give me relief to know that a brave <race> was looking " ..
                "out for him.",
            rewardMoney = 9400,
        },
        [29877] = {
            description = "Virmen - they no just eat our food. They trying to start farms of their own. " ..
                "The problem is... well, they ookin' dumb.\n\nYou no believe Muno? Last night, they break " ..
                "into tool sheds... steal equipment. When we wake up, we find rakes and wheelbarrows " ..
                "planted in ground.\n\nThey was WATERING them. They was trying to GROW " ..
                "WHEELBARROWS.\n\nPlease, while you out there, unbury our stuff.",
            rewardItems = {{88371, 1}},
            rewardMoney = 102000,
        },
        [29881] = {
            description = "As you have seen, this grove is abundant with beautiful pink petals. As each " ..
                "petal ages, the tone deepens and fades.\n\nIf you would be so kind, I am in need of a " ..
                "few petals that have freshly fallen. Only the ones that have just fallen will have " ..
                "precisely the right color I am after.\n\nFrom it I can forge an ink that will be " ..
                "breathtaking. Can you help me?",
            rewardMoney = 98000,
        },
        [29885] = {
            description = "We do not have time to wait around for the Admiral to recover.\n\nSully and I " ..
                "are planning to search for Anduin to the north, but we'll need supplies for our " ..
                "journey.\n\nThe lake here is teeming with wildlife, which we have received permission to " ..
                "hunt.\n\nGo and gather some supplies while Sully and I finalize our preparations.",
            rewardItems = {{83097, 10}},
            rewardMoney = 98000,
        },
        [29888] = {
            description = "I see that you and your people are desperate to find your Prince Anduin.\n\nI " ..
                "know someone who may be able to help you, a pandaren Lorewalker who knows this land " ..
                "better than anyone. I cannot guarantee what kind of reception you will receive, but he " ..
                "will almost certainly be as curious about you as you are of him!\n\nThe Lorewalker lives " ..
                "in the forest to the southwest. Tell him that the Pearlfin have sent you.",
            rewardMoney = 49000,
        },
        [29889] = {
            description = "A delicious smell wafts out from the bottle on the table.\n\nA little taste " ..
                "couldn't hurt, right?",
            rewardMoney = 49000,
        },
        [29890] = {
            description = "The dream brew is complete! This time, when you drink it, you must embrace the " ..
                "visions you see from a state of inner focus.\n\nFollow me to my pagoda, and I will teach " ..
                "you how to achieve the inner calm that we pandaren value so much.\n\nYour troubled mind " ..
                "will present you with many distractions, but just remember to stay centered!",
            rewardChoices = {{80763, 1}, {80764, 1}, {80765, 1}, {80766, 1}, {80767, 1}},
            rewardMoney = 98000,
        },
        [29892] = {
            description = "A brew's body is an important and often overlooked factor.\n\nTo create the " ..
                "perfect consistency, I will need pristine eyes from the Bog Crocolisks to the " ..
                "east.\n\nTake care. The creatures are quite vicious.",
            rewardMoney = 98000,
        },
        [29893] = {
            description = "The most distinguishing feature of the Dream Brew is its iridescent, " ..
                "dream-like color.\n\nTo the east, you will find Glittering Amberflies. I will need their " ..
                "wings to create the final luminescent color of the brew.\n\nTake this knife and use it " ..
                "to collect 8 wings.",
            rewardMoney = 98000,
        },
        [29900] = {
            description = "My father has dedicated his life to studying the Vale of Eternal " ..
                "Blossoms.\n\nThe Vale is a mythical place, sealed after the Pandaren revolution twelve " ..
                "thousand years ago. We know so little about it!\n\nMy father followed a trail of clues " ..
                "to the cave down the hill, seeking a very old poem known as the Song of the Vale, but he " ..
                "is in no condition to retrieve it. It is guarded by some sort of ancestor spirit.\n\nIf " ..
                "you are heading that way anyway, would you mind bringing it back to him?",
            rewardChoices = {
                {80749, 1}, {80750, 1}, {80751, 1}, {80752, 1}, {80753, 1}, {80754, 1}, {80755, 1},
                {80756, 1}, {80757, 1},
            },
            rewardMoney = 98000,
        },
        [29901] = {
            description = "You have done all you can for the Prince's friends.\n\nYou completed your " ..
                "mission and found the White Pawn - Prince Anduin. Admiral Taylor and the other SI:7 " ..
                "agents will be eager to have the boy safe in their custody.\n\nIt is time to return home.",
            rewardMoney = 98000,
        },
        [29903] = {
            description = "Elder Lusshan and I agree that the best path forward will be to work " ..
                "together.\n\nWe will share with the Pearlfin our superior military knowledge and " ..
                "weaponry.\n\nIn return, they will be a powerful ally should we again encounter the " ..
                "Horde.\n\nTake this crate of equipment and weapons. I need you to go around the village " ..
                "and equip the jinyu with weapons befitting their skills.",
            rewardMoney = 98000,
        },
        [29904] = {
            description = "I've prepared a team of bright young Pearlfin trainees who need field " ..
                "experience.\n\nTake them northeast, into the Bamboo Wilds, and kill any wildlife that " ..
                "you find.\n\nDon't bring them back until they're fit for battle.",
            rewardMoney = 98000,
        },
        [29905] = {
            description = "Advance scouts report that the hozen at the Slingtail Pits are amassing with " ..
                "reinforcements from their tribes to the north.\n\nOur forces are gathered for battle on " ..
                "the ridge to the northwest. They are just waiting for you.\n\nNow is the time to show " ..
                "them what we are made of. Now is the time to destroy them indefinitely.",
            rewardItems = {{84105, 1}},
            rewardMoney = 196000,
        },
        [29906] = {
            description = "Despite the hozen's apparent disarray, there is an order to their chaos. Their " ..
                "leader, Chief Gukgut, is the shrewd mastermind behind their attacks.\n\nHe is organizing " ..
                "their movements at the great pit at the hozen camp to the northwest.\n\nStrike now and " ..
                "show him no mercy, <name>, for he will do the same.",
            rewardChoices = {
                {80788, 1}, {80789, 1}, {80790, 1}, {80791, 1}, {80792, 1}, {80793, 1}, {80794, 1},
                {80795, 1}, {80796, 1}, {80797, 1},
            },
            rewardMoney = 196000,
        },
        [29907] = {
            description = "My niece and I are new to Pandaria. Probably like yourself. We're visitors " ..
                "from the Wandering Isle, and, to be honest, we have no idea where we're going.\n\nThat " ..
                "farm up ahead looks as fine a place as any to take off our shoes and enjoy a brew. What " ..
                "do you say, Li Li?\n\n<race>? Would you like to share the road with us?",
            rewardMoney = 10200,
        },
        [29908] = {
            description = "I apologize for the state of things around here. The virmen - those rabbity " ..
                "creatures, down the hill - have been pushing further and further into my family's farm, " ..
                "and our crops - which are normally bigger, and more delicious, by the way - have been " ..
                "suffering because of it.\n\nI'm no soldier... but you might be! Would you mind pushing " ..
                "some of these virmen off of our land?",
            rewardChoices = {
                {81769, 1}, {81770, 1}, {81771, 1}, {81772, 1}, {81773, 1}, {81774, 1}, {81775, 1},
                {81776, 1}, {81777, 1},
            },
            rewardMoney = 102000,
        },
        [29909] = {
            description = "Your help here is appreciated, <name>. I'd like to give you another job, if " ..
                "you're interested.\n\nMy son, Ang, runs the small farm just down this hill. He should " ..
                "have brought me some fruits and vegetables this morning, but I haven't seen him all " ..
                "day.\n\nWould you go down there and see what's going on?",
            rewardMoney = 10200,
        },
        [29910] = {
            description = "I went off this morning to watch my papa fight the virmen. When I came back, " ..
                "the farm was full of marmots!\n\nI don't want to kill them, but we need to get rid of " ..
                "them. Hey, I know! We can close the holes!\n\nFill in their holes with dirt, so they " ..
                "can't come out in our farm anymore.",
            rewardItems = {{88370, 1}},
            rewardMoney = 102000,
        },
        [29911] = {
            description = "Here, <name>. My father will be wanting this.\n\nThank you, again, for helping " ..
                "with the virmen.",
            rewardMoney = 10200,
        },
        [29912] = {
            description = "Most of these vegetables will be sold, but I'd like to keep some for my " ..
                "family. Specifically, my nephew Liang needs some to feed to his pigs.\n\nUnfortunately, " ..
                "the pathway to Liang's farm is currently swarming with Snagtooth virmen. We're going to " ..
                "have to ask Miss Fanny to help us out.\n\nBring some of the food we've gathered to Miss " ..
                "Fanny, who stands next to my house. Then ask her - NICELY! - to send them down to " ..
                "Liang's ranch.",
            rewardMoney = 77000,
        },
        [29913] = {
            description = "I told you earlier, my pigs are picky eaters. They need to eat meat to grow " ..
                "strong, but they don't like mutton, they don't like yak, and I'm not about to feed them " ..
                "any pig meat.\n\nThey do, however, eat meat off of the mushan beasts, and they're also " ..
                "quite partial to turtle. Both creatures can be found in abundance to the west.\n\nMy " ..
                "skills as a hunter are admittedly quite weak. Can you help out a young rancher and his " ..
                "pigs?",
            rewardChoices = {
                {88010, 1}, {88011, 1}, {88012, 1}, {88013, 1}, {88014, 1}, {88015, 1}, {88016, 1},
                {88017, 1}, {88018, 1},
            },
            rewardMoney = 102000,
        },
        [29914] = {
            description = "I try to keep an eye on my stock, but every once in a while some of them sneak " ..
                "away. With all the confusion these virmen are causing, I may have let my guard down for " ..
                "a few moments, and some of my pigs escaped.\n\nCare to look for them? I'd start by " ..
                "looking down the hill, to the west.",
            rewardMoney = 102000,
        },
        [29915] = {
            description = "I'm not the only one having trouble with his stock, it seems. One of Francis' " ..
                "sheep has wandered over to my ranch, for the third time this week. I'm beginning to " ..
                "think he needs help tending to his flock.\n\nYou should check up on him, neighbor. And " ..
                "bring this poor little thing with you.",
            rewardMoney = 10200,
        },
        [29916] = {
            description = "First the hawks came. You've probably seen some of them circling up " ..
                "above.\n\nThe wolves came shortly after. I think they smelled my weakness.\n\nI'm not " ..
                "nearly as brave as Master Shang thought I was. The master will be quite cross with me if " ..
                "I don't do something about these beasts.\n\nCan... can you help, <sir/ma'am>?",
            rewardMoney = 77000,
        },
        [29917] = {
            description = "I've been thinking... the wolves might stop attacking if we kill their pack " ..
                "leader.\n\nWe call him Lupello, and he patrols the opposite riverbank.\n\n<Francis' " ..
                "concentration is broken by another attack. Perhaps you should go deal with Lupello " ..
                "yourself.>",
            rewardMoney = 102000,
        },
        [29918] = {
            description = "<Master Shang speaks to his shepherd boy.>\n\nFrancis, you need to show " ..
                "bravery! You have everything it takes to make a great shepherd, except the courage to " ..
                "face your fears!\n\n<He looks over to you.>\n\nYou, stranger. You helped the rest of my " ..
                "family. Francis is like a second son to me.\n\nShow my apprentice what it means to lack " ..
                "fear. Use this rope to lasso and defeat one of the great white hawks above us.\n\n<Shang " ..
                "points to the sky, looks at Francis, and leaves.>",
            rewardChoices = {{81824, 1}, {81825, 1}, {81826, 1}, {81827, 1}, {81828, 1}},
            rewardMoney = 204000,
        },
        [29919] = {
            description = "Hello again, <name>. What is this, the fourth time we've run into one another " ..
                "already?\n\nSay... my keg is quickly becoming quite empty. I've heard mention of a " ..
                "brewery to the southwest, and that's where we're headed. Care to join us?",
            rewardMoney = 51000,
        },
        [29920] = {
            description = "My love, Lo, tried to get permission to marry me from the pandriarchs. Though " ..
                "they have passed beyond, their favor would carry a lot of weight.\n\nThing is, they are " ..
                "spirits, and none of the gifts or tributes we brought impress them. To win their favor " ..
                "they claimed that either Lo or a champion must defeat them in single combat.\n\nLo is a " ..
                "good man, but not a fighter.\n\nWould you be our champion?",
            rewardChoices = {{80758, 1}, {80759, 1}, {80760, 1}, {80761, 1}, {80762, 1}},
            rewardMoney = 98000,
        },
        [29922] = {
            description = "Lorewalker Cho came by and asked for you while you were gone.\n\nHe needs your " ..
                "assistance urgently in the town of Dawn's Blossom to the north. For what reason, he did " ..
                "not say.\n\nSpeak to Kitemaster Ut-Nam. He would be happy to send you there.",
            rewardMoney = 49000,
        },
        [29924] = {
            description = "Kher Shan is one big dooker.\n\nGrooked all my sons! Ick Ick, Nab Nab, Eet " ..
                "Eet, Bitty Bitty, and the others I can't remember.\n\nWikket wanna help hozen? Go grook " ..
                "Kher Shan!\n\nThe dooker's over there.\n\n< Nibi Nibi points to the east.>",
        },
        [29925] = {
            description = "Alright, I called in every favor I could. Here's what we got.\n\nCho must be " ..
                "on to something big!\n\nLemme know when you're ready to go see him - I got a ride all " ..
                "prepared for ya.",
            rewardMoney = 24500,
        },
        [29926] = {
            description = "You ever seen a shale spider, <class>? Usually harmless, just creepin' around " ..
                "eatin' rocks, but they got a taste for jade like cubs on candy. The boys call 'em " ..
                "\"nibblers.\"\n\nA few days back, we tunneled into a huge nest of these critters. They " ..
                "spilled out into the mines and went crazy, chewed up damn near everything in sight - " ..
                "including some of the boys.\n\nYou get in there and clear 'em out, and we got plenty of " ..
                "jade to spare. The quarry is directly west of here.",
            rewardMoney = 98000,
        },
        [29927] = {
            description = "<For once, the foreman lowers her voice.>\n\nLook, this ain't easy... I got " ..
                "another favor to ask. My idiot husband, Hao, is a shift lead down at the quarry. I told " ..
                "him not to go back, that it was too dangerous, but he's as stubborn as a hozen and twice " ..
                "as stupid. Says the boys need him around for \"moral support.\"\n\n<Mann " ..
                "sneers.>\n\nWhat about my moral support?! What am I gonna do if that idiot " ..
                "dies?!\n\nPlease... keep an eye out for him. Tell him to come home.\n\n<Her eyes soften " ..
                "before she turns away.>",
            rewardMoney = 74000,
        },
        [29928] = {
            description = "Our whole jade supply line has fallen apart. The mines are a death trap, " ..
                "morale is historically low, and - as if that weren't bad enough - the mason's quarter " ..
                "has been overrun by wood sprites!\n\nNow even the plants are out to ruin me!\n\nYou need " ..
                "jade so badly, you can follow the road southwest to the mason's quarter and get it from " ..
                "those glorified chopsticks yourself.",
            rewardMoney = 98000,
        },
        [29929] = {
            description = "<Hao struggles against the rubble with all his might.>\n\nHNNNGHHH!!\n\nLet me " ..
                "guess: my wife sent you? Imagine that, my delicate little snow lily all worried. Ha ha! " ..
                "She's always frettin' over me. Look--HNNGHH!!!--it'll take more than a " ..
                "little--HNNGGHHH!!--cave-in to keep ol' Hao down.\n\nSome o' the boys, on the other " ..
                "hand, are in trouble. Help 'em out if you find any, will ya? I'll be fine.\n\nReally.",
            rewardMoney = 98000,
        },
        [29931] = {
            description = "You've done great here, kid. Thanks to you, we have quite a bit of extra jade, " ..
                "and I know just the someone who could use it.\n\nMy friend Foreman Raike is running the " ..
                "great statue project at the Serpent's Heart.\n\nBring a shipment of extra jade to him, " ..
                "and tell him his old friend Mann says hello. He'll be eagerly waiting your arrival.",
            rewardMoney = 49000,
        },
        [29932] = {
            description = "You've done us a huge favor here, traveler.\n\nNow that we have enough jade to " ..
                "complete the statue, we should send word of our progress to Yu'Lon, the Jade " ..
                "Serpent.\n\nWhen you arrive, speak to Elder Sage Wind-Yi outside the entrance to the " ..
                "Temple of the Jade Serpent.\n\nIf you wish to speed your journey, speak to Kitemaster " ..
                "Shoku. I'm sure he can spare an extra kite for you.",
        },
        [29936] = {
            description = "Welcome, wikket! Me Kah Kah - chief of Grookin Hill hozen.\n\nDook Ookem " ..
                "wanted to be chief, but good wikket grook him good - big gift to Kah Kah.\n\nHozen has " ..
                "gift for good wikket too. Gift come from great crash. Hozen keep it safe for wikket.",
            rewardChoices = {{80763, 1}, {80764, 1}, {80765, 1}, {80766, 1}, {80767, 1}},
            rewardMoney = 74000,
        },
        [29937] = {
            description = "So these guys like fish, huh? Well how about we finish what you started and " ..
                "make them LOVE us?\n\nI've still got some explosive powder from the wreck, just need " ..
                "something to attract the fish.\n\nGuts is sure to do the trick - never fails. I saw some " ..
                "birds flyin' around south of town.\n\nWell? Whatcha waitin' for?",
            rewardMoney = 98000,
        },
        [29939] = {
            description = "There. I've plastered your bird guts over my explosives.\n\nI call 'em Gut " ..
                "Bombs, patent pending.\n\nSince you made friends with these fellas, how about you do the " ..
                "honors?\n\nJust light the fuse and throw 'em down by the shoreline!",
            rewardMoney = 98000,
        },
        [29940] = {
            description = "Alright, fine. I DON'T have everything under control here. I spent all morning " ..
                "fighting off virmen. I managed to clear them off of my property, but they got away with " ..
                "some of my crops.\n\nThey took them down to the river, to the south. I have no idea what " ..
                "they're doing with them, but it's probably not eating them.\n\nIf my father wants his " ..
                "delivery now, I'm going to need some help getting those crops back. Could you help me " ..
                "out?",
            rewardChoices = {
                {81796, 1}, {81797, 1}, {81798, 1}, {81799, 1}, {81800, 1}, {81801, 1}, {81802, 1},
                {81803, 1}, {81804, 1},
            },
            rewardMoney = 102000,
        },
        [29941] = {
            description = "I recognize all you've managed to do here, <class>. My report to the Warchief " ..
                "will include an account of your deeds.\n\nBut there's no time to rest!\n\nThis land must " ..
                "be charted and prepared for Horde settlement. I've already selected an away team to do " ..
                "just that.\n\nFind them before they grow comfortable here. Inform them of their mission, " ..
                "and try to convince your new friends to send along one of their own to serve as a " ..
                "guide.\n\nYou'll be staying here with me. We have preparations to make.",
            rewardMoney = 74000,
        },
        [29942] = {
            description = "You think hozen crazy, wikket? Wait til you see hozen with no slickies!\n\nNot " ..
                "enough slickies for hozen and wikkets.\n\nSnappers! Hozen hate them ookin' snappers. " ..
                "Wikkets can eat all the snappers!\n\n< Eekle Eekle points to the south.>",
            rewardMoney = 98000,
        },
        [29943] = {
            description = "Prince Anduin Wrynn. The very son of our enemy's king! Fortune has smiled on " ..
                "the Horde once again, <name>.\n\nBut there's another side of this coin. We'd be naive to " ..
                "think the child was left alone.\n\nAny Alliance scum within sight of this land must be " ..
                "searching desperately for their precious princeling.\n\nYou and I are going to scour the " ..
                "area and root out his would-be rescuers.",
            rewardChoices = {
                {80749, 1}, {80750, 1}, {80751, 1}, {80752, 1}, {80753, 1}, {80754, 1}, {80755, 1},
                {80756, 1}, {80757, 1},
            },
            rewardMoney = 98000,
        },
        [29944] = {
            description = "Before any kegs are tapped, we have work to do. These virmen are no different " ..
                "than the virmen on the Wandering Isle... a nuisance that breeds as fast as the rabbits " ..
                "they resemble.\n\nSure, we could kill every last virmen we find, but what's the point in " ..
                "needless bloodshed? Let's just take out their alphas, and they'll slow down with " ..
                "their... reproduction.",
            rewardItems = {{88375, 1}},
            rewardMoney = 102000,
        },
        [29946] = {
            description = "We've dealt with the alpha males. Now, the alpha female.\n\nVirmen aren't " ..
                "terribly selective when it comes to breeding, but most broods will still have a dominant " ..
                "mother figure. She's usually bigger, meaner, and tougher than anyone else in the " ..
                "brood.\n\nYou know, I wouldn't mind testing my skills against a warren-mother. Mind if I " ..
                "fight alongside you?",
            rewardMoney = 102000,
        },
        [29947] = {
            description = "Uncle Chen's still got his eye on me, which means I won't be wandering off any " ..
                "time soon. I guess it's up to you to take these turnips... I mean, \"carrots\"... into " ..
                "the Twisted Warren and deliver them for me.\n\nIt should be pretty simple. Just toss the " ..
                "vegetables in front of virmen, then watch their reaction when they find out it's really " ..
                "a turnip!",
            rewardItems = {{88376, 1}},
            rewardMoney = 102000,
        },
        [29948] = {
            description = "You and that Chen fellow are good people, helpin' out with the virmen like you " ..
                "are. I don't like to ask for favors, but I ain't gonna turn 'em away, either.\n\nWhile " ..
                "you're out there puttin' the hurt to those rabbit-men, you wouldn't mind keepin' an eye " ..
                "out for some bags o' hops, would ya? I'm pretty sure they lifted 'em last " ..
                "night.\n\nProbably usin' em for pillows, knowin' how they are.",
            rewardMoney = 102000,
        },
        [29949] = {
            description = "I'd say we've earned our reward. I can't wait to taste what Mudmug's been brewing.",
            rewardMoney = 10200,
        },
        [29950] = {
            description = "Uncle Chen asked me not to get into any fights while he was away... but that " ..
                "doesn't mean I can't go exploring. Finally, a chance to look around Pandaria without " ..
                "stopping every forty-seven steps for another rest!\n\nYou want to come with me? I'll bet " ..
                "there's all kinds of cool places we can visit, not too far away from here.",
            rewardMoney = 102000,
        },
        [29951] = {
            description = "While you're just hangin' around, I might as well get you involved in my whole " ..
                "beer-makin' \"process\". Ain't much of a process, really... I just mix all the stuff " ..
                "together and wait.\n\nYou probably heard - I like to use the muddy water from the " ..
                "riverbanks, to the south. Would you mind fillin' up this flask with that water and " ..
                "bringin' it back? I'll start gettin' the hops and barley all ready.",
            rewardChoices = {
                {81778, 1}, {81779, 1}, {81780, 1}, {81781, 1}, {81782, 1}, {81783, 1}, {81784, 1},
                {81785, 1}, {81786, 1},
            },
            rewardMoney = 102000,
        },
        [29952] = {
            description = "Yes, I found the Stormstout Brewery... although I didn't exactly get the warm " ..
                "reception I expected.\n\n<Chen pours himself a mug of ale.>\n\nDo you want to hear the " ..
                "story?",
            rewardMoney = 204000,
        },
        [29966] = {
            description = "Look, <name>!\n\nThese Alliance dogs built a camp up on the ridge.\n\nHere, " ..
                "take my grog. Let's make a fire they can see from Stormwind!\n\nFor the Horde!",
            rewardMoney = 98000,
        },
        [29967] = {
            description = "It's an emergency!\n\nLooks like you stirred up a hornet's nest killin' all " ..
                "them fish-folk.\n\nThey're conductin' a full-on counterattack on Grookin Hill!\n\nI was " ..
                "hopin' to get some R&D time, but we're gunna hafta put my methane-grenade theory to work " ..
                "right away!\n\nMeet me on the east side of the fort, and bring yer throwin' arm!",
            rewardChoices = {
                {80788, 1}, {80789, 1}, {80790, 1}, {80791, 1}, {80792, 1}, {80793, 1}, {80794, 1},
                {80795, 1}, {80796, 1}, {80797, 1},
            },
            rewardMoney = 98000,
        },
        [29968] = {
            description = "One word: Methane!\n\nWe're going green. Clean burning, high availability, all " ..
                "natural, and will keep the druids off my back when we get back to our neck of the " ..
                "world.\n\nThat, and I ran out of blasting powder...\n\nSo, I need your help, " ..
                "<name>.\n\nNo, no, I wouldn't ask you to do the dirty work - especially not in front of " ..
                "the general. I'll collect these 'deposits' myself.\n\nYou gather up some wood for an " ..
                "outhouse - I'm thinking long-term here!",
            rewardMoney = 98000,
        },
        [29971] = {
            description = "Hey, while you were out our scouts came back. And get this, they found some " ..
                "Alliance kid.\n\nYou should probably go debrief them.",
            rewardMoney = 9800,
        },
        [29981] = {
            description = "I'm not from here. I've never even BEEN here before today. But even I can tell " ..
                "you that something's wrong.\n\nThat wall over there was built to keep mantid off of " ..
                "pandaren lands. Now, the mantid are sending their winged scouts over the top, as if the " ..
                "wall wasn't even there!\n\nThe only reason those spindly scouts aren't dying is because " ..
                "they're attacking farmers, not soldiers. They wouldn't stand a chance against someone " ..
                "like you.",
            rewardMoney = 102000,
        },
        [29982] = {
            description = "A few farmers remain in the fields... some perilously close to the crumbling " ..
                "wall. I don't want any farmers pretending to be heroes. We will take care of this mantid " ..
                "swarm, and then they can return to their homes.\n\nMy Shado-Pan are too busy defending " ..
                "this town to organize evacuations. You want to prove yourself useful? Get those farmers " ..
                "out of harm's way.",
            rewardChoices = {
                {88019, 1}, {88020, 1}, {88021, 1}, {88022, 1}, {88023, 1}, {88024, 1}, {88025, 1},
                {88026, 1}, {88027, 1},
            },
            rewardMoney = 102000,
        },
        [29983] = {
            description = "We should be able to handle the defense of Stoneplow from here on out.\n\n<The " ..
                "Watch Commander motions towards Lin Tenderpaw.>\n\nLin here is searching for someone she " ..
                "calls \"The Hidden Master\". I believe I know who she's talking about, and I have a clue " ..
                "for you.\n\nGo north.",
            rewardMoney = 10200,
        },
        [29984] = {
            description = "We will start with a test: The Trial of Bamboo.\n\nYour friend Lin failed this " ..
                "test.\n\nFollow me, and listen carefully to my instructions.",
            rewardMoney = 102000,
        },
        [29985] = {
            description = "The mist in this forest is a constant nuisance - one which I'm glad to hand " ..
                "off to trainees like you. Strange creatures lurk in the mist between these trees, and " ..
                "they must constantly be pushed back.\n\nConsider this part of your training.",
            rewardMoney = 102000,
        },
        [29986] = {
            description = "Trainee.\n\nSeveral wards surround us, hidden in the woods near my home. They " ..
                "are quite effective at dispersing the mist, but they require constant upkeep.\n\nYou " ..
                "will find one to the north, one to the west, and one to the south. Find these wards and " ..
                "light them.",
            rewardChoices = {{81814, 1}, {81815, 1}, {81816, 1}, {81817, 1}, {81818, 1}},
            rewardMoney = 102000,
        },
        [29987] = {
            description = "You have progressed in your training, I think. Come with me, and we will " ..
                "attempt the Trial of Wood.",
            rewardMoney = 102000,
        },
        [29988] = {
            description = "I can sense your anxiety, but you are not ready yet. Your training must " ..
                "continue before you perform the final test. As for your task... I need you to fetch me " ..
                "some eggs.\n\nYes, eggs. The marshland atop the hills to the east is home to a number of " ..
                "birds, all of which are generally peaceful in nature. You should have no trouble " ..
                "gathering enough eggs to last me several weeks.",
            rewardMoney = 102000,
        },
        [29989] = {
            description = "You have accomplished much in the short time you have been here, <name>. I " ..
                "would not normally offer this test so soon... but I feel that you're ready.\n\nIt is " ..
                "time you attempted the Trial of Stone.",
            rewardChoices = {
                {81760, 1}, {81761, 1}, {81762, 1}, {81763, 1}, {81764, 1}, {81765, 1}, {81766, 1},
                {81767, 1}, {81768, 1},
            },
            rewardMoney = 204000,
        },
        [29990] = {
            description = "I told myself that, if I ever made it here to the Hidden Master, I would learn " ..
                "everything I could from him. This is my chance, <name>. I'm not going to let it slip " ..
                "away.\n\nStill, I fear that Stoneplow needs us. I left early, before we were able to " ..
                "push the mantid scouts back. I'd feel better if you would check in with the Watch " ..
                "Commander for me.\n\nOh, and if you run into the others, maybe you should tell them " ..
                "where the Hidden Master is...",
            rewardMoney = 10200,
        },
        [29992] = {
            description = "I'd like to go tell Xiao, Kang, and the others that I've found the hidden " ..
                "master, but now he won't let me leave! He says I have to pass that test of bamboo " ..
                "first.\n\n<Lin whispers:> How'd you do that, by the way?\n\nIt looks like, for the time " ..
                "being, I'm stuck here practicing my punches against this rock. And my knuckles are about " ..
                "to cave in.\n\nIf you could gather some jademoon leaves, I could prepare an ointment and " ..
                "at least numb some of this pain.",
            rewardMoney = 102000,
        },
        [29993] = {
            description = "Have you seen my son, Lo? He was here a moment ago and I told him we were " ..
                "leaving today.\n\nI'm sure he's off trying to woo that young Syra Goldendraft. That is " ..
                "the very reason we need to leave!\n\nNo son of mine is going to run off with a " ..
                "Goldendraft!\n\nI'm going to search around here for them.\n\nI do keep catching those " ..
                "two sneaking off to the Arboretum. Any chance you could head out there and look for them?",
            rewardMoney = 98000,
        },
        [29995] = {
            description = "The \"children\" you seek are not actually children but grown pandaren, " ..
                "despite what their elders might claim. Their love will not be held in check by the feuds " ..
                "of their families.\n\nYou will find both Syra and Lo at the Shrine of the Dawn, ever " ..
                "seeking an answer to their dilemma amongst the pandriarchs of old.",
            rewardMoney = 98000,
        },
        [29997] = {
            description = "Since you were so helpful at the mines, would you be willing to help us with a " ..
                "small problem here at the temple?\n\nWise Mari has been complaining recently of a " ..
                "disturbance in his temple.\n\nThe water sprites have gotten quite playful recently, and " ..
                "made off with his ceremonial staff.\n\nIf you could help him, I would be most grateful. " ..
                "I may even put in a word with the Jade Serpent for you.\n\nJust follow the path to the " ..
                "north.",
            rewardMoney = 98000,
        },
        [29999] = {
            description = "Have you seen the young serpents in the training yard?\n\nThe littles ones " ..
                "tend to be mischievous, and some of them ran off to play before the training " ..
                "session.\n\nThe Mistress will get angry if she discovers they're missing.\n\nWould you " ..
                "go find them and bring them back to me? I don't want them to get into trouble.\n\nThey " ..
                "like to play out in the open, so look for them in courtyards and around the spires.",
            rewardMoney = 98000,
        },
        [30004] = {
            description = "You have helped us more than you can ever imagine, <name>.\n\nI do not know " ..
                "what I would do if our precious scrolls were ever to be lost.\n\nPlease return to the " ..
                "Elder Sage Rain-Zhu and tell him that the library is in order.",
            rewardMoney = 49000,
        },
        [30005] = {
            description = "Do you like fireworks, <sir/miss>?\n\nI love them! In older times we would set " ..
                "them off to frighten away demons, but I just like them because they're pretty!\n\nI " ..
                "think there are still some old launchers lying around the temple.\n\nWould you go set " ..
                "off some big fireworks for me? It would make me so happy!",
            rewardMoney = 98000,
        },
        [30011] = {
            description = "Please tell the Elder Sage Rain-Zhu that I will begin my work at once.",
            rewardMoney = 49000,
        },
        [30015] = {
            description = "Blood and Thunder! My axe hungers!\n\nWe won't return to Orgrimmar until every " ..
                "last Alliance is purged from this land.\n\nI will train these natives myself, if I have " ..
                "to. One way or another, this land will be made ready for Horde settlement.\n\nIn the " ..
                "meantime, their chief gave me this to pass on to you - a map and a message in some fancy " ..
                "script.\n\nDo what you must, but be quick about it.\n\nWar is brewing...",
            rewardMoney = 49000,
        },
        [30027] = {
            description = "First, you will need a weapon suited to your talents. Retrieve a staff from " ..
                "one of the weapon racks below, bring it to me, and show me that you know how to equip it " ..
                "properly.",
            rewardMoney = 15,
        },
        [30028] = {
            description = "Since you are heading south, can you try to recover some of the grain that " ..
                "these thieves made off with?\n\nWe saw birds and sprites running off with entire bags of " ..
                "our best bulk stock into the fields east and south of here.",
            rewardMoney = 102000,
        },
        [30029] = {
            description = "So... we bought some cheap grains in bulk. It turned out the grain was " ..
                "infested with sprites.\n\nI HATE sprites. With their wee beady eyes and constant " ..
                "smiling.\n\nI would like to resolve this quietly. Can I buy your services to discretely " ..
                "eliminate some of these grain thieves?",
            rewardChoices = {{84329, 1}, {84330, 1}, {84331, 1}, {84332, 1}, {84333, 1}},
            rewardMoney = 102000,
        },
        [30030] = {
            description = "Just to be clear, what happened was an accident. What I did, I did for " ..
                "INDUSTRY!\n\nThere was no way I could have known that a sprite invasion would happen at " ..
                "any time, or that one of them would try to eat my new \"Pan's Miracle Gro\" " ..
                "formula.\n\nNow not only do they have a big sprite leading them, but he's one angry " ..
                "beast.\n\nIf I pay you, will you take him out?",
            rewardMoney = 102000,
        },
        [30031] = {
            description = "As long as you're here, you might as well help me out. I'm feeling pretty darn " ..
                "unqualified for the task, seeing as I've never drank a drop of beer in my life.\n\nYou " ..
                "should try a little sample of each of their grains. Let's see if any of this stuff is " ..
                "sweet enough for Uncle Chen.",
            rewardMoney = 102000,
        },
        [30032] = {
            description = "Looking for sweet grain? My father once mentioned a malted cave barley that " ..
                "sounds about right.\n\nIf you are willing to brave the peril, there is an ancient cave " ..
                "at the base of the Winds' Edge south of here.\n\nThere is even an old lift my father " ..
                "made when he would travel into the jungle.\n\nIn the cave is a bush as old as my family. " ..
                "From that bush you can pluck a grain so sweet it will humble your senses.\n\nJust watch " ..
                "out for its guardians.",
            rewardChoices = {
                {81787, 1}, {81788, 1}, {81789, 1}, {81790, 1}, {81791, 1}, {81792, 1}, {81793, 1},
                {81794, 1}, {81795, 1},
            },
            rewardMoney = 102000,
        },
        [30033] = {
            description = "First, you will need weapons suited to your talents. Retrieve a spellblade and " ..
                "a hand fan from one of the weapon racks below, bring it to me, and show me that you know " ..
                "how to hold it properly.",
            rewardMoney = 15,
        },
        [30034] = {
            description = "First, you will need a weapon suited to your talents. Retrieve a crossbow from " ..
                "one of the weapon racks below, bring it to me, and show me that you know how to hold it " ..
                "properly.",
            rewardMoney = 15,
        },
        [30035] = {
            description = "First, you will need weapons suited to your talents. Retrieve a mace and a " ..
                "book of prayers from one of the weapon racks below, bring them to me, and show me that " ..
                "you know how to hold them properly.",
            rewardMoney = 15,
        },
        [30036] = {
            description = "First, you will need weapons suited to your talents. Retrieve a pair of " ..
                "daggers from one of the weapon racks below, bring them to me, and show me that you know " ..
                "how to hold them properly.",
            rewardMoney = 15,
        },
        [30037] = {
            description = "First, you will need weapons suited to your talents. Retrieve an axe and a " ..
                "shield from one of the weapon racks below, bring them to me, and show me that you know " ..
                "how to hold them properly.",
            rewardMoney = 15,
        },
        [30038] = {
            description = "First, you will need a weapon suited to your talents. Retrieve a sword from " ..
                "one of the weapon racks below, bring it to me, and show me that you know how to hold it " ..
                "properly.",
            rewardMoney = 15,
        },
        [30039] = {
            description = "Freshly arrived for your training, your first task is simple: Speak to Master " ..
                "Shang Xi.",
            rewardMoney = 2,
        },
        [30040] = {
            description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.",
            rewardMoney = 2,
        },
        [30041] = {
            description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.",
            rewardMoney = 2,
        },
        [30042] = {
            description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.",
            rewardMoney = 2,
        },
        [30043] = {
            description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.",
            rewardMoney = 2,
        },
        [30044] = {
            description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.",
            rewardMoney = 2,
        },
        [30045] = {
            description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.",
            rewardMoney = 2,
        },
        [30046] = {
            description = "You know what? I don't have to take this.\n\nI'll show that Uncle Gao what it " ..
                "means to be a real brewer. I'll brew the best beer he's ever tasted, with ingredients " ..
                "I've never even used before.\n\nI'm Chen Stormstout, and I'm the best brewer alive.",
            rewardMoney = 10200,
        },
        [30047] = {
            description = "Uncle Chen is going to love this. Or... he might tell us to find something " ..
                "sweeter. He's kind of dumb like that.\n\nLet's get this grain back to him at Halfhill.",
            rewardMoney = 102000,
        },
        [30048] = {
            description = "I'll let you in on my brewing plan, <name>: I'm planning on making an Emperor " ..
                "Stout. Done right, it should be dark, roasty, and high in alcohol.\n\n<A frown appears " ..
                "on Chen's face.>\n\nI just realized... I never told my plans to Li Li. She'll have no " ..
                "idea what type of grain to bring back!\n\nCould you speak with her? I need her to bring " ..
                "back the sweetest malted grains she can find.",
            rewardMoney = 10200,
        },
        [30049] = {
            description = "Would you mind checking in on Mudmug? He may need some assistance bringing " ..
                "that water back.\n\nI'm sure he'll appreciate the help of a big, strong <class> like " ..
                "yourself to help him shoulder the load.",
            rewardMoney = 10200,
        },
        [30050] = {
            description = "You want me to just GIVE you some hops? Pfshh! This is the third time today " ..
                "some little <race> like you has come up to me asking for food!\n\nYou want food? Then " ..
                "you'd better work!\n\n<She shoves a watering can into your hand.>\n\nNow go water my " ..
                "plants!",
            rewardChoices = {
                {81844, 1}, {81845, 1}, {81846, 1}, {81847, 1}, {81848, 1}, {81849, 1}, {81850, 1},
                {81851, 1}, {81852, 1}, {81853, 1},
            },
            rewardMoney = 102000,
        },
        [30051] = {
            description = "Look at it, <name>: the Gilded Fan. I heared lots of good things about the " ..
                "water they got here. Lots of bad things, too.\n\nNo sayin' what kind of water Chen's " ..
                "gonna be needin', so what say we make him a little sampler platter?\n\nCome on, let's " ..
                "get movin'. We'll go scoop up some water together.",
            rewardChoices = {{81839, 1}, {81840, 1}, {81841, 1}, {81842, 1}, {81843, 1}},
            rewardMoney = 102000,
        },
        [30052] = {
            description = "You want some hops? I've got plenty in the shed out back. I'll gladly share " ..
                "some with you... if you'll help me weed my field.\n\nNow \"hop\" to it! Get it?",
            rewardMoney = 102000,
        },
        [30053] = {
            description = "With Li Li fetching grain, and Mudmug handling our water, all we need is hops, " ..
                "and some good wood barrels. I'll handle the barrels... but I need you to gather the " ..
                "hops.\n\nI don't know much about the hops from this land, but I'm sure the nearby " ..
                "farmers have something worth brewing with. Go see what you can rustle up.",
            rewardMoney = 102000,
        },
        [30054] = {
            description = "Virmen, they bite too much.\n\nThey bite Mung-Mung 's carrot. They bite " ..
                "Mung-Mung 's pumpkin. Mung-Mung try to shoo them away, and the dookers bite Mung-Mung 's " ..
                "tail and foot.\n\nEnough is ookin' enough.\n\nYou fight way better than Mung-Mung does. " ..
                "Bring back their bitey teeth. Then we see who does the biting.",
            rewardMoney = 102000,
        },
        [30055] = {
            description = "All three farmers have delivered their hops to Halfhill. Perhaps you should " ..
                "check in with Chen to make sure that he received them.",
            rewardMoney = 102000,
        },
        [30056] = {
            description = "Brave <class>, you could not have arrived at a better time. My daughter is " ..
                "missing!\n\nI've got a suspicion that the virmen took her down into that stinking little " ..
                "warren of theirs. I'm too old to fight virmen, and my farmhand is already exhausted from " ..
                "fighting them off all morning.\n\nCould you look for her?",
            rewardMoney = 102000,
        },
        [30057] = {
            description = "Those virmen... they make me do horrible, horrible, silly things. All " ..
                "involving carrots. I couldn't tell you how many carrots they threw at me.\n\nLet's not " ..
                "waste any more time. Get me out of here!",
            rewardChoices = {
                {81751, 1}, {81752, 1}, {81753, 1}, {81754, 1}, {81755, 1}, {81756, 1}, {81757, 1},
                {81758, 1}, {81759, 1},
            },
            rewardMoney = 102000,
        },
        [30058] = {
            description = "The esteemed Journeyman Chu would appear to have created a monster. It is " ..
                "silken death with wings.\n\nMothallus.\n\nYou have already faced its brood. Now we ask " ..
                "that you help us face the creature itself.\n\nPlease, <class>, venture into the pit and " ..
                "rifle the bait. This will bring the beast to you.\n\nOur mothfighters will assist you as " ..
                "you need, though silk tends to stick to them more than most so you may need to help " ..
                "them, should they become overwhelmed.",
            rewardChoices = {
                {88028, 1}, {88029, 1}, {88030, 1}, {88031, 1}, {88032, 1}, {88033, 1}, {88034, 1},
                {90622, 1},
            },
            rewardMoney = 102000,
        },
        [30059] = {
            description = "Oh... oh good! A <class>! Could you help me?\n\nI created a strain of vile " ..
                "monsters during my experiments to improve silk output.\n\nThe result was a full-scale " ..
                "moth rebellion. Can you use your <class>iness and destroy some of these mutants?",
            rewardMoney = 102000,
        },
        [30068] = {
            description = "Do you see the violent black and white flames erupting all around the " ..
                "temple?\n\nThe greater our doubt, the stronger they rage. Unchecked, they will devour " ..
                "the entire temple.\n\nWe have but one hope.\n\nTake flight on one of our war serpents. " ..
                "Fly it near the pure springs of water, and then douse the fires with water from the " ..
                "pools.",
            rewardMoney = 114000,
        },
        [30069] = {
            description = "Quickly and quietly; that's how SI:7 prefers to operate. That was the plan, at " ..
                "least.\n\nRell Nightwind is already inside Garrosh'ar Point looking for signs of Anduin " ..
                "and Taylor, but it's getting hot in there and he needs support.\n\nFight yer way through " ..
                "these dogs and find Rell!",
            rewardMoney = 98000,
        },
        [30070] = {
            description = "Alright <lad/lass>. We've taken enough jabs at this warlock army... now it's " ..
                "time to cut off the head.\n\nGa'trul 's back there, in that big ol' temple ruin. Give " ..
                "him a good what-for, and the Horde will have lost its last stake here in Pandaria.",
            rewardChoices = {
                {90338, 1}, {90339, 1}, {90340, 1}, {90341, 1}, {90342, 1}, {90343, 1}, {90344, 1},
                {90345, 1}, {90346, 1},
            },
            rewardMoney = 294000,
        },
        [30073] = {
            description = "We have everything we need. It's time to start brewing.\n\nPay attention, " ..
                "<name>... you might learn a thing or two.",
            rewardMoney = 10200,
        },
        [30074] = {
            description = "Now, onward to the Stormstout Brewery! It's high time that I was reunited with " ..
                "the rest of the Stormstouts... and what better way to reunite than over a few mugs of " ..
                "ale?\n\nYou know where the brewery is, right? Just follow this road to the west. You " ..
                "can't miss it. Of course, you're free to share the road with us - we'll be leaving any " ..
                "moment now.",
            rewardMoney = 10200,
        },
        [30075] = {
            description = "Are you seeing this? Virmen, hozen, and water sprites... all pouring out of " ..
                "the brewery doors and windows! What the heck is going on in there!?\n\nThere is another " ..
                "entrance, on the eastern side of the brewery. I'm going to run over there and try to " ..
                "figure out what's going on. In the meantime, see if you can't get rid of these " ..
                "creatures. There's nothing worse than a drunken hozen.",
            rewardChoices = {{81834, 1}, {81835, 1}, {81836, 1}, {81837, 1}, {81838, 1}},
            rewardMoney = 102000,
        },
        [30076] = {
            description = "I've heard lots of cockamamie rumors about this here brewery. I thought they " ..
                "were all false... until I saw that giant hozen.\n\nSo, it got me thinkin', what if the " ..
                "other rumors are true? I heard this one rumor just the other day about some water " ..
                "sprites that run around inside the brewery, causin' a ruckus and whatnot. Their bodies " ..
                "are actually MADE OF WATER.\n\nI reckon a man could make some mighty fine beer with some " ..
                "fancy water like that. If you find any, could you bring me some?",
            rewardMoney = 102000,
        },
        [30077] = {
            description = "I can't believe that giant hozen! He's just throwing barrels " ..
                "everywhere!\n\nBarrels, man!\n\nIt looks like he managed to get pretty much all the " ..
                "pandaren that were working out in front of the brewery. If I were you, I'd help some of " ..
                "them break out. Put some of those ridiculous muscles to use.\n\nWe're headed over to the " ..
                "brewery's rear entrance, to the east. Meet you there!",
            rewardMoney = 102000,
        },
        [30078] = {
            description = "That's it, <name>. I've had enough of this.\n\nIf somebody doesn't do " ..
                "SOMETHING to take care of this brewery, we'll lose it forever. And there's far too much " ..
                "family history - and beer - in there to risk wasting.\n\nSo... we're going to break in " ..
                "through the back door. You, Li Li, Mudmug, and me.\n\nIt's gonna be a brawl in " ..
                "there.\n\nLet me know when you're ready.",
            rewardChoices = {
                {81742, 1}, {81743, 1}, {81744, 1}, {81745, 1}, {81746, 1}, {81747, 1}, {81748, 1},
                {81749, 1}, {81750, 1},
            },
            rewardMoney = 306000,
        },
        [30079] = {
            description = "Pandaren always welcome travelers with open arms - and open kegs! But this " ..
                "town full of jerks!\n\nEveryone so busy sulking, they won't talk to Ken-Ken at " ..
                "all!\n\nCan you find someone in town who will talk to us? Maybe normal pandaren just " ..
                "hiding in the houses?",
            rewardMoney = 98000,
        },
        [30080] = {
            description = "My nephew, Yi-Mo, has always been sort of a downer. When this wave of despair " ..
                "hit the town, he took it harder than most. He sat around for days refusing to eat, just " ..
                "staring off into the horizon.\n\nNow he's wandered off toward the cliffs northeast of " ..
                "here, where the thunderbirds nest and hunt.\n\nPlease, <class>, will you look for him?",
            rewardMoney = 74000,
        },
        [30081] = {
            description = "Alright, Ken-Ken pretty sure he knows what wrong with pandaren! Got old, old " ..
                "hozen remedy that do the trick.\n\nNeed to mix honey, fish oil, and salt. Ken-Ken saw " ..
                "lots of beehives in the trees around town, and there must be fish left in the dry " ..
                "ponds.\n\nThat just leave salt... Mei might know where we can find some.",
            rewardMoney = 98000,
        },
        [30082] = {
            description = "Ever since this storm began, I've just been... tired.\n\nNot physically... no. " ..
                "It's like my very soul is exhausted. Worthless. Hopeless. I imagine it's what one feels " ..
                "when a mate leaves them for someone with a rounder belly, but I've never had a mate so " ..
                "how would I know?\n\nHow can I claim to know anything? I'm worthless to everyone but " ..
                "these thunderbirds. At least they'll have a good meal out of me.\n\n<Yi-Mo sighs deeply " ..
                "and continues staring off into the sky. It doesn't look like he's going anywhere.>",
            rewardChoices = {
                {81440, 1}, {81441, 1}, {81442, 1}, {81443, 1}, {81444, 1}, {81445, 1}, {81446, 1},
                {81447, 1}, {81448, 1},
            },
            rewardMoney = 98000,
        },
        [30083] = {
            description = "With our grip on the province loosening, saurok from the wilds have already " ..
                "moved in to the cave just north of town.\n\nMost of our hunters are face-down in their " ..
                "own tears, so the saurok just walk in here like they own the place and grab whatever " ..
                "they want!\n\nI want to send a message that Zhu's Watch is not to be crossed.\n\nWill " ..
                "you be my messenger?",
            rewardChoices = {{81512, 1}, {81513, 1}, {81514, 1}, {81515, 1}, {81516, 1}},
            rewardMoney = 98000,
        },
        [30084] = {
            description = "Bonfires are surprisingly effective at discouraging beasts from wandering out " ..
                "of the wilds. We have three along the border to the southwest which we normally keep lit " ..
                "at all times.\n\nNobody's been there for days, though, and the fires must be out by now. " ..
                "It's only a matter of time before the wilds creep back in and overtake the land we have " ..
                "kept safe for centuries.\n\nPlease, re-ignite the bonfires. They are critical in keeping " ..
                "the province safe, and they are memorials to the founders of our way of life.",
            rewardMoney = 98000,
        },
        [30085] = {
            description = "We need to find out what's going on inside that brewery, <name>!\n\nWe may " ..
                "have cleared out some of the bigger pests, but I'm certain there's plenty more where " ..
                "they came from. Gather up a few of your friends, and meet me inside!",
            rewardMoney = 10200,
        },
        [30086] = {
            description = "Oh, hello. Are you looking for the owner of this place? Then look to the " ..
                "pandaren up at the top of the stairs.\n\nI'm just a visitor... like you.\n\nNow if " ..
                "you'll excuse me, my friends and I are trying to decide something. We can talk again " ..
                "afterwards.",
        },
        [30088] = {
            description = "Okay, so that not work. Well... it cheer Ken-Ken up! But pandaren still " ..
                "sad...\n\nWe try another old hozen remedy - this time, we go back even further than " ..
                "gramma, way WAY back to ancient times. Hozen still do this sometimes... mostly at " ..
                "parties.\n\nKen-Ken got woodworking to do - you bring him teeth! Not yours; big ones, " ..
                "like a panther would have!\n\nOh, and some paint! Mei might know where to find.",
            rewardChoices = {
                {88053, 1}, {88054, 1}, {88055, 1}, {88056, 1}, {88057, 1}, {88058, 1}, {88059, 1},
                {88060, 1}, {88061, 1},
            },
            rewardMoney = 98000,
        },
        [30089] = {
            description = "Well... THAT was unexpected!\n\nCome to think of it, now Ken-Ken remember why " ..
                "hozen use mask in the first place...\n\nA legend about the Monkey King says he used a " ..
                "mask to cure old pandaren emperor, Shaohao, when he was too sad to lead his people. Then " ..
                "they buried mask--with all his sadness--in the ground.\n\nWe should use the mask on more " ..
                "pandaren, but instead of putting sad away in ground, we gonna PUNCH ITS BUTT.\n\nLet's " ..
                "do this, <name>!",
            rewardChoices = {
                {81467, 1}, {81468, 1}, {81469, 1}, {81470, 1}, {81471, 1}, {81472, 1}, {81473, 1},
                {81474, 1}, {81475, 1},
            },
            rewardMoney = 98000,
        },
        [30090] = {
            description = "Hmm... Is that Yi-Mo kid over there?\n\n< Ken-Ken squints against the " ..
                "increasing torrents of rain.>\n\nIt is! He's at the well, and he's not lookin' so " ..
                "good.\n\nKen-Ken got a bad feeling about this...",
            rewardChoices = {{88580, 1}},
            rewardMoney = 196000,
        },
        [30091] = {
            description = "All of this started with our ponds. In a single day, all of the water " ..
                "retreated down into the earth. When there was no more water in the ponds, it began to " ..
                "fall from the sky.\n\nDespite endless torrents of rain, the ponds do not fill. It's as " ..
                "if the land itself thirsts and cannot be quenched.\n\nNow the ponds birth horrific " ..
                "manifestations of despair. Elementals made of water from the sky and salt from the " ..
                "earth; the tears of Pandaria.",
            rewardMoney = 98000,
        },
        [30093] = {
            description = "The city has been in chaos for days now. Hiram Creed, disguised as a Gilnean, " ..
                "has infected the lot of those dogs with his own draconic blood. Even the Forsaken are " ..
                "having trouble routing him out.\n\nOnly a surgical assassination can end this!\n\nThe " ..
                "bridge behind me is relatively unguarded. Slip in through merchant's square and head " ..
                "south - you'll find Creed in the middle of the military district.\n\nI'll keep an eye on " ..
                "you and pull you out if there's any trouble.\n\n...There WILL be trouble!",
            rewardMoney = 94000,
        },
        [30095] = {
            description = "Nozdormu, the bronze Aspect, has asked for help from the champions of the " ..
                "Alliance. You are on his short list. I can share few other details.\n\nIt is " ..
                "uncharacteristic of my master to request the assistance of mortals, but I suppose that " ..
                "all things change with time... even the Aspect of Time himself.\n\nHe awaits you at the " ..
                "End Time, in the distant future. I can help you to travel there, if you so choose.",
            rewardMoney = 9400,
        },
        [30097] = {
            description = "From what I understand, you intend to avoid this future. If this is true, then " ..
                "we must archive data from this timestrand before it is lost to us.\n\nWe believe that " ..
                "the most interesting and valuable elements of this future are the powerful \"echoes\" " ..
                "that roam the dragonshrines.\n\nTake this vessel with you as you silence these echoes. A " ..
                "portion of their energies will be archived within the bronze dragonflight's depository.",
            rewardChoices = {{72852, 1}, {72871, 1}, {72872, 1}},
            rewardMoney = 376000,
        },
        [30102] = {
            description = "There's no need to stand around here forever. Have you forgotten? We can " ..
                "CONTROL TIME. Especially since you got rid of that Murozond fellow, back in the " ..
                "future.\n\nThat Dragon Soul that you just liberated? Thrall already has it, back in your " ..
                "present day. And he's going to need your help.\n\nYou ready to go?",
            rewardMoney = 9400,
        },
        [30103] = {
            description = "The Dragon Soul... a weapon with enough power to defeat Deathwing. Thanks to " ..
                "you, it is now safely in our hands.\n\nCome! The aspects await us. We must bring the " ..
                "Dragon Soul to Wyrmrest Temple, in the center of Dragonblight.",
            rewardChoices = {{72858, 1}, {72887, 1}, {72888, 1}},
            rewardMoney = 376000,
        },
        [30104] = {
            description = "You... <name>, was it? You assisted with our archival in the past. Well, " ..
                "technically it was the future, but I believe you understand. Time is highly " ..
                "relative.\n\nI require more information for our archive. While you and Nozdormu don't " ..
                "intend to overwrite this timestrand, as you did in the End Time, we can still benefit " ..
                "from more data.\n\nI require information on Captain Varo'then, one of Azshara's pretty " ..
                "little handmaidens, and... hmm... oh, how about that big felguard, just down those " ..
                "stairs?",
            rewardChoices = {{72881, 1}, {72882, 1}, {72883, 1}, {72880, 1}},
            rewardMoney = 376000,
        },
        [30106] = {
            description = "Prince Wrathion will be pleased to hear that you've succeeded. You should " ..
                "report back to him at Ravenholdt Manor.\n\nThe Prince has been known to be extremely " ..
                "generous to those who help him.",
            rewardItems = {{77945, 1}, {77946, 1}},
            rewardMoney = 47000,
        },
        [30107] = {
            description = "The daggers I have given you are lifeless shells. They can do great things, " ..
                "once they are given a means to contain the power I have in mind.\n\nI need for you to " ..
                "acquire Shadowy Gems for me. The facets of these unusual stones are like windows into " ..
                "the infinite. They are often used by minions of the Twilight's Hammer to control the " ..
                "most powerful of elementals.\n\nA great battle is raging around Wyrmrest Temple. Collect " ..
                "Elementium Gem Clusters from Deathwing's minions and bring the gems to me.",
            rewardMoney = 94000,
        },
        [30108] = {
            description = "Your next target is the Black Dragon Nalice, who is engaged in some sort of " ..
                "arcane debauchery beneath the ruined tower of Karazhan.\n\nYour primary mission is to " ..
                "destroy her, but if you can bring me back a vial of her blood, I'll be able to use it to " ..
                "augment the power of the daggers I've given you.\n\nYour accomplice Zazzo has already " ..
                "been dispatched to the scene and awaits you there. He'll have more details.",
            rewardMoney = 47000,
        },
        [30109] = {
            description = "I've pinpointed Nalice to the Master's Cellar, an extended basement you'll " ..
                "find in the ruins up ahead.\n\nDragon cultists are everywhere, and Nalice has set up " ..
                "some strange arcane storage devices throughout the area. Perhaps you can use those to " ..
                "your advantage?\n\nSneak past the cultists, obliterate Nalice, and grab a vial of her " ..
                "blood for Wrathion.\n\nI'll keep my eyes on you and pull you out if you get into any " ..
                "trouble. But I'm NOT coming in there with you!",
            rewardMoney = 94000,
        },
        [30113] = {
            description = "<Zazzo performs an enchantment on the vial of blood, then quickly hands it " ..
                "back to you, as though it's toxic.>\n\nDone! You'll want to get this back to Wrathion as " ..
                "soon as possible, along with those two daggers of yours.\n\nI don't know what he plans " ..
                "to do with this stuff. Between you and me, sometimes that little dragon kid creeps me " ..
                "out. Good luck!",
            rewardItems = {{77947, 1}, {77948, 1}},
            rewardMoney = 47000,
        },
        [30116] = {
            description = "Do you understand why I have you assassinate the dragons, yet spare the " ..
                "mortals? It isn't their fault. They must seek out their own destiny, free from the " ..
                "meddling of my kind.\n\nWe are nearing the end of our mission, and it is time for you to " ..
                "seek out your own destiny as well. I can continue to augment your weapons, but " ..
                "collecting shadowy gems won't be enough. My work will require entire clusters. Gather " ..
                "them from my father's minions...",
            rewardMoney = 94000,
        },
        [30117] = {
            description = "Excuse me... <name>? Did I hear your name correctly?\n\nI've come from " ..
                "Stoneplow, in the west. They sent me to pick up some emergency beer rations, but the " ..
                "Stormstout Brewery is all boarded up!\n\nIt looks like your handsome friend there - no, " ..
                "not Mudmug, the other one - has a few casks with him. Could you spare a keg for a town " ..
                "in need?",
            rewardMoney = 10200,
        },
        [30120] = {
            description = "'Ey, mon, you be here! Dis is good, mon!\n\nDrak'Tharon soon be cleansed of " ..
                "them foul undead and restored to her noble purpose. In return for your help, the keep's " ..
                "most valuable treasures be yours, mon!\n\nOnce ya be reachin' its top, ya must summon " ..
                "me, and I'll perform the ritual.\n\nAlas, my summonin' will be comin' at a cost. Ya must " ..
                "collect mojo from the survivors.",
            rewardChoices = {{40755, 1}, {40756, 1}, {40757, 1}, {40758, 1}},
            rewardMoney = 177000,
        },
        [30121] = {
            description = "I sent a diplomat to look for allies in the ruins east of here.\n\nMy diplomat " ..
                "has not returned and now Kang tells me this jungle is filled with a sinister people " ..
                "known as the mogu.\n\nChezin is my friend and Leza's brother. To lose a brother would " ..
                "cause her to give in to despair. She already has enough to worry about with her " ..
                "fever.\n\nCould you investigate the ruins east of here and find out what happened?",
            rewardMoney = 9800,
        },
        [30122] = {
            description = "You have found a beautiful silver flask decorated with ornate filigree. With " ..
                "the right materials and your skill in alchemy, it could become quite magical.",
            rewardItems = {{75525, 1}},
        },
        [30123] = {
            description = "Leza has a fever. No mother in labor should have a fever.\n\nMama Bramblestaff " ..
                "once told me that Skitterer Stew could heal almost any illness. Let us put this " ..
                "knowledge to the test.\n\nGather some intact skitterer glands for me while I get the " ..
                "herbs we'll need and I'll whip up a batch.",
            rewardMoney = 98000,
        },
        [30124] = {
            description = "These sunwalkers are a tiresome lot. I need soldiers with horde blood in their " ..
                "veins and honor in their hearts. Not some pacifist sun spirit filth.\n\nThe Alliance are " ..
                "here, $p. Followed us no doubt, or somehow tracked the same visions Leza had that led us " ..
                "here. It doesn't matter. I don't want them to know how divided we are at the moment. Go " ..
                "kill their scout south of here before it can report back.\n\nHellscream's eyes upon you.",
            rewardMoney = 98000,
        },
        [30127] = {
            description = "Mogu? They seem like the elves, ancient and an over developed sense of " ..
                "entitlement. Everyone of Azeroth must learn, sooner or later, that the Horde is not " ..
                "\"visiting\" this world. We are here. We are staying.\n\nTeach them this lesson. Quell " ..
                "their numbers in the ruins south and west of here. Break their amassing forces before " ..
                "they decide to attack.\n\nLearn what you can of how these creatures fight, and how they " ..
                "die.",
            rewardMoney = 98000,
        },
        [30128] = {
            description = "The mogu found the Pools of Youth!\n\nMama Bramblestaff used to tell me old " ..
                "stories about those. During the mogu empire they would use the waters to extend " ..
                "life.\n\nThing is those stories never ended well for some reason. As if the waters were " ..
                "cursed.\n\nEither way, we should investigate. There is a good chance those waters might " ..
                "help Leza.\n\nIt looks like the Pools of Youth are on the northwestern side of the ruins.",
            rewardChoices = {{81537, 1}, {81538, 1}, {81539, 1}, {81540, 1}, {81541, 1}},
            rewardMoney = 98000,
        },
        [30129] = {
            description = "Mogu don't often gather in numbers like this. We should find out what they are " ..
                "up to.\n\nI thought I heard someone shouting orders near the center of the ruins.\n\nWe " ..
                "should probably see if he has information.",
            rewardMoney = 98000,
        },
        [30130] = {
            description = "Kang's remedy isn't working.\n\nThere is something else at work here. A power " ..
                "deep beneath the soil. It is sapping us of hope, hitting us with depression and " ..
                "despair.\n\nKang tells me this land has lotus plants. I might be able to make a tea that " ..
                "would hopefully lend Leza some strength.\n\nPlease, $p, search the ruins south and west " ..
                "of here for lotus leaves. I will pay you for your efforts.",
            rewardChoices = {{88532, 5}},
            rewardMoney = 98000,
        },
        [30131] = {
            description = "My child is coming. I must help as I may.\n\nStay nearby, hero. If my wife and " ..
                "child survive, I would have them look on the face of the one who saved them.",
            rewardMoney = 98000,
        },
        [30132] = {
            description = "Leza now walks with the ancestors of this strange land. I must look now to the " ..
                "living.\n\nKor has led a group of our scouts west deeper into the jungle.\n\nI sent a " ..
                "scout of my own to investigate the crane temple. Please, $p, seek out my scout, get " ..
                "their report, then meet up with Kor and lend what aid you can to him.\n\nWe will join " ..
                "you as quickly as we are able.",
            rewardChoices = {{84281, 1}, {84282, 1}, {84283, 1}, {84284, 1}, {84285, 1}},
            rewardMoney = 10200,
        },
        [30133] = {
            description = "Deep in the wilds, on the southern coast where the Krasarang River meets the " ..
                "sea, rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout " ..
                "followers.\n\nThey should be told of what happened here.\n\nIf you're headed that way, I " ..
                "have a favor to ask; We often send supplies to the temple, but our last courier has not " ..
                "returned. Please look for signs of him as you travel - where the road forks at the " ..
                "Dojani River, he'd have gone north. When you reach the temple, find Koro Mistwalker.",
            rewardMoney = 98000,
        },
        [30138] = {
            description = "I have examined each egg, <name>. Out of the lot that you brought me, I have " ..
                "chosen the three eggs with the most promise.\n\nYou may choose only one egg to take with " ..
                "you. Are you ready to make your final selection?",
            rewardChoices = {{78962, 1}, {78960, 1}, {78961, 1}},
            rewardMoney = 57000,
        },
        [30146] = {
            description = "Cloud serpents love to eat, and one of their favorite treats is the sugar " ..
                "minnow.\n\nThese fish can be found in salt or fresh water anywhere in Pandaria. I trust " ..
                "you have some skill in fishing, and your own fishing pole to catch them?\n\nBring me a " ..
                "fresh catch and I'm sure the hungry beasts around here will be very grateful.",
            rewardMoney = 114000,
        },
        [30149] = {
            description = "I have heard that you know a thing or two about cooking.\n\nAs it so happens, " ..
                "serpents love to eat Fish Cakes.\n\nIf you use your culinary skills and bring me 5 of " ..
                "these dishes, the cloud serpents around here will be very happy.",
            rewardMoney = 114000,
        },
        [30151] = {
            description = "<The hatchling looks up at you with a bored, listless expression.>\n\nYou have " ..
                "a feeling the serpent is tired of being cooped up all day.\n\nHow about playing a little " ..
                "game of catch?",
            rewardMoney = 114000,
        },
        [30155] = {
            description = "The situation at the islands remains dire, <name>.\n\nThe Slitherscale saurok " ..
                "have not responded to our attempts at peace, so only one option remains.\n\nIn order to " ..
                "protect the wild cloud serpents, we must rid the island of their presence. Only then can " ..
                "the cloud serpents be left to live in peace.",
            rewardMoney = 114000,
        },
        [30156] = {
            description = "<The serpent darts forward and bites your fingers.>\n\nOuch! It seems, without " ..
                "a doubt, that the little beast is hungry. You recall that some meaty-looking turtles can " ..
                "be found on the wild cloud serpent island to the northeast.\n\nPerhaps some turtle meat " ..
                "will fill the hatchling's voracious appetite.",
            rewardMoney = 114000,
        },
        [30158] = {
            description = "If we are to stop the poachers, we need to take more aggressive action.\n\nIf " ..
                "we can remove the enemies' primary tools for killing and capturing serpents, we may be " ..
                "able to stop their operation altogether.\n\nI need you to go into their territory on the " ..
                "eastern end of Windward Isle and steal their weapons.\n\nA cat without claws cannot " ..
                "strike.",
            rewardMoney = 114000,
        },
        [30163] = {
            description = "We fell back to the refuge when the mogu attacked but lost a number of our " ..
                "people along the way.\n\nTravel west and north of here and look for any captives you can " ..
                "rescue that could help us in our fight.\n\nLeave any Alliance you find to their fate.",
            rewardMoney = 102000,
        },
        [30164] = {
            description = "I tried to save as many of the Stoneplow envoys as I could but these " ..
                "\"mantid\" dragged many of them off into the jungle.\n\nThese are civilians in need of " ..
                "our help.\n\nPlease take the herbs you gathered earlier. I've infused them with what " ..
                "gifts of the Light are still granted me. Use them on as many of the Stoneplow envoys as " ..
                "you can.",
            rewardMoney = 102000,
        },
        [30168] = {
            description = "Saurok!\n\nThese vile creatures are obsessed with killing and stealing. They " ..
                "attacked our settlement without provocation or warning.\n\nPlease, <class>, can you aid " ..
                "us?\n\nHelp us recover our lost possessions from these Riverblade raiders that march " ..
                "along the river and we will gladly reward you.",
            rewardChoices = {{81532, 1}, {81534, 1}, {81535, 1}, {81536, 1}},
            rewardMoney = 102000,
        },
        [30169] = {
            description = "The raiders are led by a particularly violent saurok known as Slovan. The " ..
                "Crane Temple usually comes to our aid when he attacks but now we find ourselves " ..
                "outmatched and outmaneuvered.\n\nPlease, <class>, aid us by destroying this raid " ..
                "leader.\n\nYou can find him in his den behind the Krasari Falls.",
            rewardItems = {{88387, 1}},
            rewardMoney = 102000,
        },
        [30172] = {
            description = "No, no, no, don't you worry about pickin' 'em up. I can hold these here " ..
                "barrels.\n\nI may not be the handsomest pandaren, or the smartest, or any fun to be " ..
                "around in the slightest, but I'm stronger than a mushan beast.\n\nI'mma just need you to " ..
                "lead the way.",
            rewardMoney = 10200,
        },
        [30174] = {
            description = "Kor should have caught up by now. He said he was going to secure the Ruins of " ..
                "Korja east of here and meet us to help with the mantid threat.\n\nHe may need help " ..
                "against Groundbreaker Brojai. Could you assist him? Kang and I will follow shortly.",
            rewardChoices = {
                {81449, 1}, {81450, 1}, {81451, 1}, {81452, 1}, {81453, 1}, {81454, 1}, {81455, 1},
                {81456, 1}, {81457, 1},
            },
            rewardMoney = 102000,
        },
        [30175] = {
            description = "The mantid! They came out of nowhere and smashed our convoy to ruin, " ..
                "scattering our people this way and that.\n\nNow they are preparing to hit " ..
                "Stoneplow.\n\nPlease, <class>, destroy some of these beasts before they get sufficient " ..
                "numbers to flank our home.\n\nIf my cousin, Ambassador Len, is still alive and at our " ..
                "convoy he should be able to reward you for your help.",
            rewardChoices = {
                {81458, 1}, {81459, 1}, {81460, 1}, {81461, 1}, {81462, 1}, {81463, 1}, {81464, 1},
                {81465, 1}, {81466, 1},
            },
            rewardMoney = 102000,
        },
        [30178] = {
            description = "Deep in the wilds, on the southern coast where the Krasarang River meets the " ..
                "sea, rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout " ..
                "followers.\n\nThey should be told of what happened here.\n\nIf you're headed that way, I " ..
                "have a favor to ask; We often send supplies to the temple, but our last courier has not " ..
                "returned. Please look for signs of him as you travel - where the road forks at the " ..
                "Dojani River, he'd have gone south. When you reach the temple, find Koro Mistwalker.",
            rewardMoney = 98000,
        },
        [30179] = {
            description = "The... mogu. Do not trust. Poison. Get sample... sample blades. Bring to " ..
                "Dezco... in Thunder Cleft, west of here.",
            rewardChoices = {{81522, 1}, {81523, 1}, {81524, 1}, {81525, 1}, {81526, 1}},
            rewardMoney = 98000,
        },
        [30181] = {
            description = "Mushan! Would ya look at the size o' 'em. Old as the dirt they walk on " ..
                "probably. A fine trophy.\n\nIf you are lookin' to test your mettle as a big game hunter, " ..
                "start with them.",
            rewardMoney = 102000,
        },
        [30182] = {
            description = "So, when I was scouting east of here I saw a collection of foxes. That's what " ..
                "I first learned to hunt when back on the Wandering Isle.\n\nIf you want to see the " ..
                "challenge a young pandaren hunter faced when growing up, head east and face off against " ..
                "a bunch of foxes. They tend to be clever and cunning so be on your guard.",
            rewardMoney = 102000,
        },
        [30183] = {
            description = "Tigers! No matter what land I go to I hear about these big fanged beasts. And " ..
                "yet I haven't had a chance to hunt any of them.\n\nLet's go hunt some tigers. I'll go " ..
                "east, you go west. I think I saw some near Dustback Gorge. I'm sure there are tons near " ..
                "those mushan.",
            rewardChoices = {
                {84320, 1}, {84321, 1}, {84322, 1}, {84323, 1}, {84324, 1}, {84325, 1}, {84326, 1},
                {84327, 1}, {84328, 1},
            },
            rewardMoney = 102000,
        },
        [30184] = {
            description = "My boy here is a talented hunter... in training. Let's show him an old 'Nessy " ..
                "style hunt shall we?\n\nI saw a mighty big mushan east of here with a hide dark as " ..
                "night. It looked like it had taken down a number of hunters in its day.\n\nIf you want a " ..
                "big game hunt, go try an' take it on.",
            rewardChoices = {
                {81854, 1}, {81855, 1}, {81856, 1}, {81857, 1}, {81858, 1}, {81859, 1}, {90542, 1},
                {90545, 1}, {90622, 1},
            },
            rewardMoney = 102000,
        },
        [30185] = {
            description = "Granted, tortoises are not big game but they can be mean game. They also work " ..
                "as the perfect bait for bigger game!\n\nGotcher found some ol' tablets sayin' that the " ..
                "Torjari Pit is a sacrificin' site. The old empire used ta' feed unruly sorts to the " ..
                "waters as it were.\n\nWell ah mean to see me what's down in that water. Gather up some " ..
                "fresh tortoise shells and meet me at the pit.\n\nLet's see if ol' legends be true.",
            rewardMoney = 102000,
        },
        [30186] = {
            description = "If them tablets were correct, all ay got ta do is a small dance ritual and the " ..
                "big thing o' the deep will be summoned.\n\nWhen it comes out, we'll get 'em and show me " ..
                "pop we are both true big game hunters like him.",
            rewardChoices = {{81819, 1}, {81820, 1}, {81821, 1}, {81822, 1}, {81823, 1}},
            rewardMoney = 102000,
        },
        [30188] = {
            description = "I can no longer call myself your teacher, <name>.\n\nYou have proven yourself " ..
                "worthy of your cloud serpent.\n\nToday, you shall join our ranks. Are you ready?",
            rewardChoices = {{79802, 1}},
            rewardMoney = 57000,
        },
        [30189] = {rewardItems = {{79320, 1}}},
        [30190] = {
            description = "Sprites again! I hate these things. We need to stop them before they hurt " ..
                "someone or burn down half of the village!\n\nIf you see any of the pests, please deal " ..
                "with them!",
            rewardMoney = 114000,
        },
        [30191] = {
            description = "Someone left some beer out up on the southern rise and now the sprites have " ..
                "developed a taste for our brew. They've been sneaking into town all morning, stealing " ..
                "whatever kegs they find.\n\nBring back what you can. A pandaren worker without brew is " ..
                "just... it won't be very productive. We need the men in good spirits.",
            rewardMoney = 114000,
        },
        [30192] = {
            description = "I don't know if you noticed, but my town is burning...\n\nThe sprites have " ..
                "started kicking the braziers! They're going to set fire to the whole town!\n\nPlease " ..
                "help us! Stamp out any fires you see!",
            rewardMoney = 114000,
        },
        [30193] = {
            description = "Hard workers deserve hearty meals, but I'm all out of good meat!\n\nCan you " ..
                "head out into the forest and get me some fresh gazelle meat?",
            rewardMoney = 114000,
        },
        [30194] = {
            description = "The villagers have lost another yak this morning to one of the thundermaw " ..
                "wolves from across the river. The wolves grow bold.\n\nThis is a sign that they are " ..
                "breeding beyond the vale's ability to sustain them. It's time to thin their numbers " ..
                "again.\n\nIf you are willing to aid me in this, you would have my sincere appreciation.",
            rewardMoney = 114000,
        },
        [30195] = {
            description = "Would you do a humble merchant a favor? I've been needin' to refresh my stock " ..
                "of eternal blossoms. They grow in the woods nearby.\n\nCould you help me out, perhaps?",
            rewardMoney = 114000,
        },
        [30196] = {
            description = "Building a new village makes for hungry workers it seems!\n\nI have a hearty " ..
                "stew recipe prepared, but I need some lushrooms from the Tu Shen Burial Ground to the " ..
                "east. Apparently there are roused spirits causing trouble up there though, and I'm not " ..
                "very well suited for the violent life.\n\nIf you're heading up the burial grounds today, " ..
                "could you collect some lushrooms for me?",
            rewardMoney = 114000,
        },
        [30200] = {
            description = "We used to have the trainees clear out the ruins of spiders as part of their " ..
                "training, but now we send them straight to the mogu front. The spiders have gotten out " ..
                "of control.\n\nCare to put things back in control?",
            rewardMoney = 114000,
        },
        [30205] = {
            description = "Hello, friend.\n\nOne of Leven's men brought word to me of a mogu artifact in " ..
                "the eastern ruins, but said he couldn't figure out how to retrieve it. I suspect it's " ..
                "guarded by one of their rune locks.\n\nIf you go to the artifact, you should find four " ..
                "runes somewhere nearby that when activated will release the lock. If you could bring the " ..
                "artifact back to me, I would be very grateful.",
            rewardMoney = 114000,
        },
        [30206] = {
            description = "In the walls of the ruins themselves, there are precious runestones that we " ..
                "can make use of back in the eastern vale.\n\nIf you see any while you are within the " ..
                "ruins, would you be so kind as to bring them back to me?",
            rewardMoney = 114000,
        },
        [30226] = {
            description = "A small group of mogu have been sighted on Ruin's Rise, to the " ..
                "north.\n\nExtinguish them.",
            rewardMoney = 114000,
        },
        [30229] = {
            description = "I apologize for my harsh words earlier. Dezco might have been right to wait " ..
                "and move west with a unified strength.\n\nThe mogu hit us hard when we were searching " ..
                "the ruins west of here. They ambushed us using summoning portals and some dark magics. I " ..
                "haven't seen such evil sorcery used since Outland.\n\nWe need a respite. Head west, kill " ..
                "their summoners, cut their supply line.",
            rewardMoney = 102000,
        },
        [30230] = {
            description = "Mogu are thugs. They have always been thugs.\n\nOnly when they ruled their " ..
                "empires in the old stories did they ever know any kind of magic.\n\nBut these mogu are " ..
                "using arcane portals and spells. We need to stop them!\n\n$p, look for any artifacts the " ..
                "mogu are using to cast their magics with. I saw a number of their collectors and " ..
                "reclaimers to the west and north that were gathering these items.",
            rewardChoices = {
                {81503, 1}, {81504, 1}, {81505, 1}, {81506, 1}, {81507, 1}, {81508, 1}, {81509, 1},
                {81510, 1}, {81511, 1},
            },
            rewardMoney = 102000,
        },
        [30231] = {
            description = "I need more pomfruit! Go knock some loose from the trees for me, would " ..
                "you?\n\nTake this, I use it when I go harvesting. Things go quicker when the fruit comes " ..
                "to you!",
            rewardMoney = 114000,
        },
        [30232] = {
            description = "The hawk numbers in the vale are thriving. This is opportune for our " ..
                "fletchers, for we will need a great number of feathers if we are to keep the archers " ..
                "upon the wall stocked with arrows.\n\nIf you would not mind, could you aid us in " ..
                "gathering these feathers?",
            rewardMoney = 114000,
        },
        [30233] = {
            description = "Hi! So, I have a dilemma. I've only got one good wolf name.... wait for it... " ..
                "Cracklefang! I know, amazing right?! But now there are TWO big nasty wolves in the " ..
                "forest, which is all kinds of confusing.\n\nI need you to kill one of them so I can free " ..
                "up the name. Should be simple enough, yeah? Especially for someone of your " ..
                "incredibleness.\n\nSo, are you on board? I'm hoping for yes!",
            rewardItems = {{90625, 1}},
            rewardMoney = 228000,
        },
        [30235] = {
            description = "Quid is a very powerful and very ancient water spirit, though you might not " ..
                "know it with his child-like ways.\n\nThis morning, Quid nearly killed several villagers " ..
                "in the bar when he jokingly caused several of the water kegs to explode.\n\nAs long as " ..
                "the water flows, Quid will remain. He cannot be slain. But he can be reminded that we do " ..
                "not take his dangerous antics in jest.\n\nWould you be willing to carry this message to " ..
                "him on behalf of the village?",
            rewardItems = {{90625, 1}},
            rewardMoney = 228000,
        },
        [30236] = {
            description = "It seems Aetha has been levitating the livestock and dropping them into the " ..
                "river again. The mayor has requested that we remind her that these kinds of jokes are " ..
                "not welcomed.\n\nWould you be so generous as to travel to the ridge above the village " ..
                "and teach her this lesson? You cannot kill her, you can only send her away for a time, " ..
                "but this should prove a potent reminder.",
            rewardItems = {{90625, 1}},
            rewardMoney = 228000,
        },
        [30238] = {
            description = "The spirits of our ancestors are reliving one of the most revered battles in " ..
                "our history at the Tu Shen Burial Grounds to the east.\n\nDo as I ask, <race>, and honor " ..
                "their gravestones. Remind them that they are respected even these many years later, and " ..
                "that they are deserving of peaceful rest.",
            rewardMoney = 114000,
        },
        [30239] = {
            description = "You can hear the spirit of Lao-Fe, the Slavebinder shouting taunts from the " ..
                "cave at the top of Tu Shen Burial Mound.\n\nDefeating him will surely serve to ensure " ..
                "victory for the spirits of the pandaren monks.",
            rewardItems = {{90625, 1}},
            rewardMoney = 228000,
        },
        [30240] = {
            description = "This is one of the challenges I put upon my warriors to keep them strong and " ..
                "fast. Let's see how you fare.\n\nSurvive the ring for 60 seconds without getting pushed " ..
                "out or killed. Stay on your toes.",
            rewardMoney = 114000,
        },
        [30241] = {
            description = "So much death. And more to come, if Ambassador Han's stories of the mantid are " ..
                "to be believed.\n\nWe must help. We must do our part to save lives.\n\nTravel to " ..
                "Stoneplow. Warn them of the coming mantid attack.\n\nI will join you with what forces I " ..
                "can muster once I have laid Kor's body to rest.",
            rewardMoney = 10200,
        },
        [30243] = {
            description = "The mantid are attacking again, and we're a bit short-handed up on the wall. " ..
                "In hopes that you'd help, I saved one of the more fun posts for you: the hot " ..
                "oil!\n\nIt's a bit more violent and a bit less scandalous than it sounds.\n\nIt's simple " ..
                "really. Get up on the wall, find one of the oil stations, and dump it on any of the " ..
                "mantid pouring up against the wall. It's very effective.",
            rewardMoney = 114000,
        },
        [30244] = {
            description = "There are mantid on top of the wall. The defenders on the ramparts are calling " ..
                "for help!",
            rewardMoney = 114000,
        },
        [30245] = {
            description = "We sent some scouts towards the Five Sisters to the north to try and find " ..
                "whatever mogu leader has risen up to direct their movements in the valley. Few have " ..
                "returned.\n\nI'd like to think they're just off downing too much ale or being " ..
                "irresponsible with some young pandaren, but they may actually be in some trouble.\n\nCan " ..
                "you scout for the scouts? And see if they've turned up any information on that leader " ..
                "while you're at it?",
            rewardMoney = 114000,
        },
        [30249] = {
            description = "A giant beast has burrowed under the gate into the courtyard. The defenders " ..
                "need your help!",
            rewardItems = {{90625, 1}},
            rewardMoney = 228000,
        },
        [30251] = {
            description = "A giant mantid is terrorizing the inside of the wall. It seems doubtful that " ..
                "the defenders will be able deal with it without you.",
            rewardItems = {{90625, 1}},
            rewardMoney = 228000,
        },
        [30252] = {
            description = "I've been pushing and shoving and hammering all morning, but it's " ..
                "hopeless.\n\nThese rocks won't budge!\n\n\"It will be a breeze,\" Grandpa said. " ..
                "\"Farming's like breathing!\" he said. Maybe for him, but not for me!\n\nHow am I " ..
                "supposed to succeed at this whole FARMING thing if I can't even clear my farm for " ..
                "planting?\n\nHey, wait a minute. You look like you've got some muscle on you.\n\nWould " ..
                "you be willing to help me out? Just until I can catch my breath.",
            rewardMoney = 102000,
        },
        [30254] = {
            description = "Okay, now we've got our seeds, it's time to plant them.\n\nFirst, we have to " ..
                "prepare the soil! You gotta till the soil and break it up to make a nice bed for our " ..
                "little sprouts.\n\nTill those two plots of soil over there, then plant the seeds in them.",
            rewardMoney = 102000,
        },
        [30255] = {
            description = "My grandfather used to say \"Yoonie, a cabbage is like a woman: ignore her and " ..
                "she'll turn rotten. Pamper her and she'll grow big and plump and you can put a ribbon on " ..
                "her and take her to market to show her off to your frie-\" look, he was from a different " ..
                "time, okay?\n\nThe point is, now that our cabbages have sprouted, they need attention! " ..
                "Today they look a little dry, so you should water them.\n\nHere's the old watering can " ..
                "grandpa left. It will always be near the field if you need it.",
            rewardMoney = 102000,
        },
        [30256] = {
            description = "It's time for our hard work to pay off! Normally we'd have to wait a day " ..
                "before the crops are ready to harvest.\n\nFortunately, those seeds Greenfield gave us " ..
                "were specially designed to grow FAST. The yield won't be worth much, but they're good " ..
                "for stepping new farmers through the process.\n\nOur cabbages should be ready to " ..
                "harvest. I'll let you do the honors, of course!",
            rewardMoney = 102000,
        },
        [30257] = {
            description = "All right friend, all of that farming was just for practice!\n\nAre you ready " ..
                "to try the real thing?\n\nThere's a lady by the name of Gina Mudclaw who runs the " ..
                "Halfhill Market, which is across the street to the south.\n\nI heard she's looking to " ..
                "buy some vegetables. Since it's your first time meeting her, you shouldn't go " ..
                "empty-handed.\n\nWhy don't you look around the ranch and see if there are any items " ..
                "hiding around?\n\nMight be that we'll find a good gift to take to our new neighbor!",
            rewardMoney = 51000,
        },
        [30259] = {
            description = "Dem virmen's back!\n\nThey been biting Mr. Mudclaw's carrots. Ruining his " ..
                "crop. And who is gonna pay? Mung-Mung, that's who!\n\nYou go get the chewed up carrots " ..
                "before Mr. Mudclaw sees. They all over the fields to the southwest, and down under the " ..
                "ground in the virmen's tunnels, too.\n\nOtherwise, Mung-Mung in big trouble.\n\nYou do " ..
                "this for me?",
            rewardMoney = 114000,
        },
        [30261] = {
            description = "Get to the bottom of the wall in the fastest time possible.\n\nSpeak to me " ..
                "when you're ready to roll.",
            rewardMoney = 228000,
        },
        [30263] = {
            description = "The Shao-Tien are on their heels. Most of them retreated to Winterbough Glade " ..
                "after their last defeat. We should press the advantage.\n\nTake the fight to these mogu " ..
                "in the clearing to the northwest. Let us leave them no minute of rest as long as they " ..
                "remain in the Vale.",
            rewardMoney = 114000,
        },
        [30264] = {
            description = "The mantid forces are pouring against the wall. I've arranged for some flying " ..
                "serpents to cut away at their forces from the air.\n\nWould you be willing to take the " ..
                "reigns on one of them?",
            rewardMoney = 228000,
        },
        [30265] = {
            description = "I've been staring down into the waters of the lake, pondering life, love, and " ..
                "everything beautiful, and suddenly I realized that the sparkles in the water aren't just " ..
                "a reflection of my radiant personality, there are actually some sort of shining objects " ..
                "down there! Surely valuable.\n\nWould you mind taking a drip and relieving the lake's " ..
                "depths of its mysterious sparkles? Pretty please?",
            rewardMoney = 114000,
        },
        [30266] = {
            description = "We have cannons set up on the top of the towers flanking the main gate. They " ..
                "are our best method to clear the skies when the flying mantid try to pass over the wall, " ..
                "like they are now.\n\nLooks like you're on, <name>.",
            rewardMoney = 114000,
        },
        [30267] = {
            description = "I love fishing. I'd be enjoying myself much more, however, if I had my bait " ..
                "and my lures. They were thrown away in a... a misunderstanding with my wife, Rin.\n\n< " ..
                "Gladecaster Lang sighs.>\n\nShould I let a whole day of fishing be ruined, just because " ..
                "of a little domestic squabble? No! All I need is bugs and feathers, after all, and this " ..
                "glade is filled with those two things.\n\nCare to help a fisherman out?",
            rewardMoney = 102000,
        },
        [30268] = {
            description = "Take a good look. The river nearby is swarming with these snakes. Their venom " ..
                "causes a condition the locals call \"the murksweats.\"\n\nSeveral refugees were bitten " ..
                "as they fled the temple and have already begun to show symptoms: nausea, vomiting, and " ..
                "intense sweating as the body rejects all fluids, causing dehydration and potentially " ..
                "death.\n\nWe are administering anti-venom as quickly as possible, but we'll need more " ..
                "venom glands. Don't bother removing the glands yourself - just bring back the whole head.",
            rewardChoices = {{81517, 1}, {81518, 1}, {81519, 1}, {81520, 1}, {81521, 1}},
            rewardMoney = 102000,
        },
        [30269] = {
            description = "As we say at the temple: \"Never fight a tiger with a hozen on your " ..
                "back.\"\n\nWe will deal with the sha, but first we must see to the more immediate... " ..
                "nuisance.\n\n<Koro slams the writhing saurok HARD against the stone.>\n\nGroups of " ..
                "refugees from the temple are heading for a camp to the north, but they're being ambushed " ..
                "by saurok. Help me see the next group to the camp and we'll figure out our next move " ..
                "from there.",
            rewardMoney = 102000,
        },
        [30270] = {
            description = "\"A hooded falcon catches no quarry.\"\n\nThis is one of the first mantras we " ..
                "teach young monks at the temple. It means that even a foe as swift and lethal as a " ..
                "falcon can be neutralized by depriving its senses.\n\nThe saurok have scouts all over " ..
                "the region acting as eyes for their raiding parties.\n\nIt's time we put their eyes out, " ..
                "don't you think?",
            rewardMoney = 102000,
        },
        [30271] = {
            description = "The sha have the mysterious ability to evoke powerful, often overwhelming, " ..
                "emotional responses in their victims.\n\nAs we fled the temple, senior members of the " ..
                "Crane Wing order stayed behind to cover our escape. They are no doubt being subjected to " ..
                "intense emotional trauma, and I fear they are not all strong enough to resist falling " ..
                "into despair.\n\n$p, we have to show them there is still hope! Show them that despair " ..
                "CAN be defeated!",
            rewardMoney = 102000,
        },
        [30272] = {
            description = "Now as for that \"striking the rain\" part... well, sometimes you have " ..
                "to.\n\n\"Hope is the sun behind a stormy sky - ever in the heart, but veiled to the " ..
                "eye.\"\n\nThere seems to be no end to the sha pouring out of the temple. But in order to " ..
                "see beyond the veil of despair, you must carve through it.\n\nWith any luck, you'll find " ..
                "a sun behind the clouds...",
            rewardMoney = 102000,
        },
        [30273] = {
            description = "\"Broken are the bodies wherein hopeless hearts reside - the blight of despair " ..
                "strikes forth from inside.\"\n\nThis was the last piece of wisdom the Red Crane imparted " ..
                "to me, just hours before the Sha outbreak. It makes sense now...\n\n$p, when the Sha " ..
                "attacked, they broke forth from the temple's basement...\n\nAll of his teachings - the " ..
                "very Way of the Crane itself... it's all been preparation for facing the Sha of " ..
                "Despair.\n\nThe Red Crane has been expecting this conflict for centuries!",
            rewardChoices = {
                {81485, 1}, {81486, 1}, {81487, 1}, {81488, 1}, {81489, 1}, {81490, 1}, {81491, 1},
                {81492, 1}, {81493, 1},
            },
            rewardMoney = 204000,
        },
        [30274] = {
            description = "An Alliance member? Here? Elune be praised.\n\nMy team has encountered a snag. " ..
                "We opened a portal to this land using some ancient scrolls we had found that predated " ..
                "Azshara's rule.\n\nUnfortunately, the coordinates provided on the tablets were warded " ..
                "and the portal that meant to take us to our destination landed us in this " ..
                "oubliette.\n\nWe have been trapped here for days, and it is slowly leaching our energies " ..
                "to power itself.\n\nCan you find the nearby shackles that bind the oubliette and disable " ..
                "them?",
            rewardMoney = 102000,
        },
        [30275] = {
            description = "How could this crocolisk have grown so large?\n\nCertainly, rumors exist of " ..
                "very old crocolisks that have grown to enormous sizes... but this female can't be more " ..
                "than a dozen years old.\n\nPerhaps someone in New Cifera can shed some light on the " ..
                "subject.",
            rewardMoney = 102000,
        },
        [30282] = {
            description = "The mogu have erected their filthy banners around the lake to the west, " ..
                "claiming it as their own. Take this torch and show them what we think of their banners.",
            rewardMoney = 114000,
        },
        [30283] = {
            description = "Sometimes I feel sorry for these mogu... maybe ripping out the spirits of " ..
                "other races is just their way of coping with family issues at home? Maybe we should be " ..
                "more sympathetic to where all this aggression stems from?\n\nOr we could just smash all " ..
                "their soul-stealing ritual objects down at the lake. That sounds more fun to me " ..
                "personally.",
            rewardMoney = 114000,
        },
        [30284] = {
            description = "The water has been frothing with danger this day! Some sort of swarming, " ..
                "meat-eating fishy nastiness has taken up residence in our lake! Deplorable. And just " ..
                "when I was considering stripping down to my nothings to take a mid-day dip!\n\nYou are " ..
                "adept in the ways of slaughtering any manner of nasty, are you not? Would you put your " ..
                "skills to use this day, in the name of pandaren everywhere desiring a swim?\n\nIt's a " ..
                "truly noble cause, especially with me among their ranks!",
            rewardMoney = 114000,
        },
        [30286] = {
            description = "Many villagers are cornered and scared, unable to defend themselves. You will " ..
                "need to defend them. Rescue them.\n\nGo quickly friend, save as many as you can!",
            rewardMoney = 114000,
        },
        [30287] = {
            description = "Leven sent Rook here to stop mogu, but there are more than Rook can kill " ..
                "alone.\n\nYou help? Rook will tell Leven you helped. Promise.",
            rewardMoney = 114000,
        },
        [30288] = {
            description = "I don't know if you noticed, but my town is on fire... again.\n\nWe have water " ..
                "buckets all over town, but no one can get out to put out the fires. Please, please, help " ..
                "us!",
            rewardMoney = 114000,
        },
        [30289] = {
            description = "Mogu stealing peoples minds! Making them do evil things.\n\nDon't kill them, " ..
                "just kill the mogu, then they forget about all the mogu mind stealing and stop being " ..
                "evil. You should fix people like Rook is.",
            rewardMoney = 114000,
        },
        [30290] = {
            description = "Mogu stone dog creatures chasing villagers and hurting them. Rook try to smash " ..
                "some, but they too fast.\n\nYou help smash some too?",
            rewardMoney = 114000,
        },
        [30292] = {
            description = "The mogu are taking over the minds of the saurok at the lake to our west and " ..
                "turning them against us! The thing is, they were already against us, so I'm not sure " ..
                "they really thought this thing through fully.\n\nAnyway, Anji's the fighter in this " ..
                "pair, I'm more the lover, so I'm looking for someone to do all the weapon swinging and " ..
                "spell flinging and war crying and such.\n\nCan you go kill some saurok for me?",
            rewardMoney = 114000,
        },
        [30293] = {
            description = "The Shao-Tien Mindbenders have taken over the minds of our defenders down at " ..
                "Whitepetal Lake to the west. Get down there and kill the mogu that are controlling them, " ..
                "but don't kill the defenders! Killing their captors should free them from their mind " ..
                "control.\n\nSooner would be better. Anji might try to go down there to help soon, and " ..
                "her ability to restrain herself when in the heat of things is not one of the qualities I " ..
                "married her for.",
            rewardMoney = 114000,
        },
        [30296] = {
            description = "Big mogu leader is here! Up behind village. If we kill big mogu leader, Leven " ..
                "be happy with us for sure!\n\nYou been good at helping Rook. Want to help more maybe? " ..
                "Please?",
            rewardItems = {{90625, 1}},
            rewardMoney = 228000,
        },
        [30297] = {
            description = "Big mogu leader is here! Up behind village. If we kill big mogu leader, Leven " ..
                "be happy with us for sure!\n\nYou been good at helping Rook. Want to help more maybe? " ..
                "Please?",
            rewardItems = {{90625, 1}},
            rewardMoney = 228000,
        },
        [30298] = {
            description = "The mogu think they can inhabit these ruins uncontested. Let's show them the " ..
                "error in their ways.",
            rewardMoney = 114000,
        },
        [30299] = {
            description = "The mogu have forced spirits into their old statues to bring them to life, " ..
                "control them, and turn them against us.\n\nThe only way to free the bound spirits is to " ..
                "destroy their vessels.",
            rewardMoney = 114000,
        },
        [30301] = {
            description = "There is no more sure message we can send them then to burn the tents the " ..
                "sleep in.\n\nScour the ruins. Destroy every tent you find.",
            rewardMoney = 114000,
        },
        [30302] = {
            description = "Scouts spotted a Shao-Tien Imperion entering the Guo-Lai Halls. I need someone " ..
                "I can trust to make sure he doesn't come out of there alive.\n\nI think you're the " ..
                "<class> for the job.",
            rewardItems = {{90625, 1}},
            rewardMoney = 228000,
        },
        [30304] = {
            description = "Hey! You know what awesome thing happened to me this morning?\n\nI was " ..
                "strolling through the ruins with Anji, eyes on the ground so I wouldn't step on anymore " ..
                "of those creepy spider pods, when one of the statues came to life and tried to smash " ..
                "me!\n\nAnji ended up doing the smashing. But I'm not satisfied. I think that you should " ..
                "go out there and smash all the statues, whether they're moving or not. It's the only way " ..
                "to be sure.",
            rewardMoney = 114000,
        },
        [30305] = {
            description = "You know He Softfoot? Sneaky guy, don't talk much. He put traps all over ruins " ..
                "for mogu. He said Rook just need to trick mogu into traps. Rook don't really know " ..
                "how.\n\nMaybe you do it? You find traps, you get bad guys into traps? Can you not tell " ..
                "He though, please?",
            rewardMoney = 114000,
        },
        [30306] = {
            description = "We have some fresh trainees that are far from being a danger to you, but in " ..
                "numbers, they may prove enough of a challenge. And if not, they could use the lesson in " ..
                "humility.\n\nStep into the battle ring when you're ready. Don't go easy on them.",
            rewardMoney = 114000,
        },
        [30308] = {
            description = "Leven always says the only good quilen is a dead quilen, and I'm inclined to " ..
                "agree. You here to aid the cause?",
            rewardMoney = 114000,
        },
        [30309] = {
            description = "The mogu have been sending their narcissistic stone effigies onto our " ..
                "battlefield today. They're brining them to life up on the Golden Stair.\n\nThe bigger " ..
                "they are, the harder we hit'm. You in?",
            rewardMoney = 114000,
        },
        [30312] = {
            description = "A foolish contingent attempted to mount an offensive on the Golden Stair " ..
                "through the eastern pass, and were bombarded by cannons. Those that made it back are in " ..
                "bad shape, and there are still wounded out in the field.\n\nHere are some bandages. Use " ..
                "these, or any other healing skills you possess, and help get our wounded defenders back " ..
                "to safety.\n\nPlease hurry, there is little time.",
            rewardMoney = 114000,
        },
        [30317] = {
            description = "How'd you like to make yourself useful?\n\nThe season's been awful dry lately. " ..
                "I need someone to water the crops out in the Heartland. Here's the thing: I need you to " ..
                "water ALL of the crops.\n\nI keep a few kites with Wing Nga, the flightmaster across the " ..
                "way. Grab one of those kites, then throw water on any areas that look dry and dusty.",
            rewardMoney = 114000,
        },
        [30319] = {
            description = "One of my farmhands, Wika-Wika, has been tilling the soil in my westernmost " ..
                "field. I understand he's had some problems with pests.\n\nHe's got plenty of pesticide " ..
                "to spray the bugs that eat my crops, but I'm afraid he has no way to deal with the " ..
                "marmots.\n\nWould you lend him a hand? With rampant hozen and virmen attacks, I can't " ..
                "afford to lose crops to simple pests.",
            rewardMoney = 114000,
        },
        [30320] = {
            description = "I came upon one of the Shao-Tien Soul-Render's daggers. It radiates a strong " ..
                "magic. I've been told it should allow you to enter their spirit vortexes.\n\nThe mogu " ..
                "use these to harvest spirits and bind them to their will, but I'm hoping you can use it " ..
                "to free the spirits.\n\nEnter any of the spirit vortexes you can find up on the Golden " ..
                "Stair, and free all the captive spirits you find.",
            rewardMoney = 114000,
        },
        [30323] = {
            description = "A few weeks ago, a group of those jumpy little Springtail virmen broke into my " ..
                "lockbox and stole several handfuls of my jewelry. I've since found a few pieces, but " ..
                "they still have most of my collection.\n\nIf you're headed up to the Springtail Crag, in " ..
                "the cliffs to the north, you should keep an eye out for them. I'd love to get my jewelry " ..
                "back.",
            rewardMoney = 114000,
        },
        [30326] = {
            description = "I've heard people talk about the hozen like they're just some tribe of " ..
                "barely-functional idiots... but that's not true! They have brains, too - they just don't " ..
                "all like to use them that much.\n\nI've heard that the Kunzen tribe has two chiefs - one " ..
                "in charge of fighting, and one in charge of stories, lore, and history.\n\nWhat I " ..
                "wouldn't give to see what kind of stories they tell...",
            rewardMoney = 114000,
        },
        [30327] = {
            description = "I, umm... well...\n\nOh, never mind. It was a stupid idea.\n\nIt's just that, " ..
                "I was thinking that maybe we can stop the Kunzen hozen from attacking us without having " ..
                "to, you know... KILL anything. I noticed a few ropes on the side of the mountain. I " ..
                "think they're using them to climb down to our farms and...\n\nNo, forget it. It was a " ..
                "silly idea anyways.",
            rewardMoney = 114000,
        },
        [30328] = {
            description = "One of my most popular recipes is the Thousand-Year Dumpling, which is filled " ..
                "with preserved vegetables.\n\nI normally let the vegetables ferment in a hole underneath " ..
                "my house, but when I looked for them this morning, they were gone!\n\nI blame those " ..
                "thieving virmen.\n\nBring them back, and I'll let you help me cook!",
            rewardMoney = 114000,
        },
        [30329] = {
            description = "A certain few pandaren around here prefer their dishes unbearably spicy. " ..
                "Unfortunately, my access to such peppers is limited.\n\nThe Kunzen hozen, in the " ..
                "mountains to the west, often carry cindergut peppers. A few of those and I'll be set for " ..
                "a few days.\n\nSay, could you collect some for me? You might want to wear gloves if " ..
                "you'll be handling them directly.",
            rewardMoney = 114000,
        },
        [30330] = {
            description = "I like to bake with truffles... when I can find them. They only grow up on the " ..
                "Skyrange, and in very, very scarce amounts.\n\nThey're a fantastic ingredient, but we " ..
                "can't risk over-farming them. That's why we need to replace what we've taken. Bring me a " ..
                "handful of adult truffles, and plant some of these spores in their place.",
            rewardMoney = 114000,
        },
        [30331] = {
            description = "Have you ever tried Mushan Tail Stew? Chances are, if you have, that it was " ..
                "stringy and tasteless. You see, there's a trick to making the perfect Mushan Tail Stew: " ..
                "you need to cook it at high elevation.\n\nI've already gathered the ingredients. Take " ..
                "this pot up to the Kunzen Village, up in the mountains to the west, and prepare the stew " ..
                "over their bonfire.",
            rewardMoney = 114000,
        },
        [30332] = {
            description = "You know what? I think I want to grill up some goatsteak today.\n\nNo, not " ..
                "from the puny little shaghorns they keep around here. They don't have nearly enough fat " ..
                "on them.\n\n<The chef pats his voluminous belly.>\n\nYou think I got to this size eating " ..
                "no-fat-havin' goats?\n\nNow, the shaghorns up on the Skyrange, to the west... those'll " ..
                "do just fine.",
            rewardMoney = 114000,
        },
        [30333] = {
            description = "Like any farming community, we have the occasional virmen troubles.\n\nThe " ..
                "most powerful Springtail virmen live high up in the cliffs to the north, and only come " ..
                "down when they run out of veggies to nibble on.\n\nFrankly, I've dealt with virmen " ..
                "before. They're nothing but a pest that must be kept in check, and there's no better way " ..
                "to do that than by killing their warren-mother. Easy as that.",
            rewardMoney = 114000,
        },
        [30338] = {
            description = "For the life of me, I can't figure out why the mogu would have built all their " ..
                "statues and such down in that lake. I'm sure there wasn't always water down there, but " ..
                "it still seems wickedly inconvenient should it ever have rained.\n\nAh well, who's to " ..
                "fathom the strange intentions of the mogu...\n\nWould you be so kind as to swim down " ..
                "there and bring back any artifacts that seem even vaguely carry-able? I'd certainly " ..
                "appreciate it.",
            rewardMoney = 114000,
        },
        [30339] = {
            description = "Some of the best fishin' in all of pandaria in this lake right here. I brought " ..
                "enough brew to last me all day, but I didn't think to bring any bait.\n\nWho can really " ..
                "remember such things?\n\nIf you'd be willing to gather me some bait along the shore, I'd " ..
                "be willin' to think on you favorably when it comes time to price my merchandise. Oh, and " ..
                "I'll pay you too, of course.\n\nHow's that sound?",
            rewardMoney = 114000,
        },
        [30340] = {
            description = "I came out for a beautiful day of fishin', but I didn't think to bring a pole. " ..
                "There are so many things to remember for fishin', I just can't keep it all in my " ..
                "head.\n\nThose reeds along the river look alright for makin' a pole out of. If you'd " ..
                "gather me some number of them, I'd be willin' to think on you favorably when it comes " ..
                "time to price my merchandise. Oh, and I'll pay you too, of course.\n\nHow's that sound?",
            rewardMoney = 114000,
        },
        [30342] = {
            description = "I was kicking the water for fun again when one of those vicious crocolisks " ..
                "lunged out to try to bite my foot off! Rude! I have proceeded to rest my weary soles a " ..
                "few feet farther from the water, but I already look back on my water-kicking days " ..
                "longingly.\n\nWould you be so kind as to kill a crocolisk or eight for me? I assure you " ..
                "they deserve it for frightening me though.",
            rewardMoney = 114000,
        },
        [30344] = {
            description = "I wonder if I could bother you for another task. My daughter, the good " ..
                "Sentinel Commander Lyalia here, refuses to let me go into the field.\n\nI have spent " ..
                "everyday in that oubliette staring at the ruins to our north, itching to " ..
                "investigate.\n\nIf we are where I suspect we are those ruins could contain the key we " ..
                "need to finding the fabled Pools of Youth!\n\nPlease, <class>! Go to those ruins and " ..
                "salvage any tablets that still have writing on them.",
            rewardChoices = {{81522, 1}, {81523, 1}, {81524, 1}, {81525, 1}, {81526, 1}},
            rewardMoney = 102000,
        },
        [30346] = {
            description = "Perhaps these mogu know where the pools are.\n\nOur scouts have reported " ..
                "seeing a commander along the southern side of the Ruins of Dojan.\n\nKill him and take " ..
                "whatever information he is carrying. They should lead you to the pool.",
            rewardMoney = 102000,
        },
        [30347] = {
            description = "North! Go north to the Pools of Youth. Get some of the water but be on your " ..
                "guard.\n\nThe mogu list this as a \"high value\" target. Kang Bramblestaff will meet you " ..
                "there if he has not already arrived by your side.",
            rewardChoices = {{81537, 1}, {81538, 1}, {81539, 1}, {81540, 1}, {81541, 1}},
            rewardMoney = 102000,
        },
        [30348] = {
            description = "Something is... off. The water feels strange.\n\nWhen we arrived here I felt " ..
                "the presence of the Light, strong and vibrant, far to the north.\n\nI thought it would " ..
                "be the Pools of Youth. But this... this water is tainted somehow. Stained with mogu " ..
                "magics.\n\nI think it best I try only a sip and we see what happens.",
            rewardMoney = 102000,
        },
        [30349] = {
            description = "While you were at the ruins dusting off tablets for my father I lost five " ..
                "scouts to wandering mogu patrols.\n\nThese creatures apparently have little interest in " ..
                "peace and are about as trustworthy as the Horde.\n\nThey are too numerous and we are too " ..
                "weak, however.\n\nGo to the ruins west of here and cull the mogu numbers. They won't be " ..
                "expecting a <class>.",
            rewardChoices = {{84281, 1}, {84282, 1}, {84283, 1}, {84284, 1}, {84285, 1}},
            rewardMoney = 102000,
        },
        [30350] = {
            description = "The hidden master may have to wait. Look at these people, $p.\n\nThey are so " ..
                "THIN! They must be starving.\n\nYou know what we need? A big steaming bowl of Squirmy " ..
                "Delight.\n\nIf you find yourself near a river, try rounding up some intact skitterer " ..
                "glands and I'll cook up a batch.",
            rewardItems = {{88388, 10}},
            rewardMoney = 102000,
        },
        [30351] = {
            description = "The mogu really like their poisons and curses. Mama Bramblestaff always said " ..
                "lotus tea cures any mogu curse.\n\nI saw some imperial lotus plants in the nearby Ruins " ..
                "of Dojan. We should go gather some of their leaves and keep them on hand just in case " ..
                "the mogu get unruly.\n\nAlso, this will give me a chance to introduce my fists to some " ..
                "mogu faces.",
            rewardItems = {{88532, 5}},
            rewardMoney = 102000,
        },
        [30352] = {
            description = "Thing about hunting birds is you need ammo - and I ain't got any. Thing about " ..
                "hunting with Nesingwary is you need to prove you can keep your tally and bragging rights " ..
                "up.\n\nCan't hunt, can't brag. And I like bragging so this is no good.\n\nCan I hire you " ..
                "to go kill me some carp hunters? You'll find them up and down the river west of here. " ..
                "There are a bunch of them so don't hesitate to hunt while doing other stuff.",
            rewardMoney = 102000,
        },
        [30353] = {
            description = "Two words: Tiger Blood!\n\nThis is gonna sell better than saronite back on the " ..
                "black market. Especially once I finish spreading a rumor about how it makes you all buff " ..
                "and stuff.\n\nAnd this jungle is just full of tigers. Can you round up a few vials of " ..
                "tiger blood for me? I'll cut you in on the scam.",
            rewardChoices = {
                {81494, 1}, {81495, 1}, {81496, 1}, {81497, 1}, {81498, 1}, {81499, 1}, {81500, 1},
                {81501, 1}, {81502, 1},
            },
            rewardMoney = 102000,
        },
        [30354] = {
            description = "We were searching the ruins south of here when the mogu fell upon us out of " ..
                "nowhere.\n\nSome of us were able to retreat to this encampment but many others were " ..
                "captured. The mogu have also caught a number of the Horde who happened to be in the area " ..
                "as well.\n\nPlease, $p, rescue any sentinels that you can.\n\nLeave the Dawnchasers to " ..
                "their fate.",
            rewardMoney = 102000,
        },
        [30355] = {
            description = "Mogu do NOT use arcane magics.\n\nThey are thugs. They have always been thugs. " ..
                "Only when they ruled their empires in the old stories did they ever know any kind of " ..
                "magic.\n\nBut these mogu are using arcane portals and old artifacts. We need to stop " ..
                "them!\n\n$p, look for any artifacts the mogu are using to cast their magics with. I saw " ..
                "piles of these items being collected near the Ruins of Korja south of here.",
            rewardChoices = {
                {81503, 1}, {81504, 1}, {81505, 1}, {81506, 1}, {81507, 1}, {81508, 1}, {81509, 1},
                {81510, 1}, {81511, 1},
            },
            rewardMoney = 102000,
        },
        [30356] = {
            description = "The mogu reclaimers are using portals to connect to Kun-Lai Summit, bringing " ..
                "in reinforcements and supplies.\n\nWhat is worse, they are sending their captives " ..
                "through these portals.\n\nGo to the Ruins of Korja and destroy as many of these Korjan " ..
                "Reclaimers as you can find.",
            rewardMoney = 102000,
        },
        [30357] = {
            description = "Help me, $p. These poor pandaren are in need of healing, and my powers are " ..
                "weakened.\n\nI did find an old tome in my collection that allowed me to convert the " ..
                "herbs you collected earlier into a healing poultice.\n\nUse this on the injured pandaren " ..
                "and it should get them back on their feet.",
            rewardChoices = {{84291, 1}, {84292, 1}, {84293, 1}, {84294, 1}, {84295, 1}},
            rewardMoney = 102000,
        },
        [30359] = {
            description = "They have my daughter! Brojai... that Lord Reclaimer! I can see him clearly " ..
                "through Lyalia's eyes.\n\nThat foolish girl must have tried to take him head " ..
                "on.\n\nPlease, $p! Go to the Ruins of Korja and try to free her.\n\nI'll get Kang and " ..
                "try to draw out Brojai from the ruins with a distraction.",
            rewardMoney = 102000,
        },
        [30360] = {
            description = "My father gave me his life. Tyrande gave me her trust. My sentinels gave me " ..
                "their allegiance.\n\nIt is time I repaid them all.\n\nWith Brojai dead we can mop up the " ..
                "remaining mogu. The next threat is the mantid.\n\nGo north to Stoneplow and lend them " ..
                "your help. Tell them I will be bringing what sentinels I can muster to aid in the " ..
                "defense of their city against the mantid.",
            rewardMoney = 10200,
        },
        [30361] = {
            description = "The mantid! They came out of nowhere and smashed our convoy to ruin, " ..
                "scattering our people this way and that.\n\nNow they are preparing to hit " ..
                "Stoneplow.\n\nPlease, <class>, destroy some of these beasts before they get sufficient " ..
                "numbers to flank our home.\n\nIf my cousin, Ambassador Len, is still alive and at our " ..
                "convoy he should be able to reward you for your help.",
            rewardChoices = {
                {81458, 1}, {81459, 1}, {81460, 1}, {81461, 1}, {81462, 1}, {81463, 1}, {81464, 1},
                {81465, 1}, {81466, 1},
            },
            rewardMoney = 106000,
        },
        [30363] = {
            description = "Ha! So my father just wasted twenty years of our lives on a fool's " ..
                "errand!\n\nI'm taking charge.\n\nWhen Tyrande sent us here she was very specific that we " ..
                "not come back until we find the source of the Light that she saw in her visions. It's " ..
                "obvious now that the Pools of Youth were not it.\n\nI want you to look for my scout. I " ..
                "sent her to investigate the Crane Temple but she hasn't returned.\n\nGet her report and " ..
                "rendezvous with us at the Sentinel Basecamp further west.",
            rewardMoney = 10200,
        },
        [30376] = {
            description = "The Shado-Pan are likely dealing with similar outbreaks elsewhere in " ..
                "Pandaria.\n\nSeek out Loon Mai, the Shado-Pan Watch Commander in Stoneplow on the " ..
                "western end of the Valley of the Four Winds. Let him know that we have the situation " ..
                "here under control; the Shado-Pan need not send any aid.\n\nQuite the opposite, in fact " ..
                "- I will be sending many of my followers on pilgrimage, to bring a message of hope to " ..
                "those in need.\n\nThank you again, $p. Farewell.",
            rewardMoney = 10200,
        },
        [30384] = {
            description = "Horde sunwalkers! We saw one of their scouts patrolling by the oubliette not " ..
                "long before you arrived.\n\nI don't know how he got here but I can guarantee you he " ..
                "isn't alone. They never are.\n\nKill the sunwalker scout before he reports our position.",
            rewardMoney = 102000,
        },
        [30385] = {
            description = "I offer you my heartfelt appreciation for your aid. Anji awaits you in the " ..
                "Setting Sun Garrison to the west.\n\nMay the day favor you, young <class>.",
            rewardMoney = 57000,
        },
        [30444] = {
            description = "We've been granted a brief respite from the mogu attacks as they attempt to " ..
                "recoup near the Five Sisters to our north. I would like you to see to it that they not " ..
                "be granted a similar reprieve.\n\nShow no mercy.",
            rewardMoney = 114000,
        },
        [30445] = {
            description = "She is headstrong, my little Lyalia. I should have known she would try to " ..
                "challenge the Lord Reclaimer.\n\nSince her mother died, I forsook much of the time I " ..
                "should have spent with her in search of immortality, insisting that we could live " ..
                "forever, together.\n\nAnd now my obsession has cost my little Lyalia her " ..
                "life.\n\nPlease, $p, when she wakes, tell her I love her.",
            rewardChoices = {
                {81449, 1}, {81450, 1}, {81451, 1}, {81452, 1}, {81453, 1}, {81454, 1}, {81455, 1},
                {81456, 1}, {81457, 1},
            },
            rewardMoney = 102000,
        },
        [30449] = {
            description = "Now that you have gathered all of the Crane cards together into a deck, a " ..
                "ninth card mysteriously appears with the same backing as the first eight. On this card " ..
                "is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have " ..
                "heard that the entrance to this faire appears near Mulgore and Goldshire every month.",
            rewardItems = {{79330, 1}},
        },
        [30450] = {
            description = "Now that you have gathered all of the Ox cards together into a deck, a ninth " ..
                "card mysteriously appears with the same backing as the first eight. On this card is " ..
                "inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard " ..
                "that the entrance to this faire appears near Mulgore and Goldshire every month.",
            rewardItems = {{79329, 1}},
        },
        [30451] = {
            description = "Now that you have gathered all of the Serpent cards together into a deck, a " ..
                "ninth card mysteriously appears with the same backing as the first eight. On this card " ..
                "is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have " ..
                "heard that the entrance to this faire appears near Mulgore and Goldshire every month.",
            rewardItems = {{79331, 1}},
        },
        [30452] = {
            description = "Now that you have gathered all of the Tiger cards together into a deck, a " ..
                "ninth card mysteriously appears with the same backing as the first eight. On this card " ..
                "is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have " ..
                "heard that the entrance to this faire appears near Mulgore and Goldshire every month.",
            rewardChoices = {{79327, 1}, {79328, 1}},
        },
        [30457] = {
            description = "Clearly, you are a hero come to aid us.\n\nSlay the Bataari Tribe in the " ..
                "Kun-Lai Pass to the northwest until the Bataari Fire-Warrior is angered enough to " ..
                "appear. Dispatch him.",
            rewardChoices = {
                {84537, 1}, {84538, 1}, {84539, 1}, {84540, 1}, {84541, 1}, {84542, 1}, {90467, 1},
                {90468, 1}, {90623, 1},
            },
            rewardMoney = 204000,
        },
        [30459] = {
            description = "As soon as their reinforcements arrive, the yaungol are going to overrun our " ..
                "position here. If they do that, the village will be lost.\n\nWould you be willing to " ..
                "retrieve as many arrows off the battlefield as you can carry? I have a plan that just " ..
                "might save us with your help.",
            rewardMoney = 102000,
        },
        [30460] = {
            description = "Our warriors are fighting to keep the yaungol at bay in the Kun-Lai Pass to " ..
                "the northwest.\n\nTake this liniment. It is a powerful medicine that has been passed " ..
                "down in my family over the generations.\n\nUse the dit da jow to heal the injured " ..
                "warriors if you do not have healing powers of your own to use on them.",
            rewardMoney = 102000,
        },
        [30467] = {
            description = "My son - can you find my son?\n\nWhen the Jinyu attacked, he ran off in the " ..
                "confusion. I don't know if they've done anything with him, or if he's still alive, " ..
                "even.\n\nNothing else matters if I can't find him.\n\nI'd ask Mei... but something's " ..
                "wrong with her. She seems too... impulsive since the attack. I just can't trust that " ..
                "she'd bring him back safely.",
            rewardMoney = 51000,
        },
        [30468] = {
            description = "<The Swordmistress does not look well. There's a darkness to her eyes " ..
                "uncharacteristic of the pandaren.>\n\nI don't think I've ever been as... as furious as " ..
                "now. What betrayal!\n\nI fought them off when they attacked, killed a few here, but " ..
                "Merchant Shi is too much of a coward to let me go and finish the job!\n\nYou, do it for " ..
                "me. Kill them. Kill them all.",
            rewardChoices = {
                {84528, 1}, {84529, 1}, {84530, 1}, {84531, 1}, {84532, 1}, {84533, 1}, {84534, 1},
                {84535, 1}, {84536, 1},
            },
            rewardMoney = 102000,
        },
        [30469] = {
            description = "Of course, the first priority is finding my son. But, if we save ourselves " ..
                "only to starve, then what have we accomplished, in the end?\n\nPlease, I need you to " ..
                "recover some of the supplies that the Jinyu took from our caravan.",
            rewardMoney = 102000,
        },
        [30471] = {
            description = "That crazy Chee Chee is actually pretty neat. Mah always said that hozen were " ..
                "nothing but trouble, but... I guess he's just a better hozen then the rest of " ..
                "them.\n\nWe should do something nice for him! Those mountain hozen in the west make some " ..
                "really fancy stir fry, and keep bowls of it inside their little hozen houses.\n\nI bet " ..
                "Chee Chee would love some!",
            rewardMoney = 114000,
        },
        [30473] = {
            description = "That Fish Fellreed is kind of weird. First of all, her name's Fish. That's " ..
                "weird.\n\nOnce you talk to her, though, she's really a nice lady. Did you know that " ..
                "she's an animal lover?\n\nI've got an idea! The Kunzen hozen, in the mountains to the " ..
                "west, make little animal statues and put them in their huts to scare off bad guys. I bet " ..
                "Fish would LOVE something weird like that!",
            rewardMoney = 114000,
        },
        [30475] = {
            description = "Farmer Fung is pretty mean, and just a little scary. Mah always said that he " ..
                "was one of the best farmers in the valley, though.\n\nI think I know the perfect gift " ..
                "for a mean, kind of scary guy like him.\n\nThere's some big plainshawks that circle the " ..
                "hills to the west of here. You should get one, find a big piece of meat, and then ask " ..
                "Kol Ironpaw to grill it up!",
            rewardMoney = 114000,
        },
        [30480] = {
            description = "From the moment I first rose from the river, I knew I was destined to be " ..
                "Waterspeaker.\n\nI was taught many rituals, and have performed all of them, save " ..
                "one.\n\nThere was one, an extremely ancient one, that we were told to call upon if our " ..
                "people ever turned against us.\n\nThis must have happened in our people's distant past, " ..
                "because we haven't needed to use it in our village's memory.\n\nI suppose now is the " ..
                "time to do so.",
            rewardMoney = 102000,
        },
        [30481] = {
            description = "You see the shiny stones in the walls? Rook wants some. The mogu been " ..
                "collecting them, so they have some to take too maybe.\n\nIf you find stones, you please " ..
                "bring them to Rook? Rook will be your friend.",
            rewardMoney = 114000,
        },
        [30482] = {
            description = "A single large mogu performing a ritual on the lake caught your attention " ..
                "while you were killing the other mogu in the area. It seems unwise to let his ritual " ..
                "complete.",
            rewardItems = {{90625, 1}},
            rewardMoney = 228000,
        },
        [30484] = {
            description = "The time for war is at hand, <name>!\n\nWe've been training these natives " ..
                "non-stop since you left, and I believe they're as good as they're going to get.\n\nSee " ..
                "for yourself. Check in with the others and return with your findings.\n\nWe must rely on " ..
                "our enemy being somehow... even less prepared.",
            rewardMoney = 98000,
        },
        [30485] = {
            description = "These hozen are behaving most unnaturally, <name>. Marching in formation? In " ..
                "armor?\n\nThis troubles me. We must discuss it at another time, however. I have come to " ..
                "ask for your assistance.\n\nThe ancient fresco, where last we spoke, is nearly unveiled. " ..
                "I am certain that it holds ancient wisdom - knowledge that the emperor wanted us to " ..
                "remember.\n\nMy meditations alone may not be enough to discern its meaning. Please, take " ..
                "this heirloom to the shrine of my ancestors. I shall require their assistance.",
            rewardMoney = 98000,
        },
        [30487] = {
            description = "The mountain pass is very dangerous. You need much luck to survive. Nephew " ..
                "Bentnail will show you the way.\n\nPerhaps today is a lucky day to travel though. Wind " ..
                "blows from the east; this is good sign. Grummles always travel best when east wind " ..
                "blows.\n\nClimb in the cart when you are ready to leave.",
            rewardMoney = 106000,
        },
        [30489] = {
            description = "Say, if you really are here to help, I could use me some needles off them " ..
                "sprites in Pranksters' Hollow.\n\nThe grummles don't believe in luck they can't smell. " ..
                "They'll pay better for yaks that have that fresh needle scent.",
            rewardMoney = 106000,
        },
        [30491] = {
            description = "Look, my father is crazy. I love him, but he's crazy.\n\nThese yaungol managed " ..
                "to completely obliterate our ranch and scattered our yaks every which way.\n\nIf I know " ..
                "my father though, he's going to try to go head to head with the yaungol to get the yaks " ..
                "back.\n\nCan you help us round up some of the yaks so my father doesn't do anything " ..
                "stupid?\n\nJust ride them over to the Yak Wash so we can clean them up and sell them to " ..
                "the grummles.",
            rewardMoney = 106000,
        },
        [30492] = {
            description = "I wasn't lying about your reward. Here, take these washed yaks to the grummle " ..
                "caravan master Eightcoins.\n\nYou can find him at the Grummle Bazaar west of here. He'll " ..
                "credit us and give you a delivery fee.\n\nHe may be short, but he is our biggest " ..
                "customer.\n\nReturn to me if you lose the yaks. More often than not they just come right " ..
                "back here anyway. Once they've been cleaned that is.",
            rewardChoices = {{82574, 1}, {82575, 1}, {82576, 1}, {82577, 1}, {82578, 1}},
            rewardMoney = 106000,
        },
        [30495] = {
            description = "Can I trouble you for another favor?\n\nWe're way behind schedule, and this " ..
                "jade shipment is the last we need to finish the great statue.\n\nI've got my hands full, " ..
                "so could you run this ore over to the other foremen?\n\nHistorian Dinh, Surveyor Sawa, " ..
                "and Kitemaster Shoku can all be found around the base of the statue. Taskmaster Emi is " ..
                "directing production at the top of the statue.\n\nWe're on a deadline, so make sure you " ..
                "do it fast! Time's a wasting!",
            rewardChoices = {{80773, 1}, {80774, 1}, {80775, 1}, {80776, 1}, {80777, 1}},
            rewardMoney = 98000,
        },
        [30496] = {
            description = "There is great dissent in Inkgill, <race>. Elder Shai Hu drank the " ..
                "sha-corrupted waters of the mere, and forced the others to do the same. When I " ..
                "protested, Orachi of the town guard confiscated my ritual staff and banished me.\n\nNow, " ..
                "I am not only an exile, I am unable to speak with the waters that once gave me " ..
                "guidance!\n\nI am not a fighter. But if you are, perhaps you can recover my staff from " ..
                "Orachi? He is in town to our north.",
            rewardMoney = 204000,
        },
        [30498] = {
            description = "Oh, before I forget, I have something I was asked to deliver to you. A letter " ..
                "from one of your companions, I assume.\n\nI was made to understand that your presence " ..
                "was urgently required, so I took the liberty of arranging your passage.\n\nSpeak to " ..
                "Ginsa Arroweye just south of here when you're ready. She has a kite waiting.",
            rewardMoney = 74000,
        },
        [30499] = {
            description = "Oh, before I forget, I have something I was asked to deliver to you. A letter " ..
                "from one of your companions, I assume.\n\nI was made to understand that your presence " ..
                "was urgently required, so I took the liberty of arranging your passage.\n\nSpeak to " ..
                "Ginsa Arroweye just south of here when you're ready. She has a kite waiting.",
            rewardMoney = 74000,
        },
        [30500] = {
            description = "Pandaria is a mystical land, traveler.\n\nIt bears repeating that some of its " ..
                "secrets remain hidden, even to Lorewalkers.\n\nSealing those fissures did not mend what " ..
                "has been broken. If the legends are true, it will take much more to release this land " ..
                "from the grasp of the Sha.\n\nThe aggression of that battle awakened a host of living " ..
                "negative emotions. What you see here is likely the first of many such " ..
                "manifestations.\n\nFor now, we can only try to diminish their presence here.",
            rewardMoney = 98000,
        },
        [30502] = {
            description = "The more powerful remnants of that horrible manifestation may be too much for " ..
                "you to handle on your own, <name>.\n\nI fear I'd be of little help in terms of actual " ..
                "combat, but I can suggest a solution.\n\nThe great jade statue was soon to become a " ..
                "living serpent - one of our revered celestials. Its construction imbued it with special " ..
                "powers that may sufficiently weaken these adversaries.",
            rewardMoney = 98000,
        },
        [30504] = {
            description = "Your companions have made themselves at home in our land, and brought with " ..
                "them a dangerous conflict.\n\nThe full extent of their destruction here we cannot yet " ..
                "know. Already it is... unspeakable.\n\nNevertheless, to forsake your friends out of " ..
                "spite would be against our way. Any that yet live are doubtlessly wounded and in " ..
                "desperate need of care.\n\nThese fireworks were to celebrate the statue's completion. " ..
                "Use them near your companions to signal Mishi, and she will bear them off to safety.",
            rewardMoney = 98000,
        },
        [30506] = {
            description = "It would seem that your Admiral Taylor has awakened from his injuries. He and " ..
                "his people are upstairs in the apothecary's house back in Binan Village.\n\nHe has " ..
                "requested your presence.",
            rewardMoney = 10200,
        },
        [30507] = {
            description = "It would seem that your Admiral Taylor has awakened from his injuries. He and " ..
                "his people are upstairs in the apothecary's house across the way.\n\nHe has requested " ..
                "your presence.",
            rewardMoney = 10200,
        },
        [30508] = {
            description = "It would seem that your Admiral Taylor has awakened from his injuries. He and " ..
                "his people are upstairs.\n\nHe has requested your presence.",
            rewardMoney = 10200,
        },
        [30509] = {
            description = "It would seem that your General Nazgrim has awakened from his injuries. He and " ..
                "his people are upstairs in the apothecary's house back in Binan Village.\n\nHe has " ..
                "requested your presence.",
            rewardMoney = 10200,
        },
        [30510] = {
            description = "It would seem that your General Nazgrim has awakened from his injuries. He and " ..
                "his people are upstairs in the apothecary's house across the way.\n\nHe has requested " ..
                "your presence.",
            rewardMoney = 10200,
        },
        [30511] = {
            description = "It would seem that your General Nazgrim has awakened from his injuries. He and " ..
                "his people are upstairs.\n\nHe has requested your presence.",
            rewardMoney = 10200,
        },
        [30512] = {
            description = "< Admiral Taylor winces in pain.>\n\nJade Forest was a disaster.\n\nAnduin's " ..
                "gone. We lost some good people. We didn't stop the Horde from advancing into the " ..
                "continent.\n\nBut I think I've found a way to get the locals on our side. You just " ..
                "helped fight off some of these \"yaungol\", no?\n\nI hear yaungol sacked Westwind Rest, " ..
                "a local village. We've been told that two groups of survivors have camped out along the " ..
                "road west out of town.\n\nWe help them out, maybe they'll consider siding with the " ..
                "Allliance.",
            rewardMoney = 102000,
        },
        [30513] = {
            description = "I am injured, but we can't stop here.\n\nThe hozen were... unreliable. The " ..
                "pandaren would be much better allies.\n\nYou have seen the refugees in this village, and " ..
                "heard of the yaungol invasion, no?\n\nWell, we've heard from the locals that Eastwind " ..
                "Rest, a nearby village, was destroyed by the Yaungol.\n\nApparently some survivors have " ..
                "gathered along the road out of town.\n\nGo. Take the road west. Gather the " ..
                "survivors.\n\nWe'll help them rebuild. Then, they will see the advantage of joining the " ..
                "Horde!",
            rewardMoney = 102000,
        },
        [30514] = {
            description = "The yaungol have always been a difficult, proud people, but never this violent " ..
                "or aggressive.\n\nI do not know what has prompted this change in their behavior, but we " ..
                "don't have time to find out, now. We fear for our lives and livelihoods as long as " ..
                "Ur-Bataar, leader of the Bataari yaungol, lives.\n\nGo, set the banner in his camp " ..
                "ablaze to challenge him, and then defeat him in battle. Only then will we be secure.",
            rewardMoney = 204000,
        },
        [30515] = {
            description = "The yaungol have always been a difficult, proud people, but never this violent " ..
                "or aggressive.\n\nI do not know what has prompted this change in their behavior, but we " ..
                "don't have time to find out, now. We fear for our lives and livelihoods as long as " ..
                "Ur-Bataar, leader of the Bataari yaungol, lives.\n\nGo, set the banner in his camp " ..
                "ablaze to challenge him, and then defeat him in battle. Only then will we be secure.",
            rewardMoney = 204000,
        },
        [30517] = {
            description = "The next voting member on the Tiller's council is Farmer Fung, and it's easy " ..
                "to see why.\n\nThat man's vegetables are the biggest in the valley! I only hope that " ..
                "someday I can grow pumpkins as big as his.\n\nIf we hope to join the Tillers, he would " ..
                "be the next person to convince.",
            rewardMoney = 57000,
        },
        [30519] = {
            description = "The next vote we'll need is from Nana Mudclaw. She's Haohan's grandmother, and " ..
                "she's been a Tiller longer than you and I have been alive!\n\nShe's still working at the " ..
                "Tillers building in Halfhill. Why don't you pay her a visit?",
            rewardMoney = 57000,
        },
        [30522] = {
            description = "What are YOU doing here, citypaw?\n\nLook, I've got my hands full with a " ..
                "break-in at my shed to the west. Some rascals came in the middle of the night and " ..
                "ransacked the place.\n\nI've got missing seeds, broken tools, and eaten inventory to " ..
                "deal with.\n\nI'll just add it to my list of other troubles: a whole wagon of melons " ..
                "stolen, a broken water pump, animals ruining my harvest...\n\nI wish that I could just " ..
                "get to the bottom of all this already!",
            rewardMoney = 114000,
        },
        [30523] = {
            description = "Hey <name>. I've been looking at that wagon every day, day in and day out, " ..
                "since the day I moved in. Quite an eyesore, don't you think?\n\nI heard in town that " ..
                "Fish Fellreed is quite handy with tools. She might be able to fix it up, and then we " ..
                "could turn that patch of land into a plot for farming.\n\nWhy don't you talk to her and " ..
                "see if she'd be willing to do the job?",
            rewardMoney = 57000,
        },
        [30525] = {
            description = "All right, <name>. This is our big chance!\n\nMr. Mudclaw's farm is in big " ..
                "trouble. Those mountain hozen are coming down at night, wrecking his crops and eating " ..
                "his hard-earned harvest.\n\nWe've got to get rid of them for good, and I know just how " ..
                "to do it.\n\nBack in the day, my grandpa showed me how to mix a wounding poison to deal " ..
                "with the pests on the farm.\n\nThe virmen warrens to the north hold the key ingredients " ..
                "for my mixture.\n\nDon't look so worried, <name>! I'm pretty sure this is going to work.",
            rewardMoney = 114000,
        },
        [30529] = {
            description = "Now that we're officially members of the Tillers Union, Mr. Mudclaw said he'd " ..
                "be happy to help us upturn this big ole' rock in the middle of our field.\n\nOnce we " ..
                "clear away that stone, I've got something special planned.\n\nRun down and give him a " ..
                "holler to let him know that we're ready.",
            rewardMoney = 57000,
        },
        [30535] = {
            description = "Well, first things first! I'm going to need lots of help 'round here.\n\nIf " ..
                "we're going to be partners, you've got to learn how to harvest crops, and if you wanna " ..
                "harvest crops you gotta plant seeds!\n\nNow it's my understanding that a mister, uh... " ..
                "Grainfell? No, that wasn't it... Greedfill? That doesn't sound right...\n\nGreenfield! " ..
                "That's his name! He's the man to see for seeds.\n\nGreenfield's got a stall over at " ..
                "Halfhill Market, directly southeast of here - go see him and pick up some vegetable " ..
                "seeds.",
            rewardMoney = 102000,
        },
        [30565] = {
            description = "Things seem to be goin' our way more and more lately, <name>. I was out doin " ..
                "some explorin' when I came upon this little beauty.\n\n<Sully gestures to the ballista " ..
                "to his right.>\n\nProblem is she's one of a set and the other one is still in pieces. " ..
                "I'd have gotten it together by now if those pesky Grimleers hadn't ambushed me and taken " ..
                "some of the gears and bolts.\n\nHey, ye seem to be pretty good at handlin' the natives. " ..
                "Ye wouldn't mind goin' and helpin' ol'Sully out would ye?",
            rewardMoney = 98000,
        },
        [30568] = {
            description = "Welcome back, <name>! It seems the Jinyu have taken to our training even " ..
                "better than I had hoped. We're in the final stages of our preparations now.\n\nI need " ..
                "someone to go check in with Amber, Bold Karasshi, and Mishka. See if they need any help " ..
                "to complete their training.\n\nYou'll find Karasshi and Mishka here in Pearlfin Village. " ..
                "Amber is training recruits in Slingtail Pits to the northwest.",
            rewardMoney = 98000,
        },
        [30569] = {
            description = "I... I escaped from Farmer Chow 's, to the southeast of here. It's been taken " ..
                "over by yaungol, but the old man and his wife just won't give it up!\n\nPlease, go there " ..
                "and help him out. Maybe if you do, he'll be willing to send some folks back here and " ..
                "help you guys farm up some food for the new town?",
            rewardMoney = 10200,
        },
        [30570] = {
            description = "I... I escaped from Farmer Chow 's, to the southeast of here. It's been taken " ..
                "over by yaungol, but the old man and his wife just won't give it up!\n\nPlease, go there " ..
                "and help him... Maybe if you do, he'll be willing to send some folks back here and help " ..
                "you guys farm up some food for the new town?",
            rewardMoney = 10200,
        },
        [30571] = {
            description = "Those Ordo yaungol are working my farmhands to death! It just ain't " ..
                "right.\n\nPlease, <class>, save them before it's too late.",
            rewardMoney = 102000,
        },
        [30575] = {
            description = "Mobility is going to be key to maintaining our foothold in this new land. " ..
                "Problem is, there's no way to maintain mobility without mounts, and... well, we don't " ..
                "have many of those here, now do we?\n\nThe local yaks seem to make good mounts. At " ..
                "least, the local pandaren say they do. Why don't you go round some up for us?",
            rewardChoices = {
                {84509, 1}, {84510, 1}, {84511, 1}, {84512, 1}, {84513, 1}, {84514, 1}, {84515, 1},
                {84516, 1}, {84517, 1},
            },
            rewardMoney = 102000,
        },
        [30581] = {
            description = "Sure, I'm willing to help you guys out. But we need to eat, too! I don't even " ..
                "have a pot to cook in! Let alone ingredients to put in it!\n\nHere's a list of the " ..
                "things that I need. Now get!",
            rewardItems = {{88398, 1}},
            rewardMoney = 102000,
        },
        [30583] = {
            description = "Oi!\n\nWe need ta' get us some food, if we're gonna survive here for " ..
                "long!\n\nYe' may not know it, but I'm somethin' of a cook me'self. Why don'tcha go out " ..
                "there and fetch us some meaty bits. I can cook 'em up and feed us for weeks! Or, days, " ..
                "at least.",
            rewardMoney = 102000,
        },
        [30584] = {
            description = "Have you ever had a fresh dojani eel <name>? No?\n\nWell you have not lived " ..
                "then! Head north up to the dojani river and fish up a few for us. Be careful, those eels " ..
                "can zap you if you're not careful!",
            rewardItems = {{81175, 1}},
            rewardMoney = 114000,
        },
        [30585] = {
            description = "Legend tells of a great beast in the forest to the north. My son is missing " ..
                "and I fear he may have wandered too near its lair....\n\nHead northwest to Krasari Falls " ..
                "and look for a mysterious whirlpool - this is the key to revealing what is hidden there. " ..
                "Kill the wretched beast and recover any clues to my son's whereabouts.",
            rewardMoney = 114000,
        },
        [30586] = {
            description = "Pandaren have been harvesting jagged abalone in this area for generations. Now " ..
                "it's time for you to learn the ritual.\n\nThe abalone can be found just northeast of " ..
                "here in narsong trench. Be careful, we have noticed increased shark activity in that " ..
                "area recently.",
            rewardMoney = 114000,
        },
        [30587] = {
            description = "For now, the yaungol invaders seem content to steal yaks. Surveying the area, " ..
                "however, you notice they could easily move on the Yak Wash at any moment.\n\nThinning " ..
                "their numbers may help show the yaungol that this area is protected.",
            rewardMoney = 106000,
        },
        [30588] = {
            description = "The riverblade saurok clan is attacking one of our local fishing expeditions! " ..
                "They need help right away!\n\nThin those saurok out and help that expedition return " ..
                "safely!",
            rewardMoney = 114000,
        },
        [30593] = {
            description = "The admiral's asked me to take care of a major problem, but my specialty's in " ..
                "healing, not fighting!\n\nThe pandaren in the camp here have told me that something is " ..
                "animating the statues to the northeast at Mogujia\n\nWill you help me out, <name>? We " ..
                "can't afford to have a fight with an army of statues right now.",
            rewardMoney = 102000,
        },
        [30594] = {
            description = "I've got much to do here, <name>. I could use your help.\n\nThere's a place to " ..
                "the northwest. The pandaren here call it Mogujia. Something's causing the statues there " ..
                "to animate, and our pandaren friends here are pretty spooked about it.\n\nIf they're not " ..
                "dealt with soon, we might have a serious problem. We just moved in. It's not like we can " ..
                "afford to fight a war with an army of statues right now.",
            rewardMoney = 102000,
        },
        [30595] = {
            description = "Let me guess, you're here to deal with the mogu statues that are being " ..
                "reanimated. What a coincidence, I'm here to, um... conduct research on the mogu.\n\nI " ..
                "tell you what, if you bring me as many of the mogu relics in there that you can carry, " ..
                "I'll give you a cut. Of the research... funding.",
            rewardMoney = 102000,
        },
        [30597] = {
            description = "This beautiful stone clearly has magical potential... at least to one trained " ..
                "in alchemy. You are certain that with the right herbs native to Pandaria, this stone " ..
                "could become very useful.",
            rewardItems = {{75274, 1}},
            rewardXP = 69400,
        },
        [30598] = {
            description = "Great cranes have been nesting in this area for generations. The Narsong " ..
                "Spires provide a sheltered area to rear their young.\n\nTheir pristine eggs are revered " ..
                "as bait for catching the silver goby. Retrieve a crane egg and see if you can catch a " ..
                "goby!",
            rewardMoney = 114000,
        },
        [30599] = {
            description = "Before, grummles keep hozen from ravaging by bribing with food.\n\nBut now the " ..
                "Broketooth hozen south of here have their big magic idols. The Ook of Dook has trained " ..
                "them to use their idols to get power from sacrifices.\n\nThey are using them to kill " ..
                "grummles!\n\nYou must destroy these idols!\n\nFor every idol, there is a chief. Kill the " ..
                "chief and throw the corpse on their altar.",
            rewardItems = {{88385, 1}},
            rewardMoney = 106000,
        },
        [30601] = {
            description = "It is very bad fortune to travel mountain paths without a good guide. We " ..
                "grummles make the best guides, but many have run away. They fear the mountain pass now. " ..
                "Many good grummles disappear up there.\n\nGrummles are good at many things, but are not " ..
                "very brave. Maybe with fire lotus incense you can make them brave. Then they will show " ..
                "you the way.",
            rewardMoney = 106000,
        },
        [30603] = {
            description = "They took my luckydo! Their leader hozen here, Mo Mo, stole my " ..
                "rabbitsfoot.\n\nThis is most bad fortune for grummles. My rabbitsfoot is a big luckydo " ..
                "for grummles everywhere. If hozen learn how to get luck from my rabbitsfoot then all is " ..
                "lost.\n\nPlease can you get it back?",
            rewardMoney = 106000,
        },
        [30604] = {
            description = "Hozen only ravage when they think their supplies are too few for their number " ..
                "of mouths.\n\nProblem is, hozen always have more mouths than food.\n\nWe have very few " ..
                "grummles these days.\n\nIt is a hard thing to ask, but can you be a friend to grummles, " ..
                "and destroy some of the Broketooth hozen south of here? It is the only way to prevent " ..
                "them from destroying the landscape.",
            rewardMoney = 106000,
        },
        [30605] = {
            description = "While you were gone, I saw a group of grummles coming down the Burlap Trail. " ..
                "It was led by my Brother Yakshoe.\n\nBut then the Knucklethumps attacked. They took my " ..
                "brother and his grummles north.\n\nPlease, $p! Save my brother. He always has bad " ..
                "fortune and no luck, but he is my brother. Look for him at the alter in front of Fort " ..
                "Silverback.",
            rewardItems = {{88379, 10}},
            rewardMoney = 106000,
        },
        [30606] = {
            description = "The Knucklethump hozen have new chief, the Ook of Dook.\n\nHe sees fear in the " ..
                "west, anger in the south, hatred in the north, and yaungols in the east.\n\nAnd so he " ..
                "sets his hozen to ravage, gathering food and supplies for coming famine.\n\nThey are " ..
                "many Knucklethumps and dangerous.\n\nPlease, Luckydo, can you defeat their fighters?",
            rewardChoices = {
                {88080, 1}, {88081, 1}, {88082, 1}, {88083, 1}, {88084, 1}, {88085, 1}, {88086, 1},
                {90623, 1},
            },
            rewardMoney = 106000,
        },
        [30607] = {
            description = "The hozen have a yeti! They call it Old Poot Poot and keep it at the back of " ..
                "their cave.\n\nHozen are normally scared of yeti, but now they feed it grummles.\n\nThey " ..
                "have a Hunter Chief, Cho Cho the Wicked. Can you see if he has a key on him to the yeti " ..
                "shackles?\n\nBad fortune for hozen if a yeti is loose in their fort.",
            rewardMoney = 106000,
        },
        [30610] = {
            description = "Now that grummles are rescued, we need to rescue our supplies.\n\nThe Ook of " ..
                "Dook is only chief because he has supplies.\n\nGo to the Dooker Dome area north west of " ..
                "here. Take some grummles with you. Keep them safe and get them near supply " ..
                "crates.\n\nGrummles know what to do from there.\n\nRabbitsfoot and I will meet you there.",
            rewardMoney = 106000,
        },
        [30612] = {
            description = "The time has come to face the Ook of Dook. We beat him, and the hozen won't " ..
                "have someone telling them to ravage.\n\nHere is the plan: Yakshoe will lead Tassle in to " ..
                "arena and scare away Chomp Chomp.\n\nThen, you sneak in and fight the Ook of Dook while " ..
                "his hozen are distracted by the yeti rampaging through their home.\n\nWe'll meet you " ..
                "back at Kota Basecamp with a big reward. Good fortune to you, friend of grummles.",
            rewardChoices = {
                {82541, 1}, {82542, 1}, {82543, 1}, {82544, 1}, {82545, 1}, {82546, 1}, {82547, 1},
                {82548, 1}, {82549, 1},
            },
            rewardMoney = 106000,
        },
        [30613] = {
            description = "Armored Carp are a delicacy around these parts.\n\nUnfortunately we can't fish " ..
                "them up since they snap our hooks with their powerful jaws. Take this fishing spear and " ..
                "see if you can catch a few for us.",
            rewardMoney = 114000,
        },
        [30614] = {
            description = "When the yaungols came, they began to dig up oil. What is this \"oil\", I " ..
                "wonder? Perhaps it is thing of much undiscovered luck. This I must know.\n\nHere, take " ..
                "this vial, and fill it with yaungol oil from one of their windmills. I will give you " ..
                "many fortunes if you bring me some.",
            rewardMoney = 106000,
        },
        [30616] = {
            description = "Yaungols are attacking our Burlap Trail. This is most bad fortune for " ..
                "grummles.\n\nWe use that trail to carry supplies to the Serpent's Spine. Without " ..
                "supplies, the defenders of the wall are in danger.\n\nGrummles are packers and " ..
                "explorers, not fighters. Could you be a luckydo for us and stop the yaungol blockade?",
            rewardChoices = {{82569, 1}, {82570, 1}, {82571, 1}, {82572, 1}, {82573, 1}},
            rewardMoney = 106000,
        },
        [30619] = {
            description = "I know your friends are worried about the animating statues over at Mogujia, " ..
                "but I'll tell you what you should really be worried about.\n\nWhere there are animated " ..
                "statues, there are mogu. I don't know if you've seen one before, but if you " ..
                "haven't...\n\nWell, let's just say mogu are bad, bad, news.\n\nWhile you're dealing with " ..
                "whatever else you're doing, you need to get the mogu behind the trouble!",
            rewardChoices = {
                {82487, 1}, {82488, 1}, {82489, 1}, {82490, 1}, {82491, 1}, {82492, 1}, {82493, 1},
                {82494, 1}, {82495, 1},
            },
            rewardMoney = 204000,
        },
        [30620] = {
            description = "I know your friends are worried about the animating statues over at Mogujia, " ..
                "but I'll tell you what you should really be worried about.\n\nWhere there are animated " ..
                "statues, there are Mogu. I don't know if you've seen one before, but if you " ..
                "haven't...\n\nWell, let's just say Mogu are bad, bad, news.\n\nWhile you're dealing with " ..
                "whatever else you're doing, you need to get the Mogu behind the trouble!",
            rewardChoices = {
                {82487, 1}, {82488, 1}, {82489, 1}, {82490, 1}, {82491, 1}, {82492, 1}, {82493, 1},
                {82494, 1}, {82495, 1},
            },
            rewardMoney = 204000,
        },
        [30622] = {
            description = "Without the wall to protect us, we barely stand a chance. If you hadn't " ..
                "gathered so many people to help us, we wouldn't have a prayer.\n\nCheck in with Captain " ..
                "Oakenshield - he should be up near the break in the wall. Kill as many mantid as you can " ..
                "on the way there.\n\nIf we win, we win. If we lose, we go down fighting. For Pandaria!",
            rewardMoney = 102000,
        },
        [30623] = {
            description = "<Mei motions towards the battlefield.>\n\nYou see those huge mantid commanders " ..
                "out there? They have a strange aura about them. It reminds me of the sadness we saw at " ..
                "Zhu's Watch.\n\nPerhaps... they're under the influence of the sha, too?\n\nI kept " ..
                "Ken-Ken's mask - the one he used to remove the sha from Yi-Mo. I believe that, if we use " ..
                "it on the mantid, we can convince them to turn back.",
        },
        [30624] = {
            description = "I been thinkin'.\n\nWe got all this beer that Chen brewed, and we got all " ..
                "these people that you've gathered. We should bring the two together.\n\nThere's a bunch " ..
                "o' folks out there in the fields, riskin' their lives for Pandaria. You an' I should at " ..
                "least bring 'em a keg or two.\n\nThey might raise their mugs in victory. They might " ..
                "enjoy one last drink before gettin' skivvered by a mantid. Either way, I wouldn't want " ..
                "'em to fight without a good brew in their belly.",
        },
        [30625] = {
            description = "Those five students - the ones who were looking for the Hidden Master - they " ..
                "went up to the front lines, alone. I'd send Shado-Pan to aid them, but I haven't got any " ..
                "left.\n\nThere's dangerous creatures up there near the wall. If you find those students, " ..
                "make sure that they haven't fallen to any of them.",
            rewardMoney = 204000,
        },
        [30626] = {
            description = "I'm going to withdraw what few forces I have. We may have to fall back to the " ..
                "Stormstout Brewery, or even Halfhill. That call is Commander Loon Mai 's to make.\n\nYou " ..
                "go ahead. Deliver word to the Commander. My Shado-Pan will be shortly behind.",
            rewardMoney = 10200,
        },
        [30627] = {
            description = "That commander speaks hastily. He has the weapon he needs to win this battle. " ..
                "He has YOU.\n\n\"But it's too hard,\" you might say.\n\nYou would be wrong. It is not " ..
                "too hard. NOTHING IS TOO HARD.\n\nGo now, <name>. Go, and save Stoneplow!",
            rewardMoney = 306000,
        },
        [30628] = {
            description = "One last thing, <name>. Don't worry, it's not another favor. You've killed " ..
                "enough mantid today.\n\nWe recently received a shipment of high-quality armor from " ..
                "Kun-Lai Summit. I was planning to keep them for my men... but I can't think of anybody " ..
                "more deserving than you. You'll find them on the second floor of the inn, here in town.",
            rewardChoices = {
                {81476, 1}, {81477, 1}, {81478, 1}, {81479, 1}, {81480, 1}, {81481, 1}, {81482, 1},
                {81483, 1}, {81484, 1},
            },
            rewardMoney = 306000,
        },
        [30631] = {
            description = "Look at this creature, traveler. Only moments after we arrived, this mogu " ..
                "assassin attacked with no warning.\n\nHis blade was intended for the leader of the " ..
                "Golden Lotus. It is very lucky indeed that we were here to stop the attack.\n\nSeeing " ..
                "this attempt on Zhi's life, I fear for the safety of those who have already entered the " ..
                "valley.\n\nThe caretakers are settling your people into the city to the southeast. Go " ..
                "and speak to the leaders. Make sure they are safe.",
            rewardMoney = 102000,
        },
        [30632] = {
            description = "According to Zhi the Harmonious, the mogu are moving into the Vale from the " ..
                "Ruins of Guo-Lai to the west.\n\nI sent Anji and Kun to investigate the situation, but " ..
                "they have not yet returned.\n\nI need a capable <class> like you to go check on them.",
            rewardMoney = 57000,
        },
        [30633] = {
            description = "We'd been briefed on mogu sightings in the Vale, but the situation is worse " ..
                "than we had anticipated.\n\nScouts are swarming all over the ruins to the northwest, " ..
                "gathering intel and stealing treasures.\n\nYour objective is clear - dispatch of any " ..
                "scouts you see. An army cannot move if we take out its eyes.",
            rewardMoney = 114000,
        },
        [30634] = {
            description = "Lao Softfoot and I scouted up the ruins to the north.\n\nIt looks like the " ..
                "mogu are infiltrating the valley through a cave just up the hill, and already they are " ..
                "sending formidable reinforcements through.\n\nThere are too many enemies to take them " ..
                "head on, so you'll have to meet Lao Softfoot at the entrance to the ruins.\n\nHe'll help " ..
                "you sneak in under the cover of stealth. Then, plant this keg of explosives at the mouth " ..
                "of the cave.\n\nThe rest should take care of itself.",
            rewardMoney = 114000,
        },
        [30635] = {
            description = "We've taken care of the scout problem for now, but there are still advance " ..
                "mogu forces inside the Guo-Lai Halls down the hill.\n\nUnfortunately, their vicious " ..
                "guard dogs are protecting their operations deeper in the ruins.\n\nGo and dispatch of " ..
                "their beasts. Be on your guard - they can be quite good at blending into their " ..
                "surroundings.",
            rewardMoney = 114000,
        },
        [30636] = {
            description = "Many thousands of years ago, the rulers of the Vale sought energy from a " ..
                "powerful crystal known as Revelite.\n\nWith this substance, they were able to power " ..
                "cities, factories, and engines of war.\n\nZhi the Harmonious has asked us to collect " ..
                "some crystals and bring them back to the city.\n\nKeep an eye out for them while you are " ..
                "in the ruins.",
            rewardMoney = 114000,
        },
        [30638] = {
            description = "This is serious.\n\nKun and I will keep an eye on things here, but you should " ..
                "go to the Golden Pagoda.\n\nGo, swiftly!",
            rewardMoney = 57000,
        },
        [30640] = {
            description = "I have received some troubling news, <name>.\n\nThe mogu are plotting to steal " ..
                "three artifacts of power from the Vale.\n\nWe must retrieve the artifacts immediately " ..
                "and hide them for safekeeping.\n\nThe first artifact is the Battle Spear of the Thunder " ..
                "King.\n\nUpon emperor Lei Shen's death, the spear was placed in an ancient shrine to the " ..
                "northwest.\n\nBring the spear back to me.",
            rewardMoney = 114000,
        },
        [30641] = {
            description = "The second artifact of power is the Battle Helm of the Thunder " ..
                "King.\n\nEmperor Lei Shen wore the helm into every battle. It became so well-known that " ..
                "his enemies would flee at the mere sight of it.\n\nWhen the Emperor died, they placed " ..
                "the helm in the very bottom of the Guo-Lai Halls to the west, surrounded by thousands of " ..
                "terracotta soldiers.\n\nThus, they could look upon their leader and follow him into " ..
                "death.",
            rewardMoney = 114000,
        },
        [30642] = {
            description = "The final artifact is the Thunder King's axe.\n\nLei Shen charged into battle " ..
                "with his spear in one hand, and his axe in the other.\n\nIt is said that he could throw " ..
                "his axe with brutal accuracy, and when it hit its target, it made a sound like crashing " ..
                "thunder.\n\nAfter his death, the axe was placed in a ceremonial chamber to the " ..
                "southwest.\n\nNeedless to say, we must not let it fall into the mogu's hands.",
            rewardChoices = {
                {90597, 1}, {90598, 1}, {90599, 1}, {90600, 1}, {90601, 1}, {90602, 1}, {90603, 1},
                {90607, 1}, {90609, 1},
            },
            rewardMoney = 114000,
        },
        [30643] = {
            description = "The battle against the mogu rages fiercely with neither side giving " ..
                "quarter.\n\nWe cannot hold our position forever. Something must be done to strike a blow " ..
                "at the mogu, a blow from which they cannot recover.\n\nGo check in with Zhi the " ..
                "Harmonious at The Silent Sanctuary. I wish to hear his thoughts on this matter.",
            rewardMoney = 57000,
        },
        [30649] = {
            description = "Look at this creature, traveler. Only moments after we arrived, this mogu " ..
                "assassin attacked with no warning.\n\nHis blade was intended for the leader of the " ..
                "Golden Lotus. It is very lucky indeed that we were here to stop the attack.\n\nSeeing " ..
                "this attempt on Zhi's life, I fear for the safety of those who have already entered the " ..
                "valley.\n\nThe caretakers are settling your people into the city to the northeast. Go " ..
                "and speak to the leaders. Make sure they are safe.",
            rewardMoney = 102000,
        },
        [30650] = {
            description = "Look, I know the Alliance needs recruits, and there's just not enough of us " ..
                "here right now to make a fighting presence of this town.\n\nBut I know that the yaungol " ..
                "over at Fire Camp Ordo, to the northwest, have taken many of my people as prisoners. And " ..
                "I also know that if you would be willing to rescue them from their captivity, they'd " ..
                "more than likely be willing to join the Alliance.\n\nWhat do you say, <name>?",
            rewardMoney = 102000,
        },
        [30651] = {
            description = "Oh, well now, let's have us some fun, <boyo/girly>!\n\nThose Ordo yaungol to " ..
                "the northwest have saved us the trouble o' havin' to make some bombs. They already have " ..
                "them there.\n\nLet's put their explosive barrels to good use and destroy their " ..
                "oil-pumpin' machines, shall we?",
            rewardItems = {{88577, 1}},
            rewardMoney = 102000,
        },
        [30652] = {
            description = "The yaungol of Fire Camp Ordo are a dire threat. I need you to head northwest " ..
                "and take out their leader.\n\nUnfortunately, his four subordinates are maintaining a " ..
                "fire barrier that prevents us from getting to him in the adjoining cave.\n\nTake them " ..
                "out and the shield will come down. You'll find them in their tents, channeling.",
        },
        [30653] = {
            description = "I been thinkin'.\n\nWe got all this beer that Chen brewed, and we got all " ..
                "these people that you've gathered. We should bring the two together.\n\nThere's a bunch " ..
                "o' folks out there in the fields, riskin' their lives for Pandaria. You an' I should at " ..
                "least bring 'em a keg or two.\n\nThey might raise their mugs in victory. They might " ..
                "enjoy one last drink before gettin' skivvered by a mantid. Either way, I wouldn't want " ..
                "'em to fight without a good brew in their belly.",
        },
        [30654] = {
            description = "The mogu are up to something, I can feel it.\n\nThey've been sending scouts " ..
                "down into the Guo-Lai Halls.\n\nAccording to the caretakers, the Halls are home to " ..
                "ancient treasures of emperors past. Not only riches, but artifacts of great power.\n\nWe " ..
                "must prevent the mogu from accessing these treasures! Go down the ramp to the northwest " ..
                "and stop them!",
            rewardMoney = 228000,
            startedBy = {{58465}},
        },
        [30655] = {
            description = "Look, I know the Horde needs recruits, and there's just not enough of us here " ..
                "right now to make a fighting presence of this town.\n\nBut I know that the yaungol over " ..
                "at Fire Camp Ordo, to the west, have taken many of my people as prisoners. And I also " ..
                "know that if you would be willing to rescue them from their captivity, they'd more than " ..
                "likely be willing to join the Horde.\n\nWhat do you say, <name>?",
            rewardMoney = 102000,
        },
        [30656] = {
            description = "I love blowing stuff up. It's in my blood!\n\nThe yaungol to the west at Fire " ..
                "Camp Ordo have a ton of explosive barrels just lying around.\n\nI say we put them to " ..
                "good use and destroy their oil-pumpin' machines while having some fun!",
            rewardItems = {{88577, 1}},
            rewardMoney = 102000,
        },
        [30657] = {
            description = "The yaungol of Fire Camp Ordo are the worst threat we're facing. I need you to " ..
                "head west and take out their leader.\n\nThe coward is hiding in a cave, which is " ..
                "protected by a fire shield cast by his four underlings.\n\nTake them out and the shield " ..
                "will come down. You'll find them in their tents, channeling.",
        },
        [30658] = {
            description = "Have you heard of the prickly puffer fish <name>? Of course you haven't, " ..
                "you're new around these parts!\n\nThey can be found in the sarjun depths, due west of " ..
                "here. Take this fishing spear and see if you can bring me back of few of their poison " ..
                "tipped spines.",
            rewardMoney = 114000,
        },
        [30660] = {
            description = "<The shield is down. Time to head into the cave and slay the Warbringer of the " ..
                "Ordo yaungol!>",
            rewardChoices = {
                {82589, 1}, {82590, 1}, {82591, 1}, {82592, 1}, {82593, 1}, {82594, 1}, {82595, 1},
                {82596, 1}, {82597, 1}, {82598, 1},
            },
            rewardMoney = 306000,
        },
        [30661] = {
            description = "<The shield is down. Time to head into the cave and slay the Warbringer of the " ..
                "Ordo!>",
            rewardChoices = {
                {82589, 1}, {82590, 1}, {82591, 1}, {82592, 1}, {82593, 1}, {82594, 1}, {82595, 1},
                {82596, 1}, {82597, 1}, {82598, 1},
            },
            rewardMoney = 306000,
        },
        [30662] = {
            description = "You've taken the shield down at Fire Camp Ordo. Go back there before the " ..
                "shield goes up again.\n\nTime to head into the cave and slay their chief!",
            rewardChoices = {
                {82589, 1}, {82590, 1}, {82591, 1}, {82592, 1}, {82593, 1}, {82594, 1}, {82595, 1},
                {82596, 1}, {82597, 1}, {82598, 1},
            },
            rewardMoney = 306000,
        },
        [30665] = {
            description = "I sent for reinforcements from the Shado-Pan Monastery, but have heard nothing " ..
                "back. We have already lost the town.\n\nA few lucky villagers may have survived, but we " ..
                "are pinned down here.\n\nWe do not have time to entertain strangers. If you can fight, " ..
                "help my men defend this tower. If not, leave, for you will not survive long here.",
            rewardMoney = 102000,
        },
        [30666] = {
            description = "Normally, my day consists of catching fish, and then eating the fish I caught, " ..
                "followed by sleeping. Note that I did not include \"fight with a crocolisk\" in that " ..
                "list of activities.\n\nYou look like a handy <class>. Can you go get rid of some of " ..
                "these crocolisks, so I can get back to my regular routine? The crocolisks normally keep " ..
                "to themselves up at Kea Krak, to the northwest.",
            rewardMoney = 102000,
        },
        [30667] = {
            description = "When the crocs started attacking, they scared a bunch of the lories out of " ..
                "their nests, up in that island to our northwest.\n\nI can use those lories' feathers to " ..
                "make some specialized lures, which will come in handy if and when I get to stop " ..
                "defending my brethren from these reptiles.\n\nYou up for some feather hunting?",
            rewardMoney = 102000,
        },
        [30668] = {
            description = "<Jay looks off in the direction of Kea Krak.>\n\nHmm. They don't seem to be... " ..
                "calming down. We're going to have to try something different.\n\nYou'll need a raft. Go " ..
                "grab some wood planks and seaweed, and bring them over to me. I'll put something " ..
                "together for you.",
            rewardMoney = 10200,
        },
        [30669] = {
            description = "Your raft is down in the water below. Take it out to the middle of the lake, " ..
                "where you should find a woman. Her name is Ana Wu.\n\nWhenever I have a question that I " ..
                "can't figure out on my own, I'll ask her. She should be able to tell us why these " ..
                "crocolisks won't stop attacking.",
            rewardMoney = 10200,
        },
        [30670] = {
            description = "Our true enemies are the sha, not the yungol.\n\nThe sha are emotion manifest. " ..
                "Destructive, yes. But undisciplined. Undisciplined force cannot last. The flood, in " ..
                "dispersion, loses its force. The wildfire burns its fuel.\n\nAnd, discipline and wisdom " ..
                "can turn their destructive energy against themselves.\n\nBring me the essences of the " ..
                "sha in the village, and I will explain further.",
            rewardMoney = 102000,
        },
        [30671] = {
            description = "<Ana listens to your story, and nods.>\n\nCrocolisks attacking? I know a story " ..
                "about that. And I will share it with you, but first... I grow hungry.\n\nShark meat " ..
                "should do the trick. You should find enough sharks in the water beneath us.",
            rewardChoices = {
                {88035, 1}, {88036, 1}, {88037, 1}, {88038, 1}, {88039, 1}, {88040, 1}, {88041, 1},
                {88042, 1}, {88043, 1},
            },
            rewardMoney = 102000,
        },
        [30672] = {
            description = "The story did not end happily. The Narsong crocolisk is no more.\n\nThis time, " ..
                "however, you may have a chance to change the ending.\n\nThe hozen to the south are " ..
                "overfishing these waters. With the fish gone, the crocolisks are hungry and desperate - " ..
                "and so they attack Marista.\n\nGo now, <race>! Stop those hozen from their reckless " ..
                "fishing!",
            rewardChoices = {
                {81542, 1}, {81543, 1}, {81544, 1}, {81545, 1}, {81546, 1}, {81547, 1}, {81548, 1},
                {81549, 1}, {81550, 1}, {81551, 1},
            },
            rewardMoney = 204000,
        },
        [30674] = {
            description = "Some of the fish that the Unga hozen have gathered don't seem do be dead yet. " ..
                "There may still be time to throw them back into the water.",
        },
        [30675] = {
            description = "The map you hold is crinkled, dirty, and poorly drawn, but you can see a big X " ..
                "on a beach.\n\nIs there buried treasure somewhere on this island?",
            rewardMoney = 102000,
        },
        [30678] = {
            description = "Turns out these rays are not as easy to catch as I thought! You seem like a " ..
                "pretty smart guy, think you can help me out?\n\nI made the bombs but have been having " ..
                "trouble using the raft with my hurt leg. The rays are common in the shallows just west " ..
                "of here. Take the bombs and use my raft to bring me back their stingers!\n\nOh yeah, " ..
                "watch out for the hammerheads!",
            rewardMoney = 114000,
        },
        [30682] = {
            description = "I can't believe you made it here!\n\nI don't know how much longer I could have " ..
                "stayed hidden in here.\n\nI'm sure that there are others. <class>, we have to rescue " ..
                "them! Then we can go to Shado-Pan Fallback. The master there will know what to do!",
            rewardItems = {{88579, 1}},
            rewardMoney = 102000,
        },
        [30683] = {
            description = "Did you have to throw our supplies at them?! Why not use your weapon? Maybe " ..
                "fancy spells or kicks? Why the supplies?!\n\nNow we don't have enough to last us, " ..
                "especially with Nephew Bentnail here. His appetite is like a yeti's!\n\nYou threw it, " ..
                "you get us more. There is wreckage down the path. Maybe you will find supplies there.",
            rewardChoices = {
                {82505, 1}, {82506, 1}, {82507, 1}, {82508, 1}, {82509, 1}, {82510, 1}, {82511, 1},
                {82512, 1}, {82513, 1},
            },
            rewardMoney = 106000,
        },
        [30690] = {
            description = "Simply killing Kobai will accomplish nothing, as he is possessed by a " ..
                "particularly powerful and destructive Sha - Malevolent Fury.\n\nYou will use the trap I " ..
                "have fashioned from the Blinding Rage Essences you brought. Lure him into the trap, and " ..
                "then steal his mask. Once you put it on, Malevolent Fury will appear and attempt to take " ..
                "control of you.\n\nDefeat him, and we will have made a victory of this tragic situation. " ..
                "You can find him to the north of the retreat, where he taunts us in insane rage.",
            rewardChoices = {
                {88071, 1}, {88072, 1}, {88073, 1}, {88074, 1}, {88075, 1}, {88076, 1}, {88077, 1},
                {88078, 1}, {88079, 1},
            },
            rewardMoney = 204000,
        },
        [30691] = {
            description = "While you are in the water below, you should slay Nahassa, the mortbreath " ..
                "patriarch. He suffers. I can feel his death cries ululating up to the surface of the " ..
                "lagoon.\n\nFind his cave, and put him out of his misery. Not because it will solve " ..
                "Marista's crocolisk problem. Simply out of mercy.",
        },
        [30694] = {
            description = "My students tell me the surrounding area is littered with deadly traps, no " ..
                "doubt set by the saurok. Stumbling into one gets you a face full of spikes.\n\nAs the " ..
                "saying goes: \"The Way is rife with danger - tread lightly, and with " ..
                "scrutiny.\"\n\n<Koro hands you a long tree branch.>\n\nHere, this is scrutiny.\n\nIt " ..
                "should be long enough to set the traps off at a safe distance.",
            rewardChoices = {
                {84272, 1}, {84273, 1}, {84274, 1}, {84275, 1}, {84276, 1}, {84277, 1}, {84278, 1},
                {84279, 1}, {84280, 1},
            },
            rewardMoney = 102000,
        },
        [30695] = {
            description = "Huge maws of despair are spewing out sha from the pagodas on either side of " ..
                "the temple. Meanwhile, your impromptu training in the Way continues.\n\n\"She who mends " ..
                "torn umbrella will be more dry than she who strikes at rain.\"\n\nWhile I take issue " ..
                "with that particular lesson--sometimes punching the rain can be quite effective--the " ..
                "meaning holds true in this case.\n\nTake out those maws of despair and give my order a " ..
                "chance at reclaiming the temple grounds.",
            rewardChoices = {
                {81552, 1}, {81553, 1}, {81554, 1}, {81555, 1}, {81556, 1}, {81557, 1}, {90546, 1},
                {90547, 1}, {90622, 1},
            },
            rewardMoney = 102000,
        },
        [30698] = {
            description = "YOU! You're just who I have been looking for!\n\nI need more parts for my " ..
                "goblin fishing bombs but I hurt my leg and can't collect them myself.\n\nYou see those " ..
                "shipwrecks nearby? I bet they have just what I need if you can get to it and fish it " ..
                "out. Take my fishing raft and see what you can find! My buddy has been trying to help me " ..
                "out too so you might find some extra rafts near the wreckage, feel free to use em' too.",
            rewardMoney = 114000,
        },
        [30700] = {
            description = "A giant, poisonous crab is wrecking havoc on our local abalone stores. I need " ..
                "you to go down into narsong trench and take it out!",
            rewardMoney = 114000,
        },
        [30701] = {
            description = "Nothing tastes quite like viseclaw soup. It's a krasarang specialty!\n\nI was " ..
                "just about to start up on a new batch when I realized I am missing a key ingredient, the " ..
                "eyes!\n\nI need you to kill the viseclaw fishers on the beach and return with their eyes " ..
                "for the soup!",
            rewardMoney = 114000,
        },
        [30714] = {
            description = "And, now they fear you.\n\nTheir leaders, a Blademaster and a Mage, lie deeper " ..
                "in the ruins. Kill them. Make them hurt. For us.",
            rewardMoney = 102000,
        },
        [30715] = {
            description = "When we regrouped after their initial attack, we numbered three less. You can " ..
                "fight, and we must plan our defense should these cursed yaungol attack again.\n\nIf you " ..
                "would help us, grant our fallen comrades their last rites, and recover their armor. You " ..
                "will find their bodies to the west, near the gate.\n\nAnd try to keep the birds off them.",
            rewardMoney = 106000,
        },
        [30716] = {
            description = "Chi-Ji is always with us. Even when he is not here in the Cradle, pieces of " ..
                "his spirit run through the forests and beaches of the island, watching us and testing " ..
                "us.\n\nProve your dexterity in the eyes of Chi-Ji, <name>. Find and catch the spirits of " ..
                "the crane.",
            rewardMoney = 114000,
        },
        [30717] = {
            description = "The cranes of Krasarang are a gift from Chi-Ji. Even the very feathers they " ..
                "leave behind are a gift for us to appreciate.\n\nWe use these feathers to adorn our " ..
                "garments and to fletch arrows. But first... they must be gathered.",
            rewardMoney = 114000,
        },
        [30718] = {
            description = "Our order prides itself on excellence in combat. We hone these combat skills " ..
                "by dueling one another, here on the Cradle of Chi-Ji.\n\nProve yourself in the eyes of " ..
                "the Red Crane. Venture south, into the center of the island, and duel with your fellow " ..
                "students.",
            rewardMoney = 114000,
        },
        [30723] = {
            description = "Hmm... If Shado-Master Chong trusted you, perhaps you can help us.\n\nThe " ..
                "yaungol are our enemies.\n\nStill, we must prove we are better than they. We will show " ..
                "them honor in death.\n\nAs after most battles, the carrion birds have begun gathering. " ..
                "Thin their numbers, so the bodies of our foes will not be desecrated. They've gathered " ..
                "at the battlefield to the west.",
            rewardMoney = 106000,
        },
        [30724] = {
            description = "They are attacking again!\n\n<Lin looks to the Ox Gate.>\n\nArchers... on the " ..
                "wall!\n\nI need you to get up there. My wife Suna went to scout the wall with that fool " ..
                "Lao-Chen. Perhaps if he had spent more time preparing defenses and less building that " ..
                "ridiculous ale lift contraption...\n\nIt matters not. Get a kite from Len, to the west, " ..
                "and then get up there and find my wife. She'll know what to do next.",
            rewardMoney = 10600,
        },
        [30725] = {
            description = "We regularly organize one-on-one duels with trainees that we think are " ..
                "well-suited for one another. We have found one such trainee for you, <name>.\n\nHer name " ..
                "is Ellia Ravenmane. This will be her first duel, too. She will be waiting for you at the " ..
                "pavilion just to the south of here.",
            rewardMoney = 228000,
        },
        [30726] = {
            description = "Your next challenger is another relatively new trainee. His name is Minh " ..
                "Do-Tan, and he has won his last two matches.\n\nHe will be waiting for you near the " ..
                "crane statue to the south.",
            rewardMoney = 228000,
        },
        [30727] = {
            description = "Ellia Ravenmane requested a rematch with you. She seems to identify you as her " ..
                "\"rival\".\n\nWe discourage rivalries here within the Cradle of Chi-Ji, but we rarely " ..
                "decline a rematch request. You will find Ellia near the Pedestal of Hope, on the " ..
                "island's eastern side.",
            rewardMoney = 228000,
        },
        [30728] = {
            description = "You have been matched with a... special trainee. His name is Fat " ..
                "Long-Fat.\n\n< Thelonius chooses his words carefully.>\n\nFat Long-Fat... operates " ..
                "outside of the normal rules of combat. He does not fight every day, and when he does, he " ..
                "chooses his competitor. Today, for some reason... he has selected you.\n\nYou will find " ..
                "him atop Angkhal Pavilion.",
            rewardMoney = 228000,
        },
        [30729] = {
            description = "We welcome all kinds here within the Cradle, as long as they recognize and " ..
                "subscribe to the ideologies of the Red Crane. One of our new, more exotic trainees comes " ..
                "from the human kingdoms to the northeast. She goes by the rather foreign-sounding name " ..
                "of Julia Bates.\n\nShe is your next challenger. You will find her on the island's " ..
                "western shore.",
            rewardMoney = 228000,
        },
        [30730] = {
            description = "Jinyu normally avoid our order, but every few years, we find one that " ..
                "subscribes to the way of the Crane. One such jinyu is Dextrous Izissha.\n\nIzissha is " ..
                "your next challenger. He waits for you on the island's southwestern shore.",
            rewardMoney = 228000,
        },
        [30731] = {
            description = "Most of the duels within the Cradle take place between two trainees. Rarely, " ..
                "when a trainee exhibits a rare amount of skill, they will have an opportunity to duel " ..
                "their trainer.\n\nToday, you duel against Kuo-Na. She will be waiting for you at the " ..
                "Pedestal of Hope.",
            rewardMoney = 228000,
        },
        [30732] = {
            description = "Your \"rival\" has appeared again. Ellia Ravenmane has been avoiding her " ..
                "duties on the island, instead focusing on personal training, with the intent to defeat " ..
                "you in battle.\n\n\"I will destroy <name>,\" she said.\n\nI have honored her request for " ..
                "a rematch, but I will be keeping a close eye on her. Her motives may be shifting in a " ..
                "dangerous direction.",
            rewardMoney = 228000,
        },
        [30733] = {
            description = "You are making a name for yourself, <name>. I received a challenge from one of " ..
                "our more skilled competitors. He believes you are not as strong as you seem.\n\nHis name " ..
                "is Tukka-Tuk, the hozen. If you've ever fought against hozen before, you know that their " ..
                "apparent juvenility belies their battle acumen. Good luck.",
            rewardMoney = 228000,
        },
        [30734] = {
            description = "Usually our trainees are adventurers like yourself, or monks from Tian " ..
                "Monastery, or occasionally retired Shado-Pan. Very rarely, though, we will greet " ..
                "trainees that have no fighting experience whatsoever.\n\nHuck Wheelbarrow is one such " ..
                "trainee. He has requested a duel with you. Look for him on the island's western shore.",
            rewardMoney = 228000,
        },
        [30735] = {
            description = "Our highest-ranked trainee is an outsider like you. It is both strange and " ..
                "exciting to live in a time when so many foreigners have embraced the way of the " ..
                "Crane.\n\nYour challenger's name is Mindel Sunspeaker, and he awaits you within Angkhal " ..
                "Pavilion.",
            rewardMoney = 228000,
        },
        [30736] = {
            description = "You have already defeated Kuo-Na Quillpaw. You have not yet fought her " ..
                "brother, Yan.\n\nHe will meet you at the Pedestal of Hope, and he will not hold back. " ..
                "His reputation as a trainer is at stake.",
            rewardMoney = 228000,
        },
        [30737] = {
            description = "Fat Long-Fat has requested another match with you. I find this strange. And " ..
                "concerning.\n\nHe will be waiting atop the Dome Belrissa.",
            rewardMoney = 228000,
        },
        [30738] = {
            description = "When we last spoke, I promised to tell you the secret of Fat Long-Fat. I still " ..
                "plan to tell you that secret... after I determine your worth.\n\nI will meet you on the " ..
                "western shore, and we will duel.",
            rewardMoney = 228000,
        },
        [30739] = {
            description = "Ellia Ravenmane, your rival, has returned. She demands that you meet her atop " ..
                "the Pedestal of Hope.\n\nYou need to understand, <name>... something horrible has " ..
                "happened to her. She has changed. You will see for yourself when you arrive at the " ..
                "pedestal.\n\nGood luck, <name>.",
            rewardMoney = 228000,
        },
        [30740] = {
            description = "While you will always hold a place of honor among our order, you are still " ..
                "welcome to participate in our duels.\n\nOne of our current champions awaits you in the " ..
                "Dome Balrissa. I know that they would be honored to duel with you.",
            rewardMoney = 228000,
        },
        [30742] = {
            description = "I mussed up. Bad.\n\nIt's hard work cutting seeds out of kafa berries! But I " ..
                "noticed goots eat the berries up and give back the seeds... in a day or so.\n\nI fed " ..
                "everything I had to the goots on Kota Peak and now they're nuts! Chargin' everything " ..
                "that moves.\n\nKota used to be safe for Grummles to gather kafa. Not anymore. Not with " ..
                "them goots. Will you help?",
            rewardMoney = 106000,
        },
        [30743] = {
            description = "It was genius: kafa berries go in the goot, seeds come out.\n\nKafa'kota is " ..
                "already rare and worth a fortune, but my invention--Kafa'goot--is GOURMET.\n\nBut its " ..
                "over now. Uncle is upset and peak is a muss. All thats left is to collect the rest of " ..
                "the Kafa'goot and never make it again.\n\nI won't ask you to gather it--kind of a mussy " ..
                "task, not fit for hero-- just mark it so I can find it easily when the mountain is safe " ..
                "again.",
            rewardItems = {{88382, 1}},
            rewardMoney = 106000,
        },
        [30744] = {
            description = "Kota Peak is famous for its kafa bushes - no other can survive at this " ..
                "elevation.\n\nGrummles make very good living selling Kafa'kota Blend, but it's dangerous " ..
                "now thanks to my cousin here. He's got the wildlife up there hooked on kafa with his " ..
                "scheming.\n\nKafa'kota is more scarce than ever with goots gobblin' it up and yetis " ..
                "hoarding it in their caves.\n\nI pay you good for any berries you bring down from " ..
                "Kota.\n\nHere, take a sample. Eat it. See for yourself the power of kafa.",
        },
        [30746] = {
            description = "<The roar bellows out again, louder and more fierce than any of the yetis " ..
                "you've encountered so far. Again, a grummle voice replies...>\n\nEep! Please, great Kota " ..
                "Kon, forgive grummle. Let me go, I'll bring lots of kafa right away! Promise!\n\n<The " ..
                "beast called Kota Kon answers with another meaty roar.>",
            rewardMoney = 106000,
        },
        [30750] = {
            description = "The yaungol on the wall here are providing covering fire for the ones below. I " ..
                "don't know what Lao-chen is thinking, but I want you to deal with these archers.\n\nThe " ..
                "good news is, up here we've got the spirit of the Ox helping us. When they're weakened, " ..
                "the ox spirit will stun them and you can use it to knock 'em off the wall.\n\nYou'll " ..
                "find the archers just out that door.",
            rewardMoney = 106000,
        },
        [30751] = {
            description = "I have an idea, and... am prepared to make a terrible sacrifice.\n\nAs much as " ..
                "I know that we need my stout brew, to fortify our defenders for the long-term security " ..
                "of the Ox Gate...\n\nIt is too painful to discuss details now, but please - while you " ..
                "are up here defending the wall, gather the barrels of oil they are using to light their " ..
                "arrows. We will need them.",
            rewardMoney = 106000,
        },
        [30753] = {
            description = "There is only one way to kill sharks where I come from, with your bare " ..
                "hands!\n\nI dumped a good amount of chum in the water just off the dock here, this place " ..
                "should be crawling with the local reef sharks in no time. Hop on the first one you see " ..
                "and take it out!",
            rewardMoney = 114000,
        },
        [30754] = {
            description = "Certain fish are only attracted to bright lights. The forest north of here is " ..
                "home to a local pandaren firefly called a suncrawler.\n\nYou should be able to find them " ..
                "on the base of the tree trunks all around that area. Bring me back a handful of them and " ..
                "I can use them for bait!",
            rewardMoney = 114000,
        },
        [30757] = {
            description = "Our lord, Taran Zhu, has been overcome by a sha of pure hatred. The whole " ..
                "monastery has been lost!\n\n<class>, you must find a way to free him of this possession. " ..
                "Last I knew, he was meditating in the Grove of Falling Blossoms.",
            rewardChoices = {
                {87315, 1}, {87316, 1}, {87317, 1}, {87318, 1}, {87319, 1}, {87320, 1}, {87321, 1},
                {87322, 1}, {87323, 1},
            },
            rewardMoney = 440000,
        },
        [30763] = {
            description = "Certain fish are very difficult to catch. The wolf piranha falls squarely into " ..
                "this category.\n\nLucky for me that you showed up! Put those fishing skills to the test " ..
                "and bring me back a few from the krasarang river due northwest of here.",
            rewardMoney = 114000,
        },
        [30766] = {
            description = "<A relic drops off of the statue. Hmm, these could prove to be valuable to the " ..
                "right person.>\n\n<There's a collector on the outskirts of the ruins. Perhaps he'd be " ..
                "interested in purchasing them from you?>",
            rewardMoney = 102000,
        },
        [30768] = {
            description = "Lin...\n\nI don't care what Ban, Lao-Chin, or even Taran Zhu says. I'm moving " ..
                "ahead into Townlong. I may not be able to save Lin myself, but I'm not going to sit " ..
                "around waiting for everyone else to catch up.\n\nOnce Taran Zhu opens the doors to his " ..
                "precious monastery, we'll save Lin. Until then, I'll scout ahead and make sure he's " ..
                "alright.",
            rewardMoney = 55000,
        },
        [30769] = {
            description = "Now that we have had time to assess our enemies' weaknesses, it is time for us " ..
                "to deal the yaungol a direct blow.\n\nGo and confront the Osul Sharphorn up the mesa to " ..
                "the west.\n\nLet them know that we are here, and that we are not scared of their threats.",
            rewardChoices = {
                {88087, 1}, {88088, 1}, {88089, 1}, {88090, 1}, {88091, 1}, {88092, 1}, {88093, 1},
                {88094, 1}, {88095, 1},
            },
            rewardMoney = 110000,
        },
        [30770] = {
            description = "There is one thing that every army needs, and that is a supply line.\n\nThe " ..
                "enemy camp to the west contains a large beast herd, which serves as the yaungol army's " ..
                "main source of food.\n\nLuckily for us, the yaks and mushan beasts of this region are " ..
                "easily scared.\n\nSneak in, give the beasts a good slap, and watch the results.",
            rewardMoney = 110000,
        },
        [30771] = {
            description = "When the Osul tribe goes to war, they coat their spears and arrows with a " ..
                "highly flammable, ever-burning pitch.\n\nThey use this terrible weapon to shed not only " ..
                "blood, but to raze the homes of their enemies.\n\nI need you to collect some of this " ..
                "pitch while you are in their camp.\n\nWe will use it to show the yaungol that when you " ..
                "play with fire, you can get burned.",
            rewardMoney = 110000,
        },
        [30772] = {
            description = "Ahead of us is the main thrust of the yaungol army.\n\nHere, they prepare " ..
                "their vast army to attack the villages of Kun-Lai.\n\nIf we strike at the Osul now, we " ..
                "can cut them at their very core.\n\nRemember, for every of their number that we strike " ..
                "down here, we save one of our own back at home.",
            rewardChoices = {
                {83671, 1}, {83672, 1}, {83673, 1}, {83674, 1}, {83675, 1}, {83676, 1}, {83677, 1},
                {83678, 1}, {83679, 1},
            },
            rewardMoney = 110000,
        },
        [30773] = {
            description = "The yaungol's siege weapons - those ballista spearthrowers down there - are " ..
                "tearing apart our defenses both at Longying Oupost and in Kun-Lai Summit.\n\nThose " ..
                "terrible weapons must be destroyed.\n\nTake these explosives. I've covered them in the " ..
                "pitch that you collected.\n\nToss them at those ballistas, and we'll give the yaungol a " ..
                "little taste of their own medicine.",
            rewardItems = {{88583, 1}},
            rewardMoney = 110000,
        },
        [30774] = {
            description = "I must ask a most important task of you, <name>.\n\nSomewhere among the cages " ..
                "in the Osul camp is my husband, Lin. He is the light of my world.\n\nPlease find him and " ..
                "return him to me, and save as many of our fellow Shado-Pan as you can as well.\n\nYou " ..
                "should find keys to those cages on the Osul Marauders.",
            rewardMoney = 110000,
        },
        [30775] = {
            description = "What is there to say, stranger?\n\nI fought Jung Duk and lost. I was the fool " ..
                "to believe he would fight fairly.\n\nNow, my own brothers turned against me, and here I " ..
                "am, speaking to our enemies.\n\nI know you have come for Osul blood.\n\nI only ask that " ..
                "you hunt down the three who betrayed me.\n\nUrang, who poisoned my drink. Ku-Tong, who " ..
                "bent my spear. And Battat, whose dagger slipped into my side as my victory was " ..
                "assured.\n\nDo this, and I can die in peace.",
            rewardMoney = 110000,
        },
        [30776] = {
            description = "THIS. IS. WAR.\n\nI will have the heads of everyone who took Lin from me. " ..
                "EVERYONE!\n\nWe will begin with the Osul leader, Jung Duk.\n\nTake this Shado-Pan war " ..
                "banner and place it at the center of their camp.\n\nJung Duk will have no choice but to " ..
                "face you.\n\nShow him no mercy, <name>.",
            rewardChoices = {
                {83689, 1}, {83690, 1}, {83691, 1}, {83692, 1}, {83693, 1}, {83694, 1}, {83695, 1},
                {83696, 1}, {83697, 1},
            },
            rewardMoney = 220000,
        },
        [30777] = {
            description = "I have bad news. When I returned, Suna was already gone.\n\nThe others say " ..
                "that she took her things and headed down the road to the east, muttering about hunting " ..
                "down the source of the yaungol aggression.\n\nI cannot allow her to venture into " ..
                "dangerous territory alone.\n\nI've already prepared a group of soldiers to push further " ..
                "east.\n\nWe are leaving shortly. Hop on the caravan if you wish to travel with the " ..
                "Shado-Pan. You can also meet us there if you wish.",
            rewardMoney = 55000,
        },
        [30778] = {
            description = "If we are to make camp here, we cannot leave all of these yaungol bodies lying " ..
                "to rot.\n\nTake this torch and set fire to the villagers' corpses.\n\nThe incense from " ..
                "the torch should purify the earth and air around them as well.\n\nEven our enemies " ..
                "deserve to be laid to rest.",
            rewardMoney = 110000,
        },
        [30779] = {
            description = "The rotting corpses are attracting hyena scavengers.\n\nIn addition to " ..
                "spreading diseases from feeding on the dead, the feral creatures will attack us on " ..
                "sight.\n\nGo and eradicate the beasts. It is unfortunate, but ultimately for the best.",
            rewardMoney = 110000,
        },
        [30780] = {
            description = "As we entered the village, I couldn't help but notice yaungol totems lying " ..
                "around this camp.\n\nI have a suspicion that there are dark forces at work here, and " ..
                "those totems may be the key to drawing them out.\n\nCould you bring me some of these " ..
                "totems for further inspection? I would like to study them.",
            rewardMoney = 110000,
        },
        [30781] = {
            description = "Ban has asked me to explore the village to determine what happened here.\n\nI " ..
                "noticed smoke rising up from the east, the west, northwest, and the south.\n\nI need " ..
                "someone I trust to watch my back.\n\nWhat do you say? Want to help me on my first " ..
                "scouting mission?",
            rewardChoices = {
                {83746, 1}, {83747, 1}, {83748, 1}, {83749, 1}, {83750, 1}, {83751, 1}, {83752, 1},
                {83753, 1}, {83754, 1}, {83755, 1},
            },
            rewardMoney = 110000,
        },
        [30782] = {
            description = "The spirits of the fallen villagers have risen! I can feel the hatred " ..
                "emanating from the spirits.\n\n<name>, if we are to survive here, we must defend " ..
                "ourselves. This is the only way we can put them to rest.",
            rewardMoney = 110000,
        },
        [30783] = {
            description = "I should have suspected a sha presence earlier!\n\nWe are safe as long as we " ..
                "stand inside the Totem of Harmony 's protective wards, but many of our people were not " ..
                "so lucky.\n\nThey were trapped outside the camp when the sha's powers manifested, and " ..
                "now they turn upon each other!\n\nTake one of my totems with you. Place the totem near a " ..
                "crazed ally to purify them, but beware.\n\nYou may have to face the darkness that " ..
                "gripped them.",
            rewardItems = {{88584, 1}},
            rewardMoney = 110000,
        },
        [30784] = {
            description = "One of our rangers reported seeing Suna up the hill to the northwest.\n\nI am " ..
                "relieved to find her safe. I had feared what she would do in her grief.\n\nWould you go " ..
                "speak to her on my behalf?\n\nTake this totem with you. If you encounter any danger " ..
                "along the way, you may find it useful.",
            rewardChoices = {
                {83662, 1}, {83663, 1}, {83664, 1}, {83665, 1}, {83666, 1}, {83667, 1}, {83668, 1},
                {83669, 1}, {83670, 1},
            },
            rewardMoney = 110000,
        },
        [30785] = {
            description = "With your help, we have quelled the spirits of this place.\n\nAt last, they " ..
                "may rest in peace.\n\nOur journey into this cursed land, I am afraid, has only " ..
                "begun.\n\nI have some important matters to finish up here, but we will be moving out " ..
                "soon.\n\nI need someone to go ahead and tell Lord Taran Zhu that we are joining " ..
                "him.\n\nFind him at the Gao-Ran Battlefront. Tell him what has transpired here.",
            rewardMoney = 55000,
        },
        [30786] = {
            description = "My fate is sealed. The yaungol put this spear in my side. The wound will kill " ..
                "me.\n\nThe yaungol hold me in place with their twisted, corrupted magic. The indignity " ..
                "of it hurts worse than my spear-wound.\n\nMy death, I cannot stop. My imprisonment... " ..
                "you may be able to help me with this.",
            rewardMoney = 110000,
        },
        [30787] = {
            description = "Until recently, the yaungol shaman would come here to work alongside us. Now, " ..
                "they bend my people to their will.\n\nIf we refuse, they kill us. Even if we oblige... " ..
                "they kill us.\n\nThe yaungol mist-shaman's magic flows through his torch. Take his torch " ..
                "away, and he has nothing.",
            rewardChoices = {{84605, 1}, {84606, 1}, {84607, 1}, {84608, 1}, {84609, 1}},
            rewardMoney = 110000,
        },
        [30788] = {
            description = "The leader of the yaungol mist-shaman is named Jahesh. He is known for his " ..
                "strength.\n\nOne of my kind is also known for his strength. His name is " ..
                "Golgoss.\n\nGolgoss sleeps within the mists of the Upper Sumprushes. Help me to summon " ..
                "him, and he will join me in avenging our people.",
            rewardMoney = 110000,
        },
        [30789] = {
            description = "If I am to fight Jahesh, leader of the yaungol mist-shaman, I must have " ..
                "Arconiss by my side. Arconiss ' ferocity is second to none.\n\nHe rests beneath the " ..
                "mists of the Upper Sumprushes. Find his resting place, and then use these torches to " ..
                "awaken him.",
            rewardMoney = 110000,
        },
        [30790] = {
            description = "Golgoss' strength is great, but he requires nutrition before he can use " ..
                "it.\n\nThe snarlthorn bushes in the Upper Sumprushes have heavy, fibrous branches. These " ..
                "should sate his appetite.",
            rewardMoney = 110000,
        },
        [30791] = {
            description = "Arconiss fights with unmatched fury, but his extended stay beneath the mists " ..
                "has left him weakened.\n\nThe rodents of the swamp are plentiful, and their bodies are " ..
                "filled with nourishing blood. Return with blood enough to reignite Arconiss' spirit.",
            rewardMoney = 110000,
        },
        [30792] = {
            description = "I knew death would come. I did not know that it would come this fast.\n\nI " ..
                "must buy time. The mist of the Upper Sumprushes is warm and fragrant. Such mist is " ..
                "nutritive to my kind.\n\nGather this mist however you can... in jars, in vials, within " ..
                "the interior of your bags. Bring it back to me, and I can use it to remain corporeal for " ..
                "a bit longer.",
            rewardMoney = 110000,
        },
        [30793] = {
            description = "Now is the time to strike.\n\nGolgoss, Arconiss, and I will go east, into " ..
                "Jahesh's domain. Meet us there, and prepare for battle.\n\nToday, we restore the pride " ..
                "of our people.",
            rewardChoices = {
                {83653, 1}, {83654, 1}, {83655, 1}, {83656, 1}, {83657, 1}, {83658, 1}, {83659, 1},
                {83660, 1}, {83661, 1},
            },
            rewardMoney = 220000,
        },
        [30794] = {
            description = "I... am alive... but barely. They killed the rest. My friends... and " ..
                "family...\n\nI must return to the village... But, I do not have long, and cannot move on " ..
                "my own... are you a healer? I... have a healing potion in my hut... search my " ..
                "belongings. You can use your magic, if you have it.",
            rewardMoney = 51000,
        },
        [30796] = {
            description = "These spirits must have been released when the tombs were opened...\n\nDeath " ..
                "was not final for the Mogu. Instead, death was merely a stop over on the path to a new " ..
                "body. Spiritbinders used a foul magic to transfer spirits from one shell to the " ..
                "next.\n\nYears of being trapped in the tombs has left them confused. They need to be " ..
                "destroyed before their confusion turns to anger or worse, they find a new shell.",
            rewardMoney = 106000,
        },
        [30797] = {
            description = "A ritual took place here, and from the looks of it wasn't successful.\n\nAmong " ..
                "the abandoned items a book lies open. The text on the pages is foreign to " ..
                "you.\n\nCarrying the whole book may be difficult, but a single page might be enough. If " ..
                "you can get the page to Lorewalker Cho he may be able to tell you what it says.",
            rewardMoney = 106000,
        },
        [30798] = {
            description = "The Mogu have been scattered and sparse in number for many years. Their " ..
                "purpose in the valley makes sense now.\n\nWith this many restless spirits they can build " ..
                "themselves an army using the guardians buried in each tomb. Combined with the Zandalari " ..
                "forces this would be devastating!\n\nThe Tomb of Secrets houses elite warriors called " ..
                "the Emperor's Shield. They must not be resurrected! You'll find the tomb on the highest " ..
                "rise to the southwest.",
            rewardMoney = 106000,
        },
        [30802] = {
            description = "We need to figure out where they are taking the Thunder King's remains. It " ..
                "won't be possible for them to ressurect him in the Valley of the Emperors. They would " ..
                "need to be somewhere remote and secure.\n\nIt appears that getting out of here may also " ..
                "prove to be a challenge....\n\nFight your way out and look for information concerning " ..
                "location of the remains.",
            rewardChoices = {{82579, 1}, {82580, 1}, {82581, 1}, {82582, 1}, {82583, 1}},
            rewardMoney = 106000,
        },
        [30804] = {
            description = "I am not gonna take this anymore. My wife, bless her, poured her heart and " ..
                "soul in to that ranch making it what it is today.\n\nThem yaungol got a leader over " ..
                "there being all smug and what not. I'll pay you handsomely if you knock that smug smile " ..
                "off his filthy, stinking, good for nothing face.",
            rewardChoices = {
                {84518, 1}, {84519, 1}, {84520, 1}, {84521, 1}, {84522, 1}, {84523, 1}, {84524, 1},
                {84525, 1}, {84526, 1},
            },
            rewardMoney = 106000,
        },
        [30805] = {
            description = "After the mercenaries robbed us, most left.\n\nBut one of them... after the " ..
                "others took all we had, he ran the rest of us through. For sport!\n\nGet justice for the " ..
                "fallen. Perhaps news of their death will raise my spirits enough to go on.\n\nYou'll " ..
                "find them just west of here.",
            rewardMoney = 102000,
        },
        [30806] = {
            description = "Many have perished here. We will need to honor them properly, which means " ..
                "gathering the makings of incense of life.\n\nIt doesn't just smell nice - it has " ..
                "restorative properties, and can even help plants grow. Maybe I can get a whiff of the " ..
                "ingredients to get me back on my feet.\n\nThe materials can be found on creatures around " ..
                "here - except for the spices, which were stolen by the mercenaries who pillaged the " ..
                "village.",
            rewardMoney = 102000,
        },
        [30807] = {
            description = "I do not wish to dishonor my friends and leave them in unmarked " ..
                "graves.\n\nYet, we have never needed to bury so many at once, and I am in no condition " ..
                "to gather materials.\n\nPlease, visit the lakes that hug the mountains edge along the " ..
                "road to the south. Underneath the waterfalls there, you will find stones that have been " ..
                "polished to a sheen by the falling water. They will make suitable headstones.",
            rewardMoney = 102000,
        },
        [30808] = {
            description = "The yaungols stole our luckydos! Mean riders with spears took them from our " ..
                "caravan of brothers coming down the Burlap Trail.\n\nThis is very bad fortune. If the " ..
                "yaungol discover the secrets of luckydos all grummles will be in big trouble.\n\nRecover " ..
                "our luckydos from Fire Camp Ruqin north of here and we will pay many fortunes to you.",
            rewardMoney = 106000,
        },
        [30814] = {
            description = "<Lord Taran immediately pins you down with his steely gaze.>\n\n<class>, you " ..
                "bear the marks of many a past battle.\n\nGood! We need more seasoned people like you to " ..
                "hold back the front.\n\nWe've managed to secure a foothold here, but the yaungol are " ..
                "desperate to remove our presence.\n\nIf you wish to prove your worth, go down the hill " ..
                "and show the yaungol that we will not back down.",
            rewardMoney = 110000,
        },
        [30815] = {
            description = "I have resolved to remove this spear from my side.\n\nFor this, I require your " ..
                "assistance. Your grasping hands are stronger than mine.",
            rewardChoices = {{83756, 1}, {83757, 1}, {83758, 1}, {83760, 1}, {83761, 1}},
            rewardMoney = 11000,
        },
        [30816] = {
            description = "When the trolls came, they brought their mercenary... friends with them. I saw " ..
                "them go past us, to the fishing camp in the northwest. My cousin, a healer, lives there " ..
                "- can you check in with him and make sure he and his village are well?",
            rewardMoney = 10200,
        },
        [30819] = {
            description = "Thank you much, friend. After this tragedy, it is good that fortune has smiled " ..
                "on us and sent you.\n\nYou have gotten justice for my fallen friends, and gathered the " ..
                "necessary materials to honor them. I will gather their bodies, prepare the materials for " ..
                "their funerals, and meet you at the graveyard.\n\nIn the meantime, however, please " ..
                "return to my cousin and ask him to gather the villagers for the funeral.",
            rewardMoney = 10200,
        },
        [30820] = {
            description = "As I said, I will gather the town - we will be at the funeral.\n\nAs the one " ..
                "who has done so much to honor our friends, we feel it is only right that you will be the " ..
                "one to light the Incense of Life and usher their spirits to the life beyond.",
            rewardChoices = {
                {82496, 1}, {82497, 1}, {82498, 1}, {82499, 1}, {82500, 1}, {82501, 1}, {82502, 1},
                {82503, 1}, {82504, 1},
            },
            rewardMoney = 204000,
        },
        [30823] = {
            description = "My cousin over at Kota Basecamp mussed up. He mussed up bad.\n\nHe was too " ..
                "lazy to cut seeds out of kafa berries by hand, but he noticed goots eat the berries up " ..
                "and give back the seeds... in a day or so.\n\nHe fed everything he had to the goots on " ..
                "Kota Peak and now they're nuts! Chargin' everything that moves.\n\nKota used to be safe " ..
                "for Grummles to gather kafa. Not anymore. Not with them goots. Will you help?",
            rewardMoney = 106000,
        },
        [30824] = {
            description = "It was a crazy idea: kafa berries go in the goot, seeds come out.\n\nKafa'kota " ..
                "is already rare and worth a fortune, but my cousin's invention--Kafa'goot--is " ..
                "GOURMET.\n\nBut its over now. Uncle Keenbean is upset and peak is a muss. All thats left " ..
                "is to collect the rest of the Kafa'goot and never make it again.\n\nI won't ask you to " ..
                "gather it--kind of a mussy task, not fit for hero-- just mark it so we can find it " ..
                "easily when the mountain is safe again.",
            rewardItems = {{88382, 1}},
            rewardMoney = 106000,
        },
        [30825] = {
            description = "Kota Peak is famous for its kafa bushes - no other can survive at this " ..
                "elevation.\n\nGrummles make very good living selling Kafa'kota Blend, but it's dangerous " ..
                "now thanks to our cousin. He's got the wildlife up there hooked on kafa with his " ..
                "scheming.\n\nKafa'kota is more scarce than ever with goots gobblin' it up and yetis " ..
                "hoarding it in their caves.\n\nUncle Keenbean will pay you good for any berries you " ..
                "bring down from Kota.\n\nHere, take a sample. Eat it. See for yourself the power of kafa.",
        },
        [30826] = {
            description = "Lots of yetis in Kota, yup. Usually not too dangerous. Usually just eat " ..
                "goots.\n\nThen stupid Cousin Gootfur over at Kota Basecamp fed kafa to the goots, and " ..
                "the yeti ate them goots.\n\nNow they're moody, cranky, sleep a lot but never seem " ..
                "rested. Typical kafa addicts.\n\nGonna come outta those caves soon, I'm sure. Come " ..
                "lookin' for more kafa.\n\nThen we all in trouble.",
            rewardItems = {{88578, 10}},
            rewardMoney = 106000,
        },
        [30827] = {
            description = "If my suspicions are correct, this place still reels from some lingering " ..
                "darkness.\n\nWhatever happened here... it could not have been the natural course of " ..
                "events.\n\nEven the yaungol are not so brutal as to slaughter their own kind to the " ..
                "point of... this.\n\nI will use the totems that you brought me to perform a cleansing " ..
                "ritual.\n\nI need someone to assist me in the ceremony. Let me know when you are ready.",
            rewardMoney = 110000,
        },
        [30828] = {
            description = "Pools of the same murky substance that came out of Mei emerged in the lake " ..
                "recently.\n\nI will travel into the Mere with you. Point out the pools of corruption " ..
                "that you are ready for me to cleanse.\n\nYou will need to deal with whatever comes out " ..
                "and protect me as I complete the ritual.",
            rewardMoney = 102000,
        },
        [30834] = {
            description = "They survived? My father is alive!\n\nI thought we would all die here in this " ..
                "horrible mere, at the hands of these insane Jinyu.\n\nI will find my way back - meet me " ..
                "back at camp.",
            rewardMoney = 204000,
        },
        [30855] = {
            description = "I can hear the voice of the Mere - it has been purified.\n\nBut, this chapter " ..
                "in my people's history will never be closed - not until we defeat Shai Hu.\n\nHe has " ..
                "retreated to the central island in the Mere, corrupting our holiest of sites.\n\nBeware " ..
                "- he is strong. But, after all we have done, I am confident we will be stronger.",
            rewardChoices = {
                {82550, 1}, {82551, 1}, {82552, 1}, {82553, 1}, {82554, 1}, {82555, 1}, {82556, 1},
                {82557, 1}, {82558, 1},
            },
            rewardMoney = 204000,
        },
        [30879] = {
            description = "Welcome, Challenger, to my tournament of champions! Today we test the " ..
                "strengths of Pandaria's most dedicated heroes.\n\nYour first opponent awaits you under " ..
                "the eastern gazebo. Defeat her, and you may proceed to the next round.\n\nFight with " ..
                "strength, fight with honor.",
            rewardMoney = 114000,
        },
        [30880] = {
            description = "Welcome, challenger, to my tournament of champions! Today we test the " ..
                "strengths of Pandaria's most dedicated heroes.\n\nYour first opponent awaits you under " ..
                "the eastern gazebo. Defeat her, and you may proceed to the next round.\n\nFight with " ..
                "strength, fight with honor.",
            rewardMoney = 114000,
        },
        [30881] = {
            description = "You may know your next challengers. They were arguing fiercely when they " ..
                "arrived, so I have charged them with fighting side by side.\n\nThis will teach them the " ..
                "strength of friendship, and possibly entertain me in the process.\n\nGo to the north " ..
                "eastern arena and face this jinyu and hozen.\n\nDo not be gentle, they need to learn to " ..
                "work together.",
            rewardMoney = 114000,
        },
        [30883] = {
            description = "Your next challenger is a favorite of mine. He draws strength from raw force " ..
                "and determination.\n\nPlus he has a mask.\n\nFace him in the western arena when you are " ..
                "ready, and good luck.",
            rewardMoney = 114000,
        },
        [30884] = {
            description = "This battlefront has been undermanned and unsupplied for too long during my " ..
                "absence in Kun-Lai. We need to get things back in order here before we can pick up the " ..
                "trail of the Sha of Hatred.\n\nTaoshi is my best. I've sent her north to investigate " ..
                "rumors of mantid that have somehow made it through the battlefront. I need someone I can " ..
                "trust to get out there and work with her to plug any holes in our defenses.\n\nIf my " ..
                "reports on you are correct, I can trust you with this, right <class>?",
            rewardMoney = 27500,
        },
        [30886] = {
            objectivesText = {
                "See if you've already completed this by typing: /run " ..
                    "print(C_QuestLog.IsQuestFlaggedCompleted(30886))",
            },
        },
        [30887] = {
            description = "Those are mantid scouts down there. Gao-Ran's Battlefront is meant to keep " ..
                "them out of eastern Townlong Steppes. If we allow them north of the barricade, we may " ..
                "lose our foothold here.\n\nLet's clear them out. I'll be with you.",
            rewardMoney = 110000,
        },
        [30888] = {
            description = "Normally, it only takes a few scouts to hold this pass. Most of this territory " ..
                "is in sight of the wall, so archers would devastate any mantid force attempting to push " ..
                "through here. The problem is, most of the archers are occupied with the onslaught at the " ..
                "gate.\n\nTake this flare - it will help you locate the mantid that are sneaking through " ..
                "the eastern pass under our diminished watch. Kill any you find. We can't let them lay a " ..
                "trail that might lead the mantid swarms farther into the steppes.",
            rewardMoney = 110000,
        },
        [30889] = {
            description = "Good to meet you, <class>. We have traps all along the pass to help us catch " ..
                "mantid that might be sneaking through, but their numbers have been so great that most of " ..
                "the traps have already been triggered.\n\nTaoshi said you might be able to reset some of " ..
                "them while you're out there. Can you help?",
            rewardMoney = 110000,
        },
        [30890] = {
            description = "I'm being told that our scouts have been on duty in Shallowstep Pass for more " ..
                "than 2 days straight, no rest. No wonder mantid are slipping through. Even the most " ..
                "dedicated scouts would slip with those kinds of shifts.\n\nI want you to go out there " ..
                "and deliver orders to the scouts that they are to return to the battlefront immediately " ..
                "for rest and rations. I'll arrange for a new shift to be posted.",
            rewardChoices = {{84610, 1}, {84611, 1}, {84612, 1}, {84613, 1}, {84614, 1}},
            rewardMoney = 110000,
        },
        [30891] = {
            description = "A new face! Pleasure to meet you. I'm Septi. I keep the Shado-Pan " ..
                "fighting.\n\nThe mantid have poison that chews through the skin and infects the blood. " ..
                "It makes for a slow, excruciating death when not treated.\n\nI need pollen from the " ..
                "violet citron flowers. The nearest place to find them is around Dampsoil Burrow just " ..
                "north of the battlefront. If you happen to go in that direction, could you bring some " ..
                "back for me?",
            rewardMoney = 110000,
        },
        [30892] = {
            description = "<name>, I could use your help. With their long shifts, our warriors down at " ..
                "the southern front of the battlefront are fighting to the point of exhaustion, and many " ..
                "of them have been exposed to the mantid poison.\n\nWe need more people to tend to the " ..
                "wounded. I've prepared some bandages with the herbs you brought me, but if you have some " ..
                "healing skills, those might work even better.\n\nPlease, <name>, get our men back on " ..
                "their feet so that they can get back here to safety.",
            rewardMoney = 110000,
        },
        [30893] = {
            description = "Gao-ran's men need help down on the southern front. If you want to stand by " ..
                "the Shado-Pan, that's where you should do it.",
            rewardChoices = {
                {83698, 1}, {83699, 1}, {83700, 1}, {83701, 1}, {83702, 1}, {83703, 1}, {83704, 1},
                {83705, 1}, {83706, 1},
            },
            rewardMoney = 110000,
        },
        [30894] = {
            description = "I do have another task for you, <name>, though it's a might grim. I really " ..
                "need to get to the bottom of this mantid poison, but to do that, I need more information " ..
                "directly from the source.\n\nWhile you're down on the southern battlefield, could you " ..
                "bring me back some mantid limbs so that I can examine their intact poison glands.",
            rewardItems = {{88585, 1}},
            rewardMoney = 110000,
        },
        [30895] = {
            description = "I've got another job for you.\n\nThe dragon cannons we depend on to keep the " ..
                "thicker swathes of mantid back are running low on ammo. The camp's cannoneers developed " ..
                "an improvised explosive that's made from the globe seeds down the western ridge.\n\nThey " ..
                "dispatched a couple initiates to bring some back hours ago, but have heard nothing from " ..
                "them. I want to send someone a bit more capable to make sure that this gets taken care " ..
                "of.\n\nAre you my <man/woman> for this?",
            rewardChoices = {
                {88096, 1}, {88097, 1}, {88098, 1}, {88099, 1}, {88100, 1}, {88101, 1}, {88102, 1},
                {88103, 1}, {88104, 1},
            },
            rewardMoney = 110000,
        },
        [30896] = {
            description = "I can't catch the little buggers for the life of me.\n\nKill any you can get " ..
                "your hands on. And keep a close eye on your valuables, they like to steal anything that " ..
                "isn't tied down.",
            rewardItems = {{88487, 5}},
            rewardMoney = 110000,
        },
        [30897] = {
            description = "Look... um... this is really embarrassing. I set down my sword for like ONE " ..
                "SECOND to gather some orbs, and a big sprite sprung out of nowhere, snatched it, and " ..
                "bounded off down the western gap.\n\nI can't go back to camp without it. Losing your " ..
                "weapon is a sure way to get kicked out of the Shado-Pan. It's sacred.\n\nPlease, can you " ..
                "try to find this big sprite and get my sword back? It would mean a lot to me.",
            rewardItems = {{88586, 1}},
            rewardMoney = 110000,
        },
        [30898] = {
            description = "The mantid numbers have been increasing since you left for the cleft. Let's " ..
                "put these orbs you gathered to use.\n\nGet down on the battlefront and man one of the " ..
                "cannons. Let none through.",
            rewardMoney = 110000,
        },
        [30899] = {
            description = "<name>, take these crossbow bolts and then bring them to Hawkmaster Nurong at " ..
                "Farwatch Overlook to the southwest.\n\nNurong is praised among all the Wukao for being a " ..
                "flawless shot. His efforts are credited with holding the line here for these many " ..
                "months. I'm hoping you can work with him and judge for yourself. He may be the final " ..
                "Shado-Pan we need for the hunt.",
            rewardMoney = 110000,
        },
        [30900] = {
            description = "That thing is huge!\n\nThe Shado-Pan holding the battlefront were never " ..
                "trained for something like this... let's get down there and take it out ourselves.",
            rewardChoices = {{83726, 1}, {83727, 1}, {83728, 1}, {83729, 1}, {83730, 1}},
            rewardMoney = 110000,
        },
        [30901] = {
            description = "I'm heading westward with Taoshi to gather the strongest I can find to " ..
                "confront the Sha of Hatred.\n\nI would like you to come with me.",
            rewardMoney = 27500,
        },
        [30907] = {
            description = "And now the final round. I have selected three challengers for you to face. " ..
                "This may seem unfair... to a weakling. You are not a weakling, correct?\n\nGo to the " ..
                "main temple, stand in the grand arena, and face these three challengers. Prove you are " ..
                "stronger than their combined power!\n\nGood luck, Challenger!",
            rewardMoney = 114000,
        },
        [30918] = {
            description = "I am ashamed to ask, but for Greenstone's sake... might we now trouble you to " ..
                "face Vengeful Hui on our behalf...? See if you've already completed this by " ..
                "typing:\n\n/run print(C_QuestLog.IsQuestFlaggedCompleted(30918))",
        },
        [30921] = {
            description = "<class>. You may be of assistance.\n\nThe Shado-Pan wishes to know why the " ..
                "mantid are attacking so violently. We have our suspicions, but we cannot be sure. " ..
                "Furthermore, we do not want the mantid to know that we are investigating them.\n\nThat's " ..
                "where you come in.\n\nI need you to kill the mantid of Kri'vess, in the north. I will " ..
                "lurk behind you in the shadows, and search for clues on their bodies.",
            rewardChoices = {
                {83707, 1}, {83708, 1}, {83709, 1}, {83710, 1}, {83711, 1}, {83712, 1}, {83713, 1},
                {83714, 1}, {83715, 1},
            },
            rewardMoney = 110000,
        },
        [30922] = {
            description = "The Shado-Pan are rare, elite, and quite expensive to train and replace. We " ..
                "can't afford to have any falling to a poisoned weapon or an infected cut. That's why I " ..
                "need you to get... something.\n\nLet me be blunt. Mushan urine is a great, natural " ..
                "antiseptic. They produce a large amount of it, which is lucky... because we tend to use " ..
                "a lot.",
            rewardMoney = 110000,
        },
        [30923] = {
            description = "Every day, the mantid build up munitions for use on their enemies. We cannot " ..
                "stop them, just you and I... but we can set them back.\n\n< Tai Ho hands you some " ..
                "explosives.>\n\nI need to keep a low profile. Would you do the honors?",
            rewardMoney = 110000,
        },
        [30924] = {
            description = "Niuzao, the Black Ox, rests in the temple to the west. He may know why the " ..
                "mantid are attacking.\n\nHe may, in fact, know much more than that.\n\nI will rendezvous " ..
                "with you at Niuzao Temple, <class>.",
            rewardMoney = 110000,
        },
        [30925] = {
            description = "Niuzao owns a statuette which he values greatly: a small icon, in his image, " ..
                "sculpted by one of his long-since fallen sentinels. This statuette was recently stolen " ..
                "by the Sra'thik mantid, and taken to their encampment to our north.\n\nBring back this " ..
                "statuette. Then we will give you - and your Shado-Pan associate - the answers you seek.",
            rewardChoices = {{83736, 1}, {83737, 1}, {83738, 1}, {83739, 1}, {83740, 1}},
            rewardMoney = 110000,
        },
        [30926] = {
            description = "It is with a heavy heart that I confirm your suspicions. The mantid are indeed " ..
                "under the sway of the Sha of Fear.\n\nIt was OUR sworn duty to confine that creature " ..
                "beneath our temple. Unfortunately, our vigil faltered, our defenses buckled, and the sha " ..
                "escaped. It is with the mantid now.\n\nSee for yourself. The mantid burrowed into the " ..
                "western side of our island.",
            rewardChoices = {{83731, 1}, {83732, 1}, {83733, 1}, {83734, 1}, {83735, 1}},
            rewardMoney = 110000,
        },
        [30927] = {
            description = "I overheard. Our secret is out, then.\n\nWhen I learned that the mantid had " ..
                "burrowed beneath our temple, I reacted hastily. I sent dozens of guardians to defend " ..
                "what they could, but they were not prepared. They succumbed to fear, and never " ..
                "returned.\n\nA pandaren deserves to die embracing the ground, as he does in sleep... not " ..
                "flat on his back with his eyes transfixed in terror. Please, <name>. Give them the peace " ..
                "they deserve.",
            rewardMoney = 110000,
        },
        [30928] = {
            description = "You now know Niuzao's secret. We are not only the wardens of this temple... we " ..
                "were the wardens of the Sha of Fear that was buried beneath it.\n\nThe Sha itself may " ..
                "have escaped... but it left traces behind. If you're truly going down into the " ..
                "catacombs, you should eliminate those traces, before they escape and cause greater " ..
                "problems than those we already face.",
            rewardMoney = 110000,
        },
        [30929] = {
            description = "Is this the place where they replace defective yaks?\n\nCan anybody help me " ..
                "out, here?",
            rewardMoney = 55000,
        },
        [30930] = {
            description = "I can't find a single good yak here. ALL the yaks are bad!\n\nSome are too " ..
                "stinky, some too fight-y, others just scared.\n\nYou look like a lucky <race>. Here, " ..
                "take a lasso. See if you can find a good yak for me.",
            rewardItems = {{82467, 1}},
            rewardMoney = 110000,
        },
        [30931] = {
            description = "I came here to visit my dad at the temple. As soon as I got here, I saw the " ..
                "most terrifying thing I've ever seen.\n\nIt was a mantid, walking right past me, " ..
                "carrying my father's crossbow.\n\nSomething's happened to my dad! We've got to find out " ..
                "what it is... but first, we'll need his crossbow back. I saw him heading west, behind " ..
                "the temple.",
            rewardMoney = 110000,
        },
        [30932] = {
            description = "Yes, the boy's father - Sentinel Ku-Yao - has gone missing. He could be any " ..
                "number of places... we have no shortage of enemies these days.\n\nYou're free to look " ..
                "around, if you wish. You might start by looking for his yak, or by asking Sentinel Yalo " ..
                "what he knows.",
            rewardMoney = 110000,
        },
        [30933] = {
            description = "I've searched everywhere... but I haven't found my father. I KNOW he's alive " ..
                "still. He just needs his crossbow... then he'll be OK.\n\nI've heard that you Shado-Pan " ..
                "guys sometimes fight the mantid on Sra'vess. I don't have any way of getting there. If " ..
                "you ever go over there, can you look for my dad?",
            rewardMoney = 114000,
        },
        [30935] = {
            description = "The villagers of Zouchin know the coast better than anyone in Kun-Lai. If the " ..
                "Zandalari are hiding on one of the islands, they will know.\n\nMishi will take you as " ..
                "far as Emperor's Path. I will go ahead to speak with the village elders.\n\nFollow the " ..
                "path to Whispercloud Rise. Shin Whispercloud will help you reach the village.",
            rewardMoney = 106000,
        },
        [30942] = {
            description = "Shhh! Don't speak so loudly! My father might hear you.\n\n< Shomi gestures to " ..
                "Steelbender Doshu.>\n\nMy father is delusional! He thinks I should be studying my tea " ..
                "pouring while our village is under attack. It's ridiculous! I have just as much courage " ..
                "as any man. I just don't know how to fight... yet.\n\nThat's where you come in. Let me " ..
                "travel with you! I'm a fast learner and I won't get in the way I " ..
                "promise!\n\nPleaseeeeee!\n\nIf we get separated I'll meet you back in the village.",
            rewardChoices = {
                {82599, 1}, {82600, 1}, {82601, 1}, {82602, 1}, {82603, 1}, {82604, 1}, {90488, 1},
                {90489, 1}, {90623, 1},
            },
            rewardMoney = 106000,
        },
        [30943] = {
            description = "I've seen the numbers these invaders have brought with them, this will not be " ..
                "an easy victory. I do know of one thing that may help us gain an advantage.\n\nThere is " ..
                "a plant that grows around the village that can be used to make a rather effective " ..
                "explosive liquid. If you can gather enough I can begin brewing the mixture.\n\nThe plant " ..
                "you are looking for is appropriately named volatile bloom. Handle it with care, <class>.",
            rewardMoney = 106000,
        },
        [30944] = {
            description = "The villagers have been guarding Zouchin since the first attack. They are " ..
                "exhausted and many are injured.\n\nIf the Zandalari attack again the last thing we need " ..
                "is for the defenders to fall asleep on the job.\n\nRelieve them of their posts so that " ..
                "they might have time to heal and see their families.\n\nYou'll find them stationed " ..
                "around the village.",
            rewardMoney = 106000,
        },
        [30952] = {
            description = "The mantid continue to attack us. Their numbers ebb and flow, but they do not " ..
                "stop.\n\nIt is no matter. The yak is stamina embodied. We will not bend to them. We will " ..
                "defend his home forever.\n\nWill you help us?",
            rewardMoney = 228000,
        },
        [30953] = {
            description = "Our sentinels can fight for days on end, but even they have their limits. " ..
                "Since the mantid swarm began, too many of them have pushed themselves beyond their " ..
                "abilities.\n\nPlease, aid them in whatever way you can. If you are unable to heal them " ..
                "yourself, you may give them some of this. A mouthful of nutritious yak's milk will give " ..
                "them the strength they need.",
            rewardMoney = 114000,
        },
        [30954] = {
            description = "This is no time to hold to tradition. Our masons' calloused hands bleed and " ..
                "tremble. Our blacksmiths cannot forge weapons as quickly as our sentinels can break " ..
                "them.\n\nIt is time to fight smart.\n\nMany of the mantid come bearing weapons, and when " ..
                "they die, they simply leave them on the battlefield. It would be a shame to see them go " ..
                "to waste.",
            rewardMoney = 114000,
        },
        [30958] = {
            description = "Niuzao's appearance on the battlefield is a blessing... in more ways than " ..
                "one.\n\nWith the distraction that he's caused, our stonemasons have seized the " ..
                "opportunity to build up our crumbling walls. They could use your help.\n\nToss any loose " ..
                "bricks you find up their way. And hurry! Niuzao will not rampage forever.",
            rewardMoney = 114000,
        },
        [30959] = {
            description = "The mantid now surround the Temple with their infernal war wagons. The sooner " ..
                "we are rid of those things, the better. You could destroy them with your own weapons and " ..
                "spells, but this will work much faster.\n\n<Ogo hands you a few small casks of " ..
                "hastily-packed explosives.>\n\nBeware of retaliation from mantid that remain be inside " ..
                "the war wagon when it explodes. In fact, I'd stay as far away from those things as " ..
                "possible.",
            rewardMoney = 114000,
        },
        [30960] = {
            description = "I still have some cleanup to do here in the pass - there are some mantid still " ..
                "making it through. You're a valuable person to have at hand though, and I know Taran " ..
                "wouldn't appreciate me keeping you longer for such basic work.\n\nTaran should still be " ..
                "in the main camp with Gao-Ran. Report back in. I'll catch up with you a bit later.",
            rewardMoney = 27500,
        },
        [30961] = {
            description = "I will go now to return to my kinsmen. Please visit us back at the " ..
                "southwestern edge of the Mere, so that we may thank you. See if you've already completed " ..
                "this by typing:\n\n/run print(C_QuestLog.IsQuestFlaggedCompleted(30961))",
        },
        [30963] = {
            description = "The Shado-Pan fight. As such, their armor often gets cut, scratched, torn, and " ..
                "burned. And it's my job to repair it.\n\nI'm no armorer, but I can repair a broken piece " ..
                "of mail as long as the hole's not too big.\n\nI prefer to use shell fragments from the " ..
                "tortoises that live in the wild fields to the northeast. Get some for me, and I can keep " ..
                "more Shado-Pan armored and alive.",
            rewardChoices = {
                {83680, 1}, {83681, 1}, {83682, 1}, {83683, 1}, {83684, 1}, {83685, 1}, {83686, 1},
                {83687, 1}, {83688, 1},
            },
            rewardMoney = 110000,
        },
        [30964] = {
            description = "A dry bandage doesn't do much good, other than maybe keeping bugs out of the " ..
                "wound. In some camps, that's the best you can hope for.\n\nNot in my camp, though.\n\nI " ..
                "prefer to make a paste from whatever soothing herbs I can find, and layer that between " ..
                "bandages. The most soothing herbs I've been able to find in the field are the " ..
                "Mao-Willows from the fields in the northeast. If you run into any, bring them back.",
            rewardMoney = 110000,
        },
        [30967] = {
            description = "Not all of my fellow villagers from Inkgill are corrupted. Many heeded my " ..
                "warnings and did not drink of the sha-tainted waters.\n\nThey are in hiding, terrified, " ..
                "and intimidated by the guards.\n\nPlease, tell them there is hope! Go into the village " ..
                "to the north. Speak with them and send them to me.",
            rewardMoney = 102000,
        },
        [30968] = {
            description = "The end of our hunt is upon us. We have gathered the strongest the Shado-Pan " ..
                "have to offer, and with your strength to aid us, we will defeat the Sha of Hatred and " ..
                "choke out its influence on the world.\n\nWhen we enter the tunnel, stay close, and keep " ..
                "hatred clear from your heart. The fight ahead will put all of us to the " ..
                "test.\n\nWhatever happens, it has been an honor traveling beside you, <name>.",
            rewardChoices = {
                {83644, 1}, {83645, 1}, {83646, 1}, {83647, 1}, {83648, 1}, {83649, 1}, {83650, 1},
                {83651, 1}, {83652, 1},
            },
            rewardMoney = 330000,
        },
        [30970] = {
            description = "These scorpions are infected with sha. It seems to have driven them out of " ..
                "their hole and into our camp, seething with hatred at invaders in their territory.\n\nWe " ..
                "need to clear the scorpions and secure the camp. Kill any you find.",
            rewardChoices = {{83741, 1}, {83742, 1}, {83743, 1}, {83744, 1}, {83745, 1}},
            rewardMoney = 110000,
        },
        [30971] = {
            description = "I was dispatched back to camp to gather pitch-tipped arrows for our archers at " ..
                "the bridge, and this is what I came to. I trained with most of these pandaren... I " ..
                "wasn't prepared for this.\n\nStill, the archers at the bridge need our help. If you " ..
                "could help gather arrows from the wreckage, then maybe we can salvage something from " ..
                "this horror.",
            rewardMoney = 110000,
        },
        [30972] = {
            description = "Lao-Chin's archers will need these arrows down at the bridge. Can you bring them?",
            rewardMoney = 27500,
        },
        [30973] = {
            description = "The mantid coming across the bridge have thick carapaces that shrug off most " ..
                "of our attacks. They have a weakness though: fire.\n\nLao-Chen's men brought kegs to the " ..
                "battlefield for exactly this purpose. Kick the kegs into groups of mantid, and " ..
                "Lao-Chin's archers will light them up.\n\nThey should be easy to finish off from there.",
            rewardChoices = {
                {88105, 1}, {88106, 1}, {88107, 1}, {88108, 1}, {88109, 1}, {88110, 1}, {88111, 1},
                {88112, 1}, {88113, 1},
            },
            rewardMoney = 110000,
        },
        [30975] = {
            description = "Let's press these insects back across the bridge and break their " ..
                "spirits!\n\nFollow my lead.",
            rewardChoices = {{83721, 1}, {83722, 1}, {83723, 1}, {83724, 1}, {83725, 1}},
            rewardMoney = 110000,
        },
        [30976] = {
            description = "We are one stronger. Your help is invaluable.\n\nLet's move on westward to " ..
                "Rensai's Watchpost to find the last member for our party.",
            rewardMoney = 27500,
        },
        [30977] = {
            description = "All of my men are down at Farwatch Overlook to the southwest, holding off " ..
                "mantid that are trying to fly across the chasm. As long as my marksmen have arrows, " ..
                "they'll ground any mantid that clear the chasm.\n\nIf you're here to help, I could use " ..
                "some more men clearing the mantid out once they're on the ground. Are you willing, " ..
                "<class>?",
            rewardChoices = {
                {84596, 1}, {84597, 1}, {84598, 1}, {84599, 1}, {84600, 1}, {84601, 1}, {84602, 1},
                {84603, 1}, {84604, 1},
            },
            rewardMoney = 110000,
        },
        [30978] = {
            description = "We're about to get hit hard...\n\nPick up that cannon there and lend a hand, " ..
                "if you would. There will be no shortage of targets.",
            rewardItems = {{88590, 1}},
            rewardMoney = 110000,
        },
        [30979] = {
            description = "Let's get down there and finish that big bug off, you and I.",
            rewardChoices = {
                {84587, 1}, {84588, 1}, {84589, 1}, {84590, 1}, {84591, 1}, {84592, 1}, {84593, 1},
                {84594, 1}, {84595, 1},
            },
            rewardMoney = 110000,
        },
        [30980] = {
            description = "You said that Taran Zhu is in Townlong and was asking for me? Must be " ..
                "something important...",
            rewardMoney = 27500,
        },
        [30981] = {
            description = "Taoshi is setting up an ambush for one of the mantid leaders on the south side " ..
                "of Sik'vess. She is tasked with retrieving his crystal so that we can use it to open the " ..
                "door.\n\nTwo are stronger than one. I want you there to make sure it goes smoothly.",
            rewardMoney = 110000,
        },
        [30984] = {
            description = "This was supposed to be a routine sweep, <name>. Clean up a few troggs, make " ..
                "sure there is no threat to the city and then be in the tavern by midday.\n\nInstead I've " ..
                "a group of scouts missing, flame hounds pouring out of the chasm and Xorenth going on " ..
                "about \"the next twilight's hammer.\"\n\n< Commander Bagran spits>\n\nGo in there and " ..
                "get my scouts back so we can figure out what is going on down here.",
            rewardMoney = 3300,
        },
        [30987] = {
            description = "We have a duty, <name>.\n\nIt is our responsibility to spread the Tushui " ..
                "philosophy beyond the edges of the Wandering Isle... and there is no better place to " ..
                "start doing that than here: Stormwind City, heart of the Alliance.\n\nLet's find out who " ..
                "their leader is. We need allies.",
            rewardMoney = 35,
        },
        [30988] = {
            description = "I only recently received word that some of your kind might be coming our way. " ..
                "I'd be glad to call you an ally, if you're willing to join our cause.\n\nWalk with me, " ..
                "<name>.",
            rewardMoney = 35,
        },
        [30991] = {
            description = "When I trained as a Brewmaster, I didn't expect to use my knowledge like " ..
                "this...\n\nDid you know beer catches fire when lit? Well, with yaungol oil mixed in, " ..
                "it's downright explosive.\n\nI've mixed the oil in with these kegs. Roll them at the " ..
                "yaungol over by the gate, and ignite them when you get close.\n\nIt'll take a few " ..
                "seconds for the keg to blow, but when it does...\n\nWell, let's just say I wouldn't want " ..
                "to be over there.\n\nWhich is why I'll be over here. Mourning the loss of this brew.",
            rewardItems = {{88531, 1}},
            rewardMoney = 106000,
        },
        [30992] = {
            description = "We've heard back from Suna, on the wall. Something's going on...\n\nIt looks " ..
                "like they are preparing for their final push. It's time to finish this, friend.",
            rewardMoney = 212000,
        },
        [30993] = {
            description = "This has simply gone too far. I cannot ignore our abandonment any " ..
                "longer.\n\nAfter all that's happened here, and all you've been through in Firebough, we " ..
                "must travel to the monastery.\n\nWhatever they are doing in there can wait! We can take " ..
                "my balloon up the mountain to the Monastery. It's anchored back by the camp, to the " ..
                "northeast.",
            rewardMoney = 10600,
        },
        [30995] = {
            description = "I sent recon out over an hour ago and none of them have reported back. And now " ..
                "these damned hounds are pouring out of the chasm.\n\nI don't know what's going on down " ..
                "there, but I'm not going anywhere till I get my men back.\n\nI want you to head in there " ..
                "and find them, <name>, preferably while they are still alive.",
            rewardMoney = 3300,
        },
        [30996] = {
            description = "These dark shaman have been down here for months, raising beasts and " ..
                "performing dark rituals.\n\nI don't know what they aim to achieve with all of this, but " ..
                "it's clear that they are no friend of the Alliance. And I need your help stopping them, " ..
                "<name>.\n\nFight your way through the chasm and kill Dark Shaman Koranthal and Lava " ..
                "Guard Gordoth.",
            rewardChoices = {{82891, 1}, {82892, 1}, {82893, 1}, {82894, 1}, {82895, 1}},
            rewardMoney = 3300,
        },
        [30997] = {
            description = "I'm glad you're here, <name>. The horde is amassing an army and I'm not going " ..
                "to wait to find out why.\n\nWe need to strike fast and take down some of the larger " ..
                "beasts they have down here.\n\nI want you to head in there and take care of Adarogg and " ..
                "Slagmaw before the horde can use them as weapons against us.",
            rewardMoney = 3300,
        },
        [31000] = {
            description = "Shado-Pan marksmen keep a constant watch over the Dread Wastes from the top of " ..
                "the Serpent's Spine. They would surely welcome the aid of a skilled <class> such as " ..
                "yourself.\n\nTake a kite and check in with Bowmistress Li.",
            rewardMoney = 11400,
        },
        [31001] = {
            description = "It's bad enough trying to hold off the mantid, but now we've got spiders " ..
                "swarming up from the ruins below.\n\nOne of my best marksmen caught a blast of webbing " ..
                "around his leg and got pulled straight down!\n\nWe think he's alive, but I don't have " ..
                "the manpower to send anyone in after him. We're stretched thin up here, <class>.\n\nIf " ..
                "you want to help, use the rope behind me to drop down into the ruins. You're not afraid " ..
                "of heights are you?\n\nHow about spiders?",
            rewardMoney = 114000,
        },
        [31002] = {
            description = "We're holding, but just barely. Anything you can do to stem the tide of " ..
                "dreadspinners coming up the wall would be a big help.\n\nFeel like tearing open spider " ..
                "eggs one at a time by hand?\n\nI didn't think so. Take one of our dragon guns and light " ..
                "it up down there. I wanna hear those puppies pop.",
            rewardChoices = {
                {84037, 1}, {84038, 1}, {84039, 1}, {84040, 1}, {84041, 1}, {84042, 1}, {84043, 1},
                {84044, 1}, {84045, 1},
            },
            rewardMoney = 114000,
        },
        [31003] = {
            description = "You aren't going to believe what I saw! Two mantid fighting each other, " ..
                "whipping some serious magic back and forth.\n\nOne of them didn't look like any mantid " ..
                "I've ever seen. Completely different color and dress to him, like some kind of... oracle " ..
                "or something. The other one was a total psycho, splashing sha energy around like it was " ..
                "a keg of Stormstout Special.\n\nLook, I gotta get back to my post, but those two are " ..
                "still fighting in the cave behind me and I have a feeling it's a big deal. Check it out?",
            rewardMoney = 114000,
        },
        [31004] = {
            description = "Take... this...\n\n<The dying mantid struggles to outstretch his arm. In his " ..
                "mangled grasp rests a metal fork with two long, thin prongs and an ornately jeweled " ..
                "handle.>\n\nAwaken... the Wind-Reaver...\n\nIt is the only way... to end the swarm.",
            rewardMoney = 57000,
        },
        [31005] = {
            description = "You will forgive my current state. I have slept for many years.\n\nA Klaxxi'va " ..
                "should have been here to attend my Wakening with kypari sap... but you will have to " ..
                "do.\n\nI sense the buzzing of sapflies to the south. They gorge on the nourishing sap I " ..
                "need. Bring them to me.",
            rewardMoney = 114000,
        },
        [31006] = {
            description = "I must report to the Klaxxi. They would not have woken me unless the situation " ..
                "were dire.\n\nYou have not been entirely useless. For that, I will spare your " ..
                "life.\n\nThe council may even find a use for you.",
            rewardChoices = {{84055, 1}, {84056, 1}, {84057, 1}, {84058, 1}, {84059, 1}},
            rewardMoney = 114000,
        },
        [31008] = {
            description = "You! Filth!\n\nYou work for me now!\n\nThe amber blades of the Shek'zeer " ..
                "Bladesworn are the finest weapons in the empire.\n\nIf you are not impaled upon them " ..
                "immediately after leaving here, bring me as many of the blades as you can carry! I want " ..
                "to make sure we have weapons in reserve, should we need them.",
            rewardChoices = {
                {88114, 1}, {88115, 1}, {88116, 1}, {88117, 1}, {88118, 1}, {88119, 1}, {88120, 1},
                {88121, 1}, {88122, 1},
            },
            rewardMoney = 114000,
        },
        [31009] = {
            description = "A Klaxxi'va whispers to the tower. It carries their whisper far; to other " ..
                "towers, to mantid, to paragons. The whisper bounces back, and the Klaxxi hear " ..
                "it.\n\nThis way, they see all.\n\nA tower near the palace is quiet. This will not do. It " ..
                "must sing for the Klaxxi.\n\nIt is my job to fix the tower, but if you serve the Klaxxi, " ..
                "you should serve me as well. You fix the tower, and I will wait here!",
        },
        [31010] = {
            description = "The crystal sings to the Klaxxi. They sense a paragon in the clutch, east of " ..
                "the tower.\n\nClutch-keepers are trying to pollute this one. The Klaxxi will not permit " ..
                "this.\n\nGo and find the paragon. Place your hands on his chamber, and the Klaxxi will " ..
                "channel their whispers through you to break him free. Protect him if you can.",
            rewardMoney = 228000,
        },
        [31011] = {
            description = "The Zandalari have begun their attack! You must help defend the village!\n\nIf " ..
                "we can't push them back, we will never find the Thunder King's remains!",
            rewardMoney = 106000,
        },
        [31012] = {
            description = "Here we are, <name>... Orgrimmar, heart of the Horde.\n\nWe can be helpful " ..
                "beyond the edges of the Wandering Isle. There are innumerable problems out there, just " ..
                "waiting for us to solve them. This is what Master Shang Xi would have wanted.\n\nThere's " ..
                "no better place to start doing that than here, with the aid of the Horde. Let's find out " ..
                "who their leader is. We need allies.",
            rewardMoney = 35,
        },
        [31015] = {
            description = "Pandaria is rich with history, legends, stories, and lore of every sort. While " ..
                "you are traveling throughout the world I would ask that you keep an eye open for " ..
                "artifacts and pieces of information that you feel would be pertinent to our work " ..
                "here.\n\nWhen you accumulate enough knowledge, we will compile it in to a volume for " ..
                "your personal collection here.\n\nYou can, of course, return whenever you like to review " ..
                "the volumes we are making for you.",
            rewardMoney = 11400,
        },
        [31018] = {
            description = "The Klaxxi have detected the existence of another paragon, Wakener.\n\nThis " ..
                "one was kept well-hidden from us, and for good reason.\n\nThe Empress already has " ..
                "possession of this one, and her adjuncts work to destroy it even now.\n\nThey are " ..
                "performing their sorcery in a chamber deep beneath the palace, and they must be " ..
                "stopped.\n\nWe hold Klaxxi'vess. You must go in our stead. Find the entrance to their " ..
                "chamber from the ledge to the west.",
            rewardMoney = 114000,
        },
        [31019] = {
            description = "In order for our efforts against the mantid empire to continue, we require " ..
                "more amber.\n\nThere is a great deposit of amber underneath the lake to the south, but " ..
                "the area is inhabited by a savage saurok tribe.\n\nI cannot spare anyone else. You must " ..
                "go to the lake and test the tribe's strength. Thin their numbers and eliminate their " ..
                "leader, who is probably hiding in his underground cavern.\n\nSurely this is not too " ..
                "great a task for you?",
            rewardMoney = 114000,
        },
        [31020] = {
            description = "I must join the Klaxxi Council and the other paragons immediately, but I am " ..
                "barely strong enough to stand.\n\nI must feed, Wakener.\n\nI sense the beating hearts of " ..
                "creatures on the northern bank of the lake.\n\nKill them for me, and I shall do the rest.",
            rewardMoney = 114000,
        },
        [31021] = {
            description = "Liquid amber is most efficient for restoring a newly awakened paragon's " ..
                "strength, and is usually provided at a wakening ceremony.\n\nUnfortunately, it seems you " ..
                "did not receive these instructions, so we shall have to improvise.\n\nI can sense a vast " ..
                "quantity of fossilized amber in the lake below us. It will serve, but I am too weak to " ..
                "dig it up myself.\n\nDo this for me, and I will see to it that you are rewarded.",
            rewardMoney = 114000,
        },
        [31022] = {
            description = "What is that tree on the hill to the west? Can it be... Kypari Zar?\n\n<Korven " ..
                "the Prime lapses into silence.>\n\nWhen I returned from my final ravage, before being " ..
                "elevated to a paragon, I was given the honor of planting that very tree.\n\nI see it has " ..
                "grown into a great kypari, but... it seems something is amiss.\n\nThere is an old sonar " ..
                "tower at the base of the tree. Take me there, Wakener. I can use the tower to take a " ..
                "closer look.",
            rewardMoney = 114000,
        },
        [31023] = {
            description = "This strange-looking carving is covered in a complex written language that " ..
                "might be mantid in origin.\n\nYou notice more relics strewn carelessly among the camps " ..
                "and inside the lake.\n\nPerhaps the Klaxxi would be interested in examining these " ..
                "artifacts.\n\nWho knows? Perhaps it will earn you some favor.",
            rewardMoney = 114000,
        },
        [31024] = {
            description = "As Kovok grows, he will require equal parts discipline and reward.\n\nI lack " ..
                "no shortage of discipline, but our supply of meat is almost empty.\n\nTo the south, you " ..
                "will find turtles roaming north of the Lake of Stars and Kypari Zar.\n\nHunt them. Kovok " ..
                "likes the taste of their flesh.",
            rewardMoney = 114000,
        },
        [31030] = {
            description = "This... is unspeakable. If the monastery has truly been taken over by the Sha, " ..
                "we will need a great effort to purge the monks inside of corruption.\n\nGather a group " ..
                "of your allies, and meet me inside the Monastery.",
            rewardMoney = 10600,
        },
        [31032] = {
            description = "Nurong wants me to pass out torches for burning the bodies.\n\nThe flying " ..
                "mantid are fragile, and won't last long in the hot smoke.",
            rewardItems = {{88589, 1}},
            rewardMoney = 110000,
        },
        [31036] = {
            description = "Orgrimmar's Ragefire Chasm has been taken by the Dark Shaman. <name>, we " ..
                "cannot allow this to pass unpunished, lest they next set their sights on Thunder " ..
                "Bluff.\n\nGo speak with Commander Bagran just inside the Chasm. Help him in any way you " ..
                "can, for our fates are intertwined.",
            rewardMoney = 70,
        },
        [31038] = {
            description = "News of your feats has been traveling around the camp, <name>.\n\nIn fact, " ..
                "Snow Blossom would like to test your skill in battle.\n\nYou had best prepare yourself, " ..
                "<class>. She is not easily defeated.\n\nIf you can prove your worth to her, you will win " ..
                "a valuable friend.",
            rewardMoney = 114000,
        },
        [31041] = {
            description = "Eggs. Yes, you heard me right. I said eggs, and these aren't for " ..
                "eating.\n\nHave you ever seen a cloud serpent egg?\n\nThese rare eggs look like jewels, " ..
                "and were once worth their weight in solid gold.\n\nShan'ze Dao to the north normally " ..
                "teems with wild cloud serpents, but the mogu and the sprites have their eggs on " ..
                "lock-down.\n\nWe need to save as many of these precious eggs as we can.\n\nI'm counting " ..
                "on YOU, <name>.",
            rewardMoney = 114000,
        },
        [31042] = {
            description = "The Shan'ze Serpentbinders dominate the minds of wild cloud serpents, but they " ..
                "also create their own dark creatures from stone, metal, blood, and ancient " ..
                "sorcery.\n\nTheir creations, the Onyx Stormclaws, guard the island to the " ..
                "northwest.\n\nI wish to study the magic binding these creatures. Bring me their hearts, " ..
                "so that I can better understand what sorcery we are up against.",
            rewardMoney = 114000,
        },
        [31043] = {
            description = "It is said that Shan'ze Dao was once home to a great mogu temple.\n\nThere, " ..
                "the Shan'ze studied and practiced the art of subjugating the dead or inanimate.\n\nMuch " ..
                "of their knowledge still remains on the island to the northwest, buried among the " ..
                "ruins.\n\nWe need to get our hands on their knowledge - both to keep it out of their " ..
                "hands, and to understand the nature of their experiments.",
            rewardMoney = 114000,
        },
        [31044] = {
            description = "Among the Shan'ze's fiercest and most loyal creations are their " ..
                "quilen.\n\nThese beasts will hunt until they kill their prey, or die in the " ..
                "process.\n\nI need you to not only cull their numbers, but also to retrieve their bronze " ..
                "claws.\n\nTheir claws are strong and razor sharp, and we can use them to make weapons " ..
                "and hooks for our cause.",
            rewardMoney = 114000,
        },
        [31045] = {
            description = "<class>, I need your strength to eliminate the Shan'ze Illusionists on Shan'ze " ..
                "Dao, to the northwest.\n\nIt wearies me to ask of you this difficult task.\n\nThe " ..
                "illusionists are among the strongest of the Shan'ze's elite sorcerors.\n\nThey will not " ..
                "be easy to defeat, but I know no <class> who is better suited to the task.",
            rewardMoney = 114000,
        },
        [31047] = {
            description = "Do you know the story of the great cloud serpents of Pandaria, " ..
                "<name>?\n\nSomeday you must hear it. Unfortunately, there is no time to tell it " ..
                "now.\n\nWhat you must know is that the wild cloudrunner serpents of Townlong are in " ..
                "trouble.\n\nThe mogu are capturing wild serpents and corrupting their minds, bending " ..
                "them to their sinister will.\n\nGo to Shan'ze Dao, to the northwest. Free the adult " ..
                "serpents from their chains. Save them!",
            rewardMoney = 114000,
        },
        [31048] = {
            description = "We've found ancient mogu burial urns among the ruins on Shan'ze Dao.\n\nThis " ..
                "is normally no problem, except these urns are home to angry mogu spirits.\n\nNot only do " ..
                "these urns pose a danger to anyone unlucky enough to find one, but they could be used " ..
                "for destruction if they were to fall into the wrong hands.\n\nWe must rid Shan'ze Dao of " ..
                "their presence.",
            rewardMoney = 114000,
        },
        [31055] = {
            description = "Dear $p,\n\nWe have received your research on the saurok and believe we have " ..
                "pieced together clues about their past.\n\nIf you visit us at the Seat of Knowledge in " ..
                "Vale of Eternal Blossoms we can add this contribution to your personal " ..
                "collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho",
            rewardMoney = 114000,
        },
        [31062] = {
            description = "The Shan'ze's experiments are overseen by a powerful necromancer known as a " ..
                "Shan'ze Deathspeaker.\n\nIf we are to put an end to their operations, we must eliminate " ..
                "their leader.",
            rewardMoney = 114000,
        },
        [31063] = {
            description = "Lao-Chin is facing off against the leader just above the entrance in the tree, " ..
                "on the north side of Sik'vess. He is to bring back the second crystal that we need to " ..
                "get into the mantid tunnel.\n\nGo there and lend him your aid.",
            rewardMoney = 110000,
        },
        [31064] = {
            description = "Hawkmaster Nurong has gone ahead to the northwest of Sik'vess to make sure the " ..
                "last mantid leader cannot escape.\n\nCatch up with him and help him kill the mantid " ..
                "leader. Nurong will bring back the final crystal once you've aided him in this.",
            rewardMoney = 110000,
        },
        [31065] = {
            description = "Taoshi set up a spyglass on the ridge edge to show me what her scouting " ..
                "uncovered.\n\nGo over and take a look.",
            rewardMoney = 27500,
        },
        [31066] = {
            description = "So, you survived the imperial clutches. You are... resilient.\n\nThe Klaxxi " ..
                "hear another paragon to the north, among the sha-scorched roots of Kypari Vor.\n\nThis " ..
                "one cries out in terror and agony. It cannot be saved.\n\nThe Klaxxi want him put down. " ..
                "Go and defeat him or do not return here.",
            rewardChoices = {{84060, 1}, {84061, 1}, {84062, 1}, {84063, 1}, {84064, 1}},
            rewardMoney = 114000,
        },
        [31068] = {
            description = "\"When the horror comes a-rising And the heavens hum with war Our great vessel " ..
                "of salvation Must be broken from its core.\"\n\nThe scroll continues on for several " ..
                "stanzas. Perhaps somebody at The Sunset Brewgarden will be able to decipher its cryptic " ..
                "message.",
            rewardChoices = {{84071, 1}, {84072, 1}, {84073, 1}},
            rewardMoney = 114000,
        },
        [31069] = {
            description = "About that scroll you found...\n\nI keep looking at that line in the second " ..
                "stanza - \"bound with wood and shade\". The \"shade\", in particular, intrigues me.\n\nI " ..
                "must admit, I've often considered taking some of the area's residual sha essence and " ..
                "incorporating it into a brew. I suspect that this is the shade which our recipe calls " ..
                "for.\n\nYou will find large amalgamations of sha to the southeast of our tree... though " ..
                "you may also be able to harvest some from the local wildlife.",
            rewardChoices = {{84080, 1}, {84081, 1}, {84082, 1}, {84083, 1}, {84084, 1}},
            rewardMoney = 114000,
        },
        [31070] = {
            description = "That recipe said: \"rending daggers of the great ones\"...\n\n< Olon ponders " ..
                "this line.>\n\nMushan! That's it!\n\nThere's plenty of mushan roaming out there with " ..
                "these great, big teeth... they're as long as daggers. That's gotta be what the recipe " ..
                "calls for.",
            rewardMoney = 114000,
        },
        [31071] = {
            description = "I have failed my fellow brewers.\n\nI took some supplies out to the clearing, " ..
                "east of our tree... and I left them there. Now, with the sha corrupting the land, and " ..
                "the mantid on the prowl, it is too dangerous for me to bring them back.\n\nIf you would " ..
                "help me look for them, perhaps I could regain some of my lost honor.",
            rewardMoney = 114000,
        },
        [31072] = {
            description = "Forget about them, and forget their BREW. We've got real work to do.\n\nThe " ..
                "scroll mentions \"rending daggers of the great ones\". I've got a feeling I know where " ..
                "to find them.\n\nA pair of mantid lieutenants patrol the Horrid March, to the south. " ..
                "Each one carries a ceremonial dagger.\n\nBring those daggers back here, <name>. We may " ..
                "be on the brink of something big.",
            rewardChoices = {
                {88123, 1}, {88124, 1}, {88125, 1}, {88126, 1}, {88127, 1}, {88128, 1}, {88129, 1},
                {88130, 1}, {88131, 1},
            },
            rewardMoney = 114000,
        },
        [31073] = {
            description = "<Vu eyes the recipe.>\n\nHmm... \"bound with wood\". We don't typically brew " ..
                "with wood. Sap, yes... but not wood.\n\nWe have, on rare occasions, infused our drinks " ..
                "with corewood from the treants to the west of here. Most of them have fallen to the " ..
                "mantid... but their remains should suffice for our recipe.",
            rewardMoney = 114000,
        },
        [31075] = {
            description = "Olon had a clever idea. He thinks that we should visit the sprites to the " ..
                "west, and ask them if they have any of these ingredients. Some of the elements to this " ..
                "recipe are seeming... strange.\n\nThe Rikkitun sprites have a village to the west of " ..
                "Kor'vess. I hope to see you there, <name>.",
            rewardMoney = 114000,
        },
        [31076] = {
            description = "Greetings, <race>. I am Chen Stormstout.\n\nI'm looking for my family. I am " ..
                "told that several Stormstouts came across the wall to help face the mantid threat. I " ..
                "mean to find them, and join them.\n\nHave you seen anyone named Stormstout come through " ..
                "here? Would you mind helping me ask around?",
            rewardMoney = 57000,
        },
        [31077] = {
            description = "I was too late. She was so small... and I was too late.\n\nShe should be given " ..
                "a proper burial. A little warrior like her deserves better than this.",
            rewardMoney = 57000,
        },
        [31078] = {
            description = "There will be time for mourning later. For now, there are other Stormstouts to " ..
                "be found.\n\nThey say that Han Stormstout was last seen exploring Kor'vess. I suspect he " ..
                "headed into that mantid burrow, just across the way.\n\nYou should meet me down there, " ..
                "<name>. I don't doubt that I can handle a few mantid by myself... but I'd feel better " ..
                "with you by my side.",
            rewardMoney = 114000,
        },
        [31080] = {
            description = "I think that old paper said something about \"fiery wings.\" Those little " ..
                "dragons around here have wings. They're kind of fiery, in a way.\n\nYou're quicker than " ..
                "me. Try catching some of those dragons... or at least slapping the powder off of " ..
                "them.\n\nNo point in killing a harmless little dragon, if all you want is the sparkle " ..
                "from their wings.",
            rewardMoney = 114000,
        },
        [31081] = {
            description = "I suspect we are going to need the help of these sprites.\n\nWe have two " ..
                "enchanted daggers, bound together with wood and shade. Now we need someone to perform " ..
                "ancient \"incantations\" on our artifact.\n\nBefore we ask for favors, let's show the " ..
                "sprites that we mean well. I heard their leader talking about a pair of mistlurkers that " ..
                "kidnapped several of their villagers. If we slay these fog beasts... we may get the " ..
                "\"incantation\" we need in return.",
            rewardMoney = 114000,
        },
        [31082] = {
            description = "I know what you and the girl-panda seek. We can perform the rite for you... in " ..
                "time.\n\nFirst, I require aid. The seeds fall from our great mother-tree. It is our " ..
                "responsibility to collect them, even in dangerous times like these.\n\nEscort my " ..
                "chanters to the motherseeds, that they may bring them back to the collection pit.",
            rewardMoney = 114000,
        },
        [31083] = {
            description = "As soon as the creature died, a strange group of sprites appeared and took its " ..
                "pearl away.\n\nThe sprites have a village nearby, called Rikkitun Village. Perhaps you " ..
                "should investigate.",
            rewardItems = {{88417, 1}},
            rewardMoney = 342000,
        },
        [31084] = {
            description = "It has been a very, very long time since our tribe has been called on to " ..
                "perform this rite. I will do the best I can.",
            rewardMoney = 114000,
        },
        [31085] = {
            description = "We've found the blades, bound them together with wood and shade, and blessed " ..
                "them with an ancient incantation. If I'm not mistaken, it's time to use this " ..
                "thing.\n\nThe sprites spoke of an ancient piece of sap within the Amber Hibernal, a " ..
                "mantid cave near their empress' palace. That must be the \"Blood of Ancients\" that the " ..
                "prophecy spoke of.\n\nWhatever's inside that sap must be important. Good luck, <name>.",
            rewardChoices = {
                {84019, 1}, {84020, 1}, {84021, 1}, {84022, 1}, {84023, 1}, {84024, 1}, {84025, 1},
                {84026, 1}, {84027, 1},
            },
            rewardMoney = 114000,
        },
        [31086] = {
            description = "Lya and I agree on one thing: \"Blood of Ancients\" is almost certainly the " ..
                "sap from the great trees of the area. I should know - I brew with the stuff all the " ..
                "time.\n\nThe most ancient tree of all is the one that Grand Empress Shek'zeer calls her " ..
                "home, now known as the Heart of Fear. Find some amber from that tree, and our brew " ..
                "should be complete.",
            rewardMoney = 114000,
        },
        [31087] = {
            description = "The Klaxxi'va hear another paragon. His cries are weak and lost in darkness. " ..
                "The signal must be strengthened.\n\nThere is a tower in Amberglow Hollow that has been " ..
                "silent for many years. It must sing; the Klaxxi demand it!\n\nThis time I will go with " ..
                "you. You will help me repair it.\n\nTake the resonating crystal and meet me in Amberglow.",
            rewardMoney = 114000,
        },
        [31088] = {
            description = "The Stinging Trail nurtures young Kypari trees. The empress drains the " ..
                "saplings too early, outsider. They must grow before the amber can be taken.\n\nThe " ..
                "Klaxxi'va demand punishment for this crime! It will please them if you rain death on the " ..
                "Ik'thik harvesters.",
            rewardMoney = 114000,
        },
        [31089] = {
            description = "The Klaxxi'va have spoken to me, outsider. The paragon is hidden in the Briny " ..
                "Muck only, he is not so hidden anymore.\n\nThe lizard men surround him. He cannot fall " ..
                "into their scaley hands.\n\nYou will find him; you will awaken him. Do not return " ..
                "without him!\n\nIf you do this the Klaxxi will be pleased with us.",
            rewardMoney = 114000,
        },
        [31090] = {
            description = "It is a crime to harvest the young trees, but a much bigger crime to waste the " ..
                "amber.\n\nYoung amber is not as strong, but the Klaxxi need it to continue the fight. We " ..
                "will bring them more and they will sing my praises!\n\nGather the young amber. We will " ..
                "store it until it is aged and can be consumed.",
            rewardChoices = {{84635, 1}, {84636, 1}, {84637, 1}, {84638, 1}, {84639, 1}},
            rewardMoney = 114000,
        },
        [31091] = {
            description = "You look at me and see I am no great warrior. Why was I chosen to be a " ..
                "Paragon? Not all weapons can be seen, Wakener. One should not judge by appearance " ..
                "alone.\n\nBefore I explain further, I need to know that you are " ..
                "trustworthy.\n\nSomething precious to me was hidden at the time of my preservation. I am " ..
                "nothing without it.\n\nDefend me as I unearth my greatest weapon, and you will have my " ..
                "trust.",
            rewardChoices = {
                {83983, 1}, {83984, 1}, {83985, 1}, {83986, 1}, {83987, 1}, {83988, 1}, {83989, 1},
                {83990, 1}, {83991, 1},
            },
            rewardMoney = 114000,
        },
        [31092] = {
            description = "After years of working with the Kunchong I developed a theory; raising one " ..
                "from infancy would strengthen the bond and therefore strengthen the sonic " ..
                "connection.\n\nI had just begun training Kovok when I was chosen for encasement. He is " ..
                "still very young and will need diligent training to reach his full potential.\n\nI'm " ..
                "entrusting Kovok to you, but be warned; if any harm comes to him your life is " ..
                "forfeit.\n\nFirst, you must feed him to gain his trust. The turtles in the area should " ..
                "be suitable for this.",
            rewardMoney = 114000,
        },
        [31093] = {
            description = "Dear $p,\n\nYour research into the hozen has proven quite enlightening.\n\nIf " ..
                "you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this " ..
                "contribution to your personal collection.\n\nThank you for your " ..
                "diligence!\n\nSincerely,\n\nLorewalker Cho",
            rewardMoney = 114000,
        },
        [31094] = {
            description = "Dear $p,\n\nI have thoroughly enjoyed reading your research in to the jinyu. A " ..
                "fascinating people and quite clever too.\n\nIf you visit us at the Seat of Knowledge in " ..
                "Vale of Eternal Blossoms we can add this contribution to your personal " ..
                "collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho",
            rewardMoney = 114000,
        },
        [31096] = {
            description = "Dear $p,\n\nYou have recovered the story of our people's freedom from the mogu " ..
                "empire.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can " ..
                "add this contribution to your personal collection.\n\nThank you for your " ..
                "diligence!\n\nSincerely,\n\nLorewalker Cho",
            rewardMoney = 114000,
        },
        [31097] = {
            description = "Dear $p,\n\nWhile we appreciate your efforts to investigate the lore of " ..
                "Pandaria, the documents you sent us on the mantid managed to rob me of several nights " ..
                "sleep. Terrifying stuff.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal " ..
                "Blossoms we can add this contribution to your personal collection.\n\nThank you for your " ..
                "diligence!\n\nSincerely,\n\nLorewalker Cho",
            rewardMoney = 114000,
        },
        [31100] = {
            description = "Dear $p,\n\nYour research in to the yaungol has proven most insightful.\n\nIf " ..
                "you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this " ..
                "contribution to your personal collection.\n\nThank you for your " ..
                "diligence!\n\nSincerely,\n\nLorewalker Cho",
            rewardMoney = 114000,
        },
        [31102] = {
            description = "Dear $p,\n\nIt would seem you have discovered the full tale of Shaohao, the " ..
                "last emperor of Pandaria.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal " ..
                "Blossoms we can add this contribution to your personal collection.\n\nThank you for your " ..
                "diligence!\n\nSincerely,\n\nLorewalker Cho",
            rewardMoney = 114000,
        },
        [31103] = {
            description = "Dear $p,\n\nAt long last thanks to your research we have the full Ballad of " ..
                "Liu Lang.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can " ..
                "add this contribution to your personal collection.\n\nThank you for your " ..
                "diligence!\n\nSincerely,\n\nLorewalker Cho",
            rewardMoney = 114000,
        },
        [31107] = {
            description = "At Shek'zeer's command, the great kypari tree of Kypari Vor was twisted into a " ..
                "totem of horror.\n\nLike those outside of the palace, the clutch nearby is now used to " ..
                "corrupt our swarmborn.\n\nRecover the eggs of the Vor'thik before they are tainted. We " ..
                "shall raise them here. They will be the citizens of a new empire, free from the sha.",
            rewardMoney = 114000,
        },
        [31108] = {
            description = "Amber is power. It brings life.\n\nThis... dread amber you brought me has been " ..
                "twisted. It is concentrated fear.\n\nThe Vor'thik know this well. Their kypari has been " ..
                "completely engulfed by sha, and they use the dread amber to quicken their own " ..
                "swarmborn.\n\nBring me the crystals used by the Vor'thik fear-shapers in their rituals. " ..
                "The Klaxxi will study them and decide on a protocol for disposal.",
            rewardMoney = 114000,
        },
        [31109] = {
            description = "The Empress continues to amass her forces. Without intervention, they WILL " ..
                "overrun that wall - even if it means smothering it in the corpses of a million " ..
                "swarmborn.\n\nLet us find a better place for those corpses.\n\nLet me know when you are " ..
                "ready to depart for the clutches - I will gladly drop you in from above.",
            rewardMoney = 114000,
        },
        [31111] = {
            description = "The warriors of Zan'vess are some of the most feared and respected in the " ..
                "empire, for good reason.\n\nImpalers are unmatched in their mastery of the polearm - no " ..
                "doubt Malik trained among the Zan'thik in his time. Their manipulators command " ..
                "terrifying sonic power with the ease and subtlety of a breath.\n\nBoth will need to be " ..
                "dealt with.",
            rewardMoney = 114000,
        },
        [31113] = {
            description = "The Yaungol are a constant nuisance, but the group at Fire Camp Gai-Cho, to " ..
                "the northeast, conspired with the Osul yaungol in their recent incursion into " ..
                "Kun-Lai.\n\nWe cannot allow such an incursion to go unpunished.\n\nGo, attack Fire Camp " ..
                "Gai-Cho. We need to make sure they remain occupied, so that they cannot rise up and " ..
                "threaten The Ox Gate again.",
            rewardMoney = 114000,
        },
        [31114] = {
            description = "We have always left the Deadtalkers alone. For so long, they were just " ..
                "responsible for maintaining the sacred burial grounds of the yaungol tribes.\n\nNow, " ..
                "though, they are practicing dark magic, defiling the corpses of their former " ..
                "clanmates...\n\nI know not where they learned those dark magics, or why they no longer " ..
                "treat their dead with respect, but we do not have time to find out.\n\nWe need to stop " ..
                "them.",
            rewardMoney = 114000,
        },
        [31118] = {
            description = "We need to understand what went wrong with the Deadtalkers.\n\nFor so many " ..
                "years, the Deadtalkers were simply responsible for maintaining the burial grounds and " ..
                "holding funerals for fallen warriors.\n\nFrom a recent raid, we've recovered a tablet " ..
                "from the grounds that is clearly written using a cipher, but it isn't one we've " ..
                "encountered before. If you can gather a ciphered scroll from one of the Deadtalkers, we " ..
                "can begin to put together the cypher and understand what's happened.",
            rewardMoney = 114000,
        },
        [31120] = {
            description = "Cheng Bo is the Warbringer of Fire Camp Gai-Cho. While you've made a dent in " ..
                "their operations, you now have an opportunity to strike a major blow.\n\nSlay the " ..
                "Warbringer!",
            rewardMoney = 114000,
        },
        [31128] = {
            description = "Lao-Chin seems to have his head in the clouds... or, rather, in his " ..
                "beer.\n\nAfter all of his recent battles, he seems completely obsessed with with trying " ..
                "to develop the perfect brew for fighting.\n\nThat's well and good, but we need him to " ..
                "actually do some fighting!\n\nYou should go challenge him, see if you can snap him out " ..
                "of his rut.\n\nIf you beat him, he'll probably want to go out and help fight just to try " ..
                "to one-up you!",
            rewardMoney = 228000,
        },
        [31129] = {
            description = "$p! It is so great to see you healthy, and traveling so far. It would seem " ..
                "that our paths are quite tightly intertwined.\n\nI'm here looking for my family. I am " ..
                "told that several Stormstouts came across the wall to help face the mantid threat. I " ..
                "mean to find them, and join them.\n\nHave you seen anyone named Stormstout come through " ..
                "here? Would you mind helping me ask around?",
            rewardMoney = 57000,
        },
        [31130] = {
            description = "Stranger, I may be able to help you find your prince. But first, I would like " ..
                "to know a little more about you and your people.\n\nCome, help me with my chores, and we " ..
                "will chat.\n\nYou have the look of a grizzled war veteran, but certainly you have a few " ..
                "minutes to help a bookish Pandaren like myself putter around the house, yes?",
            rewardMoney = 74000,
        },
        [31131] = {
            description = "Reports suggest that things are quiet at Whitepetal Lake today, but I've " ..
                "dispatched Ren Firetongue and He Softfoot to make sure it stays they way.\n\nIf you want " ..
                "to aid the effort further, head to the west to the lake, meet up with He, and help him " ..
                "keep things secure from any hostile threats.",
            rewardMoney = 57000,
        },
        [31132] = {
            description = "Oh, where have my manners gone? Technically, I suppose I am the host " ..
                "here.\n\nAllow me to tell you a little bit about myself and my people before asking " ..
                "questions of you.",
        },
        [31133] = {
            description = "I'm no brewer - just looking at all those heaps of ingredients makes my head " ..
                "spin. Just put the brew in front of me when it's finished, thank you.\n\nNo, I'm here to " ..
                "make sure that the brewers don't get cut in half while they're trying to make that " ..
                "perfect brew. It's not an easy job.\n\nThe Kor'thik mantid across this basin have been " ..
                "attacking us nightly. If you're already heading over there, why don't you return the " ..
                "favor and attack a few of them?",
            rewardChoices = {
                {84617, 1}, {84618, 1}, {84619, 1}, {84620, 1}, {84621, 1}, {84622, 1}, {84623, 1},
                {84624, 1}, {84625, 1},
            },
            rewardMoney = 114000,
        },
        [31134] = {
            description = "This is a very ancient place, traveler.\n\nOnly recently have I pieced " ..
                "together a method of translating the forgotten language carved into these stones.\n\nOh, " ..
                "the thrill of discovery! This never gets old, I assure you.\n\nHere, you are the guest. " ..
                "You do the honors. I insist.\n\nUse this key to unlock the secrets the stones contain.",
            rewardMoney = 98000,
        },
        [31135] = {
            description = "It's a victory for us every time we're able to help another survivor escape " ..
                "from the contaminated halls of Gnomeregan. <class>s like you will play an important part " ..
                "in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has " ..
                "assembled a team of trainers to help you learn your arts.\n\nXi, Friend of the Small has " ..
                "visited us from a faraway land and will help oversee your training and adjustment to " ..
                "life on the surface. She's waiting for you on the small practice field across the road.",
            rewardMoney = 8,
        },
        [31136] = {
            description = "Scouts bring me reports of a powerful Imperion that slipped through our lines " ..
                "in the south and is now heading for the road in the eastern vale.\n\nI need someone I " ..
                "can trust to stop it. Find it and kill it quickly, <name>.",
            finishedBy = {{58408}},
            rewardItems = {{90625, 1}},
            rewardMoney = 228000,
        },
        [31138] = {
            description = "When you fight, you grow in skill. As you grow in skill, you will begin to " ..
                "figure out new moves. Go, explore, learn, and show me what you figure out.",
            rewardItems = {{59042, 1}},
            rewardMoney = 40,
        },
        [31139] = {
            description = "So you're the new recruit from Stormwind, eh? I'm Marshal McBride, commander " ..
                "of this garrison. Glad to have you on board...\n\n<McBride looks through some " ..
                "papers.>\n\n<name>. It is <name>, right?\n\nYou've arrived just in time. The Blackrock " ..
                "orcs have managed to sneak into Northshire through a break in the mountain. My soldiers " ..
                "are doing the best that they can to push them back, but I fear they will be overwhelmed " ..
                "soon.\n\nHead northwest into the forest and kill the attacking Blackrock worgs! Help my " ..
                "soldiers!",
            rewardItems = {{57254, 1}},
            rewardMoney = 50,
        },
        [31140] = {
            description = "The invading orcs aren't fools. They are sizing us up, making sure that when " ..
                "they attack it will be to their advantage.\n\nIn the forest, to the northwest, are " ..
                "Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. " ..
                "I want you take the fight to them!\n\nKill the Blackrock spies! We must show them that " ..
                "we know they are watching us and that we are prepared!",
            rewardItems = {{57387, 1}},
            rewardMoney = 40,
        },
        [31141] = {
            description = "I was asked to bring this to your attention as soon as you returned from " ..
                "dealing with the Blackrock spies, <name>. It appears to be a letter sealed with the " ..
                "insignia of Bao, a pandaren who is visiting us from a faraway land. I wouldn't hesitate " ..
                "to read it before you go about any other business here in the Abbey.",
        },
        [31142] = {
            description = "Now that you've had the chance to test your abilities in battle, it's time to " ..
                "explain one more reason why training is so important.\n\nAs you get more experience, " ..
                "you'll be able to do new techniques you never thought of.\n\nGo, get some experience, " ..
                "learn a new skill, and demonstrate it on one of the training dummies.",
            rewardMoney = 50,
        },
        [31143] = {
            description = "While you were out training I received an urgent message from Sergeant Willem. " ..
                "Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our " ..
                "battalion behind the abbey. Willem has asked me to send him a hero. You have to go help " ..
                "them, <name>!\n\nFind Sergeant Willem north of the abbey at the command tent. Go!",
            rewardMoney = 13,
        },
        [31145] = {
            description = "Excellent work, <name>! The rear is now officially clear. We'll take care of " ..
                "the stragglers. I want you to go back to Marshal McBride, standing in front of " ..
                "Northshire Abbey, south of here, and let him know that the goblin situation is under " ..
                "control.\n\nFarewell, <class>.",
            rewardMoney = 7,
        },
        [31146] = {
            description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived " ..
                "for you. The pandaren visitor, Ting, sent it for you. Maybe you monks can read this " ..
                "garbage, but I can't. You should go talk to her. She's in the Inn across the way.",
        },
        [31150] = {
            description = "<name>, this rune was given to me to pass on to ye. Take some time to read it " ..
                "when ye have a chance. I'm thinkin' it came from our visitor from afar, Lo. Take a " ..
                "gander at it and go find him inside Anvilmar.",
            rewardMoney = 25,
        },
        [31151] = {
            description = "The truth is, you already have the talent and ability to learn what you need " ..
                "to. What I can help you do is show you where to unlock it.\n\nFirst, you must practice " ..
                "until you begin to understand a new technique. The first technique you learn will be the " ..
                "Tiger Palm. Go, learn more until you have unlocked the potential within yourself, and " ..
                "then practice your new move!\n\nRemember - it's all in the mind!",
        },
        [31156] = {
            description = "Ah, while you were gone a parchment came for you, <name>.\n\nRead it when you " ..
                "have time. If I'm not mistaken, it came from our Pandaren friend, Gato. He visits from " ..
                "afar to grant us the honor of his wisdom, and to teach the ways of the monk. Do not " ..
                "shame your people by failing at his lessons!",
        },
        [31157] = {
            description = "As you walk the road of your training, you will begin to discover within " ..
                "yourself the power to unlock new techniques. You need not even learn them from me, or " ..
                "another more experienced monk - you will find that they come to you on their own.\n\nFor " ..
                "now, you should go and practice the basics. Gather more experience, and develop a new " ..
                "technique - once you have, you can practice it on the dummies nearby to master it.",
            rewardItems = {{87265, 1}},
        },
        [31159] = {
            description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves " ..
                "fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us " ..
                "here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis " ..
                "long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh " ..
                "Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat " ..
                "will last.\n\nIt's time to begin ya trainin', <name>. Speak with Zabrax to the east.",
            rewardMoney = 25,
        },
        [31160] = {
            description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats " ..
                "killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if " ..
                "ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.",
            rewardMoney = 50,
        },
        [31161] = {
            description = "Ya done quite well for ya'self, <class>. I'm sure I could teach ya a trick or " ..
                "two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one " ..
                "last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and " ..
                "fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know " ..
                "when ya ready.",
            rewardItems = {{85574, 1}},
            rewardMoney = 50,
        },
        [31162] = {
            description = "As ya get bettah' at fightin', you'll start to find new tings that ya nevah " ..
                "knew you could do.\n\nWanna see? Go, train up some, and learn someting new.\n\n'Den come " ..
                "back and ya can show me.",
            rewardMoney = 40,
        },
        [31165] = {
            description = "Just a moment ago a messenger was looking for you, <name>. I believe she was " ..
                "sent by our Pandaren visitor, Shoyu. You should read it.",
        },
        [31166] = {
            description = "You have done well. As you continue along your path, you will grow, learning " ..
                "new techniques that you couldn't have imagined before.\n\nYour first lesson is the power " ..
                "of experience. Go, learn a new ability, and demonstrate it for me.",
        },
        [31167] = {
            description = "So there you have it, traveler, or as much of it as would make for a proper " ..
                "introduction, hmm?\n\nWhat of you, then? Are your people so much different than " ..
                "mine?\n\nSurely, there must be things we share in common. Let us see...",
            rewardMoney = 98000,
        },
        [31168] = {
            description = "This sigil was given to me by a messenger from our Pandaren visitor, Laoxi. It " ..
                "seems he would have words with you when you have a moment. Read it and bring it to him " ..
                "afterwards.",
            rewardMoney = 25,
        },
        [31169] = {
            description = "The true secret to the art of the monk is unlocking the knowledge and power " ..
                "hidden inside yourself.\n\nGo, get more experience, and learn a new skill. Then " ..
                "demonstrate it on one of the training dummies.",
        },
        [31170] = {
            description = "As you advance within your class, you will want to take advantage of the " ..
                "training that your class trainer can provide you. For young monks here on Sunstrider " ..
                "Isle, your trainer is Pao, our Pandaren visitor. Speak with her and see what training " ..
                "she has available for you.\n\nPao - as with all the trainers on Sunstrider Isle - is " ..
                "inside the Sunspire on the lower level.",
        },
        [31171] = {
            description = "Good. You are off to a bright start. This road will be long, and as you become " ..
                "more accomplished, you will begin to discover that you can do things you could never " ..
                "have imagined before.\n\nGo, get more experience, and learn a new technique. Once you " ..
                "have, demonstrate it on one of the training dummies.",
        },
        [31173] = {
            description = "I hope your people are all alright... the crash was unbelievably loud and " ..
                "destructive!\n\n<Mojo looks you over, evaluating your potential.>\n\nYes, you'll do " ..
                "fine. They've said that they need more people to fight, and they don't want me to hurt " ..
                "myself. I'm not afraid, but I don't want to intrude. So, I'll teach you.\n\nAs you may " ..
                "have discovered, your experiences in combat will unlock new potential within you. Go, " ..
                "see if you can master a new ability. Show it to me. You'll get the hang of things.",
        },
        [31175] = {
            description = "Our efforts to secure the shallows before Zan'vess have paid off.\n\nWe have " ..
                "spotted another paragon buried in amber, hidden in the waters to the " ..
                "southwest.\n\nAdding another paragon to our numbers is vital. Another champion from ages " ..
                "past could turn the tide in our favor.\n\nI would go immediately, but unfortunately, I " ..
                "am needed here.\n\nSince you are already a Wakener, you can carry out this task in my " ..
                "stead.",
            rewardMoney = 114000,
        },
        [31176] = {
            description = "Food. I must have food.\n\nIn my time, the meat of the starfish brought not " ..
                "only strength, but also clarity of mind. This is what I must eat.\n\nBring this to me " ..
                "from the nearby shallows.\n\nWait much longer, and I will devour you instead.",
            rewardMoney = 114000,
        },
        [31177] = {
            description = "In my living years, I was the greatest warrior of the swarm.\n\nHelp me regain " ..
                "my strength, and I shall show you.\n\nI smell the salt sea nearby, and where you can " ..
                "find the sea, you will find briny clackers.\n\nBring me their tails. I must feast upon " ..
                "their flesh.",
            rewardMoney = 114000,
        },
        [31178] = {
            description = "A warrior is not ready for battle until he tastes the blood of his " ..
                "enemies.\n\nI am still too weak to hunt, so you must go in my stead.\n\nOnly the blood " ..
                "from the fiercest predators will do. I can smell their presence in the waters outside " ..
                "this cave!\n\nBring this to me, and then perhaps you shall see why they call me the " ..
                "Bloodseeker.",
            rewardMoney = 114000,
        },
        [31179] = {
            description = "I'm afraid that I wet my hands with saurok blood while you were away.\n\nI'm " ..
                "sorry, but I could not help myself. Now, watch them attack me.\n\nPitiful!\n\nDo they " ..
                "think to take vengeance for their fallen? Do they come challenge ME?\n\nI, who have won " ..
                "a hundred wars? I, who stood alone against thousands and still shouted for my enemies to " ..
                "come?\n\nNo, these... saurok... will crumple before me like paper before the flame!\n\nI " ..
                "shall show you my might, Wakener. Fight alongside me and see.\n\nHere they come!",
            rewardChoices = {
                {84095, 1}, {84096, 1}, {84097, 1}, {84098, 1}, {84099, 1}, {84100, 1}, {90104, 1},
                {90105, 1}, {90624, 1},
            },
            rewardMoney = 114000,
        },
        [31181] = {
            description = "We got a load of empty crab pots out there that need fresh bait.\n\nNow, we " ..
                "COULD pull them one at a time and bait them up here in comfort. A nice chair to sit on, " ..
                "maybe a hot cup of tea to keep you warm. Sounds nice, doesn't it?\n\nNever gonna " ..
                "happen.\n\nHead to Lonesome Cove, immediately southwest, and bait those pots with two " ..
                "chunks of fresh sea monarch. By \"fresh\" I mean killed right there in the water.\n\nOh, " ..
                "and by \"pots\" I mean traps. If you wanna be part of the crew, you'd better learn the " ..
                "lingo.",
            rewardChoices = {
                {84001, 1}, {84002, 1}, {84003, 1}, {84004, 1}, {84005, 1}, {84006, 1}, {84007, 1},
                {84008, 1}, {84009, 1},
            },
            rewardMoney = 114000,
        },
        [31183] = {
            description = "Alright, $p, I got another job for ya.\n\nYou see that lion seal in the pen " ..
                "over there? Name's Dog. He's been Soggy's pet for years.\n\nDog's acting up lately - I " ..
                "think he's getting restless in that pen. Why don't you go talk to Soggy and let him " ..
                "know.\n\nI'd say it's about time you meet the cap'n anyway.",
            rewardMoney = 11400,
        },
        [31184] = {
            description = "Look, I ain't got reason to trust you, but there's a task I can't give to my " ..
                "crew.\n\nI need you to search the wreck of our old ship, the Mist-Hopper, and bring back " ..
                "the charter. It'd be sealed up in a silver tube, in a footlocker.\n\nIt's sort of, uh... " ..
                "incriminating. I can't risk any of the crew finding it if they decide to visit the ol' " ..
                "girl. She's resting on the Shelf of Mazu, to the west.\n\nI'd suggest riding a rip " ..
                "current out there, if you got the stomach. They're all over the shelf.",
            rewardMoney = 114000,
        },
        [31185] = {
            description = "Dog ain't my \"pet.\" He's a member of this crew, and my best friend. Saved my " ..
                "life more than once, you know.\n\nBut I'm gettin' too old to walk him anymore, and he " ..
                "still needs his exercise. Take Dog for a trip around the shelf for me, would ya?\n\nHe " ..
                "loves to swim through the hot geysers just southeast of the shallows.\n\nHe absolutely " ..
                "has to... er... \"leave his mark\" on the dead whale at the far western edge of the " ..
                "shelf.\n\nOh, and he'll want to visit our old shipwreck, too. He likes to reminisce.",
            rewardChoices = {
                {84010, 1}, {84011, 1}, {84012, 1}, {84013, 1}, {84014, 1}, {84015, 1}, {84016, 1},
                {84017, 1}, {84018, 1},
            },
            rewardMoney = 114000,
        },
        [31186] = {
            description = "< Dog whines as best as a lion seal can, feebly lifting one flipper toward his " ..
                "massive jaws.\n\nHe's hungry.\n\nThe Shelf of Mazu is covered in rockshell makrura that " ..
                "should make a fine meal for him.>",
            rewardMoney = 114000,
        },
        [31187] = {
            description = "I just got word that a string of pots we dropped this morning hit it BIG. " ..
                "We're on the crab!\n\nProblem is, the rips are getting stronger and we lost track of " ..
                "some of the pots. They're just sitting out there, filled with spiky blue GOLD!\n\nI need " ..
                "you back out there. Hook one of these buoys up to any of the full traps you find and " ..
                "send it to the surface for us.",
            rewardMoney = 114000,
        },
        [31189] = {
            description = "I never thought I'd see the day, but for the first time since... well, EVER, " ..
                "Master Angler Ju Lien asked for some help with his lines.\n\nApparently the sea is going " ..
                "crazy today and he can't keep up. See if you can give him a hand. He's fishing just " ..
                "south of here.",
            rewardMoney = 114000,
        },
        [31190] = {
            description = "I'm not gonna sit in a damn rocking chair while my crew gets devoured by a " ..
                "leviathan!\n\nCome on, let's get to the dock and launch a dinghy. I got a special one " ..
                "set up just for this kind of situation. My own little Mist-Hopper Jr.\n\nWe'll give that " ..
                "thing a case of harpoon fever.",
            rewardChoices = {
                {83992, 1}, {83993, 1}, {83994, 1}, {83995, 1}, {83996, 1}, {83997, 1}, {83998, 1},
                {83999, 1}, {84000, 1},
            },
            rewardMoney = 114000,
        },
        [31196] = {
            description = "The mantid outnumber us quite badly. Hundreds of them for each of us.\n\nAnd, " ..
                "they surround us on two sides - at Gao-Ran in the south we're holding them off, but to " ..
                "the west, on the island they call Sra'vess, they continue to mass unabated.\n\nWe're not " ..
                "stupid. We're not going to launch a full scale attack on them. We can't sustain an " ..
                "intense battle on multiple fronts.\n\nInstead, we're going to send you, and one of our " ..
                "Wu Kao, to do some dirty work. Sounds fun, doesn't it?",
            rewardMoney = 114000,
        },
        [31197] = {
            description = "Killing the smaller mantid works mostly as a distraction. It forces them to " ..
                "replenish their numbers before they consider any serious offensive.\n\nThe big ones, " ..
                "though - we kill a few of those, and we really disrupt operations on the island. That " ..
                "buys ourselves a substantial amount of time. With mantid, it's like their size is " ..
                "directly proportional to their importance in the empire.\n\nSo kill some of the big ones " ..
                "for me, while you're out there.",
            rewardMoney = 114000,
        },
        [31198] = {
            description = "The mantid have statues built on Sra'vess. We don't know exactly what they use " ..
                "them for. They may have some sort of religious significance, or maybe they assist with " ..
                "their sonic communication.\n\nWhen you fight your opponent, you don't just engage them " ..
                "physically, you also engage them mentally. Whatever they use them for, the fact is that " ..
                "those statues are important to them.\n\nWhich is why I want you to blow them up. Losing " ..
                "something important will be a substantial hit to morale.",
            rewardMoney = 114000,
        },
        [31199] = {
            description = "The mantid don't just attack in swarms.\n\nThey're smart. They use alchemy, " ..
                "bombs... and what's worst, they've got siege weapons. Those have the potential to be " ..
                "incredibly destructive if they attack with them.\n\nWe've got reports that they're " ..
                "building up a force of siege weapons to the west at Sra'vess. Go and destroy them.",
            rewardMoney = 114000,
        },
        [31200] = {
            description = "Our alchemists have cooked up a set of gas bombs that will discourage mantid " ..
                "from staying anywhere that we set them off.\n\nIf we plant these in the critical " ..
                "structures of Sra'vess, they'll need to evacuate. That should sow some chaos and delay " ..
                "any action from the mantid there for days.\n\nGet to it, <name>.",
            rewardMoney = 114000,
        },
        [31201] = {
            description = "Our scouts have sent a very troubling report.\n\nThree of our trainees have " ..
                "gone missing, and our scouts found them...\n\nThey've been captured by the mantid and " ..
                "sent to their Kunchong pits.\n\nTheir Kunchong FEEDING pits. We're lucky that the " ..
                "Kunchong don't eat that often.\n\nI need you to get in there, give them these escape " ..
                "kites, and get them out!",
            rewardMoney = 114000,
        },
        [31207] = {
            description = "Ah, I can still remember running fights out of a muddy hole in the ground back " ..
                "in Nagrand. We've come a long way, eh, Wodin?\n\nI tell you, there's nothing more these " ..
                "Tiger monks like than a good scrap. So much so that they've paid good coin for me to set " ..
                "up shop here and help draw the strongest fighters from all around!\n\nSo how about it? " ..
                "You and a couple friends up for a few rounds in the Arena of Annihilation...? Big money, " ..
                "big prizes!",
            rewardChoices = {
                {90459, 1}, {90460, 1}, {90461, 1}, {90462, 1}, {90463, 1}, {90464, 1}, {90465, 1},
                {90466, 1},
            },
            rewardMoney = 114000,
        },
        [31209] = {
            description = "I require another ingredient to create my first poison, Wakener.\n\nThis " ..
                "ingredient you can easily find on the scarabs nearby.\n\nKill them and bring me their " ..
                "wings.",
            rewardMoney = 114000,
        },
        [31210] = {
            description = "The last ingredient is perhaps the deadliest.\n\nThe dreadshade flower grows " ..
                "all along these hills.\n\nIt is by eating these poisonous plants that the local wildlife " ..
                "has become so venomous.\n\nA single drop of dreadshade nectar can stop a kunchong's " ..
                "heart.\n\nGo and bring me some of these flowers. Do not be tempted to taste them.",
            rewardMoney = 114000,
        },
        [31216] = {
            description = "The swarm begins, Wakener! The mantid amass at the Heart of Fear.\n\nAlready " ..
                "they fill the skies with their wings and rend the earth with their claws. They shall not " ..
                "stop the dark march until their bodies are laid open and bleeding upon the " ..
                "ground.\n\nThis we shall gladly do. We will attack them from above. While I fly, use my " ..
                "poisons to destroy their advance.\n\nDo not mix the two serums until you are ready to " ..
                "attack. The reaction can be quite... violent.\n\nSpeak to me when you are ready to go.",
            rewardMoney = 114000,
        },
        [31221] = {
            description = "So... you've been challenged by the infamous Tenwu of the Red Smoke.\n\nThat's " ..
                "what he calls himself, at least. He's a good fighter, and a good rogue, but it's a " ..
                "wonder he manages to sneak up on anyone with how loudly he brags about " ..
                "himself.\n\nAnyways, I think you should answer the challenge. Maybe it'll give him a " ..
                "touch of humility. Maybe not. Either way, if you win, he'll probably be willing to go " ..
                "with you on your missions.\n\nAnd I get some entertainment.",
            rewardMoney = 228000,
        },
        [31231] = {
            description = "Back in Gurthani Terrace where you found me, dreadspinners continue to occupy " ..
                "the attention of Shado-Pan marksmen who could otherwise be thinning out this wretched " ..
                "swarm.\n\nEradicate those spiders and offer some relief to the archers on that wall.",
            rewardMoney = 114000,
        },
        [31232] = {
            description = "My brothers speak of an ancient mogu empire that once dwelled in the ruins to " ..
                "the east.\n\nOnce, this tribe knew untold secrets of sorcery and subjugation.\n\nI have " ..
                "a curious mind, Wakener, and I wish to learn of the empires that ruled after my " ..
                "time.\n\nKnowledge of the past will determine our future.\n\nGo search the ruins for " ..
                "their ancient tablets. I will study their secrets and make them our own.",
            rewardMoney = 114000,
        },
        [31233] = {
            description = "I found a grove of young amber trees to the east, Wakener.\n\nI've placed " ..
                "tapping devices on these trees, but I have been too busy to retrieve the sap.\n\nI need " ..
                "someone to find the extractors. Activate them, then bring me samples of the amber.",
            rewardMoney = 114000,
        },
        [31234] = {
            description = "Ah! Wakener! You must help me! (You will help me, or else I will help myself " ..
                "to you!)\n\nI need more materials for my experiments, yes yes! (Blood and guts, hearts " ..
                "and brains, tongues and eyes, eyes, eyes!)\n\nTo the west, I have seen creatures of mist " ..
                "and fog. They possess such big, round, wonderful globes! Big for seeing, round and " ..
                "unblinking!\n\nGo now, little Wakener. Bring me back a single pristine eye!",
            rewardMoney = 114000,
        },
        [31235] = {
            description = "I recovered this weapon on a recent scouting run near the wall. It would seem " ..
                "ideal for helping your Shado-Pan with their infestation problem in Gurthani " ..
                "Terrace.\n\nThe more they are focused on keeping spiders off the wall, the less time " ..
                "they are killing fear-gripped swarmborn.",
            rewardMoney = 114000,
        },
        [31237] = {
            description = "If this Empress is truly possessed by fear and paranoia, she will have sent " ..
                "scouts to every corner of the land in order to cement her control.\n\nThese scout grubs " ..
                "are likely everywhere, but difficult to spot with the naked eye. Better to track them by " ..
                "the pheromone trails they leave behind.\n\nI've already... gifted you... a reactive " ..
                "toxin that will reveal these trails to you for a brief time after experiencing the " ..
                "thrill of victory.\n\nGo now to the Terrace of Gurthan and root out these spies.",
            rewardMoney = 114000,
        },
        [31238] = {
            description = "Kovok is growing at an accelerated rate, but his brain may not be able to keep " ..
                "up. He'll require a special diet to ensure that he does not outgrow the capacity to " ..
                "control his own body.\n\nMushan tongue is rich in the nutrients that promote brain " ..
                "growth in kunchong, but they normally eat the beasts whole and fill up quickly. If we " ..
                "feed Kovok only mushan tongues every couple of days or so, it should balance out his " ..
                "growth.\n\nGreatback mushan graze the hills east of here, near the Gurthani Terrace.",
            rewardMoney = 114000,
        },
        [31239] = {
            description = "So, you wanna be a hozen. Huh, wikket?\n\nHozen defend their lands from " ..
                "enemies, like jinyu.\n\nKah Kah fought many jinyu fights, and won them all.\n\nHozen " ..
                "only give name name to good grookers. Go grook jinyu and maybe they call you <name> " ..
                "<name>.\n\nJinyu creepin' down by the river. Ook 'em in the dooker!",
            rewardItems = {{84105, 1}},
            rewardMoney = 98000,
        },
        [31240] = {
            description = "Anji came by and asked for you. Said she was heading to the northeast " ..
                "ruins.\n\nOh, Anji, such a fiery spirit, that girl! Probably better for your long-term " ..
                "health if you not keep her waiting.",
            rewardMoney = 57000,
        },
        [31241] = {
            description = "<name> good wikket, they say...\n\n<name> help hozen, they say...\n\nNo more " ..
                "grookin' <name>, they say.\n\nThat ok. Look out there. Wicked wikkets fallin' like rain, " ..
                "ripe for the grookin'!\n\nGo, join the fun. But remember, Chief Kah Kah gets all the " ..
                "shinies! That's hozen rule number two.\n\n< Jeek Jeek scratches his head.>\n\nHmm, all " ..
                "hozen rules are number two...",
            rewardChoices = {{88699, 1}, {88700, 1}, {88701, 1}, {88702, 1}, {88703, 1}},
            rewardMoney = 98000,
        },
        [31242] = {
            description = "My scouts have spotted no mogu near Mistfall Village today, but I've been " ..
                "hearing of some troubles with local wildlife and spirits in the graveyard. I dispatched " ..
                "Che to assess the situation, but he'll most likely need your help.\n\nFind your way " ..
                "southwest to the village and meet Che there. Do what you can.",
            rewardMoney = 57000,
        },
        [31243] = {
            description = "Mogu have been sighted at Mistfall Village to the southwest. I dispatched Rook " ..
                "and Sun immediately, but I need another capable hand there as soon as possible.\n\nDon't " ..
                "delay. The villagers need you.",
            rewardMoney = 57000,
        },
        [31244] = {
            description = "Leven came by in quite a huff! Said something about mogu in the ruins.\n\nBest " ..
                "be off to find him I think. Angry Leven is not a fun Leven.",
            rewardMoney = 57000,
        },
        [31245] = {
            description = "Che stopped by on the way to the village and ask if I'd seen you. I told him " ..
                "no.\n\nYou can go see him if you want. But now you're not obligated to see him! I am so " ..
                "marvelously considerate, am I not?",
            rewardMoney = 57000,
        },
        [31246] = {
            description = "I can see smoke from the village. And it's not my fault this time!\n\nBest go " ..
                "and help.",
            rewardMoney = 57000,
        },
        [31247] = {
            description = "Anji and Kun stopped by on the way to the garrison. Lovely pair, don't you " ..
                "think? So different, yet so devoted to each other... ah, it makes my heart swoon just " ..
                "thinking about it.\n\nThey asked for you by name. Maybe they want to put you through " ..
                "some of the training paces? I certainly hope they don't have something more naughty in " ..
                "mind...",
            rewardMoney = 57000,
        },
        [31249] = {
            description = "Everything I've heard suggests the village has been unaffected by the " ..
                "Shao-Tien offensive at the lake, but I won't take any risks.\n\nI'm dispatching you and " ..
                "Che Wildwalker to keep watch at the village, and aid the townsfolk while you're there.",
            rewardMoney = 57000,
        },
        [31250] = {
            description = "We've taken losses from the mogu forces descending the Golden Stair and their " ..
                "flanking attackers at Whitepetal Lake. Our lines are thin.\n\nI'm dispatching Anji and " ..
                "Kun to the Setting Sun Garrison to double our efforts at training new recruits. I'd like " ..
                "you there with them, <name>. Show them what a true <class> is made of.",
            rewardMoney = 57000,
        },
        [31251] = {
            description = "Yeah, yeah.\n\nEveryone knows us goblins do tinkering. And explosives. And... " ..
                "well, ya' know, the less reputable stuff.\n\nBut what nobody knows is that I'm really a " ..
                "great chef! It's a hobby of mine.\n\nGather us up some meaty bits from the creatures " ..
                "around here, and I'll cook us up the best meals ANYWHERE!\n\nAnd I promise, I'll only " ..
                "use three or four percent rocket fuel.",
            rewardMoney = 102000,
        },
        [31252] = {
            description = "Well, far as I figure, we've got quite a lot of rebuildin' to do.\n\nI'm not " ..
                "one for joining any big causes, but my farmhands aren't gonna have much to do 'round " ..
                "here, to be honest. And, since you helped them out, they want to join your \"Alliance.\" " ..
                "So, who am I to stop 'em?\n\nBring 'em with you, back to Farmhand Bo. I'll miss 'em, but " ..
                "they're better off with you.",
            rewardMoney = 204000,
        },
        [31253] = {
            description = "Well, far as I figure, we've got quite a lot of rebuildin' to do.\n\nI'm not " ..
                "one for joining any big causes, but my farmhands aren't gonna have much to do 'round " ..
                "here, to be honest. And, since you helped them out, they want to join your \"Horde\". " ..
                "So, who am I to stop 'em?\n\nBring 'em with you, back to Farmhand Ko. I'll miss 'em, but " ..
                "they're better off with you.",
            rewardMoney = 204000,
        },
        [31254] = {
            description = "Ah! Greetings friend of Lorewalker Cho. I have a message for you.\n\n<The " ..
                "strange little creature hands you a battered scroll case.>\n\nThe Lorewalker waits for " ..
                "you in Kun-Lai. Very dangerous to travel there, yes, very dangerous.\n\nLook for guides " ..
                "along the road to help you find your way.",
            rewardMoney = 10200,
        },
        [31255] = {
            description = "Ah! Greetings friend of Lorewalker Cho. I have a message for you.\n\n<The " ..
                "strange little creature hands you a battered scroll case.>\n\nThe Lorewalker waits for " ..
                "you in Kun-Lai. Very dangerous to travel there, yes, very dangerous.\n\nLook for guides " ..
                "along the road to help you find your way.",
            rewardMoney = 10200,
        },
        [31256] = {
            description = "Lok'tar, <class>.\n\nWe've made progress, but we're going to need mobility if " ..
                "we want to maintain our foothold here in Kun-Lai.\n\nI don't see many worgs, kodo, or " ..
                "the like around here. What I do see are yaks. Our pandaren allies have said they make " ..
                "good mounts, so they'll have to do.\n\nGo round some up and return them here, so we can " ..
                "get our people riding them!",
            rewardChoices = {
                {84509, 1}, {84510, 1}, {84511, 1}, {84512, 1}, {84513, 1}, {84514, 1}, {84515, 1},
                {84516, 1}, {84517, 1},
            },
            rewardMoney = 102000,
        },
        [31260] = {
            description = "I am totally on to another great scam!\n\nWhen I was flying overhead I saw a " ..
                "really ancient tigress prowling about.\n\nDo you know how much her blood would go for on " ..
                "the black market? Not to mention if I convince some warlocks it adds extra potency to " ..
                "their summoning spells or something.\n\nIf you bring me back some of her blood I will " ..
                "cut you in on the scam. She was prowling about on the far side of the Dojani River from " ..
                "here.",
            rewardMoney = 98000,
        },
        [31261] = {
            description = "Gore from Captain Jack's head drips and mysteriously seeps into the ground as " ..
                "you examine your hard-won trophy.\n\nStrange, but no time to investigate that now. " ..
                "There's too much work to be done.\n\nThe chieftain of your newfound friends will " ..
                "doubtlessly be impressed with this proof of your grookin' skills.",
            rewardMoney = 196000,
        },
        [31262] = {
            description = "So, now that you've got a vibe for how cranes fight, I've got a doozy for " ..
                "you.\n\nNeedlebeak!\n\nOr at least, that's what I'm calling him. Biggest crane I ever " ..
                "saw. And its beak is so sharp it's like a sword.\n\nNorthwest of here you'll find the " ..
                "big water fall that kicks off the Dojani River. Needlebeak likes to hang out by the " ..
                "waterfall.\n\nYou bring me its beak as a trophy and I will talk you up a good game to " ..
                "Nesingwary.",
            rewardChoices = {
                {88044, 1}, {88045, 1}, {88046, 1}, {88047, 1}, {88048, 1}, {88049, 1}, {88050, 1},
                {88051, 1}, {88052, 1},
            },
            rewardMoney = 98000,
        },
        [31265] = {
            description = "Here to help, are ya? Well, first thing's first.\n\n<Arie rummages through her " ..
                "pockets for a moment before producing a small vial of glowing blue fluid.>\n\nHere it " ..
                "is! \"Mazu's Breath.\" Cap'n's own formula.\n\nWhat? You thought I'd send you out to sea " ..
                "without a means of breathin'? I need deckhands, not corpses!\n\nDown the hatch with it, " ..
                "green. This'll give you a fighting chance out there on the shelf.",
            rewardMoney = 28500,
        },
        [31267] = {
            description = "Korven has told me of his findings. There is an enormous amber deposit sitting " ..
                "at the bottom of the Lake of Stars.\n\nUnfortunately, a hostile saurok tribe lives at " ..
                "the edge of the lake, and revere the amber as their own.\n\nThey will not allow us to " ..
                "enter their territory easily.\n\nGo south to the lake. Kill the Mistblade saurok, so " ..
                "that we can more easily harvest the nearby amber.",
            rewardMoney = 114000,
        },
        [31268] = {
            description = "Far to the south, the swarm breeds weapons of destruction - enormous, nearly " ..
                "unbreakable amber scorpions.\n\nLike all other creatures, they are subject to " ..
                "manipulation, but unlike other creatures, they have not yet submitted to my mind " ..
                "control.\n\nIt appears that further research is necessary before I can dominate them for " ..
                "our own purposes.\n\nI must study their brains, and you must retrieve some specimens for " ..
                "me.\n\nTake this sonic emitter. I have found it to be quite effective against the beasts.",
            rewardMoney = 114000,
        },
        [31270] = {
            description = "When we discovered the sha influence at Kypari Zar, I had hoped the corruption " ..
                "could still be cleansed.\n\nUnfortunately, the Klaxxi Council has confirmed that the sha " ..
                "of fear's corruption is deep-seated, and continues to spread.\n\nTo the south, I have " ..
                "observed some of the local wildlife consumed by an unnamed terror.\n\nThe sha can warp " ..
                "and twist its victims into unimaginable horrors.\n\nWe must stop the corruption before " ..
                "it becomes worse. Seek out the sha-infected Horrorscale Scorpids. Eliminate them.",
            rewardMoney = 114000,
        },
        [31271] = {
            description = "Far to the south, Wakener, the Empress's genemancers set about their dark " ..
                "experiments. (Dark yes, but not as dark as mine!)\n\nThey dissect and mutate the nearby " ..
                "wildlife, breeding creatures of their own design. (Their design, which will become my " ..
                "design!)\n\nWe must not let them succeed! (No, no! Only I am allowed such " ..
                "power!)\n\nTheir mutations are already being unleashed for war. Go! Destroy them at any " ..
                "cost!",
            rewardMoney = 114000,
        },
        [31272] = {
            description = "The Empress's genemancers play with dangerous toys.\n\nTo the south, they are " ..
                "injecting local wildlife with pheromone-laden parasites, in an attempt to create " ..
                "monstrous mutations for war.\n\nCarelessly, they have allowed their parasitic worms to " ..
                "escape into the local ecosystem.\n\nLeft unchecked, the infection will spread from one " ..
                "animal to another, until we have an outbreak.\n\nI will inject you with a mild toxin. " ..
                "With it, you will be able to identify infected creatures.\n\nKill the carriers at once.",
            rewardMoney = 114000,
        },
        [31279] = {
            description = "I'm so glad you enjoy my food. Are you interested in the recipes? If so, you " ..
                "should learn them properly, from my teachers in Halfhill Market. Everything I know about " ..
                "the kitchen, I learned from them.\n\nSay, if you happen to pass through there, would you " ..
                "deliver this note to Sungshin Ironpaw for me? She was my favorite teacher, and I want " ..
                "her to know that I miss her.",
            rewardMoney = 11400,
        },
        [31281] = {
            description = "You wish to be a chef? If you are dedicated, I can unlock your hidden " ..
                "potential, no matter how inexperienced you are.\n\nIf you wish to learn, show me you can " ..
                "at least follow basic instructions. Learn how to slice peaches and show me what you've " ..
                "learned. I have fresh pandaren peaches which I will sell to you at a token price.",
            rewardMoney = 11400,
        },
        [31285] = {
            description = "Nobody really travels up the Ancient Passage on foot. That is just asking for " ..
                "a faceful of saurok if you are not careful.\n\nTell you what, Egg Shell and I were just " ..
                "about to set off upriver to Binan Village. Want a lift?",
            rewardMoney = 10200,
        },
        [31286] = {
            description = "Ah, a <class>. I could make good use of your skills.\n\nA convoy was struck " ..
                "just up the road by a band of marauding saurok. These marauders made off with some... " ..
                "merchandise... her ladyship, the Madam Goya, had a mind to sell.\n\nOne does not steal " ..
                "from her ladyship.\n\nIf you recover these items I will gladly provide you a finders fee.",
            rewardMoney = 102000,
        },
        [31287] = {
            description = "The Spring Road is under the protection of her ladyship, the esteemed Madam " ..
                "Goya.\n\nThe saurok of Hatescale Burrow northeast of here require \"education\" in this " ..
                "fact. We have warned them before but sadly they seem to have a very short " ..
                "memory.\n\nTravel northeast to this burrow and find their shaman leader. Eliminate him " ..
                "and you will have the gratitude of her ladyship. As well as an appropriate bounty.",
            rewardMoney = 102000,
        },
        [31291] = {
            description = "Interested in being a Lorewalker? There is lots of digging and reading and " ..
                "digging and more reading.\n\nI have entire days where I stare at a broken vase trying to " ..
                "figure out how it goes back together.\n\nShould give it a try. Go solve one artifact of " ..
                "Pandaria and we will appreciate you sharing the knowledge of how you did it.",
            rewardMoney = 114000,
        },
        [31293] = {
            description = "Leven sent Rook here to stop mogu, but there are more than Rook can kill " ..
                "alone.\n\nYou help? Rook will tell Leven you helped. Promise.",
            rewardMoney = 114000,
        },
        [31295] = {
            description = "Thank you for your help, <class>.\n\nI would enjoy your company for longer, " ..
                "but Leven is leading an attack on the mogu within the Ruins of Guo-Lai to the northwest, " ..
                "and awaits your capable hands.\n\nMay the celestials protect you, young one.",
            rewardMoney = 57000,
        },
        [31297] = {
            description = "The mogu will not be able to maintain this attack much longer. We should be " ..
                "able to handle it here, thanks to your kind aid.\n\nMight you be willing to find Anji at " ..
                "the Setting Sun Training Camp to the west? She's been tasked with preparing fresh-faced " ..
                "pandaren to aid the cause. You could show them a thing or two as well, I imagine.",
            rewardMoney = 57000,
        },
        [31302] = {
            description = "You seem to know your way around the kitchen. Demonstrate to me your skills " ..
                "and make me 5 bowls of rice pudding.",
            rewardMoney = 11400,
        },
        [31308] = {
            description = "Now that you are a pet trainer, it's time to test your skills!\n\nHead out " ..
                "into the forest and pick a fight with a battle pet. Make sure to use your Track Pets " ..
                "skill so you can see pets you can fight on the minimap. Come back to me after you have " ..
                "won and I will continue your training. Good luck!",
            rewardMoney = 106000,
        },
        [31309] = {
            description = "Now that you have won a battle, we need to heal up your pets so they can fight " ..
                "another day! Visit Erma, our local stable master, to heal and revive your pets.",
            rewardMoney = 106000,
        },
        [31311] = {
            description = "The Pandaren Way of the Grill produces foods that increase your physical " ..
                "strength. Bring some raw tiger steaks to the Master of the Grill, and he will teach you " ..
                "what you can do with them. There are many tigers in the Jade Forest and the Krasarang " ..
                "Wilds, but you can also find them in other places.",
            rewardItems = {{74833, 5}},
            rewardMoney = 11400,
        },
        [31312] = {
            description = "The old, faded leather is falling apart, but still legible.\n\nScrawled on it " ..
                "is some kind of map, and the following lines:\n\nDeep in the valley where four winds " ..
                "blow, The maiden laughs behind her golden fan. At the feet of her ancestors' stair, She " ..
                "whispers secrets into the echoing dark.",
            rewardMoney = 114000,
        },
        [31316] = {
            description = "I can tell you have been honing your pet battle skills, <name>. I think it's " ..
                "time for you to take on a real challenge.\n\nJulia Stevens can be found at the Maclure " ..
                "Vineyards south of Stormwind. She is an up and coming wild pet tamer and I think it's " ..
                "time you faced her in battle!",
            rewardItems = {{89125, 1}},
            rewardMoney = 94000,
        },
        [31319] = {
            description = "Your companions have made themselves at home in our land, and brought with " ..
                "them a dangerous conflict.\n\nThe full extent of their destruction here we cannot yet " ..
                "know. Already it is... unspeakable.\n\nNevertheless, to forsake your friends out of " ..
                "spite would be against our way. Any that yet live are doubtlessly wounded and in " ..
                "desperate need of care.\n\nThese fireworks were to celebrate the statue's completion. " ..
                "Use them near your companions to signal Mishi, and she will bear them off to safety.",
            rewardMoney = 98000,
        },
        [31320] = {
            description = "Heeeey buddy, how'sh it goin'? You wanna buy a jinyu a drink?",
            rewardMoney = 114000,
        },
        [31322] = {
            description = "My dreams grow dim recently, <race>.\n\nI need something powerful to kick " ..
                "myshelf back into gear!\n\nI heard there'sh a delishush drink that folksh are making " ..
                "nowadays.\n\nIt'sh called Jade Witch Brew.\n\nI'd sure like to taste some.",
            rewardMoney = 114000,
        },
        [31323] = {
            description = "All right, <name>, in order to continue my vishions, I must now have my own " ..
                "brewery.\n\n...\n\nJust kidding! You should have sheen your own face! Hilarioush... " ..
                "hic!\n\nAnyway, I heard of a new drink that is unlike any other, and I would like a " ..
                "tashte.\n\nHave you heard of the Mad Brewer'sh Breakfasht? If you can bring me some of " ..
                "thish shtuff, you will be my friend for life.",
            rewardMoney = 114000,
        },
        [31324] = {
            description = "Our secret recipes! I was gathering them up. But then... hozen?\n\n<Auntie " ..
                "looks very confused.>\n\nHow is Gao to brew anything? He needs those recipes or disaster " ..
                "is sure to strike!",
            rewardChoices = {{87310, 1}, {87311, 1}, {87312, 1}, {87313, 1}, {87314, 1}},
            rewardMoney = 408000,
        },
        [31326] = {
            description = "It's a dazzling diamond tiara. Who in the valley would be wealthy enough to " ..
                "own such a piece of jewelry?\n\nWhoever it is, they might be willing to give a nice " ..
                "reward.",
            rewardMoney = 114000,
        },
        [31327] = {
            description = "With the brewery infested by hozen and... and who knows what else, I'm sure " ..
                "that the brewers are in trouble.\n\nWould you mind helping me find out what's going on, " ..
                "my friend?",
            rewardChoices = {
                {87301, 1}, {87302, 1}, {87303, 1}, {87304, 1}, {87305, 1}, {87306, 1}, {87307, 1},
                {87308, 1}, {87309, 1},
            },
            rewardMoney = 408000,
        },
        [31329] = {
            description = "It is a very old, antique brooch with very detailed molding and filigree " ..
                "worked into the edges. It looks very valuable.\n\nThere's only one person who keeps " ..
                "losing jewelry to furry hooligans, and she would probably want to see this heirloom " ..
                "returned.",
            rewardMoney = 114000,
        },
        [31332] = {
            description = "I'm excited to start my training. We start with sliced peaches, right?",
            rewardItems = {{86057, 5}},
            rewardMoney = 11400,
        },
        [31342] = {
            description = "You have proven yourself in battle.\n\nStill, if you would aid us further, I " ..
                "must ask something else of you.\n\nThe Sha of Violence awaits beyond within the Sealed " ..
                "Chambers. Destroy it if you would earn my respect.",
            rewardChoices = {
                {87324, 1}, {87325, 1}, {87326, 1}, {87327, 1}, {87328, 1}, {87329, 1}, {87330, 1},
                {87331, 1}, {87332, 1},
            },
            rewardMoney = 440000,
        },
        [31354] = {
            description = "That was some amazing work you and the captain did out there, $p! It's an " ..
                "honor to have you on the crew.\n\nOh! And Ju Lien survived! He swam ashore just after " ..
                "you started letting the harpoons fly. He was raving about some kind of gigantic egg or " ..
                "something that washed in with Jiao.\n\nGo check up on him, will you? He's probably " ..
                "hauled it out of the water by now.",
            rewardMoney = 114000,
        },
        [31356] = {
            description = "There is an ancient pandaren saying that states, \"With deep doubts comes deep " ..
                "wisdom.\"\n\nThe Sha of Doubt has infested the Heart of Jade within the temple. It must " ..
                "be destroyed.\n\nI dare say that you are about to become all the wiser, <class>.",
            rewardChoices = {
                {87283, 1}, {87284, 1}, {87285, 1}, {87286, 1}, {87287, 1}, {87288, 1}, {87289, 1},
                {87290, 1}, {87291, 1},
            },
            rewardMoney = 408000,
        },
        [31357] = {
            description = "The mogu have reawakened and are a threat to all of Pandaria. They are on the " ..
                "cusp of becoming even more dangerous.\n\nThere are four great mogu kings of legend: Zian " ..
                "of the Endless Shadow, Meng the Demented, Qiang the Merciless, and Subetai the Swift. " ..
                "Four artifacts of these kings are secreted away in the Vault of Kings Past, " ..
                "below.\n\nYou must retrieve these relics before the mogu discover them and become " ..
                "unstoppable.",
            rewardChoices = {
                {87342, 1}, {87343, 1}, {87344, 1}, {87345, 1}, {87346, 1}, {87347, 1}, {87348, 1},
                {87349, 1}, {87350, 1},
            },
            rewardMoney = 440000,
        },
        [31360] = {
            description = "A new king of the mogu has arisen: Xin the Weaponmaster.\n\nHe single-handedly " ..
                "subjugated the mogu clans, and now they and their new leaders vie for his favor.\n\nI've " ..
                "never seen or read of any who are his equal in battle. Do not underestimate Xin, " ..
                "<name>.\n\nOur fate rests in your hands.",
            rewardChoices = {
                {87333, 1}, {87334, 1}, {87335, 1}, {87336, 1}, {87337, 1}, {87338, 1}, {87339, 1},
                {87340, 1}, {87341, 1},
            },
            rewardMoney = 440000,
        },
        [31362] = {
            description = "I must say, <name>, despite their skirmishes with the hozen, I've never seen " ..
                "the jinyu so militant.\n\nThis troubles me. We must discuss it another time, however. I " ..
                "have come to ask for your assistance.\n\nThe fresco, where last we spoke, is nearly " ..
                "unveiled. I am certain that it holds ancient wisdom - knowledge that the emperor would " ..
                "have us remember.\n\nMy meditations alone may not be enough to discern its meaning. " ..
                "Please, take this heirloom to the shrine of my ancestors. I shall require their " ..
                "assistance.",
            rewardMoney = 98000,
        },
        [31364] = {
            description = "The mantid have something they call Raigonn. It's a giant bug they're using to " ..
                "bust down the wall's gates!\n\nLet's keep that thing from getting into the vale!",
            rewardChoices = {{87351, 1}, {87352, 1}, {87353, 1}, {87354, 1}, {87355, 1}},
            rewardMoney = 456000,
        },
        [31369] = {
            description = "If you want to explore all the secrets of the deep ocean, and catch some big " ..
                "fish, speak to Haito at the Anglers Wharf in Krasarang Wilds.\n\nI'm sure he'd love to " ..
                "show you a thing or two about reeling!",
            rewardMoney = 11400,
        },
        [31370] = {
            description = "If you want to explore all the secrets of the deep ocean, and catch some big " ..
                "fish, speak to Haito at the Anglers Wharf in Krasarang Wilds.\n\nI'm sure he'd love to " ..
                "show you a thing or two about reeling!",
            rewardMoney = 11400,
        },
        [31372] = {
            description = "The Tillers do their business at Halfhill in the Valley of the Four " ..
                "Winds.\n\nIf you're interested in getting started, I hear there's a new farmer in town " ..
                "by the name of Farmer Yoon.\n\nI betcha he'll be looking for help.",
            rewardMoney = 11400,
        },
        [31375] = {
            description = "The Order of the Cloud Serpent is always searching for talented riders.\n\nIf " ..
                "you wish to follow our way, you should speak to Instructor Skythorn at The Arboretum in " ..
                "the Jade Forest.\n\nI wish you luck, <race>.",
            rewardMoney = 11400,
        },
        [31376] = {
            description = "Darkness enshrouds the Temple of the Jade Serpent, and Yu'Lon's priests " ..
                "beseech us for aid.\n\nThey hold the sha in check, but just barely.\n\nYou may be able " ..
                "to turn the tide, <class>.",
        },
        [31378] = {
            description = "The Temple of the Red Crane still reels from the aftermath of the sha's " ..
                "presence, and has only recently gathered to rebuild and retrain its warriors.\n\nIf you " ..
                "wish to help at the temple, speak to Thelonius at the Cradle of Chi-Ji.",
        },
        [31379] = {
            description = "The Temple of the Red Crane still reels from the aftermath of the sha's " ..
                "presence, and has only recently gathered to rebuild and retrain its warriors.\n\nIf you " ..
                "wish to help at the temple, speak to Thelonius at the Cradle of Chi-Ji.",
        },
        [31381] = {
            description = "Xuen, the great Celestial of the North, seeks the greatest champions in the " ..
                "land.\n\nToday, he holds trials of battle at his temple in Kun-Lai Summit.\n\nIf you " ..
                "wish to test yourself against skilled fighters from all across Pandaria, then go to him " ..
                "and enter the challenger's ring!",
        },
        [31382] = {
            description = "Niuzao Temple, far to the west, is under attack by the mantid.\n\nThe great " ..
                "Celestial holds them back for now, but he cannot stand alone forever.\n\nGo and help the " ..
                "defenders, <class>. The Temple must not fall!",
        },
        [31383] = {
            description = "Niuzao Temple, far to the west, is under attack by the mantid.\n\nThe great " ..
                "Celestial holds them back for now, but he cannot stand alone forever.\n\nGo and help the " ..
                "defenders, <class>. The Temple must not fall!",
        },
        [31386] = {
            description = "We Shado-Pan have amassed our forces for the first time in many ages.\n\nThe " ..
                "Sha of Hatred has escaped beyond the Serpent's Spine, and it is our sacred duty to " ..
                "imprison it once more.\n\nHowever, our warriors are great, but our numbers too few. Help " ..
                "from a capable <class> may not be turned away.\n\nIf you wish to join the offensive, " ..
                "speak to Taran Zhu in the Townlong Steppes.",
            rewardMoney = 11000,
        },
        [31388] = {
            description = "We Shado-Pan have amassed our forces for the first time in many ages.\n\nThe " ..
                "Sha of Hatred has escaped beyond the Serpent's Spine, and it is our sacred duty to " ..
                "imprison it once more.\n\nHowever, our warriors are great, but our numbers too few. Help " ..
                "from a capable <class> may not be turned away.\n\nIf you wish to join the offensive, " ..
                "speak to Taran Zhu in the Townlong Steppes.",
            rewardMoney = 11000,
        },
        [31390] = {
            description = "The Klaxxi are only rumored to exist, far beyond the wall in the Dread " ..
                "Wastes.\n\nFew have ventured into that territory, and none have returned to tell the " ..
                "tale.\n\nIf you are set on finding these... Klaxxi... there is a small group of " ..
                "Shado-Pan manning the wall to the far southwest who may know more.",
            rewardMoney = 11400,
        },
        [31392] = {
            description = "Have you heard the news, traveller? There's been at attack at one of our most " ..
                "sacred places, the Vale of Eternal Blossoms!\n\nEven now, there's a human prince within " ..
                "the White Tiger Temple arguing that you and the other races from beyond the mists should " ..
                "be allowed within.\n\nThe temple is in the northeast of Kun-Lai. Maybe you can convince " ..
                "the White Tiger to allow you inside?\n\nI only hope the Vale has not been utterly " ..
                "destroyed...",
            rewardMoney = 77000,
        },
        [31393] = {
            description = "Have you heard the news, traveller? There's been at attack at one of our most " ..
                "sacred places, the Vale of Eternal Blossoms!\n\nEven now, there's a human prince within " ..
                "the White Tiger Temple arguing that you and the other races from beyond the mists should " ..
                "be allowed within.\n\nThe temple is in the northeast of Kun-Lai. Maybe you can convince " ..
                "the White Tiger to allow you inside?\n\nI only hope the Vale has not been utterly " ..
                "destroyed...",
            rewardMoney = 77000,
        },
        [31394] = {
            description = "Nobody is allowed into the Vale without the approval of the August Celestials. " ..
                "Xuen, The White Tiger, appears ready to listen to me.\n\nBut Taran Zhu of the Shado-Pan " ..
                "is reluctant to let the Alliance or Horde anywhere NEAR the Vale after all that's " ..
                "happened.\n\n<Anduin shakes his head.>\n\nMaybe you can help me make my case. Speak to " ..
                "the White Tiger on our behalf. Be careful! He may set a number of challenges before " ..
                "you...",
            rewardMoney = 102000,
        },
        [31395] = {
            description = "The human calf is arguing on our behalf. He is well-spoken; I can see why " ..
                "Baine Bloodhoof regards the prince so highly.\n\nStill, the argument does not go well. I " ..
                "am of little consequence, but you are a hero of the Horde. Perhaps you can intercede in " ..
                "our favor?\n\nSpeak with the White Tiger and plead our case, <race>.\n\nBe careful! He " ..
                "may set a number of challenges before you...",
            rewardMoney = 102000,
        },
        [31398] = {
            description = "Why would the saurok have amber? More importantly, why would Oracle Hiss'ir be " ..
                "so protective of it?\n\nIt is unlikely this came from the heavily guarded Zan'vess, so " ..
                "where did it come from?\n\nPerhaps the Klaxxi will know what to make of it.",
            rewardChoices = {
                {84626, 1}, {84627, 1}, {84628, 1}, {84629, 1}, {84630, 1}, {84631, 1}, {84632, 1},
                {84633, 1}, {84634, 1},
            },
            rewardMoney = 114000,
        },
        [31439] = {
            description = "The beacon in Amberglow Hollow seems to have been tampered with. Right before " ..
                "the signal cut out the Klaxxi'va picked up a signal for another paragon nearby.\n\nThey " ..
                "believe he is hidden in that wretched little swamp, Duskroot Fen.\n\nI will meet you in " ..
                "the fen to set up a temporary beacon until I can get Amberglow operational again.\n\nYou " ..
                "will wake the paragon and then you will help me.",
            rewardMoney = 114000,
        },
        [31441] = {
            description = "Today you learn that no one can be trusted in times of war, Wakener. Even " ..
                "those closest to the Klaxxi are susceptible to corruption.\n\nWho knows how long this " ..
                "traitor has been corrupted. He must be destroyed!\n\nYou appear confused. Do you not see " ..
                "the traitor in our midst? Allow me to adjust your vision.",
            rewardMoney = 114000,
        },
        [31442] = {
            description = "There are four tomes of great necromantic evil studied in Scholomance: \" In " ..
                "the Shadow of the Light \", \" Kel'Thuzad's Deep Knowledge \", \" Forbidden Rites and " ..
                "other Rituals Necromantic \" and \" The Dark Grimoire \".\n\nAs we make our way through " ..
                "this cursed place, find and destroy each book so that no other fool can come along later " ..
                "and learn their vile secrets.",
            rewardMoney = 456000,
        },
        [31443] = {
            description = "You've caught a unique fish... with wings. Perhaps it deserves the expert " ..
                "opinion of Nat Pagle in Anglers Wharf.",
            rewardMoney = 114000,
        },
        [31444] = {
            description = "You have fished up something special. It looks pretty aggressive.\n\nMaybe Nat " ..
                "Pagle at the Anglers Wharf might know more about it?",
            rewardMoney = 114000,
        },
        [31446] = {
            description = "You aren't sure how, but you've caught an extraordinary cephalopod. Nat Pagle " ..
                "at Anglers Wharf would be very interested to see it.",
            rewardMoney = 114000,
        },
        [31447] = {
            description = "The key to lifting the curse of this place rests in the final death of " ..
                "Darkmaster Gandling.\n\nDo it, $p, and make him suffer!",
            rewardMoney = 24000,
        },
        [31448] = {
            description = "The key to lifting the curse of this place rests in the final death of " ..
                "Darkmaster Gandling.\n\nDo it, $p, and make him suffer!",
            rewardChoices = {
                {87379, 1}, {87380, 1}, {87381, 1}, {87382, 1}, {87383, 1}, {87384, 1}, {87385, 1},
                {87386, 1}, {87387, 1},
            },
            rewardMoney = 456000,
        },
        [31450] = {
            description = "These new allies have shed light on a great and important truth: it is not " ..
                "just Shen-zin Su that is ailing, but all of the land beyond the clouds. The world needs " ..
                "healing, and I think that you should be the ones to heal it.\n\nI would like you, Ji, " ..
                "and Aysa to leave and bring your strength and wisdom to the world. These Alliance and " ..
                "Horde have different ideals, but at the core of both lies noble intent.\n\nI will leave " ..
                "the choice of who you wish to accompany to you.",
            rewardMoney = 85,
        },
        [31451] = {
            description = "Usually, Merchant Shi comes through Kun-Lai Summit to trade with the Jinyu and " ..
                "Grummle. We've heard word that he hadn't been seen at Binan, and we haven't seen him " ..
                "here...\n\nI'm worried something has happened to him. Can you go to the Inkgill Mere and " ..
                "see if he's there?",
            rewardMoney = 10200,
        },
        [31452] = {
            description = "Usually, Merchant Shi comes through Kun-Lai Summit to trade with the Jinyu and " ..
                "Grummle. We've heard word that he hadn't been seen at Binan, and we haven't seen him " ..
                "here...\n\nI'm worried something has happened to him. Can you go to the Inkgill Mere and " ..
                "see if he's there?",
            rewardMoney = 10200,
        },
        [31453] = {
            description = "Our new recruits have spoken in hushed tones about a group of Pandaren they " ..
                "call the \"Shado-Pan\". They are apparently very strong, and secretive.\n\nIt's clear " ..
                "that, no matter what happens here in Kun-Lai, making an alliance with these Shado-Pan " ..
                "will be critical to our foothold in Pandaria.\n\nThat's where you come in. Rumor is they " ..
                "have a base of operations to the southeast, near Firebough Nook.\n\nYou will go there, " ..
                "and curry their favor. For the Horde!",
            rewardMoney = 10200,
        },
        [31455] = {
            description = "Our new recruits have spoken in hushed tones about a group of Pandaren they " ..
                "call the \"Shado-Pan\". They are apparently very strong, and secretive.\n\nThat's where " ..
                "you come in. Rumor is they have a base of operations to the southeast, near Firebough " ..
                "Nook. You should travel there as an envoy of the Alliance. Give them any help they " ..
                "require.",
            rewardMoney = 10200,
        },
        [31456] = {
            description = "There's another Pandaren settlement out here, Muskpaw Ranch. I don't know if " ..
                "they're alright, what with everything that's been going on with the Yaungol " ..
                "invasion.\n\nYou've been so helpful - you should go check up on them, friend!",
            rewardMoney = 10200,
        },
        [31457] = {
            description = "There's another Pandaren settlement out here, Muskpaw Ranch. I don't know if " ..
                "they're alright, what with everything that's been going on with the Yaungol " ..
                "invasion.\n\nYou've been so helpful - you should go check up on them, friend!",
            rewardMoney = 10200,
        },
        [31458] = {
            description = "Kor'ik has been sending signals to the empress for weeks. Everything the " ..
                "Klaxxi have done, the empress knows about.\n\nThat stops now!\n\nKypari Ik will be the " ..
                "first to receive news of Kor'ik's demise. It would benefit us to make sure that message " ..
                "does not make it to the empress.\n\nDestroying the whisperers and beacon there will buy " ..
                "us enough time to come up with a plan before the empress can act.",
            rewardMoney = 114000,
        },
        [31459] = {
            description = "One of those grummles came by and said that Lorewalker Cho sent for you. You " ..
                "should go ahead and meet up with him, he might have something important to say.\n\nThe " ..
                "grummel said he's at Onekeg, to the north.",
        },
        [31460] = {
            description = "One of those adorable little grummles came by and said that Lorewalker Cho " ..
                "sent for you. You should meet up with him!\n\nThe grummel said he's at Onekeg, to the " ..
                "north.",
            rewardMoney = 10200,
        },
        [31464] = {
            objectivesText = {
                "See if you've already completed this by typing: /run " ..
                    "print(C_QuestLog.IsQuestFlaggedCompleted(31464))",
            },
        },
        [31465] = {
            description = "Kypari Ik is just one of many locations that houses some of Empress " ..
                "Shek'zeer's offspring. In their juvenile state the young are reckless and difficult to " ..
                "control. They are also deadly.\n\nSwarmborn are hatched with a highly toxic venom that " ..
                "diminishes in potency with age. The venom can incapacitate even the strongest and most " ..
                "skilled fighter if it hits flesh.\n\nI would like you to bring me some of this venom.",
            rewardChoices = {
                {88132, 1}, {88133, 1}, {88134, 1}, {88135, 1}, {88136, 1}, {88137, 1}, {88138, 1},
                {88139, 1}, {88140, 1},
            },
            rewardMoney = 114000,
        },
        [31467] = {
            description = "With the grill, you can transform those raw tiger steaks into food that makes " ..
                "you stronger. Learn the recipe for charbroiled tiger steaks from me. Show me what you " ..
                "can do.",
            rewardMoney = 11400,
        },
        [31468] = {
            description = "I have on good authority that you are a champion among champions, but if " ..
                "you'll permit me this indulgence, I would like to test your mettle for myself.\n\nThe " ..
                "mogu who assault the Vale of Eternal Blossoms, the mogu minions who inhabit Shan'ze Dao, " ..
                "and the sha-corrupted mantid swarming the Dread Wastes... these may provide an adequate " ..
                "challenge for one of your stature.\n\nProve yourself to me. No rush - I expect this to " ..
                "take you some time.",
            rewardMoney = 114000,
        },
        [31470] = {
            description = "If you wish to make dishes that enhance agility, you should bring some carrots " ..
                "and rice to the Master of the Wok. The virmen around here tend to carry a lot of carrots " ..
                "around. You can also grow your own, if you have a farm.",
            rewardItems = {{74841, 5}},
            rewardMoney = 11400,
        },
        [31471] = {
            description = "To cook with the wok, you need to be nimble. Your first lesson is sauteed carrots.",
            rewardMoney = 11400,
        },
        [31472] = {
            description = "The cuisine of the Way of the Pot help expand your intellect. Bring some jade " ..
                "lungfish to the Master of the Pot and she will teach you. You can fish for jade lungfish " ..
                "in the Jade Forest.",
            rewardItems = {{74856, 5}},
            rewardMoney = 11400,
        },
        [31475] = {
            description = "A great meal can lift your spirits, and none more so than food from the Way of " ..
                "the Steamer. Bring the Master some giant mantis shrimp and he will show you. You can " ..
                "fish for giant mantis shrimp in the ocean.",
            rewardItems = {{74857, 5}},
            rewardMoney = 11400,
        },
        [31479] = {
            description = "The Pandaren Way of the Brew produces... Well, I'll let the Master of the Brew " ..
                "explain it. Bring him some ginseng and he will show you the way.",
            rewardItems = {{74845, 1}},
            rewardMoney = 11400,
        },
        [31482] = {
            description = "< Wrathion 's piercing red eyes fixate on you.>\n\nYou are among a rare breed, " ..
                "<name>.\n\nYou are just what I am looking for - an individual with the potential to " ..
                "shape events on a global scale.\n\nCome now, I promised you a reward, and you shall have " ..
                "it! East of this tavern is a series of stone steps leading up to a vista that the locals " ..
                "have named \"Mason's Folly.\" Meet me there.",
            rewardChoices = {{89873, 1}, {89881, 1}, {89882, 1}},
            rewardMoney = 57000,
        },
        [31483] = {
            description = "The Pandaren campaign is only beginning! We turn our attention now to the " ..
                "ongoing conflict between the Alliance and the Horde.\n\nMy contacts in Ravenholdt tell " ..
                "me that the Alliance 7th Legion and a considerable Horde invasion force are converging " ..
                "toward Pandaria's southern shores. Like it or not, Pandaria may soon become a " ..
                "battlefield.\n\nWe are done for now, but I want you to contact me when your fleet " ..
                "arrives. Then... together we will spring into action!",
        },
        [31486] = {
            description = "I'm so glad you enjoy my food. Are you interested in the recipes? If so, you " ..
                "should learn them properly, from my teachers in Halfhill Market. Everything I know about " ..
                "the kitchen, I learned from them.\n\nSay, if you happen to pass through there, would you " ..
                "deliver this note to Sungshin Ironpaw for me? She was my favorite teacher, and I want " ..
                "her to know that I miss her.",
            rewardMoney = 11400,
        },
        [31487] = {
            description = "Relying on sonic whispers to manipulate the kunchong was only the most " ..
                "primitive stage of my research, and yet the Empire seems to have adopted the practice " ..
                "wholly. The manipulators of the Shek'zeer are too impatient to form a proper bond with " ..
                "their kunchong.\n\nTheir laziness will cost them dearly.\n\nStrike this tuning fork near " ..
                "the dread kunchong in the clutches - watch as they reel in confusion and lash out at " ..
                "their masters. Use this to your advantage and put them down.",
            rewardMoney = 114000,
        },
        [31488] = {
            description = "Excuse me, <class>. Is your name <name>?\n\nA figure in a dark cloak asked " ..
                "that I give this to you. She was a traveler from beyond the mists, like yourself, but - " ..
                "well, I didn't trust her.\n\nThe message comes from a tavern in the veiled stair. I'll " ..
                "give you the note but... you should watch your back if you venture up there!",
            rewardMoney = 57000,
        },
        [31494] = {
            description = "The Shek'zeer manipulators are corralling young kunchong into that clutch and " ..
                "exposing them to raw fear energies, twisting them and accelerating their " ..
                "growth.\n\nDisgusting! I will not allow it!\n\nBreak open the cages and set those " ..
                "hatchlings free.",
            rewardMoney = 114000,
        },
        [31496] = {
            description = "The wonders of the kypari sap never cease to amaze me. Among its numerous " ..
                "properties and applications, the sap can be refined into a nutritious and extremely " ..
                "delectable elixir.\n\nNowhere in the Empire will you find a finer execution of this brew " ..
                "than the palace itself. Surely, the homes of the loyalists have feeders brimming with " ..
                "this sweet nectar.\n\nFill this jar at their feeders and return it to me. I long to " ..
                "sample the imperial ambrosia once more.",
            rewardMoney = 114000,
        },
        [31497] = {
            description = "There is a book of great value to me here in the halls.\n\nUnfortunately, it's " ..
                "in the possession of Flameweaver Koegler. I've tried to get close to him before, but " ..
                "it's never quite worked out.\n\nYou might have better luck. Just watch out -- I hear " ..
                "that he's gone well and truly insane. The Flameweaver plans to burn every tome they have " ..
                "in the library.\n\nHe'll probably burn the Scarlet Halls down in the process.",
            rewardChoices = {
                {87370, 1}, {87371, 1}, {87372, 1}, {87373, 1}, {87374, 1}, {87375, 1}, {87376, 1},
                {87377, 1}, {87378, 1},
            },
            rewardMoney = 456000,
        },
        [31498] = {rewardMoney = 114000, rewardXP = 177000},
        [31500] = {rewardMoney = 114000, rewardXP = 177000},
        [31501] = {rewardMoney = 114000, rewardXP = 177000},
        [31502] = {
            description = "The young fliers of this era are fascinating. Their exceptional agility and " ..
                "endurance were, in my time, the feats of incredibly skilled or mature fliers.\n\nThis " ..
                "would seem to indicate some kind of evolution in wing structure... Or perhaps a result " ..
                "of advancements in training? Induced genetic mutation? Selective breeding?\n\nGah! " ..
                "There's no way to know for certain without tissue samples.\n\nBring me their wings! And " ..
                "try not to ruin them in the process, will you? I need them intact!",
            rewardMoney = 114000,
        },
        [31503] = {
            description = "There is a champion among the loyalists, Vess-Guard Na'kal, whose strength " ..
                "comes not from experience or development, but from genetic modification. He was meant to " ..
                "be an example of the future of mantid - the sick idea that we can be born strong, " ..
                "without earning it.\n\nHe's a mockery of my work! Gene augmentation was meant for " ..
                "mature, post-swarm veterans ONLY!\n\nEnd him. Perhaps it will serve as a lesson to Grand " ..
                "Empress Shek'zeer that taking shortcuts leads to ruin.",
            rewardMoney = 114000,
        },
        [31504] = {
            description = "If the Grand Empress's agents are still operating under security standards " ..
                "from my time, they would have hidden powerful pheromone mines all around the " ..
                "clutches.\n\nWith mere whisper she could detonate them all simultaneously, engulfing the " ..
                "palace and rendering entire siege armies powerless.\n\nIf we hope to have any success in " ..
                "a large scale standoff, we need to disable those mines. My... \"gift\" to you when we " ..
                "met will allow you to see the mines. Disturb them and get to a safe distance.",
            rewardMoney = 114000,
        },
        [31505] = {
            description = "Vess-Guard Vik'az co-ordinates the defense forces at Zan'vess. He is worth ten " ..
                "mantid in battle, and his presence inspires the Zan'thik who fight alongside " ..
                "him.\n\nNeedless to say, we need him dead.\n\nHe patrols the housing area at the center " ..
                "of the island.",
            rewardMoney = 114000,
        },
        [31507] = {
            description = "The venomsting scorpions on Zan'vess are fed sap from a young age, causing a " ..
                "fascinating mutation in which their natural armor plating becomes infused with amber. " ..
                "Effectively, it's organic kyparite, the same substance used in forging most of the " ..
                "empire's weapons and armor.\n\nI think I've found a way to chemically break down " ..
                "kyparite, but it needs testing. Use these grenades on the Zan'thik venomstings and " ..
                "observe the results.",
            rewardMoney = 114000,
        },
        [31508] = {
            description = "Kyparite worms have shown extreme adaptations in order to mimic the " ..
                "environment around them. They can also grow to immense sizes at rates which are nearly " ..
                "unheard of for most creatures.\n\nTheir physiology could provide valuable insight into " ..
                "further mutations.\n\nBring me sample shards from the muck tunnelers in the shallows " ..
                "near Zan'vess.",
            rewardMoney = 114000,
        },
        [31509] = {
            description = "The fallout from Shek'zeer's madness will continue long after her reign has " ..
                "ended. We will struggle to heal our lands for many years to come, and even then our " ..
                "efforts may prove fruitless.\n\nA new species of sha-twisted flora has begun taking root " ..
                "near Zan'vess. Destroy any that you find, but beware - there is no telling what kind of " ..
                "sinister defenses it may have.",
            rewardMoney = 114000,
        },
        [31510] = {
            description = "On the southwestern corner of Zan'vess lie the Whispering Stones. Much like " ..
                "the towers here, they are critical in transmitting long-range sonic signals.\n\nAn " ..
                "adjunct of the Empress operates the stones, keeping her in communication with the " ..
                "Zan'thik forces. Disrupt the signal, then silence him.",
            rewardMoney = 114000,
        },
        [31511] = {
            description = "I will gather up the other Tauren pilgrims and we will travel into the Vale " ..
                "together.\n\nMeet me at the Gate of the August Celestials at the southern edge of " ..
                "Kun-Lai Summit and speak with me there.",
            rewardMoney = 51000,
        },
        [31512] = {
            description = "The celestials are allowing us back into the Vale! This will be a sight to " ..
                "behold.\n\nWe shouldn't waste any time. Head to the Gate of the August Celestials at the " ..
                "southern edge of Kun-Lai Summit and speak with me there.",
            rewardMoney = 51000,
        },
        [31513] = {
            description = "The problem with the Scarlet Crusade is that they keep coming back, even after " ..
                "death.\n\nBehind those resurrections is High Inquisitor Whitemane. With her death, so " ..
                "goes the Crusade.\n\nTo give her the final rest, we need two swords of legend, each with " ..
                "a lost but storied history.\n\nLuckily for me... er, us, these two blades of the " ..
                "anointed are at rest here within the monastery.\n\nFind them and once you've killed " ..
                "Whitemane, plunge the blades into her corpse to make the death permanent.",
        },
        [31517] = {
            description = "We honor strength here, not brutality. It is unfortunate but there are some " ..
                "who come to my doorstep oblivious to this distinction.\n\nI have turned away one such " ..
                "challenger. In retaliation, he sacked the village of Yinying.\n\nGo to Yinying Village " ..
                "southeast of the temple, and face this \" Shonuf.\" Give him a lesson in true strength.",
            rewardMoney = 114000,
        },
        [31520] = {
            description = "<name>, I need you to assemble a hearty group and lead them into the Temple of " ..
                "the Jade Serpent. Activate the Challenger's Orb therein, and vanquish the Sha of " ..
                "Doubt.\n\nReturn to me when you've completed this challenge, and I shall reward you " ..
                "handsomely.",
            rewardMoney = 456000,
        },
        [31521] = {
            description = "There will come a day when you have mastered all that we have to teach you. " ..
                "When that day comes, it will be time for you to teach others in turn. When you have " ..
                "proven to yourself that you have mastered all the Ways, come back and speak with me.",
            rewardMoney = 11400,
            rewardXP = 23600,
        },
        [31536] = {
            description = "To preserve maximum freshness, cooking ingredients need to be stored properly. " ..
                "Fortunately, Merchant Cheng over there sells good containers. I hate to send you on such " ..
                "a menial errand, but would you go purchase an empty tiger meat basket for me?",
            rewardMoney = 11400,
        },
        [31538] = {
            description = "There's one final person who needs to taste my brew.\n\nI've heard that he's " ..
                "traveled far and wide, and tasted drinks from all over the world.\n\nHe happens to be in " ..
                "town, and I'd like to know what he thinks of my skills.",
            rewardMoney = 114000,
        },
        [31539] = {
            description = "We live in a world of magic.The few among us who are skilled can imbue this " ..
                "magic into the things we craft and give them power. Such things are valued.\n\nFewer " ..
                "still, however, are those among us who can create things that are cherished through the " ..
                "ages not because they are imbued with power, but because of their great beauty.\n\nThe " ..
                "Temple of the Jade Serpent has commissioned us for such a work, and I believe you are " ..
                "the worthiest among us. Will you accept the commission?",
            rewardItems = {{79731, 1}},
            rewardMoney = 114000,
        },
        [31540] = {
            description = "It seems like the Tian Monsatery is training a lot of monks this year. We've " ..
                "received a huge commission for staves. And by huge, I mean HUGE.\n\nCould you take on " ..
                "part of the commission? I'd very much appreciate it. You will receive the rewards for " ..
                "your portion, of course.",
            rewardItems = {{79731, 2}},
            rewardMoney = 114000,
            rewardXP = 236000,
        },
        [31541] = {
            description = "One of the greatest poets of our time is Master Kwang. He has composed a poem " ..
                "of great beauty, and a merchant in Halfhill would like to have these words inscribed in " ..
                "stone, to display proudly in her home. She has requested a scribe of great skill to take " ..
                "on this job. Will you accept the commission?",
            rewardItems = {{79731, 1}},
            rewardMoney = 114000,
            rewardXP = 236000,
        },
        [31542] = {
            description = "The practice of caligraphy is an old custom in Pandaria. I am working on a " ..
                "piece about an ancient war, so I seek an ink that is suitable to the subject " ..
                "matter.\n\nI have searched high and low for the right hue, but it eludes me. Can you " ..
                "think of a way to achieve the color I am seeking?",
            rewardItems = {{79731, 1}},
            rewardMoney = 114000,
            rewardXP = 236000,
        },
        [31543] = {
            description = "Many great pieces of art are results of great love. A merchant in Halfhill " ..
                "wishes to have a portrait made for his beloved, as a birthday present. Will you accept " ..
                "this commission?",
            rewardItems = {{79731, 1}},
            rewardMoney = 114000,
            rewardXP = 236000,
        },
        [31544] = {
            description = "All things must come to an end - even the life of a good man. A family in Kun " ..
                "Lai has commissioned a monument for their beloved patriarch who has passed on recently. " ..
                "Will you accept the commission?",
            rewardItems = {{79731, 1}},
            rewardMoney = 114000,
            rewardXP = 236000,
        },
        [31545] = {
            description = "The Pandaria Treasure Society is interested in purchasing finely crafted goods " ..
                "from skilled jewelcrafters such as yourself. The items will be catalogued, and the most " ..
                "exceptional cuts stored in a secret vault, while the rest are sold to refresh our " ..
                "funds.\n\nOur goal is to eventually create a unique collection for a special event.",
        },
        [31548] = {
            description = "Now that you are a pet trainer, it's time to test your skills!\n\nHead out " ..
                "into the valley and pick a fight with a battle pet. Come back to me after you have won " ..
                "and I will continue your training. Good luck!",
            rewardMoney = 9000,
        },
