        [31808] = {
            description = "Kovok has progressed at an astonishing rate. Perhaps the years in hibernation " ..
                "effected his growth process...\n\nWhatever the reason, this could not have come at a " ..
                "better time. I believe it is time to test his abilities.\n\nYou have done so much to aid " ..
                "in his training. It is only fitting that you assist him in his first battle.\n\nI've " ..
                "already guided him to the edge of the scar. Find him and destroy Shek'zeer's army!",
            rewardMoney = 114000,
        },
        [31811] = {
            description = "I can no longer call myself your teacher, <name>.\n\nYou have proven yourself " ..
                "worthy of your cloud serpent.\n\nToday, you shall join our ranks. Are you ready?",
            rewardChoices = {{85429, 1}},
            rewardMoney = 57000,
            startedBy = {{58564}},
        },
        [31812] = {
            description = "I can tell you have been honing your pet battle skills, <name>. I think it's " ..
                "time for you to take on a real challenge.\n\nZunta can be found near the Tor'kren Farm " ..
                "south of Orgrimmar. He is an up and coming wild pet tamer and I think it's time you " ..
                "faced him in battle!",
            rewardItems = {{89125, 1}},
            rewardMoney = 3500,
        },
        [31813] = {
            description = "Der be another trainer not far from here that you ought to fight to test your " ..
                "worth.\n\nDagra the Fierce waits on the northern slope of Thorn Hill, east of The " ..
                "Crossroads. If you be beatin' her, you just might have what it takes.",
            rewardItems = {{89125, 1}},
            rewardMoney = 94000,
        },
        [31814] = {
            description = "Determination is naught without proper challenge.\n\nFind Analynn wandering " ..
                "the roads in western Ashenvale. She is a bit...eccentric...but a fine trainer " ..
                "nonetheless! Fighting her will harden your team.",
            rewardItems = {{89125, 1}},
            rewardMoney = 65000,
        },
        [31815] = {
            description = "<name>, a rare opportunity has arisen that I think you will be interested " ..
                "in.\n\nZonya the Sadist in southern Stonetalon Mountains has returned to the battle " ..
                "scene. I must suggest that you face her to further hone your own abilities as a tamer.",
            rewardItems = {{89125, 1}},
            rewardMoney = 94000,
        },
        [31817] = {
            description = "Are you ready for a real measure of your prowess, <race>?\n\nMerda Stronghoof " ..
                "has made camp at da place dey call Karnum's Glade in the Cenarion Wildlands of Desolace. " ..
                "Fighting a trainer as powerful as her will put your skills to the test, eh?",
            rewardItems = {{89125, 1}},
            rewardMoney = 114000,
        },
        [31818] = {description = "Think you can take me again, eh?", rewardMoney = 175},
        [31819] = {
            description = "You climbed this mountain once more only to face your own demise.",
            rewardMoney = 225,
        },
        [31820] = {
            description = "I'm all caught up with the other kids now, even though I started very late. " ..
                "Now I can join the regular classes!\n\nI made you an apron to show you how much I " ..
                "appreciate all you've done for me. I hope you like it?",
            rewardChoices = {{74853, 5}, {74662, 5}, {74661, 5}},
            rewardItems = {{86468, 1}},
            rewardMoney = 342000,
        },
        [31822] = {
            description = "Good, good. It's important to keep your pets healthy and ready for " ..
                "battle.\n\nMy next task for you is to fight a few battles and raise a pet to level 3. " ..
                "Once you do that, come back and see me and we can talk about catching your own pets!",
            rewardMoney = 225,
        },
