        [31836] = {
            description = "Welcome back <name>, the time has come for the next step of your training. " ..
                "Speak with Master Yoon in the Training Grounds below us for your next lesson.",
            rewardChoices = {{89548, 1}, {89549, 1}, {89550, 1}},
        },
        [31837] = {
            description = "Welcome back <name>, the time has come for the next step of your training. " ..
